def _gpu_worker_nodeset_names(values: Mapping[str, Any]) -> tuple[str, ...]:
    return tuple(
        name
        for name, nodeset in _target_worker_nodesets_by_name(values).items()
        if soperator_nodeset_is_gpu_worker(nodeset)
        and _nonnegative_int(nodeset.get("replicas"), fallback=0) > 0
    )


def _pod_nodeset_name(item: Mapping[str, Any]) -> str:
    metadata = _mapping(item.get("metadata"))
    labels = _mapping(metadata.get("labels"))
    for key in _SOPERATOR_NODESET_LABEL_KEYS:
        value = normalize_component_token(labels.get(key))
        if value:
            return value
    name = str(metadata.get("name", "") or "").strip()
    return re.sub(r"-[0-9]+$", "", name)


def _gpu_driver_jail_init_passed(item: Mapping[str, Any]) -> bool:
    for status in _sequence_of_mappings(_mapping(item.get("status")).get("initContainerStatuses")):
        if str(status.get("name", "") or "").strip() != (
            SOPERATOR_GPU_DRIVER_JAIL_INIT_CONTAINER_NAME
        ):
            continue
        terminated = _mapping(_mapping(status.get("state")).get("terminated"))
        return _nonnegative_int(terminated.get("exitCode"), fallback=-1) == 0
    return False


