def _jail_gpu_exact_worker_exec(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    worker: Mapping[str, Any],
    args: Sequence[str],
    timeout_seconds: int,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> SoperatorMigrationCommandResult:
    pod_name = str(worker.get("pod") or "").strip()
    pod_uid = str(worker.get("pod_uid") or "").strip()
    kubernetes_node = str(worker.get("node") or "").strip()
    if not pod_name or not pod_uid or not kubernetes_node:
        raise SoperatorMigrationPhasePending(
            "GPU post-activation gate lacks an exact worker Pod UID/node binding."
        )
    exists, pod = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource=f"pod/{pod_name}",
    )
    if (
        not exists
        or str(_mapping(pod.get("metadata")).get("uid") or "").strip() != pod_uid
        or str(_mapping(pod.get("spec")).get("nodeName") or "").strip() != kubernetes_node
        or not _pod_is_ready(pod)
    ):
        raise SoperatorMigrationPhasePending(
            "GPU post-activation worker Pod changed identity, node, or readiness."
        )
    return command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_name,
            "-c",
            "slurmd",
            "--",
            *args,
        ],
        check=False,
        timeout_seconds=timeout_seconds,
    )


_JAIL_GPU_DCGM_RUNTIME_SCRIPT = r"""
set -euo pipefail
readonly jail_root=/mnt/jail
driver_version="$(nvidia-smi --query-gpu=driver_version --format=csv,noheader \
  | head -n 1 | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
driver_major="${driver_version%%.*}"
case "${driver_major}" in
  ''|*[!0-9]*) exit 41 ;;
esac
cuda_major=12
if [ "${driver_major}" -ge 580 ]; then
  cuda_major=13
fi
package="datacenter-gpu-manager-4-cuda${cuda_major}"
plugin_dir="/usr/libexec/datacenter-gpu-manager-4/plugins/cuda${cuda_major}"
core_version="$(chroot "${jail_root}" dpkg-query -W -f='${Version}' \
  datacenter-gpu-manager-4-core)"
[ -n "${core_version}" ]
action=verified
if [ ! -d "${jail_root}${plugin_dir}" ]; then
  chroot "${jail_root}" /bin/bash -lc '
set -euo pipefail
exec flock /var/lock/cxcli-dcgm-runtime.lock \
  apt-get install -y --no-install-recommends --reinstall "$1=$2"
' cxcli-dcgm-runtime "${package}" "${core_version}"
  action=installed
fi
package_version="$(chroot "${jail_root}" dpkg-query -W -f='${Version}' "${package}")"
[ "${package_version}" = "${core_version}" ]
[ -d "${jail_root}${plugin_dir}" ]
printf 'CXCLI_DCGM_ACTION=%s\n' "${action}"
printf 'CXCLI_DCGM_DRIVER_VERSION=%s\n' "${driver_version}"
printf 'CXCLI_DCGM_CUDA_MAJOR=%s\n' "${cuda_major}"
printf 'CXCLI_DCGM_PACKAGE=%s\n' "${package}"
printf 'CXCLI_DCGM_PACKAGE_VERSION=%s\n' "${package_version}"
printf 'CXCLI_DCGM_PLUGIN_DIR=%s\n' "${plugin_dir}"
"""


def _jail_gpu_dcgm_runtime_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    worker: Mapping[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> dict[str, Any]:
    """Align the Jail DCGM diagnostic runtime with the live host driver branch."""

    result = _jail_gpu_exact_worker_exec(
        command_runner=command_runner,
        kube_context=kube_context,
        worker=worker,
        args=("/bin/bash", "-c", _JAIL_GPU_DCGM_RUNTIME_SCRIPT),
        timeout_seconds=900,
        namespace=namespace,
    )
    markers = {
        key: value.strip()
        for line in result.stdout.splitlines()
        if line.startswith("CXCLI_DCGM_") and "=" in line
        for key, value in (line.split("=", 1),)
    }
    required = {
        "CXCLI_DCGM_ACTION",
        "CXCLI_DCGM_DRIVER_VERSION",
        "CXCLI_DCGM_CUDA_MAJOR",
        "CXCLI_DCGM_PACKAGE",
        "CXCLI_DCGM_PACKAGE_VERSION",
        "CXCLI_DCGM_PLUGIN_DIR",
    }
    if (
        result.returncode != 0
        or not required.issubset(markers)
        or markers.get("CXCLI_DCGM_ACTION") not in {"installed", "verified"}
        or markers.get("CXCLI_DCGM_CUDA_MAJOR") not in {"12", "13"}
    ):
        raise SoperatorMigrationPhasePending(
            "Jail DCGM runtime could not be aligned with the live GPU driver branch: "
            + _command_detail(result)
        )
    checked_at = _utc_now()
    evidence = {
        "status": "passed",
        "action": markers["CXCLI_DCGM_ACTION"],
        "driver_version": markers["CXCLI_DCGM_DRIVER_VERSION"],
        "cuda_major": markers["CXCLI_DCGM_CUDA_MAJOR"],
        "package": markers["CXCLI_DCGM_PACKAGE"],
        "package_version": markers["CXCLI_DCGM_PACKAGE_VERSION"],
        "plugin_dir": markers["CXCLI_DCGM_PLUGIN_DIR"],
        "checked_at": checked_at,
        "stdout_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
    }
    if markers["CXCLI_DCGM_ACTION"] == "installed":
        evidence["installed_at"] = checked_at
    return evidence


def _jail_gpu_health_checker_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    worker: Mapping[str, Any],
    slurm_node: str,
    gpu_count: int,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> dict[str, Any]:
    result = _jail_gpu_exact_worker_exec(
        command_runner=command_runner,
        kube_context=kube_context,
        worker=worker,
        args=("/bin/bash", "-c", _JAIL_GPU_FULL_HEALTH_CHECK_SCRIPT),
        timeout_seconds=900,
        namespace=namespace,
    )
    payloads: list[Mapping[str, Any]] = []
    for line in result.stdout.splitlines():
        try:
            candidate = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(candidate, Mapping) and str(candidate.get("status") or "").strip():
            payloads.append(candidate)
    health_payload = payloads[-1] if payloads else {}
    failed_checks: list[str] = []
    for test in _sequence_of_mappings(_mapping(health_payload).get("tests")):
        test_name = str(test.get("name") or "").strip()
        for check in _sequence_of_mappings(test.get("checks")):
            check_name = str(check.get("name") or "").strip()
            status = str(_mapping(check.get("state")).get("status") or "").strip().upper()
            if status in {"ERROR", "FAIL", "FAILED"}:
                failed_checks.append(".".join(part for part in (test_name, check_name) if part))
    if (
        result.returncode != 0
        or str(_mapping(health_payload).get("status") or "").strip().upper() != "PASS"
        or failed_checks
    ):
        raise SoperatorMigrationPhasePending(
            "full GPU health-checker did not return an unambiguous PASS on the pinned worker: "
            + _command_detail(result)
        )
    return {
        "status": "passed",
        "node_name": slurm_node,
        "gpu_count": gpu_count,
        "failed_checks": [],
        "result_sha256": _fingerprint(health_payload),
        "stdout_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
        "stderr_sha256": hashlib.sha256(result.stderr.encode("utf-8")).hexdigest(),
    }


def _jail_gpu_slurm_node_name(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    worker: Mapping[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> str:
    candidate = str(worker.get("pod") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", candidate):
        raise SoperatorMigrationPhasePending(
            "GPU post-activation gate lacks one safe worker Pod name to verify with Slurm."
        )
    result = _jail_gpu_exact_worker_exec(
        command_runner=command_runner,
        kube_context=kube_context,
        worker=worker,
        args=("scontrol", "show", "node", candidate, "-o"),
        timeout_seconds=60,
        namespace=namespace,
    )
    node_names = re.findall(r"(?:^|\s)NodeName=([^\s]+)", result.stdout)
    if result.returncode != 0 or node_names != [candidate]:
        raise SoperatorMigrationPhasePending(
            "GPU post-activation gate could not prove the exact worker Pod name as one "
            "canonical Slurm node."
        )
    return candidate


def _jail_gpu_temporary_partition_fields(output: str) -> dict[str, str]:
    return {
        match.group(1): match.group(2)
        for match in re.finditer(r"(?:^|\s)([A-Za-z][A-Za-z0-9]*)=([^\s]+)", output)
    }


def _jail_gpu_partition_missing(result: SoperatorMigrationCommandResult) -> bool:
    if result.returncode == 0:
        return False
    # kubectl writes the remote command's diagnostic to stdout, then writes its
    # own generic "command terminated" wrapper to stderr.  Inspect both streams
    # so the wrapper cannot hide Slurm's authoritative not-found response.
    detail = "\n".join((result.stdout, result.stderr)).lower()
    return bool(re.search(r"(?:^|\n)partition\s+\S+\s+not found(?:\s|$)", detail)) or any(
        marker in detail
        for marker in (
            "invalid partition name specified",
            "invalid partition",
            "partition does not exist",
            "partition not found",
        )
    )


def _ensure_jail_gpu_temporary_partition(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: dict[str, Any],
    slurm_node: str,
    checkpoint_writer: Callable[[], None] | None,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> str:
    partition_name = str(state.get("partition_name") or "").strip()
    if not partition_name:
        partition_name = f"cxcli-gpu-{uuid4().hex[:12]}"
        state.update(
            {
                "partition_name": partition_name,
                "partition_status": "intent-recorded",
                "partition_intent_at": _utc_now(),
                "slurm_node": slurm_node,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if (
        not re.fullmatch(r"cxcli-gpu-[0-9a-f]{12}", partition_name)
        or str(state.get("slurm_node") or "").strip() != slurm_node
    ):
        raise SoperatorMigrationPhasePending(
            "GPU post-activation temporary partition checkpoint binding is invalid or drifted."
        )
    observed = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=("scontrol", "show", "partition", partition_name, "-o"),
        timeout_seconds=60,
    )
    if observed.returncode != 0:
        if not _jail_gpu_partition_missing(observed):
            raise SoperatorMigrationPhasePending(
                "could not determine whether the root-only GPU smoke partition exists: "
                + _command_detail(observed)
            )
        if str(state.get("partition_status") or "") == "created":
            smoke = _mapping(state.get("pinned_h100_smoke"))
            if str(smoke.get("status") or ""):
                raise SoperatorMigrationPhasePending(
                    "checkpointed GPU smoke partition disappeared before terminal cleanup."
                )
            recreations = state.setdefault("partition_recreations", [])
            if not isinstance(recreations, list):
                raise SoperatorMigrationPhasePending(
                    "GPU smoke partition recreation history is malformed."
                )
            recreation = {
                "partition_name": partition_name,
                "slurm_node": slurm_node,
                "prior_contract_sha256": str(state.get("partition_contract_sha256") or ""),
                "terminal_attempt_count": len(_sequence_of_mappings(smoke.get("attempt_history"))),
                "intent_at": _utc_now(),
            }
            recreations.append(recreation)
            state["partition_status"] = "recreate-intent"
            if checkpoint_writer is not None:
                checkpoint_writer()
        created = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=(
                "scontrol",
                "create",
                f"PartitionName={partition_name}",
                f"Nodes={slurm_node}",
                "Default=NO",
                "MaxTime=00:10:00",
                "RootOnly=YES",
                "State=UP",
            ),
            timeout_seconds=60,
        )
        if created.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "could not create the root-only temporary GPU smoke partition: "
                + _command_detail(created)
            )
        observed = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("scontrol", "show", "partition", partition_name, "-o"),
            timeout_seconds=60,
        )
    fields = _jail_gpu_temporary_partition_fields(observed.stdout)
    if (
        observed.returncode != 0
        or fields.get("PartitionName") != partition_name
        or fields.get("Nodes") != slurm_node
        or fields.get("RootOnly") != "YES"
        or fields.get("State") != "UP"
    ):
        raise SoperatorMigrationPhasePending(
            "temporary GPU smoke partition does not match the exact root-only node contract."
        )
    state["partition_status"] = "created"
    state["partition_contract_sha256"] = _fingerprint(
        {
            "PartitionName": partition_name,
            "Nodes": slurm_node,
            "RootOnly": "YES",
            "State": "UP",
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    recreations = state.get("partition_recreations")
    if isinstance(recreations, list) and recreations:
        latest = recreations[-1]
        if isinstance(latest, dict) and not latest.get("created_at"):
            latest["created_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
    return partition_name


def _delete_jail_gpu_temporary_partition(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> None:
    partition_name = str(state.get("partition_name") or "").strip()
    if not partition_name:
        raise SoperatorMigrationPhasePending(
            "GPU smoke partition cleanup lacks its checkpointed exact name."
        )
    deleted = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=("scontrol", "delete", f"PartitionName={partition_name}"),
        timeout_seconds=60,
    )
    observed = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=("scontrol", "show", "partition", partition_name, "-o"),
        timeout_seconds=60,
    )
    if observed.returncode == 0:
        state["partition_status"] = "cleanup-pending"
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "root-only temporary GPU smoke partition still exists after cleanup: "
            + _command_detail(deleted)
        )
    if not _jail_gpu_partition_missing(observed):
        state["partition_status"] = "cleanup-pending"
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "could not prove deletion of the root-only temporary GPU smoke partition: "
            + _command_detail(observed)
        )
    state["partition_status"] = "deleted"
    state["partition_deleted_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()


_JAIL_GPU_SMOKE_RETRYABLE_TERMINAL_STATES = frozenset(
    {
        "BOOT_FAIL",
        "CANCELLED",
        "DEADLINE",
        "FAILED",
        "NODE_FAIL",
        "OUT_OF_MEMORY",
        "PREEMPTED",
        "REVOKED",
        "TIMEOUT",
    }
)

_JAIL_GPU_SMOKE_UNAVAILABLE_NODE_STATES = frozenset(
    {
        "DOWN",
        "DRAIN",
        "FAIL",
        "FAILING",
        "INVALID_REG",
        "NO_RESPOND",
        "POWER_DOWN",
    }
)


def _jail_gpu_smoke_node_unavailable_reason(evidence: Mapping[str, Any]) -> str:
    if int(evidence.get("returncode") or 0) != 0:
        return "Slurm node inspection failed"
    raw_state = str(evidence.get("state") or "").strip().upper()
    states = {token for token in re.split(r"[+~#*]+", raw_state) if token}
    unavailable = sorted(states & _JAIL_GPU_SMOKE_UNAVAILABLE_NODE_STATES)
    if not raw_state:
        return "Slurm node state is missing"
    if unavailable:
        reason = str(evidence.get("reason") or "").strip()
        detail = f" ({reason})" if reason else ""
        return "Slurm node is not dispatchable: " + ", ".join(unavailable) + detail
    return ""


def _reconcile_jail_gpu_terminal_failed_smoke(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    smoke: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
    namespace: str,
) -> bool:
    """Release only an exact, uniquely terminal failed smoke attempt for retry."""

    job_name = str(smoke.get("job_name") or "").strip()
    if not re.fullmatch(r"cxcli-h100-[0-9a-f]{12}", job_name):
        return False
    accounting = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=(
            "sacct",
            "-nX",
            f"--starttime={_post_jail_live_job_accounting_start(smoke)}",
            f"--name={job_name}",
            "-o",
            "JobIDRaw,JobName,NodeList,State,ExitCode",
            "-P",
        ),
        timeout_seconds=60,
    )
    if accounting.returncode != 0:
        return False
    matches: list[dict[str, str]] = []
    for line in accounting.stdout.splitlines():
        fields = line.split("|")
        if len(fields) != 5 or fields[1].strip() != job_name:
            continue
        job_id = fields[0].strip()
        state = fields[3].strip().split(maxsplit=1)[0].split("+", 1)[0].upper()
        if not re.fullmatch(r"[1-9][0-9]*", job_id):
            continue
        matches.append(
            {
                "job_id": job_id,
                "job_name": job_name,
                "node_list": fields[2].strip(),
                "state": state,
                "exit_code": fields[4].strip(),
            }
        )
    if len(matches) != 1 or matches[0]["state"] not in _JAIL_GPU_SMOKE_RETRYABLE_TERMINAL_STATES:
        return False
    active = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=("squeue", "-h", "-j", matches[0]["job_id"], "-o", "%i|%j|%T"),
        timeout_seconds=60,
    )
    active_missing = bool(
        active.returncode != 0
        and _slurm_action_error_is_job_missing(RuntimeError(_command_detail(active)))
    )
    if not ((active.returncode == 0 and not active.stdout.strip()) or active_missing):
        return False
    history = smoke.get("attempt_history")
    if not isinstance(history, list):
        history = []
    history.append(
        {
            **matches[0],
            "reconciled_at": _utc_now(),
            "result_sha256": str(smoke.get("result_sha256") or ""),
            "reason": str(smoke.get("reason") or ""),
        }
    )
    smoke.clear()
    smoke.update({"status": "", "attempt_history": history})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return True


def _reconcile_jail_gpu_unstartable_indeterminate_smoke(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    smoke: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
    namespace: str,
) -> bool:
    """Cancel only one exact checkpointed smoke that cannot start on its bound node."""

    if str(smoke.get("status") or "") != "Indeterminate":
        return False
    job_name = str(smoke.get("job_name") or "").strip()
    slurm_node = str(smoke.get("node_name") or "").strip()
    partition_name = str(smoke.get("partition_name") or "").strip()
    if (
        not re.fullmatch(r"cxcli-h100-[0-9a-f]{12}", job_name)
        or not slurm_node
        or not re.fullmatch(r"cxcli-gpu-[0-9a-f]{12}", partition_name)
    ):
        return False
    if _reconcile_jail_gpu_terminal_failed_smoke(
        command_runner=command_runner,
        kube_context=kube_context,
        smoke=smoke,
        checkpoint_writer=checkpoint_writer,
        namespace=namespace,
    ):
        return True
    cancellation = smoke.get("unstartable_cancellation")
    if cancellation is not None and not isinstance(cancellation, dict):
        raise SoperatorMigrationPhasePending(
            "pinned H100 smoke unstartable cancellation checkpoint is malformed."
        )
    cancellation = cancellation if isinstance(cancellation, dict) else {}
    job_id = str(cancellation.get("job_id") or "").strip()
    if not job_id:
        queued = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("squeue", "-h", f"--name={job_name}", "-o", "%i|%j|%T"),
            timeout_seconds=60,
        )
        rows = [line.strip().split("|") for line in queued.stdout.splitlines() if line.strip()]
        if (
            queued.returncode != 0
            or len(rows) != 1
            or len(rows[0]) != 3
            or rows[0][1].strip() != job_name
            or rows[0][2].strip().upper() != "PENDING"
            or not re.fullmatch(r"[1-9][0-9]*", rows[0][0].strip())
        ):
            return False
        job_id = rows[0][0].strip()
        job = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("scontrol", "show", "job", job_id, "-o"),
            timeout_seconds=60,
        )
        fields = _jail_gpu_temporary_partition_fields(job.stdout)
        if (
            job.returncode != 0
            or fields.get("JobId") != job_id
            or fields.get("JobName") != job_name
            or fields.get("JobState", "").upper() != "PENDING"
            or fields.get("Partition") != partition_name
            or fields.get("ReqNodeList") != slurm_node
        ):
            return False
        node_evidence = _jail_gpu_slurm_node_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            slurm_node=slurm_node,
            namespace=namespace,
        )
        unavailable_reason = _jail_gpu_smoke_node_unavailable_reason(node_evidence)
        if not unavailable_reason:
            return False
        cancellation.update(
            {
                "status": "intent",
                "job_id": job_id,
                "job_name": job_name,
                "node_name": slurm_node,
                "partition_name": partition_name,
                "node_evidence": node_evidence,
                "reason": unavailable_reason,
                "intent_at": _utc_now(),
            }
        )
        smoke["unstartable_cancellation"] = cancellation
        if checkpoint_writer is not None:
            checkpoint_writer()
    if cancellation.get("status") == "intent":
        cancelled = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("scancel", job_id),
            timeout_seconds=60,
        )
        if cancelled.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "pinned H100 smoke could not cancel its exact unstartable job: "
                + _command_detail(cancelled)
            )
        cancellation["status"] = "dispatched"
        cancellation["dispatched_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    if _reconcile_jail_gpu_terminal_failed_smoke(
        command_runner=command_runner,
        kube_context=kube_context,
        smoke=smoke,
        checkpoint_writer=checkpoint_writer,
        namespace=namespace,
    ):
        return True
    raise SoperatorMigrationPhasePending(
        "pinned H100 smoke cancellation was dispatched for its exact unstartable job; "
        "waiting for terminal Slurm accounting evidence."
    )


def _jail_gpu_pinned_h100_smoke(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: dict[str, Any],
    slurm_node: str,
    expected_gpu_count: int,
    checkpoint_writer: Callable[[], None] | None,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> dict[str, Any]:
    smoke = state.setdefault("pinned_h100_smoke", {})
    if not isinstance(smoke, dict):
        raise RuntimeError("gpu_post_activation.pinned_h100_smoke must be a mapping.")
    if expected_gpu_count <= 0:
        raise SoperatorMigrationPhasePending(
            "pinned H100 smoke requires a positive exact worker GPU count."
        )
    if str(smoke.get("status") or "") == "passed":
        if (
            str(smoke.get("node_name") or "") != slurm_node
            or int(smoke.get("expected_gpu_count") or 0) != expected_gpu_count
        ):
            raise SoperatorMigrationPhasePending(
                "checkpointed H100 smoke result is bound to a different Slurm node."
            )
        return dict(smoke)
    smoke_status = str(smoke.get("status") or "")
    if smoke_status in {
        "dispatching",
        "Indeterminate",
    }:
        reconciled = _reconcile_jail_gpu_terminal_failed_smoke(
            command_runner=command_runner,
            kube_context=kube_context,
            smoke=smoke,
            checkpoint_writer=checkpoint_writer,
            namespace=namespace,
        )
        if not reconciled and smoke_status == "Indeterminate":
            reconciled = _reconcile_jail_gpu_unstartable_indeterminate_smoke(
                command_runner=command_runner,
                kube_context=kube_context,
                smoke=smoke,
                checkpoint_writer=checkpoint_writer,
                namespace=namespace,
            )
        if reconciled:
            smoke_status = str(smoke.get("status") or "")
        else:
            if smoke_status == "dispatching":
                smoke["status"] = "Indeterminate"
                smoke["reason"] = (
                    "the pinned H100 srun response was lost; cxcli will not blindly retry an "
                    "uncertain Slurm dispatch"
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
            raise SoperatorMigrationPhasePending(
                str(smoke.get("reason") or "pinned H100 smoke dispatch remains Indeterminate")
            )
    pre_dispatch_node = _jail_gpu_slurm_node_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        slurm_node=slurm_node,
        namespace=namespace,
    )
    state["pre_dispatch_slurm_node"] = pre_dispatch_node
    unavailable_reason = _jail_gpu_smoke_node_unavailable_reason(pre_dispatch_node)
    if unavailable_reason:
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "pinned H100 smoke refused a Slurm dispatch that cannot start: " + unavailable_reason
        )
    partition_name = _ensure_jail_gpu_temporary_partition(
        command_runner=command_runner,
        kube_context=kube_context,
        state=state,
        slurm_node=slurm_node,
        checkpoint_writer=checkpoint_writer,
        namespace=namespace,
    )
    job_name = str(smoke.get("job_name") or "").strip()
    if not job_name:
        job_name = f"cxcli-h100-{uuid4().hex[:12]}"
        smoke.update(
            {
                "status": "prepared",
                "job_name": job_name,
                "node_name": slurm_node,
                "expected_gpu_count": expected_gpu_count,
                "partition_name": partition_name,
                "command_sha256": hashlib.sha256(
                    _JAIL_GPU_PINNED_H100_SCRIPT.encode("utf-8")
                ).hexdigest(),
                "prepared_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if (
        not re.fullmatch(r"cxcli-h100-[0-9a-f]{12}", job_name)
        or str(smoke.get("node_name") or "") != slurm_node
        or str(smoke.get("partition_name") or "") != partition_name
        or int(smoke.get("expected_gpu_count") or 0) != expected_gpu_count
    ):
        raise SoperatorMigrationPhasePending(
            "pinned H100 smoke checkpoint identity or node binding is invalid."
        )
    smoke["status"] = "dispatching"
    smoke["dispatch_started_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    result = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=(
            "srun",
            f"--job-name={job_name}",
            f"--partition={partition_name}",
            "--nodes=1",
            f"--nodelist={slurm_node}",
            f"--gres=gpu:{expected_gpu_count}",
            "--exclusive",
            "--time=00:05:00",
            "--wait=60",
            "/bin/bash",
            "-c",
            _JAIL_GPU_PINNED_H100_SCRIPT,
            "cxcli-h100-smoke",
            slurm_node,
        ),
        timeout_seconds=600,
    )
    marker = re.search(
        r"(?m)^cxcli-h100-smoke job_id=([1-9][0-9]*) node=([A-Za-z0-9_.-]+) "
        r"gpu_count=([1-9][0-9]*) product=([^\r\n]+)$",
        result.stdout,
    )
    if result.returncode != 0 or marker is None or marker.group(2) != slurm_node:
        smoke.update(
            {
                "status": "Indeterminate",
                "finished_at": _utc_now(),
                "result_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
                "reason": (
                    "the pinned H100 srun did not return canonical terminal evidence; its "
                    "dispatch outcome is Indeterminate and cxcli will not blindly retry: "
                    + _command_detail(result)
                ),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(str(smoke["reason"]))
    product = marker.group(4).strip()
    if "h100" not in product.lower():
        raise SoperatorMigrationPhasePending(
            "pinned GPU smoke did not report an NVIDIA H100 product."
        )
    smoke.update(
        {
            "status": "passed",
            "passed_at": _utc_now(),
            "job_id": marker.group(1),
            "node_name": slurm_node,
            "pinned": True,
            "gpu_count": int(marker.group(3)),
            "gpu_product": product,
            "stdout_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
            "stderr_sha256": hashlib.sha256(result.stderr.encode("utf-8")).hexdigest(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return dict(smoke)


def _jail_gpu_smoke_terminal_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    smoke: Mapping[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
    timeout_seconds: int = 600,
) -> dict[str, Any]:
    job_id = str(smoke.get("job_id") or "").strip()
    job_name = str(smoke.get("job_name") or "").strip()
    slurm_node = str(smoke.get("node_name") or "").strip()
    if (
        not _valid_post_jail_live_job_id(job_id)
        or not re.fullmatch(r"cxcli-h100-[0-9a-f]{12}", job_name)
        or not slurm_node
    ):
        raise SoperatorMigrationPhasePending(
            "pinned H100 smoke lacks an exact Slurm job/name/node identity."
        )
    deadline = time.monotonic() + timeout_seconds
    while True:
        result = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=(
                "sacct",
                "-nX",
                "-j",
                job_id,
                "--format=JobIDRaw,JobName,State,ExitCode,NodeList",
                "-P",
            ),
            timeout_seconds=60,
        )
        rows = [line.strip().split("|") for line in result.stdout.splitlines() if line.strip()]
        allocation_rows = [
            row for row in rows if len(row) >= 5 and row[0].strip() == job_id and "." not in row[0]
        ]
        if result.returncode == 0 and len(allocation_rows) == 1:
            row = [field.strip() for field in allocation_rows[0]]
            state = row[2].split(maxsplit=1)[0].split("+", 1)[0].upper()
            if state == "COMPLETED":
                if row[1] != job_name or row[3] != "0:0" or row[4] != slurm_node:
                    raise SoperatorMigrationPhasePending(
                        "pinned H100 smoke accounting identity, node, or exit code did not verify."
                    )
                return {
                    "status": "passed",
                    "job_id": job_id,
                    "job_name": job_name,
                    "state": state,
                    "exit_code": row[3],
                    "node_name": row[4],
                    "observation_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
                }
            if state in {
                "BOOT_FAIL",
                "CANCELLED",
                "DEADLINE",
                "FAILED",
                "NODE_FAIL",
                "OUT_OF_MEMORY",
                "PREEMPTED",
                "TIMEOUT",
            }:
                raise SoperatorMigrationPhasePending(
                    f"pinned H100 smoke entered terminal state {state}."
                )
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "pinned H100 smoke did not reach an exact COMPLETED 0:0 accounting record "
                "after its worker epilog."
            )
        time.sleep(2.0)


def _jail_gpu_slurm_node_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    slurm_node: str,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> dict[str, Any]:
    result = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=("scontrol", "show", "node", slurm_node, "-o"),
        timeout_seconds=60,
    )
    fields = _jail_gpu_temporary_partition_fields(result.stdout)
    reason = str(fields.get("Reason") or "").strip()
    if reason.lower() in {"none", "(null)"}:
        reason = ""
    return {
        "node_name": slurm_node,
        "state": str(fields.get("State") or "").strip(),
        "reason": reason,
        "observation_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
        "returncode": result.returncode,
    }


def _gpu_topology_replay_slurm_node_contract(
    *,
    output: str,
    node_name: str,
    gpu_count: int,
    topology: Mapping[str, Any],
) -> tuple[bool, bool]:
    fields = _jail_gpu_temporary_partition_fields(output)
    configured_gres = str(topology.get("gres") or f"gpu:{gpu_count}").strip().lower()
    gres_matches = bool(
        re.fullmatch(
            rf"{re.escape(configured_gres)}(?:\(s:[^)]+\))?",
            str(fields.get("Gres") or "").lower(),
        )
    )
    state_tokens = {
        token for token in re.split(r"[+~#*]+", str(fields.get("State") or "").upper()) if token
    }
    observed_sockets = _positive_int(fields.get("Sockets"), fallback=0)
    observed_cores = _positive_int(fields.get("CoresPerSocket"), fallback=0)
    observed_threads = _positive_int(fields.get("ThreadsPerCore"), fallback=0)
    configured_cpus = _positive_int(topology.get("cpus"), fallback=0)
    cpu_topology_matches = bool(
        (
            observed_sockets == _positive_int(topology.get("sockets"), fallback=0)
            and observed_cores == _positive_int(topology.get("cores_per_socket"), fallback=0)
            and observed_threads == _positive_int(topology.get("threads_per_core"), fallback=0)
        )
        or (
            topology.get("parameters") == "l3cache_as_socket"
            and observed_sockets == configured_cpus
            and observed_cores == 1
            and observed_threads == 1
        )
    )
    topology_matches = bool(
        fields.get("NodeName") == node_name
        and _positive_int(fields.get("CPUTot"), fallback=0) == configured_cpus
        and _positive_int(fields.get("Boards"), fallback=0)
        == _positive_int(topology.get("boards"), fallback=0)
        and cpu_topology_matches
        and fields.get("Parameters") == topology.get("parameters") == "l3cache_as_socket"
        and gres_matches
        and _non_negative_int(fields.get("CPUAlloc"), fallback=-1) == 0
        and _non_negative_int(fields.get("AllocMem"), fallback=-1) == 0
        and "INVALID_REG" not in state_tokens
    )
    stale_reason = bool(
        re.search(
            rf"Reason=gres/gpu GRES autodetected core affinity [0-9]+-[0-9]+ on node "
            rf"{re.escape(node_name)} doesn't match socket boundaries\..*"
            r"Consider setting Parameters=l3cache_as_socket as part of the Node configuration\.",
            output,
        )
    )
    drain_is_exact_stale_topology = bool(
        topology_matches and "DRAIN" in state_tokens and "IDLE" in state_tokens and stale_reason
    )
    ready_after_resume = bool(
        topology_matches
        and "DRAIN" not in state_tokens
        and "DOWN" not in state_tokens
        and "IDLE" in state_tokens
        and str(fields.get("Reason") or "").lower() in {"", "none", "(null)"}
    )
    return drain_is_exact_stale_topology, ready_after_resume


def _gpu_typed_gres_stale_slurmd_contract(
    *,
    output: str,
    node_name: str,
    gpu_count: int,
    topology: Mapping[str, Any],
) -> bool:
    """Recognize only a stale generic-GRES process after a typed-GRES replay."""

    fields = _jail_gpu_temporary_partition_fields(output)
    configured_gres = str(topology.get("gres") or "").strip().lower()
    generic_gres = str(fields.get("Gres") or "").strip().lower()
    state_tokens = {
        token for token in re.split(r"[+~#*]+", str(fields.get("State") or "").upper()) if token
    }
    typed_match = re.fullmatch(r"gpu:([a-z0-9_]+):([1-9][0-9]*)", configured_gres)
    if typed_match is None or int(typed_match.group(2)) != gpu_count:
        return False
    reason_matches = bool(
        re.search(
            rf"(?:^|\s)Reason=gres/gpu:{re.escape(typed_match.group(1))} count too low "
            rf"\(0 < {gpu_count}\)(?: \[[^\]]+\])?(?:\s|$)",
            output,
        )
    )
    return bool(
        fields.get("NodeName") == node_name
        and re.fullmatch(rf"gpu:{gpu_count}(?:\(s:[^)]+\))?", generic_gres)
        and {"DOWN", "INVALID_REG"} <= state_tokens
        and _non_negative_int(fields.get("CPUAlloc"), fallback=-1) == 0
        and _non_negative_int(fields.get("AllocMem"), fallback=-1) == 0
        and reason_matches
    )


def _gpu_typed_gres_slurmd_config_contract(
    *,
    output: str,
    node_name: str,
    gpu_count: int,
    topology: Mapping[str, Any],
) -> bool:
    """Verify the exact typed-GRES topology produced by the pod's current jail config."""

    first_line = next((line.strip() for line in output.splitlines() if line.strip()), "")
    fields = _jail_gpu_temporary_partition_fields(first_line)
    configured_gres = str(topology.get("gres") or "").strip().lower()
    return bool(
        fields.get("NodeName") == node_name
        and _positive_int(fields.get("CPUs"), fallback=0)
        == _positive_int(topology.get("cpus"), fallback=0)
        and _positive_int(fields.get("Boards"), fallback=0)
        == _positive_int(topology.get("boards"), fallback=0)
        and _positive_int(fields.get("SocketsPerBoard"), fallback=0)
        == _positive_int(topology.get("sockets"), fallback=0)
        and _positive_int(fields.get("CoresPerSocket"), fallback=0)
        == _positive_int(topology.get("cores_per_socket"), fallback=0)
        and _positive_int(fields.get("ThreadsPerCore"), fallback=0)
        == _positive_int(topology.get("threads_per_core"), fallback=0)
        and _positive_int(gpu_count, fallback=0) > 0
        and str(fields.get("Gres") or "").strip().lower() == configured_gres
    )


def _rollover_gpu_typed_gres_stale_worker_processes(
    *,
    phase: dict[str, Any],
    replay: Mapping[str, Any],
    release_gate: Mapping[str, Any],
    stale_workers: Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None],
    mutation_guard: Callable[[], None] | None,
    timeout_seconds: int = 900,
) -> list[str]:
    """Restart only exact stale slurmd Pods, issuing all deletes before waiting."""

    requested = tuple(dict.fromkeys(str(name or "").strip() for name in stale_workers))
    state = phase.setdefault("gpu_typed_gres_worker_rollover", {})
    if not isinstance(state, dict):
        raise SoperatorMigrationPhasePending("typed-GRES worker rollover checkpoint is malformed.")
    checkpoint_workers = tuple(_string_sequence(state.get("workers")))
    if checkpoint_workers:
        if not set(requested) <= set(checkpoint_workers):
            raise SoperatorMigrationPhasePending(
                "typed-GRES worker rollover live stale set drifted from its checkpoint."
            )
        requested = checkpoint_workers
    workers = {
        str(worker.get("pod") or "").strip(): worker
        for worker in _sequence_of_mappings(release_gate.get("workers"))
    }
    topology_by_nodeset = _mapping(replay.get("topology_by_nodeset"))
    workload_bindings = _mapping(release_gate.get("nodeset_workload_bindings"))
    if not requested or any(not name or name not in workers for name in requested):
        raise SoperatorMigrationPhasePending(
            "typed-GRES worker rollover lacks exact release-gate worker identities."
        )
    binding = {
        "schema": _GPU_TYPED_GRES_WORKER_ROLLOVER_SCHEMA,
        "workers": list(requested),
        "topology_replay_fingerprint": _fingerprint(replay),
        "workload_bindings": {
            nodeset: {
                "nodeset_uid": str(_mapping(record).get("nodeset_uid") or "").strip(),
                "workload_uid": str(_mapping(record).get("workload_uid") or "").strip(),
            }
            for nodeset, record in sorted(workload_bindings.items())
        },
    }
    if any(not all(record.values()) for record in binding["workload_bindings"].values()):
        raise SoperatorMigrationPhasePending(
            "typed-GRES worker rollover lacks exact NodeSet and StatefulSet identities."
        )
    if state and any(state.get(key) != value for key, value in binding.items()):
        raise SoperatorMigrationPhasePending(
            "typed-GRES worker rollover binding drifted from its checkpoint."
        )
    old_pods = state.setdefault("old_pods", {})
    if not isinstance(old_pods, dict):
        raise SoperatorMigrationPhasePending(
            "typed-GRES worker rollover old-Pod checkpoint is malformed."
        )

    for pod_name in requested:
        worker = workers[pod_name]
        nodeset = str(worker.get("nodeset") or "").strip()
        topology = _mapping(topology_by_nodeset.get(nodeset))
        workload_uid = str(_mapping(workload_bindings.get(nodeset)).get("workload_uid") or "")
        pod = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=pod_name,
        )
        identity = _immutable_child_exact_identity(
            pod,
            label=f"typed-GRES stale worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
        )
        owner = _immutable_child_controller_owner(
            pod,
            label=f"typed-GRES stale worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
        )
        node_name = str(_mapping(pod.get("spec")).get("nodeName") or "").strip()
        prior = _mapping(old_pods.get(pod_name))
        if prior:
            continue
        if (
            identity["uid"] != str(worker.get("pod_uid") or "").strip()
            or node_name != str(worker.get("node") or "").strip()
            or str(_mapping(owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
            or str(_mapping(owner).get("kind") or "") != "StatefulSet"
            or str(_mapping(owner).get("name") or "") != nodeset
            or str(_mapping(owner).get("uid") or "") != workload_uid
            or not _pod_is_ready(pod)
        ):
            raise SoperatorMigrationPhasePending(
                f"typed-GRES worker rollover refuses non-matching Pod binding for {pod_name}."
            )
        config = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                pod_name,
                "-c",
                "slurmd",
                "--",
                "chroot",
                "/mnt/jail",
                "/usr/sbin/slurmd",
                "-C",
            ],
            timeout_seconds=60,
            check=False,
        )
        if config.returncode != 0 or not _gpu_typed_gres_slurmd_config_contract(
            output=config.stdout,
            node_name=pod_name,
            gpu_count=_positive_int(worker.get("gpu_count"), fallback=0),
            topology=topology,
        ):
            raise SoperatorMigrationPhasePending(
                f"typed-GRES worker rollover could not prove the new jail config for {pod_name}."
            )
        old_pods[pod_name] = {
            "uid": identity["uid"],
            "resource_version": identity["resourceVersion"],
            "node": node_name,
            "nodeset": nodeset,
            "statefulset_uid": workload_uid,
            "slurmd_config_sha256": hashlib.sha256(config.stdout.encode("utf-8")).hexdigest(),
        }
    state.update(
        {**binding, "status": "delete-intent", "intent_at": state.get("intent_at") or _utc_now()}
    )
    checkpoint_writer()

    for pod_name in requested:
        old = _mapping(old_pods.get(pod_name))
        if old.get("delete_accepted_at"):
            continue
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/pods/{pod_name}",
            uid=str(old.get("uid") or ""),
            resource_version=str(old.get("resource_version") or ""),
            propagation_policy="Background",
            timeout_seconds=300,
            mutation_guard=mutation_guard,
            wait_for_absence=False,
        )
        old_pods[pod_name]["delete_accepted_at"] = _utc_now()
        checkpoint_writer()

    state["status"] = "waiting-replacements"
    state["all_deletes_accepted_at"] = state.get("all_deletes_accepted_at") or _utc_now()
    checkpoint_writer()
    deadline = time.monotonic() + max(timeout_seconds, 0)
    replacements: dict[str, dict[str, str]] = {}
    while True:
        pending: list[str] = []
        for pod_name in requested:
            old = _mapping(old_pods.get(pod_name))
            pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=pod_name,
                label="typed-GRES worker replacement",
            )
            if pod is None:
                pending.append(pod_name)
                continue
            identity = _immutable_child_exact_identity(
                pod,
                label=f"typed-GRES replacement worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            owner = _immutable_child_controller_owner(
                pod,
                label=f"typed-GRES replacement worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            statuses = _sequence_of_mappings(_mapping(pod.get("status")).get("containerStatuses"))
            if identity["uid"] == str(old.get("uid") or "") or not _pod_is_ready(pod):
                pending.append(pod_name)
                continue
            if (
                str(_mapping(owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
                or str(_mapping(owner).get("kind") or "") != "StatefulSet"
                or str(_mapping(owner).get("name") or "") != str(old.get("nodeset") or "")
                or str(_mapping(owner).get("uid") or "") != str(old.get("statefulset_uid") or "")
                or str(_mapping(pod.get("spec")).get("nodeName") or "")
                != str(old.get("node") or "")
                or not statuses
                or any(
                    _non_negative_int(item.get("restartCount"), fallback=-1) != 0
                    for item in statuses
                )
            ):
                raise SoperatorMigrationPhasePending(
                    f"typed-GRES replacement Pod binding is invalid for {pod_name}."
                )
            replacements[pod_name] = {
                "uid": identity["uid"],
                "resource_version": identity["resourceVersion"],
                "node": str(old.get("node") or ""),
                "nodeset": str(old.get("nodeset") or ""),
                "statefulset_uid": str(old.get("statefulset_uid") or ""),
            }
        if not pending:
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "typed-GRES worker rollover timed out waiting for exact Ready replacements: "
                + ", ".join(pending)
            )
        time.sleep(2)
    state.update(
        {
            **binding,
            "status": "verified",
            "replacement_pods": replacements,
            "verified_at": _utc_now(),
        }
    )
    checkpoint_writer()
    return [
        "Typed-GRES lifecycle repair restarted "
        f"{len(requested)} stale worker process(es) in parallel and verified exact replacements."
    ]


def _reconcile_gpu_topology_replay_slurm_drains(
    *,
    phase: dict[str, Any],
    replacement_phase: Mapping[str, Any] | None,
    release_gate: Mapping[str, Any],
    values: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    namespace: str,
    mutation_guard: Callable[[], None] | None = None,
) -> list[str]:
    topology_phase = _mapping(replacement_phase)
    replay = _mapping(topology_phase.get("gpu_topology_values_replay"))
    if (
        replay.get("schema") != _GPU_TOPOLOGY_VALUES_REPLAY_SCHEMA
        or replay.get("status") != "verified"
    ):
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "GPU topology drain recovery requires durable checkpoint writes."
        )
    workers = sorted(
        _sequence_of_mappings(release_gate.get("workers")),
        key=lambda item: str(item.get("pod") or ""),
    )
    worker_names = [str(worker.get("pod") or "").strip() for worker in workers]
    if (
        not worker_names
        or any(not name for name in worker_names)
        or len(set(worker_names)) != len(worker_names)
    ):
        raise SoperatorMigrationPhasePending(
            "GPU topology drain recovery lacks unique verified worker identities."
        )

    partition_configuration = _mapping(values.get("partitionConfiguration"))
    target_partitions = {
        str(item.get("name") or "").strip()
        for item in _sequence_of_mappings(partition_configuration.get("partitions"))
        if str(item.get("name") or "").strip()
    }
    pause_by_name = {
        record.partition: record
        for record in _rolling_compute_checkpoint_pause_records(topology_phase)
        if record.partition in target_partitions
    }
    if not target_partitions or set(pause_by_name) != target_partitions:
        raise SoperatorMigrationPhasePending(
            "GPU topology drain recovery requires exact checkpointed target partition pauses."
        )
    pause_journal = {
        "partition_pause": [pause_by_name[name].as_payload() for name in sorted(pause_by_name)]
    }
    _reassert_controller_bridge_partition_pause_after_reconfigure(
        journal=pause_journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )

    queue = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        args=("squeue", "-h", "-o", "%i|%T|%N"),
        timeout_seconds=60,
    )
    if queue.returncode != 0 or queue.stdout.strip():
        raise SoperatorMigrationPhasePending(
            "GPU topology drain recovery requires an empty Slurm queue while all target "
            "partitions remain paused."
        )

    topology_by_nodeset = _mapping(replay.get("topology_by_nodeset"))
    typed_gres_stale: list[str] = []
    for worker in workers:
        node_name = str(worker.get("pod") or "").strip()
        nodeset = str(worker.get("nodeset") or "").strip()
        gpu_count = _positive_int(worker.get("gpu_count"), fallback=0)
        topology = _mapping(topology_by_nodeset.get(nodeset))
        observed = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("scontrol", "show", "node", node_name, "-o"),
            timeout_seconds=60,
        )
        stale, ready = _gpu_topology_replay_slurm_node_contract(
            output=observed.stdout,
            node_name=node_name,
            gpu_count=gpu_count,
            topology=topology,
        )
        stale_process = _gpu_typed_gres_stale_slurmd_contract(
            output=observed.stdout,
            node_name=node_name,
            gpu_count=gpu_count,
            topology=topology,
        )
        if observed.returncode != 0 or not (stale or ready or stale_process):
            raise SoperatorMigrationPhasePending(
                f"GPU topology drain recovery refuses non-matching Slurm state for {node_name}."
            )
        if stale_process:
            typed_gres_stale.append(node_name)

    rollover_lines: list[str] = []
    if typed_gres_stale:
        rollover_lines.extend(
            _rollover_gpu_typed_gres_stale_worker_processes(
                phase=phase,
                replay=replay,
                release_gate=release_gate,
                stale_workers=typed_gres_stale,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )

    drained: list[str] = []
    observations: dict[str, str] = {}
    registration_deadline = time.monotonic() + 300
    while True:
        drained = []
        observations = {}
        pending_registrations: list[str] = []
        for worker in workers:
            node_name = str(worker.get("pod") or "").strip()
            nodeset = str(worker.get("nodeset") or "").strip()
            gpu_count = _positive_int(worker.get("gpu_count"), fallback=0)
            topology = _mapping(topology_by_nodeset.get(nodeset))
            observed = _kubectl_exec_login_once(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                args=("scontrol", "show", "node", node_name, "-o"),
                timeout_seconds=60,
            )
            stale, ready = _gpu_topology_replay_slurm_node_contract(
                output=observed.stdout,
                node_name=node_name,
                gpu_count=gpu_count,
                topology=topology,
            )
            if observed.returncode != 0 or not (stale or ready):
                pending_registrations.append(node_name)
                continue
            observations[node_name] = hashlib.sha256(observed.stdout.encode("utf-8")).hexdigest()
            if stale:
                drained.append(node_name)
        if not pending_registrations:
            break
        if not typed_gres_stale or time.monotonic() >= registration_deadline:
            raise SoperatorMigrationPhasePending(
                "GPU topology drain recovery is waiting for exact typed-GRES registration: "
                + ", ".join(pending_registrations)
            )
        time.sleep(2)

    recovery = phase.setdefault("gpu_topology_slurm_drain_recovery", {})
    if not isinstance(recovery, dict):
        raise SoperatorMigrationPhasePending(
            "GPU topology Slurm drain recovery checkpoint is malformed."
        )
    binding = {
        "schema": "nebius-cxcli-soperator-gpu-topology-slurm-drain-recovery/v1",
        "workers": worker_names,
        "topology_replay_fingerprint": _fingerprint(replay),
        "partition_pause_fingerprint": _fingerprint(pause_journal["partition_pause"]),
    }
    if recovery and any(recovery.get(key) != value for key, value in binding.items()):
        raise SoperatorMigrationPhasePending(
            "GPU topology Slurm drain recovery binding drifted from its checkpoint."
        )
    if drained:
        recovery.update(
            {
                **binding,
                "status": "resume-intent",
                "drained_workers": drained,
                "pre_resume_observations": observations,
                "intent_at": recovery.get("intent_at") or _utc_now(),
            }
        )
        checkpoint_writer()
        resumed = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("scontrol", "update", f"NodeName={','.join(drained)}", "State=RESUME"),
            timeout_seconds=60,
        )
        if resumed.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "GPU topology drain recovery could not resume its exact worker set: "
                + _command_detail(resumed)
            )

    verified: dict[str, str] = {}
    for worker in workers:
        node_name = str(worker.get("pod") or "").strip()
        nodeset = str(worker.get("nodeset") or "").strip()
        observed = _kubectl_exec_login_once(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            args=("scontrol", "show", "node", node_name, "-o"),
            timeout_seconds=60,
        )
        _stale, ready = _gpu_topology_replay_slurm_node_contract(
            output=observed.stdout,
            node_name=node_name,
            gpu_count=_positive_int(worker.get("gpu_count"), fallback=0),
            topology=_mapping(topology_by_nodeset.get(nodeset)),
        )
        if observed.returncode != 0 or not ready:
            raise SoperatorMigrationPhasePending(
                f"GPU topology drain recovery is waiting for {node_name} to register IDLE."
            )
        verified[node_name] = hashlib.sha256(observed.stdout.encode("utf-8")).hexdigest()
    recovery.update(
        {
            **binding,
            "status": "verified",
            "verified_observations": verified,
            "verified_at": _utc_now(),
        }
    )
    checkpoint_writer()
    return [
        *rollover_lines,
        "GPU topology drain recovery kept all target partitions paused and resumed "
        f"{len(drained)} stale worker drain(s) in one operation.",
    ]


def _ensure_jail_gpu_post_activation_gate(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    values: Mapping[str, Any],
    checkpoint_writer: Callable[[], None] | None,
    release_gate_key: str = "post_jail_gpu_workload_release_gate",
    namespace: str = _SOPERATOR_NAMESPACE,
    replacement_phase: Mapping[str, Any] | None = None,
    mutation_guard: Callable[[], None] | None = None,
) -> list[str]:
    state = phase.setdefault("gpu_post_activation", {})
    if not isinstance(state, dict):
        raise RuntimeError("populate-jail-refresh.gpu_post_activation must be a mapping.")
    if not _gpu_worker_nodeset_names(values):
        state.clear()
        state.update({"status": "not-required", "checked_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        return ["GPU Jail post-activation gate skipped: no active GPU worker NodeSet."]
    release_gate = _mapping(phase.get(release_gate_key))
    workers = sorted(
        _sequence_of_mappings(release_gate.get("workers")),
        key=lambda item: (str(item.get("nodeset") or ""), str(item.get("pod") or "")),
    )
    if str(release_gate.get("status") or "") != "passed" or not workers:
        raise SoperatorMigrationPhasePending(
            "GPU post-activation validation requires the exact passed GPU workload release gate."
        )
    topology_drain_lines = _reconcile_gpu_topology_replay_slurm_drains(
        phase=phase,
        replacement_phase=replacement_phase,
        release_gate=release_gate,
        values=values,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        namespace=namespace,
        mutation_guard=mutation_guard,
    )
    worker = workers[0]
    gpu_count = _positive_int(worker.get("gpu_count"), fallback=0)
    if gpu_count <= 0:
        raise SoperatorMigrationPhasePending(
            "GPU post-activation worker binding lacks a positive GPU count."
        )
    slurm_node = _jail_gpu_slurm_node_name(
        command_runner=command_runner,
        kube_context=kube_context,
        worker=worker,
        namespace=namespace,
    )
    worker_binding = {
        "pod": str(worker.get("pod") or ""),
        "pod_uid": str(worker.get("pod_uid") or ""),
        "kubernetes_node": str(worker.get("node") or ""),
        "slurm_node": slurm_node,
        "gpu_count": gpu_count,
    }
    existing_binding = _mapping(state.get("worker_binding"))
    if existing_binding and dict(existing_binding) != worker_binding:
        prior_uid = str(existing_binding.get("pod_uid") or "").strip()
        live_uid = str(worker_binding.get("pod_uid") or "").strip()
        stable_existing = dict(existing_binding)
        stable_live = dict(worker_binding)
        stable_existing.pop("pod_uid", None)
        stable_live.pop("pod_uid", None)
        repair = _mapping(_mapping(replacement_phase).get("gpu_health_sysfs_repair"))
        repair_replacement = _mapping(
            _mapping(repair.get("replacement_pods")).get(worker_binding["pod"])
        )
        target_statefulset_uid = str(repair_replacement.get("statefulset_uid") or "").strip()
        verified_replacement = None
        if stable_existing == stable_live and replacement_phase is not None:
            verified_replacement = _verified_gpu_health_sysfs_worker_replacement(
                replacement_phase,
                pod_name=worker_binding["pod"],
                prior_uid=prior_uid,
                live_uid=live_uid,
                nodeset_name=str(worker.get("nodeset") or "").strip(),
                target_statefulset_uid=target_statefulset_uid,
            )
        rollout_successor = None
        if verified_replacement is None and replacement_phase is not None:
            live_pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=worker_binding["pod"],
                label=(
                    "GPU post-activation in-place worker successor "
                    f"{_SOPERATOR_NAMESPACE}/{worker_binding['pod']}"
                ),
            )
            if live_pod is not None:
                rollout_successor = _verified_completed_in_place_worker_rollout_successor(
                    replacement_phase,
                    pod=live_pod,
                    pod_name=worker_binding["pod"],
                    live_uid=live_uid,
                    nodeset_name=str(worker.get("nodeset") or "").strip(),
                    target_statefulset_uid=str(worker.get("workload_uid") or "").strip(),
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
        if verified_replacement is None and rollout_successor is None:
            raise SoperatorMigrationPhasePending(
                "GPU post-activation worker Pod or Slurm-node identity drifted from the checkpoint."
            )
        history = state.setdefault("worker_binding_history", [])
        if not isinstance(history, list):
            raise SoperatorMigrationPhasePending(
                "GPU post-activation worker binding history is malformed."
            )
        transition = (
            {
                "binding": dict(existing_binding),
                "replaced_by_pod_uid": live_uid,
                "boundary": "gpu-health-sysfs-repair",
                "repair_verified_at": str(repair.get("verified_at") or ""),
            }
            if verified_replacement is not None
            else {
                "binding": dict(existing_binding),
                "replaced_by_pod_uid": live_uid,
                "boundary": "completed-in-place-worker-rollout",
                "rollout": dict(_mapping(rollout_successor)),
            }
        )
        if transition not in history:
            history.append(transition)
        state.clear()
        state["worker_binding_history"] = history
    state.update(
        {
            "status": "checking",
            "started_at": str(state.get("started_at") or _utc_now()),
            "worker_binding": worker_binding,
        }
    )
    state.pop("reason", None)
    if checkpoint_writer is not None:
        checkpoint_writer()
    try:
        state["dcgm_runtime"] = _jail_gpu_dcgm_runtime_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            worker=worker,
            namespace=namespace,
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        health = _jail_gpu_health_checker_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            worker=worker,
            slurm_node=slurm_node,
            gpu_count=gpu_count,
            namespace=namespace,
        )
        state["full_health_checker"] = health
        if checkpoint_writer is not None:
            checkpoint_writer()
        smoke = _jail_gpu_pinned_h100_smoke(
            command_runner=command_runner,
            kube_context=kube_context,
            state=state,
            slurm_node=slurm_node,
            expected_gpu_count=gpu_count,
            checkpoint_writer=checkpoint_writer,
            namespace=namespace,
        )
        if int(smoke.get("gpu_count") or 0) != gpu_count:
            raise SoperatorMigrationPhasePending(
                "pinned H100 smoke GPU count does not match the exact worker runtime probe."
            )
        state["pinned_h100_accounting"] = _jail_gpu_smoke_terminal_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            smoke=smoke,
            namespace=namespace,
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        post_epilog_health = _jail_gpu_health_checker_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            worker=worker,
            slurm_node=slurm_node,
            gpu_count=gpu_count,
            namespace=namespace,
        )
        post_epilog = {
            "status": "passed",
            "node_name": slurm_node,
            "completed": True,
            "exit_code": 0,
            "health_checker": post_epilog_health,
        }
        state["post_epilog"] = post_epilog
        slurm_node_evidence = _jail_gpu_slurm_node_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            slurm_node=slurm_node,
            namespace=namespace,
        )
        state["slurm_node"] = slurm_node_evidence
        validation = validate_jail_gpu_post_activation(
            expected_node=slurm_node,
            expected_gpu_count=gpu_count,
            full_health_checker=health,
            pinned_h100_smoke=smoke,
            post_epilog=post_epilog,
            slurm_node=slurm_node_evidence,
        )
        state["validation"] = validation.as_payload()
        _delete_jail_gpu_temporary_partition(
            command_runner=command_runner,
            kube_context=kube_context,
            state=state,
            checkpoint_writer=checkpoint_writer,
            namespace=namespace,
        )
    except (JailGpuPostActivationError, SoperatorMigrationPhasePending) as exc:
        if str(state.get("status") or "") != "Indeterminate":
            state["status"] = "failed"
        state["reason"] = str(exc)
        state["checked_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "GPU Jail post-activation validation failed while scheduling remains paused: "
            + str(exc)
        ) from exc
    state.update({"status": "passed", "checked_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        *topology_drain_lines,
        "GPU Jail post-activation validation passed on the pinned H100 worker: full "
        "health-checker, Slurm smoke allocation, post-epilog health, and exact "
        "schedulable IDLE state with no reason.",
    ]


def _resume_slurm_after_cutover(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    phase: dict[str, Any],
    values: Mapping[str, Any],
    checkpoint_writer: Callable[[], None] | None,
    slurm_pause_records: Sequence[SlurmPartitionPauseRecord] = (),
    cxcli_drained_node_names: Sequence[str] = (),
    action_journal: dict[str, Any] | None = None,
    authority_provider: Callable[[], Mapping[str, str]] | None = None,
) -> list[str]:
    identity_lines = _reconcile_slurm_worker_runtime_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
    )
    lines: list[str] = []
    if identity_lines:
        lines.append(
            "Slurm worker runtime identity reconciled after target Soperator cutover: "
            + "; ".join(identity_lines)
        )
    lines.extend(
        _ensure_gpu_worker_jail_release_gate(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            values=values,
            checkpoint_writer=checkpoint_writer,
        )
    )
    del action_journal, authority_provider
    if slurm_pause_records:
        lines.append(
            "Slurm partitions remain paused after the target workload release gate; "
            "their exact pre-upgrade records are retained until final gates pass, then "
            "restored before destructive bridge cleanup."
        )
    else:
        lines.append("No cxcli-owned Slurm partition pause was recorded at this cutover.")
    resumed_nodes = _resume_drained_slurm_nodes(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=cxcli_drained_node_names,
    )
    if resumed_nodes:
        lines.append(
            "Slurm nodes resumed after target Soperator cutover: " + ", ".join(resumed_nodes) + "."
        )
    return lines


