def _command_not_found(result: SoperatorMigrationCommandResult) -> bool:
    detail = " ".join(
        part.strip() for part in (result.stderr, result.stdout) if part and part.strip()
    )
    normalized = re.sub(r"\s+", " ", detail).strip().lower()
    if normalized in {"not found", "notfound", "resource not found"}:
        return True
    if "statuscode.not_found" in normalized:
        return True
    if "error from server (notfound)" in normalized:
        return True
    return bool(
        re.search(r"\brequest error\s+not[_ -]?found\b", normalized)
        or re.search(r"\brpc error:\s*code\s*=\s*not[_ -]?found\b", normalized)
    )


def _kubectl_exec_pod_not_found(
    result: SoperatorMigrationCommandResult,
    *,
    pod: str,
    namespace: str,
) -> bool:
    if result.returncode == 0:
        return False
    expected_args = ("-n", namespace, "exec", pod)
    if not any(
        result.args[index : index + len(expected_args)] == expected_args
        for index in range(len(result.args) - len(expected_args) + 1)
    ):
        return False
    stderr_lines: list[str] = []
    for raw_line in str(result.stderr or "").splitlines():
        normalized = re.sub(r"\s+", " ", raw_line).strip().lower()
        if normalized:
            stderr_lines.append(normalized)
    expected_errors = {
        f'error from server (notfound): pods "{pod}" not found'.lower(),
        f'error: unable to upgrade connection: pods "{pod}" not found'.lower(),
    }
    return len(stderr_lines) == 1 and stderr_lines[0] in expected_errors


