def _ensure_live_nodes_ready(snapshot: Mapping[str, Any]) -> None:
    groups = _mapping(snapshot.get("node_groups"))
    if not groups:
        raise RuntimeError("External Soperator upgrade validation found no Kubernetes node groups.")
    empty = [
        str(name)
        for name, group in groups.items()
        if isinstance(group, Mapping) and int(group.get("node_count", 0) or 0) <= 0
    ]
    if empty:
        raise RuntimeError(
            "External Soperator upgrade validation found empty node groups: " + ", ".join(empty)
        )


def _continuous_worker_pause_required(checkpoint: Mapping[str, Any]) -> bool:
    planned = {
        str(phase or "").strip()
        for phase in checkpoint.get("planned_phases", []) or []
        if str(phase or "").strip()
    }
    completed = {
        str(phase or "").strip()
        for phase in checkpoint.get("completed_phases", []) or []
        if str(phase or "").strip()
    }
    return (
        _EXTERNAL_NODE_TEMPLATE_PHASE_ID in planned
        and "rolling-compute-migration" in planned
        and "rolling-compute-migration" not in completed
    )


_IN_PLACE_TARGET_PARTITION_REBASE_FIELDS = frozenset(
    {
        "Default",
        "PowerDownOnIdle",
        "ResumeTimeout",
        "SuspendTime",
        "SuspendTimeout",
        "TRES",
        "TotalCPUs",
        "TotalNodes",
    }
)


def _rebase_in_place_target_partition_pause_record(
    record: SlurmPartitionPauseRecord,
    live: SlurmPartitionState,
) -> SlurmPartitionPauseRecord | None:
    """Carry exact DOWN ownership across the allowlisted target-chart transition."""

    if live.name != record.partition or slurm_partition_state_token(live.state) != "DOWN":
        return None

    def _fields(value: str) -> dict[str, str]:
        return {
            key: item
            for token in canonical_slurm_partition_record(value).split()
            for key, item in (token.split("=", 1),)
        }

    before = _fields(record.applied_record)
    after = _fields(live.record)
    changed = {key for key in set(before) | set(after) if before.get(key) != after.get(key)}
    changed.discard("State")
    if not changed or not changed <= _IN_PLACE_TARGET_PARTITION_REBASE_FIELDS:
        return None
    previous = dict(after)
    previous["State"] = record.previous_state
    previous_record = canonical_slurm_partition_record(
        " ".join(f"{key}={value}" for key, value in previous.items())
    )
    return SlurmPartitionPauseRecord(
        partition=record.partition,
        previous_state=record.previous_state,
        previous_record=previous_record,
        previous_record_fingerprint=slurm_partition_record_fingerprint(previous_record),
        applied_state="DOWN",
        applied_record=live.record,
        applied_record_fingerprint=live.record_fingerprint,
    )


def _ensure_continuous_worker_slurm_pause(
    *,
    checkpoint: dict[str, Any],
    source_report: Mapping[str, Any],
    worker_node_groups: Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    job_policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None,
    interactive_prompt_pause: Callable[[], Any] | None,
    allow_resolved_interactive_job_policy: bool,
    slurm_scheduling_pause: bool,
) -> list[str]:
    if not slurm_scheduling_pause or not _continuous_worker_pause_required(checkpoint):
        return []
    external_phase = _phase_state(checkpoint, _EXTERNAL_NODE_TEMPLATE_PHASE_ID)
    rolling_phase = _phase_state(checkpoint, "rolling-compute-migration")
    checkpointed_records = _merge_slurm_partition_pause_records(
        _rolling_compute_checkpoint_pause_records(external_phase),
        _rolling_compute_checkpoint_pause_records(rolling_phase),
    )
    bridge_gap_records = _controller_bridge_authority_gap_partition_pause_records(
        _mapping(checkpoint.get("controller_bridge"))
    )
    if bridge_gap_records:
        records = _merge_slurm_partition_pause_records(
            checkpointed_records,
            bridge_gap_records,
        )
        external_phase["slurm_paused_partitions"] = [record.as_payload() for record in records]
        external_phase["slurm_partition_restore_manual_command"] = (
            _external_upgrade_slurm_partition_recovery_inspection_command(records) or None
        )
        external_phase["slurm_partition_restore_deferred_reason"] = (
            "node images and the shared jail may be GPU-incompatible until target Soperator "
            "worker reconciliation and the GPU workload release gate pass"
        )
        external_phase["slurm_pause_release_boundary"] = "rolling-compute-migration"
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            "Continuous Slurm scheduling pause reused the controller-bridge exact "
            "partition checkpoint during the target-version cold restart; live worker "
            "and job revalidation resumes after target controller authority."
        ]
    if checkpointed_records:
        live_partitions = {
            item.name: item
            for item in _external_upgrade_partition_state_snapshot(
                command_runner=command_runner,
                kube_context=kube_context,
            )
        }
        checkpointed_names = {record.partition for record in checkpointed_records}
        if set(live_partitions) != checkpointed_names:
            raise SoperatorMigrationPhasePending(
                "Continuous Slurm scheduling pause found a changed partition set after "
                "the all-partitions job-free boundary; review the new or removed partition "
                "before resuming the worker rollout."
            )
        reconciled_records: list[SlurmPartitionPauseRecord] = []
        drifted: list[str] = []
        rebased: list[str] = []
        for record in checkpointed_records:
            live = live_partitions[record.partition]
            if (
                record.applied_record
                and record.applied_record_fingerprint
                and _slurm_partition_observation_matches(
                    live,
                    record=record.applied_record,
                    fingerprint=record.applied_record_fingerprint,
                )
            ):
                reconciled_records.append(record)
                continue
            target_record = _rebase_in_place_target_partition_pause_record(record, live)
            if target_record is None:
                drifted.append(record.partition)
                continue
            reconciled_records.append(target_record)
            rebased.append(record.partition)
        if drifted:
            raise RuntimeError(
                "recovery-required: continuous Slurm scheduling pause no longer matches "
                "cxcli's exact all-partitions State=DOWN journal for: "
                + ", ".join(sorted(drifted))
                + ". Inspect the full live partition records before continuing."
            )
        if rebased:
            external_phase["slurm_paused_partitions"] = [
                record.as_payload() for record in reconciled_records
            ]
            rolling_phase["slurm_paused_partitions"] = [
                record.as_payload() for record in reconciled_records
            ]
        reconciled_by_name = {record.partition: record for record in reconciled_records}
        bridge = checkpoint.get("controller_bridge")
        bridge_rebound = False
        if isinstance(bridge, dict):
            bridge_payloads = _sequence_of_mappings(bridge.get("partition_pause"))
            rebound_payloads: list[dict[str, str]] = []
            for payload in bridge_payloads:
                partition = str(payload.get("partition") or "").strip()
                replacement = reconciled_by_name.get(partition)
                desired = replacement.as_payload() if replacement is not None else dict(payload)
                bridge_rebound = bridge_rebound or dict(payload) != desired
                rebound_payloads.append(desired)
            if bridge_rebound:
                bridge["partition_pause"] = rebound_payloads
                bridge["partition_pause_revalidated_at"] = _utc_now()
        if (rebased or bridge_rebound) and checkpoint_writer is not None:
            checkpoint_writer()
        return [
            "Continuous Slurm scheduling pause reused the exact all-partitions State=DOWN "
            "journal and its prior job-free gate; no node-scoped job discovery was repeated "
            "across the checkpointed worker replacement boundary."
            + (
                " Target-chart partition fields were rebound to the exact DOWN records for: "
                + ", ".join(sorted(rebased))
                + "."
                if rebased
                else ""
            )
        ]
    live_worker_nodes = _external_upgrade_worker_nodeset_slurm_nodes(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    _service_groups, source_worker_groups = _split_external_node_template_upgrade_groups(
        source_report=source_report,
        worker_node_groups=worker_node_groups,
    )
    live_nodes_by_group = _worker_nodes_by_source_group(
        nodes=_read_kubernetes_nodes_for_worker_rollout(
            command_runner=command_runner,
            kube_context=kube_context,
        ),
        worker_groups=source_worker_groups,
    )
    live_worker_kubernetes_nodes = tuple(
        _node_name(node)
        for group_name, _raw_group in source_worker_groups
        for node in live_nodes_by_group.get(group_name, ())
        if _node_name(node)
    )
    source_worker_nodes = _nodes_for_worker_groups(
        source_report=source_report,
        worker_node_groups=worker_node_groups,
    )
    quiet_nodes = live_worker_nodes or live_worker_kubernetes_nodes or source_worker_nodes
    if not quiet_nodes:
        raise SoperatorMigrationPhasePending(
            "continuous worker scheduling pause could not resolve any live Slurm "
            "worker nodes before the GPU compatibility boundary."
        )

    def _record_intent(record: SlurmPartitionPauseRecord) -> None:
        _checkpoint_slurm_partition_pause_intent(
            phase=external_phase,
            record=record,
            checkpoint_writer=checkpoint_writer,
        )

    quiet_lines, live_records = _ensure_slurm_quiet(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=quiet_nodes,
        job_policy=job_policy,
        cancel_job_ids=cancel_job_ids,
        requeue_job_ids=requeue_job_ids,
        job_wait_timeout_seconds=job_wait_timeout_seconds,
        job_refresh_interval_seconds=job_refresh_interval_seconds,
        slurm_decision_recorder=slurm_decision_recorder,
        slurm_pause_intent_recorder=_record_intent,
        interactive_prompt_pause=interactive_prompt_pause,
        allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
        slurm_scheduling_pause=True,
        held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
        held_job_checkpoint_writer=checkpoint_writer,
        slurm_action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
        slurm_action_checkpoint_writer=checkpoint_writer,
        slurm_controller_authority_provider=lambda: _external_upgrade_slurm_action_authority(
            checkpoint
        ),
    )
    records = _merge_slurm_partition_pause_records(checkpointed_records, live_records)
    external_phase["slurm_paused_partitions"] = [record.as_payload() for record in records]
    external_phase["slurm_partition_restore_manual_command"] = (
        _external_upgrade_slurm_partition_recovery_inspection_command(records) or None
    )
    external_phase["slurm_partition_restore_deferred_reason"] = (
        "node images and the shared jail may be GPU-incompatible until target Soperator "
        "worker reconciliation and the GPU workload release gate pass"
    )
    external_phase["slurm_pause_release_boundary"] = "rolling-compute-migration"
    if checkpoint_writer is not None:
        checkpoint_writer()
    if checkpointed_records and not live_records:
        quiet_lines.append(
            "Continuous Slurm scheduling pause reused the checkpointed exact partition "
            "ownership records."
        )
    quiet_lines.append(
        "Slurm scheduling remains paused across GPU stack and target Soperator "
        "reconciliation until the direct GPU workload release gate passes."
    )
    return quiet_lines


def _inherit_continuous_worker_slurm_pause_records(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> tuple[SlurmPartitionPauseRecord, ...]:
    """Bind the current rolling phase to the exact continuous-pause journal."""

    external_phase = _phase_state(checkpoint, _EXTERNAL_NODE_TEMPLATE_PHASE_ID)
    bridge_records = tuple(
        _bridge_partition_record(item)
        for item in _sequence_of_mappings(
            _mapping(checkpoint.get("controller_bridge")).get("partition_pause")
        )
    )
    external_records = _rolling_compute_checkpoint_pause_records(external_phase)
    inherited_records = _merge_slurm_partition_pause_records(
        bridge_records,
        external_records,
    )
    records = _merge_slurm_partition_pause_records(
        inherited_records,
        _rolling_compute_checkpoint_pause_records(phase),
    )
    if not inherited_records:
        return records
    phase["slurm_pause_inherited_from"] = [
        source
        for source, source_records in (
            (_CONTROLLER_HA_BRIDGE_PHASE_ID, bridge_records),
            (_EXTERNAL_NODE_TEMPLATE_PHASE_ID, external_records),
        )
        if source_records
    ]
    phase["slurm_paused_partitions"] = [record.as_payload() for record in records]
    phase["slurm_partition_restore_manual_command"] = (
        _external_upgrade_slurm_partition_recovery_inspection_command(records) or None
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return records


def _execute_external_node_template_upgrade_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    """Upgrade the MK8s control plane before the campaign-owned compute phase."""

    checkpoint_writer = _execution_checkpoint_writer(checkpoint_writer)
    phase = _phase_state(checkpoint, _EXTERNAL_NODE_TEMPLATE_PHASE_ID)
    onboarding = _target_onboarding(payload, target_ref)
    compute_mode = str(
        _mapping(_mapping(onboarding.get("upgrade_path")).get("compute_migration")).get("mode", "")
        or ""
    ).strip()
    fallback_target = _external_node_template_target(onboarding)
    control_plane_target = _external_control_plane_target(
        onboarding=onboarding,
        fallback=fallback_target,
    )
    phase["target"] = {"k8s_version": control_plane_target}
    phase["node_group_mode"] = compute_mode
    phase["source_node_groups"] = (
        "in-place-update" if compute_mode == COMPUTE_MIGRATION_MODE_IN_PLACE else "retained"
    )
    phase["target_node_group_owner"] = "rolling-compute-migration"
    cluster_id = _external_migration_cluster_id(
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        nebius_api=nebius_api,
    )
    phase["cluster_id"] = cluster_id
    mutation_performed = False
    lines: list[str] = _revalidate_protected_login_sessions(
        checkpoint=checkpoint,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )

    control_plane = phase.setdefault("control_plane", {})
    if not isinstance(control_plane, dict):
        raise RuntimeError(
            "External Soperator upgrade checkpoint external-node-template-upgrade.control_plane "
            "must be a mapping."
        )
    try:
        cluster = _cluster_payload_by_id(nebius_api=nebius_api, cluster_id=cluster_id)
    except Exception as exc:
        hop_state = _mapping(control_plane.get("hops"))
        for raw_state in hop_state.values():
            if not isinstance(raw_state, dict):
                continue
            if (
                str(raw_state.get("status", "") or "") == "updating"
                and raw_state.get("provider_update_attempted") is True
            ):
                reconciliation = _ExternalNodeTemplateReconciliation(
                    _EXTERNAL_RECONCILIATION_UNKNOWN,
                    "Nebius API did not return the live MK8s control-plane state for "
                    f"{cluster_id}: {exc}. cxcli cannot safely mark the checkpointed "
                    "control-plane update complete.",
                )
                _record_external_node_template_reconciliation(raw_state, reconciliation)
                raw_state["pending_reason"] = reconciliation.reason
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise SoperatorMigrationPhasePending(reconciliation.reason) from exc
        raise
    current_version = _minor_version_text_or_empty(_cluster_control_plane_version(cluster))
    if not current_version:
        hop_state = _mapping(control_plane.get("hops"))
        for raw_state in hop_state.values():
            if not isinstance(raw_state, dict):
                continue
            if (
                str(raw_state.get("status", "") or "") == "updating"
                and raw_state.get("provider_update_attempted") is True
            ):
                reconciliation = _ExternalNodeTemplateReconciliation(
                    _EXTERNAL_RECONCILIATION_UNKNOWN,
                    "Nebius API did not report the live MK8s control-plane version; "
                    "cxcli cannot safely mark the checkpointed control-plane update "
                    "complete.",
                )
                _record_external_node_template_reconciliation(raw_state, reconciliation)
                raw_state["pending_reason"] = reconciliation.reason
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise SoperatorMigrationPhasePending(reconciliation.reason)
        raise SoperatorMigrationPhasePending(
            "external-node-template-upgrade could not detect the live MK8s control-plane "
            "version. Rerun onboarding after confirming Nebius API access works."
        )
    control_plane["current_version"] = current_version
    control_plane["target_version"] = control_plane_target
    _ensure_external_node_template_k8s_not_downgrade(current_version, control_plane_target)
    hop_state = control_plane.setdefault("hops", {})
    if not isinstance(hop_state, dict):
        raise RuntimeError(
            "External Soperator upgrade checkpoint external-node-template-upgrade.control_plane.hops "
            "must be a mapping."
        )
    active_hops = [
        (str(target_version), raw_state)
        for target_version, raw_state in hop_state.items()
        if isinstance(raw_state, dict) and str(raw_state.get("status", "") or "") == "updating"
    ]
    if len(active_hops) > 1:
        raise RuntimeError(
            "recovery-required: external MK8s control-plane journal contains multiple "
            "active provider operations; cxcli will not infer which operation owns the "
            "cluster."
        )
    if active_hops:
        raw_target_version, state = active_hops[0]
        hop_to_version = str(state.get("target_version", "") or raw_target_version).strip()
        hop_from_version = str(state.get("from_version", "") or "").strip()
        if not hop_from_version or not hop_to_version or hop_to_version != control_plane_target:
            raise RuntimeError(
                "recovery-required: active MK8s control-plane operation does not match "
                f"the config-owned segment target {control_plane_target}."
            )
        reconciliation = _reconcile_external_control_plane_hop_resume(
            checkpoint=checkpoint,
            state=state,
            cluster=cluster,
            cluster_id=cluster_id,
            current_version=current_version,
            hop_from_version=hop_from_version,
            hop_to_version=hop_to_version,
        )
        _record_external_node_template_reconciliation(state, reconciliation)
        if reconciliation.status == _EXTERNAL_RECONCILIATION_COMPLETED:
            phase["mutation_performed"] = True
            _record_reconciled_provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=state,
                nebius_api=nebius_api,
                provider_payload=cluster,
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
                checkpoint_writer=checkpoint_writer,
                verified_postcondition={"control_plane_version": hop_to_version},
            )
            state.update(
                {
                    "from_version": hop_from_version,
                    "target_version": hop_to_version,
                    "status": "completed",
                    "completed_at": _utc_now(),
                    "observed_version": _cluster_control_plane_status_version(cluster),
                }
            )
            current_version = hop_to_version
            control_plane["current_version"] = current_version
            if checkpoint_writer is not None:
                checkpoint_writer()
            lines.append(
                "External MK8s control-plane hop completed after resume reconciliation: "
                f"{hop_to_version}."
            )
        elif reconciliation.status in {
            _EXTERNAL_RECONCILIATION_WAITING,
            _EXTERNAL_RECONCILIATION_UNKNOWN,
        }:
            phase["mutation_performed"] = True
            state["pending_reason"] = reconciliation.reason
            if checkpoint_writer is not None:
                checkpoint_writer()
            _require_journaled_provider_operation_before_unmet_postcondition(
                resource_state=state,
                nebius_api=nebius_api,
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
            )
        else:
            state["status"] = "failed"
            state["error"] = reconciliation.reason
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise RuntimeError(reconciliation.reason)

    try:
        hops = require_single_minor_hop(current_version, control_plane_target)
    except ValueError as exc:
        raise RuntimeError(str(exc).replace("--to-version", "--to-k8s-version")) from exc
    if not hops:
        control_plane["status"] = "already-current"
        lines.append(f"External MK8s control plane already at Kubernetes {control_plane_target}.")
    for hop in hops:
        state = hop_state.setdefault(hop.to_version, {})
        if not isinstance(state, dict):
            raise RuntimeError(
                "External Soperator upgrade checkpoint external-node-template-upgrade "
                f"control-plane hop {hop.to_version} must be a mapping."
            )
        reconciliation = _reconcile_external_control_plane_hop_resume(
            checkpoint=checkpoint,
            state=state,
            cluster=cluster,
            cluster_id=cluster_id,
            current_version=current_version,
            hop_from_version=hop.from_version,
            hop_to_version=hop.to_version,
        )
        if reconciliation.status != _EXTERNAL_RECONCILIATION_RETRY:
            _record_external_node_template_reconciliation(state, reconciliation)
        if reconciliation.status == _EXTERNAL_RECONCILIATION_COMPLETED:
            phase["mutation_performed"] = True
            _record_reconciled_provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=state,
                nebius_api=nebius_api,
                provider_payload=cluster,
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
                checkpoint_writer=checkpoint_writer,
            )
            state.update(
                {
                    "from_version": hop.from_version,
                    "target_version": hop.to_version,
                    "status": "completed",
                    "completed_at": _utc_now(),
                    "observed_version": current_version,
                }
            )
            control_plane["current_version"] = current_version
            if checkpoint_writer is not None:
                checkpoint_writer()
            lines.append(
                "External MK8s control-plane hop completed after resume "
                f"reconciliation: {hop.to_version}."
            )
            continue
        if reconciliation.status in {
            _EXTERNAL_RECONCILIATION_WAITING,
            _EXTERNAL_RECONCILIATION_UNKNOWN,
        }:
            phase["mutation_performed"] = True
            state.update(
                {
                    "from_version": hop.from_version,
                    "target_version": hop.to_version,
                    "status": "updating",
                    "pending_reason": reconciliation.reason,
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            _require_journaled_provider_operation_before_unmet_postcondition(
                resource_state=state,
                nebius_api=nebius_api,
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
            )
        if reconciliation.status == _EXTERNAL_RECONCILIATION_DRIFT_CONFLICT:
            state["status"] = "failed"
            state["error"] = reconciliation.reason
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise RuntimeError(reconciliation.reason)
        if (
            state.get("status") == "completed"
            and state.get("target_version") == hop.to_version
            and _minor_version_at_least(current_version, hop.to_version)
        ):
            lines.append(f"External MK8s control-plane hop already completed: {hop.to_version}.")
            current_version = hop.to_version
            continue
        state.update(
            {
                "from_version": hop.from_version,
                "target_version": hop.to_version,
                "status": "updating",
                "started_at": state.get("started_at") or _utc_now(),
            }
        )
        cluster_metadata = _mapping(cluster.get("metadata"))
        operation_entry = _provider_operation_entry(
            checkpoint=checkpoint,
            operation_kind="mk8s-control-plane-update",
            resource_id=cluster_id,
            resource_uid=str(
                cluster_metadata.get("uid", "") or cluster_metadata.get("id", "") or cluster_id
            ),
            resource_version=_node_group_resource_version(cluster),
            intended_postcondition={"control_plane_version": hop.to_version},
        )
        state["operation"] = operation_entry
        _record_provider_operation(checkpoint, operation_entry)
        if checkpoint_writer is not None:
            checkpoint_writer()
        try:
            state["provider_update_attempted"] = True
            operation_entry["attempt_state"] = "provider-requested"
            state["operation"] = operation_entry
            _record_provider_operation(checkpoint, operation_entry)
            if checkpoint_writer is not None:
                checkpoint_writer()
            cluster = _update_cluster_control_plane(
                nebius_api=nebius_api,
                cluster_id=cluster_id,
                control_plane_version=hop.to_version,
                operation_accepted=_provider_operation_acceptance_callback(
                    checkpoint=checkpoint,
                    resource_state=state,
                    operation_entry=operation_entry,
                    checkpoint_writer=checkpoint_writer,
                ),
            )
        except subprocess.TimeoutExpired as exc:
            state["status"] = "updating"
            state["error"] = str(exc)
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=state,
                operation_entry=operation_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            operation_id = str(operation_entry.get("provider_operation_id", "") or "").strip()
            if not _provider_operation_id_is_real(operation_id):
                raise
            _require_reconciled_provider_operation_terminal(
                nebius_api=nebius_api,
                provider_operation_id=operation_id,
                provider_operation_kind=str(operation_entry.get("operation_kind", "") or ""),
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
            )
            cluster = _wait_for_provider_resource_postcondition(
                fetch=lambda: nebius_api.get_cluster(cluster_id),
                satisfied=lambda item, target_version=hop.to_version: (
                    _cluster_control_plane_terminal_readiness(
                        item,
                        target_version=target_version,
                    ).status
                    == _EXTERNAL_RECONCILIATION_COMPLETED
                ),
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
            )
            cluster = {**cluster, "_cxcli_provider_operation_id": operation_id}
        except (Exception, KeyboardInterrupt) as exc:
            state["status"] = "updating"
            state["error"] = str(exc)
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=state,
                operation_entry=operation_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            raise
        mutation_performed = True
        returned_operation_id = _required_provider_operation_id(
            cluster,
            operation_kind="MK8s control-plane update",
            resource_id=cluster_id,
        )
        journaled_operation_id = str(operation_entry.get("provider_operation_id", "") or "").strip()
        if returned_operation_id != journaled_operation_id:
            raise RuntimeError(
                "recovery-required: completed MK8s control-plane provider response does "
                "not match the exact operation ID recorded at acceptance "
                f"(journal={journaled_operation_id or 'missing'}, "
                f"response={returned_operation_id})."
            )
        reconciliation = _cluster_control_plane_terminal_readiness(
            cluster,
            target_version=hop.to_version,
        )
        _record_external_node_template_reconciliation(state, reconciliation)
        if reconciliation.status != _EXTERNAL_RECONCILIATION_COMPLETED:
            state["status"] = "updating"
            state["pending_reason"] = reconciliation.reason
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=state,
                operation_entry=operation_entry,
                reason=reconciliation.reason,
                checkpoint_writer=checkpoint_writer,
            )
            cluster = _wait_for_provider_resource_postcondition(
                fetch=lambda: nebius_api.get_cluster(cluster_id),
                satisfied=lambda item, target_version=hop.to_version: (
                    _cluster_control_plane_terminal_readiness(
                        item,
                        target_version=target_version,
                    ).status
                    == _EXTERNAL_RECONCILIATION_COMPLETED
                ),
                operation_kind="MK8s control-plane update",
                resource_id=cluster_id,
            )
            cluster = {**cluster, "_cxcli_provider_operation_id": returned_operation_id}
            reconciliation = _cluster_control_plane_terminal_readiness(
                cluster,
                target_version=hop.to_version,
            )
            _record_external_node_template_reconciliation(state, reconciliation)
        _provider_operation_terminal(
            checkpoint=checkpoint,
            resource_state=state,
            operation_entry=operation_entry,
            provider_payload=cluster,
            operation_kind="MK8s control-plane update",
            resource_id=cluster_id,
            verified_postcondition={"control_plane_version": hop.to_version},
            checkpoint_writer=checkpoint_writer,
        )
        state["status"] = "completed"
        state["completed_at"] = _utc_now()
        state["observed_version"] = _cluster_control_plane_status_version(cluster)
        operation_entry = dict(copy.deepcopy(to_plain_data(dict(_mapping(state.get("operation"))))))
        state["operation"] = operation_entry
        control_plane["current_version"] = state["observed_version"]
        if checkpoint_writer is not None:
            checkpoint_writer()
        lines.append(
            f"External MK8s control-plane upgraded: {hop.from_version} -> {hop.to_version}."
        )

    control_plane["status"] = "completed"
    phase["status"] = "completed"
    phase["completed_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    lines.append(
        "External MK8s control-plane upgrade completed; rolling-compute-migration owns "
        + (
            "the accepted in-place node-group updates."
            if compute_mode == COMPUTE_MIGRATION_MODE_IN_PLACE
            else "the accepted blue-green replacements."
        )
    )
    return mutation_performed, lines


def _execute_target_gpu_stack_remediation_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None = None,
    continuous_pause_guard: Callable[[], Sequence[str]] | None = None,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, _TARGET_GPU_STACK_PHASE_ID)
    lines = list(continuous_pause_guard() if continuous_pause_guard is not None else ())
    rows = _target_gpu_stack_app_rows(payload, target_ref)
    if not rows:
        phase["missing_app_rows"] = list(_TARGET_GPU_STACK_APP_ORDER)
        raise SoperatorMigrationPhasePending(
            "target GPU stack reconciliation requires target-scoped GPU Operator or "
            "Network Operator app rows. Rerun `nebius-cxcli ext-soperator onboard` so "
            "the accepted config carries the reconciliation app rows before executing the upgrade."
        )
    applied: list[Mapping[str, str]] = []
    for row in rows:
        result = _helm_upgrade_target_app_chart(
            command_runner=command_runner,
            kube_context=kube_context,
            row=row,
        )
        applied.append(result)
        post_render_patches = _apply_target_gpu_stack_post_render_patches(
            command_runner=command_runner,
            kube_context=kube_context,
            payload=payload,
            target_ref=target_ref,
            app_id=result["id"],
        )
        if post_render_patches:
            result["post_render_patches"] = json.dumps(
                post_render_patches,
                sort_keys=True,
            )
        phase["charts"] = [dict(item) for item in applied]
        if checkpoint_writer is not None:
            checkpoint_writer()
        version = f"@{result['version']}" if result.get("version") else ""
        lines.append(
            "Applied target GPU stack chart: "
            f"{result['id']}={result['release_name']} "
            f"({result['namespace']}, {result['chart_ref']}{version})"
        )
        if result.get("timeout_recovered") == "true":
            timeout_suffix = (
                f" after {result['timeout_seconds']}s" if result.get("timeout_seconds") else ""
            )
            lines.append(
                "Accepted target GPU stack chart after Helm client timeout"
                f"{timeout_suffix}: {result['id']} live release is ready."
            )
        for patch in post_render_patches:
            patch_name = patch.get("name") or patch.get("kind") or "resource"
            lines.append(
                f"Applied target GPU stack post-render patch: {result['id']} -> {patch_name}"
            )
    phase["charts"] = [dict(item) for item in applied]
    phase["completed_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    return True, lines


def _controller_bridge_source_binding(
    source_report: Mapping[str, Any],
) -> tuple[BridgeSourceBinding, Mapping[str, Any]]:
    source = _mapping(_mapping(source_report.get("snapshot")).get("controller_bridge_source"))
    blockers = tuple(str(item or "").strip() for item in source.get("blockers", []) if str(item))
    if source.get("status") != "ready" or blockers:
        detail = "; ".join(blockers) or "bridge source inventory is absent"
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires a fresh onboarding discovery with exact controller "
            f"workload, Pod, PVC/PV, image, configuration, MUNGE, and JWT evidence: {detail}."
        )
    slurmcluster = _mapping(source.get("slurmcluster"))
    workload = _mapping(source.get("controller_workload"))
    pod = _mapping(source.get("controller_pod"))
    pvc = _mapping(source.get("controller_pvc"))
    pv = _mapping(source.get("controller_pv"))
    jail_pvc = _mapping(source.get("jail_pvc"))
    jail_pv = _mapping(source.get("jail_pv"))
    jail_storage = _mapping(source.get("jail_storage"))
    configuration = _mapping(source.get("configuration"))
    munge = _mapping(source.get("munge"))
    jwt = _mapping(source.get("jwt"))
    try:
        binding = BridgeSourceBinding(
            namespace=str(slurmcluster.get("namespace", "") or ""),
            slurmcluster_name=str(slurmcluster.get("name", "") or ""),
            slurmcluster_uid=str(slurmcluster.get("uid", "") or ""),
            controller_workload_name=str(workload.get("name", "") or ""),
            controller_workload_uid=str(workload.get("uid", "") or ""),
            controller_pod_name=str(pod.get("name", "") or ""),
            controller_pod_uid=str(pod.get("uid", "") or ""),
            controller_pvc_name=str(pvc.get("name", "") or ""),
            controller_pvc_uid=str(pvc.get("uid", "") or ""),
            controller_pv_name=str(pv.get("name", "") or ""),
            controller_pv_uid=str(pv.get("uid", "") or ""),
            jail_pvc_name=str(jail_pvc.get("name", "") or ""),
            jail_pvc_uid=str(jail_pvc.get("uid", "") or ""),
            jail_pv_name=str(jail_pv.get("name", "") or ""),
            jail_pv_uid=str(jail_pv.get("uid", "") or ""),
            jail_filesystem_id=str(jail_storage.get("filesystem_id", "") or ""),
            slurm_image_digest=str(pod.get("resolved_image_digest", "") or ""),
            slurm_version=str(pod.get("slurm_version", "") or ""),
            configuration_fingerprint=str(configuration.get("fingerprint", "") or ""),
            munge_fingerprint=str(munge.get("fingerprint", "") or ""),
            jwt_fingerprint=str(jwt.get("fingerprint", "") or ""),
        )
        binding.as_payload()
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            f"controller-ha-bridge source binding is incomplete: {exc}"
        ) from exc
    return binding, source


def _controller_bridge_checkpoint_source_binding(
    checkpoint: Mapping[str, Any],
) -> tuple[BridgeSourceBinding, Mapping[str, Any]] | None:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, Mapping):
        return None
    try:
        validate_bridge_journal(journal)
    except ValueError:
        return None
    authority = _mapping(journal.get("authority"))
    intent = _mapping(journal.get("source_fence_intent"))
    source_fencing = _mapping(_mapping(journal.get("fencing")).get("source"))
    stage = str(journal.get("stage", "") or "")
    dispatch_gap = (
        stage == BridgeStage.SOURCE_PRECOPIED.value
        and authority.get("owner") == "source-singleton"
        and not str(authority.get("first_bridge_write_at", "") or "")
        and authority.get("source_restart_prohibited") is not True
        and intent.get("state") == "dispatching"
        and source_fencing.get("proven") is not True
    )
    fenced_source = (
        stage
        in {
            BridgeStage.SOURCE_FENCED.value,
            BridgeStage.STATE_PROMOTED.value,
            BridgeStage.SOURCE_HA_ACTIVE.value,
            BridgeStage.TARGET_HA_ACTIVE.value,
            BridgeStage.BRIDGE_FENCED.value,
            BridgeStage.TARGET_SINGLETON_ACTIVE.value,
            BridgeStage.HANDOFF_VALIDATED.value,
            BridgeStage.PARTITIONS_RESTORED.value,
        }
        and intent.get("state") == "accepted"
        and source_fencing.get("proven") is True
        and source_fencing.get("process_absent") is True
        and source_fencing.get("writable_mount_absent") is True
    )
    if not dispatch_gap and not fenced_source:
        return None
    payload = dict(_mapping(journal.get("source_binding")))
    field_names = tuple(BridgeSourceBinding.__dataclass_fields__)
    if set(payload) != set(field_names):
        return None
    try:
        binding = BridgeSourceBinding(**{field: str(payload[field]) for field in field_names})
        binding.as_payload()
    except (TypeError, ValueError):
        return None
    if (
        intent.get("source_workload_uid") != binding.controller_workload_uid
        or intent.get("source_pod_uid") != binding.controller_pod_uid
        or source_fencing.get("workload_uid") != binding.controller_workload_uid
        or source_fencing.get("pod_uid") != binding.controller_pod_uid
    ):
        return None
    runtime_target = _mapping(source_fencing.get("runtime_target"))
    if (
        not str(runtime_target.get("node_name", "") or "")
        or not str(runtime_target.get("node_uid", "") or "")
        or not runtime_target.get("state_markers")
    ):
        return None
    source = {
        "slurmcluster": {
            "namespace": binding.namespace,
            "name": binding.slurmcluster_name,
            "uid": binding.slurmcluster_uid,
        },
        "controller_workload": {
            "name": binding.controller_workload_name,
            "uid": binding.controller_workload_uid,
        },
        "controller_pod": {
            "name": binding.controller_pod_name,
            "uid": binding.controller_pod_uid,
            "node_name": str(runtime_target["node_name"]),
        },
        "controller_pvc": {
            "name": binding.controller_pvc_name,
            "uid": binding.controller_pvc_uid,
        },
        "controller_pv": {
            "name": binding.controller_pv_name,
            "uid": binding.controller_pv_uid,
        },
        "jail_pvc": {"name": binding.jail_pvc_name, "uid": binding.jail_pvc_uid},
        "jail_pv": {"name": binding.jail_pv_name, "uid": binding.jail_pv_uid},
    }
    return binding, source


def _controller_bridge_plan_source_binding(
    *,
    checkpoint: Mapping[str, Any],
    source_report: Mapping[str, Any],
) -> tuple[BridgeSourceBinding, Mapping[str, Any]]:
    checkpoint_source = _controller_bridge_checkpoint_source_binding(checkpoint)
    journal_stage = str(_mapping(checkpoint.get("controller_bridge")).get("stage", "") or "")
    source_fenced_stages = {
        BridgeStage.SOURCE_FENCED.value,
        BridgeStage.STATE_PROMOTED.value,
        BridgeStage.SOURCE_HA_ACTIVE.value,
        BridgeStage.TARGET_HA_ACTIVE.value,
        BridgeStage.BRIDGE_FENCED.value,
        BridgeStage.TARGET_SINGLETON_ACTIVE.value,
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
    }
    # After the accepted source singleton is fenced, discovery is expected to see
    # the target SlurmCluster/controller as the only live ready source candidate.
    # Revalidating the completed bridge must stay bound to its immutable journaled
    # source rather than reinterpret that target as a changed original source.
    if checkpoint_source is not None and journal_stage in source_fenced_stages:
        return checkpoint_source
    try:
        return _controller_bridge_source_binding(source_report)
    except SoperatorMigrationPhasePending:
        if checkpoint_source is None:
            raise
        return checkpoint_source


def _target_slurmctld_image_lock(
    payload: Mapping[str, Any],
    *,
    target_ref: str,
    checkpoint: Mapping[str, Any] | None = None,
) -> tuple[str, str, dict[str, str]]:
    images = _mapping(_target_soperator_values(payload, target_ref).get("images"))
    image = str(images.get("slurmctld", "") or "").strip()
    if not image:
        row = _target_soperator_row(payload, target_ref)
        onboarding = _target_onboarding(payload, target_ref)
        campaign = _mapping(onboarding.get("upgrade_path"))
        target_version = str(
            row.get("version")
            or _mapping(campaign.get("soperator_app")).get("target_version")
            or onboarding.get("target_version")
            or ""
        ).strip()
        profile = soperator_migration_profile_for_version(target_version)
        component_contracts = (
            profile.get("component_contracts") if isinstance(profile, Mapping) else None
        )
        candidates: list[str] = []
        if isinstance(component_contracts, Sequence) and not isinstance(
            component_contracts,
            (str, bytes, bytearray),
        ):
            for contract in component_contracts:
                if not isinstance(contract, Mapping) or contract.get("id") != "slurm-cluster":
                    continue
                contract_images = _mapping(contract.get("images")).get("values")
                if not isinstance(contract_images, Sequence) or isinstance(
                    contract_images,
                    (str, bytes, bytearray),
                ):
                    continue
                candidates.extend(
                    candidate
                    for raw_candidate in contract_images
                    if (candidate := str(raw_candidate or "").strip())
                    and candidate.rsplit("/", 1)[-1].split(":", 1)[0] == "controller_slurmctld"
                )
        if len(candidates) == 1:
            image = candidates[0]
    if not image:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires exactly one target controller_slurmctld image "
            "from values.images.slurmctld or the accepted target release profile."
        )
    version_match = re.search(r"(?<!\d)(\d{2}\.\d{2}\.\d+)(?!\d)", image)
    if not version_match:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge could not derive the target Slurm version from "
            f"images.slurmctld={image!r}."
        )
    existing_lock = _mapping(
        _mapping((checkpoint or {}).get("controller_bridge")).get("target_image_lock")
    )
    if existing_lock:
        immutable_reference = str(existing_lock.get("immutable_reference", "") or "")
        platform_digest = str(existing_lock.get("platform_digest", "") or "")
        digest_match = re.search(r"@(sha256:[0-9a-f]{64})$", immutable_reference)
        if (
            str(existing_lock.get("source", "") or "") != image
            or str(existing_lock.get("os", "") or "") != "linux"
            or str(existing_lock.get("architecture", "") or "") != "amd64"
            or digest_match is None
            or platform_digest != digest_match.group(1)
        ):
            raise RuntimeError(
                "recovery-required: checkpointed target Slurm OCI lock does not match "
                "the accepted image or linux/amd64 platform digest."
            )
        return (
            immutable_reference,
            version_match.group(1),
            {str(key): str(value) for key, value in existing_lock.items()},
        )
    try:
        resolution = resolve_oci_image(image, os_name="linux", architecture="amd64")
    except (RuntimeError, ValueError, OSError) as exc:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge could not resolve the accepted upstream Slurm controller "
            f"image to one immutable linux/amd64 OCI manifest: {exc}"
        ) from exc
    return resolution.immutable_reference, version_match.group(1), resolution.as_payload()


def _controller_bridge_plan(
    *,
    checkpoint: Mapping[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    nebius_api: SoperatorMigrationNebiusApi,
    placement_domains: Sequence[BridgePlacementDomain] | None = None,
) -> tuple[BridgePlan, BridgeSourceBinding, Mapping[str, Any], Mapping[str, str]]:
    source_binding, source = _controller_bridge_plan_source_binding(
        checkpoint=checkpoint,
        source_report=source_report,
    )
    target_image, target_slurm_version, target_image_lock = _target_slurmctld_image_lock(
        payload,
        target_ref=target_ref,
        checkpoint=checkpoint,
    )
    controller_groups = [
        (group_name, raw_group)
        for group_name, raw_group in _source_node_group_inventory(source_report).items()
        if isinstance(raw_group, Mapping)
        and _source_group_service_role(group_name, raw_group) == "controller"
    ]
    if len(controller_groups) != 1:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires exactly one source controller node-group binding."
        )
    _group_name, raw_group = controller_groups[0]
    node_group_id = _source_group_node_group_id(raw_group)
    if not node_group_id:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge could not resolve the source controller node-group ID."
        )
    source_node_group = _node_group_payload_by_id(
        nebius_api=nebius_api,
        node_group_id=node_group_id,
    )
    source_template = copy.deepcopy(
        _mapping(_mapping(source_node_group.get("spec")).get("template"))
    )
    source_version = _minor_version_text_or_empty(_node_group_version(source_node_group))
    if not source_template or not source_version:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge could not clone the source controller node template and "
            "Kubernetes version."
        )
    source_filesystems = _sequence_of_mappings(source_template.get("filesystems"))
    jail_attachments = [
        item
        for item in source_filesystems
        if _filesystem_attachment_id(item) == source_binding.jail_filesystem_id
    ]
    if len(jail_attachments) != 1:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires exactly one source controller node-group "
            "attachment for the immutable Jail SFS discovered during onboarding."
        )
    jail_attachment = dict(copy.deepcopy(to_plain_data(jail_attachments[0])))
    if not str(jail_attachment.get("mount_tag", "") or "").strip():
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge source Jail SFS attachment has no exact mount tag."
        )
    managed_adapter = placement_domains is not None
    controller_spool: Mapping[str, Any] = {}
    filesystem_id = ""
    if managed_adapter:
        candidates = [
            item
            for item in source_filesystems
            if _filesystem_attachment_id(item) != source_binding.jail_filesystem_id
            and "controller" in str(item.get("mount_tag", "") or "").lower()
            and "spool" in str(item.get("mount_tag", "") or "").lower()
        ]
        if len(candidates) != 1:
            raise SoperatorMigrationPhasePending(
                "managed controller-ha-bridge requires exactly one chart-managed "
                "controller-spool filesystem attachment on the fixed controller domain."
            )
        controller_spool = dict(copy.deepcopy(to_plain_data(candidates[0])))
        filesystem_id = _filesystem_attachment_id(controller_spool)
    else:
        filesystem_state = _mapping(
            _mapping(_mapping(checkpoint.get("phase_state")).get("create-aligned-sfs")).get(
                "filesystems"
            )
        )
        controller_spool = _mapping(filesystem_state.get("controller-spool"))
        filesystem_id = str(controller_spool.get("id", "") or "").strip()
        if not filesystem_id:
            spec = next(
                (
                    item
                    for item in _aligned_filesystem_specs(payload=payload, target_ref=target_ref)
                    if item.key == "controller-spool"
                ),
                None,
            )
            if spec is not None:
                filesystem_id = _filesystem_id(
                    _get_filesystem_by_name(
                        nebius_api=nebius_api,
                        project_id=_nebius_project_id(payload),
                        name=spec.name,
                    )
                )
                controller_spool = {
                    "id": filesystem_id,
                    "mount_tag": spec.mount_tag,
                }
    if not filesystem_id:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires the aligned controller-spool SFS before bridge "
            "node-group creation."
        )
    mount_tag = str(controller_spool.get("mount_tag", "") or "controller-spool").strip()
    fingerprint = str(checkpoint.get("campaign_fingerprint", "") or "").strip()
    cluster_id = _target_cluster_id(payload, target_ref)
    bridge_group_names = _controller_bridge_node_group_names(checkpoint)
    if placement_domains is not None:
        managed_domains: list[BridgePlacementDomain] = []
        for domain in placement_domains:
            live_domain = _node_group_payload_by_id(
                nebius_api=nebius_api,
                node_group_id=domain.node_group_id,
            )
            live_name = _node_group_name(live_domain)
            if not live_name:
                raise SoperatorMigrationPhasePending(
                    f"managed bridge {domain.role} provider group has no stable name."
                )
            managed_domains.append(
                BridgePlacementDomain.managed(
                    name=live_name,
                    role=domain.role,
                    node_group_id=domain.node_group_id,
                    selector=dict(domain.selector or {}),
                    live_node_uid=domain.live_node_uid,
                    ready_capacity=domain.ready_capacity,
                    template=domain.template,
                )
            )
        resolved_domains = tuple(managed_domains)
    else:
        resolved_domains = (
            BridgePlacementDomain.external(
                name=bridge_group_names[0],
                role="external-a",
                template=source_template,
            ),
            BridgePlacementDomain.external(
                name=bridge_group_names[1],
                role="external-b",
                template=source_template,
            ),
        )
    if len(resolved_domains) != 2:
        raise RuntimeError("Controller bridge requires exactly two placement domains.")
    plan = BridgePlan(
        campaign_fingerprint=fingerprint,
        cluster_id=cluster_id,
        cluster_name=source_binding.slurmcluster_name,
        source_kubernetes_version=source_version,
        source_slurm_image=source_binding.slurm_image_digest,
        target_slurm_image=target_image,
        source_slurm_version=source_binding.slurm_version,
        target_slurm_version=target_slurm_version,
        state_save_location="/mnt/controller-spool/current",
        controller_spool_attachment={
            "attach_mode": "READ_WRITE",
            "existing_filesystem": {"id": filesystem_id},
            "mount_tag": mount_tag,
        },
        jail_attachment=jail_attachment,
        placement_domains=(resolved_domains[0], resolved_domains[1]),
    )
    return plan, source_binding, source, target_image_lock


def _controller_bridge_journal(
    *,
    checkpoint: dict[str, Any],
    plan: BridgePlan,
    source_binding: BridgeSourceBinding,
    target_image_lock: Mapping[str, str],
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    segment_epoch_suffix = _controller_bridge_segment_epoch_suffix(
        checkpoint=checkpoint,
        plan=plan,
    )
    raw = checkpoint.get("controller_bridge")
    if raw is None:
        journal = new_bridge_journal(
            source=source_binding,
            plan=plan,
            authority_epoch=f"source-{segment_epoch_suffix}",
        )
        journal["segment_epoch_suffix"] = segment_epoch_suffix
        journal["target_image_lock"] = dict(target_image_lock)
        validate_bridge_journal(journal)
        checkpoint["controller_bridge"] = journal
        if checkpoint_writer is not None:
            checkpoint_writer()
        return journal
    if not isinstance(raw, dict):
        raise RuntimeError("External Soperator v6 controller_bridge must be a mapping.")
    if str(raw.get("segment_epoch_suffix", "") or "") != segment_epoch_suffix:
        raise RuntimeError(
            "recovery-required: controller bridge segment epoch differs from the "
            "current campaign segment."
        )
    try:
        validate_bridge_journal(raw)
    except ValueError as exc:
        raise RuntimeError(
            f"External Soperator v6 controller bridge journal is invalid: {exc}"
        ) from exc
    expected_source = source_binding.as_payload()
    if dict(_mapping(raw.get("source_binding"))) != expected_source:
        raise RuntimeError(
            "recovery-required: controller bridge source identity or fingerprints changed."
        )
    if (
        str(raw.get("campaign_fingerprint", "") or "") != plan.campaign_fingerprint
        or str(raw.get("cluster_id", "") or "") != plan.cluster_id
        or [
            str(item.get("name", "") or "")
            for item in _sequence_of_mappings(raw.get("node_groups"))
        ]
        != [item.name for item in plan.placement_domains]
    ):
        raise RuntimeError("recovery-required: controller bridge plan differs from the v6 journal.")
    expected_attachment_sha256 = _fingerprint(plan.controller_spool_attachment)
    expected_jail_attachment_sha256 = _fingerprint(plan.jail_attachment)
    if any(
        str(item.get("controller_spool_attachment_sha256", "") or "") != expected_attachment_sha256
        or str(item.get("jail_attachment_sha256", "") or "") != expected_jail_attachment_sha256
        for item in _sequence_of_mappings(raw.get("node_groups"))
    ):
        raise RuntimeError(
            "recovery-required: controller bridge node-group spool or Jail SFS attachment "
            "differs from the v6 journal."
        )
    if dict(_mapping(raw.get("target_image_lock"))) != dict(target_image_lock):
        raise RuntimeError("recovery-required: target Slurm OCI digest or platform lock changed.")
    return raw


def _controller_bridge_segment_epoch_suffix(
    *,
    checkpoint: Mapping[str, Any],
    plan: BridgePlan,
) -> str:
    """Return a stable, campaign-local authority suffix unique to one segment."""

    segment_id = str(checkpoint.get("current_segment_id", "") or "").strip()
    if not segment_id:
        raise RuntimeError("Controller bridge requires the current campaign segment identity.")
    segment_digest = hashlib.sha256(segment_id.encode("utf-8")).hexdigest()[:12]
    return f"{plan.campaign_fingerprint[:12]}-{segment_digest}"


def _controller_bridge_epoch(journal: Mapping[str, Any], owner: str) -> str:
    suffix = str(journal.get("segment_epoch_suffix", "") or "").strip()
    if not suffix:
        current = str(_mapping(journal.get("authority")).get("epoch", "") or "")
        for prefix in ("source-", "bridge-source-", "bridge-target-", "target-"):
            if current.startswith(prefix):
                suffix = current.removeprefix(prefix)
                break
    if not re.fullmatch(r"[a-z0-9.-]+", suffix):
        raise RuntimeError("Controller bridge segment authority suffix is missing or unsafe.")
    return f"{owner}-{suffix}"


def _migrate_pre_authority_bridge_segment_epoch(
    *,
    checkpoint: dict[str, Any],
    plan: BridgePlan,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Repair the old campaign-wide epoch before any bridge controller can write."""

    raw = checkpoint.get("controller_bridge")
    if not isinstance(raw, dict):
        return
    if str(raw.get("stage", "") or "") in {
        BridgeStage.TARGET_HA_ACTIVE.value,
        BridgeStage.BRIDGE_FENCED.value,
        BridgeStage.TARGET_SINGLETON_ACTIVE.value,
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
        BridgeStage.CLEANED.value,
    }:
        return
    expected_suffix = _controller_bridge_segment_epoch_suffix(checkpoint=checkpoint, plan=plan)
    expected_epoch = f"source-{expected_suffix}"
    authority = _mapping(raw.get("authority"))
    current_epoch = str(authority.get("epoch", "") or "")
    segment_epochs = {
        f"{owner}-{expected_suffix}"
        for owner in ("source", "bridge-source", "bridge-target", "target", "pre-target")
    }
    if current_epoch in segment_epochs:
        raw["segment_epoch_suffix"] = expected_suffix
        return
    legacy_epoch = f"source-{plan.campaign_fingerprint[:12]}"
    if current_epoch != legacy_epoch:
        raise RuntimeError(
            "recovery-required: controller bridge authority epoch is neither the current "
            "segment identity nor the repairable campaign-wide identity."
        )
    validate_bridge_journal(raw)
    state_precopy = _mapping(raw.get("state_precopy"))
    if (
        authority.get("owner") != "source-singleton"
        or str(authority.get("first_bridge_write_at", "") or "")
        or authority.get("source_restart_prohibited") is True
        or str(raw.get("stage", "") or "")
        not in {
            BridgeStage.PLANNED.value,
            BridgeStage.SUBSTRATE_READY.value,
            BridgeStage.SOURCE_CONFIGURED.value,
        }
        or _mapping(raw.get("source_fence_intent"))
        or _mapping(raw.get("cold_reader"))
        or _mapping(raw.get("state_manifest")).get("promoted") is True
        or _sequence_of_mappings(raw.get("controller_roles"))
        or str(state_precopy.get("completed_at", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: campaign-wide controller epoch cannot be repaired after "
            "source fencing, state promotion, or the first bridge write."
        )
    migration = raw.get("segment_epoch_migration")
    expected_migration = {
        "schema": "nebius-cxcli-controller-bridge-segment-epoch-migration/v1",
        "from_epoch": legacy_epoch,
        "to_epoch": expected_epoch,
        "segment_id": str(checkpoint.get("current_segment_id", "") or ""),
    }
    if migration is None:
        migration = {
            **expected_migration,
            "state": "intent-recorded",
            "intent_at": _utc_now(),
        }
        raw["segment_epoch_migration"] = migration
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif not isinstance(migration, dict) or any(
        migration.get(key) != value for key, value in expected_migration.items()
    ):
        raise RuntimeError("recovery-required: controller segment epoch migration changed.")

    lease_exists, live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Lease",
            "namespace": str(raw.get("namespace", "") or ""),
            "name": CONTROLLER_AUTHORITY_LEASE,
        },
    )
    if not lease_exists:
        raise RuntimeError("recovery-required: controller authority Lease disappeared.")
    metadata = _mapping(live.get("metadata"))
    annotations = _mapping(metadata.get("annotations"))
    old_holder = f"{legacy_epoch}:source-singleton"
    new_holder = f"{expected_epoch}:source-singleton"
    observed_holder = str(_mapping(live.get("spec")).get("holderIdentity", "") or "")
    if observed_holder == old_holder:
        current_binding = validate_controller_authority_lease(
            live,
            namespace=str(raw.get("namespace", "") or ""),
            campaign_fingerprint=plan.campaign_fingerprint,
            cluster_id=plan.cluster_id,
            authority_epoch=legacy_epoch,
            owner="source-singleton",
        )
        migration.update(
            {
                "state": "dispatching",
                "dispatching_at": str(migration.get("dispatching_at", "") or "") or _utc_now(),
                "lease_uid": current_binding["uid"],
                "lease_resource_version": current_binding["resource_version"],
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        patch = [
            {"op": "test", "path": "/metadata/uid", "value": current_binding["uid"]},
            {
                "op": "test",
                "path": "/metadata/resourceVersion",
                "value": current_binding["resource_version"],
            },
            {"op": "test", "path": "/spec/holderIdentity", "value": old_holder},
            {
                "op": "test",
                "path": "/metadata/annotations/nebius.ai~1cxcli-authority-epoch",
                "value": str(annotations.get("nebius.ai/cxcli-authority-epoch", "") or ""),
            },
            {
                "op": "replace",
                "path": "/metadata/annotations/nebius.ai~1cxcli-authority-epoch",
                "value": expected_epoch,
            },
            {"op": "replace", "path": "/spec/holderIdentity", "value": new_holder},
        ]
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                str(raw.get("namespace", "") or ""),
                "patch",
                "lease",
                CONTROLLER_AUTHORITY_LEASE,
                "--type=json",
                "-p",
                json.dumps(patch, separators=(",", ":")),
            ],
            timeout_seconds=120,
        )
        lease_exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity={
                "kind": "Lease",
                "namespace": str(raw.get("namespace", "") or ""),
                "name": CONTROLLER_AUTHORITY_LEASE,
            },
        )
        if not lease_exists:
            raise RuntimeError("recovery-required: controller authority Lease vanished after CAS.")
    elif observed_holder != new_holder:
        raise RuntimeError(
            "recovery-required: controller authority Lease has an unexpected holder during "
            "segment epoch repair."
        )
    binding = validate_controller_authority_lease(
        live,
        namespace=str(raw.get("namespace", "") or ""),
        campaign_fingerprint=plan.campaign_fingerprint,
        cluster_id=plan.cluster_id,
        authority_epoch=expected_epoch,
        owner="source-singleton",
    )
    mutable_authority = raw.get("authority")
    if not isinstance(mutable_authority, dict):
        raise RuntimeError("Controller bridge authority journal must be mutable.")
    mutable_authority["epoch"] = expected_epoch
    history = mutable_authority.get("history")
    if not isinstance(history, list):
        raise RuntimeError("Controller bridge authority history must be mutable.")
    history.append(
        {
            "epoch": expected_epoch,
            "owner": "source-singleton",
            "at": _utc_now(),
            "reason": "campaign segment authority epoch repaired before first bridge write",
        }
    )
    raw["segment_epoch_suffix"] = expected_suffix
    raw["authority_lease"] = binding
    raw["state_precopy"] = {}
    migration.update({"state": "accepted", "accepted_at": _utc_now(), **binding})
    validate_bridge_journal(raw)
    if checkpoint_writer is not None:
        checkpoint_writer()


def _recover_controller_bridge_pre_authority_source_restart(
    *,
    checkpoint: dict[str, Any],
    plan: BridgePlan,
    source_binding: BridgeSourceBinding,
    source: Mapping[str, Any],
    artifact_dir: Path,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    raw = checkpoint.get("controller_bridge")
    if not isinstance(raw, dict):
        return []
    expected_source = source_binding.as_payload()
    recorded_source = dict(_mapping(raw.get("source_binding")))
    if recorded_source == expected_source:
        return []
    changed_fields = {
        key
        for key in set(recorded_source) | set(expected_source)
        if recorded_source.get(key) != expected_source.get(key)
    }
    authority = _mapping(raw.get("authority"))
    source_fence_intent = _mapping(raw.get("source_fence_intent"))
    source_fencing = _mapping(_mapping(raw.get("fencing")).get("source"))
    bridge_fencing = _mapping(_mapping(raw.get("fencing")).get("bridge"))
    precopy = _mapping(raw.get("state_precopy"))
    stage = str(raw.get("stage", "") or "")
    if (
        changed_fields == {"controller_pod_uid"}
        and stage == BridgeStage.STATE_PROMOTED.value
        and authority.get("owner") == "source-singleton"
        and not str(authority.get("first_bridge_write_at", "") or "")
        and authority.get("source_restart_prohibited") is not True
        and source_fence_intent.get("state") == "accepted"
        and source_fencing.get("proven") is True
        and source_fencing.get("process_absent") is True
        and source_fencing.get("writable_mount_absent") is True
        and bridge_fencing.get("proven") is not True
        and not _sequence_of_mappings(raw.get("controller_roles"))
        and str(precopy.get("source_pod_uid", "") or "")
        == str(recorded_source.get("controller_pod_uid", "") or "")
        and str(source_fence_intent.get("source_pod_uid", "") or "")
        == str(recorded_source.get("controller_pod_uid", "") or "")
    ):
        validate_bridge_journal(raw)
        source_configuration = raw.get("source_configuration")
        fencing = raw.get("fencing")
        recoveries_value = raw.get("source_restart_recoveries")
        recoveries = [] if recoveries_value is None else recoveries_value
        if not isinstance(source_configuration, dict):
            raise RuntimeError(
                "recovery-required: promoted-state source restart lacks mutable source "
                "configuration."
            )
        if not isinstance(fencing, dict) or not isinstance(fencing.get("source"), dict):
            raise RuntimeError(
                "recovery-required: promoted-state source restart lacks mutable fencing state."
            )
        if not isinstance(recoveries, list):
            raise RuntimeError(
                "recovery-required: controller bridge source restart recoveries must be a list."
            )
        epoch = str(authority.get("epoch", "") or "")
        precopy_token = str(precopy.get("transfer_token", "") or "")
        cold_reader = _mapping(raw.get("cold_reader"))
        cold_token = str(cold_reader.get("transfer_token", "") or "")
        delta_token = str(cold_reader.get("delta_token", "") or "")
        manifest = _mapping(raw.get("state_manifest"))
        if (
            not re.fullmatch(r"[a-z0-9.-]+", epoch)
            or not re.fullmatch(r"[0-9a-f]{32}", precopy_token)
            or not re.fullmatch(r"[0-9a-f]{32}", cold_token)
            or not re.fullmatch(r"[0-9a-f]{32}", delta_token)
            or cold_reader.get("status") != "absent"
            or cold_reader.get("mount_absent") is not True
            or cold_reader.get("remote_delta_applied") is not True
            or str(cold_reader.get("authority_epoch", "") or "") != epoch
            or str(cold_reader.get("remote_epoch_path", "") or "") != f"/shared/epochs/{epoch}"
            or manifest.get("promoted") is not True
            or manifest.get("fsynced") is not True
            or str(manifest.get("epoch_directory", "") or "")
            != f"/mnt/controller-spool/epochs/{epoch}"
            or str(manifest.get("stable_path", "") or "") != plan.state_save_location
        ):
            raise RuntimeError(
                "recovery-required: pre-authority promoted-state source restart has unsafe "
                "or incomplete campaign bindings."
            )

        source_workload = _mapping(source.get("controller_workload"))
        source_pod = _mapping(source.get("controller_pod"))
        workload_resource = {
            ("apps.kruise.io/v1beta1", "StatefulSet"): "statefulsets.apps.kruise.io",
            ("apps/v1", "StatefulSet"): "statefulsets.apps",
            ("apps/v1", "Deployment"): "deployments.apps",
        }.get(
            (
                str(source_workload.get("api_version", "") or ""),
                str(source_workload.get("kind", "") or ""),
            )
        )
        if (
            workload_resource is None
            or str(source_workload.get("namespace", "") or "") != source_binding.namespace
            or str(source_workload.get("name", "") or "") != source_binding.controller_workload_name
            or str(source_workload.get("uid", "") or "") != source_binding.controller_workload_uid
            or str(source_pod.get("namespace", "") or "") != source_binding.namespace
            or str(source_pod.get("name", "") or "") != source_binding.controller_pod_name
            or str(source_pod.get("uid", "") or "") != source_binding.controller_pod_uid
        ):
            raise RuntimeError(
                "recovery-required: replacement source controller discovery is not bound to "
                "the expected live workload and Pod."
            )
        exclusivity_evidence = _prove_cluster_wide_slurmctld_exclusivity(
            expected_pods=(
                (
                    source_binding.namespace,
                    source_binding.controller_pod_name,
                    source_binding.controller_pod_uid,
                ),
            ),
            expected_workload=(
                workload_resource,
                source_binding.namespace,
                source_binding.controller_workload_name,
                source_binding.controller_workload_uid,
            ),
            expected_replicas=1,
            proof_label="pre-authority restored source controller recovery",
            campaign_fingerprint=plan.campaign_fingerprint,
            journal=raw,
            kube_context=kube_context,
            command_runner=command_runner,
        )

        local_paths = (
            artifact_dir / f"{epoch}.{precopy_token}.precopy.tar",
            artifact_dir / f"{epoch}.{precopy_token}.precopy.snar",
            artifact_dir / f"{epoch}.{delta_token}.cold-delta.tar",
            artifact_dir / f"{epoch}.{delta_token}.cold.snar",
            artifact_dir / f"{epoch}.{delta_token}.cold-source.tree.tsv",
        )
        recorded_local_paths = (
            str(precopy.get("archive_path", "") or ""),
            str(precopy.get("incremental_snapshot_path", "") or ""),
            str(cold_reader.get("delta_archive_path", "") or ""),
            str(cold_reader.get("incremental_snapshot_path", "") or ""),
            str(cold_reader.get("source_manifest_path", "") or ""),
        )
        if recorded_local_paths != tuple(str(path) for path in local_paths):
            raise RuntimeError(
                "recovery-required: promoted-state source restart artifacts differ from "
                "their campaign-owned locations."
            )
        for path in local_paths:
            if path.is_symlink() or (path.exists() and not path.is_file()):
                raise RuntimeError(
                    "recovery-required: promoted-state source restart found an unsafe local "
                    f"artifact: {path}."
                )

        current = "/shared/current"
        current_temporary = f"/shared/.current-{epoch}"
        destination = f"/shared/epochs/{epoch}"
        precopy_destination = f"/shared/epochs/{epoch}.precopy"
        precopy_build = f"/shared/.incoming-{epoch}-precopy-{precopy_token}"
        cold_build = f"/shared/.incoming-{epoch}-cold-delta-{cold_token}"
        removable_directories = (
            destination,
            precopy_destination,
            precopy_build,
            cold_build,
        )
        removable_files = (
            f"/shared/.cxcli-incremental/{epoch}.precopy.tar",
            f"/shared/.cxcli-incremental/{epoch}.precopy.snar",
            f"/shared/.cxcli-incremental/{epoch}.cold-delta.tar",
            f"/shared/.cxcli-manifests/{epoch}.precopy.tree.tsv",
            f"/shared/.cxcli-manifests/{epoch}.precopy.tree.tsv.work",
            f"/shared/.cxcli-manifests/{epoch}.precopy.tree.tsv.paths",
            f"/shared/.cxcli-manifests/{epoch}.precopy.build.tsv",
            f"/shared/.cxcli-manifests/{epoch}.precopy.build.tsv.work",
            f"/shared/.cxcli-manifests/{epoch}.precopy.build.tsv.paths",
            f"/shared/.cxcli-manifests/{epoch}.cold-source.tree.tsv",
            f"/shared/.cxcli-manifests/{epoch}.cold-build.tree.tsv",
            f"/shared/.cxcli-manifests/{epoch}.cold-build.tree.tsv.work",
            f"/shared/.cxcli-manifests/{epoch}.cold-build.tree.tsv.paths",
            f"/shared/.cxcli-manifests/{epoch}.cold.tree.tsv",
            f"/shared/.cxcli-manifests/{epoch}.cold.tree.tsv.work",
            f"/shared/.cxcli-manifests/{epoch}.cold.tree.tsv.paths",
        )
        recovery_intent = raw.get("source_restart_recovery_intent")
        expected_intent = {
            "schema": "nebius-cxcli-controller-bridge-source-restart-recovery-intent/v1",
            "mode": "discard-stale-promoted-state",
            "authority_epoch": epoch,
            "prior_source_pod_uid": str(recorded_source["controller_pod_uid"]),
            "replacement_source_pod_uid": str(expected_source["controller_pod_uid"]),
        }
        if recovery_intent is None:
            preflight_script = (
                "set -eu; expected="
                + shlex.quote(f"epochs/{epoch}")
                + f"; test -L {shlex.quote(current)}; "
                + f'test "$(readlink {shlex.quote(current)})" = "$expected"; '
                + f"test ! -L {shlex.quote(destination)}; "
                + f"test -d {shlex.quote(destination)}; "
                + "; ".join(
                    f"if test -e {shlex.quote(path)}; then test ! -L {shlex.quote(path)}; fi"
                    for path in removable_directories[1:] + removable_files
                )
            )
            command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    plan.namespace,
                    "exec",
                    "cxcli-controller-bridge-stager",
                    "-c",
                    "stager",
                    "--",
                    "/bin/sh",
                    "-ec",
                    preflight_script,
                ],
                timeout_seconds=300,
            )
            raw["source_restart_recovery_intent"] = {
                **expected_intent,
                "state": "cleanup-dispatching",
                "exclusivity_proof_sha256": _fingerprint(exclusivity_evidence),
                "recorded_at": _utc_now(),
            }
            if checkpoint_writer is not None:
                checkpoint_writer()
        elif (
            not isinstance(recovery_intent, Mapping)
            or any(recovery_intent.get(key) != value for key, value in expected_intent.items())
            or recovery_intent.get("state") != "cleanup-dispatching"
        ):
            raise RuntimeError(
                "recovery-required: promoted-state source restart cleanup intent changed."
            )

        cleanup_script = (
            "set -eu; expected="
            + shlex.quote(f"epochs/{epoch}")
            + f"; if test -e {shlex.quote(current)} || test -L {shlex.quote(current)}; then "
            + f"test -L {shlex.quote(current)}; "
            + f'test "$(readlink {shlex.quote(current)})" = "$expected"; '
            + f"rm -f -- {shlex.quote(current)}; fi; "
            + f"if test -e {shlex.quote(current_temporary)} || "
            + f"test -L {shlex.quote(current_temporary)}; then "
            + f"test -L {shlex.quote(current_temporary)}; "
            + f'test "$(readlink {shlex.quote(current_temporary)})" = "$expected"; '
            + f"rm -f -- {shlex.quote(current_temporary)}; fi; "
            + "; ".join(
                f"if test -e {shlex.quote(path)}; then test ! -L {shlex.quote(path)}; "
                f"test -d {shlex.quote(path)}; rm -rf -- {shlex.quote(path)}; fi"
                for path in removable_directories
            )
            + "; "
            + "; ".join(
                f"if test -e {shlex.quote(path)}; then test ! -L {shlex.quote(path)}; "
                f"test -f {shlex.quote(path)}; rm -f -- {shlex.quote(path)}; fi"
                for path in removable_files
            )
            + "; sync -f /shared; sync -f /shared/epochs"
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                cleanup_script,
            ],
            timeout_seconds=300,
        )
        for path in local_paths:
            path.unlink(missing_ok=True)

        raw["source_binding"] = expected_source
        raw["stage"] = BridgeStage.SOURCE_CONFIGURED.value
        raw["state_precopy"] = {}
        raw["state_manifest"] = {
            "epoch_directory": "",
            "stable_path": plan.state_save_location,
            "sha256": "",
            "file_count": 0,
            "fsynced": False,
            "promoted": False,
        }
        raw["cold_reader"] = {}
        raw["pre_source_fence_readiness"] = {}
        raw["source_fence_intent"] = {}
        raw["runtime_fence_proofs"] = []
        raw["controller_roles"] = []
        source_configuration["client_propagation"] = None
        fencing["source"] = {
            "proven": False,
            "pod_uid": str(expected_source["controller_pod_uid"]),
            "workload_uid": str(expected_source["controller_workload_uid"]),
            "process_absent": False,
            "writable_mount_absent": False,
            "observed_at": "",
            "runtime_target": {},
        }
        raw["shared_mount_canaries"] = [
            dict(item)
            for item in _sequence_of_mappings(raw.get("shared_mount_canaries"))
            if item.get("purpose") != CONTROLLER_BRIDGE_PRE_SOURCE_FENCE_CANARY
        ]
        raw["source_restart_recoveries"] = recoveries
        recoveries.append(
            {
                "schema": "nebius-cxcli-controller-bridge-source-restart-recovery/v1",
                "reason": "operator-restored-source-after-state-promotion-before-first-bridge-write",
                "prior_source_pod_uid": str(recorded_source["controller_pod_uid"]),
                "replacement_source_pod_uid": str(expected_source["controller_pod_uid"]),
                "exclusivity_proof_sha256": _fingerprint(exclusivity_evidence),
                "recovered_at": _utc_now(),
            }
        )
        raw.pop("source_restart_recovery_intent", None)
        validate_bridge_journal(raw)
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            "Controller bridge recovery: proved the restored source is the sole live "
            "controller, discarded the stale campaign-owned promoted snapshot, and reset "
            "all dependent source-fence proofs before a fresh cold promotion."
        ]
    if (
        changed_fields != {"controller_pod_uid"}
        or stage != BridgeStage.SOURCE_PRECOPIED.value
        or authority.get("owner") != "source-singleton"
        or str(authority.get("first_bridge_write_at", "") or "")
        or authority.get("source_restart_prohibited") is True
        or source_fence_intent.get("state") != "dispatching"
        or source_fencing.get("proven") is True
        or bridge_fencing.get("proven") is True
        or str(precopy.get("source_pod_uid", "") or "")
        != str(recorded_source.get("controller_pod_uid", "") or "")
        or str(source_fence_intent.get("source_pod_uid", "") or "")
        != str(recorded_source.get("controller_pod_uid", "") or "")
    ):
        return []
    validate_bridge_journal(raw)
    epoch = str(authority.get("epoch", "") or "")
    transfer_token = str(precopy.get("transfer_token", "") or "")
    if not re.fullmatch(r"[a-z0-9.-]+", epoch) or not re.fullmatch(r"[0-9a-f]{32}", transfer_token):
        raise RuntimeError(
            "recovery-required: pre-authority source restart has unsafe pre-copy tokens."
        )
    expected_archive = artifact_dir / f"{epoch}.{transfer_token}.precopy.tar"
    expected_snapshot = artifact_dir / f"{epoch}.{transfer_token}.precopy.snar"
    if (
        str(precopy.get("archive_path", "") or "") != str(expected_archive)
        or str(precopy.get("incremental_snapshot_path", "") or "") != str(expected_snapshot)
        or str(precopy.get("remote_path", "") or "") != f"/shared/epochs/{epoch}.precopy"
    ):
        raise RuntimeError(
            "recovery-required: pre-authority source restart pre-copy paths differ from "
            "their campaign-owned locations."
        )
    for path in (expected_archive, expected_snapshot):
        if path.is_symlink() or (path.exists() and not path.is_file()):
            raise RuntimeError(
                "recovery-required: pre-authority source restart found an unsafe local "
                f"pre-copy artifact: {path}."
            )
    destination = f"/shared/epochs/{epoch}.precopy"
    build = f"/shared/.incoming-{epoch}-precopy-{transfer_token}"
    manifest = f"/shared/.cxcli-manifests/{epoch}.precopy.tree.tsv"
    build_manifest = f"/shared/.cxcli-manifests/{epoch}.precopy.build.tsv"
    remote_archive = f"/shared/.cxcli-incremental/{epoch}.precopy.tar"
    remote_snapshot = f"/shared/.cxcli-incremental/{epoch}.precopy.snar"
    cleanup_script = (
        "set -eu; "
        + "; ".join(
            f"test ! -L {shlex.quote(path)}"
            for path in (
                destination,
                build,
                manifest,
                build_manifest,
                f"{build_manifest}.work",
                f"{build_manifest}.paths",
                remote_archive,
                remote_snapshot,
            )
        )
        + f"; if test -e {shlex.quote(destination)}; then "
        + f"test -d {shlex.quote(destination)}; rm -rf -- {shlex.quote(destination)}; fi"
        + f"; if test -e {shlex.quote(build)}; then "
        + f"test -d {shlex.quote(build)}; rm -rf -- {shlex.quote(build)}; fi"
        + "; rm -f -- "
        + " ".join(
            shlex.quote(path)
            for path in (
                manifest,
                build_manifest,
                f"{build_manifest}.work",
                f"{build_manifest}.paths",
                remote_archive,
                remote_snapshot,
            )
        )
        + "; sync -f /shared/epochs"
    )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            cleanup_script,
        ],
        timeout_seconds=300,
    )
    for path in (expected_archive, expected_snapshot):
        path.unlink(missing_ok=True)
    raw["source_binding"] = expected_source
    raw["stage"] = BridgeStage.SOURCE_CONFIGURED.value
    raw["state_precopy"] = {}
    raw["pre_source_fence_readiness"] = {}
    raw["source_fence_intent"] = {}
    source_configuration = raw.get("source_configuration")
    if not isinstance(source_configuration, dict):
        raise RuntimeError(
            "recovery-required: pre-authority source restart lacks mutable source configuration."
        )
    source_configuration["client_propagation"] = None
    fencing = raw.get("fencing")
    if not isinstance(fencing, dict) or not isinstance(fencing.get("source"), dict):
        raise RuntimeError(
            "recovery-required: pre-authority source restart lacks mutable fencing state."
        )
    fencing["source"] = {
        "proven": False,
        "pod_uid": str(expected_source["controller_pod_uid"]),
        "workload_uid": str(expected_source["controller_workload_uid"]),
        "process_absent": False,
        "writable_mount_absent": False,
        "observed_at": "",
        "runtime_target": {},
    }
    raw["shared_mount_canaries"] = [
        dict(item)
        for item in _sequence_of_mappings(raw.get("shared_mount_canaries"))
        if item.get("purpose") != CONTROLLER_BRIDGE_PRE_SOURCE_FENCE_CANARY
    ]
    recoveries = raw.setdefault("source_restart_recoveries", [])
    if not isinstance(recoveries, list):
        raise RuntimeError(
            "recovery-required: controller bridge source restart recoveries must be a list."
        )
    recoveries.append(
        {
            "schema": "nebius-cxcli-controller-bridge-source-restart-recovery/v1",
            "reason": "operator-restored-source-before-first-bridge-write",
            "prior_source_pod_uid": str(recorded_source["controller_pod_uid"]),
            "replacement_source_pod_uid": str(expected_source["controller_pod_uid"]),
            "recovered_at": _utc_now(),
        }
    )
    validate_bridge_journal(raw)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Controller bridge recovery: rebound the pre-authority source Pod, removed only "
        "the stale campaign-owned pre-copy, and invalidated dependent fence proofs."
    ]


def _create_controller_bridge_node_groups(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    plan: BridgePlan,
    nebius_api: SoperatorMigrationNebiusApi,
    checkpoint_writer: Callable[[], None] | None,
) -> tuple[bool, list[str]]:
    records = journal.get("node_groups")
    if not isinstance(records, list) or len(records) != 2:
        raise RuntimeError("Controller bridge node-group journal must contain two records.")
    if all(domain.ownership == "managed-existing" for domain in plan.placement_domains):
        lines: list[str] = []
        for record, domain in zip(records, plan.placement_domains, strict=True):
            if not isinstance(record, dict):
                raise RuntimeError("Managed bridge placement-domain record must be mutable.")
            live = _node_group_payload_by_id(
                nebius_api=nebius_api,
                node_group_id=domain.node_group_id,
            )
            if (
                _node_group_id(live) != domain.node_group_id
                or _node_group_name(live) != domain.name
                or not _node_group_resource_version(live)
                or _node_group_fixed_count(live) != domain.ready_capacity
                or _minor_version_text_or_empty(_node_group_version(live))
                != plan.source_kubernetes_version
            ):
                raise RuntimeError(
                    "recovery-required: managed controller bridge placement domain "
                    f"{domain.role} changed identity, capacity, or Kubernetes version."
                )
            record.update(
                {
                    "id": domain.node_group_id,
                    "name": domain.name,
                    "bound": True,
                    "created": False,
                    "provider_resource_version": _node_group_resource_version(live),
                    "bound_at": record.get("bound_at") or _utc_now(),
                }
            )
            lines.append(
                "Controller bridge placement domain: bound existing "
                f"{domain.role} group {domain.name} ({domain.node_group_id}); provider "
                "create is forbidden."
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return False, lines

    payloads = bridge_node_group_payloads(plan)
    existing_groups = _list_node_groups(nebius_api=nebius_api, cluster_id=plan.cluster_id)
    mutation_performed = False
    lines: list[str] = []
    for record, create_payload in zip(records, payloads, strict=True):
        if not isinstance(record, dict):
            raise RuntimeError("Controller bridge node-group record must be mutable.")
        name = str(_mapping(create_payload.get("metadata")).get("name", "") or "")
        existing = _find_node_group_by_name(existing_groups, name)
        if existing:
            checkpointed_id, checkpointed_version = _completed_controller_bridge_record_binding(
                record,
                name=name,
                slot=int(record.get("slot", -1)),
            )
            node_group_id = _node_group_id(existing)
            exact = (
                _node_group_payload_by_id(
                    nebius_api=nebius_api,
                    node_group_id=node_group_id,
                )
                if node_group_id
                else existing
            )
            node_group_id = _validate_reused_controller_bridge_quota_group(
                node_group=exact or existing,
                name=name,
                slot=int(record.get("slot", -1)),
                cluster_id=plan.cluster_id,
                source_version=checkpointed_version or plan.source_kubernetes_version,
                expected_template=_mapping(_mapping(create_payload.get("spec")).get("template")),
                expected_filesystems_exact=True,
                expected_node_group_id=checkpointed_id,
            )
            recorded_id = str(record.get("id", "") or "")
            if recorded_id and recorded_id != node_group_id:
                raise RuntimeError(
                    f"recovery-required: controller bridge node-group identity changed for {name}."
                )
            existing_domain = _mapping(record.get("scheduling_failure_domain"))
            domain_group_id = str(existing_domain.get("node_group_id", "") or "")
            topology_key = str(existing_domain.get("topology_key", "") or "")
            runtime_fields = {
                field: str(existing_domain.get(field, "") or "")
                for field in ("topology_value", "node_name", "node_uid")
            }
            runtime_values_present = [bool(value) for value in runtime_fields.values()]
            if recorded_id and record.get("created") is True:
                if (
                    topology_key != "nebius.com/node-group-id"
                    or domain_group_id != node_group_id
                    or any(runtime_values_present) != all(runtime_values_present)
                    or (
                        all(runtime_values_present)
                        and runtime_fields["topology_value"] != node_group_id
                    )
                ):
                    raise RuntimeError(
                        "recovery-required: reused controller bridge node-group scheduling "
                        f"binding is incomplete or changed for {name}."
                    )
                lines.append(f"Controller bridge node group: reused {name} ({node_group_id}).")
                continue
            record.update(
                {
                    "id": node_group_id,
                    "created": True,
                    "bound_at": _utc_now(),
                    "scheduling_failure_domain": {
                        "topology_key": "nebius.com/node-group-id",
                        "node_group_id": node_group_id,
                    },
                }
            )
            lines.append(f"Controller bridge node group: reused {name} ({node_group_id}).")
            if checkpoint_writer is not None:
                checkpoint_writer()
            continue

        operation_entry = _provider_operation_intent_for_request(
            checkpoint=checkpoint,
            resource_state=record,
            operation_kind="mk8s-node-group-create",
            resource_id=f"{plan.cluster_id}/node-groups/{name}",
            resource_uid=name,
            resource_version=0,
            intended_postcondition={
                "cluster_id": plan.cluster_id,
                "name": name,
                "fixed_node_count": 1,
                "version": plan.source_kubernetes_version,
                "bridge_slot": record.get("slot"),
                "excluded_from_provider_upgrade": True,
            },
            checkpoint_writer=checkpoint_writer,
        )
        _provider_operation_requested(
            checkpoint=checkpoint,
            resource_state=record,
            operation_entry=operation_entry,
            checkpoint_writer=checkpoint_writer,
        )
        try:
            created = nebius_api.create_node_group(
                payload=create_payload,
                timeout_seconds=3900,
                operation_accepted=_provider_operation_acceptance_callback(
                    checkpoint=checkpoint,
                    resource_state=record,
                    operation_entry=operation_entry,
                    checkpoint_writer=checkpoint_writer,
                ),
            )
        except (Exception, KeyboardInterrupt) as exc:
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=record,
                operation_entry=operation_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            raise
        node_group_id = _node_group_id(created)
        if not node_group_id:
            raise RuntimeError(f"Controller bridge node group {name} returned no ID.")
        exact_created = _node_group_payload_by_id(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
        )
        _validate_reused_controller_bridge_quota_group(
            node_group=exact_created or created,
            name=name,
            slot=int(record.get("slot", -1)),
            cluster_id=plan.cluster_id,
            source_version=plan.source_kubernetes_version,
            expected_template=_mapping(_mapping(create_payload.get("spec")).get("template")),
            expected_filesystems_exact=True,
        )
        operation_entry["resource_uid"] = str(
            _mapping(created.get("metadata")).get("uid") or node_group_id
        )
        _provider_operation_terminal(
            checkpoint=checkpoint,
            resource_state=record,
            operation_entry=operation_entry,
            provider_payload=created,
            operation_kind="MK8s node-group create",
            resource_id=node_group_id,
            verified_postcondition={
                "cluster_id": plan.cluster_id,
                "name": name,
                "fixed_node_count": 1,
                "version": plan.source_kubernetes_version,
                "bridge_slot": record.get("slot"),
                "excluded_from_provider_upgrade": True,
                "node_group_id": node_group_id,
            },
            checkpoint_writer=checkpoint_writer,
        )
        record.update(
            {
                "id": node_group_id,
                "created": True,
                "bound_at": _utc_now(),
                "scheduling_failure_domain": {
                    "topology_key": "nebius.com/node-group-id",
                    "node_group_id": node_group_id,
                },
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        mutation_performed = True
        lines.append(f"Controller bridge node group: created {name} ({node_group_id}).")
    return mutation_performed, lines


def _controller_bridge_object_identity(resource: Mapping[str, Any]) -> dict[str, str]:
    metadata = _mapping(resource.get("metadata"))
    return {
        "api_version": str(resource.get("apiVersion", "") or "").strip(),
        "kind": str(resource.get("kind", "") or "").strip(),
        "namespace": str(metadata.get("namespace", "") or "").strip(),
        "name": str(metadata.get("name", "") or "").strip(),
        "uid": str(metadata.get("uid", "") or "").strip(),
        "resource_version": str(metadata.get("resourceVersion", "") or "").strip(),
    }


def _controller_bridge_resource_get_args(
    *,
    kube_context: str,
    kind: str,
    namespace: str,
    name: str,
) -> list[str]:
    normalized_kind = str(kind or "").strip()
    normalized_namespace = str(namespace or "").strip()
    normalized_name = str(name or "").strip()
    if not normalized_kind or not normalized_name:
        raise RuntimeError("Controller bridge resource identity is incomplete.")
    args = ["kubectl", "--context", kube_context]
    if normalized_kind not in {"Namespace", "PersistentVolume", "PriorityClass"}:
        if not normalized_namespace:
            raise RuntimeError(
                f"Controller bridge {normalized_kind}/{normalized_name} lacks a namespace."
            )
        args.extend(("-n", normalized_namespace))
    args.extend(("get", normalized_kind.lower(), normalized_name, "-o", "json"))
    return args


def _controller_bridge_live_resource(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    identity: Mapping[str, Any],
) -> tuple[bool, Mapping[str, Any]]:
    args = _controller_bridge_resource_get_args(
        kube_context=kube_context,
        kind=str(identity.get("kind", "") or ""),
        namespace=str(identity.get("namespace", "") or ""),
        name=str(identity.get("name", "") or ""),
    )
    result = command_runner(args, check=False, timeout_seconds=120)
    if result.returncode != 0:
        if _command_not_found(result):
            return False, {}
        raise RuntimeError(
            f"{_command_text(result.args)} failed: {result.stderr.strip() or result.stdout.strip()}"
        )
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"{_command_text(result.args)} returned invalid JSON: {exc}") from exc
    if not isinstance(payload, Mapping):
        raise RuntimeError(f"{_command_text(result.args)} returned a non-object JSON payload")
    return True, payload


def _controller_bridge_resource_journal_key(identity: Mapping[str, Any]) -> str:
    return "|".join(
        (
            str(identity.get("api_version", "") or ""),
            str(identity.get("kind", "") or ""),
            str(identity.get("namespace", "") or ""),
            str(identity.get("name", "") or ""),
            str(identity.get("uid", "") or ""),
        )
    )


def _controller_bridge_resource_fingerprint(
    resources: Sequence[Mapping[str, Any]],
    *,
    names: Sequence[str],
    data_keys: Sequence[str],
) -> str:
    expected_names = {str(item or "").strip() for item in names if str(item or "").strip()}
    expected_keys = {str(item or "").strip() for item in data_keys if str(item or "").strip()}
    material: list[dict[str, Any]] = []
    for resource in resources:
        identity = _controller_bridge_object_identity(resource)
        if identity["name"] not in expected_names:
            continue
        field_hashes = {
            str(key): hashlib.sha256(str(value or "").encode("utf-8")).hexdigest()
            for key, value in sorted(_mapping(resource.get("data")).items())
            if str(key) in expected_keys
        }
        if field_hashes:
            material.append({"identity": identity, "field_hashes": field_hashes})
    if not material:
        return ""
    stable = json.dumps(material, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(stable.encode("utf-8")).hexdigest()


def _controller_bridge_jwt_secret_material(
    resources: Sequence[Mapping[str, Any]],
    *,
    namespace: str,
    names: Sequence[str],
    data_keys: Sequence[str],
) -> tuple[str, list[dict[str, Any]]]:
    """Hash only selected JWT fields while binding their immutable Secret identities."""

    expected_namespace = str(namespace or "").strip()
    expected_names = {str(item or "").strip() for item in names if str(item or "").strip()}
    expected_keys = {str(item or "").strip() for item in data_keys if str(item or "").strip()}
    if not expected_namespace or not expected_names or not expected_keys:
        raise RuntimeError(
            "recovery-required: controller JWT material contract is missing its namespace, "
            "Secret names, or data keys."
        )

    material: list[dict[str, Any]] = []
    bindings: list[dict[str, Any]] = []
    observed_keys: set[str] = set()
    seen_names: set[str] = set()
    for resource in sorted(
        resources,
        key=lambda item: str(_mapping(item.get("metadata")).get("name", "") or ""),
    ):
        identity = _controller_bridge_object_identity(resource)
        if (
            identity["kind"] != "Secret"
            or identity["namespace"] != expected_namespace
            or identity["name"] not in expected_names
        ):
            continue
        if not identity["uid"] or identity["name"] in seen_names:
            raise RuntimeError(
                "recovery-required: controller JWT Secret identity is missing or duplicated."
            )
        data = _mapping(resource.get("data"))
        selected = {
            key: hashlib.sha256(str(data[key] or "").encode("utf-8")).hexdigest()
            for key in sorted(expected_keys & {str(item) for item in data})
        }
        if not selected:
            continue
        seen_names.add(identity["name"])
        observed_keys.update(selected)
        binding = {
            "namespace": identity["namespace"],
            "name": identity["name"],
            "uid": identity["uid"],
            "data_keys": sorted(selected),
        }
        bindings.append(binding)
        material.append({**binding, "field_hashes": selected})
    if not material or observed_keys != expected_keys:
        raise RuntimeError(
            "recovery-required: controller JWT Secret material is incomplete for the "
            "checkpointed data-key contract."
        )
    return _fingerprint(material), bindings


def _capture_controller_bridge_jwt_material_contract(
    *,
    journal: dict[str, Any],
    source: Mapping[str, Any],
    source_resources: Sequence[Mapping[str, Any]],
) -> None:
    jwt = _mapping(source.get("jwt"))
    names = tuple(sorted(str(item or "").strip() for item in jwt.get("object_names", []) or []))
    data_keys = tuple(sorted(str(item or "").strip() for item in jwt.get("data_keys", []) or []))
    expected_source_fingerprint = str(jwt.get("fingerprint", "") or "").strip()
    source_namespace = str(_mapping(source.get("slurmcluster")).get("namespace", "") or "")
    observed_source_fingerprint = _controller_bridge_resource_fingerprint(
        source_resources,
        names=names,
        data_keys=data_keys,
    )
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_source_fingerprint)
        or observed_source_fingerprint != expected_source_fingerprint
        or expected_source_fingerprint
        != str(_mapping(journal.get("source_binding")).get("jwt_fingerprint", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: source controller JWT identity or content changed after onboarding."
        )
    content_sha256, bindings = _controller_bridge_jwt_secret_material(
        source_resources,
        namespace=source_namespace,
        names=names,
        data_keys=data_keys,
    )
    contract = {
        "schema": CONTROLLER_BRIDGE_JWT_MATERIAL_CONTRACT_SCHEMA,
        "secret_names": sorted(item["name"] for item in bindings),
        "data_keys": sorted({key for item in bindings for key in item["data_keys"]}),
        "source_fingerprint": expected_source_fingerprint,
        "content_sha256": content_sha256,
        "source_secret_bindings": bindings,
        "captured_at": _utc_now(),
    }
    existing = _mapping(journal.get("jwt_material_contract"))
    if existing:
        comparable_existing = {
            key: value for key, value in existing.items() if key != "captured_at"
        }
        comparable_contract = {
            key: value for key, value in contract.items() if key != "captured_at"
        }
        if comparable_existing != comparable_contract:
            raise RuntimeError(
                "recovery-required: source controller JWT material contract changed after "
                "it was checkpointed."
            )
        contract["captured_at"] = str(existing.get("captured_at", "") or "")
    journal["jwt_material_contract"] = contract


def _controller_slurmctld_container(pod: Mapping[str, Any]) -> Mapping[str, Any]:
    containers = [
        item
        for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("containers"))
        if "slurmctld" in str(item.get("name", "") or "").lower()
    ]
    if len(containers) != 1:
        raise RuntimeError(
            "recovery-required: target controller JWT proof requires one exact slurmctld container."
        )
    return containers[0]


def _controller_jwt_key_path(slurm_config: str) -> str:
    """Resolve Slurm's active HS256 key path, including its documented fallback."""

    def _values(name: str) -> list[str]:
        return [
            value.strip()
            for value in re.findall(
                rf"(?im)^\s*{re.escape(name)}\s*=\s*([^#\r\n]+?)\s*$",
                slurm_config,
            )
        ]

    auth_types = _values("AuthAltTypes")
    if len(auth_types) != 1 or "auth/jwt" not in {
        item.strip() for item in auth_types[0].split(",")
    }:
        raise RuntimeError(
            "recovery-required: target Slurm configuration must enable AuthAltTypes=auth/jwt."
        )
    auth_parameters = _values("AuthAltParameters")
    if len(auth_parameters) > 1:
        raise RuntimeError(
            "recovery-required: target Slurm configuration has ambiguous AuthAltParameters."
        )
    parameters: dict[str, str] = {}
    if auth_parameters and auth_parameters[0].lower() not in {"(null)", "none"}:
        for raw_parameter in auth_parameters[0].split(","):
            key, separator, value = raw_parameter.strip().partition("=")
            if not separator or not key.strip() or key.strip() in parameters:
                raise RuntimeError(
                    "recovery-required: target Slurm AuthAltParameters cannot be parsed "
                    "unambiguously."
                )
            parameters[key.strip()] = value.strip()
    configured_path = parameters.get("jwt_key", "")
    if not configured_path:
        if parameters.get("jwks"):
            raise RuntimeError(
                "recovery-required: JWKS-only target configuration cannot prove HS256 token "
                "continuity."
            )
        state_paths = _values("StateSaveLocation")
        if len(state_paths) != 1:
            raise RuntimeError(
                "recovery-required: target Slurm JWT fallback requires one StateSaveLocation."
            )
        configured_path = str(PurePosixPath(state_paths[0]) / "jwt_hs256.key")
    path = PurePosixPath(configured_path)
    if not path.is_absolute() or ".." in path.parts or str(path) != configured_path:
        raise RuntimeError(
            "recovery-required: target Slurm jwt_key path must be one normalized absolute path."
        )
    return str(path)


def _controller_jwt_decoded_key_hashes(
    secrets: Sequence[Mapping[str, Any]],
    *,
    bindings: Sequence[Mapping[str, Any]],
) -> list[dict[str, str]]:
    """Return hash-only identities for the decoded source-bound Secret keys."""

    indexed = {
        (
            str(_mapping(item.get("metadata")).get("namespace", "") or ""),
            str(_mapping(item.get("metadata")).get("name", "") or ""),
            str(_mapping(item.get("metadata")).get("uid", "") or ""),
        ): item
        for item in secrets
    }
    candidates: list[dict[str, str]] = []
    for binding in bindings:
        identity = (
            str(binding.get("namespace", "") or ""),
            str(binding.get("name", "") or ""),
            str(binding.get("uid", "") or ""),
        )
        secret = indexed.get(identity)
        if secret is None:
            raise RuntimeError(
                "recovery-required: target JWT Secret identity changed before file proof."
            )
        data = _mapping(secret.get("data"))
        for key in binding.get("data_keys", []) or []:
            encoded = str(data.get(str(key), "") or "")
            try:
                decoded = base64.b64decode(encoded, validate=True)
            except (binascii.Error, ValueError) as exc:
                raise RuntimeError(
                    "recovery-required: target JWT Secret data is not valid Kubernetes "
                    "base64 content."
                ) from exc
            if not decoded:
                raise RuntimeError(
                    "recovery-required: target JWT Secret contains an empty selected key."
                )
            candidates.append(
                {
                    "namespace": identity[0],
                    "name": identity[1],
                    "uid": identity[2],
                    "data_key": str(key),
                    "sha256": hashlib.sha256(decoded).hexdigest(),
                }
            )
    return candidates


def _controller_slurmctld_jwt_wiring(
    pod: Mapping[str, Any],
    *,
    jwt_key_path: str,
) -> tuple[dict[str, Any], str]:
    """Bind the configured jwt_key path to its exact slurmctld volume wiring."""

    container = _controller_slurmctld_container(pod)
    matches: list[tuple[int, Mapping[str, Any], str]] = []
    for mount in _sequence_of_mappings(container.get("volumeMounts")):
        mount_path = str(mount.get("mountPath", "") or "").rstrip("/") or "/"
        prefix = mount_path if mount_path == "/" else f"{mount_path}/"
        if jwt_key_path.startswith(prefix) and jwt_key_path != mount_path:
            matches.append((len(mount_path), mount, jwt_key_path[len(prefix) :]))
    if not matches:
        raise RuntimeError(
            "recovery-required: target slurmctld configured jwt_key is outside its mounted volumes."
        )
    longest = max(item[0] for item in matches)
    selected = [item for item in matches if item[0] == longest]
    if len(selected) != 1:
        raise RuntimeError(
            "recovery-required: target slurmctld configured jwt_key has ambiguous volume wiring."
        )
    _length, mount, relative_path = selected[0]
    if str(mount.get("subPath", "") or "") or str(mount.get("subPathExpr", "") or ""):
        raise RuntimeError(
            "recovery-required: target slurmctld JWT key mounts cannot use subPath or subPathExpr."
        )
    volume_name = str(mount.get("name", "") or "")
    volumes = [
        item
        for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
        if str(item.get("name", "") or "") == volume_name
    ]
    if len(volumes) != 1:
        raise RuntimeError(
            "recovery-required: target slurmctld JWT key volume identity is missing or ambiguous."
        )
    volume = volumes[0]
    source = {
        key: copy.deepcopy(to_plain_data(value)) for key, value in volume.items() if key != "name"
    }
    wiring = {
        "container_name": str(container.get("name", "") or ""),
        "container_image": str(container.get("image", "") or ""),
        "volume_name": volume_name,
        "mount_path": str(mount.get("mountPath", "") or ""),
        "relative_path": relative_path,
        "read_only": mount.get("readOnly") is True,
        "volume_source": source,
    }
    return wiring, _fingerprint(wiring)


def _controller_slurmctld_jwt_secret_file(
    pod: Mapping[str, Any],
    *,
    bindings: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Resolve one exact checkpointed HS256 Secret key into slurmctld's filesystem."""

    expected = {
        (str(binding.get("name", "") or ""), str(key or "")): binding
        for binding in bindings
        for key in binding.get("data_keys", []) or []
    }
    if not expected:
        raise RuntimeError(
            "recovery-required: target controller JWT Secret-file contract is empty."
        )
    container = _controller_slurmctld_container(pod)
    volumes = {
        str(item.get("name", "") or ""): item
        for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
        if str(item.get("name", "") or "")
    }
    resolved: list[dict[str, Any]] = []

    def _relative_key_paths(
        source: Mapping[str, Any],
        *,
        secret_name: str,
    ) -> list[tuple[str, str]]:
        selected_keys = [key for name, key in expected if name == secret_name]
        if "items" not in source:
            return [(key, key) for key in selected_keys]
        result: list[tuple[str, str]] = []
        for item in _sequence_of_mappings(source.get("items")):
            key = str(item.get("key", "") or "")
            path = str(item.get("path", "") or "")
            if key in selected_keys:
                result.append((key, path))
        return result

    for mount in _sequence_of_mappings(container.get("volumeMounts")):
        if str(mount.get("subPath", "") or "") or str(mount.get("subPathExpr", "") or ""):
            continue
        volume_name = str(mount.get("name", "") or "")
        mount_path = str(mount.get("mountPath", "") or "")
        volume = _mapping(volumes.get(volume_name))
        sources: list[tuple[str, Mapping[str, Any]]] = []
        secret = _mapping(volume.get("secret"))
        if secret:
            sources.append((str(secret.get("secretName", "") or ""), secret))
        for projected_source in _sequence_of_mappings(
            _mapping(volume.get("projected")).get("sources")
        ):
            projected_secret = _mapping(projected_source.get("secret"))
            if projected_secret:
                sources.append((str(projected_secret.get("name", "") or ""), projected_secret))
        for secret_name, source in sources:
            for data_key, relative_path in _relative_key_paths(
                source,
                secret_name=secret_name,
            ):
                path = PurePosixPath(relative_path)
                if (
                    not relative_path
                    or path.is_absolute()
                    or ".." in path.parts
                    or str(path) != relative_path
                ):
                    raise RuntimeError(
                        "recovery-required: target JWT Secret item path is not normalized."
                    )
                binding = expected[(secret_name, data_key)]
                secret_file_path = str(PurePosixPath(mount_path) / path)
                wiring = {
                    "container_name": str(container.get("name", "") or ""),
                    "container_image": str(container.get("image", "") or ""),
                    "volume_name": volume_name,
                    "mount_path": mount_path,
                    "relative_path": relative_path,
                    "read_only": mount.get("readOnly") is True,
                    "secret_name": secret_name,
                    "secret_uid": str(binding.get("uid", "") or ""),
                    "data_key": data_key,
                    "volume_source": copy.deepcopy(to_plain_data(dict(source))),
                }
                resolved.append(
                    {
                        "jwt_secret_binding": {
                            "namespace": str(binding.get("namespace", "") or ""),
                            "name": secret_name,
                            "uid": str(binding.get("uid", "") or ""),
                        },
                        "jwt_data_key": data_key,
                        "jwt_secret_file_path": secret_file_path,
                        "source_wiring": wiring,
                        "source_wiring_sha256": _fingerprint(wiring),
                    }
                )
    if len(resolved) != 1:
        raise RuntimeError(
            "recovery-required: target slurmctld must mount exactly one checkpointed HS256 "
            "Secret key with explicit file wiring."
        )
    return resolved[0]


def _probe_target_controller_jwt_key(
    *,
    pod: Mapping[str, Any],
    jwt_key_path: str,
    jwt_secret_file_path: str,
    token_smoke: bool,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, Any]:
    """Hash the configured live key and optionally mint a token without disclosing it."""

    metadata = _mapping(pod.get("metadata"))
    pod_name = str(metadata.get("name", "") or "").strip()
    pod_uid = str(metadata.get("uid", "") or "").strip()
    container = _controller_slurmctld_container(pod)
    container_name = str(container.get("name", "") or "").strip()
    container_image = str(container.get("image", "") or "").strip()
    status = next(
        (
            item
            for item in _sequence_of_mappings(_mapping(pod.get("status")).get("containerStatuses"))
            if str(item.get("name", "") or "") == container_name
        ),
        {},
    )
    container_image_id = str(status.get("imageID", "") or "").strip()
    if (
        not pod_name
        or not pod_uid
        or not container_name
        or not container_image
        or not container_image_id
    ):
        raise RuntimeError(
            "recovery-required: target JWT live proof lacks immutable Pod or container image "
            "identity."
        )
    require_bind_mount = jwt_key_path != jwt_secret_file_path
    script = (
        'set -eu; key_path="$1"; secret_path="$2"; test -r "$secret_path"; '
        'secret_hash=$(sha256sum "$secret_path"); secret_hash=${secret_hash%% *}; '
    )
    if token_smoke:
        if require_bind_mount:
            script += (
                'awk -v target="$key_path" \'$5 == target { found=1 } '
                "END { exit(found ? 0 : 1) }' /proc/self/mountinfo; "
            )
        script += (
            'test -r "$key_path"; key_hash=$(sha256sum "$key_path"); '
            'key_hash=${key_hash%% *}; test "$key_hash" = "$secret_hash"; '
            "unset SLURM_JWT; "
            "jwt_token=$(scontrol token lifespan=60 2>/dev/null); "
            'case "$jwt_token" in SLURM_JWT=*) :;; *) exit 97;; esac; '
            "unset jwt_token; "
        )
    script += 'printf "%s\\n" "$secret_hash"'
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "-c",
            container_name,
            "--",
            "/bin/sh",
            "-ec",
            script,
            "cxcli-jwt-proof",
            jwt_key_path,
            jwt_secret_file_path,
        ],
        check=False,
        timeout_seconds=120,
    )
    live_hash = result.stdout.strip()
    if result.returncode != 0 or not re.fullmatch(r"[0-9a-f]{64}", live_hash):
        qualifier = " and token smoke" if token_smoke else ""
        raise RuntimeError(
            "recovery-required: target controller configured JWT key hash"
            f"{qualifier} failed without exposing key material."
        )
    observed_at = _utc_now() if token_smoke else ""
    return {
        "controller_pod_uid": pod_uid,
        "controller_container_name": container_name,
        "controller_container_image": container_image,
        "controller_container_image_id": container_image_id,
        "live_key_sha256": live_hash,
        "token_smoke_passed": token_smoke,
        "token_smoke_observed_at": observed_at if token_smoke else "",
    }


def _ensure_target_controller_jwt_secret_material(
    *,
    journal: dict[str, Any],
    takeover: dict[str, Any],
    pod: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> bool:
    """Adopt the checkpointed HS256 key in the target-named Secret while gated."""

    contract = _mapping(journal.get("jwt_material_contract"))
    source_bindings = _sequence_of_mappings(contract.get("source_secret_bindings"))
    if len(source_bindings) != 1:
        raise RuntimeError(
            "recovery-required: target JWT handoff requires one exact source Secret binding."
        )
    source_binding = source_bindings[0]
    data_keys = tuple(str(item or "") for item in source_binding.get("data_keys", []) or [])
    if len(data_keys) != 1 or not data_keys[0]:
        raise RuntimeError(
            "recovery-required: target JWT handoff requires one exact source Secret data key."
        )
    data_key = data_keys[0]
    source_name = str(source_binding.get("name", "") or "")
    source_uid = str(source_binding.get("uid", "") or "")
    source_secret = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "secret",
            source_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    source_content_sha256, observed_source_bindings = _controller_bridge_jwt_secret_material(
        (source_secret,),
        namespace=_SOPERATOR_NAMESPACE,
        names=(source_name,),
        data_keys=(data_key,),
    )
    if observed_source_bindings != list(source_bindings) or source_content_sha256 != str(
        contract.get("content_sha256", "") or ""
    ):
        raise RuntimeError(
            "recovery-required: source JWT material changed before target Secret handoff."
        )
    source_encoded = str(_mapping(source_secret.get("data")).get(data_key, "") or "")
    try:
        source_decoded = base64.b64decode(source_encoded, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise RuntimeError(
            "recovery-required: source JWT material is not valid Kubernetes base64 content."
        ) from exc
    if not source_uid or not source_decoded:
        raise RuntimeError(
            "recovery-required: source JWT material lacks its immutable identity or key."
        )
    source_key_sha256 = hashlib.sha256(source_decoded).hexdigest()

    container = _controller_slurmctld_container(pod)
    if not _is_exact_target_controller_command_gate(container):
        raise RuntimeError(
            "recovery-required: target JWT Secret material may change only while the exact "
            "controller command gate is active."
        )
    volumes = {
        str(item.get("name", "") or ""): item
        for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
        if str(item.get("name", "") or "")
    }
    candidates: list[str] = []
    for mount in _sequence_of_mappings(container.get("volumeMounts")):
        uses_subpath = str(mount.get("subPath", "") or "") or str(
            mount.get("subPathExpr", "") or ""
        )
        volume = _mapping(volumes.get(str(mount.get("name", "") or "")))
        sources: list[Mapping[str, Any]] = []
        direct_secret = _mapping(volume.get("secret"))
        if direct_secret:
            sources.append(direct_secret)
        for projected_source in _sequence_of_mappings(
            _mapping(volume.get("projected")).get("sources")
        ):
            projected_secret = _mapping(projected_source.get("secret"))
            if projected_secret:
                sources.append(projected_secret)
        for source in sources:
            target_name = str(source.get("secretName", "") or source.get("name", "") or "")
            items = _sequence_of_mappings(source.get("items"))
            exposes_key = (
                any(str(item.get("key", "") or "") == data_key for item in items)
                if "items" in source
                else True
            )
            if target_name and exposes_key:
                if uses_subpath:
                    raise RuntimeError(
                        "recovery-required: target slurmctld JWT key mounts cannot use "
                        "subPath or subPathExpr."
                    )
                candidates.append(target_name)
    if len(candidates) != 1:
        raise RuntimeError(
            "recovery-required: target slurmctld must mount exactly one Secret source for "
            "the checkpointed HS256 data key."
        )
    target_name = candidates[0]
    target_secret = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "secret",
            target_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    target_metadata = _mapping(target_secret.get("metadata"))
    target_uid = str(target_metadata.get("uid", "") or "")
    target_resource_version = str(target_metadata.get("resourceVersion", "") or "")
    if not target_uid or not target_resource_version:
        raise RuntimeError(
            "recovery-required: target JWT Secret lacks immutable UID or CAS resourceVersion."
        )
    handoff = takeover.setdefault("target_jwt_secret_handoff", {})
    if not isinstance(handoff, dict):
        raise RuntimeError("Target JWT Secret handoff journal must be mutable.")
    stable = {
        "source_secret_name": source_name,
        "source_secret_uid": source_uid,
        "target_secret_name": target_name,
        "target_secret_uid": target_uid,
        "data_key": data_key,
        "key_sha256": source_key_sha256,
    }
    for key, value in stable.items():
        recorded = str(handoff.get(key, "") or "")
        if recorded and recorded != value:
            raise RuntimeError(
                "recovery-required: target JWT Secret handoff binding changed after intent."
            )
    prior_handoff_status = str(handoff.get("status", "") or "")
    prior_verified = prior_handoff_status == "verified" or bool(
        str(handoff.get("verified_at", "") or "")
    )
    handoff.update(
        {
            "schema": "nebius-cxcli/target-jwt-secret-handoff-v1",
            **stable,
            "status": "verified" if prior_verified else "dispatching",
            "intent_at": str(handoff.get("intent_at", "") or _utc_now()),
        }
    )
    if checkpoint_writer is not None and not prior_verified:
        checkpoint_writer()
    patch_required = (
        str(_mapping(target_secret.get("data")).get(data_key, "") or "") != source_encoded
    )
    if patch_required:
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource=f"secret/{target_name}",
            patch={
                "metadata": {"resourceVersion": target_resource_version},
                "data": {data_key: source_encoded},
            },
            patch_via_stdin=True,
        )
    accepted_secret = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "secret",
            target_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    if (
        str(_mapping(accepted_secret.get("metadata")).get("uid", "") or "") != target_uid
        or str(_mapping(accepted_secret.get("data")).get(data_key, "") or "") != source_encoded
    ):
        raise SoperatorMigrationPhasePending(
            "target JWT Secret did not accept the checkpointed HS256 material exactly."
        )
    handoff.update({"status": "verified", "verified_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return patch_required or (
        prior_verified and not _mapping(takeover.get("jwt_material_preflight"))
    )


def _observe_target_controller_jwt_material(
    *,
    journal: Mapping[str, Any],
    pod: Mapping[str, Any],
    slurm_config: str,
    token_smoke: bool,
    allow_projection_wait: bool = False,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, Any]:
    contract = _mapping(journal.get("jwt_material_contract"))
    if contract.get("schema") != CONTROLLER_BRIDGE_JWT_MATERIAL_CONTRACT_SCHEMA:
        raise RuntimeError(
            "recovery-required: target singleton takeover lacks the checkpointed JWT "
            "material contract."
        )
    bindings = _sequence_of_mappings(contract.get("source_secret_bindings"))
    secret_names = tuple(str(item) for item in contract.get("secret_names", []) or [])
    secrets = tuple(
        _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "secret",
                name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        for name in secret_names
    )
    content_sha256, observed_bindings = _controller_bridge_jwt_secret_material(
        secrets,
        namespace=_SOPERATOR_NAMESPACE,
        names=secret_names,
        data_keys=tuple(str(item) for item in contract.get("data_keys", []) or []),
    )
    if observed_bindings != contract.get("source_secret_bindings") or content_sha256 != str(
        contract.get("content_sha256", "") or ""
    ):
        raise RuntimeError(
            "recovery-required: target singleton JWT Secret identity or content differs "
            "from the checkpointed source material."
        )
    takeover = _mapping(journal.get("target_singleton_takeover"))
    target_handoff = _mapping(takeover.get("target_jwt_secret_handoff"))
    if target_handoff.get("status") != "verified":
        raise RuntimeError(
            "recovery-required: target singleton JWT Secret material handoff is not verified."
        )
    target_binding = {
        "namespace": _SOPERATOR_NAMESPACE,
        "name": str(target_handoff.get("target_secret_name", "") or ""),
        "uid": str(target_handoff.get("target_secret_uid", "") or ""),
        "data_keys": [str(target_handoff.get("data_key", "") or "")],
    }
    target_secret = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "secret",
            target_binding["name"],
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    source_candidates = _controller_jwt_decoded_key_hashes(secrets, bindings=bindings)
    target_candidates = _controller_jwt_decoded_key_hashes(
        (target_secret,),
        bindings=(target_binding,),
    )
    if (
        len(source_candidates) != 1
        or len(target_candidates) != 1
        or source_candidates[0]["sha256"] != target_candidates[0]["sha256"]
        or target_candidates[0]["sha256"] != str(target_handoff.get("key_sha256", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: target JWT Secret differs from checkpointed source material."
        )
    jwt_key_path = _controller_jwt_key_path(slurm_config)
    _destination_wiring, destination_wiring_sha256 = _controller_slurmctld_jwt_wiring(
        pod,
        jwt_key_path=jwt_key_path,
    )
    secret_file = _controller_slurmctld_jwt_secret_file(
        pod,
        bindings=(target_binding,),
    )
    projection_deadline = time.monotonic() + 180
    while True:
        live_probe = _probe_target_controller_jwt_key(
            pod=pod,
            jwt_key_path=jwt_key_path,
            jwt_secret_file_path=str(secret_file["jwt_secret_file_path"]),
            token_smoke=token_smoke,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        if token_smoke or live_probe["live_key_sha256"] == target_candidates[0]["sha256"]:
            break
        if not allow_projection_wait:
            raise RuntimeError(
                "recovery-required: target mounted JWT Secret file differs from its exact "
                "checkpointed Secret key."
            )
        if time.monotonic() >= projection_deadline:
            raise SoperatorMigrationPhasePending(
                "target JWT Secret was accepted, but the exact gated controller Pod has not "
                "projected its checkpointed HS256 key."
            )
        time.sleep(5)
    matched = [
        item
        for item in target_candidates
        if {
            "namespace": item["namespace"],
            "name": item["name"],
            "uid": item["uid"],
        }
        == secret_file["jwt_secret_binding"]
        and item["data_key"] == secret_file["jwt_data_key"]
    ]
    if len(matched) != 1 or matched[0]["sha256"] != live_probe["live_key_sha256"]:
        raise RuntimeError(
            "recovery-required: target mounted JWT Secret file differs from its exact "
            "checkpointed Secret key."
        )
    wiring_sha256 = _fingerprint(
        {
            "source": secret_file["source_wiring_sha256"],
            "destination": destination_wiring_sha256,
        }
    )
    return {
        "source_fingerprint": str(contract.get("source_fingerprint", "") or ""),
        "content_sha256": content_sha256,
        "secret_bindings": observed_bindings,
        "jwt_key_path": jwt_key_path,
        "jwt_secret_binding": secret_file["jwt_secret_binding"],
        "jwt_data_key": secret_file["jwt_data_key"],
        "jwt_secret_file_path": secret_file["jwt_secret_file_path"],
        "source_wiring_sha256": secret_file["source_wiring_sha256"],
        "destination_wiring_sha256": destination_wiring_sha256,
        "wiring_sha256": wiring_sha256,
        **live_probe,
    }


def _preflight_target_singleton_jwt_material(
    *,
    journal: dict[str, Any],
    target_ref: str,
    slurm_config: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    stage = BridgeStage(str(journal.get("stage", "") or ""))
    authority = _mapping(journal.get("authority"))
    if stage is not BridgeStage.TARGET_HA_ACTIVE or authority.get("owner") != "bridge-target":
        raise RuntimeError(
            "recovery-required: target JWT preflight may be refreshed only while the "
            "target-version bridge is authoritative."
        )
    exists, workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="statefulset.apps.kruise.io/controller",
    )
    metadata = _mapping(workload.get("metadata"))
    workload_uid = str(metadata.get("uid", "") or "").strip()
    resource_version = str(metadata.get("resourceVersion", "") or "").strip()
    replicas = _resource_replicas(workload, default=-1)
    if not exists or not workload_uid or not resource_version or replicas != 1:
        raise SoperatorMigrationPhasePending(
            "target JWT preflight requires the exact gated controller workload at replicas=1 "
            "before bridge fencing."
        )
    pod_template_spec = _mapping(
        _mapping(_mapping(workload.get("spec")).get("template")).get("spec")
    )
    gated_containers = [
        item
        for item in _sequence_of_mappings(pod_template_spec.get("containers"))
        if "slurmctld" in str(item.get("name", "") or "").lower()
    ]
    if len(gated_containers) != 1 or not _is_exact_target_controller_command_gate(
        gated_containers[0]
    ):
        raise SoperatorMigrationPhasePending(
            "target JWT preflight requires the exact canonical controller command gate "
            "before bridge fencing."
        )
    pod_exists, pod = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="pod/controller-0",
    )
    pod_metadata = _mapping(pod.get("metadata"))
    pod_uid = str(pod_metadata.get("uid", "") or "").strip()
    owner_uids = {
        str(item.get("uid", "") or "")
        for item in _sequence_of_mappings(pod_metadata.get("ownerReferences"))
    }
    if not pod_exists or not pod_uid or owner_uids != {workload_uid}:
        raise SoperatorMigrationPhasePending(
            "target JWT preflight requires the exact gated controller-0 Pod owned by the "
            "checkpointed workload."
        )
    pod_container = _controller_slurmctld_container(pod)
    if not _is_exact_target_controller_command_gate(pod_container):
        raise SoperatorMigrationPhasePending(
            "target JWT preflight requires the live controller-0 Pod to retain the exact "
            "canonical command gate."
        )
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    allow_projection_wait = _ensure_target_controller_jwt_secret_material(
        journal=journal,
        takeover=takeover,
        pod=pod,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    observation = _observe_target_controller_jwt_material(
        journal=journal,
        pod=pod,
        slurm_config=slurm_config,
        token_smoke=False,
        allow_projection_wait=allow_projection_wait,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    recorded_target_ref = str(takeover.get("target_ref", "") or "")
    if recorded_target_ref and recorded_target_ref != target_ref:
        raise RuntimeError("recovery-required: target JWT preflight target changed on resume.")
    takeover["target_ref"] = target_ref
    existing = _mapping(takeover.get("jwt_material_preflight"))
    # A recreated Pod may report a platform-manifest imageID instead of the
    # gated Pod's local runtime imageID. The configured image remains stable
    # here; target startup separately enforces the locked platform digest.
    stable_fields = (
        "source_fingerprint",
        "content_sha256",
        "secret_bindings",
        "jwt_key_path",
        "jwt_secret_binding",
        "jwt_data_key",
        "jwt_secret_file_path",
        "source_wiring_sha256",
        "destination_wiring_sha256",
        "wiring_sha256",
        "live_key_sha256",
        "controller_container_name",
        "controller_container_image",
    )
    if existing and (
        existing.get("target_ref") != target_ref
        or existing.get("controller_workload_uid") != workload_uid
        or any(existing.get(field) != observation[field] for field in stable_fields)
    ):
        raise RuntimeError(
            "recovery-required: target JWT preflight binding changed before bridge fencing."
        )
    takeover["jwt_material_preflight"] = {
        "schema": CONTROLLER_BRIDGE_JWT_MATERIAL_PREFLIGHT_SCHEMA,
        "status": "verified",
        **observation,
        "target_ref": target_ref,
        "controller_workload_uid": workload_uid,
        "controller_workload_resource_version": resource_version,
        "verified_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()


def _revalidate_target_singleton_jwt_material(
    *,
    journal: dict[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    target_pod: Mapping[str, Any] | None = None,
) -> None:
    pod = (
        target_pod
        if target_pod is not None
        else _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "pod/controller-0",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
    )
    pod_uid = str(_mapping(pod.get("metadata")).get("uid", "") or "").strip()
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    checkpointed_pod_uid = str(takeover.get("controller_pod_uid", "") or "").strip()
    if not pod_uid or not checkpointed_pod_uid:
        raise RuntimeError(
            "recovery-required: target singleton JWT proof lacks its controller Pod identity."
        )
    successor = pod_uid != checkpointed_pod_uid
    workload_exists, workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="statefulset.apps.kruise.io/controller",
    )
    workload_uid = str(_mapping(workload.get("metadata")).get("uid", "") or "").strip()
    preflight = _mapping(takeover.get("jwt_material_preflight"))
    if (
        not workload_exists
        or _resource_replicas(workload, default=-1) != 1
        or not workload_uid
        or workload_uid != preflight.get("controller_workload_uid")
        or workload_uid != str(takeover.get("controller_workload_uid", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: target singleton JWT proof found a different controller "
            "workload identity."
        )
    pod_metadata = _mapping(pod.get("metadata"))
    pod_status = _mapping(pod.get("status"))
    pod_container = _controller_slurmctld_container(pod)
    container_name = str(pod_container.get("name", "") or "")
    container_status = next(
        (
            item
            for item in _sequence_of_mappings(pod_status.get("containerStatuses"))
            if str(item.get("name", "") or "") == container_name
        ),
        {},
    )
    existing = _mapping(takeover.get("jwt_material_proof"))
    if successor:
        accepted_image_digests = _locked_target_runtime_image_digests(journal)
        observed_image_digest = _runtime_image_digest(
            str(container_status.get("imageID", "") or "")
        )
        owner_uids = {
            str(item.get("uid", "") or "").strip()
            for item in _sequence_of_mappings(pod_metadata.get("ownerReferences"))
        }
        ready = any(
            str(item.get("type", "") or "") == "Ready"
            and str(item.get("status", "") or "") == "True"
            for item in _sequence_of_mappings(pod_status.get("conditions"))
        )
        if (
            existing.get("status") != "verified"
            or owner_uids != {workload_uid}
            or pod_metadata.get("deletionTimestamp")
            or str(pod_status.get("phase", "") or "") != "Running"
            or not ready
            or container_status.get("ready") is not True
            or _nonnegative_int(container_status.get("restartCount"), fallback=-1) != 0
            or str(pod_container.get("image", "") or "")
            != str(existing.get("controller_container_image", "") or "")
            or observed_image_digest not in accepted_image_digests
        ):
            raise RuntimeError(
                "recovery-required: replacement target controller Pod did not preserve the "
                "exact workload, readiness, restart, and immutable image contract."
            )
    config_result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            "controller-0",
            "-c",
            container_name,
            "--",
            "scontrol",
            "show",
            "config",
        ],
        check=False,
        timeout_seconds=120,
    )
    if config_result.returncode != 0:
        raise RuntimeError(
            "recovery-required: target singleton JWT proof could not read active Slurm "
            "configuration."
        )
    observation = _observe_target_controller_jwt_material(
        journal=journal,
        pod=pod,
        slurm_config=config_result.stdout,
        token_smoke=True,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    # Keep JWT material and the configured image stable across Pod recreation.
    # The startup path already validates the live target platform digest.
    stable_fields = (
        "source_fingerprint",
        "content_sha256",
        "secret_bindings",
        "jwt_key_path",
        "jwt_secret_binding",
        "jwt_data_key",
        "jwt_secret_file_path",
        "source_wiring_sha256",
        "destination_wiring_sha256",
        "wiring_sha256",
        "live_key_sha256",
        "controller_container_name",
        "controller_container_image",
    )
    if preflight.get("status") != "verified" or any(
        observation[field] != preflight.get(field) for field in stable_fields
    ):
        raise RuntimeError(
            "recovery-required: target singleton configured JWT key differs from its "
            "pre-fence path, content, or container proof."
        )
    authority = _mapping(journal.get("authority"))
    authority_epoch = str(authority.get("epoch", "") or "").strip()
    if authority.get("owner") != "target-singleton" or not authority_epoch:
        raise RuntimeError(
            "recovery-required: target singleton JWT proof requires target-singleton authority."
        )
    timestamp = str(observation.get("token_smoke_observed_at", "") or "")
    proof = {
        "schema": CONTROLLER_BRIDGE_JWT_MATERIAL_PROOF_SCHEMA,
        "status": "verified",
        **observation,
        "target_ref": target_ref,
        "controller_pod_uid": pod_uid,
        "controller_workload_uid": workload_uid,
        "authority_epoch": authority_epoch,
        "verified_at": timestamp,
        "revalidated_at": timestamp,
    }
    if existing:
        immutable_fields = {
            key: value
            for key, value in proof.items()
            if key
            not in {
                "verified_at",
                "revalidated_at",
                "token_smoke_observed_at",
            }
        }
        if successor:
            immutable_fields.pop("controller_pod_uid", None)
            # The runtime may report either member of the exact locked OCI
            # index/platform pair after a Pod recreation. The successor gate
            # above has already rejected every digest outside that set.
            immutable_fields.pop("controller_container_image_id", None)
        if any(existing.get(key) != value for key, value in immutable_fields.items()):
            raise RuntimeError(
                "recovery-required: target singleton JWT proof binding changed on resume."
            )
        proof["verified_at"] = str(existing.get("verified_at", "") or "")
    prior_proof = takeover.get("jwt_material_proof")
    prior_successors = takeover.get("controller_pod_successors")
    if successor:
        successors = list(_sequence_of_mappings(prior_successors))
        successors.append(
            {
                "schema": "nebius-cxcli-controller-pod-successor/v1",
                "prior_pod_uid": checkpointed_pod_uid,
                "successor_pod_uid": pod_uid,
                "controller_workload_uid": workload_uid,
                "node_name": str(_mapping(pod.get("spec")).get("nodeName", "") or ""),
                "controller_container_image_id": str(
                    observation.get("controller_container_image_id", "") or ""
                ),
                "jwt_revalidated_at": timestamp,
                "adopted_at": _utc_now(),
            }
        )
        takeover["controller_pod_successors"] = successors
        takeover["controller_pod_uid"] = pod_uid
    takeover["jwt_material_proof"] = proof
    if successor:
        try:
            _prove_replacement_target_singleton_adoption(
                journal=journal,
                target_ref=target_ref,
                pod_uid=pod_uid,
                workload_uid=workload_uid,
                slurm_config=config_result.stdout,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        except Exception:
            takeover["controller_pod_uid"] = checkpointed_pod_uid
            takeover["jwt_material_proof"] = prior_proof
            if prior_successors is None:
                takeover.pop("controller_pod_successors", None)
            else:
                takeover["controller_pod_successors"] = prior_successors
            raise
    if checkpoint_writer is not None:
        checkpoint_writer()


def _prove_replacement_target_singleton_adoption(
    *,
    journal: Mapping[str, Any],
    target_ref: str,
    pod_uid: str,
    workload_uid: str,
    slurm_config: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    """Prove a manager-created controller successor before canonical repair."""

    takeover = _mapping(journal.get("target_singleton_takeover"))
    expected_state = str(takeover.get("target_state_save_location", "") or "")
    observed_state = re.search(
        r"(?im)^\s*StateSaveLocation\s*=\s*(\S+)\s*$",
        slurm_config,
    )
    observed_cluster = re.search(r"(?im)^\s*ClusterName\s*=\s*(\S+)\s*$", slurm_config)
    if (
        not expected_state.startswith("/")
        or not observed_state
        or observed_state.group(1) != expected_state
        or not observed_cluster
        or observed_cluster.group(1) != target_ref
    ):
        raise SoperatorMigrationPhasePending(
            "replacement target singleton adoption requires the checkpointed cluster and "
            "shared state path."
        )
    _revalidate_controller_authority_lease(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _prove_cluster_wide_slurmctld_exclusivity(
        expected_pods=((_SOPERATOR_NAMESPACE, "controller-0", pod_uid),),
        expected_workload=(
            "statefulsets.apps.kruise.io",
            _SOPERATOR_NAMESPACE,
            "controller",
            workload_uid,
        ),
        expected_replicas=1,
        proof_label="replacement target singleton adoption",
        campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    ping = _kubectl_exec_slurm_controller(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "ping"),
        timeout_seconds=120,
    )
    if ping.returncode != 0 or not re.search(
        r"Slurmctld\(primary\).*\bis\s+UP\b",
        ping.stdout,
        re.IGNORECASE,
    ):
        raise SoperatorMigrationPhasePending(
            "replacement target singleton adoption did not prove the live Slurm primary."
        )


def _controller_bridge_material_fingerprint(
    resource: Mapping[str, Any],
) -> str:
    """Bind every API field that can alter mirrored controller material."""

    annotations = _mapping(_mapping(resource.get("metadata")).get("annotations"))
    material = {
        "data": copy.deepcopy(to_plain_data(_mapping(resource.get("data")))),
        "binaryData": copy.deepcopy(to_plain_data(_mapping(resource.get("binaryData")))),
        "type": copy.deepcopy(to_plain_data(resource.get("type"))),
        "immutable": copy.deepcopy(to_plain_data(resource.get("immutable"))),
        "source_uid": str(annotations.get(_CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION, "") or ""),
    }
    stable = json.dumps(
        material,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return hashlib.sha256(stable.encode("utf-8")).hexdigest()


def _controller_bridge_role_rules_fingerprint(role: Mapping[str, Any]) -> str:
    """Return an order-insensitive semantic hash for Kubernetes RBAC PolicyRules."""

    canonical_rules: list[dict[str, list[str]]] = []
    for rule in _sequence_of_mappings(role.get("rules")):
        canonical_rule: dict[str, list[str]] = {}
        for key, raw_values in sorted(rule.items(), key=lambda item: str(item[0])):
            if not isinstance(raw_values, Sequence) or isinstance(raw_values, (str, bytes)):
                raise RuntimeError(
                    "recovery-required: source controller Role contains a non-list "
                    f"PolicyRule field: {key}."
                )
            canonical_rule[str(key)] = sorted({str(value) for value in raw_values})
        canonical_rules.append(canonical_rule)
    canonical_rules.sort(key=lambda item: json.dumps(item, sort_keys=True, separators=(",", ":")))
    stable = json.dumps(canonical_rules, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(stable.encode("utf-8")).hexdigest()


_CONTROLLER_BRIDGE_ALLOWED_ROLE_ACCESS: Mapping[tuple[str, str], frozenset[str]] = {
    ("slurm.nebius.ai", "nodesets"): frozenset({"get", "list", "watch"}),
    ("slurm.nebius.ai", "nodesetpowerstates"): frozenset(
        {"get", "list", "watch", "create", "update", "patch"}
    ),
    ("slurm.nebius.ai", "nodesetpowerstates/status"): frozenset({"get", "list", "watch"}),
}


def _validate_controller_bridge_role_rules_allowlist(role: Mapping[str, Any]) -> None:
    """Reject source controller RBAC outside the bridge's exact power-manager contract."""

    rules = _sequence_of_mappings(role.get("rules"))
    if not rules:
        raise RuntimeError("controller-ha-bridge source controller Role has no rules.")
    for index, rule in enumerate(rules):
        if rule.get("nonResourceURLs") or rule.get("resourceNames"):
            raise RuntimeError(
                "controller-ha-bridge source controller Role rule "
                f"{index} uses unsupported resource-name or non-resource URL access."
            )
        api_groups = rule.get("apiGroups")
        resources = rule.get("resources")
        verbs = rule.get("verbs")
        if any(
            not isinstance(values, Sequence)
            or isinstance(values, (str, bytes, bytearray))
            or not values
            for values in (api_groups, resources, verbs)
        ):
            raise RuntimeError(
                f"controller-ha-bridge source controller Role rule {index} is incomplete."
            )
        normalized_verbs = {str(verb) for verb in verbs}
        for api_group in {str(value) for value in api_groups}:
            for resource in {str(value) for value in resources}:
                allowed_verbs = _CONTROLLER_BRIDGE_ALLOWED_ROLE_ACCESS.get((api_group, resource))
                if allowed_verbs is None or not normalized_verbs.issubset(allowed_verbs):
                    raise RuntimeError(
                        "controller-ha-bridge refuses source controller RBAC outside the "
                        "allowlisted NodeSet power-manager contract: "
                        f"rule={index} apiGroup={api_group or '<core>'} "
                        f"resource={resource} verbs={','.join(sorted(normalized_verbs))}."
                    )


def _revalidate_controller_bridge_source_material(
    *,
    source: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[dict[str, Any], tuple[dict[str, Any], ...]]:
    bindings = (
        ("slurmclusters.slurm.nebius.ai", _mapping(source.get("slurmcluster"))),
        ("statefulset.apps.kruise.io", _mapping(source.get("controller_workload"))),
        ("pod", _mapping(source.get("controller_pod"))),
        ("persistentvolumeclaim", _mapping(source.get("controller_pvc"))),
        ("persistentvolume", _mapping(source.get("controller_pv"))),
    )
    live_by_kind: dict[str, dict[str, Any]] = {}
    for resource, binding in bindings:
        name = str(binding.get("name", "") or "")
        namespace = str(binding.get("namespace", "") or "")
        args = ["kubectl", "--context", kube_context]
        if namespace:
            args.extend(["-n", namespace])
        args.extend(["get", resource, name, "-o", "json"])
        live = _json_from_command(command_runner, args, timeout_seconds=120)
        live_uid = str(_mapping(live.get("metadata")).get("uid", "") or "")
        if not live_uid or live_uid != str(binding.get("uid", "") or ""):
            raise RuntimeError(
                "recovery-required: controller bridge source identity changed for "
                f"{resource}/{name}."
            )
        live_by_kind[resource] = live

    pvc = live_by_kind["persistentvolumeclaim"]
    pv = live_by_kind["persistentvolume"]
    pvc_binding = _mapping(source.get("controller_pvc"))
    pv_binding = _mapping(source.get("controller_pv"))
    claim_ref = _mapping(_mapping(pv.get("spec")).get("claimRef"))
    if (
        str(_mapping(pvc.get("spec")).get("volumeName", "") or "")
        != str(pv_binding.get("name", "") or "")
        or str(claim_ref.get("name", "") or "") != str(pvc_binding.get("name", "") or "")
        or str(claim_ref.get("namespace", "") or "") != str(pvc_binding.get("namespace", "") or "")
        or (
            str(claim_ref.get("uid", "") or "")
            and str(claim_ref.get("uid", "") or "") != str(pvc_binding.get("uid", "") or "")
        )
    ):
        raise RuntimeError(
            "recovery-required: source controller PVC/PV claim binding changed after onboarding."
        )

    jail_pvc_binding = _mapping(source.get("jail_pvc"))
    jail_pv_binding = _mapping(source.get("jail_pv"))
    jail_pvc_name = str(jail_pvc_binding.get("name", "") or "")
    jail_pv_name = str(jail_pv_binding.get("name", "") or "")
    jail_pvc = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "persistentvolumeclaim",
            jail_pvc_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    jail_pv = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "persistentvolume",
            jail_pv_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    jail_claim_ref = _mapping(_mapping(jail_pv.get("spec")).get("claimRef"))
    jail_storage = _mapping(source.get("jail_storage"))
    jail_pvc_spec = _mapping(jail_pvc.get("spec"))
    jail_pv_spec = _mapping(jail_pv.get("spec"))
    live_jail_storage_class = str(
        jail_pvc_spec.get("storageClassName", "") or jail_pv_spec.get("storageClassName", "") or ""
    )
    live_jail_access_modes = sorted(
        str(item or "") for item in jail_pv_spec.get("accessModes", []) or [] if str(item or "")
    )
    expected_jail_access_modes = sorted(
        str(item or "") for item in jail_storage.get("access_modes", []) or [] if str(item or "")
    )
    if (
        str(_mapping(jail_pvc.get("metadata")).get("uid", "") or "")
        != str(jail_pvc_binding.get("uid", "") or "")
        or str(_mapping(jail_pv.get("metadata")).get("uid", "") or "")
        != str(jail_pv_binding.get("uid", "") or "")
        or str(_mapping(jail_pvc.get("spec")).get("volumeName", "") or "") != jail_pv_name
        or str(jail_claim_ref.get("namespace", "") or "") != _SOPERATOR_NAMESPACE
        or str(jail_claim_ref.get("name", "") or "") != jail_pvc_name
        or (
            str(jail_claim_ref.get("uid", "") or "")
            and str(jail_claim_ref.get("uid", "") or "")
            != str(jail_pvc_binding.get("uid", "") or "")
        )
        or str(_mapping(jail_pv_spec.get("local")).get("path", "") or "")
        != str(jail_storage.get("local_path", "") or "")
        or live_jail_storage_class != str(jail_storage.get("storage_class_name", "") or "")
        or str(_mapping(jail_pv_spec.get("capacity")).get("storage", "") or "")
        != str(jail_storage.get("storage_size", "") or "")
        or live_jail_access_modes != expected_jail_access_modes
        or str(jail_pv_spec.get("volumeMode", "") or "Filesystem")
        != str(jail_storage.get("volume_mode", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: source controller Jail PVC/PV identity, claim, or static "
            "SFS storage contract changed after onboarding."
        )

    config = _mapping(source.get("configuration"))
    munge = _mapping(source.get("munge"))
    jwt = _mapping(source.get("jwt"))
    config_maps = tuple(
        _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "configmap",
                str(name),
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        for name in config.get("config_map_names", []) or []
    )
    credential_names = tuple(
        sorted(
            {
                str(name)
                for section in (munge, jwt)
                for name in section.get("object_names", []) or []
                if str(name)
            }
        )
    )
    secrets = tuple(
        _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "secret",
                name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        for name in credential_names
    )
    comparisons = (
        (
            "configuration",
            config_maps,
            tuple(config.get("config_map_names", []) or []),
            tuple(config.get("data_keys", []) or []),
            str(config.get("fingerprint", "") or ""),
        ),
        (
            "MUNGE",
            secrets,
            credential_names,
            tuple(munge.get("data_keys", []) or []),
            str(munge.get("fingerprint", "") or ""),
        ),
        (
            "JWT",
            secrets,
            credential_names,
            tuple(jwt.get("data_keys", []) or []),
            str(jwt.get("fingerprint", "") or ""),
        ),
    )
    for label, resources, names, keys, expected in comparisons:
        observed = _controller_bridge_resource_fingerprint(
            resources,
            names=names,
            data_keys=keys,
        )
        if not expected or observed != expected:
            raise RuntimeError(
                "recovery-required: source controller "
                f"{label} identity or content changed after onboarding."
            )
    return live_by_kind["pod"], (*config_maps, *secrets)


def _controller_bridge_mirrored_objects(
    *,
    source: Mapping[str, Any],
    source_pod_spec: Mapping[str, Any],
    namespace: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[dict[str, Any], ...]:
    objects: list[dict[str, Any]] = []
    refs = tuple(
        (
            kind,
            tuple(
                str(name or "").strip()
                for name in raw_names or []
                if str(name or "").strip()
                # kube-root-ca.crt is Kubernetes-owned namespace material. It
                # may be present in source reports created before service-account
                # projections were excluded, but it must never be mirrored or
                # adopted by a bridge campaign.
                and not (kind == "configmap" and str(name or "").strip() == "kube-root-ca.crt")
            ),
        )
        for kind, raw_names in (
            ("configmap", _mapping(source.get("configuration")).get("config_map_names")),
            ("secret", _mapping(source.get("munge")).get("object_names")),
            ("secret", _mapping(source.get("jwt")).get("object_names")),
        )
    )
    seen: set[tuple[str, str]] = set()
    for kind, names in refs:
        for name in names:
            key = (kind, name)
            if key in seen:
                continue
            seen.add(key)
            live = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    kind,
                    name,
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
            metadata = _mapping(live.get("metadata"))
            mirrored: dict[str, Any] = {
                "apiVersion": str(live.get("apiVersion", "v1") or "v1"),
                "kind": str(live.get("kind", "") or ""),
                "metadata": {
                    "namespace": namespace,
                    "name": name,
                    "labels": {
                        "app.kubernetes.io/managed-by": "nebius-cxcli",
                        CONTROLLER_BRIDGE_LABEL: "true",
                    },
                    "annotations": {
                        _CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION: str(
                            metadata.get("uid", "") or ""
                        ),
                        "nebius.ai/cxcli-source-resource-version": str(
                            metadata.get("resourceVersion", "") or ""
                        ),
                    },
                },
            }
            for field in ("data", "binaryData", "immutable", "type"):
                if field in live:
                    mirrored[field] = copy.deepcopy(to_plain_data(live[field]))
            objects.append(mirrored)

    service_account_name = str(source_pod_spec.get("serviceAccountName", "") or "default")
    if service_account_name != "default":
        service_account = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "serviceaccount",
                service_account_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        objects.append(
            {
                "apiVersion": "v1",
                "kind": "ServiceAccount",
                "metadata": {
                    "namespace": namespace,
                    "name": service_account_name,
                    "labels": {
                        "app.kubernetes.io/managed-by": "nebius-cxcli",
                        CONTROLLER_BRIDGE_LABEL: "true",
                    },
                    "annotations": {
                        _CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION: str(
                            _mapping(service_account.get("metadata")).get("uid", "") or ""
                        )
                    },
                },
                # The mirrored Pod opts in only after cxcli proves one exact, allowlisted
                # source-namespace RoleBinding. Keep the ServiceAccount default fail-closed.
                "automountServiceAccountToken": False,
                "imagePullSecrets": copy.deepcopy(
                    to_plain_data(service_account.get("imagePullSecrets", []))
                ),
            }
        )
        pull_secret_names = {
            str(item.get("name", "") or "").strip()
            for item in (
                *_sequence_of_mappings(source_pod_spec.get("imagePullSecrets")),
                *_sequence_of_mappings(service_account.get("imagePullSecrets")),
            )
            if str(item.get("name", "") or "").strip()
        }
        for pull_secret_name in sorted(pull_secret_names):
            if ("secret", pull_secret_name) in seen:
                continue
            pull_secret = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    "secret",
                    pull_secret_name,
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
            objects.append(
                {
                    "apiVersion": "v1",
                    "kind": "Secret",
                    "metadata": {
                        "namespace": namespace,
                        "name": pull_secret_name,
                        "labels": {
                            "app.kubernetes.io/managed-by": "nebius-cxcli",
                            CONTROLLER_BRIDGE_LABEL: "true",
                        },
                        "annotations": {
                            _CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION: str(
                                _mapping(pull_secret.get("metadata")).get("uid", "") or ""
                            )
                        },
                    },
                    "type": str(pull_secret.get("type", "") or "Opaque"),
                    "data": copy.deepcopy(to_plain_data(_mapping(pull_secret.get("data")))),
                }
            )
        role_bindings = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "rolebindings.rbac.authorization.k8s.io",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        controller_role_refs = []
        for binding in _sequence_of_mappings(role_bindings.get("items")):
            subjects = _sequence_of_mappings(binding.get("subjects"))
            if not any(
                subject.get("kind") == "ServiceAccount"
                and subject.get("name") == service_account_name
                and str(subject.get("namespace") or _SOPERATOR_NAMESPACE) == _SOPERATOR_NAMESPACE
                for subject in subjects
            ):
                continue
            role_ref = _mapping(binding.get("roleRef"))
            if (
                role_ref.get("apiGroup") == "rbac.authorization.k8s.io"
                and role_ref.get("kind") == "Role"
                and "controller" in str(role_ref.get("name", "") or "").lower()
            ):
                controller_role_refs.append(dict(role_ref))
        if len(controller_role_refs) != 1:
            raise SoperatorMigrationPhasePending(
                "controller-ha-bridge requires exactly one source controller RoleBinding "
                "for the mirrored service account."
            )
        source_role_ref = controller_role_refs[0]
        source_role_name = str(source_role_ref.get("name", "") or "").strip()
        source_role = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "role.rbac.authorization.k8s.io",
                source_role_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        source_role_metadata = _mapping(source_role.get("metadata"))
        source_role_uid = str(source_role_metadata.get("uid", "") or "").strip()
        if (
            str(source_role.get("apiVersion", "") or "") != "rbac.authorization.k8s.io/v1"
            or str(source_role.get("kind", "") or "") != "Role"
            or str(source_role_metadata.get("namespace", "") or "") != _SOPERATOR_NAMESPACE
            or str(source_role_metadata.get("name", "") or "") != source_role_name
            or not source_role_uid
            or not _sequence_of_mappings(source_role.get("rules"))
        ):
            raise SoperatorMigrationPhasePending(
                "controller-ha-bridge source controller Role has no exact UID-bound "
                "non-empty rules contract."
            )
        source_role_rules_sha256 = _controller_bridge_role_rules_fingerprint(source_role)
        _validate_controller_bridge_role_rules_allowlist(source_role)
        objects.append(
            {
                "apiVersion": "rbac.authorization.k8s.io/v1",
                "kind": "RoleBinding",
                "metadata": {
                    "namespace": _SOPERATOR_NAMESPACE,
                    "name": "cxcli-controller-bridge-power-manager",
                    "labels": {
                        "app.kubernetes.io/managed-by": "nebius-cxcli",
                        CONTROLLER_BRIDGE_LABEL: "true",
                    },
                    "annotations": {
                        _CONTROLLER_BRIDGE_SOURCE_ROLE_UID_ANNOTATION: source_role_uid,
                        _CONTROLLER_BRIDGE_SOURCE_ROLE_RULES_ANNOTATION: (source_role_rules_sha256),
                    },
                },
                "roleRef": source_role_ref,
                "subjects": [
                    {
                        "kind": "ServiceAccount",
                        "name": service_account_name,
                        "namespace": namespace,
                    }
                ],
            }
        )
    return tuple(objects)


def _controller_bridge_source_role_binding_contract(
    *,
    resources: Sequence[Mapping[str, Any]],
    bridge_namespace: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, Any]:
    expected_role_bindings = tuple(
        resource for resource in resources if resource.get("kind") == "RoleBinding"
    )
    if len(expected_role_bindings) > 1:
        raise RuntimeError("Controller bridge substrate has ambiguous source RoleBindings.")
    if not expected_role_bindings:
        return {
            "schema": "nebius-cxcli-controller-bridge-source-role/v1",
            "required": False,
        }

    expected_binding = expected_role_bindings[0]
    expected_binding_metadata = _mapping(expected_binding.get("metadata"))
    expected_binding_annotations = _mapping(expected_binding_metadata.get("annotations"))
    expected_role_ref = _mapping(expected_binding.get("roleRef"))
    expected_subjects = _sequence_of_mappings(expected_binding.get("subjects"))
    if len(expected_subjects) != 1:
        raise RuntimeError(
            "Controller bridge source RoleBinding must bind one exact service account."
        )
    expected_subject = expected_subjects[0]
    if str(expected_subject.get("namespace", "") or "") != bridge_namespace:
        raise RuntimeError(
            "Controller bridge source RoleBinding subject namespace does not match the bridge."
        )
    live_binding = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "rolebinding.rbac.authorization.k8s.io",
            str(expected_binding_metadata.get("name", "") or ""),
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    live_binding_metadata = _mapping(live_binding.get("metadata"))
    return {
        "schema": "nebius-cxcli-controller-bridge-source-role/v1",
        "required": True,
        "binding": {
            "namespace": _SOPERATOR_NAMESPACE,
            "name": str(expected_binding_metadata.get("name", "") or ""),
            "uid": str(live_binding_metadata.get("uid", "") or ""),
            "role_ref": {
                "api_group": str(expected_role_ref.get("apiGroup", "") or ""),
                "kind": str(expected_role_ref.get("kind", "") or ""),
                "name": str(expected_role_ref.get("name", "") or ""),
            },
            "service_account": {
                "namespace": str(expected_subject.get("namespace", "") or ""),
                "name": str(expected_subject.get("name", "") or ""),
            },
        },
        "role": {
            "namespace": _SOPERATOR_NAMESPACE,
            "name": str(expected_role_ref.get("name", "") or ""),
            "uid": str(
                expected_binding_annotations.get(
                    _CONTROLLER_BRIDGE_SOURCE_ROLE_UID_ANNOTATION,
                    "",
                )
                or ""
            ),
            "rules_sha256": str(
                expected_binding_annotations.get(
                    _CONTROLLER_BRIDGE_SOURCE_ROLE_RULES_ANNOTATION,
                    "",
                )
                or ""
            ),
        },
    }


def _bind_and_preflight_controller_bridge_resource_ownership(
    *,
    resources: Sequence[dict[str, Any]],
    plan: BridgePlan,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    """Bind every bridge object to one campaign and reject resource takeover."""

    expected_annotations = {
        _CONTROLLER_BRIDGE_CAMPAIGN_ANNOTATION: plan.campaign_fingerprint,
        _CONTROLLER_BRIDGE_CLUSTER_ANNOTATION: plan.cluster_id,
    }
    for resource in resources:
        metadata = resource.setdefault("metadata", {})
        if not isinstance(metadata, dict):
            raise RuntimeError("Controller bridge resource metadata must be a mapping.")
        annotations = metadata.setdefault("annotations", {})
        if not isinstance(annotations, dict):
            raise RuntimeError("Controller bridge resource annotations must be a mapping.")
        annotations.update(expected_annotations)
        expected_identity = {
            "api_version": str(resource.get("apiVersion", "") or ""),
            "kind": str(resource.get("kind", "") or ""),
            "namespace": str(metadata.get("namespace", "") or ""),
            "name": str(metadata.get("name", "") or ""),
        }
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=expected_identity,
        )
        if not exists:
            continue
        live_metadata = _mapping(live.get("metadata"))
        live_labels = _mapping(live_metadata.get("labels"))
        live_annotations = _mapping(live_metadata.get("annotations"))
        if (
            live_labels.get("app.kubernetes.io/managed-by") != "nebius-cxcli"
            or live_labels.get(CONTROLLER_BRIDGE_LABEL) != "true"
            or any(
                live_annotations.get(key) != value for key, value in expected_annotations.items()
            )
        ):
            raise SoperatorMigrationPhasePending(
                "controller-ha-bridge refuses to adopt or overwrite pre-existing "
                f"{expected_identity['kind']}/{expected_identity['name']} outside the "
                "exact config-owned campaign. Remove the foreign resource or resume its "
                "own checkpoint."
            )


def _controller_security_resource_contract(resource: Mapping[str, Any]) -> dict[str, Any]:
    metadata = _mapping(resource.get("metadata"))
    contract: dict[str, Any] = {
        "apiVersion": str(resource.get("apiVersion", "") or ""),
        "kind": str(resource.get("kind", "") or ""),
        "metadata": {
            "name": str(metadata.get("name", "") or ""),
            "namespace": str(metadata.get("namespace", "") or ""),
            "labels": dict(_mapping(metadata.get("labels"))),
            "annotations": {
                str(key): str(value)
                for key, value in _mapping(metadata.get("annotations")).items()
                if key != "kubectl.kubernetes.io/last-applied-configuration"
            },
        },
    }
    if "spec" in resource:
        contract["spec"] = copy.deepcopy(to_plain_data(resource.get("spec")))
    return contract


def _controller_security_resources_sha256(resources: Sequence[Mapping[str, Any]]) -> str:
    contracts = sorted(
        (_controller_security_resource_contract(resource) for resource in resources),
        key=lambda item: (
            str(item.get("kind", "") or ""),
            str(_mapping(item.get("metadata")).get("namespace", "") or ""),
            str(_mapping(item.get("metadata")).get("name", "") or ""),
        ),
    )
    return _fingerprint(contracts)


def _controller_bridge_workload_security_sha256(statefulset: Mapping[str, Any]) -> str:
    pod_spec = _mapping(_mapping(_mapping(statefulset.get("spec")).get("template")).get("spec"))
    container_security = [
        {
            "field": field,
            "name": str(container.get("name", "") or ""),
            "securityContext": copy.deepcopy(
                to_plain_data(_mapping(container.get("securityContext")))
            ),
        }
        for field in ("initContainers", "containers", "ephemeralContainers")
        for container in _sequence_of_mappings(pod_spec.get(field))
    ]
    host_volumes = [
        {
            "name": str(volume.get("name", "") or ""),
            "hostPath": copy.deepcopy(to_plain_data(_mapping(volume.get("hostPath")))),
        }
        for volume in _sequence_of_mappings(pod_spec.get("volumes"))
        if "hostPath" in volume
    ]
    return _fingerprint(
        {
            "automountServiceAccountToken": pod_spec.get("automountServiceAccountToken", False),
            "serviceAccountName": str(pod_spec.get("serviceAccountName", "") or "default"),
            "hostNetwork": pod_spec.get("hostNetwork", False),
            "hostPID": pod_spec.get("hostPID", False),
            "hostIPC": pod_spec.get("hostIPC", False),
            "securityContext": copy.deepcopy(
                to_plain_data(_mapping(pod_spec.get("securityContext")))
            ),
            "containerSecurity": container_security,
            "hostVolumes": host_volumes,
        }
    )


def _seal_controller_security_contract(contract: dict[str, Any]) -> None:
    contract["semantic_sha256"] = _fingerprint(
        {key: value for key, value in contract.items() if key != "semantic_sha256"}
    )


def _live_controller_security_network_binding(
    *,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, Any]:
    soperator_namespace = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "namespace",
            _SOPERATOR_NAMESPACE,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    namespace_metadata = _mapping(soperator_namespace.get("metadata"))
    namespace_uid = str(namespace_metadata.get("uid", "") or "")
    if (
        str(namespace_metadata.get("name", "") or "") != _SOPERATOR_NAMESPACE
        or namespace_metadata.get("deletionTimestamp")
        or not namespace_uid
    ):
        raise RuntimeError(
            "recovery-required: controller security preflight requires the exact live "
            "Soperator namespace UID."
        )
    api_service = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            "default",
            "get",
            "service",
            "kubernetes",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    service_metadata = _mapping(api_service.get("metadata"))
    service_spec = _mapping(api_service.get("spec"))
    service_uid = str(service_metadata.get("uid", "") or "")
    addresses = tuple(
        str(value or "").strip()
        for value in (
            service_spec.get("clusterIPs")
            if isinstance(service_spec.get("clusterIPs"), Sequence)
            and not isinstance(service_spec.get("clusterIPs"), (str, bytes, bytearray))
            else (service_spec.get("clusterIP"),)
        )
        if str(value or "").strip() not in {"", "None"}
    )
    cidrs: list[str] = []
    for address in addresses:
        try:
            parsed = ipaddress.ip_address(address)
        except ValueError as exc:
            raise RuntimeError(
                "recovery-required: Kubernetes API Service has a non-IP ClusterIP."
            ) from exc
        if parsed.is_link_local or parsed.is_multicast or parsed.is_unspecified:
            raise RuntimeError(
                "recovery-required: Kubernetes API Service ClusterIP is unsafe for the "
                "bridge NetworkPolicy."
            )
        cidrs.append(f"{parsed}/{parsed.max_prefixlen}")
    if (
        str(service_metadata.get("namespace", "") or "") != "default"
        or str(service_metadata.get("name", "") or "") != "kubernetes"
        or service_metadata.get("deletionTimestamp")
        or not service_uid
        or not cidrs
    ):
        raise RuntimeError(
            "recovery-required: Kubernetes API Service identity or exact ClusterIP is missing."
        )
    return {
        "soperator_namespace": {"name": _SOPERATOR_NAMESPACE, "uid": namespace_uid},
        "kubernetes_api_service": {
            "namespace": "default",
            "name": "kubernetes",
            "uid": service_uid,
        },
        "kubernetes_api_cidrs": sorted(set(cidrs)),
    }


def _inspector_security_objects(
    *,
    campaign_fingerprint: str,
    cluster_id: str,
) -> tuple[dict[str, Any], ...]:
    return tuple(
        controller_inspector_namespace_objects(
            campaign_fingerprint=campaign_fingerprint,
            cluster_id=cluster_id,
        )
    )


def _preflight_controller_inspector_namespace(
    *,
    journal: dict[str, Any],
    plan: BridgePlan,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Prove hostPID inspector admission before any source-cluster mutation."""

    resources = list(
        _inspector_security_objects(
            campaign_fingerprint=plan.campaign_fingerprint,
            cluster_id=plan.cluster_id,
        )
    )
    _bind_and_preflight_controller_bridge_resource_ownership(
        resources=resources,
        plan=plan,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    existing_contract = _mapping(journal.get("security_contract"))
    if existing_contract:
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            require_bridge=False,
        )
    else:
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=resources,
            timeout_seconds=300,
        )

    live_resources: list[Mapping[str, Any]] = []
    resource_bindings: list[dict[str, str]] = []
    for desired in resources:
        desired_metadata = _mapping(desired.get("metadata"))
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity={
                "kind": str(desired.get("kind", "") or ""),
                "namespace": str(desired_metadata.get("namespace", "") or ""),
                "name": str(desired_metadata.get("name", "") or ""),
            },
        )
        live_metadata = _mapping(live.get("metadata"))
        if (
            not exists
            or not str(live_metadata.get("uid", "") or "")
            or not _desired_manifest_contract_matches(live, desired)
        ):
            raise RuntimeError(
                "recovery-required: dedicated controller inspector security resource did "
                f"not converge exactly: {desired.get('kind')}/{desired_metadata.get('name')}."
            )
        live_resources.append(live)
        resource_bindings.append(
            {
                "kind": str(desired.get("kind", "") or ""),
                "namespace": str(desired_metadata.get("namespace", "") or ""),
                "name": str(desired_metadata.get("name", "") or ""),
                "uid": str(live_metadata.get("uid", "") or ""),
                "semantic_sha256": _controller_security_resources_sha256((live,)),
            }
        )

    nodes_payload = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "nodes", "-o", "json"],
        timeout_seconds=120,
    )
    node_bindings = [
        _controller_runtime_node_identity(
            node,
            expected_name=str(_mapping(node.get("metadata")).get("name", "") or ""),
        )
        for node in _sequence_of_mappings(nodes_payload.get("items"))
    ]
    if not node_bindings:
        raise RuntimeError(
            "recovery-required: controller inspector admission preflight found no Nodes."
        )
    attempt_id = uuid4().hex
    dry_run_pods = tuple(
        controller_runtime_census_pod(
            campaign_fingerprint=plan.campaign_fingerprint,
            purpose="admission-preflight",
            attempt_id=attempt_id,
            image=_CONTROLLER_SPOOL_CLEANUP_IMAGE,
            target=ControllerRuntimeCensusTarget(**binding),
        )
        for binding in node_bindings
    )
    payload = {
        "apiVersion": "v1",
        "kind": "List",
        "items": [to_plain_data(item) for item in dry_run_pods],
    }
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "apply",
            "--server-side",
            "--dry-run=server",
            "--field-manager=nebius-cxcli-controller-inspector-preflight",
            "-f",
            "-",
        ],
        input_text=json.dumps(payload, sort_keys=True),
        timeout_seconds=300,
    )
    network_binding = _live_controller_security_network_binding(
        kube_context=kube_context,
        command_runner=command_runner,
    )
    inspector_namespace = next(item for item in live_resources if item.get("kind") == "Namespace")
    inspector_namespace_uid = str(
        _mapping(inspector_namespace.get("metadata")).get("uid", "") or ""
    )
    contract = dict(existing_contract) if existing_contract else {}
    contract.update(
        {
            "schema": "nebius-cxcli-controller-security/v1",
            **network_binding,
            "inspector": {
                "namespace": CONTROLLER_INSPECTOR_NAMESPACE,
                "namespace_uid": inspector_namespace_uid,
                "resources": resource_bindings,
                "resources_sha256": _controller_security_resources_sha256(live_resources),
                "admission_nodes": [
                    {
                        field: binding[field]
                        for field in ("node_name", "node_uid", "provider_id", "system_uuid")
                    }
                    for binding in sorted(node_bindings, key=lambda item: item["node_name"])
                ],
                "admission_nodes_sha256": _fingerprint(
                    [
                        {
                            field: binding[field]
                            for field in ("node_name", "node_uid", "provider_id", "system_uuid")
                        }
                        for binding in sorted(node_bindings, key=lambda item: item["node_name"])
                    ]
                ),
                "server_dry_run_at": _utc_now(),
            },
        }
    )
    _seal_controller_security_contract(contract)
    journal["security_contract"] = contract
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Controller inspector admission: dedicated privileged namespace, deny-all network "
        f"policy, and server dry-run passed on {len(node_bindings)} exact Node(s)."
    ]


def _controller_bridge_pod_spec_with_bridge_storage(
    *,
    pod_spec: Mapping[str, Any],
    source_state_pvc: str,
    source_jail_pvc: str,
) -> tuple[dict[str, Any], str]:
    """Retarget the exact source state/Jail mounts into the bridge namespace."""

    state_claim = str(source_state_pvc or "").strip()
    jail_claim = str(source_jail_pvc or "").strip()
    if not state_claim or not jail_claim or state_claim == jail_claim:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires distinct checkpointed controller-state and "
            "Jail PVC identities."
        )
    rewritten = copy.deepcopy(dict(pod_spec))
    volumes = _sequence_of_mappings(rewritten.get("volumes"))

    def _matching_volumes(claim_name: str) -> list[dict[str, Any]]:
        return [
            volume
            for volume in volumes
            if str(_mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or "")
            == claim_name
        ]

    state_volumes = _matching_volumes(state_claim)
    if len(state_volumes) != 1 or not str(state_volumes[0].get("name", "") or ""):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires exactly one source Pod volume bound to the "
            "checkpointed controller state PVC."
        )
    jail_volumes = _matching_volumes(jail_claim)
    if len(jail_volumes) != 1 or not str(jail_volumes[0].get("name", "") or ""):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires exactly one source Pod volume bound to the "
            "checkpointed Jail PVC."
        )
    other_pvcs = sorted(
        {
            claim_name
            for volume in volumes
            if (
                claim_name := str(
                    _mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or ""
                )
            )
            and claim_name not in {state_claim, jail_claim}
        }
    )
    if other_pvcs:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge cannot mirror cross-namespace source PVC references: "
            + ", ".join(other_pvcs)
            + ". Map these paths to bridge-node SFS/local volumes before retrying."
        )
    jail_volume_claim = jail_volumes[0].get("persistentVolumeClaim")
    if not isinstance(jail_volume_claim, dict):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge source Jail volume lost its PVC binding."
        )
    jail_volume_claim["claimName"] = CONTROLLER_BRIDGE_JAIL_PVC
    projected_service_account_volumes = {
        str(volume.get("name", "") or "")
        for volume in volumes
        if str(volume.get("name", "") or "").startswith("kube-api-access-")
    }
    rewritten["volumes"] = [
        volume
        for volume in volumes
        if str(volume.get("name", "") or "") not in projected_service_account_volumes
    ]
    for field in ("initContainers", "containers", "ephemeralContainers"):
        for container in _sequence_of_mappings(rewritten.get(field)):
            mounts = container.get("volumeMounts")
            if isinstance(mounts, list):
                container["volumeMounts"] = [
                    mount
                    for mount in mounts
                    if str(_mapping(mount).get("name", "") or "")
                    not in projected_service_account_volumes
                ]
    # The old controller is managed by OpenKruise and can carry readiness gates
    # whose conditions are produced only for that workload.  The bridge is a
    # native StatefulSet, so retaining those gates makes healthy bridge Pods
    # permanently unready.
    rewritten.pop("readinessGates", None)
    return rewritten, str(state_volumes[0]["name"])


def _create_controller_bridge_kubernetes_substrate(
    *,
    journal: dict[str, Any],
    plan: BridgePlan,
    source: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    pod_record = _mapping(source.get("controller_pod"))
    live_pod, _source_material = _revalidate_controller_bridge_source_material(
        source=source,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _capture_controller_bridge_jwt_material_contract(
        journal=journal,
        source=source,
        source_resources=_source_material,
    )
    live_metadata = _mapping(live_pod.get("metadata"))
    if str(live_metadata.get("uid", "") or "") != str(pod_record.get("uid", "") or ""):
        raise RuntimeError(
            "recovery-required: source controller Pod changed after onboarding bridge binding."
        )
    source_pvc = str(_mapping(source.get("controller_pvc")).get("name", "") or "")
    source_jail_pvc = str(_mapping(source.get("jail_pvc")).get("name", "") or "")
    pod_spec, state_volume_name = _controller_bridge_pod_spec_with_bridge_storage(
        pod_spec=_mapping(live_pod.get("spec")),
        source_state_pvc=source_pvc,
        source_jail_pvc=source_jail_pvc,
    )

    jail_storage = _mapping(source.get("jail_storage"))
    jail_access_modes = tuple(
        str(item or "") for item in jail_storage.get("access_modes", []) or []
    )
    if (
        str(jail_storage.get("filesystem_id", "") or "")
        != str(_mapping(plan.jail_attachment.get("existing_filesystem")).get("id", "") or "")
        or not str(jail_storage.get("local_path", "") or "").startswith("/")
        or not str(jail_storage.get("storage_class_name", "") or "")
        or not str(jail_storage.get("storage_size", "") or "")
        or "ReadWriteMany" not in jail_access_modes
        or str(jail_storage.get("volume_mode", "") or "") != "Filesystem"
    ):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge source Jail PVC/PV and immutable SFS attachment "
            "contract is incomplete or inconsistent."
        )
    containers = pod_spec.get("containers")
    if not isinstance(containers, list):
        raise SoperatorMigrationPhasePending("source controller Pod has no container list.")
    source_container_name = str(pod_record.get("container_name", "") or "")
    matched_container = False
    for container in containers:
        if isinstance(container, dict) and container.get("name") == source_container_name:
            container["image"] = plan.source_slurm_image
            matched_container = True
    if not matched_container:
        raise SoperatorMigrationPhasePending(
            "source controller container identity changed after onboarding."
        )
    mirrored_resources = list(
        _controller_bridge_mirrored_objects(
            source=source,
            source_pod_spec=pod_spec,
            namespace=plan.namespace,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    )
    pod_spec["automountServiceAccountToken"] = any(
        resource.get("kind") == "RoleBinding" for resource in mirrored_resources
    )
    security_contract = journal.get("security_contract")
    if not isinstance(security_contract, dict) or not security_contract:
        raise RuntimeError(
            "Controller bridge substrate requires the dedicated inspector admission and "
            "network security preflight before creation."
        )
    resources = list(
        bridge_kubernetes_objects(
            plan,
            controller_pod_spec=pod_spec,
            state_volume_name=state_volume_name,
            state_volume_claim_name=CONTROLLER_BRIDGE_STATE_PVC,
            state_storage_class="cxcli-controller-bridge-state",
            state_storage_size="20Gi",
            state_local_path="/mnt/controller-spool",
            state_node_match_expressions=(
                {
                    "key": "nebius.com/node-group-id",
                    "operator": "In",
                    "values": [
                        str(item.get("id", "") or "")
                        for item in _sequence_of_mappings(journal.get("node_groups"))
                    ],
                },
            ),
            jail_volume_claim_name=CONTROLLER_BRIDGE_JAIL_PVC,
            jail_storage_class=str(jail_storage["storage_class_name"]),
            jail_storage_size=str(jail_storage["storage_size"]),
            jail_local_path=str(jail_storage["local_path"]),
            jail_access_modes=jail_access_modes,
            jail_volume_mode=str(jail_storage["volume_mode"]),
            soperator_namespace=str(
                _mapping(security_contract.get("soperator_namespace")).get("name", "") or ""
            ),
            soperator_cluster_name=str(
                _mapping(journal.get("source_binding")).get("slurmcluster_name", "") or ""
            ),
            kubernetes_api_cidrs=tuple(
                str(item or "") for item in security_contract.get("kubernetes_api_cidrs", [])
            ),
            replicas=0,
        )
    )
    authority = _mapping(journal.get("authority"))
    resources.append(
        controller_authority_lease(
            namespace=plan.namespace,
            campaign_fingerprint=plan.campaign_fingerprint,
            cluster_id=plan.cluster_id,
            authority_epoch=str(authority.get("epoch", "") or ""),
            owner=str(authority.get("owner", "") or ""),
        )
    )
    resources[1:1] = mirrored_resources
    _bind_and_preflight_controller_bridge_resource_ownership(
        resources=resources,
        plan=plan,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _kubectl_apply_objects(
        command_runner=command_runner,
        kube_context=kube_context,
        objects=resources,
        timeout_seconds=300,
    )
    if all(domain.mount_policy == "cxcli-mount-daemonset" for domain in plan.placement_domains):
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "rollout",
                "status",
                "daemonset/cxcli-controller-bridge-mounts",
                "--timeout=10m",
            ],
            timeout_seconds=660,
        )
    mirrored_material: list[dict[str, str]] = []
    for resource in resources:
        kind = str(resource.get("kind", "") or "")
        if kind not in {"ConfigMap", "Secret"}:
            continue
        expected_metadata = _mapping(resource.get("metadata"))
        expected_annotations = _mapping(expected_metadata.get("annotations"))
        source_uid = str(
            expected_annotations.get(_CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION, "") or ""
        )
        if not source_uid:
            continue
        name = str(expected_metadata.get("name", "") or "")
        live = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "get",
                kind.lower(),
                name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        live_metadata = _mapping(live.get("metadata"))
        live_annotations = _mapping(live_metadata.get("annotations"))
        expected_material_fingerprint = _controller_bridge_material_fingerprint(resource)
        if (
            str(live_annotations.get(_CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION, "") or "")
            != source_uid
            or _controller_bridge_material_fingerprint(live) != expected_material_fingerprint
        ):
            raise RuntimeError(
                "recovery-required: mirrored controller material changed during bridge "
                f"substrate creation: {kind}/{name}."
            )
        mirrored_material.append(
            {
                "kind": kind,
                "name": name,
                "uid": str(live_metadata.get("uid", "") or ""),
                "source_uid": source_uid,
                "material_sha256": expected_material_fingerprint,
            }
        )
    journal["mirrored_material"] = mirrored_material
    journal["source_role_binding"] = _controller_bridge_source_role_binding_contract(
        resources=resources,
        bridge_namespace=plan.namespace,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _revalidate_controller_bridge_source_role_binding(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    journal["source_material_revalidated_at"] = _utc_now()
    kubernetes_resources: list[dict[str, str]] = []
    verified_live_by_identity: dict[tuple[str, str, str], Mapping[str, Any]] = {}
    for resource in resources:
        expected_metadata = _mapping(resource.get("metadata"))
        expected_identity = {
            "api_version": str(resource.get("apiVersion", "") or ""),
            "kind": str(resource.get("kind", "") or ""),
            "namespace": str(expected_metadata.get("namespace", "") or ""),
            "name": str(expected_metadata.get("name", "") or ""),
        }
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=expected_identity,
        )
        if not exists:
            raise RuntimeError(
                "Controller bridge substrate apply did not create "
                f"{expected_identity['kind']}/{expected_identity['name']}."
            )
        live_identity = _controller_bridge_object_identity(live)
        live_labels = _mapping(_mapping(live.get("metadata")).get("labels"))
        if (
            live_identity["api_version"] != expected_identity["api_version"]
            or live_identity["kind"] != expected_identity["kind"]
            or live_identity["namespace"] != expected_identity["namespace"]
            or live_identity["name"] != expected_identity["name"]
            or not live_identity["uid"]
            or not live_identity["resource_version"]
            or live_labels.get(CONTROLLER_BRIDGE_LABEL) != "true"
            or (
                expected_identity["kind"] in {"PersistentVolume", "PersistentVolumeClaim"}
                and not _desired_manifest_contract_matches(live, resource)
            )
        ):
            raise RuntimeError(
                "recovery-required: controller bridge substrate identity, ownership, or "
                "static storage contract is invalid for "
                f"{expected_identity['kind']}/{expected_identity['name']}."
            )
        kubernetes_resources.append(live_identity)
        verified_live_by_identity[
            (
                live_identity["kind"],
                live_identity["namespace"],
                live_identity["name"],
            )
        ] = live
    journal["kubernetes_resources"] = kubernetes_resources
    # The exact live objects above already passed identity, ownership, and
    # storage-contract validation. Reuse that linearizable observation for the
    # security snapshot instead of issuing a second serial GET for every bridge
    # resource.
    live_by_identity = verified_live_by_identity
    bridge_namespace = live_by_identity.get(("Namespace", "", plan.namespace))
    bridge_statefulset = live_by_identity.get(
        ("StatefulSet", plan.namespace, "cxcli-slurm-controller-bridge")
    )
    bridge_policies = [
        item
        for (kind, namespace, _name), item in live_by_identity.items()
        if kind == "NetworkPolicy" and namespace == plan.namespace
    ]
    if bridge_namespace is None or bridge_statefulset is None or len(bridge_policies) != 2:
        raise RuntimeError(
            "recovery-required: controller bridge security resources are incomplete after apply."
        )
    security_contract["bridge"] = {
        "namespace": plan.namespace,
        "namespace_uid": str(_mapping(bridge_namespace.get("metadata")).get("uid", "") or ""),
        "pod_security_enforce": str(
            _mapping(_mapping(bridge_namespace.get("metadata")).get("labels")).get(
                "pod-security.kubernetes.io/enforce", ""
            )
            or ""
        ),
        "namespace_semantic_sha256": _controller_security_resources_sha256((bridge_namespace,)),
        "network_policies": [
            {
                "name": str(_mapping(item.get("metadata")).get("name", "") or ""),
                "uid": str(_mapping(item.get("metadata")).get("uid", "") or ""),
                "semantic_sha256": _controller_security_resources_sha256((item,)),
            }
            for item in sorted(
                bridge_policies,
                key=lambda item: str(_mapping(item.get("metadata")).get("name", "") or ""),
            )
        ],
        "network_policies_sha256": _controller_security_resources_sha256(bridge_policies),
        "statefulset_uid": str(_mapping(bridge_statefulset.get("metadata")).get("uid", "") or ""),
        "workload_security_sha256": _controller_bridge_workload_security_sha256(bridge_statefulset),
    }
    _seal_controller_security_contract(security_contract)
    lease_exists, live_lease = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Lease",
            "namespace": plan.namespace,
            "name": CONTROLLER_AUTHORITY_LEASE,
        },
    )
    if not lease_exists:
        raise RuntimeError("Controller authority Lease disappeared during substrate creation.")
    try:
        journal["authority_lease"] = validate_controller_authority_lease(
            live_lease,
            namespace=plan.namespace,
            campaign_fingerprint=plan.campaign_fingerprint,
            cluster_id=plan.cluster_id,
            authority_epoch=str(authority.get("epoch", "") or ""),
            owner=str(authority.get("owner", "") or ""),
        )
    except ValueError as exc:
        raise RuntimeError(f"Controller authority Lease did not bind exactly: {exc}") from exc
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Controller bridge Kubernetes substrate: two-controller StatefulSet staged at "
        "replicas=0 with exact source image digest, shared state, and required anti-affinity; "
        "source mutation remains blocked pending the two-node shared-SFS canary."
    ]


def _revalidate_controller_bridge_mirrored_material(
    *,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    namespace = str(journal.get("namespace", "") or "")
    records = _sequence_of_mappings(journal.get("mirrored_material"))
    if not records:
        raise RuntimeError(
            "recovery-required: controller bridge has no immutable mirrored material binding."
        )
    for record in records:
        kind = str(record.get("kind", "") or "")
        name = str(record.get("name", "") or "")
        live = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                kind.lower(),
                name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        metadata = _mapping(live.get("metadata"))
        annotations = _mapping(metadata.get("annotations"))
        material_matches = _controller_bridge_material_fingerprint(live) == str(
            record.get("material_sha256", "") or ""
        )
        if not material_matches:
            material_matches = _controller_bridge_handoff_config_successor_matches(
                journal=journal,
                record=record,
                live=live,
            )
        if (
            str(metadata.get("uid", "") or "") != str(record.get("uid", "") or "")
            or str(annotations.get(_CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION, "") or "")
            != str(record.get("source_uid", "") or "")
            or not material_matches
        ):
            raise RuntimeError(
                "recovery-required: controller bridge mirrored material identity or content "
                f"changed: {kind}/{name}."
            )
    _revalidate_controller_bridge_source_role_binding(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )


def _controller_bridge_handoff_config_successor_matches(
    *,
    journal: Mapping[str, Any],
    record: Mapping[str, Any],
    live: Mapping[str, Any],
) -> bool:
    """Accept only the exact checkpointed bridge ConfigMap handoff successor."""

    if str(record.get("kind") or "") != "ConfigMap":
        return False
    stage = str(journal.get("stage") or "")
    takeover = _mapping(journal.get("target_singleton_takeover"))
    alignment = _mapping(takeover.get("bridge_handoff_configuration"))
    source_configuration = _mapping(journal.get("source_configuration"))
    bridge_copy = _mapping(_mapping(source_configuration.get("copies")).get("bridge"))
    metadata = _mapping(live.get("metadata"))
    live_data = copy.deepcopy(dict(_mapping(live.get("data"))))
    config_key = str(source_configuration.get("config_key") or "").strip()
    intended_slurm_conf = str(source_configuration.get("intended_slurm_conf") or "")
    live_config = str(live_data.get(config_key) or "")
    live_config_sha256 = hashlib.sha256(live_config.encode("utf-8")).hexdigest()
    handoff_sha256 = str(alignment.get("to_sha256") or "")
    handoff_successor = (
        stage == BridgeStage.TARGET_HA_ACTIVE.value
        and live_config_sha256 == handoff_sha256
        and live_config_sha256 == str(alignment.get("config_sha256") or "")
    )
    recovery_staging = _mapping(takeover.get("recovery_bridge_jailed_config"))
    recovery_observation = _mapping(takeover.get("recovery_jailed_config_preimage"))
    target_start = _mapping(takeover.get("target_start"))
    recovery_canaries = _sequence_of_mappings(recovery_observation.get("canaries"))
    observed_target_pod_uid = str(recovery_observation.get("target_start_pod_uid") or "")
    current_target_pod_uid = str(target_start.get("pod_uid") or "")
    current_target_node_name = str(target_start.get("node_name") or "")
    observed_target_is_historical = any(
        str(item.get("pod_uid") or "") == observed_target_pod_uid
        for item in _sequence_of_mappings(takeover.get("target_primary_takeover_history"))
    )
    current_target_was_stopped = any(
        str(item.get("pod_uid") or "") == current_target_pod_uid
        and str(item.get("node_name") or "") == current_target_node_name
        for item in _sequence_of_mappings(takeover.get("target_stop_pods"))
    )
    current_target_was_runtime_fenced = any(
        item.get("schema") == "nebius-cxcli-controller-runtime-fence/v1"
        and item.get("fenced") is True
        and str(item.get("node_name") or "") == current_target_node_name
        and int(item.get("slurmctld_count", -1)) == 0
        and int(item.get("writable_state_mount_count", -1)) == 0
        and int(item.get("unreadable_process_count", -1)) == 0
        and bool(str(item.get("verified_at") or ""))
        for item in _sequence_of_mappings(takeover.get("target_runtime_fence"))
    )
    recovery_target_attempt_is_bound = bool(current_target_pod_uid) and (
        current_target_pod_uid == observed_target_pod_uid
        or (
            bool(observed_target_pod_uid)
            and observed_target_is_historical
            and current_target_was_stopped
            and current_target_was_runtime_fenced
        )
    )
    recovery_successor = (
        stage == BridgeStage.BRIDGE_FENCED.value
        and recovery_staging.get("schema") == "nebius-cxcli/controller-bridge-jailed-config-v1"
        and recovery_staging.get("state") == "accepted"
        and str(recovery_staging.get("config_map_name") or "") == str(record.get("name") or "")
        and str(recovery_staging.get("config_key") or "") == config_key
        and str(recovery_staging.get("expected_preimage_sha256") or "") == handoff_sha256
        and str(recovery_staging.get("target_sha256") or "")
        == str(alignment.get("expected_bridge_only_sha256") or "")
        and live_config_sha256 == str(recovery_staging.get("target_sha256") or "")
        and recovery_observation.get("schema")
        == "nebius-cxcli/controller-bridge-jailed-config-observation-v1"
        and recovery_observation.get("proven_after_target_runtime_fence") is True
        and str(recovery_observation.get("sha256") or "") == handoff_sha256
        and len(recovery_canaries) == 2
        and all(str(item.get("sha256") or "") == handoff_sha256 for item in recovery_canaries)
        and target_start.get("state") == "accepted"
        and recovery_target_attempt_is_bound
    )
    if (
        alignment.get("schema") != "nebius-cxcli/target-bridge-handoff-configuration-v1"
        or alignment.get("status") != "verified"
        or str(alignment.get("config_map_name") or "") != str(record.get("name") or "")
        or str(alignment.get("config_map_uid") or "") != str(record.get("uid") or "")
        or str(metadata.get("uid") or "") != str(record.get("uid") or "")
        or str(bridge_copy.get("name") or "") != str(record.get("name") or "")
        or str(bridge_copy.get("uid") or "") != str(record.get("uid") or "")
        or not config_key
        or not intended_slurm_conf
        or not (handoff_successor or recovery_successor)
    ):
        return False

    # Reconstruct the exact accepted preimage. Matching both its full data hash
    # and material fingerprint proves that the handoff changed only slurm.conf;
    # every other data/binary/type/immutable/source-UID field remains bound.
    reconstructed = copy.deepcopy(dict(live))
    reconstructed_data = copy.deepcopy(live_data)
    reconstructed_data[config_key] = intended_slurm_conf
    reconstructed["data"] = reconstructed_data
    return _controller_bridge_config_map_data_sha256(reconstructed_data) == str(
        source_configuration.get("intended_config_data_sha256") or ""
    ) and _controller_bridge_material_fingerprint(reconstructed) == str(
        bridge_copy.get("intended_material_sha256") or ""
    )


def _revalidate_controller_bridge_source_role_binding(
    *,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    contract = _mapping(journal.get("source_role_binding"))
    if contract.get("schema") != "nebius-cxcli-controller-bridge-source-role/v1":
        raise RuntimeError(
            "recovery-required: controller bridge source Role contract is missing or invalid."
        )
    required = contract.get("required")
    if required is False:
        return
    if required is not True:
        raise RuntimeError(
            "recovery-required: controller bridge source Role requirement is ambiguous."
        )

    binding = _mapping(contract.get("binding"))
    role = _mapping(contract.get("role"))
    role_ref = _mapping(binding.get("role_ref"))
    service_account = _mapping(binding.get("service_account"))
    binding_namespace = str(binding.get("namespace", "") or "")
    binding_name = str(binding.get("name", "") or "")
    binding_uid = str(binding.get("uid", "") or "")
    role_namespace = str(role.get("namespace", "") or "")
    role_name = str(role.get("name", "") or "")
    role_uid = str(role.get("uid", "") or "")
    role_rules_sha256 = str(role.get("rules_sha256", "") or "")
    if (
        binding_namespace != _SOPERATOR_NAMESPACE
        or role_namespace != _SOPERATOR_NAMESPACE
        or not binding_name
        or not binding_uid
        or role_ref.get("api_group") != "rbac.authorization.k8s.io"
        or role_ref.get("kind") != "Role"
        or str(role_ref.get("name", "") or "") != role_name
        or not role_name
        or not role_uid
        or not re.fullmatch(r"[0-9a-f]{64}", role_rules_sha256)
        or str(service_account.get("namespace", "") or "")
        != str(journal.get("namespace", "") or "")
        or not str(service_account.get("name", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: controller bridge source Role journal binding is incomplete."
        )

    live_binding = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            binding_namespace,
            "get",
            "rolebinding.rbac.authorization.k8s.io",
            binding_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    live_binding_metadata = _mapping(live_binding.get("metadata"))
    live_binding_annotations = _mapping(live_binding_metadata.get("annotations"))
    live_role_ref = _mapping(live_binding.get("roleRef"))
    live_subjects = _sequence_of_mappings(live_binding.get("subjects"))
    expected_subject = {
        "kind": "ServiceAccount",
        "name": str(service_account.get("name", "") or ""),
        "namespace": str(service_account.get("namespace", "") or ""),
    }
    if (
        str(live_binding.get("apiVersion", "") or "") != "rbac.authorization.k8s.io/v1"
        or str(live_binding.get("kind", "") or "") != "RoleBinding"
        or str(live_binding_metadata.get("namespace", "") or "") != binding_namespace
        or str(live_binding_metadata.get("name", "") or "") != binding_name
        or str(live_binding_metadata.get("uid", "") or "") != binding_uid
        or {
            "api_group": str(live_role_ref.get("apiGroup", "") or ""),
            "kind": str(live_role_ref.get("kind", "") or ""),
            "name": str(live_role_ref.get("name", "") or ""),
        }
        != dict(role_ref)
        or len(live_subjects) != 1
        or {
            "kind": str(live_subjects[0].get("kind", "") or ""),
            "name": str(live_subjects[0].get("name", "") or ""),
            "namespace": str(live_subjects[0].get("namespace", "") or ""),
        }
        != expected_subject
        or str(
            live_binding_annotations.get(_CONTROLLER_BRIDGE_SOURCE_ROLE_UID_ANNOTATION, "") or ""
        )
        != role_uid
        or str(
            live_binding_annotations.get(
                _CONTROLLER_BRIDGE_SOURCE_ROLE_RULES_ANNOTATION,
                "",
            )
            or ""
        )
        != role_rules_sha256
    ):
        raise RuntimeError(
            "recovery-required: controller bridge source RoleBinding identity or target changed."
        )

    live_role = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            role_namespace,
            "get",
            "role.rbac.authorization.k8s.io",
            role_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    live_role_metadata = _mapping(live_role.get("metadata"))
    if (
        str(live_role.get("apiVersion", "") or "") != "rbac.authorization.k8s.io/v1"
        or str(live_role.get("kind", "") or "") != "Role"
        or str(live_role_metadata.get("namespace", "") or "") != role_namespace
        or str(live_role_metadata.get("name", "") or "") != role_name
        or str(live_role_metadata.get("uid", "") or "") != role_uid
        or not _sequence_of_mappings(live_role.get("rules"))
        or _controller_bridge_role_rules_fingerprint(live_role) != role_rules_sha256
    ):
        raise RuntimeError(
            "recovery-required: source controller Role identity or rules changed before "
            "controller writer activation."
        )


def _controller_bridge_recoverable_target_network_peer_name(
    journal: Mapping[str, Any],
) -> str:
    network_peer = _mapping(journal.get("target_network_peer"))
    if network_peer:
        return ""
    transition = _mapping(journal.get("version_transition"))
    marker = _mapping(transition.get("target_cluster_name_marker"))
    binding_recovery = _mapping(transition.get("target_config_binding_recovery"))
    source_cluster_name = str(transition.get("source_cluster_name") or "").strip()
    target_cluster_name = str(transition.get("target_cluster_name") or "").strip()
    if (
        journal.get("stage") == "target-ha-active"
        and transition.get("cluster_name_change") is True
        and source_cluster_name
        and target_cluster_name
        and source_cluster_name != target_cluster_name
        and marker.get("state") == "accepted"
        and str(marker.get("source_cluster_name") or "").strip() == source_cluster_name
        and str(marker.get("target_cluster_name") or "").strip() == target_cluster_name
        and binding_recovery.get("status") == "verified"
    ):
        return target_cluster_name
    return ""


def _revalidate_controller_bridge_security_contract(
    *,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    require_bridge: bool = True,
) -> None:
    """Fail closed when inspector, PSA, NetworkPolicy, API, or Pod security drifts."""

    contract = _mapping(journal.get("security_contract"))
    recorded_sha256 = str(contract.get("semantic_sha256", "") or "")
    if (
        contract.get("schema") != "nebius-cxcli-controller-security/v1"
        or not re.fullmatch(r"[0-9a-f]{64}", recorded_sha256)
        or _fingerprint({key: value for key, value in contract.items() if key != "semantic_sha256"})
        != recorded_sha256
    ):
        raise RuntimeError(
            "recovery-required: controller bridge security contract is absent or changed."
        )
    live_network = _live_controller_security_network_binding(
        kube_context=kube_context,
        command_runner=command_runner,
    )
    for field in (
        "soperator_namespace",
        "kubernetes_api_service",
        "kubernetes_api_cidrs",
    ):
        if to_plain_data(live_network[field]) != to_plain_data(contract.get(field)):
            raise RuntimeError(
                "recovery-required: controller bridge exact Soperator namespace or "
                "Kubernetes API network binding changed before writer activation."
            )

    inspector = _mapping(contract.get("inspector"))
    expected_inspector_resources = _inspector_security_objects(
        campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
        cluster_id=str(journal.get("cluster_id", "") or ""),
    )
    inspector_records = {
        (str(item.get("kind", "") or ""), str(item.get("name", "") or "")): item
        for item in _sequence_of_mappings(inspector.get("resources"))
    }
    live_inspector_resources: list[Mapping[str, Any]] = []
    for desired in expected_inspector_resources:
        desired_metadata = _mapping(desired.get("metadata"))
        key = (
            str(desired.get("kind", "") or ""),
            str(desired_metadata.get("name", "") or ""),
        )
        record = _mapping(inspector_records.get(key))
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity={
                "kind": key[0],
                "namespace": str(desired_metadata.get("namespace", "") or ""),
                "name": key[1],
            },
        )
        live_metadata = _mapping(live.get("metadata"))
        if (
            not exists
            or str(live_metadata.get("uid", "") or "") != str(record.get("uid", "") or "")
            or not _desired_manifest_contract_matches(live, desired)
            or _controller_security_resources_sha256((live,))
            != str(record.get("semantic_sha256", "") or "")
        ):
            raise RuntimeError(
                "recovery-required: dedicated privileged inspector Namespace or deny-all "
                f"NetworkPolicy drifted: {key[0]}/{key[1]}."
            )
        live_inspector_resources.append(live)
    if _controller_security_resources_sha256(live_inspector_resources) != str(
        inspector.get("resources_sha256", "") or ""
    ) or str(
        _mapping(
            next(item for item in live_inspector_resources if item.get("kind") == "Namespace").get(
                "metadata"
            )
        ).get("uid", "")
        or ""
    ) != str(inspector.get("namespace_uid", "") or ""):
        raise RuntimeError(
            "recovery-required: dedicated controller inspector security fingerprint changed."
        )

    bridge = _mapping(contract.get("bridge"))
    if not bridge:
        if require_bridge:
            raise RuntimeError(
                "recovery-required: controller bridge security resources are not journaled."
            )
        return
    bridge_namespace_name = str(bridge.get("namespace", "") or "")
    exists, live_bridge_namespace = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Namespace",
            "namespace": "",
            "name": bridge_namespace_name,
        },
    )
    namespace_metadata = _mapping(live_bridge_namespace.get("metadata"))
    namespace_labels = _mapping(namespace_metadata.get("labels"))
    if (
        not exists
        or str(namespace_metadata.get("uid", "") or "")
        != str(bridge.get("namespace_uid", "") or "")
        or str(namespace_labels.get("pod-security.kubernetes.io/enforce", "") or "")
        != str(bridge.get("pod_security_enforce", "") or "")
        or _controller_security_resources_sha256((live_bridge_namespace,))
        != str(bridge.get("namespace_semantic_sha256", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: controller bridge Namespace identity or Pod Security labels drifted."
        )
    network_peer = _mapping(journal.get("target_network_peer"))
    additional_cluster_names = (
        tuple(str(item or "") for item in network_peer.get("cluster_names", []))
        if network_peer.get("status") == "verified"
        else ()
    )
    recovered_target_network_peer = ""
    if not additional_cluster_names:
        recovered_target_network_peer = _controller_bridge_recoverable_target_network_peer_name(
            journal
        )
        if recovered_target_network_peer:
            additional_cluster_names = (recovered_target_network_peer,)
    expected_policies = list(
        bridge_network_policy_objects(
            namespace=bridge_namespace_name,
            soperator_namespace=str(
                _mapping(contract.get("soperator_namespace")).get("name", "") or ""
            ),
            soperator_cluster_name=str(
                _mapping(journal.get("source_binding")).get("slurmcluster_name", "") or ""
            ),
            additional_soperator_cluster_names=additional_cluster_names,
            kubernetes_api_cidrs=tuple(
                str(item or "") for item in contract.get("kubernetes_api_cidrs", [])
            ),
        )
    )
    expected_annotations = {
        _CONTROLLER_BRIDGE_CAMPAIGN_ANNOTATION: str(journal.get("campaign_fingerprint", "") or ""),
        _CONTROLLER_BRIDGE_CLUSTER_ANNOTATION: str(journal.get("cluster_id", "") or ""),
    }
    for policy in expected_policies:
        metadata = policy.setdefault("metadata", {})
        if not isinstance(metadata, dict):  # pragma: no cover - static manifest
            raise AssertionError
        metadata["annotations"] = expected_annotations
    prior_policy_hashes: dict[str, str] = {}
    prior_policy_set_hash = ""
    if recovered_target_network_peer:
        prior_policies = list(
            bridge_network_policy_objects(
                namespace=bridge_namespace_name,
                soperator_namespace=str(
                    _mapping(contract.get("soperator_namespace")).get("name", "") or ""
                ),
                soperator_cluster_name=str(
                    _mapping(journal.get("source_binding")).get("slurmcluster_name", "") or ""
                ),
                kubernetes_api_cidrs=tuple(
                    str(item or "") for item in contract.get("kubernetes_api_cidrs", [])
                ),
            )
        )
        for policy in prior_policies:
            metadata = policy.setdefault("metadata", {})
            if not isinstance(metadata, dict):  # pragma: no cover - static manifest
                raise AssertionError
            metadata["annotations"] = expected_annotations
            prior_policy_hashes[str(metadata.get("name") or "")] = (
                _controller_security_resources_sha256((policy,))
            )
        prior_policy_set_hash = _controller_security_resources_sha256(prior_policies)
    policy_records = {
        str(item.get("name", "") or ""): item
        for item in _sequence_of_mappings(bridge.get("network_policies"))
    }
    live_policies: list[Mapping[str, Any]] = []
    required_policy_uid = ""
    for desired in expected_policies:
        desired_metadata = _mapping(desired.get("metadata"))
        name = str(desired_metadata.get("name", "") or "")
        record = _mapping(policy_records.get(name))
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity={
                "kind": "NetworkPolicy",
                "namespace": bridge_namespace_name,
                "name": name,
            },
        )
        live_semantic_sha256 = _controller_security_resources_sha256((live,))
        recorded_semantic_sha256 = str(record.get("semantic_sha256", "") or "")
        recoverable_hash_transition = bool(
            recovered_target_network_peer
            and name == "cxcli-controller-bridge-required-traffic"
            and recorded_semantic_sha256 == prior_policy_hashes.get(name)
            and live_semantic_sha256 == _controller_security_resources_sha256((desired,))
        )
        if (
            not exists
            or str(_mapping(live.get("metadata")).get("uid", "") or "")
            != str(record.get("uid", "") or "")
            or not _desired_manifest_contract_matches(live, desired)
            or (
                live_semantic_sha256 != recorded_semantic_sha256 and not recoverable_hash_transition
            )
        ):
            raise RuntimeError(
                "recovery-required: controller bridge NetworkPolicy identity or semantics "
                f"drifted: {name}."
            )
        live_policies.append(live)
        if name == "cxcli-controller-bridge-required-traffic":
            required_policy_uid = str(_mapping(live.get("metadata")).get("uid") or "").strip()
    live_policy_set_hash = _controller_security_resources_sha256(live_policies)
    recorded_policy_set_hash = str(bridge.get("network_policies_sha256", "") or "")
    if live_policy_set_hash != recorded_policy_set_hash and not (
        recovered_target_network_peer and recorded_policy_set_hash == prior_policy_set_hash
    ):
        raise RuntimeError(
            "recovery-required: controller bridge NetworkPolicy set fingerprint changed."
        )
    statefulset_exists, statefulset = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "StatefulSet",
            "namespace": bridge_namespace_name,
            "name": "cxcli-slurm-controller-bridge",
        },
    )
    if (
        not statefulset_exists
        or str(_mapping(statefulset.get("metadata")).get("uid", "") or "")
        != str(bridge.get("statefulset_uid", "") or "")
        or _controller_bridge_workload_security_sha256(statefulset)
        != str(bridge.get("workload_security_sha256", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: controller bridge workload security contract drifted."
        )
    if recovered_target_network_peer:
        required_policy_record = policy_records.get("cxcli-controller-bridge-required-traffic")
        if (
            not isinstance(journal, dict)
            or not isinstance(contract, dict)
            or not isinstance(bridge, dict)
            or not isinstance(required_policy_record, dict)
            or not required_policy_uid
        ):
            raise RuntimeError(
                "recovery-required: verified controller bridge target NetworkPolicy peer "
                "could not be restored to the mutable journal."
            )
        required_policy_record["semantic_sha256"] = next(
            _controller_security_resources_sha256((policy,))
            for policy in live_policies
            if str(_mapping(policy.get("metadata")).get("name") or "")
            == "cxcli-controller-bridge-required-traffic"
        )
        bridge["network_policies_sha256"] = live_policy_set_hash
        contract["semantic_sha256"] = _fingerprint(
            {key: value for key, value in contract.items() if key != "semantic_sha256"}
        )
        journal["target_network_peer"] = {
            "status": "verified",
            "cluster_names": [recovered_target_network_peer],
            "network_policy_uid": required_policy_uid,
            "verified_at": _utc_now(),
            "recovered_from_exact_live_policy": True,
        }


def _controller_runtime_node_identity(
    node: Mapping[str, Any],
    *,
    expected_name: str,
    expected_uid: str = "",
) -> dict[str, str]:
    metadata = _mapping(node.get("metadata"))
    spec = _mapping(node.get("spec"))
    node_info = _mapping(_mapping(node.get("status")).get("nodeInfo"))
    identity = {
        "node_name": str(metadata.get("name", "") or ""),
        "node_uid": str(metadata.get("uid", "") or ""),
        "node_resource_version": str(metadata.get("resourceVersion", "") or ""),
        "provider_id": str(spec.get("providerID", "") or ""),
        "system_uuid": str(node_info.get("systemUUID", "") or ""),
    }
    if (
        metadata.get("deletionTimestamp")
        or identity["node_name"] != expected_name
        or (expected_uid and identity["node_uid"] != expected_uid)
        or any(not value for value in identity.values())
    ):
        raise RuntimeError(
            "recovery-required: controller runtime proof requires an exact non-deleting "
            f"Node UID/resourceVersion/provider identity for {expected_name}."
        )
    return identity


def _controller_runtime_node_identity_sha256(identity: Mapping[str, Any]) -> str:
    return hashlib.sha256(
        "\0".join(
            str(identity.get(field, "") or "")
            for field in ("node_uid", "provider_id", "system_uuid")
        ).encode("utf-8")
    ).hexdigest()


def _revalidate_controller_runtime_census_nodes(
    *,
    node_census: Sequence[Mapping[str, Any]],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[dict[str, str]]:
    if not node_census:
        raise RuntimeError(
            "recovery-required: controller authority mutation requires a fresh all-node "
            "runtime census."
        )
    recorded_by_name: dict[str, Mapping[str, Any]] = {}
    for binding in node_census:
        node_name = str(binding.get("node_name", "") or "")
        if not node_name or node_name in recorded_by_name:
            raise RuntimeError(
                "recovery-required: controller runtime census has incomplete or duplicate "
                "Node bindings."
            )
        recorded_by_name[node_name] = binding
    live_payload = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "nodes", "-o", "json"],
        timeout_seconds=120,
    )
    live_nodes = _sequence_of_mappings(live_payload.get("items"))
    live_by_name = {
        str(_mapping(node.get("metadata")).get("name", "") or ""): node for node in live_nodes
    }
    if (
        len(live_by_name) != len(live_nodes)
        or not live_by_name
        or set(live_by_name) != set(recorded_by_name)
    ):
        raise RuntimeError(
            "recovery-required: Kubernetes Node membership changed after the all-node "
            "controller census; rerun the entire census before authority mutation."
        )
    observed: list[dict[str, str]] = []
    for node_name in sorted(recorded_by_name):
        binding = recorded_by_name[node_name]
        try:
            current = _controller_runtime_node_identity(
                live_by_name[node_name],
                expected_name=node_name,
                expected_uid=str(binding.get("node_uid", "") or ""),
            )
        except RuntimeError as exc:
            raise RuntimeError(
                "recovery-required: controller runtime census Node/provider identity changed "
                f"before authority mutation: {node_name}."
            ) from exc
        if any(
            current[field] != str(binding.get(field, "") or "")
            for field in ("node_uid", "provider_id", "system_uuid")
        ):
            raise RuntimeError(
                "recovery-required: controller runtime census Node/provider identity changed "
                f"before authority mutation: {node_name}."
            )
        observed.append(current)
    return observed


def _revalidate_controller_runtime_fence_nodes(
    *,
    node_fence: Sequence[Mapping[str, Any]],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[dict[str, str]]:
    """Revalidate every exact fence target without claiming full membership."""

    if not node_fence:
        raise RuntimeError("recovery-required: controller runtime fence has no Node identities.")
    recorded_by_name: dict[str, Mapping[str, Any]] = {}
    for binding in node_fence:
        node_name = str(binding.get("node_name", "") or "")
        if not node_name or node_name in recorded_by_name:
            raise RuntimeError(
                "recovery-required: controller runtime fence has incomplete or duplicate "
                "Node bindings."
            )
        recorded_by_name[node_name] = binding
    live_payload = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "nodes", "-o", "json"],
        timeout_seconds=120,
    )
    live_nodes = _sequence_of_mappings(live_payload.get("items"))
    live_by_name = {
        str(_mapping(node.get("metadata")).get("name", "") or ""): node for node in live_nodes
    }
    if len(live_by_name) != len(live_nodes) or not live_by_name:
        raise RuntimeError(
            "recovery-required: Kubernetes Node inventory is empty or ambiguous during "
            "controller runtime-fence revalidation."
        )
    observed: list[dict[str, str]] = []
    for node_name in sorted(recorded_by_name):
        binding = recorded_by_name[node_name]
        recorded_identity_sha256 = str(binding.get("node_identity_sha256", "") or "")
        if not re.fullmatch(r"[0-9a-f]{64}", recorded_identity_sha256):
            raise RuntimeError(
                "recovery-required: controller runtime-fence Node identity digest is "
                f"missing for {node_name}."
            )
        node = live_by_name.get(node_name)
        if node is None:
            raise RuntimeError(
                "recovery-required: controller runtime-fence Node disappeared before "
                f"authority mutation: {node_name}."
            )
        try:
            current = _controller_runtime_node_identity(
                node,
                expected_name=node_name,
                expected_uid=str(binding.get("node_uid", "") or ""),
            )
        except RuntimeError as exc:
            raise RuntimeError(
                "recovery-required: controller runtime-fence Node/provider identity changed "
                f"before authority mutation: {node_name}."
            ) from exc
        if _controller_runtime_node_identity_sha256(current) != recorded_identity_sha256:
            raise RuntimeError(
                "recovery-required: controller runtime-fence Node/provider identity changed "
                f"before authority mutation: {node_name}."
            )
        observed.append(current)
    return observed


def _transition_controller_authority_lease(
    *,
    journal: dict[str, Any],
    from_epoch: str,
    from_owner: str,
    to_epoch: str,
    to_owner: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    runtime_node_census: Sequence[Mapping[str, Any]],
) -> dict[str, str]:
    """CAS the cxcli authority Lease before enabling a new controller writer."""

    namespace = str(journal.get("namespace", "") or "")
    campaign = str(journal.get("campaign_fingerprint", "") or "")
    cluster_id = str(journal.get("cluster_id", "") or "")
    lease_exists, live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Lease",
            "namespace": namespace,
            "name": CONTROLLER_AUTHORITY_LEASE,
        },
    )
    if not lease_exists:
        raise RuntimeError("recovery-required: controller authority Lease disappeared.")
    metadata = _mapping(live.get("metadata"))
    spec = _mapping(live.get("spec"))
    observed_holder = str(spec.get("holderIdentity", "") or "")
    from_holder = f"{from_epoch}:{from_owner}"
    to_holder = f"{to_epoch}:{to_owner}"
    transitions = journal.setdefault("authority_lease_transitions", [])
    if not isinstance(transitions, list):
        raise RuntimeError("Controller authority Lease transitions must be a list.")
    transition = next(
        (
            item
            for item in transitions
            if isinstance(item, dict)
            and item.get("from_holder") == from_holder
            and item.get("to_holder") == to_holder
        ),
        None,
    )
    if transition is None:
        transition = {
            "from_holder": from_holder,
            "to_holder": to_holder,
            "state": "intent-recorded",
            "intent_at": _utc_now(),
        }
        transitions.append(transition)
        if checkpoint_writer is not None:
            checkpoint_writer()
    if observed_holder == to_holder:
        try:
            binding = validate_controller_authority_lease(
                live,
                namespace=namespace,
                campaign_fingerprint=campaign,
                cluster_id=cluster_id,
                authority_epoch=to_epoch,
                owner=to_owner,
            )
        except ValueError as exc:
            raise RuntimeError(
                f"recovery-required: accepted controller authority Lease drifted: {exc}"
            ) from exc
        transition.update(
            {
                "state": "accepted",
                "accepted_at": str(transition.get("accepted_at", "") or "") or _utc_now(),
                "accepted_by_live_reconciliation": True,
                **binding,
            }
        )
        journal["authority_lease"] = binding
        if checkpoint_writer is not None:
            checkpoint_writer()
        return binding
    if observed_holder != from_holder:
        raise RuntimeError(
            "recovery-required: controller authority Lease has an unexpected holder: "
            f"{observed_holder or '<missing>'}."
        )
    try:
        current_binding = validate_controller_authority_lease(
            live,
            namespace=namespace,
            campaign_fingerprint=campaign,
            cluster_id=cluster_id,
            authority_epoch=from_epoch,
            owner=from_owner,
        )
    except ValueError as exc:
        raise RuntimeError(
            f"recovery-required: controller authority Lease drifted before CAS: {exc}"
        ) from exc
    transition.update(
        {
            "state": "dispatching",
            "dispatching_at": str(transition.get("dispatching_at", "") or "") or _utc_now(),
            "from_uid": current_binding["uid"],
            "from_resource_version": current_binding["resource_version"],
            "runtime_node_census": [
                {
                    "node_name": str(item.get("node_name", "") or ""),
                    "node_uid": str(item.get("node_uid", "") or ""),
                    "node_resource_version": str(item.get("node_resource_version", "") or ""),
                    "node_identity_sha256": _controller_runtime_node_identity_sha256(item),
                }
                for item in runtime_node_census
            ],
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    _revalidate_controller_bridge_security_contract(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    pre_cas_nodes = _revalidate_controller_runtime_census_nodes(
        node_census=runtime_node_census,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    transition["pre_cas_node_resource_versions"] = {
        item["node_name"]: item["node_resource_version"] for item in pre_cas_nodes
    }
    annotations = _mapping(metadata.get("annotations"))
    epoch_annotation = "nebius.ai/cxcli-authority-epoch"
    patch = [
        {"op": "test", "path": "/metadata/uid", "value": current_binding["uid"]},
        {
            "op": "test",
            "path": "/metadata/resourceVersion",
            "value": current_binding["resource_version"],
        },
        {
            "op": "test",
            "path": "/metadata/annotations/nebius.ai~1cxcli-authority-epoch",
            "value": str(annotations.get(epoch_annotation, "") or ""),
        },
        {"op": "test", "path": "/spec/holderIdentity", "value": from_holder},
        {
            "op": "replace",
            "path": "/metadata/annotations/nebius.ai~1cxcli-authority-epoch",
            "value": to_epoch,
        },
        {"op": "replace", "path": "/spec/holderIdentity", "value": to_holder},
    ]
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "patch",
            "lease",
            CONTROLLER_AUTHORITY_LEASE,
            "--type=json",
            "-p",
            json.dumps(patch, separators=(",", ":")),
        ],
        timeout_seconds=120,
    )
    lease_exists, updated = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Lease",
            "namespace": namespace,
            "name": CONTROLLER_AUTHORITY_LEASE,
        },
    )
    if not lease_exists:
        raise RuntimeError("recovery-required: controller authority Lease vanished after CAS.")
    try:
        binding = validate_controller_authority_lease(
            updated,
            namespace=namespace,
            campaign_fingerprint=campaign,
            cluster_id=cluster_id,
            authority_epoch=to_epoch,
            owner=to_owner,
        )
    except ValueError as exc:
        raise RuntimeError(
            f"recovery-required: controller authority Lease CAS did not converge: {exc}"
        ) from exc
    transition.update({"state": "accepted", "accepted_at": _utc_now(), **binding})
    journal["authority_lease"] = binding
    if checkpoint_writer is not None:
        checkpoint_writer()
    return binding


def _revalidate_controller_authority_lease(
    *,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    namespace = str(journal.get("namespace", "") or "")
    authority = _mapping(journal.get("authority"))
    exists, lease = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Lease",
            "namespace": namespace,
            "name": CONTROLLER_AUTHORITY_LEASE,
        },
    )
    if not exists:
        raise RuntimeError("recovery-required: controller authority Lease is absent.")
    try:
        binding = validate_controller_authority_lease(
            lease,
            namespace=namespace,
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            cluster_id=str(journal.get("cluster_id", "") or ""),
            authority_epoch=str(authority.get("epoch", "") or ""),
            owner=str(authority.get("owner", "") or ""),
        )
    except ValueError as exc:
        raise RuntimeError(f"recovery-required: controller authority Lease drifted: {exc}") from exc
    recorded = _mapping(journal.get("authority_lease"))
    if recorded and (
        binding.get("uid") != str(recorded.get("uid", "") or "")
        or int(binding.get("resource_version", "0"))
        < int(str(recorded.get("resource_version", "0") or "0"))
    ):
        raise RuntimeError(
            "recovery-required: controller authority Lease UID changed or resourceVersion regressed."
        )


def _prove_controller_runtime_fence(
    *,
    journal: dict[str, Any],
    boundary: str,
    targets: Sequence[ControllerFenceTarget],
    image: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    fresh_attempt: bool,
) -> list[dict[str, Any]]:
    """Prove host writers are absent; fresh attempts never reuse verified evidence."""

    if not targets:
        raise RuntimeError(f"Controller runtime fence {boundary} has no historical nodes.")
    proof_purpose = str(boundary or "").strip()
    if not proof_purpose:
        raise RuntimeError("Controller runtime fence boundary must be non-empty.")
    proofs = journal.setdefault("runtime_fence_proofs", [])
    if not isinstance(proofs, list):
        raise RuntimeError("Controller runtime fence proofs must be a list.")
    target_payload = [
        {
            "node_name": target.node_name,
            "node_uid": target.node_uid,
            "state_markers": list(target.state_markers),
        }
        for target in targets
    ]
    # Reconcile the latest exact unverified intent after interruption.  A new
    # attempt is required after verified evidence, but resubmitting an
    # indeterminate create with a different identity would orphan the original
    # inspector and discard the only crash-safe operation handle.
    resumable = next(
        (
            item
            for item in reversed(proofs)
            if fresh_attempt
            and isinstance(item, dict)
            and item.get("purpose") == proof_purpose
            and item.get("status") == "intent-recorded"
            and item.get("image") == image
            and item.get("targets") == target_payload
            and re.fullmatch(r"[0-9a-f]{32}", str(item.get("attempt_id", "") or ""))
        ),
        None,
    )
    fresh_attempt_id = (
        str(resumable.get("attempt_id", "") or "")
        if isinstance(resumable, Mapping)
        else (uuid4().hex if fresh_attempt else "")
    )
    if fresh_attempt_id:
        boundary = f"{proof_purpose}-attempt-{fresh_attempt_id}"
    existing = next(
        (item for item in proofs if isinstance(item, dict) and item.get("boundary") == boundary),
        None,
    )
    if existing is None:
        existing = {
            "boundary": boundary,
            "status": "intent-recorded",
            "intent_at": _utc_now(),
            "image": image,
            "targets": target_payload,
            "results": [],
        }
        if fresh_attempt_id:
            existing.update(
                {
                    "purpose": proof_purpose,
                    "attempt_id": fresh_attempt_id,
                    "fresh_attempt": True,
                }
            )
        proofs.append(existing)
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif existing.get("image") != image or existing.get("targets") != target_payload:
        raise RuntimeError(
            f"recovery-required: controller runtime fence binding drifted at {boundary}."
        )
    if existing.get("status") == "verified":
        return [dict(item) for item in _sequence_of_mappings(existing.get("results"))]

    namespace = CONTROLLER_INSPECTOR_NAMESPACE
    campaign = str(journal.get("campaign_fingerprint", "") or "")
    epoch_slug = re.sub(r"[^a-z0-9.-]+", "-", proof_purpose.lower()).strip("-.")
    proof_epoch = (
        f"fence-{epoch_slug[:32]}-{fresh_attempt_id[:12]}".rstrip("-.")
        if fresh_attempt_id
        else f"fence-{epoch_slug[:48]}".rstrip("-.")
    )
    results: list[dict[str, Any]] = []
    prepared_targets: list[
        tuple[
            ControllerFenceTarget,
            dict[str, str],
            dict[str, Any],
            str,
        ]
    ] = []
    missing_pods: list[dict[str, Any]] = []
    for target in targets:
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", target.node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_identity_before = _controller_runtime_node_identity(
            node,
            expected_name=target.node_name,
            expected_uid=target.node_uid,
        )
        desired = controller_runtime_fence_pod(
            campaign_fingerprint=campaign,
            authority_epoch=proof_epoch,
            image=image,
            target=target,
        )
        pod_name = str(_mapping(desired.get("metadata")).get("name", "") or "")
        pod_exists, live = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource=f"pod/{pod_name}",
        )
        prior = next(
            (
                item
                for item in _sequence_of_mappings(existing.get("results"))
                if item.get("node_uid") == target.node_uid
            ),
            {},
        )
        if pod_exists:
            metadata = _mapping(live.get("metadata"))
            labels = _mapping(metadata.get("labels"))
            annotations = _mapping(metadata.get("annotations"))
            prior_uid = str(prior.get("pod_uid", "") or "")
            if (
                (prior_uid and str(metadata.get("uid", "") or "") != prior_uid)
                or labels.get("app.kubernetes.io/managed-by") != "nebius-cxcli"
                or labels.get(CONTROLLER_BRIDGE_LABEL) != "fence"
                or labels.get(CONTROLLER_FENCE_LABEL) != "true"
                or annotations.get("nebius.ai/cxcli-campaign-fingerprint") != campaign
                or not _controller_runtime_fence_manifest_contract_matches(live, desired)
            ):
                raise RuntimeError(
                    f"recovery-required: controller runtime fence Pod drifted: {pod_name}."
                )
        else:
            if prior:
                raise RuntimeError(
                    f"recovery-required: controller runtime fence Pod disappeared: {pod_name}."
                )
            missing_pods.append(desired)
        prepared_targets.append((target, node_identity_before, desired, pod_name))

    # Every host inspector is independent and the manifest pins each Pod to one
    # exact Node UID.  Admit and wait for the whole proof set together so a
    # cluster-wide fence takes roughly the duration of the slowest host scan,
    # rather than the sum of every host scan.  The intent above remains the
    # crash-safe handle for reconciling a partial API admission on resume.
    if missing_pods:
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=tuple(missing_pods),
            timeout_seconds=300,
        )
    pod_resources = [f"pod/{pod_name}" for *_prepared, pod_name in prepared_targets]
    # A named `kubectl wait --for=condition=Ready` fails immediately when the
    # API read path has not observed a just-created Pod yet.  Bind a separate
    # creation barrier before evaluating readiness so admitted inspectors cannot
    # be mistaken for absent ones during read-after-write propagation.
    created = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "wait",
            "--for=create",
            *pod_resources,
            "--timeout=2m",
        ],
        check=False,
        timeout_seconds=150,
    )
    if created.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"Controller runtime fence {boundary} was admitted but did not become "
            "observable on every bound Node."
        )
    wait = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "wait",
            "--for=condition=Ready",
            *pod_resources,
            "--timeout=5m",
        ],
        check=False,
        timeout_seconds=360,
    )

    for target, node_identity_before, _desired, pod_name in prepared_targets:
        pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pod",
                pod_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        logs = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "logs",
                f"pod/{pod_name}",
                "-c",
                "inspector",
            ],
            check=False,
            timeout_seconds=120,
        )
        try:
            evidence = parse_controller_runtime_fence_evidence(logs.stdout, target=target)
        except ValueError as exc:
            raise SoperatorMigrationPhasePending(
                f"Controller runtime fence {boundary} failed on {target.node_name}: {exc}"
            ) from exc
        metadata = _mapping(pod.get("metadata"))
        status = _mapping(pod.get("status"))
        inspector_status = next(
            (
                item
                for item in _sequence_of_mappings(status.get("containerStatuses"))
                if item.get("name") == "inspector"
            ),
            {},
        )
        if (
            wait.returncode != 0
            or logs.returncode != 0
            or str(status.get("phase", "") or "") != "Running"
            or inspector_status.get("ready") is not True
            or str(_mapping(pod.get("spec")).get("nodeName", "") or "") != target.node_name
            or not str(metadata.get("uid", "") or "")
        ):
            raise SoperatorMigrationPhasePending(
                f"Controller runtime fence {boundary} did not become Ready exactly on "
                f"{target.node_name}."
            )
        node_after = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", target.node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_identity_after = _controller_runtime_node_identity(
            node_after,
            expected_name=target.node_name,
            expected_uid=target.node_uid,
        )
        if any(
            node_identity_after[field] != node_identity_before[field]
            for field in ("node_uid", "provider_id", "system_uuid")
        ):
            raise RuntimeError(
                "recovery-required: controller fence Node/provider identity changed during "
                f"the runtime probe: {target.node_name}."
            )
        results.append(
            {
                **evidence.as_payload(),
                "pod_name": pod_name,
                "pod_uid": str(metadata.get("uid", "") or ""),
                "node_resource_version_before": node_identity_before["node_resource_version"],
                "node_resource_version_after": node_identity_after["node_resource_version"],
                "node_identity_sha256": _controller_runtime_node_identity_sha256(
                    node_identity_after
                ),
                "verified_at": _utc_now(),
            }
        )
    existing.update({"status": "verified", "results": results, "verified_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return results


def _controller_fence_targets_from_identities(
    identities: Sequence[Mapping[str, Any]],
    *,
    state_markers: Sequence[str],
    boundary: str,
) -> tuple[ControllerFenceTarget, ...]:
    """Build one exact, de-duplicated host-fence target set."""

    markers = tuple(str(item or "").strip() for item in state_markers if str(item or "").strip())
    if not markers:
        raise RuntimeError(f"Controller runtime fence {boundary} has no state markers.")
    targets_by_uid: dict[str, ControllerFenceTarget] = {}
    for identity in identities:
        node_name = str(identity.get("node_name", "") or "").strip()
        node_uid = str(identity.get("node_uid", "") or "").strip()
        if not node_name or not node_uid:
            raise RuntimeError(
                f"Controller runtime fence {boundary} has an incomplete historical node identity."
            )
        existing = targets_by_uid.get(node_uid)
        if existing is not None and existing.node_name != node_name:
            raise RuntimeError(
                f"Controller runtime fence {boundary} maps node UID {node_uid} to multiple names."
            )
        targets_by_uid[node_uid] = ControllerFenceTarget(
            node_name=node_name,
            node_uid=node_uid,
            state_markers=markers,
        )
    if not targets_by_uid:
        raise RuntimeError(f"Controller runtime fence {boundary} has no historical nodes.")
    return tuple(targets_by_uid[node_uid] for node_uid in sorted(targets_by_uid))


def _bridge_partition_record(payload: Mapping[str, Any]) -> SlurmPartitionPauseRecord:
    return SlurmPartitionPauseRecord(
        partition=str(payload.get("partition", "") or ""),
        previous_state=str(payload.get("previous_state", "") or ""),
        previous_record=str(payload.get("previous_record", "") or ""),
        previous_record_fingerprint=str(payload.get("previous_record_fingerprint", "") or ""),
        applied_state=str(payload.get("applied_state", "") or "DOWN"),
        applied_record=str(payload.get("applied_record", "") or ""),
        applied_record_fingerprint=str(payload.get("applied_record_fingerprint", "") or ""),
    )


def _bridge_partition_inventory_state(payload: Mapping[str, Any]) -> SlurmPartitionState:
    return SlurmPartitionState(
        name=str(payload.get("name", "") or ""),
        state=str(payload.get("state", "") or ""),
        record=str(payload.get("record", "") or ""),
        record_fingerprint=str(payload.get("record_fingerprint", "") or ""),
        nodes=str(payload.get("nodes", "") or ""),
    )


def _bridge_partition_inventory_payload(state: SlurmPartitionState) -> dict[str, str]:
    return {
        "name": state.name,
        "state": state.state,
        "record": state.record,
        "record_fingerprint": state.record_fingerprint,
        "nodes": state.nodes,
    }


def _controller_bridge_source_fence_dispatch_gap(journal: Mapping[str, Any]) -> bool:
    """Return whether the source is in the durable scale-to-zero handoff gap."""
    intent = _mapping(journal.get("source_fence_intent"))
    authority = _mapping(journal.get("authority"))
    source_fencing = _mapping(_mapping(journal.get("fencing")).get("source"))
    if (
        str(journal.get("stage", "") or "") != BridgeStage.SOURCE_PRECOPIED.value
        or intent.get("state") != "dispatching"
        or authority.get("owner") != "source-singleton"
        or str(authority.get("first_bridge_write_at", "") or "")
        or authority.get("source_restart_prohibited") is not False
        or source_fencing.get("proven") is not False
    ):
        return False
    authority_epoch = str(authority.get("epoch", "") or "")
    source_binding = _mapping(journal.get("source_binding"))
    if (
        not authority_epoch
        or intent.get("authority_epoch") != authority_epoch
        or intent.get("source_workload_uid") != source_binding.get("controller_workload_uid")
        or intent.get("source_pod_uid") != source_binding.get("controller_pod_uid")
        or not str(intent.get("dispatching_at", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: source controller fence dispatch is not bound to the "
            "exact source authority, workload, and Pod identities."
        )
    validate_bridge_journal(journal)
    return True


def _controller_bridge_partition_pause_authority_gap(journal: Mapping[str, Any]) -> bool:
    """Return whether only durable pause evidence is available between writers."""

    if _controller_bridge_source_fence_dispatch_gap(journal):
        return True
    authority = _mapping(journal.get("authority"))
    source_writer_scale = _mapping(authority.get("writer_scale"))
    source_fencing = _mapping(_mapping(journal.get("fencing")).get("source"))
    if (
        str(journal.get("stage", "") or "") == BridgeStage.STATE_PROMOTED.value
        and authority.get("owner") == "bridge-source"
        and authority.get("source_restart_prohibited") is True
        and str(authority.get("first_bridge_write_at", "") or "").strip()
        and source_writer_scale.get("state") == "accepted"
        and _non_negative_int(source_writer_scale.get("from_replicas"), fallback=-1) == 0
        and _positive_int(source_writer_scale.get("to_replicas"), fallback=0) == 2
        and str(source_writer_scale.get("statefulset_uid", "") or "").strip()
        and str(source_writer_scale.get("dispatching_at", "") or "").strip()
        and str(source_writer_scale.get("accepted_at", "") or "").strip()
        and source_fencing.get("proven") is True
        and source_fencing.get("process_absent") is True
        and source_fencing.get("writable_mount_absent") is True
    ):
        # The source-version bridge writer mutation may be accepted before the
        # bridge Pods prove primary/backup service.  A stale jailed slurm.conf
        # can leave both accepted Pods unable to answer Slurm RPCs while the
        # exact StatefulSet is repaired.  Bind pause reuse to the accepted
        # 0 -> 2 CAS and completed source runtime fence until HA is proven.
        validate_bridge_journal(journal)
        return True
    transition = _mapping(journal.get("version_transition"))
    runtime_fence = _sequence_of_mappings(transition.get("source_runtime_fence"))
    if (
        str(journal.get("stage", "") or "") == BridgeStage.SOURCE_HA_ACTIVE.value
        and authority.get("owner") == "bridge-source"
        and authority.get("source_restart_prohibited") is True
        and str(authority.get("first_bridge_write_at", "") or "").strip()
        and str(transition.get("cold_stop_dispatching_at", "") or "").strip()
        and str(transition.get("both_stopped_at", "") or "").strip()
        and str(transition.get("post_stop_api_absence_verified_at", "") or "").strip()
        and not str(transition.get("target_write_at", "") or "").strip()
        and transition.get("downgrade_prohibited") is False
        and len(runtime_fence) == 2
        and all(
            item.get("fenced") is True
            and int(item.get("slurmctld_count", -1) or 0) == 0
            and int(item.get("writable_state_mount_count", -1) or 0) == 0
            for item in runtime_fence
        )
    ):
        # The version-transition lifecycle intentionally remains source-ha-active
        # until target authority is accepted.  During its exact 2 -> 0 cold stop,
        # that stage name must not trigger Slurm RPC revalidation: no controller
        # can answer, and the checkpointed partition records plus fresh runtime
        # and API-absence fences are the only valid authority evidence.
        validate_bridge_journal(journal)
        return True
    target_scale = _mapping(transition.get("target_writer_scale"))
    if (
        str(journal.get("stage", "") or "") == BridgeStage.SOURCE_HA_ACTIVE.value
        and authority.get("owner") == "bridge-target"
        and authority.get("source_restart_prohibited") is True
        and str(authority.get("first_bridge_write_at", "") or "").strip()
        and str(transition.get("target_write_at", "") or "").strip()
        and transition.get("downgrade_prohibited") is True
        and target_scale.get("state") == "accepted"
        and _positive_int(target_scale.get("to_replicas"), fallback=0) == 2
    ):
        # Accepting the target writer scale is the irreversible mutation
        # boundary, not the HA service proof.  Until target primary/backup is
        # durably verified and the bridge stage advances, Slurm RPCs may still
        # be unavailable (for example, while repairing a stale jailed config).
        # Reuse the exact partition checkpoint instead of probing an authority
        # that has not yet passed its service gate.
        validate_bridge_journal(journal)
        return True
    intent = _mapping(journal.get("source_fence_intent"))
    if (
        str(journal.get("stage", "") or "")
        not in {BridgeStage.SOURCE_FENCED.value, BridgeStage.STATE_PROMOTED.value}
        or authority.get("owner") != "source-singleton"
        or str(authority.get("first_bridge_write_at", "") or "")
        or intent.get("state") != "accepted"
        or source_fencing.get("proven") is not True
        or source_fencing.get("process_absent") is not True
        or source_fencing.get("writable_mount_absent") is not True
    ):
        return False
    validate_bridge_journal(journal)
    return True


def _controller_bridge_authority_gap_partition_pause_records(
    journal: Mapping[str, Any],
) -> tuple[SlurmPartitionPauseRecord, ...]:
    """Return the exact durable partition pause while no controller can answer."""

    if not _controller_bridge_partition_pause_authority_gap(journal):
        return ()
    inventory = tuple(
        _bridge_partition_inventory_state(item)
        for item in _sequence_of_mappings(journal.get("partition_inventory"))
    )
    records = tuple(
        _bridge_partition_record(item)
        for item in _sequence_of_mappings(journal.get("partition_pause"))
    )
    inventory_names = {state.name for state in inventory}
    records_by_name = {record.partition: record for record in records}
    if (
        not inventory
        or not str(journal.get("partition_inventory_captured_at", "") or "")
        or not records
        or not str(journal.get("partition_pause_captured_at", "") or "")
        or not str(journal.get("partition_pause_revalidated_at", "") or "")
        or len(inventory_names) != len(inventory)
        or len(records_by_name) != len(records)
        or any(not record.applied_record for record in records)
        or any(
            state.state.upper() == "UP" and state.name not in records_by_name for state in inventory
        )
        or any(record.partition not in inventory_names for record in records)
    ):
        raise RuntimeError(
            "recovery-required: controller authority gap lacks the complete exact "
            "partition pause and immediate pre-fence revalidation proof."
        )
    return records


def _bridge_pause_all_partitions(
    *,
    journal: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    checkpoint: Mapping[str, Any] | None = None,
) -> list[str]:
    if _controller_bridge_authority_gap_partition_pause_records(journal):
        return [
            "Slurm scheduling pause: retained the checkpointed exact DOWN records "
            "during the accepted controller authority gap; live revalidation will "
            "resume through bridge authority."
        ]
    inventory_raw = journal.get("partition_inventory")
    if inventory_raw is None:
        inventory = _external_upgrade_partition_state_snapshot(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if not inventory:
            raise SoperatorMigrationPhasePending(
                "controller-ha-bridge requires at least one Slurm partition before pause."
            )
        journal["partition_inventory"] = [
            _bridge_partition_inventory_payload(state) for state in inventory
        ]
        journal["partition_inventory_captured_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    else:
        if (
            not isinstance(inventory_raw, list)
            or not str(journal.get("partition_inventory_captured_at", "") or "").strip()
        ):
            raise RuntimeError(
                "recovery-required: controller bridge partition inventory is incomplete."
            )
        inventory = tuple(
            _bridge_partition_inventory_state(item) for item in _sequence_of_mappings(inventory_raw)
        )
        if not inventory or len({state.name for state in inventory}) != len(inventory):
            raise RuntimeError(
                "recovery-required: controller bridge partition inventory is empty or "
                "contains duplicate names."
            )
    saved = journal.get("partition_pause")
    saved_records = tuple(_bridge_partition_record(item) for item in _sequence_of_mappings(saved))
    if isinstance(saved, list) and str(journal.get("partition_pause_captured_at", "") or ""):
        if _controller_bridge_partition_pause_authority_gap(journal):
            pause_by_name = {record.partition: record for record in saved_records}
            if (
                len(pause_by_name) != len(saved_records)
                or any(not record.applied_record for record in saved_records)
                or not str(journal.get("partition_pause_revalidated_at", "") or "")
                or any(
                    state.state.upper() == "UP" and state.name not in pause_by_name
                    for state in inventory
                )
                or any(
                    record.partition not in {state.name for state in inventory}
                    for record in saved_records
                )
            ):
                raise RuntimeError(
                    "recovery-required: controller authority gap lacks the complete exact "
                    "partition pause and immediate pre-fence revalidation proof."
                )
            return [
                "Slurm scheduling pause: retained the checkpointed exact DOWN records "
                "during the accepted source scale-to-zero dispatch; live revalidation "
                "will resume through bridge authority."
            ]
        live_inventory = {
            state.name: state
            for state in _external_upgrade_partition_state_snapshot(
                command_runner=command_runner,
                kube_context=kube_context,
            )
        }
        pause_by_name = {record.partition: record for record in saved_records}
        inventory_names = {state.name for state in inventory}
        if set(live_inventory) != inventory_names:
            if checkpoint is None:
                raise RuntimeError(
                    "recovery-required: the Slurm partition set changed after the controller "
                    "bridge inventory checkpoint."
                )
            (
                _all_partition_records,
                target_partition_records,
                _target_partition_payload,
                retired_partition_payload,
                restore_records_sha256,
            ) = _checkpoint_slurm_partition_restore_plan(checkpoint)
            target_records_by_name = {
                record.partition: record for record in target_partition_records
            }
            target_partition_names = set(target_records_by_name)
            retired_partition_names = {
                str(item.get("partition") or "").strip() for item in retired_partition_payload
            }
            exact_target_handoff = bool(
                retired_partition_names
                and retired_partition_names <= inventory_names
                and inventory_names - set(live_inventory) == retired_partition_names
                and set(live_inventory) == target_partition_names
                and all(
                    record.applied_state == "DOWN"
                    and record.applied_record
                    and record.applied_record_fingerprint
                    and _slurm_partition_observation_matches(
                        live_inventory[name],
                        record=record.applied_record,
                        fingerprint=record.applied_record_fingerprint,
                    )
                    for name, record in target_records_by_name.items()
                )
            )
            if not exact_target_handoff:
                raise RuntimeError(
                    "recovery-required: the Slurm partition set changed after the controller "
                    "bridge inventory checkpoint."
                )
            journal["partition_target_handoff"] = {
                "schema": "nebius-cxcli/controller-bridge-partition-target-handoff-v1",
                "status": "verified",
                "restore_records_sha256": restore_records_sha256,
                "target_partitions": sorted(target_partition_names),
                "retired_source_partitions": sorted(retired_partition_names),
                "verified_at": _utc_now(),
            }
            if checkpoint_writer is not None:
                checkpoint_writer()
            return [
                "Slurm scheduling pause: accepted the durable target partition handoff; "
                f"{len(target_partition_names)} canonical target partition(s) remain "
                f"exactly DOWN and {len(retired_partition_names)} source-era partition(s) "
                "remain retired."
            ]
        reassert_pause = False
        for state in inventory:
            record = pause_by_name.get(state.name)
            expected_record = record.applied_record if record is not None else state.record
            expected_fingerprint = (
                record.applied_record_fingerprint
                if record is not None
                else state.record_fingerprint
            )
            if expected_record and _slurm_partition_observation_matches(
                live_inventory[state.name],
                record=expected_record,
                fingerprint=expected_fingerprint,
            ):
                continue
            if record is not None and _slurm_partition_observation_matches(
                live_inventory[state.name],
                record=record.previous_record,
                fingerprint=record.previous_record_fingerprint,
            ):
                reassert_pause = True
                continue
            raise RuntimeError(
                "recovery-required: a partition changed after the controller bridge "
                f"pause checkpoint: {state.name}."
            )
        if reassert_pause:
            _reassert_controller_bridge_partition_pause_after_reconfigure(
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
            live_inventory = {
                state.name: state
                for state in _external_upgrade_partition_state_snapshot(
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
            }
            if set(live_inventory) != {state.name for state in inventory}:
                raise RuntimeError(
                    "recovery-required: the Slurm partition set changed while reasserting "
                    "the controller bridge pause checkpoint."
                )
            for state in inventory:
                record = pause_by_name.get(state.name)
                expected_record = record.applied_record if record is not None else state.record
                expected_fingerprint = (
                    record.applied_record_fingerprint
                    if record is not None
                    else state.record_fingerprint
                )
                if not expected_record or not _slurm_partition_observation_matches(
                    live_inventory[state.name],
                    record=expected_record,
                    fingerprint=expected_fingerprint,
                ):
                    raise RuntimeError(
                        "recovery-required: a partition changed while reasserting the "
                        f"controller bridge pause checkpoint: {state.name}."
                    )
        return [
            "Slurm scheduling pause: reused "
            f"{len(saved_records)} owned DOWN record(s) and revalidated all "
            f"{len(inventory)} partition snapshots."
        ]

    durable: dict[str, dict[str, str]] = {
        record.partition: record.as_payload() for record in saved_records
    }
    for record in saved_records:
        observation = _external_upgrade_partition_state(
            command_runner=command_runner,
            kube_context=kube_context,
            partition=record.partition,
        )
        if record.applied_record:
            if not _slurm_partition_observation_matches(
                observation,
                record=record.applied_record,
                fingerprint=record.applied_record_fingerprint,
            ):
                raise RuntimeError(
                    "recovery-required: a partially checkpointed controller-bridge pause "
                    f"record drifted for partition {record.partition}."
                )
            continue
        if not _slurm_partition_observation_matches(
            observation,
            record=record.previous_record,
            fingerprint=record.previous_record_fingerprint,
        ):
            raise RuntimeError(
                "recovery-required: controller-bridge pause intent for partition "
                f"{record.partition} has no exact applied observation and live state no "
                "longer matches the pre-mutation record. Automatic recovery is unsafe."
            )

    def _record(record: SlurmPartitionPauseRecord) -> None:
        durable[record.partition] = record.as_payload()
        journal["partition_pause"] = [durable[name] for name in sorted(durable)]
        if checkpoint_writer is not None:
            checkpoint_writer()

    newly_applied = _external_upgrade_pause_slurm_partitions(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=(),
        intent_recorder=_record,
        all_partitions=True,
        snapshot=inventory,
    )
    for record in newly_applied:
        durable[record.partition] = record.as_payload()
    records = tuple(_bridge_partition_record(durable[name]) for name in sorted(durable))
    if any(not record.applied_record for record in records):
        raise RuntimeError(
            "recovery-required: controller-bridge partition pause completed without an "
            "exact post-mutation observation for every recorded intent."
        )
    live_inventory = {
        state.name: state
        for state in _external_upgrade_partition_state_snapshot(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    }
    pause_by_name = {record.partition: record for record in records}
    if set(live_inventory) != {state.name for state in inventory}:
        raise RuntimeError(
            "recovery-required: the Slurm partition set changed while scheduling was paused."
        )
    for state in inventory:
        record = pause_by_name.get(state.name)
        expected_record = record.applied_record if record is not None else state.record
        expected_fingerprint = (
            record.applied_record_fingerprint if record is not None else state.record_fingerprint
        )
        if not _slurm_partition_observation_matches(
            live_inventory[state.name],
            record=expected_record,
            fingerprint=expected_fingerprint,
        ):
            raise RuntimeError(
                "recovery-required: Slurm partition state drifted while applying the "
                f"controller bridge scheduling pause: {state.name}."
            )
    journal["partition_pause"] = [record.as_payload() for record in records]
    journal["partition_pause_captured_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        f"Slurm scheduling pause: set {len(records)} previously UP partition(s) to DOWN; "
        "already non-schedulable partition states were preserved."
    ]


def _bridge_slurm_config_with_timeouts(slurm_conf: str) -> tuple[str, dict[str, str]]:
    updated = source_controller_config_with_bridge_hosts(slurm_conf)
    originals: dict[str, str] = {}
    for key in ("SlurmdTimeout", "SlurmctldTimeout"):
        match = re.search(rf"(?im)^\s*{key}\s*=\s*(\S+)\s*$", updated)
        originals[key] = match.group(1) if match else ""
        replacement = f"{key}=3600"
        if match:
            updated = re.sub(rf"(?im)^\s*{key}\s*=\s*\S+\s*$", replacement, updated)
        else:
            updated = updated.rstrip() + "\n" + replacement + "\n"
    return updated, originals


def _reassert_controller_bridge_partition_pause_after_reconfigure(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    records = tuple(
        _bridge_partition_record(item)
        for item in _sequence_of_mappings(journal.get("partition_pause"))
    )
    if not records or any(not record.applied_record for record in records):
        raise RuntimeError(
            "recovery-required: source controller reconfigure lacks the exact checkpointed "
            "partition pause records."
        )
    reasserted: list[str] = []
    for record in records:
        live = _external_upgrade_partition_state(
            command_runner=command_runner,
            kube_context=kube_context,
            partition=record.partition,
        )
        if _slurm_partition_observation_matches(
            live,
            record=record.applied_record,
            fingerprint=record.applied_record_fingerprint,
        ):
            continue
        if not _slurm_partition_observation_matches(
            live,
            record=record.previous_record,
            fingerprint=record.previous_record_fingerprint,
        ):
            raise RuntimeError(
                "recovery-required: Slurm partition state changed outside its exact "
                f"checkpointed UP/DOWN pair after controller reconfigure: {record.partition}."
            )
        result = _kubectl_exec_login(
            command_runner=command_runner,
            kube_context=kube_context,
            args=(
                "scontrol",
                "update",
                f"PartitionName={record.partition}",
                f"State={record.applied_state}",
            ),
            check=False,
            timeout_seconds=120,
        )
        accepted = False
        for attempt in range(6):
            if attempt:
                time.sleep(2)
            after = _external_upgrade_partition_state(
                command_runner=command_runner,
                kube_context=kube_context,
                partition=record.partition,
            )
            if _slurm_partition_observation_matches(
                after,
                record=record.applied_record,
                fingerprint=record.applied_record_fingerprint,
            ):
                accepted = True
                break
        if not accepted:
            raise RuntimeError(
                "recovery-required: source controller reconfigure reset partition scheduling "
                "and cxcli could not observe the exact restored DOWN record after its "
                f"bounded convergence window: {record.partition}; "
                f"update result={_command_detail(result)}."
            )
        reasserted.append(record.partition)
    journal["partition_pause_revalidated_at"] = _utc_now()
    journal["partition_pause_reasserted"] = reasserted
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Slurm scheduling pause after controller reconfigure: all checkpoint-owned DOWN "
        f"records verified; reasserted {len(reasserted)} partition(s)."
    ]


def _restore_controller_gap_timeouts(
    slurm_conf: str,
    originals: Mapping[str, Any],
) -> str:
    expected_keys = ("SlurmdTimeout", "SlurmctldTimeout")
    if set(originals) != set(expected_keys):
        raise RuntimeError(
            "controller bridge journal does not contain the exact original timeout contract."
        )
    restored = slurm_conf
    for key in expected_keys:
        value = str(originals.get(key, "") or "").strip()
        if value and not re.fullmatch(r"[0-9]+", value):
            raise RuntimeError(f"journaled original {key} is not a non-negative integer.")
        restored = re.sub(rf"(?im)^\s*{key}\s*=\s*\S+\s*\n?", "", restored)
        if value:
            restored = restored.rstrip() + f"\n{key}={value}\n"
    return restored.rstrip() + "\n"


_SLURM_PRESERVATION_JOBS_SCHEMA = "nebius-cxcli-slurm-preservation-jobs/v1"
_SLURM_PRESERVATION_DISRUPTIVE_ACTIONS = frozenset({"cancel", "requeue", "requeue-hold"})
_SLURM_COLD_JOB_CENSUS_SCHEMA = "nebius-cxcli-slurm-cold-job-census/v1"


def _capture_controller_bridge_cold_job_census(
    *,
    checkpoint: dict[str, Any],
    transition: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Bind every live or pending job immediately before the cold controller stop."""

    action_journal = ensure_slurm_action_journal(checkpoint)
    validate_slurm_action_journal(action_journal)
    jobs = _external_upgrade_all_slurm_jobs(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    records: dict[str, Any] = {}
    for job in jobs:
        observation = _external_upgrade_slurm_job_control_observation(
            command_runner=command_runner,
            kube_context=kube_context,
            job_id=job.job_id,
        )
        fields = _slurm_job_control_record_fields(observation.record)
        partition = str(fields.get("Partition", "") or "").strip()
        if not partition or partition != job.partition:
            raise SoperatorMigrationPhasePending(
                f"cold controller restart could not bind Slurm job {job.job_id} to one "
                "unchanged partition."
            )
        records[job.job_id] = {
            "observation": observation.as_payload(),
            "partition": partition,
        }
    transition["cold_job_census"] = {
        "schema": _SLURM_COLD_JOB_CENSUS_SCHEMA,
        "status": "captured",
        "job_ids": sorted(records),
        "jobs": records,
        "action_journal_generation": int(action_journal.get("active_authority_generation", 0) or 0),
        "captured_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()


def _verify_controller_bridge_cold_job_census(
    *,
    checkpoint: dict[str, Any],
    transition: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    census = transition.get("cold_job_census")
    if not isinstance(census, dict):
        raise RuntimeError(
            "recovery-required: target controller start lacks the pre-stop all-job census."
        )
    records = census.get("jobs")
    job_ids = census.get("job_ids")
    if (
        census.get("schema") != _SLURM_COLD_JOB_CENSUS_SCHEMA
        or census.get("status") not in {"captured", "verified"}
        or not isinstance(records, Mapping)
        or not isinstance(job_ids, list)
        or job_ids != sorted(str(job_id) for job_id in records)
    ):
        raise RuntimeError("recovery-required: pre-stop Slurm all-job census is incomplete.")
    action_journal = ensure_slurm_action_journal(checkpoint)
    validate_slurm_action_journal(action_journal)
    evidence: dict[str, Any] = {}
    for job_id, raw_record in sorted(records.items()):
        record = _mapping(raw_record)
        payload = _mapping(record.get("observation"))
        _validate_slurm_job_control_observation_payload(
            payload,
            job_id=job_id,
            label="cold controller restart baseline",
        )
        baseline = _SlurmJobControlObservation(
            job_id=job_id,
            identity=_slurm_job_control_payload_identity(payload),
            identity_fingerprint=str(payload.get("identity_fingerprint", "") or ""),
            job_state=str(payload.get("job_state", "") or ""),
            reason=str(payload.get("reason", "") or ""),
            priority=str(payload.get("priority", "") or ""),
            held=payload.get("held") is True,
            record=str(payload.get("record", "") or ""),
            record_fingerprint=str(payload.get("record_fingerprint", "") or ""),
        )
        binding = _slurm_action_binding_from_observation(baseline)
        overrides = _slurm_preservation_operator_override(
            action_journal=action_journal,
            binding=binding,
        )
        if overrides:
            evidence[job_id] = {"status": "operator-modified", "actions": list(overrides)}
            continue
        try:
            current = _external_upgrade_slurm_job_control_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                job_id=job_id,
            )
        except RuntimeError:
            current = None
        baseline_partition = str(record.get("partition", "") or "").strip()
        if current is not None:
            current_fields = _slurm_job_control_record_fields(current.record)
            if (
                current.identity_fingerprint != baseline.identity_fingerprint
                or str(current_fields.get("Partition", "") or "").strip() != baseline_partition
                or _slurm_job_control_record_restart_count(current.record)
                != binding.restart_baseline
                or not (
                    slurm_job_is_active(_affected_job_from_observation(current))
                    or slurm_job_is_pending(_affected_job_from_observation(current))
                )
            ):
                raise SoperatorMigrationPhasePending(
                    f"Slurm job {job_id} changed identity, partition, restart lineage, or "
                    "active state across the controller restart."
                )
            evidence[job_id] = {"status": "preserved", "partition": baseline_partition}
            continue
        if slurm_job_is_pending(_affected_job_from_observation(baseline)):
            raise SoperatorMigrationPhasePending(
                f"pending Slurm job {job_id} disappeared across the controller restart."
            )
        baseline_allocation = _slurm_preservation_job_allocation(baseline)
        accounting = _slurm_preservation_sacct_observation(
            command_runner=command_runner,
            kube_context=kube_context,
            job_id=job_id,
        )
        if (
            accounting["state"].upper().rstrip("+") != "COMPLETED"
            or accounting["exit_code"] != "0:0"
            or accounting["submit_time"] != baseline_allocation["submit_time"]
            or accounting["start_time"] != baseline_allocation["start_time"]
            or accounting["node_list"] != baseline_allocation["node_list"]
            or not accounting["restarts"].isdecimal()
            or int(accounting["restarts"]) != baseline_allocation["restarts"]
        ):
            raise SoperatorMigrationPhasePending(
                f"Slurm job {job_id} disappeared without an exact successful completion "
                "across the controller restart."
            )
        evidence[job_id] = {"status": "completed", "partition": baseline_partition}
    census.update(
        {
            "status": "verified",
            "verification": evidence,
            "verified_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [f"Cold controller restart preserved {len(records)} exact active/pending Slurm job(s)."]


def _affected_job_from_observation(
    observation: _SlurmJobControlObservation,
) -> AffectedSlurmJob:
    return AffectedSlurmJob(
        job_id=observation.job_id,
        user="",
        state=observation.job_state,
        partition="",
        allocated_nodes="",
        requested_nodes="",
        scheduled_nodes="",
        reason=observation.reason,
        elapsed="",
        limit="",
        remaining="",
        name="",
        impact_scope="allocated-node",
    )


def _slurm_preservation_job_allocation(
    observation: _SlurmJobControlObservation,
) -> dict[str, Any]:
    fields = _slurm_job_control_record_fields(observation.record)
    restarts = _slurm_job_control_record_restart_count(observation.record)
    allocation = {
        "node_list": str(fields.get("NodeList", "") or "").strip(),
        "start_time": str(fields.get("StartTime", "") or "").strip(),
        "submit_time": str(fields.get("SubmitTime", "") or "").strip(),
        "restarts": restarts,
    }
    if (
        not allocation["node_list"]
        or allocation["node_list"] in _SLURM_UNALLOCATED_JOB_NODE_LIST_VALUES
        or not allocation["start_time"]
        or allocation["start_time"] in _SLURM_UNALLOCATED_JOB_NODE_LIST_VALUES
        or allocation["submit_time"]
        != str(observation.identity.get("submit_time", "") or "").strip()
        or restarts is None
    ):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge could not capture a complete allocation, start time, "
            f"submit time, and restart baseline for running Slurm job {observation.job_id}."
        )
    return allocation


def _validate_slurm_preservation_job_record(
    *,
    job_id: str,
    record: Mapping[str, Any],
) -> None:
    if record.get("schema") != _SLURM_PRESERVATION_JOBS_SCHEMA:
        raise RuntimeError(
            f"External Soperator v6 preservation record for Slurm job {job_id} has "
            "an unsupported schema."
        )
    binding_payload = record.get("binding")
    observation_payload = record.get("observation")
    allocation = record.get("allocation")
    if not isinstance(binding_payload, Mapping) or not isinstance(observation_payload, Mapping):
        raise RuntimeError(
            f"External Soperator v6 preservation record for Slurm job {job_id} lacks "
            "its immutable binding or observation."
        )
    binding = SlurmJobActionBinding.from_payload(binding_payload)
    _validate_slurm_job_control_observation_payload(
        observation_payload,
        job_id=job_id,
        label="preservation baseline",
    )
    observation = _SlurmJobControlObservation(
        job_id=job_id,
        identity=_slurm_job_control_payload_identity(observation_payload),
        identity_fingerprint=str(observation_payload.get("identity_fingerprint", "") or ""),
        job_state=str(observation_payload.get("job_state", "") or ""),
        reason=str(observation_payload.get("reason", "") or ""),
        priority=str(observation_payload.get("priority", "") or ""),
        held=observation_payload.get("held") is True,
        record=str(observation_payload.get("record", "") or ""),
        record_fingerprint=str(observation_payload.get("record_fingerprint", "") or ""),
    )
    if binding != _slurm_action_binding_from_observation(observation):
        raise RuntimeError(
            f"External Soperator v6 preservation binding drifted for Slurm job {job_id}."
        )
    if not isinstance(allocation, Mapping):
        raise RuntimeError(
            f"External Soperator v6 preservation record for Slurm job {job_id} lacks "
            "its allocation baseline."
        )
    expected_allocation = _slurm_preservation_job_allocation(observation)
    if dict(allocation) != expected_allocation or binding.job_id != job_id:
        raise RuntimeError(
            f"External Soperator v6 preservation allocation drifted for Slurm job {job_id}."
        )
    if not str(record.get("captured_at", "") or "").strip():
        raise RuntimeError(
            f"External Soperator v6 preservation record for Slurm job {job_id} lacks "
            "its capture timestamp."
        )


def _validate_slurm_capture_completion_record(
    *,
    job_id: str,
    record: Mapping[str, Any],
) -> None:
    accounting = record.get("accounting")
    if not isinstance(accounting, Mapping):
        raise RuntimeError(
            f"External Soperator v6 capture-completion record for Slurm job {job_id} "
            "lacks accounting evidence."
        )
    normalized = {str(key): str(value) for key, value in accounting.items()}
    if (
        normalized.get("job_id") != job_id
        or normalized.get("state", "").upper().rstrip("+") != "COMPLETED"
        or normalized.get("exit_code") != "0:0"
        or not normalized.get("restarts", "").isdecimal()
        or not normalized.get("submit_time")
        or not normalized.get("start_time")
        or not normalized.get("node_list")
    ):
        raise RuntimeError(
            f"External Soperator v6 capture-completion record for Slurm job {job_id} "
            "is not an exact successful allocation-level completion."
        )
    expected_sha256 = hashlib.sha256(_stable_json(normalized).encode("utf-8")).hexdigest()
    if (
        record.get("schema") != _SLURM_PRESERVATION_JOBS_SCHEMA
        or str(record.get("accounting_sha256", "") or "") != expected_sha256
        or not str(record.get("observed_at", "") or "").strip()
    ):
        raise RuntimeError(
            f"External Soperator v6 capture-completion record for Slurm job {job_id} "
            "is incomplete or changed."
        )


def _capture_controller_bridge_preservation_jobs(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    preservation = journal.get("preservation_jobs")
    if not isinstance(preservation, dict):
        raise RuntimeError("Controller bridge preservation_jobs journal must be mutable.")
    if preservation.get("schema") != _SLURM_PRESERVATION_JOBS_SCHEMA:
        raise RuntimeError(
            "External Soperator v6 preservation_jobs schema mismatch; no conversion is supported."
        )
    records = preservation.get("jobs")
    if not isinstance(records, dict):
        raise RuntimeError("Controller bridge preservation_jobs records must be mutable.")
    completed_during_capture = preservation.setdefault("completed_during_capture", {})
    if not isinstance(completed_during_capture, dict):
        raise RuntimeError("Controller bridge completed_during_capture records must be mutable.")
    capture_state = str(preservation.get("capture_state", "") or "")
    captured_ids = preservation.get("capture_job_ids")
    if capture_state == "complete":
        recorded_ids = set(records) | set(completed_during_capture)
        if (
            not isinstance(captured_ids, list)
            or sorted(recorded_ids) != sorted(str(item or "") for item in captured_ids)
            or set(records) & set(completed_during_capture)
        ):
            raise RuntimeError(
                "recovery-required: controller bridge preservation job capture is incomplete."
            )
        for job_id, record in sorted(records.items()):
            if not isinstance(record, Mapping):
                raise RuntimeError(
                    f"Controller bridge preservation record for {job_id} must be a mapping."
                )
            _validate_slurm_preservation_job_record(job_id=job_id, record=record)
        for job_id, record in sorted(completed_during_capture.items()):
            if not isinstance(record, Mapping):
                raise RuntimeError(
                    f"Controller bridge capture-completion record for {job_id} must be a mapping."
                )
            _validate_slurm_capture_completion_record(job_id=job_id, record=record)
        return [
            "Running-job lineage: reused "
            f"{len(records)} immutable allocation baseline(s) and "
            f"{len(completed_during_capture)} natural completion proof(s)."
        ]
    if capture_state not in {"", "dispatching"}:
        raise RuntimeError(
            "recovery-required: controller bridge preservation capture state is invalid."
        )
    if capture_state == "":
        action_journal = ensure_slurm_action_journal(checkpoint)
        validate_slurm_action_journal(action_journal)
        active_jobs = tuple(
            job
            for job in _external_upgrade_all_slurm_jobs(
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if slurm_job_is_active(job)
        )
        captured_ids = sorted({job.job_id for job in active_jobs})
        preservation.update(
            {
                "capture_state": "dispatching",
                "capture_job_ids": captured_ids,
                "capture_intent_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if not isinstance(captured_ids, list) or any(
        not str(item or "").strip() for item in captured_ids
    ):
        raise RuntimeError(
            "recovery-required: controller bridge preservation capture_job_ids is invalid."
        )
    for raw_job_id in captured_ids:
        job_id = str(raw_job_id)
        existing = records.get(job_id)
        if isinstance(existing, Mapping):
            _validate_slurm_preservation_job_record(job_id=job_id, record=existing)
            continue
        completed = completed_during_capture.get(job_id)
        if isinstance(completed, Mapping):
            _validate_slurm_capture_completion_record(job_id=job_id, record=completed)
            continue
        try:
            observation = _external_upgrade_slurm_job_control_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                job_id=job_id,
            )
        except RuntimeError:
            observation = None
        if not slurm_job_is_active(
            AffectedSlurmJob(
                job_id=job_id,
                user="",
                state=observation.job_state if observation is not None else "",
                partition="",
                allocated_nodes="",
                requested_nodes="",
                scheduled_nodes="",
                reason="",
                elapsed="",
                limit="",
                remaining="",
                name="",
                impact_scope="allocated-node",
            )
        ):
            accounting = _slurm_preservation_sacct_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                job_id=job_id,
            )
            normalized_accounting = {str(key): str(value) for key, value in accounting.items()}
            if observation is not None:
                observed_allocation = _slurm_preservation_job_allocation(observation)
                if (
                    normalized_accounting.get("submit_time")
                    != str(observation.identity.get("submit_time", "") or "")
                    or normalized_accounting.get("start_time")
                    != observed_allocation.get("start_time")
                    or normalized_accounting.get("node_list")
                    != observed_allocation.get("node_list")
                    or not normalized_accounting.get("restarts", "").isdecimal()
                    or int(normalized_accounting["restarts"]) != observed_allocation.get("restarts")
                ):
                    raise SoperatorMigrationPhasePending(
                        f"Slurm job {job_id} changed allocation, start time, submit time, "
                        "or Restarts while cxcli was capturing its preservation baseline."
                    )
            completion_record = {
                "schema": _SLURM_PRESERVATION_JOBS_SCHEMA,
                "accounting": normalized_accounting,
                "accounting_sha256": hashlib.sha256(
                    _stable_json(normalized_accounting).encode("utf-8")
                ).hexdigest(),
                "observed_at": _utc_now(),
            }
            try:
                _validate_slurm_capture_completion_record(
                    job_id=job_id,
                    record=completion_record,
                )
            except RuntimeError as exc:
                raise SoperatorMigrationPhasePending(
                    f"Slurm job {job_id} left its running allocation while cxcli was "
                    "capturing the preservation baseline and did not prove an exact "
                    "natural COMPLETED/0:0 accounting result."
                ) from exc
            completed_during_capture[job_id] = completion_record
            if checkpoint_writer is not None:
                checkpoint_writer()
            continue
        assert observation is not None
        record = {
            "schema": _SLURM_PRESERVATION_JOBS_SCHEMA,
            "binding": _slurm_action_binding_from_observation(observation).as_payload(),
            "observation": observation.as_payload(),
            "allocation": _slurm_preservation_job_allocation(observation),
            "captured_at": _utc_now(),
        }
        records[job_id] = record
        if checkpoint_writer is not None:
            checkpoint_writer()
    preservation.update(
        {
            "capture_state": "complete",
            "captured_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        f"Running-job lineage: captured {len(records)} immutable allocation baseline(s) and "
        f"{len(completed_during_capture)} natural completion proof(s) after scheduling pause."
    ]


def _slurm_preservation_operator_override(
    *,
    action_journal: Mapping[str, Any],
    binding: SlurmJobActionBinding,
) -> tuple[str, ...]:
    applied: list[str] = []
    for action in _sequence_of_mappings(action_journal.get("actions")):
        action_binding = action.get("binding")
        if not isinstance(action_binding, Mapping):
            continue
        candidate = SlurmJobActionBinding.from_payload(action_binding)
        if (
            candidate != binding
            or action.get("state") != SLURM_ACTION_APPLIED
            or action.get("kind") not in _SLURM_PRESERVATION_DISRUPTIVE_ACTIONS
        ):
            continue
        applied.append(str(action.get("kind", "") or ""))
    return tuple(applied)


def _slurm_preservation_sacct_observation(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    job_id: str,
) -> dict[str, str]:
    result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=(
            "sacct",
            "-X",
            "--noheader",
            "--parsable2",
            "--jobs",
            job_id,
            "--format=JobIDRaw,Submit,Start,NodeList,Restarts,State,ExitCode",
        ),
        check=False,
        timeout_seconds=120,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"running-job preservation could not query accounting for Slurm job {job_id}: "
            + _command_detail(result)
        )
    rows: list[dict[str, str]] = []
    fields = (
        "job_id",
        "submit_time",
        "start_time",
        "node_list",
        "restarts",
        "state",
        "exit_code",
    )
    for raw_line in result.stdout.splitlines():
        values = raw_line.strip().split("|")
        if len(values) == len(fields) + 1 and values[-1] == "":
            values.pop()
        if len(values) != len(fields):
            continue
        row = dict(zip(fields, (value.strip() for value in values), strict=True))
        if row["job_id"] == job_id:
            rows.append(row)
    if len(rows) != 1:
        raise SoperatorMigrationPhasePending(
            "running-job preservation requires exactly one allocation-level accounting "
            f"record for Slurm job {job_id}; observed {len(rows)}."
        )
    return rows[0]


def _prior_completed_preservation_proof(
    *,
    verifications: Sequence[Mapping[str, Any]],
    proof_stage: str,
    job_id: str,
) -> dict[str, str] | None:
    """Reuse an exact terminal proof after accounting enters its writer fence."""

    stage_order = (
        "source-version-bridge-active",
        "target-version-bridge-active",
        "target-singleton-active",
        "pre-cleanup",
    )
    if proof_stage not in stage_order:
        return None
    current_index = stage_order.index(proof_stage)
    for verification in reversed(verifications):
        prior_stage = str(verification.get("stage") or "").strip()
        if (
            prior_stage not in stage_order[:current_index]
            or verification.get("status") != "verified"
        ):
            continue
        job_proof = _mapping(_mapping(verification.get("jobs")).get(job_id))
        accounting_sha256 = str(job_proof.get("accounting_sha256") or "").strip()
        verified_at = str(job_proof.get("verified_at") or "").strip()
        if (
            job_proof.get("status") == "completed-preserved"
            and re.fullmatch(r"[0-9a-f]{64}", accounting_sha256)
            and verified_at
        ):
            return {
                "accounting_sha256": accounting_sha256,
                "verified_at": verified_at,
                "stage": prior_stage,
            }
    return None


def _verify_controller_bridge_preservation_jobs(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    proof_stage: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    reuse_existing: bool = True,
    proof_binding: Mapping[str, Any] | None = None,
) -> list[str]:
    preservation = journal.get("preservation_jobs")
    if not isinstance(preservation, dict) or preservation.get("capture_state") != "complete":
        raise SoperatorMigrationPhasePending(
            f"{proof_stage} requires the complete running-job preservation baseline."
        )
    verifications = preservation.get("verifications")
    records = preservation.get("jobs")
    completed_during_capture = preservation.get("completed_during_capture", {})
    if (
        not isinstance(verifications, list)
        or not isinstance(records, Mapping)
        or not isinstance(completed_during_capture, Mapping)
    ):
        raise RuntimeError("Controller bridge preservation verification journal is invalid.")
    prior = next(
        (
            item
            for item in verifications
            if isinstance(item, Mapping) and item.get("stage") == proof_stage
        ),
        None,
    )
    if prior is not None and reuse_existing:
        if prior.get("status") != "verified" or not str(prior.get("verified_at", "") or "").strip():
            raise RuntimeError(
                f"recovery-required: running-job verification {proof_stage} is incomplete."
            )
        return [
            f"Running-job lineage: reused {proof_stage} proof for "
            f"{len(records) + len(completed_during_capture)} job(s)."
        ]
    if prior is not None:
        verifications.remove(prior)
        if checkpoint_writer is not None:
            checkpoint_writer()
    action_journal = ensure_slurm_action_journal(checkpoint)
    validate_slurm_action_journal(action_journal)
    evidence: dict[str, Any] = {}
    for job_id, raw_record in sorted(completed_during_capture.items()):
        if not isinstance(raw_record, Mapping):
            raise RuntimeError(
                f"Controller bridge capture-completion record for {job_id} must be a mapping."
            )
        _validate_slurm_capture_completion_record(job_id=job_id, record=raw_record)
        evidence[job_id] = {
            "status": "completed-during-capture",
            "accounting_sha256": str(raw_record.get("accounting_sha256", "") or ""),
            "verified_at": _utc_now(),
        }
    for job_id, raw_record in sorted(records.items()):
        if not isinstance(raw_record, Mapping):
            raise RuntimeError(
                f"Controller bridge preservation record for {job_id} must be a mapping."
            )
        _validate_slurm_preservation_job_record(job_id=job_id, record=raw_record)
        binding = SlurmJobActionBinding.from_payload(_mapping(raw_record.get("binding")))
        overrides = _slurm_preservation_operator_override(
            action_journal=action_journal,
            binding=binding,
        )
        if overrides:
            evidence[job_id] = {
                "status": "operator-modified",
                "actions": list(overrides),
                "verified_at": _utc_now(),
            }
            continue
        baseline = _mapping(raw_record.get("allocation"))
        try:
            current = _external_upgrade_slurm_job_control_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                job_id=job_id,
            )
        except RuntimeError:
            current = None
        if current is not None and slurm_job_is_active(
            AffectedSlurmJob(
                job_id=job_id,
                user="",
                state=current.job_state,
                partition="",
                allocated_nodes="",
                requested_nodes="",
                scheduled_nodes="",
                reason="",
                elapsed="",
                limit="",
                remaining="",
                name="",
                impact_scope="allocated-node",
            )
        ):
            current_allocation = _slurm_preservation_job_allocation(current)
            if (
                current.identity_fingerprint != binding.identity_fingerprint
                or current_allocation != dict(baseline)
            ):
                raise SoperatorMigrationPhasePending(
                    f"running Slurm job {job_id} changed JobID lineage, allocation, start "
                    f"time, submit time, or Restarts before {proof_stage}."
                )
            evidence[job_id] = {
                "status": "active-preserved",
                "identity_fingerprint": current.identity_fingerprint,
                "record_fingerprint": current.record_fingerprint,
                "verified_at": _utc_now(),
            }
            continue
        prior_completion = _prior_completed_preservation_proof(
            verifications=tuple(item for item in verifications if isinstance(item, Mapping)),
            proof_stage=proof_stage,
            job_id=job_id,
        )
        if prior_completion is not None:
            evidence[job_id] = {
                "status": "completed-preserved",
                "accounting_sha256": prior_completion["accounting_sha256"],
                "reused_from_stage": prior_completion["stage"],
                "verified_at": _utc_now(),
            }
            continue
        accounting = _slurm_preservation_sacct_observation(
            command_runner=command_runner,
            kube_context=kube_context,
            job_id=job_id,
        )
        normalized_state = accounting["state"].upper().rstrip("+")
        if (
            accounting["submit_time"] != baseline.get("submit_time")
            or accounting["start_time"] != baseline.get("start_time")
            or accounting["node_list"] != baseline.get("node_list")
            or not accounting["restarts"].isdecimal()
            or int(accounting["restarts"]) != baseline.get("restarts")
            or normalized_state != "COMPLETED"
            or accounting["exit_code"] != "0:0"
        ):
            raise SoperatorMigrationPhasePending(
                f"Slurm job {job_id} did not retain its exact allocation/start/restart "
                f"lineage and complete successfully before {proof_stage}."
            )
        evidence[job_id] = {
            "status": "completed-preserved",
            "accounting_sha256": hashlib.sha256(
                _stable_json(accounting).encode("utf-8")
            ).hexdigest(),
            "verified_at": _utc_now(),
        }
    verification: dict[str, Any] = {
        "stage": proof_stage,
        "status": "verified",
        "jobs": evidence,
        "verified_at": _utc_now(),
    }
    if proof_binding is not None:
        raw_generation = proof_binding.get("action_journal_generation")
        if isinstance(raw_generation, bool) or not isinstance(raw_generation, int):
            raise RuntimeError("Running-job proof action-journal generation must be an integer.")
        authority_epoch = str(proof_binding.get("authority_epoch", "") or "").strip()
        if raw_generation < 0 or not authority_epoch:
            raise RuntimeError("Running-job proof binding is incomplete.")
        target_generation = proof_binding.get("target_authority_generation")
        target_action_generation = proof_binding.get("target_action_journal_generation")
        if (
            isinstance(target_generation, bool)
            or not isinstance(target_generation, int)
            or target_generation < 0
            or isinstance(target_action_generation, bool)
            or not isinstance(target_action_generation, int)
            or target_action_generation < 0
        ):
            raise RuntimeError("Running-job proof target action-generation binding is incomplete.")
        verification.update(dict(proof_binding))
    verifications.append(verification)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        f"Running-job lineage: {proof_stage} verified "
        f"{len(records) + len(completed_during_capture)} job(s) without "
        "allocation loss or unapproved restart."
    ]


def _controller_bridge_client_config_contract(slurm_conf: str) -> dict[str, Any]:
    cluster_names = re.findall(r"(?im)^\s*ClusterName\s*=\s*(\S+)\s*$", slurm_conf)
    controller_hosts = re.findall(r"(?im)^\s*SlurmctldHost\s*=\s*(\S+)\s*$", slurm_conf)
    if (
        len(cluster_names) != 1
        or not controller_hosts
        or len(set(controller_hosts)) != len(controller_hosts)
    ):
        raise RuntimeError(
            "controller bridge client configuration requires one ClusterName and an "
            "ordered, duplicate-free SlurmctldHost list."
        )
    timeouts: dict[str, str] = {}
    for key in ("SlurmdTimeout", "SlurmctldTimeout"):
        values = re.findall(rf"(?im)^\s*{key}\s*=\s*(\S+)\s*$", slurm_conf)
        if len(values) > 1:
            raise RuntimeError(
                f"controller bridge client configuration contains duplicate {key} values."
            )
        timeouts[key] = values[0] if values else ""
    return {
        "config_sha256": hashlib.sha256(slurm_conf.encode("utf-8")).hexdigest(),
        "cluster_name": cluster_names[0],
        "controller_hosts": controller_hosts,
        "timeouts": timeouts,
    }


def _target_takeover_client_controller_hosts(target_ref: str) -> tuple[str, ...]:
    return (
        *CONTROLLER_BRIDGE_CONTROLLER_HOSTS,
        f"controller-0({target_ref}-controller-svc)",
    )


def _reconcile_target_takeover_client_host_order(
    *,
    checkpoint: Mapping[str, Any],
    journal: Mapping[str, Any],
    takeover: dict[str, Any],
    target_ref: str,
    expected_contract: Mapping[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Supersede only the proven pre-fence target-first ordering defect."""

    previous = takeover.get("client_handoff_propagation")
    if not isinstance(previous, Mapping):
        return
    expected_sha256 = str(expected_contract.get("config_sha256", "") or "")
    future_target = f"controller-0({target_ref}-controller-svc)"
    old_hosts = (future_target, *CONTROLLER_BRIDGE_CONTROLLER_HOSTS)
    new_hosts = (*CONTROLLER_BRIDGE_CONTROLLER_HOSTS, future_target)
    manager_pause = _mapping(
        _mapping(_mapping(checkpoint.get("phase_state")).get("retire-old-resources")).get(
            "in_place_target_manager_pause"
        )
    )
    old_sha256 = str(previous.get("config_sha256", "") or "")
    interrupted_singleton_recovery = (
        str(journal.get("stage") or "") == BridgeStage.BRIDGE_FENCED.value
        and str(_mapping(journal.get("authority")).get("owner") or "") == "target-singleton"
        and _mapping(_mapping(journal.get("fencing")).get("bridge")).get("proven") is True
        and manager_pause.get("status") == "verified"
        and str(_mapping(takeover.get("target_start")).get("state") or "") == "accepted"
        and previous.get("schema") == "nebius-cxcli-controller-client-propagation/v1"
        and previous.get("status") == "verified"
        and previous.get("proof_stage") == "before-target-takeover"
        and previous.get("live_rpc_verified") is True
        and tuple(previous.get("controller_hosts", []) or []) == new_hosts
        and tuple(expected_contract.get("controller_hosts", []) or []) == new_hosts
        and old_sha256 == str(takeover.get("client_handoff_config_sha256", "") or "")
    )
    if interrupted_singleton_recovery:
        takeover["superseded_client_handoff_propagation"] = copy.deepcopy(dict(previous))
        takeover["client_handoff_singleton_recovery"] = {
            "schema": "nebius-cxcli/target-takeover-client-singleton-recovery-v1",
            "status": "accepted",
            "controller_hosts": list(new_hosts),
            "superseded_proof_sha256": _fingerprint(previous),
            "accepted_at": _utc_now(),
        }
        takeover.pop("client_handoff_propagation", None)
        if checkpoint_writer is not None:
            checkpoint_writer()
        return
    if str(previous.get("config_sha256", "") or "") == expected_sha256:
        return
    if (
        str(journal.get("stage") or "") != BridgeStage.TARGET_HA_ACTIVE.value
        or str(_mapping(journal.get("authority")).get("owner") or "") != "bridge-target"
        or _mapping(_mapping(journal.get("fencing")).get("bridge")).get("proven") is True
        or manager_pause.get("status") != "verified"
        or previous.get("schema") != "nebius-cxcli-controller-client-propagation/v1"
        or previous.get("status") != "verified"
        or previous.get("proof_stage") != "before-target-takeover"
        or previous.get("live_rpc_verified") is not True
        or tuple(previous.get("controller_hosts", []) or []) != old_hosts
        or tuple(expected_contract.get("controller_hosts", []) or []) != new_hosts
        or old_sha256 != str(takeover.get("client_handoff_config_sha256", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: target takeover client configuration changed outside the "
            "exact pre-fence target-first ordering correction."
        )
    migration = takeover.get("client_handoff_host_order_correction")
    if migration is not None:
        raise RuntimeError(
            "recovery-required: target takeover client host ordering was already corrected "
            "but its replacement proof is missing."
        )
    takeover["superseded_client_handoff_propagation"] = copy.deepcopy(dict(previous))
    takeover["client_handoff_host_order_correction"] = {
        "schema": "nebius-cxcli/target-takeover-client-host-order-v1",
        "status": "accepted",
        "from_hosts": list(old_hosts),
        "to_hosts": list(new_hosts),
        "superseded_proof_sha256": _fingerprint(previous),
        "accepted_at": _utc_now(),
    }
    takeover.pop("client_handoff_propagation", None)
    if checkpoint_writer is not None:
        checkpoint_writer()


def _align_target_bridge_controller_configuration_for_handoff(
    *,
    checkpoint: Mapping[str, Any],
    journal: dict[str, Any],
    takeover: dict[str, Any],
    bridge_only_config: str,
    handoff_config: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Keep bridge daemons and clients on one exact pre-fence host list."""

    namespace = str(journal.get("namespace", "") or "").strip()
    bridge_copy = _mapping(
        _mapping(_mapping(journal.get("source_configuration")).get("copies")).get("bridge")
    )
    config_map_name = str(bridge_copy.get("name", "") or "").strip()
    config_key = str(
        _mapping(journal.get("source_configuration")).get("config_key", "") or ""
    ).strip()
    if (
        str(journal.get("stage") or "") != BridgeStage.TARGET_HA_ACTIVE.value
        or str(_mapping(journal.get("authority")).get("owner") or "") != "bridge-target"
        or not namespace
        or not config_map_name
        or not config_key
    ):
        raise RuntimeError(
            "recovery-required: target handoff bridge configuration lacks its exact "
            "pre-fence authority or ConfigMap binding."
        )
    config_map = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            f"configmap/{config_map_name}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = _mapping(config_map.get("metadata"))
    current = str(_mapping(config_map.get("data")).get(config_key, "") or "")
    config_map_uid = str(metadata.get("uid", "") or "").strip()
    roles = _sequence_of_mappings(journal.get("controller_roles"))
    role_config_fingerprints = {
        str(role.get("configuration_fingerprint", "") or "").strip() for role in roles
    }
    current_sha256 = hashlib.sha256(current.encode("utf-8")).hexdigest()
    checkpointed_bridge_preimage = (
        len(role_config_fingerprints) == 1
        and "" not in role_config_fingerprints
        and current_sha256 in role_config_fingerprints
    )
    if (
        not config_map_uid
        or (
            current not in {bridge_only_config, handoff_config} and not checkpointed_bridge_preimage
        )
        or str(bridge_copy.get("uid", "") or "") != config_map_uid
    ):
        raise RuntimeError(
            "recovery-required: target handoff bridge ConfigMap changed outside its exact "
            "two-host to three-host transition."
        )
    alignment = takeover.setdefault("bridge_handoff_configuration", {})
    if not isinstance(alignment, dict):
        raise RuntimeError("Target bridge handoff configuration journal must be mutable.")
    alignment.update(
        {
            "schema": "nebius-cxcli/target-bridge-handoff-configuration-v1",
            "config_map_name": config_map_name,
            "config_map_uid": config_map_uid,
            "from_sha256": str(alignment.get("from_sha256") or current_sha256),
            "expected_bridge_only_sha256": hashlib.sha256(
                bridge_only_config.encode("utf-8")
            ).hexdigest(),
            "to_sha256": hashlib.sha256(handoff_config.encode("utf-8")).hexdigest(),
            "intent_at": str(alignment.get("intent_at") or _utc_now()),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    if current != handoff_config:
        _patch_slurm_config_map_text(
            namespace=namespace,
            name=config_map_name,
            config_key=config_key,
            slurm_conf=handoff_config,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        alignment.update({"status": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()

    pod_names = [str(role.get("pod_name", "") or "").strip() for role in roles]
    if len(pod_names) != 2 or any(not item for item in pod_names):
        raise RuntimeError(
            "recovery-required: target bridge handoff requires both exact controller roles."
        )
    bridge_workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "statefulset/cxcli-slurm-controller-bridge",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    target_container = _controller_bridge_container_name(
        bridge_workload,
        expected_image=str(
            _mapping(journal.get("version_transition")).get("target_image", "") or ""
        ),
    )
    live_jailed_digests = _controller_bridge_live_jailed_config_digests(
        namespace=namespace,
        container_name=target_container,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    rolling_phase = _mapping(
        _mapping(checkpoint.get("phase_state")).get("rolling-compute-migration")
    )
    legacy_bridge = _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge"))
    canonical_recovery = _mapping(legacy_bridge.get("canonical_payload_recovery"))
    compatible_config_map = _mapping(legacy_bridge.get("configmap"))
    compatible_source_config_map = _mapping(legacy_bridge.get("source_configmap"))
    compatible_digests = {
        str(item.get("compatible_sha256", "") or "").strip()
        for item in (compatible_config_map, compatible_source_config_map)
    }
    observed_jailed_digests = set(live_jailed_digests.values())
    expected_handoff_sha256 = hashlib.sha256(handoff_config.encode("utf-8")).hexdigest()
    expected_bridge_only_sha256 = hashlib.sha256(bridge_only_config.encode("utf-8")).hexdigest()
    checkpointed_compatible_sha256 = ""
    if len(compatible_digests) == 1 and "" not in compatible_digests:
        compatible_sha256 = next(iter(compatible_digests))
        recovery_sha256 = str(canonical_recovery.get("compatible_sha256", "") or "")
        recovery_is_valid = not canonical_recovery or (
            canonical_recovery.get("status") == "verified" and recovery_sha256 == compatible_sha256
        )
        if recovery_is_valid:
            checkpointed_compatible_sha256 = compatible_sha256
    accepted_jailed_preimages = {
        expected_handoff_sha256,
        expected_bridge_only_sha256,
        checkpointed_compatible_sha256,
        *role_config_fingerprints,
    }
    if (
        len(live_jailed_digests) != 2
        or len(observed_jailed_digests) != 1
        or not observed_jailed_digests.issubset(accepted_jailed_preimages)
    ):
        raise RuntimeError(
            "recovery-required: target bridge jailed configurations changed outside the "
            "exact checkpointed bridge-only to handoff transition."
        )
    observed_jailed_sha256 = next(iter(observed_jailed_digests))
    jailed_staging = _mapping(alignment.get("jailed_config_staging"))
    recorded_staging_target = str(jailed_staging.get("target_sha256", "") or "")
    recorded_staging_preimage = str(jailed_staging.get("expected_preimage_sha256", "") or "")
    staging_preimage_sha256 = (
        recorded_staging_preimage
        if recorded_staging_target == expected_handoff_sha256
        and re.fullmatch(r"[0-9a-f]{64}", recorded_staging_preimage)
        else observed_jailed_sha256
    )
    _stage_controller_bridge_jailed_config(
        journal=journal,
        config_map_name=config_map_name,
        config_key=config_key,
        target_config_sha256=expected_handoff_sha256,
        expected_preimage_sha256=staging_preimage_sha256,
        target_image=str(_mapping(journal.get("version_transition")).get("target_image", "") or ""),
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        staging_owner=alignment,
        staging_key="jailed_config_staging",
        pod_name_prefix="cxcli-controller-handoff-config-stager",
    )
    deadline = time.monotonic() + 180
    while True:
        observed: list[str] = []
        for pod_name in pod_names:
            result = command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    namespace,
                    "exec",
                    pod_name,
                    "-c",
                    target_container,
                    "--",
                    "cat",
                    "/etc/slurm/slurm.conf",
                ],
                check=False,
                timeout_seconds=120,
            )
            observed.append(result.stdout if result.returncode == 0 else "")
        if observed == [handoff_config, handoff_config]:
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target bridge ConfigMap accepted the three-host handoff contract, but both "
                "exact controller Pods have not observed it."
            )
        time.sleep(5)
    reconfigure = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_names[0],
            "-c",
            target_container,
            "--",
            "scontrol",
            "reconfigure",
        ],
        check=False,
        timeout_seconds=120,
    )
    if reconfigure.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "target bridge daemons observed the handoff configuration, but their guarded "
            "reconfigure did not succeed."
        )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pod_by_name = {
        str(_mapping(pod.get("metadata")).get("name", "") or ""): pod
        for pod in _sequence_of_mappings(pods_payload.get("items"))
    }
    _revalidate_target_bridge_roles(
        journal=journal,
        pod_by_name=pod_by_name,
        target_container=target_container,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    alignment.update(
        {
            "status": "verified",
            "verified_at": _utc_now(),
            "config_sha256": hashlib.sha256(handoff_config.encode("utf-8")).hexdigest(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Target bridge and clients aligned on the exact bridge-first three-host handoff "
        "configuration before fencing."
    ]


def _ensure_target_bridge_authentication_for_handoff(
    *,
    journal: dict[str, Any],
    takeover: dict[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Move the retained HA bridge to the exact target MUNGE identity while stopped."""

    namespace = str(journal.get("namespace", "") or "").strip()
    if (
        str(journal.get("stage") or "") != BridgeStage.TARGET_HA_ACTIVE.value
        or str(_mapping(journal.get("authority")).get("owner") or "") != "bridge-target"
        or not namespace
        or not target_ref
    ):
        raise RuntimeError(
            "recovery-required: target bridge authentication handoff lacks exact HA authority."
        )
    mirrored_material = journal.get("mirrored_material")
    if not isinstance(mirrored_material, list):
        raise RuntimeError("Controller bridge mirrored material journal must be mutable.")
    munge_records = [
        item
        for item in mirrored_material
        if isinstance(item, dict)
        and item.get("kind") == "Secret"
        and "munge" in str(item.get("name", "") or "").lower()
    ]
    if len(munge_records) != 1:
        raise RuntimeError(
            "recovery-required: target bridge authentication handoff requires one exact "
            "mirrored MUNGE Secret."
        )
    material_record = munge_records[0]
    bridge_secret_name = str(material_record.get("name", "") or "").strip()
    target_secret_name = f"{target_ref}-munge"
    target_secret = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"secret/{target_secret_name}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    target_metadata = _mapping(target_secret.get("metadata"))
    target_secret_uid = str(target_metadata.get("uid", "") or "").strip()
    target_material_sha256 = _controller_bridge_material_fingerprint(target_secret)
    if not target_secret_uid or not _mapping(target_secret.get("data")):
        raise SoperatorMigrationPhasePending(
            "target bridge authentication handoff requires the exact non-empty target MUNGE Secret."
        )
    bridge_secret = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            f"secret/{bridge_secret_name}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    bridge_metadata = _mapping(bridge_secret.get("metadata"))
    bridge_secret_uid = str(bridge_metadata.get("uid", "") or "").strip()
    if bridge_secret_uid != str(material_record.get("uid", "") or ""):
        raise RuntimeError(
            "recovery-required: retained bridge MUNGE Secret identity changed before handoff."
        )
    desired_bridge_secret = copy.deepcopy(dict(bridge_secret))
    desired_bridge_metadata = copy.deepcopy(dict(bridge_metadata))
    desired_annotations = copy.deepcopy(dict(_mapping(bridge_metadata.get("annotations"))))
    desired_annotations[_CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION] = target_secret_uid
    desired_bridge_metadata["annotations"] = desired_annotations
    desired_bridge_secret["metadata"] = desired_bridge_metadata
    desired_bridge_secret["data"] = copy.deepcopy(dict(_mapping(target_secret.get("data"))))
    desired_bridge_secret["binaryData"] = copy.deepcopy(
        dict(_mapping(target_secret.get("binaryData")))
    )
    desired_bridge_secret["type"] = target_secret.get("type")
    desired_material_sha256 = _controller_bridge_material_fingerprint(desired_bridge_secret)
    current_material_sha256 = _controller_bridge_material_fingerprint(bridge_secret)
    handoff = takeover.setdefault("bridge_authentication_handoff", {})
    if not isinstance(handoff, dict):
        raise RuntimeError("Target bridge authentication handoff journal must be mutable.")
    immutable_binding = {
        "bridge_secret_name": bridge_secret_name,
        "bridge_secret_uid": bridge_secret_uid,
        "target_secret_name": target_secret_name,
        "target_secret_uid": target_secret_uid,
        "target_material_sha256": target_material_sha256,
        "desired_bridge_material_sha256": desired_material_sha256,
    }
    for key, value in immutable_binding.items():
        recorded = str(handoff.get(key, "") or "")
        if recorded and recorded != value:
            raise RuntimeError(
                "recovery-required: target bridge authentication material changed after intent."
            )
    handoff.update(
        {
            "schema": "nebius-cxcli/target-bridge-authentication-handoff-v1",
            **immutable_binding,
            "source_bridge_material_sha256": str(
                handoff.get("source_bridge_material_sha256") or current_material_sha256
            ),
            "intent_at": str(handoff.get("intent_at") or _utc_now()),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()

    marker_handoff = takeover.setdefault("bridge_accounting_cluster_marker_handoff", {})
    if not isinstance(marker_handoff, dict):
        raise RuntimeError("Target bridge accounting marker handoff journal must be mutable.")
    marker_staged = marker_handoff.get("status") == "staged"

    exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    metadata = _mapping(statefulset.get("metadata"))
    status = _mapping(statefulset.get("status"))
    statefulset_uid = str(metadata.get("uid", "") or "").strip()
    replicas = _resource_replicas(statefulset, default=-1) if exists else -1
    recorded_statefulset_uid = str(handoff.get("statefulset_uid", "") or "")
    if (
        not exists
        or not statefulset_uid
        or (recorded_statefulset_uid and recorded_statefulset_uid != statefulset_uid)
        or replicas not in {0, 2}
    ):
        raise RuntimeError(
            "recovery-required: target bridge authentication handoff lost its exact "
            f"StatefulSet or 0/2 replica boundary: replicas={replicas}."
        )
    handoff["statefulset_uid"] = statefulset_uid
    if (
        handoff.get("status") == "verified"
        and replicas == 2
        and _non_negative_int(status.get("readyReplicas"), fallback=0) == 2
        and current_material_sha256 == desired_material_sha256
    ):
        handoff["revalidated_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        return ["Target MUNGE authentication handoff reused from the exact HA journal."]

    roles = _sequence_of_mappings(journal.get("controller_roles"))
    state_path = str(
        _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
    )
    target_image = str(_mapping(journal.get("version_transition")).get("target_image", "") or "")
    if len(roles) != 2 or not state_path.startswith("/") or not target_image:
        raise RuntimeError(
            "recovery-required: target bridge authentication handoff lacks historical "
            "writer nodes, state path, or target image."
        )
    incomplete_restart = (
        handoff.get("status") == "restart-dispatching"
        and _non_negative_int(status.get("readyReplicas"), fallback=0) != 2
    )
    if replicas == 2 and (
        current_material_sha256 != desired_material_sha256
        or not marker_staged
        or incomplete_restart
    ):
        pods_payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pods",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        pods = _sequence_of_mappings(pods_payload.get("items"))
        exact_pods = tuple(
            (
                namespace,
                str(_mapping(pod.get("metadata")).get("name", "") or ""),
                str(_mapping(pod.get("metadata")).get("uid", "") or ""),
            )
            for pod in pods
        )
        if len(exact_pods) != 2 or any(not name or not uid for _, name, uid in exact_pods):
            raise SoperatorMigrationPhasePending(
                "target bridge authentication handoff requires both exact live HA Pods."
            )
        recovery_without_process_census = (
            current_material_sha256 == desired_material_sha256
            and bool(_sequence_of_mappings(handoff.get("pre_stop_runtime_census")))
            and (not marker_staged or incomplete_restart)
        )
        current_census = _prove_cluster_wide_slurmctld_exclusivity(
            expected_pods=exact_pods,
            expected_workload=(
                "statefulsets.apps",
                namespace,
                "cxcli-slurm-controller-bridge",
                statefulset_uid,
            ),
            expected_replicas=2,
            proof_label="target bridge authentication handoff pre-stop runtime census",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=not recovery_without_process_census,
        )
        if current_census:
            handoff["pre_stop_runtime_census"] = current_census
        handoff.update(
            {
                "status": "stop-dispatching",
                "stop_dispatching_at": _utc_now(),
                "pre_stop_pods": [
                    {"namespace": item[0], "name": item[1], "uid": item[2]} for item in exact_pods
                ],
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        scale_exists, scale_statefulset = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
        )
        scale_metadata = _mapping(scale_statefulset.get("metadata"))
        if (
            not scale_exists
            or str(scale_metadata.get("uid", "") or "") != statefulset_uid
            or _resource_replicas(scale_statefulset, default=-1) != 2
        ):
            raise SoperatorMigrationPhasePending(
                "target bridge authentication handoff lost the exact two-replica "
                "StatefulSet after its pre-stop census."
            )
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=0,
            current_replicas=2,
            resource_version=str(scale_metadata.get("resourceVersion", "") or ""),
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "wait",
                "--for=delete",
                "pod",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "--timeout=10m",
            ],
            timeout_seconds=660,
        )
        handoff.update({"status": "stopped", "stopped_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        replicas = 0
    elif replicas == 2 and current_material_sha256 == desired_material_sha256:
        material_record.update(
            {
                "source_uid": target_secret_uid,
                "material_sha256": desired_material_sha256,
                "target_handoff": "accepted",
            }
        )
        handoff.update(
            {
                "status": "restart-accepted",
                "secret_accepted_at": str(handoff.get("secret_accepted_at") or _utc_now()),
            }
        )

    if replicas == 0:
        fence_targets = tuple(
            ControllerFenceTarget(
                node_name=str(role.get("node_name", "") or ""),
                node_uid=str(role.get("node_uid", "") or ""),
                state_markers=(state_path, "/mnt/controller-spool/current"),
            )
            for role in roles
        )
        handoff["runtime_fence"] = _prove_controller_runtime_fence(
            journal=journal,
            boundary="target-bridge-authentication-handoff",
            targets=fence_targets,
            image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="target bridge authentication handoff stopped writers",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        bridge_secret = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                f"secret/{bridge_secret_name}",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        live_metadata = _mapping(bridge_secret.get("metadata"))
        live_material_sha256 = _controller_bridge_material_fingerprint(bridge_secret)
        source_material_sha256 = str(handoff.get("source_bridge_material_sha256") or "")
        if live_material_sha256 == source_material_sha256:
            _kubectl_patch_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                resource=f"secret/{bridge_secret_name}",
                patch={
                    "metadata": {
                        "resourceVersion": str(live_metadata.get("resourceVersion", "") or ""),
                        "annotations": {
                            _CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION: target_secret_uid
                        },
                    },
                    "data": copy.deepcopy(dict(_mapping(target_secret.get("data")))),
                    "binaryData": copy.deepcopy(dict(_mapping(target_secret.get("binaryData")))),
                    "type": target_secret.get("type"),
                },
                patch_via_stdin=True,
            )
        elif live_material_sha256 != desired_material_sha256:
            raise RuntimeError(
                "recovery-required: retained bridge MUNGE Secret changed outside the exact "
                "source-to-target authentication transition."
            )
        accepted_secret = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                f"secret/{bridge_secret_name}",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        if (
            str(_mapping(accepted_secret.get("metadata")).get("uid", "") or "") != bridge_secret_uid
            or _controller_bridge_material_fingerprint(accepted_secret) != desired_material_sha256
        ):
            raise SoperatorMigrationPhasePending(
                "target bridge MUNGE Secret patch was not accepted exactly."
            )
        material_record.update(
            {
                "source_uid": target_secret_uid,
                "material_sha256": desired_material_sha256,
                "target_handoff": "accepted",
            }
        )
        handoff.update({"status": "secret-accepted", "secret_accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        _stage_target_bridge_accounting_cluster_marker(
            journal=journal,
            takeover=takeover,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        exists, stopped_statefulset = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
        )
        stopped_metadata = _mapping(stopped_statefulset.get("metadata"))
        if (
            not exists
            or str(stopped_metadata.get("uid", "") or "") != statefulset_uid
            or _resource_replicas(stopped_statefulset, default=-1) != 0
        ):
            raise RuntimeError(
                "recovery-required: target bridge authentication handoff lost the stopped "
                "StatefulSet before restart."
            )
        _revalidate_controller_authority_lease(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        handoff.update({"status": "restart-dispatching", "restart_dispatching_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=2,
            current_replicas=0,
            resource_version=str(stopped_metadata.get("resourceVersion", "") or ""),
        )

    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "rollout",
            "status",
            "statefulset/cxcli-slurm-controller-bridge",
            "--timeout=10m",
        ],
        timeout_seconds=660,
    )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pod_by_name = {
        str(_mapping(item.get("metadata")).get("name", "") or ""): item
        for item in _sequence_of_mappings(pods_payload.get("items"))
    }
    _revalidate_target_bridge_roles(
        journal=journal,
        pod_by_name=pod_by_name,
        target_container="slurmctld",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    marker_result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            "cxcli-slurm-controller-bridge-0",
            "-c",
            "slurmctld",
            "--",
            "cat",
            "/var/spool/slurmctld/clustername",
        ],
        check=False,
        timeout_seconds=120,
    )
    marker_value = marker_result.stdout.strip()
    marker_match = re.fullmatch(rf"{re.escape(target_ref)}\|([0-9]+)", marker_value)
    if marker_result.returncode != 0 or marker_match is None:
        raise SoperatorMigrationPhasePending(
            "target-authenticated bridge did not adopt the target accounting cluster ID."
        )
    marker_handoff = takeover.get("bridge_accounting_cluster_marker_handoff")
    if not isinstance(marker_handoff, dict) or marker_handoff.get("status") != "staged":
        raise RuntimeError(
            "recovery-required: target accounting cluster marker lost its staged journal."
        )
    marker_handoff.update(
        {
            "status": "verified",
            "accounting_cluster_id": marker_match.group(1),
            "verified_marker_sha256": hashlib.sha256(
                marker_result.stdout.encode("utf-8")
            ).hexdigest(),
            "verified_at": _utc_now(),
        }
    )
    exact_live_pods = tuple(
        (
            namespace,
            name,
            str(_mapping(pod.get("metadata")).get("uid", "") or ""),
        )
        for name, pod in sorted(pod_by_name.items())
    )
    if len(exact_live_pods) != 2 or any(not name or not uid for _, name, uid in exact_live_pods):
        raise SoperatorMigrationPhasePending(
            "target-authenticated bridge lacks both immutable live Pod identities."
        )
    handoff["post_restart_runtime_census"] = _prove_cluster_wide_slurmctld_exclusivity(
        expected_pods=exact_live_pods,
        expected_workload=(
            "statefulsets.apps",
            namespace,
            "cxcli-slurm-controller-bridge",
            statefulset_uid,
        ),
        expected_replicas=2,
        proof_label="target bridge authentication handoff post-restart runtime census",
        campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    handoff.update({"status": "verified", "verified_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Target MUNGE identity atomically adopted by the stopped HA bridge; primary and "
        "standby were revalidated before client RPC."
    ]


def _stage_target_bridge_accounting_cluster_marker(
    *,
    journal: dict[str, Any],
    takeover: dict[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Reset the stopped shared-state marker so target slurmdbd can assign its ID."""

    marker = takeover.setdefault("bridge_accounting_cluster_marker_handoff", {})
    if not isinstance(marker, dict):
        raise RuntimeError("Target bridge accounting marker handoff journal must be mutable.")
    recorded_target = str(marker.get("target_ref", "") or "")
    if recorded_target and recorded_target != target_ref:
        raise RuntimeError(
            "recovery-required: target accounting cluster marker changed its target."
        )
    namespace = str(journal.get("namespace", "") or "")
    if not namespace or not target_ref:
        raise RuntimeError(
            "recovery-required: target accounting cluster marker lacks its namespace or target."
        )
    script = (
        "set -eu\n"
        "marker=/shared/current/clustername\n"
        f"target={shlex.quote(target_ref)}\n"
        'test -f "$marker"\n'
        'test ! -L "$marker"\n'
        'current=$(cat "$marker")\n'
        'case "$current" in\n'
        '  "$target") ;;\n'
        '  "$target"\\|*) suffix=${current#"$target|"}; '
        'case "$suffix" in ""|*[!0-9]*) exit 1 ;; esac ;;\n'
        "  *) exit 1 ;;\n"
        "esac\n"
        'preimage_sha=$(sha256sum "$marker" | cut -d " " -f 1)\n'
        'expected_staged_sha=$(printf "%s" "$target" | sha256sum | cut -d " " -f 1)\n'
        'if test "$preimage_sha" != "$expected_staged_sha"; then\n'
        '  temporary="${marker}.cxcli-accounting.partial"\n'
        '  rm -f "$temporary"\n'
        '  cp -p "$marker" "$temporary"\n'
        '  printf "%s" "$target" > "$temporary"\n'
        '  sync -f "$temporary"\n'
        '  mv -f "$temporary" "$marker"\n'
        '  sync -f "$(dirname "$marker")"\n'
        "fi\n"
        'test "$(cat "$marker")" = "$target"\n'
        'staged_sha=$(sha256sum "$marker" | cut -d " " -f 1)\n'
        "printf 'schema=nebius-cxcli-target-accounting-cluster-marker/v1\\n"
        "preimage_sha256=%s\\nstaged_sha256=%s\\n' "
        '"$preimage_sha" "$staged_sha"\n'
    )
    marker.update(
        {
            "schema": "nebius-cxcli/target-accounting-cluster-marker-handoff-v1",
            "status": "dispatching",
            "target_ref": target_ref,
            "path": "/mnt/controller-spool/current/clustername",
            "intent_at": str(marker.get("intent_at") or _utc_now()),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            script,
        ],
        check=False,
        timeout_seconds=300,
    )
    preimage_match = re.search(r"(?m)^preimage_sha256=([0-9a-f]{64})$", result.stdout)
    staged_match = re.search(r"(?m)^staged_sha256=([0-9a-f]{64})$", result.stdout)
    if result.returncode != 0 or preimage_match is None or staged_match is None:
        raise SoperatorMigrationPhasePending(
            "stopped target bridge could not reset its accounting cluster marker exactly."
        )
    recorded_preimage = str(marker.get("preimage_sha256", "") or "")
    if recorded_preimage and recorded_preimage != preimage_match.group(1):
        expected_staged_sha256 = hashlib.sha256(target_ref.encode()).hexdigest()
        prior_staged_sha256 = str(marker.get("staged_sha256", "") or "")
        if preimage_match.group(1) not in {
            expected_staged_sha256,
            prior_staged_sha256,
        }:
            raise RuntimeError(
                "recovery-required: target accounting cluster marker preimage changed after "
                "staging intent."
            )
    marker.update(
        {
            "status": "staged",
            "preimage_sha256": recorded_preimage or preimage_match.group(1),
            "staged_sha256": staged_match.group(1),
            "staged_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()


def _controller_bridge_client_pod_identity(
    pod: Mapping[str, Any],
    *,
    container_name: str,
    role: str,
) -> dict[str, Any]:
    metadata = _mapping(pod.get("metadata"))
    spec = _mapping(pod.get("spec"))
    status = _mapping(pod.get("status"))
    name = str(metadata.get("name", "") or "").strip()
    uid = str(metadata.get("uid", "") or "").strip()
    node_name = str(spec.get("nodeName", "") or "").strip()
    containers = tuple(
        item
        for item in _sequence_of_mappings(spec.get("containers"))
        if str(item.get("name", "") or "").strip() == container_name
    )
    container_statuses = tuple(
        item
        for item in _sequence_of_mappings(status.get("containerStatuses"))
        if str(item.get("name", "") or "").strip() == container_name
    )
    container_status = container_statuses[0] if len(container_statuses) == 1 else {}
    container_id = str(container_status.get("containerID", "") or "").strip()
    restart_count = _nonnegative_int(container_status.get("restartCount"), fallback=-1)
    if (
        not name
        or not uid
        or not node_name
        or metadata.get("deletionTimestamp")
        or len(containers) != 1
        or len(container_statuses) != 1
        or not _pod_is_ready(pod)
        or container_status.get("ready") is not True
        or not _mapping(_mapping(container_status.get("state")).get("running"))
        or not container_id
        or restart_count < 0
    ):
        raise SoperatorMigrationPhasePending(
            f"controller bridge {role} client Pod {name or '<unnamed>'} is not an exact "
            f"Running/Ready {container_name} consumer with immutable runtime identity."
        )
    return {
        "role": role,
        "name": name,
        "uid": uid,
        "node_name": node_name,
        "container_name": container_name,
        "container_id": container_id,
        "restart_count": restart_count,
    }


def _controller_bridge_client_consumers(
    *,
    journal: Mapping[str, Any],
    target_ref: str,
    source_clients: bool,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    include_workers: bool = True,
) -> list[dict[str, Any]]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    pods = _sequence_of_mappings(payload.get("items"))
    pods_by_uid = {
        str(_mapping(pod.get("metadata")).get("uid", "") or "").strip(): pod for pod in pods
    }
    consumers: list[dict[str, Any]] = []
    if source_clients:
        protected = _sequence_of_mappings(
            _mapping(journal.get("login_session_handoff")).get("protected_pods")
        )
        if not protected:
            raise SoperatorMigrationPhasePending(
                "source controller fencing requires an exact protected login backend."
            )
        for binding in protected:
            uid = str(binding.get("uid", "") or "").strip()
            pod = pods_by_uid.get(uid)
            if pod is None or str(_mapping(pod.get("metadata")).get("name", "") or "") != str(
                binding.get("name", "") or ""
            ):
                raise SoperatorMigrationPhasePending(
                    "source controller fencing cannot revalidate the exact protected login "
                    f"Pod UID {uid or '<missing>'}."
                )
            identity = _controller_bridge_client_pod_identity(
                pod,
                container_name="sshd",
                role="source-login",
            )
            if identity["container_id"] != str(binding.get("container_id", "") or ""):
                raise SoperatorMigrationPhasePending(
                    "source controller fencing observed a changed protected login container "
                    f"identity for {identity['name']}."
                )
            consumers.append(identity)
    else:
        target_login_pods: list[Mapping[str, Any]] = []
        for pod in pods:
            metadata = _mapping(pod.get("metadata"))
            labels = _mapping(metadata.get("labels"))
            container_names = {
                str(item.get("name", "") or "").strip()
                for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("containers"))
            }
            if (
                labels.get("app.kubernetes.io/instance") == target_ref
                and labels.get("app.kubernetes.io/component") == "login"
                and "sshd" in container_names
            ):
                target_login_pods.append(pod)
        if not target_login_pods:
            raise SoperatorMigrationPhasePending(
                "target controller handoff requires at least one exact target-owned login "
                "Pod before bridge fencing."
            )
        consumers.extend(
            _controller_bridge_client_pod_identity(
                pod,
                container_name="sshd",
                role="target-login",
            )
            for pod in target_login_pods
        )

    if not include_workers:
        return sorted(consumers, key=lambda item: (str(item["role"]), str(item["name"])))

    worker_pods: list[Mapping[str, Any]] = []
    for pod in pods:
        metadata = _mapping(pod.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        container_names = {
            str(item.get("name", "") or "").strip()
            for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("containers"))
        }
        if "slurmd" not in container_names:
            continue
        if not source_clients and labels.get("app.kubernetes.io/instance") != target_ref:
            continue
        worker_pods.append(pod)
    if not worker_pods:
        scope = "source" if source_clients else "target-owned"
        raise SoperatorMigrationPhasePending(
            f"controller bridge client propagation found no {scope} slurmd Pods to prove."
        )
    worker_role = "source-worker" if source_clients else "target-worker"
    consumers.extend(
        _controller_bridge_client_pod_identity(
            pod,
            container_name="slurmd",
            role=worker_role,
        )
        for pod in worker_pods
    )
    return sorted(consumers, key=lambda item: (str(item["role"]), str(item["name"])))


def _controller_bridge_target_login_identity_successors(
    *,
    previous: Sequence[Mapping[str, Any]],
    current: Sequence[Mapping[str, Any]],
    config_sha256: str,
    previous_config_sha256: str | None = None,
    allow_node_replacement: bool = False,
) -> list[dict[str, str]] | None:
    """Classify only same-node, zero-restart target-login Pod successors."""

    previous_by_key = {
        (str(item.get("role", "") or ""), str(item.get("name", "") or "")): item
        for item in previous
    }
    current_by_key = {
        (str(item.get("role", "") or ""), str(item.get("name", "") or "")): item for item in current
    }
    if (
        not config_sha256
        or len(previous_by_key) != len(previous)
        or len(current_by_key) != len(current)
        or set(previous_by_key) != set(current_by_key)
    ):
        return None
    immutable_fields = (
        "role",
        "name",
        "uid",
        "node_name",
        "container_name",
        "container_id",
        "restart_count",
        "config_sha256",
    )
    prior_config_sha256 = previous_config_sha256 or config_sha256
    stable_login_fields = ("role", "name", "container_name")
    successors: list[dict[str, str]] = []
    for key, prior in previous_by_key.items():
        observed = current_by_key[key]
        identity_stable = all(
            prior.get(field) == observed.get(field)
            for field in immutable_fields
            if field != "config_sha256"
        )
        config_successor = bool(
            str(prior.get("config_sha256", "") or "") == prior_config_sha256
            and str(observed.get("config_sha256", "") or "") == config_sha256
        )
        if identity_stable and config_successor:
            continue
        prior_uid = str(prior.get("uid", "") or "").strip()
        current_uid = str(observed.get("uid", "") or "").strip()
        prior_container = str(prior.get("container_id", "") or "").strip()
        current_container = str(observed.get("container_id", "") or "").strip()
        if (
            key[0] != "target-login"
            or any(prior.get(field) != observed.get(field) for field in stable_login_fields)
            or (not allow_node_replacement and prior.get("node_name") != observed.get("node_name"))
            or str(prior.get("config_sha256", "") or "") != prior_config_sha256
            or str(observed.get("config_sha256", "") or "") != config_sha256
            or _non_negative_int(prior.get("restart_count"), fallback=-1) != 0
            or _non_negative_int(observed.get("restart_count"), fallback=-1) != 0
            or not prior_uid
            or not current_uid
            or prior_uid == current_uid
            or not prior_container
            or not current_container
            or prior_container == current_container
        ):
            return None
        successors.append(
            {
                "name": key[1],
                "previous_uid": prior_uid,
                "replacement_uid": current_uid,
                "previous_container_id": prior_container,
                "replacement_container_id": current_container,
                "node_name": str(observed.get("node_name", "") or ""),
            }
        )
    return successors or None


def _prove_controller_bridge_session_free_target_login_successors(
    *,
    previous: Sequence[Mapping[str, Any]],
    current: Sequence[Mapping[str, Any]],
    config_sha256: str,
    previous_config_sha256: str,
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    allowed_replacement_node_uids: Sequence[str] = (),
) -> list[dict[str, str]] | None:
    successors = _controller_bridge_target_login_identity_successors(
        previous=previous,
        current=current,
        config_sha256=config_sha256,
        previous_config_sha256=previous_config_sha256,
        allow_node_replacement=bool(allowed_replacement_node_uids),
    )
    if not successors:
        return None
    pod_names = tuple(item["name"] for item in successors)
    session_probe = _active_login_ssh_session_probe(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_names=pod_names,
    )
    if (
        session_probe.get("status") != "checked"
        or _non_negative_int(session_probe.get("active_sessions"), fallback=-1) != 0
    ):
        return None
    target = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "slurmcluster",
            target_ref,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    target_uid = str(_mapping(target.get("metadata")).get("uid", "") or "").strip()
    if not target_uid:
        return None
    allowed_node_uids = {
        str(uid or "").strip() for uid in allowed_replacement_node_uids if str(uid or "").strip()
    }
    for successor in successors:
        pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "pod",
                successor["name"],
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        metadata = _mapping(pod.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        owners = [
            owner
            for owner in _sequence_of_mappings(metadata.get("ownerReferences"))
            if owner.get("controller") is True
        ]
        if (
            str(metadata.get("uid", "") or "") != successor["replacement_uid"]
            or str(_mapping(pod.get("spec")).get("nodeName", "") or "") != successor["node_name"]
            or labels.get("app.kubernetes.io/instance") != target_ref
            or labels.get("app.kubernetes.io/component") != "login"
            or len(owners) != 1
            or owners[0].get("kind") != "StatefulSet"
        ):
            return None
        if allowed_node_uids:
            node = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "get",
                    "node",
                    successor["node_name"],
                    "-o",
                    "json",
                    "--request-timeout=20s",
                ],
                timeout_seconds=60,
                check=False,
            )
            if str(_mapping(node.get("metadata")).get("uid", "") or "") not in allowed_node_uids:
                return None
        workload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "statefulsets.apps.kruise.io",
                str(owners[0].get("name", "") or ""),
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        workload_metadata = _mapping(workload.get("metadata"))
        workload_owners = [
            owner
            for owner in _sequence_of_mappings(workload_metadata.get("ownerReferences"))
            if owner.get("controller") is True
        ]
        if (
            str(workload_metadata.get("uid", "") or "") != str(owners[0].get("uid", "") or "")
            or len(workload_owners) != 1
            or workload_owners[0].get("kind") != "SlurmCluster"
            or str(workload_owners[0].get("name", "") or "") != target_ref
            or str(workload_owners[0].get("uid", "") or "") != target_uid
        ):
            return None
        successor["workload_uid"] = str(workload_metadata.get("uid", "") or "")
        successor["slurmcluster_uid"] = target_uid
    return successors


def _prove_controller_bridge_client_configuration(
    *,
    journal: Mapping[str, Any],
    proof_owner: dict[str, Any],
    proof_key: str,
    proof_stage: str,
    expected_contract: Mapping[str, Any],
    expected_cluster_name: str | None = None,
    required_hosts: Sequence[str],
    target_ref: str,
    source_clients: bool,
    require_raised_timeouts: bool,
    require_live_rpc: bool,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    allowed_target_worker_replacement_node_uids: Sequence[str] = (),
    allowed_target_login_replacement_node_uids: Sequence[str] = (),
    allowed_target_worker_pod_successors: Mapping[str, Mapping[str, Any]] | None = None,
    allow_checkpointed_config_successor: bool = False,
    allow_session_free_target_login_successor: bool = False,
) -> list[str]:
    expected_sha256 = str(expected_contract.get("config_sha256", "") or "")
    expected_cluster = str(expected_contract.get("cluster_name", "") or "")
    expected_hosts = [
        str(item or "") for item in expected_contract.get("controller_hosts", []) or []
    ]
    canonical_hosts = [str(item or "") for item in required_hosts]
    expected_timeouts = {
        str(key): str(value or "")
        for key, value in _mapping(expected_contract.get("timeouts")).items()
    }
    raised_timeouts_missing = require_raised_timeouts and any(
        expected_timeouts.get(key) != "3600" for key in ("SlurmdTimeout", "SlurmctldTimeout")
    )
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_sha256)
        or expected_cluster != str(expected_cluster_name or journal.get("cluster_name", "") or "")
        or not expected_hosts
        or len(expected_hosts) != len(set(expected_hosts))
        or expected_hosts != canonical_hosts
        or raised_timeouts_missing
    ):
        raise RuntimeError(
            f"controller bridge {proof_stage} expected client configuration contract is invalid."
        )
    previous = proof_owner.get(proof_key)
    if previous is not None and not isinstance(previous, Mapping):
        raise RuntimeError(f"controller bridge {proof_stage} client proof must be a mapping.")
    if not require_live_rpc and _mapping(previous).get("status") != "verified":
        raise RuntimeError(
            f"recovery-required: controller bridge {proof_stage} was fenced without a "
            "durable successful client connectivity proof."
        )

    consumers = _controller_bridge_client_consumers(
        journal=journal,
        target_ref=target_ref,
        source_clients=source_clients,
        kube_context=kube_context,
        command_runner=command_runner,
    )

    def probe_consumer(consumer: Mapping[str, Any]) -> dict[str, Any]:
        prefix = [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            str(consumer["name"]),
            "-c",
            str(consumer["container_name"]),
            "--",
        ]
        observed_contract: Mapping[str, Any] = {}
        last_config_error = "stale or non-canonical jailed Slurm configuration"
        # SFS-backed jail propagation can legitimately take longer than 25
        # seconds under controller reconciliation load. Keep the proof bounded,
        # but avoid forcing an expensive full-command resume for normal delay.
        for attempt in range(12):
            config = command_runner(
                [*prefix, "cat", _SOPERATOR_LEGACY_SLURM_CONF],
                check=False,
                timeout_seconds=120,
            )
            if config.returncode != 0:
                last_config_error = "cannot read the jailed slurm.conf"
                observed_contract = {}
            else:
                try:
                    observed_contract = _controller_bridge_client_config_contract(config.stdout)
                except RuntimeError:
                    last_config_error = (
                        "has an invalid or partially propagated jailed Slurm configuration"
                    )
                    observed_contract = {}
                else:
                    observed_timeouts = _mapping(observed_contract.get("timeouts"))
                    observed_timeouts_missing = require_raised_timeouts and any(
                        observed_timeouts.get(key) != "3600"
                        for key in ("SlurmdTimeout", "SlurmctldTimeout")
                    )
                    if (
                        observed_contract["config_sha256"] == expected_sha256
                        and observed_contract["cluster_name"] == expected_cluster
                        and observed_contract["controller_hosts"] == expected_hosts
                        and not observed_timeouts_missing
                    ):
                        break
                    last_config_error = "has stale or non-canonical jailed Slurm configuration"
            if attempt < 11:
                time.sleep(5)
        else:
            raise SoperatorMigrationPhasePending(
                f"controller bridge {proof_stage} client {consumer['name']} {last_config_error}."
            )
        rpc_evidence: dict[str, str] = {}
        if require_live_rpc:
            for action, command in (
                ("ping", ("scontrol", "ping")),
                ("show_config", ("scontrol", "show", "config")),
            ):
                result = command_runner(
                    [
                        *prefix,
                        "env",
                        f"SLURM_CONF={_SOPERATOR_LEGACY_SLURM_CONF}",
                        *command,
                    ],
                    check=False,
                    timeout_seconds=120,
                )
                if result.returncode != 0:
                    raise SoperatorMigrationPhasePending(
                        f"controller bridge {proof_stage} client {consumer['name']} failed "
                        f"its direct {action.replace('_', ' ')} RPC."
                    )
                if action == "ping" and not re.search(
                    r"Slurmctld\([^)]*\).*\bis\s+UP\b",
                    result.stdout,
                    re.IGNORECASE,
                ):
                    raise SoperatorMigrationPhasePending(
                        f"controller bridge {proof_stage} client {consumer['name']} did not "
                        "observe an UP controller authority."
                    )
                if action == "show_config":
                    cluster_match = re.search(
                        r"(?im)^\s*ClusterName\s*=\s*(\S+)\s*$", result.stdout
                    )
                    if not cluster_match or cluster_match.group(1) != expected_cluster:
                        raise SoperatorMigrationPhasePending(
                            f"controller bridge {proof_stage} client {consumer['name']} "
                            "resolved a different controller configuration."
                        )
                rpc_evidence[f"{action}_sha256"] = hashlib.sha256(
                    result.stdout.encode("utf-8")
                ).hexdigest()
        return {
            **consumer,
            "config_sha256": observed_contract["config_sha256"],
            **rpc_evidence,
        }

    # Each consumer keeps the complete config + ping + show-config proof.  The
    # probes are independent read-only subprocesses, so bounding them in parallel
    # avoids an O(worker count) latency multiplier on large fixed worker groups.
    max_probe_workers = min(32, len(consumers))
    if max_probe_workers <= 1:
        evidence = [probe_consumer(consumers[0])]
    else:
        with ThreadPoolExecutor(max_workers=max_probe_workers) as executor:
            evidence = list(executor.map(probe_consumer, consumers))

    immutable_fields = (
        "role",
        "name",
        "uid",
        "node_name",
        "container_name",
        "container_id",
        "restart_count",
        "config_sha256",
    )
    previous_evidence = _sequence_of_mappings(_mapping(previous).get("consumers"))
    consumer_successors = list(
        copy.deepcopy(
            to_plain_data(
                _mapping(previous).get("consumer_successors", [])
                if isinstance(_mapping(previous).get("consumer_successors"), list)
                else []
            )
        )
    )
    if previous_evidence:
        old = [tuple(item.get(field) for field in immutable_fields) for item in previous_evidence]
        new = [tuple(item.get(field) for field in immutable_fields) for item in evidence]
        previous_config_sha256 = str(_mapping(previous).get("config_sha256", "") or "")
        if old != new or previous_config_sha256 != expected_sha256:
            stable_identity_fields = tuple(
                field for field in immutable_fields if field != "config_sha256"
            )
            config_successor_valid = bool(
                allow_checkpointed_config_successor
                and previous_config_sha256
                and previous_config_sha256 != expected_sha256
                and _mapping(previous).get("cluster_name") == expected_cluster
                and _mapping(previous).get("controller_hosts") == expected_hosts
                and [
                    tuple(item.get(field) for field in stable_identity_fields)
                    for item in previous_evidence
                ]
                == [tuple(item.get(field) for field in stable_identity_fields) for item in evidence]
                and all(
                    str(item.get("config_sha256", "") or "") == previous_config_sha256
                    for item in previous_evidence
                )
                and all(
                    str(item.get("config_sha256", "") or "") == expected_sha256 for item in evidence
                )
            )
            if config_successor_valid:
                consumer_successors.append(
                    {
                        "kind": "checkpointed-client-config-reconciliation",
                        "previous_config_sha256": previous_config_sha256,
                        "replacement_config_sha256": expected_sha256,
                        "previous_consumers_sha256": _fingerprint(previous_evidence),
                        "replacement_consumers_sha256": _fingerprint(evidence),
                        "accepted_at": _utc_now(),
                    }
                )
                old = new
            login_successors = (
                _prove_controller_bridge_session_free_target_login_successors(
                    previous=previous_evidence,
                    current=evidence,
                    config_sha256=expected_sha256,
                    previous_config_sha256=previous_config_sha256,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
                if allow_session_free_target_login_successor and previous_config_sha256
                else None
            )
            login_successor_valid = bool(login_successors)
            if login_successor_valid:
                consumer_successors.append(
                    {
                        "kind": "checkpointed-session-free-target-login-replacement",
                        "previous_consumers_sha256": _fingerprint(previous_evidence),
                        "replacement_consumers_sha256": _fingerprint(evidence),
                        "logins": login_successors,
                        "accepted_at": _utc_now(),
                    }
                )
                old = new
            previous_by_key = {
                (str(item.get("role", "") or ""), str(item.get("name", "") or "")): item
                for item in previous_evidence
            }
            evidence_by_key = {
                (str(item.get("role", "") or ""), str(item.get("name", "") or "")): item
                for item in evidence
            }
            mixed_successors: list[dict[str, str]] = []
            changed_logins: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
            worker_pod_successors = _mapping(allowed_target_worker_pod_successors)
            mixed_successor_valid = bool(
                not config_successor_valid
                and not login_successor_valid
                and previous_config_sha256 == expected_sha256
                and len(previous_by_key) == len(previous_evidence)
                and len(evidence_by_key) == len(evidence)
                and set(previous_by_key) == set(evidence_by_key)
            )
            if mixed_successor_valid:
                for key, prior in previous_by_key.items():
                    observed = evidence_by_key[key]
                    if tuple(prior.get(field) for field in immutable_fields) == tuple(
                        observed.get(field) for field in immutable_fields
                    ):
                        continue
                    if (
                        prior.get("config_sha256") != expected_sha256
                        or observed.get("config_sha256") != expected_sha256
                        or prior.get("container_name") != observed.get("container_name")
                        or _non_negative_int(observed.get("restart_count"), fallback=-1) != 0
                    ):
                        mixed_successor_valid = False
                        break
                    if key[0] == "target-login":
                        changed_logins.append((prior, observed))
                        continue
                    successor = _mapping(worker_pod_successors.get(key[1]))
                    if (
                        key[0] != "target-worker"
                        or str(prior.get("uid", "") or "")
                        != str(successor.get("previous_uid", "") or "")
                        or str(observed.get("uid", "") or "")
                        != str(successor.get("replacement_uid", "") or "")
                        or str(prior.get("node_name", "") or "")
                        != str(successor.get("node_name", "") or "")
                        or str(observed.get("node_name", "") or "")
                        != str(successor.get("node_name", "") or "")
                    ):
                        mixed_successor_valid = False
                        break
                    mixed_successors.append(
                        {
                            "role": key[0],
                            "name": key[1],
                            "previous_uid": str(prior.get("uid", "") or ""),
                            "replacement_uid": str(observed.get("uid", "") or ""),
                            "node_name": str(observed.get("node_name", "") or ""),
                            "boundary": "gpu-typed-gres-worker-rollover",
                        }
                    )
            if mixed_successor_valid and changed_logins:
                login_successors = _prove_controller_bridge_session_free_target_login_successors(
                    previous=[item[0] for item in changed_logins],
                    current=[item[1] for item in changed_logins],
                    config_sha256=expected_sha256,
                    previous_config_sha256=previous_config_sha256,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    allowed_replacement_node_uids=allowed_target_login_replacement_node_uids,
                )
                mixed_successor_valid = bool(login_successors)
                if login_successors:
                    mixed_successors.extend(
                        {
                            "role": "target-login",
                            "name": item["name"],
                            "previous_uid": item["previous_uid"],
                            "replacement_uid": item["replacement_uid"],
                            "node_name": item["node_name"],
                            "boundary": "completed-login-provider-rollover",
                        }
                        for item in login_successors
                    )
            mixed_successor_valid = mixed_successor_valid and bool(mixed_successors)
            if mixed_successor_valid:
                consumer_successors.append(
                    {
                        "kind": "checkpointed-mixed-target-client-replacements",
                        "previous_consumers_sha256": _fingerprint(previous_evidence),
                        "replacement_consumers_sha256": _fingerprint(evidence),
                        "replacements": mixed_successors,
                        "accepted_at": _utc_now(),
                    }
                )
                old = new
            allowed_node_uids = {
                str(uid or "").strip()
                for uid in allowed_target_worker_replacement_node_uids
                if str(uid or "").strip()
            }
            successor_valid = (
                config_successor_valid
                or login_successor_valid
                or mixed_successor_valid
                or bool(
                    previous_config_sha256 == expected_sha256
                    and allowed_node_uids
                    and len(previous_by_key) == len(previous_evidence)
                    and len(evidence_by_key) == len(evidence)
                    and set(previous_by_key) == set(evidence_by_key)
                )
            )
            changed_workers: list[dict[str, str]] = []
            node_uids_by_name: dict[str, str] = {}
            if (
                successor_valid
                and not config_successor_valid
                and not login_successor_valid
                and not mixed_successor_valid
            ):
                nodes_payload = _json_from_command(
                    command_runner,
                    [
                        "kubectl",
                        "--context",
                        kube_context,
                        "get",
                        "nodes",
                        "-o",
                        "json",
                        "--request-timeout=20s",
                    ],
                    timeout_seconds=60,
                    check=False,
                )
                node_uids_by_name = {
                    str(_mapping(node.get("metadata")).get("name", "") or ""): str(
                        _mapping(node.get("metadata")).get("uid", "") or ""
                    )
                    for node in _sequence_of_mappings(nodes_payload.get("items"))
                }
                for key, prior in previous_by_key.items():
                    observed = evidence_by_key[key]
                    prior_identity = tuple(prior.get(field) for field in immutable_fields)
                    observed_identity = tuple(observed.get(field) for field in immutable_fields)
                    if prior_identity == observed_identity:
                        continue
                    if key[0] != "target-worker":
                        successor_valid = False
                        break
                    stable_fields = ("role", "name", "container_name", "config_sha256")
                    observed_node_uid = node_uids_by_name.get(
                        str(observed.get("node_name", "") or ""), ""
                    )
                    if (
                        any(prior.get(field) != observed.get(field) for field in stable_fields)
                        or _nonnegative_int(observed.get("restart_count"), fallback=-1) != 0
                        or observed_node_uid not in allowed_node_uids
                    ):
                        successor_valid = False
                        break
                    changed_workers.append(
                        {
                            "name": key[1],
                            "previous_uid": str(prior.get("uid", "") or ""),
                            "replacement_uid": str(observed.get("uid", "") or ""),
                            "replacement_node_uid": observed_node_uid,
                        }
                    )
                successor_valid = successor_valid and bool(changed_workers)
            if not successor_valid:
                raise RuntimeError(
                    f"recovery-required: controller bridge {proof_stage} client Pod identity "
                    "or jailed configuration changed after durable proof."
                )
            if (
                not config_successor_valid
                and not login_successor_valid
                and not mixed_successor_valid
            ):
                consumer_successors.append(
                    {
                        "kind": "checkpointed-worker-provider-replacement",
                        "previous_consumers_sha256": _fingerprint(previous_evidence),
                        "replacement_consumers_sha256": _fingerprint(evidence),
                        "workers": changed_workers,
                        "accepted_at": _utc_now(),
                    }
                )
        if not require_live_rpc:
            previous_by_uid = {str(item.get("uid", "") or ""): item for item in previous_evidence}
            for item in evidence:
                prior = previous_by_uid[str(item["uid"])]
                for field in (
                    "ping_sha256",
                    "show_config_sha256",
                ):
                    item[field] = str(prior.get(field, "") or "")
    timestamp = _utc_now()
    proof_owner[proof_key] = {
        "schema": "nebius-cxcli-controller-client-propagation/v1",
        "status": "verified",
        "proof_stage": proof_stage,
        "cluster_name": expected_cluster,
        "controller_hosts": expected_hosts,
        "timeouts": expected_timeouts,
        "config_sha256": expected_sha256,
        "consumers": evidence,
        "consumer_successors": consumer_successors,
        "live_rpc_verified": require_live_rpc
        or _mapping(previous).get("live_rpc_verified") is True,
        "verified_at": str(_mapping(previous).get("verified_at", "") or "") or timestamp,
        "revalidated_at": timestamp,
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    login_count = sum(1 for item in evidence if str(item["role"]).endswith("login"))
    worker_count = sum(1 for item in evidence if str(item["role"]).endswith("worker"))
    return [
        f"Slurm client propagation {proof_stage}: exact jailed config and immutable Pod "
        f"identity proved on {login_count} login and {worker_count} worker client(s)"
        + (" with non-mutating direct ping/config visibility." if require_live_rpc else ".")
    ]


def _repair_in_place_login_bridge_config_propagation(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    expected_contract: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Serially recreate session-free login Pods whose jailed config predates the bridge."""

    expected_sha256 = str(expected_contract.get("config_sha256") or "").strip()
    expected_cluster = str(expected_contract.get("cluster_name") or "").strip()
    expected_hosts = list(expected_contract.get("controller_hosts") or [])
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_sha256)
        or expected_cluster != target_ref
        or not expected_hosts
    ):
        raise RuntimeError("in-place login bridge propagation expected contract is invalid.")
    handoff = phase.setdefault("in_place_bridge_client_handoff", {})
    if not isinstance(handoff, dict):
        raise RuntimeError("In-place bridge client handoff journal must be a mapping.")
    rollout = handoff.setdefault("login_config_rollout", {})
    if not isinstance(rollout, dict):
        raise RuntimeError("In-place login bridge config rollout must be a mapping.")
    pod_journal = rollout.setdefault("pods", {})
    if not isinstance(pod_journal, dict):
        raise RuntimeError("In-place login bridge config Pod journal must be a mapping.")

    def _observed_contract(consumer: Mapping[str, Any]) -> Mapping[str, Any]:
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                str(consumer["name"]),
                "-c",
                str(consumer["container_name"]),
                "--",
                "cat",
                _SOPERATOR_LEGACY_SLURM_CONF,
            ],
            check=False,
            timeout_seconds=120,
        )
        if result.returncode != 0:
            return {}
        try:
            return _controller_bridge_client_config_contract(result.stdout)
        except RuntimeError:
            return {}

    def _matches_expected(consumer: Mapping[str, Any]) -> bool:
        observed = _observed_contract(consumer)
        return bool(
            observed.get("config_sha256") == expected_sha256
            and observed.get("cluster_name") == expected_cluster
            and observed.get("controller_hosts") == expected_hosts
        )

    changed: list[str] = []
    for _attempt in range(3):
        consumers = _controller_bridge_client_consumers(
            journal=_mapping(checkpoint.get("controller_bridge")),
            target_ref=target_ref,
            source_clients=False,
            kube_context=kube_context,
            command_runner=command_runner,
            include_workers=False,
        )
        stale: list[dict[str, Any]] = []
        for consumer in consumers:
            if consumer.get("role") != "target-login":
                continue
            if _matches_expected(consumer):
                pod_journal[str(consumer["name"])] = {
                    "status": "verified",
                    "uid": str(consumer["uid"]),
                    "config_sha256": expected_sha256,
                    "verified_at": _utc_now(),
                }
            else:
                stale.append(consumer)
        if checkpoint_writer is not None:
            checkpoint_writer()
        if not stale:
            rollout.update(
                {
                    "status": "verified",
                    "config_sha256": expected_sha256,
                    "verified_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return (
                [
                    "In-place controller safety: recreated session-free login Pods so "
                    "their jailed Slurm configuration is pinned exclusively to the bridge."
                ]
                if changed
                else []
            )

        consumer = sorted(stale, key=lambda item: str(item["name"]))[0]
        pod_name = str(consumer["name"])
        session_probe = _active_login_ssh_session_probe(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_names=(pod_name,),
        )
        if (
            session_probe.get("status") != "checked"
            or _non_negative_int(session_probe.get("active_sessions"), fallback=-1) != 0
        ):
            raise SoperatorMigrationPhasePending(
                f"login Pod {pod_name} has stale bridge configuration but is not proven "
                "session-free; controller nodes remain protected by the bridge."
            )
        wait_for_login_service_ready_endpoints(
            command_runner,
            namespace=_SOPERATOR_NAMESPACE,
            target_ref=target_ref,
            kube_context=kube_context,
            min_ready_endpoints=2,
            timeout_seconds=0,
        )
        live_pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "pod",
                pod_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        metadata = _mapping(live_pod.get("metadata"))
        live_uid = str(metadata.get("uid") or "").strip()
        resource_version = str(metadata.get("resourceVersion") or "").strip()
        if live_uid != str(consumer["uid"]) or not resource_version:
            raise SoperatorMigrationPhasePending(
                f"login Pod {pod_name} changed while binding its bridge config restart."
            )
        pod_journal[pod_name] = {
            "status": "recreating",
            "source_uid": live_uid,
            "config_sha256": expected_sha256,
            "session_probe": session_probe,
            "started_at": _utc_now(),
        }
        rollout.update({"status": "recreating", "config_sha256": expected_sha256})
        if checkpoint_writer is not None:
            checkpoint_writer()
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/pods/{pod_name}",
            uid=live_uid,
            resource_version=resource_version,
            propagation_policy="Foreground",
            timeout_seconds=300,
        )
        deadline = time.monotonic() + 600
        while True:
            replacement = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    "pod",
                    pod_name,
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
                check=False,
            )
            replacement_uid = str(_mapping(replacement.get("metadata")).get("uid") or "").strip()
            if replacement_uid and replacement_uid != live_uid and _pod_is_ready(replacement):
                try:
                    wait_for_login_service_ready_endpoints(
                        command_runner,
                        namespace=_SOPERATOR_NAMESPACE,
                        target_ref=target_ref,
                        kube_context=kube_context,
                        min_ready_endpoints=2,
                        timeout_seconds=0,
                    )
                except SoperatorMigrationPhasePending:
                    pass
                else:
                    pod_journal[pod_name] = {
                        "status": "ready-awaiting-config",
                        "source_uid": live_uid,
                        "replacement_uid": replacement_uid,
                        "config_sha256": expected_sha256,
                        "ready_at": _utc_now(),
                    }
                    if checkpoint_writer is not None:
                        checkpoint_writer()
                    replacement_consumer = {
                        **consumer,
                        "uid": replacement_uid,
                    }
                    propagation_deadline = time.monotonic() + 180
                    while not _matches_expected(replacement_consumer):
                        if time.monotonic() >= propagation_deadline:
                            raise SoperatorMigrationPhasePending(
                                f"login Pod {pod_name} is Ready after its one serial restart, "
                                "but its exact jailed bridge configuration is still "
                                "propagating; resume will observe it without deleting the "
                                "same healthy replacement again."
                            )
                        time.sleep(5)
                    pod_journal[pod_name].update(
                        {
                            "status": "verified",
                            "verified_at": _utc_now(),
                        }
                    )
                    if checkpoint_writer is not None:
                        checkpoint_writer()
                    changed.append(pod_name)
                    break
            if time.monotonic() >= deadline:
                raise SoperatorMigrationPhasePending(
                    f"login Pod {pod_name} did not return Ready behind both preserved "
                    "Service endpoints after its bridge configuration restart."
                )
            time.sleep(5)
    raise SoperatorMigrationPhasePending(
        "login bridge configuration remained stale after serial session-free Pod restarts."
    )


def _controller_bridge_config_map_data_sha256(data: Mapping[str, Any]) -> str:
    normalized = {str(key): str(value) for key, value in sorted(data.items())}
    return hashlib.sha256(_stable_json(normalized).encode("utf-8")).hexdigest()


def _controller_bridge_live_config_map(
    *,
    namespace: str,
    name: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, str]]:
    live = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "configmap",
            name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = dict(_mapping(live.get("metadata")))
    data = _mapping(live.get("data"))
    if (
        str(live.get("apiVersion", "") or "") != "v1"
        or str(live.get("kind", "") or "") != "ConfigMap"
        or str(metadata.get("namespace", "") or "") != namespace
        or str(metadata.get("name", "") or "") != name
        or not str(metadata.get("uid", "") or "").strip()
        or not str(metadata.get("resourceVersion", "") or "").strip()
        or any(
            not isinstance(key, str) or not isinstance(value, str) for key, value in data.items()
        )
    ):
        raise RuntimeError(
            "recovery-required: controller bridge ConfigMap lacks its exact "
            f"v1 identity or string data contract: {namespace}/{name}."
        )
    return dict(live), metadata, dict(data)


def _controller_bridge_slurm_conf_entry(
    data: Mapping[str, str],
    *,
    config_key: str,
) -> tuple[str, str]:
    value = data.get(config_key)
    if not isinstance(value, str) or not value.strip():
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires the active JailedConfig slurm.conf key to map "
            f"to one non-empty ConfigMap entry: {config_key}."
        )
    if not re.search(r"(?im)^\s*ClusterName\s*=\s*\S+\s*$", value):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge active JailedConfig slurm.conf entry lacks exactly "
            "identifiable Slurm cluster content."
        )
    return config_key, value


def _controller_bridge_json_pointer_token(value: str) -> str:
    return value.replace("~", "~0").replace("/", "~1")


def _controller_bridge_active_slurm_configuration(
    *,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[dict[str, str], dict[str, Any], dict[str, Any], dict[str, str]]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "jailedconfigs.slurm.nebius.ai",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    candidates: list[tuple[dict[str, Any], dict[str, Any], str]] = []
    for jailed_config in _sequence_of_mappings(payload.get("items")):
        spec = _mapping(jailed_config.get("spec"))
        config_map_name = str(_mapping(spec.get("configMap")).get("name", "") or "").strip()
        for item in _sequence_of_mappings(spec.get("items")):
            if str(item.get("path", "") or "").strip() == "/etc/slurm/slurm.conf":
                candidates.append((dict(jailed_config), dict(item), config_map_name))
    if len(candidates) != 1:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge requires exactly one JailedConfig item mapped to "
            f"/etc/slurm/slurm.conf; found {len(candidates)}."
        )
    jailed_config, item, config_map_name = candidates[0]
    jailed_metadata = _mapping(jailed_config.get("metadata"))
    config_key = str(item.get("key", "") or "").strip()
    if (
        str(jailed_config.get("apiVersion", "") or "") != "slurm.nebius.ai/v1alpha1"
        or str(jailed_config.get("kind", "") or "") != "JailedConfig"
        or str(jailed_metadata.get("namespace", "") or "") != _SOPERATOR_NAMESPACE
        or not str(jailed_metadata.get("name", "") or "").strip()
        or not str(jailed_metadata.get("uid", "") or "").strip()
        or not str(jailed_metadata.get("resourceVersion", "") or "").strip()
        or not config_map_name
        or not config_key
    ):
        raise RuntimeError(
            "recovery-required: active Slurm JailedConfig lacks its exact API identity, "
            "ConfigMap reference, or slurm.conf key."
        )
    source_live, source_metadata, source_data = _controller_bridge_live_config_map(
        namespace=_SOPERATOR_NAMESPACE,
        name=config_map_name,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    detected_key, _slurm_conf = _controller_bridge_slurm_conf_entry(
        source_data,
        config_key=config_key,
    )
    if detected_key != config_key:
        raise RuntimeError(
            "recovery-required: active Slurm JailedConfig key does not match the exact "
            "slurm.conf entry in its referenced ConfigMap."
        )
    return (
        {
            "jailed_config_name": str(jailed_metadata.get("name", "") or ""),
            "jailed_config_uid": str(jailed_metadata.get("uid", "") or ""),
            "jailed_config_resource_version": str(jailed_metadata.get("resourceVersion", "") or ""),
            "config_map_name": config_map_name,
            "config_map_uid": str(source_metadata.get("uid", "") or ""),
            "config_key": config_key,
            "path": "/etc/slurm/slurm.conf",
        },
        source_live,
        source_metadata,
        source_data,
    )


def _ensure_controller_bridge_active_slurm_config_mirror(
    *,
    journal: dict[str, Any],
    source_live: Mapping[str, Any],
    source_metadata: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, str]]:
    namespace = str(journal.get("namespace", "") or "").strip()
    name = str(source_metadata.get("name", "") or "").strip()
    source_uid = str(source_metadata.get("uid", "") or "").strip()
    source_resource_version = str(source_metadata.get("resourceVersion", "") or "").strip()
    campaign_fingerprint = str(journal.get("campaign_fingerprint", "") or "").strip()
    cluster_id = str(journal.get("cluster_id", "") or "").strip()
    if not all(
        (
            namespace,
            name,
            source_uid,
            source_resource_version,
            campaign_fingerprint,
            cluster_id,
        )
    ):
        raise RuntimeError(
            "recovery-required: active Slurm ConfigMap mirror lacks an exact campaign, "
            "cluster, namespace, or source identity."
        )
    desired: dict[str, Any] = {
        "apiVersion": "v1",
        "kind": "ConfigMap",
        "metadata": {
            "namespace": namespace,
            "name": name,
            "labels": {
                "app.kubernetes.io/managed-by": "nebius-cxcli",
                CONTROLLER_BRIDGE_LABEL: "true",
            },
            "annotations": {
                _CONTROLLER_BRIDGE_CAMPAIGN_ANNOTATION: campaign_fingerprint,
                _CONTROLLER_BRIDGE_CLUSTER_ANNOTATION: cluster_id,
                _CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION: source_uid,
                "nebius.ai/cxcli-source-resource-version": source_resource_version,
            },
        },
    }
    for field in ("data", "binaryData", "immutable"):
        if field in source_live:
            desired[field] = copy.deepcopy(to_plain_data(source_live[field]))
    identity = _controller_bridge_object_identity(desired)
    exists, live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity=identity,
    )
    if not exists:
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=(desired,),
        )
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=identity,
        )
    live_metadata = _mapping(live.get("metadata"))
    live_annotations = _mapping(live_metadata.get("annotations"))
    live_labels = _mapping(live_metadata.get("labels"))
    if (
        not exists
        or str(live_metadata.get("uid", "") or "") == ""
        or live_labels.get("app.kubernetes.io/managed-by") != "nebius-cxcli"
        or live_labels.get(CONTROLLER_BRIDGE_LABEL) != "true"
        or any(
            live_annotations.get(key) != value
            for key, value in _mapping(desired["metadata"]).get("annotations", {}).items()
        )
        or _controller_bridge_material_fingerprint(live)
        != _controller_bridge_material_fingerprint(desired)
    ):
        raise RuntimeError(
            "recovery-required: active Slurm ConfigMap mirror is absent, foreign, or "
            f"changed: {namespace}/{name}."
        )
    record = {
        "kind": "ConfigMap",
        "name": name,
        "uid": str(live_metadata.get("uid", "") or ""),
        "source_uid": source_uid,
        "material_sha256": _controller_bridge_material_fingerprint(live),
    }
    mirrored_records = journal.get("mirrored_material")
    if not isinstance(mirrored_records, list):
        raise RuntimeError("Controller bridge mirrored material journal must be mutable.")
    matches = [
        item
        for item in mirrored_records
        if isinstance(item, dict) and item.get("kind") == "ConfigMap" and item.get("name") == name
    ]
    if len(matches) > 1:
        raise RuntimeError("recovery-required: active Slurm ConfigMap mirror is duplicated.")
    if matches:
        if matches[0] != record:
            raise RuntimeError(
                "recovery-required: active Slurm ConfigMap mirror changed after checkpoint."
            )
    else:
        mirrored_records.append(record)
        resources = journal.get("kubernetes_resources")
        if not isinstance(resources, list):
            raise RuntimeError("Controller bridge Kubernetes resource journal must be mutable.")
        resources.append(_controller_bridge_object_identity(live))
        checkpoint_writer()
    return dict(live), dict(live_metadata), dict(_mapping(live.get("data")))


def _controller_bridge_source_configuration_intent(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None],
) -> dict[str, Any]:
    bridge_namespace = str(journal.get("namespace", "") or "").strip()
    if not bridge_namespace:
        raise RuntimeError("Controller bridge source configuration lacks a bridge namespace.")
    source_reference, source_live, source_metadata, source_data = (
        _controller_bridge_active_slurm_configuration(
            kube_context=kube_context,
            command_runner=command_runner,
        )
    )
    name = source_reference["config_map_name"]
    bridge_live, bridge_metadata, bridge_data = (
        _ensure_controller_bridge_active_slurm_config_mirror(
            journal=journal,
            source_live=source_live,
            source_metadata=source_metadata,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    config_key, original_slurm_conf = _controller_bridge_slurm_conf_entry(
        source_data,
        config_key=source_reference["config_key"],
    )
    bridge_config_key, bridge_slurm_conf = _controller_bridge_slurm_conf_entry(
        bridge_data,
        config_key=source_reference["config_key"],
    )
    if config_key != source_reference["config_key"]:
        raise RuntimeError(
            "recovery-required: active Slurm ConfigMap key changed after JailedConfig proof."
        )
    if bridge_config_key != config_key or bridge_slurm_conf != original_slurm_conf:
        raise RuntimeError(
            "recovery-required: bridge ConfigMap does not match the exact source slurm.conf "
            "preimage."
        )
    source_uid = str(source_metadata.get("uid", "") or "")
    bridge_uid = str(bridge_metadata.get("uid", "") or "")
    bridge_annotations = _mapping(bridge_metadata.get("annotations"))
    mirrored_records = journal.get("mirrored_material")
    if not isinstance(mirrored_records, list):
        raise RuntimeError("Controller bridge mirrored material journal must be mutable.")
    record = next(
        (
            item
            for item in mirrored_records
            if isinstance(item, dict)
            and item.get("kind") == "ConfigMap"
            and item.get("name") == name
        ),
        None,
    )
    source_uid_annotation = str(
        bridge_annotations.get(_CONTROLLER_BRIDGE_SOURCE_UID_ANNOTATION, "") or ""
    )
    bridge_preimage_material_sha256 = _controller_bridge_material_fingerprint(bridge_live)
    if (
        not isinstance(record, dict)
        or str(record.get("uid", "") or "") != bridge_uid
        or str(record.get("source_uid", "") or "") != source_uid
        or source_uid_annotation != source_uid
        or str(record.get("material_sha256", "") or "") != bridge_preimage_material_sha256
    ):
        raise RuntimeError(
            "recovery-required: bridge ConfigMap immutable source/bridge binding changed "
            f"before configuration intent: {name}."
        )
    original_data_sha256 = _controller_bridge_config_map_data_sha256(source_data)
    if _controller_bridge_config_map_data_sha256(bridge_data) != original_data_sha256:
        raise RuntimeError(
            "recovery-required: source and bridge ConfigMap data differ before configuration intent."
        )
    intended_slurm_conf, original_timeouts = _bridge_slurm_config_with_timeouts(original_slurm_conf)
    if intended_slurm_conf == original_slurm_conf:
        raise RuntimeError("Controller bridge source configuration intent is a no-op.")
    intended_source_data = {**source_data, config_key: intended_slurm_conf}
    intended_bridge_data = {**bridge_data, config_key: intended_slurm_conf}
    intended_data_sha256 = _controller_bridge_config_map_data_sha256(intended_source_data)
    if _controller_bridge_config_map_data_sha256(intended_bridge_data) != intended_data_sha256:
        raise RuntimeError("Controller bridge intended ConfigMap copies are not identical.")
    source_intended_live = copy.deepcopy(source_live)
    source_intended_live["data"] = intended_source_data
    bridge_intended_live = copy.deepcopy(bridge_live)
    bridge_intended_live["data"] = intended_bridge_data
    intent_at = _utc_now()
    configuration: dict[str, Any] = {
        "schema": CONTROLLER_BRIDGE_SOURCE_CONFIGURATION_SCHEMA,
        "config_map_names": [name],
        "source_reference": source_reference,
        "config_key": config_key,
        "original_slurm_conf": original_slurm_conf,
        "original_slurm_conf_sha256": hashlib.sha256(
            original_slurm_conf.encode("utf-8")
        ).hexdigest(),
        "intended_slurm_conf": intended_slurm_conf,
        "intended_slurm_conf_sha256": hashlib.sha256(
            intended_slurm_conf.encode("utf-8")
        ).hexdigest(),
        "original_config_data_sha256": original_data_sha256,
        "intended_config_data_sha256": intended_data_sha256,
        "original_timeouts": original_timeouts,
        "bridge_config_sha256": hashlib.sha256(intended_slurm_conf.encode("utf-8")).hexdigest(),
        "client_config_contract": _controller_bridge_client_config_contract(intended_slurm_conf),
        "intent_at": intent_at,
        "copies": {
            "source": {
                "namespace": _SOPERATOR_NAMESPACE,
                "name": name,
                "uid": source_uid,
                "intent_resource_version": str(source_metadata.get("resourceVersion", "") or ""),
                "preimage_data_sha256": original_data_sha256,
                "intended_data_sha256": intended_data_sha256,
                "preimage_material_sha256": _controller_bridge_material_fingerprint(source_live),
                "intended_material_sha256": _controller_bridge_material_fingerprint(
                    source_intended_live
                ),
                "state": "intent-recorded",
                "intent_at": intent_at,
            },
            "bridge": {
                "namespace": bridge_namespace,
                "name": name,
                "uid": bridge_uid,
                "intent_resource_version": str(bridge_metadata.get("resourceVersion", "") or ""),
                "preimage_data_sha256": original_data_sha256,
                "intended_data_sha256": intended_data_sha256,
                "preimage_material_sha256": bridge_preimage_material_sha256,
                "intended_material_sha256": _controller_bridge_material_fingerprint(
                    bridge_intended_live
                ),
                "state": "intent-recorded",
                "intent_at": intent_at,
            },
        },
    }
    journal["source_configuration"] = configuration
    checkpoint_writer()
    return configuration


def _reconcile_controller_bridge_config_map_copy(
    *,
    configuration: dict[str, Any],
    copy_name: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None],
    apply_if_preimage: bool = True,
) -> dict[str, Any]:
    copies = configuration.get("copies")
    if not isinstance(copies, dict) or not isinstance(copies.get(copy_name), dict):
        raise RuntimeError(
            f"Controller bridge source configuration lacks mutable {copy_name} copy intent."
        )
    operation = copies[copy_name]
    namespace = str(operation.get("namespace", "") or "")
    name = str(operation.get("name", "") or "")
    expected_uid = str(operation.get("uid", "") or "")
    intent_resource_version = str(operation.get("intent_resource_version", "") or "")
    config_key = str(configuration.get("config_key", "") or "")
    original_slurm_conf = str(configuration.get("original_slurm_conf", "") or "")
    intended_slurm_conf = str(configuration.get("intended_slurm_conf", "") or "")
    live, metadata, data = _controller_bridge_live_config_map(
        namespace=namespace,
        name=name,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    live_uid = str(metadata.get("uid", "") or "")
    live_resource_version = str(metadata.get("resourceVersion", "") or "")
    if live_uid != expected_uid:
        raise RuntimeError(
            "recovery-required: controller bridge configuration ConfigMap UID changed: "
            f"{namespace}/{name}."
        )
    live_data_sha256 = _controller_bridge_config_map_data_sha256(data)
    live_material_sha256 = _controller_bridge_material_fingerprint(live)
    live_slurm_conf = data.get(config_key)
    intended = (
        live_slurm_conf == intended_slurm_conf
        and live_data_sha256 == str(operation.get("intended_data_sha256", "") or "")
        and live_material_sha256 == str(operation.get("intended_material_sha256", "") or "")
    )
    preimage = (
        live_slurm_conf == original_slurm_conf
        and live_data_sha256 == str(operation.get("preimage_data_sha256", "") or "")
        and live_material_sha256 == str(operation.get("preimage_material_sha256", "") or "")
    )
    operation_state = str(operation.get("state", "") or "")
    if intended:
        accepted_resource_version = str(operation.get("accepted_resource_version", "") or "")
        if operation_state == "accepted" and accepted_resource_version != live_resource_version:
            raise RuntimeError(
                "recovery-required: accepted controller bridge configuration "
                f"ConfigMap resourceVersion drifted: {namespace}/{name}."
            )
        if operation_state != "accepted" and live_resource_version == intent_resource_version:
            raise RuntimeError(
                "recovery-required: controller bridge configuration changed without advancing "
                f"resourceVersion: {namespace}/{name}."
            )
        operation.update(
            {
                "state": "accepted",
                "accepted_resource_version": live_resource_version,
                "accepted_data_sha256": live_data_sha256,
                "accepted_at": str(operation.get("accepted_at", "") or "") or _utc_now(),
            }
        )
        checkpoint_writer()
        return live
    if operation_state == "accepted":
        raise RuntimeError(
            "recovery-required: accepted controller bridge configuration content drifted: "
            f"{namespace}/{name}."
        )
    if not preimage or live_resource_version != intent_resource_version:
        raise RuntimeError(
            "recovery-required: controller bridge configuration ConfigMap is neither its exact "
            f"journaled preimage nor intended image: {namespace}/{name}."
        )
    if not apply_if_preimage:
        raise RuntimeError(
            "recovery-required: controller bridge configuration patch returned without applying "
            f"its exact intended image: {namespace}/{name}."
        )
    operation.update(
        {
            "state": "dispatching",
            "dispatching_at": str(operation.get("dispatching_at", "") or "") or _utc_now(),
        }
    )
    checkpoint_writer()
    patch = [
        {"op": "test", "path": "/metadata/uid", "value": expected_uid},
        {
            "op": "test",
            "path": "/metadata/resourceVersion",
            "value": intent_resource_version,
        },
        {
            "op": "test",
            "path": f"/data/{_controller_bridge_json_pointer_token(config_key)}",
            "value": original_slurm_conf,
        },
        {
            "op": "replace",
            "path": f"/data/{_controller_bridge_json_pointer_token(config_key)}",
            "value": intended_slurm_conf,
        },
    ]
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "patch",
            "configmap",
            name,
            "--type=json",
            "--patch-file",
            "/dev/stdin",
        ],
        input_text=json.dumps(patch, separators=(",", ":")),
        timeout_seconds=300,
    )
    return _reconcile_controller_bridge_config_map_copy(
        configuration=configuration,
        copy_name=copy_name,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        apply_if_preimage=False,
    )


def _wait_for_source_controller_slurm_config_projection(
    *,
    intended_slurm_conf: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    timeout_seconds: float = 180.0,
    poll_interval_seconds: float = 5.0,
) -> None:
    deadline = time.monotonic() + max(timeout_seconds, 0.0)
    while True:
        mounted_config = _kubectl_exec_slurm_controller(
            command_runner=command_runner,
            kube_context=kube_context,
            args=("cat", _SOPERATOR_LEGACY_SLURM_CONF),
            timeout_seconds=120,
        )
        if mounted_config.returncode == 0 and mounted_config.stdout == intended_slurm_conf:
            return
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "source controller has not yet projected the exact intended jailed slurm.conf; "
                "no Slurm reconfigure was dispatched."
            )
        time.sleep(max(poll_interval_seconds, 0.0))


def _controller_bridge_source_reference_rebind_allowed(
    *,
    stage: str,
    configuration: Mapping[str, Any],
    expected_source_reference: Mapping[str, Any],
    source_reference: Mapping[str, Any],
) -> bool:
    stable_reference_fields = (
        "jailed_config_name",
        "jailed_config_uid",
        "config_map_name",
        "config_map_uid",
        "config_key",
        "path",
    )
    old_resource_version = str(
        expected_source_reference.get("jailed_config_resource_version", "") or ""
    )
    new_resource_version = str(source_reference.get("jailed_config_resource_version", "") or "")
    copies = _mapping(configuration.get("copies"))
    source_copy = _mapping(copies.get("source"))
    intended_data_sha256 = str(configuration.get("intended_config_data_sha256", "") or "")
    exact_accepted_source_copy = bool(
        intended_data_sha256
        and source_copy.get("state") == "accepted"
        and source_copy.get("intended_data_sha256") == intended_data_sha256
        and source_copy.get("accepted_data_sha256") == intended_data_sha256
    )
    exact_copy_recovery = any(
        _non_negative_int(_mapping(item).get("recovery_count"), fallback=0) > 0
        for item in copies.values()
    )
    return bool(
        stage == BridgeStage.SUBSTRATE_READY.value
        and (exact_accepted_source_copy or exact_copy_recovery)
        and old_resource_version
        and new_resource_version
        and old_resource_version != new_resource_version
        and all(
            expected_source_reference.get(field) == source_reference.get(field)
            for field in stable_reference_fields
        )
    )


def _configure_source_controller_for_bridge(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    _recover_controller_bridge_pre_authority_configuration_rollback(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    if str(journal.get("stage", "") or "") != BridgeStage.SUBSTRATE_READY.value:
        return []
    _reconcile_controller_bridge_scheduling_domains_from_live_canary(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    try:
        pre_source_mutation_mount_canary(journal)
    except ValueError as exc:
        raise RuntimeError(
            "recovery-required: source controller configuration is blocked until the "
            f"checkpointed pre-source-mutation bridge canary is valid: {exc}"
        ) from exc
    if checkpoint_writer is None:
        raise RuntimeError(
            "Controller bridge source configuration requires a durable checkpoint writer."
        )
    raw_configuration = journal.get("source_configuration")
    if not isinstance(raw_configuration, dict):
        raise RuntimeError("Controller bridge source_configuration must be mutable.")
    if raw_configuration:
        if raw_configuration.get("schema") != CONTROLLER_BRIDGE_SOURCE_CONFIGURATION_SCHEMA:
            raise RuntimeError(
                "recovery-required: unsupported controller bridge source configuration journal; "
                "no legacy conversion is available."
            )
        configuration = raw_configuration
    else:
        configuration = _controller_bridge_source_configuration_intent(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    source_reference, _live_config, _live_metadata, _live_data = (
        _controller_bridge_active_slurm_configuration(
            kube_context=kube_context,
            command_runner=command_runner,
        )
    )
    expected_source_reference = _mapping(configuration.get("source_reference"))
    if expected_source_reference != source_reference:
        old_resource_version = str(
            expected_source_reference.get("jailed_config_resource_version", "") or ""
        )
        new_resource_version = str(source_reference.get("jailed_config_resource_version", "") or "")
        if not _controller_bridge_source_reference_rebind_allowed(
            stage=str(journal.get("stage", "") or ""),
            configuration=configuration,
            expected_source_reference=expected_source_reference,
            source_reference=source_reference,
        ):
            raise RuntimeError(
                "recovery-required: active Slurm JailedConfig or ConfigMap identity changed "
                "after configuration intent."
            )
        rebindings = configuration.setdefault("source_reference_rebindings", [])
        if not isinstance(rebindings, list):
            raise RuntimeError("Controller bridge source_reference_rebindings must be mutable.")
        rebindings.append(
            {
                "reason": "exact-jailed-config-resource-version-after-accepted-copy",
                "jailed_config_uid": str(source_reference["jailed_config_uid"]),
                "previous_resource_version": old_resource_version,
                "resource_version": new_resource_version,
                "rebound_at": _utc_now(),
            }
        )
        configuration["source_reference"] = dict(source_reference)
        checkpoint_writer()
    if configuration.get("config_map_names") != [source_reference["config_map_name"]]:
        raise RuntimeError(
            "recovery-required: active Slurm ConfigMap name changed after configuration intent."
        )
    _reconcile_controller_bridge_config_map_copy(
        configuration=configuration,
        copy_name="source",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    mirrored_config = _reconcile_controller_bridge_config_map_copy(
        configuration=configuration,
        copy_name="bridge",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    _wait_for_source_controller_slurm_config_projection(
        intended_slurm_conf=str(configuration.get("intended_slurm_conf", "") or ""),
        kube_context=kube_context,
        command_runner=command_runner,
    )
    result = _kubectl_exec_slurm_controller(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "reconfigure"),
        timeout_seconds=120,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source slurmctld did not accept the bridge host configuration: "
            + _command_detail(result)
        )
    ping = _kubectl_exec_slurm_controller(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "ping"),
        timeout_seconds=120,
    )
    if ping.returncode != 0 or not re.search(
        r"(?m)^Slurmctld\(primary\).*\bis UP\s*$",
        ping.stdout,
    ):
        raise SoperatorMigrationPhasePending(
            "source slurmctld accepted reconfigure but the exact primary controller did not "
            "remain UP; restore the checkpointed configuration preimage before retrying."
        )
    partition_lines = _reassert_controller_bridge_partition_pause_after_reconfigure(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    configuration["reconfigured_at"] = _utc_now()
    configuration["source_ping_sha256"] = hashlib.sha256(ping.stdout.encode("utf-8")).hexdigest()
    mirrored_records = journal.get("mirrored_material")
    if not isinstance(mirrored_records, list):
        raise RuntimeError("Controller bridge mirrored material journal must be mutable.")
    name = str(configuration["config_map_names"][0])
    record = next(
        (
            item
            for item in mirrored_records
            if isinstance(item, dict)
            and item.get("kind") == "ConfigMap"
            and item.get("name") == name
        ),
        None,
    )
    intended_material_sha256 = str(
        _mapping(_mapping(configuration.get("copies")).get("bridge")).get(
            "intended_material_sha256", ""
        )
        or ""
    )
    if (
        not isinstance(record, dict)
        or _controller_bridge_material_fingerprint(mirrored_config) != intended_material_sha256
    ):
        raise RuntimeError(
            f"Controller bridge mirrored ConfigMap intended binding is invalid: {name}."
        )
    record["material_sha256"] = intended_material_sha256
    advance_bridge_stage(journal, BridgeStage.SOURCE_CONFIGURED)
    checkpoint_writer()
    return [
        "Source controller configuration: exact UID/resourceVersion-bound source and bridge "
        "ConfigMap copies applied; ordered SlurmctldHost entries and raised controller-gap "
        "timeouts retain their checkpointed preimage for final restoration."
    ] + partition_lines


def _recover_controller_bridge_pre_authority_configuration_rollback(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if str(journal.get("stage", "") or "") != BridgeStage.SOURCE_CONFIGURED.value:
        return
    configuration = journal.get("source_configuration")
    copies = _mapping(_mapping(configuration).get("copies"))
    if not isinstance(configuration, dict) or set(copies) != {"source", "bridge"}:
        return
    authority = _mapping(journal.get("authority"))
    if (
        authority.get("owner") != "source-singleton"
        or str(authority.get("first_bridge_write_at", "") or "")
        or authority.get("source_restart_prohibited") is True
    ):
        return
    original_slurm_conf = str(configuration.get("original_slurm_conf", "") or "")
    config_key = str(configuration.get("config_key", "") or "")
    observed: dict[str, dict[str, str]] = {}
    live_resources: dict[str, dict[str, Any]] = {}
    exact_preimages = 0
    exact_intended = 0
    preimage_copies: list[str] = []
    for copy_name in ("source", "bridge"):
        operation = _mapping(copies.get(copy_name))
        namespace = str(operation.get("namespace", "") or "")
        name = str(operation.get("name", "") or "")
        live, metadata, data = _controller_bridge_live_config_map(
            namespace=namespace,
            name=name,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        live_uid = str(metadata.get("uid", "") or "")
        live_resource_version = str(metadata.get("resourceVersion", "") or "")
        data_sha256 = _controller_bridge_config_map_data_sha256(data)
        material_sha256 = _controller_bridge_material_fingerprint(live)
        is_preimage = (
            live_uid == str(operation.get("uid", "") or "")
            and data.get(config_key) == original_slurm_conf
            and data_sha256 == str(operation.get("preimage_data_sha256", "") or "")
            and material_sha256 == str(operation.get("preimage_material_sha256", "") or "")
        )
        is_intended = (
            live_uid == str(operation.get("uid", "") or "")
            and data.get(config_key) == str(configuration.get("intended_slurm_conf", "") or "")
            and data_sha256 == str(operation.get("intended_data_sha256", "") or "")
            and material_sha256 == str(operation.get("intended_material_sha256", "") or "")
        )
        exact_preimages += int(is_preimage)
        exact_intended += int(is_intended)
        if is_preimage:
            preimage_copies.append(copy_name)
        live_resources[copy_name] = live
        observed[copy_name] = {
            "namespace": namespace,
            "name": name,
            "uid": live_uid,
            "resource_version": live_resource_version,
            "data_sha256": data_sha256,
            "material_sha256": material_sha256,
        }
    if exact_preimages == 0:
        return
    if exact_preimages != 2:
        if exact_preimages + exact_intended != 2:
            raise RuntimeError(
                "recovery-required: controller bridge configuration rollback is only partially "
                "present and the remaining ConfigMap is not the exact accepted intended image."
            )
        if checkpoint_writer is None:
            raise RuntimeError(
                "Controller bridge partial configuration rollback recovery requires a durable "
                "checkpoint."
            )
        recovered_at = _utc_now()
        for copy_name in preimage_copies:
            operation = copies[copy_name]
            if not isinstance(operation, dict):
                raise RuntimeError(
                    "Controller bridge partial configuration rollback copy must be mutable."
                )
            operation.update(
                {
                    "state": "intent-recorded",
                    "intent_resource_version": observed[copy_name]["resource_version"],
                    "intent_at": recovered_at,
                    "recovery_reason": (
                        "operator-restored-exact-preimage-before-authority-transfer"
                    ),
                    "recovered_at": recovered_at,
                    "recovery_count": _non_negative_int(operation.get("recovery_count"), fallback=0)
                    + 1,
                }
            )
            for field in (
                "dispatching_at",
                "accepted_at",
                "accepted_resource_version",
                "accepted_data_sha256",
            ):
                operation.pop(field, None)
        for field in ("reconfigured_at", "source_ping_sha256", "client_propagation"):
            configuration.pop(field, None)
        journal["stage"] = BridgeStage.SUBSTRATE_READY.value
        checkpoint_writer()
        return
    if checkpoint_writer is None:
        raise RuntimeError(
            "Controller bridge configuration rollback recovery requires a durable checkpoint."
        )
    bridge_live = copy.deepcopy(live_resources["bridge"])
    bridge_metadata = _mapping(bridge_live.get("metadata"))
    bridge_annotations = dict(_mapping(bridge_metadata.get("annotations")))
    source_resource_version = observed["source"]["resource_version"]
    if bridge_annotations.get("nebius.ai/cxcli-source-resource-version") != source_resource_version:
        bridge_annotations["nebius.ai/cxcli-source-resource-version"] = source_resource_version
        mutable_metadata = dict(bridge_metadata)
        mutable_metadata["annotations"] = bridge_annotations
        bridge_live["metadata"] = mutable_metadata
        replacement = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "replace",
                "-f",
                "-",
                "-o",
                "json",
            ],
            input_text=json.dumps(bridge_live, separators=(",", ":")),
            check=False,
            timeout_seconds=120,
        )
        if replacement.returncode != 0:
            raise RuntimeError(
                "recovery-required: controller bridge configuration rollback could not "
                "CAS-rebind the bridge mirror to the restored source resourceVersion: "
                + _command_detail(replacement)
            )
        try:
            replaced = json.loads(replacement.stdout)
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "recovery-required: controller bridge restored mirror replacement returned "
                "invalid JSON."
            ) from exc
        if not isinstance(replaced, Mapping):
            raise RuntimeError(
                "recovery-required: controller bridge restored mirror replacement returned "
                "a non-object response."
            )
        replaced_metadata = _mapping(replaced.get("metadata"))
        if (
            str(replaced_metadata.get("uid", "") or "") != observed["bridge"]["uid"]
            or _mapping(replaced_metadata.get("annotations")).get(
                "nebius.ai/cxcli-source-resource-version"
            )
            != source_resource_version
        ):
            raise RuntimeError(
                "recovery-required: controller bridge restored mirror source binding was not "
                "accepted exactly."
            )
        observed["bridge"]["resource_version"] = str(
            replaced_metadata.get("resourceVersion", "") or ""
        )
    ping = _kubectl_exec_slurm_controller(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "ping"),
        timeout_seconds=120,
    )
    if ping.returncode != 0 or not re.search(
        r"(?m)^Slurmctld\(primary\).*\bis UP\s*$",
        ping.stdout,
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge configuration rollback restored both exact preimages, but the "
            "source Slurm controller is not yet proven UP."
        )
    recoveries = journal.setdefault("configuration_recoveries", [])
    if not isinstance(recoveries, list):
        raise RuntimeError("Controller bridge configuration_recoveries must be mutable.")
    recoveries.append(
        {
            "schema": "nebius-cxcli-controller-bridge-configuration-recovery/v1",
            "reason": "operator-restored-exact-preimage-before-authority-transfer",
            "prior_intended_slurm_conf_sha256": str(
                configuration.get("intended_slurm_conf_sha256", "") or ""
            ),
            "copies": observed,
            "source_ping_sha256": hashlib.sha256(ping.stdout.encode("utf-8")).hexdigest(),
            "recovered_at": _utc_now(),
        }
    )
    mirrored_records = journal.get("mirrored_material")
    if not isinstance(mirrored_records, list):
        raise RuntimeError("Controller bridge mirrored material journal must be mutable.")
    bridge_name = observed["bridge"]["name"]
    mirror = next(
        (
            item
            for item in mirrored_records
            if isinstance(item, dict)
            and item.get("kind") == "ConfigMap"
            and item.get("name") == bridge_name
        ),
        None,
    )
    if not isinstance(mirror, dict):
        raise RuntimeError(
            "recovery-required: controller bridge configuration rollback lost its mirror "
            "material record."
        )
    mirror["material_sha256"] = observed["bridge"]["material_sha256"]
    journal["source_configuration"] = {}
    journal["stage"] = BridgeStage.SUBSTRATE_READY.value
    checkpoint_writer()


def _reconcile_controller_bridge_scheduling_domains_from_live_canary(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    groups = journal.get("node_groups")
    if not isinstance(groups, list) or len(groups) != 2:
        raise RuntimeError("Controller bridge scheduling-domain repair requires two groups.")
    needs_repair = False
    for group in groups:
        if not isinstance(group, dict):
            raise RuntimeError("Controller bridge scheduling-domain group must be mutable.")
        domain = _mapping(group.get("scheduling_failure_domain"))
        runtime_values = [
            str(domain.get(field, "") or "")
            for field in ("topology_value", "node_name", "node_uid")
        ]
        if any(runtime_values) != all(runtime_values):
            raise RuntimeError(
                "recovery-required: controller bridge scheduling-domain runtime binding is "
                "partially populated."
            )
        needs_repair = needs_repair or not all(runtime_values)
    if not needs_repair:
        return
    if checkpoint_writer is None:
        raise RuntimeError(
            "Controller bridge scheduling-domain repair requires a durable checkpoint writer."
        )
    canaries = [
        item
        for item in _sequence_of_mappings(journal.get("shared_mount_canaries"))
        if item.get("purpose") == CONTROLLER_BRIDGE_PRE_SOURCE_MUTATION_CANARY
    ]
    if len(canaries) != 1 or canaries[0].get("schema") != CONTROLLER_BRIDGE_MOUNT_CANARY_SCHEMA:
        raise RuntimeError(
            "recovery-required: controller bridge scheduling-domain repair lacks exactly one "
            "checkpointed pre-source-mutation canary."
        )
    pods = _sequence_of_mappings(canaries[0].get("pods"))
    if len(pods) != 2 or [pod.get("slot") for pod in pods] != [0, 1]:
        raise RuntimeError(
            "recovery-required: controller bridge scheduling-domain repair lacks two ordered "
            "canary Pod bindings."
        )
    repaired: list[dict[str, str]] = []
    for slot, (group, pod) in enumerate(zip(groups, pods, strict=True)):
        group_id = str(group.get("id", "") or "")
        node_name = str(pod.get("node_name", "") or "")
        node_uid = str(pod.get("node_uid", "") or "")
        if (
            pod.get("node_group_id") != group_id
            or pod.get("failure_domain") != group_id
            or not node_name
            or not node_uid
        ):
            raise RuntimeError(
                "recovery-required: controller bridge canary scheduling-domain binding differs "
                f"for slot {slot}."
            )
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        metadata = _mapping(node.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        if (
            str(metadata.get("name", "") or "") != node_name
            or str(metadata.get("uid", "") or "") != node_uid
            or str(labels.get("nebius.com/node-group-id", "") or "") != group_id
        ):
            raise RuntimeError(
                "recovery-required: controller bridge canary Node UID or immutable node-group "
                f"label changed for slot {slot}."
            )
        expected = {
            "topology_key": "nebius.com/node-group-id",
            "topology_value": group_id,
            "node_group_id": group_id,
            "node_name": node_name,
            "node_uid": node_uid,
        }
        existing = _mapping(group.get("scheduling_failure_domain"))
        existing_runtime = {key: str(existing.get(key, "") or "") for key in expected}
        if existing_runtime["topology_value"] and existing_runtime != expected:
            raise RuntimeError(
                "recovery-required: controller bridge scheduling-domain checkpoint differs "
                f"from live canary evidence for slot {slot}."
            )
        repaired.append(expected)
    for group, domain in zip(groups, repaired, strict=True):
        group["scheduling_failure_domain"] = domain
    checkpoint_writer()


def _bridge_stager_pod(
    *,
    plan: BridgePlan,
    node_name: str = "",
) -> dict[str, Any]:
    spec: dict[str, Any] = {
        "restartPolicy": "Never",
        "nodeSelector": {CONTROLLER_BRIDGE_LABEL: "true"},
        "tolerations": [
            {
                "key": CONTROLLER_BRIDGE_LABEL,
                "operator": "Equal",
                "value": "true",
                "effect": "NoSchedule",
            }
        ],
        "containers": [
            {
                "name": "stager",
                "image": plan.source_slurm_image,
                "command": ["/bin/sh", "-ec", "trap 'exit 0' TERM INT; while :; do sleep 30; done"],
                "volumeMounts": [{"name": "state", "mountPath": "/shared"}],
                "securityContext": {"allowPrivilegeEscalation": False, "runAsUser": 0},
            }
        ],
        "volumes": [
            {
                "name": "state",
                "persistentVolumeClaim": {"claimName": "cxcli-controller-bridge-state"},
            }
        ],
    }
    if node_name:
        spec.pop("nodeSelector", None)
        spec["nodeName"] = node_name
    return {
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {
            "namespace": plan.namespace,
            "name": "cxcli-controller-bridge-stager",
            "labels": {
                "app.kubernetes.io/managed-by": "nebius-cxcli",
                CONTROLLER_BRIDGE_LABEL: "stager",
            },
        },
        "spec": spec,
    }


def _ensure_bridge_stager(
    *,
    plan: BridgePlan,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    _kubectl_apply_objects(
        command_runner=command_runner,
        kube_context=kube_context,
        objects=(_bridge_stager_pod(plan=plan),),
        timeout_seconds=300,
    )
    _kubectl_wait(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=plan.namespace,
        resource="pod/cxcli-controller-bridge-stager",
        condition="Ready",
        timeout="10m",
        timeout_seconds=660,
    )


def _bridge_mount_canary_pod(
    *,
    namespace: str,
    slot: int,
    image: str,
    campaign_fingerprint: str,
    cluster_id: str,
) -> dict[str, Any]:
    return {
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {
            "namespace": namespace,
            "name": f"cxcli-controller-bridge-canary-{slot}",
            "labels": {
                "app.kubernetes.io/managed-by": "nebius-cxcli",
                CONTROLLER_BRIDGE_LABEL: "canary",
                CONTROLLER_BRIDGE_SLOT_LABEL: str(slot),
            },
            "annotations": {
                "nebius.ai/cxcli-campaign-fingerprint": campaign_fingerprint,
                "nebius.ai/cxcli-cluster-id": cluster_id,
            },
        },
        "spec": {
            "activeDeadlineSeconds": 900,
            "automountServiceAccountToken": False,
            "enableServiceLinks": False,
            "restartPolicy": "Never",
            "terminationGracePeriodSeconds": 5,
            "securityContext": {"seccompProfile": {"type": "RuntimeDefault"}},
            "nodeSelector": {
                CONTROLLER_BRIDGE_LABEL: "true",
                CONTROLLER_BRIDGE_SLOT_LABEL: str(slot),
            },
            "tolerations": [
                {
                    "key": CONTROLLER_BRIDGE_LABEL,
                    "operator": "Equal",
                    "value": "true",
                    "effect": "NoSchedule",
                }
            ],
            "containers": [
                {
                    "name": "canary",
                    "image": image,
                    "command": [
                        "/bin/sh",
                        "-ec",
                        "trap 'exit 0' TERM INT; while :; do sleep 30; done",
                    ],
                    "volumeMounts": [
                        {"name": "state", "mountPath": "/shared"},
                        {"name": "jail", "mountPath": "/jail"},
                    ],
                    "securityContext": {
                        "allowPrivilegeEscalation": False,
                        "capabilities": {"drop": ["ALL"]},
                        "readOnlyRootFilesystem": True,
                        "runAsUser": 0,
                    },
                }
            ],
            "volumes": [
                {
                    "name": "state",
                    "persistentVolumeClaim": {"claimName": CONTROLLER_BRIDGE_STATE_PVC},
                },
                {
                    "name": "jail",
                    "persistentVolumeClaim": {"claimName": CONTROLLER_BRIDGE_JAIL_PVC},
                },
            ],
        },
    }


def _delete_owned_controller_bridge_canary(
    *,
    desired: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    identity = _controller_bridge_object_identity(desired)
    exists, live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity=identity,
    )
    if not exists:
        return
    desired_metadata = _mapping(desired.get("metadata"))
    live_metadata = _mapping(live.get("metadata"))
    desired_annotations = _mapping(desired_metadata.get("annotations"))
    live_annotations = _mapping(live_metadata.get("annotations"))
    desired_labels = _mapping(desired_metadata.get("labels"))
    live_labels = _mapping(live_metadata.get("labels"))
    live_spec = _mapping(live.get("spec"))
    desired_spec = _mapping(desired.get("spec"))
    live_containers = _sequence_of_mappings(live_spec.get("containers"))
    desired_containers = _sequence_of_mappings(desired_spec.get("containers"))
    live_uid = str(live_metadata.get("uid", "") or "")
    resource_version = str(live_metadata.get("resourceVersion", "") or "")
    if (
        not live_uid
        or not resource_version
        or any(live_annotations.get(key) != value for key, value in desired_annotations.items())
        or any(live_labels.get(key) != value for key, value in desired_labels.items())
        or live_spec.get("nodeSelector") != desired_spec.get("nodeSelector")
        or len(live_containers) != 1
        or len(desired_containers) != 1
        or live_containers[0].get("image") != desired_containers[0].get("image")
    ):
        raise RuntimeError(
            "recovery-required: controller bridge mount canary name is occupied by a "
            "resource outside the exact campaign ownership and scheduling contract."
        )
    delete_options = {
        "apiVersion": "v1",
        "kind": "DeleteOptions",
        "preconditions": {"uid": live_uid, "resourceVersion": resource_version},
        "propagationPolicy": "Foreground",
    }
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "delete",
            "--raw",
            f"/api/v1/namespaces/{identity['namespace']}/pods/{identity['name']}",
            "-f",
            "-",
        ],
        input_text=json.dumps(delete_options, separators=(",", ":")),
        timeout_seconds=120,
    )
    _wait_for_kubernetes_resource_uid_absent(
        command_runner=command_runner,
        kube_context=kube_context,
        api_path=f"/api/v1/namespaces/{identity['namespace']}/pods/{identity['name']}",
        uid=live_uid,
        timeout_seconds=300,
    )


def _prove_controller_bridge_shared_mount(
    *,
    journal: dict[str, Any],
    image: str,
    purpose: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    observe_jailed_config: bool = False,
) -> dict[str, Any]:
    namespace = str(journal.get("namespace", "") or "")
    expected_groups = [
        str(item.get("id", "") or "") for item in _sequence_of_mappings(journal.get("node_groups"))
    ]
    if len(expected_groups) != 2 or len(set(expected_groups)) != 2 or not all(expected_groups):
        raise RuntimeError(
            "Controller bridge shared-mount proof requires two exact provider node-group IDs."
        )
    campaign_fingerprint = str(journal.get("campaign_fingerprint", "") or "")
    cluster_id = str(journal.get("cluster_id", "") or "")
    objects = tuple(
        _bridge_mount_canary_pod(
            namespace=namespace,
            slot=slot,
            image=image,
            campaign_fingerprint=campaign_fingerprint,
            cluster_id=cluster_id,
        )
        for slot in (0, 1)
    )
    for desired in objects:
        _delete_owned_controller_bridge_canary(
            desired=desired,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    _kubectl_apply_objects(
        command_runner=command_runner,
        kube_context=kube_context,
        objects=objects,
        timeout_seconds=300,
    )
    for slot in (0, 1):
        _kubectl_wait(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource=f"pod/cxcli-controller-bridge-canary-{slot}",
            condition="Ready",
            timeout="10m",
            timeout_seconds=660,
        )
    pod_records: list[dict[str, str]] = []
    for slot in (0, 1):
        pod_name = f"cxcli-controller-bridge-canary-{slot}"
        pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pod",
                pod_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        node_labels = _mapping(node_metadata.get("labels"))
        node_group_id = str(node_labels.get("nebius.com/node-group-id", "") or "")
        if node_group_id != expected_groups[slot]:
            raise RuntimeError(
                "Controller bridge mount canary scheduled outside its journaled node group: "
                f"slot={slot}, observed={node_group_id or '<missing>'}."
            )
        pod_records.append(
            {
                "slot": slot,
                "pod_name": pod_name,
                "pod_uid": str(_mapping(pod.get("metadata")).get("uid", "") or ""),
                "node_name": node_name,
                "node_uid": str(node_metadata.get("uid", "") or ""),
                "node_group_id": node_group_id,
                "failure_domain": node_group_id,
            }
        )
    if (
        len({item["pod_uid"] for item in pod_records}) != 2
        or len({item["node_uid"] for item in pod_records}) != 2
        or len({item["failure_domain"] for item in pod_records}) != 2
    ):
        raise RuntimeError(
            "Controller bridge shared-mount proof requires two distinct Pod UIDs, Node UIDs, "
            "and immutable node-group scheduling domains."
        )
    group_records = journal.get("node_groups")
    if not isinstance(group_records, list) or len(group_records) != 2:
        raise RuntimeError("Controller bridge failure-domain journal must contain two groups.")
    for slot, pod_record in enumerate(pod_records):
        group_record = group_records[slot]
        if not isinstance(group_record, dict):
            raise RuntimeError("Controller bridge failure-domain group must be mutable.")
        existing_domain = _mapping(group_record.get("scheduling_failure_domain"))
        existing_runtime_binding = {
            "topology_key": str(existing_domain.get("topology_key", "") or ""),
            "topology_value": str(existing_domain.get("topology_value", "") or ""),
            "node_group_id": str(existing_domain.get("node_group_id", "") or ""),
            "node_name": str(existing_domain.get("node_name", "") or ""),
            "node_uid": str(existing_domain.get("node_uid", "") or ""),
        }
        expected_runtime_binding = {
            "topology_key": "nebius.com/node-group-id",
            "topology_value": pod_record["failure_domain"],
            "node_group_id": pod_record["node_group_id"],
            "node_name": pod_record["node_name"],
            "node_uid": pod_record["node_uid"],
        }
        if existing_runtime_binding["topology_value"] and (
            existing_runtime_binding != expected_runtime_binding
        ):
            raise RuntimeError(
                "recovery-required: controller bridge canary Node UID or immutable "
                f"node-group scheduling-domain binding changed for slot {slot}."
            )
        group_record["scheduling_failure_domain"] = expected_runtime_binding

    token = uuid4().hex
    canary_name = f".cxcli-{purpose}-{str(journal.get('campaign_fingerprint', ''))[:12]}"
    first_paths = (f"/shared/{canary_name}.a", f"/jail/{canary_name}.a")
    second_paths = (f"/shared/{canary_name}.b", f"/jail/{canary_name}.b")
    first = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_records[0]["pod_name"],
            "-c",
            "canary",
            "--",
            "/bin/sh",
            "-ec",
            "umask 077; "
            + "; ".join(
                f"printf %s {shlex.quote(token)} > {shlex.quote(path)}; sync -f {shlex.quote(path)}"
                for path in first_paths
            ),
        ],
        check=False,
        timeout_seconds=120,
    )
    second = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_records[1]["pod_name"],
            "-c",
            "canary",
            "--",
            "/bin/sh",
            "-ec",
            "; ".join(
                f'test "$(cat {shlex.quote(first_path)})" = {shlex.quote(token)}; '
                f"printf %s {shlex.quote(token)} > {shlex.quote(second_path)}; "
                f"sync -f {shlex.quote(second_path)}"
                for first_path, second_path in zip(first_paths, second_paths, strict=True)
            ),
        ],
        check=False,
        timeout_seconds=120,
    )
    round_trip = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_records[0]["pod_name"],
            "-c",
            "canary",
            "--",
            "/bin/sh",
            "-ec",
            "; ".join(
                f'test "$(cat {shlex.quote(second_path)})" = {shlex.quote(token)}; '
                f"rm -f {shlex.quote(first_path)} {shlex.quote(second_path)}; "
                f"sync -f {shlex.quote(mount_path)}"
                for first_path, second_path, mount_path in zip(
                    first_paths,
                    second_paths,
                    ("/shared", "/jail"),
                    strict=True,
                )
            ),
        ],
        check=False,
        timeout_seconds=120,
    )
    if any(result.returncode != 0 for result in (first, second, round_trip)):
        raise SoperatorMigrationPhasePending(
            "controller bridge state or Jail SFS failed the bidirectional two-node "
            "read/write canary."
        )
    jailed_config_observation = (
        _controller_bridge_canary_jailed_config_observation(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        if observe_jailed_config
        else {}
    )
    records = journal.get("shared_mount_canaries")
    if not isinstance(records, list):
        raise RuntimeError("Controller bridge shared-mount canary journal must be mutable.")
    attachment_digests = {
        str(item.get("controller_spool_attachment_sha256", "") or "")
        for item in _sequence_of_mappings(journal.get("node_groups"))
    }
    jail_attachment_digests = {
        str(item.get("jail_attachment_sha256", "") or "")
        for item in _sequence_of_mappings(journal.get("node_groups"))
    }
    if len(attachment_digests) != 1 or not re.fullmatch(
        r"[0-9a-f]{64}", next(iter(attachment_digests), "")
    ):
        raise RuntimeError(
            "Controller bridge shared-mount proof lacks one immutable controller-spool "
            "attachment binding."
        )
    if len(jail_attachment_digests) != 1 or not re.fullmatch(
        r"[0-9a-f]{64}", next(iter(jail_attachment_digests), "")
    ):
        raise RuntimeError(
            "Controller bridge shared-mount proof lacks one immutable Jail attachment binding."
        )
    pv_records = [
        item
        for item in _sequence_of_mappings(journal.get("kubernetes_resources"))
        if item.get("kind") == "PersistentVolume"
    ]
    pvc_records = [
        item
        for item in _sequence_of_mappings(journal.get("kubernetes_resources"))
        if item.get("kind") == "PersistentVolumeClaim" and item.get("namespace") == namespace
    ]
    if len(pv_records) != 2 or len(pvc_records) != 2:
        raise RuntimeError(
            "Controller bridge shared-mount proof requires the exact journaled state and "
            "Jail PV/PVC pairs."
        )
    pv_by_name = {str(item.get("name", "") or ""): item for item in pv_records}
    pvc_by_name = {str(item.get("name", "") or ""): item for item in pvc_records}

    def _storage_binding(claim_name: str) -> dict[str, str]:
        pv = _mapping(pv_by_name.get(f"{claim_name}-pv"))
        pvc = _mapping(pvc_by_name.get(claim_name))
        return {
            "pv_name": str(pv.get("name", "") or ""),
            "pv_uid": str(pv.get("uid", "") or ""),
            "pvc_name": str(pvc.get("name", "") or ""),
            "pvc_uid": str(pvc.get("uid", "") or ""),
        }

    record = {
        "schema": CONTROLLER_BRIDGE_MOUNT_CANARY_SCHEMA,
        "purpose": purpose,
        "image": image,
        "token_sha256": hashlib.sha256(token.encode("utf-8")).hexdigest(),
        "controller_spool_attachment_sha256": next(iter(attachment_digests)),
        "jail_attachment_sha256": next(iter(jail_attachment_digests)),
        "storage": {
            "controller_spool": _storage_binding(CONTROLLER_BRIDGE_STATE_PVC),
            "jail": _storage_binding(CONTROLLER_BRIDGE_JAIL_PVC),
        },
        "mount_paths": {"controller_spool": "/shared", "jail": "/jail"},
        "pods": pod_records,
        "bidirectional": True,
        "observed_at": _utc_now(),
    }
    if jailed_config_observation:
        record["jailed_config_observation"] = jailed_config_observation
    matching_indexes = [
        index
        for index, existing in enumerate(records)
        if isinstance(existing, Mapping) and existing.get("purpose") == purpose
    ]
    if len(matching_indexes) > 1:
        raise RuntimeError(
            f"Controller bridge shared-mount purpose {purpose} has duplicate journal records."
        )
    if matching_indexes:
        records[matching_indexes[0]] = record
    else:
        records.append(record)
    if checkpoint_writer is not None:
        checkpoint_writer()
    for slot in (0, 1):
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "delete",
                f"pod/cxcli-controller-bridge-canary-{slot}",
                "--ignore-not-found",
                "--wait=true",
            ],
            timeout_seconds=300,
        )
    return record


def _establish_controller_bridge_pre_source_mutation_readiness(
    *,
    journal: dict[str, Any],
    plan: BridgePlan,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if str(journal.get("stage", "") or "") != BridgeStage.PLANNED.value:
        return []
    if checkpoint_writer is None:
        raise RuntimeError(
            "Controller bridge substrate readiness requires a durable checkpoint writer."
        )
    source_configuration = journal.get("source_configuration")
    source_fencing = _mapping(_mapping(journal.get("fencing")).get("source"))
    state_manifest = _mapping(journal.get("state_manifest"))
    authority = _mapping(journal.get("authority"))
    if (
        source_configuration
        or source_fencing.get("proven") is True
        or state_manifest.get("promoted") is True
        or authority.get("owner") != "source-singleton"
        or str(authority.get("first_bridge_write_at", "") or "")
        or authority.get("source_restart_prohibited") is True
    ):
        raise RuntimeError(
            "recovery-required: controller bridge cannot establish pre-source-mutation "
            "readiness after controller configuration, fencing, state promotion, or "
            "authority transfer."
        )
    _prove_controller_bridge_shared_mount(
        journal=journal,
        image=plan.source_slurm_image,
        purpose=CONTROLLER_BRIDGE_PRE_SOURCE_MUTATION_CANARY,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    pre_source_mutation_mount_canary(journal)
    advance_bridge_stage(journal, BridgeStage.SUBSTRATE_READY)
    checkpoint_writer()
    return [
        "Controller bridge substrate ready: both fixed node groups are bound to distinct "
        "immutable node-group scheduling domains and live Node UIDs, and passed the "
        "checkpointed bidirectional shared-SFS mount canary before any source controller "
        "mutation."
    ]


def _bridge_file_sha256(path: Path) -> str:
    if path.is_symlink() or not path.is_file():
        raise RuntimeError(f"Controller bridge artifact is missing: {path}.")
    if stat.S_IMODE(path.stat().st_mode) & 0o077:
        raise RuntimeError(
            f"Controller bridge artifact permissions are broader than owner-only: {path}."
        )
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _bridge_copy_file_from_pod(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    pod: str,
    container: str,
    source_path: str,
    destination: Path,
) -> tuple[str, int]:
    if destination.exists():
        return _bridge_file_sha256(destination), destination.stat().st_size
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    destination.parent.chmod(0o700)
    partial = destination.parent / f".{destination.name}.partial-{uuid4().hex}"
    try:
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "cp",
                "-c",
                container,
                f"{pod}:{source_path}",
                str(partial),
            ],
            timeout_seconds=1800,
        )
        if partial.is_symlink() or not partial.is_file():
            raise RuntimeError(
                f"Controller bridge Pod copy did not create a regular file: {source_path}."
            )
        partial.chmod(0o600)
        os.replace(partial, destination)
    except BaseException:
        if partial.exists():
            partial.unlink()
        raise
    return _bridge_file_sha256(destination), destination.stat().st_size


def _reset_incomplete_bridge_artifacts(paths: Sequence[Path]) -> None:
    """Remove only cxcli-owned local artifacts when a multi-file copy was interrupted."""

    if all(path.is_file() and not path.is_symlink() for path in paths):
        return
    unsafe = [path for path in paths if path.is_symlink() or (path.exists() and not path.is_file())]
    if unsafe:
        raise RuntimeError(
            "recovery-required: a controller bridge artifact path is not a regular file: "
            + ", ".join(str(path) for path in unsafe)
        )
    for path in paths:
        path.unlink(missing_ok=True)


def _bridge_incremental_tool_preflight_script(*, root: str) -> str:
    return (
        "set -eu; export LC_ALL=C; "
        f"test -d {shlex.quote(root)}; test -r {shlex.quote(root)}; "
        "tar --version | head -n 1 | grep -F 'GNU tar' >/dev/null; "
        "help=$(tar --help); "
        "for option in --listed-incremental --numeric-owner --xattrs --acls; do "
        'printf \'%s\\n\' "$help" | grep -F -- "$option" >/dev/null; done; '
        "for tool in sha256sum find sort sync stat readlink cp mv rm cmp tr wc cut grep chmod; do "
        'command -v "$tool" >/dev/null; done; '
        "cp --help | grep -F -- '--reflink' >/dev/null"
    )


def _bridge_tree_manifest_script(*, root: str, output: str) -> str:
    """Return a deterministic content and representable-metadata manifest.

    The shared bridge SFS exposes whole-second mtime precision even when the
    source controller PVC exposes nanoseconds. Compare the common,
    destination-representable precision so a lossless content copy is not
    rejected solely because the destination filesystem canonicalizes the
    fractional part of an mtime.
    """

    return (
        "set -eu; export LC_ALL=C; umask 077; "
        f"root={shlex.quote(root)}; output={shlex.quote(output)}; "
        'test -d "$root"; work="${output}.work"; paths="${output}.paths"; '
        'test ! -e "$work"; test ! -e "$paths"; cd "$root"; '
        "nul_count=$(find . -xdev -mindepth 1 -print0 | tr -cd '\\000' | wc -c | tr -d ' '); "
        "line_count=$(find . -xdev -mindepth 1 -printf '%P\\n' | wc -l | tr -d ' '); "
        'test "$nul_count" = "$line_count"; '
        "find . -xdev -mindepth 1 -printf '%P\\n' | LC_ALL=C sort > \"$paths\"; "
        ': > "$work"; tab=$(printf "\\t"); '
        "while IFS= read -r relative; do "
        'case "$relative" in *"$tab"*) exit 91;; esac; path="./$relative"; '
        'mode=$(stat -c %a -- "$path"); uid=$(stat -c %u -- "$path"); '
        'gid=$(stat -c %g -- "$path"); mtime_seconds=$(stat -c %Y -- "$path"); '
        'if test -L "$path"; then '
        'target=$(readlink -- "$path"); '
        'test "$(readlink -- "$path" | wc -l | tr -d " ")" = 1; '
        'case "$target" in *"$tab"*) exit 92;; esac; '
        'printf "L\\t%s\\t%s\\t%s\\t%s\\t%s\\t%s\\n" '
        '"$mode" "$uid" "$gid" "$mtime_seconds" "$relative" "$target" >> "$work"; '
        'elif test -d "$path"; then '
        'printf "D\\t%s\\t%s\\t%s\\t%s\\t%s\\n" '
        '"$mode" "$uid" "$gid" "$mtime_seconds" "$relative" >> "$work"; '
        'elif test -f "$path"; then '
        'size=$(stat -c %s -- "$path"); '
        'digest=$(sha256sum -- "$path" | cut -d " " -f 1); '
        'printf "F\\t%s\\t%s\\t%s\\t%s\\t%s\\t%s\\t%s\\n" '
        '"$mode" "$uid" "$gid" "$mtime_seconds" "$size" "$digest" "$relative" >> "$work"; '
        'else exit 93; fi; done < "$paths"; '
        'rm -f "$paths"; mv "$work" "$output"; sync -f "$output"; '
        'digest=$(sha256sum "$output" | cut -d " " -f 1); '
        'count=$(wc -l < "$output" | tr -d " "); '
        'printf "CXCLI_MANIFEST=%s CXCLI_ENTRIES=%s\\n" "$digest" "$count"'
    )


def _bridge_tree_manifest_transient_cleanup_script(*, output: str) -> str:
    """Remove only an operation-owned temporary manifest and its sidecars."""

    paths = (output, f"{output}.work", f"{output}.paths")
    return "; ".join(f"test ! -L {shlex.quote(path)}; rm -f {shlex.quote(path)}" for path in paths)


def _bridge_stage_precopy_archive(
    *,
    plan: BridgePlan,
    authority_epoch: str,
    archive: Path,
    archive_sha256: str,
    snapshot: Path,
    snapshot_sha256: str,
    transfer_token: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[str, str, int]:
    if not re.fullmatch(r"[a-z0-9.-]+", authority_epoch) or not re.fullmatch(
        r"[a-f0-9]{32}", transfer_token
    ):
        raise RuntimeError("Controller bridge pre-copy tokens are unsafe.")
    destination = f"/shared/epochs/{authority_epoch}.precopy"
    build = f"/shared/.incoming-{authority_epoch}-precopy-{transfer_token}"
    material_dir = "/shared/.cxcli-incremental"
    remote_archive = f"{material_dir}/{authority_epoch}.precopy.tar"
    remote_snapshot = f"{material_dir}/{authority_epoch}.precopy.snar"
    for local_path, remote_path, expected_hash in (
        (archive, remote_archive, archive_sha256),
        (snapshot, remote_snapshot, snapshot_sha256),
    ):
        probe = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                f"test \"$(sha256sum {shlex.quote(remote_path)} | cut -d ' ' -f 1)\" = {shlex.quote(expected_hash)}; "
                f'test "$(stat -c %a {shlex.quote(remote_path)})" = 600',
            ],
            check=False,
            timeout_seconds=120,
        )
        if probe.returncode == 0:
            continue
        exists = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "test",
                "-e",
                remote_path,
            ],
            check=False,
            timeout_seconds=120,
        )
        if exists.returncode == 0:
            raise RuntimeError(
                "recovery-required: immutable controller pre-copy material hash drifted."
            )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                f"mkdir -p {shlex.quote(material_dir)}",
            ],
            timeout_seconds=120,
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "cp",
                str(local_path),
                f"cxcli-controller-bridge-stager:{remote_path}",
                "-c",
                "stager",
            ],
            timeout_seconds=1800,
        )
        verified_hash = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "sha256sum",
                remote_path,
            ],
            timeout_seconds=120,
        )
        if not re.search(rf"(?m)^{re.escape(expected_hash)}\s", verified_hash.stdout):
            raise RuntimeError("Controller bridge pre-copy material upload hash mismatch.")
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                f"chmod 600 {shlex.quote(remote_path)}; sync -f {shlex.quote(remote_path)}",
            ],
            timeout_seconds=120,
        )
    manifest_path = f"/shared/.cxcli-manifests/{authority_epoch}.precopy.tree.tsv"
    manifest_command = _bridge_tree_manifest_script(root=destination, output=manifest_path)
    existing_verification = (
        _bridge_incremental_tool_preflight_script(root=destination) + "; " + manifest_command
    )
    existing = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            existing_verification,
        ],
        check=False,
        timeout_seconds=1800,
    )
    if existing.returncode != 0:
        build_manifest = f"/shared/.cxcli-manifests/{authority_epoch}.precopy.build.tsv"
        script = (
            _bridge_incremental_tool_preflight_script(root="/shared")
            + "; "
            + f"mkdir -p /shared/epochs /shared/.cxcli-manifests; test ! -e {shlex.quote(destination)}; "
            + f"test ! -L {shlex.quote(build)}; "
            + f"if test -e {shlex.quote(build)}; then test -d {shlex.quote(build)}; "
            + f"rm -rf -- {shlex.quote(build)}; fi; "
            + _bridge_tree_manifest_transient_cleanup_script(output=build_manifest)
            + "; "
            + f"mkdir {shlex.quote(build)}; "
            + "tar --listed-incremental=/dev/null --numeric-owner --xattrs --acls "
            + f"-xpf {shlex.quote(remote_archive)} -C {shlex.quote(build)}; "
            + _bridge_tree_manifest_script(root=build, output=build_manifest)
            + "; "
            + f"find {shlex.quote(build)} -xdev -type f -exec sync -f {{}} \\;; "
            + f"find {shlex.quote(build)} -xdev -type d -exec sync -f {{}} \\;; "
            + f"sync -f {shlex.quote(build)}; mv {shlex.quote(build)} {shlex.quote(destination)}; "
            + "sync -f /shared/epochs; "
            + f"mv {shlex.quote(build_manifest)} {shlex.quote(manifest_path)}; "
            + f"sha256sum {shlex.quote(manifest_path)}"
        )
        existing = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                script,
            ],
            timeout_seconds=1800,
        )
    manifest_match = re.search(
        r"CXCLI_MANIFEST=([0-9a-f]{64}) CXCLI_ENTRIES=(\d+)", existing.stdout
    )
    if not manifest_match:
        manifest_hash_match = re.search(r"(?m)^([0-9a-f]{64})\s", existing.stdout)
        if not manifest_hash_match:
            raise RuntimeError("Controller bridge pre-copy manifest verification failed.")
        manifest_hash = manifest_hash_match.group(1)
        count_result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "wc",
                "-l",
                manifest_path,
            ],
            timeout_seconds=120,
        )
        entry_count = int(count_result.stdout.strip().split()[0])
    else:
        manifest_hash = manifest_match.group(1)
        entry_count = int(manifest_match.group(2))
    return destination, manifest_hash, entry_count


def _precopy_controller_state_to_bridge(
    *,
    journal: dict[str, Any],
    plan: BridgePlan,
    source: Mapping[str, Any],
    artifact_dir: Path,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if str(journal.get("stage", "") or "") != BridgeStage.SOURCE_CONFIGURED.value:
        return []
    controller = _mapping(source.get("controller_pod"))
    config = _kubectl_exec_slurm_controller(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "show", "config"),
        timeout_seconds=120,
    )
    if config.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge could not inspect source StateSaveLocation: "
            + _command_detail(config)
        )
    match = re.search(r"(?im)^\s*StateSaveLocation\s*=\s*(\S+)\s*$", config.stdout)
    if not match or not match.group(1).startswith("/"):
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge source StateSaveLocation is missing or not absolute."
        )
    state_path = match.group(1)
    epoch = str(_mapping(journal.get("authority")).get("epoch", "") or "")
    if not re.fullmatch(r"[a-z0-9.-]+", epoch):
        raise RuntimeError("Controller bridge authority epoch is unsafe.")
    precopy = journal.get("state_precopy")
    if not isinstance(precopy, dict):
        raise RuntimeError("Controller bridge pre-copy journal must be mutable.")
    if precopy and str(precopy.get("source_state_save_location", "") or "") != state_path:
        raise RuntimeError(
            "recovery-required: source StateSaveLocation changed after pre-copy intent."
        )
    transfer_token = str(precopy.get("transfer_token", "") or "") or uuid4().hex
    if not re.fullmatch(r"[0-9a-f]{32}", transfer_token):
        raise RuntimeError("Controller bridge pre-copy transfer token is invalid.")
    remote_prefix = f"/tmp/cxcli-{epoch}-{transfer_token}.precopy"
    remote_archive = f"{remote_prefix}.tar"
    remote_snapshot = f"{remote_prefix}.snar"
    remote_complete = f"{remote_prefix}.complete"
    # The same campaign advances through multiple Kubernetes segments while
    # retaining one authority epoch and artifact directory. Bind local scratch
    # files to the journaled transfer token so a later segment cannot mistake a
    # prior segment's complete artifacts for its own source snapshot.
    local_archive = artifact_dir / f"{epoch}.{transfer_token}.precopy.tar"
    local_snapshot = artifact_dir / f"{epoch}.{transfer_token}.precopy.snar"
    source_preflight = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            str(controller.get("name", "") or ""),
            "-c",
            str(controller.get("container_name", "") or ""),
            "--",
            "/bin/sh",
            "-ec",
            _bridge_incremental_tool_preflight_script(root=state_path) + "; test -w /tmp",
        ],
        check=False,
        timeout_seconds=120,
    )
    if source_preflight.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge exact source image lacks writable scratch space, GNU "
            "incremental tar, or metadata-preserving coreutils required for online pre-copy."
        )
    precopy.update(
        {
            "source_state_save_location": state_path,
            "source_pod_name": str(controller.get("name", "") or ""),
            "source_pod_uid": str(controller.get("uid", "") or ""),
            "source_image": plan.source_slurm_image,
            "archive_path": str(local_archive),
            "incremental_snapshot_path": str(local_snapshot),
            "transfer_token": transfer_token,
            "intent_at": str(precopy.get("intent_at", "") or "") or _utc_now(),
            "gnu_incremental": True,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    local_artifacts = (local_archive, local_snapshot)
    _reset_incomplete_bridge_artifacts(local_artifacts)
    if not all(path.is_file() for path in local_artifacts):
        source_script = (
            _bridge_incremental_tool_preflight_script(root=state_path)
            + "; "
            + f"archive={shlex.quote(remote_archive)}; snapshot={shlex.quote(remote_snapshot)}; "
            + f"complete={shlex.quote(remote_complete)}; "
            + 'if test -f "$complete"; then test -f "$archive"; test -f "$snapshot"; '
            + 'else rm -f -- "$archive" "$snapshot" "$complete"; '
            + "umask 077; "
            + 'tar_status=0; tar --listed-incremental="$snapshot" --numeric-owner '
            + f'--xattrs --acls --one-file-system -cpf "$archive" -C {shlex.quote(state_path)} . '
            + '|| tar_status=$?; test "$tar_status" -le 1; tar -tf "$archive" >/dev/null; '
            + 'sync -f "$archive"; sync -f "$snapshot"; '
            + 'archive_hash=$(sha256sum "$archive" | cut -d " " -f 1); '
            + 'snapshot_hash=$(sha256sum "$snapshot" | cut -d " " -f 1); '
            + 'printf "%s %s\\n" "$archive_hash" "$snapshot_hash" > "$complete"; '
            + 'sync -f "$complete"; fi; cat "$complete"'
        )
        generated = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                str(controller.get("name", "") or ""),
                "-c",
                str(controller.get("container_name", "") or ""),
                "--",
                "/bin/sh",
                "-ec",
                source_script,
            ],
            timeout_seconds=1800,
        )
        if not re.search(r"(?m)^[0-9a-f]{64} [0-9a-f]{64}$", generated.stdout):
            raise RuntimeError(
                "Controller bridge source did not produce a complete incremental pre-copy."
            )
        _bridge_copy_file_from_pod(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            pod=str(controller.get("name", "") or ""),
            container=str(controller.get("container_name", "") or ""),
            source_path=remote_snapshot,
            destination=local_snapshot,
        )
        _bridge_copy_file_from_pod(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            pod=str(controller.get("name", "") or ""),
            container=str(controller.get("container_name", "") or ""),
            source_path=remote_archive,
            destination=local_archive,
        )
    archive_sha256 = _bridge_file_sha256(local_archive)
    snapshot_sha256 = _bridge_file_sha256(local_snapshot)
    source_hashes = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            str(controller.get("name", "") or ""),
            "-c",
            str(controller.get("container_name", "") or ""),
            "--",
            "cat",
            remote_complete,
        ],
        timeout_seconds=120,
    )
    source_hash_match = re.search(
        r"(?m)^([0-9a-f]{64}) ([0-9a-f]{64})$",
        source_hashes.stdout,
    )
    if not source_hash_match or source_hash_match.groups() != (
        archive_sha256,
        snapshot_sha256,
    ):
        raise RuntimeError(
            "recovery-required: local controller pre-copy artifacts do not match the "
            "source-generated immutable completion record."
        )
    for field, observed in (
        ("archive_sha256", archive_sha256),
        ("incremental_snapshot_sha256", snapshot_sha256),
    ):
        recorded = str(precopy.get(field, "") or "")
        if recorded and recorded != observed:
            raise RuntimeError(
                f"recovery-required: controller pre-copy {field} changed after checkpoint."
            )
    _ensure_bridge_stager(
        plan=plan,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    stager_preflight = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            _bridge_incremental_tool_preflight_script(root="/shared"),
        ],
        check=False,
        timeout_seconds=120,
    )
    if stager_preflight.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge exact source image lacks the required GNU incremental tar "
            "or metadata-preserving coreutils contract."
        )
    remote_path, remote_manifest, entry_count = _bridge_stage_precopy_archive(
        plan=plan,
        authority_epoch=epoch,
        archive=local_archive,
        archive_sha256=archive_sha256,
        snapshot=local_snapshot,
        snapshot_sha256=snapshot_sha256,
        transfer_token=transfer_token,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    precopy.update(
        {
            "remote_path": remote_path,
            "archive_sha256": archive_sha256,
            "incremental_snapshot_sha256": snapshot_sha256,
            "remote_manifest_sha256": remote_manifest,
            "file_count": entry_count,
            "completed_at": _utc_now(),
        }
    )
    advance_bridge_stage(journal, BridgeStage.SOURCE_PRECOPIED)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Controller state online pre-copy: GNU incremental baseline and metadata-preserving "
        f"archive staged ({entry_count} entries, manifest sha256={remote_manifest})."
    ]


def _suspend_source_reconciliation_for_bridge(
    *,
    journal: dict[str, Any],
    source_report: Mapping[str, Any],
    target_version: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    try:
        pre_source_mutation_mount_canary(journal)
    except ValueError as exc:
        raise RuntimeError(
            "recovery-required: source reconciliation suspension is blocked until the "
            f"checkpointed pre-source-mutation bridge canary is valid: {exc}"
        ) from exc
    lines = _suspend_legacy_flux_helmreleases(
        command_runner=command_runner,
        kube_context=kube_context,
        phase=journal,
    )
    profile_group = _source_report_migration_profile_group(source_report)
    _changed, pause_lines = _scale_down_legacy_soperator_controllers(
        command_runner=command_runner,
        kube_context=kube_context,
        phase=journal,
        target_version=target_version,
        profile_group=profile_group,
        checkpoint_writer=checkpoint_writer,
    )
    lines.extend(pause_lines)
    selectors = _source_controller_pause_deployment_selectors(profile_group)
    if not selectors:
        lines.extend(
            _ensure_in_place_target_manager_paused(
                phase=journal,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                required=False,
                authority_role="source",
            )
        )
    deployment_fence = _mapping(journal.get("source_controller_reconciliation_fence"))
    modern_manager_fence = _mapping(journal.get("in_place_target_manager_pause"))
    if selectors and deployment_fence.get("status") != "verified":
        raise SoperatorMigrationPhasePending(
            "source Soperator manager scale-to-zero and Pod absence have not been proven."
        )
    if modern_manager_fence and modern_manager_fence.get("status") != "verified":
        raise SoperatorMigrationPhasePending(
            "source Soperator manager scale-to-zero and Pod absence have not been proven."
        )
    manager_fence = modern_manager_fence or deployment_fence
    journal["source_reconciliation"] = {
        "status": "suspended",
        "flux": copy.deepcopy(
            dict(
                _mapping(journal.get("source_flux_reconciliation_fence"))
                or {"status": "absent-or-not-installed"}
            )
        ),
        "manager": copy.deepcopy(
            dict(
                manager_fence
                or {
                    "status": "not-required",
                    "reason": (
                        "the locked source migration profile has no legacy manager selector "
                        "and deployment/soperator-manager is absent"
                    ),
                }
            )
        ),
        "verified_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    return lines


def _controller_bridge_pre_source_fence_node_groups(
    *,
    journal: Mapping[str, Any],
    plan: BridgePlan,
    nebius_api: SoperatorMigrationNebiusApi,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[dict[str, Any]]:
    records = _sequence_of_mappings(journal.get("node_groups"))
    if len(records) != 2:
        raise RuntimeError("Controller bridge pre-source-fence requires two node groups.")
    managed_adapter = all(
        domain.ownership == "managed-existing" for domain in plan.placement_domains
    )
    payloads: Sequence[Mapping[str, Any]] = (
        ({}, {}) if managed_adapter else bridge_node_group_payloads(plan)
    )
    proofs: list[dict[str, Any]] = []
    for slot, (record, expected_payload) in enumerate(zip(records, payloads, strict=True)):
        node_group_id = str(record.get("id", "") or "")
        expected_name = (
            str(record.get("name", "") or "")
            if managed_adapter
            else str(_mapping(expected_payload.get("metadata")).get("name", "") or "")
        )
        if (
            not node_group_id
            or str(record.get("name", "") or "") != expected_name
            or record.get("slot") != slot
        ):
            raise RuntimeError(
                "recovery-required: controller bridge pre-source-fence node-group "
                f"identity is incomplete for slot {slot}."
            )
        live = _node_group_payload_by_id(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
        )
        if _node_group_id(live) != node_group_id or _node_group_name(live) != expected_name:
            raise RuntimeError(
                "recovery-required: controller bridge pre-source-fence provider identity "
                f"changed for slot {slot}."
            )
        if managed_adapter:
            expected_domain = plan.placement_domains[slot]
            if (
                _node_group_fixed_count(live) != expected_domain.ready_capacity
                or _minor_version_text_or_empty(_node_group_version(live))
                != plan.source_kubernetes_version
            ):
                raise RuntimeError(
                    "recovery-required: managed bridge placement-domain capacity or "
                    f"Kubernetes version changed for slot {slot}."
                )
        else:
            checkpointed_id, checkpointed_version = _completed_controller_bridge_record_binding(
                record,
                name=expected_name,
                slot=slot,
            )
            _validate_reused_controller_bridge_quota_group(
                node_group=live,
                name=expected_name,
                slot=slot,
                cluster_id=plan.cluster_id,
                source_version=checkpointed_version or plan.source_kubernetes_version,
                expected_template=_mapping(_mapping(expected_payload.get("spec")).get("template")),
                expected_filesystems_exact=True,
                expected_node_group_id=checkpointed_id,
            )
        domain = _mapping(record.get("scheduling_failure_domain"))
        node_name = str(domain.get("node_name", "") or "")
        node_uid = str(domain.get("node_uid", "") or "")
        topology_key = str(domain.get("topology_key", "") or "")
        topology_value = str(domain.get("topology_value", "") or "")
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        node_labels = _mapping(node_metadata.get("labels"))
        if (
            not node_name
            or str(node_metadata.get("uid", "") or "") != node_uid
            or str(node_labels.get("nebius.com/node-group-id", "") or "") != node_group_id
            or topology_key != "nebius.com/node-group-id"
            or str(node_labels.get(topology_key, "") or "") != topology_value
        ):
            raise RuntimeError(
                "recovery-required: controller bridge pre-source-fence Node UID, node-group, "
                f"or scheduling-domain binding changed for slot {slot}."
            )
        proofs.append(
            {
                "slot": slot,
                "id": node_group_id,
                "name": expected_name,
                "resource_version": _node_group_resource_version(live),
                "controller_spool_attachment_sha256": str(
                    record.get("controller_spool_attachment_sha256", "") or ""
                ),
                "jail_attachment_sha256": str(record.get("jail_attachment_sha256", "") or ""),
                "node_name": node_name,
                "node_uid": node_uid,
                "failure_domain": topology_value,
            }
        )
    if len({item["failure_domain"] for item in proofs}) != 2:
        raise RuntimeError(
            "Controller bridge pre-source-fence proof requires two distinct scheduling domains."
        )
    return proofs


def _source_controller_pre_fence_live_binding(
    *,
    source: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
    source_workload = _mapping(source.get("controller_workload"))
    workload_name = str(source_workload.get("name", "") or "")
    workload_uid = str(source_workload.get("uid", "") or "")
    workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"statefulset.apps.kruise.io/{workload_name}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    workload_metadata = _mapping(workload.get("metadata"))
    if (
        str(workload_metadata.get("uid", "") or "") != workload_uid
        or _resource_replicas(workload, default=-1) != 1
    ):
        raise SoperatorMigrationPhasePending(
            "source controller must remain the exact running singleton while the fresh "
            "pre-fence bridge proof is captured."
        )
    source_pod = _mapping(source.get("controller_pod"))
    pod_name = str(source_pod.get("name", "") or "")
    pod = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod",
            pod_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pod_metadata = _mapping(pod.get("metadata"))
    if str(pod_metadata.get("uid", "") or "") != str(source_pod.get("uid", "") or ""):
        raise RuntimeError(
            "recovery-required: source controller Pod changed before the fresh fence proof."
        )
    return workload, pod


def _prepare_controller_bridge_source_fence(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    plan: BridgePlan,
    source: Mapping[str, Any],
    replicas: int,
    nebius_api: SoperatorMigrationNebiusApi,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> tuple[dict[str, Any], list[str]]:
    if checkpoint_writer is None:
        raise RuntimeError("Controller bridge source fence requires a durable checkpoint writer.")
    intent = journal.get("source_fence_intent")
    readiness = journal.get("pre_source_fence_readiness")
    if not isinstance(intent, dict) or not isinstance(readiness, dict):
        raise RuntimeError("Controller bridge source-fence journal must be mutable.")
    intent_state = str(intent.get("state", "") or "")
    if intent_state in {"dispatching", "accepted"}:
        validate_bridge_journal(journal)
        live_node_groups = _controller_bridge_pre_source_fence_node_groups(
            journal=journal,
            plan=plan,
            nebius_api=nebius_api,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        if _fingerprint(live_node_groups) != str(readiness.get("node_groups_sha256", "") or ""):
            raise RuntimeError(
                "recovery-required: controller bridge pre-source-fence provider or Node "
                "binding changed after fence intent."
            )
        if intent_state == "accepted" or replicas == 0:
            return intent, []
        # A linearizable read of replicas=1 proves the checkpointed scale intent
        # did not take effect while reconciliation remains suspended. Re-run the
        # complete proof instead of treating the prior canary as fresh.
        if replicas != 1:
            raise RuntimeError(
                "recovery-required: source controller replicas are ambiguous after the "
                "checkpointed fence dispatch intent."
            )
    if intent_state not in {"", "intent-recorded", "dispatching"}:
        raise RuntimeError("recovery-required: source fence intent state is unsupported.")
    if replicas != 1:
        raise RuntimeError(
            "recovery-required: source controller changed before a fresh pre-fence proof "
            "could be bound."
        )

    # An intent-recorded checkpoint, or dispatching with the exact singleton
    # still live, proves no scale took effect. Re-run the canary instead of
    # trusting its historical observation after a crash/resume.
    _source_controller_pre_fence_live_binding(
        source=source,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _controller_bridge_pre_source_fence_node_groups(
        journal=journal,
        plan=plan,
        nebius_api=nebius_api,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _prove_controller_bridge_shared_mount(
        journal=journal,
        image=plan.source_slurm_image,
        purpose=CONTROLLER_BRIDGE_PRE_SOURCE_FENCE_CANARY,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    canary = pre_source_fence_mount_canary(journal)
    live_node_groups = _controller_bridge_pre_source_fence_node_groups(
        journal=journal,
        plan=plan,
        nebius_api=nebius_api,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    workload, _pod = _source_controller_pre_fence_live_binding(
        source=source,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    workload_metadata = _mapping(workload.get("metadata"))
    authority_epoch = str(_mapping(journal.get("authority")).get("epoch", "") or "")
    readiness.clear()
    readiness.update(
        {
            "schema": "nebius-cxcli-controller-bridge-pre-source-fence-readiness/v1",
            "status": "verified",
            "authority_epoch": authority_epoch,
            "source_workload_uid": str(
                _mapping(source.get("controller_workload")).get("uid", "") or ""
            ),
            "source_workload_resource_version": str(
                workload_metadata.get("resourceVersion", "") or ""
            ),
            "source_pod_uid": str(_mapping(source.get("controller_pod")).get("uid", "") or ""),
            "source_replicas": 1,
            "canary_sha256": _fingerprint(canary),
            "node_groups": live_node_groups,
            "node_groups_sha256": _fingerprint(live_node_groups),
            "verified_at": _utc_now(),
        }
    )
    readiness["semantic_sha256"] = _fingerprint(readiness)
    intent.clear()
    intent.update(
        {
            "schema": "nebius-cxcli-controller-bridge-source-fence-intent/v1",
            "state": "intent-recorded",
            "authority_epoch": authority_epoch,
            "readiness_sha256": readiness["semantic_sha256"],
            "canary_sha256": readiness["canary_sha256"],
            "source_workload_uid": readiness["source_workload_uid"],
            "source_pod_uid": readiness["source_pod_uid"],
            "intent_at": _utc_now(),
        }
    )
    checkpoint_writer()

    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "accept-only")
    journal["action_broker_mode"] = "accept-only"
    checkpoint_writer()
    validate_bridge_journal(journal)
    return intent, [
        "Controller bridge pre-fence readiness: fresh post-pre-copy two-node shared-SFS "
        "canary, provider attachments, Node UIDs, and distinct zones are bound to the "
        "source authority epoch and durable fence intent."
    ]


def _fence_source_controller_for_bridge(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    plan: BridgePlan,
    source_report: Mapping[str, Any],
    source: Mapping[str, Any],
    target_ref: str,
    target_version: str,
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if str(journal.get("stage", "") or "") != BridgeStage.SOURCE_PRECOPIED.value:
        return []
    try:
        pre_source_mutation_mount_canary(journal)
    except ValueError as exc:
        raise RuntimeError(
            "recovery-required: source controller fencing is blocked until the checkpointed "
            f"pre-source-mutation bridge canary is valid: {exc}"
        ) from exc
    lines = _suspend_source_reconciliation_for_bridge(
        journal=journal,
        source_report=source_report,
        target_version=target_version,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    source_workload = _mapping(source.get("controller_workload"))
    workload_name = str(source_workload.get("name", "") or "")
    workload_uid = str(source_workload.get("uid", "") or "")
    workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"statefulset.apps.kruise.io/{workload_name}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = _mapping(workload.get("metadata"))
    if str(metadata.get("uid", "") or "") != workload_uid:
        raise RuntimeError(
            "recovery-required: source controller workload changed before writer fencing."
        )
    replicas = _resource_replicas(workload, default=-1)
    if replicas not in {0, 1}:
        raise SoperatorMigrationPhasePending(
            f"source controller workload replicas changed outside 1 -> 0 fence: {replicas}."
        )
    dispatch_gap = replicas == 0 and _controller_bridge_source_fence_dispatch_gap(journal)
    source_configuration = journal.get("source_configuration")
    if not isinstance(source_configuration, dict):
        raise RuntimeError("Controller bridge source_configuration must be mutable.")
    expected_contract = _mapping(source_configuration.get("client_config_contract"))
    if dispatch_gap:
        lines.append(
            "Slurm client propagation before-source-fence: retained the durable exact "
            "jailed-config, immutable client identity, and live RPC proof after the "
            "accepted source scale-to-zero dispatch."
        )
    else:
        lines.extend(
            _prove_controller_bridge_client_configuration(
                journal=journal,
                proof_owner=source_configuration,
                proof_key="client_propagation",
                proof_stage="before-source-fence",
                expected_contract=expected_contract,
                required_hosts=tuple(
                    str(item) for item in expected_contract.get("controller_hosts", []) or []
                ),
                target_ref=target_ref,
                source_clients=True,
                require_raised_timeouts=True,
                require_live_rpc=True,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
        lines.extend(
            _reassert_controller_bridge_partition_pause_after_reconfigure(
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
    client_proof = _mapping(source_configuration.get("client_propagation"))
    if (
        client_proof.get("status") != "verified"
        or client_proof.get("live_rpc_verified") is not True
        or client_proof.get("proof_stage") != "before-source-fence"
        or (
            dispatch_gap
            and (
                client_proof.get("config_sha256") != expected_contract.get("config_sha256")
                or client_proof.get("controller_hosts") != expected_contract.get("controller_hosts")
                or client_proof.get("timeouts") != expected_contract.get("timeouts")
            )
        )
    ):
        raise SoperatorMigrationPhasePending(
            "source controller fencing requires the durable source login/worker jailed "
            "configuration and direct RPC propagation proof."
        )

    fencing = journal.get("fencing")
    if not isinstance(fencing, dict) or not isinstance(fencing.get("source"), dict):
        raise RuntimeError("Controller bridge source fencing journal must be mutable.")
    source_fencing = fencing["source"]
    source_pod = _mapping(source.get("controller_pod"))
    source_pod_name = str(source_pod.get("name", "") or "")
    runtime_target = _mapping(source_fencing.get("runtime_target"))
    if not runtime_target:
        live_source_pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "pod",
                source_pod_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        live_pod_metadata = _mapping(live_source_pod.get("metadata"))
        live_pod_spec = _mapping(live_source_pod.get("spec"))
        if str(live_pod_metadata.get("uid", "") or "") != str(source_pod.get("uid", "") or ""):
            raise RuntimeError(
                "recovery-required: source controller Pod changed before runtime fencing."
            )
        source_node_name = str(live_pod_spec.get("nodeName", "") or "")
        live_source_node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", source_node_name, "-o", "json"],
            timeout_seconds=120,
        )
        source_node_uid = str(_mapping(live_source_node.get("metadata")).get("uid", "") or "")
        source_pvc = _mapping(source.get("controller_pvc"))
        source_pv = _mapping(source.get("controller_pv"))
        source_pvc_name = str(source_pvc.get("name", "") or "")
        state_volume_names = {
            str(volume.get("name", "") or "")
            for volume in _sequence_of_mappings(live_pod_spec.get("volumes"))
            if str(_mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or "")
            == source_pvc_name
        }
        mount_paths = {
            str(mount.get("mountPath", "") or "")
            for container in _sequence_of_mappings(live_pod_spec.get("containers"))
            for mount in _sequence_of_mappings(container.get("volumeMounts"))
            if str(mount.get("name", "") or "") in state_volume_names
        }
        if (
            not source_node_name
            or not source_node_uid
            or len(state_volume_names) != 1
            or len(mount_paths) != 1
        ):
            raise SoperatorMigrationPhasePending(
                "source controller runtime fence requires one exact node UID and state mount path."
            )
        runtime_target = {
            "node_name": source_node_name,
            "node_uid": source_node_uid,
            "state_markers": sorted(
                {
                    source_pvc_name,
                    str(source_pvc.get("uid", "") or ""),
                    str(source_pv.get("name", "") or ""),
                    str(source_pv.get("uid", "") or ""),
                    *mount_paths,
                }
                - {""}
            ),
        }
        source_fencing["runtime_target"] = dict(runtime_target)
        if checkpoint_writer is not None:
            checkpoint_writer()
    fence_intent, readiness_lines = _prepare_controller_bridge_source_fence(
        checkpoint=checkpoint,
        journal=journal,
        plan=plan,
        source=source,
        replicas=replicas,
        nebius_api=nebius_api,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    lines.extend(readiness_lines)
    if replicas == 1:
        fence_intent["state"] = "dispatching"
        fence_intent["dispatching_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        readiness = _mapping(journal.get("pre_source_fence_readiness"))
        live_node_groups = _controller_bridge_pre_source_fence_node_groups(
            journal=journal,
            plan=plan,
            nebius_api=nebius_api,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        if _fingerprint(live_node_groups) != str(readiness.get("node_groups_sha256", "") or ""):
            raise RuntimeError(
                "recovery-required: controller bridge provider attachment or Node binding "
                "changed immediately before source scale-to-zero."
            )
        workload, _pod = _source_controller_pre_fence_live_binding(
            source=source,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        metadata = _mapping(workload.get("metadata"))
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"statefulset.apps.kruise.io/{workload_name}",
            replicas=0,
            current_replicas=1,
            resource_version=str(metadata.get("resourceVersion", "") or ""),
        )
    _kubectl_wait(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"pod/{source_pod_name}",
        condition="delete",
        timeout="10m",
        timeout_seconds=660,
    )
    all_pods = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "pods", "-A", "-o", "json"],
        timeout_seconds=120,
    )
    source_pvc_name = str(_mapping(source.get("controller_pvc")).get("name", "") or "")
    remaining_mounts = [
        str(_mapping(pod.get("metadata")).get("namespace", "") or "")
        + "/"
        + str(_mapping(pod.get("metadata")).get("name", "") or "")
        for pod in _sequence_of_mappings(all_pods.get("items"))
        if any(
            str(_mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or "")
            == source_pvc_name
            for volume in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
        )
    ]
    if remaining_mounts:
        raise SoperatorMigrationPhasePending(
            "source controller PVC still has a Pod mount after fence: "
            + ", ".join(remaining_mounts)
            + "."
        )
    runtime_evidence = _prove_controller_runtime_fence(
        journal=journal,
        boundary="source-singleton-stopped",
        targets=(
            ControllerFenceTarget(
                node_name=str(runtime_target.get("node_name", "") or ""),
                node_uid=str(runtime_target.get("node_uid", "") or ""),
                state_markers=tuple(
                    str(item) for item in runtime_target.get("state_markers", []) or []
                ),
            ),
        ),
        image=str(_mapping(journal.get("source_binding")).get("slurm_image_digest", "") or ""),
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        fresh_attempt=True,
    )
    source_fencing.update(
        {
            "proven": True,
            "process_absent": True,
            "writable_mount_absent": True,
            "runtime_evidence": runtime_evidence,
            "observed_at": _utc_now(),
            "remaining_pvc_mounts": [],
        }
    )
    fence_intent["state"] = "accepted"
    fence_intent["accepted_at"] = _utc_now()
    advance_bridge_stage(journal, BridgeStage.SOURCE_FENCED)
    if checkpoint_writer is not None:
        checkpoint_writer()
    lines.append(
        "Source controller fenced: reconciler paused, singleton scaled to zero, "
        "controller Pod absent, and no remaining Pod mounts the source RWO PVC."
    )
    return lines


def _bridge_cold_reader_pod(
    *,
    source: Mapping[str, Any],
    image: str,
    authority_epoch: str,
) -> dict[str, Any]:
    controller = _mapping(source.get("controller_pod"))
    pvc = _mapping(source.get("controller_pvc"))
    return {
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {
            "namespace": _SOPERATOR_NAMESPACE,
            "name": "cxcli-controller-state-cold-reader",
            "labels": {
                "app.kubernetes.io/managed-by": "nebius-cxcli",
                CONTROLLER_BRIDGE_LABEL: "true",
                "nebius.ai/cxcli-controller-bridge-role": "cold-reader",
            },
            "annotations": {
                "nebius.ai/cxcli-authority-epoch": authority_epoch,
                "nebius.ai/cxcli-source-pvc-uid": str(pvc.get("uid", "") or ""),
                "nebius.ai/cxcli-source-pod-uid": str(controller.get("uid", "") or ""),
            },
        },
        "spec": {
            "restartPolicy": "Never",
            "nodeName": str(controller.get("node_name", "") or ""),
            "containers": [
                {
                    "name": "reader",
                    "image": image,
                    "imagePullPolicy": "IfNotPresent",
                    "command": [
                        "/bin/sh",
                        "-ec",
                        "trap 'exit 0' TERM INT; while :; do sleep 30; done",
                    ],
                    "volumeMounts": [
                        {"name": "source", "mountPath": "/source", "readOnly": True},
                        {"name": "work", "mountPath": "/work"},
                    ],
                    "securityContext": {
                        "allowPrivilegeEscalation": False,
                        "readOnlyRootFilesystem": True,
                        "runAsUser": 0,
                    },
                }
            ],
            "volumes": [
                {
                    "name": "source",
                    "persistentVolumeClaim": {
                        "claimName": str(pvc.get("name", "") or ""),
                        "readOnly": True,
                    },
                },
                {"name": "work", "emptyDir": {}},
            ],
        },
    }


def _bridge_source_pvc_mounts(
    *,
    source: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[dict[str, str], ...]:
    source_namespace = str(
        _mapping(source.get("slurmcluster")).get("namespace", "") or _SOPERATOR_NAMESPACE
    )
    source_pvc = str(_mapping(source.get("controller_pvc")).get("name", "") or "")
    all_pods = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "pods", "-A", "-o", "json"],
        timeout_seconds=120,
    )
    mounts: list[dict[str, str]] = []
    for pod in _sequence_of_mappings(all_pods.get("items")):
        metadata = _mapping(pod.get("metadata"))
        if str(metadata.get("namespace", "") or "") != source_namespace:
            continue
        if not any(
            str(_mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or "")
            == source_pvc
            for volume in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
        ):
            continue
        mounts.append(
            {
                "namespace": source_namespace,
                "name": str(metadata.get("name", "") or ""),
                "uid": str(metadata.get("uid", "") or ""),
                "node_name": str(_mapping(pod.get("spec")).get("nodeName", "") or ""),
            }
        )
    return tuple(mounts)


def _assert_bridge_cold_reader_identity(
    *,
    pod: Mapping[str, Any],
    journal_record: Mapping[str, Any],
    source: Mapping[str, Any],
    image: str,
) -> None:
    metadata = _mapping(pod.get("metadata"))
    spec = _mapping(pod.get("spec"))
    controller = _mapping(source.get("controller_pod"))
    pvc = _mapping(source.get("controller_pvc"))
    expected_uid = str(journal_record.get("pod_uid", "") or "")
    observed_uid = str(metadata.get("uid", "") or "")
    if expected_uid and observed_uid != expected_uid:
        raise RuntimeError(
            "recovery-required: controller cold-reader Pod UID changed after intent."
        )
    labels = _mapping(metadata.get("labels"))
    annotations = _mapping(metadata.get("annotations"))
    containers = _sequence_of_mappings(spec.get("containers"))
    reader = next((item for item in containers if item.get("name") == "reader"), {})
    source_volumes = [
        item for item in _sequence_of_mappings(spec.get("volumes")) if item.get("name") == "source"
    ]
    if (
        not observed_uid
        or labels.get(CONTROLLER_BRIDGE_LABEL) != "true"
        or labels.get("nebius.ai/cxcli-controller-bridge-role") != "cold-reader"
        or annotations.get("nebius.ai/cxcli-authority-epoch")
        != journal_record.get("authority_epoch")
        or annotations.get("nebius.ai/cxcli-source-pvc-uid") != str(pvc.get("uid", "") or "")
        or annotations.get("nebius.ai/cxcli-source-pod-uid") != str(controller.get("uid", "") or "")
        or str(spec.get("nodeName", "") or "") != str(controller.get("node_name", "") or "")
        or str(reader.get("image", "") or "") != image
        or len(source_volumes) != 1
        or str(_mapping(source_volumes[0].get("persistentVolumeClaim")).get("claimName", "") or "")
        != str(pvc.get("name", "") or "")
        or _mapping(source_volumes[0].get("persistentVolumeClaim")).get("readOnly") is not True
    ):
        raise RuntimeError(
            "recovery-required: controller cold-reader Pod identity or read-only mount drifted."
        )


def _delete_exact_bridge_cold_reader(
    *,
    journal: dict[str, Any],
    source: Mapping[str, Any],
    image: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    record = journal.get("cold_reader")
    if not isinstance(record, dict) or not str(record.get("pod_uid", "") or ""):
        raise RuntimeError("Controller bridge cold-reader exact identity is not journaled.")
    exists, live = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="pod/cxcli-controller-state-cold-reader",
    )
    if exists:
        _assert_bridge_cold_reader_identity(
            pod=live,
            journal_record=record,
            source=source,
            image=image,
        )
        metadata = _mapping(live.get("metadata"))
        resource_version = str(metadata.get("resourceVersion", "") or "")
        if not resource_version:
            raise RuntimeError("Controller bridge cold-reader Pod has no resourceVersion.")
        record.update(
            {
                "status": "delete-intent",
                "delete_intent_at": str(record.get("delete_intent_at", "") or "") or _utc_now(),
                "delete_resource_version": resource_version,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        delete_options = {
            "apiVersion": "v1",
            "kind": "DeleteOptions",
            "preconditions": {
                "uid": str(record.get("pod_uid", "") or ""),
                "resourceVersion": resource_version,
            },
            "propagationPolicy": "Foreground",
        }
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "delete",
                "--raw",
                "/api/v1/namespaces/soperator/pods/cxcli-controller-state-cold-reader",
                "-f",
                "-",
            ],
            input_text=json.dumps(delete_options, separators=(",", ":")),
            timeout_seconds=120,
        )
        _kubectl_wait(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="pod/cxcli-controller-state-cold-reader",
            condition="delete",
            timeout="10m",
            timeout_seconds=660,
        )
    exists_after, replacement = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="pod/cxcli-controller-state-cold-reader",
    )
    if exists_after:
        replacement_uid = str(_mapping(replacement.get("metadata")).get("uid", "") or "")
        raise RuntimeError(
            "recovery-required: controller cold-reader Pod remains or was replaced after "
            f"exact deletion (uid={replacement_uid or '<missing>'})."
        )
    mounts = _bridge_source_pvc_mounts(
        source=source,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    if mounts:
        raise RuntimeError(
            "recovery-required: source controller RWO PVC has an unknown mount after cold "
            "reader cleanup: "
            + ", ".join(f"{item['namespace']}/{item['name']}[{item['uid']}]" for item in mounts)
        )
    record.update(
        {
            "status": "absent",
            "mount_absent": True,
            "absent_at": str(record.get("absent_at", "") or "") or _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()


def _bridge_upload_immutable_stager_file(
    *,
    plan: BridgePlan,
    local_path: Path,
    remote_path: str,
    expected_sha256: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    probe = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            f"test \"$(sha256sum {shlex.quote(remote_path)} | cut -d ' ' -f 1)\" = {shlex.quote(expected_sha256)}; "
            f'test "$(stat -c %a {shlex.quote(remote_path)})" = 600',
        ],
        check=False,
        timeout_seconds=120,
    )
    if probe.returncode == 0:
        return
    exists = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "test",
            "-e",
            remote_path,
        ],
        check=False,
        timeout_seconds=120,
    )
    if exists.returncode == 0:
        raise RuntimeError(
            "recovery-required: immutable controller cold-delta material hash drifted."
        )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "cp",
            str(local_path),
            f"cxcli-controller-bridge-stager:{remote_path}",
            "-c",
            "stager",
        ],
        timeout_seconds=1800,
    )
    verified = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "sha256sum",
            remote_path,
        ],
        timeout_seconds=120,
    )
    if not re.search(rf"(?m)^{re.escape(expected_sha256)}\s", verified.stdout):
        raise RuntimeError("Controller bridge cold-delta material upload hash mismatch.")
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            f"chmod 600 {shlex.quote(remote_path)}; sync -f {shlex.quote(remote_path)}",
        ],
        timeout_seconds=120,
    )


def _bridge_apply_cold_delta(
    *,
    plan: BridgePlan,
    authority_epoch: str,
    transfer_token: str,
    delta_archive: Path,
    delta_sha256: str,
    source_manifest: Path,
    source_manifest_sha256: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[str, int]:
    if not re.fullmatch(r"[a-z0-9.-]+", authority_epoch) or not re.fullmatch(
        r"[a-f0-9]{32}", transfer_token
    ):
        raise RuntimeError("Controller bridge cold-delta tokens are unsafe.")
    material_dir = "/shared/.cxcli-incremental"
    manifest_dir = "/shared/.cxcli-manifests"
    remote_delta = f"{material_dir}/{authority_epoch}.cold-delta.tar"
    remote_source_manifest = f"{manifest_dir}/{authority_epoch}.cold-source.tree.tsv"
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            f"mkdir -p {material_dir} {manifest_dir}",
        ],
        timeout_seconds=120,
    )
    _bridge_upload_immutable_stager_file(
        plan=plan,
        local_path=delta_archive,
        remote_path=remote_delta,
        expected_sha256=delta_sha256,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _bridge_upload_immutable_stager_file(
        plan=plan,
        local_path=source_manifest,
        remote_path=remote_source_manifest,
        expected_sha256=source_manifest_sha256,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    destination = f"/shared/epochs/{authority_epoch}"
    build = f"/shared/.incoming-{authority_epoch}-cold-delta-{transfer_token}"
    build_manifest = f"{manifest_dir}/{authority_epoch}.cold-build.tree.tsv"
    destination_manifest = f"{manifest_dir}/{authority_epoch}.cold.tree.tsv"
    verify_destination = (
        _bridge_tree_manifest_script(root=destination, output=destination_manifest)
        + "; "
        + f"cmp -s {shlex.quote(destination_manifest)} {shlex.quote(remote_source_manifest)}; "
        + f"sha256sum {shlex.quote(destination_manifest)}"
    )
    existing = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            verify_destination,
        ],
        check=False,
        timeout_seconds=1800,
    )
    if existing.returncode != 0:
        apply_script = (
            _bridge_incremental_tool_preflight_script(root="/shared")
            + "; "
            + f"test ! -e {shlex.quote(destination)}; "
            + f"if test -e {shlex.quote(build)}; then "
            + _bridge_tree_manifest_script(root=build, output=build_manifest)
            + f"; cmp -s {shlex.quote(build_manifest)} {shlex.quote(remote_source_manifest)}; "
            + "else "
            + f"mkdir {shlex.quote(build)}; "
            + "tar --listed-incremental=/dev/null --numeric-owner --xattrs --acls "
            + f"-xpf {shlex.quote(remote_delta)} -C {shlex.quote(build)}; "
            + _bridge_tree_manifest_script(root=build, output=build_manifest)
            + f"; cmp -s {shlex.quote(build_manifest)} {shlex.quote(remote_source_manifest)}; fi; "
            + f"find {shlex.quote(build)} -xdev -type f -exec sync -f {{}} \\;; "
            + f"find {shlex.quote(build)} -xdev -type d -exec sync -f {{}} \\;; "
            + f"sync -f {shlex.quote(build)}; mv {shlex.quote(build)} {shlex.quote(destination)}; "
            + "sync -f /shared/epochs; "
            + f"mv {shlex.quote(build_manifest)} {shlex.quote(destination_manifest)}; "
            + f"sha256sum {shlex.quote(destination_manifest)}"
        )
        existing = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                apply_script,
            ],
            timeout_seconds=1800,
        )
    observed_hash = re.search(r"(?m)^([0-9a-f]{64})\s", existing.stdout)
    if not observed_hash or observed_hash.group(1) != source_manifest_sha256:
        raise RuntimeError(
            "recovery-required: promoted controller state does not match the fenced source "
            "content and metadata manifest."
        )
    with source_manifest.open("r", encoding="utf-8") as handle:
        entry_count = sum(1 for _line in handle)
    return destination, entry_count


def _cold_copy_and_promote_controller_state(
    *,
    journal: dict[str, Any],
    plan: BridgePlan,
    source: Mapping[str, Any],
    artifact_dir: Path,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if str(journal.get("stage", "") or "") != BridgeStage.SOURCE_FENCED.value:
        return []
    try:
        pre_source_mutation_mount_canary(journal)
    except ValueError as exc:
        raise RuntimeError(
            "recovery-required: controller state cold promotion is blocked until the "
            f"checkpointed pre-source-mutation bridge canary is valid: {exc}"
        ) from exc
    epoch = str(_mapping(journal.get("authority")).get("epoch", "") or "")
    if not re.fullmatch(r"[a-z0-9.-]+", epoch):
        raise RuntimeError("Controller bridge authority epoch is unsafe.")
    precopy = _mapping(journal.get("state_precopy"))
    local_baseline = Path(str(precopy.get("incremental_snapshot_path", "") or ""))
    baseline_sha256 = str(precopy.get("incremental_snapshot_sha256", "") or "")
    if (
        not local_baseline.is_file()
        or not re.fullmatch(r"[0-9a-f]{64}", baseline_sha256)
        or _bridge_file_sha256(local_baseline) != baseline_sha256
    ):
        raise RuntimeError(
            "recovery-required: immutable GNU incremental pre-copy baseline is missing or "
            "changed before the cold delta."
        )
    cold_reader = journal.get("cold_reader")
    if not isinstance(cold_reader, dict):
        raise RuntimeError("Controller bridge cold-reader journal must be mutable.")
    controller = _mapping(source.get("controller_pod"))
    pvc = _mapping(source.get("controller_pvc"))
    pvc_exists, live_pvc = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"persistentvolumeclaim/{str(pvc.get('name', '') or '')}",
    )
    if not pvc_exists or str(_mapping(live_pvc.get("metadata")).get("uid", "") or "") != str(
        pvc.get("uid", "") or ""
    ):
        raise RuntimeError(
            "recovery-required: source controller RWO PVC identity changed before cold delta."
        )
    live_node = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "node",
            str(controller.get("node_name", "") or ""),
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    source_node_uid = str(_mapping(live_node.get("metadata")).get("uid", "") or "")
    if not source_node_uid:
        raise RuntimeError("Source controller node has no immutable UID for cold-reader binding.")
    transfer_token = str(cold_reader.get("transfer_token", "") or "") or uuid4().hex
    expected_record = {
        "pod_name": "cxcli-controller-state-cold-reader",
        "source_pvc_name": str(pvc.get("name", "") or ""),
        "source_pvc_uid": str(pvc.get("uid", "") or ""),
        "source_node_name": str(controller.get("node_name", "") or ""),
        "source_node_uid": source_node_uid,
        "source_image": plan.source_slurm_image,
        "authority_epoch": epoch,
        "transfer_token": transfer_token,
    }
    for key, expected in expected_record.items():
        recorded = str(cold_reader.get(key, "") or "")
        if recorded and recorded != expected:
            raise RuntimeError(f"recovery-required: controller cold-reader {key} binding changed.")
        cold_reader[key] = expected
    cold_reader.setdefault("intent_at", _utc_now())
    cold_reader.setdefault("status", "intent-recorded")
    if checkpoint_writer is not None:
        checkpoint_writer()

    reader_exists, live_reader = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="pod/cxcli-controller-state-cold-reader",
    )
    if reader_exists:
        _assert_bridge_cold_reader_identity(
            pod=live_reader,
            journal_record=cold_reader,
            source=source,
            image=plan.source_slurm_image,
        )
    else:
        mounts_before = _bridge_source_pvc_mounts(
            source=source,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        if mounts_before:
            raise RuntimeError(
                "recovery-required: source RWO controller PVC gained an unknown mount before "
                "the exact cold-reader was created."
            )
        if _mapping(journal.get("state_manifest")).get("promoted") is not True:
            reader = _bridge_cold_reader_pod(
                source=source,
                image=plan.source_slurm_image,
                authority_epoch=epoch,
            )
            _kubectl_apply_objects(
                command_runner=command_runner,
                kube_context=kube_context,
                objects=(reader,),
                timeout_seconds=300,
            )
            _kubectl_wait(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                resource="pod/cxcli-controller-state-cold-reader",
                condition="create",
                timeout="2m",
                timeout_seconds=150,
            )
            _kubectl_wait(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                resource="pod/cxcli-controller-state-cold-reader",
                condition="Ready",
                timeout="10m",
                timeout_seconds=660,
            )
            reader_exists, live_reader = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                resource="pod/cxcli-controller-state-cold-reader",
            )
            if not reader_exists:
                raise RuntimeError("Controller bridge cold-reader disappeared after Ready.")
            _assert_bridge_cold_reader_identity(
                pod=live_reader,
                journal_record=cold_reader,
                source=source,
                image=plan.source_slurm_image,
            )
    if reader_exists:
        live_metadata = _mapping(live_reader.get("metadata"))
        observed_uid = str(live_metadata.get("uid", "") or "")
        recorded_uid = str(cold_reader.get("pod_uid", "") or "")
        if recorded_uid and recorded_uid != observed_uid:
            raise RuntimeError("recovery-required: controller cold-reader Pod UID drifted.")
        reader_node = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                "node",
                str(_mapping(live_reader.get("spec")).get("nodeName", "") or ""),
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        if str(_mapping(reader_node.get("metadata")).get("uid", "") or "") != str(
            cold_reader.get("source_node_uid", "") or ""
        ):
            raise RuntimeError(
                "recovery-required: source controller node UID changed under cold-reader."
            )
        statuses = _sequence_of_mappings(
            _mapping(live_reader.get("status")).get("containerStatuses")
        )
        live_status = next((item for item in statuses if item.get("name") == "reader"), {})
        live_image_id = str(live_status.get("imageID", "") or "")
        expected_digest = plan.source_slurm_image.rsplit("sha256:", 1)[-1]
        if expected_digest not in live_image_id:
            raise SoperatorMigrationPhasePending(
                "controller cold-reader is not running the exact immutable source image digest."
            )
        cold_reader.update(
            {
                "pod_uid": observed_uid,
                "pod_resource_version": str(live_metadata.get("resourceVersion", "") or ""),
                "live_image_id": live_image_id,
                "status": "ready",
                "ready_at": str(cold_reader.get("ready_at", "") or "") or _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()

    manifest = journal.get("state_manifest")
    if not isinstance(manifest, dict):
        manifest = dict(_mapping(manifest))
        journal["state_manifest"] = manifest
    if manifest.get("promoted") is not True:
        if not reader_exists:
            raise RuntimeError(
                "recovery-required: promoted state is absent but the exact cold reader is gone."
            )
        delta_token = str(cold_reader.get("delta_token", "") or "") or uuid4().hex
        if not re.fullmatch(r"[0-9a-f]{32}", delta_token):
            raise RuntimeError("Controller bridge cold-delta operation token is invalid.")
        cold_reader["delta_token"] = delta_token
        if checkpoint_writer is not None:
            checkpoint_writer()
        local_delta = artifact_dir / f"{epoch}.{delta_token}.cold-delta.tar"
        local_updated_snapshot = artifact_dir / f"{epoch}.{delta_token}.cold.snar"
        local_source_manifest = artifact_dir / f"{epoch}.{delta_token}.cold-source.tree.tsv"
        remote_prefix = f"/work/{epoch}-{delta_token}.cold"
        remote_delta = f"{remote_prefix}-delta.tar"
        remote_updated_snapshot = f"{remote_prefix}.snar"
        remote_source_manifest = f"{remote_prefix}-source.tree.tsv"
        remote_complete = f"{remote_prefix}.complete"
        local_artifacts = (local_delta, local_updated_snapshot, local_source_manifest)
        _reset_incomplete_bridge_artifacts(local_artifacts)
        if not all(path.is_file() for path in local_artifacts):
            delta_script = (
                _bridge_incremental_tool_preflight_script(root="/source")
                + "; umask 077; "
                + f"delta={shlex.quote(remote_delta)}; snapshot={shlex.quote(remote_updated_snapshot)}; "
                + f"source_manifest={shlex.quote(remote_source_manifest)}; complete={shlex.quote(remote_complete)}; "
                + 'if test -f "$complete"; then test -f "$delta"; test -f "$snapshot"; '
                + 'test -f "$source_manifest"; else rm -f -- "$delta" "$snapshot" '
                + '"$source_manifest" "$complete"; '
                + 'rm -f -- "$snapshot"; '
                + 'tar --format=posix --listed-incremental="$snapshot" --numeric-owner '
                + '--xattrs --acls -cpf "$delta" -C /source .; '
                + _bridge_tree_manifest_script(root="/source", output=remote_source_manifest)
                + '; sync -f "$delta"; sync -f "$snapshot"; '
                + 'delta_hash=$(sha256sum "$delta" | cut -d " " -f 1); '
                + 'snapshot_hash=$(sha256sum "$snapshot" | cut -d " " -f 1); '
                + 'manifest_hash=$(sha256sum "$source_manifest" | cut -d " " -f 1); '
                + 'printf "%s %s %s\\n" "$delta_hash" "$snapshot_hash" "$manifest_hash" '
                + '> "$complete"; sync -f "$complete"; fi; cat "$complete"'
            )
            generated = command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "exec",
                    "cxcli-controller-state-cold-reader",
                    "-c",
                    "reader",
                    "--",
                    "/bin/sh",
                    "-ec",
                    delta_script,
                ],
                timeout_seconds=1800,
            )
            if not re.search(
                r"(?m)^[0-9a-f]{64} [0-9a-f]{64} [0-9a-f]{64}$",
                generated.stdout,
            ):
                raise RuntimeError("Controller bridge cold-reader delta capture is incomplete.")
            for remote_path, local_path in (
                (remote_delta, local_delta),
                (remote_updated_snapshot, local_updated_snapshot),
                (remote_source_manifest, local_source_manifest),
            ):
                _bridge_copy_file_from_pod(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    namespace=_SOPERATOR_NAMESPACE,
                    pod="cxcli-controller-state-cold-reader",
                    container="reader",
                    source_path=remote_path,
                    destination=local_path,
                )
        delta_sha256 = _bridge_file_sha256(local_delta)
        updated_snapshot_sha256 = _bridge_file_sha256(local_updated_snapshot)
        source_manifest_sha256 = _bridge_file_sha256(local_source_manifest)
        cold_hashes = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                "cxcli-controller-state-cold-reader",
                "-c",
                "reader",
                "--",
                "cat",
                remote_complete,
            ],
            timeout_seconds=120,
        )
        cold_hash_match = re.search(
            r"(?m)^([0-9a-f]{64}) ([0-9a-f]{64}) ([0-9a-f]{64})$",
            cold_hashes.stdout,
        )
        if not cold_hash_match or cold_hash_match.groups() != (
            delta_sha256,
            updated_snapshot_sha256,
            source_manifest_sha256,
        ):
            raise RuntimeError(
                "recovery-required: local controller cold-delta artifacts do not match "
                "the fenced reader completion record."
            )
        for field, observed in (
            ("delta_archive_sha256", delta_sha256),
            ("incremental_snapshot_sha256", updated_snapshot_sha256),
            ("source_manifest_sha256", source_manifest_sha256),
        ):
            recorded = str(cold_reader.get(field, "") or "")
            if recorded and recorded != observed:
                raise RuntimeError(
                    f"recovery-required: controller cold-reader {field} changed after checkpoint."
                )
        cold_reader.update(
            {
                "delta_archive_path": str(local_delta),
                "capture_mode": "full-cold-posix-v1",
                "delta_archive_sha256": delta_sha256,
                "delta_archive_size": local_delta.stat().st_size,
                "incremental_snapshot_path": str(local_updated_snapshot),
                "incremental_snapshot_sha256": updated_snapshot_sha256,
                "source_manifest_path": str(local_source_manifest),
                "source_manifest_sha256": source_manifest_sha256,
                "delta_captured_at": str(cold_reader.get("delta_captured_at", "") or "")
                or _utc_now(),
                "status": "delta-captured",
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        destination, file_count = _bridge_apply_cold_delta(
            plan=plan,
            authority_epoch=epoch,
            transfer_token=transfer_token,
            delta_archive=local_delta,
            delta_sha256=delta_sha256,
            source_manifest=local_source_manifest,
            source_manifest_sha256=source_manifest_sha256,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        cold_reader.update(
            {
                "remote_delta_applied": True,
                "remote_epoch_path": destination,
                "remote_apply_at": _utc_now(),
                "status": "promoted-reader-mounted",
            }
        )
        manifest.update(
            {
                "epoch_directory": f"/mnt/controller-spool/epochs/{epoch}",
                "stable_path": "/mnt/controller-spool/current",
                "sha256": source_manifest_sha256,
                "remote_manifest_sha256": source_manifest_sha256,
                "file_count": file_count,
                "fsynced": True,
                "promoted": True,
                "promoted_at": _utc_now(),
                "cold_delta_archive_sha256": delta_sha256,
                "incremental_snapshot_sha256": updated_snapshot_sha256,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    else:
        file_count = int(manifest.get("file_count", 0) or 0)

    expected_current_target = f"epochs/{epoch}"
    current_link = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            "if test -L /shared/current; then observed=$(readlink /shared/current); "
            'test -d "/shared/$observed"; printf "%s\\n" "$observed"; '
            "elif test -e /shared/current; then exit 1; else printf 'CXCLI_ABSENT\\n'; fi",
        ],
        timeout_seconds=120,
    )
    observed_current_target = current_link.stdout.strip()
    campaign_prefix = re.escape(plan.campaign_fingerprint[:12])
    campaign_epoch_pattern = (
        rf"epochs/(?:source|bridge-source|bridge-target|target|pre-target)-"
        rf"{campaign_prefix}(?:-[0-9a-f]{{12}})?"
    )
    if observed_current_target != "CXCLI_ABSENT" and not re.fullmatch(
        campaign_epoch_pattern, observed_current_target
    ):
        raise RuntimeError(
            "recovery-required: controller bridge shared current symlink does not reference "
            "an exact epoch owned by this campaign."
        )
    link_promotion = manifest.setdefault("current_link_promotion", {})
    if not isinstance(link_promotion, dict):
        raise RuntimeError("Controller bridge current-link promotion journal must be mutable.")
    recorded_target = str(link_promotion.get("target", "") or "")
    recorded_preimage = str(link_promotion.get("preimage", "") or "")
    if link_promotion and (
        link_promotion.get("schema") != "nebius-cxcli/controller-bridge-current-link-promotion-v1"
        or (
            recorded_preimage != "CXCLI_ABSENT"
            and not re.fullmatch(campaign_epoch_pattern, recorded_preimage)
        )
    ):
        raise RuntimeError(
            "recovery-required: controller bridge current-link promotion journal is invalid."
        )
    if recorded_target and recorded_target != expected_current_target:
        raise RuntimeError(
            "recovery-required: controller bridge current-link promotion target changed."
        )
    if recorded_preimage and observed_current_target not in {
        recorded_preimage,
        expected_current_target,
    }:
        raise RuntimeError(
            "recovery-required: controller bridge shared current symlink changed after "
            "promotion intent."
        )
    if not recorded_preimage:
        recorded_preimage = observed_current_target
        link_promotion.update(
            {
                "schema": "nebius-cxcli/controller-bridge-current-link-promotion-v1",
                "preimage": recorded_preimage,
                "target": expected_current_target,
                "status": "intent-recorded",
                "intent_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    current_link_script = (
        "set -eu; expected="
        + shlex.quote(expected_current_target)
        + "; preimage="
        + shlex.quote(recorded_preimage)
        + "; temporary="
        + shlex.quote(f"/shared/.current-{epoch}")
        + "; if test -L /shared/current; then "
        "observed=$(readlink /shared/current); "
        'if test "$observed" = "$expected"; then :; else '
        'test "$observed" = "$preimage"; '
        'if test -L "$temporary"; then test "$(readlink "$temporary")" = "$expected"; '
        'elif test -e "$temporary"; then exit 1; else '
        'ln -s "$expected" "$temporary"; fi; '
        'mv -T "$temporary" /shared/current; fi; '
        "elif test -e /shared/current; then exit 1; else "
        'if test -L "$temporary"; then test "$(readlink "$temporary")" = "$expected"; '
        'elif test -e "$temporary"; then exit 1; else '
        'ln -s "$expected" "$temporary"; fi; '
        'mv -T "$temporary" /shared/current; fi; '
        "sync -f /shared"
    )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            current_link_script,
        ],
        timeout_seconds=1800,
    )
    link_promotion.update({"status": "verified", "verified_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    _delete_exact_bridge_cold_reader(
        journal=journal,
        source=source,
        image=plan.source_slurm_image,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    advance_bridge_stage(journal, BridgeStage.STATE_PROMOTED)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Controller state final GNU incremental delta applied to an isolated pre-copy clone "
        f"and promoted atomically: {file_count} entries, manifest "
        f"sha256={manifest.get('sha256')}."
    ]


_SLURMCTLD_CAPABLE_WORKLOAD_RESOURCES = (
    "statefulsets.apps",
    "statefulsets.apps.kruise.io",
    "deployments.apps",
    "replicasets.apps",
    "replicationcontrollers",
    "daemonsets.apps",
    "jobs.batch",
    "cronjobs.batch",
)


def _is_exact_target_controller_command_gate(container: Mapping[str, Any]) -> bool:
    gated_values = target_controller_gate_values({})
    expected = _mapping(
        _mapping(_mapping(gated_values.get("slurmNodes")).get("controller")).get("slurmctld")
    )
    return tuple(str(item) for item in container.get("command", []) or []) == tuple(
        str(item) for item in expected.get("command", []) or []
    ) and tuple(str(item) for item in container.get("args", []) or []) == tuple(
        str(item) for item in expected.get("args", []) or []
    )


def _container_manifest_is_slurmctld_capable(container: Mapping[str, Any]) -> bool:
    if _is_exact_target_controller_command_gate(container):
        return False
    executable_contract = " ".join(
        (
            str(container.get("name", "") or ""),
            str(container.get("image", "") or ""),
            *(str(item) for item in container.get("command", []) or []),
            *(str(item) for item in container.get("args", []) or []),
        )
    ).lower()
    return "slurmctld" in executable_contract


def _pod_spec_is_slurmctld_capable(pod_spec: Mapping[str, Any]) -> bool:
    return any(
        _container_manifest_is_slurmctld_capable(container)
        for container in _sequence_of_mappings(pod_spec.get("containers"))
    )


def _pod_spec_has_exact_target_controller_command_gate(
    pod_spec: Mapping[str, Any],
) -> bool:
    containers = _sequence_of_mappings(pod_spec.get("containers"))
    return len(containers) == 1 and _is_exact_target_controller_command_gate(containers[0])


def _exact_owned_live_target_controller_pods(
    pods: Sequence[Mapping[str, Any]],
    *,
    workload_uid: str,
) -> list[Mapping[str, Any]]:
    return [
        pod
        for pod in pods
        if str(_mapping(pod.get("metadata")).get("name", "") or "") == "controller-0"
        and str(_mapping(pod.get("status")).get("phase", "") or "") not in {"Succeeded", "Failed"}
        and {
            str(owner.get("uid", "") or "")
            for owner in _sequence_of_mappings(_mapping(pod.get("metadata")).get("ownerReferences"))
            if owner.get("controller") is True
        }
        == {workload_uid}
    ]


def _pod_is_exact_inert_controller_bridge_stager(pod: Mapping[str, Any]) -> bool:
    metadata = _mapping(pod.get("metadata"))
    spec = _mapping(pod.get("spec"))
    labels = _mapping(metadata.get("labels"))
    containers = _sequence_of_mappings(spec.get("containers"))
    if len(containers) != 1:
        return False
    container = containers[0]
    return (
        str(metadata.get("namespace", "") or "") == CONTROLLER_BRIDGE_NAMESPACE
        and str(metadata.get("name", "") or "") == "cxcli-controller-bridge-stager"
        and not _sequence_of_mappings(metadata.get("ownerReferences"))
        and labels.get("app.kubernetes.io/managed-by") == "nebius-cxcli"
        and labels.get(CONTROLLER_BRIDGE_LABEL) == "stager"
        and spec.get("restartPolicy") == "Never"
        and not _sequence_of_mappings(spec.get("initContainers"))
        and not _sequence_of_mappings(spec.get("ephemeralContainers"))
        and str(container.get("name", "") or "") == "stager"
        and tuple(str(item) for item in container.get("command", []) or [])
        == (
            "/bin/sh",
            "-ec",
            "trap 'exit 0' TERM INT; while :; do sleep 30; done",
        )
        and not tuple(container.get("args", []) or [])
    )


def _pod_spec_is_exact_inert_controller_bridge_mount_helper(
    pod_spec: Mapping[str, Any],
) -> bool:
    containers = _sequence_of_mappings(pod_spec.get("containers"))
    return (
        len(containers) == 1
        and not _sequence_of_mappings(pod_spec.get("initContainers"))
        and not _sequence_of_mappings(pod_spec.get("ephemeralContainers"))
        and str(containers[0].get("name", "") or "") == "mount-shared-filesystems"
        and tuple(str(item) for item in containers[0].get("command", []) or [])
        == CONTROLLER_BRIDGE_MOUNT_HELPER_COMMAND
        and not tuple(containers[0].get("args", []) or [])
    )


def _pod_spec_is_exact_inert_legacy_controller_placeholder(
    pod_spec: Mapping[str, Any],
) -> bool:
    if _sequence_of_mappings(pod_spec.get("ephemeralContainers")):
        return False
    init_containers = _sequence_of_mappings(pod_spec.get("initContainers"))
    has_inert_munge_sidecar = (
        len(init_containers) == 1
        and str(init_containers[0].get("name", "") or "") == "munge"
        and str(init_containers[0].get("restartPolicy", "") or "") == "Always"
        and tuple(str(item) for item in init_containers[0].get("command", []) or []) == ("sleep",)
        and tuple(str(item) for item in init_containers[0].get("args", []) or []) == ("infinity",)
    )
    containers = _sequence_of_mappings(pod_spec.get("containers"))
    by_name = {
        str(container.get("name", "") or ""): container
        for container in containers
        if str(container.get("name", "") or "")
    }
    expected_name_sets = (
        {"slurmctld", "ensure-jail-virtiofs"},
        {"slurmctld", "wait-for-accounting"},
        {"slurmctld", "wait-for-accounting", "ensure-jail-virtiofs"},
    )
    return (
        has_inert_munge_sidecar
        and len(containers) == len(by_name)
        and set(by_name) in expected_name_sets
        and all(
            tuple(str(item) for item in container.get("command", []) or []) == ("sleep",)
            and tuple(str(item) for item in container.get("args", []) or []) == ("infinity",)
            for container in by_name.values()
        )
    )


def _pod_is_exact_inert_known_controller_helper(pod: Mapping[str, Any]) -> bool:
    metadata = _mapping(pod.get("metadata"))
    spec = _mapping(pod.get("spec"))
    labels = _mapping(metadata.get("labels"))
    owners = _sequence_of_mappings(metadata.get("ownerReferences"))
    owner = owners[0] if len(owners) == 1 and owners[0].get("controller") is True else {}
    bridge_mount = (
        str(metadata.get("namespace", "") or "") == CONTROLLER_BRIDGE_NAMESPACE
        and labels.get("app.kubernetes.io/managed-by") == "nebius-cxcli"
        and labels.get("nebius.ai/cxcli-controller-bridge-mounts") == "true"
        and owner.get("kind") == "DaemonSet"
        and owner.get("name") == "cxcli-controller-bridge-mounts"
        and _pod_spec_is_exact_inert_controller_bridge_mount_helper(spec)
    )
    legacy_placeholder = (
        str(metadata.get("namespace", "") or "") == _SOPERATOR_NAMESPACE
        and labels.get("app.kubernetes.io/managed-by") == "slurm-operator"
        and labels.get("slurm.nebius.ai/controller-type") == "placeholder"
        and owner.get("kind") == "DaemonSet"
        and owner.get("name") == "controller-placeholder"
        and _pod_spec_is_exact_inert_legacy_controller_placeholder(spec)
    )
    return bridge_mount or legacy_placeholder


def _pod_is_exact_checkpointed_controller_runtime_fence(
    pod: Mapping[str, Any],
    *,
    journal: Mapping[str, Any],
) -> bool:
    """Recognize only an exact, verified fence Pod bound in this checkpoint."""

    metadata = _mapping(pod.get("metadata"))
    pod_namespace = str(metadata.get("namespace", "") or "")
    pod_name = str(metadata.get("name", "") or "")
    pod_uid = str(metadata.get("uid", "") or "")
    campaign = str(journal.get("campaign_fingerprint", "") or "")
    spec = _mapping(pod.get("spec"))
    if (
        pod_namespace != CONTROLLER_INSPECTOR_NAMESPACE
        or not pod_name
        or not pod_uid
        or not re.fullmatch(r"[0-9a-f]{64}", campaign)
        or _sequence_of_mappings(metadata.get("ownerReferences"))
        or _sequence_of_mappings(spec.get("initContainers"))
        or _sequence_of_mappings(spec.get("ephemeralContainers"))
    ):
        return False
    for proof in _sequence_of_mappings(journal.get("runtime_fence_proofs")):
        if proof.get("status") != "verified":
            continue
        purpose = str(proof.get("purpose") or proof.get("boundary") or "").strip()
        image = str(proof.get("image", "") or "")
        attempt_id = str(proof.get("attempt_id", "") or "")
        if not purpose or (attempt_id and not re.fullmatch(r"[0-9a-f]{32}", attempt_id)):
            continue
        epoch_slug = re.sub(r"[^a-z0-9.-]+", "-", purpose.lower()).strip("-.")
        proof_epoch = (
            f"fence-{epoch_slug[:32]}-{attempt_id[:12]}".rstrip("-.")
            if attempt_id
            else f"fence-{epoch_slug[:48]}".rstrip("-.")
        )
        results_by_node_uid = {
            str(result.get("node_uid", "") or ""): result
            for result in _sequence_of_mappings(proof.get("results"))
        }
        for target_payload in _sequence_of_mappings(proof.get("targets")):
            node_uid = str(target_payload.get("node_uid", "") or "")
            result = _mapping(results_by_node_uid.get(node_uid))
            if (
                str(result.get("pod_name", "") or "") != pod_name
                or str(result.get("pod_uid", "") or "") != pod_uid
            ):
                continue
            try:
                target = ControllerFenceTarget(
                    node_name=str(target_payload.get("node_name", "") or ""),
                    node_uid=node_uid,
                    state_markers=tuple(
                        str(marker) for marker in target_payload.get("state_markers", []) or []
                    ),
                )
                desired = controller_runtime_fence_pod(
                    campaign_fingerprint=campaign,
                    authority_epoch=proof_epoch,
                    image=image,
                    target=target,
                )
            except (TypeError, ValueError):
                continue
            if _controller_runtime_fence_manifest_contract_matches(pod, desired):
                return True
    return False


def _workload_is_exact_inert_known_controller_helper(
    *,
    resource: str,
    workload: Mapping[str, Any],
) -> bool:
    if resource != "daemonsets.apps":
        return False
    metadata = _mapping(workload.get("metadata"))
    labels = _mapping(metadata.get("labels"))
    pod_spec = _slurmctld_workload_pod_spec(resource, workload)
    bridge_mount = (
        str(metadata.get("namespace", "") or "") == CONTROLLER_BRIDGE_NAMESPACE
        and str(metadata.get("name", "") or "") == "cxcli-controller-bridge-mounts"
        and labels.get("app.kubernetes.io/managed-by") == "nebius-cxcli"
        and labels.get(CONTROLLER_BRIDGE_LABEL) == "true"
        and _pod_spec_is_exact_inert_controller_bridge_mount_helper(pod_spec)
    )
    legacy_placeholder = (
        str(metadata.get("namespace", "") or "") == _SOPERATOR_NAMESPACE
        and str(metadata.get("name", "") or "") == "controller-placeholder"
        and labels.get("app.kubernetes.io/managed-by") == "slurm-operator"
        and labels.get("slurm.nebius.ai/controller-type") == "placeholder"
        and _pod_spec_is_exact_inert_legacy_controller_placeholder(pod_spec)
    )
    return bridge_mount or legacy_placeholder


def _controller_process_binding_from_pod(
    pod: Mapping[str, Any],
    *,
    namespace: str,
    pod_name: str,
    pod_uid: str,
) -> tuple[str, ControllerProcessBinding]:
    metadata = _mapping(pod.get("metadata"))
    spec = _mapping(pod.get("spec"))
    status = _mapping(pod.get("status"))
    if (
        str(metadata.get("namespace", "") or "") != namespace
        or str(metadata.get("name", "") or "") != pod_name
        or str(metadata.get("uid", "") or "") != pod_uid
        or metadata.get("deletionTimestamp")
        or str(status.get("phase", "") or "") != "Running"
    ):
        raise SoperatorMigrationPhasePending(
            f"Controller runtime census lost exact running Pod {namespace}/{pod_name}."
        )
    containers = [
        container
        for container in _sequence_of_mappings(spec.get("containers"))
        if _container_manifest_is_slurmctld_capable(container)
    ]
    if len(containers) != 1:
        raise SoperatorMigrationPhasePending(
            f"Controller runtime census requires one exact expected slurmctld container in "
            f"{namespace}/{pod_name}."
        )
    container_name = str(containers[0].get("name", "") or "")
    container_statuses = [
        item
        for item in _sequence_of_mappings(status.get("containerStatuses"))
        if str(item.get("name", "") or "") == container_name
    ]
    if len(container_statuses) != 1 or not _mapping(
        _mapping(container_statuses[0].get("state")).get("running")
    ):
        raise SoperatorMigrationPhasePending(
            f"Controller runtime census expected container {namespace}/{pod_name}/"
            f"{container_name} is not exactly running."
        )
    container_status = container_statuses[0]
    try:
        binding = ControllerProcessBinding(
            pod_namespace=namespace,
            pod_name=pod_name,
            pod_uid=pod_uid,
            container_name=container_name,
            container_id=str(container_status.get("containerID", "") or ""),
            image_id=str(container_status.get("imageID", "") or ""),
        )
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            f"Controller runtime census expected container binding is incomplete: {exc}"
        ) from exc
    node_name = str(spec.get("nodeName", "") or "")
    if not node_name:
        raise SoperatorMigrationPhasePending(
            f"Controller runtime census expected Pod {namespace}/{pod_name} has no node."
        )
    return node_name, binding


def _prove_controller_runtime_process_census(
    *,
    expected_pods: Sequence[tuple[str, str, str]],
    proof_label: str,
    campaign_fingerprint: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[dict[str, Any]]:
    """Census actual host PIDs on every Node and bind allowed writers to exact CRI IDs."""

    all_pods = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "pods", "--all-namespaces", "-o", "json"],
        timeout_seconds=120,
    )
    pods_by_identity = {
        (
            str(_mapping(pod.get("metadata")).get("namespace", "") or ""),
            str(_mapping(pod.get("metadata")).get("name", "") or ""),
            str(_mapping(pod.get("metadata")).get("uid", "") or ""),
        ): pod
        for pod in _sequence_of_mappings(all_pods.get("items"))
    }
    bindings_by_node: dict[str, list[ControllerProcessBinding]] = {}
    initial_bindings: dict[tuple[str, str, str], dict[str, str]] = {}
    for expected in expected_pods:
        pod = pods_by_identity.get(expected)
        if pod is None:
            raise SoperatorMigrationPhasePending(
                f"{proof_label} runtime census lost expected Pod {expected[0]}/{expected[1]}."
            )
        node_name, binding = _controller_process_binding_from_pod(
            pod,
            namespace=expected[0],
            pod_name=expected[1],
            pod_uid=expected[2],
        )
        bindings_by_node.setdefault(node_name, []).append(binding)
        initial_bindings[expected] = binding.as_payload()

    nodes_payload = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "nodes", "-o", "json"],
        timeout_seconds=120,
    )
    nodes = _sequence_of_mappings(nodes_payload.get("items"))
    if not nodes:
        raise RuntimeError("recovery-required: controller runtime census found no Nodes.")
    targets: list[ControllerRuntimeCensusTarget] = []
    node_identities: dict[str, dict[str, str]] = {}
    for node in nodes:
        node_name = str(_mapping(node.get("metadata")).get("name", "") or "")
        identity = _controller_runtime_node_identity(node, expected_name=node_name)
        if node_name in node_identities:
            raise RuntimeError(
                f"recovery-required: controller runtime census found duplicate Node {node_name}."
            )
        node_identities[node_name] = identity
        targets.append(
            ControllerRuntimeCensusTarget(
                **identity,
                expected_processes=tuple(bindings_by_node.get(node_name, ())),
            )
        )
    if set(bindings_by_node) - set(node_identities):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} expected controller Pod is bound to a Node outside the census."
        )

    purpose_slug = re.sub(r"[^a-z0-9.-]+", "-", proof_label.lower()).strip("-.")
    purpose = f"census-{purpose_slug[:48]}".rstrip("-.")
    attempt_id = uuid4().hex
    results: list[dict[str, Any]] = []
    desired_by_target: list[tuple[ControllerRuntimeCensusTarget, dict[str, Any]]] = []

    def _inspector_pods_by_name() -> dict[str, Mapping[str, Any]]:
        payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                CONTROLLER_INSPECTOR_NAMESPACE,
                "get",
                "pods",
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
        )
        return {
            str(_mapping(pod.get("metadata")).get("name", "") or ""): pod
            for pod in _sequence_of_mappings(payload.get("items"))
            if str(_mapping(pod.get("metadata")).get("name", "") or "")
        }

    for target in targets:
        desired = controller_runtime_census_pod(
            campaign_fingerprint=campaign_fingerprint,
            purpose=purpose,
            attempt_id=attempt_id,
            image=_CONTROLLER_SPOOL_CLEANUP_IMAGE,
            target=target,
        )
        desired_by_target.append((target, desired))

    census_pod_names = [
        str(_mapping(desired.get("metadata")).get("name", "") or "")
        for _target, desired in desired_by_target
    ]
    if len(census_pod_names) != len(set(census_pod_names)) or any(
        not name for name in census_pod_names
    ):
        raise RuntimeError("recovery-required: controller census Pod names are not unique.")
    existing_census_pods = sorted(set(census_pod_names) & set(_inspector_pods_by_name()))
    if existing_census_pods:
        raise RuntimeError(
            "recovery-required: fresh controller runtime census Pod already exists: "
            + ", ".join(existing_census_pods)
            + "."
        )

    def _delete_census_pods_and_prove_absence() -> None:
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                CONTROLLER_INSPECTOR_NAMESPACE,
                "delete",
                "pod",
                *census_pod_names,
                "--ignore-not-found=true",
                "--wait=true",
                "--timeout=120s",
            ],
            timeout_seconds=180,
        )
        remaining = sorted(set(census_pod_names) & set(_inspector_pods_by_name()))
        if remaining:
            raise RuntimeError(
                "recovery-required: controller runtime census cleanup did not prove exact "
                "inspector Pod absence: " + ", ".join(remaining) + "."
            )

    try:
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=tuple(desired for _target, desired in desired_by_target),
            timeout_seconds=300,
        )
        terminal_deadline = time.monotonic() + 300
        terminal_pods: dict[str, Mapping[str, Any]] = {}
        while True:
            observed_pods = _inspector_pods_by_name()
            terminal_pods = {}
            for pod_name in census_pod_names:
                pod = observed_pods.get(pod_name)
                phase = str(_mapping(_mapping(pod).get("status")).get("phase", "") or "")
                if pod is not None and phase in {"Succeeded", "Failed"}:
                    terminal_pods[pod_name] = pod
            if len(terminal_pods) == len(census_pod_names):
                break
            if time.monotonic() >= terminal_deadline:
                pending_nodes = [
                    target.node_name
                    for target, desired in desired_by_target
                    if str(_mapping(desired.get("metadata")).get("name", "") or "")
                    not in terminal_pods
                ]
                raise SoperatorMigrationPhasePending(
                    f"{proof_label} runtime census did not become terminal on: "
                    + ", ".join(pending_nodes)
                    + "."
                )
            time.sleep(1)
        validated_census_pods: list[
            tuple[ControllerRuntimeCensusTarget, dict[str, Any], str, Mapping[str, Any]]
        ] = []
        for target, desired in desired_by_target:
            pod_name = str(_mapping(desired.get("metadata")).get("name", "") or "")
            pod = terminal_pods[pod_name]
            pod_metadata = _mapping(pod.get("metadata"))
            if (
                str(_mapping(pod.get("status")).get("phase", "") or "") != "Succeeded"
                or str(_mapping(pod.get("spec")).get("nodeName", "") or "") != target.node_name
                or not str(pod_metadata.get("uid", "") or "")
                or not _desired_manifest_contract_matches(pod, desired)
            ):
                raise SoperatorMigrationPhasePending(
                    f"{proof_label} runtime census did not complete exactly on {target.node_name}."
                )
            validated_census_pods.append((target, desired, pod_name, pod))

        evidence_by_pod: dict[str, ControllerRuntimeCensusEvidence] = {}
        max_log_readers = min(8, len(validated_census_pods))
        with ThreadPoolExecutor(max_workers=max_log_readers) as executor:
            futures = {
                executor.submit(
                    _collect_controller_runtime_census_evidence,
                    pod_name=pod_name,
                    target=target,
                    proof_label=proof_label,
                    kube_context=kube_context,
                    command_runner=command_runner,
                ): pod_name
                for target, _desired, pod_name, _pod in validated_census_pods
            }
            for future in as_completed(futures):
                pod_name = futures[future]
                evidence_by_pod[pod_name] = future.result()

        for target, _desired, pod_name, pod in validated_census_pods:
            pod_metadata = _mapping(pod.get("metadata"))
            results.append(
                {
                    **target.__dict__,
                    "expected_processes": [
                        binding.as_payload() for binding in target.expected_processes
                    ],
                    "evidence": evidence_by_pod[pod_name].as_payload(),
                    "census_pod_uid": str(pod_metadata.get("uid", "") or ""),
                    "attempt_id": attempt_id,
                }
            )
        for expected, initial_binding in initial_bindings.items():
            pod = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    expected[0],
                    "get",
                    "pod",
                    expected[1],
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
            _node_name, current_binding = _controller_process_binding_from_pod(
                pod,
                namespace=expected[0],
                pod_name=expected[1],
                pod_uid=expected[2],
            )
            if current_binding.as_payload() != initial_binding:
                raise RuntimeError(
                    f"recovery-required: expected controller container changed during "
                    f"{proof_label}: {expected[0]}/{expected[1]}."
                )

        final_results = _revalidate_controller_runtime_census_nodes(
            node_census=results,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        current_by_name = {item["node_name"]: item for item in final_results}
        for result in results:
            result.update(current_by_name[str(result.get("node_name", "") or "")])
        return results
    finally:
        _delete_census_pods_and_prove_absence()


def _collect_controller_runtime_census_evidence(
    *,
    pod_name: str,
    target: ControllerRuntimeCensusTarget,
    proof_label: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> ControllerRuntimeCensusEvidence:
    """Read an immutable terminal census log with bounded transport retries."""

    last_reason = "no evidence returned"
    for attempt in range(3):
        logs = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                CONTROLLER_INSPECTOR_NAMESPACE,
                "logs",
                f"pod/{pod_name}",
                "-c",
                "inspector",
                "--request-timeout=20s",
            ],
            check=False,
            timeout_seconds=60,
        )
        if logs.returncode != 0:
            last_reason = "kubectl logs did not return successfully"
        else:
            try:
                return parse_controller_runtime_census_evidence(logs.stdout, target=target)
            except ValueError as exc:
                # The completed Pod and its container log are immutable. Retrying
                # only the read handles transient auth/proxy text without accepting
                # a persistently malformed or ambiguous census payload.
                last_reason = str(exc)
        if attempt < 2:
            time.sleep(1)
    raise SoperatorMigrationPhasePending(
        f"{proof_label} runtime census failed on {target.node_name} after three "
        f"immutable log reads: {last_reason}."
    )


def _prove_controller_runtime_process_census_with_fresh_retry(
    *,
    expected_pods: Sequence[tuple[str, str, str]],
    proof_label: str,
    campaign_fingerprint: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[dict[str, Any]]:
    """Retry one whole census when a terminal Pod produced malformed evidence."""

    for attempt in range(2):
        try:
            return _prove_controller_runtime_process_census(
                expected_pods=expected_pods,
                proof_label=proof_label,
                campaign_fingerprint=campaign_fingerprint,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        except SoperatorMigrationPhasePending as exc:
            if attempt == 0 and "after three immutable log reads" in str(exc):
                # The failed attempt has already deleted every exact census Pod and
                # proved absence in its finally block. A new attempt ID produces a
                # genuinely fresh host scan rather than rereading ambiguous evidence.
                continue
            raise
    raise AssertionError("fresh controller runtime census retry exhausted")


def _slurmctld_workload_pod_spec(
    resource: str,
    workload: Mapping[str, Any],
) -> Mapping[str, Any]:
    spec = _mapping(workload.get("spec"))
    if resource == "cronjobs.batch":
        template = _mapping(_mapping(spec.get("jobTemplate")).get("spec")).get("template")
    else:
        template = spec.get("template")
    return _mapping(_mapping(template).get("spec"))


def _slurmctld_workload_desired_replicas(
    resource: str,
    workload: Mapping[str, Any],
) -> int:
    spec = _mapping(workload.get("spec"))
    if resource == "daemonsets.apps":
        return 1
    if resource == "jobs.batch":
        conditions = _sequence_of_mappings(_mapping(workload.get("status")).get("conditions"))
        terminal = any(
            str(condition.get("type", "") or "") in {"Complete", "Failed"}
            and str(condition.get("status", "") or "").lower() == "true"
            for condition in conditions
        )
        if terminal or _bool_value(spec.get("suspend"), fallback=False):
            return 0
        if _non_negative_int(spec.get("completions"), fallback=1) == 0:
            return 0
        return _non_negative_int(spec.get("parallelism"), fallback=1)
    if resource == "cronjobs.batch":
        return 0 if _bool_value(spec.get("suspend"), fallback=False) else 1
    return _resource_replicas(workload, default=1)


def _prove_cluster_wide_slurmctld_exclusivity(
    *,
    expected_pods: Sequence[tuple[str, str, str]],
    expected_workload: tuple[str, str, str, str] | None,
    expected_replicas: int,
    proof_label: str,
    campaign_fingerprint: str,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    process_census: bool = True,
) -> list[dict[str, Any]]:
    if str(journal.get("campaign_fingerprint", "") or "") != campaign_fingerprint:
        raise RuntimeError(f"{proof_label} checkpoint campaign binding changed.")
    expected_pod_set = set(expected_pods)
    if len(expected_pod_set) != len(expected_pods) or any(
        not namespace or not name or not uid for namespace, name, uid in expected_pods
    ):
        raise RuntimeError(f"{proof_label} has incomplete or duplicate journaled Pod bindings.")
    if expected_replicas == 0:
        if expected_pods or expected_workload is not None:
            raise RuntimeError(f"{proof_label} zero-authority proof has unexpected bindings.")
        expected_uid = ""
    else:
        if expected_workload is None:
            raise RuntimeError(f"{proof_label} has no journaled workload binding.")
        expected_resource, expected_namespace, expected_name, expected_uid = expected_workload
        if (
            expected_resource not in _SLURMCTLD_CAPABLE_WORKLOAD_RESOURCES
            or not expected_namespace
            or not expected_name
            or not expected_uid
            or expected_replicas < 0
        ):
            raise RuntimeError(f"{proof_label} has an incomplete journaled workload binding.")

    all_pods = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "pods", "--all-namespaces", "-o", "json"],
        timeout_seconds=120,
    )
    live_pods: dict[tuple[str, str, str], Mapping[str, Any]] = {}
    for pod in _sequence_of_mappings(all_pods.get("items")):
        metadata = _mapping(pod.get("metadata"))
        phase = str(_mapping(pod.get("status")).get("phase", "") or "")
        if phase in {"Succeeded", "Failed"}:
            continue
        if (
            _pod_is_exact_inert_controller_bridge_stager(pod)
            or _pod_is_exact_inert_known_controller_helper(pod)
            or _pod_is_exact_checkpointed_controller_runtime_fence(pod, journal=journal)
        ):
            continue
        if not _pod_spec_is_slurmctld_capable(_mapping(pod.get("spec"))):
            continue
        identity = (
            str(metadata.get("namespace", "") or ""),
            str(metadata.get("name", "") or ""),
            str(metadata.get("uid", "") or ""),
        )
        live_pods[identity] = pod
    if set(live_pods) != expected_pod_set:
        raise SoperatorMigrationPhasePending(
            f"{proof_label} found a second nonterminal or otherwise unexpected "
            "slurmctld-capable Pod, or lost a journaled controller. Pending and "
            "crash-looping Pods are unsafe even before start."
        )
    for identity, pod in live_pods.items():
        if _mapping(pod.get("metadata")).get("deletionTimestamp"):
            raise SoperatorMigrationPhasePending(
                f"{proof_label} controller Pod {identity[0]}/{identity[1]} is terminating; "
                "runtime authority is unsafe until its node-level fence completes."
            )
        owner_uids = {
            str(owner.get("uid", "") or "")
            for owner in _sequence_of_mappings(_mapping(pod.get("metadata")).get("ownerReferences"))
            if owner.get("controller") is True
        }
        if expected_uid not in owner_uids:
            raise SoperatorMigrationPhasePending(
                f"{proof_label} Pod {identity[0]}/{identity[1]} is not owned by the "
                "journaled controller workload."
            )

    def _load_slurmctld_capable_workloads(resource: str) -> Mapping[str, Any]:
        return _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                resource,
                "--all-namespaces",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )

    # These cluster-wide reads are independent and were the dominant latency in
    # every authority gate. Keep the mutation path serial, but bound concurrent
    # read-only discovery so a fresh all-node census is not needlessly delayed.
    with ThreadPoolExecutor(
        max_workers=min(4, len(_SLURMCTLD_CAPABLE_WORKLOAD_RESOURCES))
    ) as executor:
        workload_payloads = tuple(
            executor.map(
                _load_slurmctld_capable_workloads,
                _SLURMCTLD_CAPABLE_WORKLOAD_RESOURCES,
            )
        )

    live_workloads: dict[tuple[str, str, str, str], int] = {}
    for resource, workloads in zip(
        _SLURMCTLD_CAPABLE_WORKLOAD_RESOURCES,
        workload_payloads,
        strict=True,
    ):
        for workload in _sequence_of_mappings(workloads.get("items")):
            metadata = _mapping(workload.get("metadata"))
            desired = _slurmctld_workload_desired_replicas(resource, workload)
            if _workload_is_exact_inert_known_controller_helper(
                resource=resource,
                workload=workload,
            ):
                continue
            if desired <= 0 or not _pod_spec_is_slurmctld_capable(
                _slurmctld_workload_pod_spec(resource, workload)
            ):
                continue
            identity = (
                resource,
                str(metadata.get("namespace", "") or ""),
                str(metadata.get("name", "") or ""),
                str(metadata.get("uid", "") or ""),
            )
            if metadata.get("deletionTimestamp"):
                raise SoperatorMigrationPhasePending(
                    f"{proof_label} slurmctld-capable workload {identity[1]}/{identity[2]} "
                    "is terminating and remains unsafe."
                )
            live_workloads[identity] = desired
    expected_workloads = {} if expected_workload is None else {expected_workload: expected_replicas}
    if live_workloads != expected_workloads:
        raise SoperatorMigrationPhasePending(
            f"{proof_label} found another desired workload that can create slurmctld Pods, "
            "lost its journaled workload, or observed replicas other than "
            f"{expected_replicas}."
        )
    if not process_census:
        return []
    return _prove_controller_runtime_process_census_with_fresh_retry(
        expected_pods=expected_pods,
        proof_label=proof_label,
        campaign_fingerprint=campaign_fingerprint,
        kube_context=kube_context,
        command_runner=command_runner,
    )


def _controller_bridge_runtime_pod_bindings(
    *,
    journal: Mapping[str, Any],
    roles: Sequence[Mapping[str, Any]],
    live_pods: Mapping[str, Mapping[str, Any]],
    workload_uid: str,
) -> tuple[tuple[str, str, str], ...]:
    """Resolve exact bridge Pods, including the journaled authentication restart."""

    namespace = str(journal.get("namespace", "") or "")
    journaled = tuple(
        (
            namespace,
            str(role.get("pod_name", "") or ""),
            str(role.get("pod_uid", "") or ""),
        )
        for role in roles
    )
    live = tuple(
        (
            namespace,
            name,
            str(_mapping(pod.get("metadata")).get("uid", "") or ""),
        )
        for name, pod in sorted(live_pods.items())
    )
    if len(journaled) != 2 or any(not name or not uid for _, name, uid in journaled):
        raise RuntimeError("controller bridge requires exactly two journaled Pod identities.")
    if live == tuple(sorted(journaled)):
        return live

    handoff = _mapping(
        _mapping(journal.get("target_singleton_takeover")).get("bridge_authentication_handoff")
    )
    pre_stop = tuple(
        sorted(
            (
                str(item.get("namespace", "") or ""),
                str(item.get("name", "") or ""),
                str(item.get("uid", "") or ""),
            )
            for item in _sequence_of_mappings(handoff.get("pre_stop_pods"))
        )
    )
    if (
        handoff.get("status") not in {"restart-dispatching", "restart-accepted", "verified"}
        or str(handoff.get("statefulset_uid", "") or "") != workload_uid
        or pre_stop != tuple(sorted(journaled))
        or len(live_pods) != 2
        or set(live_pods) != {name for _, name, _ in journaled}
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge Pod identities changed outside the exact authentication restart."
        )
    role_by_name = {str(role.get("pod_name", "") or ""): role for role in roles}
    for name, pod in live_pods.items():
        metadata = _mapping(pod.get("metadata"))
        pod_uid = str(metadata.get("uid", "") or "")
        role = role_by_name[name]
        owners = _sequence_of_mappings(metadata.get("ownerReferences"))
        exact_owner = [
            owner
            for owner in owners
            if owner.get("controller") is True
            and owner.get("kind") == "StatefulSet"
            and owner.get("name") == "cxcli-slurm-controller-bridge"
            and owner.get("uid") == workload_uid
        ]
        if (
            not pod_uid
            or metadata.get("deletionTimestamp")
            or str(_mapping(pod.get("spec")).get("nodeName", "") or "")
            != str(role.get("node_name", "") or "")
            or len(exact_owner) != 1
        ):
            raise SoperatorMigrationPhasePending(
                "controller bridge authentication restart successor lost its exact "
                "StatefulSet or node binding."
            )
    return live


def _prove_journaled_controller_bridge_exclusivity(
    *,
    journal: Mapping[str, Any],
    proof_label: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    process_census: bool = True,
) -> None:
    _revalidate_controller_authority_lease(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    namespace = str(journal.get("namespace", "") or "")
    roles = _sequence_of_mappings(journal.get("controller_roles"))
    journaled_pods = tuple(
        (
            namespace,
            str(role.get("pod_name", "") or ""),
            str(role.get("pod_uid", "") or ""),
        )
        for role in roles
    )
    if len(journaled_pods) != 2:
        raise RuntimeError(f"{proof_label} requires exactly two journaled bridge Pods.")
    writer_scale = _mapping(_mapping(journal.get("authority")).get("writer_scale"))
    workload_uid = str(writer_scale.get("statefulset_uid", "") or "")
    if writer_scale.get("state") != "accepted" or writer_scale.get("to_replicas") != 2:
        raise RuntimeError(f"{proof_label} requires the accepted journaled replicas=2 scale.")
    _revalidate_controller_bridge_mirrored_material(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    workload_exists, workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    workload_metadata = _mapping(workload.get("metadata"))
    if (
        not workload_exists
        or str(workload_metadata.get("uid", "") or "") != workload_uid
        or _resource_replicas(workload, default=-1) != 2
    ):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} lost the exact two-replica bridge workload binding."
        )
    pod_spec = _mapping(_mapping(_mapping(workload.get("spec")).get("template")).get("spec"))
    containers = _sequence_of_mappings(pod_spec.get("containers"))
    slurmctld = next(
        (item for item in containers if "slurmctld" in str(item.get("name", "") or "").lower()),
        {},
    )
    expected_images = {str(role.get("image", "") or "") for role in roles}
    expected_image = next(iter(expected_images), "")
    if (
        len(expected_images) != 1
        or not re.fullmatch(r"[^\s]+@sha256:[0-9a-f]{64}", expected_image)
        or str(slurmctld.get("image", "") or "") not in expected_images
    ):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} bridge workload is not bound to one exact journaled OCI digest."
        )
    state_path = str(
        _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
    )
    state_volume_names = {
        str(volume.get("name", "") or "")
        for volume in _sequence_of_mappings(pod_spec.get("volumes"))
        if str(_mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or "")
        == "cxcli-controller-bridge-state"
    }
    state_mounts = [
        mount
        for mount in _sequence_of_mappings(slurmctld.get("volumeMounts"))
        if str(mount.get("name", "") or "") in state_volume_names
    ]
    if (
        not state_path.startswith("/")
        or len(state_volume_names) != 1
        or len(state_mounts) != 1
        or str(state_mounts[0].get("mountPath", "") or "") != state_path
        or str(state_mounts[0].get("subPath", "") or "") != "current"
    ):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} StateSaveLocation is not backed by the journaled shared current "
            "subPath mount."
        )
    config_candidates: list[str] = []
    for record in _sequence_of_mappings(journal.get("mirrored_material")):
        if str(record.get("kind", "") or "") != "ConfigMap":
            continue
        live = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "configmap",
                str(record.get("name", "") or ""),
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        config_candidates.extend(
            str(value or "")
            for value in _mapping(live.get("data")).values()
            if "ClusterName=" in str(value)
        )
    if len(config_candidates) != 1 or not re.search(
        rf"(?im)^\s*StateSaveLocation\s*=\s*{re.escape(state_path)}\s*$",
        config_candidates[0],
    ):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} live Slurm configuration does not resolve StateSaveLocation "
            "through the shared state mount."
        )
    expected_digest = expected_image.rsplit("@sha256:", 1)[-1]
    live_pods: dict[str, Mapping[str, Any]] = {}
    for role in roles:
        pod_name = str(role.get("pod_name", "") or "")
        pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pod",
                pod_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        live_pods[pod_name] = pod
        container_status = next(
            (
                item
                for item in _sequence_of_mappings(
                    _mapping(pod.get("status")).get("containerStatuses")
                )
                if item.get("name") == slurmctld.get("name")
            ),
            {},
        )
        if expected_digest not in str(container_status.get("imageID", "") or ""):
            raise SoperatorMigrationPhasePending(
                f"{proof_label} bridge Pod {pod_name} image digest changed."
            )
    expected_pods = _controller_bridge_runtime_pod_bindings(
        journal=journal,
        roles=roles,
        live_pods=live_pods,
        workload_uid=workload_uid,
    )
    _prove_cluster_wide_slurmctld_exclusivity(
        expected_pods=expected_pods,
        expected_workload=(
            "statefulsets.apps",
            namespace,
            "cxcli-slurm-controller-bridge",
            workload_uid,
        ),
        expected_replicas=2,
        proof_label=proof_label,
        campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        process_census=process_census,
    )


def _target_singleton_current_config_sha256(
    *,
    journal: Mapping[str, Any],
    checkpoint: Mapping[str, Any] | None,
) -> str:
    original = str(
        _mapping(journal.get("target_singleton_takeover")).get("final_config_sha256") or ""
    )
    if checkpoint is None:
        return original
    stage = str(journal.get("stage") or "")
    if stage not in {
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
    }:
        return original
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    target_binding = _mapping(_mapping(rolling.get("slurmcluster_handoff_binding")).get("target"))
    post_open_metrics = _mapping(
        _mapping(
            _mapping(rolling.get("legacy_rootfs_slurm_config_bridge")).get("target_writer_release")
        ).get("post_open_metrics_config")
    )
    topology = _mapping(post_open_metrics.get("topology_values_replay"))
    final_values = _mapping(topology.get("final_values_reconciliation"))
    config = _mapping(topology.get("config"))
    promoted = str(config.get("full_sha256") or "")
    if not topology and not final_values:
        return original
    if (
        topology.get("schema") != _LEGACY_ROOTFS_POST_OPEN_METRICS_TOPOLOGY_REPLAY_SCHEMA
        or topology.get("status") != "verified"
        or str(topology.get("target_uid") or "") != str(target_binding.get("uid") or "")
        or final_values.get("schema") != _LEGACY_ROOTFS_FINAL_VALUES_REPLAY_SCHEMA
        or final_values.get("status") != "verified"
        or final_values.get("active_jail_slot") != "slot-b"
        or str(final_values.get("values_fingerprint") or "")
        != str(topology.get("values_fingerprint") or "")
        or not re.fullmatch(r"[0-9a-f]{64}", str(final_values.get("proof_fingerprint") or ""))
        or not re.fullmatch(r"[0-9a-f]{64}", promoted)
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton current client configuration lacks the exact final-values "
            "topology successor proof."
        )
    return promoted


def _prove_journaled_target_singleton_exclusivity(
    *,
    journal: Mapping[str, Any],
    proof_label: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint: Mapping[str, Any] | None = None,
) -> None:
    _revalidate_controller_authority_lease(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    takeover = _mapping(journal.get("target_singleton_takeover"))
    pod_uid = str(takeover.get("controller_pod_uid", "") or "")
    workload_uid = str(takeover.get("controller_workload_uid", "") or "")
    if not pod_uid or not workload_uid:
        raise RuntimeError(f"{proof_label} has an incomplete target singleton binding.")
    _prove_cluster_wide_slurmctld_exclusivity(
        expected_pods=((_SOPERATOR_NAMESPACE, "controller-0", pod_uid),),
        expected_workload=(
            "statefulsets.apps.kruise.io",
            _SOPERATOR_NAMESPACE,
            "controller",
            workload_uid,
        ),
        expected_replicas=1,
        proof_label=proof_label,
        campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    final_config_sha256 = _target_singleton_current_config_sha256(
        journal=journal,
        checkpoint=checkpoint,
    )
    if not final_config_sha256:
        # TARGET_SINGLETON_ACTIVE is an intermediate, accept-only stage.  Its
        # final one-host client contract is installed immediately afterwards.
        return
    if not re.fullmatch(r"[0-9a-f]{64}", final_config_sha256):
        raise RuntimeError(f"{proof_label} has an invalid final configuration digest.")
    config_name = str(takeover.get("final_config_map_name", "") or "")
    config_map = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "configmap",
            config_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    config_key = str(_mapping(journal.get("source_configuration")).get("config_key", "") or "")
    final_config = str(_mapping(config_map.get("data")).get(config_key, "") or "")
    target_state_path = str(takeover.get("target_state_save_location", "") or "")
    target_ref = str(takeover.get("target_ref", "") or "")
    expected_singleton_host = f"controller-0({target_ref}-controller-svc)"
    if (
        not config_key
        or not target_ref
        or not target_state_path.startswith("/")
        or hashlib.sha256(final_config.encode("utf-8")).hexdigest() != final_config_sha256
        or re.findall(r"(?im)^\s*SlurmctldHost\s*=\s*(\S+)\s*$", final_config)
        != [expected_singleton_host]
        or not re.search(
            rf"(?im)^\s*StateSaveLocation\s*=\s*{re.escape(target_state_path)}\s*$",
            final_config,
        )
    ):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} final one-host configuration or shared state path drifted."
        )
    target_image = str(_mapping(journal.get("version_transition")).get("target_image", "") or "")
    expected_digest = target_image.rsplit("@sha256:", 1)[-1]
    target_pod = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod/controller-0",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    containers = _sequence_of_mappings(_mapping(target_pod.get("spec")).get("containers"))
    container = next(
        (item for item in containers if "slurmctld" in str(item.get("name", "") or "").lower()),
        {},
    )
    status = next(
        (
            item
            for item in _sequence_of_mappings(
                _mapping(target_pod.get("status")).get("containerStatuses")
            )
            if item.get("name") == container.get("name")
        ),
        {},
    )
    if (
        str(_mapping(target_pod.get("metadata")).get("uid", "") or "") != pod_uid
        or not expected_digest
        or expected_digest not in str(status.get("imageID", "") or "")
    ):
        raise SoperatorMigrationPhasePending(
            f"{proof_label} target Pod identity or locked OCI digest changed."
        )
    consumers = _controller_bridge_client_consumers(
        journal=journal,
        target_ref=str(takeover.get("target_ref", "") or ""),
        source_clients=False,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    for consumer in consumers:
        prefix = [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            str(consumer["name"]),
            "-c",
            str(consumer["container_name"]),
            "--",
        ]
        config = command_runner(
            [*prefix, "cat", _SOPERATOR_LEGACY_SLURM_CONF],
            check=False,
            timeout_seconds=120,
        )
        ping = command_runner(
            [
                *prefix,
                "env",
                f"SLURM_CONF={_SOPERATOR_LEGACY_SLURM_CONF}",
                "scontrol",
                "ping",
            ],
            check=False,
            timeout_seconds=120,
        )
        if (
            config.returncode != 0
            or hashlib.sha256(config.stdout.encode("utf-8")).hexdigest() != final_config_sha256
            or ping.returncode != 0
            or not re.search(
                r"Slurmctld\(primary\).*\bis\s+UP\b",
                ping.stdout,
                re.IGNORECASE,
            )
        ):
            raise SoperatorMigrationPhasePending(
                f"{proof_label} client {consumer['name']} lost the final config or "
                "authenticated controller connectivity."
            )


def _prove_cluster_wide_slurmctld_absence(
    *,
    proof_label: str,
    campaign_fingerprint: str,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    process_census: bool = True,
) -> list[dict[str, Any]]:
    return _prove_cluster_wide_slurmctld_exclusivity(
        expected_pods=(),
        expected_workload=None,
        expected_replicas=0,
        proof_label=proof_label,
        campaign_fingerprint=campaign_fingerprint,
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        process_census=process_census,
    )


def _prove_source_bridge_takeover(
    *,
    journal: dict[str, Any],
    pod_by_name: Mapping[str, Mapping[str, Any]],
    source_container: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> str:
    """Select the first bridge backup and prove that it assumed live control."""

    takeover = journal.get("source_bridge_takeover")
    if not isinstance(takeover, dict):
        takeover = {}
        journal["source_bridge_takeover"] = takeover
    ordered_names = sorted(pod_by_name)
    if len(ordered_names) != 2:
        raise RuntimeError("Source bridge takeover requires exactly two bridge Pods.")
    target_name = ordered_names[0]
    target_uid = str(_mapping(pod_by_name[target_name].get("metadata")).get("uid", "") or "")
    if not target_uid:
        raise RuntimeError("Source bridge takeover target has no immutable Pod UID.")
    recorded_name = str(takeover.get("pod_name", "") or "")
    recorded_uid = str(takeover.get("pod_uid", "") or "")
    if recorded_name and (recorded_name != target_name or recorded_uid != target_uid):
        raise RuntimeError("recovery-required: source bridge takeover target Pod identity changed.")

    def _primary_markers() -> list[str]:
        return _source_bridge_primary_markers(
            journal=journal,
            ordered_names=ordered_names,
            source_container=source_container,
            kube_context=kube_context,
            command_runner=command_runner,
        )

    primary_names = _primary_markers()
    if len(primary_names) > 1:
        raise RuntimeError(
            "recovery-required: both source bridge Pods report primary-controller activation."
        )
    if not primary_names:
        takeover.update(
            {
                "state": "dispatching",
                "pod_name": target_name,
                "pod_uid": target_uid,
                "backup_index": 1,
                "dispatching_at": str(takeover.get("dispatching_at", "") or "") or _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                str(journal.get("namespace", "") or ""),
                "exec",
                target_name,
                "-c",
                source_container,
                "--",
                "scontrol",
                "takeover",
                "1",
            ],
            timeout_seconds=180,
        )
        deadline = time.monotonic() + 120
        while True:
            primary_names = _primary_markers()
            if primary_names:
                break
            if time.monotonic() >= deadline:
                raise SoperatorMigrationPhasePending(
                    "source bridge takeover did not produce a primary-controller runtime marker."
                )
            time.sleep(1)
    if primary_names != [target_name]:
        raise RuntimeError(
            "recovery-required: source bridge takeover activated an unexpected bridge Pod."
        )
    active_probe = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            str(journal.get("namespace", "") or ""),
            "exec",
            target_name,
            "-c",
            source_container,
            "--",
            "squeue",
            "--noheader",
        ],
        check=False,
        timeout_seconds=120,
    )
    if active_probe.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source bridge takeover marker exists but the active controller RPC probe failed."
        )
    takeover.update(
        {
            "state": "accepted",
            "pod_name": target_name,
            "pod_uid": target_uid,
            "backup_index": 1,
            "accepted_at": str(takeover.get("accepted_at", "") or "") or _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return target_name


def _source_bridge_primary_markers(
    *,
    journal: Mapping[str, Any],
    ordered_names: Sequence[str],
    source_container: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[str]:
    primary_names: list[str] = []
    for pod_name in ordered_names:
        logs = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                str(journal.get("namespace", "") or ""),
                "logs",
                pod_name,
                "-c",
                source_container,
            ],
            check=False,
            timeout_seconds=120,
        )
        if logs.returncode != 0:
            raise SoperatorMigrationPhasePending(
                f"source bridge takeover could not read runtime logs for {pod_name}."
            )
        if "Running as primary controller" in logs.stdout:
            primary_names.append(pod_name)
    return primary_names


def _revalidate_source_bridge_takeover(
    *,
    journal: Mapping[str, Any],
    pod_by_name: Mapping[str, Mapping[str, Any]],
    source_container: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> str:
    """Revalidate the accepted runtime takeover without dispatching another takeover."""

    ordered_names = sorted(pod_by_name)
    if len(ordered_names) != 2:
        raise SoperatorMigrationPhasePending(
            "source bridge takeover revalidation requires exactly two bridge Pods."
        )
    target_name = ordered_names[0]
    target_uid = str(_mapping(pod_by_name[target_name].get("metadata")).get("uid", "") or "")
    takeover = _mapping(journal.get("source_bridge_takeover"))
    if (
        takeover.get("state") != "accepted"
        or takeover.get("backup_index") != 1
        or str(takeover.get("pod_name", "") or "") != target_name
        or str(takeover.get("pod_uid", "") or "") != target_uid
        or not target_uid
    ):
        raise SoperatorMigrationPhasePending(
            "source bridge takeover journal is not accepted for the exact first bridge Pod."
        )
    roles = _sequence_of_mappings(journal.get("controller_roles"))
    role_by_name = {str(role.get("pod_name", "") or ""): role for role in roles}
    if (
        len(roles) != 2
        or len(role_by_name) != 2
        or set(role_by_name) != set(ordered_names)
        or str(role_by_name[target_name].get("role", "") or "") != "active"
        or str(role_by_name[target_name].get("pod_uid", "") or "") != target_uid
        or any(
            str(role_by_name[name].get("role", "") or "") != "standby"
            or str(role_by_name[name].get("pod_uid", "") or "")
            != str(_mapping(pod_by_name[name].get("metadata")).get("uid", "") or "")
            for name in ordered_names[1:]
        )
    ):
        raise SoperatorMigrationPhasePending(
            "source bridge takeover roles are not bound to the exact active and standby Pods."
        )
    primary_names = _source_bridge_primary_markers(
        journal=journal,
        ordered_names=ordered_names,
        source_container=source_container,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    if primary_names != [target_name]:
        raise SoperatorMigrationPhasePending(
            "source bridge takeover runtime marker no longer identifies the journaled active Pod."
        )
    active_probe = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            str(journal.get("namespace", "") or ""),
            "exec",
            target_name,
            "-c",
            source_container,
            "--",
            "squeue",
            "--noheader",
        ],
        check=False,
        timeout_seconds=120,
    )
    if active_probe.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source bridge takeover active controller RPC probe failed during revalidation."
        )
    return target_name


def _revalidate_target_bridge_roles(
    *,
    journal: Mapping[str, Any],
    pod_by_name: Mapping[str, Mapping[str, Any]],
    target_container: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    """Revalidate the target-version bridge HA roles without replaying source takeover."""

    roles = _sequence_of_mappings(journal.get("controller_roles"))
    role_by_name = {str(role.get("pod_name", "") or ""): role for role in roles}
    if (
        len(pod_by_name) != 2
        or len(roles) != 2
        or len(role_by_name) != 2
        or set(role_by_name) != set(pod_by_name)
        or sorted(str(role.get("role", "") or "") for role in roles) != ["active", "standby"]
    ):
        raise SoperatorMigrationPhasePending(
            "target bridge role journal is not bound to exactly one active and one standby Pod."
        )
    expected_roles = {name: str(role.get("role", "") or "") for name, role in role_by_name.items()}
    probe_pod = sorted(pod_by_name)[0]
    for attempt in range(6):
        ping = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                str(journal.get("namespace", "") or ""),
                "exec",
                probe_pod,
                "-c",
                target_container,
                "--",
                "scontrol",
                "ping",
            ],
            check=False,
            timeout_seconds=120,
        )
        role_matches = re.findall(
            r"Slurmctld\((primary|backup(?:\d+)?)\)\s+at\s+([^\s]+)\s+is\s+UP",
            ping.stdout,
            flags=re.IGNORECASE,
        )
        observed_roles: dict[str, str] = {}
        ambiguous_host = False
        for runtime_role, host in role_matches:
            matches = [name for name in pod_by_name if host.startswith(name)]
            if len(matches) != 1:
                ambiguous_host = True
                break
            observed_roles[matches[0]] = (
                "active" if runtime_role.lower() == "primary" else "standby"
            )
        if (
            ping.returncode == 0
            and not ambiguous_host
            and len(role_matches) == 2
            and observed_roles == expected_roles
        ):
            return
        if attempt < 5:
            time.sleep(5)
    raise SoperatorMigrationPhasePending(
        "target bridge runtime no longer proves the journaled active and standby roles."
    )


def _controller_bridge_container_name(
    statefulset: Mapping[str, Any],
    *,
    expected_image: str,
) -> str:
    pod_spec = _mapping(_mapping(_mapping(statefulset.get("spec")).get("template")).get("spec"))
    matches = [
        str(container.get("name", "") or "")
        for container in _sequence_of_mappings(pod_spec.get("containers"))
        if str(container.get("image", "") or "") == expected_image
    ]
    if len(matches) != 1 or not matches[0]:
        raise SoperatorMigrationPhasePending(
            "controller bridge workload does not have exactly one container bound to the "
            "locked source image digest."
        )
    return matches[0]


def _ensure_controller_bridge_source_jailed_config(
    *,
    journal: dict[str, Any],
    statefulset: Mapping[str, Any],
    replicas: int,
    source_image: str,
    jailed_config_observation: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> int:
    """Stage the source bridge host list before its first writable process starts."""

    configuration = _mapping(journal.get("source_configuration"))
    config_names = configuration.get("config_map_names")
    config_map_name = (
        str(config_names[0] or "").strip()
        if isinstance(config_names, list) and len(config_names) == 1
        else ""
    )
    config_key = str(configuration.get("config_key", "") or "").strip()
    target_sha256 = str(configuration.get("bridge_config_sha256", "") or "").strip()
    preimage_sha256 = str(configuration.get("original_slurm_conf_sha256", "") or "").strip()
    observed_preimage_sha256 = str(jailed_config_observation.get("sha256", "") or "").strip()
    observed_canaries = _sequence_of_mappings(jailed_config_observation.get("canaries"))
    if (
        not config_map_name
        or not config_key
        or not re.fullmatch(r"[0-9a-f]{64}", target_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", preimage_sha256)
        or jailed_config_observation.get("schema")
        != "nebius-cxcli/controller-bridge-jailed-config-observation-v1"
        or not re.fullmatch(r"[0-9a-f]{64}", observed_preimage_sha256)
        or len(observed_canaries) != 2
        or len({str(item.get("pod_uid", "") or "") for item in observed_canaries}) != 2
        or any(not str(item.get("pod_uid", "") or "") for item in observed_canaries)
    ):
        raise RuntimeError(
            "recovery-required: source bridge jailed configuration lacks exact ConfigMap "
            "and digest bindings."
        )
    namespace = str(journal.get("namespace", "") or "")
    metadata = _mapping(statefulset.get("metadata"))
    statefulset_uid = str(metadata.get("uid", "") or "").strip()
    if not namespace or not statefulset_uid or replicas not in {0, 2}:
        raise RuntimeError(
            "recovery-required: source bridge jailed configuration has an invalid workload "
            "identity or replica contract."
        )
    staging = journal.get("source_jailed_config")
    if not isinstance(staging, dict):
        staging = {}
        journal["source_jailed_config"] = staging
    repair = journal.get("source_jailed_config_repair")
    if not isinstance(repair, dict):
        repair = {}
        journal["source_jailed_config_repair"] = repair
    recorded_observation = _mapping(repair.get("jailed_config_preimage"))
    recorded_observation_sha256 = str(recorded_observation.get("sha256", "") or "")
    if recorded_observation_sha256 and observed_preimage_sha256 not in {
        recorded_observation_sha256,
        target_sha256,
    }:
        raise RuntimeError(
            "recovery-required: jailed slurm.conf changed after the source bridge repair "
            "preimage was journaled."
        )
    if not recorded_observation_sha256:
        repair["jailed_config_preimage"] = copy.deepcopy(dict(jailed_config_observation))
        if checkpoint_writer is not None:
            checkpoint_writer()
    restart_required = False
    if replicas == 2 and staging.get("state") != "accepted":
        authority = _mapping(journal.get("authority"))
        writer_scale = _mapping(authority.get("writer_scale"))
        if (
            authority.get("owner") != "bridge-source"
            or writer_scale.get("state") != "accepted"
            or str(writer_scale.get("statefulset_uid", "") or "") != statefulset_uid
            or _positive_int(writer_scale.get("to_replicas"), fallback=0) != 2
        ):
            raise RuntimeError(
                "recovery-required: unstaged source bridge replicas are not the exact "
                "accepted writer scale."
            )
        pods_payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pods",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        pods = _sequence_of_mappings(pods_payload.get("items"))
        pod_bindings: list[dict[str, str]] = []
        for pod in pods:
            pod_metadata = _mapping(pod.get("metadata"))
            owners = _sequence_of_mappings(pod_metadata.get("ownerReferences"))
            if not any(
                owner.get("controller") is True
                and str(owner.get("uid", "") or "") == statefulset_uid
                for owner in owners
            ):
                raise RuntimeError(
                    "recovery-required: unstaged source bridge Pod ownership changed."
                )
            pod_bindings.append(
                {
                    "name": str(pod_metadata.get("name", "") or ""),
                    "uid": str(pod_metadata.get("uid", "") or ""),
                }
            )
        if len(pod_bindings) != 2 or any(
            not item["name"] or not item["uid"] for item in pod_bindings
        ):
            raise RuntimeError(
                "recovery-required: unstaged source bridge does not have two exact Pods."
            )
        repair.update(
            {
                "schema": "nebius-cxcli/controller-bridge-source-jailed-config-repair-v1",
                "state": "stop-dispatching",
                "intent_at": str(repair.get("intent_at", "") or "") or _utc_now(),
                "statefulset_uid": statefulset_uid,
                "target_sha256": target_sha256,
                "preimage_sha256": preimage_sha256,
                "pods": pod_bindings,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=0,
            current_replicas=2,
            resource_version=str(metadata.get("resourceVersion", "") or ""),
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "wait",
                "--for=delete",
                "pod",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "--timeout=10m",
            ],
            timeout_seconds=660,
        )
        replicas = 0
        restart_required = True
    if replicas == 0 and repair.get("state") == "stop-dispatching":
        state_path = str(
            _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
        )
        domains = tuple(
            _mapping(item.get("scheduling_failure_domain"))
            for item in _sequence_of_mappings(journal.get("node_groups"))
        )
        if len(domains) != 2 or not state_path.startswith("/"):
            raise RuntimeError(
                "recovery-required: source jailed-config repair lacks both bridge nodes."
            )
        runtime_fence = _prove_controller_runtime_fence(
            journal=journal,
            boundary="source-bridge-jailed-config-repair",
            targets=_controller_fence_targets_from_identities(
                domains,
                state_markers=(state_path, "/mnt/controller-spool/current"),
                boundary="source bridge jailed-config repair",
            ),
            image=source_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="source bridge jailed-config repair post-stop fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        repair.update(
            {
                "state": "stopped",
                "runtime_fence": runtime_fence,
                "stopped_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    staging = journal.get("source_jailed_config")
    if not isinstance(staging, dict):
        staging = {}
        journal["source_jailed_config"] = staging
    recorded_staging_preimage = str(staging.get("expected_preimage_sha256", "") or "")
    effective_preimage_sha256 = (
        recorded_staging_preimage
        if observed_preimage_sha256 == target_sha256 and recorded_staging_preimage
        else observed_preimage_sha256
    )
    if recorded_staging_preimage and recorded_staging_preimage != effective_preimage_sha256:
        _reconcile_failed_recovery_jailed_config_stager(
            journal=journal,
            staging=staging,
            target_config_sha256=target_sha256,
            observed_preimage_sha256=effective_preimage_sha256,
            target_image=source_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    _stage_controller_bridge_jailed_config(
        journal=journal,
        config_map_name=config_map_name,
        config_key=config_key,
        target_config_sha256=target_sha256,
        expected_preimage_sha256=effective_preimage_sha256,
        target_image=source_image,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        staging_owner=journal,
        staging_key="source_jailed_config",
        pod_name_prefix="cxcli-controller-source-config-stager",
    )
    if restart_required or repair.get("state") == "stopped":
        exists, stopped = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
        )
        stopped_metadata = _mapping(stopped.get("metadata"))
        if (
            not exists
            or str(stopped_metadata.get("uid", "") or "") != statefulset_uid
            or _resource_replicas(stopped, default=-1) != 0
        ):
            raise RuntimeError(
                "recovery-required: source jailed-config repair lost its stopped StatefulSet."
            )
        _revalidate_controller_authority_lease(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        repair.update({"state": "restart-dispatching", "restart_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=2,
            current_replicas=0,
            resource_version=str(stopped_metadata.get("resourceVersion", "") or ""),
        )
        repair.update({"state": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        return 2
    if replicas == 2 and repair.get("state") == "restart-dispatching":
        if str(repair.get("statefulset_uid", "") or "") != statefulset_uid:
            raise RuntimeError(
                "recovery-required: source jailed-config restart StatefulSet UID changed."
            )
        repair.update({"state": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
    return replicas


def _activate_source_version_controller_bridge(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    plan: BridgePlan,
    source: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if str(journal.get("stage", "") or "") != BridgeStage.STATE_PROMOTED.value:
        return []
    _delete_exact_bridge_cold_reader(
        journal=journal,
        source=source,
        image=plan.source_slurm_image,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    _revalidate_controller_bridge_mirrored_material(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    source_writer_mount_proof = _prove_controller_bridge_shared_mount(
        journal=journal,
        image=plan.source_slurm_image,
        purpose="source-writer-start",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        observe_jailed_config=True,
    )
    exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=plan.namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not exists:
        raise RuntimeError("Controller bridge StatefulSet disappeared before activation.")
    metadata = _mapping(statefulset.get("metadata"))
    statefulset_uid = str(metadata.get("uid", "") or "")
    if not statefulset_uid:
        raise RuntimeError("Controller bridge StatefulSet has no immutable UID.")
    replicas = _resource_replicas(statefulset, default=-1)
    if replicas not in {0, 2}:
        raise RuntimeError(
            f"Controller bridge StatefulSet replicas drifted outside 0 -> 2: {replicas}."
        )
    source_container = _controller_bridge_container_name(
        statefulset,
        expected_image=plan.source_slurm_image,
    )
    replicas = _ensure_controller_bridge_source_jailed_config(
        journal=journal,
        statefulset=statefulset,
        replicas=replicas,
        source_image=plan.source_slurm_image,
        jailed_config_observation=_mapping(
            source_writer_mount_proof.get("jailed_config_observation")
        ),
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    authority = journal.get("authority")
    if not isinstance(authority, dict):
        raise RuntimeError("Controller bridge authority journal must be mutable.")
    epoch = _controller_bridge_epoch(journal, "bridge-source")
    scale = authority.get("writer_scale")
    if not isinstance(scale, dict):
        scale = {}
        authority["writer_scale"] = scale
    recorded_uid = str(scale.get("statefulset_uid", "") or "")
    if recorded_uid and recorded_uid != statefulset_uid:
        raise RuntimeError(
            "recovery-required: bridge writer StatefulSet UID changed after scale intent."
        )
    scale.setdefault("statefulset_uid", statefulset_uid)
    scale.setdefault("from_replicas", 0)
    scale.setdefault("to_replicas", 2)
    source_epoch = str(authority.get("epoch", "") or "")
    source_owner = str(authority.get("owner", "") or "")
    if source_owner not in {"source-singleton", "bridge-source"}:
        raise RuntimeError(
            "recovery-required: source-version bridge activation found an unexpected "
            f"authority owner: {source_owner or '<missing>'}."
        )
    pre_authority_census: list[dict[str, Any]] = []
    if replicas == 0:
        source_fence = _mapping(_mapping(journal.get("fencing")).get("source"))
        source_runtime = _sequence_of_mappings(source_fence.get("runtime_evidence"))
        state_path = str(
            _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
        )
        if len(source_runtime) != 1 or not state_path.startswith("/"):
            raise RuntimeError(
                "recovery-required: source-version bridge writer start lacks the exact "
                "source runtime-fence identity or StateSaveLocation."
            )
        bridge_runtime_nodes = tuple(
            _mapping(item.get("scheduling_failure_domain"))
            for item in _sequence_of_mappings(journal.get("node_groups"))
        )
        if len(bridge_runtime_nodes) != 2:
            raise RuntimeError(
                "recovery-required: source-version bridge writer start lacks both exact "
                "bridge node identities."
            )
        writer_runtime_targets = _controller_fence_targets_from_identities(
            (*source_runtime, *bridge_runtime_nodes),
            state_markers=(state_path, "/mnt/controller-spool/current"),
            boundary="source-version bridge pre-authority",
        )
        if len(writer_runtime_targets) != 3:
            raise RuntimeError(
                "recovery-required: source singleton and both bridge writers are not bound "
                "to three distinct historical nodes."
            )
        pre_authority_runtime_fence = _prove_controller_runtime_fence(
            journal=journal,
            boundary="source-version-bridge-pre-authority",
            targets=writer_runtime_targets,
            image=plan.source_slurm_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        pre_authority_census = _prove_cluster_wide_slurmctld_absence(
            proof_label="source-version bridge pre-authority runtime fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    _transition_controller_authority_lease(
        journal=journal,
        from_epoch=(source_epoch if source_owner == "source-singleton" else epoch),
        from_owner=source_owner,
        to_epoch=epoch,
        to_owner="bridge-source",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        runtime_node_census=pre_authority_census,
    )
    if replicas == 0:
        _revalidate_controller_runtime_fence_nodes(
            node_fence=pre_authority_runtime_fence,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="source-version bridge immediate pre-scale fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_runtime_census_nodes(
            node_census=pre_authority_census,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        scale.update(
            {
                "state": "dispatching",
                "dispatching_at": str(scale.get("dispatching_at", "") or "") or _utc_now(),
                "resource_version": str(metadata.get("resourceVersion", "") or ""),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        try:
            _kubectl_scale_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=plan.namespace,
                resource="statefulset/cxcli-slurm-controller-bridge",
                replicas=2,
                current_replicas=0,
                resource_version=str(metadata.get("resourceVersion", "") or ""),
            )
            replicas = 2
        except (Exception, KeyboardInterrupt):
            scale_exists, scale_observation = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=plan.namespace,
                resource="statefulset/cxcli-slurm-controller-bridge",
            )
            scale_metadata = _mapping(scale_observation.get("metadata"))
            if not scale_exists or str(scale_metadata.get("uid", "") or "") != statefulset_uid:
                raise RuntimeError(
                    "recovery-required: bridge writer scale outcome is indeterminate and "
                    "the exact StatefulSet identity cannot be revalidated."
                ) from None
            replicas = _resource_replicas(scale_observation, default=-1)
            if replicas == 0:
                _prove_controller_runtime_fence(
                    journal=journal,
                    boundary="source-version-bridge-scale-rejected-pre-authority-rollback",
                    targets=writer_runtime_targets,
                    image=plan.source_slurm_image,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                    fresh_attempt=True,
                )
                rollback_census = _prove_cluster_wide_slurmctld_absence(
                    proof_label=(
                        "source-version bridge rejected scale immediate pre-authority rollback"
                    ),
                    campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
                    journal=journal,
                    kube_context=kube_context,
                    command_runner=command_runner,
                )
                _transition_controller_authority_lease(
                    journal=journal,
                    from_epoch=epoch,
                    from_owner="bridge-source",
                    to_epoch=source_epoch,
                    to_owner="source-singleton",
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                    runtime_node_census=rollback_census,
                )
                scale.update(
                    {
                        "state": "rejected",
                        "rejected_at": _utc_now(),
                        "source_restart_revalidated_safe": True,
                    }
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise
            if replicas != 2:
                raise RuntimeError(
                    "recovery-required: bridge writer scale outcome is outside exact "
                    f"0 or 2 replicas: {replicas}."
                ) from None
    if replicas == 2:
        scale.update(
            {
                "state": "accepted",
                "accepted_at": str(scale.get("accepted_at", "") or "") or _utc_now(),
            }
        )
        if not str(authority.get("first_bridge_write_at", "") or ""):
            record_bridge_authority(
                journal,
                epoch=epoch,
                owner="bridge-source",
                reason=("source-version bridge writer scale accepted for promoted shared state"),
                first_bridge_write=True,
            )
        elif authority.get("owner") != "bridge-source":
            raise RuntimeError(
                "recovery-required: controller bridge authority changed before "
                "source-version HA activation completed."
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "rollout",
            "status",
            "statefulset/cxcli-slurm-controller-bridge",
            "--timeout=15m",
        ],
        timeout_seconds=960,
    )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    if len(pods) != 2:
        raise SoperatorMigrationPhasePending(
            f"controller bridge requires exactly two controller Pods; found {len(pods)}."
        )
    pod_by_name: dict[str, Mapping[str, Any]] = {}
    for pod in pods:
        metadata = _mapping(pod.get("metadata"))
        name = str(metadata.get("name", "") or "")
        pod_by_name[name] = pod
        statuses = _sequence_of_mappings(_mapping(pod.get("status")).get("containerStatuses"))
        status = next(
            (item for item in statuses if str(item.get("name", "") or "") == source_container),
            {},
        )
        live_image_id = str(status.get("imageID", "") or "")
        expected_digest = plan.source_slurm_image.rsplit("sha256:", 1)[-1]
        if expected_digest not in live_image_id:
            raise SoperatorMigrationPhasePending(
                f"controller bridge Pod {name} is not running the exact source image digest."
            )
        process = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                plan.namespace,
                "exec",
                name,
                "-c",
                source_container,
                "--",
                "/bin/sh",
                "-ec",
                'test "$(pgrep -x slurmctld | wc -l)" -eq 1',
            ],
            check=False,
            timeout_seconds=120,
        )
        if process.returncode != 0:
            raise SoperatorMigrationPhasePending(
                f"controller bridge Pod {name} does not have exactly one slurmctld process."
            )
    ping = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            plan.namespace,
            "exec",
            sorted(pod_by_name)[0],
            "-c",
            source_container,
            "--",
            "scontrol",
            "ping",
        ],
        check=False,
        timeout_seconds=120,
    )
    if ping.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source-version controller bridge did not answer scontrol ping: "
            + _command_detail(ping)
        )
    up_hosts = re.findall(
        r"Slurmctld\((?:primary|backup\d*)\)\s+at\s+([^\s]+)\s+is\s+UP",
        ping.stdout,
        flags=re.IGNORECASE,
    )
    live_bridge_hosts = {
        name for name in pod_by_name if any(host.startswith(name) for host in up_hosts)
    }
    if live_bridge_hosts != set(pod_by_name):
        raise SoperatorMigrationPhasePending(
            "source-version bridge did not prove both bridge slurmctld daemons UP."
        )
    active_name = _prove_source_bridge_takeover(
        journal=journal,
        pod_by_name=pod_by_name,
        source_container=source_container,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    role_matches = [
        ("primary" if name == active_name else "backup", name) for name in sorted(pod_by_name)
    ]
    controller_roles: list[dict[str, Any]] = []
    for role, host in role_matches:
        pod_name = next((name for name in pod_by_name if host.startswith(name)), "")
        pod = pod_by_name.get(pod_name, {})
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        node = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                "node",
                node_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        node_group_id = str(
            _mapping(node_metadata.get("labels")).get("nebius.com/node-group-id", "") or ""
        )
        node_labels = _mapping(node_metadata.get("labels"))
        expected_node_group_ids = {
            str(item.get("id", "") or "")
            for item in _sequence_of_mappings(journal.get("node_groups"))
        }
        if node_group_id not in expected_node_group_ids:
            raise SoperatorMigrationPhasePending(
                f"controller bridge Pod {pod_name} is outside the two journaled node groups."
            )
        expected_domain = next(
            (
                _mapping(item.get("scheduling_failure_domain"))
                for item in _sequence_of_mappings(journal.get("node_groups"))
                if str(item.get("id", "") or "") == node_group_id
            ),
            {},
        )
        topology_key = str(_mapping(expected_domain).get("topology_key", "") or "")
        topology_value = str(_mapping(expected_domain).get("topology_value", "") or "")
        if (
            topology_key != "nebius.com/node-group-id"
            or not topology_value
            or str(node_labels.get(topology_key, "") or "") != topology_value
        ):
            raise SoperatorMigrationPhasePending(
                f"controller bridge Pod {pod_name} lost its journaled scheduling domain."
            )
        controller_roles.append(
            {
                "pod_name": pod_name,
                "pod_uid": str(_mapping(pod.get("metadata")).get("uid", "") or ""),
                "node_name": node_name,
                "node_uid": str(node_metadata.get("uid", "") or ""),
                "node_group_id": node_group_id,
                "failure_domain": topology_value,
                "host": host,
                "role": "active" if role.lower() == "primary" else "standby",
                "image": plan.source_slurm_image,
                "configuration_fingerprint": _mapping(journal.get("source_binding")).get(
                    "configuration_fingerprint"
                ),
                "observed_at": _utc_now(),
            }
        )
    if len({item["failure_domain"] for item in controller_roles}) != 2:
        raise SoperatorMigrationPhasePending(
            "controller bridge active and standby are not on distinct immutable "
            "node-group scheduling domains."
        )
    journal["controller_roles"] = controller_roles
    if checkpoint_writer is not None:
        checkpoint_writer()
    _prove_journaled_controller_bridge_exclusivity(
        journal=journal,
        proof_label="source-version controller bridge activation",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    preservation_lines = _verify_controller_bridge_preservation_jobs(
        checkpoint=checkpoint,
        journal=journal,
        proof_stage="source-version-bridge-active",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    advance_bridge_stage(journal, BridgeStage.SOURCE_HA_ACTIVE)
    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "dispatch-enabled")
    journal["action_broker_mode"] = "dispatch-enabled"
    if checkpoint_writer is not None:
        checkpoint_writer()
    _drain_external_upgrade_slurm_action_journal(
        journal=action_journal,
        command_runner=command_runner,
        kube_context=kube_context,
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
        checkpoint_writer=checkpoint_writer,
    )
    return [
        "Controller bridge active: exact source image, shared StateSaveLocation, one active "
        "and one standby on distinct nodes, and no source singleton process."
    ] + preservation_lines


def _execute_controller_ha_bridge_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    artifact_dir: Path,
    checkpoint_writer: Callable[[], None] | None,
    placement_domains: Sequence[BridgePlacementDomain] | None = None,
) -> tuple[bool, list[str]]:
    plan, source_binding, source, target_image_lock = _controller_bridge_plan(
        checkpoint=checkpoint,
        payload=payload,
        source_report=source_report,
        target_ref=target_ref,
        nebius_api=nebius_api,
        placement_domains=placement_domains,
    )
    _migrate_pre_authority_bridge_segment_epoch(
        checkpoint=checkpoint,
        plan=plan,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    artifact_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
    artifact_dir.chmod(0o700)
    recovery_lines = _recover_controller_bridge_pre_authority_source_restart(
        checkpoint=checkpoint,
        plan=plan,
        source_binding=source_binding,
        source=source,
        artifact_dir=artifact_dir,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    journal = _controller_bridge_journal(
        checkpoint=checkpoint,
        plan=plan,
        source_binding=source_binding,
        target_image_lock=target_image_lock,
        checkpoint_writer=checkpoint_writer,
    )
    phase = _phase_state(checkpoint, _CONTROLLER_HA_BRIDGE_PHASE_ID)
    initial_stage = str(journal.get("stage", "") or "")
    initial_pause = tuple(_sequence_of_mappings(journal.get("partition_pause")))

    advanced_stages = {
        BridgeStage.TARGET_HA_ACTIVE.value,
        BridgeStage.BRIDGE_FENCED.value,
        BridgeStage.TARGET_SINGLETON_ACTIVE.value,
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
        BridgeStage.CLEANED.value,
    }
    if initial_stage in advanced_stages:
        if not _controller_bridge_satisfied(
            checkpoint=checkpoint,
            kube_context=kube_context,
            nebius_api=nebius_api,
            command_runner=command_runner,
        ):
            raise SoperatorMigrationPhasePending(
                "controller-ha-bridge advanced journal stage could not be securely "
                f"revalidated: stage={initial_stage}. Resume the same v6 checkpoint."
            )
        phase.update(
            {
                "bridge_schema": journal.get("schema"),
                "bridge_stage": initial_stage,
                "namespace": plan.namespace,
                "source_image": plan.source_slurm_image,
                "target_image": plan.target_slurm_image,
                "target_platform": dict(target_image_lock),
                "completed_at": phase.get("completed_at") or _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return False, [
            "Controller bridge resume: securely revalidated the already-advanced "
            f"journal stage {initial_stage} without replaying source-version takeover."
        ]

    lines = list(recovery_lines)
    lines.extend(
        _preflight_controller_inspector_namespace(
            journal=journal,
            plan=plan,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    ensure_slurm_action_journal(checkpoint)
    lines.extend(
        _protect_upgrade_login_sessions(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    lines.extend(
        _reconcile_checkpointed_in_place_bridge_authority(
            checkpoint=checkpoint,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    lines.extend(
        _bridge_pause_all_partitions(
            journal=journal,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            checkpoint=checkpoint,
        )
    )
    lines.extend(
        _capture_controller_bridge_preservation_jobs(
            checkpoint=checkpoint,
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    node_group_mutation, node_group_lines = _create_controller_bridge_node_groups(
        checkpoint=checkpoint,
        journal=journal,
        plan=plan,
        nebius_api=nebius_api,
        checkpoint_writer=checkpoint_writer,
    )
    lines.extend(node_group_lines)
    if str(journal.get("stage", "") or "") == BridgeStage.PLANNED.value:
        lines.extend(
            _create_controller_bridge_kubernetes_substrate(
                journal=journal,
                plan=plan,
                source=source,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
        lines.extend(
            _establish_controller_bridge_pre_source_mutation_readiness(
                journal=journal,
                plan=plan,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
    if str(journal.get("stage", "") or "") in {
        BridgeStage.SUBSTRATE_READY.value,
        BridgeStage.SOURCE_CONFIGURED.value,
        BridgeStage.SOURCE_PRECOPIED.value,
    }:
        lines.extend(
            _suspend_source_reconciliation_for_bridge(
                journal=journal,
                source_report=source_report,
                target_version=str(checkpoint.get("target_version", "") or ""),
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
    lines.extend(
        _configure_source_controller_for_bridge(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    lines.extend(
        _precopy_controller_state_to_bridge(
            journal=journal,
            plan=plan,
            source=source,
            artifact_dir=artifact_dir,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    lines.extend(
        _fence_source_controller_for_bridge(
            checkpoint=checkpoint,
            journal=journal,
            plan=plan,
            source_report=source_report,
            source=source,
            target_ref=target_ref,
            target_version=str(checkpoint.get("target_version", "") or ""),
            kube_context=kube_context,
            nebius_api=nebius_api,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    lines.extend(
        _cold_copy_and_promote_controller_state(
            journal=journal,
            plan=plan,
            source=source,
            artifact_dir=artifact_dir,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    lines.extend(
        _activate_source_version_controller_bridge(
            checkpoint=checkpoint,
            journal=journal,
            plan=plan,
            source=source,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    validate_bridge_journal(journal)
    if journal.get("stage") != BridgeStage.SOURCE_HA_ACTIVE.value:
        raise SoperatorMigrationPhasePending(
            "controller-ha-bridge has not yet proved one active and one standby "
            "source-version slurmctld. Resume the same v6 checkpoint."
        )
    phase.update(
        {
            "bridge_schema": journal.get("schema"),
            "bridge_stage": journal.get("stage"),
            "namespace": plan.namespace,
            "source_image": plan.source_slurm_image,
            "target_image": plan.target_slurm_image,
            "target_platform": dict(target_image_lock),
            "completed_at": phase.get("completed_at") or _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    final_pause = tuple(_sequence_of_mappings(journal.get("partition_pause")))
    mutation_performed = (
        node_group_mutation
        or initial_stage != str(journal.get("stage", "") or "")
        or initial_pause != final_pause
    )
    return mutation_performed, lines


def _target_values_gated_by_controller_bridge(
    *,
    checkpoint: dict[str, Any],
    values: Mapping[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            "target Soperator staging requires the v6 temporary controller bridge journal."
        )
    try:
        validate_bridge_journal(journal)
        stage = BridgeStage(str(journal.get("stage", "") or ""))
    except ValueError as exc:
        raise RuntimeError(f"Controller bridge journal is invalid: {exc}") from exc
    if stage in {
        BridgeStage.TARGET_SINGLETON_ACTIVE,
        BridgeStage.HANDOFF_VALIDATED,
        BridgeStage.PARTITIONS_RESTORED,
        BridgeStage.CLEANED,
    }:
        return copy.deepcopy(dict(values))
    if stage not in {
        BridgeStage.SOURCE_HA_ACTIVE,
        BridgeStage.TARGET_HA_ACTIVE,
        BridgeStage.BRIDGE_FENCED,
    }:
        raise SoperatorMigrationPhasePending(
            "target Soperator staging requires an active source- or target-version "
            f"controller bridge; current stage={stage.value}."
        )
    gated = target_controller_gate_values(values)
    gate_fingerprint = _fingerprint(gated)
    gate_contract = {
        "schema": "nebius-cxcli/target-controller-command-gate-v2",
        "slurmctld": {
            key: copy.deepcopy(value)
            for key, value in _mapping(
                _mapping(_mapping(gated.get("slurmNodes")).get("controller")).get("slurmctld")
            ).items()
            if key in {"command", "args", "livenessProbe", "readinessProbe"}
        },
    }
    expected_gate_contract = {
        "schema": gate_contract["schema"],
        "slurmctld": copy.deepcopy(
            _mapping(
                _mapping(
                    _mapping(target_controller_gate_values({}).get("slurmNodes")).get("controller")
                ).get("slurmctld")
            )
        ),
    }
    if gate_contract != expected_gate_contract:
        raise RuntimeError(
            "recovery-required: target controller command-gate contract is not canonical."
        )
    gate_contract_fingerprint = _fingerprint(gate_contract)
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    recorded = str(takeover.get("command_gate_values_fingerprint", "") or "")
    recorded_contract = str(takeover.get("command_gate_contract_fingerprint", "") or "")
    if recorded_contract and recorded_contract != gate_contract_fingerprint:
        raise RuntimeError(
            "recovery-required: target controller command-gate contract changed after staging."
        )
    migration_mode = ""
    if not recorded_contract and recorded:
        if recorded == gate_fingerprint:
            migration_mode = "exact-values-match"
        else:
            rolling = _mapping(
                _mapping(checkpoint.get("phase_state")).get("rolling-compute-migration")
            )
            intent = _mapping(rolling.get("target_handoff_values_apply_intent"))
            proof = _mapping(rolling.get("target_handoff_values_proof"))
            if not (
                intent.get("status") == "verified"
                and proof.get("status") == "verified"
                and str(intent.get("values_fingerprint") or "").strip() == recorded
                and str(proof.get("values_fingerprint") or "").strip() == recorded
                and str(proof.get("apply_intent_schema") or "").strip()
                == str(intent.get("schema") or "").strip()
            ):
                raise RuntimeError(
                    "recovery-required: target controller command-gate values changed "
                    "after staging without an exact verified Helm apply proof."
                )
            migration_mode = "verified-staged-values"
    takeover.update(
        {
            "command_gate_applied": True,
            "command_gate_values_fingerprint": recorded or gate_fingerprint,
            "command_gate_contract_schema": gate_contract["schema"],
            "command_gate_contract_fingerprint": gate_contract_fingerprint,
            "command_gate_applied_at": takeover.get("command_gate_applied_at") or _utc_now(),
        }
    )
    if migration_mode:
        takeover["command_gate_contract_migration"] = {
            "schema": "nebius-cxcli/target-controller-command-gate-migration-v1",
            "status": "verified",
            "mode": migration_mode,
            "legacy_values_fingerprint": recorded,
            "verified_at": _utc_now(),
        }
    if checkpoint_writer is not None:
        checkpoint_writer()
    return gated


def _in_place_target_controller_gate_was_established(
    checkpoint: Mapping[str, Any],
) -> bool:
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    gate = rolling.get("in_place_target_controller_command_gate")
    return isinstance(gate, Mapping) and bool(str(gate.get("status", "") or "").strip())


def _reconcile_checkpointed_in_place_bridge_authority(
    *,
    checkpoint: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if not _in_place_target_controller_gate_was_established(checkpoint):
        return []
    phase = _phase_state(checkpoint, "rolling-compute-migration")
    lines = _ensure_in_place_bridge_client_configuration(
        checkpoint=checkpoint,
        phase=phase,
        target_ref=target_ref,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    lines.extend(
        _ensure_in_place_target_controller_command_gate(
            checkpoint=checkpoint,
            phase=phase,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    return lines


def _controller_bridge_target_config(
    *,
    journal: Mapping[str, Any],
    values: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[str, str, str]:
    cluster_name = str(values.get("clusterName") or target_ref).strip()
    config_map_name = f"{cluster_name}{_LEGACY_ROOTFS_SLURM_CONFIG_MAP_SUFFIX}"
    config_map = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "configmap",
            config_map_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    data = _mapping(config_map.get("data"))
    slurm_conf = str(data.get("slurm.conf", "") or "")
    if not slurm_conf:
        raise SoperatorMigrationPhasePending(
            f"target Slurm ConfigMap {_SOPERATOR_NAMESPACE}/{config_map_name} is not ready."
        )
    configured_cluster = re.search(r"(?im)^\s*ClusterName\s*=\s*(\S+)\s*$", slurm_conf)
    if not configured_cluster or configured_cluster.group(1) != cluster_name:
        raise SoperatorMigrationPhasePending(
            "target Slurm configuration ClusterName does not match the exact target Helm values."
        )
    target_state_match = re.search(r"(?im)^\s*StateSaveLocation\s*=\s*(\S+)\s*$", slurm_conf)
    target_state_path = target_state_match.group(1) if target_state_match else ""
    if not target_state_path.startswith("/"):
        raise SoperatorMigrationPhasePending(
            "target Slurm configuration requires one absolute StateSaveLocation."
        )
    # The bridge PVC is mounted with ``subPath=current`` at the exact source
    # controller StateSaveLocation.  The shared SFS host path
    # (/mnt/controller-spool/current) is intentionally not an in-container
    # mount in the mirrored source Pod contract.  Keep the target-version
    # bridge on that journaled mount path so the Slurm version transition
    # cannot start against an unmounted directory.
    bridge_state_path = str(
        _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
    ).strip()
    if not bridge_state_path.startswith("/"):
        raise SoperatorMigrationPhasePending(
            "target-version bridge configuration requires the journaled absolute source "
            "StateSaveLocation mounted from the promoted shared epoch."
        )
    slurm_conf = _controller_bridge_preserve_source_partitions(
        target_slurm_conf=slurm_conf,
        source_slurm_conf=str(
            _mapping(journal.get("source_configuration")).get("original_slurm_conf", "") or ""
        ),
    )
    return (
        config_map_name,
        bridge_only_controller_config(
            slurm_conf,
            state_save_location=bridge_state_path,
        ),
        target_state_path,
    )


def _controller_bridge_partition_definitions(slurm_conf: str, *, label: str) -> dict[str, str]:
    definitions: dict[str, str] = {}
    for raw_line in slurm_conf.splitlines():
        match = re.match(r"^\s*PartitionName\s*=\s*([^\s#]+)", raw_line, flags=re.IGNORECASE)
        if match is None:
            continue
        name = match.group(1).strip()
        key = name.casefold()
        if not name or key in definitions:
            raise RuntimeError(
                f"controller bridge {label} Slurm configuration contains a duplicate or "
                "empty PartitionName definition."
            )
        definitions[key] = raw_line.strip()
    return definitions


def _controller_bridge_paused_legacy_partition(line: str) -> str:
    rendered = re.sub(
        r"(?i)(?<!\S)Default\s*=\s*\S+",
        "Default=NO",
        line,
        count=1,
    )
    if not re.search(r"(?i)(?<!\S)Default\s*=", rendered):
        rendered = rendered.rstrip() + " Default=NO"
    rendered = re.sub(
        r"(?i)(?<!\S)State\s*=\s*\S+",
        "State=DOWN",
        rendered,
        count=1,
    )
    if not re.search(r"(?i)(?<!\S)State\s*=", rendered):
        rendered = rendered.rstrip() + " State=DOWN"
    return rendered


def _controller_bridge_preserve_source_partitions(
    *,
    target_slurm_conf: str,
    source_slurm_conf: str,
) -> str:
    """Keep legacy job partitions readable while target slurmctld converts state.

    Slurm drops a restored job when its saved partition is absent from the new
    configuration.  The source partitions therefore remain defined throughout
    the controller-version handoff, but are non-default and DOWN until the
    separately journaled partition-restore boundary.
    """

    target = _controller_bridge_partition_definitions(target_slurm_conf, label="target")
    source = _controller_bridge_partition_definitions(source_slurm_conf, label="source")
    missing = [
        _controller_bridge_paused_legacy_partition(line)
        for name, line in source.items()
        if name not in target
    ]
    if not missing:
        return target_slurm_conf.rstrip() + "\n"
    return target_slurm_conf.rstrip() + "\n" + "\n".join(missing) + "\n"


def _controller_bridge_backup_recovery_binding(
    transition: dict[str, Any],
    *,
    backup_epoch: str,
) -> tuple[dict[str, Any], bool]:
    recovery = transition.get("backup_recovery")
    if not isinstance(recovery, dict):
        recovery = {}
        transition["backup_recovery"] = recovery
    in_progress = (
        recovery.get("state")
        in {
            "intent-recorded",
            "dispatching",
        }
        and transition.get("backup_recovery_consumed") is not True
    )
    if in_progress:
        return recovery, True
    if recovery:
        recovery_history = transition.setdefault("backup_recovery_history", [])
        if not isinstance(recovery_history, list):
            raise RuntimeError("Controller state recovery history binding is malformed.")
        recovery_history.append(copy.deepcopy(recovery))
    restore_token = uuid4().hex
    recovery = {
        "restore_epoch": f"{backup_epoch}-recovered-{restore_token[:12]}",
        "token": restore_token,
    }
    transition["backup_recovery"] = recovery
    transition["backup_recovery_consumed"] = False
    return recovery, False


def _restore_source_bridge_after_failed_target_transition(
    *,
    checkpoint: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        return []
    transition = journal.get("version_transition")
    if not isinstance(transition, dict):
        return []
    if (
        str(journal.get("stage", "") or "") != BridgeStage.SOURCE_HA_ACTIVE.value
        or str(transition.get("target_write_at", "") or "").strip()
        or transition.get("downgrade_prohibited") is True
        or str(transition.get("target_material_staged_at", "") or "").strip()
        or _mapping(journal.get("authority")).get("owner") != "bridge-source"
    ):
        return []
    source_image = str(transition.get("source_image", "") or "")
    namespace = str(journal.get("namespace", "") or "")
    writer_uid = str(
        _mapping(_mapping(journal.get("authority")).get("writer_scale")).get("statefulset_uid", "")
        or ""
    )
    if not source_image or not namespace or not writer_uid:
        raise RuntimeError(
            "recovery-required: pre-target source bridge recovery lacks exact bindings."
        )
    exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    metadata = _mapping(statefulset.get("metadata"))
    spec = _mapping(statefulset.get("spec"))
    template = _mapping(_mapping(spec.get("template")).get("spec"))
    source_containers = [
        item
        for item in _sequence_of_mappings(template.get("containers"))
        if str(item.get("image", "") or "") == source_image
        and "slurmctld" in str(item.get("name", "") or "").lower()
    ]
    replicas = _resource_replicas(statefulset, default=-1)
    if (
        not exists
        or str(metadata.get("uid", "") or "") != writer_uid
        or len(source_containers) != 1
        or replicas not in {0, 2}
    ):
        raise RuntimeError(
            "recovery-required: pre-target source bridge workload identity, image, or "
            "replicas drifted."
        )
    recovery = transition.setdefault("source_recovery_after_failed_target_transition", {})
    if not isinstance(recovery, dict):
        raise RuntimeError("Pre-target source bridge recovery journal is malformed.")
    if replicas == 0:
        runtime_fence = _sequence_of_mappings(transition.get("source_runtime_fence"))
        if (
            len(runtime_fence) != 2
            or any(
                item.get("fenced") is not True
                or int(item.get("slurmctld_count", -1) or 0) != 0
                or int(item.get("writable_state_mount_count", -1) or 0) != 0
                for item in runtime_fence
            )
            or not str(transition.get("post_stop_api_absence_verified_at", "") or "")
        ):
            raise RuntimeError(
                "recovery-required: pre-target source bridge recovery lacks the exact "
                "two-node runtime and API absence fence."
            )
        _revalidate_controller_bridge_mirrored_material(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        recovery.update(
            {
                "state": "dispatching",
                "dispatching_at": _utc_now(),
                "statefulset_uid": writer_uid,
                "source_image": source_image,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=2,
            current_replicas=0,
            resource_version=str(metadata.get("resourceVersion", "") or ""),
        )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "rollout",
            "status",
            "statefulset/cxcli-slurm-controller-bridge",
            "--timeout=10m",
        ],
        timeout_seconds=660,
    )
    takeover = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            "cxcli-slurm-controller-bridge-0",
            "-c",
            str(source_containers[0].get("name", "") or ""),
            "--",
            "scontrol",
            "takeover",
            "1",
        ],
        check=False,
        timeout_seconds=120,
    )
    primary_log = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "logs",
            "cxcli-slurm-controller-bridge-0",
            "-c",
            str(source_containers[0].get("name", "") or ""),
        ],
        check=False,
        timeout_seconds=120,
    )
    if takeover.returncode != 0 or "Running as primary controller" not in primary_log.stdout:
        raise RuntimeError(
            "recovery-required: source bridge restarted but exact primary takeover was not proven."
        )
    if not _source_version_controller_bridge_recovered(
        checkpoint=checkpoint,
        command_runner=command_runner,
        kube_context=kube_context,
    ):
        raise RuntimeError(
            "recovery-required: source bridge restart did not prove exact source image 2/2."
        )
    recovery.update({"state": "accepted", "accepted_at": _utc_now()})
    transition.update(
        {
            "cold_stop_dispatching_at": "",
            "source_recovered_at": _utc_now(),
        }
    )
    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "dispatch-enabled")
    journal["action_broker_mode"] = "dispatch-enabled"
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Pre-target controller failure recovered automatically: exact source image 2/2 "
        "and bridge-0 primary were proven before returning the phase error."
    ]


def _controller_bridge_live_jailed_config_digests(
    *,
    namespace: str,
    container_name: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, str]:
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    if len(pods) != 2:
        raise SoperatorMigrationPhasePending(
            "target-version bridge jailed-config proof requires exactly two live Pods."
        )
    result: dict[str, str] = {}
    for pod in pods:
        pod_name = str(_mapping(pod.get("metadata")).get("name", "") or "")
        pod_uid = str(_mapping(pod.get("metadata")).get("uid", "") or "")
        if not pod_name or not pod_uid:
            raise RuntimeError(
                "recovery-required: target-version bridge Pod lacks an immutable identity."
            )
        digest = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "exec",
                pod_name,
                "-c",
                container_name,
                "--",
                "sha256sum",
                _SOPERATOR_LEGACY_SLURM_CONF,
            ],
            check=False,
            timeout_seconds=120,
        )
        match = re.match(r"^([0-9a-f]{64})\s+", str(digest.stdout or ""))
        if digest.returncode != 0 or not match:
            raise SoperatorMigrationPhasePending(
                f"target-version bridge Pod {pod_name} did not expose its jailed slurm.conf."
            )
        result[pod_uid] = match.group(1)
    return result


def _controller_bridge_canary_jailed_config_observation(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, Any]:
    namespace = str(journal.get("namespace", "") or "")
    campaign_fingerprint = str(journal.get("campaign_fingerprint", "") or "")
    if not namespace or not campaign_fingerprint:
        raise RuntimeError(
            "recovery-required: jailed-config observation lacks its campaign binding."
        )
    observations: list[dict[str, str]] = []
    for slot in (0, 1):
        pod_name = f"cxcli-controller-bridge-canary-{slot}"
        pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pod",
                pod_name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        metadata = _mapping(pod.get("metadata"))
        annotations = _mapping(metadata.get("annotations"))
        status = _mapping(pod.get("status"))
        conditions = _sequence_of_mappings(status.get("conditions"))
        pod_uid = str(metadata.get("uid", "") or "")
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        if (
            not pod_uid
            or not node_name
            or annotations.get("nebius.ai/cxcli-campaign-fingerprint") != campaign_fingerprint
            or not any(
                item.get("type") == "Ready" and item.get("status") == "True" for item in conditions
            )
        ):
            raise RuntimeError(
                "recovery-required: shared-mount canary lost its exact Ready campaign identity."
            )
        digest = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "exec",
                pod_name,
                "-c",
                "canary",
                "--",
                "sha256sum",
                "/jail/etc/slurm/slurm.conf",
            ],
            check=False,
            timeout_seconds=120,
        )
        match = re.match(r"^([0-9a-f]{64})\s+", str(digest.stdout or ""))
        if digest.returncode != 0 or not match:
            raise RuntimeError(
                "recovery-required: shared-mount canary could not digest jailed slurm.conf."
            )
        observations.append(
            {
                "slot": str(slot),
                "pod_name": pod_name,
                "pod_uid": pod_uid,
                "node_name": node_name,
                "sha256": match.group(1),
            }
        )
    digests = {item["sha256"] for item in observations}
    if len(digests) != 1 or len({item["pod_uid"] for item in observations}) != 2:
        raise RuntimeError(
            "recovery-required: both immutable bridge canaries did not observe one jailed "
            "slurm.conf digest."
        )
    return {
        "schema": "nebius-cxcli/controller-bridge-jailed-config-observation-v1",
        "sha256": next(iter(digests)),
        "observed_at": _utc_now(),
        "canaries": observations,
    }


def _reconcile_failed_recovery_jailed_config_stager(
    *,
    journal: dict[str, Any],
    staging: dict[str, Any],
    target_config_sha256: str,
    observed_preimage_sha256: str,
    target_image: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    recorded_preimage = str(staging.get("expected_preimage_sha256", "") or "")
    if recorded_preimage == observed_preimage_sha256:
        return
    namespace = str(journal.get("namespace", "") or "")
    campaign_fingerprint = str(journal.get("campaign_fingerprint", "") or "")
    pod_name = str(staging.get("pod_name", "") or "")
    exists, pod = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource=f"pod/{pod_name}",
    )
    metadata = _mapping(pod.get("metadata"))
    annotations = _mapping(metadata.get("annotations"))
    labels = _mapping(metadata.get("labels"))
    spec = _mapping(pod.get("spec"))
    status = _mapping(pod.get("status"))
    containers = _sequence_of_mappings(spec.get("containers"))
    container_statuses = _sequence_of_mappings(status.get("containerStatuses"))
    terminated = (
        _mapping(_mapping(container_statuses[0].get("state")).get("terminated"))
        if len(container_statuses) == 1
        else {}
    )
    command = (
        "\n".join(str(item) for item in containers[0].get("command", ()))
        if len(containers) == 1
        else ""
    )
    if (
        not exists
        or str(staging.get("state", "") or "") != "dispatching"
        or str(staging.get("target_sha256", "") or "") != target_config_sha256
        or str(metadata.get("name", "") or "") != pod_name
        or annotations.get("nebius.ai/cxcli-campaign-fingerprint") != campaign_fingerprint
        or annotations.get("nebius.ai/cxcli-target-config-sha256") != target_config_sha256
        or labels.get("app.kubernetes.io/managed-by") != "nebius-cxcli"
        or labels.get("nebius.ai/cxcli-controller-bridge") != "config-stager"
        or status.get("phase") != "Failed"
        or int(terminated.get("exitCode", 0) or 0) == 0
        or len(containers) != 1
        or containers[0].get("image") != target_image
        or f"expected_target={target_config_sha256}" not in command
        or f"expected_preimage={recorded_preimage}" not in command
    ):
        raise RuntimeError(
            "recovery-required: jailed-config CAS preimage changed, but the exact prior "
            "stager was not proven to have failed before mutation."
        )
    staging.update(
        {
            "state": "retrying",
            "superseded_expected_preimage_sha256": recorded_preimage,
            "expected_preimage_sha256": observed_preimage_sha256,
            "preimage_reconciled_at": _utc_now(),
            "failed_pod_uid": str(metadata.get("uid", "") or ""),
            "failed_exit_code": int(terminated.get("exitCode", 0) or 0),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()


def _wait_for_controller_bridge_stager_ready_or_terminal(
    *,
    namespace: str,
    pod_name: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    timeout_seconds: int = 300,
) -> None:
    """Wait for stager readiness without hiding a terminal failure until timeout."""

    deadline = time.monotonic() + timeout_seconds
    while True:
        exists, pod = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource=f"pod/{pod_name}",
        )
        if exists:
            status = _mapping(pod.get("status"))
            conditions = _sequence_of_mappings(status.get("conditions"))
            if any(
                item.get("type") == "Ready" and item.get("status") == "True" for item in conditions
            ):
                return
            phase = str(status.get("phase", "") or "")
            if phase in {"Failed", "Succeeded"}:
                exits = [
                    str(_mapping(_mapping(item.get("state")).get("terminated")).get("exitCode"))
                    for item in _sequence_of_mappings(status.get("containerStatuses"))
                    if _mapping(_mapping(item.get("state")).get("terminated"))
                ]
                exit_detail = ",".join(exits) if exits else "unknown"
                raise SoperatorMigrationPhasePending(
                    "controller bridge jailed-config stager became terminal before "
                    f"readiness: pod={pod_name}, phase={phase}, exit={exit_detail}."
                )
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                f"controller bridge jailed-config stager did not become Ready: {pod_name}."
            )
        time.sleep(1)


def _stage_controller_bridge_jailed_config(
    *,
    journal: dict[str, Any],
    config_map_name: str,
    config_key: str,
    target_config_sha256: str,
    expected_preimage_sha256: str,
    target_image: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    staging_owner: dict[str, Any] | None = None,
    staging_key: str = "target_jailed_config",
    pod_name_prefix: str = "cxcli-controller-config-stager",
) -> None:
    if not re.fullmatch(r"[0-9a-f]{64}", target_config_sha256) or not re.fullmatch(
        r"[0-9a-f]{64}", expected_preimage_sha256
    ):
        raise RuntimeError("Controller bridge jailed-config digests are malformed.")
    namespace = str(journal.get("namespace", "") or "")
    controller_roles = _sequence_of_mappings(journal.get("controller_roles"))
    node_name = str(controller_roles[0].get("node_name", "") or "") if controller_roles else ""
    if not node_name:
        node_groups = _sequence_of_mappings(journal.get("node_groups"))
        if node_groups:
            node_name = str(
                _mapping(node_groups[0].get("scheduling_failure_domain")).get("node_name", "") or ""
            )
    campaign_fingerprint = str(journal.get("campaign_fingerprint", "") or "")
    cluster_id = str(journal.get("cluster_id", "") or "")
    if not all(
        (namespace, node_name, campaign_fingerprint, cluster_id, config_map_name, config_key)
    ):
        raise RuntimeError(
            "recovery-required: target jailed-config staging lacks its exact campaign binding."
        )
    if staging_owner is None:
        staging_owner = journal.get("version_transition")
        if not isinstance(staging_owner, dict):
            raise RuntimeError("Controller bridge version transition journal must be mutable.")
    if not staging_key or not pod_name_prefix:
        raise RuntimeError("Controller bridge jailed-config staging identity is incomplete.")
    staging = staging_owner.get(staging_key)
    if not isinstance(staging, dict):
        staging = {}
        staging_owner[staging_key] = staging
    recorded_target = str(staging.get("target_sha256", "") or "")
    recorded_preimage = str(staging.get("expected_preimage_sha256", "") or "")
    if (recorded_target and recorded_target != target_config_sha256) or (
        recorded_preimage and recorded_preimage != expected_preimage_sha256
    ):
        raise RuntimeError(
            "recovery-required: target jailed-config staging digests changed after intent."
        )
    pod_name = f"{pod_name_prefix}-{target_config_sha256[:12]}"
    staging.update(
        {
            "schema": "nebius-cxcli/controller-bridge-jailed-config-v1",
            "state": "dispatching",
            "intent_at": str(staging.get("intent_at", "") or "") or _utc_now(),
            "target_sha256": target_config_sha256,
            "expected_preimage_sha256": expected_preimage_sha256,
            "config_map_name": config_map_name,
            "config_key": config_key,
            "pod_name": pod_name,
            "node_name": node_name,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "delete",
            f"pod/{pod_name}",
            "--ignore-not-found",
            "--wait=true",
        ],
        timeout_seconds=300,
    )
    target_path = "/jail/etc/slurm/slurm.conf"
    source_path = "/config/slurm.conf"
    script = (
        "set -eu\n"
        f"target={shlex.quote(target_path)}\n"
        f"source={shlex.quote(source_path)}\n"
        f"expected_target={shlex.quote(target_config_sha256)}\n"
        f"expected_preimage={shlex.quote(expected_preimage_sha256)}\n"
        'source_sha=$(sha256sum "$source" | cut -d " " -f 1)\n'
        'test "$source_sha" = "$expected_target"\n'
        'current_sha=$(sha256sum "$target" | cut -d " " -f 1)\n'
        'if test "$current_sha" != "$expected_target"; then\n'
        '  test "$current_sha" = "$expected_preimage"\n'
        '  temporary="${target}.cxcli-${expected_target}.partial"\n'
        '  rm -f "$temporary"\n'
        '  cp -p "$source" "$temporary"\n'
        '  sync -f "$temporary"\n'
        '  mv -f "$temporary" "$target"\n'
        '  sync -f "$(dirname "$target")"\n'
        "fi\n"
        'actual_sha=$(sha256sum "$target" | cut -d " " -f 1)\n'
        'test "$actual_sha" = "$expected_target"\n'
        "printf 'schema=nebius-cxcli-controller-bridge-jailed-config/v1\\n"
        'target_sha256=%s\\n\' "$actual_sha"\n'
        "touch /dev/shm/cxcli-config-staged\n"
        "trap 'exit 0' TERM INT\n"
        "sleep 600\n"
    )
    manifest = {
        "apiVersion": "v1",
        "kind": "Pod",
        "metadata": {
            "name": pod_name,
            "namespace": namespace,
            "labels": {
                "app.kubernetes.io/managed-by": "nebius-cxcli",
                "nebius.ai/cxcli-controller-bridge": "config-stager",
            },
            "annotations": {
                "nebius.ai/cxcli-campaign-fingerprint": campaign_fingerprint,
                "nebius.ai/cxcli-target-config-sha256": target_config_sha256,
            },
        },
        "spec": {
            "automountServiceAccountToken": False,
            "nodeName": node_name,
            "restartPolicy": "Never",
            "tolerations": [{"operator": "Exists"}],
            "containers": [
                {
                    "name": "stager",
                    "image": target_image,
                    "imagePullPolicy": "IfNotPresent",
                    "command": ["/bin/sh", "-ec", script],
                    "securityContext": {
                        "readOnlyRootFilesystem": True,
                        "runAsNonRoot": False,
                        "runAsUser": 0,
                    },
                    "readinessProbe": {
                        "exec": {"command": ["test", "-f", "/dev/shm/cxcli-config-staged"]},
                        "failureThreshold": 300,
                        "periodSeconds": 1,
                    },
                    "resources": {
                        "requests": {"cpu": "5m", "memory": "16Mi"},
                        "limits": {"cpu": "100m", "memory": "64Mi"},
                    },
                    "volumeMounts": [
                        {"name": "jail", "mountPath": "/jail"},
                        {"name": "config", "mountPath": "/config", "readOnly": True},
                    ],
                }
            ],
            "volumes": [
                {
                    "name": "jail",
                    "persistentVolumeClaim": {"claimName": "cxcli-controller-bridge-jail"},
                },
                {
                    "name": "config",
                    "configMap": {
                        "name": config_map_name,
                        "items": [{"key": config_key, "path": "slurm.conf"}],
                    },
                },
            ],
        },
    }
    command_runner(
        ["kubectl", "--context", kube_context, "apply", "-f", "-"],
        input_text=json.dumps(manifest, sort_keys=True),
        timeout_seconds=300,
    )
    _wait_for_controller_bridge_stager_ready_or_terminal(
        namespace=namespace,
        pod_name=pod_name,
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=300,
    )
    evidence = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "logs",
            pod_name,
            "-c",
            "stager",
        ],
        timeout_seconds=120,
    )
    if (
        "schema=nebius-cxcli-controller-bridge-jailed-config/v1" not in evidence.stdout
        or f"target_sha256={target_config_sha256}" not in evidence.stdout
    ):
        raise SoperatorMigrationPhasePending(
            "target-version bridge jailed-config stager did not return exact digest evidence."
        )
    staging.update(
        {
            "state": "accepted",
            "accepted_at": _utc_now(),
            "evidence_sha256": hashlib.sha256(evidence.stdout.encode("utf-8")).hexdigest(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "delete",
            f"pod/{pod_name}",
            "--wait=true",
        ],
        timeout_seconds=300,
    )


def _stage_controller_bridge_cluster_name_marker(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    transition = journal.get("version_transition")
    if not isinstance(transition, dict):
        raise RuntimeError("Controller bridge version transition journal must be mutable.")
    source_cluster_name = str(transition.get("source_cluster_name", "") or "").strip()
    target_cluster_name = str(transition.get("target_cluster_name", "") or "").strip()
    if not source_cluster_name or not target_cluster_name:
        raise RuntimeError(
            "recovery-required: target controller state-marker migration lacks cluster names."
        )
    if source_cluster_name == target_cluster_name:
        transition["target_cluster_name_marker"] = {
            "schema": "nebius-cxcli/controller-cluster-name-marker-v1",
            "state": "not-required",
            "source_cluster_name": source_cluster_name,
            "target_cluster_name": target_cluster_name,
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
        return
    marker = transition.get("target_cluster_name_marker")
    if not isinstance(marker, dict):
        marker = {}
        transition["target_cluster_name_marker"] = marker
    recorded_source = str(marker.get("source_cluster_name", "") or "")
    recorded_target = str(marker.get("target_cluster_name", "") or "")
    if (recorded_source and recorded_source != source_cluster_name) or (
        recorded_target and recorded_target != target_cluster_name
    ):
        raise RuntimeError(
            "recovery-required: controller cluster-name marker intent changed after recording."
        )
    marker.update(
        {
            "schema": "nebius-cxcli/controller-cluster-name-marker-v1",
            "state": "dispatching",
            "intent_at": str(marker.get("intent_at", "") or "") or _utc_now(),
            "source_cluster_name": source_cluster_name,
            "target_cluster_name": target_cluster_name,
            "path": "/mnt/controller-spool/current/clustername",
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    marker_path = "/shared/current/clustername"
    script = (
        "set -eu\n"
        f"marker={shlex.quote(marker_path)}\n"
        f"expected_source={shlex.quote(source_cluster_name)}\n"
        f"expected_target={shlex.quote(target_cluster_name)}\n"
        'test -f "$marker"\n'
        'test ! -L "$marker"\n'
        'current=$(cat "$marker")\n'
        'case "$current" in\n'
        '  "$expected_target") suffix="" ;;\n'
        '  "$expected_target"\\|*) suffix=${current#"$expected_target"} ;;\n'
        '  "$expected_source") suffix="" ;;\n'
        '  "$expected_source"\\|*) suffix=${current#"$expected_source"} ;;\n'
        "  *) exit 1 ;;\n"
        "esac\n"
        'case "$suffix" in\n'
        '  "") ;;\n'
        "  \\|*) suffix_digits=${suffix#|}; "
        'case "$suffix_digits" in ""|*[!0-9]*) exit 1 ;; esac ;;\n'
        "  *) exit 1 ;;\n"
        "esac\n"
        'target_value="${expected_target}${suffix}"\n'
        'if test "$current" != "$target_value"; then\n'
        '  temporary="${marker}.cxcli-target.partial"\n'
        '  rm -f "$temporary"\n'
        '  cp -p "$marker" "$temporary"\n'
        '  printf "%s\\n" "$target_value" > "$temporary"\n'
        '  sync -f "$temporary"\n'
        '  mv -f "$temporary" "$marker"\n'
        '  sync -f "$(dirname "$marker")"\n'
        "fi\n"
        'actual=$(cat "$marker")\n'
        'test "$actual" = "$target_value"\n'
        'marker_sha=$(sha256sum "$marker" | cut -d " " -f 1)\n'
        "printf 'schema=nebius-cxcli-controller-cluster-name-marker/v1\\n"
        "target_cluster_name=%s\\nmarker_suffix=%s\\nmarker_sha256=%s\\n' "
        '"$expected_target" "$suffix" "$marker_sha"\n'
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            str(journal.get("namespace", "") or ""),
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            script,
        ],
        timeout_seconds=300,
    )
    if (
        "schema=nebius-cxcli-controller-cluster-name-marker/v1" not in result.stdout
        or f"target_cluster_name={target_cluster_name}" not in result.stdout
    ):
        raise SoperatorMigrationPhasePending(
            "target controller cluster-name state marker did not return exact evidence."
        )
    marker.update(
        {
            "state": "accepted",
            "accepted_at": _utc_now(),
            "evidence_sha256": hashlib.sha256(result.stdout.encode("utf-8")).hexdigest(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()


def _ensure_controller_bridge_target_jailed_config(
    *,
    journal: dict[str, Any],
    statefulset: Mapping[str, Any],
    target_replicas: int,
    container_name: str,
    config_map_name: str,
    config_key: str,
    target_config_sha256: str,
    target_image: str,
    target_write_already_accepted: bool,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> int:
    transition = journal.get("version_transition")
    source_configuration = _mapping(journal.get("source_configuration"))
    if not isinstance(transition, dict):
        raise RuntimeError("Controller bridge version transition journal must be mutable.")
    expected_preimage_sha256 = str(source_configuration.get("bridge_config_sha256", "") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", expected_preimage_sha256):
        raise RuntimeError(
            "recovery-required: target jailed-config staging lacks the exact source bridge "
            "configuration preimage digest."
        )
    namespace = str(journal.get("namespace", "") or "")
    repair = transition.get("target_jailed_config_repair")
    if not isinstance(repair, dict):
        repair = {}
        transition["target_jailed_config_repair"] = repair
    marker = _mapping(transition.get("target_cluster_name_marker"))
    marker_required = (
        transition.get("cluster_name_change") is True and marker.get("state") != "accepted"
    )
    staging = _mapping(transition.get("target_jailed_config"))
    restart_required = False
    if target_replicas == 2:
        if marker_required and staging.get("state") == "accepted":
            observed = {target_config_sha256}
        else:
            live_digests = _controller_bridge_live_jailed_config_digests(
                namespace=namespace,
                container_name=container_name,
                kube_context=kube_context,
                command_runner=command_runner,
            )
            observed = set(live_digests.values())
        if observed == {target_config_sha256} and not marker_required:
            mutable_staging = transition.get("target_jailed_config")
            if not isinstance(mutable_staging, dict):
                mutable_staging = {}
                transition["target_jailed_config"] = mutable_staging
            mutable_staging.update(
                {
                    "schema": "nebius-cxcli/controller-bridge-jailed-config-v1",
                    "state": "accepted",
                    "target_sha256": target_config_sha256,
                    "expected_preimage_sha256": expected_preimage_sha256,
                    "accepted_at": str(mutable_staging.get("accepted_at", "") or "") or _utc_now(),
                    "accepted_by_live_reconciliation": True,
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return 2
        if observed not in ({expected_preimage_sha256}, {target_config_sha256}):
            raise RuntimeError(
                "recovery-required: live target bridge jailed configurations do not match "
                "either the exact source preimage or target digest."
            )
        if not target_write_already_accepted:
            raise RuntimeError(
                "recovery-required: target bridge has live replicas before the accepted "
                "writer boundary but still reads the source jailed configuration."
            )
        metadata = _mapping(statefulset.get("metadata"))
        statefulset_uid = str(metadata.get("uid", "") or "")
        pods_payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pods",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        pods = _sequence_of_mappings(pods_payload.get("items"))
        pre_stop_pods = tuple(
            (
                namespace,
                str(_mapping(pod.get("metadata")).get("name", "") or ""),
                str(_mapping(pod.get("metadata")).get("uid", "") or ""),
            )
            for pod in pods
        )
        if (
            len(pre_stop_pods) != 2
            or any(not name or not uid for _pod_namespace, name, uid in pre_stop_pods)
            or not statefulset_uid
        ):
            raise RuntimeError(
                "recovery-required: target jailed-config repair lacks exact live writer identities."
            )
        prior_repair_census = _sequence_of_mappings(repair.get("pre_stop_runtime_census"))
        if marker_required and staging.get("state") == "accepted" and prior_repair_census:
            pre_stop_census = prior_repair_census
            _revalidate_controller_runtime_census_nodes(
                node_census=pre_stop_census,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        else:
            pre_stop_census = _prove_cluster_wide_slurmctld_exclusivity(
                expected_pods=pre_stop_pods,
                expected_workload=(
                    "statefulsets.apps",
                    namespace,
                    "cxcli-slurm-controller-bridge",
                    statefulset_uid,
                ),
                expected_replicas=2,
                proof_label="target-version bridge jailed-config repair pre-stop runtime census",
                campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        repair.update(
            {
                "schema": "nebius-cxcli/controller-bridge-jailed-config-repair-v1",
                "state": "stop-dispatching",
                "intent_at": str(repair.get("intent_at", "") or "") or _utc_now(),
                "statefulset_uid": statefulset_uid,
                "target_sha256": target_config_sha256,
                "preimage_sha256": expected_preimage_sha256,
                "repair_count": _positive_int(repair.get("repair_count"), fallback=0) + 1,
                "cluster_name_marker_required": marker_required,
                "pre_stop_runtime_census": pre_stop_census,
                "pre_stop_pods": [
                    {"namespace": pod_namespace, "name": name, "uid": uid}
                    for pod_namespace, name, uid in pre_stop_pods
                ],
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=0,
            current_replicas=2,
            resource_version=str(metadata.get("resourceVersion", "") or ""),
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "wait",
                "--for=delete",
                "pod",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "--timeout=10m",
            ],
            timeout_seconds=660,
        )
        controller_roles = _sequence_of_mappings(journal.get("controller_roles"))
        state_path = str(
            _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
        )
        if len(controller_roles) != 2 or not state_path.startswith("/"):
            raise RuntimeError(
                "recovery-required: target jailed-config repair lacks both historical nodes."
            )
        repair["runtime_fence"] = _prove_controller_runtime_fence(
            journal=journal,
            boundary="target-version-bridge-jailed-config-repair",
            targets=tuple(
                ControllerFenceTarget(
                    node_name=str(role.get("node_name", "") or ""),
                    node_uid=str(role.get("node_uid", "") or ""),
                    state_markers=(state_path, "/mnt/controller-spool/current"),
                )
                for role in controller_roles
            ),
            image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="target-version bridge jailed-config repair post-stop fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        repair["post_stop_node_revalidation"] = _revalidate_controller_runtime_census_nodes(
            node_census=pre_stop_census,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        repair.update({"state": "stopped", "stopped_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        target_replicas = 0
        restart_required = True

    _stage_controller_bridge_jailed_config(
        journal=journal,
        config_map_name=config_map_name,
        config_key=config_key,
        target_config_sha256=target_config_sha256,
        expected_preimage_sha256=expected_preimage_sha256,
        target_image=target_image,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    _stage_controller_bridge_cluster_name_marker(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    if restart_required:
        exists, stopped_statefulset = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
        )
        stopped_metadata = _mapping(stopped_statefulset.get("metadata"))
        if (
            not exists
            or str(stopped_metadata.get("uid", "") or "") != repair.get("statefulset_uid")
            or _resource_replicas(stopped_statefulset, default=-1) != 0
        ):
            raise RuntimeError(
                "recovery-required: target jailed-config repair lost its stopped StatefulSet."
            )
        _revalidate_controller_authority_lease(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_runtime_census_nodes(
            node_census=_sequence_of_mappings(repair.get("pre_stop_runtime_census")),
            kube_context=kube_context,
            command_runner=command_runner,
        )
        repair.update({"state": "restart-dispatching", "restart_dispatching_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=2,
            current_replicas=0,
            resource_version=str(stopped_metadata.get("resourceVersion", "") or ""),
        )
        repair.update({"state": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        target_replicas = 2
    return target_replicas


def _revalidate_controller_bridge_job_state_recovery(
    *,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[str]:
    transition = _mapping(journal.get("version_transition"))
    recovery = _mapping(transition.get("job_state_recovery"))
    if not recovery:
        return []
    target_config_sha256 = str(transition.get("target_config_sha256", "") or "")
    job_id = str(recovery.get("job_id", "") or "").strip()
    recovery_epoch = str(recovery.get("recovery_epoch", "") or "").strip()
    recovered_job_state_sha256 = str(recovery.get("job_state_sha256", "") or "").strip()
    if (
        recovery.get("schema") != "nebius-cxcli/controller-bridge-job-state-recovery-v1"
        or recovery.get("state") != "verified"
        or str(recovery.get("target_config_sha256", "") or "") != target_config_sha256
        or not re.fullmatch(r"[0-9a-f]{64}", target_config_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", recovered_job_state_sha256)
        or not re.fullmatch(r"[0-9]+", job_id)
        or not recovery_epoch
    ):
        raise RuntimeError("recovery-required: controller job-state recovery journal is invalid.")
    namespace = str(journal.get("namespace", "") or "")
    exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    metadata = _mapping(statefulset.get("metadata"))
    status = _mapping(statefulset.get("status"))
    if (
        not exists
        or str(metadata.get("uid", "") or "")
        != str(recovery.get("controller_statefulset_uid", "") or "")
        or _resource_replicas(statefulset, default=-1) != 2
        or _non_negative_int(status.get("readyReplicas"), fallback=0) != 2
    ):
        raise SoperatorMigrationPhasePending(
            "recovered target controller bridge is not the exact Ready 2/2 StatefulSet."
        )
    jailed_digests = _controller_bridge_live_jailed_config_digests(
        namespace=namespace,
        container_name="slurmctld",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    if len(jailed_digests) != 2 or set(jailed_digests.values()) != {target_config_sha256}:
        raise SoperatorMigrationPhasePending(
            "recovered target controllers do not share the exact repaired jailed config."
        )
    spool = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            "cxcli-controller-bridge-stager",
            "-c",
            "stager",
            "--",
            "/bin/sh",
            "-ec",
            "printf '%s\\n' \"$(readlink /shared/current)\"; "
            "sha256sum /shared/current/job_state; cat /shared/current/clustername",
        ],
        timeout_seconds=120,
    )
    spool_lines = spool.stdout.splitlines()
    live_job_state_fields = spool_lines[1].split() if len(spool_lines) == 3 else []
    target_cluster_name = str(transition.get("target_cluster_name", "") or "")
    if (
        len(spool_lines) != 3
        or spool_lines[0] != f"epochs/{recovery_epoch}"
        or len(live_job_state_fields) != 2
        or not re.fullmatch(r"[0-9a-f]{64}", live_job_state_fields[0])
        or live_job_state_fields[1] != "/shared/current/job_state"
        or not target_cluster_name
        or not re.fullmatch(
            re.escape(target_cluster_name) + r"(?:\|[0-9]+)?",
            spool_lines[2],
        )
    ):
        raise RuntimeError(
            "recovery-required: recovered controller state epoch identity or marker drifted."
        )
    pod_names = sorted(
        str(role.get("pod_name", "") or "")
        for role in _sequence_of_mappings(journal.get("controller_roles"))
        if str(role.get("pod_name", "") or "")
    )
    if len(pod_names) != 2:
        raise RuntimeError("recovery-required: recovered controller roles are incomplete.")
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_names[0],
            "-c",
            "slurmctld",
            "--",
            "scontrol",
            "show",
            "job",
            job_id,
            "-o",
        ],
        timeout_seconds=120,
    )
    fields = _slurm_job_control_record_fields(" ".join(result.stdout.split()))
    if (
        str(fields.get("JobId", "") or "") != job_id
        or str(fields.get("JobState", "") or "") != recovery.get("job_state")
        or str(fields.get("Reason", "") or "") != recovery.get("job_reason")
        or str(fields.get("Partition", "") or "") != recovery.get("job_partition")
        or str(fields.get("Restarts", "") or "") != "0"
    ):
        raise SoperatorMigrationPhasePending(
            f"recovered Slurm job {job_id} no longer matches its held pending lineage."
        )
    return [f"Recovered Slurm job {job_id} revalidated from the sealed pre-switch state."]


def _upgrade_controller_bridge_to_target_version(
    *,
    checkpoint: dict[str, Any],
    values: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            "target Slurm version transition requires the v6 controller bridge journal."
        )
    validate_bridge_journal(journal)
    stage = BridgeStage(str(journal.get("stage", "") or ""))
    if stage is BridgeStage.TARGET_HA_ACTIVE:
        recovery_lines = _revalidate_controller_bridge_job_state_recovery(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        return [
            "Controller bridge target-version HA proof reused from journal v6.",
            *recovery_lines,
        ]
    if stage in {
        BridgeStage.BRIDGE_FENCED,
        BridgeStage.TARGET_SINGLETON_ACTIVE,
        BridgeStage.HANDOFF_VALIDATED,
        BridgeStage.PARTITIONS_RESTORED,
        BridgeStage.CLEANED,
    }:
        return ["Controller bridge target-version HA proof reused from journal v6."]
    if stage is not BridgeStage.SOURCE_HA_ACTIVE:
        raise SoperatorMigrationPhasePending(
            "target Slurm version transition requires source-version bridge HA; "
            f"current stage={stage.value}."
        )
    namespace = str(journal.get("namespace", "") or "")
    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "accept-only")
    journal["action_broker_mode"] = "accept-only"
    if checkpoint_writer is not None:
        checkpoint_writer()

    transition = journal.get("version_transition")
    if not isinstance(transition, dict):
        raise RuntimeError("Controller bridge version transition journal must be mutable.")
    target_write_already_accepted = bool(str(transition.get("target_write_at", "") or "").strip())
    if target_write_already_accepted:
        target_scale = _mapping(transition.get("target_writer_scale"))
        if (
            transition.get("downgrade_prohibited") is not True
            or target_scale.get("state") != "accepted"
            or _mapping(journal.get("authority")).get("owner") != "bridge-target"
        ):
            raise RuntimeError("recovery-required: target-version writer checkpoint is incomplete.")
    backup_epoch = _controller_bridge_epoch(journal, "pre-target")
    target_epoch = _controller_bridge_epoch(journal, "bridge-target")

    exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not exists:
        raise RuntimeError("Controller bridge StatefulSet disappeared before version transition.")
    metadata = _mapping(statefulset.get("metadata"))
    replicas = _resource_replicas(statefulset, default=-1)
    if replicas not in {0, 2}:
        raise RuntimeError(
            f"Controller bridge replicas drifted outside simultaneous 2 -> 0 stop: {replicas}."
        )
    pending_target_scale = transition.get("target_writer_scale")
    if (
        not target_write_already_accepted
        and isinstance(pending_target_scale, dict)
        and pending_target_scale.get("state") == "dispatching"
    ):
        pending_uid = str(pending_target_scale.get("statefulset_uid", "") or "")
        template = _mapping(_mapping(_mapping(statefulset.get("spec")).get("template")).get("spec"))
        target_image = str(transition.get("target_image", "") or "")
        target_container = next(
            (
                item
                for item in _sequence_of_mappings(template.get("containers"))
                if str(item.get("image", "") or "") == target_image
            ),
            {},
        )
        template_annotations = _mapping(
            _mapping(_mapping(statefulset.get("spec")).get("template")).get("metadata")
        ).get("annotations")
        target_config_sha256 = str(transition.get("target_config_sha256", "") or "")
        if (
            not pending_uid
            or str(metadata.get("uid", "") or "") != pending_uid
            or not target_container
            or not re.fullmatch(r"[0-9a-f]{64}", target_config_sha256)
            or str(
                _mapping(template_annotations).get("nebius.ai/cxcli-target-config-sha256", "") or ""
            )
            != target_config_sha256
        ):
            raise RuntimeError(
                "recovery-required: an indeterminate target-version writer scale cannot be "
                "bound to the exact target image, config, and StatefulSet UID."
            )
        if replicas == 2:
            pending_target_scale.update(
                {
                    "state": "accepted",
                    "accepted_at": _utc_now(),
                    "accepted_by_live_reconciliation": True,
                }
            )
            record_bridge_authority(
                journal,
                epoch=target_epoch,
                owner="bridge-target",
                reason=(
                    "live replicas proved an indeterminate target-version writer scale was accepted"
                ),
            )
            transition.update(
                {
                    "target_write_at": _utc_now(),
                    "downgrade_prohibited": True,
                }
            )
            target_write_already_accepted = True
            _revalidate_controller_authority_lease(
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        else:
            pending_target_scale.update(
                {
                    "state": "reconciled-not-accepted",
                    "reconciled_at": _utc_now(),
                }
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if not target_write_already_accepted:
        transition["stop_intent_at"] = transition.get("stop_intent_at") or _utc_now()
        transition["stop_expected_replicas"] = replicas
    if not target_write_already_accepted and replicas == 2:
        live_bridge_pods = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pods",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        transition["stop_pod_uids"] = [
            str(_mapping(pod.get("metadata")).get("uid", "") or "")
            for pod in _sequence_of_mappings(live_bridge_pods.get("items"))
        ]
        if len(transition["stop_pod_uids"]) != 2 or not all(transition["stop_pod_uids"]):
            raise SoperatorMigrationPhasePending(
                "target Slurm transition requires two exact bridge Pod UIDs before stop."
            )
        pre_stop_pods = tuple(
            (
                namespace,
                str(_mapping(pod.get("metadata")).get("name", "") or ""),
                str(_mapping(pod.get("metadata")).get("uid", "") or ""),
            )
            for pod in _sequence_of_mappings(live_bridge_pods.get("items"))
        )
        statefulset_uid = str(metadata.get("uid", "") or "")
        if (
            len(pre_stop_pods) != 2
            or any(not name or not uid for _namespace, name, uid in pre_stop_pods)
            or not statefulset_uid
        ):
            raise SoperatorMigrationPhasePending(
                "target Slurm transition requires the exact live bridge workload and Pod "
                "identities before its cold stop."
            )
        _capture_controller_bridge_cold_job_census(
            checkpoint=checkpoint,
            transition=transition,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        # Run the expensive all-node host-process census while the HA bridge is
        # still serving.  During the short vendor-required major-version cold
        # restart, the exact bridge-node fences plus the API/workload absence
        # proof below are sufficient when every pre-stop Node identity remains
        # unchanged.  This keeps safety evidence fail-closed without extending
        # the controller outage by a whole-cluster census.
        pre_stop_census = _prove_cluster_wide_slurmctld_exclusivity(
            expected_pods=pre_stop_pods,
            expected_workload=(
                "statefulsets.apps",
                namespace,
                "cxcli-slurm-controller-bridge",
                statefulset_uid,
            ),
            expected_replicas=2,
            proof_label="source-version bridge pre-stop runtime census",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        transition.update(
            {
                "pre_stop_runtime_census": pre_stop_census,
                "pre_stop_runtime_census_at": _utc_now(),
                "pre_stop_runtime_pods": [
                    {"namespace": pod_namespace, "name": name, "uid": uid}
                    for pod_namespace, name, uid in pre_stop_pods
                ],
                "pre_stop_runtime_workload_uid": statefulset_uid,
            }
        )
    if not target_write_already_accepted and checkpoint_writer is not None:
        checkpoint_writer()
    if not target_write_already_accepted and replicas == 2:
        transition.update(
            {
                "cold_stop_attempt": _positive_int(transition.get("cold_stop_attempt"), fallback=0)
                + 1,
                "cold_stop_dispatching_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=0,
            current_replicas=2,
            resource_version=str(metadata.get("resourceVersion", "") or ""),
        )
    if not target_write_already_accepted:
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "wait",
                "--for=delete",
                "pod",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "--timeout=10m",
            ],
            timeout_seconds=660,
        )
        if replicas == 2:
            transition["both_stopped_at"] = _utc_now()
        else:
            transition["both_stopped_at"] = transition.get("both_stopped_at") or _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        stopped_roles = _sequence_of_mappings(journal.get("controller_roles"))
        state_path = str(
            _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
        )
        if len(stopped_roles) != 2 or not state_path.startswith("/"):
            raise RuntimeError(
                "Controller bridge cold stop requires two historical node bindings and "
                "the exact mounted StateSaveLocation."
            )
        runtime_evidence = _prove_controller_runtime_fence(
            journal=journal,
            boundary="source-version-bridge-stopped",
            targets=tuple(
                ControllerFenceTarget(
                    node_name=str(role.get("node_name", "") or ""),
                    node_uid=str(role.get("node_uid", "") or ""),
                    state_markers=(state_path, "/mnt/controller-spool/current"),
                )
                for role in stopped_roles
            ),
            image=str(transition.get("source_image", "") or ""),
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        transition["source_runtime_fence"] = runtime_evidence
        pre_stop_census = _sequence_of_mappings(transition.get("pre_stop_runtime_census"))
        if not pre_stop_census:
            raise RuntimeError(
                "recovery-required: source-version bridge cold stop lacks the fresh "
                "pre-stop all-node runtime census."
            )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="source-version bridge cold stop",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        transition["post_stop_node_revalidation"] = _revalidate_controller_runtime_census_nodes(
            node_census=pre_stop_census,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        transition["post_stop_api_absence_verified_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()

    if not target_write_already_accepted and not str(transition.get("backup_sha256", "") or ""):
        backup_operation = transition.get("backup_operation")
        if not isinstance(backup_operation, dict):
            backup_operation = {}
            transition["backup_operation"] = backup_operation
        backup_token = str(backup_operation.get("token", "") or "") or uuid4().hex
        if not re.fullmatch(r"[a-f0-9]{32}", backup_token):
            raise RuntimeError("Controller cold-backup operation token is malformed.")
        backup_operation.update(
            {
                "state": str(backup_operation.get("state", "") or "") or "intent-recorded",
                "intent_at": str(backup_operation.get("intent_at", "") or "") or _utc_now(),
                "token": backup_token,
                "backup_epoch": backup_epoch,
            }
        )
        expected_preimage_sha256 = str(backup_operation.get("expected_preimage_sha256", "") or "")
        expected_preimage_entries = int(backup_operation.get("expected_preimage_entries", 0) or 0)
        if checkpoint_writer is not None:
            checkpoint_writer()
        if not expected_preimage_sha256:
            preimage_manifest = (
                f"/shared/backups/.{backup_epoch}.preimage-{backup_token}.manifest.tsv"
            )
            preimage_script = (
                "test ! -L /shared/backups; mkdir -p /shared/backups; "
                "test -d /shared/backups; "
                + _bridge_tree_manifest_transient_cleanup_script(output=preimage_manifest)
                + "; "
                + _bridge_tree_manifest_script(root="/shared/current", output=preimage_manifest)
                + f"; rm -f {shlex.quote(preimage_manifest)}"
            )
            preimage = command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    namespace,
                    "exec",
                    "cxcli-controller-bridge-stager",
                    "-c",
                    "stager",
                    "--",
                    "/bin/sh",
                    "-ec",
                    preimage_script,
                ],
                timeout_seconds=1800,
            )
            preimage_match = re.search(
                r"CXCLI_MANIFEST=([0-9a-f]{64}) CXCLI_ENTRIES=([1-9][0-9]*)",
                preimage.stdout,
            )
            if not preimage_match:
                raise SoperatorMigrationPhasePending(
                    "controller bridge cold backup could not bind the fenced preimage."
                )
            expected_preimage_sha256 = preimage_match.group(1)
            expected_preimage_entries = int(preimage_match.group(2))
            backup_operation.update(
                {
                    "expected_preimage_sha256": expected_preimage_sha256,
                    "expected_preimage_entries": expected_preimage_entries,
                    "preimage_bound_at": _utc_now(),
                }
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
        backup_temporary = f"/shared/backups/.{backup_epoch}.partial-{backup_token}"
        backup_path = f"/shared/backups/{backup_epoch}"
        backup_manifest = f"{backup_path}/TREE.manifest.tsv"
        temporary_manifest = f"{backup_temporary}/TREE.manifest.tsv"
        verification_manifest = (
            f"/shared/backups/.{backup_epoch}.verify-{backup_token}.manifest.tsv"
        )
        backup_script = (
            f"mkdir -p /shared/backups; test ! -L {shlex.quote(backup_path)}; "
            f"if test ! -e {shlex.quote(backup_path)}; then "
            f"test ! -L {shlex.quote(backup_temporary)}; "
            f"rm -rf {shlex.quote(backup_temporary)}; "
            f"mkdir -p {shlex.quote(backup_temporary + '/state')}; "
            f"cp -a /shared/current/. {shlex.quote(backup_temporary + '/state/')}; "
            + _bridge_tree_manifest_script(
                root=f"{backup_temporary}/state",
                output=temporary_manifest,
            )
            + f"; test \"$(sha256sum {shlex.quote(temporary_manifest)} | cut -d ' ' -f 1)\" = "
            + shlex.quote(expected_preimage_sha256)
            + f"; test \"$(wc -l < {shlex.quote(temporary_manifest)} | tr -d ' ')\" = "
            + shlex.quote(str(expected_preimage_entries))
            + "; "
            + f"find {shlex.quote(backup_temporary + '/state')} -xdev -type f -exec sync -f {{}} \\;; "
            + f"sync -f {shlex.quote(temporary_manifest)}; "
            + f"sync -f {shlex.quote(backup_temporary + '/state')}; "
            + f"mv {shlex.quote(backup_temporary)} {shlex.quote(backup_path)}; "
            + "sync -f /shared/backups; else "
            + f"test -d {shlex.quote(backup_path + '/state')}; "
            + f"test -f {shlex.quote(backup_manifest)}; fi; "
            + _bridge_tree_manifest_transient_cleanup_script(output=verification_manifest)
            + "; "
            + _bridge_tree_manifest_script(
                root=f"{backup_path}/state",
                output=verification_manifest,
            )
            + f"; test \"$(sha256sum {shlex.quote(verification_manifest)} | cut -d ' ' -f 1)\" = "
            + shlex.quote(expected_preimage_sha256)
            + f"; test \"$(wc -l < {shlex.quote(verification_manifest)} | tr -d ' ')\" = "
            + shlex.quote(str(expected_preimage_entries))
            + f"; cmp -s {shlex.quote(verification_manifest)} {shlex.quote(backup_manifest)}; "
            + f"rm -f {shlex.quote(verification_manifest)}; "
            + "printf 'CXCLI_BACKUP_MANIFEST=%s CXCLI_BACKUP_ENTRIES=%s\\n' "
            + f"\"$(sha256sum {shlex.quote(backup_manifest)} | cut -d ' ' -f 1)\" "
            + f"\"$(wc -l < {shlex.quote(backup_manifest)} | tr -d ' ')\""
        )
        backup_operation.update({"state": "dispatching", "dispatching_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        backup = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                backup_script,
            ],
            timeout_seconds=1800,
        )
        backup_match = re.search(
            r"CXCLI_BACKUP_MANIFEST=([0-9a-f]{64}) CXCLI_BACKUP_ENTRIES=([1-9][0-9]*)",
            backup.stdout,
        )
        if not backup_match:
            raise SoperatorMigrationPhasePending(
                "controller bridge cold target-version backup did not return exact metadata."
            )
        if (
            backup_match.group(1) != expected_preimage_sha256
            or int(backup_match.group(2)) != expected_preimage_entries
        ):
            raise RuntimeError(
                "recovery-required: controller cold backup no longer matches its fenced preimage."
            )
        backup_operation.update({"state": "accepted", "accepted_at": _utc_now()})
        transition.update(
            {
                "backup_path": f"/mnt/controller-spool/backups/{backup_epoch}",
                "backup_sha256": backup_match.group(1),
                "backup_entry_count": int(backup_match.group(2)),
                "backup_completed_at": _utc_now(),
                "backup_cold_after_runtime_fence": True,
                "backup_recovery_consumed": False,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()

    if not target_write_already_accepted:
        expected_backup_sha256 = str(transition.get("backup_sha256", "") or "")
        expected_backup_entries = int(transition.get("backup_entry_count", 0) or 0)
        if (
            not re.fullmatch(r"[0-9a-f]{64}", expected_backup_sha256)
            or expected_backup_entries <= 0
            or transition.get("backup_cold_after_runtime_fence") is not True
        ):
            raise RuntimeError(
                "Target-version bridge restart requires a cold, runtime-fenced state backup."
            )
        comparison_token = uuid4().hex
        current_manifest = f"/shared/backups/.current-{comparison_token}.manifest.tsv"
        comparison_script = (
            _bridge_tree_manifest_transient_cleanup_script(output=current_manifest)
            + "; "
            + _bridge_tree_manifest_script(root="/shared/current", output=current_manifest)
            + "; "
            + f"test \"$(sha256sum {shlex.quote(current_manifest)} | cut -d ' ' -f 1)\" = "
            + shlex.quote(expected_backup_sha256)
            + "; "
            + f"test \"$(wc -l < {shlex.quote(current_manifest)} | tr -d ' ')\" = "
            + shlex.quote(str(expected_backup_entries))
            + f"; rm -f {shlex.quote(current_manifest)}"
        )
        comparison = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "exec",
                "cxcli-controller-bridge-stager",
                "-c",
                "stager",
                "--",
                "/bin/sh",
                "-ec",
                comparison_script,
            ],
            check=False,
            timeout_seconds=1800,
        )
        recovery = _mapping(transition.get("backup_recovery"))
        recovery_in_progress = (
            recovery.get("state")
            in {
                "intent-recorded",
                "dispatching",
            }
            and transition.get("backup_recovery_consumed") is not True
        )
        if comparison.returncode != 0 or recovery_in_progress:
            recovery, _reused_in_progress = _controller_bridge_backup_recovery_binding(
                transition,
                backup_epoch=backup_epoch,
            )
            restore_epoch = str(recovery.get("restore_epoch", "") or "")
            restore_token = str(recovery.get("token", "") or "")
            if not restore_epoch or not restore_token:
                raise RuntimeError(
                    "Controller state recovery intent lacks an exact epoch or operation token."
                )
            if not re.fullmatch(r"[a-z0-9.-]+", restore_epoch) or not re.fullmatch(
                r"[a-f0-9]{32}", restore_token
            ):
                raise RuntimeError("Controller state recovery binding is malformed.")
            restore_path = f"/shared/epochs/{restore_epoch}"
            restore_partial = f"/shared/epochs/.{restore_epoch}.partial-{restore_token}"
            restore_manifest = f"/shared/backups/.restore-{restore_token}.manifest.tsv"
            restore_link = f"/shared/.current-{restore_token}"
            recovery.update(
                {
                    "state": "intent-recorded",
                    "intent_at": str(recovery.get("intent_at", "") or "") or _utc_now(),
                    "restore_epoch": restore_epoch,
                    "restore_path": f"/mnt/controller-spool/epochs/{restore_epoch}",
                    "token": restore_token,
                    "expected_manifest_sha256": expected_backup_sha256,
                    "expected_entry_count": expected_backup_entries,
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            restore_script = (
                f"test -d {shlex.quote('/shared/backups/' + backup_epoch + '/state')}; "
                + f"test ! -L {shlex.quote(restore_path)}; "
                + _bridge_tree_manifest_transient_cleanup_script(output=restore_manifest)
                + "; "
                + f"if test ! -e {shlex.quote(restore_path)}; then "
                + f"test ! -L {shlex.quote(restore_partial)}; "
                + f"rm -rf {shlex.quote(restore_partial)}; "
                + f"mkdir -p {shlex.quote(restore_partial)}; "
                + f"cp -a {shlex.quote('/shared/backups/' + backup_epoch + '/state/.')} "
                + f"{shlex.quote(restore_partial + '/')}; "
                + _bridge_tree_manifest_script(root=restore_partial, output=restore_manifest)
                + "; "
                + f"test \"$(sha256sum {shlex.quote(restore_manifest)} | cut -d ' ' -f 1)\" = "
                + shlex.quote(expected_backup_sha256)
                + "; "
                + f"test \"$(wc -l < {shlex.quote(restore_manifest)} | tr -d ' ')\" = "
                + shlex.quote(str(expected_backup_entries))
                + f"; find {shlex.quote(restore_partial)} -xdev -type f -exec sync -f {{}} \\;; "
                + f"sync -f {shlex.quote(restore_partial)}; "
                + f"mv {shlex.quote(restore_partial)} {shlex.quote(restore_path)}; "
                + "sync -f /shared/epochs; else "
                + _bridge_tree_manifest_script(root=restore_path, output=restore_manifest)
                + "; "
                + f"test \"$(sha256sum {shlex.quote(restore_manifest)} | cut -d ' ' -f 1)\" = "
                + shlex.quote(expected_backup_sha256)
                + "; "
                + f"test \"$(wc -l < {shlex.quote(restore_manifest)} | tr -d ' ')\" = "
                + shlex.quote(str(expected_backup_entries))
                + "; fi; "
                + f"rm -f {shlex.quote(restore_link)}; "
                + f"ln -s {shlex.quote('epochs/' + restore_epoch)} {shlex.quote(restore_link)}; "
                + f"mv -Tf {shlex.quote(restore_link)} /shared/current; sync -f /shared; "
                + f"rm -f {shlex.quote(restore_manifest)}"
            )
            recovery.update({"state": "dispatching", "dispatching_at": _utc_now()})
            if checkpoint_writer is not None:
                checkpoint_writer()
            command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    namespace,
                    "exec",
                    "cxcli-controller-bridge-stager",
                    "-c",
                    "stager",
                    "--",
                    "/bin/sh",
                    "-ec",
                    restore_script,
                ],
                timeout_seconds=1800,
            )
            recovery.update({"state": "accepted", "accepted_at": _utc_now()})
            transition.update(
                {
                    "backup_recovery_consumed": True,
                    "backup_recovery_epoch": restore_epoch,
                    "backup_recovered_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()

    _target_config_name, target_bridge_config, _target_state_path = (
        _controller_bridge_target_config(
            journal=journal,
            values=values,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    )
    target_cluster_match = re.search(r"(?im)^\s*ClusterName\s*=\s*(\S+)\s*$", target_bridge_config)
    target_cluster_name = target_cluster_match.group(1) if target_cluster_match else ""
    source_cluster_name = str(journal.get("cluster_name", "") or "").strip()
    recorded_target_cluster_name = str(transition.get("target_cluster_name", "") or "").strip()
    if (
        not source_cluster_name
        or not target_cluster_name
        or (recorded_target_cluster_name and recorded_target_cluster_name != target_cluster_name)
    ):
        raise RuntimeError(
            "recovery-required: controller bridge source/target Slurm cluster-name "
            "transition is incomplete or changed."
        )
    transition.update(
        {
            "source_cluster_name": source_cluster_name,
            "target_cluster_name": target_cluster_name,
            "cluster_name_change": source_cluster_name != target_cluster_name,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    source_configuration = _mapping(journal.get("source_configuration"))
    bridge_config_names = tuple(
        str(item or "").strip()
        for item in source_configuration.get("config_map_names", []) or []
        if str(item or "").strip()
    )
    if len(bridge_config_names) != 1:
        raise RuntimeError("Controller bridge requires one exact mounted Slurm ConfigMap.")
    bridge_config_map = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "configmap",
            bridge_config_names[0],
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    bridge_data = copy.deepcopy(dict(_mapping(bridge_config_map.get("data"))))
    slurm_config_key = str(source_configuration.get("config_key", "") or "").strip()
    if (
        not slurm_config_key
        or slurm_config_key not in bridge_data
        or "ClusterName=" not in str(bridge_data.get(slurm_config_key, "") or "")
    ):
        raise RuntimeError(
            "Controller bridge mounted ConfigMap lost its exact journaled slurm.conf key."
        )
    bridge_data[slurm_config_key] = target_bridge_config
    if not target_write_already_accepted:
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource=f"configmap/{bridge_config_names[0]}",
            patch={"data": bridge_data},
            patch_via_stdin=True,
        )
    mirrored_records = journal.get("mirrored_material")
    if not isinstance(mirrored_records, list):
        raise RuntimeError("Controller bridge mirrored material journal must be mutable.")
    mirrored_config_record = next(
        (
            item
            for item in mirrored_records
            if isinstance(item, dict)
            and item.get("kind") == "ConfigMap"
            and item.get("name") == bridge_config_names[0]
        ),
        None,
    )
    if not isinstance(mirrored_config_record, dict):
        raise RuntimeError("Controller bridge mounted ConfigMap identity binding is missing.")
    if not target_write_already_accepted:
        mirrored_config_record["material_sha256"] = _controller_bridge_material_fingerprint(
            {**bridge_config_map, "data": bridge_data}
        )

    exists, stopped_statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not exists:
        raise RuntimeError("Controller bridge StatefulSet disappeared while stopped.")
    stopped_metadata = _mapping(stopped_statefulset.get("metadata"))
    containers = _sequence_of_mappings(
        _mapping(
            _mapping(_mapping(stopped_statefulset.get("spec")).get("template")).get("spec")
        ).get("containers")
    )
    container_name = next(
        (
            str(item.get("name", "") or "")
            for item in containers
            if "slurmctld" in str(item.get("name", "") or "").lower()
        ),
        "",
    )
    if not container_name:
        raise RuntimeError("Controller bridge StatefulSet lost its slurmctld container.")
    target_image = str(transition.get("target_image", "") or "")
    target_containers = copy.deepcopy(list(containers))
    target_container_matches = 0
    for container in target_containers:
        if str(container.get("name", "") or "") == container_name:
            container["image"] = target_image
            target_container_matches += 1
    if target_container_matches != 1:
        raise RuntimeError(
            "Controller bridge target image patch requires one exact slurmctld container."
        )
    rendered_target_config_sha256 = hashlib.sha256(target_bridge_config.encode("utf-8")).hexdigest()
    target_config_binding_recovery: dict[str, Any] | None = None
    if target_write_already_accepted:
        accepted_jailed_config = _mapping(transition.get("target_jailed_config"))
        accepted_target_config_sha256 = str(accepted_jailed_config.get("target_sha256", "") or "")
        if accepted_jailed_config.get("state") != "accepted" or not re.fullmatch(
            r"[0-9a-f]{64}", accepted_target_config_sha256
        ):
            raise RuntimeError(
                "recovery-required: accepted target-version bridge writers lack the exact "
                "jailed configuration binding."
            )
        target_config_sha256 = accepted_target_config_sha256
        recorded_target_config_sha256 = str(transition.get("target_config_sha256", "") or "")
        if recorded_target_config_sha256 != accepted_target_config_sha256:
            target_config_binding_recovery = {
                "schema": "nebius-cxcli/controller-bridge-target-config-binding-recovery-v1",
                "status": "pending-live-verification",
                "previous_sha256": recorded_target_config_sha256,
                "accepted_sha256": accepted_target_config_sha256,
                "rendered_target_sha256": rendered_target_config_sha256,
            }
    else:
        target_config_sha256 = rendered_target_config_sha256
    if not target_write_already_accepted:
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            patch={
                "metadata": {
                    "resourceVersion": str(stopped_metadata.get("resourceVersion", "") or "")
                },
                "spec": {
                    "template": {
                        "metadata": {
                            "annotations": {
                                "nebius.ai/cxcli-target-config-sha256": target_config_sha256
                            }
                        },
                        # JSON merge patch replaces arrays. Preserve the entire security,
                        # mount, command, and sidecar contract while changing one image.
                        "spec": {"containers": target_containers},
                    }
                },
            },
            patch_via_stdin=True,
        )
    if not target_write_already_accepted:
        transition.update(
            {
                "target_config_sha256": target_config_sha256,
                "target_material_staged_at": transition.get("target_material_staged_at")
                or _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()

    _revalidate_controller_bridge_mirrored_material(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _prove_controller_bridge_shared_mount(
        journal=journal,
        image=target_image,
        purpose="target-writer-start",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )

    exists, patched_statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not exists:
        raise RuntimeError("Controller bridge StatefulSet disappeared before target restart.")
    patched_metadata = _mapping(patched_statefulset.get("metadata"))
    patched_uid = str(patched_metadata.get("uid", "") or "")
    source_writer_uid = str(
        _mapping(_mapping(journal.get("authority")).get("writer_scale")).get("statefulset_uid", "")
        or ""
    )
    patched_template = _mapping(
        _mapping(_mapping(patched_statefulset.get("spec")).get("template")).get("spec")
    )
    patched_target_container = next(
        (
            item
            for item in _sequence_of_mappings(patched_template.get("containers"))
            if item.get("name") == container_name
        ),
        {},
    )
    patched_annotations = _mapping(
        _mapping(_mapping(patched_statefulset.get("spec")).get("template")).get("metadata")
    ).get("annotations")
    if (
        not patched_uid
        or patched_uid != source_writer_uid
        or str(patched_target_container.get("image", "") or "") != target_image
        or str(_mapping(patched_annotations).get("nebius.ai/cxcli-target-config-sha256", "") or "")
        != target_config_sha256
    ):
        raise RuntimeError(
            "recovery-required: target-version bridge workload UID, image, or configuration "
            "binding changed before writer start."
        )
    target_replicas = _resource_replicas(patched_statefulset, default=-1)
    if target_replicas not in {0, 2}:
        raise RuntimeError(
            f"Target-version bridge writer replicas drifted outside 0 or 2: {target_replicas}."
        )
    target_replicas = _ensure_controller_bridge_target_jailed_config(
        journal=journal,
        statefulset=patched_statefulset,
        target_replicas=target_replicas,
        container_name=container_name,
        config_map_name=bridge_config_names[0],
        config_key=slurm_config_key,
        target_config_sha256=target_config_sha256,
        target_image=target_image,
        target_write_already_accepted=target_write_already_accepted,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    if target_write_already_accepted:
        transition["target_config_sha256"] = target_config_sha256
        if target_config_binding_recovery is not None:
            target_config_binding_recovery.update(
                {
                    "status": "verified",
                    "verified_at": _utc_now(),
                }
            )
            transition["target_config_binding_recovery"] = target_config_binding_recovery
        if checkpoint_writer is not None:
            checkpoint_writer()
    target_scale_key = (
        "target_writer_restart"
        if target_write_already_accepted and target_replicas == 0
        else "target_writer_scale"
    )
    target_scale = transition.get(target_scale_key)
    if not isinstance(target_scale, dict):
        target_scale = {}
        transition[target_scale_key] = target_scale
    recorded_target_uid = str(target_scale.get("statefulset_uid", "") or "")
    if recorded_target_uid and recorded_target_uid != patched_uid:
        raise RuntimeError(
            "recovery-required: target-version writer scale StatefulSet UID changed."
        )
    target_scale.setdefault("statefulset_uid", patched_uid)
    target_scale.setdefault("from_replicas", 0)
    target_scale.setdefault("to_replicas", 2)
    authority = _mapping(journal.get("authority"))
    current_owner = str(authority.get("owner", "") or "")
    current_epoch = str(authority.get("epoch", "") or "")
    if current_owner not in {"bridge-source", "bridge-target"}:
        raise RuntimeError(
            "recovery-required: target-version bridge restart found unexpected authority "
            f"owner {current_owner or '<missing>'}."
        )
    target_runtime_targets: tuple[ControllerFenceTarget, ...] = ()
    target_pre_authority_census: list[dict[str, Any]] = []
    pre_stop_runtime_census = _sequence_of_mappings(transition.get("pre_stop_runtime_census"))
    if target_replicas == 0:
        if not pre_stop_runtime_census:
            raise RuntimeError(
                "recovery-required: target-version bridge start lacks the checkpointed "
                "pre-stop all-node runtime census."
            )
        target_runtime_targets = _controller_fence_targets_from_identities(
            _sequence_of_mappings(journal.get("controller_roles")),
            state_markers=(
                str(
                    _mapping(journal.get("state_precopy")).get("source_state_save_location", "")
                    or ""
                ),
                "/mnt/controller-spool/current",
            ),
            boundary="target-version bridge pre-authority",
        )
        _prove_controller_runtime_fence(
            journal=journal,
            boundary="target-version-bridge-pre-authority",
            targets=target_runtime_targets,
            image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="target-version bridge immediate pre-authority runtime fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        target_pre_authority_census = pre_stop_runtime_census
    _transition_controller_authority_lease(
        journal=journal,
        from_epoch=(current_epoch if current_owner == "bridge-source" else target_epoch),
        from_owner=current_owner,
        to_epoch=target_epoch,
        to_owner="bridge-target",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        runtime_node_census=target_pre_authority_census,
    )
    if (
        target_replicas == 2
        and not target_write_already_accepted
        and not str(target_scale.get("dispatching_at", "") or "")
    ):
        raise RuntimeError(
            "recovery-required: target-version bridge has live writers without a durable "
            "0 to 2 scale intent."
        )
    if target_replicas == 0:
        target_scale.update(
            {
                "state": "dispatching",
                "dispatching_at": _utc_now(),
                "resource_version": str(patched_metadata.get("resourceVersion", "") or ""),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _prove_controller_runtime_fence(
            journal=journal,
            boundary="target-version-bridge-pre-writer-scale",
            targets=target_runtime_targets,
            image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        _prove_cluster_wide_slurmctld_absence(
            proof_label="target-version bridge immediate pre-scale runtime fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=False,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_runtime_census_nodes(
            node_census=pre_stop_runtime_census,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        try:
            _kubectl_scale_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                resource="statefulset/cxcli-slurm-controller-bridge",
                replicas=2,
                current_replicas=0,
                resource_version=str(patched_metadata.get("resourceVersion", "") or ""),
            )
            target_replicas = 2
        except (Exception, KeyboardInterrupt):
            scale_exists, scale_observation = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                resource="statefulset/cxcli-slurm-controller-bridge",
            )
            scale_metadata = _mapping(scale_observation.get("metadata"))
            if not scale_exists or str(scale_metadata.get("uid", "") or "") != patched_uid:
                raise RuntimeError(
                    "recovery-required: target-version writer scale outcome is indeterminate "
                    "and the exact StatefulSet cannot be revalidated."
                ) from None
            target_replicas = _resource_replicas(scale_observation, default=-1)
            if target_replicas == 0:
                target_scale.update(
                    {
                        "state": "rejected",
                        "rejected_at": _utc_now(),
                        "target_write_observed": target_write_already_accepted,
                    }
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise
            if target_replicas != 2:
                raise RuntimeError(
                    "recovery-required: target-version writer scale outcome is outside "
                    f"exact 0 or 2 replicas: {target_replicas}."
                ) from None
    if target_replicas == 2:
        target_scale.update(
            {
                "state": "accepted",
                "accepted_at": str(target_scale.get("accepted_at", "") or "") or _utc_now(),
            }
        )
        if not target_write_already_accepted:
            record_bridge_authority(
                journal,
                epoch=target_epoch,
                owner="bridge-target",
                reason=("target-version bridge writer scale accepted for shared controller state"),
            )
            transition.update(
                {
                    "target_write_at": _utc_now(),
                    "downgrade_prohibited": True,
                }
            )
            target_write_already_accepted = True
        if checkpoint_writer is not None:
            checkpoint_writer()
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "rollout",
            "status",
            "statefulset/cxcli-slurm-controller-bridge",
            "--timeout=15m",
        ],
        timeout_seconds=960,
    )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    expected_digest = target_image.rsplit("@sha256:", 1)[-1]
    if (
        len(pods) != 2
        or len({str(_mapping(pod.get("spec")).get("nodeName", "") or "") for pod in pods}) != 2
    ):
        raise SoperatorMigrationPhasePending(
            "target-version bridge did not create two controllers on distinct nodes."
        )
    for pod in pods:
        status = next(
            (
                item
                for item in _sequence_of_mappings(
                    _mapping(pod.get("status")).get("containerStatuses")
                )
                if item.get("name") == container_name
            ),
            {},
        )
        if expected_digest not in str(status.get("imageID", "") or ""):
            raise SoperatorMigrationPhasePending(
                "target-version bridge Pod is not running the locked OCI platform digest."
            )
    first_pod = str(_mapping(pods[0].get("metadata")).get("name", "") or "")
    ping = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            first_pod,
            "-c",
            container_name,
            "--",
            "scontrol",
            "ping",
        ],
        check=False,
        timeout_seconds=120,
    )
    role_matches = re.findall(
        r"Slurmctld\((primary|backup)\)\s+at\s+([^\s]+)\s+is\s+UP",
        ping.stdout,
        flags=re.IGNORECASE,
    )
    if ping.returncode != 0 or sorted(role.lower() for role, _host in role_matches) != [
        "backup",
        "primary",
    ]:
        raise SoperatorMigrationPhasePending(
            "target-version bridge did not prove one primary and one backup slurmctld."
        )
    cold_job_lines = _verify_controller_bridge_cold_job_census(
        checkpoint=checkpoint,
        transition=transition,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    pod_by_name = {str(_mapping(pod.get("metadata")).get("name", "") or ""): pod for pod in pods}
    expected_node_group_ids = {
        str(item.get("id", "") or "") for item in _sequence_of_mappings(journal.get("node_groups"))
    }
    controller_roles: list[dict[str, Any]] = []
    for role, host in role_matches:
        pod_name = next((name for name in pod_by_name if host.startswith(name)), "")
        pod = pod_by_name.get(pod_name, {})
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        node_group_id = str(
            _mapping(node_metadata.get("labels")).get("nebius.com/node-group-id", "") or ""
        )
        node_labels = _mapping(node_metadata.get("labels"))
        if node_group_id not in expected_node_group_ids:
            raise SoperatorMigrationPhasePending(
                f"target-version bridge Pod {pod_name} is outside the journaled node groups."
            )
        expected_domain = next(
            (
                _mapping(item.get("scheduling_failure_domain"))
                for item in _sequence_of_mappings(journal.get("node_groups"))
                if str(item.get("id", "") or "") == node_group_id
            ),
            {},
        )
        topology_key = str(_mapping(expected_domain).get("topology_key", "") or "")
        topology_value = str(_mapping(expected_domain).get("topology_value", "") or "")
        if (
            topology_key != "nebius.com/node-group-id"
            or not topology_value
            or str(node_labels.get(topology_key, "") or "") != topology_value
        ):
            raise SoperatorMigrationPhasePending(
                f"target-version bridge Pod {pod_name} lost its scheduling domain."
            )
        controller_roles.append(
            {
                "pod_name": pod_name,
                "pod_uid": str(_mapping(pod.get("metadata")).get("uid", "") or ""),
                "node_name": node_name,
                "node_uid": str(node_metadata.get("uid", "") or ""),
                "node_group_id": node_group_id,
                "failure_domain": topology_value,
                "host": host,
                "role": "active" if role.lower() == "primary" else "standby",
                "image": target_image,
                "configuration_fingerprint": transition["target_config_sha256"],
                "observed_at": _utc_now(),
            }
        )
    if len({item["failure_domain"] for item in controller_roles}) != 2:
        raise SoperatorMigrationPhasePending(
            "target-version bridge controllers are not on distinct immutable "
            "node-group scheduling domains."
        )
    journal["controller_roles"] = controller_roles
    if checkpoint_writer is not None:
        checkpoint_writer()
    _prove_journaled_controller_bridge_exclusivity(
        journal=journal,
        proof_label="target-version controller bridge activation",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    preservation_lines = _verify_controller_bridge_preservation_jobs(
        checkpoint=checkpoint,
        journal=journal,
        proof_stage="target-version-bridge-active",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    advance_bridge_stage(journal, BridgeStage.TARGET_HA_ACTIVE)
    set_slurm_action_broker_mode(action_journal, "dispatch-enabled")
    journal["action_broker_mode"] = "dispatch-enabled"
    if checkpoint_writer is not None:
        checkpoint_writer()
    _drain_external_upgrade_slurm_action_journal(
        journal=action_journal,
        command_runner=command_runner,
        kube_context=kube_context,
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
        checkpoint_writer=checkpoint_writer,
    )
    return (
        [
            "Controller bridge upgraded together to the exact target Slurm image: "
            "state backup fsynced, downgrade prohibited, one active and one standby verified."
        ]
        + cold_job_lines
        + preservation_lines
    )


def _patch_slurm_config_map_text(
    *,
    namespace: str,
    name: str,
    config_key: str,
    slurm_conf: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    config_map = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "configmap",
            name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    data = copy.deepcopy(dict(_mapping(config_map.get("data"))))
    current = data.get(config_key)
    if not isinstance(current, str) or not re.search(
        r"(?im)^\s*ClusterName\s*=\s*\S+\s*$", current
    ):
        raise SoperatorMigrationPhasePending(
            f"Slurm ConfigMap {namespace}/{name} lost its exact journaled key {config_key}."
        )
    data[config_key] = slurm_conf
    _kubectl_patch_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource=f"configmap/{name}",
        patch={"data": data},
        patch_via_stdin=True,
    )


def _controller_config_with_state_save_location(
    slurm_conf: str,
    *,
    state_save_location: str,
) -> str:
    if not state_save_location.startswith("/"):
        raise RuntimeError("Controller StateSaveLocation must be an absolute path.")
    rendered, count = re.subn(
        r"(?im)^\s*StateSaveLocation\s*=\s*\S+\s*$",
        f"StateSaveLocation={state_save_location}",
        slurm_conf,
    )
    if count != 1:
        raise RuntimeError("Controller configuration must contain exactly one StateSaveLocation.")
    return rendered


def _ungate_in_place_target_controller_for_takeover(
    *,
    takeover: dict[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Remove the target writer gate and restore its singleton replica."""

    ungate = takeover.setdefault("target_controller_ungate", {})
    if not isinstance(ungate, dict):
        raise RuntimeError("Target controller ungate journal must be mutable.")
    _remove_in_place_target_controller_command_gate(
        state=ungate,
        target_ref=target_ref,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    target = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"slurmcluster/{target_ref}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulsets.apps.kruise.io/controller",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    target_uid = str(_mapping(target.get("metadata")).get("uid", "") or "")
    workload_metadata = _mapping(workload.get("metadata"))
    workload_uid = str(workload_metadata.get("uid", "") or "")
    owner_uids = {
        str(owner.get("uid", "") or "")
        for owner in _sequence_of_mappings(workload_metadata.get("ownerReferences"))
        if owner.get("controller") is True
    }
    containers = _sequence_of_mappings(
        _mapping(_mapping(workload.get("spec")).get("template")).get("spec", {}).get("containers")
    )
    if (
        not target_uid
        or not workload_uid
        or owner_uids != {target_uid}
        or len(containers) != 1
        or str(containers[0].get("name", "") or "") != "slurmctld"
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton ungate could not bind the exact owned controller workload."
        )
    if _is_exact_target_controller_command_gate(containers[0]):
        resource_version = str(workload_metadata.get("resourceVersion", "") or "")
        if not resource_version:
            raise SoperatorMigrationPhasePending(
                "target singleton ungate lacks the controller workload resourceVersion."
            )
        patch = [
            {"op": "test", "path": "/metadata/uid", "value": workload_uid},
            {
                "op": "test",
                "path": "/metadata/resourceVersion",
                "value": resource_version,
            },
            {
                "op": "test",
                "path": "/spec/template/spec/containers/0/name",
                "value": "slurmctld",
            },
            {"op": "remove", "path": "/spec/template/spec/containers/0/command"},
            {"op": "remove", "path": "/spec/template/spec/containers/0/args"},
        ]
        ungate.update(
            {
                "status": "dispatching",
                "target_uid": target_uid,
                "workload_uid": workload_uid,
                "resource_version": resource_version,
                "intent_at": str(ungate.get("intent_at", "") or _utc_now()),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "patch",
                "statefulsets.apps.kruise.io/controller",
                "--type",
                "json",
                "-p",
                json.dumps(patch, sort_keys=True, separators=(",", ":")),
            ],
            timeout_seconds=120,
        )
        ungate.update({"status": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()

    workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulsets.apps.kruise.io/controller",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    workload_metadata = _mapping(workload.get("metadata"))
    live_workload_uid = str(workload_metadata.get("uid", "") or "")
    live_containers = _sequence_of_mappings(
        _mapping(_mapping(workload.get("spec")).get("template")).get("spec", {}).get("containers")
    )
    live_replicas = _resource_replicas(workload, default=-1)
    if (
        live_workload_uid != workload_uid
        or len(live_containers) != 1
        or str(live_containers[0].get("name", "") or "") != "slurmctld"
        or _is_exact_target_controller_command_gate(live_containers[0])
        or live_replicas not in {0, 1}
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton ungate lost the exact ungated controller workload binding."
        )
    scale = ungate.setdefault("singleton_scale", {})
    if not isinstance(scale, dict):
        raise RuntimeError("Target controller singleton scale journal must be mutable.")
    scale_state = str(scale.get("status", "") or "")
    if live_replicas == 0:
        if scale_state == "accepted":
            raise RuntimeError(
                "recovery-required: accepted target controller singleton scale regressed "
                "to replicas=0 while the manager remained paused."
            )
        resource_version = str(workload_metadata.get("resourceVersion", "") or "")
        if not resource_version:
            raise SoperatorMigrationPhasePending(
                "target controller singleton scale lacks the workload resourceVersion."
            )
        scale.update(
            {
                "status": "dispatching",
                "workload_uid": workload_uid,
                "resource_version": resource_version,
                "from_replicas": 0,
                "to_replicas": 1,
                "intent_at": str(scale.get("intent_at", "") or _utc_now()),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="statefulsets.apps.kruise.io/controller",
            replicas=1,
            current_replicas=0,
            resource_version=resource_version,
        )
        scale.update({"status": "accepted", "accepted_at": _utc_now()})
    else:
        scale.update(
            {
                "status": "verified",
                "workload_uid": workload_uid,
                "observed_replicas": 1,
                "verified_at": _utc_now(),
            }
        )
    ungate.update(
        {
            "status": "verified",
            "target_uid": target_uid,
            "workload_uid": workload_uid,
            "verified_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()


def _restart_target_version_bridge_after_failed_takeover(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    bridge_config_name: str,
    bridge_only_config: str,
    target_config_name: str,
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    namespace = str(journal.get("namespace", "") or "")
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    recovery_attempt = _positive_int(takeover.get("recovery_bridge_restart_count"), fallback=0) + 1
    target_exists, target_workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="statefulset.apps.kruise.io/controller",
    )
    target_stop_evidence: list[dict[str, str]] = []
    if target_exists:
        target_replicas = _resource_replicas(target_workload, default=-1)
        if target_replicas not in {0, 1}:
            raise RuntimeError(
                "Target takeover recovery refuses an unexpected controller replica count: "
                f"{target_replicas}. Fence the target controller before restarting the bridge."
            )
        if target_replicas == 1:
            target_pod_exists, target_pod = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                resource="pod/controller-0",
            )
            if not target_pod_exists:
                raise RuntimeError(
                    "recovery-required: target singleton replicas=1 but controller-0 has no "
                    "observable Pod identity; cxcli will not restart the bridge without a "
                    "runtime fence target."
                )
            target_pod_metadata = _mapping(target_pod.get("metadata"))
            target_pod_status = _mapping(target_pod.get("status"))
            target_node_name = str(_mapping(target_pod.get("spec")).get("nodeName", "") or "")
            target_node_uid = ""
            if target_node_name:
                target_node = _json_from_command(
                    command_runner,
                    [
                        "kubectl",
                        "--context",
                        kube_context,
                        "get",
                        "node",
                        target_node_name,
                        "-o",
                        "json",
                    ],
                    timeout_seconds=120,
                )
                target_node_uid = str(_mapping(target_node.get("metadata")).get("uid", "") or "")
                if not target_node_uid:
                    raise RuntimeError(
                        "recovery-required: target singleton node lacks an immutable UID."
                    )
                target_stop_evidence.append(
                    {
                        "pod_name": "controller-0",
                        "pod_uid": str(target_pod_metadata.get("uid", "") or ""),
                        "node_name": target_node_name,
                        "node_uid": target_node_uid,
                    }
                )
            elif str(target_pod_status.get("phase", "") or "") != "Pending":
                raise RuntimeError(
                    "recovery-required: target singleton Pod has no node identity but is not "
                    "provably unscheduled Pending."
                )
            takeover.update(
                {
                    "target_stop_attempt": recovery_attempt,
                    "target_stop_intent_at": _utc_now(),
                    "target_stop_pods": target_stop_evidence,
                    "target_stop_unscheduled_pending": not target_node_name,
                    "target_stop_unscheduled_pod_uid": (
                        str(target_pod_metadata.get("uid", "") or "")
                        if not target_node_name
                        else ""
                    ),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            target_metadata = _mapping(target_workload.get("metadata"))
            _kubectl_scale_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                resource="statefulset.apps.kruise.io/controller",
                replicas=0,
                current_replicas=1,
                resource_version=str(target_metadata.get("resourceVersion", "") or ""),
            )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "wait",
                "--for=delete",
                "pod/controller-0",
                "--timeout=10m",
            ],
            timeout_seconds=660,
        )
        target_pod_exists, _target_pod = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="pod/controller-0",
        )
        target_exists, target_workload = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="statefulset.apps.kruise.io/controller",
        )
        if (
            target_pod_exists
            or not target_exists
            or _resource_replicas(target_workload, default=-1) != 0
        ):
            raise RuntimeError(
                "Target takeover recovery did not prove replicas=0 and controller-0 absent; "
                "the target-version bridge remains fenced to avoid split brain."
            )
        target_ungate = takeover.get("target_controller_ungate")
        if isinstance(target_ungate, dict):
            singleton_scale = target_ungate.get("singleton_scale")
            if isinstance(singleton_scale, dict) and singleton_scale.get("status") == "accepted":
                singleton_scale.update(
                    {
                        "status": "fenced",
                        "fenced_at": _utc_now(),
                        "recovery_attempt": recovery_attempt,
                    }
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
    if (
        not target_stop_evidence
        and _positive_int(takeover.get("target_stop_attempt"), fallback=0) == recovery_attempt
    ):
        target_stop_evidence = [
            {
                "pod_name": str(item.get("pod_name", "") or ""),
                "pod_uid": str(item.get("pod_uid", "") or ""),
                "node_name": str(item.get("node_name", "") or ""),
                "node_uid": str(item.get("node_uid", "") or ""),
            }
            for item in _sequence_of_mappings(takeover.get("target_stop_pods"))
        ]
    unscheduled_pending_proof = (
        _positive_int(takeover.get("target_stop_attempt"), fallback=0) == recovery_attempt
        and takeover.get("target_stop_unscheduled_pending") is True
        and bool(str(takeover.get("target_stop_unscheduled_pod_uid", "") or ""))
    )
    target_start = _mapping(takeover.get("target_start"))
    if (
        not target_stop_evidence
        and not unscheduled_pending_proof
        and str(target_start.get("state", "") or "") in {"dispatching", "accepted"}
    ):
        raise RuntimeError(
            "recovery-required: target singleton start was dispatched but cxcli has neither "
            "an exact historical node for runtime fencing nor an exact unscheduled Pending "
            "Pod proof; the bridge remains fenced."
        )
    state_path = str(
        _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
    )
    target_image = str(_mapping(journal.get("version_transition")).get("target_image", "") or "")
    if target_stop_evidence:
        if not state_path.startswith("/") or any(
            not item[required]
            for item in target_stop_evidence
            for required in ("pod_name", "pod_uid", "node_name", "node_uid")
        ):
            raise RuntimeError(
                "recovery-required: target singleton runtime-fence identity is incomplete."
            )
        takeover["target_runtime_fence"] = _prove_controller_runtime_fence(
            journal=journal,
            boundary=f"failed-target-singleton-takeover-{recovery_attempt}",
            targets=tuple(
                ControllerFenceTarget(
                    node_name=item["node_name"],
                    node_uid=item["node_uid"],
                    state_markers=(state_path, "/mnt/controller-spool/current"),
                )
                for item in target_stop_evidence
            ),
            image=str(_mapping(journal.get("version_transition")).get("target_image", "") or ""),
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        takeover["jwt_material_proof"] = {}
        takeover["controller_pod_uid"] = ""
        takeover["controller_workload_uid"] = ""
        takeover["jwt_material_proof_cleared_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not bridge_exists:
        raise RuntimeError("Target takeover failed and the target-version bridge is missing.")
    bridge_replicas = _resource_replicas(bridge_workload, default=-1)
    if bridge_replicas not in {0, 2}:
        raise RuntimeError(
            "Target takeover recovery refuses a partially scaled bridge workload: "
            f"replicas={bridge_replicas}."
        )
    if (
        bridge_replicas == 2
        and _non_negative_int(
            _mapping(bridge_workload.get("status")).get("readyReplicas"), fallback=0
        )
        != 2
    ):
        bridge_pods_payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pods",
                "-l",
                f"{CONTROLLER_BRIDGE_LABEL}=true",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        bridge_pods = _sequence_of_mappings(bridge_pods_payload.get("items"))
        bridge_pod_identities = [
            {
                "pod_name": str(_mapping(pod.get("metadata")).get("name", "") or ""),
                "pod_uid": str(_mapping(pod.get("metadata")).get("uid", "") or ""),
                "node_name": str(_mapping(pod.get("spec")).get("nodeName", "") or ""),
            }
            for pod in bridge_pods
        ]
        if len(bridge_pod_identities) != 2 or any(
            not identity["pod_name"] or not identity["pod_uid"]
            for identity in bridge_pod_identities
        ):
            raise RuntimeError(
                "recovery-required: unhealthy target-version bridge recovery lacks both "
                "immutable Pod identities."
            )
        recovery_scale_down = takeover.setdefault("recovery_bridge_scale_down", {})
        if not isinstance(recovery_scale_down, dict):
            raise RuntimeError("Target takeover recovery scale-down journal must be mutable.")
        recovery_scale_down.update(
            {
                "schema": "nebius-cxcli/target-takeover-recovery-bridge-scale-down-v1",
                "state": "dispatching",
                "attempt": recovery_attempt,
                "intent_at": str(recovery_scale_down.get("intent_at") or _utc_now()),
                "pods": bridge_pod_identities,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        bridge_metadata = _mapping(bridge_workload.get("metadata"))
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=0,
            current_replicas=2,
            resource_version=str(bridge_metadata.get("resourceVersion", "") or ""),
        )
        for identity in bridge_pod_identities:
            command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    namespace,
                    "wait",
                    "--for=delete",
                    f"pod/{identity['pod_name']}",
                    "--timeout=10m",
                ],
                timeout_seconds=660,
            )
        bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
        )
        if not bridge_exists or _resource_replicas(bridge_workload, default=-1) != 0:
            raise RuntimeError(
                "recovery-required: unhealthy target-version bridge did not reach replicas=0."
            )
        recovery_scale_down.update({"state": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        bridge_replicas = 0
    bridge_roles = _sequence_of_mappings(journal.get("controller_roles"))
    if len(bridge_roles) != 2:
        raise RuntimeError(
            "recovery-required: target takeover recovery lacks both historical bridge nodes."
        )
    stopped_writer_identities = (*bridge_roles, *target_stop_evidence)
    stopped_writer_targets = _controller_fence_targets_from_identities(
        stopped_writer_identities,
        state_markers=(state_path, "/mnt/controller-spool/current"),
        boundary="failed target takeover recovery",
    )
    recovery_pre_authority_census: list[dict[str, Any]] = []
    if bridge_replicas == 0:
        takeover["recovery_pre_authority_runtime_fence"] = _prove_controller_runtime_fence(
            journal=journal,
            boundary="failed-target-takeover-recovery-pre-authority",
            targets=stopped_writer_targets,
            image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        recovery_pre_authority_census = _prove_cluster_wide_slurmctld_absence(
            proof_label="failed target singleton takeover immediate pre-authority fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    authority = _mapping(journal.get("authority"))
    target_epoch = _controller_bridge_epoch(journal, "target")
    bridge_epoch = str(takeover.get("bridge_authority_epoch", "") or "")
    authority_owner = str(authority.get("owner", "") or "")
    authority_epoch = str(authority.get("epoch", "") or "")
    if not bridge_epoch:
        raise RuntimeError(
            "recovery-required: failed target takeover lost its target/bridge authority binding."
        )
    if authority_owner == "target-singleton" and authority_epoch == target_epoch:
        _transition_controller_authority_lease(
            journal=journal,
            from_epoch=target_epoch,
            from_owner="target-singleton",
            to_epoch=bridge_epoch,
            to_owner="bridge-target",
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            runtime_node_census=recovery_pre_authority_census,
        )
        record_bridge_authority(
            journal,
            epoch=bridge_epoch,
            owner="bridge-target",
            reason="failed target singleton fenced before target-version bridge recovery",
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif authority_owner == "bridge-target" and authority_epoch == bridge_epoch:
        _revalidate_controller_authority_lease(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    else:
        raise RuntimeError(
            "recovery-required: failed target takeover found an unexpected controller authority."
        )
    _patch_slurm_config_map_text(
        namespace=namespace,
        name=bridge_config_name,
        config_key=str(_mapping(journal.get("source_configuration")).get("config_key", "") or ""),
        slurm_conf=bridge_only_config,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    # The target sconfigcontroller owns the jailed client configuration. Restore
    # its source ConfigMap to the live bridge-only topology before restarting
    # bridge writers; otherwise it can overwrite the staged recovery file with
    # the failed singleton topology after the bridge is already healthy.
    _patch_slurm_config_map_text(
        namespace=_SOPERATOR_NAMESPACE,
        name=target_config_name,
        config_key=str(_mapping(journal.get("source_configuration")).get("config_key", "") or ""),
        slurm_conf=bridge_only_config,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    if bridge_replicas == 0:
        bridge_only_sha256 = hashlib.sha256(bridge_only_config.encode("utf-8")).hexdigest()
        mount_proof = _prove_controller_bridge_shared_mount(
            journal=journal,
            image=target_image,
            purpose="takeover-recovery-writer-start",
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            observe_jailed_config=True,
        )
        observed_preimage = _mapping(mount_proof.get("jailed_config_observation"))
        observed_preimage_sha256 = str(observed_preimage.get("sha256", "") or "")
        recorded_observation = _mapping(takeover.get("recovery_jailed_config_preimage"))
        recorded_observation_sha256 = str(recorded_observation.get("sha256", "") or "")
        if recorded_observation_sha256 and observed_preimage_sha256 not in {
            recorded_observation_sha256,
            bridge_only_sha256,
        }:
            raise RuntimeError(
                "recovery-required: jailed slurm.conf changed after its post-fence recovery "
                "preimage was journaled."
            )
        if not recorded_observation_sha256:
            takeover["recovery_jailed_config_preimage"] = {
                **observed_preimage,
                "proven_after_target_runtime_fence": True,
                "target_start_pod_uid": str(target_start.get("pod_uid", "") or ""),
            }
            recorded_observation_sha256 = observed_preimage_sha256
            if checkpoint_writer is not None:
                checkpoint_writer()
        recovery_staging = takeover.get("recovery_bridge_jailed_config")
        if not isinstance(recovery_staging, dict):
            recovery_staging = {}
            takeover["recovery_bridge_jailed_config"] = recovery_staging
        recorded_staging_preimage = str(recovery_staging.get("expected_preimage_sha256", "") or "")
        recovery_preimage_sha256 = (
            recorded_staging_preimage
            if observed_preimage_sha256 == bridge_only_sha256 and recorded_staging_preimage
            else observed_preimage_sha256
        )
        if recorded_staging_preimage and recorded_staging_preimage != recovery_preimage_sha256:
            _reconcile_failed_recovery_jailed_config_stager(
                journal=journal,
                staging=recovery_staging,
                target_config_sha256=bridge_only_sha256,
                observed_preimage_sha256=recovery_preimage_sha256,
                target_image=target_image,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        _stage_controller_bridge_jailed_config(
            journal=journal,
            config_map_name=bridge_config_name,
            config_key=str(
                _mapping(journal.get("source_configuration")).get("config_key", "") or ""
            ),
            target_config_sha256=bridge_only_sha256,
            expected_preimage_sha256=recovery_preimage_sha256,
            target_image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            staging_owner=takeover,
            staging_key="recovery_bridge_jailed_config",
            pod_name_prefix="cxcli-controller-recovery-config-stager",
        )
        takeover["recovery_pre_scale_runtime_fence"] = _prove_controller_runtime_fence(
            journal=journal,
            boundary="failed-target-takeover-recovery-pre-writer-scale",
            targets=stopped_writer_targets,
            image=target_image,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            fresh_attempt=True,
        )
        recovery_pre_scale_census = _prove_cluster_wide_slurmctld_absence(
            proof_label="failed target takeover recovery immediate pre-scale fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_bridge_security_contract(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        _revalidate_controller_runtime_census_nodes(
            node_census=recovery_pre_scale_census,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        bridge_metadata = _mapping(bridge_workload.get("metadata"))
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=2,
            current_replicas=0,
            resource_version=str(bridge_metadata.get("resourceVersion", "") or ""),
        )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "rollout",
            "status",
            "statefulset/cxcli-slurm-controller-bridge",
            "--timeout=15m",
        ],
        timeout_seconds=960,
    )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    if len(pods) != 2:
        raise RuntimeError(
            "Target takeover recovery did not restore exactly two bridge controller Pods."
        )
    statefulset_exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    containers = _sequence_of_mappings(
        _mapping(_mapping(_mapping(statefulset.get("spec")).get("template")).get("spec")).get(
            "containers"
        )
    )
    container_name = next(
        (
            str(item.get("name", "") or "")
            for item in containers
            if "slurmctld" in str(item.get("name", "") or "").lower()
        ),
        "",
    )
    if not statefulset_exists or not container_name:
        raise RuntimeError("Recovered bridge lost its exact slurmctld workload binding.")
    first_pod = str(_mapping(pods[0].get("metadata")).get("name", "") or "")
    role_matches: tuple[tuple[str, str], ...] = ()
    for attempt in range(6):
        ping = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "exec",
                first_pod,
                "-c",
                container_name,
                "--",
                "scontrol",
                "ping",
            ],
            check=False,
            timeout_seconds=120,
        )
        role_matches = _controller_bridge_ping_up_roles(ping.stdout)
        if ping.returncode == 0 and sorted(role for role, _host in role_matches) == [
            "backup",
            "primary",
        ]:
            break
        if attempt < 5:
            time.sleep(5)
    else:
        raise RuntimeError(
            "Target takeover recovery did not prove one primary and one backup bridge controller."
        )
    pod_by_name = {str(_mapping(pod.get("metadata")).get("name", "") or ""): pod for pod in pods}
    roles: list[dict[str, Any]] = []
    for role, host in role_matches:
        pod_name = next((name for name in pod_by_name if host.startswith(name)), "")
        pod = pod_by_name.get(pod_name, {})
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        roles.append(
            {
                "pod_name": pod_name,
                "pod_uid": str(_mapping(pod.get("metadata")).get("uid", "") or ""),
                "node_name": node_name,
                "node_uid": str(node_metadata.get("uid", "") or ""),
                "node_group_id": str(
                    _mapping(node_metadata.get("labels")).get("nebius.com/node-group-id", "") or ""
                ),
                "host": host,
                "role": "active" if role.lower() == "primary" else "standby",
                "image": str(
                    _mapping(journal.get("version_transition")).get("target_image", "") or ""
                ),
                "configuration_fingerprint": hashlib.sha256(
                    bridge_only_config.encode("utf-8")
                ).hexdigest(),
                "observed_at": _utc_now(),
            }
        )
    expected_group_ids = {
        str(item.get("id", "") or "") for item in _sequence_of_mappings(journal.get("node_groups"))
    }
    if {item["node_group_id"] for item in roles} != expected_group_ids or len(
        {item["node_uid"] for item in roles}
    ) != 2:
        raise RuntimeError(
            "Target takeover recovery bridge is not bound to the two exact journaled nodes."
        )
    journal["controller_roles"] = roles
    _prove_journaled_controller_bridge_exclusivity(
        journal=journal,
        proof_label="target takeover recovery bridge",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _prove_controller_bridge_client_configuration(
        journal=journal,
        proof_owner=takeover,
        proof_key="recovery_client_propagation",
        proof_stage="after-failed-target-takeover",
        expected_contract=_controller_bridge_client_config_contract(bridge_only_config),
        expected_cluster_name=target_ref,
        required_hosts=CONTROLLER_BRIDGE_CONTROLLER_HOSTS,
        target_ref=target_ref,
        source_clients=False,
        require_raised_timeouts=False,
        require_live_rpc=True,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "dispatch-enabled")
    journal["action_broker_mode"] = "dispatch-enabled"
    takeover["recovery_bridge_restart_count"] = recovery_attempt
    takeover["last_recovery_bridge_restart_at"] = _utc_now()
    takeover["recovery_bridge_active"] = True
    if checkpoint_writer is not None:
        checkpoint_writer()
    _drain_external_upgrade_slurm_action_journal(
        journal=action_journal,
        command_runner=command_runner,
        kube_context=kube_context,
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
        checkpoint_writer=checkpoint_writer,
    )


def _complete_target_singleton_final_config(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    takeover: dict[str, Any],
    target_config_name: str,
    handoff_config: str,
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if BridgeStage(str(journal.get("stage", "") or "")) is not BridgeStage.TARGET_SINGLETON_ACTIVE:
        raise SoperatorMigrationPhasePending(
            "final singleton configuration requires a durably proven target singleton."
        )
    _kubectl_wait(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="pod/controller-0",
        condition="Ready",
        timeout="15m",
        timeout_seconds=960,
    )
    target_pod = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod/controller-0",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    target_pod_metadata = _mapping(target_pod.get("metadata"))
    target_pod_uid = str(target_pod_metadata.get("uid", "") or "")
    checkpointed_pod_uid = str(takeover.get("controller_pod_uid", "") or "")
    if not target_pod_uid or (checkpointed_pod_uid and target_pod_uid != checkpointed_pod_uid):
        raise SoperatorMigrationPhasePending(
            "target singleton Pod identity changed before final one-host configuration."
        )
    containers = _sequence_of_mappings(_mapping(target_pod.get("spec")).get("containers"))
    container_name = next(
        (
            str(item.get("name", "") or "")
            for item in containers
            if "slurmctld" in str(item.get("name", "") or "").lower()
        ),
        "",
    )
    if not container_name:
        raise SoperatorMigrationPhasePending(
            "target singleton finalization found no exact slurmctld container."
        )
    expected_image = str(_mapping(journal.get("version_transition")).get("target_image", "") or "")
    accepted_image_digests = _locked_target_runtime_image_digests(
        journal,
        expected_image=expected_image,
    )
    container_status = next(
        (
            item
            for item in _sequence_of_mappings(
                _mapping(target_pod.get("status")).get("containerStatuses")
            )
            if item.get("name") == container_name
        ),
        {},
    )
    if (
        _runtime_image_digest(str(container_status.get("imageID", "") or ""))
        not in accepted_image_digests
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton finalization observed a different locked OCI index or "
            "platform digest."
        )
    workload_exists, workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="statefulset.apps.kruise.io/controller",
    )
    if not workload_exists or _resource_replicas(workload, default=-1) != 1:
        raise SoperatorMigrationPhasePending(
            "target singleton finalization requires the supported controller replicas=1."
        )

    target_state_path = str(takeover.get("target_state_save_location", "") or "")
    if not target_state_path.startswith("/"):
        raise SoperatorMigrationPhasePending(
            "target singleton finalization lacks its absolute target StateSaveLocation."
        )
    final_singleton_host = f"controller-0({target_ref}-controller-svc)"
    final_config = _restore_controller_gap_timeouts(
        final_singleton_controller_config(
            handoff_config,
            target_host=final_singleton_host,
        ),
        _mapping(_mapping(journal.get("source_configuration")).get("original_timeouts")),
    )
    _patch_slurm_config_map_text(
        namespace=_SOPERATOR_NAMESPACE,
        name=target_config_name,
        config_key=str(_mapping(journal.get("source_configuration")).get("config_key", "") or ""),
        slurm_conf=final_config,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    reconfigure = _kubectl_exec_slurm_controller(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "reconfigure"),
        timeout_seconds=120,
    )
    if reconfigure.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "target singleton is active, but final one-host Slurm reconfigure failed."
        )
    proof = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            "controller-0",
            "-c",
            container_name,
            "--",
            "/bin/sh",
            "-ec",
            (
                f"export SLURM_CONF={shlex.quote(_SOPERATOR_LEGACY_SLURM_CONF)}; "
                'test "$(pgrep -x slurmctld | wc -l)" -eq 1; '
                "scontrol ping; scontrol show config; scontrol show jobs -o"
            ),
        ],
        check=False,
        timeout_seconds=180,
    )
    state_path_match = re.search(r"(?im)^\s*StateSaveLocation\s*=\s*(\S+)\s*$", proof.stdout)
    if (
        proof.returncode != 0
        or not _controller_ping_proves_only_live_host(
            proof.stdout,
            expected_host="controller-0",
        )
        or not state_path_match
        or state_path_match.group(1) != target_state_path
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton finalization did not prove one primary on the promoted shared state."
        )
    final_live = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "configmap",
            target_config_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    final_data = _mapping(final_live.get("data"))
    config_key = str(_mapping(journal.get("source_configuration")).get("config_key", "") or "")
    final_text = str(final_data.get(config_key, "") or "")
    if not config_key or not re.search(r"(?im)^\s*ClusterName\s*=\s*\S+\s*$", final_text):
        raise SoperatorMigrationPhasePending(
            "target singleton final ConfigMap lost its exact journaled slurm.conf entry."
        )
    host_values = re.findall(r"(?im)^\s*SlurmctldHost\s*=\s*(\S+)\s*$", final_text)
    if host_values != [final_singleton_host]:
        raise SoperatorMigrationPhasePending(
            "target singleton final Slurm configuration does not contain exactly one host."
        )
    client_lines = _prove_controller_bridge_client_configuration(
        journal=journal,
        proof_owner=takeover,
        proof_key="final_client_propagation",
        proof_stage="final-target-singleton",
        expected_contract=_controller_bridge_client_config_contract(final_text),
        expected_cluster_name=target_ref,
        required_hosts=(final_singleton_host,),
        target_ref=target_ref,
        source_clients=False,
        require_raised_timeouts=False,
        require_live_rpc=True,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    takeover.update(
        {
            "controller_pod_uid": target_pod_uid,
            "controller_workload_uid": str(_mapping(workload.get("metadata")).get("uid", "") or ""),
            "final_config_map_name": target_config_name,
            "state_loaded": True,
            "state_observation_sha256": hashlib.sha256(proof.stdout.encode("utf-8")).hexdigest(),
            "only_primary_proven": True,
            "final_slurmctld_host_count": 1,
            "final_config_sha256": hashlib.sha256(final_text.encode("utf-8")).hexdigest(),
        }
    )
    _revalidate_target_singleton_jwt_material(
        journal=journal,
        target_ref=target_ref,
        target_pod=target_pod,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    _prove_journaled_target_singleton_exclusivity(
        journal=journal,
        proof_label="target singleton handoff",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    preservation_lines = _verify_controller_bridge_preservation_jobs(
        checkpoint=checkpoint,
        journal=journal,
        proof_stage="target-singleton-active",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    advance_bridge_stage(journal, BridgeStage.HANDOFF_VALIDATED)
    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "dispatch-enabled")
    journal["action_broker_mode"] = "dispatch-enabled"
    if checkpoint_writer is not None:
        checkpoint_writer()
    _drain_external_upgrade_slurm_action_journal(
        journal=action_journal,
        command_runner=command_runner,
        kube_context=kube_context,
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
        checkpoint_writer=checkpoint_writer,
    )
    return (
        client_lines
        + [
            "Controller authority transferred to supported target controller-0: bridge fenced, "
            "shared state loaded, one primary and one SlurmctldHost verified, replicas=1."
        ]
        + preservation_lines
    )


def _fence_target_version_bridge_for_takeover(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    stage = BridgeStage(str(journal.get("stage", "") or ""))
    if stage not in {BridgeStage.TARGET_HA_ACTIVE, BridgeStage.BRIDGE_FENCED}:
        raise SoperatorMigrationPhasePending(
            "target takeover bridge fence requires target-version HA or a checkpointed "
            f"bridge fence; current stage={stage.value}."
        )
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    client_proof = _mapping(takeover.get("client_handoff_propagation"))
    deferred_client_proof = _target_takeover_client_proof_is_deferred(
        stage=stage,
        takeover=takeover,
    )
    if (
        client_proof.get("status") != "verified"
        or client_proof.get("live_rpc_verified") is not True
        or client_proof.get("proof_stage") != "before-target-takeover"
    ) and not deferred_client_proof:
        raise SoperatorMigrationPhasePending(
            "target bridge fencing requires the durable target login/worker handoff "
            "configuration and direct RPC propagation proof."
        )
    namespace = str(journal.get("namespace", "") or "")
    bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not bridge_exists:
        raise RuntimeError("Controller bridge workload disappeared before target takeover.")
    replicas = _resource_replicas(bridge_workload, default=-1)
    if replicas not in {0, 2}:
        raise RuntimeError(
            f"Controller bridge workload drifted outside the exact 2 -> 0 fence: {replicas}."
        )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    if replicas == 2 and len(pods) != 2:
        raise SoperatorMigrationPhasePending(
            "target takeover requires exactly two live bridge Pods before fencing."
        )
    attempt = _positive_int(takeover.get("bridge_stop_attempt"), fallback=0) + 1
    stop_evidence: list[dict[str, str]] = []
    for pod in pods:
        pod_metadata = _mapping(pod.get("metadata"))
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        stop_evidence.append(
            {
                "pod_name": str(pod_metadata.get("name", "") or ""),
                "pod_uid": str(pod_metadata.get("uid", "") or ""),
                "node_name": node_name,
                "node_uid": str(node_metadata.get("uid", "") or ""),
            }
        )
    if not stop_evidence:
        stop_evidence = [
            {
                "pod_name": str(item.get("pod_name", "") or ""),
                "pod_uid": str(item.get("pod_uid", "") or ""),
                "node_name": str(item.get("node_name", "") or ""),
                "node_uid": str(item.get("node_uid", "") or ""),
            }
            for item in _sequence_of_mappings(takeover.get("bridge_stop_pods"))
        ]
    if len(stop_evidence) != 2 or any(
        not item[required]
        for item in stop_evidence
        for required in ("pod_name", "pod_uid", "node_name", "node_uid")
    ):
        raise RuntimeError(
            "recovery-required: target takeover lacks the two exact historical bridge "
            "Pod and node identities required for runtime fencing."
        )
    takeover.update(
        {
            "bridge_stop_attempt": attempt,
            "bridge_stop_intent_at": _utc_now(),
            "bridge_stop_pods": stop_evidence,
            "bridge_stop_expected_replicas": replicas,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    if replicas == 2:
        bridge_metadata = _mapping(bridge_workload.get("metadata"))
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            resource="statefulset/cxcli-slurm-controller-bridge",
            replicas=0,
            current_replicas=2,
            resource_version=str(bridge_metadata.get("resourceVersion", "") or ""),
        )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "wait",
            "--for=delete",
            "pod",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "--timeout=10m",
        ],
        timeout_seconds=660,
    )
    bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    remaining = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    if (
        not bridge_exists
        or _resource_replicas(bridge_workload, default=-1) != 0
        or _sequence_of_mappings(remaining.get("items"))
    ):
        raise SoperatorMigrationPhasePending(
            "target takeover did not prove bridge replicas=0 and all exact bridge Pods absent."
        )
    state_path = str(
        _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
    )
    if not state_path.startswith("/"):
        raise RuntimeError(
            "Target takeover runtime fence requires the exact mounted StateSaveLocation."
        )
    runtime_evidence = _prove_controller_runtime_fence(
        journal=journal,
        boundary=f"target-version-bridge-takeover-{attempt}",
        targets=tuple(
            ControllerFenceTarget(
                node_name=item["node_name"],
                node_uid=item["node_uid"],
                state_markers=(state_path, "/mnt/controller-spool/current"),
            )
            for item in stop_evidence
        ),
        image=str(_mapping(journal.get("version_transition")).get("target_image", "") or ""),
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        fresh_attempt=True,
    )
    authority = _mapping(journal.get("authority"))
    authority_owner = str(authority.get("owner", "") or "")
    authority_epoch = str(authority.get("epoch", "") or "")
    target_epoch = _controller_bridge_epoch(journal, "target")
    target_start_state = str(_mapping(takeover.get("target_start")).get("state", "") or "")
    authority_transferred = False
    if authority_owner == "bridge-target":
        takeover_pre_authority_census = _prove_cluster_wide_slurmctld_absence(
            proof_label="target-version bridge takeover runtime fence",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        recorded_bridge_epoch = str(takeover.get("bridge_authority_epoch", "") or "")
        if recorded_bridge_epoch and recorded_bridge_epoch != authority_epoch:
            raise RuntimeError("recovery-required: target takeover bridge authority epoch changed.")
        takeover["bridge_authority_epoch"] = authority_epoch
        if checkpoint_writer is not None:
            checkpoint_writer()
        _transition_controller_authority_lease(
            journal=journal,
            from_epoch=authority_epoch,
            from_owner="bridge-target",
            to_epoch=target_epoch,
            to_owner="target-singleton",
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            runtime_node_census=takeover_pre_authority_census,
        )
        authority_transferred = True
    elif authority_owner == "target-singleton" and authority_epoch == target_epoch:
        if stage is not BridgeStage.BRIDGE_FENCED:
            raise RuntimeError(
                "recovery-required: target authority was checkpointed before the bridge "
                "fence stage."
            )
        if target_start_state not in {"dispatching", "accepted"}:
            _prove_cluster_wide_slurmctld_absence(
                proof_label="checkpointed target authority before singleton dispatch",
                campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        _revalidate_controller_authority_lease(
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    else:
        raise RuntimeError(
            "recovery-required: target takeover found unexpected journaled controller "
            f"authority {authority_owner or '<missing>'}."
        )
    fencing = journal.get("fencing")
    if not isinstance(fencing, dict) or not isinstance(fencing.get("bridge"), dict):
        raise RuntimeError("Controller bridge fencing journal must be mutable.")
    prior_pod_uids = [
        str(item or "")
        for item in _mapping(fencing.get("bridge")).get("pod_uids", []) or []
        if str(item or "")
    ]
    stopped_pod_uids = [item["pod_uid"] for item in stop_evidence] or prior_pod_uids
    fencing["bridge"].update(
        {
            "proven": True,
            "pod_uids": stopped_pod_uids,
            "processes_absent": True,
            "writable_state_mounts_absent": True,
            "runtime_fence": runtime_evidence,
            "observed_at": _utc_now(),
            "attempt": attempt,
        }
    )
    takeover["recovery_bridge_active"] = False
    if stage is BridgeStage.TARGET_HA_ACTIVE:
        advance_bridge_stage(journal, BridgeStage.BRIDGE_FENCED)
    if authority_transferred:
        record_bridge_authority(
            journal,
            epoch=target_epoch,
            owner="target-singleton",
            reason="bridge runtime-fenced and authority Lease transferred before target start",
        )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return stopped_pod_uids


def _target_takeover_client_proof_requires_live_rpc(
    *,
    stage: BridgeStage,
    takeover: Mapping[str, Any],
) -> bool:
    return stage is BridgeStage.TARGET_HA_ACTIVE or takeover.get("recovery_bridge_active") is True


def _target_takeover_pod_was_runtime_fenced(
    takeover: Mapping[str, Any],
    *,
    pod_uid: str,
    node_name: str,
) -> bool:
    stopped = next(
        (
            item
            for item in _sequence_of_mappings(takeover.get("target_stop_pods"))
            if str(item.get("pod_uid", "") or "") == pod_uid
            and (not node_name or str(item.get("node_name", "") or "") == node_name)
        ),
        None,
    )
    if stopped is None:
        return False
    node_name = str(stopped.get("node_name", "") or "")
    stopped_node_uid = str(stopped.get("node_uid", "") or "")
    return bool(stopped_node_uid) and any(
        item.get("fenced") is True
        and bool(str(item.get("verified_at", "") or ""))
        and str(item.get("node_name", "") or "") == node_name
        and str(item.get("node_uid", "") or "") == stopped_node_uid
        for item in _sequence_of_mappings(takeover.get("target_runtime_fence"))
    )


def _controller_ping_proves_only_live_host(
    output: str,
    *,
    expected_host: str,
) -> bool:
    roles = re.findall(
        r"(?im)^\s*Slurmctld\(([^)]+)\)\s+at\s+(\S+)\s+is\s+(UP|DOWN)\s*$",
        output,
    )
    return bool(roles) and {host for _role, host, state in roles if state.upper() == "UP"} == {
        expected_host
    }


def _controller_bridge_ping_up_roles(output: str) -> tuple[tuple[str, str], ...]:
    """Normalize Slurm's backup, backup1, ... labels for one HA-role proof."""

    return tuple(
        ("primary" if role.lower() == "primary" else "backup", host)
        for role, host in re.findall(
            r"Slurmctld\((primary|backup(?:\d+)?)\)\s+at\s+([^\s]+)\s+is\s+UP",
            output,
            flags=re.IGNORECASE,
        )
    )


def _ensure_target_singleton_primary_takeover(
    *,
    journal: dict[str, Any],
    takeover: dict[str, Any],
    target_ref: str,
    target_pod: Mapping[str, Any],
    container_name: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Prove the canonical one-host target controller is active."""

    metadata = _mapping(target_pod.get("metadata"))
    pod_uid = str(metadata.get("uid", "") or "")
    node_name = str(_mapping(target_pod.get("spec")).get("nodeName", "") or "")
    authority = _mapping(journal.get("authority"))
    authority_epoch = str(authority.get("epoch", "") or "")
    if (
        not pod_uid
        or not node_name
        or not container_name
        or authority.get("owner") != "target-singleton"
        or authority_epoch != _controller_bridge_epoch(journal, "target")
    ):
        raise RuntimeError(
            "recovery-required: target primary takeover lacks its exact Pod, node, "
            "container, or controller-authority binding."
        )
    _revalidate_controller_authority_lease(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    operation = takeover.setdefault("target_primary_takeover", {})
    if not isinstance(operation, dict):
        raise RuntimeError("Target primary takeover journal must be mutable.")
    expected_binding = {
        "target_ref": target_ref,
        "pod_uid": pod_uid,
        "node_name": node_name,
        "container_name": container_name,
        "authority_epoch": authority_epoch,
        "controller_index": 0,
    }
    recorded_pod_uid = str(operation.get("pod_uid", "") or "")
    recorded_node_name = str(operation.get("node_name", "") or "")
    if recorded_pod_uid and recorded_pod_uid != pod_uid:
        if not _target_takeover_pod_was_runtime_fenced(
            takeover,
            pod_uid=recorded_pod_uid,
            node_name=recorded_node_name,
        ):
            raise RuntimeError(
                "recovery-required: target primary takeover Pod binding changed without "
                "an exact runtime-fence proof."
            )
        history = takeover.setdefault("target_primary_takeover_history", [])
        if not isinstance(history, list):
            raise RuntimeError("Target primary takeover history must be mutable.")
        if not any(
            str(_mapping(item).get("pod_uid", "") or "") == recorded_pod_uid for item in history
        ):
            history.append(dict(operation))
        operation.clear()
    for field, expected in expected_binding.items():
        recorded = operation.get(field)
        if recorded not in (None, "") and recorded != expected:
            raise RuntimeError(
                f"recovery-required: target primary takeover {field} binding changed."
            )
    operation.update(expected_binding)

    ping_command = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        _SOPERATOR_NAMESPACE,
        "exec",
        "controller-0",
        "-c",
        container_name,
        "--",
        "env",
        f"SLURM_CONF={_SOPERATOR_LEGACY_SLURM_CONF}",
        "scontrol",
        "ping",
    ]

    def _ping_roles() -> str:
        ping = command_runner(ping_command, check=False, timeout_seconds=120)
        if ping.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "target singleton primary takeover could not read the live controller roles."
            )
        if not _controller_ping_proves_only_live_host(
            ping.stdout,
            expected_host="controller-0",
        ):
            raise SoperatorMigrationPhasePending(
                "target singleton primary takeover requires controller-0 to be the only "
                "live controller before promotion."
            )
        return ping.stdout

    active_rpc_command = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        _SOPERATOR_NAMESPACE,
        "exec",
        "controller-0",
        "-c",
        container_name,
        "--",
        "/bin/sh",
        "-ec",
        (
            f"export SLURM_CONF={shlex.quote(_SOPERATOR_LEGACY_SLURM_CONF)}; "
            "scontrol show config; scontrol show jobs -o"
        ),
    ]

    if str(operation.get("status", "") or "") != "verifying":
        operation.update({"status": "verifying", "verifying_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()

    for attempt in range(15):
        ping_output = _ping_roles()
        active_rpc = command_runner(active_rpc_command, check=False, timeout_seconds=30)
        if active_rpc.returncode == 0:
            operation.update(
                {
                    "status": "verified",
                    "accepted_at": str(operation.get("accepted_at", "") or "") or _utc_now(),
                    "verified_at": _utc_now(),
                    "ping_sha256": hashlib.sha256(ping_output.encode("utf-8")).hexdigest(),
                    "active_rpc_sha256": hashlib.sha256(
                        active_rpc.stdout.encode("utf-8")
                    ).hexdigest(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return
        if attempt < 14:
            time.sleep(2)
    raise SoperatorMigrationPhasePending(
        "target singleton controller-0 did not become active before the bounded deadline."
    )


def _revalidate_target_singleton_image_digest(
    *,
    takeover: dict[str, Any],
    target_pod: Mapping[str, Any],
    container_name: str,
    expected_image: str,
    expected_image_lock: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    """Bind startup to one Pod UID and the locked platform-or-index digest."""

    pod_uid = str(_mapping(target_pod.get("metadata")).get("uid", "") or "")
    if not pod_uid or not container_name:
        raise RuntimeError(
            "recovery-required: target singleton image proof lacks an exact immutable "
            "platform/index lock, Pod UID, or container binding."
        )
    accepted_digests = _locked_target_runtime_image_digests(
        {"target_image_lock": expected_image_lock},
        expected_image=expected_image,
    )
    current_pod = dict(target_pod)
    proof = takeover.setdefault("target_image_proof", {})
    if not isinstance(proof, dict):
        raise RuntimeError("Target singleton image proof journal must be mutable.")
    recorded_uid = str(proof.get("pod_uid", "") or "")
    if recorded_uid and recorded_uid != pod_uid:
        recorded_node_name = str(proof.get("node_name", "") or "")
        if not _target_takeover_pod_was_runtime_fenced(
            takeover,
            pod_uid=recorded_uid,
            node_name=recorded_node_name,
        ):
            raise RuntimeError(
                "recovery-required: target singleton image proof Pod identity changed "
                "without an exact runtime-fence proof."
            )
        history = takeover.setdefault("target_image_proof_history", [])
        if not isinstance(history, list):
            raise RuntimeError("Target singleton image proof history must be mutable.")
        if not any(
            str(_mapping(item).get("pod_uid", "") or "") == recorded_uid for item in history
        ):
            history.append(dict(proof))
        proof.clear()
    proof.update(
        {
            "schema": "nebius-cxcli/target-singleton-image-proof-v1",
            "pod_uid": pod_uid,
            "node_name": str(_mapping(target_pod.get("spec")).get("nodeName", "") or ""),
            "container_name": container_name,
            "expected_image": expected_image,
            "accepted_image_digests": sorted(accepted_digests),
        }
    )
    for attempt in range(6):
        live_uid = str(_mapping(current_pod.get("metadata")).get("uid", "") or "")
        if live_uid != pod_uid:
            raise SoperatorMigrationPhasePending(
                "target singleton Pod identity changed while its image digest converged."
            )
        container_status = next(
            (
                item
                for item in _sequence_of_mappings(
                    _mapping(current_pod.get("status")).get("containerStatuses")
                )
                if item.get("name") == container_name
            ),
            {},
        )
        observed_image_id = str(container_status.get("imageID", "") or "")
        observed_digest = _runtime_image_digest(observed_image_id)
        proof.update(
            {
                "status": "observing",
                "attempts": attempt + 1,
                "last_observed_image_id": observed_image_id,
                "last_observed_digest": observed_digest,
                "last_observed_at": _utc_now(),
            }
        )
        if observed_digest in accepted_digests:
            proof.update(
                {
                    "status": "verified",
                    "matched_digest": observed_digest,
                    "verified_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return current_pod
        if checkpoint_writer is not None:
            checkpoint_writer()
        if attempt < 5:
            time.sleep(2)
            current_pod = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    "pod/controller-0",
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
    raise SoperatorMigrationPhasePending(
        "target singleton is not running the locked target OCI index or platform digest."
    )


def _runtime_image_digest(image_id: str) -> str:
    """Return the trailing immutable runtime digest, if it is exact."""

    match = re.search(r"@?(sha256:[0-9a-f]{64})$", image_id.strip())
    return match.group(1) if match else ""


def _locked_target_runtime_image_digests(
    journal: Mapping[str, Any],
    *,
    expected_image: str | None = None,
) -> frozenset[str]:
    """Validate and return the exact OCI index/platform runtime digest set."""

    image_lock = _mapping(journal.get("target_image_lock"))
    immutable_reference = str(image_lock.get("immutable_reference", "") or "").strip()
    repository = str(image_lock.get("repository", "") or "").strip()
    index_digest = str(image_lock.get("index_digest", "") or "").strip()
    platform_digest = str(image_lock.get("platform_digest", "") or "").strip()
    reference_match = re.fullmatch(r"(.+)@(sha256:[0-9a-f]{64})", immutable_reference)
    if (
        reference_match is None
        or (expected_image is not None and immutable_reference != expected_image)
        or (repository and repository != reference_match.group(1))
        or platform_digest != reference_match.group(2)
        or not re.fullmatch(r"sha256:[0-9a-f]{64}", index_digest)
    ):
        raise RuntimeError(
            "recovery-required: target singleton image proof lacks an exact immutable "
            "OCI index/platform lock."
        )
    return frozenset({index_digest, platform_digest})


def _target_takeover_client_proof_is_deferred(
    *,
    stage: BridgeStage,
    takeover: Mapping[str, Any],
) -> bool:
    target_start = _mapping(takeover.get("target_start"))
    target_start_state = str(target_start.get("state") or "")
    accepted_start = (
        target_start_state in {"accepted", "preparing"}
        or (
            target_start_state == "dispatching"
            and bool(str(target_start.get("preparing_at") or ""))
            and bool(str(target_start.get("dispatching_at") or ""))
            and target_start.get("observed_replicas_before") == 0
            and target_start.get("ungate_required") is True
            and not str(target_start.get("pod_uid") or "")
            and not str(target_start.get("node_name") or "")
        )
        or (
            target_start_state == "dispatching"
            and bool(str(target_start.get("accepted_at") or ""))
            and bool(str(target_start.get("pod_uid") or ""))
            and bool(str(target_start.get("node_name") or ""))
            and target_start.get("ungate_required") is False
        )
    )
    return (
        stage is BridgeStage.BRIDGE_FENCED
        and takeover.get("recovery_bridge_active") is not True
        and _mapping(takeover.get("client_handoff_singleton_recovery")).get("status") == "accepted"
        and accepted_start
    )


def _target_singleton_start_config(
    handoff_config: str,
    *,
    target_ref: str,
    state_save_location: str,
) -> str:
    """Build the resolvable one-host daemon config used after bridge fencing."""

    with_state = _controller_config_with_state_save_location(
        handoff_config,
        state_save_location=state_save_location,
    )
    return final_singleton_controller_config(
        with_state,
        target_host=f"controller-0({target_ref}-controller-svc)",
    )


def _wait_for_target_singleton_start_config_propagation(
    *,
    journal: Mapping[str, Any],
    takeover: dict[str, Any],
    target_ref: str,
    target_start_config: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Prove the shared jailed file is singleton-only before starting slurmctld."""

    expected = _controller_bridge_client_config_contract(target_start_config)
    expected_sha256 = str(expected.get("config_sha256") or "")
    expected_hosts = [str(item) for item in expected.get("controller_hosts", []) or []]
    if str(expected.get("cluster_name") or "") != target_ref or expected_hosts != [
        f"controller-0({target_ref}-controller-svc)"
    ]:
        raise RuntimeError("Target singleton start propagation contract is invalid.")
    consumers = _controller_bridge_client_consumers(
        journal=journal,
        target_ref=target_ref,
        source_clients=False,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    if not consumers:
        raise SoperatorMigrationPhasePending(
            "target singleton start configuration has no live jailed-config consumer proof."
        )

    def observe(consumer: Mapping[str, Any]) -> dict[str, Any]:
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                str(consumer.get("name") or ""),
                "-c",
                str(consumer.get("container_name") or ""),
                "--",
                "cat",
                _SOPERATOR_LEGACY_SLURM_CONF,
            ],
            check=False,
            timeout_seconds=120,
        )
        observed_sha256 = ""
        if result.returncode == 0:
            try:
                observed_sha256 = str(
                    _controller_bridge_client_config_contract(result.stdout).get("config_sha256")
                    or ""
                )
            except RuntimeError:
                observed_sha256 = ""
        return {
            "name": str(consumer.get("name") or ""),
            "uid": str(consumer.get("uid") or ""),
            "node_name": str(consumer.get("node_name") or ""),
            "config_sha256": observed_sha256,
        }

    evidence: list[dict[str, Any]] = []
    for attempt in range(12):
        max_workers = min(32, len(consumers))
        if max_workers <= 1:
            evidence = [observe(consumers[0])]
        else:
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                evidence = list(executor.map(observe, consumers))
        if evidence and all(item.get("config_sha256") == expected_sha256 for item in evidence):
            takeover["target_start_config_propagation"] = {
                "schema": "nebius-cxcli/target-singleton-start-config-propagation-v1",
                "status": "verified",
                "config_sha256": expected_sha256,
                "controller_hosts": expected_hosts,
                "consumers": evidence,
                "verified_at": _utc_now(),
            }
            if checkpoint_writer is not None:
                checkpoint_writer()
            return
        if attempt < 11:
            time.sleep(5)
    raise SoperatorMigrationPhasePending(
        "target singleton start configuration did not propagate to every jailed client "
        "before the bounded pre-start deadline."
    )


def _handoff_controller_bridge_to_target_singleton(
    *,
    checkpoint: dict[str, Any],
    ungated_values: Mapping[str, Any],
    target_ref: str,
    expected_version: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    target_values_applier: Callable[[Mapping[str, Any], str], None] | None = None,
) -> list[str]:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            "target singleton takeover requires the v6 controller bridge journal."
        )
    validate_bridge_journal(journal)
    stage = BridgeStage(str(journal.get("stage", "") or ""))
    if stage in {
        BridgeStage.HANDOFF_VALIDATED,
        BridgeStage.PARTITIONS_RESTORED,
        BridgeStage.CLEANED,
    }:
        _revalidate_target_singleton_jwt_material(
            journal=journal,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        lines = ["Target singleton controller takeover reused from journal v6."]
        lines.extend(
            _reconcile_in_place_target_values_after_singleton_handoff(
                checkpoint=checkpoint,
                ungated_values=ungated_values,
                expected_version=expected_version,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
                target_values_applier=target_values_applier,
            )
        )
        lines.extend(
            _restore_in_place_target_manager_after_singleton_handoff(
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        return lines
    if stage not in {
        BridgeStage.TARGET_HA_ACTIVE,
        BridgeStage.BRIDGE_FENCED,
        BridgeStage.TARGET_SINGLETON_ACTIVE,
    }:
        raise SoperatorMigrationPhasePending(
            "target singleton takeover requires target-version bridge HA; "
            f"current stage={stage.value}."
        )
    client_lines: list[str] = []
    if stage is BridgeStage.TARGET_HA_ACTIVE:
        phase_state = checkpoint.setdefault("phase_state", {})
        if not isinstance(phase_state, dict):
            raise RuntimeError("External upgrade phase-state journal must be mutable.")
        retire_phase = phase_state.setdefault("retire-old-resources", {})
        if not isinstance(retire_phase, dict):
            raise RuntimeError("Retire-old-resources phase journal must be mutable.")
        manager_pause_phase = (
            journal
            if isinstance(journal.get("in_place_target_manager_pause"), dict)
            else retire_phase
        )
        client_lines.extend(
            _ensure_in_place_target_manager_paused(
                phase=manager_pause_phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        client_lines.extend(
            _ensure_in_place_target_controller_command_gate(
                checkpoint=checkpoint,
                phase=retire_phase,
                target_ref=target_ref,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
    source_configuration = _mapping(journal.get("source_configuration"))
    bridge_config_names = tuple(
        str(item or "").strip()
        for item in source_configuration.get("config_map_names", []) or []
        if str(item or "").strip()
    )
    if len(bridge_config_names) != 1:
        raise RuntimeError("Target singleton takeover requires one bridge Slurm ConfigMap.")
    bridge_config_name = bridge_config_names[0]
    target_config_name, bridge_only_config, observed_target_state_path = (
        _controller_bridge_target_config(
            journal=journal,
            values=ungated_values,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    )
    target_takeover_hosts = _target_takeover_client_controller_hosts(target_ref)
    handoff_config = source_controller_config_with_bridge_hosts(
        bridge_only_config,
        source_host=target_takeover_hosts[0],
        bridge_hosts=target_takeover_hosts[1:],
    )
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    recorded_target_state_path = str(takeover.get("target_state_save_location", "") or "")
    if recorded_target_state_path and recorded_target_state_path != observed_target_state_path:
        bridge_state_path = str(
            _mapping(journal.get("state_precopy")).get("source_state_save_location", "") or ""
        )
        if observed_target_state_path != bridge_state_path:
            raise RuntimeError(
                "recovery-required: target singleton StateSaveLocation changed after intent."
            )
    else:
        takeover["target_state_save_location"] = observed_target_state_path
        if checkpoint_writer is not None:
            checkpoint_writer()
    target_state_path = recorded_target_state_path or observed_target_state_path
    recorded_target_ref = str(takeover.get("target_ref", "") or "")
    if recorded_target_ref and recorded_target_ref != target_ref:
        raise RuntimeError("recovery-required: target singleton reference changed after intent.")
    takeover["target_ref"] = target_ref
    _reconcile_target_takeover_client_host_order(
        checkpoint=checkpoint,
        journal=journal,
        takeover=takeover,
        target_ref=target_ref,
        expected_contract=_controller_bridge_client_config_contract(handoff_config),
        checkpoint_writer=checkpoint_writer,
    )
    authentication_handoff = _mapping(takeover.get("bridge_authentication_handoff"))
    authentication_recovery_active = bool(
        authentication_handoff and authentication_handoff.get("status") != "verified"
    )
    if stage is BridgeStage.TARGET_HA_ACTIVE:
        if authentication_recovery_active:
            client_lines.extend(
                _ensure_target_bridge_authentication_for_handoff(
                    journal=journal,
                    takeover=takeover,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                )
            )
        client_lines.extend(
            _align_target_bridge_controller_configuration_for_handoff(
                checkpoint=checkpoint,
                journal=journal,
                takeover=takeover,
                bridge_only_config=bridge_only_config,
                handoff_config=handoff_config,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
        if not authentication_recovery_active:
            client_lines.extend(
                _ensure_target_bridge_authentication_for_handoff(
                    journal=journal,
                    takeover=takeover,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                )
            )
    if stage is BridgeStage.TARGET_SINGLETON_ACTIVE:
        _revalidate_target_singleton_jwt_material(
            journal=journal,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        lines = _complete_target_singleton_final_config(
            checkpoint=checkpoint,
            journal=journal,
            takeover=takeover,
            target_config_name=target_config_name,
            handoff_config=_controller_config_with_state_save_location(
                handoff_config,
                state_save_location=target_state_path,
            ),
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        lines.extend(
            _restore_in_place_target_manager_after_singleton_handoff(
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        return lines
    if _target_takeover_client_proof_is_deferred(stage=stage, takeover=takeover):
        client_lines.append(
            "Interrupted singleton recovery: deferred the superseded bridge-first client "
            "proof until the already-started target singleton is revalidated and every "
            "client proves the final one-host configuration."
        )
    else:
        _patch_slurm_config_map_text(
            namespace=_SOPERATOR_NAMESPACE,
            name=target_config_name,
            config_key=str(source_configuration.get("config_key", "") or ""),
            slurm_conf=handoff_config,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        takeover.update(
            {
                "client_handoff_config_sha256": hashlib.sha256(
                    handoff_config.encode("utf-8")
                ).hexdigest(),
                "client_handoff_config_applied_at": _utc_now(),
            }
        )
        client_lines.extend(
            _prove_controller_bridge_client_configuration(
                journal=journal,
                proof_owner=takeover,
                proof_key="client_handoff_propagation",
                proof_stage="before-target-takeover",
                expected_contract=_controller_bridge_client_config_contract(handoff_config),
                expected_cluster_name=target_ref,
                required_hosts=target_takeover_hosts,
                target_ref=target_ref,
                source_clients=False,
                require_raised_timeouts=False,
                require_live_rpc=_target_takeover_client_proof_requires_live_rpc(
                    stage=stage,
                    takeover=takeover,
                ),
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
    if stage is BridgeStage.TARGET_HA_ACTIVE:
        _preflight_target_singleton_jwt_material(
            journal=journal,
            target_ref=target_ref,
            slurm_config=handoff_config,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    action_journal = ensure_slurm_action_journal(checkpoint)
    set_slurm_action_broker_mode(action_journal, "accept-only")
    journal["action_broker_mode"] = "accept-only"
    if checkpoint_writer is not None:
        checkpoint_writer()

    _fence_target_version_bridge_for_takeover(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )

    target_start_config = _target_singleton_start_config(
        handoff_config,
        target_ref=target_ref,
        state_save_location=target_state_path,
    )
    _patch_slurm_config_map_text(
        namespace=_SOPERATOR_NAMESPACE,
        name=target_config_name,
        config_key=str(source_configuration.get("config_key", "") or ""),
        slurm_conf=target_start_config,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    takeover.update(
        {
            "target_start_config_sha256": hashlib.sha256(
                target_start_config.encode("utf-8")
            ).hexdigest(),
            "target_state_save_location": target_state_path,
            "target_start_config_applied_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()

    try:
        target_exists, target_workload_before = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="statefulset.apps.kruise.io/controller",
        )
        target_replicas_before = (
            _resource_replicas(target_workload_before, default=-1) if target_exists else 0
        )
        target_workload_uid_before = str(
            _mapping(target_workload_before.get("metadata")).get("uid", "") or ""
        )
        preflight = _mapping(takeover.get("jwt_material_preflight"))
        if (
            not target_exists
            or target_replicas_before not in {0, 1}
            or not target_workload_uid_before
            or target_workload_uid_before != preflight.get("controller_workload_uid")
        ):
            raise SoperatorMigrationPhasePending(
                "target singleton takeover found a missing, replaced, or unexpected gated "
                f"controller workload: replicas={target_replicas_before}."
            )
        target_template_spec = _mapping(
            _mapping(_mapping(target_workload_before.get("spec")).get("template")).get("spec")
        )
        target_template_containers = [
            item
            for item in _sequence_of_mappings(target_template_spec.get("containers"))
            if "slurmctld" in str(item.get("name", "") or "").lower()
        ]
        if len(target_template_containers) != 1:
            raise SoperatorMigrationPhasePending(
                "target singleton takeover requires one exact slurmctld workload container."
            )
        target_gated_before = _is_exact_target_controller_command_gate(
            target_template_containers[0]
        )
        target_start = takeover.get("target_start")
        if not isinstance(target_start, dict):
            target_start = {}
            takeover["target_start"] = target_start
        prior_start_state = str(target_start.get("state", "") or "")
        prior_start_pod_uid = str(target_start.get("pod_uid", "") or "")
        prior_start_node_name = str(target_start.get("node_name", "") or "")
        if (
            target_replicas_before == 0
            and prior_start_state == "accepted"
            and prior_start_pod_uid
            and _target_takeover_pod_was_runtime_fenced(
                takeover,
                pod_uid=prior_start_pod_uid,
                node_name=prior_start_node_name,
            )
        ):
            history = takeover.setdefault("target_start_history", [])
            if not isinstance(history, list):
                raise RuntimeError("Target singleton start history must be mutable.")
            if not any(
                str(_mapping(item).get("pod_uid") or "") == prior_start_pod_uid for item in history
            ):
                history.append(copy.deepcopy(target_start))
            target_start.clear()
            prior_start_state = ""
        if (
            not target_gated_before
            and prior_start_state not in {"dispatching", "accepted"}
            # A previously ungated workload at replicas=0 is safe to reuse only
            # after its last accepted Pod was exactly runtime-fenced above.
            and prior_start_pod_uid
            and not _target_takeover_pod_was_runtime_fenced(
                takeover,
                pod_uid=prior_start_pod_uid,
                node_name=prior_start_node_name,
            )
        ):
            raise RuntimeError(
                "recovery-required: target controller became ungated before cxcli "
                "recorded its singleton-start intent."
            )
        ungate_required = target_gated_before or target_replicas_before == 0
        gated_pod_uid = str(preflight.get("controller_pod_uid", "") or "")
        expected_target_image = str(
            _mapping(journal.get("version_transition")).get("target_image", "") or ""
        )
        recorded_start_ref = str(target_start.get("target_ref", "") or "")
        recorded_start_image = str(target_start.get("target_image", "") or "")
        if (recorded_start_ref and recorded_start_ref != target_ref) or (
            recorded_start_image and recorded_start_image != expected_target_image
        ):
            raise RuntimeError(
                "recovery-required: target singleton start intent changed its target or image."
            )
        target_start.update(
            {
                "state": "accepted" if target_replicas_before == 1 else "preparing",
                "preparing_at": str(target_start.get("preparing_at", "") or "") or _utc_now(),
                "target_ref": target_ref,
                "target_image": expected_target_image,
                "observed_replicas_before": target_replicas_before,
                "ungate_required": ungate_required,
                "gated_pod_uid": gated_pod_uid,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _wait_for_target_singleton_start_config_propagation(
            journal=journal,
            takeover=takeover,
            target_ref=target_ref,
            target_start_config=target_start_config,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        if ungate_required:
            bridge_stop_identities = _sequence_of_mappings(takeover.get("bridge_stop_pods"))
            if len(bridge_stop_identities) != 2:
                raise RuntimeError(
                    "recovery-required: target singleton writer start lacks both historical "
                    "bridge node identities."
                )
            target_start_fence_targets = _controller_fence_targets_from_identities(
                bridge_stop_identities,
                state_markers=(
                    str(
                        _mapping(journal.get("state_precopy")).get("source_state_save_location", "")
                        or ""
                    ),
                    "/mnt/controller-spool/current",
                ),
                boundary="target singleton pre-writer-start",
            )
            _prove_controller_runtime_fence(
                journal=journal,
                boundary="target-singleton-pre-writer-start",
                targets=target_start_fence_targets,
                image=expected_target_image,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
                fresh_attempt=True,
            )
            target_start_census = _prove_cluster_wide_slurmctld_absence(
                proof_label="target singleton immediate pre-start runtime fence",
                campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
            )
            _revalidate_controller_bridge_security_contract(
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
            )
            _revalidate_controller_runtime_census_nodes(
                node_census=target_start_census,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        target_start.update(
            {
                "state": "dispatching",
                "dispatching_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        _ungate_in_place_target_controller_for_takeover(
            takeover=takeover,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        if ungate_required:
            target_start["ungate_accepted_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
        if gated_pod_uid:
            _wait_for_kubernetes_resource_uid_absent(
                command_runner=command_runner,
                kube_context=kube_context,
                api_path="/api/v1/namespaces/soperator/pods/controller-0",
                uid=gated_pod_uid,
                timeout_seconds=900,
            )
        _kubectl_wait(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="pod/controller-0",
            condition="Ready",
            timeout="15m",
            timeout_seconds=960,
        )
        target_pod = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "pod/controller-0",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        target_start.update(
            {
                "state": "accepted",
                "accepted_at": _utc_now(),
                "pod_uid": str(_mapping(target_pod.get("metadata")).get("uid", "") or ""),
                "node_name": str(_mapping(target_pod.get("spec")).get("nodeName", "") or ""),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        containers = _sequence_of_mappings(_mapping(target_pod.get("spec")).get("containers"))
        live_slurmctld_containers = [
            item for item in containers if "slurmctld" in str(item.get("name", "") or "").lower()
        ]
        if len(live_slurmctld_containers) != 1 or _is_exact_target_controller_command_gate(
            live_slurmctld_containers[0]
        ):
            raise SoperatorMigrationPhasePending(
                "target controller rollout did not replace the canonical command-gated Pod."
            )
        container_name = next(
            (
                str(item.get("name", "") or "")
                for item in containers
                if "slurmctld" in str(item.get("name", "") or "").lower()
            ),
            "",
        )
        if not container_name:
            raise SoperatorMigrationPhasePending(
                "target controller Pod has no exact slurmctld container."
            )
        expected_image = str(
            _mapping(journal.get("version_transition")).get("target_image", "") or ""
        )
        target_pod = _revalidate_target_singleton_image_digest(
            takeover=takeover,
            target_pod=target_pod,
            container_name=container_name,
            expected_image=expected_image,
            expected_image_lock=_mapping(journal.get("target_image_lock")),
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        _ensure_target_singleton_primary_takeover(
            journal=journal,
            takeover=takeover,
            target_ref=target_ref,
            target_pod=target_pod,
            container_name=container_name,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        proof = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                "controller-0",
                "-c",
                container_name,
                "--",
                "/bin/sh",
                "-ec",
                (
                    f"export SLURM_CONF={shlex.quote(_SOPERATOR_LEGACY_SLURM_CONF)}; "
                    'test "$(pgrep -x slurmctld | wc -l)" -eq 1; '
                    "scontrol ping; scontrol show config; scontrol show jobs -o"
                ),
            ],
            check=False,
            timeout_seconds=180,
        )
        if proof.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "target singleton did not load and answer from the shared controller state."
            )
        if not _controller_ping_proves_only_live_host(
            proof.stdout,
            expected_host="controller-0",
        ):
            raise SoperatorMigrationPhasePending(
                "target controller did not prove itself as the only live controller."
            )
        state_path_match = re.search(r"(?im)^\s*StateSaveLocation\s*=\s*(\S+)\s*$", proof.stdout)
        if not state_path_match or state_path_match.group(1) != target_state_path:
            raise SoperatorMigrationPhasePending(
                "target singleton StateSaveLocation does not use the promoted shared epoch."
            )
        target_workload_exists, target_workload = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="statefulset.apps.kruise.io/controller",
        )
        target_workload_metadata = _mapping(target_workload.get("metadata"))
        target_workload_template = _mapping(
            _mapping(_mapping(target_workload.get("spec")).get("template")).get("spec")
        )
        target_workload_containers = [
            item
            for item in _sequence_of_mappings(target_workload_template.get("containers"))
            if "slurmctld" in str(item.get("name", "") or "").lower()
        ]
        if (
            not target_workload_exists
            or _resource_replicas(target_workload, default=-1) != 1
            or str(target_workload_metadata.get("uid", "") or "") != target_workload_uid_before
            or len(target_workload_containers) != 1
            or _is_exact_target_controller_command_gate(target_workload_containers[0])
        ):
            raise SoperatorMigrationPhasePending(
                "target singleton controller workload is not the exact ungated replicas=1 workload."
            )
        target_pod_uid = str(_mapping(target_pod.get("metadata")).get("uid", "") or "")
        target_workload_uid = str(target_workload_metadata.get("uid", "") or "")
        if not target_pod_uid or not target_workload_uid:
            raise SoperatorMigrationPhasePending(
                "target singleton takeover lacks immutable Pod or workload identity."
            )
        _prove_cluster_wide_slurmctld_exclusivity(
            expected_pods=((_SOPERATOR_NAMESPACE, "controller-0", target_pod_uid),),
            expected_workload=(
                "statefulsets.apps.kruise.io",
                _SOPERATOR_NAMESPACE,
                "controller",
                target_workload_uid,
            ),
            expected_replicas=1,
            proof_label="target singleton startup adoption",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        target_pod_metadata = _mapping(target_pod.get("metadata"))
        takeover.update(
            {
                "command_gate_applied": False,
                "command_gate_removed_at": _utc_now(),
                "controller_pod_uid": str(target_pod_metadata.get("uid", "") or ""),
                "controller_workload_uid": str(
                    _mapping(target_workload.get("metadata")).get("uid", "") or ""
                ),
                "final_config_map_name": target_config_name,
                "state_loaded": True,
                "state_observation_sha256": hashlib.sha256(
                    proof.stdout.encode("utf-8")
                ).hexdigest(),
                "only_primary_proven": True,
            }
        )
        _revalidate_target_singleton_jwt_material(
            journal=journal,
            target_ref=target_ref,
            target_pod=target_pod,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    except (Exception, KeyboardInterrupt) as exc:
        _restart_target_version_bridge_after_failed_takeover(
            checkpoint=checkpoint,
            journal=journal,
            bridge_config_name=bridge_config_name,
            bridge_only_config=bridge_only_config,
            target_config_name=target_config_name,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        raise SoperatorMigrationPhasePending(
            "target singleton startup failed; cxcli fenced it and restored the target-version "
            f"HA bridge for roll-forward retry: {exc}"
        ) from exc

    _revalidate_controller_authority_lease(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    advance_bridge_stage(journal, BridgeStage.TARGET_SINGLETON_ACTIVE)
    if checkpoint_writer is not None:
        checkpoint_writer()
    client_lines.extend(
        _complete_target_singleton_final_config(
            checkpoint=checkpoint,
            journal=journal,
            takeover=takeover,
            target_config_name=target_config_name,
            handoff_config=target_start_config,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    client_lines.extend(
        _reconcile_in_place_target_values_after_singleton_handoff(
            checkpoint=checkpoint,
            ungated_values=ungated_values,
            expected_version=expected_version,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            target_values_applier=target_values_applier,
        )
    )
    client_lines.extend(
        _restore_in_place_target_manager_after_singleton_handoff(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    return client_lines


def _reconcile_in_place_target_values_after_singleton_handoff(
    *,
    checkpoint: dict[str, Any],
    ungated_values: Mapping[str, Any],
    expected_version: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    target_values_applier: Callable[[Mapping[str, Any], str], None] | None = None,
) -> list[str]:
    """Make the final slot-aware Helm values durable before manager restoration."""

    journal = _mapping(checkpoint.get("controller_bridge"))
    if str(journal.get("stage") or "") not in {
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
        BridgeStage.CLEANED.value,
    }:
        raise SoperatorMigrationPhasePending(
            "target values reconciliation requires the durable target-singleton handoff."
        )
    phase_state = checkpoint.setdefault("phase_state", {})
    if not isinstance(phase_state, dict):
        raise RuntimeError("External upgrade phase-state journal must be mutable.")
    retire_phase = phase_state.setdefault("retire-old-resources", {})
    if not isinstance(retire_phase, dict):
        raise RuntimeError("Retire-old-resources phase journal must be mutable.")
    reconciliation = retire_phase.setdefault("in_place_target_values_reconciliation", {})
    if not isinstance(reconciliation, dict):
        raise RuntimeError("Target values reconciliation journal must be mutable.")

    effective_values = _effective_target_soperator_helm_values(ungated_values)
    expected_fingerprint = _fingerprint(effective_values)
    recorded_fingerprint = str(reconciliation.get("values_fingerprint") or "")
    stored_values = _target_soperator_helm_stored_values(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    stored_fingerprint = _fingerprint(stored_values)
    latest_release_deployed = _target_soperator_latest_release_is_deployed(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    populate_phase = _accepted_populate_jail_phase_state(checkpoint)
    handoff = _mapping(populate_phase.get("rootfs_handoff_verification"))
    accepted_active_slot = str(handoff.get("active_slot", "") or "").strip()
    if recorded_fingerprint and recorded_fingerprint != expected_fingerprint:
        rolling_phase = _mapping(
            _mapping(checkpoint.get("phase_state")).get("rolling-compute-migration")
        )
        post_singleton_proof = _mapping(rolling_phase.get("post_singleton_values_proof"))
        post_singleton_reconciliation = _mapping(
            rolling_phase.get("post_singleton_values_reconciliation")
        )
        proof_fingerprint = _fingerprint(post_singleton_proof)
        reusable_checkpointed_values = (
            reconciliation.get("status") == "verified"
            and stored_fingerprint == recorded_fingerprint
            and post_singleton_proof.get("schema") == _TARGET_HELM_APPLY_PROOF_SCHEMA
            and post_singleton_proof.get("status") == "verified"
            and str(post_singleton_proof.get("values_fingerprint") or "") == recorded_fingerprint
            and str(reconciliation.get("proof_fingerprint") or "") == proof_fingerprint
            and post_singleton_reconciliation.get("status") == "verified"
            and str(post_singleton_reconciliation.get("values_fingerprint") or "")
            == recorded_fingerprint
            and str(post_singleton_reconciliation.get("proof_fingerprint") or "")
            == proof_fingerprint
            and str(reconciliation.get("active_jail_slot") or "") == accepted_active_slot
        )
        recoverable_missing_slot_binding = (
            reconciliation.get("status") == "verified"
            and not str(reconciliation.get("active_jail_slot") or "").strip()
            and stored_fingerprint == recorded_fingerprint
            and str(handoff.get("status", "") or "") == "verified"
            and accepted_active_slot in {"slot-a", "slot-b"}
            and str(_mapping(effective_values.get("jailRootfs")).get("activeSlot") or "")
            == accepted_active_slot
        )
        recoverable_failed_apply = (
            reconciliation.get("status") != "verified"
            and not latest_release_deployed
            and stored_fingerprint == recorded_fingerprint
            and not post_singleton_proof
            and not post_singleton_reconciliation
        )
        if reusable_checkpointed_values:
            reconciliation.setdefault(
                "post_cleanup_reconstructed_values_fingerprint", expected_fingerprint
            )
            reconciliation.setdefault("post_cleanup_checkpoint_values_reused_at", _utc_now())
            effective_values = stored_values
            expected_fingerprint = recorded_fingerprint
        elif recoverable_failed_apply:
            failed_attempts = reconciliation.setdefault("superseded_failed_attempts", [])
            if not isinstance(failed_attempts, list):
                raise RuntimeError(
                    "Target values reconciliation failed-attempt journal must be a list."
                )
            failed_attempts.append(
                {
                    "values_fingerprint": recorded_fingerprint,
                    "intent_at": str(reconciliation.get("intent_at") or ""),
                    "superseded_at": _utc_now(),
                    "reason": "latest Helm release did not deploy",
                }
            )
            for key in (
                "applied_at",
                "apply_window_recovered_at",
                "proof_fingerprint",
                "verified_at",
            ):
                reconciliation.pop(key, None)
            reconciliation["intent_at"] = _utc_now()
            reconciliation["status"] = "repairing"
        elif not recoverable_missing_slot_binding:
            raise RuntimeError(
                "recovery-required: final target Helm values changed after singleton handoff."
            )
        else:
            reconciliation["superseded_values_fingerprint"] = recorded_fingerprint
            reconciliation["superseded_reason"] = (
                "verified values omitted the checkpointed active Jail slot binding"
            )
            reconciliation["superseded_at"] = _utc_now()
            reconciliation["status"] = "repairing"
    reconciliation.update(
        {
            "schema": _IN_PLACE_TARGET_VALUES_RECONCILIATION_SCHEMA,
            "values_fingerprint": expected_fingerprint,
            "active_jail_slot": accepted_active_slot,
            "intent_at": str(reconciliation.get("intent_at") or _utc_now()),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()

    if stored_fingerprint == expected_fingerprint and latest_release_deployed:
        rolling_phase = phase_state.get("rolling-compute-migration")
        if not isinstance(rolling_phase, dict):
            raise SoperatorMigrationPhasePending(
                "final target Helm values require the mutable rolling-compute handoff proof."
            )
        target_binding = _mapping(
            _mapping(rolling_phase.get("slurmcluster_handoff_binding")).get("target")
        )
        if not target_binding:
            takeover_target_ref = str(
                _mapping(journal.get("target_singleton_takeover")).get("target_ref") or ""
            ).strip()
            transition_target_ref = str(
                _mapping(
                    _mapping(checkpoint.get("slurmcluster_identity_transition")).get("target")
                ).get("name")
                or ""
            ).strip()
            if (
                takeover_target_ref
                and transition_target_ref
                and takeover_target_ref != transition_target_ref
            ):
                raise RuntimeError(
                    "recovery-required: target singleton and completed SlurmCluster "
                    "transition identities differ."
                )
            target_ref = takeover_target_ref or transition_target_ref
            if target_ref:
                recovered_binding = _checkpoint_live_target_slurmcluster_handoff_binding(
                    checkpoint=checkpoint,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    checkpoint_writer=checkpoint_writer,
                )
                target_binding = _mapping(recovered_binding.get("target"))
        target_ref = str(target_binding.get("name") or "").strip()
        if not target_ref:
            raise SoperatorMigrationPhasePending(
                "final target Helm values require the exact target SlurmCluster binding."
            )
        apply_window = {
            "schema": _IN_PLACE_TARGET_VALUES_APPLY_WINDOW_SCHEMA,
            "intent_at": str(reconciliation.get("intent_at") or ""),
            "applied_at": str(reconciliation.get("applied_at") or ""),
            "values_fingerprint": expected_fingerprint,
        }
        if apply_window["intent_at"] and not apply_window["applied_at"]:
            recovered_at = _utc_now()
            reconciliation["applied_at"] = recovered_at
            reconciliation["apply_window_recovered_at"] = recovered_at
            apply_window["applied_at"] = recovered_at
            if checkpoint_writer is not None:
                checkpoint_writer()
        recorded_apply_window = rolling_phase.get("post_singleton_values_apply_window")
        if recorded_apply_window is None:
            if not apply_window["intent_at"] or not apply_window["applied_at"]:
                raise SoperatorMigrationPhasePending(
                    "final target Helm values lack their durable reconciliation apply window."
                )
            rolling_phase["post_singleton_values_apply_window"] = copy.deepcopy(apply_window)
            if checkpoint_writer is not None:
                checkpoint_writer()
        elif recorded_apply_window != apply_window:
            raise RuntimeError(
                "recovery-required: final target Helm reconciliation apply window changed."
            )
        proof = _mapping(rolling_phase.get("post_singleton_values_proof"))
        if not proof:
            if reconciliation.get("status") == "accepted":
                _repair_final_target_controller_fields_after_helm_replay(
                    reconciliation=reconciliation,
                    target_binding=target_binding,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            proof = _prove_target_soperator_helm_apply(
                phase=rolling_phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=ungated_values,
                expected_version=expected_version,
                require_command_fence_override=False,
                recovered_from_live_state=True,
                intent_key="post_singleton_values_apply_intent",
                reconciliation_window_key="post_singleton_values_apply_window",
            )
            rolling_phase["post_singleton_values_proof"] = copy.deepcopy(to_plain_data(proof))
        proof_fingerprint = _fingerprint(proof)
        reconciliation.update(
            {
                "status": "verified",
                "proof_fingerprint": proof_fingerprint,
                "verified_at": _utc_now(),
            }
        )
        rolling_phase["post_singleton_values_reconciliation"] = {
            key: copy.deepcopy(to_plain_data(reconciliation.get(key)))
            for key in (
                "schema",
                "status",
                "values_fingerprint",
                "active_jail_slot",
                "proof_fingerprint",
                "verified_at",
            )
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
        return ["Final slot-aware target Helm values verified before manager restoration."]
    if reconciliation.get("status") == "accepted":
        raise RuntimeError(
            "recovery-required: accepted final target Helm values do not match the live release."
        )

    if target_values_applier is not None:
        target_values_applier(ungated_values, expected_version)
    else:
        _helm_upgrade_target_soperator(
            command_runner=command_runner,
            kube_context=kube_context,
            values=ungated_values,
            expected_version=expected_version,
            wait=False,
        )
    reconciliation.update(
        {
            "status": "accepted",
            "applied_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    raise SoperatorMigrationPhasePending(
        "reapplied the final slot-aware target Helm values after singleton handoff; "
        "resume after the manager and target workloads reconcile."
    )


def _repair_final_target_controller_fields_after_helm_replay(
    *,
    reconciliation: dict[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Restore controller fields removed by the singleton command-gate cleanup.

    A Helm three-way replay does not restore a field when its old and new manifests are
    identical but an intervening safety patch removed it from the live object.  Reconcile
    only the four controller fields owned by that safety patch before proving the full
    deployed manifest.
    """

    binding = {
        key: str(target_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    if binding["namespace"] != _SOPERATOR_NAMESPACE or not binding["name"] or not binding["uid"]:
        raise SoperatorMigrationPhasePending(
            "final target controller-field repair requires the exact target SlurmCluster binding."
        )
    manifest_result = command_runner(
        [
            "helm",
            "--kube-context",
            kube_context,
            "get",
            "manifest",
            _SOPERATOR_TARGET_RELEASE_NAME,
            "-n",
            _SOPERATOR_NAMESPACE,
        ],
        timeout_seconds=120,
        check=False,
    )
    if manifest_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "final target controller-field repair could not read the deployed Helm manifest."
        )
    stored_spec = _target_slurmcluster_spec_from_helm_documents(
        manifest_result.stdout,
        target_ref=binding["name"],
        label="final target controller-field repair manifest",
    )
    stored_slurmctld = _mapping(
        _mapping(_mapping(_mapping(stored_spec.get("slurmNodes")).get("controller"))).get(
            "slurmctld"
        )
    )
    if not stored_slurmctld:
        raise SoperatorMigrationPhasePending(
            "final target controller-field repair found no rendered slurmctld contract."
        )
    expected_fields = {
        key: copy.deepcopy(to_plain_data(stored_slurmctld[key]))
        for key in _IN_PLACE_CONTROLLER_GATE_FIELDS
        if key in stored_slurmctld
    }
    expected_fingerprint = _fingerprint(expected_fields)
    repair = reconciliation.setdefault("controller_fields_repair", {})
    if not isinstance(repair, dict):
        raise RuntimeError("Target controller-field repair journal must be mutable.")
    immutable = {
        "schema": _IN_PLACE_TARGET_CONTROLLER_FIELDS_REPAIR_SCHEMA,
        "target": binding,
        "expected_fields_fingerprint": expected_fingerprint,
    }
    if repair and any(repair.get(key) != value for key, value in immutable.items()):
        raise RuntimeError(
            "recovery-required: final target controller-field repair identity changed."
        )
    repair.update(immutable)

    target = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"slurmcluster/{binding['name']}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    metadata = _mapping(target.get("metadata"))
    if str(metadata.get("uid") or "") != binding["uid"]:
        raise SoperatorMigrationPhasePending(
            "final target controller-field repair observed a different SlurmCluster UID."
        )
    resource_version = str(metadata.get("resourceVersion") or "").strip()
    if not resource_version:
        raise SoperatorMigrationPhasePending(
            "final target controller-field repair found no live resourceVersion."
        )
    live_slurmctld = _mapping(
        _mapping(
            _mapping(_mapping(_mapping(target.get("spec")).get("slurmNodes")).get("controller"))
        ).get("slurmctld")
    )
    observed_fields = {
        key: copy.deepcopy(to_plain_data(live_slurmctld[key]))
        for key in _IN_PLACE_CONTROLLER_GATE_FIELDS
        if key in live_slurmctld
    }
    if observed_fields == expected_fields:
        repair.update(
            {
                "status": "verified",
                "live_resource_version": resource_version,
                "verified_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return

    repair.update(
        {
            "status": "intent-recorded",
            "observed_fields_fingerprint": _fingerprint(observed_fields),
            "changed_fields": sorted(set(observed_fields) | set(expected_fields)),
            "intent_resource_version": resource_version,
            "intent_at": str(repair.get("intent_at") or _utc_now()),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    patch_fields = {
        key: copy.deepcopy(to_plain_data(expected_fields.get(key)))
        if key in expected_fields
        else None
        for key in _IN_PLACE_CONTROLLER_GATE_FIELDS
    }
    _kubectl_patch_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"slurmcluster/{binding['name']}",
        patch={
            "metadata": {
                "uid": binding["uid"],
                "resourceVersion": resource_version,
            },
            "spec": {
                "slurmNodes": {
                    "controller": {"slurmctld": patch_fields},
                }
            },
        },
        patch_via_stdin=True,
    )
    repair.update({"status": "accepted", "accepted_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()

    updated = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"slurmcluster/{binding['name']}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    updated_metadata = _mapping(updated.get("metadata"))
    updated_slurmctld = _mapping(
        _mapping(
            _mapping(_mapping(_mapping(updated.get("spec")).get("slurmNodes")).get("controller"))
        ).get("slurmctld")
    )
    updated_fields = {
        key: copy.deepcopy(to_plain_data(updated_slurmctld[key]))
        for key in _IN_PLACE_CONTROLLER_GATE_FIELDS
        if key in updated_slurmctld
    }
    if (
        str(updated_metadata.get("uid") or "") != binding["uid"]
        or updated_fields != expected_fields
    ):
        raise SoperatorMigrationPhasePending(
            "final target controller-field repair was accepted but did not converge exactly."
        )
    repair.update(
        {
            "status": "verified",
            "live_resource_version": str(updated_metadata.get("resourceVersion") or ""),
            "verified_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()


def _controller_bridge_cleanup_api_path(identity: Mapping[str, Any]) -> str:
    kind = str(identity.get("kind", "") or "")
    namespace = str(identity.get("namespace", "") or "")
    name = str(identity.get("name", "") or "")
    if (
        kind == "Namespace"
        and name in {CONTROLLER_BRIDGE_NAMESPACE, CONTROLLER_INSPECTOR_NAMESPACE}
        and not namespace
    ):
        return f"/api/v1/namespaces/{name}"
    if kind == "PersistentVolume" and name and not namespace:
        return f"/api/v1/persistentvolumes/{name}"
    if kind == "PriorityClass" and name == "cxcli-soperator-upgrade-bridge" and not namespace:
        return f"/apis/scheduling.k8s.io/v1/priorityclasses/{name}"
    if (
        kind == "PersistentVolumeClaim"
        and namespace == CONTROLLER_BRIDGE_NAMESPACE
        and name in {CONTROLLER_BRIDGE_STATE_PVC, CONTROLLER_BRIDGE_JAIL_PVC}
    ):
        return f"/api/v1/namespaces/{namespace}/persistentvolumeclaims/{name}"
    if kind == "RoleBinding" and namespace == _SOPERATOR_NAMESPACE and name:
        return f"/apis/rbac.authorization.k8s.io/v1/namespaces/{namespace}/rolebindings/{name}"
    raise RuntimeError(
        "Controller bridge cleanup only deletes its exact bridge/inspector namespaces, "
        "Retain PV/PVC pairs and cross-namespace RoleBinding directly."
    )


def _controller_bridge_cleanup_action_binding(
    checkpoint: Mapping[str, Any],
) -> dict[str, Any]:
    action_journal = _mapping(_mapping(checkpoint.get("slurm")).get("action_journal"))
    if not action_journal:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the durable Slurm action journal."
        )
    validate_slurm_action_journal(action_journal)
    try:
        binding = slurm_action_partition_restore_binding(action_journal)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the frozen pre-target Slurm action "
            "generation and active target-singleton generation."
        ) from exc
    authority = _external_upgrade_slurm_action_authority(checkpoint)
    authority_epoch = str(authority.get("authority_epoch", "") or "").strip()
    if not authority_epoch or authority_epoch != binding["authority_epoch"]:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the live target authority epoch to match "
            "the durable target action generation."
        )
    with suppress(ValueError):
        binding.update(slurm_action_target_finalization_binding(action_journal))
    return binding


def _ensure_controller_bridge_target_action_generation(
    *,
    checkpoint: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    """Seal pre-target actions and keep target-authority job control available."""

    bridge = _mapping(checkpoint.get("controller_bridge"))
    stage = BridgeStage(str(bridge.get("stage", "") or ""))
    if stage not in {
        BridgeStage.HANDOFF_VALIDATED,
        BridgeStage.PARTITIONS_RESTORED,
        BridgeStage.CLEANED,
    }:
        raise SoperatorMigrationPhasePending(
            "target Slurm action generation requires a validated target singleton handoff; "
            f"current controller bridge stage={stage.value}."
        )
    authority = _mapping(bridge.get("authority"))
    bridge_fencing = _mapping(_mapping(bridge.get("fencing")).get("bridge"))
    if (
        authority.get("owner") != "target-singleton"
        or bridge_fencing.get("proven") is not True
        or bridge_fencing.get("processes_absent") is not True
    ):
        raise SoperatorMigrationPhasePending(
            "target Slurm action generation requires target singleton authority and a "
            "runtime-fenced stopped bridge."
        )
    action_journal = _checkpoint_slurm_action_journal_for_job_control(checkpoint)
    if not _mapping(action_journal.get("partition_restore_boundary")):
        if action_journal.get("broker_mode") != "dispatch-enabled":
            set_slurm_action_broker_mode(action_journal, "dispatch-enabled")
            if checkpoint_writer is not None:
                checkpoint_writer()
        _drain_external_upgrade_slurm_action_journal(
            journal=action_journal,
            command_runner=command_runner,
            kube_context=kube_context,
            authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
            checkpoint_writer=checkpoint_writer,
            finalize_unresolved=True,
        )
        blockers = slurm_action_partition_restore_blockers(action_journal)
        if blockers:
            raise SoperatorMigrationPhasePending(
                "target Slurm action generation waits until every pre-target durable TUI "
                "action is terminal and no action is Indeterminate."
            )
        authority_epoch = str(authority.get("epoch", "") or "").strip()
        if not authority_epoch:
            raise SoperatorMigrationPhasePending(
                "target Slurm action generation requires the target singleton authority epoch."
            )
        begin_target_slurm_action_generation(
            action_journal,
            authority_epoch=authority_epoch,
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    validate_slurm_action_journal(action_journal)
    try:
        slurm_action_partition_restore_binding(action_journal)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "target Slurm action generation requires the frozen pre-target generation."
        ) from exc
    broker_mode = str(action_journal.get("broker_mode", "") or "")
    if broker_mode == "accept-only":
        raise SoperatorMigrationPhasePending(
            "target Slurm action generation finalization is checkpointed and must finish "
            "before final health is rebound."
        )
    if broker_mode == SLURM_ACTION_ADMISSION_CLOSED:
        try:
            slurm_action_target_finalization_binding(action_journal)
        except ValueError as exc:
            raise SoperatorMigrationPhasePending(
                "target Slurm action generation is closed but not yet terminally finalized."
            ) from exc
    elif broker_mode != "dispatch-enabled":
        raise SoperatorMigrationPhasePending(
            "target Slurm action generation requires dispatch-enabled admission during the upgrade."
        )
    return _controller_bridge_cleanup_action_binding(checkpoint)


def _finalize_controller_bridge_target_actions(
    *,
    checkpoint: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    """Close target action admission, drain accepted work, and freeze its proof."""

    action_journal = _checkpoint_slurm_action_journal_for_job_control(checkpoint)
    validate_slurm_action_journal(action_journal)
    try:
        slurm_action_partition_restore_binding(action_journal)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "final action drain requires the frozen pre-target and active target generations."
        ) from exc
    mode = str(action_journal.get("broker_mode", "") or "")
    if mode == "dispatch-enabled":
        _drain_external_upgrade_slurm_action_journal(
            journal=action_journal,
            command_runner=command_runner,
            kube_context=kube_context,
            authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
            checkpoint_writer=checkpoint_writer,
            finalize_unresolved=True,
        )
        if any(
            action.get("state") == SLURM_ACTION_DISPATCHING
            for action in _sequence_of_mappings(action_journal.get("actions"))
        ):
            raise SoperatorMigrationPhasePending(
                "final action boundary waits for the in-flight TUI dispatch to reach a "
                "definitive or Indeterminate result."
            )
        set_slurm_action_broker_mode(action_journal, "accept-only")
        if checkpoint_writer is not None:
            checkpoint_writer()
        mode = str(action_journal.get("broker_mode", "") or "")
    if mode == "accept-only":
        set_slurm_action_broker_mode(action_journal, SLURM_ACTION_ADMISSION_CLOSED)
        if checkpoint_writer is not None:
            checkpoint_writer()
        mode = str(action_journal.get("broker_mode", "") or "")
    if mode != SLURM_ACTION_ADMISSION_CLOSED:
        raise SoperatorMigrationPhasePending(
            "final action boundary requires irreversibly closed TUI action admission."
        )
    _drain_external_upgrade_slurm_action_journal(
        journal=action_journal,
        command_runner=command_runner,
        kube_context=kube_context,
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
        checkpoint_writer=checkpoint_writer,
        finalize_unresolved=True,
        drain_closed_admission=True,
    )
    blockers = slurm_action_finalization_blockers(action_journal)
    if blockers:
        states = sorted({str(action.get("state", "") or "") for action in blockers})
        raise SoperatorMigrationPhasePending(
            "final partition restore is blocked until every accepted target-generation TUI "
            "action is Applied or Rejected; remaining state(s): " + ", ".join(states)
        )
    try:
        finalize_target_slurm_action_generation(action_journal)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(str(exc)) from exc
    if checkpoint_writer is not None:
        checkpoint_writer()
    _controller_bridge_cleanup_require_target_action_generation(action_journal)
    return _controller_bridge_cleanup_action_binding(checkpoint)


def _controller_bridge_cleanup_require_target_action_generation(
    action_journal: Mapping[str, Any],
) -> None:
    validate_slurm_action_journal(action_journal)
    try:
        slurm_action_partition_restore_binding(action_journal)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the frozen pre-target Slurm action generation."
        ) from exc
    if action_journal.get("broker_mode") != SLURM_ACTION_ADMISSION_CLOSED:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires irreversibly closed target-generation TUI "
            "action admission."
        )
    try:
        slurm_action_target_finalization_binding(action_journal)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the immutable finalized target action generation."
        ) from exc
    if slurm_action_finalization_blockers(action_journal):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup cannot proceed while any accepted action is Queued, "
            "Dispatching, or Indeterminate."
        )


def _controller_bridge_cleanup_require_final_health_binding(
    checkpoint: Mapping[str, Any],
    *,
    binding: Mapping[str, Any],
) -> None:
    final_health = _mapping(checkpoint.get("final_health"))
    if final_health.get("status") != "passed" or any(
        final_health.get(field) != value for field, value in binding.items()
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires fresh final campaign health bound to the "
            "current Slurm action-journal generation and controller authority epoch."
        )


def _controller_bridge_cleanup_require_preservation_binding(
    checkpoint: Mapping[str, Any],
    *,
    cleanup: Mapping[str, Any],
) -> None:
    binding = _controller_bridge_cleanup_action_binding(checkpoint)
    _controller_bridge_cleanup_require_final_health_binding(checkpoint, binding=binding)
    preservation = _mapping(cleanup.get("pre_cleanup_preservation_proof"))
    verifications = tuple(
        item
        for item in _sequence_of_mappings(
            _mapping(_mapping(checkpoint.get("controller_bridge")).get("preservation_jobs")).get(
                "verifications"
            )
        )
        if item.get("stage") == "pre-cleanup"
    )
    verification = verifications[0] if len(verifications) == 1 else {}
    if (
        preservation.get("status") != "verified"
        or any(preservation.get(field) != value for field, value in binding.items())
        or not str(preservation.get("verified_at", "") or "").strip()
        or verification.get("status") != "verified"
        or any(verification.get(field) != value for field, value in binding.items())
        or preservation.get("verification_sha256") != _fingerprint(verification)
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires a fresh running-job preservation proof "
            "bound to the current action-journal generation and authority epoch."
        )


def _controller_bridge_require_partition_restore_binding(
    checkpoint: Mapping[str, Any],
) -> dict[str, Any]:
    journal = _mapping(checkpoint.get("controller_bridge"))
    bridge_restore = _mapping(journal.get("partition_restore"))
    checkpoint_restore = _mapping(_mapping(checkpoint.get("slurm")).get("final_partition_restore"))
    (
        _all_records,
        _records,
        records_payload,
        retired_records_payload,
        expected_sha256,
    ) = _checkpoint_slurm_partition_restore_plan(checkpoint)
    action_journal = _checkpoint_slurm_action_journal_for_job_control(checkpoint)
    binding = _controller_bridge_cleanup_action_binding(checkpoint)
    expected = {
        "status": "restored",
        "records_sha256": expected_sha256,
        "partition_count": len(records_payload),
        "target_retired_partition_count": len(retired_records_payload),
        "target_retired_partitions": sorted(
            str(item.get("partition") or "") for item in retired_records_payload
        ),
        **binding,
    }
    if any(bridge_restore.get(key) != value for key, value in expected.items()) or any(
        checkpoint_restore.get(key) != value for key, value in expected.items()
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the exact checkpointed partition restore "
            "bound to the current action-journal generation and authority epoch."
        )
    if checkpoint_restore.get("partitions") != records_payload:
        raise RuntimeError(
            "recovery-required: final Slurm partition restore records changed after restore."
        )
    for field in ("intent_at", "restored_at"):
        bridge_value = str(bridge_restore.get(field, "") or "")
        checkpoint_value = str(checkpoint_restore.get(field, "") or "")
        if not bridge_value or bridge_value != checkpoint_value:
            raise SoperatorMigrationPhasePending(
                "controller bridge cleanup requires matching durable partition restore "
                f"{field} evidence."
            )
    _controller_bridge_cleanup_require_target_action_generation(action_journal)
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=_mapping(journal.get("cleanup")),
    )
    return dict(bridge_restore)


def _controller_bridge_cleanup_required_gates(checkpoint: Mapping[str, Any]) -> None:
    completed = {
        str(item or "").strip()
        for item in checkpoint.get("completed_phases", []) or []
        if str(item or "").strip()
    }
    gate_profile = _mapping(checkpoint.get("controller_bridge_cleanup_profile"))
    configured_required = {
        str(item or "").strip()
        for item in gate_profile.get("required_phase_ids", []) or []
        if str(item or "").strip()
    }
    required = configured_required or {
        "rolling-compute-migration",
        POPULATE_JAIL_REFRESH_PHASE_ID,
        "validation-and-rollback-hold",
        "retire-old-resources",
        "post-upgrade-mk8s-check",
        "post-upgrade-helm-check",
    }
    bridge_stage = str(_mapping(checkpoint.get("controller_bridge")).get("stage") or "")
    if (
        POPULATE_JAIL_REFRESH_PHASE_ID in required
        and bridge_stage
        in {
            BridgeStage.TARGET_SINGLETON_ACTIVE.value,
            BridgeStage.HANDOFF_VALIDATED.value,
            BridgeStage.PARTITIONS_RESTORED.value,
            BridgeStage.CLEANED.value,
        }
        and _phase_has_durable_completed_fast_verification(
            checkpoint,
            POPULATE_JAIL_REFRESH_PHASE_ID,
            require_before_copy_boundary=False,
            require_current_verification_report=False,
        )
    ):
        # A later Kubernetes-only campaign segment has a fresh completed_phases
        # list, while the Jail refresh belongs to the earlier chart/Jail segment.
        # Its durable event pair and successor bridge authority are the
        # cross-segment completion proof.
        completed.add(POPULATE_JAIL_REFRESH_PHASE_ID)
    missing = sorted(required - completed)
    if missing:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup is blocked until all final worker, accounting, Jail, "
            "GPU, login and Helm gates complete: " + ", ".join(missing)
        )
    for phase_id in sorted(required):
        verification = stage_fast_verification_report(
            phase_id,
            _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id)),
        )
        if str(verification.get("status", "") or "") in {"passed", "skipped"}:
            continue
        historical_populate_successor = bool(
            phase_id == POPULATE_JAIL_REFRESH_PHASE_ID
            and bridge_stage
            in {
                BridgeStage.TARGET_SINGLETON_ACTIVE.value,
                BridgeStage.HANDOFF_VALIDATED.value,
                BridgeStage.PARTITIONS_RESTORED.value,
                BridgeStage.CLEANED.value,
            }
            and _phase_has_durable_completed_fast_verification(
                checkpoint,
                phase_id,
                require_before_copy_boundary=False,
                require_current_verification_report=False,
            )
        )
        if not historical_populate_successor:
            raise SoperatorMigrationPhasePending(
                f"controller bridge cleanup requires passed fast verification for {phase_id}."
            )
    binding = _controller_bridge_cleanup_action_binding(checkpoint)
    _controller_bridge_cleanup_require_final_health_binding(checkpoint, binding=binding)


def _controller_bridge_target_state_binding(
    *,
    journal: Mapping[str, Any],
    target_pod: Mapping[str, Any],
    container_name: str,
    state_path: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, str]:
    if not state_path.startswith("/"):
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup proof requires an absolute StateSaveLocation."
        )
    containers = _sequence_of_mappings(_mapping(target_pod.get("spec")).get("containers"))
    container = next(
        (item for item in containers if str(item.get("name", "") or "") == container_name),
        {},
    )
    candidate_volume_names = {
        str(item.get("name", "") or "")
        for item in _sequence_of_mappings(container.get("volumeMounts"))
        if str(item.get("name", "") or "")
        and (
            state_path == str(item.get("mountPath", "") or "")
            or state_path.startswith(str(item.get("mountPath", "") or "").rstrip("/") + "/")
        )
    }
    volumes = _sequence_of_mappings(_mapping(target_pod.get("spec")).get("volumes"))
    pvc_names = {
        str(_mapping(item.get("persistentVolumeClaim")).get("claimName", "") or "")
        for item in volumes
        if str(item.get("name", "") or "") in candidate_volume_names
        and str(_mapping(item.get("persistentVolumeClaim")).get("claimName", "") or "")
    }
    if len(pvc_names) != 1:
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup proof requires StateSaveLocation to resolve to "
            "exactly one controller-spool PVC."
        )
    pvc_name = next(iter(pvc_names))
    pvc_exists, pvc = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"persistentvolumeclaim/{pvc_name}",
    )
    pvc_metadata = _mapping(pvc.get("metadata"))
    pvc_uid = str(pvc_metadata.get("uid", "") or "")
    pv_name = str(_mapping(pvc.get("spec")).get("volumeName", "") or "")
    if not pvc_exists or not pvc_uid or not pv_name:
        raise SoperatorMigrationPhasePending(
            "target singleton controller-spool PVC is not durably Bound."
        )
    pv = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "persistentvolume",
            pv_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pv_metadata = _mapping(pv.get("metadata"))
    pv_uid = str(pv_metadata.get("uid", "") or "")
    claim_ref = _mapping(_mapping(pv.get("spec")).get("claimRef"))
    if (
        not pv_uid
        or str(claim_ref.get("namespace", "") or "") != _SOPERATOR_NAMESPACE
        or str(claim_ref.get("name", "") or "") != pvc_name
        or str(claim_ref.get("uid", "") or "") != pvc_uid
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton controller-spool PV/PVC claim identity is incomplete or drifted."
        )
    bridge_pv_uids = {
        str(item.get("uid", "") or "")
        for item in _sequence_of_mappings(journal.get("kubernetes_resources"))
        if item.get("kind") == "PersistentVolume"
    }
    bridge_pvc_uids = {
        str(item.get("uid", "") or "")
        for item in _sequence_of_mappings(journal.get("kubernetes_resources"))
        if item.get("kind") == "PersistentVolumeClaim"
    }
    if pv_uid in bridge_pv_uids or pvc_uid in bridge_pvc_uids:
        raise RuntimeError(
            "recovery-required: target singleton state still uses a bridge-owned PV or PVC."
        )
    return {
        "namespace": _SOPERATOR_NAMESPACE,
        "pvc_name": pvc_name,
        "pvc_uid": pvc_uid,
        "pv_name": pv_name,
        "pv_uid": pv_uid,
        "state_path": state_path,
        "observed_at": _utc_now(),
    }


def _slurmctld_host_identities(slurm_config: str) -> tuple[str, ...]:
    """Parse every SlurmctldHost directive without discarding address aliases."""

    directive_lines = re.findall(
        r"(?im)^\s*SlurmctldHost(?:\[\d+\])?\s*=.*$",
        slurm_config,
    )
    identities: list[str] = []
    for line in directive_lines:
        match = re.fullmatch(
            r"\s*SlurmctldHost(?:\[\d+\])?\s*=\s*([^\s()]+)"
            r"(?:\([^\s()]+\))?\s*",
            line,
            flags=re.IGNORECASE,
        )
        if match is None:
            return ()
        identities.append(match.group(1))
    return tuple(identities)


def _revalidate_target_singleton_before_controller_bridge_cleanup(
    *,
    journal: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Adopt only a fully proven controller successor before destructive cleanup."""

    takeover = _mapping(journal.get("target_singleton_takeover"))
    target_ref = str(takeover.get("target_ref", "") or "").strip()
    if not target_ref:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the checkpointed target SlurmCluster identity."
        )
    _revalidate_target_singleton_jwt_material(
        journal=journal,
        target_ref=target_ref,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )


def _prove_controller_bridge_cleanup_target_singleton(
    *,
    journal: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    require_cluster_wide_census: bool = True,
) -> dict[str, str]:
    takeover = _mapping(journal.get("target_singleton_takeover"))
    target_uid = str(takeover.get("controller_pod_uid", "") or "")
    target_exists, target_pod = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="pod/controller-0",
    )
    target_metadata = _mapping(target_pod.get("metadata"))
    if (
        not target_exists
        or not target_uid
        or str(target_metadata.get("uid", "") or "") != target_uid
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the checkpointed target controller-0 Pod."
        )
    workload_exists, workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="statefulset.apps.kruise.io/controller",
    )
    workload_uid = str(_mapping(workload.get("metadata")).get("uid", "") or "")
    if (
        not workload_exists
        or _resource_replicas(workload, default=-1) != 1
        or not workload_uid
        or workload_uid != str(takeover.get("controller_workload_uid", "") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires the checkpointed target controller replicas=1."
        )
    containers = _sequence_of_mappings(_mapping(target_pod.get("spec")).get("containers"))
    slurmctld_containers = [
        str(item.get("name", "") or "")
        for item in containers
        if "slurmctld" in str(item.get("name", "") or "").lower()
    ]
    if len(slurmctld_containers) != 1:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires one target slurmctld container."
        )
    container_name = slurmctld_containers[0]
    expected_image = str(_mapping(journal.get("version_transition")).get("target_image", "") or "")
    accepted_image_digests = _locked_target_runtime_image_digests(
        journal,
        expected_image=expected_image,
    )
    status = next(
        (
            item
            for item in _sequence_of_mappings(
                _mapping(target_pod.get("status")).get("containerStatuses")
            )
            if item.get("name") == container_name
        ),
        {},
    )
    observed_image_digest = _runtime_image_digest(str(status.get("imageID", "") or ""))
    if observed_image_digest not in accepted_image_digests:
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup target image digest differs from the locked OCI "
            "index/platform pair."
        )
    proof = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            "controller-0",
            "-c",
            container_name,
            "--",
            "/bin/sh",
            "-ec",
            ('test "$(pgrep -x slurmctld | wc -l)" -eq 1; scontrol ping; scontrol show config'),
        ],
        check=False,
        timeout_seconds=180,
    )
    state_path = str(takeover.get("target_state_save_location", "") or "")
    observed_state = re.search(r"(?im)^\s*StateSaveLocation\s*=\s*(\S+)\s*$", proof.stdout)
    if (
        proof.returncode != 0
        or not _controller_ping_proves_only_live_host(
            proof.stdout,
            expected_host="controller-0",
        )
        or not observed_state
        or observed_state.group(1) != state_path
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup did not prove one target primary on shared state."
        )
    config_name = str(takeover.get("final_config_map_name", "") or "")
    if not config_name:
        raise RuntimeError("Target singleton cleanup proof lacks its final ConfigMap binding.")
    config = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "configmap",
            config_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    config_key = str(_mapping(journal.get("source_configuration")).get("config_key", "") or "")
    final_config = str(_mapping(config.get("data")).get(config_key, "") or "")
    hosts = _slurmctld_host_identities(final_config)
    if hosts != ("controller-0",):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires exactly one final SlurmctldHost."
        )
    if require_cluster_wide_census:
        _prove_cluster_wide_slurmctld_exclusivity(
            expected_pods=((_SOPERATOR_NAMESPACE, "controller-0", target_uid),),
            expected_workload=(
                "statefulsets.apps.kruise.io",
                _SOPERATOR_NAMESPACE,
                "controller",
                workload_uid,
            ),
            expected_replicas=1,
            proof_label="controller bridge cleanup",
            campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
            journal=journal,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    return _controller_bridge_target_state_binding(
        journal=journal,
        target_pod=target_pod,
        container_name=container_name,
        state_path=state_path,
        kube_context=kube_context,
        command_runner=command_runner,
    )


def _controller_bridge_cleanup_resource_records(
    journal: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    records = _sequence_of_mappings(journal.get("kubernetes_resources"))
    if not records:
        raise RuntimeError("Controller bridge cleanup has no bound Kubernetes resources.")
    return records


def _controller_bridge_cleanup_storage_records(
    journal: Mapping[str, Any],
) -> dict[str, dict[str, Mapping[str, Any]]]:
    """Return the exact state and Jail PV/PVC identities owned by the bridge."""

    records = _controller_bridge_cleanup_resource_records(journal)
    namespace = str(journal.get("namespace", "") or "")
    expected_names = {
        "controller_spool": CONTROLLER_BRIDGE_STATE_PVC,
        "jail": CONTROLLER_BRIDGE_JAIL_PVC,
    }
    storage: dict[str, dict[str, Mapping[str, Any]]] = {}
    for label, claim_name in expected_names.items():
        pv_matches = [
            item
            for item in records
            if item.get("kind") == "PersistentVolume"
            and not str(item.get("namespace", "") or "")
            and item.get("name") == f"{claim_name}-pv"
        ]
        pvc_matches = [
            item
            for item in records
            if item.get("kind") == "PersistentVolumeClaim"
            and item.get("namespace") == namespace
            and item.get("name") == claim_name
        ]
        if len(pv_matches) != 1 or len(pvc_matches) != 1:
            raise RuntimeError(
                "Controller bridge cleanup requires one exact name/UID-bound state and "
                f"Jail PV/PVC pair; invalid {label} binding."
            )
        if any(
            not str(item.get(field, "") or "")
            for item in (*pv_matches, *pvc_matches)
            for field in ("api_version", "kind", "name", "uid", "resource_version")
        ):
            raise RuntimeError(f"Controller bridge cleanup {label} storage identity is incomplete.")
        storage[label] = {"pv": pv_matches[0], "pvc": pvc_matches[0]}
    bridge_pvs = [item for item in records if item.get("kind") == "PersistentVolume"]
    bridge_pvcs = [
        item
        for item in records
        if item.get("kind") == "PersistentVolumeClaim" and item.get("namespace") == namespace
    ]
    if len(bridge_pvs) != 2 or len(bridge_pvcs) != 2:
        raise RuntimeError("Controller bridge cleanup found an unexpected bridge PV/PVC inventory.")
    return storage


def _controller_bridge_cleanup_bind_inspector_namespace(
    *,
    journal: Mapping[str, Any],
    cleanup: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, str]:
    """Bind the exact privileged inspector Namespace before destructive cleanup."""

    inspector = _mapping(_mapping(journal.get("security_contract")).get("inspector"))
    expected_uid = str(inspector.get("namespace_uid", "") or "")
    expected_name = str(inspector.get("namespace", "") or "")
    if expected_name != CONTROLLER_INSPECTOR_NAMESPACE or not expected_uid:
        raise RuntimeError(
            "Controller bridge cleanup lacks the exact privileged inspector Namespace binding."
        )
    existing = _mapping(cleanup.get("inspector_namespace_identity"))
    if existing:
        identity = {
            field: str(existing.get(field, "") or "")
            for field in (
                "api_version",
                "kind",
                "namespace",
                "name",
                "uid",
                "resource_version",
            )
        }
        if (
            identity != dict(existing)
            or identity
            != {
                "api_version": "v1",
                "kind": "Namespace",
                "namespace": "",
                "name": CONTROLLER_INSPECTOR_NAMESPACE,
                "uid": expected_uid,
                "resource_version": identity["resource_version"],
            }
            or not identity["resource_version"]
        ):
            raise RuntimeError(
                "recovery-required: privileged inspector Namespace cleanup identity drifted."
            )
        return identity
    if str(cleanup.get("intent_at", "") or ""):
        raise RuntimeError(
            "recovery-required: destructive controller bridge cleanup started without an "
            "exact privileged inspector Namespace identity."
        )
    _revalidate_controller_bridge_security_contract(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    exists, live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity={
            "kind": "Namespace",
            "namespace": "",
            "name": CONTROLLER_INSPECTOR_NAMESPACE,
        },
    )
    identity = _controller_bridge_object_identity(live)
    if (
        not exists
        or identity
        != {
            "api_version": "v1",
            "kind": "Namespace",
            "namespace": "",
            "name": CONTROLLER_INSPECTOR_NAMESPACE,
            "uid": expected_uid,
            "resource_version": identity["resource_version"],
        }
        or not identity["resource_version"]
    ):
        raise RuntimeError(
            "recovery-required: privileged inspector Namespace identity changed before cleanup."
        )
    cleanup["inspector_namespace_identity"] = identity
    if checkpoint_writer is not None:
        checkpoint_writer()
    return identity


def _controller_bridge_cleanup_verify_bridge_storage(
    *,
    journal: Mapping[str, Any],
    target_state: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> dict[str, dict[str, str]]:
    storage_records = _controller_bridge_cleanup_storage_records(journal)
    proof: dict[str, dict[str, str]] = {}
    bridge_pv_uids: set[str] = set()
    bridge_pvc_uids: set[str] = set()
    for label, pair in storage_records.items():
        pvc_record = pair["pvc"]
        pv_record = pair["pv"]
        pvc_exists, pvc = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=pvc_record,
        )
        pv_exists, pv = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=pv_record,
        )
        if not pvc_exists or not pv_exists:
            raise RuntimeError(
                "recovery-required: bridge state or Jail PV/PVC disappeared before "
                "checkpointed cleanup intent."
            )
        pvc_uid = str(_mapping(pvc.get("metadata")).get("uid", "") or "")
        pv_uid = str(_mapping(pv.get("metadata")).get("uid", "") or "")
        pvc_spec = _mapping(pvc.get("spec"))
        pv_spec = _mapping(pv.get("spec"))
        claim_ref = _mapping(pv_spec.get("claimRef"))
        local_path = str(_mapping(pv_spec.get("local")).get("path", "") or "")
        if (
            pvc_uid != pvc_record.get("uid")
            or pv_uid != pv_record.get("uid")
            or str(pvc_spec.get("volumeName", "") or "") != pv_record.get("name")
            or str(claim_ref.get("namespace", "") or "") != pvc_record.get("namespace")
            or str(claim_ref.get("name", "") or "") != pvc_record.get("name")
            or str(claim_ref.get("uid", "") or "") != pvc_record.get("uid")
            or pv_spec.get("persistentVolumeReclaimPolicy") != "Retain"
            or not local_path.startswith("/")
            or pv_spec.get("csi")
        ):
            raise RuntimeError(
                "recovery-required: bridge state or Jail Retain PV/PVC identity changed."
            )
        if label == "controller_spool" and local_path != "/mnt/controller-spool":
            raise RuntimeError(
                "recovery-required: bridge controller-spool local path changed before cleanup."
            )
        bridge_pv_uids.add(pv_uid)
        bridge_pvc_uids.add(pvc_uid)
        proof[label] = {
            "pv_name": str(pv_record.get("name", "") or ""),
            "pv_uid": pv_uid,
            "pvc_name": str(pvc_record.get("name", "") or ""),
            "pvc_uid": pvc_uid,
            "reclaim_policy": "Retain",
            "local_path": local_path,
        }
    if (
        str(target_state.get("pv_uid", "") or "") in bridge_pv_uids
        or str(target_state.get("pvc_uid", "") or "") in bridge_pvc_uids
    ):
        raise RuntimeError(
            "recovery-required: target controller state still uses bridge-owned storage."
        )
    return proof


def _controller_bridge_cleanup_require_storage_proof(
    *,
    journal: Mapping[str, Any],
    cleanup: Mapping[str, Any],
) -> dict[str, Mapping[str, Any]]:
    storage_records = _controller_bridge_cleanup_storage_records(journal)
    proof = _mapping(cleanup.get("bridge_storage_bindings"))
    if set(proof) != set(storage_records):
        raise RuntimeError(
            "recovery-required: durable bridge state and Jail storage proof is incomplete."
        )
    normalized: dict[str, Mapping[str, Any]] = {}
    for label, pair in storage_records.items():
        binding = _mapping(proof.get(label))
        pv_record = pair["pv"]
        pvc_record = pair["pvc"]
        expected_identity = {
            "pv_name": str(pv_record.get("name", "") or ""),
            "pv_uid": str(pv_record.get("uid", "") or ""),
            "pvc_name": str(pvc_record.get("name", "") or ""),
            "pvc_uid": str(pvc_record.get("uid", "") or ""),
        }
        local_path = str(binding.get("local_path", "") or "")
        if (
            set(binding)
            != {
                "pv_name",
                "pv_uid",
                "pvc_name",
                "pvc_uid",
                "reclaim_policy",
                "local_path",
            }
            or any(binding.get(field) != value for field, value in expected_identity.items())
            or binding.get("reclaim_policy") != "Retain"
            or not local_path.startswith("/")
            or (label == "controller_spool" and local_path != "/mnt/controller-spool")
        ):
            raise RuntimeError(
                "recovery-required: durable bridge state or Jail Retain storage proof drifted."
            )
        normalized[label] = binding
    return normalized


def _controller_bridge_slot_label_value(group: Mapping[str, Any]) -> str:
    slot = group.get("slot")
    return "" if slot is None else str(slot)


def _controller_bridge_require_stopped_retained_substrate(
    *,
    journal: Mapping[str, Any],
    target_state: Mapping[str, Any],
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    cleanup = _mapping(journal.get("cleanup"))
    if (
        str(cleanup.get("intent_at", "") or "")
        or _mapping(cleanup.get("kubernetes_operations"))
        or _mapping(cleanup.get("node_group_operations"))
        or cleanup.get("namespace_deleted") is True
        or cleanup.get("bridge_resources_absent") is True
        or any(str(item or "") for item in cleanup.get("node_groups_deleted", []) or [])
    ):
        raise RuntimeError(
            "recovery-required: destructive controller bridge cleanup started before "
            "partition restoration."
        )
    records = _controller_bridge_cleanup_resource_records(journal)
    retained_kinds = {"Namespace", "PersistentVolume", "PersistentVolumeClaim", "StatefulSet"}
    retained = [record for record in records if record.get("kind") in retained_kinds]
    if {str(record.get("kind", "") or "") for record in retained} != retained_kinds:
        raise RuntimeError(
            "Controller bridge partition restore lacks its exact retained substrate bindings."
        )
    for record in retained:
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=record,
        )
        if not exists or str(_mapping(live.get("metadata")).get("uid", "") or "") != str(
            record.get("uid", "") or ""
        ):
            raise SoperatorMigrationPhasePending(
                "partition restoration requires every stopped bridge recovery resource "
                f"to remain available: {record.get('kind')}/{record.get('name')}."
            )
    _controller_bridge_cleanup_verify_bridge_storage(
        journal=journal,
        target_state=target_state,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=CONTROLLER_BRIDGE_NAMESPACE,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    bridge_pods = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            CONTROLLER_BRIDGE_NAMESPACE,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    if (
        not bridge_exists
        or _resource_replicas(bridge_workload, default=-1) != 0
        or _sequence_of_mappings(bridge_pods.get("items"))
    ):
        raise SoperatorMigrationPhasePending(
            "partition restoration requires the retained controller bridge at replicas=0 "
            "with no bridge Pods."
        )
    for group in _sequence_of_mappings(journal.get("node_groups")):
        node_group_id = str(group.get("id", "") or "")
        live_group = _node_group_payload_by_id(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
        )
        labels = _node_group_template_labels(live_group)
        expected_slot = _controller_bridge_slot_label_value(group)
        if (
            not node_group_id
            or _node_group_id(live_group) != node_group_id
            or _node_group_name(live_group) != str(group.get("name", "") or "")
            or _node_group_fixed_count_allow_zero(live_group) != 1
            or labels.get(CONTROLLER_BRIDGE_LABEL) != "true"
            or labels.get(CONTROLLER_BRIDGE_SLOT_LABEL) != expected_slot
        ):
            raise SoperatorMigrationPhasePending(
                "partition restoration requires both exact one-node bridge recovery "
                f"groups to remain available: {node_group_id or '<missing>'}."
            )


def _controller_bridge_delete_exact_kubernetes_resource(
    *,
    cleanup: dict[str, Any],
    identity: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    wait_for_absence: bool = True,
) -> None:
    operations = cleanup.setdefault("kubernetes_operations", {})
    if not isinstance(operations, dict):
        raise RuntimeError("Controller bridge Kubernetes cleanup journal must be mutable.")
    key = _controller_bridge_resource_journal_key(identity)
    operation = operations.setdefault(key, {})
    if not isinstance(operation, dict):
        raise RuntimeError("Controller bridge Kubernetes cleanup operation must be mutable.")
    expected = {
        field: str(identity.get(field, "") or "")
        for field in ("api_version", "kind", "namespace", "name", "uid", "resource_version")
    }
    bound = _mapping(operation.get("identity"))
    if bound and dict(bound) != expected:
        raise RuntimeError("recovery-required: bridge Kubernetes cleanup identity changed.")
    operation.setdefault("identity", expected)
    operation.setdefault("intent_at", _utc_now())
    prior_state = str(operation.setdefault("state", "intent-recorded") or "")
    if checkpoint_writer is not None:
        checkpoint_writer()
    exists, live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity=identity,
    )
    delete_resource_version = str(operation.get("delete_resource_version", "") or "")
    if prior_state == "absent":
        if exists:
            raise RuntimeError(
                "recovery-required: a checkpointed-absent bridge Kubernetes UID reappeared."
            )
        return
    if prior_state in {"dispatching", "delete-accepted"} and not exists:
        operation["state"] = "absent"
        operation.setdefault("absent_at", _utc_now())
        if checkpoint_writer is not None:
            checkpoint_writer()
        return
    if exists:
        live_metadata = _mapping(live.get("metadata"))
        live_uid = str(live_metadata.get("uid", "") or "")
        live_resource_version = str(live_metadata.get("resourceVersion", "") or "")
        deletion_timestamp = str(live_metadata.get("deletionTimestamp", "") or "")
        if live_uid != expected["uid"]:
            raise RuntimeError(
                "recovery-required: bridge cleanup found a replacement Kubernetes resource."
            )
        if not live_resource_version:
            raise RuntimeError(
                "recovery-required: bridge cleanup resource has no live resourceVersion."
            )
        if prior_state in {"dispatching", "delete-accepted"} and deletion_timestamp:
            operation["state"] = "delete-accepted"
            operation.setdefault("accepted_at", _utc_now())
            operation["terminating_at"] = deletion_timestamp
            operation["terminating_resource_version"] = live_resource_version
            prior_state = "delete-accepted"
            if checkpoint_writer is not None:
                checkpoint_writer()
        elif (
            delete_resource_version
            and delete_resource_version != live_resource_version
            and prior_state not in {"intent-recorded", ""}
        ):
            raise RuntimeError(
                "recovery-required: bridge cleanup resourceVersion changed after dispatch "
                "without same-UID termination evidence."
            )
        elif prior_state == "delete-accepted" and not deletion_timestamp:
            raise RuntimeError(
                "recovery-required: bridge cleanup delete was accepted, but the exact UID "
                "is no longer terminating."
            )
        if prior_state != "delete-accepted":
            delete_resource_version = live_resource_version
            operation["delete_resource_version"] = delete_resource_version
    elif not delete_resource_version:
        delete_resource_version = expected["resource_version"]
        operation["delete_resource_version"] = delete_resource_version
    if prior_state != "delete-accepted":
        operation["state"] = "dispatching"
        operation["dispatching_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=_controller_bridge_cleanup_api_path(identity),
            uid=expected["uid"],
            resource_version=delete_resource_version,
            propagation_policy="Background",
            timeout_seconds=300,
            allow_not_found=True,
            wait_for_absence=wait_for_absence,
        )
        operation["state"] = "delete-accepted"
        operation["accepted_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    if not wait_for_absence:
        return
    _wait_for_kubernetes_resource_uid_absent(
        command_runner=command_runner,
        kube_context=kube_context,
        api_path=_controller_bridge_cleanup_api_path(identity),
        uid=expected["uid"],
        timeout_seconds=300,
    )
    operation["state"] = "absent"
    operation["absent_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()


def _controller_bridge_delete_node_groups(
    *,
    checkpoint: dict[str, Any],
    journal: dict[str, Any],
    nebius_api: SoperatorMigrationNebiusApi,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    cleanup = journal.get("cleanup")
    if not isinstance(cleanup, dict):
        raise RuntimeError("Controller bridge cleanup journal must be mutable.")
    operations = cleanup.setdefault("node_group_operations", {})
    if not isinstance(operations, dict):
        raise RuntimeError("Controller bridge node-group cleanup journal must be mutable.")
    deleted = {
        str(item or "") for item in cleanup.get("node_groups_deleted", []) or [] if str(item or "")
    }
    preserved = {
        str(item or "")
        for item in cleanup.get("node_groups_preserved", []) or []
        if str(item or "")
    }
    for record in _sequence_of_mappings(journal.get("node_groups")):
        node_group_id = str(record.get("id", "") or "")
        group_name = str(record.get("name", "") or "")
        slot = _controller_bridge_slot_label_value(record)
        if not node_group_id or not group_name:
            raise RuntimeError("Controller bridge node-group cleanup identity is incomplete.")
        state = operations.setdefault(node_group_id, {})
        if not isinstance(state, dict):
            raise RuntimeError("Controller bridge node-group cleanup operation must be mutable.")
        try:
            live = _node_group_payload_by_id(
                nebius_api=nebius_api,
                node_group_id=node_group_id,
            )
        except Exception as exc:
            if not _sdk_not_found_error(exc):
                raise
            live = {}
        live_id = _node_group_id(live)
        if record.get("cleanup_policy") == "preserve-domain":
            if (
                not live_id
                or live_id != node_group_id
                or _node_group_name(live) != group_name
                or not _node_group_resource_version(live)
            ):
                raise RuntimeError(
                    "recovery-required: managed bridge placement domain changed or "
                    "disappeared during Kubernetes-resource cleanup."
                )
            preserved.add(node_group_id)
            cleanup["node_groups_preserved"] = sorted(preserved)
            if checkpoint_writer is not None:
                checkpoint_writer()
            continue
        if not live_id:
            operation = _mapping(state.get("operation"))
            if operation.get("attempt_state") in _PROVIDER_OPERATION_TERMINAL_STATES:
                deleted.add(node_group_id)
                continue
            if _provider_operation_id_is_real(operation.get("provider_operation_id")):
                _record_reconciled_provider_operation_terminal(
                    checkpoint=checkpoint,
                    resource_state=state,
                    nebius_api=nebius_api,
                    provider_payload={},
                    operation_kind="MK8s bridge node-group delete",
                    resource_id=node_group_id,
                    checkpoint_writer=checkpoint_writer,
                    verified_postcondition={"deleted": True},
                )
                deleted.add(node_group_id)
                continue
            raise RuntimeError(
                "recovery-required: bridge node group is absent without terminal exact "
                f"provider delete evidence: {node_group_id}."
            )
        labels = _node_group_template_labels(live)
        metadata = _mapping(live.get("metadata"))
        if (
            live_id != node_group_id
            or _node_group_name(live) != group_name
            or labels.get(CONTROLLER_BRIDGE_LABEL) != "true"
            or labels.get(CONTROLLER_BRIDGE_SLOT_LABEL) != slot
        ):
            raise RuntimeError(
                "recovery-required: bridge node-group identity or ownership labels changed."
            )
        if state and not _provider_operation_request_is_retryable(state):
            _require_journaled_provider_operation_before_unmet_postcondition(
                resource_state=state,
                nebius_api=nebius_api,
                operation_kind="MK8s bridge node-group delete",
                resource_id=node_group_id,
            )
        operation = _provider_operation_intent_for_request(
            checkpoint=checkpoint,
            resource_state=state,
            operation_kind="mk8s-node-group-delete",
            resource_id=node_group_id,
            resource_uid=str(metadata.get("uid") or metadata.get("id") or node_group_id),
            resource_version=_node_group_resource_version(live),
            intended_postcondition={
                "deleted": True,
                "name": group_name,
                "bridge_slot": int(slot),
            },
            checkpoint_writer=checkpoint_writer,
        )
        _provider_operation_requested(
            checkpoint=checkpoint,
            resource_state=state,
            operation_entry=operation,
            checkpoint_writer=checkpoint_writer,
        )
        try:
            result = _delete_node_group(
                nebius_api=nebius_api,
                node_group_id=node_group_id,
                operation_accepted=_provider_operation_acceptance_callback(
                    checkpoint=checkpoint,
                    resource_state=state,
                    operation_entry=operation,
                    checkpoint_writer=checkpoint_writer,
                ),
            )
            _provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=state,
                operation_entry=operation,
                provider_payload=result,
                operation_kind="MK8s bridge node-group delete",
                resource_id=node_group_id,
                verified_postcondition={"deleted": True},
                checkpoint_writer=checkpoint_writer,
            )
        except (Exception, KeyboardInterrupt) as exc:
            if operation.get("attempt_state") != "provider-terminal":
                _provider_operation_pending(
                    checkpoint=checkpoint,
                    resource_state=state,
                    operation_entry=operation,
                    reason=str(exc),
                    checkpoint_writer=checkpoint_writer,
                )
            raise
        deleted.add(node_group_id)
        cleanup["node_groups_deleted"] = sorted(deleted)
        if checkpoint_writer is not None:
            checkpoint_writer()
    cleanup["node_groups_deleted"] = sorted(deleted)
    cleanup["node_groups_preserved"] = sorted(preserved)
    return sorted(deleted)


def _controller_bridge_cleanup_prove_kubernetes_absent(
    *,
    journal: Mapping[str, Any],
    cleanup: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> None:
    """Prove the exact bridge and inspector Kubernetes resources remain absent."""

    owned_pods = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "pods",
            "-A",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    unexpected_owned_pods = [
        f"{_mapping(item.get('metadata')).get('namespace', '')}/"
        f"{_mapping(item.get('metadata')).get('name', '')}"
        for item in _sequence_of_mappings(owned_pods.get("items"))
    ]
    if unexpected_owned_pods:
        raise RuntimeError(
            "recovery-required: cxcli-owned controller bridge Pods remain after cleanup: "
            + ", ".join(unexpected_owned_pods)
        )
    records = _controller_bridge_cleanup_resource_records(journal)
    bridge_namespaces = [
        item
        for item in records
        if item.get("kind") == "Namespace"
        and item.get("name") == CONTROLLER_BRIDGE_NAMESPACE
        and not item.get("namespace")
    ]
    if len(bridge_namespaces) != 1:
        raise RuntimeError(
            "recovery-required: bridge Kubernetes absence proof lacks its exact Namespace."
        )
    # An absent Namespace is the authoritative absence proof for every object that
    # was bound inside it. Re-reading every namespaced object separately adds many
    # authenticated API round trips and cannot strengthen that Kubernetes invariant.
    # Cluster-scoped resources remain individually name/UID bound below.
    resources_to_probe = [
        bridge_namespaces[0],
        *(
            item
            for item in records
            if not item.get("namespace") and item is not bridge_namespaces[0]
        ),
    ]
    for record in resources_to_probe:
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=record,
        )
        if exists:
            live_uid = str(_mapping(live.get("metadata")).get("uid", "") or "")
            raise RuntimeError(
                "recovery-required: bridge Kubernetes resource remains after cleanup: "
                f"{record.get('kind')}/{record.get('name')} uid={live_uid or 'missing'}."
            )
    expected_resource_keys = {_controller_bridge_resource_journal_key(record) for record in records}
    if set(str(item or "") for item in cleanup.get("kubernetes_resources_deleted", []) or []) != (
        expected_resource_keys
    ):
        raise RuntimeError("recovery-required: bridge Kubernetes absence journal is incomplete.")
    inspector_identity = _mapping(cleanup.get("inspector_namespace_identity"))
    inspector_contract = _mapping(_mapping(journal.get("security_contract")).get("inspector"))
    expected_inspector_identity = {
        "api_version": "v1",
        "kind": "Namespace",
        "namespace": "",
        "name": CONTROLLER_INSPECTOR_NAMESPACE,
        "uid": str(inspector_contract.get("namespace_uid", "") or ""),
        "resource_version": str(inspector_identity.get("resource_version", "") or ""),
    }
    inspector_key = _controller_bridge_resource_journal_key(inspector_identity)
    inspector_operation = _mapping(
        _mapping(cleanup.get("kubernetes_operations")).get(inspector_key)
    )
    if (
        dict(inspector_identity) != expected_inspector_identity
        or not expected_inspector_identity["uid"]
        or not expected_inspector_identity["resource_version"]
        or cleanup.get("inspector_namespace_deleted") is not True
        or str(inspector_operation.get("state", "") or "") != "absent"
        or dict(_mapping(inspector_operation.get("identity"))) != expected_inspector_identity
    ):
        raise RuntimeError(
            "recovery-required: privileged inspector Namespace absence journal is incomplete."
        )
    inspector_exists, inspector_live = _controller_bridge_live_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        identity=inspector_identity,
    )
    if inspector_exists:
        raise RuntimeError(
            "recovery-required: privileged inspector Namespace remains after bridge cleanup: "
            f"uid={_mapping(inspector_live.get('metadata')).get('uid') or 'missing'}."
        )


def _controller_bridge_kubernetes_cleanup_complete(cleanup: Mapping[str, Any]) -> bool:
    return all(
        cleanup.get(field) is True
        for field in (
            "bridge_resources_absent",
            "namespace_deleted",
            "inspector_namespace_deleted",
        )
    )


def _controller_bridge_cleanup_prove_absent(
    *,
    journal: Mapping[str, Any],
    cleanup: Mapping[str, Any],
    target_state: Mapping[str, Any],
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    kubernetes_absence_proven: bool = False,
) -> None:
    if not kubernetes_absence_proven:
        _controller_bridge_cleanup_prove_kubernetes_absent(
            journal=journal,
            cleanup=cleanup,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    group_records = _sequence_of_mappings(journal.get("node_groups"))
    expected_deleted_group_ids = {
        str(item.get("id", "") or "")
        for item in group_records
        if item.get("cleanup_policy") == "delete-domain"
    }
    expected_preserved_group_ids = {
        str(item.get("id", "") or "")
        for item in group_records
        if item.get("cleanup_policy") == "preserve-domain"
    }
    for node_group_id in expected_deleted_group_ids:
        try:
            live_group = _node_group_payload_by_id(
                nebius_api=nebius_api,
                node_group_id=node_group_id,
            )
        except Exception as exc:
            if not _sdk_not_found_error(exc):
                raise
            live_group = {}
        if _node_group_id(live_group):
            raise SoperatorMigrationPhasePending(
                "temporary controller bridge node-group delete is terminal, but live "
                f"absence is not visible yet: {node_group_id}."
            )
    if set(str(item or "") for item in cleanup.get("node_groups_deleted", []) or []) != (
        expected_deleted_group_ids
    ):
        raise RuntimeError("recovery-required: bridge node-group absence journal is incomplete.")
    for node_group_id in expected_preserved_group_ids:
        live_group = _node_group_payload_by_id(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
        )
        if _node_group_id(live_group) != node_group_id:
            raise RuntimeError(
                "recovery-required: managed bridge placement domain disappeared during cleanup."
            )
    if set(str(item or "") for item in cleanup.get("node_groups_preserved", []) or []) != (
        expected_preserved_group_ids
    ):
        raise RuntimeError("recovery-required: bridge preserved-domain journal is incomplete.")
    checkpointed_target = _mapping(cleanup.get("target_state_binding"))
    for field in ("pvc_name", "pvc_uid", "pv_name", "pv_uid", "state_path"):
        if str(checkpointed_target.get(field, "") or "") != str(target_state.get(field, "") or ""):
            raise RuntimeError(
                "recovery-required: target controller state identity changed after bridge cleanup."
            )


def _source_reconciliation_fence_delete_api_path(
    identity: Mapping[str, Any],
) -> str:
    kind = str(identity.get("kind") or "").strip()
    name = str(identity.get("name") or "").strip()
    namespace = str(identity.get("namespace") or "").strip()
    if kind == "ValidatingAdmissionPolicy" and not namespace:
        return f"/apis/admissionregistration.k8s.io/v1/validatingadmissionpolicies/{name}"
    if kind == "ValidatingAdmissionPolicyBinding" and not namespace:
        return f"/apis/admissionregistration.k8s.io/v1/validatingadmissionpolicybindings/{name}"
    if kind == "Role" and namespace == _SOPERATOR_NAMESPACE:
        return f"/apis/rbac.authorization.k8s.io/v1/namespaces/{namespace}/roles/{name}"
    if kind == "RoleBinding" and namespace == _SOPERATOR_NAMESPACE:
        return f"/apis/rbac.authorization.k8s.io/v1/namespaces/{namespace}/rolebindings/{name}"
    raise RuntimeError(
        "source reconciliation fence cleanup found an unsupported exact resource identity."
    )


def _cleanup_source_reconciliation_fence(
    *,
    checkpoint: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    raw_state = phase.get("source_reconciliation_fence")
    if raw_state is None:
        return []
    if (
        not isinstance(raw_state, dict)
        or raw_state.get("schema") != _SOURCE_RECONCILIATION_FENCE_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "final cleanup found a malformed source reconciliation fence journal."
        )
    state = raw_state
    if not str(phase.get("source_cleanup_completed_at") or "").strip():
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence remains active until exact source cleanup completes."
        )
    immutable_handoff = _mapping(phase.get("immutable_child_handoff"))
    if immutable_handoff and str(immutable_handoff.get("status") or "").strip() != "complete":
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence remains active until immutable child handoff completes."
        )
    source = _mapping(state.get("source"))
    exists, live_source = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"slurmcluster/{str(source.get('name') or '')}",
    )
    if exists:
        live_uid = str(_mapping(live_source.get("metadata")).get("uid") or "").strip()
        if live_uid != str(source.get("uid") or "").strip():
            raise RuntimeError(
                "recovery-required: a replacement source SlurmCluster occupies the fenced name."
            )
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence remains active while the exact source SlurmCluster exists."
        )
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence cleanup requires durable checkpoint writes."
        )
    desired_by_kind = {
        str(item.get("kind") or ""): item
        for item in _source_reconciliation_fence_resources(state=state)
    }
    recorded_by_kind = {
        str(item.get("kind") or ""): dict(item)
        for item in _sequence_of_mappings(state.get("managed_resource_bindings"))
    }
    if set(desired_by_kind) != set(recorded_by_kind):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence cleanup lacks every exact managed-resource binding."
        )
    cleanup = state.setdefault("cleanup", {})
    if not isinstance(cleanup, dict):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence cleanup journal must be a mapping."
        )
    operations = cleanup.setdefault("operations", {})
    if not isinstance(operations, dict):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence cleanup operations must be a mapping."
        )
    if not cleanup.get("intent_at"):
        cleanup["intent_at"] = _utc_now()
        checkpoint_writer()
    deletion_order = (
        "RoleBinding",
        "ValidatingAdmissionPolicyBinding",
        "ValidatingAdmissionPolicy",
        "Role",
    )
    for kind in deletion_order:
        desired = desired_by_kind[kind]
        recorded = recorded_by_kind[kind]
        operation = operations.setdefault(kind, {})
        if not isinstance(operation, dict):
            raise SoperatorMigrationPhasePending(
                f"source reconciliation fence cleanup {kind} operation is malformed."
            )
        exists, live = _source_reconciliation_fence_get_managed_resource(
            desired=desired,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if not exists:
            if not operation.get("delete_intent_at"):
                raise SoperatorMigrationPhasePending(
                    f"source reconciliation fence {kind} disappeared before delete intent."
                )
            operation["state"] = "absent"
            operation["absent_at"] = operation.get("absent_at") or _utc_now()
            checkpoint_writer()
            continue
        live_binding = _source_reconciliation_fence_managed_binding(
            desired=desired,
            live=live,
            operation_id=str(state.get("operation_id") or ""),
        )
        if live_binding["uid"] != str(recorded.get("uid") or ""):
            raise RuntimeError(
                f"recovery-required: source reconciliation fence {kind} UID was replaced."
            )
        if not operation.get("delete_intent_at"):
            operation.update(
                {
                    "uid": live_binding["uid"],
                    "resource_version": live_binding["resource_version"],
                    "delete_intent_at": _utc_now(),
                }
            )
            checkpoint_writer()
        elif (
            str(operation.get("uid") or "") != live_binding["uid"]
            or str(operation.get("resource_version") or "") != live_binding["resource_version"]
        ):
            raise RuntimeError(
                f"recovery-required: source reconciliation fence {kind} changed after delete intent."
            )
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=_source_reconciliation_fence_delete_api_path(live_binding),
            uid=live_binding["uid"],
            resource_version=live_binding["resource_version"],
            propagation_policy="Orphan",
            timeout_seconds=120,
            allow_not_found=True,
        )
        exists_after, _live_after = _source_reconciliation_fence_get_managed_resource(
            desired=desired,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if exists_after:
            raise SoperatorMigrationPhasePending(
                f"source reconciliation fence {kind} deletion is not yet visible."
            )
        operation["state"] = "absent"
        operation["absent_at"] = _utc_now()
        checkpoint_writer()
    cleanup["status"] = "complete"
    cleanup["completed_at"] = _utc_now()
    state["status"] = "removed"
    checkpoint_writer()
    return [
        "Source reconciliation fence removed after target-singleton proof and exact source "
        "retirement; admission policy, binding and canary RBAC are absent."
    ]


def _cleanup_controller_bridge_after_final_health(
    *,
    checkpoint: dict[str, Any],
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> tuple[bool, list[str]]:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            "final cleanup requires the v6 controller bridge journal."
        )
    validate_bridge_journal(journal)
    stage = BridgeStage(str(journal.get("stage", "") or ""))
    if stage not in {BridgeStage.PARTITIONS_RESTORED, BridgeStage.CLEANED}:
        raise SoperatorMigrationPhasePending(
            "final cleanup requires restored partition records after target singleton "
            "validation; "
            f"current bridge stage={stage.value}."
        )
    action_journal = _checkpoint_slurm_action_journal_for_job_control(checkpoint)
    _controller_bridge_cleanup_require_target_action_generation(action_journal)
    _controller_bridge_cleanup_required_gates(checkpoint)
    _controller_bridge_require_partition_restore_binding(checkpoint)
    login = _mapping(journal.get("login_session_handoff"))
    if str(login.get("state", "") or "") != "complete":
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup waits indefinitely for voluntary login-session handoff."
        )
    authority = _mapping(journal.get("authority"))
    bridge_fencing = _mapping(_mapping(journal.get("fencing")).get("bridge"))
    if (
        authority.get("owner") != "target-singleton"
        or bridge_fencing.get("proven") is not True
        or bridge_fencing.get("processes_absent") is not True
    ):
        raise SoperatorMigrationPhasePending(
            "controller bridge cleanup requires target authority and a fenced bridge."
        )
    cleanup = journal.get("cleanup")
    if not isinstance(cleanup, dict):
        raise RuntimeError("Controller bridge cleanup journal must be mutable.")
    kubernetes_cleanup_complete = _controller_bridge_kubernetes_cleanup_complete(cleanup)
    if kubernetes_cleanup_complete:
        if cleanup.get("final_singleton_proven") is not True or not _mapping(
            cleanup.get("target_state_binding")
        ):
            raise RuntimeError(
                "recovery-required: bridge Kubernetes cleanup completed without its "
                "durable target-singleton proof."
            )
        _controller_bridge_cleanup_prove_kubernetes_absent(
            journal=journal,
            cleanup=cleanup,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        inspector_namespace = _mapping(cleanup.get("inspector_namespace_identity"))
    else:
        inspector_namespace = _controller_bridge_cleanup_bind_inspector_namespace(
            journal=journal,
            cleanup=cleanup,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    preservation_lines: list[str] = []
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    _revalidate_target_singleton_before_controller_bridge_cleanup(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    target_state = _prove_controller_bridge_cleanup_target_singleton(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        require_cluster_wide_census=not kubernetes_cleanup_complete,
    )
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    records = _controller_bridge_cleanup_resource_records(journal)
    bridge_namespace = next(
        (
            item
            for item in records
            if item.get("kind") == "Namespace" and item.get("name") == CONTROLLER_BRIDGE_NAMESPACE
        ),
        {},
    )
    storage_records = _controller_bridge_cleanup_storage_records(journal)
    bridge_pvcs = [storage_records[label]["pvc"] for label in ("controller_spool", "jail")]
    bridge_pvs = [storage_records[label]["pv"] for label in ("controller_spool", "jail")]
    role_bindings = [
        item
        for item in records
        if item.get("kind") == "RoleBinding" and item.get("namespace") == _SOPERATOR_NAMESPACE
    ]
    priority_classes = [
        item
        for item in records
        if item.get("kind") == "PriorityClass"
        and item.get("name") == "cxcli-soperator-upgrade-bridge"
        and not item.get("namespace")
    ]
    if not bridge_namespace:
        raise RuntimeError("Controller bridge cleanup lacks its exact namespace binding.")
    prior_target_state = _mapping(cleanup.get("target_state_binding"))
    if prior_target_state:
        for field in ("pvc_name", "pvc_uid", "pv_name", "pv_uid", "state_path"):
            if str(prior_target_state.get(field, "") or "") != str(
                target_state.get(field, "") or ""
            ):
                raise RuntimeError(
                    "recovery-required: target state identity changed during bridge cleanup."
                )
    if stage is BridgeStage.CLEANED:
        _controller_bridge_cleanup_require_target_action_generation(action_journal)
        source_fence_lines = _cleanup_source_reconciliation_fence(
            checkpoint=checkpoint,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        _controller_bridge_cleanup_prove_absent(
            journal=journal,
            cleanup=cleanup,
            target_state=target_state,
            kube_context=kube_context,
            nebius_api=nebius_api,
            command_runner=command_runner,
            kubernetes_absence_proven=kubernetes_cleanup_complete,
        )
        return False, [
            *source_fence_lines,
            *preservation_lines,
            "Temporary controller bridge cleanup reused: target singleton, retained state "
            "and exact bridge-resource absence were revalidated.",
        ]
    _controller_bridge_cleanup_required_gates(checkpoint)
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    _controller_bridge_cleanup_require_target_action_generation(action_journal)
    _controller_bridge_cleanup_required_gates(checkpoint)
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    source_fence_lines = _cleanup_source_reconciliation_fence(
        checkpoint=checkpoint,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    cleanup["intent_at"] = str(cleanup.get("intent_at", "") or "") or _utc_now()
    cleanup["target_state_binding"] = target_state
    cleanup["shared_state_retained"] = True
    cleanup["final_singleton_proven"] = True
    if checkpoint_writer is not None:
        checkpoint_writer()
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    operations = cleanup.get("kubernetes_operations")
    if not isinstance(operations, dict):
        raise RuntimeError("Controller bridge Kubernetes cleanup journal must be mutable.")
    namespace_key = _controller_bridge_resource_journal_key(bridge_namespace)
    namespace_operation = _mapping(operations.get(namespace_key))
    namespace_removed = str(namespace_operation.get("state", "") or "") == "absent"
    if cleanup.get("namespace_deleted") is True and not namespace_removed:
        raise RuntimeError(
            "recovery-required: bridge namespace is marked deleted without its exact "
            "UID-preconditioned operation proof."
        )
    if namespace_removed:
        if not str(cleanup.get("bridge_storage_verified_at", "") or ""):
            raise RuntimeError(
                "recovery-required: bridge namespace disappeared before the Retain PV/PVC "
                "separation proof was checkpointed."
            )
        _controller_bridge_cleanup_require_storage_proof(
            journal=journal,
            cleanup=cleanup,
        )
        for pvc_record in bridge_pvcs:
            pvc_operation = _mapping(
                operations.get(_controller_bridge_resource_journal_key(pvc_record))
            )
            if str(pvc_operation.get("state", "") or "") not in {
                "delete-accepted",
                "absent",
            } or dict(_mapping(pvc_operation.get("identity"))) != {
                field: str(pvc_record.get(field, "") or "")
                for field in (
                    "api_version",
                    "kind",
                    "namespace",
                    "name",
                    "uid",
                    "resource_version",
                )
            }:
                raise RuntimeError(
                    "recovery-required: bridge namespace disappeared before both exact "
                    "state and Jail PVC deletions were durably accepted."
                )
        if dict(_mapping(namespace_operation.get("identity"))) != {
            field: str(bridge_namespace.get(field, "") or "")
            for field in (
                "api_version",
                "kind",
                "namespace",
                "name",
                "uid",
                "resource_version",
            )
        }:
            raise RuntimeError(
                "recovery-required: bridge namespace cleanup operation identity drifted."
            )
        namespace_exists, namespace_live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=bridge_namespace,
        )
        if namespace_exists:
            raise RuntimeError(
                "recovery-required: checkpointed-absent bridge namespace reappeared with UID "
                f"{_mapping(namespace_live.get('metadata')).get('uid') or 'missing'}."
            )
        cleanup["namespace_deleted"] = True
    else:
        pvc_operations_started = any(
            _mapping(operations.get(_controller_bridge_resource_journal_key(record)))
            for record in bridge_pvcs
        )
        if _mapping(cleanup.get("bridge_storage_bindings")):
            _controller_bridge_cleanup_require_storage_proof(
                journal=journal,
                cleanup=cleanup,
            )
            if not pvc_operations_started:
                cleanup["bridge_storage_bindings"] = (
                    _controller_bridge_cleanup_verify_bridge_storage(
                        journal=journal,
                        target_state=target_state,
                        kube_context=kube_context,
                        command_runner=command_runner,
                    )
                )
        else:
            if pvc_operations_started:
                raise RuntimeError(
                    "recovery-required: bridge PVC cleanup started without a durable state "
                    "and Jail Retain storage proof."
                )
            cleanup["bridge_storage_bindings"] = _controller_bridge_cleanup_verify_bridge_storage(
                journal=journal,
                target_state=target_state,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        if not pvc_operations_started:
            bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=CONTROLLER_BRIDGE_NAMESPACE,
                resource="statefulset/cxcli-slurm-controller-bridge",
            )
            bridge_pods = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    CONTROLLER_BRIDGE_NAMESPACE,
                    "get",
                    "pods",
                    "-l",
                    f"{CONTROLLER_BRIDGE_LABEL}=true",
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
            if (
                not bridge_exists
                or _resource_replicas(bridge_workload, default=-1) != 0
                or _sequence_of_mappings(bridge_pods.get("items"))
            ):
                raise SoperatorMigrationPhasePending(
                    "controller bridge cleanup requires replicas=0 and no bridge Pods."
                )
        cleanup["bridge_storage_verified_at"] = (
            str(cleanup.get("bridge_storage_verified_at", "") or "") or _utc_now()
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    for role_binding in role_bindings:
        _controller_bridge_delete_exact_kubernetes_resource(
            cleanup=cleanup,
            identity=role_binding,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    for priority_class in priority_classes:
        _controller_bridge_delete_exact_kubernetes_resource(
            cleanup=cleanup,
            identity=priority_class,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    for bridge_pvc in bridge_pvcs:
        _controller_bridge_delete_exact_kubernetes_resource(
            cleanup=cleanup,
            identity=bridge_pvc,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            wait_for_absence=False,
        )
    if not namespace_removed:
        _controller_bridge_delete_exact_kubernetes_resource(
            cleanup=cleanup,
            identity=bridge_namespace,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        cleanup["namespace_deleted"] = True
        if checkpoint_writer is not None:
            checkpoint_writer()
    for bridge_pvc in bridge_pvcs:
        _controller_bridge_delete_exact_kubernetes_resource(
            cleanup=cleanup,
            identity=bridge_pvc,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    for bridge_pv in bridge_pvs:
        _controller_bridge_delete_exact_kubernetes_resource(
            cleanup=cleanup,
            identity=bridge_pv,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    _controller_bridge_delete_exact_kubernetes_resource(
        cleanup=cleanup,
        identity=inspector_namespace,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    cleanup["inspector_namespace_deleted"] = True
    if checkpoint_writer is not None:
        checkpoint_writer()
    deleted_resource_keys: list[str] = []
    for record in records:
        exists, live = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity=record,
        )
        if exists:
            live_uid = str(_mapping(live.get("metadata")).get("uid", "") or "")
            raise RuntimeError(
                "recovery-required: bridge Kubernetes resource remains after cleanup: "
                f"{record.get('kind')}/{record.get('name')} uid={live_uid or 'missing'}."
            )
        deleted_resource_keys.append(_controller_bridge_resource_journal_key(record))
    cleanup["kubernetes_resources_deleted"] = sorted(deleted_resource_keys)
    cleanup["bridge_resources_absent"] = True
    if checkpoint_writer is not None:
        checkpoint_writer()
    deleted_groups = _controller_bridge_delete_node_groups(
        checkpoint=checkpoint,
        journal=journal,
        nebius_api=nebius_api,
        checkpoint_writer=checkpoint_writer,
    )
    expected_deleted_groups = {
        str(item.get("id", "") or "")
        for item in _sequence_of_mappings(journal.get("node_groups"))
        if item.get("cleanup_policy") == "delete-domain"
    }
    expected_preserved_groups = {
        str(item.get("id", "") or "")
        for item in _sequence_of_mappings(journal.get("node_groups"))
        if item.get("cleanup_policy") == "preserve-domain"
    }
    if set(deleted_groups) != expected_deleted_groups:
        raise RuntimeError("Controller bridge cleanup deleted-domain proof is incomplete.")
    if set(cleanup.get("node_groups_preserved", []) or []) != expected_preserved_groups:
        raise RuntimeError("Controller bridge cleanup preserved-domain proof is incomplete.")
    target_state = _prove_controller_bridge_cleanup_target_singleton(
        journal=journal,
        kube_context=kube_context,
        command_runner=command_runner,
        require_cluster_wide_census=False,
    )
    cleanup["target_state_binding"] = target_state
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    _controller_bridge_cleanup_prove_absent(
        journal=journal,
        cleanup=cleanup,
        target_state=target_state,
        kube_context=kube_context,
        nebius_api=nebius_api,
        command_runner=command_runner,
    )
    _controller_bridge_cleanup_require_target_action_generation(action_journal)
    cleanup["proof_checked_at"] = _utc_now()
    cleanup["completed_at"] = _utc_now()
    advance_bridge_stage(journal, BridgeStage.CLEANED)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return True, [
        *source_fence_lines,
        *preservation_lines,
        "Temporary controller bridge removed: exact bridge and privileged-inspector "
        "namespaces, both Retain state/Jail PV/PVC pairs, cross-namespace RBAC and both "
        "temporary node groups are absent.",
        "Final controller proof: one target slurmctld, one SlurmctldHost, replicas=1, "
        "and target shared state retained.",
    ]


def _execute_create_aligned_sfs_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    worker_node_groups: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    project_id = _nebius_project_id(payload)
    specs = _aligned_filesystem_specs(payload=payload, target_ref=target_ref)
    phase = _phase_state(checkpoint, "create-aligned-sfs")
    filesystems = phase.setdefault("filesystems", {})
    if not isinstance(filesystems, dict):
        raise RuntimeError(
            "External Soperator upgrade checkpoint create-aligned-sfs.filesystems must be a mapping."
        )
    mutation_performed = False
    lines: list[str] = []
    for spec in specs:
        existing_state = filesystems.get(spec.key)
        if existing_state is not None and not isinstance(existing_state, dict):
            raise RuntimeError(
                "recovery-required: create-aligned-sfs filesystem journal state for "
                f"{spec.key} must be a mapping."
            )
        resource_state: dict[str, Any] = existing_state if isinstance(existing_state, dict) else {}
        filesystems[spec.key] = resource_state
        existing = _get_filesystem_by_name(
            nebius_api=nebius_api,
            project_id=project_id,
            name=spec.name,
        )
        created = False
        filesystem = existing
        intended_postcondition = {
            "project_id": project_id,
            "name": spec.name,
            "size_gib": spec.size_gib,
            "block_size_kib": spec.block_size_kib,
            "type": spec.filesystem_type,
            "forbid_deletion": spec.forbid_deletion,
        }
        if not _filesystem_id(filesystem):
            if resource_state and not _provider_operation_request_is_retryable(resource_state):
                _require_journaled_provider_operation_before_unmet_postcondition(
                    resource_state=resource_state,
                    nebius_api=nebius_api,
                    operation_kind="compute filesystem create",
                    resource_id=f"{project_id}/filesystems/{spec.name}",
                    verify_resource_identity=False,
                )
            operation_entry = _provider_operation_intent_for_request(
                checkpoint=checkpoint,
                resource_state=resource_state,
                operation_kind="compute-filesystem-create",
                resource_id=f"{project_id}/filesystems/{spec.name}",
                resource_uid=spec.name,
                resource_version=0,
                intended_postcondition=intended_postcondition,
                checkpoint_writer=checkpoint_writer,
            )
            _provider_operation_requested(
                checkpoint=checkpoint,
                resource_state=resource_state,
                operation_entry=operation_entry,
                checkpoint_writer=checkpoint_writer,
            )
            try:
                filesystem = _create_filesystem(
                    nebius_api=nebius_api,
                    project_id=project_id,
                    spec=spec,
                    operation_accepted=_provider_operation_acceptance_callback(
                        checkpoint=checkpoint,
                        resource_state=resource_state,
                        operation_entry=operation_entry,
                        checkpoint_writer=checkpoint_writer,
                    ),
                )
                filesystem_id = _filesystem_id(filesystem)
                if not filesystem_id:
                    raise RuntimeError(
                        f"Aligned SFS filesystem '{spec.name}' did not return a filesystem id."
                    )
                operation_entry["resource_uid"] = str(
                    _filesystem_metadata(filesystem).get("uid") or filesystem_id
                )
                _provider_operation_terminal(
                    checkpoint=checkpoint,
                    resource_state=resource_state,
                    operation_entry=operation_entry,
                    provider_payload=filesystem,
                    operation_kind="compute filesystem create",
                    resource_id=filesystem_id,
                    verified_postcondition={
                        **intended_postcondition,
                        "filesystem_id": filesystem_id,
                    },
                    checkpoint_writer=checkpoint_writer,
                )
            except (Exception, KeyboardInterrupt) as exc:
                if operation_entry.get("attempt_state") != "provider-terminal":
                    _provider_operation_pending(
                        checkpoint=checkpoint,
                        resource_state=resource_state,
                        operation_entry=operation_entry,
                        reason=str(exc),
                        checkpoint_writer=checkpoint_writer,
                    )
                raise
            created = True
            mutation_performed = True
        else:
            _validate_existing_filesystem(spec, filesystem)
        filesystem_id = _filesystem_id(filesystem)
        if not filesystem_id:
            raise RuntimeError(
                f"Aligned SFS filesystem '{spec.name}' did not return a filesystem id."
            )
        if _provider_operation_is_pre_request_intent(resource_state):
            _discard_pre_request_provider_intent(
                checkpoint=checkpoint,
                resource_state=resource_state,
                checkpoint_writer=checkpoint_writer,
            )
        operation = _mapping(resource_state.get("operation"))
        if operation.get(
            "attempt_state"
        ) not in _PROVIDER_OPERATION_TERMINAL_STATES and _provider_operation_id_is_real(
            operation.get("provider_operation_id")
        ):
            _record_reconciled_provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=resource_state,
                nebius_api=nebius_api,
                provider_payload=filesystem,
                operation_kind="compute filesystem create",
                resource_id=filesystem_id,
                checkpoint_writer=checkpoint_writer,
                verified_postcondition={
                    **intended_postcondition,
                    "filesystem_id": filesystem_id,
                },
            )
        checkpointed_id = str(resource_state.get("id", "") or "").strip()
        if checkpointed_id and checkpointed_id != filesystem_id:
            raise RuntimeError(
                "recovery-required: aligned SFS filesystem identity changed for "
                f"{spec.name}: journal={checkpointed_id}, live={filesystem_id}."
            )
        checkpointed_created = resource_state.get("created")
        if checkpointed_created is None and resource_state:
            operation = _mapping(resource_state.get("operation"))
            if operation.get("attempt_state") in _PROVIDER_OPERATION_TERMINAL_STATES and (
                _provider_operation_id_is_real(operation.get("provider_operation_id"))
            ):
                checkpointed_created = True
            else:
                raise RuntimeError(
                    "recovery-required: live aligned SFS filesystem exists, but its "
                    f"journal binding is incomplete and has no terminal create operation: "
                    f"{spec.name}."
                )
        if checkpointed_created is True:
            operation = _mapping(resource_state.get("operation"))
            if operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES or not (
                _provider_operation_id_is_real(operation.get("provider_operation_id"))
            ):
                raise RuntimeError(
                    "recovery-required: aligned SFS filesystem exists, but its cxcli create "
                    f"operation is not terminal in the v6 journal: {spec.name}."
                )
        elif checkpointed_created is False and created:
            raise RuntimeError(
                "recovery-required: aligned SFS journal marks a reused filesystem, but "
                f"this invocation created {spec.name}."
            )
        resource_state.update(
            {
                "id": filesystem_id,
                "name": spec.name,
                "mount_tag": spec.mount_tag,
                "size_gib": spec.size_gib,
                "block_size_kib": spec.block_size_kib,
                "type": spec.filesystem_type,
                "created": bool(checkpointed_created)
                if checkpointed_created is not None
                else created,
                "bound_at": resource_state.get("bound_at") or _utc_now(),
            }
        )
        filesystems[spec.key] = resource_state
        if checkpoint_writer is not None:
            checkpoint_writer()
        lines.append(
            f"Aligned SFS {spec.key}: {'created' if created else 'reused'} {spec.name} ({filesystem_id})"
        )
    phase["source_node_group_attachments"] = "deferred-to-new-node-group-creation"
    lines.append(
        "Aligned SFS source node-group attachments: deferred; bridge and target node groups "
        "receive filesystems at creation time, so no source node is rolled before controller HA."
    )
    return mutation_performed, lines


def _execute_online_bulk_data_sync_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, "online-bulk-data-sync")
    jobs = phase.setdefault("jobs", {})
    if not isinstance(jobs, dict):
        raise RuntimeError(
            "External Soperator upgrade checkpoint online-bulk-data-sync.jobs must be a mapping."
        )
    storage = _snapshot_storage(source_report)
    if not storage:
        phase["skipped_reason"] = "source discovery did not detect old Soperator storage"
        return False, ["Data sync skipped: no old Soperator storage was detected."]
    mutation_performed = False
    lines: list[str] = []
    manifests: list[dict[str, Any]] = []
    live_pvcs = _snapshot_pvc_names(live_snapshot)
    missing_pvcs: list[str] = []
    for key in _soperator_storage_keys_for_target(payload=payload, target_ref=target_ref):
        source_pvc = _source_pvc_name_for_storage_key(source_report, key)
        target_pvc = _target_pvc_name_for_storage_key(payload, target_ref, key)
        if not source_pvc:
            continue
        for pvc_name, role in ((source_pvc, "source"), (target_pvc, "target")):
            if pvc_name not in live_pvcs:
                missing_pvcs.append(f"{role}:{key}:{pvc_name}")
        if source_pvc == target_pvc:
            jobs[key] = {"source_pvc": source_pvc, "target_pvc": target_pvc, "skipped": True}
            lines.append(
                f"Data sync {key}: skipped because source and target PVC are {source_pvc}."
            )
            continue
        source_path, target_path = _copy_job_paths_for_storage_key(
            payload=payload,
            target_ref=target_ref,
            key=key,
        )
        manifests.append(
            _copy_job_manifest(
                key=key,
                source_pvc=source_pvc,
                target_pvc=target_pvc,
                source_path=source_path,
                target_path=target_path,
            )
        )
        jobs[key] = {
            "source_pvc": source_pvc,
            "target_pvc": target_pvc,
            "source_path": source_path,
            "target_path": target_path,
        }
    if missing_pvcs:
        phase["missing_pvcs"] = missing_pvcs
        raise SoperatorMigrationPhasePending(
            "online-bulk-data-sync requires existing source and target PVCs before copy Jobs run. "
            "Missing PVCs: " + ", ".join(missing_pvcs) + "."
        )
    if not manifests:
        phase["skipped_reason"] = "no source PVC to target PVC copy pairs were detected"
        return False, lines or ["Data sync skipped: no PVC copy pairs were detected."]
    for manifest in manifests:
        name = str(_mapping(manifest.get("metadata")).get("name", "") or "").strip()
        if name:
            _delete_failed_job_before_reapply(
                command_runner=command_runner,
                kube_context=kube_context,
                name=name,
            )
    _kubectl_apply_objects(
        command_runner=command_runner,
        kube_context=kube_context,
        objects=manifests,
        timeout_seconds=300,
    )
    mutation_performed = True
    for manifest in manifests:
        name = str(_mapping(manifest.get("metadata")).get("name", "") or "").strip()
        if not name:
            continue
        _wait_for_job_complete_or_failed(
            command_runner=command_runner,
            kube_context=kube_context,
            name=name,
            timeout_seconds=3900,
        )
        lines.append(f"Data sync job completed: {name}")
    return mutation_performed, lines


def _accounting_handoff_state(phase: dict[str, Any]) -> dict[str, Any]:
    state = phase.setdefault("accounting_handoff", {})
    if not isinstance(state, dict):
        state = {}
        phase["accounting_handoff"] = state
    return state


def _accounting_handoff_waits_for_target_config_restore(phase: Mapping[str, Any]) -> bool:
    accounting = _mapping(phase.get("accounting_handoff"))
    immutable = _mapping(phase.get("immutable_child_handoff"))
    bridge = _mapping(phase.get("legacy_rootfs_slurm_config_bridge"))
    immutable_status = str(immutable.get("status") or "").strip()
    accounting_status = str(accounting.get("status") or "").strip()
    manager_restore_pending = immutable_status in {"manager-paused", "children-prepared"}
    target_config_pulse_pending = bool(
        accounting_status == "target-enabled"
        and immutable_status == "manager-restored"
        and str(bridge.get("status") or "").strip()
        not in {"target-compatibility-active", "released"}
    )
    return bool(
        str(phase.get("source_accounting_owner_retired_at") or "").strip()
        and (manager_restore_pending or target_config_pulse_pending)
    )


def _source_accounting_handoff_required(
    *,
    checkpoint: Mapping[str, Any],
    source_report: Mapping[str, Any],
) -> bool:
    backup = _mapping(checkpoint.get("backup"))
    if backup.get("accounting_db_dump") is True:
        return True
    snapshot = _mapping(source_report.get("snapshot"))
    for key in ("pvcs", "pods", "statefulsets", "soperator_namespace_resources"):
        for resource in _sequence_of_mappings(snapshot.get(key)):
            metadata = _mapping(resource.get("metadata"))
            name = str(metadata.get("name", "") or "").strip()
            kind = str(resource.get("kind", "") or "").strip().lower()
            if name.startswith("storage-") and name.endswith("-acct-db-0"):
                return True
            if name.endswith("-acct-db-0") and kind in {"", "pod"}:
                return True
            if name.endswith("-acct-db") and kind in {"statefulset", "mariadb"}:
                return True
    return False


def _accounting_handoff_cluster_name(value: Any, *, label: str) -> str:
    name = str(value or "").strip()
    if not re.fullmatch(r"[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?", name):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff cannot use the {label} cluster name {name!r}; "
            "the name must be a DNS-compatible Slurm cluster identifier."
        )
    return name


def _accounting_handoff_source_resource_name(
    source_report: Mapping[str, Any],
    *,
    target_ref: str,
) -> str:
    source = _source_slurmcluster_resource(source_report, target_ref=target_ref)
    return _accounting_handoff_cluster_name(
        _mapping(source.get("metadata")).get("name"),
        label="source SlurmCluster resource",
    )


def _accounting_handoff_target_cluster_name(
    values: Mapping[str, Any],
    *,
    target_ref: str,
) -> str:
    return _accounting_handoff_cluster_name(
        values.get("clusterName") or target_ref,
        label="target",
    )


def _accounting_handoff_mariadb_pod_identity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    expected_slurmcluster_binding: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    pod = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod",
            pod_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = _mapping(pod.get("metadata"))
    if (
        str(metadata.get("name", "") or "").strip() != pod_name
        or str(metadata.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff requires MariaDB pod {_SOPERATOR_NAMESPACE}/{pod_name}, "
            "but that exact pod is unavailable."
        )
    uid = str(metadata.get("uid", "") or "").strip()
    if not uid:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff could not bind MariaDB pod {_SOPERATOR_NAMESPACE}/{pod_name} "
            "to an immutable UID."
        )
    if not pod_name.endswith("-0"):
        raise SoperatorMigrationPhasePending(
            "accounting handoff MariaDB Pod name does not identify ordinal zero."
        )
    database_name = pod_name[:-2]
    pod_owners = _validated_resource_owner_references(
        pod,
        label=f"Accounting MariaDB Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
    )
    pod_controller_owners = tuple(owner for owner in pod_owners if owner.get("controller") is True)
    if (
        len(pod_controller_owners) != 1
        or str(pod_controller_owners[0].get("apiVersion") or "").strip() != "apps/v1"
        or str(pod_controller_owners[0].get("kind") or "").strip() != "StatefulSet"
        or str(pod_controller_owners[0].get("name") or "").strip() != database_name
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff MariaDB Pod is not controlled by its exact StatefulSet."
        )
    statefulset = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulset.apps",
            database_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    statefulset_identity = _validated_namespaced_resource_identity(
        statefulset,
        expected_api_version="apps/v1",
        expected_kind="StatefulSet",
        label="Accounting MariaDB StatefulSet",
    )
    if statefulset_identity["uid"] != str(pod_controller_owners[0].get("uid") or "").strip():
        raise SoperatorMigrationPhasePending(
            "accounting handoff MariaDB Pod controller UID does not match its live StatefulSet."
        )
    statefulset_owners = _validated_resource_owner_references(
        statefulset,
        label=f"Accounting MariaDB StatefulSet {_SOPERATOR_NAMESPACE}/{database_name}",
    )
    statefulset_controller_owners = tuple(
        owner for owner in statefulset_owners if owner.get("controller") is True
    )
    if (
        len(statefulset_controller_owners) != 1
        or str(statefulset_controller_owners[0].get("apiVersion") or "").strip()
        != "k8s.mariadb.com/v1alpha1"
        or str(statefulset_controller_owners[0].get("kind") or "").strip() != "MariaDB"
        or str(statefulset_controller_owners[0].get("name") or "").strip() != database_name
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff MariaDB StatefulSet is not controlled by its exact MariaDB CR."
        )
    mariadb = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "mariadb.k8s.mariadb.com",
            database_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    mariadb_identity = _validated_namespaced_resource_identity(
        mariadb,
        expected_api_version="k8s.mariadb.com/v1alpha1",
        expected_kind="MariaDB",
        label="Accounting MariaDB CR",
    )
    if mariadb_identity["uid"] != str(statefulset_controller_owners[0].get("uid") or "").strip():
        raise SoperatorMigrationPhasePending(
            "accounting handoff StatefulSet owner UID does not match its live MariaDB CR."
        )
    mariadb_owners = _validated_resource_owner_references(
        mariadb,
        label=f"Accounting MariaDB CR {_SOPERATOR_NAMESPACE}/{database_name}",
    )
    mariadb_controller_owners = tuple(
        owner for owner in mariadb_owners if owner.get("controller") is True
    )
    if (
        len(mariadb_controller_owners) != 1
        or str(mariadb_controller_owners[0].get("kind") or "").strip().lower() != "slurmcluster"
        or str(mariadb_controller_owners[0].get("apiVersion") or "").strip()
        not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff MariaDB CR lacks one exact SlurmCluster controller owner."
        )
    expected_binding = _mapping(expected_slurmcluster_binding)
    if expected_binding and (
        str(expected_binding.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
        or str(mariadb_controller_owners[0].get("name") or "").strip()
        != str(expected_binding.get("name") or "").strip()
        or str(mariadb_controller_owners[0].get("uid") or "").strip()
        != str(expected_binding.get("uid") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff MariaDB owner does not match the exact checkpointed SlurmCluster."
        )
    claim_name = ""
    for volume in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes")):
        if str(volume.get("name", "") or "").strip() != "storage":
            continue
        claim_name = str(
            _mapping(volume.get("persistentVolumeClaim")).get("claimName", "") or ""
        ).strip()
        if claim_name:
            break
    if not claim_name:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff MariaDB pod {_SOPERATOR_NAMESPACE}/{pod_name} does not "
            "have an exact storage PVC binding."
        )
    pvc = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pvc",
            claim_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    pvc_metadata = _mapping(pvc.get("metadata"))
    pvc_uid = str(pvc_metadata.get("uid", "") or "").strip()
    if (
        str(pvc_metadata.get("name", "") or "").strip() != claim_name
        or str(pvc_metadata.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
        or str(_mapping(pvc.get("status")).get("phase") or "").strip() != "Bound"
        or not pvc_uid
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff could not bind MariaDB storage PVC "
            f"{_SOPERATOR_NAMESPACE}/{claim_name} to an immutable UID."
        )
    return {
        "pod": pod_name,
        "pod_uid": uid,
        "statefulset": database_name,
        "statefulset_uid": statefulset_identity["uid"],
        "mariadb": database_name,
        "mariadb_uid": mariadb_identity["uid"],
        "slurmcluster": str(mariadb_controller_owners[0].get("name") or "").strip(),
        "slurmcluster_uid": str(mariadb_controller_owners[0].get("uid") or "").strip(),
        "pvc": claim_name,
        "pvc_uid": pvc_uid,
    }


def _accounting_handoff_deployment_state(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    allow_missing: bool = False,
) -> dict[str, Any]:
    command = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        _SOPERATOR_NAMESPACE,
        "get",
        "deployment",
        "accounting",
        "-o",
        "json",
    ]
    result = command_runner(
        command,
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        if allow_missing and _kubectl_get_deployment_not_found(
            result,
            deployment="accounting",
            namespace=_SOPERATOR_NAMESPACE,
        ):
            return {"exists": False}
        raise RuntimeError(
            "accounting handoff could not inspect the exact soperator/accounting "
            f"Deployment: {_command_detail(result)}"
        )
    try:
        deployment = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError("accounting handoff Deployment lookup returned invalid JSON.") from exc
    if not isinstance(deployment, Mapping):
        raise RuntimeError("accounting handoff Deployment lookup returned a non-object payload.")
    metadata = _mapping(deployment.get("metadata"))
    if str(metadata.get("name", "") or "").strip() != "accounting":
        raise SoperatorMigrationPhasePending(
            "accounting handoff requires the chart-managed soperator/accounting "
            "Deployment, but it is unavailable."
        )
    uid = str(metadata.get("uid", "") or "").strip()
    if not uid:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not bind the soperator/accounting Deployment "
            "to an immutable UID."
        )
    resource_version = str(metadata.get("resourceVersion", "") or "").strip()
    owner_uids = {
        str(owner.get("uid", "") or "").strip()
        for owner in _sequence_of_mappings(metadata.get("ownerReferences"))
        if str(owner.get("kind", "") or "").strip().lower() == "slurmcluster"
        and owner.get("controller") is True
        and str(owner.get("uid", "") or "").strip()
    }
    if len(owner_uids) > 1:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found multiple controller SlurmCluster owners on the "
            "soperator/accounting Deployment."
        )
    status = _mapping(deployment.get("status"))
    spec = _mapping(deployment.get("spec"))
    return {
        "exists": True,
        "uid": uid,
        "resource_version": resource_version,
        "owner_uid": next(iter(owner_uids), ""),
        "generation": _non_negative_int(metadata.get("generation"), fallback=0),
        "replicas": _non_negative_int(spec.get("replicas"), fallback=1),
        "selector": dict(_mapping(_mapping(spec.get("selector")).get("matchLabels"))),
        "strategy_type": str(_mapping(spec.get("strategy")).get("type") or "").strip(),
        "template_containers": list(
            _sequence_of_mappings(
                _mapping(_mapping(spec.get("template")).get("spec")).get("containers")
            )
        ),
        "status_replicas": _non_negative_int(status.get("replicas"), fallback=0),
        "observed_generation": _non_negative_int(status.get("observedGeneration"), fallback=0),
        "updated_replicas": _non_negative_int(status.get("updatedReplicas"), fallback=0),
        "available_replicas": _non_negative_int(status.get("availableReplicas"), fallback=0),
        "ready_replicas": _non_negative_int(status.get("readyReplicas"), fallback=0),
        "unavailable_replicas": _non_negative_int(status.get("unavailableReplicas"), fallback=0),
    }


def _accounting_handoff_assert_source_pvc_identity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    expected: Mapping[str, Any],
) -> None:
    pvc_name = str(expected.get("pvc") or "").strip()
    pvc_uid = str(expected.get("pvc_uid") or "").strip()
    if not pvc_name or not pvc_uid:
        raise SoperatorMigrationPhasePending("accounting handoff source PVC binding is incomplete.")
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pvc",
            pvc_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff retained source MariaDB PVC is unavailable."
        )
    try:
        pvc = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError("accounting handoff source PVC lookup returned invalid JSON.") from exc
    metadata = _mapping(_mapping(pvc).get("metadata"))
    phase = str(_mapping(_mapping(pvc).get("status")).get("phase") or "").strip()
    if (
        str(metadata.get("name") or "").strip() != pvc_name
        or str(metadata.get("namespace") or _SOPERATOR_NAMESPACE).strip() != _SOPERATOR_NAMESPACE
        or str(metadata.get("uid") or "").strip() != pvc_uid
        or phase != "Bound"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff retained source MariaDB PVC no longer matches its exact "
            "namespace/name/UID/Bound binding."
        )


def _accounting_handoff_optional_mariadb_pod_identity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    expected_slurmcluster_binding: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod",
            pod_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        if _kubectl_get_pod_not_found(
            result,
            pod=pod_name,
            namespace=_SOPERATOR_NAMESPACE,
        ):
            return None
        raise RuntimeError(
            "accounting handoff could not inspect the exact source MariaDB Pod: "
            + _command_detail(result)
        )
    return _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        expected_slurmcluster_binding=expected_slurmcluster_binding,
    )


def _accounting_handoff_reuse_sealed_source_dump(
    *,
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    expected_fence_resource_versions: Sequence[str] = (),
    phase: Mapping[str, Any] | None = None,
) -> str | None:
    seal = state.get("source_dump_seal")
    if not isinstance(seal, dict):
        return None
    if (
        seal.get("schema") != _ACCOUNTING_HANDOFF_SOURCE_DUMP_SEAL_SCHEMA
        or seal.get("mode") != "dual-slurmdbd-command-fence"
        or str(seal.get("status") or "") != "sealed"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff final source dump seal is incomplete."
        )
    dump = _mapping(state.get("dump"))
    observed_dump = _accounting_handoff_dump_metadata(Path(str(dump.get("path") or "")))
    if (
        str(seal.get("dump_sha256") or "") != str(dump.get("sha256") or "")
        or _non_negative_int(seal.get("dump_generation"), fallback=0)
        != _non_negative_int(state.get("source_dump_generation"), fallback=0)
        or any(observed_dump.get(key) != dump.get(key) for key in ("size_bytes", "sha256"))
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff sealed source dump no longer matches its immutable binding."
        )
    source = _mapping(state.get("source"))
    target = _mapping(state.get("target"))
    if (
        str(seal.get("source_pvc") or "") != str(source.get("pvc") or "")
        or str(seal.get("source_pvc_uid") or "") != str(source.get("pvc_uid") or "")
        or str(seal.get("target_pvc") or "") != str(target.get("pvc") or "")
        or str(seal.get("target_pvc_uid") or "") != str(target.get("pvc_uid") or "")
        or _mapping(seal.get("source_history")) != _mapping(state.get("source_history"))
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff final source dump seal changed its PVC or history binding."
        )
    _accounting_handoff_assert_source_pvc_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        expected=source,
    )
    _accounting_handoff_assert_source_pvc_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        expected=target,
    )
    source_resource_name = _accounting_handoff_cluster_name(
        state.get("source_resource_name"),
        label="source SlurmCluster resource",
    )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    source_retired = bool(
        phase is not None
        and _accounting_handoff_source_retirement_checkpoint_is_exact(
            phase=phase,
            state=state,
            source_binding=source_binding,
        )
    )
    if source_retired:
        if expected_fence_resource_versions:
            raise SoperatorMigrationPhasePending(
                "accounting handoff cannot migrate live dual-fence resource versions after "
                "exact source retirement."
            )
        if (
            _accounting_handoff_optional_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=source_binding,
                label="retired sealed-dump source",
            )
            is not None
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff retired source SlurmCluster reappeared while "
                "revalidating the sealed dump."
            )
        _accounting_handoff_wait_target_command_fence_after_source_retirement(
            phase=phase,
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            target_pod=f"{target_resource_name}-acct-db-0",
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    elif expected_fence_resource_versions:
        expected_versions = tuple(
            str(item or "").strip() for item in expected_fence_resource_versions
        )
        if len(expected_versions) != 2 or not all(expected_versions):
            raise SoperatorMigrationPhasePending(
                "accounting handoff sealed source dump has malformed exact fence "
                "resourceVersion expectations."
            )
        for binding, expected_version, label in zip(
            (source_binding, target_binding),
            expected_versions,
            ("source", "target"),
            strict=True,
        ):
            resource, resource_version, enabled = _accounting_handoff_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=binding,
                label=f"{label} v1 fence migration",
            )
            if (
                resource_version != expected_version
                or not enabled
                or not _accounting_handoff_writer_command_is_fenced(resource)
            ):
                raise SoperatorMigrationPhasePending(
                    f"accounting handoff {label} live SlurmDBD fence no longer matches "
                    "the exact sealed v1 resourceVersion and canonical command."
                )
    if not source_retired:
        _accounting_handoff_wait_writer_command_fences(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            source_pod=f"{source_resource_name}-acct-db-0",
            target_pod=f"{target_resource_name}-acct-db-0",
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    source_policy = _mapping(state.get("source_cluster_policy"))
    sealed_policy_sha256 = str(seal.get("source_cluster_policy_sha256") or "").strip()
    observed_source_policy = _accounting_handoff_source_cluster_policy_projection(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=f"{source_resource_name}-acct-db-0",
        cluster_name=_accounting_handoff_cluster_name(
            state.get("source_cluster_name"),
            label="source",
        ),
    )
    if not source_policy and not sealed_policy_sha256:
        source_policy = observed_source_policy
        state["source_cluster_policy"] = source_policy
        seal["source_cluster_policy_sha256"] = source_policy["proof_sha256"]
        seal["source_cluster_policy_migrated_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif (
        not source_policy
        or not sealed_policy_sha256
        or sealed_policy_sha256 != str(source_policy.get("proof_sha256") or "")
        or dict(source_policy) != observed_source_policy
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff final source dump seal changed its cluster-policy binding."
        )
    return "Accounting history handoff reused the dual-command-fenced sealed final source DB dump."


def _accounting_handoff_wait_for_mariadb_pod(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    timeout_seconds: int = 900,
    poll_interval_seconds: int = 5,
) -> None:
    pod_command = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        _SOPERATOR_NAMESPACE,
        "get",
        "pod",
        pod_name,
        "-o",
        "json",
    ]
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        remaining_seconds = max(deadline - time.monotonic(), 0.0)
        result = command_runner(
            pod_command,
            timeout_seconds=max(1, min(120, math.ceil(remaining_seconds))),
            check=False,
        )
        if result.returncode == 0:
            try:
                pod = json.loads(result.stdout or "{}")
            except json.JSONDecodeError as exc:
                raise RuntimeError(
                    "accounting handoff target MariaDB pod lookup returned invalid JSON."
                ) from exc
            if not isinstance(pod, Mapping):
                raise RuntimeError(
                    "accounting handoff target MariaDB pod lookup returned a non-object payload."
                )
            metadata = _mapping(pod.get("metadata"))
            if (
                str(metadata.get("name", "") or "").strip() != pod_name
                or str(metadata.get("namespace", "") or "").strip() != _SOPERATOR_NAMESPACE
            ):
                raise RuntimeError(
                    "accounting handoff target MariaDB pod lookup did not return the exact "
                    f"{_SOPERATOR_NAMESPACE}/{pod_name} identity."
                )
            break
        if not _kubectl_get_pod_not_found(
            result,
            pod=pod_name,
            namespace=_SOPERATOR_NAMESPACE,
        ):
            raise RuntimeError(
                "accounting handoff could not observe the exact target MariaDB pod "
                f"{_SOPERATOR_NAMESPACE}/{pod_name}: {_command_detail(result)}"
            )
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting handoff target MariaDB pod "
                f"{_SOPERATOR_NAMESPACE}/{pod_name} did not appear within the bounded wait."
            )
        remaining_seconds = max(deadline - time.monotonic(), 0.0)
        time.sleep(min(max(poll_interval_seconds, 1), remaining_seconds))

    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "wait",
            "--for=condition=Ready",
            f"pod/{pod_name}",
            "--timeout=15m",
        ],
        timeout_seconds=1020,
    )


_ACCOUNTING_HANDOFF_CLIENT_PREAMBLE = (
    "set -euo pipefail; "
    'test -n "${MARIADB_ROOT_PASSWORD:-}"; '
    'defaults_file="$(mktemp)"; '
    "trap 'rm -f \"$defaults_file\"' EXIT; "
    'chmod 600 "$defaults_file"; '
    'printf "[client]\\nuser=root\\npassword=%s\\n" "$MARIADB_ROOT_PASSWORD" > "$defaults_file"; '
)


def _accounting_handoff_database_query(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    sql: str,
    timeout_seconds: int = 300,
) -> str:
    command = (
        _ACCOUNTING_HANDOFF_CLIENT_PREAMBLE
        + "client_bin=$(command -v mariadb || command -v mysql); "
        + 'test -n "$client_bin"; '
        + '"$client_bin" --defaults-extra-file="$defaults_file" '
        + "--skip-force --skip-reconnect --raw -N -B "
        + f"-e {shlex.quote(sql)}"
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "--",
            "bash",
            "-lc",
            command,
        ],
        timeout_seconds=timeout_seconds,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff database query failed; SQL stdout/stderr was redacted "
            f"(exit {result.returncode})."
        )
    return result.stdout


def _accounting_handoff_registered_clusters(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> tuple[str, ...]:
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=("SELECT name FROM slurm_acct_db.cluster_table WHERE deleted=0 ORDER BY name;"),
    )
    names = tuple(
        _accounting_handoff_cluster_name(line, label="registered")
        for raw_line in output.splitlines()
        if (line := raw_line.strip())
    )
    if len(names) != len(set(names)):
        raise SoperatorMigrationPhasePending(
            "accounting handoff found duplicate active Slurm cluster registrations."
        )
    return names


def _accounting_handoff_registered_cluster_ids(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> dict[str, int]:
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=("SELECT name,id FROM slurm_acct_db.cluster_table WHERE deleted=0 ORDER BY name;"),
    )
    result: dict[str, int] = {}
    for line in output.splitlines():
        if not line.strip():
            continue
        fields = line.split("\t")
        if len(fields) != 2 or not fields[1].isdecimal():
            raise SoperatorMigrationPhasePending(
                "accounting handoff found a malformed active Slurm cluster ID projection."
            )
        name = _accounting_handoff_cluster_name(fields[0], label="registered ID")
        cluster_id = int(fields[1])
        if name in result or not 2 <= cluster_id <= 4095:
            raise SoperatorMigrationPhasePending(
                "accounting handoff found duplicate names or an invalid active Slurm cluster ID."
            )
        result[name] = cluster_id
    if len(set(result.values())) != len(result):
        raise SoperatorMigrationPhasePending(
            "accounting handoff found duplicate active Slurm cluster IDs."
        )
    return result


def _accounting_handoff_source_cluster_policy_projection(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    cluster_name: str,
) -> dict[str, Any]:
    cluster_name = _accounting_handoff_cluster_name(cluster_name, label="source policy")
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=(
            "SELECT id,classification,dimensions,flags,fed_id,fed_state,"
            "COALESCE(federation,''),COALESCE(features,'') "
            "FROM slurm_acct_db.cluster_table "
            f"WHERE name='{cluster_name}' AND deleted=0;"
        ),
    )
    rows = [line.split("\t") for line in output.splitlines() if line.strip()]
    if len(rows) != 1 or len(rows[0]) != 8 or not all(value.isdecimal() for value in rows[0][:6]):
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not capture one exact source cluster policy projection."
        )
    projection = {
        "cluster_id": int(rows[0][0]),
        "classification": int(rows[0][1]),
        "dimensions": int(rows[0][2]),
        "flags": int(rows[0][3]),
        "federation_id": int(rows[0][4]),
        "federation_state": int(rows[0][5]),
        "federation": rows[0][6],
        "features": rows[0][7],
    }
    if not 2 <= projection["cluster_id"] <= 4095:
        raise SoperatorMigrationPhasePending(
            "accounting handoff source cluster has an invalid internal Slurm cluster ID."
        )
    defaults = {
        "classification": 0,
        "dimensions": 1,
        "flags": 0,
        "federation_id": 0,
        "federation_state": 0,
        "federation": "",
        "features": "",
    }
    unsupported = [
        key for key, value in projection.items() if key != "cluster_id" and value != defaults[key]
    ]
    if unsupported:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found non-default source cluster policy metadata that "
            "cannot yet be transferred safely through target-version sacctmgr: "
            + ", ".join(sorted(unsupported))
            + "."
        )
    structural = {
        "schema": "nebius-cxcli-accounting-source-cluster-policy/v1",
        "cluster_name": cluster_name,
        **projection,
    }
    structural["proof_sha256"] = _fingerprint(structural)
    return structural


def _accounting_handoff_source_cluster_name(
    source_report: Mapping[str, Any],
    *,
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    source_pod: str,
) -> str:
    source = _source_slurmcluster_resource(source_report, target_ref=target_ref)
    declared_raw = str(_mapping(source.get("spec")).get("clusterName", "") or "").strip()
    declared = (
        _accounting_handoff_cluster_name(declared_raw, label="source spec.clusterName")
        if declared_raw
        else ""
    )
    registered = _accounting_handoff_registered_clusters(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
    )
    if declared:
        if registered != (declared,):
            observed = ", ".join(registered) if registered else "none"
            raise SoperatorMigrationPhasePending(
                "accounting handoff requires exactly one active source slurm_acct_db "
                "registration matching SlurmCluster.spec.clusterName "
                f"(declared={declared}; active={observed})."
            )
        return declared
    if len(registered) != 1:
        observed = ", ".join(registered) if registered else "none"
        raise SoperatorMigrationPhasePending(
            "accounting handoff source SlurmCluster does not declare spec.clusterName, "
            "and its database does not contain exactly one active cluster registration "
            f"(active={observed})."
        )
    return registered[0]


def _accounting_handoff_dump_source_database(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> str:
    command = (
        _ACCOUNTING_HANDOFF_CLIENT_PREAMBLE
        + "dump_bin=$(command -v mariadb-dump || command -v mysqldump); "
        + 'test -n "$dump_bin"; '
        + '"$dump_bin" --defaults-extra-file="$defaults_file" '
        + "--skip-force --single-transaction --quick --routines --events --triggers "
        + "--skip-extended-insert "
        + "--ignore-table=slurm_acct_db.table_defs_table "
        + "--ignore-table=slurm_acct_db.convert_version_table "
        + "--ignore-table=slurm_acct_db.cluster_table "
        + "--databases slurm_acct_db"
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "--",
            "bash",
            "-lc",
            command,
        ],
        timeout_seconds=1800,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not capture the final source slurm_acct_db dump; "
            f"SQL stdout/stderr was redacted (exit {result.returncode})."
        )
    dump = result.stdout
    if not dump.strip() or "slurm_acct_db" not in dump or "USE `slurm_acct_db`;" not in dump:
        raise SoperatorMigrationPhasePending(
            "accounting handoff source dump is empty or is not bound to slurm_acct_db."
        )
    return dump


def _accounting_handoff_history_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    source_cluster_name: str,
) -> dict[str, int]:
    source_cluster_name = _accounting_handoff_cluster_name(
        source_cluster_name,
        label="source",
    )
    job_table = f"`{source_cluster_name}_job_table`"
    step_table = f"`{source_cluster_name}_step_table`"
    sql = (
        "SELECT "
        f"(SELECT COUNT(*) FROM slurm_acct_db.{job_table}),"
        f"(SELECT COUNT(*) FROM slurm_acct_db.{step_table}),"
        f"(SELECT COUNT(*) FROM slurm_acct_db.{job_table} WHERE time_end > 0),"
        f"(SELECT COALESCE(MAX(id_job),0) FROM slurm_acct_db.{job_table}),"
        f"(SELECT COALESCE(MAX(time_submit),0) FROM slurm_acct_db.{job_table});"
    )
    command = (
        _ACCOUNTING_HANDOFF_CLIENT_PREAMBLE
        + "client_bin=$(command -v mariadb || command -v mysql); "
        + 'test -n "$client_bin"; '
        + f'"$client_bin" --defaults-extra-file="$defaults_file" -N -B -e {shlex.quote(sql)}'
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "--",
            "bash",
            "-lc",
            command,
        ],
        timeout_seconds=300,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not collect exact source-history evidence; "
            f"SQL stdout/stderr was redacted (exit {result.returncode})."
        )
    fields = result.stdout.strip().split("\t")
    if len(fields) != 5:
        raise SoperatorMigrationPhasePending(
            "accounting handoff history evidence returned an unexpected result shape."
        )
    try:
        jobs, steps, completed_jobs, max_job_id, max_time_submit = (int(field) for field in fields)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff history evidence contains non-integer values."
        ) from exc
    return {
        "jobs": jobs,
        "steps": steps,
        "completed_jobs": completed_jobs,
        "max_job_id": max_job_id,
        "max_time_submit": max_time_submit,
    }


def _accounting_handoff_history_is_non_regressing(
    baseline: Mapping[str, Any],
    observed: Mapping[str, Any],
) -> bool:
    keys = ("jobs", "steps", "completed_jobs", "max_job_id", "max_time_submit")
    try:
        return all(int(observed[key]) >= int(baseline[key]) for key in keys)
    except (KeyError, TypeError, ValueError):
        return False


def _accounting_handoff_mysql_identifier(value: str) -> str:
    if not value or "\x00" in value:
        raise SoperatorMigrationPhasePending(
            "accounting handoff encountered an invalid MariaDB identifier."
        )
    return "`" + value.replace("`", "``") + "`"


def _accounting_handoff_create_table_clauses(create_sql: str) -> tuple[str, ...]:
    start = -1
    depth = 0
    quote = ""
    escaped = False
    clause_start = -1
    clauses: list[str] = []
    for index, char in enumerate(create_sql):
        if quote:
            if escaped:
                escaped = False
                continue
            if char == "\\" and quote != "`":
                escaped = True
                continue
            if char == quote:
                if index + 1 < len(create_sql) and create_sql[index + 1] == quote:
                    escaped = True
                    continue
                quote = ""
            continue
        if char in {"'", '"', "`"}:
            quote = char
            continue
        if char == "(":
            depth += 1
            if depth == 1:
                start = index
                clause_start = index + 1
            continue
        if char == ")":
            if depth <= 0:
                raise SoperatorMigrationPhasePending(
                    "accounting handoff could not parse an unbalanced SHOW CREATE TABLE result."
                )
            depth -= 1
            if depth == 0:
                clause = create_sql[clause_start:index].strip()
                if clause:
                    clauses.append(clause)
                if not clauses:
                    raise SoperatorMigrationPhasePending(
                        "accounting handoff found an empty SHOW CREATE TABLE definition."
                    )
                return tuple(clauses)
            continue
        if char == "," and depth == 1:
            clause = create_sql[clause_start:index].strip()
            if not clause:
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found an empty SHOW CREATE TABLE clause."
                )
            clauses.append(clause)
            clause_start = index + 1
    if start < 0 or depth != 0 or quote:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not parse the SHOW CREATE TABLE result safely."
        )
    raise SoperatorMigrationPhasePending(
        "accounting handoff SHOW CREATE TABLE result ended before its definition closed."
    )


def _accounting_handoff_table_definition(create_sql: str) -> dict[str, str]:
    definition: dict[str, str] = {}
    for clause in _accounting_handoff_create_table_clauses(create_sql):
        column = re.match(r"^`((?:``|[^`])+)`\s+", clause)
        if column:
            name = column.group(1).replace("``", "`")
            key = f"column:{name}"
        else:
            primary = re.match(r"^PRIMARY\s+KEY\b", clause, flags=re.IGNORECASE)
            named_key = re.match(
                r"^(?:(?:UNIQUE|FULLTEXT|SPATIAL)\s+)?KEY\s+`((?:``|[^`])+)`(?:\s|\()",
                clause,
                flags=re.IGNORECASE,
            )
            if primary:
                key = "index:PRIMARY"
            elif named_key:
                name = named_key.group(1).replace("``", "`")
                key = f"index:{name}"
            else:
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found an unsupported SHOW CREATE TABLE clause; "
                    "only columns and indexes can be reconciled automatically."
                )
        if key in definition:
            raise SoperatorMigrationPhasePending(
                f"accounting handoff found a duplicate SHOW CREATE TABLE definition for {key}."
            )
        definition[key] = clause
    return definition


def _accounting_handoff_optional_cluster_tables(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    cluster_name: str,
) -> tuple[str, ...]:
    cluster_name = _accounting_handoff_cluster_name(cluster_name, label="schema")
    prefix = f"{cluster_name}_"
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=(
            "SELECT TABLE_NAME FROM information_schema.TABLES "
            "WHERE TABLE_SCHEMA='slurm_acct_db' "
            f"AND LEFT(TABLE_NAME,{len(prefix)})='{prefix}' ORDER BY TABLE_NAME;"
        ),
    )
    tables = tuple(line.strip() for line in output.splitlines() if line.strip())
    if any(not table.startswith(prefix) for table in tables):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff found an invalid cluster-prefixed table for {cluster_name}."
        )
    if len(tables) != len(set(tables)):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff found duplicate table identities for {cluster_name}."
        )
    return tables


def _accounting_handoff_cluster_tables(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    cluster_name: str,
) -> tuple[str, ...]:
    tables = _accounting_handoff_optional_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        cluster_name=cluster_name,
    )
    if not tables:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff could not prove cluster-prefixed tables for {cluster_name}."
        )
    return tables


def _accounting_handoff_database_tables(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> tuple[str, ...]:
    tables = _accounting_handoff_optional_database_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    if not tables:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not prove a nonempty database table inventory."
        )
    return tables


def _accounting_handoff_optional_database_tables(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> tuple[str, ...]:
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=(
            "SELECT TABLE_NAME FROM information_schema.TABLES "
            "WHERE TABLE_SCHEMA='slurm_acct_db' AND TABLE_TYPE='BASE TABLE' "
            "ORDER BY TABLE_NAME;"
        ),
    )
    tables = tuple(line.strip() for line in output.splitlines() if line.strip())
    if len(tables) != len(set(tables)):
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not prove a unique database table inventory."
        )
    return tables


def _accounting_handoff_defer_import_until_source_retirement(
    *,
    phase: Mapping[str, Any],
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    target_identity: Mapping[str, Any],
    import_replay: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> str | None:
    """Checkpoint a sealed pre-import boundary while the source owns the shared writer."""

    if str(phase.get("source_accounting_owner_retired_at") or "").strip():
        return None
    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    owner_uid = str(deployment.get("owner_uid") or "").strip()
    if owner_uid == str(target_binding.get("uid") or "").strip():
        return None
    source_owner_matches = owner_uid == str(source_binding.get("uid") or "").strip()
    if not source_owner_matches and not owner_uid:
        source_resource, _source_resource_version, _source_enabled = (
            _accounting_handoff_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=source_binding,
                label="deferred import source owner",
            )
        )
        source_owner_matches = _accounting_handoff_deployment_owner_matches_retirement(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            source_resource=source_resource,
            deployment=deployment,
        )
    if (
        not source_owner_matches
        or not _accounting_handoff_deployment_writer_is_fenced(deployment)
        or str(deployment.get("strategy_type") or "") != "Recreate"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot defer target import without the exact "
            "source-owned, command-fenced shared Deployment."
        )
    sealed_line = _accounting_handoff_reuse_sealed_source_dump(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    if sealed_line is None:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot defer target import without its sealed source dump."
        )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    observation = _accounting_handoff_schema_bootstrap_observation(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=f"{target_resource_name}-acct-db-0",
        source_cluster_name=_accounting_handoff_cluster_name(
            state.get("source_cluster_name"), label="source"
        ),
        target_cluster_name=_accounting_handoff_cluster_name(
            state.get("target_cluster_name"), label="target"
        ),
    )
    if observation["registrations"] or observation["source_tables"] or observation["target_tables"]:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found target import state before source-owner retirement; "
            "the source owner was not retired."
        )
    binding = {
        "schema": _ACCOUNTING_HANDOFF_DEFERRED_IMPORT_SCHEMA,
        "status": "ready",
        "source": dict(source_binding),
        "target": dict(target_binding),
        "target_database_identity": {
            key: target_identity.get(key) for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
        },
        "import_replay": dict(import_replay),
        "deployment_uid": str(deployment.get("uid") or ""),
        "deployment_owner_uid": str(source_binding.get("uid") or "").strip(),
    }
    existing = _mapping(state.get("import_deferred_until_source_retirement"))
    if existing and any(existing.get(key) != value for key, value in binding.items()):
        raise SoperatorMigrationPhasePending(
            "accounting handoff deferred-import binding changed before source retirement."
        )
    if not existing:
        state["import_deferred_until_source_retirement"] = {
            **binding,
            "recorded_at": _utc_now(),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
    return (
        "Accounting history import is durably deferred until the exact source owner is "
        "retired and the target-version, command-fenced SlurmDBD Deployment owns bootstrap."
    )


def _accounting_handoff_show_create_table(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    table_name: str,
) -> str:
    table_identifier = _accounting_handoff_mysql_identifier(table_name)
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=f"SHOW CREATE TABLE slurm_acct_db.{table_identifier};",
    )
    first_line, separator, create_sql = output.partition("\t")
    if not separator or first_line.strip() != table_name or not create_sql.strip():
        raise SoperatorMigrationPhasePending(
            f"accounting handoff received an invalid SHOW CREATE TABLE result for {table_name}."
        )
    return create_sql.strip()


def _accounting_handoff_reconcile_table_schema(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    table_name: str,
    canonical_create_sql: str,
) -> dict[str, int]:
    observed_definition = _accounting_handoff_table_definition(
        _accounting_handoff_show_create_table(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            table_name=table_name,
        )
    )
    canonical_definition = _accounting_handoff_table_definition(canonical_create_sql)
    incompatible = sorted(
        key
        for key in observed_definition.keys() & canonical_definition.keys()
        if observed_definition[key] != canonical_definition[key]
    )
    if incompatible:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found incompatible common schema definitions for "
            f"{table_name}: {', '.join(incompatible)}."
        )
    missing = [
        (key, clause)
        for key, clause in canonical_definition.items()
        if key not in observed_definition
    ]
    if missing:
        additions = [
            ("ADD COLUMN " if key.startswith("column:") else "ADD ") + clause
            for key, clause in missing
        ]
        table_identifier = _accounting_handoff_mysql_identifier(table_name)
        _accounting_handoff_database_query(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            sql=f"ALTER TABLE slurm_acct_db.{table_identifier} " + ", ".join(additions) + ";",
            timeout_seconds=1800,
        )
        reconciled_definition = _accounting_handoff_table_definition(
            _accounting_handoff_show_create_table(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=pod_name,
                table_name=table_name,
            )
        )
        unverified = sorted(
            key
            for key, canonical_clause in canonical_definition.items()
            if reconciled_definition.get(key) != canonical_clause
        )
        if unverified:
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema reconciliation did not converge to the "
                f"canonical definition for {table_name}: {', '.join(unverified)}."
            )
    return {
        "changed": int(bool(missing)),
        "columns_added": sum(key.startswith("column:") for key, _clause in missing),
        "indexes_added": sum(key.startswith("index:") for key, _clause in missing),
    }


def _accounting_handoff_reconcile_source_schema(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    source_cluster_name: str,
    target_cluster_name: str,
) -> dict[str, int]:
    if source_cluster_name == target_cluster_name:
        raise SoperatorMigrationPhasePending(
            "accounting handoff refused to schema-reconcile one table prefix against itself."
        )
    source_prefix = f"{source_cluster_name}_"
    target_prefix = f"{target_cluster_name}_"
    source_tables = _accounting_handoff_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        cluster_name=source_cluster_name,
    )
    target_tables = _accounting_handoff_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        cluster_name=target_cluster_name,
    )
    source_by_suffix = {table.removeprefix(source_prefix): table for table in source_tables}
    target_by_suffix = {table.removeprefix(target_prefix): table for table in target_tables}
    if source_by_suffix.keys() != target_by_suffix.keys():
        source_only = sorted(source_by_suffix.keys() - target_by_suffix.keys())
        target_only = sorted(target_by_suffix.keys() - source_by_suffix.keys())
        details = []
        if source_only:
            details.append("source-only=" + ",".join(source_only))
        if target_only:
            details.append("target-only=" + ",".join(target_only))
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot reconcile different source/target cluster table sets"
            + (": " + "; ".join(details) if details else ".")
        )

    added_columns = 0
    added_indexes = 0
    changed_tables = 0
    for suffix in sorted(source_by_suffix):
        source_table = source_by_suffix[suffix]
        target_table = target_by_suffix[suffix]
        result = _accounting_handoff_reconcile_table_schema(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            table_name=source_table,
            canonical_create_sql=_accounting_handoff_show_create_table(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=pod_name,
                table_name=target_table,
            ),
        )
        changed_tables += result["changed"]
        added_columns += result["columns_added"]
        added_indexes += result["indexes_added"]
    return {
        "tables_verified": len(source_tables),
        "tables_changed": changed_tables,
        "columns_added": added_columns,
        "indexes_added": added_indexes,
    }


def _accounting_handoff_target_cluster_schema_payload(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    source_cluster_name: str,
    target_cluster_name: str,
) -> dict[str, Any]:
    source_cluster_name = _accounting_handoff_cluster_name(
        source_cluster_name,
        label="source schema bootstrap",
    )
    target_cluster_name = _accounting_handoff_cluster_name(
        target_cluster_name,
        label="target schema bootstrap",
    )
    source_prefix = f"{source_cluster_name}_"
    target_prefix = f"{target_cluster_name}_"
    source_tables = _accounting_handoff_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        cluster_name=source_cluster_name,
    )
    target_tables = (
        source_tables
        if source_cluster_name == target_cluster_name
        else _accounting_handoff_cluster_tables(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            cluster_name=target_cluster_name,
        )
    )
    source_by_suffix = {table.removeprefix(source_prefix): table for table in source_tables}
    target_by_suffix = {table.removeprefix(target_prefix): table for table in target_tables}
    if source_by_suffix.keys() != target_by_suffix.keys():
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap produced different source/target "
            "cluster table suffix sets."
        )
    required = {"job_table", "step_table"}
    if not required.issubset(source_by_suffix):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap lacks the required job/step tables."
        )
    definitions = {
        source_table: _accounting_handoff_show_create_table(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            table_name=target_by_suffix[suffix],
        )
        for suffix, source_table in source_by_suffix.items()
    }
    structural = {
        "schema": _ACCOUNTING_HANDOFF_TARGET_CLUSTER_SCHEMA,
        "source_cluster_name": source_cluster_name,
        "target_cluster_name": target_cluster_name,
        "source_tables": list(source_tables),
        "target_tables": list(target_tables),
        "table_suffixes": sorted(source_by_suffix),
        "definitions": definitions,
    }
    structural["proof_sha256"] = _fingerprint(structural)
    return structural


def _accounting_handoff_write_target_cluster_schema(
    *,
    payload: Mapping[str, Any],
    path: Path,
) -> dict[str, Any]:
    _write_sensitive_text_atomic(
        path,
        json.dumps(to_plain_data(payload), indent=2, sort_keys=True) + "\n",
    )
    return _accounting_handoff_dump_metadata(path)


def _accounting_handoff_load_target_cluster_schema(
    *,
    state: Mapping[str, Any],
    source_cluster_name: str,
    target_cluster_name: str,
) -> dict[str, Any]:
    metadata = _mapping(state.get("target_cluster_schema"))
    path = Path(str(metadata.get("path", "") or ""))
    try:
        payload = json.loads(
            _accounting_handoff_read_bound_private_text(
                path=path,
                metadata=metadata,
                label="target cluster schema snapshot",
            )
        )
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster schema snapshot is invalid JSON."
        ) from exc
    if (
        not isinstance(payload, Mapping)
        or payload.get("schema") != _ACCOUNTING_HANDOFF_TARGET_CLUSTER_SCHEMA
        or payload.get("source_cluster_name") != source_cluster_name
        or payload.get("target_cluster_name") != target_cluster_name
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster schema snapshot has an unsupported binding."
        )
    structural = dict(payload)
    proof_sha256 = str(structural.pop("proof_sha256", "") or "")
    if not proof_sha256 or _fingerprint(structural) != proof_sha256:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster schema snapshot failed its proof hash."
        )
    raw_definitions = structural.get("definitions")
    raw_source_tables = structural.get("source_tables")
    if (
        not isinstance(raw_definitions, Mapping)
        or not isinstance(raw_source_tables, Sequence)
        or isinstance(raw_source_tables, (str, bytes, bytearray))
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster schema snapshot is incomplete."
        )
    definitions = {str(key): str(value) for key, value in raw_definitions.items()}
    source_tables = tuple(str(item) for item in raw_source_tables)
    if not definitions or set(definitions) != set(source_tables):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster schema definitions do not match its inventory."
        )
    return {**structural, "definitions": definitions, "proof_sha256": proof_sha256}


def _accounting_handoff_reconcile_source_schema_snapshot(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    source_cluster_name: str,
    target_schema: Mapping[str, Any],
) -> dict[str, int]:
    definitions = _mapping(target_schema.get("definitions"))
    observed_tables = _accounting_handoff_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        cluster_name=source_cluster_name,
    )
    if set(observed_tables) != set(definitions):
        raise SoperatorMigrationPhasePending(
            "accounting handoff imported source table inventory differs from the "
            "checkpointed target-version schema."
        )
    result = {
        "tables_verified": 0,
        "tables_changed": 0,
        "columns_added": 0,
        "indexes_added": 0,
    }
    for table_name in sorted(definitions):
        table_result = _accounting_handoff_reconcile_table_schema(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            table_name=table_name,
            canonical_create_sql=str(definitions[table_name]),
        )
        result["tables_verified"] += 1
        result["tables_changed"] += table_result["changed"]
        result["columns_added"] += table_result["columns_added"]
        result["indexes_added"] += table_result["indexes_added"]
    return result


def _accounting_handoff_global_table_names(
    *,
    source_tables: Sequence[str],
    source_cluster_name: str,
) -> tuple[str, ...]:
    source_prefix = f"{source_cluster_name}_"
    excluded = {*_ACCOUNTING_HANDOFF_INTERNAL_TABLES, "cluster_table"}
    return tuple(
        sorted(
            table
            for table in source_tables
            if table not in excluded and not table.startswith(source_prefix)
        )
    )


def _accounting_handoff_capture_target_global_schema(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    source_tables: Sequence[str],
    source_cluster_name: str,
    target_cluster_name: str,
    path: Path,
) -> dict[str, Any]:
    global_tables = _accounting_handoff_global_table_names(
        source_tables=source_tables,
        source_cluster_name=source_cluster_name,
    )
    if not global_tables:
        raise SoperatorMigrationPhasePending(
            "accounting handoff source dump does not contain any reconcilable global tables."
        )
    target_tables = _accounting_handoff_database_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    target_prefix = f"{target_cluster_name}_"
    target_globals = {
        table
        for table in target_tables
        if table not in {*_ACCOUNTING_HANDOFF_INTERNAL_TABLES, "cluster_table"}
        and not table.startswith(target_prefix)
    }
    unexpected = sorted(set(global_tables) - target_globals)
    if unexpected:
        raise SoperatorMigrationPhasePending(
            "accounting handoff final source dump contains non-source-prefixed table(s) "
            "that are not target-current global tables: " + ", ".join(unexpected)
        )
    definitions = {
        table: _accounting_handoff_show_create_table(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            table_name=table,
        )
        for table in global_tables
    }
    _write_sensitive_text_atomic(
        path,
        json.dumps(
            {
                "schema": _ACCOUNTING_HANDOFF_TARGET_SCHEMA,
                "tables": definitions,
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
    )
    return _accounting_handoff_dump_metadata(path)


def _accounting_handoff_load_target_global_schema(
    *,
    state: Mapping[str, Any],
    source_cluster_name: str,
) -> dict[str, str]:
    metadata = _mapping(state.get("target_global_schema"))
    path = Path(str(metadata.get("path", "") or ""))
    try:
        payload = json.loads(
            _accounting_handoff_read_bound_private_text(
                path=path,
                metadata=metadata,
                label="target global schema snapshot",
            )
        )
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target global schema snapshot is invalid JSON."
        ) from exc
    if (
        not isinstance(payload, Mapping)
        or payload.get("schema") != _ACCOUNTING_HANDOFF_TARGET_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target global schema snapshot has an unsupported schema."
        )
    raw_tables = payload.get("tables")
    if not isinstance(raw_tables, Mapping) or not raw_tables:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target global schema snapshot has no table definitions."
        )
    definitions = {
        str(table): str(create_sql)
        for table, create_sql in raw_tables.items()
        if str(table) and str(create_sql)
    }
    raw_source_tables = state.get("source_database_tables")
    if not isinstance(raw_source_tables, Sequence) or isinstance(
        raw_source_tables, (str, bytes, bytearray)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff checkpoint lacks a valid source database table inventory."
        )
    expected = set(
        _accounting_handoff_global_table_names(
            source_tables=tuple(str(item) for item in raw_source_tables),
            source_cluster_name=source_cluster_name,
        )
    )
    if set(definitions) != expected:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target global schema snapshot table inventory does not "
            "match the final source dump inventory."
        )
    return definitions


def _accounting_handoff_reconcile_global_schema(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    definitions: Mapping[str, str],
) -> dict[str, int]:
    result = {
        "tables_verified": 0,
        "tables_changed": 0,
        "columns_added": 0,
        "indexes_added": 0,
    }
    for table_name in sorted(definitions):
        table_result = _accounting_handoff_reconcile_table_schema(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            table_name=table_name,
            canonical_create_sql=definitions[table_name],
        )
        result["tables_verified"] += 1
        result["tables_changed"] += table_result["changed"]
        result["columns_added"] += table_result["columns_added"]
        result["indexes_added"] += table_result["indexes_added"]
    return result


def _accounting_handoff_slurm_registration_details(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, dict[str, str]]:
    result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=(
            "sacctmgr",
            "-nP",
            "show",
            "cluster",
            "format=Cluster,ControlHost,ControlPort,RPC",
        ),
        check=False,
        timeout_seconds=300,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not verify cluster registrations through the "
            f"target-version sacctmgr: {_command_detail(result)}"
        )
    registrations: dict[str, dict[str, str]] = {}
    for raw_line in result.stdout.splitlines():
        if not raw_line.strip():
            continue
        fields = raw_line.split("|")
        if len(fields) < 4:
            raise SoperatorMigrationPhasePending(
                "accounting handoff target-version sacctmgr returned malformed cluster "
                "registration data."
            )
        name = _accounting_handoff_cluster_name(fields[0].strip(), label="sacctmgr")
        if name in registrations:
            raise SoperatorMigrationPhasePending(
                f"accounting handoff target-version sacctmgr returned duplicate {name} rows."
            )
        registrations[name] = {
            "control_host": fields[1].strip(),
            "control_port": fields[2].strip(),
            "rpc": fields[3].strip(),
        }
    return registrations


def _accounting_handoff_validate_registration_details(
    *,
    registrations: Mapping[str, Mapping[str, str]],
    source_cluster_name: str,
    target_cluster_name: str,
) -> None:
    missing = sorted({source_cluster_name, target_cluster_name} - set(registrations))
    if missing:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target-version sacctmgr did not retain required cluster "
            "registration(s): " + ", ".join(missing)
        )
    target_registration = registrations[target_cluster_name]
    if (
        str(target_registration.get("control_host", "")).lower() in {"", "(null)", "none"}
        or _non_negative_int(target_registration.get("control_port"), fallback=0) <= 0
        or _non_negative_int(target_registration.get("rpc"), fallback=0) <= 0
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster registration is not bound to an active "
            "controller host/port/RPC after accounting resumed."
        )
    if source_cluster_name != target_cluster_name:
        source_registration = registrations[source_cluster_name]
        if (
            str(source_registration.get("control_host", "")).lower() not in {"", "(null)", "none"}
            or _non_negative_int(source_registration.get("control_port"), fallback=0) != 0
            or _non_negative_int(source_registration.get("rpc"), fallback=0) != 0
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff historical source registration still points at a "
                "controller; source cleanup was blocked."
            )


def _accounting_handoff_ensure_slurm_registrations(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    source_cluster_name: str,
    target_cluster_name: str,
    timeout_seconds: int = 300,
    poll_interval_seconds: int = 5,
) -> tuple[str, ...]:
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        registrations = _accounting_handoff_slurm_registration_details(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        target_registration = registrations.get(target_cluster_name)
        target_active = bool(target_registration) and (
            str(_mapping(target_registration).get("control_host", "")).lower()
            not in {"", "(null)", "none"}
            and _non_negative_int(_mapping(target_registration).get("control_port"), fallback=0) > 0
            and _non_negative_int(_mapping(target_registration).get("rpc"), fallback=0) > 0
        )
        if target_active:
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting handoff target cluster registration did not become bound to "
                "an active controller host/port/RPC within the bounded wait."
            )
        time.sleep(max(poll_interval_seconds, 1))
    if source_cluster_name not in registrations:
        result = _kubectl_exec_login(
            command_runner=command_runner,
            kube_context=kube_context,
            args=("sacctmgr", "-i", "add", "cluster", source_cluster_name),
            check=False,
            timeout_seconds=300,
        )
        if result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "accounting handoff could not create a historical source registration "
                f"through target-version sacctmgr: {_command_detail(result)}"
            )
    while True:
        registrations = _accounting_handoff_slurm_registration_details(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if source_cluster_name in registrations:
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting handoff historical source registration did not become "
                "visible through target-version sacctmgr within the bounded wait."
            )
        time.sleep(max(poll_interval_seconds, 1))
    _accounting_handoff_validate_registration_details(
        registrations=registrations,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )
    return tuple(registrations)


def _accounting_handoff_sacct_history_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    source_cluster_name: str,
    source_history: Mapping[str, Any],
) -> dict[str, Any]:
    jobs = _non_negative_int(source_history.get("jobs"), fallback=0)
    max_job_id = _non_negative_int(source_history.get("max_job_id"), fallback=0)
    args = [
        "sacct",
        f"--clusters={source_cluster_name}",
        "--allusers",
        "--starttime=1970-01-01T00:00:00",
        "--noheader",
        "--allocations",
        "--parsable2",
        "--format=JobIDRaw,State,ExitCode",
    ]
    if jobs:
        if max_job_id <= 0:
            raise SoperatorMigrationPhasePending(
                "accounting handoff source SQL history has jobs but no positive max job id."
            )
        args.append(f"--jobs={max_job_id}")
    result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=args,
        check=False,
        timeout_seconds=300,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff source history is not queryable through target-version "
            f"sacct: {_command_detail(result)}"
        )
    rows = tuple(line.strip() for line in result.stdout.splitlines() if line.strip())
    if jobs:
        expected_id = str(max_job_id)
        visible = any(row.split("|", 1)[0].strip() == expected_id for row in rows)
        if not visible:
            raise SoperatorMigrationPhasePending(
                "accounting handoff SQL counts match, but target-version sacct cannot "
                f"read source cluster job {max_job_id}."
            )
    return {
        "cluster": source_cluster_name,
        "max_job_id": max_job_id,
        "matching_rows": len(rows),
    }


def _write_sensitive_text_atomic(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    with suppress(OSError):
        os.chmod(path.parent, 0o700)
    fd = -1
    temp_path: Path | None = None
    try:
        fd, raw_temp_path = tempfile.mkstemp(
            prefix=f".{path.name}.",
            suffix=".tmp",
            dir=path.parent,
        )
        temp_path = Path(raw_temp_path)
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            fd = -1
            os.fchmod(handle.fileno(), 0o600)
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, path)
        os.chmod(path, 0o600)
    finally:
        if fd >= 0:
            os.close(fd)
        if temp_path is not None:
            temp_path.unlink(missing_ok=True)


def _accounting_handoff_dump_semantic_sha256(content: str) -> str:
    """Hash executable dump content while ignoring dump-tool presentation noise."""

    normalized = "\n".join(
        line.rstrip()
        for line in content.splitlines()
        if line.strip() and not line.lstrip().startswith("--")
    )
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def _accounting_handoff_read_private_bytes(path: Path, *, label: str) -> bytes:
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(path, flags)
    except OSError as exc:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} is missing or cannot be opened safely."
        ) from exc
    try:
        file_stat = os.fstat(fd)
        mode = stat.S_IMODE(file_stat.st_mode)
        if not stat.S_ISREG(file_stat.st_mode):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} is not a regular file."
            )
        if mode & 0o077:
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} permissions are {mode:o}, not private mode 600."
            )
        with os.fdopen(fd, "rb") as handle:
            fd = -1
            return handle.read()
    finally:
        if fd >= 0:
            os.close(fd)


def _accounting_handoff_read_bound_private_text(
    *,
    path: Path,
    metadata: Mapping[str, Any],
    label: str,
) -> str:
    if str(metadata.get("path") or "") != str(path):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} path changed from its checkpoint binding."
        )
    content = _accounting_handoff_read_private_bytes(path, label=label)
    observed_size = len(content)
    observed_sha256 = hashlib.sha256(content).hexdigest()
    if observed_size != _non_negative_int(
        metadata.get("size_bytes"), fallback=-1
    ) or observed_sha256 != str(metadata.get("sha256") or ""):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} failed its single-read size/SHA256 guard."
        )
    try:
        return content.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} is not valid UTF-8."
        ) from exc


def _accounting_handoff_dump_metadata(path: Path) -> dict[str, Any]:
    content = _accounting_handoff_read_private_bytes(path, label="checkpoint artifact")
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff checkpoint dump is not valid UTF-8."
        ) from exc
    return {
        "path": str(path),
        "size_bytes": len(content),
        "sha256": hashlib.sha256(content).hexdigest(),
        "semantic_sha256": _accounting_handoff_dump_semantic_sha256(text),
    }


def _accounting_handoff_exact_slurmcluster(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    binding: Mapping[str, Any],
    label: str,
) -> tuple[Mapping[str, Any], str, bool]:
    namespace = str(binding.get("namespace") or "").strip()
    name = str(binding.get("name") or "").strip()
    expected_uid = str(binding.get("uid") or "").strip()
    if namespace != _SOPERATOR_NAMESPACE or not name or not expected_uid:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster binding is incomplete."
        )
    exists, resource = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"slurmcluster/{name}",
        namespace=namespace,
    )
    metadata = _mapping(resource.get("metadata"))
    if (
        not exists
        or str(metadata.get("name") or "").strip() != name
        or str(metadata.get("namespace") or namespace).strip() != namespace
        or str(metadata.get("uid") or "").strip() != expected_uid
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster no longer matches its exact "
            "namespace/name/UID binding."
        )
    resource_version = str(metadata.get("resourceVersion") or "").strip()
    if not resource_version:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster has no resourceVersion for "
            "compare-and-set mutation."
        )
    enabled = _mapping(
        _mapping(_mapping(resource.get("spec")).get("slurmNodes")).get("accounting")
    ).get("enabled")
    if not isinstance(enabled, bool):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster does not expose an explicit "
            "spec.slurmNodes.accounting.enabled boolean."
        )
    return resource, resource_version, enabled


def _accounting_handoff_optional_exact_slurmcluster(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    binding: Mapping[str, Any],
    label: str,
) -> tuple[Mapping[str, Any], str, bool] | None:
    namespace = str(binding.get("namespace") or "").strip()
    name = str(binding.get("name") or "").strip()
    expected_uid = str(binding.get("uid") or "").strip()
    if namespace != _SOPERATOR_NAMESPACE or not name or not expected_uid:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster binding is incomplete."
        )
    command = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        namespace,
        "get",
        "slurmcluster",
        name,
        "-o",
        "json",
    ]
    result = command_runner(command, timeout_seconds=120, check=False)
    if result.returncode != 0:
        if _kubectl_get_slurmcluster_not_found(
            result,
            name=name,
            namespace=namespace,
        ):
            return None
        raise RuntimeError(
            f"accounting handoff could not inspect the exact {label} SlurmCluster: "
            f"{_command_detail(result)}"
        )
    try:
        resource = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"accounting handoff {label} SlurmCluster lookup returned invalid JSON."
        ) from exc
    if not isinstance(resource, Mapping):
        raise RuntimeError(
            f"accounting handoff {label} SlurmCluster lookup returned a non-object payload."
        )
    metadata = _mapping(resource.get("metadata"))
    if (
        str(metadata.get("name") or "").strip() != name
        or str(metadata.get("namespace") or namespace).strip() != namespace
        or str(metadata.get("uid") or "").strip() != expected_uid
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster no longer matches its exact "
            "namespace/name/UID binding."
        )
    resource_version = str(metadata.get("resourceVersion") or "").strip()
    enabled = _mapping(
        _mapping(_mapping(resource.get("spec")).get("slurmNodes")).get("accounting")
    ).get("enabled")
    if not resource_version or not isinstance(enabled, bool):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmCluster lacks resourceVersion or explicit "
            "accounting.enabled state."
        )
    return resource, resource_version, enabled


def _accounting_handoff_source_replica_set_uids(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    deployment_uid: str,
) -> tuple[str, ...]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "replicasets.apps",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    return tuple(
        dict.fromkeys(
            str(_mapping(item.get("metadata")).get("uid") or "").strip()
            for item in _sequence_of_mappings(payload.get("items"))
            if any(
                str(owner.get("kind") or "").strip() == "Deployment"
                and str(owner.get("uid") or "").strip() == deployment_uid
                and owner.get("controller") is True
                for owner in _sequence_of_mappings(
                    _mapping(item.get("metadata")).get("ownerReferences")
                )
            )
            and str(_mapping(item.get("metadata")).get("uid") or "").strip()
        )
    )


def _accounting_handoff_source_writer_pods(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    replica_set_uids: Sequence[str],
    selector: Mapping[str, str] | None = None,
) -> tuple[str, ...]:
    expected = set(replica_set_uids)
    normalized_selector = {
        str(key): str(value)
        for key, value in _mapping(selector).items()
        if str(key).strip() and str(value).strip()
    }
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    return tuple(
        str(_mapping(item.get("metadata")).get("name") or "").strip()
        for item in _sequence_of_mappings(payload.get("items"))
        if (
            any(
                str(owner.get("kind") or "").strip() == "ReplicaSet"
                and str(owner.get("uid") or "").strip() in expected
                and owner.get("controller") is True
                for owner in _sequence_of_mappings(
                    _mapping(item.get("metadata")).get("ownerReferences")
                )
            )
            or (
                normalized_selector
                and all(
                    str(_mapping(_mapping(item.get("metadata")).get("labels")).get(key) or "")
                    == value
                    for key, value in normalized_selector.items()
                )
            )
        )
    )


def _accounting_handoff_bind_source_writer_lineage(
    *,
    state: dict[str, Any],
    deployment: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    gate = state.setdefault("source_writer_gate", {})
    if not isinstance(gate, dict):
        raise RuntimeError("accounting handoff source_writer_gate must be a mapping.")
    expected = _mapping(state.get("source_accounting_deployment"))
    expected_uid = str(
        gate.get("source_deployment_uid") or expected.get("uid") or deployment.get("uid") or ""
    ).strip()
    original_replicas = _non_negative_int(
        gate.get("source_deployment_replicas")
        if "source_deployment_replicas" in gate
        else expected.get("replicas", deployment.get("replicas")),
        fallback=0,
    )
    raw_replica_sets = gate.get("source_replica_sets")
    checkpointed_replica_sets = tuple(
        str(item or "").strip()
        for item in (
            raw_replica_sets
            if isinstance(raw_replica_sets, Sequence)
            and not isinstance(raw_replica_sets, (str, bytes, bytearray))
            else ()
        )
        if str(item or "").strip()
    )
    checkpointed_selector = {
        str(key): str(value)
        for key, value in _mapping(gate.get("source_deployment_selector")).items()
    }
    reconstructed_without_selector = bool(
        gate.get("source_lineage_reconstructed_without_selector") is True
    )
    lineage_checkpointed = bool(
        expected_uid
        and "source_replica_sets" in gate
        and (checkpointed_selector or reconstructed_without_selector)
        and (original_replicas == 0 or checkpointed_replica_sets)
    )
    if lineage_checkpointed:
        return
    live_uid = str(deployment.get("uid") or "").strip()
    if not expected_uid:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot bind source writer lineage without the exact "
            "checkpointed source accounting Deployment UID."
        )
    exact_source_deployment_live = bool(deployment.get("exists") and live_uid == expected_uid)
    selector = (
        _accounting_handoff_deployment_selector(deployment) if exact_source_deployment_live else {}
    )
    replica_set_uids = _accounting_handoff_source_replica_set_uids(
        command_runner=command_runner,
        kube_context=kube_context,
        deployment_uid=expected_uid,
    )
    if not replica_set_uids and (original_replicas > 0 or not exact_source_deployment_live):
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot reconstruct the checkpointed source writer lineage: "
            "no exact source-owned ReplicaSet UID remains before writer disable."
        )
    gate.update(
        {
            "source_deployment_uid": expected_uid,
            "source_deployment_replicas": original_replicas,
            "source_deployment_selector": selector,
            "source_replica_sets": list(replica_set_uids),
            "source_lineage_bound_at": _utc_now(),
        }
    )
    if not exact_source_deployment_live:
        gate["source_lineage_reconstructed_without_selector"] = True
        gate["source_lineage_reconstructed_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()


def _accounting_handoff_finalize_command_fenced_source_dump(
    *,
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> str:
    if str(state.get("status") or "") not in {"source-snapshot", "source-dumped"} or any(
        state.get(key)
        for key in (
            "import_replay",
            "import_started_at",
            "imported_dump",
            "target_enable_started_at",
        )
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff command-fenced finalization is allowed only before target "
            "import intent."
        )
    existing_seal = state.get("source_dump_seal")
    if (
        isinstance(existing_seal, Mapping)
        and existing_seal.get("schema") == _ACCOUNTING_HANDOFF_SOURCE_DUMP_SEAL_SCHEMA
        and existing_seal.get("mode") == "dual-slurmdbd-command-fence"
    ):
        sealed_line = _accounting_handoff_reuse_sealed_source_dump(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        if sealed_line is not None:
            return sealed_line
    elif isinstance(existing_seal, Mapping):
        superseded_seals = state.setdefault("superseded_source_dump_seals", [])
        if not isinstance(superseded_seals, list):
            raise RuntimeError("accounting handoff superseded_source_dump_seals must be a list.")
        superseded_seals.append({**dict(existing_seal), "superseded_at": _utc_now()})
        state.pop("source_dump_seal", None)
        if checkpoint_writer is not None:
            checkpoint_writer()
    source_resource_name = _accounting_handoff_cluster_name(
        state.get("source_resource_name"),
        label="source SlurmCluster resource",
    )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    source_pod = f"{source_resource_name}-acct-db-0"
    target_pod = f"{target_resource_name}-acct-db-0"
    observed_source = _accounting_handoff_optional_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
        expected_slurmcluster_binding=source_binding,
    )
    expected_source = _mapping(state.get("source"))
    if observed_source is None:
        _accounting_handoff_assert_source_pvc_identity(
            command_runner=command_runner,
            kube_context=kube_context,
            expected=expected_source,
        )
        recovery = state.setdefault("source_database_recovery", {})
        if not isinstance(recovery, dict):
            raise RuntimeError("accounting handoff source_database_recovery must be a mapping.")
        expected_recovery_binding = {
            key: str(source_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
        }
        if recovery:
            if (
                recovery.get("schema") != _ACCOUNTING_HANDOFF_SOURCE_DB_RECOVERY_SCHEMA
                or _mapping(recovery.get("binding")) != expected_recovery_binding
                or str(recovery.get("pvc") or "") != str(expected_source.get("pvc") or "")
                or str(recovery.get("pvc_uid") or "") != str(expected_source.get("pvc_uid") or "")
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff source database recovery intent changed binding."
                )
        else:
            recovery.update(
                {
                    "schema": _ACCOUNTING_HANDOFF_SOURCE_DB_RECOVERY_SCHEMA,
                    "status": "command-fence-intent",
                    "binding": expected_recovery_binding,
                    "pvc": str(expected_source.get("pvc") or ""),
                    "pvc_uid": str(expected_source.get("pvc_uid") or ""),
                    "intent_recorded_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
    _accounting_handoff_apply_writer_command_fence(
        state=state,
        gate_key="source_writer_command_fence",
        binding=source_binding,
        label="source",
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    _accounting_handoff_apply_writer_command_fence(
        state=state,
        gate_key="target_writer_command_fence",
        binding=target_binding,
        label="target",
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    _accounting_handoff_reconcile_writer_deployment_command_fence(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    _accounting_handoff_wait_for_mariadb_pod(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
    )
    _accounting_handoff_wait_for_mariadb_pod(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
    )
    source_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
        expected_slurmcluster_binding=source_binding,
    )
    if any(source_identity.get(key) != expected_source.get(key) for key in ("pvc", "pvc_uid")):
        raise SoperatorMigrationPhasePending(
            "accounting handoff recreated source MariaDB on a different PVC binding."
        )
    if any(
        source_identity.get(key) != expected_source.get(key)
        for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
        if key not in {"pvc", "pvc_uid"}
    ):
        recovery = state.get("source_database_recovery")
        if not isinstance(recovery, dict) or recovery.get("schema") != (
            _ACCOUNTING_HANDOFF_SOURCE_DB_RECOVERY_SCHEMA
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff source MariaDB Pod identity changed without a "
                "checkpointed recovery intent."
            )
        recovery.update(
            {
                "status": "recovered",
                "pod": str(source_identity.get("pod") or ""),
                "pod_uid": str(source_identity.get("pod_uid") or ""),
                "statefulset_uid": str(source_identity.get("statefulset_uid") or ""),
                "mariadb_uid": str(source_identity.get("mariadb_uid") or ""),
                "recovered_at": _utc_now(),
            }
        )
        state["source"] = source_identity
        if checkpoint_writer is not None:
            checkpoint_writer()
    target_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        expected_slurmcluster_binding=target_binding,
    )
    expected_target = _mapping(state.get("target"))
    if expected_target and any(
        target_identity.get(key) != expected_target.get(key)
        for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target MariaDB Pod/PVC identity changed before import intent."
        )
    state["target"] = target_identity
    _accounting_handoff_wait_writer_command_fences(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        source_pod=source_pod,
        target_pod=target_pod,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    source_cluster_name = _accounting_handoff_cluster_name(
        state.get("source_cluster_name"),
        label="source",
    )
    source_cluster_policy = _accounting_handoff_source_cluster_policy_projection(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
        cluster_name=source_cluster_name,
    )
    final_dump = _accounting_handoff_dump_source_database(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
    )
    source_history = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
        source_cluster_name=source_cluster_name,
    )
    source_tables = _accounting_handoff_database_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
    )
    current_dump = _mapping(state.get("dump"))
    current_path = Path(str(current_dump.get("path") or ""))
    if not current_path.name:
        raise SoperatorMigrationPhasePending(
            "accounting handoff preliminary source dump lacks its private artifact path."
        )
    replacement_id = uuid4().hex[:12]
    candidate_path = current_path.parent / f"source-slurm-acct-db.fenced-{replacement_id}.sql"
    replacement = {
        "schema": _ACCOUNTING_HANDOFF_DUMP_REPLACEMENT_SCHEMA,
        "status": "intent-recorded",
        "replacement_id": replacement_id,
        "previous_dump": dict(current_dump),
        "candidate_path": str(candidate_path),
        "intent_recorded_at": _utc_now(),
    }
    state["source_dump_replacement"] = replacement
    if checkpoint_writer is not None:
        checkpoint_writer()
    _write_sensitive_text_atomic(candidate_path, final_dump)
    candidate = _accounting_handoff_dump_metadata(candidate_path)
    replacement.update(
        {
            "status": "candidate-written",
            "candidate_dump": candidate,
            "source_history": source_history,
            "source_database_tables": list(source_tables),
            "source_cluster_policy": source_cluster_policy,
            "captured_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    _accounting_handoff_wait_writer_command_fences(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        source_pod=source_pod,
        target_pod=target_pod,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    generation = _non_negative_int(state.get("source_dump_generation"), fallback=0) + 1
    superseded = state.setdefault("superseded_source_dumps", [])
    if not isinstance(superseded, list):
        raise RuntimeError("accounting handoff superseded_source_dumps must be a list.")
    if current_dump:
        superseded.append(
            {
                **dict(current_dump),
                "superseded_at": _utc_now(),
                "replacement_id": replacement_id,
            }
        )
    state.update(
        {
            "status": "source-dumped",
            "source_history": source_history,
            "source_database_tables": list(source_tables),
            "source_cluster_policy": source_cluster_policy,
            "dump": candidate,
            "source_dump_generation": generation,
            "source_paused_at": _utc_now(),
        }
    )
    replacement.update(
        {
            "status": "committed",
            "committed_dump_sha256": candidate["sha256"],
            "committed_dump_generation": generation,
            "committed_at": _utc_now(),
        }
    )
    source_fence = _mapping(state.get("source_writer_command_fence"))
    target_fence = _mapping(state.get("target_writer_command_fence"))
    state["source_dump_seal"] = {
        "schema": _ACCOUNTING_HANDOFF_SOURCE_DUMP_SEAL_SCHEMA,
        "mode": "dual-slurmdbd-command-fence",
        "status": "sealed",
        "dump_sha256": candidate["sha256"],
        "dump_generation": generation,
        "source_pvc": str(source_identity.get("pvc") or ""),
        "source_pvc_uid": str(source_identity.get("pvc_uid") or ""),
        "target_pvc": str(target_identity.get("pvc") or ""),
        "target_pvc_uid": str(target_identity.get("pvc_uid") or ""),
        "source_fence_resource_version": str(source_fence.get("applied_resource_version") or ""),
        "target_fence_resource_version": str(target_fence.get("applied_resource_version") or ""),
        "source_history": source_history,
        "source_cluster_policy_sha256": source_cluster_policy["proof_sha256"],
        "sealed_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    return (
        "Accounting history handoff sealed a final source DB dump while both exact "
        "SlurmDBD writers were command-fenced."
    )


def _prepare_accounting_handoff_source_dump(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    source_report: Mapping[str, Any],
    values: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    artifact_dir: Path,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    state = _accounting_handoff_state(phase)
    if state.get("status") == "skipped":
        return ["Accounting history handoff skipped: source chart-managed accounting is absent."]
    if state.get("status") in {
        "source-snapshot",
        "source-dumped",
        "importing",
        "import-reconciled",
        "imported-paused",
        "target-enabling",
        "target-enabled",
        "in-place-pending",
        "verified",
    }:
        resumed_status = str(state.get("status") or "")
        if resumed_status == "in-place-pending":
            return [
                "Accounting history handoff reused the checkpointed in-place "
                "Pod/PVC continuity requirement."
            ]
        if resumed_status == "verified" and str(state.get("in_place_verified_at") or "").strip():
            return [
                "Accounting history handoff reused the verified in-place Pod/PVC "
                "continuity checkpoint."
            ]
        dump_path = Path(str(_mapping(state.get("dump")).get("path", "") or ""))
        observed = _accounting_handoff_dump_metadata(dump_path)
        expected = _mapping(state.get("dump"))
        if any(observed.get(key) != expected.get(key) for key in ("size_bytes", "sha256")):
            raise SoperatorMigrationPhasePending(
                "accounting handoff checkpoint dump no longer matches its recorded size/SHA256."
            )
        if resumed_status == "source-snapshot":
            return [
                "Accounting history handoff reused the preliminary source DB snapshot; "
                "the final dual-command-fenced dump remains pending after target apply."
            ]
        if resumed_status in {
            "source-dumped",
            "importing",
            "import-reconciled",
            "imported-paused",
            "target-enabling",
            "target-enabled",
            "verified",
        }:
            source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
            target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
            if resumed_status == "source-dumped":
                if str(phase.get("source_accounting_owner_retired_at") or "").strip():
                    recovery = _mapping(state.get("source_orphan_finalizer_recovery"))
                    recovery_source = _mapping(recovery.get("source"))
                    if not (
                        recovery.get("status") == "verified"
                        and str(recovery.get("verified_at") or "").strip()
                        and str(phase.get("source_cleanup_started_at") or "").strip()
                        and all(
                            str(recovery_source.get(key) or "").strip()
                            == str(source_binding.get(key) or "").strip()
                            for key in ("namespace", "name", "uid")
                        )
                    ):
                        raise SoperatorMigrationPhasePending(
                            "accounting handoff cannot reuse the sealed source dump after "
                            "retirement without the exact verified source UID boundary."
                        )
                    _accounting_handoff_assert_source_pvc_identity(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        expected=_mapping(state.get("source")),
                    )
                    target_resource_name = _accounting_handoff_cluster_name(
                        state.get("target_resource_name"),
                        label="target SlurmCluster resource",
                    )
                    _accounting_handoff_wait_target_command_fence_after_source_retirement(
                        phase=phase,
                        state=state,
                        source_binding=source_binding,
                        target_binding=target_binding,
                        target_pod=f"{target_resource_name}-acct-db-0",
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                    return [
                        "Accounting history handoff reused the immutable sealed source DB "
                        "dump after exact source retirement and target-only fence proof."
                    ]
                return [
                    _accounting_handoff_finalize_command_fenced_source_dump(
                        state=state,
                        source_binding=source_binding,
                        target_binding=target_binding,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                ]
            if resumed_status in {"importing", "import-reconciled"}:
                sealed_line = _accounting_handoff_reuse_sealed_source_dump(
                    state=state,
                    source_binding=source_binding,
                    target_binding=target_binding,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
                if sealed_line is None:
                    raise SoperatorMigrationPhasePending(
                        "accounting handoff import resume lacks its dual-command-fenced "
                        "source dump seal."
                    )
                return [sealed_line]
            source_resource = _accounting_handoff_optional_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=source_binding,
                label="source",
            )
            if resumed_status == "imported-paused" and source_resource is not None:
                sealed_line = _accounting_handoff_reuse_sealed_source_dump(
                    state=state,
                    source_binding=source_binding,
                    target_binding=target_binding,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
                if sealed_line is None:
                    raise SoperatorMigrationPhasePending(
                        "accounting handoff imported-paused resume lacks its sealed dump."
                    )
                return [sealed_line]
            if source_resource is not None:
                raise SoperatorMigrationPhasePending(
                    "accounting handoff source owner still exists after the durable target "
                    "restore boundary."
                )
            if not str(phase.get("source_cleanup_started_at") or "").strip():
                raise SoperatorMigrationPhasePending(
                    "accounting handoff source owner disappeared before durable cleanup intent."
                )
            _accounting_handoff_assert_source_pvc_identity(
                command_runner=command_runner,
                kube_context=kube_context,
                expected=_mapping(state.get("source")),
            )
            if resumed_status == "imported-paused":
                target_resource_name = _accounting_handoff_cluster_name(
                    state.get("target_resource_name"),
                    label="target SlurmCluster resource",
                )
                _accounting_handoff_wait_target_command_fence_after_source_retirement(
                    phase=phase,
                    state=state,
                    source_binding=source_binding,
                    target_binding=target_binding,
                    target_pod=f"{target_resource_name}-acct-db-0",
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
                return [
                    "Accounting history handoff adopted the retired source owner while the "
                    "target writer remains command-fenced."
                ]
        return ["Accounting history handoff reused the checkpointed final source DB dump."]
    if not _source_accounting_handoff_required(
        checkpoint=checkpoint,
        source_report=source_report,
    ):
        state.update({"status": "skipped", "reason": "source accounting was not detected"})
        if checkpoint_writer is not None:
            checkpoint_writer()
        return ["Accounting history handoff skipped: source chart-managed accounting is absent."]

    source_resource_name = _accounting_handoff_source_resource_name(
        source_report,
        target_ref=target_ref,
    )
    source_slurmcluster_binding = _source_cleanup_binding(
        source_report,
        target_ref=target_ref,
    )
    source_pod = f"{source_resource_name}-acct-db-0"
    source_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
        expected_slurmcluster_binding=source_slurmcluster_binding,
    )
    checkpointed_source_identity = _mapping(state.get("source"))
    if checkpointed_source_identity and any(
        source_identity.get(key) != checkpointed_source_identity.get(key)
        for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source MariaDB Pod/PVC identity changed during the "
            "checkpointed source snapshot."
        )
    source_cluster_name = _accounting_handoff_source_cluster_name(
        source_report,
        target_ref=target_ref,
        command_runner=command_runner,
        kube_context=kube_context,
        source_pod=source_pod,
    )
    target_cluster_name = _accounting_handoff_target_cluster_name(
        values,
        target_ref=target_ref,
    )
    if source_cluster_name == target_cluster_name:
        evidence = _accounting_handoff_history_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=source_pod,
            source_cluster_name=source_cluster_name,
        )
        state.update(
            {
                "status": "in-place-pending",
                "source_resource_name": source_resource_name,
                "source_cluster_name": source_cluster_name,
                "target_cluster_name": target_cluster_name,
                "target_resource_name": target_ref,
                "source": source_identity,
                "source_history": evidence,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            "Accounting history handoff detected one in-place Slurm accounting identity; "
            "destructive SQL import is disabled and exact MariaDB Pod/PVC continuity will "
            "be verified after chart apply."
        ]
    source_binding = _source_cleanup_binding(source_report, target_ref=target_ref)
    if not all(source_binding.values()):
        raise SoperatorMigrationPhasePending(
            "accounting handoff requires an exact source SlurmCluster namespace/name/UID "
            "binding before recording its preliminary accounting snapshot."
        )
    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
        allow_missing=True,
    )
    checkpointed_deployment = _mapping(state.get("source_accounting_deployment"))
    if deployment.get("exists"):
        if checkpointed_deployment and (
            str(deployment.get("uid") or "") != str(checkpointed_deployment.get("uid") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff source accounting Deployment identity changed "
                "during the checkpointed writer pause."
            )
        if str(deployment.get("owner_uid") or "") != source_binding["uid"]:
            raise SoperatorMigrationPhasePending(
                "accounting handoff pre-dump Deployment is not owned by the exact source "
                "SlurmCluster."
            )
        original_replicas = int(deployment["replicas"])
        deployment_uid = str(deployment["uid"])
    else:
        deployment_uid = str(checkpointed_deployment.get("uid") or "").strip()
        original_replicas = _non_negative_int(checkpointed_deployment.get("replicas"), fallback=0)
        if not deployment_uid or not _mapping(state.get("source_writer_gate")):
            raise SoperatorMigrationPhasePending(
                "accounting handoff cannot adopt a missing source accounting Deployment "
                "without its checkpointed UID and writer-disable intent."
            )
    existing_source_resource_name = str(state.get("source_resource_name") or "").strip()
    existing_source_cluster_name = str(state.get("source_cluster_name") or "").strip()
    existing_target_cluster_name = str(state.get("target_cluster_name") or "").strip()
    if (
        (existing_source_resource_name and existing_source_resource_name != source_resource_name)
        or (existing_source_cluster_name and existing_source_cluster_name != source_cluster_name)
        or (existing_target_cluster_name and existing_target_cluster_name != target_cluster_name)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source/target database identity changed during source writer pause."
        )
    state.update(
        {
            "status": "source-snapshotting",
            "source_resource_name": source_resource_name,
            "source_cluster_name": source_cluster_name,
            "target_cluster_name": target_cluster_name,
            "target_resource_name": target_ref,
            "source": source_identity,
            "source_accounting_deployment": {
                "uid": deployment_uid,
                "replicas": original_replicas,
            },
        }
    )
    _accounting_handoff_bind_source_writer_lineage(
        state=state,
        deployment=deployment,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    source_database_tables = _accounting_handoff_database_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
    )
    dump = _accounting_handoff_dump_source_database(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
    )
    evidence = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=source_pod,
        source_cluster_name=source_cluster_name,
    )
    dump_path = artifact_dir / _ACCOUNTING_HANDOFF_DUMP_FILENAME
    _write_sensitive_text_atomic(dump_path, dump)
    state.update(
        {
            "status": "source-snapshot",
            "source_history": evidence,
            "source_database_tables": list(source_database_tables),
            "dump": _accounting_handoff_dump_metadata(dump_path),
            "source_dump_generation": 0,
            "source_snapshot_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Accounting history handoff captured a preliminary source slurm_acct_db snapshot; "
        "the final dump will be sealed after both SlurmDBD writers are command-fenced "
        f"({evidence['jobs']} jobs, {evidence['steps']} steps)."
    ]


def _accounting_handoff_source_binding(
    *,
    phase: Mapping[str, Any],
    state: Mapping[str, Any],
) -> dict[str, str]:
    handoff_source = _mapping(_mapping(phase.get("slurmcluster_handoff_binding")).get("source"))
    command_source = _mapping(_mapping(state.get("source_writer_command_fence")).get("binding"))
    legacy_source = _mapping(_mapping(state.get("source_writer_gate")).get("binding"))
    candidates = []
    for raw in (handoff_source, command_source, legacy_source):
        candidate = {key: str(raw.get(key) or "").strip() for key in ("namespace", "name", "uid")}
        if any(candidate.values()):
            if not all(candidate.values()):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff source binding checkpoint is partial."
                )
            candidates.append(candidate)
    if not candidates or any(candidate != candidates[0] for candidate in candidates[1:]):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source binding checkpoints disagree."
        )
    binding = candidates[0]
    expected_name = _accounting_handoff_cluster_name(
        state.get("source_resource_name"),
        label="source SlurmCluster resource",
    )
    if (
        binding["namespace"] != _SOPERATOR_NAMESPACE
        or binding["name"] != expected_name
        or not binding["uid"]
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff requires the exact checkpointed source SlurmCluster "
            "namespace/name/UID binding."
        )
    return binding


def _accounting_handoff_target_binding(
    *,
    phase: Mapping[str, Any],
    state: Mapping[str, Any],
) -> dict[str, str]:
    binding = {
        key: str(
            _mapping(_mapping(phase.get("slurmcluster_handoff_binding")).get("target")).get(key)
            or ""
        ).strip()
        for key in ("namespace", "name", "uid")
    }
    for gate_key in ("target_writer_command_fence", "target_writer_gate"):
        gate_binding = {
            key: str(_mapping(_mapping(state.get(gate_key)).get("binding")).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        if any(gate_binding.values()) and gate_binding != binding:
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {gate_key} is bound to a different target SlurmCluster."
            )
    expected_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    if (
        binding["namespace"] != _SOPERATOR_NAMESPACE
        or binding["name"] != expected_name
        or not binding["uid"]
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target import requires the exact checkpointed "
            "SlurmCluster namespace/name/UID binding from the successful Helm handoff."
        )
    return binding


def _accounting_handoff_revalidate_target_mariadb_identity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    expected: Mapping[str, Any],
    target_binding: Mapping[str, Any],
) -> dict[str, Any]:
    observed = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        expected_slurmcluster_binding=target_binding,
    )
    if any(
        observed.get(key) != expected.get(key) for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target MariaDB Pod/PVC identity changed while the "
            "target writer was being paused; import intent was not checkpointed."
        )
    return observed


def _accounting_handoff_slurmdbd_spec(resource: Mapping[str, Any]) -> dict[str, Any]:
    accounting = _mapping(
        _mapping(_mapping(resource.get("spec")).get("slurmNodes")).get("accounting")
    )
    return dict(_mapping(accounting.get("slurmdbd")))


def _accounting_handoff_writer_command_config(
    resource: Mapping[str, Any],
) -> dict[str, Any]:
    slurmdbd = _accounting_handoff_slurmdbd_spec(resource)

    def _field(name: str) -> tuple[bool, list[str]]:
        if name not in slurmdbd:
            return False, []
        raw = slurmdbd.get(name)
        if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes, bytearray)):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff SlurmDBD {name} must be a string array."
            )
        values = [str(item) for item in raw]
        if any(not value for value in values):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff SlurmDBD {name} contains an empty item."
            )
        return True, values

    command_present, command = _field("command")
    args_present, args = _field("args")
    return {
        "command_present": command_present,
        "command": command,
        "args_present": args_present,
        "args": args,
    }


def _accounting_handoff_writer_config_identity(
    config: Mapping[str, Any],
) -> dict[str, Any]:
    command_present = config.get("command_present")
    args_present = config.get("args_present")
    command = config.get("command")
    args = config.get("args")
    if (
        not isinstance(command_present, bool)
        or not isinstance(args_present, bool)
        or not isinstance(command, Sequence)
        or isinstance(command, (str, bytes, bytearray))
        or not isinstance(args, Sequence)
        or isinstance(args, (str, bytes, bytearray))
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff SlurmDBD command identity source is malformed."
        )
    normalized_command = [str(item) for item in command]
    normalized_args = [str(item) for item in args]
    if (
        any(not item for item in (*normalized_command, *normalized_args))
        or (not command_present and normalized_command)
        or (not args_present and normalized_args)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff SlurmDBD command identity source has inconsistent shape."
        )
    normalized = {
        "command_present": command_present,
        "command": normalized_command,
        "args_present": args_present,
        "args": normalized_args,
    }
    return {
        "schema": _ACCOUNTING_HANDOFF_WRITER_CONFIG_IDENTITY_SCHEMA,
        "command_present": command_present,
        "command_items": len(normalized_command),
        "command_sha256": _fingerprint(normalized_command),
        "args_present": args_present,
        "args_items": len(normalized_args),
        "args_sha256": _fingerprint(normalized_args),
        "config_sha256": _fingerprint(normalized),
    }


def _accounting_handoff_validated_writer_config_identity(
    value: Any,
    *,
    label: str,
) -> dict[str, Any]:
    identity = _mapping(value)
    expected_keys = {
        "schema",
        "command_present",
        "command_items",
        "command_sha256",
        "args_present",
        "args_items",
        "args_sha256",
        "config_sha256",
    }
    hashes = (
        str(identity.get("command_sha256") or ""),
        str(identity.get("args_sha256") or ""),
        str(identity.get("config_sha256") or ""),
    )
    if (
        set(identity) != expected_keys
        or identity.get("schema") != _ACCOUNTING_HANDOFF_WRITER_CONFIG_IDENTITY_SCHEMA
        or not isinstance(identity.get("command_present"), bool)
        or not isinstance(identity.get("args_present"), bool)
        or not isinstance(identity.get("command_items"), int)
        or isinstance(identity.get("command_items"), bool)
        or int(identity.get("command_items", -1)) < 0
        or not isinstance(identity.get("args_items"), int)
        or isinstance(identity.get("args_items"), bool)
        or int(identity.get("args_items", -1)) < 0
        or (not identity.get("command_present") and identity.get("command_items") != 0)
        or (not identity.get("args_present") and identity.get("args_items") != 0)
        or any(re.fullmatch(r"[0-9a-f]{64}", item) is None for item in hashes)
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} writer command identity is incomplete or malformed."
        )
    return dict(identity)


def _accounting_handoff_writer_config_matches_identity(
    config: Mapping[str, Any],
    identity: Mapping[str, Any],
) -> bool:
    return _accounting_handoff_writer_config_identity(config) == dict(identity)


def _accounting_handoff_workload_writer_config(
    container: Mapping[str, Any],
    *,
    label: str,
) -> dict[str, Any]:
    def _field(name: str) -> tuple[bool, list[str]]:
        if name not in container:
            return False, []
        raw = container.get(name)
        if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes, bytearray)):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} {name} must be a string array."
            )
        values = [str(item) for item in raw]
        if any(not value for value in values):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} {name} contains an empty item."
            )
        return True, values

    command_present, command = _field("command")
    args_present, args = _field("args")
    return {
        "command_present": command_present,
        "command": command,
        "args_present": args_present,
        "args": args,
    }


def _accounting_handoff_writer_command_is_fenced(resource: Mapping[str, Any]) -> bool:
    config = _accounting_handoff_writer_command_config(resource)
    return config["command"] == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND) and config[
        "args"
    ] == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)


def _accounting_handoff_resource_version_conflict(error: BaseException) -> bool:
    current: BaseException | None = error
    for _depth in range(4):
        if current is None:
            break
        detail = str(current).lower()
        if "conflict" in detail or "object has been modified" in detail:
            return True
        current = current.__cause__ or current.__context__
    return False


def _accounting_handoff_patch_exact_writer_command(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    binding: Mapping[str, Any],
    command_present: bool,
    command: Sequence[str],
    args_present: bool,
    args: Sequence[str],
    enabled: bool,
    label: str,
    expected_resource_version: str,
) -> tuple[str, Mapping[str, Any]]:
    resource_version = str(expected_resource_version or "").strip()
    if not resource_version:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmDBD command mutation lacks the exact "
            "resourceVersion inspected with its live command/args."
        )
    slurmdbd_patch: dict[str, Any] = {
        "command": list(command) if command_present else None,
        "args": list(args) if args_present else None,
    }
    try:
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"slurmcluster/{str(binding.get('name') or '').strip()}",
            namespace=str(binding.get("namespace") or "").strip(),
            patch_via_stdin=True,
            patch={
                "metadata": {
                    "uid": str(binding.get("uid") or "").strip(),
                    "resourceVersion": resource_version,
                },
                "spec": {
                    "slurmNodes": {
                        "accounting": {
                            "enabled": enabled,
                            "slurmdbd": slurmdbd_patch,
                        }
                    }
                },
            },
        )
    except Exception as exc:
        if _accounting_handoff_resource_version_conflict(exc):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} SlurmDBD command fence lost its exact "
                "resourceVersion compare-and-set."
            ) from exc
        raise SoperatorMigrationPhasePending(
            f"accounting handoff could not compare-and-set the exact {label} SlurmDBD "
            "command fence."
        ) from exc
    updated_resource, updated_resource_version, updated_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=binding,
            label=label,
        )
    )
    expected = {
        "command_present": command_present,
        "command": list(command),
        "args_present": args_present,
        "args": list(args),
    }
    if (
        updated_enabled is not enabled
        or _accounting_handoff_writer_command_config(updated_resource) != expected
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmDBD command did not converge to its exact "
            "checkpointed value."
        )
    return updated_resource_version, updated_resource


def _accounting_handoff_apply_writer_command_fence(
    *,
    state: dict[str, Any],
    gate_key: str,
    binding: Mapping[str, Any],
    label: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    normalized_binding = {
        key: str(binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    if normalized_binding["namespace"] != _SOPERATOR_NAMESPACE or not all(
        normalized_binding.values()
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} writer fence binding is incomplete."
        )
    gate = state.setdefault(gate_key, {})
    if not isinstance(gate, dict):
        raise RuntimeError(f"accounting handoff {gate_key} must be a mapping.")
    resource, resource_version, enabled = _accounting_handoff_exact_slurmcluster(
        command_runner=command_runner,
        kube_context=kube_context,
        binding=normalized_binding,
        label=label,
    )
    if not gate:
        if _accounting_handoff_writer_command_is_fenced(resource):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff found the canonical {label} SlurmDBD command fence "
                "without its preceding durable intent; cxcli will not adopt ambiguous "
                "external writer state."
            )
        deployment = _accounting_handoff_deployment_state(
            command_runner=command_runner,
            kube_context=kube_context,
            allow_missing=True,
        )
        pre_fence_replica_sets: tuple[str, ...] = ()
        if (
            deployment.get("exists")
            and str(deployment.get("owner_uid") or "") == normalized_binding["uid"]
        ):
            pre_fence_replica_sets = _accounting_handoff_source_replica_set_uids(
                command_runner=command_runner,
                kube_context=kube_context,
                deployment_uid=str(deployment.get("uid") or ""),
            )
        gate.update(
            {
                "schema": _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA,
                "binding": normalized_binding,
                "status": "fence-intent",
                "original_enabled": enabled,
                "original_writer_identity": _accounting_handoff_writer_config_identity(
                    _accounting_handoff_writer_command_config(resource)
                ),
                "observed_resource_version": resource_version,
                "pre_fence_deployment_uid": str(deployment.get("uid") or ""),
                "pre_fence_replica_sets": list(pre_fence_replica_sets),
                "intent_recorded_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if (
        gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or {
            key: str(_mapping(gate.get("binding")).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        != normalized_binding
        or not isinstance(gate.get("original_enabled"), bool)
        or not isinstance(gate.get("original_writer_identity"), Mapping)
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} writer command fence checkpoint is incomplete or "
            "bound to a different SlurmCluster."
        )
    if label == "target" and gate.get("original_enabled") is not True:
        raise SoperatorMigrationPhasePending(
            "accounting handoff refuses to command-fence a target SlurmCluster whose "
            "checkpointed accounting state was disabled."
        )
    original_writer_identity = _accounting_handoff_validated_writer_config_identity(
        gate.get("original_writer_identity"),
        label=label,
    )
    for attempt in range(1, _ACCOUNTING_HANDOFF_WRITER_FENCE_CAS_ATTEMPTS + 1):
        live_writer_config = _accounting_handoff_writer_command_config(resource)
        already_fenced = enabled and _accounting_handoff_writer_command_is_fenced(resource)
        still_checkpointed_original = enabled == gate.get(
            "original_enabled"
        ) and _accounting_handoff_writer_config_matches_identity(
            live_writer_config,
            original_writer_identity,
        )
        if not already_fenced and not still_checkpointed_original:
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} SlurmDBD enabled/command/args drifted after "
                "fence intent; cxcli did not overwrite the external change."
            )
        if already_fenced:
            updated_resource_version, updated_resource = resource_version, resource
            break
        try:
            updated_resource_version, updated_resource = (
                _accounting_handoff_patch_exact_writer_command(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    binding=normalized_binding,
                    command_present=True,
                    command=_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND,
                    args_present=True,
                    args=_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS,
                    enabled=True,
                    label=label,
                    expected_resource_version=resource_version,
                )
            )
            break
        except SoperatorMigrationPhasePending as exc:
            if (
                not _accounting_handoff_resource_version_conflict(exc)
                or attempt >= _ACCOUNTING_HANDOFF_WRITER_FENCE_CAS_ATTEMPTS
            ):
                raise
            resource, resource_version, enabled = _accounting_handoff_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=normalized_binding,
                label=label,
            )
    else:  # pragma: no cover - bounded loop always breaks or raises
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmDBD command fence exhausted its exact "
            "resourceVersion compare-and-set attempts."
        )
    if not _accounting_handoff_writer_command_is_fenced(updated_resource):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} SlurmDBD command fence did not converge."
        )
    gate.update(
        {
            "status": "applied",
            "applied_resource_version": updated_resource_version,
            "applied_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return gate


def _accounting_handoff_deployment_selector(
    deployment: Mapping[str, Any],
) -> dict[str, str]:
    raw_selector = _mapping(deployment.get("selector"))
    selector = {
        str(key): str(value)
        for key, value in raw_selector.items()
        if str(key).strip() and str(value).strip()
    }
    if not selector:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot bind deployment/accounting Pods because the "
            "Deployment selector is empty."
        )
    return selector


def _accounting_handoff_selector_pods(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    selector: Mapping[str, str],
    deployment_uid: str,
) -> tuple[dict[str, Any], ...]:
    replica_set_uids = set(
        _accounting_handoff_source_replica_set_uids(
            command_runner=command_runner,
            kube_context=kube_context,
            deployment_uid=deployment_uid,
        )
    )
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    result: list[dict[str, Any]] = []
    for item in _sequence_of_mappings(payload.get("items")):
        metadata = _mapping(item.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        if any(str(labels.get(key) or "") != value for key, value in selector.items()):
            continue
        owner_uids = {
            str(owner.get("uid") or "").strip()
            for owner in _sequence_of_mappings(metadata.get("ownerReferences"))
            if str(owner.get("kind") or "").strip() == "ReplicaSet"
            and owner.get("controller") is True
            and str(owner.get("uid") or "").strip()
        }
        conditions = {
            str(condition.get("type") or ""): str(condition.get("status") or "")
            for condition in _sequence_of_mappings(_mapping(item.get("status")).get("conditions"))
        }
        writer_containers = tuple(
            container
            for container in _sequence_of_mappings(_mapping(item.get("spec")).get("containers"))
            if str(container.get("name") or "").strip() == "accounting"
        )
        writer_config = (
            _accounting_handoff_workload_writer_config(
                writer_containers[0],
                label="accounting Pod writer container",
            )
            if len(writer_containers) == 1
            else {}
        )
        writer_status = next(
            (
                status
                for status in _sequence_of_mappings(
                    _mapping(item.get("status")).get("containerStatuses")
                )
                if str(status.get("name") or "").strip() == "accounting"
            ),
            {},
        )
        result.append(
            {
                "name": str(metadata.get("name") or "").strip(),
                "uid": str(metadata.get("uid") or "").strip(),
                "resource_version": str(metadata.get("resourceVersion") or "").strip(),
                "labels": {
                    str(key): str(value)
                    for key, value in labels.items()
                    if str(key).strip() and str(value).strip()
                },
                "owned": len(owner_uids) == 1 and owner_uids.issubset(replica_set_uids),
                "deleting": bool(metadata.get("deletionTimestamp")),
                "host_network": _mapping(item.get("spec")).get("hostNetwork") is True,
                "node_name": str(_mapping(item.get("spec")).get("nodeName") or "").strip(),
                "pod_ip": str(_mapping(item.get("status")).get("podIP") or "").strip(),
                "phase": str(_mapping(item.get("status")).get("phase") or "").strip(),
                "ready": conditions.get("Ready") == "True",
                "writer_container_count": len(writer_containers),
                "writer_image": str(
                    writer_containers[0].get("image") if len(writer_containers) == 1 else ""
                ).strip(),
                "writer_image_id": str(writer_status.get("imageID") or "").strip(),
                "writer_command_present": bool(writer_config.get("command_present")),
                "writer_command": list(writer_config.get("command") or []),
                "writer_args_present": bool(writer_config.get("args_present")),
                "writer_args": list(writer_config.get("args") or []),
            }
        )
    return tuple(result)


def _accounting_handoff_deployment_writer_is_fenced(
    deployment: Mapping[str, Any],
) -> bool:
    container = next(
        (
            item
            for item in _sequence_of_mappings(deployment.get("template_containers"))
            if str(item.get("name") or "").strip() == "accounting"
        ),
        {},
    )
    return list(container.get("command") or []) == list(
        _ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND
    ) and list(container.get("args") or []) == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)


def _accounting_handoff_reconcile_writer_deployment_command_fence(
    *,
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    """CAS-fence the shared accounting Deployment when dual-CR reconcile cannot own it."""

    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    deployment_uid = str(deployment.get("uid") or "").strip()
    owner_uid = str(deployment.get("owner_uid") or "").strip()
    allowed_owner_uids = {
        str(binding.get("uid") or "").strip()
        for binding in (source_binding, target_binding)
        if str(binding.get("uid") or "").strip()
    }
    if (
        not deployment_uid
        or owner_uid not in allowed_owner_uids
        or str(deployment.get("strategy_type") or "") != "Recreate"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot directly command-fence the shared accounting "
            "Deployment without its exact source/target owner and Recreate strategy."
        )
    containers = tuple(_sequence_of_mappings(deployment.get("template_containers")))
    writer_indexes = tuple(
        index
        for index, container in enumerate(containers)
        if str(container.get("name") or "").strip() == "accounting"
    )
    if len(writer_indexes) != 1:
        raise SoperatorMigrationPhasePending(
            "accounting handoff requires exactly one accounting writer container before "
            "direct Deployment command fencing."
        )
    writer_index = writer_indexes[0]
    live_config = _accounting_handoff_workload_writer_config(
        containers[writer_index],
        label="accounting Deployment writer container",
    )
    owner_gate_key = (
        "source_writer_command_fence"
        if owner_uid == str(source_binding.get("uid") or "").strip()
        else "target_writer_command_fence"
    )
    owner_gate = _mapping(state.get(owner_gate_key))
    original_identity = _accounting_handoff_validated_writer_config_identity(
        owner_gate.get("original_writer_identity"),
        label="shared accounting Deployment",
    )
    gate = state.setdefault("writer_deployment_command_fence", {})
    if not isinstance(gate, dict):
        raise RuntimeError("accounting handoff writer_deployment_command_fence must be a mapping.")
    expected_contract = {
        "schema": _ACCOUNTING_HANDOFF_WRITER_DEPLOYMENT_FENCE_SCHEMA,
        "deployment_uid": deployment_uid,
        "owner_uid": owner_uid,
        "container_name": "accounting",
        "container_index": writer_index,
        "original_writer_identity": original_identity,
    }
    if gate:
        if any(gate.get(key) != value for key, value in expected_contract.items()):
            raise SoperatorMigrationPhasePending(
                "accounting handoff shared Deployment command-fence checkpoint changed "
                "identity or owner."
            )
    else:
        gate.update(
            {
                **expected_contract,
                "status": "fence-intent",
                "observed_resource_version": str(deployment.get("resource_version") or "").strip(),
                "intent_recorded_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if _accounting_handoff_deployment_writer_is_fenced(deployment):
        recovered_from_live_state = gate.get("status") != "applied"
        gate.update(
            {
                "status": "applied",
                "applied_resource_version": str(deployment.get("resource_version") or "").strip(),
                "applied_at": gate.get("applied_at") or _utc_now(),
                "recovered_from_live_state": recovered_from_live_state,
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return gate
    if not _accounting_handoff_writer_config_matches_identity(live_config, original_identity):
        raise SoperatorMigrationPhasePending(
            "accounting handoff shared Deployment writer command drifted after the exact "
            "direct-fence intent; cxcli did not overwrite the external change."
        )
    resource_version = str(deployment.get("resource_version") or "").strip()
    if not resource_version:
        raise SoperatorMigrationPhasePending(
            "accounting handoff shared Deployment lacks resourceVersion before direct fencing."
        )
    gate.update(
        {
            "status": "dispatching",
            "dispatching_resource_version": resource_version,
            "dispatching_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    base_path = f"/spec/template/spec/containers/{writer_index}"
    patch: list[dict[str, Any]] = [
        {"op": "test", "path": "/metadata/uid", "value": deployment_uid},
        {
            "op": "test",
            "path": "/metadata/resourceVersion",
            "value": resource_version,
        },
        {"op": "test", "path": "/spec/strategy/type", "value": "Recreate"},
        {"op": "test", "path": f"{base_path}/name", "value": "accounting"},
    ]
    for field, desired in (
        ("command", list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)),
        ("args", list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)),
    ):
        present = bool(live_config.get(f"{field}_present"))
        if present:
            patch.append(
                {
                    "op": "test",
                    "path": f"{base_path}/{field}",
                    "value": list(live_config.get(field) or []),
                }
            )
        patch.append(
            {
                "op": "replace" if present else "add",
                "path": f"{base_path}/{field}",
                "value": desired,
            }
        )
    try:
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "patch",
                "deployment/accounting",
                "--type=json",
                "--patch-file",
                "/dev/stdin",
            ],
            input_text=json.dumps(patch, separators=(",", ":")),
            timeout_seconds=300,
        )
    except Exception as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not compare-and-set the exact shared Deployment "
            "command fence."
        ) from exc
    updated = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if (
        str(updated.get("uid") or "").strip() != deployment_uid
        or str(updated.get("owner_uid") or "").strip() != owner_uid
        or not _accounting_handoff_deployment_writer_is_fenced(updated)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff shared Deployment command fence did not converge to its "
            "exact UID/owner-bound state."
        )
    gate.update(
        {
            "status": "applied",
            "applied_resource_version": str(updated.get("resource_version") or "").strip(),
            "applied_at": _utc_now(),
            "recovered_from_live_state": False,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return gate


def _accounting_handoff_writer_pod_has_no_listener(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> bool:
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "-c",
            "accounting",
            "--",
            "/bin/bash",
            "-lc",
            (
                "if command -v ss >/dev/null 2>&1; then "
                "test -z \"$(ss -Hln 'sport = :6819' 2>/dev/null)\"; "
                "elif command -v netstat >/dev/null 2>&1; then "
                "! netstat -lnt 2>/dev/null | awk 'NR > 2 {print $4}' | grep -Eq '(^|:)6819$'; "
                "elif test -r /proc/net/tcp; then "
                "proc_net_files=/proc/net/tcp; "
                "if test -r /proc/net/tcp6; then "
                'proc_net_files="$proc_net_files /proc/net/tcp6"; fi; '
                '! awk \'NR > 1 && $2 ~ /:1AA3$/ && $4 == "0A" { found=1 } '
                "END { exit found ? 0 : 1 }' $proc_net_files; "
                "else exit 2; fi"
            ),
        ],
        timeout_seconds=30,
        check=False,
    )
    return result.returncode == 0


def _accounting_handoff_database_connection_count(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> int:
    query = (
        "SELECT COUNT(*) FROM information_schema.PROCESSLIST "
        "WHERE ID <> CONNECTION_ID() AND DB = 'slurm_acct_db'"
    )
    script = (
        _ACCOUNTING_HANDOFF_CLIENT_PREAMBLE
        + "client_bin=$(command -v mariadb || command -v mysql); "
        + 'test -n "$client_bin"; '
        + '"$client_bin" --defaults-extra-file="$defaults_file" '
        + "--skip-force --skip-reconnect --batch --skip-column-names "
        + f"-e {shlex.quote(query)}"
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "--",
            "bash",
            "-lc",
            script,
        ],
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0 or not str(result.stdout or "").strip().isdecimal():
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not prove the MariaDB connection set was quiet "
            "under the SlurmDBD command fence."
        )
    return int(str(result.stdout).strip())


def _accounting_handoff_pre_fence_replica_sets(
    state: Mapping[str, Any],
) -> tuple[str, ...]:
    gates = (
        _mapping(state.get("source_writer_command_fence")),
        _mapping(state.get("target_writer_command_fence")),
        _mapping(state.get("source_writer_gate")),
    )
    result: list[str] = []
    for gate in gates:
        raw = gate.get("pre_fence_replica_sets") or gate.get("source_replica_sets")
        if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes, bytearray)):
            continue
        result.extend(str(item or "").strip() for item in raw if str(item or "").strip())
    return tuple(dict.fromkeys(result))


def _accounting_handoff_source_retirement_checkpoint_is_exact(
    *,
    phase: Mapping[str, Any],
    state: Mapping[str, Any],
    source_binding: Mapping[str, Any],
) -> bool:
    recovery = _mapping(state.get("source_orphan_finalizer_recovery"))
    recovery_source = _mapping(recovery.get("source"))
    return bool(
        recovery.get("status") == "verified"
        and str(recovery.get("verified_at") or "").strip()
        and str(phase.get("source_accounting_owner_retired_at") or "").strip()
        and all(
            str(recovery_source.get(key) or "").strip()
            == str(source_binding.get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        )
    )


def _accounting_handoff_deployment_owner_matches_retirement(
    *,
    state: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    source_resource: Mapping[str, Any],
    deployment: Mapping[str, Any],
    phase: Mapping[str, Any] | None = None,
) -> bool:
    """Accept the exact ownerless writer after Kubernetes accepted orphan deletion."""

    owner_uid = str(deployment.get("owner_uid") or "").strip()
    if owner_uid in {
        str(source_binding.get("uid") or "").strip(),
        str(target_binding.get("uid") or "").strip(),
    }:
        return True
    source_metadata = _mapping(source_resource.get("metadata"))
    exact_deleting_source = bool(
        str(source_metadata.get("uid") or "").strip()
        == str(source_binding.get("uid") or "").strip()
        and str(source_metadata.get("deletionTimestamp") or "").strip()
        and source_metadata.get("finalizers") == ["orphan"]
    )
    exact_retired_source = bool(
        phase is not None
        and _accounting_handoff_source_retirement_checkpoint_is_exact(
            phase=phase,
            state=state,
            source_binding=source_binding,
        )
    )
    if owner_uid or not (exact_deleting_source or exact_retired_source):
        return False
    try:
        checkpointed = _source_cleanup_checkpointed_child_bindings(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            required=True,
        )
    except SoperatorMigrationPhasePending:
        return False
    accounting_path = f"/apis/apps/v1/namespaces/{_SOPERATOR_NAMESPACE}/deployments/accounting"
    return bool(
        str(_mapping(_mapping(checkpointed).get(accounting_path)).get("uid") or "").strip()
        == str(deployment.get("uid") or "").strip()
    )


def _accounting_handoff_transition_ownerless_deployment_selector(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    timeout_seconds: int = 300,
) -> dict[str, Any]:
    """Replace the exact retired-source Deployment whose selector cannot be mutated."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "accounting Deployment selector handoff requires durable checkpoint writes."
        )
    state = _accounting_handoff_state(phase)
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    if not _accounting_handoff_source_retirement_checkpoint_is_exact(
        phase=phase,
        state=state,
        source_binding=source_binding,
    ):
        raise SoperatorMigrationPhasePending(
            "accounting Deployment selector handoff requires exact source retirement proof."
        )
    checkpointed = _source_cleanup_checkpointed_child_bindings(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        required=True,
    )
    accounting_path = f"/apis/apps/v1/namespaces/{_SOPERATOR_NAMESPACE}/deployments/accounting"
    source_deployment = _mapping(_mapping(checkpointed).get(accounting_path))
    source_uid = str(source_deployment.get("uid") or "").strip()
    source_gate = _mapping(state.get("source_writer_command_fence"))
    target_gate = _mapping(state.get("target_writer_command_fence"))
    writer_gate = _mapping(state.get("target_writer_gate"))
    retired_fence = _mapping(state.get("target_command_fence_after_source_retirement"))
    transition = state.setdefault("deployment_selector_handoff", {})
    if not isinstance(transition, dict):
        raise RuntimeError("accounting deployment_selector_handoff must be a mapping.")
    target_selector = {
        "app.kubernetes.io/component": "accounting",
        "app.kubernetes.io/instance": target_binding["name"],
        "app.kubernetes.io/name": "slurmcluster",
    }
    source_selector = {
        str(key): str(value)
        for key, value in _mapping(
            transition.get("source_selector")
            if transition
            else writer_gate.get("deployment_selector")
        ).items()
    }
    if not source_selector or source_selector == target_selector:
        raise SoperatorMigrationPhasePending(
            "accounting Deployment selector handoff requires distinct exact source and "
            "target selectors."
        )
    if transition and (
        transition.get("schema") != "nebius-cxcli-accounting-deployment-selector-handoff-v1"
        or str(transition.get("source_uid") or "").strip() != source_uid
        or _mapping(transition.get("source_selector")) != source_selector
        or _mapping(transition.get("target_selector")) != target_selector
    ):
        raise SoperatorMigrationPhasePending(
            "accounting Deployment selector handoff checkpoint drifted from its exact "
            "source/target contract."
        )
    transition_complete = transition.get("status") == "target-created"
    target_uid = str(transition.get("target_uid") or "").strip()
    writer_restored_after_transition = bool(
        transition_complete
        and str(state.get("status") or "").strip()
        in {"target-enabling", "target-enabled", "verified"}
        and source_gate.get("schema") == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        and source_gate.get("status") == "verified"
        and target_gate.get("schema") == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        and target_gate.get("status") == "restored"
        and str(target_gate.get("restored_at") or "").strip()
        and writer_gate.get("schema") == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        and writer_gate.get("status") == "enabled"
        and str(writer_gate.get("enabled_at") or "").strip()
        and str(writer_gate.get("deployment_uid") or "").strip() == target_uid
        and str(writer_gate.get("enabled_deployment_uid") or "").strip() == target_uid
        and _mapping(writer_gate.get("deployment_selector")) == target_selector
        and retired_fence.get("status") == "verified"
        and str(retired_fence.get("deployment_uid") or "").strip() == target_uid
    )
    if writer_restored_after_transition:
        deployment = _accounting_handoff_assert_target_writer_ready(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if (
            str(deployment.get("uid") or "").strip() != target_uid
            or str(deployment.get("owner_uid") or "").strip() != target_binding["uid"]
            or _accounting_handoff_deployment_selector(deployment) != target_selector
            or str(deployment.get("strategy_type") or "").strip() != "Recreate"
        ):
            raise SoperatorMigrationPhasePending(
                "completed accounting Deployment selector handoff drifted from its exact "
                "target UID, owner, selector, or strategy."
            )
        return transition
    expected_live_uid = target_uid if transition_complete else source_uid
    expected_live_selector = target_selector if transition_complete else source_selector
    if (
        not source_uid
        or (transition_complete and not target_uid)
        or str(_mapping(state.get("source_accounting_deployment")).get("uid") or "").strip()
        != source_uid
        or any(
            gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
            or gate.get("status") != "verified"
            for gate in (source_gate, target_gate)
        )
        or writer_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or writer_gate.get("status") != "disabled"
        or str(writer_gate.get("deployment_uid") or "").strip() != expected_live_uid
        or _mapping(writer_gate.get("deployment_selector")) != expected_live_selector
        or retired_fence.get("status") != "verified"
        or str(retired_fence.get("deployment_uid") or "").strip() != expected_live_uid
    ):
        raise SoperatorMigrationPhasePending(
            "accounting Deployment selector handoff lacks the exact disabled-writer, "
            "retired-source, or immutable Deployment binding."
        )
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        deployment = _accounting_handoff_deployment_state(
            command_runner=command_runner,
            kube_context=kube_context,
            allow_missing=True,
        )
        if deployment.get("exists"):
            live_uid = str(deployment.get("uid") or "").strip()
            live_selector = _accounting_handoff_deployment_selector(deployment)
            if live_uid == source_uid:
                if transition.get("source_deleted_at"):
                    raise SoperatorMigrationPhasePending(
                        "retired-source accounting Deployment UID reappeared after deletion."
                    )
                if (
                    str(deployment.get("owner_uid") or "").strip()
                    or live_selector != source_selector
                    or str(deployment.get("strategy_type") or "").strip() != "Recreate"
                    or not _accounting_handoff_deployment_writer_is_fenced(deployment)
                ):
                    raise SoperatorMigrationPhasePending(
                        "retired-source accounting Deployment changed before its exact "
                        "selector transition."
                    )
                resource_version = str(deployment.get("resource_version") or "").strip()
                if not transition.get("delete_intent_at"):
                    transition.update(
                        {
                            "schema": ("nebius-cxcli-accounting-deployment-selector-handoff-v1"),
                            "status": "delete-intent",
                            "source_uid": source_uid,
                            "source_resource_version": resource_version,
                            "source_selector": source_selector,
                            "target_selector": target_selector,
                            "delete_intent_at": _utc_now(),
                        }
                    )
                    checkpoint_writer()
                elif str(transition.get("source_resource_version") or "").strip() != (
                    resource_version
                ):
                    raise SoperatorMigrationPhasePending(
                        "retired-source accounting Deployment resourceVersion changed after "
                        "delete intent."
                    )
                _command_runner_uid_preconditioned_delete(
                    command_runner,
                    kube_context=kube_context,
                    api_path=accounting_path,
                    uid=source_uid,
                    resource_version=resource_version,
                    propagation_policy="Orphan",
                    timeout_seconds=120,
                    mutation_guard=mutation_guard,
                )
                transition.update(
                    {
                        "status": "source-deleted",
                        "source_deleted_at": _utc_now(),
                    }
                )
                checkpoint_writer()
                continue
            else:
                if (
                    str(deployment.get("owner_uid") or "").strip() != target_binding["uid"]
                    or live_selector != target_selector
                    or str(deployment.get("strategy_type") or "").strip() != "Recreate"
                    or not _accounting_handoff_deployment_writer_is_fenced(deployment)
                ):
                    raise SoperatorMigrationPhasePending(
                        "replacement accounting Deployment lacks its exact target owner, "
                        "selector, strategy, or writer fence."
                    )
                transition.update(
                    {
                        "status": "target-created",
                        "target_uid": live_uid,
                        "target_resource_version": str(
                            deployment.get("resource_version") or ""
                        ).strip(),
                        "target_created_at": transition.get("target_created_at") or _utc_now(),
                    }
                )
                checkpoint_writer()
                return transition
        elif not transition.get("delete_intent_at"):
            raise SoperatorMigrationPhasePending(
                "accounting Deployment disappeared before its durable selector-handoff intent."
            )
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target-owned accounting Deployment did not appear after the exact "
                "retired-source selector transition."
            )
        time.sleep(2)


def _accounting_handoff_wait_writer_command_fences(
    *,
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    source_pod: str,
    target_pod: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    timeout_seconds: int = 900,
) -> dict[str, Any]:
    bindings = (source_binding, target_binding)
    gates = (
        _mapping(state.get("source_writer_command_fence")),
        _mapping(state.get("target_writer_command_fence")),
    )
    normalized_bindings = tuple(
        {key: str(binding.get(key) or "").strip() for key in ("namespace", "name", "uid")}
        for binding in bindings
    )
    if any(
        gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or str(gate.get("status") or "") not in {"applied", "verified"}
        or {
            key: str(_mapping(gate.get("binding")).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        != binding
        for gate, binding in zip(gates, normalized_bindings, strict=True)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff requires both exact SlurmDBD command-fence intents before "
            "writer convergence."
        )
    pre_fence_replica_sets = _accounting_handoff_pre_fence_replica_sets(state)
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        crs_fenced = True
        source_resource: Mapping[str, Any] = {}
        for binding, label in zip(bindings, ("source", "target"), strict=True):
            resource, _resource_version, enabled = _accounting_handoff_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=binding,
                label=label,
            )
            crs_fenced = (
                crs_fenced and enabled and _accounting_handoff_writer_command_is_fenced(resource)
            )
            if label == "source":
                source_resource = resource
        deployment = _accounting_handoff_deployment_state(
            command_runner=command_runner,
            kube_context=kube_context,
            allow_missing=True,
        )
        owner_uid = str(deployment.get("owner_uid") or "").strip()
        exact_owner = _accounting_handoff_deployment_owner_matches_retirement(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            source_resource=source_resource,
            deployment=deployment,
        )
        selector = (
            _accounting_handoff_deployment_selector(deployment) if deployment.get("exists") else {}
        )
        pods = (
            _accounting_handoff_selector_pods(
                command_runner=command_runner,
                kube_context=kube_context,
                selector=selector,
                deployment_uid=str(deployment.get("uid") or ""),
            )
            if selector
            else ()
        )
        old_pods = _accounting_handoff_source_writer_pods(
            command_runner=command_runner,
            kube_context=kube_context,
            replica_set_uids=pre_fence_replica_sets,
        )
        replicas = _non_negative_int(deployment.get("replicas"), fallback=0)
        deployment_converged = bool(
            deployment.get("exists")
            and exact_owner
            and str(deployment.get("strategy_type") or "") == "Recreate"
            and _accounting_handoff_deployment_writer_is_fenced(deployment)
            and _non_negative_int(deployment.get("observed_generation"), fallback=0)
            >= _non_negative_int(deployment.get("generation"), fallback=0)
            and _non_negative_int(deployment.get("status_replicas"), fallback=0) == replicas
            and _non_negative_int(deployment.get("updated_replicas"), fallback=0) == replicas
        )
        pods_fenced = bool(
            not old_pods
            and replicas > 0
            and len(pods) == replicas
            and all(
                not pod.get("deleting")
                and pod.get("owned") is True
                and str(pod.get("phase") or "") == "Running"
                and list(pod.get("writer_command") or [])
                == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
                and list(pod.get("writer_args") or [])
                == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
                for pod in pods
            )
        )
        listeners_absent = pods_fenced and all(
            _accounting_handoff_writer_pod_has_no_listener(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=str(pod.get("name") or ""),
            )
            for pod in pods
        )
        if crs_fenced and deployment_converged and pods_fenced and listeners_absent:
            source_connections = _accounting_handoff_database_connection_count(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=source_pod,
            )
            target_connections = _accounting_handoff_database_connection_count(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
            )
            if source_connections == 0 and target_connections == 0:
                proof = {
                    "status": "verified",
                    "deployment_uid": str(deployment.get("uid") or ""),
                    "deployment_owner_uid": owner_uid,
                    "deployment_generation": _non_negative_int(
                        deployment.get("generation"), fallback=0
                    ),
                    "pods": [str(pod.get("name") or "") for pod in pods],
                    "verified_at": _utc_now(),
                }
                state["writer_command_fence_proof"] = proof
                for gate in gates:
                    if isinstance(gate, dict):
                        gate["status"] = "verified"
                        gate["verified_at"] = proof["verified_at"]
                if checkpoint_writer is not None:
                    checkpoint_writer()
                return proof
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting handoff timed out proving both SlurmDBD command fences, "
                "retired writer Pod absence, port 6819 closure, and quiet DB connections."
            )
        time.sleep(5)


def _accounting_handoff_wait_target_command_fence_after_source_retirement(
    *,
    phase: Mapping[str, Any],
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    target_pod: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None = None,
    timeout_seconds: int = 900,
) -> dict[str, Any]:
    source_gate = _mapping(state.get("source_writer_command_fence"))
    target_gate = _mapping(state.get("target_writer_command_fence"))
    if (
        source_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or target_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or str(target_gate.get("status") or "") not in {"applied", "verified"}
        or not str(phase.get("source_cleanup_started_at") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot adopt a retired source before both exact command "
            "fences and source-cleanup intent are durable."
        )
    expected_target = _mapping(state.get("target"))
    if not expected_target:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target MariaDB binding is missing after source retirement."
        )
    expected_source = _mapping(state.get("source"))
    _accounting_handoff_assert_source_pvc_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        expected=expected_source,
    )
    dump = _mapping(state.get("dump"))
    seal = _mapping(state.get("source_dump_seal"))
    observed_dump = _accounting_handoff_dump_metadata(Path(str(dump.get("path") or "")))
    if (
        seal.get("schema") != _ACCOUNTING_HANDOFF_SOURCE_DUMP_SEAL_SCHEMA
        or seal.get("mode") != "dual-slurmdbd-command-fence"
        or seal.get("status") != "sealed"
        or str(seal.get("dump_sha256") or "") != str(dump.get("sha256") or "")
        or any(observed_dump.get(key) != dump.get(key) for key in ("size_bytes", "sha256"))
        or str(seal.get("source_pvc") or "") != str(expected_source.get("pvc") or "")
        or str(seal.get("source_pvc_uid") or "") != str(expected_source.get("pvc_uid") or "")
        or str(seal.get("target_pvc") or "") != str(expected_target.get("pvc") or "")
        or str(seal.get("target_pvc_uid") or "") != str(expected_target.get("pvc_uid") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff sealed dump or retained source/target PVC binding changed "
            "after source retirement."
        )
    manager_gap = _accounting_handoff_manager_paused_selector_gap(
        phase=phase,
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        target_pod=target_pod,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if manager_gap is not None:
        state["target_command_fence_manager_paused_gap"] = manager_gap
        if checkpoint_writer is not None:
            checkpoint_writer()
        return manager_gap
    pre_fence_replica_sets = _accounting_handoff_pre_fence_replica_sets(state)
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        source = _accounting_handoff_optional_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=source_binding,
            label="retired source",
        )
        target_resource, _target_resource_version, target_enabled = (
            _accounting_handoff_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=target_binding,
                label="target",
            )
        )
        deployment = _accounting_handoff_deployment_state(
            command_runner=command_runner,
            kube_context=kube_context,
            allow_missing=True,
        )
        selector = (
            _accounting_handoff_deployment_selector(deployment) if deployment.get("exists") else {}
        )
        pods = (
            _accounting_handoff_selector_pods(
                command_runner=command_runner,
                kube_context=kube_context,
                selector=selector,
                deployment_uid=str(deployment.get("uid") or ""),
            )
            if selector
            else ()
        )
        old_pods = _accounting_handoff_source_writer_pods(
            command_runner=command_runner,
            kube_context=kube_context,
            replica_set_uids=pre_fence_replica_sets,
        )
        replicas = _non_negative_int(deployment.get("replicas"), fallback=0)
        exact_owner = bool(
            str(deployment.get("owner_uid") or "") == str(target_binding.get("uid") or "")
            or _accounting_handoff_deployment_owner_matches_retirement(
                state=state,
                source_binding=source_binding,
                target_binding=target_binding,
                source_resource={},
                deployment=deployment,
                phase=phase,
            )
        )
        deployment_fenced = bool(
            source is None
            and target_enabled
            and _accounting_handoff_writer_command_is_fenced(target_resource)
            and deployment.get("exists")
            and exact_owner
            and str(deployment.get("strategy_type") or "") == "Recreate"
            and _accounting_handoff_deployment_writer_is_fenced(deployment)
            and replicas > 0
            and _non_negative_int(deployment.get("observed_generation"), fallback=0)
            >= _non_negative_int(deployment.get("generation"), fallback=0)
            and _non_negative_int(deployment.get("status_replicas"), fallback=0) == replicas
            and _non_negative_int(deployment.get("updated_replicas"), fallback=0) == replicas
        )
        pods_fenced = bool(
            not old_pods
            and len(pods) == replicas
            and all(
                pod.get("owned") is True
                and not pod.get("deleting")
                and str(pod.get("phase") or "") == "Running"
                and list(pod.get("writer_command") or [])
                == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
                and list(pod.get("writer_args") or [])
                == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
                for pod in pods
            )
        )
        listeners_absent = pods_fenced and all(
            _accounting_handoff_writer_pod_has_no_listener(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=str(pod.get("name") or ""),
            )
            for pod in pods
        )
        target_database_quiet = bool(
            deployment_fenced
            and len(pods) == replicas
            and all(
                pod.get("owned") is True
                and not pod.get("deleting")
                and str(pod.get("phase") or "") == "Running"
                and list(pod.get("writer_command") or [])
                == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
                and list(pod.get("writer_args") or [])
                == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
                and _accounting_handoff_writer_pod_has_no_listener(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    pod_name=str(pod.get("name") or ""),
                )
                for pod in pods
            )
            and _accounting_handoff_database_connection_count(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
            )
            == 0
        )
        if old_pods and target_database_quiet:
            _accounting_handoff_retire_fenced_source_writer_lineage(
                state=state,
                source_binding=source_binding,
                target_binding=target_binding,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
            continue
        if deployment_fenced and pods_fenced and listeners_absent:
            target_identity = _accounting_handoff_mariadb_pod_identity(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
                expected_slurmcluster_binding=target_binding,
            )
            if any(
                target_identity.get(key) != expected_target.get(key)
                for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff target MariaDB identity changed after source retirement."
                )
            if (
                _accounting_handoff_database_connection_count(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    pod_name=target_pod,
                )
                == 0
            ):
                proof = {
                    "status": "verified",
                    "source_absent": True,
                    "deployment_uid": str(deployment.get("uid") or ""),
                    "deployment_generation": _non_negative_int(
                        deployment.get("generation"), fallback=0
                    ),
                    "pods": [str(pod.get("name") or "") for pod in pods],
                    "verified_at": _utc_now(),
                }
                state["target_command_fence_after_source_retirement"] = proof
                if checkpoint_writer is not None:
                    checkpoint_writer()
                return proof
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting handoff timed out proving source retirement and the exact "
                "target-only SlurmDBD command fence."
            )
        time.sleep(5)


def _accounting_handoff_retire_fenced_source_writer_lineage(
    *,
    state: dict[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    timeout_seconds: int = 300,
) -> None:
    """Delete only the exact orphaned, command-fenced source accounting lineage."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "accounting source writer lineage retirement requires durable checkpoint writes."
        )
    transition = _mapping(state.get("deployment_selector_handoff"))
    source_uid = str(_mapping(state.get("source_accounting_deployment")).get("uid") or "")
    expected_replica_set_uids = set(_accounting_handoff_pre_fence_replica_sets(state))
    source_selector = {
        "app.kubernetes.io/component": "accounting",
        "app.kubernetes.io/instance": str(source_binding.get("name") or "").strip(),
        "app.kubernetes.io/name": "slurmcluster",
    }
    target_selector = {
        **source_selector,
        "app.kubernetes.io/instance": str(target_binding.get("name") or "").strip(),
    }
    if (
        transition.get("schema") != "nebius-cxcli-accounting-deployment-selector-handoff-v1"
        or transition.get("status") != "target-created"
        or str(transition.get("source_uid") or "").strip() != source_uid
        or not str(transition.get("target_uid") or "").strip()
        or _mapping(transition.get("source_selector")) != source_selector
        or _mapping(transition.get("target_selector")) != target_selector
        or not expected_replica_set_uids
    ):
        raise SoperatorMigrationPhasePending(
            "accounting source writer lineage retirement lacks the exact target-created "
            "selector handoff and source ReplicaSet binding."
        )
    cleanup = state.setdefault("retired_source_writer_lineage", {})
    if not isinstance(cleanup, dict):
        raise RuntimeError("accounting retired_source_writer_lineage must be a mapping.")
    replica_sets = tuple(
        item
        for item in _immutable_child_list(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="replicasets.apps",
        )
        if str(_mapping(item.get("metadata")).get("uid") or "").strip() in expected_replica_set_uids
    )
    retired_pods = _accounting_handoff_selector_pods(
        command_runner=command_runner,
        kube_context=kube_context,
        selector=source_selector,
        deployment_uid=source_uid,
    )
    if not replica_sets and not retired_pods:
        cleanup.update(
            {
                "schema": "nebius-cxcli-accounting-retired-source-writer-lineage/v1",
                "status": "completed",
                "source_deployment_uid": source_uid,
                "replica_set_uids": sorted(expected_replica_set_uids),
                "completed_at": cleanup.get("completed_at") or _utc_now(),
            }
        )
        checkpoint_writer()
        return
    live_replica_set_uids = {
        str(_mapping(item.get("metadata")).get("uid") or "").strip() for item in replica_sets
    }
    if cleanup.get("status") != "intent" and live_replica_set_uids != expected_replica_set_uids:
        raise SoperatorMigrationPhasePending(
            "accounting source writer lineage changed before its exact retirement intent."
        )
    if any(
        pod.get("deleting")
        or str(pod.get("phase") or "") != "Running"
        or list(pod.get("writer_command") or []) != list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
        or list(pod.get("writer_args") or []) != list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
        or not _accounting_handoff_writer_pod_has_no_listener(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=str(pod.get("name") or ""),
        )
        for pod in retired_pods
    ):
        raise SoperatorMigrationPhasePending(
            "accounting source writer lineage retirement found an unfenced or listening Pod."
        )
    bindings = [
        {
            "name": str(_mapping(item.get("metadata")).get("name") or "").strip(),
            "uid": str(_mapping(item.get("metadata")).get("uid") or "").strip(),
            "resource_version": str(
                _mapping(item.get("metadata")).get("resourceVersion") or ""
            ).strip(),
        }
        for item in replica_sets
    ]
    if any(not all(binding.values()) for binding in bindings):
        raise SoperatorMigrationPhasePending(
            "accounting source writer lineage retirement found an incomplete ReplicaSet identity."
        )
    expected_intent = {
        "schema": "nebius-cxcli-accounting-retired-source-writer-lineage/v1",
        "status": "intent",
        "source_deployment_uid": source_uid,
        "replica_sets": bindings,
        "pods": [
            {
                "name": str(pod.get("name") or ""),
                "uid": str(pod.get("uid") or ""),
                "resource_version": str(pod.get("resource_version") or ""),
            }
            for pod in retired_pods
        ],
    }
    if cleanup:
        if any(cleanup.get(key) != value for key, value in expected_intent.items()):
            raise SoperatorMigrationPhasePending(
                "accounting source writer lineage retirement intent drifted."
            )
    else:
        cleanup.update({**expected_intent, "intent_recorded_at": _utc_now()})
        checkpoint_writer()
    for binding in bindings:
        if mutation_guard is not None:
            mutation_guard()
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=(
                f"/apis/apps/v1/namespaces/{_SOPERATOR_NAMESPACE}/replicasets/{binding['name']}"
            ),
            uid=binding["uid"],
            resource_version=binding["resource_version"],
            propagation_policy="Foreground",
            timeout_seconds=120,
            mutation_guard=None,
        )
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        remaining_replica_sets = tuple(
            item
            for item in _immutable_child_list(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="replicasets.apps",
            )
            if str(_mapping(item.get("metadata")).get("uid") or "").strip()
            in expected_replica_set_uids
        )
        remaining_pods = _accounting_handoff_source_writer_pods(
            command_runner=command_runner,
            kube_context=kube_context,
            replica_set_uids=tuple(expected_replica_set_uids),
            selector=source_selector,
        )
        if not remaining_replica_sets and not remaining_pods:
            cleanup.update(
                {
                    "status": "completed",
                    "replica_set_uids": sorted(expected_replica_set_uids),
                    "completed_at": _utc_now(),
                }
            )
            cleanup.pop("replica_sets", None)
            cleanup.pop("pods", None)
            checkpoint_writer()
            return
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting source writer lineage retirement timed out waiting for exact "
                "ReplicaSet and Pod deletion."
            )
        time.sleep(2)


def _accounting_handoff_manager_paused_selector_gap(
    *,
    phase: Mapping[str, Any],
    state: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    target_pod: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any] | None:
    """Prove the safe no-Deployment gap before the target manager is restored."""

    immutable = _mapping(phase.get("immutable_child_handoff"))
    immutable_status = str(immutable.get("status") or "").strip()
    transition = _mapping(state.get("deployment_selector_handoff"))
    if immutable_status not in {"manager-paused", "children-prepared"}:
        return None
    source_uid = str(_mapping(state.get("source_accounting_deployment")).get("uid") or "")
    source_selector = {
        "app.kubernetes.io/component": "accounting",
        "app.kubernetes.io/instance": str(source_binding.get("name") or "").strip(),
        "app.kubernetes.io/name": "slurmcluster",
    }
    target_selector = {
        **source_selector,
        "app.kubernetes.io/instance": str(target_binding.get("name") or "").strip(),
    }
    if (
        transition.get("schema") != "nebius-cxcli-accounting-deployment-selector-handoff-v1"
        or transition.get("status") != "source-deleted"
        or str(transition.get("source_uid") or "").strip() != source_uid
        or not str(transition.get("source_resource_version") or "").strip()
        or not str(transition.get("delete_intent_at") or "").strip()
        or not str(transition.get("source_deleted_at") or "").strip()
        or _mapping(transition.get("source_selector")) != source_selector
        or _mapping(transition.get("target_selector")) != target_selector
    ):
        return None
    if (
        _accounting_handoff_optional_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=source_binding,
            label="manager-paused selector-gap source",
        )
        is not None
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff manager-paused selector gap found the retired source again."
        )
    target_resource, _target_resource_version, target_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=target_binding,
            label="manager-paused selector-gap target",
        )
    )
    if not target_enabled or not _accounting_handoff_writer_command_is_fenced(target_resource):
        raise SoperatorMigrationPhasePending(
            "accounting handoff manager-paused selector gap lost the target command fence."
        )
    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
        allow_missing=True,
    )
    if deployment.get("exists"):
        return None
    manager_binding = _mapping(immutable.get("manager"))
    expected_manager_uid = str(manager_binding.get("uid") or "").strip()
    paused_generation = _positive_int(immutable.get("manager_paused_generation"), fallback=0)
    manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    _immutable_child_require_live_uid(
        manager,
        expected_uid=expected_manager_uid,
        label="manager-paused accounting selector gap",
    )
    _manager_fingerprint, manager_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=manager,
    )
    manager_status = _mapping(manager.get("status"))
    if (
        not expected_manager_uid
        or not str(manager_binding.get("spec_fingerprint") or "").strip()
        or paused_generation <= 0
        or not str(immutable.get("manager_paused_at") or "").strip()
        or _resource_replicas(manager, default=-1) != 0
        or manager_generation != paused_generation
        or _non_negative_int(manager_status.get("observedGeneration"), fallback=0)
        < manager_generation
        or any(
            _non_negative_int(manager_status.get(key), fallback=0) != 0
            for key in ("replicas", "readyReplicas", "availableReplicas", "updatedReplicas")
        )
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff selector gap lacks the exact paused-manager proof."
        )
    retired_pods = _accounting_handoff_selector_pods(
        command_runner=command_runner,
        kube_context=kube_context,
        selector=source_selector,
        deployment_uid=source_uid,
    )
    retired_pods_fenced = all(
        not pod.get("deleting")
        and str(pod.get("phase") or "") == "Running"
        and list(pod.get("writer_command") or []) == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
        and list(pod.get("writer_args") or []) == list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
        and _accounting_handoff_writer_pod_has_no_listener(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=str(pod.get("name") or ""),
        )
        for pod in retired_pods
    )
    if (
        not retired_pods_fenced
        or _accounting_handoff_database_connection_count(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
        )
        != 0
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff selector gap lacks fenced retired Pods or a quiet target DB."
        )
    return {
        "schema": "nebius-cxcli-accounting-manager-paused-selector-gap/v1",
        "status": "verified",
        "source_absent": True,
        "deployment_absent": True,
        "source_uid": source_uid,
        "manager_uid": expected_manager_uid,
        "manager_generation": manager_generation,
        "retired_fenced_pods": [str(pod.get("name") or "") for pod in retired_pods],
        "verified_at": _utc_now(),
    }


def _accounting_handoff_pause_target_writer(
    *,
    state: dict[str, Any],
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    binding = _accounting_handoff_target_binding(phase=phase, state=state)
    command_gate = _mapping(state.get("target_writer_command_fence"))
    if command_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer requires the canonical SlurmDBD command fence."
        )
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    source_resource_name = _accounting_handoff_cluster_name(
        state.get("source_resource_name"),
        label="source SlurmCluster resource",
    )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    target_pod = f"{target_resource_name}-acct-db-0"
    if str(phase.get("source_accounting_owner_retired_at") or "").strip():
        _accounting_handoff_wait_target_command_fence_after_source_retirement(
            phase=phase,
            state=state,
            source_binding=source_binding,
            target_binding=binding,
            target_pod=target_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    else:
        _accounting_handoff_wait_writer_command_fences(
            state=state,
            source_binding=source_binding,
            target_binding=binding,
            source_pod=f"{source_resource_name}-acct-db-0",
            target_pod=target_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    gate = state.setdefault("target_writer_gate", {})
    if not isinstance(gate, dict):
        raise RuntimeError("accounting handoff target_writer_gate must be a mapping.")
    existing_binding = {
        key: str(_mapping(gate.get("binding")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    if gate and (
        gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or gate.get("status") != "disabled"
        or existing_binding != binding
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer gate is not the exact durable command fence."
        )
    gate.update(
        {
            "schema": _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA,
            "binding": binding,
            "status": "disabled",
            "mode": "slurmdbd-command-fence",
            "deployment_uid": str(deployment.get("uid") or ""),
            "deployment_replicas": _non_negative_int(deployment.get("replicas"), fallback=0),
            "deployment_selector": dict(_mapping(deployment.get("selector"))),
        }
    )
    gate.setdefault("disabled_at", _utc_now())
    if checkpoint_writer is not None:
        checkpoint_writer()
    return gate


def _accounting_handoff_assert_target_writer_disabled(
    *,
    state: dict[str, Any],
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    binding = _accounting_handoff_target_binding(phase=phase, state=state)
    gate = _mapping(state.get("target_writer_gate"))
    if (
        gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or gate.get("status") != "disabled"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer lacks the canonical durable command fence."
        )
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    source_resource_name = _accounting_handoff_cluster_name(
        state.get("source_resource_name"),
        label="source SlurmCluster resource",
    )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    target_pod = f"{target_resource_name}-acct-db-0"
    if phase.get("source_accounting_owner_retired_at"):
        _accounting_handoff_wait_target_command_fence_after_source_retirement(
            phase=phase,
            state=state,
            source_binding=source_binding,
            target_binding=binding,
            target_pod=target_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=None,
        )
        return
    _accounting_handoff_wait_writer_command_fences(
        state=state,
        source_binding=source_binding,
        target_binding=binding,
        source_pod=f"{source_resource_name}-acct-db-0",
        target_pod=target_pod,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=None,
    )


def _accounting_handoff_target_spec_from_proven_helm_release(
    *,
    phase: Mapping[str, Any],
    binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    label: str,
) -> dict[str, Any]:
    normalized_binding = {
        key: str(binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    proof = _mapping(phase.get("target_handoff_values_proof"))
    proof_binding = {
        key: str(_mapping(proof.get("target")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    release_revision = _positive_int(proof.get("release_revision"), fallback=0)
    expected_chart = str(proof.get("chart") or "").strip()
    expected_app_version = str(proof.get("app_version") or "").strip()
    manifest_fingerprint = str(proof.get("installed_manifest_fingerprint") or "").strip()
    spec_fingerprint = str(proof.get("installed_spec_fingerprint") or "").strip()
    if (
        proof.get("schema") != _TARGET_HELM_APPLY_PROOF_SCHEMA
        or proof.get("status") != "verified"
        or proof_binding != normalized_binding
        or _non_negative_int(phase.get("target_handoff_values_revision"), fallback=0)
        != _ROLLING_COMPUTE_VALUES_REVISION
        or release_revision <= 0
        or not expected_chart
        or not expected_app_version
        or re.fullmatch(r"[0-9a-f]{64}", manifest_fingerprint) is None
        or re.fullmatch(r"[0-9a-f]{64}", spec_fingerprint) is None
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} lacks the exact proven Helm release identity."
        )
    releases = tuple(
        release
        for release in list_helm_releases(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            filter_regex=f"^{re.escape(_SOPERATOR_TARGET_RELEASE_NAME)}$",
        )
        if release.name == _SOPERATOR_TARGET_RELEASE_NAME
    )
    if (
        len(releases) != 1
        or releases[0].namespace != _SOPERATOR_NAMESPACE
        or releases[0].status.lower() != "deployed"
        or _positive_int(releases[0].revision, fallback=0) < release_revision
        or releases[0].chart != expected_chart
        or releases[0].app_version != expected_app_version
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} found a different or regressed live Helm release identity."
        )
    manifest_result = command_runner(
        [
            "helm",
            "--kube-context",
            kube_context,
            "get",
            "manifest",
            _SOPERATOR_TARGET_RELEASE_NAME,
            "-n",
            _SOPERATOR_NAMESPACE,
            "--revision",
            str(release_revision),
        ],
        timeout_seconds=120,
        check=False,
    )
    if manifest_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} could not read the proven historical Helm "
            "release manifest."
        )
    stored_spec = _target_slurmcluster_spec_from_helm_documents(
        manifest_result.stdout,
        target_ref=normalized_binding["name"],
        label=f"accounting {label} release manifest",
    )
    if (
        _target_slurmcluster_manifest_fingerprint(
            manifest_result.stdout,
            target_ref=normalized_binding["name"],
            label=f"accounting {label} release manifest",
        )
        != manifest_fingerprint
        or _fingerprint(stored_spec) != spec_fingerprint
    ):
        raise SoperatorMigrationPhasePending(
            f"accounting handoff {label} found Helm manifest drift from the durable apply proof."
        )
    return stored_spec


def _accounting_handoff_target_writer_config_from_proven_helm_release(
    *,
    phase: Mapping[str, Any],
    command_gate: Mapping[str, Any],
    binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    identity = _accounting_handoff_validated_writer_config_identity(
        command_gate.get("original_writer_identity"),
        label="target restore",
    )
    stored_spec = _accounting_handoff_target_spec_from_proven_helm_release(
        phase=phase,
        binding=binding,
        command_runner=command_runner,
        kube_context=kube_context,
        label="target writer restore",
    )
    config = _accounting_handoff_writer_command_config({"spec": stored_spec})
    if not _accounting_handoff_writer_config_matches_identity(config, identity):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer restore found command/args that do not match "
            "the durable pre-fence identity; the fenced writer was not changed."
        )
    return config


def _accounting_handoff_assert_target_writer_ready(
    *,
    state: Mapping[str, Any],
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    binding = _accounting_handoff_target_binding(phase=phase, state=state)
    gate = _mapping(state.get("target_writer_gate"))
    if (
        gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or gate.get("status") != "enabled"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified state lacks the durable enabled target writer gate."
        )
    resource, _resource_version, enabled = _accounting_handoff_exact_slurmcluster(
        command_runner=command_runner,
        kube_context=kube_context,
        binding=binding,
        label="target",
    )
    if not enabled:
        raise SoperatorMigrationPhasePending(
            "accounting handoff exact target writer is disabled after verification."
        )
    command_gate = _mapping(state.get("target_writer_command_fence"))
    if (
        command_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or command_gate.get("status") != "restored"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified target SlurmDBD command restore checkpoint is incomplete."
        )
    original_writer_identity = _accounting_handoff_validated_writer_config_identity(
        command_gate.get("original_writer_identity"),
        label="verified target",
    )
    if not _accounting_handoff_writer_config_matches_identity(
        _accounting_handoff_writer_command_config(resource),
        original_writer_identity,
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified target SlurmDBD command/args no longer match "
            "their checkpointed pre-fence identity."
        )
    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if str(deployment.get("owner_uid") or "") != binding["uid"] or str(
        deployment.get("uid") or ""
    ) != str(gate.get("enabled_deployment_uid") or ""):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified target accounting Deployment identity changed."
        )
    desired = _non_negative_int(deployment.get("replicas"), fallback=0)
    generation = _non_negative_int(deployment.get("generation"), fallback=0)
    selector = _accounting_handoff_deployment_selector(deployment)
    pods = _accounting_handoff_selector_pods(
        command_runner=command_runner,
        kube_context=kube_context,
        selector=selector,
        deployment_uid=str(deployment.get("uid") or ""),
    )
    deployment_writer_containers = tuple(
        container
        for container in _sequence_of_mappings(deployment.get("template_containers"))
        if str(container.get("name") or "").strip() == "accounting"
    )
    deployment_command_restored = len(deployment_writer_containers) == 1 and (
        _accounting_handoff_writer_config_matches_identity(
            _accounting_handoff_workload_writer_config(
                deployment_writer_containers[0],
                label="accounting Deployment writer container",
            ),
            original_writer_identity,
        )
    )
    ready = bool(
        desired > 0
        and generation > 0
        and _non_negative_int(deployment.get("observed_generation"), fallback=0) >= generation
        and all(
            _non_negative_int(deployment.get(key), fallback=0) == desired
            for key in (
                "status_replicas",
                "updated_replicas",
                "available_replicas",
                "ready_replicas",
            )
        )
        and _non_negative_int(deployment.get("unavailable_replicas"), fallback=0) == 0
        and len(pods) == desired
        and deployment_command_restored
        and all(
            pod["owned"]
            and not pod["deleting"]
            and pod["phase"] == "Running"
            and pod["ready"]
            and _non_negative_int(pod.get("writer_container_count"), fallback=0) == 1
            and _accounting_handoff_writer_config_matches_identity(
                {
                    "command_present": pod.get("writer_command_present"),
                    "command": list(pod.get("writer_command") or []),
                    "args_present": pod.get("writer_args_present"),
                    "args": list(pod.get("writer_args") or []),
                },
                original_writer_identity,
            )
            for pod in pods
        )
    )
    if not ready:
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified target writer readiness evidence drifted."
        )
    return deployment


def _accounting_handoff_enable_target_writer(
    *,
    state: dict[str, Any],
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    binding = _accounting_handoff_target_binding(phase=phase, state=state)
    gate = state.get("target_writer_gate")
    if not isinstance(gate, dict) or gate.get("status") not in {
        "disabled",
        "enable-intent",
        "enabled",
    }:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot enable the target writer without the durable "
            "disabled-writer gate."
        )
    existing_binding = {
        key: str(_mapping(gate.get("binding")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    if existing_binding != binding:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer enable binding changed."
        )
    command_gate = state.get("target_writer_command_fence")
    command_mode = bool(
        gate.get("schema") == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        and isinstance(command_gate, dict)
        and command_gate.get("schema") == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
    )
    if not command_mode:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer restore requires the canonical command fence."
        )
    if str(command_gate.get("status") or "") not in {
        "verified",
        "restore-intent",
        "restored",
    }:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target command-fence restore checkpoint is incomplete."
        )
    if not phase.get("source_accounting_owner_retired_at"):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer restore requires durable source-owner retirement."
        )
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    if (
        _accounting_handoff_optional_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=source_binding,
            label="retired source",
        )
        is not None
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source SlurmCluster still exists before target writer restore."
        )
    _accounting_handoff_assert_source_pvc_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        expected=_mapping(state.get("source")),
    )
    if gate.get("status") == "disabled":
        gate.update({"status": "enable-intent", "enable_intent_recorded_at": _utc_now()})
        if command_mode:
            command_gate.update(
                {"status": "restore-intent", "restore_intent_recorded_at": _utc_now()}
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
    original_writer_config = _accounting_handoff_target_writer_config_from_proven_helm_release(
        phase=phase,
        command_gate=command_gate,
        binding=binding,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    target_resource, target_resource_version, target_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=binding,
            label="target restore boundary",
        )
    )
    live_writer_config = _accounting_handoff_writer_command_config(target_resource)
    already_restored = target_enabled and live_writer_config == original_writer_config
    still_fenced = target_enabled and _accounting_handoff_writer_command_is_fenced(target_resource)
    if not already_restored and not still_fenced:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target SlurmDBD enabled/command/args drifted before "
            "restore; cxcli did not overwrite the external change."
        )
    if already_restored:
        enabled_resource_version = target_resource_version
    else:
        enabled_resource_version, _updated_resource = (
            _accounting_handoff_patch_exact_writer_command(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=binding,
                command_present=bool(original_writer_config.get("command_present")),
                command=tuple(str(item) for item in original_writer_config.get("command", [])),
                args_present=bool(original_writer_config.get("args_present")),
                args=tuple(str(item) for item in original_writer_config.get("args", [])),
                enabled=True,
                label="target restore",
                expected_resource_version=target_resource_version,
            )
        )
    deadline = time.monotonic() + 900
    while True:
        deployment = _accounting_handoff_deployment_state(
            command_runner=command_runner,
            kube_context=kube_context,
            allow_missing=True,
        )
        if deployment.get("exists") and str(deployment.get("owner_uid") or "") == binding["uid"]:
            desired = _non_negative_int(deployment.get("replicas"), fallback=0)
            generation = _non_negative_int(deployment.get("generation"), fallback=0)
            selector = _accounting_handoff_deployment_selector(deployment)
            pods = _accounting_handoff_selector_pods(
                command_runner=command_runner,
                kube_context=kube_context,
                selector=selector,
                deployment_uid=str(deployment.get("uid") or ""),
            )
            restored_command = True
            if command_mode:
                restored_command = any(
                    str(container.get("name") or "").strip() == "accounting"
                    and list(container.get("command") or [])
                    == list(original_writer_config.get("command") or [])
                    and list(container.get("args") or [])
                    == list(original_writer_config.get("args") or [])
                    for container in _sequence_of_mappings(deployment.get("template_containers"))
                )
            ready = bool(
                desired > 0
                and generation > 0
                and _non_negative_int(deployment.get("observed_generation"), fallback=0)
                >= generation
                and all(
                    _non_negative_int(deployment.get(key), fallback=0) == desired
                    for key in (
                        "status_replicas",
                        "updated_replicas",
                        "available_replicas",
                        "ready_replicas",
                    )
                )
                and _non_negative_int(deployment.get("unavailable_replicas"), fallback=0) == 0
                and len(pods) == desired
                and restored_command
                and all(
                    pod["owned"]
                    and not pod["deleting"]
                    and pod["phase"] == "Running"
                    and pod["ready"]
                    and (
                        not command_mode
                        or (
                            list(pod.get("writer_command") or [])
                            == list(original_writer_config.get("command") or [])
                            and list(pod.get("writer_args") or [])
                            == list(original_writer_config.get("args") or [])
                        )
                    )
                    for pod in pods
                )
            )
            if ready:
                gate.update(
                    {
                        "status": "enabled",
                        "enabled_resource_version": enabled_resource_version,
                        "enabled_deployment_uid": str(deployment.get("uid") or ""),
                        "enabled_replicas": desired,
                        "enabled_at": _utc_now(),
                    }
                )
                if command_mode:
                    command_gate.update(
                        {
                            "status": "restored",
                            "restored_resource_version": enabled_resource_version,
                            "restored_at": _utc_now(),
                        }
                    )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                return gate
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "accounting handoff timed out waiting for the exact target-owned "
                "accounting Deployment and Pods to become ready."
            )
        time.sleep(5)


def _accounting_handoff_fenced_writer_pod_identity(
    *,
    state: dict[str, Any],
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    gate = _accounting_handoff_pause_target_writer(
        state=state,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    deployment = _accounting_handoff_deployment_state(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if (
        str(deployment.get("uid") or "") != str(gate.get("deployment_uid") or "")
        or str(deployment.get("owner_uid") or "") != target_binding["uid"]
        or _non_negative_int(deployment.get("replicas"), fallback=0) != 1
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap requires one exact target-owned, "
            "command-fenced accounting Deployment replica."
        )
    stored_spec = _accounting_handoff_target_spec_from_proven_helm_release(
        phase=phase,
        binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
        label="target schema bootstrap",
    )
    expected_image = str(
        _accounting_handoff_slurmdbd_spec({"spec": stored_spec}).get("image") or ""
    ).strip()
    target_resource, _target_resource_version, target_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=target_binding,
            label="target schema bootstrap",
        )
    )
    live_target_image = str(
        _accounting_handoff_slurmdbd_spec(target_resource).get("image") or ""
    ).strip()
    deployment_writer_containers = tuple(
        container
        for container in _sequence_of_mappings(deployment.get("template_containers"))
        if str(container.get("name") or "").strip() == "accounting"
    )
    deployment_image = str(
        deployment_writer_containers[0].get("image")
        if len(deployment_writer_containers) == 1
        else ""
    ).strip()
    if (
        not expected_image
        or target_enabled is not True
        or live_target_image != expected_image
        or deployment_image != expected_image
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap could not bind the target SlurmDBD image "
            "across the proven Helm manifest, exact target CR, and target-owned Deployment."
        )
    pods = _accounting_handoff_selector_pods(
        command_runner=command_runner,
        kube_context=kube_context,
        selector=_accounting_handoff_deployment_selector(deployment),
        deployment_uid=str(deployment.get("uid") or ""),
    )
    if len(pods) != 1:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap could not bind one exact accounting Pod."
        )
    pod = pods[0]
    labels = _mapping(pod.get("labels"))
    selector_keys = (
        "app.kubernetes.io/component",
        "app.kubernetes.io/instance",
        "app.kubernetes.io/name",
    )
    network_selector = {key: str(labels.get(key) or "").strip() for key in selector_keys}
    helm_proof = _mapping(phase.get("target_handoff_values_proof"))
    if (
        pod.get("owned") is not True
        or pod.get("deleting")
        or str(pod.get("phase") or "") != "Running"
        or list(pod.get("writer_command") or []) != list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
        or list(pod.get("writer_args") or []) != list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
        or not str(pod.get("name") or "").strip()
        or not str(pod.get("uid") or "").strip()
        or str(pod.get("writer_image") or "").strip() != expected_image
        or not str(pod.get("writer_image_id") or "").strip()
        or pod.get("host_network") is True
        or not str(pod.get("pod_ip") or "").strip()
        or not all(network_selector.values())
        or network_selector["app.kubernetes.io/component"] != "accounting"
        or helm_proof.get("schema") != _TARGET_HELM_APPLY_PROOF_SCHEMA
        or helm_proof.get("status") != "verified"
        or _mapping(helm_proof.get("target")) != target_binding
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap accounting Pod identity is incomplete "
            "or no longer command-fenced."
        )
    try:
        pod_ip = str(ipaddress.ip_address(str(pod["pod_ip"])))
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap accounting Pod has an invalid Pod IP."
        ) from exc
    return {
        "name": str(pod["name"]),
        "uid": str(pod["uid"]),
        "image": expected_image,
        "image_id": str(pod.get("writer_image_id") or ""),
        "deployment_uid": str(deployment.get("uid") or ""),
        "deployment_owner_uid": str(deployment.get("owner_uid") or ""),
        "pod_ip": pod_ip,
        "host_network": False,
        "labels": {str(key): str(value) for key, value in labels.items()},
        "network_selector": network_selector,
        "target_helm_proof_sha256": _fingerprint(to_plain_data(helm_proof)),
    }


def _accounting_handoff_schema_bootstrap_expected_slurm_version(image: str) -> str:
    match = re.search(r"(?:^|[^A-Za-z0-9])slurm(?P<version>\d+\.\d+\.\d+)(?=$|[^0-9])", image)
    if match is None:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot derive an exact Slurm version from the "
            "Helm-proven target SlurmDBD image."
        )
    return match.group("version")


def _accounting_handoff_schema_bootstrap_binary_binding(
    writer_pod: Mapping[str, Any],
) -> dict[str, Any]:
    image = str(writer_pod.get("image") or "").strip()
    image_id = str(writer_pod.get("image_id") or "").strip()
    binding = {
        "pod_uid": str(writer_pod.get("uid") or "").strip(),
        "deployment_uid": str(writer_pod.get("deployment_uid") or "").strip(),
        "deployment_owner_uid": str(writer_pod.get("deployment_owner_uid") or "").strip(),
        "image_sha256": hashlib.sha256(image.encode("utf-8")).hexdigest(),
        "image_id": image_id,
        "expected_slurm_version": (
            _accounting_handoff_schema_bootstrap_expected_slurm_version(image)
        ),
    }
    if not all(str(binding[key] or "").strip() for key in binding) or not re.fullmatch(
        r"[0-9a-f]{64}", str(binding["image_sha256"])
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target SlurmDBD binary binding is incomplete."
        )
    return binding


def _accounting_handoff_ensure_schema_bootstrap_binary_proof(
    *,
    state: dict[str, Any],
    writer_pod: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    database_tables: Sequence[str],
) -> dict[str, Any]:
    binding = _accounting_handoff_schema_bootstrap_binary_binding(writer_pod)
    bootstrap = state.setdefault("target_schema_bootstrap", {})
    if not isinstance(bootstrap, dict):
        raise RuntimeError("accounting handoff target_schema_bootstrap must be a mapping.")
    proof = bootstrap.setdefault("binary_proof", {})
    if not isinstance(proof, dict):
        raise RuntimeError("accounting handoff binary_proof must be a mapping.")
    if proof:
        proof_schema_state = str(proof.get("database_schema_state") or "").strip()
        proof_expected_exit_code = 1 if proof_schema_state == "exact-empty" else 0
        if (
            proof.get("schema") != _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_BINARY_PROOF_SCHEMA
            or proof.get("binding") != binding
            or proof.get("observed_slurm_version") != binding["expected_slurm_version"]
            or proof.get("database_conversion_pending") is not False
            or proof_schema_state not in {"exact-empty", "existing"}
            or proof.get("schema_initialization_required")
            is not (proof_schema_state == "exact-empty")
            or proof.get("update_check_exit_code") != proof_expected_exit_code
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff target SlurmDBD binary proof drifted after import intent."
            )
        return proof

    schema_state = "exact-empty" if not database_tables else "existing"
    expected_update_check_exit_code = 1 if schema_state == "exact-empty" else 0

    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            str(writer_pod["name"]),
            "-c",
            "accounting",
            "--",
            "bash",
            "-lc",
            (
                "set -euo pipefail; "
                "SLURM_CONF=/mnt/slurm-configs/slurmdbd.conf /usr/sbin/slurmdbd -V; "
                "set +e; "
                "SLURM_CONF=/mnt/slurm-configs/slurmdbd.conf /usr/sbin/slurmdbd -u; "
                "update_rc=$?; set -e; "
                'case "$update_rc" in 0|1) ;; *) exit "$update_rc";; esac; '
                "printf 'nebius-cxcli-slurmdbd-update-check=%s\\n' \"$update_rc\""
            ),
        ],
        timeout_seconds=300,
        check=False,
    )
    combined = f"{result.stdout}\n{result.stderr}"
    versions = set(re.findall(r"\bslurm\s+(\d+\.\d+\.\d+)\b", combined, flags=re.IGNORECASE))
    update_check_codes = tuple(
        int(value)
        for value in re.findall(
            r"^nebius-cxcli-slurmdbd-update-check=([01])$",
            combined,
            flags=re.MULTILINE,
        )
    )
    if (
        result.returncode != 0
        or versions != {binding["expected_slurm_version"]}
        or update_check_codes != (expected_update_check_exit_code,)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target SlurmDBD binary/version or read-only database "
            "conversion proof failed; stdout/stderr was redacted."
        )
    observed = {
        "schema": _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_BINARY_PROOF_SCHEMA,
        "binding": binding,
        "observed_slurm_version": binding["expected_slurm_version"],
        "database_conversion_pending": False,
        "database_schema_state": schema_state,
        "schema_initialization_required": schema_state == "exact-empty",
        "update_check_exit_code": expected_update_check_exit_code,
    }
    if proof and any(proof.get(key) != value for key, value in observed.items()):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target SlurmDBD binary proof changed before import."
        )
    proof.update(observed)
    proof["verified_at"] = proof.get("verified_at") or _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    return proof


def _accounting_handoff_optional_schema_bootstrap_network_policy(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    name: str,
) -> dict[str, Any] | None:
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "networkpolicy.networking.k8s.io",
            name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        stderr = re.sub(r"\s+", " ", str(result.stderr or "")).strip().lower()
        expected = (
            f'error from server (notfound): networkpolicies.networking.k8s.io "{name}" not found'
        ).lower()
        if not str(result.stdout or "").strip() and stderr == expected:
            return None
        raise RuntimeError(
            "accounting handoff could not inspect its schema-bootstrap NetworkPolicy."
        )
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            "accounting handoff schema-bootstrap NetworkPolicy lookup returned invalid JSON."
        ) from exc
    if not isinstance(payload, Mapping):
        raise RuntimeError(
            "accounting handoff schema-bootstrap NetworkPolicy lookup returned a non-object."
        )
    return dict(payload)


def _accounting_handoff_schema_bootstrap_network_policy_manifest(
    *,
    name: str,
    selector: Mapping[str, str],
) -> dict[str, Any]:
    return {
        "apiVersion": "networking.k8s.io/v1",
        "kind": "NetworkPolicy",
        "metadata": {
            "name": name,
            "namespace": _SOPERATOR_NAMESPACE,
            "labels": {
                "app.kubernetes.io/managed-by": "nebius-cxcli",
                "nebius.ai/purpose": "accounting-schema-bootstrap",
            },
        },
        "spec": {
            "podSelector": {"matchLabels": dict(selector)},
            "policyTypes": ["Ingress"],
            "ingress": [],
        },
    }


def _accounting_handoff_label_selector_matches(
    selector: Mapping[str, Any],
    labels: Mapping[str, str],
) -> bool:
    match_labels = selector.get("matchLabels", {})
    match_expressions = selector.get("matchExpressions", [])
    if (
        not isinstance(match_labels, Mapping)
        or not isinstance(match_expressions, Sequence)
        or isinstance(match_expressions, (str, bytes, bytearray))
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff found a malformed NetworkPolicy pod selector."
        )
    for key, value in match_labels.items():
        if not isinstance(key, str) or not isinstance(value, str) or labels.get(key) != value:
            return False
    for raw_expression in match_expressions:
        if not isinstance(raw_expression, Mapping):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found a malformed NetworkPolicy match expression."
            )
        key = str(raw_expression.get("key") or "").strip()
        operator = str(raw_expression.get("operator") or "").strip()
        raw_values = raw_expression.get("values", [])
        if (
            not key
            or not isinstance(raw_values, Sequence)
            or isinstance(raw_values, (str, bytes, bytearray))
            or any(not isinstance(value, str) for value in raw_values)
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found an incomplete NetworkPolicy match expression."
            )
        values = set(raw_values)
        if operator == "In":
            matches = bool(values) and labels.get(key) in values
        elif operator == "NotIn":
            matches = bool(values) and labels.get(key) not in values
        elif operator == "Exists":
            matches = not values and key in labels
        elif operator == "DoesNotExist":
            matches = not values and key not in labels
        else:
            raise SoperatorMigrationPhasePending(
                "accounting handoff found an unsupported NetworkPolicy selector operator."
            )
        if not matches:
            return False
    return True


def _accounting_handoff_network_policy_allows_bootstrap_port(
    policy: Mapping[str, Any],
) -> bool:
    spec = _mapping(policy.get("spec"))
    raw_policy_types = spec.get("policyTypes")
    if raw_policy_types is None:
        policy_types = {"Ingress"}
        if "egress" in spec:
            policy_types.add("Egress")
    elif isinstance(raw_policy_types, Sequence) and not isinstance(
        raw_policy_types, (str, bytes, bytearray)
    ):
        policy_types = {str(item) for item in raw_policy_types}
        if not policy_types or not policy_types.issubset({"Ingress", "Egress"}):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found invalid NetworkPolicy policyTypes."
            )
    else:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found malformed NetworkPolicy policyTypes."
        )
    if "Ingress" not in policy_types:
        return False
    raw_ingress = spec.get("ingress", [])
    if not isinstance(raw_ingress, Sequence) or isinstance(raw_ingress, (str, bytes, bytearray)):
        raise SoperatorMigrationPhasePending(
            "accounting handoff found malformed NetworkPolicy ingress rules."
        )
    for raw_rule in raw_ingress:
        if not isinstance(raw_rule, Mapping):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found a malformed NetworkPolicy ingress rule."
            )
        raw_ports = raw_rule.get("ports")
        if raw_ports is None or raw_ports == []:
            return True
        if not isinstance(raw_ports, Sequence) or isinstance(raw_ports, (str, bytes, bytearray)):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found malformed NetworkPolicy ingress ports."
            )
        for raw_port in raw_ports:
            if not isinstance(raw_port, Mapping):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found a malformed NetworkPolicy ingress port."
                )
            protocol = str(raw_port.get("protocol") or "TCP").upper()
            if protocol not in {"TCP", "UDP", "SCTP"}:
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found an unsupported NetworkPolicy protocol."
                )
            if protocol != "TCP":
                continue
            port = raw_port.get("port")
            if port is None or isinstance(port, str):
                return True
            if not isinstance(port, int) or isinstance(port, bool) or not 1 <= port <= 65535:
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found an invalid NetworkPolicy TCP port."
                )
            end_port = raw_port.get("endPort", port)
            if (
                not isinstance(end_port, int)
                or isinstance(end_port, bool)
                or not port <= end_port <= 65535
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found an invalid NetworkPolicy TCP endPort."
                )
            if port <= _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT <= end_port:
                return True
    return False


def _accounting_handoff_schema_bootstrap_network_policy_union(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    writer_pod: Mapping[str, Any],
    expected_policy: Mapping[str, Any],
) -> dict[str, Any]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "networkpolicies.networking.k8s.io",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    labels = {str(key): str(value) for key, value in _mapping(writer_pod.get("labels")).items()}
    expected_name = str(expected_policy.get("name") or "").strip()
    expected_uid = str(expected_policy.get("uid") or "").strip()
    expected_resource_version = str(expected_policy.get("resource_version") or "").strip()
    applicable: list[dict[str, Any]] = []
    raw_items = payload.get("items")
    if not isinstance(raw_items, Sequence) or isinstance(raw_items, (str, bytes, bytearray)):
        raise SoperatorMigrationPhasePending(
            "accounting handoff NetworkPolicy inventory returned malformed items."
        )
    for raw_policy in raw_items:
        if not isinstance(raw_policy, Mapping):
            raise SoperatorMigrationPhasePending(
                "accounting handoff NetworkPolicy inventory contained a non-object item."
            )
        identity = _validated_namespaced_resource_identity(
            raw_policy,
            expected_api_version="networking.k8s.io/v1",
            expected_kind="NetworkPolicy",
            label="Accounting schema-bootstrap NetworkPolicy union",
        )
        if identity["namespace"] != _SOPERATOR_NAMESPACE:
            raise SoperatorMigrationPhasePending(
                "accounting handoff NetworkPolicy inventory crossed its exact namespace."
            )
        spec_raw = raw_policy.get("spec")
        if not isinstance(spec_raw, Mapping) or not isinstance(
            spec_raw.get("podSelector"), Mapping
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found a malformed NetworkPolicy specification."
            )
        spec = dict(spec_raw)
        selector = dict(spec_raw["podSelector"])
        if not _accounting_handoff_label_selector_matches(selector, labels):
            continue
        allows_port = _accounting_handoff_network_policy_allows_bootstrap_port(raw_policy)
        if identity["name"] != expected_name and allows_port:
            raise SoperatorMigrationPhasePending(
                "accounting handoff found another applicable NetworkPolicy whose additive "
                "ingress union can allow the schema-bootstrap TCP port."
            )
        if identity["name"] == expected_name and (
            identity["uid"] != expected_uid
            or identity["resourceVersion"] != expected_resource_version
            or spec.get("policyTypes") != ["Ingress"]
            or spec.get("ingress", []) != []
            or _mapping(spec.get("podSelector")).get("matchLabels")
            != _mapping(writer_pod.get("network_selector"))
            or _mapping(spec.get("podSelector")).get("matchExpressions", []) != []
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap NetworkPolicy changed before "
                "enforcement proof."
            )
        applicable.append(
            {
                "name": identity["name"],
                "uid": identity["uid"],
                "resource_version": identity["resourceVersion"],
                "spec_sha256": _fingerprint(spec),
                "allows_bootstrap_port": allows_port,
            }
        )
    if [item["name"] for item in applicable].count(expected_name) != 1:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap NetworkPolicy is absent from its "
            "applicable policy union."
        )
    structural = {
        "writer_pod_uid": str(writer_pod.get("uid") or ""),
        "writer_pod_ip": str(writer_pod.get("pod_ip") or ""),
        "applicable_policies": sorted(applicable, key=lambda item: item["name"]),
    }
    return {**structural, "proof_sha256": _fingerprint(structural)}


def _accounting_handoff_schema_bootstrap_probe_pod_identity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    expected_uid: str,
) -> dict[str, Any]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod",
            pod_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = _mapping(payload.get("metadata"))
    spec = _mapping(payload.get("spec"))
    status = _mapping(payload.get("status"))
    pod_ip_raw = str(status.get("podIP") or "").strip()
    try:
        pod_ip = str(ipaddress.ip_address(pod_ip_raw))
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap probe Pod has an invalid Pod IP."
        ) from exc
    if (
        str(metadata.get("name") or "").strip() != pod_name
        or str(metadata.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
        or str(metadata.get("uid") or "").strip() != expected_uid
        or spec.get("hostNetwork") is True
        or str(status.get("phase") or "").strip() != "Running"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap probe Pod identity is incomplete or drifted."
        )
    return {"name": pod_name, "uid": expected_uid, "pod_ip": pod_ip, "host_network": False}


def _accounting_handoff_schema_bootstrap_probe_marker(bootstrap_id: str) -> str:
    if re.fullmatch(r"[0-9a-f]{32}", bootstrap_id) is None:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap probe lacks an exact operation ID."
        )
    return f"{_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PROBE_MARKER_PREFIX}-{bootstrap_id}"


def _accounting_handoff_stop_schema_bootstrap_probe_listener(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    writer_pod_name: str,
    marker: str,
) -> None:
    pid_file = f"/tmp/{marker}.pid"
    script = f"""set -euo pipefail
pid_file={shlex.quote(pid_file)}
marker={shlex.quote(marker)}
if [ -f "$pid_file" ]; then
  pid="$(cat "$pid_file")"
  case "$pid" in (*[!0-9]*|'') exit 74;; esac
  process_is_live() {{
    state="$(awk '{{print $3}}' "/proc/$pid/stat" 2>/dev/null || true)"
    [ -n "$state" ] && [ "$state" != Z ] && [ "$state" != X ]
  }}
  if process_is_live; then
    tr '\\000' '\\n' < "/proc/$pid/cmdline" | grep -Fx -- "$marker" >/dev/null
    kill -TERM "$pid"
    for _ in $(seq 1 100); do
      process_is_live || break
      sleep 0.1
    done
    if process_is_live; then
      kill -KILL "$pid"
      for _ in $(seq 1 20); do
        process_is_live || break
        sleep 0.1
      done
      process_is_live && exit 78
    fi
  fi
  rm -f -- "$pid_file" "/tmp/$marker.log"
fi
if ss -lntH | awk '{{print $4}}' | grep -Eq '(^|:){_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT}$'; then
  exit 75
fi
"""
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            writer_pod_name,
            "-c",
            "accounting",
            "--",
            "bash",
            "-lc",
            script,
        ],
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not safely reap its exact inert network probe listener."
        )


def _accounting_handoff_start_schema_bootstrap_probe_listener(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    writer_pod_name: str,
    marker: str,
) -> None:
    _accounting_handoff_stop_schema_bootstrap_probe_listener(
        command_runner=command_runner,
        kube_context=kube_context,
        writer_pod_name=writer_pod_name,
        marker=marker,
    )
    python_code = """import signal
import socket
import sys

sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
sock.bind(("0.0.0.0", int(sys.argv[2])))
sock.listen(8)
signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
while True:
    connection, _address = sock.accept()
    connection.close()
"""
    pid_file = f"/tmp/{marker}.pid"
    script = f"""set -euo pipefail
command -v python3 >/dev/null 2>&1
umask 077
nohup python3 -c {shlex.quote(python_code)} {shlex.quote(marker)} {_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT} \
  </dev/null >{shlex.quote(f"/tmp/{marker}.log")} 2>&1 &
pid="$!"
printf '%s\\n' "$pid" > {shlex.quote(pid_file)}
for _ in $(seq 1 100); do
  kill -0 "$pid" 2>/dev/null || exit 76
  if ss -lntH | awk '{{print $4}}' | grep -Eq '(^|:){_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT}$'; then
    exit 0
  fi
  sleep 0.1
done
exit 77
"""
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            writer_pod_name,
            "-c",
            "accounting",
            "--",
            "bash",
            "-lc",
            script,
        ],
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        with suppress(SoperatorMigrationPhasePending):
            _accounting_handoff_stop_schema_bootstrap_probe_listener(
                command_runner=command_runner,
                kube_context=kube_context,
                writer_pod_name=writer_pod_name,
                marker=marker,
            )
        raise SoperatorMigrationPhasePending(
            "accounting handoff could not start its exact inert network probe listener."
        )


def _accounting_handoff_schema_bootstrap_tcp_probe(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    destination_ip: str,
    container: str = "",
) -> bool:
    command = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        _SOPERATOR_NAMESPACE,
        "exec",
        pod_name,
    ]
    if container:
        command.extend(["-c", container])
    command.extend(
        [
            "--",
            "bash",
            "-lc",
            (
                "command -v timeout >/dev/null 2>&1 || exit 125; "
                f"timeout 3 bash -c {shlex.quote(f'exec 3<>/dev/tcp/{destination_ip}/{_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT}')}"
            ),
        ]
    )
    result = command_runner(command, timeout_seconds=15, check=False)
    if result.returncode == 0:
        return True
    if result.returncode in {1, 124}:
        return False
    raise SoperatorMigrationPhasePending(
        "accounting handoff schema-bootstrap TCP probe could not produce a reliable result."
    )


def _accounting_handoff_ensure_schema_bootstrap_network_proof(
    *,
    state: dict[str, Any],
    writer_pod: Mapping[str, Any],
    probe_pod: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    bootstrap = state.setdefault("target_schema_bootstrap", {})
    if not isinstance(bootstrap, dict):
        raise RuntimeError("accounting handoff target_schema_bootstrap must be a mapping.")
    bootstrap_id = str(bootstrap.get("bootstrap_id") or "").strip()
    marker = _accounting_handoff_schema_bootstrap_probe_marker(bootstrap_id)
    binding = {
        "writer_pod_uid": str(writer_pod.get("uid") or ""),
        "writer_pod_ip": str(writer_pod.get("pod_ip") or ""),
        "probe_pod_uid": str(probe_pod.get("uid") or ""),
        "probe_pod_ip": str(probe_pod.get("pod_ip") or ""),
        "tcp_port": _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT,
    }
    proof = bootstrap.setdefault("network_enforcement_proof", {})
    if not isinstance(proof, dict):
        raise RuntimeError("accounting handoff network_enforcement_proof must be a mapping.")
    existing_binding = _mapping(proof.get("binding"))
    if existing_binding and existing_binding != binding:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap network probe binding changed."
        )
    positive = _mapping(proof.get("positive_control"))
    if not positive:
        if (
            _accounting_handoff_optional_schema_bootstrap_network_policy(
                command_runner=command_runner,
                kube_context=kube_context,
                name=f"nebius-cxcli-acct-bootstrap-{bootstrap_id[:12]}",
            )
            is not None
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found its schema-bootstrap policy before durable "
                "positive-control proof."
            )
        try:
            _accounting_handoff_start_schema_bootstrap_probe_listener(
                command_runner=command_runner,
                kube_context=kube_context,
                writer_pod_name=str(writer_pod["name"]),
                marker=marker,
            )
            if not _accounting_handoff_schema_bootstrap_tcp_probe(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=str(probe_pod["name"]),
                destination_ip=str(writer_pod["pod_ip"]),
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff network probe lacked its pre-policy positive control."
                )
        finally:
            _accounting_handoff_stop_schema_bootstrap_probe_listener(
                command_runner=command_runner,
                kube_context=kube_context,
                writer_pod_name=str(writer_pod["name"]),
                marker=marker,
            )
        proof.update(
            {
                "schema": _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_NETWORK_PROOF_SCHEMA,
                "binding": binding,
                "positive_control": {"reachable_before_policy": True, "verified_at": _utc_now()},
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif (
        proof.get("schema") != _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_NETWORK_PROOF_SCHEMA
        or positive.get("reachable_before_policy") is not True
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap positive-control proof is malformed."
        )

    policy = _accounting_handoff_apply_schema_bootstrap_network_policy(
        state=state,
        writer_pod=writer_pod,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    union = _accounting_handoff_schema_bootstrap_network_policy_union(
        command_runner=command_runner,
        kube_context=kube_context,
        writer_pod=writer_pod,
        expected_policy=policy,
    )
    prior_union = _mapping(proof.get("policy_union"))
    if prior_union and prior_union != union:
        raise SoperatorMigrationPhasePending(
            "accounting handoff applicable NetworkPolicy union changed after enforcement proof."
        )
    try:
        _accounting_handoff_start_schema_bootstrap_probe_listener(
            command_runner=command_runner,
            kube_context=kube_context,
            writer_pod_name=str(writer_pod["name"]),
            marker=marker,
        )
        remotely_reachable = _accounting_handoff_schema_bootstrap_tcp_probe(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=str(probe_pod["name"]),
            destination_ip=str(writer_pod["pod_ip"]),
        )
        locally_reachable = _accounting_handoff_schema_bootstrap_tcp_probe(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=str(writer_pod["name"]),
            destination_ip="127.0.0.1",
            container="accounting",
        )
        if remotely_reachable or not locally_reachable:
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap NetworkPolicy did not prove enforced "
                "cross-Pod isolation while the local listener remained live."
            )
    finally:
        _accounting_handoff_stop_schema_bootstrap_probe_listener(
            command_runner=command_runner,
            kube_context=kube_context,
            writer_pod_name=str(writer_pod["name"]),
            marker=marker,
        )
    proof.update(
        {
            "schema": _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_NETWORK_PROOF_SCHEMA,
            "binding": binding,
            "policy_union": union,
            "remote_reachable_under_policy": False,
            "local_listener_reachable_under_policy": True,
            "verified_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return proof


def _accounting_handoff_apply_schema_bootstrap_network_policy(
    *,
    state: dict[str, Any],
    writer_pod: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    bootstrap = state.setdefault("target_schema_bootstrap", {})
    if not isinstance(bootstrap, dict):
        raise RuntimeError("accounting handoff target_schema_bootstrap must be a mapping.")
    bootstrap_id = str(bootstrap.get("bootstrap_id") or "").strip()
    if not re.fullmatch(r"[0-9a-f]{32}", bootstrap_id):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap lacks its exact operation id."
        )
    name = f"nebius-cxcli-acct-bootstrap-{bootstrap_id[:12]}"
    manifest = _accounting_handoff_schema_bootstrap_network_policy_manifest(
        name=name,
        selector=_mapping(writer_pod.get("network_selector")),
    )
    manifest_sha256 = _fingerprint(manifest)
    policy_state = bootstrap.setdefault("network_policy", {})
    if not isinstance(policy_state, dict):
        raise RuntimeError("accounting handoff schema-bootstrap network_policy must be a mapping.")
    if not policy_state:
        if (
            _accounting_handoff_optional_schema_bootstrap_network_policy(
                command_runner=command_runner,
                kube_context=kube_context,
                name=name,
            )
            is not None
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found its schema-bootstrap NetworkPolicy before "
                "durable create intent."
            )
        policy_state.update(
            {
                "status": "create-intent",
                "name": name,
                "manifest_sha256": manifest_sha256,
                "intent_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if (
        str(policy_state.get("name") or "") != name
        or str(policy_state.get("manifest_sha256") or "") != manifest_sha256
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap NetworkPolicy binding changed."
        )
    live = _accounting_handoff_optional_schema_bootstrap_network_policy(
        command_runner=command_runner,
        kube_context=kube_context,
        name=name,
    )
    if live is None:
        if policy_state.get("status") != "create-intent":
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap NetworkPolicy disappeared after creation."
            )
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "create",
                "-f",
                "-",
                "-o",
                "json",
            ],
            input_text=json.dumps(manifest, sort_keys=True),
            timeout_seconds=120,
            check=False,
        )
        if result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "accounting handoff could not create its deny-ingress schema-bootstrap "
                "NetworkPolicy."
            )
        try:
            live = json.loads(result.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "accounting handoff NetworkPolicy create returned invalid JSON."
            ) from exc
    identity = _validated_namespaced_resource_identity(
        _mapping(live),
        expected_api_version="networking.k8s.io/v1",
        expected_kind="NetworkPolicy",
        label="Accounting schema-bootstrap NetworkPolicy",
    )
    live_spec = _mapping(_mapping(live).get("spec"))
    live_selector = _mapping(live_spec.get("podSelector"))
    if (
        identity["name"] != name
        or identity["namespace"] != _SOPERATOR_NAMESPACE
        or live_spec.get("policyTypes") != ["Ingress"]
        or live_spec.get("ingress", []) != []
        or live_selector.get("matchLabels") != _mapping(writer_pod.get("network_selector"))
        or live_selector.get("matchExpressions", []) != []
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap NetworkPolicy does not match its exact "
            "deny-ingress selector."
        )
    existing_uid = str(policy_state.get("uid") or "").strip()
    if existing_uid and existing_uid != identity["uid"]:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap NetworkPolicy UID changed."
        )
    policy_state.update(
        {
            "status": "created",
            "uid": identity["uid"],
            "resource_version": identity["resourceVersion"],
            "created_at": policy_state.get("created_at") or _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return policy_state


def _accounting_handoff_schema_bootstrap_script() -> str:
    return r"""set -euo pipefail
source_cluster="$1"
target_cluster="$2"
bootstrap_port="$3"
expected_update_rc="$4"
case "$expected_update_rc" in (0|1) ;; (*) exit 68;; esac
umask 077
tmp_dir="$(mktemp -d /tmp/nebius-cxcli-accounting-bootstrap.XXXXXX)"
dbd_pid=""
remove_tmp_dir() {
  find "$tmp_dir" -mindepth 1 -maxdepth 1 -type f -delete 2>/dev/null || true
  rmdir "$tmp_dir" 2>/dev/null || true
}
stop_dbd() {
  if [ -n "$dbd_pid" ] && kill -0 "$dbd_pid" 2>/dev/null; then
    kill -TERM "$dbd_pid"
    wait "$dbd_pid"
  fi
  dbd_pid=""
}
cleanup() {
  stop_dbd || true
  remove_tmp_dir
}
trap cleanup EXIT HUP INT TERM
cp -L /mnt/slurm-configs/*.conf "$tmp_dir"/
head -c 32 /dev/urandom > "$tmp_dir/jwt_hs256.key"
awk -v port="$bootstrap_port" -v dir="$tmp_dir" '
  BEGIN { IGNORECASE=1 }
  /^[[:space:]]*(DbdAddr|DbdPort|PidFile|LogFile|AuthAltParameters)[[:space:]]*=/ { next }
  { print }
  END {
    print "DbdAddr=127.0.0.1"
    print "DbdPort=" port
    print "PidFile=" dir "/slurmdbd.pid"
    print "LogFile=" dir "/slurmdbd.log"
    print "AuthAltParameters=jwt_key=" dir "/jwt_hs256.key"
  }
' /mnt/slurm-configs/slurmdbd.conf > "$tmp_dir/slurmdbd.conf"
awk -v port="$bootstrap_port" '
  BEGIN { IGNORECASE=1 }
  /^[[:space:]]*(AccountingStorageHost|AccountingStorageBackupHost|AccountingStoragePort)[[:space:]]*=/ { next }
  { print }
  END {
    print "AccountingStorageHost=127.0.0.1"
    print "AccountingStoragePort=" port
  }
' /mnt/slurm-configs/slurm.conf > "$tmp_dir/slurm.conf"
chmod 600 "$tmp_dir/slurmdbd.conf"
if ss -lntH | awk '{print $4}' | grep -Eq "(^|:)${bootstrap_port}$"; then
  exit 70
fi
set +e
SLURM_CONF="$tmp_dir/slurmdbd.conf" /usr/sbin/slurmdbd -u >/dev/null 2>&1
update_rc="$?"
set -e
[ "$update_rc" -eq "$expected_update_rc" ] || exit 69
SLURM_CONF="$tmp_dir/slurmdbd.conf" /usr/sbin/slurmdbd -D >"$tmp_dir/slurmdbd.stdout" 2>&1 &
dbd_pid="$!"
ready=0
for _ in $(seq 1 600); do
  if ! kill -0 "$dbd_pid" 2>/dev/null; then
    wait "$dbd_pid" || true
    exit 71
  fi
  if SLURM_CONF="$tmp_dir/slurm.conf" sacctmgr -nP show cluster format=Cluster \
      >/dev/null 2>&1; then
    ready=1
    break
  fi
  sleep 1
done
if [ "$ready" -ne 1 ]; then
  exit 72
fi
has_cluster() {
  SLURM_CONF="$tmp_dir/slurm.conf" sacctmgr -nP show cluster format=Cluster 2>/dev/null \
    | awk -F '|' -v expected="$1" '$1 == expected { found=1 } END { exit !found }'
}
if ! has_cluster "$source_cluster"; then
  SLURM_CONF="$tmp_dir/slurm.conf" sacctmgr -i add cluster "$source_cluster" \
    >/dev/null 2>&1
fi
if ! has_cluster "$target_cluster"; then
  SLURM_CONF="$tmp_dir/slurm.conf" sacctmgr -i add cluster "$target_cluster" \
    >/dev/null 2>&1
fi
has_cluster "$source_cluster"
has_cluster "$target_cluster"
stop_dbd
if ss -lntH | awk '{print $4}' | grep -Eq "(^|:)${bootstrap_port}$"; then
  exit 73
fi
trap - EXIT HUP INT TERM
remove_tmp_dir
"""


def _accounting_handoff_schema_bootstrap_process_absent(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> bool:
    script = (
        "set -euo pipefail; "
        f"! ss -lntH | awk '{{print $4}}' | grep -Eq '(^|:){_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT}$'; "
        "! pgrep -x slurmdbd >/dev/null 2>&1"
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            pod_name,
            "-c",
            "accounting",
            "--",
            "bash",
            "-lc",
            script,
        ],
        timeout_seconds=30,
        check=False,
    )
    return result.returncode == 0


def _accounting_handoff_schema_bootstrap_observation(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    source_cluster_name: str,
    target_cluster_name: str,
) -> dict[str, Any]:
    database_tables = _accounting_handoff_optional_database_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    if not database_tables:
        return {
            "database_tables": [],
            "registrations": [],
            "registration_ids": {},
            "source_tables": [],
            "target_tables": [],
        }
    if "cluster_table" not in database_tables:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found a nonempty target database without cluster_table; "
            "schema bootstrap will not modify partial state."
        )
    registrations = _accounting_handoff_registered_clusters(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    registration_ids = _accounting_handoff_registered_cluster_ids(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    if set(registration_ids) != set(registrations):
        raise SoperatorMigrationPhasePending(
            "accounting handoff cluster registration names and internal IDs disagree."
        )
    source_tables = _accounting_handoff_optional_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        cluster_name=source_cluster_name,
    )
    target_tables = (
        source_tables
        if source_cluster_name == target_cluster_name
        else _accounting_handoff_optional_cluster_tables(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            cluster_name=target_cluster_name,
        )
    )
    return {
        "database_tables": list(database_tables),
        "registrations": list(registrations),
        "registration_ids": registration_ids,
        "source_tables": list(source_tables),
        "target_tables": list(target_tables),
    }


def _accounting_handoff_cleanup_schema_bootstrap_network_policy(
    *,
    state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    bootstrap = _mapping(state.get("target_schema_bootstrap"))
    policy = _mapping(bootstrap.get("network_policy"))
    name = str(policy.get("name") or "").strip()
    uid = str(policy.get("uid") or "").strip()
    resource_version = str(policy.get("resource_version") or "").strip()
    if not name or not uid or not resource_version:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap NetworkPolicy cleanup binding is incomplete."
        )
    if policy.get("status") == "deleted":
        if (
            _accounting_handoff_optional_schema_bootstrap_network_policy(
                command_runner=command_runner,
                kube_context=kube_context,
                name=name,
            )
            is not None
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap NetworkPolicy reappeared after deletion."
            )
        return
    live = _accounting_handoff_optional_schema_bootstrap_network_policy(
        command_runner=command_runner,
        kube_context=kube_context,
        name=name,
    )
    if live is None:
        if not str(policy.get("delete_intent_at") or "").strip():
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap NetworkPolicy disappeared before "
                "durable delete intent."
            )
        policy["status"] = "deleted"
        policy["deleted_at"] = policy.get("deleted_at") or _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        return
    live_identity = _validated_namespaced_resource_identity(
        live,
        expected_api_version="networking.k8s.io/v1",
        expected_kind="NetworkPolicy",
        label="Accounting schema-bootstrap NetworkPolicy cleanup",
    )
    if (
        live_identity["name"] != name
        or live_identity["uid"] != uid
        or live_identity["resourceVersion"] != resource_version
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema-bootstrap NetworkPolicy changed before cleanup."
        )
    if not str(policy.get("delete_intent_at") or "").strip():
        policy["delete_intent_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    _command_runner_uid_preconditioned_delete(
        command_runner,
        kube_context=kube_context,
        api_path=(
            f"/apis/networking.k8s.io/v1/namespaces/{_SOPERATOR_NAMESPACE}/networkpolicies/{name}"
        ),
        uid=uid,
        resource_version=resource_version,
        propagation_policy="Background",
        timeout_seconds=120,
    )
    policy["status"] = "deleted"
    policy["deleted_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()


def _accounting_handoff_checkpoint_schema_bootstrap_dispatch(
    *,
    bootstrap: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    attempts = _non_negative_int(bootstrap.get("dispatch_attempts"), fallback=0)
    if attempts >= _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_MAX_ATTEMPTS:
        raise SoperatorMigrationPhasePending(
            "accounting handoff exhausted its bounded target schema-bootstrap attempts "
            "while both writers remain command-fenced."
        )
    previous_bootstrap = copy.deepcopy(bootstrap)
    attempt_started_at = _utc_now()
    bootstrap.update(
        {
            "status": "running",
            "dispatch_attempts": attempts + 1,
            "last_attempt_started_at": attempt_started_at,
        }
    )
    bootstrap["started_at"] = bootstrap.get("started_at") or attempt_started_at
    bootstrap.pop("exit_code", None)
    bootstrap.pop("last_attempt_finished_at", None)
    try:
        if checkpoint_writer is not None:
            checkpoint_writer()
    except BaseException:
        bootstrap.clear()
        bootstrap.update(previous_bootstrap)
        raise


def _accounting_handoff_schema_bootstrap_registration_id_proof(
    *,
    state: Mapping[str, Any],
    observation: Mapping[str, Any],
    source_cluster_name: str,
    target_cluster_name: str,
) -> dict[str, Any]:
    if source_cluster_name == target_cluster_name:
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap requires distinct source and target names."
        )
    source_policy = _mapping(state.get("source_cluster_policy"))
    old_source_id = _non_negative_int(source_policy.get("cluster_id"), fallback=0)
    registration_ids = {
        str(key): _non_negative_int(value, fallback=0)
        for key, value in _mapping(observation.get("registration_ids")).items()
    }
    expected_names = {source_cluster_name, target_cluster_name}
    if (
        not 2 <= old_source_id <= 4095
        or set(registration_ids) != expected_names
        or len(set(registration_ids.values())) != 2
        or any(not 2 <= value <= 4095 for value in registration_ids.values())
        or registration_ids[target_cluster_name] == old_source_id
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff schema bootstrap could not prove collision-free Slurm "
            "cluster IDs for historical and future SLUID namespaces."
        )
    structural = {
        "schema": "nebius-cxcli-accounting-bootstrap-cluster-ids/v1",
        "old_source_cluster_id": old_source_id,
        "new_source_cluster_id": registration_ids[source_cluster_name],
        "target_cluster_id": registration_ids[target_cluster_name],
    }
    structural["proof_sha256"] = _fingerprint(structural)
    return structural


def _accounting_handoff_ensure_target_schema_bootstrap(
    *,
    state: dict[str, Any],
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_pod: str,
    target_identity: Mapping[str, Any],
    dump_path: Path,
    source_cluster_name: str,
    target_cluster_name: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    expected_registrations = sorted({source_cluster_name, target_cluster_name})
    writer_pod = _accounting_handoff_fenced_writer_pod_identity(
        state=state,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    bootstrap = state.setdefault("target_schema_bootstrap", {})
    if not isinstance(bootstrap, dict):
        raise RuntimeError("accounting handoff target_schema_bootstrap must be a mapping.")
    observation = _accounting_handoff_schema_bootstrap_observation(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )
    complete_live = (
        sorted(observation["registrations"]) == expected_registrations
        and bool(observation["source_tables"])
        and bool(observation["target_tables"])
    )
    if not bootstrap:
        initial_status = "verified-existing" if complete_live else "intent"
        if not complete_live and (
            observation["registrations"]
            or observation["source_tables"]
            or observation["target_tables"]
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found a partial or unexpected target schema bootstrap; "
                "cxcli did not add or remove database objects."
            )
        bootstrap.update(
            {
                "schema": _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_SCHEMA,
                "status": initial_status,
                "bootstrap_id": uuid4().hex,
                "source_cluster_name": source_cluster_name,
                "target_cluster_name": target_cluster_name,
                "target_database_identity": {
                    key: target_identity.get(key)
                    for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
                },
                "writer_pod": writer_pod,
                "client_port": _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT,
                ("verified_at" if complete_live else "intent_at"): _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    if (
        bootstrap.get("schema") != _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_SCHEMA
        or bootstrap.get("source_cluster_name") != source_cluster_name
        or bootstrap.get("target_cluster_name") != target_cluster_name
        or _mapping(bootstrap.get("target_database_identity"))
        != {key: target_identity.get(key) for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS}
        or _mapping(bootstrap.get("writer_pod")) != writer_pod
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target schema-bootstrap identity changed."
        )
    binary_proof = _accounting_handoff_ensure_schema_bootstrap_binary_proof(
        state=state,
        writer_pod=writer_pod,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        database_tables=tuple(str(item) for item in observation["database_tables"]),
    )

    def _run_bootstrap() -> None:
        probe_pod = _accounting_handoff_schema_bootstrap_probe_pod_identity(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            expected_uid=str(target_identity.get("pod_uid") or ""),
        )
        _accounting_handoff_ensure_schema_bootstrap_network_proof(
            state=state,
            writer_pod=writer_pod,
            probe_pod=probe_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        _accounting_handoff_checkpoint_schema_bootstrap_dispatch(
            bootstrap=bootstrap,
            checkpoint_writer=checkpoint_writer,
        )
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                "-i",
                str(writer_pod["name"]),
                "-c",
                "accounting",
                "--",
                "bash",
                "-s",
                "--",
                source_cluster_name,
                target_cluster_name,
                str(_ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_PORT),
                str(binary_proof["update_check_exit_code"]),
            ],
            input_text=_accounting_handoff_schema_bootstrap_script(),
            timeout_seconds=1800,
            check=False,
        )
        bootstrap["exit_code"] = result.returncode
        bootstrap["last_attempt_finished_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        if result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "accounting handoff policy-isolated target-version schema bootstrap failed; "
                "stdout/stderr was redacted and the deny-ingress policy remains active "
                f"(exit {result.returncode})."
            )

    status = str(bootstrap.get("status") or "")
    if status in {"verified", "verified-existing"}:
        if not complete_live:
            raise SoperatorMigrationPhasePending(
                "accounting handoff verified target schema bootstrap drifted."
            )
    elif status == "intent":
        _run_bootstrap()
        status = "running"
    if status == "running":
        if not _accounting_handoff_schema_bootstrap_process_absent(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=str(writer_pod["name"]),
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap SlurmDBD process or listener is "
                "still present; the deny-ingress policy remains active."
            )
        observation = _accounting_handoff_schema_bootstrap_observation(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            source_cluster_name=source_cluster_name,
            target_cluster_name=target_cluster_name,
        )
        exact_empty = not (
            observation["registrations"]
            or observation["source_tables"]
            or observation["target_tables"]
        )
        if exact_empty:
            _run_bootstrap()
            observation = _accounting_handoff_schema_bootstrap_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
                source_cluster_name=source_cluster_name,
                target_cluster_name=target_cluster_name,
            )
        if (
            sorted(observation["registrations"]) != expected_registrations
            or not observation["source_tables"]
            or not observation["target_tables"]
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema bootstrap left partial registrations or tables; "
                "cxcli will not rerun the non-transactional cluster-add operation."
            )
        if (
            _accounting_handoff_database_connection_count(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
            )
            != 0
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema bootstrap left a target database connection open."
            )
        _accounting_handoff_pause_target_writer(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        bootstrap["status"] = "verified"
        bootstrap["verified_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif status not in {"verified", "verified-existing"}:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target schema bootstrap has an unsupported checkpoint state."
        )
    registration_id_proof = _accounting_handoff_schema_bootstrap_registration_id_proof(
        state=state,
        observation=observation,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )
    existing_registration_id_proof = _mapping(bootstrap.get("registration_id_proof"))
    if existing_registration_id_proof:
        if existing_registration_id_proof != registration_id_proof:
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-bootstrap Slurm cluster ID proof changed."
            )
    elif state.get("import_execution"):
        raise SoperatorMigrationPhasePending(
            "accounting handoff import intent predates its Slurm cluster ID collision proof."
        )
    else:
        bootstrap["registration_id_proof"] = registration_id_proof
        if checkpoint_writer is not None:
            checkpoint_writer()
    if state.get("import_execution"):
        target_schema = _accounting_handoff_load_target_cluster_schema(
            state=state,
            source_cluster_name=source_cluster_name,
            target_cluster_name=target_cluster_name,
        )
        raw_suffixes = target_schema.get("table_suffixes")
        if not isinstance(raw_suffixes, Sequence) or isinstance(
            raw_suffixes, (str, bytes, bytearray)
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff target cluster schema suffix inventory is invalid."
            )
        expected_suffixes = {str(item) for item in raw_suffixes}
        target_prefix = f"{target_cluster_name}_"
        observed_target_suffixes = {
            str(table).removeprefix(target_prefix) for table in observation["target_tables"]
        }
        if (
            sorted(observation["registrations"]) != expected_registrations
            or observed_target_suffixes != expected_suffixes
            or str(bootstrap.get("schema_proof_sha256") or "")
            != str(target_schema.get("proof_sha256") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff target-version schema bootstrap drifted after import intent."
            )
        if _mapping(bootstrap.get("network_policy")):
            _accounting_handoff_cleanup_schema_bootstrap_network_policy(
                state=state,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        return target_schema
    schema_payload = _accounting_handoff_target_cluster_schema_payload(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )
    existing_proof = str(bootstrap.get("schema_proof_sha256") or "").strip()
    if existing_proof and existing_proof != schema_payload["proof_sha256"]:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target schema-bootstrap proof changed before import."
        )
    schema_path = dump_path.parent / _ACCOUNTING_HANDOFF_TARGET_CLUSTER_SCHEMA_FILENAME
    schema_metadata = _accounting_handoff_write_target_cluster_schema(
        payload=schema_payload,
        path=schema_path,
    )
    existing_metadata = _mapping(state.get("target_cluster_schema"))
    if existing_metadata and existing_metadata != schema_metadata:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target cluster schema artifact changed after checkpoint."
        )
    state["target_cluster_schema"] = schema_metadata
    bootstrap["schema_proof_sha256"] = schema_payload["proof_sha256"]
    bootstrap["table_suffixes"] = schema_payload["table_suffixes"]
    if checkpoint_writer is not None:
        checkpoint_writer()
    if _mapping(bootstrap.get("network_policy")):
        _accounting_handoff_cleanup_schema_bootstrap_network_policy(
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    return _accounting_handoff_load_target_cluster_schema(
        state=state,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )


def _accounting_handoff_import_replay_binding(
    *,
    state: dict[str, Any],
    dump_path: Path,
) -> dict[str, Any]:
    expected_dump = _mapping(state.get("dump"))
    dump_text = _accounting_handoff_read_bound_private_text(
        path=dump_path,
        metadata=expected_dump,
        label="import dump",
    )
    raw_tables = state.get("source_database_tables")
    if not isinstance(raw_tables, Sequence) or isinstance(raw_tables, (str, bytes, bytearray)):
        raise SoperatorMigrationPhasePending(
            "accounting handoff final source dump lacks its database table inventory."
        )
    tables = tuple(str(item) for item in raw_tables if str(item).strip())
    reset_tables = tuple(
        table
        for table in tables
        if table not in {"cluster_table", *_ACCOUNTING_HANDOFF_INTERNAL_TABLES}
    )
    missing_reset_tables = [
        table for table in reset_tables if f"DROP TABLE IF EXISTS `{table}`;" not in dump_text
    ]
    if missing_reset_tables:
        raise SoperatorMigrationPhasePending(
            "accounting handoff refuses crash replay because the immutable dump does "
            "not reset every imported table before INSERT."
        )
    binding = {
        "schema": _ACCOUNTING_HANDOFF_IMPORT_REPLAY_SCHEMA,
        "mode": "drop-table-reset-while-target-writer-disabled",
        "dump_sha256": str(expected_dump["sha256"]),
        "source_dump_generation": _non_negative_int(
            state.get("source_dump_generation"), fallback=0
        ),
        "reset_tables": list(reset_tables),
    }
    existing = state.get("import_replay")
    if isinstance(existing, Mapping) and to_plain_data(existing) != binding:
        raise SoperatorMigrationPhasePending(
            "accounting handoff import replay binding changed after import intent."
        )
    return binding


def _accounting_handoff_adopt_legacy_no_stdin_import(
    *,
    state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_pod: str,
    source_cluster_name: str,
    target_cluster_name: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    attempts = _non_negative_int(state.get("import_attempts"), fallback=0)
    existing = state.get("legacy_no_stdin_import")
    if isinstance(existing, Mapping):
        if existing.get(
            "schema"
        ) != _ACCOUNTING_HANDOFF_LEGACY_NO_STDIN_SCHEMA or _non_negative_int(
            existing.get("attempts"), fallback=0
        ) != _non_negative_int(state.get("legacy_import_attempts"), fallback=0):
            raise SoperatorMigrationPhasePending(
                "accounting handoff legacy no-stdin migration checkpoint is malformed."
            )
        return
    if attempts == 0 or state.get("target_schema_bootstrap") or state.get("import_execution"):
        return
    definitions = _accounting_handoff_load_target_global_schema(
        state=state,
        source_cluster_name=source_cluster_name,
    )
    observed_tables = set(
        _accounting_handoff_database_tables(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
        )
    )
    expected_tables = {
        *definitions,
        "cluster_table",
        *_ACCOUNTING_HANDOFF_INTERNAL_TABLES,
    }
    registrations = _accounting_handoff_registered_clusters(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
    )
    source_tables = _accounting_handoff_optional_cluster_tables(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        cluster_name=source_cluster_name,
    )
    target_tables = (
        source_tables
        if source_cluster_name == target_cluster_name
        else _accounting_handoff_optional_cluster_tables(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            cluster_name=target_cluster_name,
        )
    )
    schema_matches = all(
        _accounting_handoff_show_create_table(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            table_name=table_name,
        )
        == expected_create
        for table_name, expected_create in definitions.items()
    )
    if (
        observed_tables != expected_tables
        or registrations
        or source_tables
        or target_tables
        or not schema_matches
        or state.get("imported_dump")
        or state.get("import_completed_at")
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot prove that the legacy import omitted stdin and "
            "left the fresh target database unchanged."
        )
    state["legacy_no_stdin_import"] = {
        "schema": _ACCOUNTING_HANDOFF_LEGACY_NO_STDIN_SCHEMA,
        "status": "verified-noop",
        "attempts": attempts,
        "observed_database_tables": sorted(observed_tables),
        "verified_at": _utc_now(),
    }
    state["legacy_import_attempts"] = attempts
    state["import_attempts"] = 0
    if str(state.get("import_started_at") or "").strip():
        state["legacy_import_started_at"] = state.pop("import_started_at")
    if checkpoint_writer is not None:
        checkpoint_writer()


def _accounting_handoff_import_execution_binding(
    *,
    state: Mapping[str, Any],
    import_replay: Mapping[str, Any],
    target_identity: Mapping[str, Any],
) -> dict[str, Any]:
    bootstrap = _mapping(state.get("target_schema_bootstrap"))
    registration_id_proof = _mapping(bootstrap.get("registration_id_proof"))
    cluster_schema = _mapping(state.get("target_cluster_schema"))
    global_schema = _mapping(state.get("target_global_schema"))
    if (
        bootstrap.get("schema") != _ACCOUNTING_HANDOFF_SCHEMA_BOOTSTRAP_SCHEMA
        or bootstrap.get("status") not in {"verified", "verified-existing"}
        or not str(bootstrap.get("schema_proof_sha256") or "").strip()
        or registration_id_proof.get("schema") != "nebius-cxcli-accounting-bootstrap-cluster-ids/v1"
        or not re.fullmatch(r"[0-9a-f]{64}", str(registration_id_proof.get("proof_sha256") or ""))
        or not str(cluster_schema.get("sha256") or "").strip()
        or not str(global_schema.get("sha256") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff import lacks its verified target-version schema bootstrap."
        )
    return {
        "schema": _ACCOUNTING_HANDOFF_IMPORT_EXECUTION_SCHEMA,
        "dump": to_plain_data(import_replay),
        "target_database_identity": {
            key: target_identity.get(key) for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
        },
        "schema_bootstrap_proof_sha256": str(bootstrap["schema_proof_sha256"]),
        "registration_id_proof_sha256": str(registration_id_proof["proof_sha256"]),
        "target_cluster_schema_sha256": str(cluster_schema["sha256"]),
        "target_global_schema_sha256": str(global_schema["sha256"]),
    }


def _accounting_handoff_import_journal_observation(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> dict[str, Any]:
    table = _ACCOUNTING_HANDOFF_IMPORT_JOURNAL_TABLE
    exists = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=(
            "SELECT COUNT(*) FROM information_schema.TABLES "
            "WHERE TABLE_SCHEMA='slurm_acct_db' "
            f"AND TABLE_NAME='{table}';"
        ),
    ).strip()
    if exists == "0":
        return {"status": "absent"}
    if exists != "1":
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal table identity is ambiguous."
        )
    output = _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=(
            "SELECT operation_id,dump_sha256,source_dump_generation "
            f"FROM slurm_acct_db.`{table}` ORDER BY operation_id;"
        ),
    )
    rows = [line.split("\t") for line in output.splitlines() if line.strip()]
    if not rows:
        return {"status": "empty"}
    if len(rows) != 1 or len(rows[0]) != 3 or not rows[0][2].isdecimal():
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal does not contain one exact completion marker."
        )
    return {
        "status": "complete",
        "marker": {
            "operation_id": rows[0][0],
            "dump_sha256": rows[0][1],
            "source_dump_generation": int(rows[0][2]),
        },
    }


def _accounting_handoff_import_journal_marker(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
) -> dict[str, Any] | None:
    observation = _accounting_handoff_import_journal_observation(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    if observation.get("status") == "absent":
        return None
    if observation.get("status") != "complete":
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal exists without one exact completion marker."
        )
    return dict(_mapping(observation.get("marker")))


def _accounting_handoff_import_payload(
    *,
    dump_text: str,
    operation_id: str,
    dump_sha256: str,
    source_dump_generation: int,
) -> str:
    if (
        not re.fullmatch(r"[0-9a-f]{32}", operation_id)
        or not re.fullmatch(r"[0-9a-f]{64}", dump_sha256)
        or source_dump_generation <= 0
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal binding is invalid."
        )
    table = _ACCOUNTING_HANDOFF_IMPORT_JOURNAL_TABLE
    return (
        dump_text.rstrip() + "\n" + f"CREATE TABLE IF NOT EXISTS `{table}` ("
        "`operation_id` char(32) NOT NULL,"
        "`dump_sha256` char(64) NOT NULL,"
        "`source_dump_generation` bigint unsigned NOT NULL,"
        "PRIMARY KEY (`operation_id`));\n" + f"DELETE FROM `{table}`;\n" + f"INSERT INTO `{table}` "
        "(`operation_id`,`dump_sha256`,`source_dump_generation`) VALUES "
        f"('{operation_id}','{dump_sha256}',{source_dump_generation});\n"
    )


def _accounting_handoff_expected_import_marker(
    *,
    execution: Mapping[str, Any],
    import_replay: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "operation_id": str(execution.get("operation_id") or ""),
        "dump_sha256": str(import_replay.get("dump_sha256") or ""),
        "source_dump_generation": _non_negative_int(
            import_replay.get("source_dump_generation"), fallback=0
        ),
    }


def _accounting_handoff_import_completion_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_pod: str,
    expected_marker: Mapping[str, Any],
    expected_source_tables: set[str],
    source_cluster_name: str,
    source_evidence: Mapping[str, Any],
) -> dict[str, Any] | None:
    observation = _accounting_handoff_import_journal_observation(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
    )
    status = str(observation.get("status") or "")
    if status in {"absent", "empty"}:
        return None
    marker = dict(_mapping(observation.get("marker")))
    if status != "complete" or marker != dict(expected_marker):
        raise SoperatorMigrationPhasePending(
            "accounting handoff import completion marker belongs to a different operation; "
            "the immutable reset was not replayed."
        )
    imported_tables = set(
        _accounting_handoff_cluster_tables(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            cluster_name=source_cluster_name,
        )
    )
    if imported_tables != expected_source_tables:
        raise SoperatorMigrationPhasePending(
            "accounting handoff import marker exists, but the imported source table "
            "inventory is incomplete."
        )
    target_evidence = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=source_cluster_name,
    )
    if target_evidence != source_evidence:
        raise SoperatorMigrationPhasePending(
            "accounting handoff import marker exists, but exact source-history evidence "
            "does not match; the target writer remains disabled."
        )
    return {"marker": marker, "history": target_evidence}


def _accounting_handoff_checkpoint_import_dispatch(
    *,
    state: dict[str, Any],
    execution: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    attempts = _non_negative_int(state.get("import_attempts"), fallback=0)
    if attempts >= _ACCOUNTING_HANDOFF_IMPORT_MAX_ATTEMPTS:
        raise SoperatorMigrationPhasePending(
            "accounting handoff exhausted its bounded exact-reset import attempts while "
            "both writers remain disabled."
        )
    previous_execution = copy.deepcopy(execution)
    had_attempts = "import_attempts" in state
    previous_attempts = state.get("import_attempts")
    execution.update(
        {
            "status": "running",
            "attempt": attempts + 1,
            "last_attempt_started_at": _utc_now(),
        }
    )
    execution["started_at"] = execution.get("started_at") or execution["last_attempt_started_at"]
    state["import_attempts"] = attempts + 1
    try:
        if checkpoint_writer is not None:
            checkpoint_writer()
    except BaseException:
        execution.clear()
        execution.update(previous_execution)
        if had_attempts:
            state["import_attempts"] = previous_attempts
        else:
            state.pop("import_attempts", None)
        raise


def _accounting_handoff_dispatch_import_reset(
    *,
    state: dict[str, Any],
    execution: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_pod: str,
    dump_path: Path,
    import_replay: Mapping[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> SoperatorMigrationCommandResult:
    dump_text = _accounting_handoff_read_bound_private_text(
        path=dump_path,
        metadata=_mapping(state.get("dump")),
        label="import dispatch dump",
    )
    if hashlib.sha256(dump_text.encode("utf-8")).hexdigest() != str(
        import_replay.get("dump_sha256") or ""
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff import dispatch dump changed from its immutable replay binding."
        )
    input_payload = _accounting_handoff_import_payload(
        dump_text=dump_text,
        operation_id=str(execution["operation_id"]),
        dump_sha256=str(import_replay["dump_sha256"]),
        source_dump_generation=_non_negative_int(
            import_replay.get("source_dump_generation"), fallback=0
        ),
    )
    _accounting_handoff_checkpoint_import_dispatch(
        state=state,
        execution=execution,
        checkpoint_writer=checkpoint_writer,
    )
    restore_command = (
        _ACCOUNTING_HANDOFF_CLIENT_PREAMBLE
        + "client_bin=$(command -v mariadb || command -v mysql); "
        + 'test -n "$client_bin"; '
        + '"$client_bin" --defaults-extra-file="$defaults_file" '
        + "--skip-force --skip-reconnect --one-database slurm_acct_db < /dev/stdin"
    )
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "exec",
            "-i",
            target_pod,
            "--",
            "bash",
            "-lc",
            restore_command,
        ],
        input_text=input_payload,
        timeout_seconds=1800,
        check=False,
    )
    execution["last_exit_code"] = result.returncode
    execution["last_attempt_finished_at"] = _utc_now()
    return result


def _accounting_handoff_drop_import_journal(
    *,
    state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    execution = _mapping(state.get("import_execution"))
    if execution.get("schema") != _ACCOUNTING_HANDOFF_IMPORT_EXECUTION_SCHEMA:
        return
    cleanup = state.setdefault("import_journal_cleanup", {})
    if not isinstance(cleanup, dict):
        raise RuntimeError("accounting handoff import_journal_cleanup must be a mapping.")
    cleanup_status = str(cleanup.get("status") or "")
    expected_marker = {
        "operation_id": str(execution.get("operation_id") or ""),
        "dump_sha256": str(
            _mapping(execution.get("binding")).get("dump", {}).get("dump_sha256") or ""
        ),
        "source_dump_generation": _non_negative_int(
            _mapping(_mapping(execution.get("binding")).get("dump")).get("source_dump_generation"),
            fallback=0,
        ),
    }
    marker = _accounting_handoff_import_journal_marker(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
    )
    if marker is None:
        if cleanup_status not in {"drop-intent", "cleaned"}:
            raise SoperatorMigrationPhasePending(
                "accounting handoff import journal disappeared before durable drop intent."
            )
        cleanup["status"] = "cleaned"
        cleanup["cleaned_at"] = cleanup.get("cleaned_at") or _utc_now()
        state["import_journal_cleaned_at"] = cleanup["cleaned_at"]
        if checkpoint_writer is not None:
            checkpoint_writer()
        return
    if marker != expected_marker:
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal changed before durable cleanup."
        )
    if cleanup_status == "cleaned":
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal reappeared after durable cleanup."
        )
    if cleanup_status != "drop-intent":
        cleanup.update(
            {
                "status": "drop-intent",
                "marker": marker,
                "intent_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    _accounting_handoff_database_query(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=pod_name,
        sql=f"DROP TABLE slurm_acct_db.`{_ACCOUNTING_HANDOFF_IMPORT_JOURNAL_TABLE}`;",
    )
    if (
        _accounting_handoff_import_journal_marker(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
        )
        is not None
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff import journal remained after its exact drop operation."
        )
    cleanup["status"] = "cleaned"
    cleanup["cleaned_at"] = _utc_now()
    state["import_journal_cleaned_at"] = cleanup["cleaned_at"]
    if checkpoint_writer is not None:
        checkpoint_writer()


def _accounting_handoff_revalidate_verified_before_cleanup(
    *,
    phase: dict[str, Any],
    state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    source_cluster_name = _accounting_handoff_cluster_name(
        state.get("source_cluster_name"),
        label="source",
    )
    target_cluster_name = _accounting_handoff_cluster_name(
        state.get("target_cluster_name"),
        label="target",
    )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    if _mapping(state.get("target_writer_command_fence")).get("schema") != (
        _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified checkpoint lacks the canonical target command fence."
        )
    if not phase.get("source_accounting_owner_retired_at"):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target verification cannot precede exact source-owner retirement."
        )
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    source_resource = _accounting_handoff_optional_exact_slurmcluster(
        command_runner=command_runner,
        kube_context=kube_context,
        binding=source_binding,
        label="source",
    )
    if source_resource is not None:
        raise SoperatorMigrationPhasePending(
            "accounting handoff source SlurmCluster reappeared after target writer restore."
        )
    cleanup_preconditions = _mapping(state.get("source_cleanup_preconditions"))
    if (
        str(cleanup_preconditions.get("uid") or "").strip() != source_binding["uid"]
        or not str(cleanup_preconditions.get("resource_version") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source retirement lacks its exact UID/resourceVersion "
            "preconditions."
        )
    _accounting_handoff_assert_source_pvc_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        expected=_mapping(state.get("source")),
    )
    if _accounting_handoff_source_writer_pods(
        command_runner=command_runner,
        kube_context=kube_context,
        replica_set_uids=_accounting_handoff_pre_fence_replica_sets(state),
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff retired source writer Pods reappeared after target restore."
        )
    dump_path = Path(str(_mapping(state.get("dump")).get("path") or ""))
    import_replay = _accounting_handoff_import_replay_binding(
        state=state,
        dump_path=dump_path,
    )
    if _mapping(state.get("imported_dump")) != import_replay:
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified dump generation/SHA binding changed before cleanup."
        )
    target_pod = f"{target_resource_name}-acct-db-0"
    target_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        expected_slurmcluster_binding=target_binding,
    )
    expected_target_identity = _mapping(state.get("target"))
    persistent_identity_keys = tuple(
        key for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS if key != "pod_uid"
    )
    if any(
        target_identity.get(key) != expected_target_identity.get(key)
        for key in persistent_identity_keys
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified target MariaDB persistent ownership or PVC "
            "identity changed before cleanup."
        )
    target_pod_uid_changed = target_identity.get("pod_uid") != expected_target_identity.get(
        "pod_uid"
    )
    _accounting_handoff_assert_target_writer_ready(
        state=state,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    live_history = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=source_cluster_name,
    )
    baseline_history = _mapping(state.get("target_history")) or _mapping(
        state.get("source_history")
    )
    if not _accounting_handoff_history_is_non_regressing(
        baseline_history,
        live_history,
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff verified target history regressed before source cleanup."
        )
    registrations = _accounting_handoff_slurm_registration_details(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    _accounting_handoff_validate_registration_details(
        registrations=registrations,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )
    sacct_evidence = _accounting_handoff_sacct_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        source_cluster_name=source_cluster_name,
        source_history=_mapping(state.get("source_history")),
    )
    state.update(
        {
            "target_history": live_history,
            "registered_clusters": sorted(registrations),
            "sacct_verification": sacct_evidence,
            "verified_revalidated_at": _utc_now(),
        }
    )
    if target_pod_uid_changed:
        raw_rollovers = state.setdefault("target_pod_uid_rollovers", [])
        if not isinstance(raw_rollovers, list):
            raise RuntimeError("accounting handoff target_pod_uid_rollovers must be a list.")
        raw_rollovers.append(
            {
                "from_pod_uid": str(expected_target_identity.get("pod_uid") or ""),
                "to_pod_uid": str(target_identity.get("pod_uid") or ""),
                "persistent_identity_fingerprint": _fingerprint(
                    {key: target_identity.get(key) for key in persistent_identity_keys}
                ),
                "verified_at": state["verified_revalidated_at"],
            }
        )
        state["target"] = target_identity
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Accounting history handoff revalidated retired source ownership, retained rollback "
        "artifacts, exact target writer restore, non-regressing history, and registrations."
    ]


def _accounting_handoff_revalidate_in_place_verified(
    *,
    state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    source_cluster_name = _accounting_handoff_cluster_name(
        state.get("source_cluster_name"),
        label="source",
    )
    target_cluster_name = _accounting_handoff_cluster_name(
        state.get("target_cluster_name"),
        label="target",
    )
    if source_cluster_name != target_cluster_name:
        raise SoperatorMigrationPhasePending(
            "accounting handoff in-place verified checkpoint has distinct source/target names."
        )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    target_pod = f"{target_resource_name}-acct-db-0"
    target_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
    )
    expected_identity = _mapping(state.get("target")) or _mapping(state.get("source"))
    if any(
        target_identity.get(key) != expected_identity.get(key)
        for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff in-place MariaDB Pod/PVC identity changed after verification."
        )
    live_history = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=source_cluster_name,
    )
    baseline_history = _mapping(state.get("target_history")) or _mapping(
        state.get("source_history")
    )
    if not _accounting_handoff_history_is_non_regressing(
        baseline_history,
        live_history,
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff in-place history regressed after verification."
        )
    sacct_evidence = _accounting_handoff_sacct_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        source_cluster_name=source_cluster_name,
        source_history=_mapping(state.get("source_history")),
    )
    state.update(
        {
            "target_history": live_history,
            "sacct_verification": sacct_evidence,
            "in_place_revalidated_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Accounting history handoff revalidated in-place MariaDB Pod/PVC continuity, "
        "non-regressing history, and target-version sacct visibility."
    ]


def _accounting_handoff_cleanup_incomplete(phase: Mapping[str, Any]) -> bool:
    state = _mapping(phase.get("accounting_handoff"))
    status = str(state.get("status") or "").strip()
    return bool(
        status
        in {
            "import-reconciled",
            "imported-paused",
            "target-enabling",
            "target-enabled",
            "verified",
        }
        and not str(state.get("in_place_verified_at") or "").strip()
        and not phase.get("source_cleanup_completed_at")
    )


def _immutable_child_handoff_incomplete(phase: Mapping[str, Any]) -> bool:
    handoff = _mapping(phase.get("immutable_child_handoff"))
    status = str(handoff.get("status") or "").strip()
    return bool(
        str(handoff.get("captured_at") or "").strip() and status not in {"not-required", "complete"}
    )


def _enforce_source_retirement_login_session_policy(
    *,
    checkpoint: Mapping[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    policy: str,
    timeout_seconds: int,
    checkpoint_writer: Callable[[], None] | None = None,
) -> list[str]:
    return _enforce_target_helm_login_session_policy(
        checkpoint=checkpoint,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        policy=policy,
        timeout_seconds=timeout_seconds,
        gate_key="source_retirement_login_session_gate",
        boundary="source-owner retirement",
        mutation_description="orphan ownership handoff",
        checkpoint_writer=checkpoint_writer,
    )


def _enforce_target_helm_login_session_policy(
    *,
    checkpoint: Mapping[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    policy: str,
    timeout_seconds: int,
    gate_key: str,
    boundary: str,
    mutation_description: str = "Helm reconciliation",
    checkpoint_writer: Callable[[], None] | None = None,
) -> list[str]:
    gate = phase.setdefault(gate_key, {})
    if not isinstance(gate, dict):
        raise RuntimeError(f"rolling-compute-migration.{gate_key} must be a mapping.")
    gate.update(
        {
            "status": "checking",
            "attempts": _non_negative_int(gate.get("attempts"), fallback=0) + 1,
            "policy": policy,
            "timeout_seconds": timeout_seconds,
            "checking_at": _utc_now(),
        }
    )
    gate.pop("reason", None)
    if checkpoint_writer is not None:
        checkpoint_writer()
    try:
        pod_names = _login_pod_names(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        gate["pods"] = list(pod_names)
        if checkpoint_writer is not None:
            checkpoint_writer()
        lines = (
            _ensure_active_login_session_hold(
                checkpoint=checkpoint,
                gate=gate,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                pod_names=pod_names,
                checkpoint_writer=checkpoint_writer,
            )
            if (
                policy == EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    str(checkpoint.get("campaign_fingerprint") or "").strip(),
                )
            )
            else None
        )
        if lines is None:
            lines = _wait_for_login_session_policy(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                policy=policy,
                timeout_seconds=timeout_seconds,
                pod_names=pod_names,
            )
    except Exception as exc:
        gate.update(
            {
                "status": "pending",
                "reason": str(exc),
                "checked_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise
    active_hold = bool(
        isinstance(gate.get("active_session_hold"), Mapping)
        and str(_mapping(gate.get("active_session_hold")).get("status") or "") != "released"
    )
    gate.update(
        {
            "status": "deferred" if active_hold else "passed",
            "checked_at": _utc_now(),
            "session_drain": to_plain_data(
                _mapping(phase.get("login_continuity")).get("session_drain")
            ),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        *lines,
        (
            "Login continuity: the wait-active session drain is deferred under an exact "
            f"active-Pod hold before the rolling-compute {boundary} "
            f"{mutation_description} attempt."
            if active_hold
            else "Login continuity: the selected session policy passed immediately before "
            f"the rolling-compute {boundary} {mutation_description} attempt."
        ),
    ]


def _verify_login_session_gate_hold_after_helm(
    *,
    gate: dict[str, Any],
    checkpoint: Mapping[str, Any] | None = None,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str = _SOPERATOR_NAMESPACE,
    checkpoint_writer: Callable[[], None] | None = None,
    boundary_description: str = "Helm reconciliation",
) -> list[str]:
    raw_state = gate.get("active_session_hold")
    if not isinstance(raw_state, dict) or str(raw_state.get("status") or "") == "released":
        return []
    if str(raw_state.get("status") or "").strip() == "release-intent":
        if not _login_session_hold_has_drained_release_intent(raw_state):
            raise SoperatorMigrationPhasePending(
                "active login-session release intent lacks its exact zero-session proof."
            )
        gate["status"] = "release-cleanup-pending"
        gate["verified_after_helm_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            "Login continuity: Helm reconciliation preserved the durable zero-session "
            "release intent; writer-backed cleanup remains pending."
        ]
    lines = _verify_active_login_session_hold(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state=raw_state,
        checkpoint_writer=checkpoint_writer,
        checkpoint=checkpoint,
    )
    gate["status"] = "deferred"
    gate["verified_after_helm_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        *lines,
        f"Login continuity: exact active-Pod hold survived {boundary_description}.",
    ]


def _accounting_handoff_require_exact_slurmcluster_controller_owner(
    resource: Mapping[str, Any],
    *,
    binding: Mapping[str, Any],
    label: str,
) -> None:
    owners = _validated_resource_owner_references(resource, label=label)
    controller_owners = tuple(owner for owner in owners if owner.get("controller") is True)
    expected_name = str(binding.get("name") or "").strip()
    expected_uid = str(binding.get("uid") or "").strip()
    if (
        len(controller_owners) != 1
        or str(controller_owners[0].get("apiVersion") or "").strip()
        not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
        or str(controller_owners[0].get("kind") or "").strip().lower() != "slurmcluster"
        or str(controller_owners[0].get("name") or "").strip() != expected_name
        or str(controller_owners[0].get("uid") or "").strip() != expected_uid
    ):
        raise SoperatorMigrationPhasePending(
            f"{label} is not controlled by the exact checkpointed target SlurmCluster."
        )


def _accounting_handoff_exact_target_login_state(
    *,
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[str, dict[str, Any]]:
    target_uid = str(target_binding.get("uid") or "").strip()
    target_name = str(target_binding.get("name") or "").strip()
    if (
        str(target_binding.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
        or not target_uid
        or not target_name
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target login readiness lacks an exact target binding."
        )
    target_resource, _target_resource_version, _target_accounting_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=target_binding,
            label="target login replica contract",
        )
    )
    expected_login_replicas = _slurm_node_size(target_resource, role="login")
    if not _slurm_node_enabled(target_resource, role="login") or expected_login_replicas <= 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff target login role is disabled or has no configured replicas."
        )
    login = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulsets.apps.kruise.io",
            "login",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    login_metadata = _mapping(login.get("metadata"))
    login_labels = _mapping(login_metadata.get("labels"))
    login_uid = str(login_metadata.get("uid") or "").strip()
    _accounting_handoff_require_exact_slurmcluster_controller_owner(
        login,
        binding=target_binding,
        label=f"Target login workload {_SOPERATOR_NAMESPACE}/login",
    )
    login_ready, login_detail = _pod_workload_ready_state(login, kind="statefulset")
    if (
        str(login_metadata.get("name") or "").strip() != "login"
        or str(login_metadata.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
        or not login_uid
        or login_labels.get("app.kubernetes.io/instance") != target_name
        or login_labels.get("app.kubernetes.io/component") != "login"
        or not login_ready
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff will not retire the source owner until the exact "
            f"target-owned login workload is ready ({login_detail})."
        )

    pod_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    ready_pods: list[dict[str, str]] = []
    for pod in _sequence_of_mappings(pod_payload.get("items")):
        metadata = _mapping(pod.get("metadata"))
        pod_owners = _validated_resource_owner_references(
            pod,
            label=f"Target login Pod {_SOPERATOR_NAMESPACE}/"
            + str(metadata.get("name") or "unknown"),
        )
        pod_controller_owners = tuple(
            owner for owner in pod_owners if owner.get("controller") is True
        )
        exact_login_owner = bool(
            len(pod_controller_owners) == 1
            and str(pod_controller_owners[0].get("apiVersion") or "").strip()
            == "apps.kruise.io/v1beta1"
            and str(pod_controller_owners[0].get("kind") or "").strip() == "StatefulSet"
            and str(pod_controller_owners[0].get("name") or "").strip() == "login"
            and str(pod_controller_owners[0].get("uid") or "").strip() == login_uid
        )
        conditions = {
            str(condition.get("type") or ""): str(condition.get("status") or "")
            for condition in _sequence_of_mappings(_mapping(pod.get("status")).get("conditions"))
        }
        name = str(metadata.get("name") or "").strip()
        uid = str(metadata.get("uid") or "").strip()
        if (
            exact_login_owner
            and name
            and uid
            and str(metadata.get("namespace") or "").strip() == _SOPERATOR_NAMESPACE
            and not metadata.get("deletionTimestamp")
            and str(_mapping(pod.get("status")).get("phase") or "").strip() == "Running"
            and conditions.get("Ready") == "True"
        ):
            ready_pods.append({"name": name, "uid": uid})
    desired = _non_negative_int(_mapping(login.get("spec")).get("replicas"), fallback=0)
    if desired != expected_login_replicas or len(ready_pods) < desired:
        raise SoperatorMigrationPhasePending(
            "accounting handoff exact target login replica contract is not ready "
            f"({len(ready_pods)}/{desired}; configured={expected_login_replicas})."
        )

    services_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "services",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    login_services: list[dict[str, str]] = []
    for service in _sequence_of_mappings(services_payload.get("items")):
        metadata = _mapping(service.get("metadata"))
        name = str(metadata.get("name") or "").strip()
        labels = _mapping(metadata.get("labels"))
        if (
            labels.get("app.kubernetes.io/instance") != target_name
            or labels.get("app.kubernetes.io/component") != "login"
        ):
            continue
        if str(metadata.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE:
            raise SoperatorMigrationPhasePending(
                "accounting handoff found a target login Service in the wrong namespace."
            )
        _accounting_handoff_require_exact_slurmcluster_controller_owner(
            service,
            binding=target_binding,
            label=f"Target login Service {_SOPERATOR_NAMESPACE}/{name}",
        )
        login_services.append(
            _immutable_child_exact_identity(
                service,
                label=f"Target login Service {_SOPERATOR_NAMESPACE}/{name}",
            )
        )
    if not login_services:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found no exact target-owned login Service."
        )

    ready_pod_uids = {pod["uid"] for pod in ready_pods}
    ready_pods_by_uid = {pod["uid"]: pod for pod in ready_pods}
    endpoint_counts: dict[str, int] = {}
    endpoint_pod_uids: set[str] = set()
    for service_binding in login_services:
        service_name = service_binding["name"]
        endpoint_slices = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "endpointslices.discovery.k8s.io",
                "-l",
                f"kubernetes.io/service-name={service_name}",
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        exact_ready_endpoints = 0
        for endpoint_slice in _sequence_of_mappings(endpoint_slices.get("items")):
            slice_owner = _immutable_child_controller_owner(
                endpoint_slice,
                label=f"Target login EndpointSlice for {_SOPERATOR_NAMESPACE}/{service_name}",
            )
            if (
                str(_mapping(slice_owner).get("apiVersion") or "") != "v1"
                or str(_mapping(slice_owner).get("kind") or "") != "Service"
                or str(_mapping(slice_owner).get("name") or "") != service_name
                or str(_mapping(slice_owner).get("uid") or "") != service_binding["uid"]
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff login EndpointSlice is not controlled by its "
                    "exact target-owned Service."
                )
            for endpoint in _sequence_of_mappings(endpoint_slice.get("endpoints")):
                target_ref = _mapping(endpoint.get("targetRef"))
                target_uid = str(target_ref.get("uid") or "").strip()
                if (
                    _mapping(endpoint.get("conditions")).get("ready") is True
                    and str(target_ref.get("kind") or "").strip().lower() == "pod"
                    and target_uid in ready_pod_uids
                    and str(target_ref.get("namespace") or _SOPERATOR_NAMESPACE)
                    == _SOPERATOR_NAMESPACE
                    and str(target_ref.get("name") or "") == ready_pods_by_uid[target_uid]["name"]
                ):
                    exact_ready_endpoints += 1
                    endpoint_pod_uids.add(target_uid)
        if exact_ready_endpoints <= 0:
            raise SoperatorMigrationPhasePending(
                "accounting handoff login Service lacks a ready endpoint bound to an "
                "exact target-owned login Pod."
            )
        endpoint_counts[service_name] = exact_ready_endpoints
    if not endpoint_pod_uids:
        raise SoperatorMigrationPhasePending(
            "accounting handoff found no exact Ready endpoint-bound target login Pod."
        )
    selected_pod = ready_pods_by_uid[sorted(endpoint_pod_uids)[0]]
    selected_live = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pod",
        name=selected_pod["name"],
    )
    _immutable_child_require_live_uid(
        selected_live,
        expected_uid=selected_pod["uid"],
        label="accounting handoff endpoint-selected target login Pod",
    )
    selected_metadata = _mapping(selected_live.get("metadata"))
    selected_labels = _mapping(selected_metadata.get("labels"))
    selected_owner = _immutable_child_controller_owner(
        selected_live,
        label="accounting handoff endpoint-selected target login Pod",
    )
    if (
        str(_mapping(selected_owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
        or str(_mapping(selected_owner).get("kind") or "") != "StatefulSet"
        or str(_mapping(selected_owner).get("name") or "") != "login"
        or str(_mapping(selected_owner).get("uid") or "") != login_uid
        or selected_labels.get("app.kubernetes.io/instance") != target_name
        or selected_labels.get("app.kubernetes.io/component") != "login"
        or selected_metadata.get("deletionTimestamp")
        or not _immutable_child_pod_ready(selected_live)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff endpoint-selected target login Pod changed before use."
        )
    return selected_pod["name"], {
        "target_name": target_name,
        "login_workload_uid": login_uid,
        "selected_pod": selected_pod["name"],
        "selected_pod_uid": selected_pod["uid"],
        "ready_pods": len(ready_pods),
        "desired_pods": desired,
        "configured_pods": expected_login_replicas,
        "services": len(login_services),
        "ready_endpoints": sum(endpoint_counts.values()),
    }


def _accounting_handoff_held_job_retirement_evidence(
    *,
    held_job_operations: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    source_resource_version: str,
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    active_operations = _active_slurm_held_job_operations(held_job_operations)
    evidence: dict[str, Any] = {
        "schema": _ACCOUNTING_HANDOFF_HELD_JOB_RETIREMENT_GATE_SCHEMA,
        "status": "not-required" if not active_operations else "verified",
        "source_uid": str(source_binding.get("uid") or "").strip(),
        "source_resource_version": str(source_resource_version or "").strip(),
        "job_ids": sorted(active_operations),
        "jobs": {},
        "verified_at": _utc_now(),
    }
    if not active_operations:
        return evidence

    target_login_pod, login_evidence = _accounting_handoff_exact_target_login_state(
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    jobs: dict[str, Any] = {}
    for job_id, operation in sorted(active_operations.items()):
        state = str(operation.get("state") or "").strip()
        if state != "held-observed":
            raise SoperatorMigrationPhasePending(
                "final source retirement requires every active cxcli-owned Slurm hold to "
                f"be durably held-observed; job {job_id} is {state or 'unrecorded'}."
            )
        held = _mapping(operation.get("held_observation"))
        try:
            current = _external_upgrade_slurm_job_control_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                job_id=job_id,
                pod_name=target_login_pod,
            )
        except RuntimeError as exc:
            raise SoperatorMigrationPhasePending(
                "final source retirement could not revalidate the exact held Slurm job "
                f"{job_id}: {exc}"
            ) from exc
        if not current.held or not _slurm_observation_matches_payload(current, held):
            raise SoperatorMigrationPhasePending(
                "final source retirement found a missing, substituted, released, or "
                f"otherwise changed cxcli-owned held Slurm job {job_id}."
            )
        jobs[job_id] = {
            "identity_fingerprint": current.identity_fingerprint,
            "record_fingerprint": current.record_fingerprint,
            "job_state": current.job_state,
            "held": current.held,
        }
    evidence["jobs"] = jobs
    evidence["target_login"] = login_evidence
    return evidence


def _accounting_handoff_require_target_control_plane_ready(
    *,
    state: dict[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    target_resource, _target_resource_version, _target_accounting_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=target_binding,
            label="target controller replica contract",
        )
    )
    expected_controller_replicas = _slurm_node_size(target_resource, role="controller")
    if (
        not _slurm_node_enabled(target_resource, role="controller")
        or expected_controller_replicas <= 0
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target controller role is disabled or has no configured replicas."
        )
    controller = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulsets.apps.kruise.io",
            "controller",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    controller_metadata = _mapping(controller.get("metadata"))
    controller_uid = str(controller_metadata.get("uid") or "").strip()
    _accounting_handoff_require_exact_slurmcluster_controller_owner(
        controller,
        binding=target_binding,
        label=f"Target controller workload {_SOPERATOR_NAMESPACE}/controller",
    )
    controller_ready, controller_detail = _pod_workload_ready_state(
        controller,
        kind="statefulset",
    )
    controller_desired = _resource_replicas(controller, default=-1)
    if (
        str(controller_metadata.get("name") or "").strip() != "controller"
        or str(controller_metadata.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
        or not controller_uid
        or controller_desired != expected_controller_replicas
        or not controller_ready
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff will not retire the source owner until the exact "
            f"target controller is ready ({controller_detail})."
        )
    login_pod, login_evidence = _accounting_handoff_exact_target_login_state(
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    ping = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "ping"),
        timeout_seconds=120,
        pod_name=login_pod,
    )
    queue = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("squeue", "-h", "-o", "%A|%T"),
        timeout_seconds=120,
        pod_name=login_pod,
    )
    if ping.returncode != 0 or queue.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "accounting handoff will not retire the source owner until target login "
            "Slurm RPC and job-list access both pass."
        )
    prior_control_plane = _mapping(state.get("target_control_plane_before_source_retirement"))
    prior_login_uid = str(
        _mapping(prior_control_plane.get("login")).get("login_workload_uid") or ""
    ).strip()
    prior_controller_uid = str(prior_control_plane.get("controller_uid") or "").strip()
    if (prior_login_uid and prior_login_uid != login_evidence["login_workload_uid"]) or (
        prior_controller_uid and prior_controller_uid != controller_uid
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target controller/login workload identity changed after "
            "its source-retirement checkpoint."
        )
    state["target_control_plane_before_source_retirement"] = {
        "status": "verified",
        "controller_uid": controller_uid,
        "controller_desired": controller_desired,
        "controller_configured": expected_controller_replicas,
        "login": login_evidence,
        "queued_job_rows": len([line for line in queue.stdout.splitlines() if line.strip()]),
        "verified_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()


def _accounting_handoff_revalidate_imported_paused_before_source_cleanup(
    *,
    phase: dict[str, Any],
    state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if str(state.get("status") or "").strip() != "imported-paused":
        raise SoperatorMigrationPhasePending(
            "accounting handoff source retirement requires a durable imported-paused state."
        )
    if _mapping(state.get("import_journal_cleanup")).get("status") != "cleaned":
        raise SoperatorMigrationPhasePending(
            "accounting handoff source retirement requires durable import-journal cleanup."
        )
    source_gate = _mapping(state.get("source_writer_command_fence"))
    target_gate = _mapping(state.get("target_writer_command_fence"))
    if (
        source_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or target_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source retirement requires both exact SlurmDBD command fences."
        )
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    dump_path = Path(str(_mapping(state.get("dump")).get("path") or ""))
    import_replay = _accounting_handoff_import_replay_binding(
        state=state,
        dump_path=dump_path,
    )
    if _mapping(state.get("imported_dump")) != import_replay:
        raise SoperatorMigrationPhasePending(
            "accounting handoff imported dump generation/SHA binding changed before "
            "source retirement."
        )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    source_resource_name = _accounting_handoff_cluster_name(
        state.get("source_resource_name"),
        label="source SlurmCluster resource",
    )
    target_pod = f"{target_resource_name}-acct-db-0"
    source_pod = f"{source_resource_name}-acct-db-0"
    if (
        _accounting_handoff_import_journal_observation(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
        ).get("status")
        != "absent"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source retirement found a residual import journal."
        )
    target_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        expected_slurmcluster_binding=target_binding,
    )
    if any(
        target_identity.get(key) != _mapping(state.get("target")).get(key)
        for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target MariaDB identity changed before source retirement."
        )
    source_resource = _accounting_handoff_optional_exact_slurmcluster(
        command_runner=command_runner,
        kube_context=kube_context,
        binding=source_binding,
        label="source",
    )
    source_resource_version = ""
    if source_resource is None:
        if not str(phase.get("source_cleanup_started_at") or "").strip():
            raise SoperatorMigrationPhasePending(
                "accounting handoff source SlurmCluster disappeared before cleanup intent."
            )
        _accounting_handoff_wait_target_command_fence_after_source_retirement(
            phase=phase,
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            target_pod=target_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        source_resource_version = str(
            _mapping(state.get("source_cleanup_preconditions")).get("resource_version") or ""
        ).strip()
    else:
        source_document, source_resource_version, source_enabled = source_resource
        if not source_enabled or not _accounting_handoff_writer_command_is_fenced(source_document):
            raise SoperatorMigrationPhasePending(
                "accounting handoff source SlurmCluster drifted from its exact command fence "
                "before retirement."
            )
        _accounting_handoff_wait_writer_command_fences(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            source_pod=source_pod,
            target_pod=target_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    target_history = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=_accounting_handoff_cluster_name(
            state.get("source_cluster_name"),
            label="source",
        ),
    )
    if target_history != _mapping(state.get("source_history")):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target history changed while both writers were fenced; "
            "source retirement is blocked."
        )
    existing_preconditions = _mapping(state.get("source_cleanup_preconditions"))
    cleanup_started = bool(str(phase.get("source_cleanup_started_at") or "").strip())
    if (
        cleanup_started
        and existing_preconditions
        and str(existing_preconditions.get("uid") or "").strip() != source_binding["uid"]
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source cleanup UID precondition drifted after import."
        )
    if source_resource is not None and cleanup_started:
        state["source_cleanup_preconditions"] = {
            "uid": source_binding["uid"],
            "resource_version": source_resource_version,
        }
    elif source_resource is None and not source_resource_version:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot adopt an absent source without its exact prior "
            "resourceVersion cleanup precondition."
        )
    state.update(
        {
            "target_history": target_history,
            "imported_paused_revalidated_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Accounting history import revalidated under both command fences; the exact "
        "source SlurmCluster is ready for UID/resourceVersion-preconditioned retirement."
    ]


def _accounting_handoff_revalidate_source_cleanup_boundary(
    *,
    phase: dict[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> tuple[str | None, list[str]]:
    state = _accounting_handoff_state(phase)
    status = str(state.get("status") or "").strip()
    if status == "skipped" or (
        status == "verified" and str(state.get("in_place_verified_at") or "").strip()
    ):
        return None, []
    if status == "source-dumped":
        source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
        target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
        source_retired = _accounting_handoff_source_retirement_checkpoint_is_exact(
            phase=phase,
            state=state,
            source_binding=source_binding,
        )
        deferred = _mapping(state.get("import_deferred_until_source_retirement"))
        dump_path = Path(str(_mapping(state.get("dump")).get("path") or ""))
        expected_deferred = {
            "schema": _ACCOUNTING_HANDOFF_DEFERRED_IMPORT_SCHEMA,
            "status": "ready",
            "source": source_binding,
            "target": target_binding,
            "target_database_identity": {
                key: _mapping(state.get("target")).get(key)
                for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
            },
            "import_replay": _accounting_handoff_import_replay_binding(
                state=state,
                dump_path=dump_path,
            ),
        }
        if any(deferred.get(key) != value for key, value in expected_deferred.items()):
            raise SoperatorMigrationPhasePending(
                "accounting handoff source cleanup lacks the exact deferred-import binding."
            )
        manager_gap: dict[str, Any] | None = None
        if source_retired:
            target_resource_name = _accounting_handoff_cluster_name(
                state.get("target_resource_name"),
                label="target SlurmCluster resource",
            )
            manager_gap = _accounting_handoff_manager_paused_selector_gap(
                phase=phase,
                state=state,
                source_binding=source_binding,
                target_binding=target_binding,
                target_pod=f"{target_resource_name}-acct-db-0",
                command_runner=command_runner,
                kube_context=kube_context,
            )
        if manager_gap is not None:
            source_deployment_uid = str(
                _mapping(state.get("source_accounting_deployment")).get("uid") or ""
            ).strip()
            writer_gate = _mapping(state.get("target_writer_gate"))
            retired_fence = _mapping(state.get("target_command_fence_after_source_retirement"))
            expected_source_selector = {
                "app.kubernetes.io/component": "accounting",
                "app.kubernetes.io/instance": source_binding["name"],
                "app.kubernetes.io/name": "slurmcluster",
            }
            if (
                str(deferred.get("deployment_uid") or "").strip() != source_deployment_uid
                or writer_gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
                or writer_gate.get("status") != "disabled"
                or _mapping(writer_gate.get("binding")) != target_binding
                or str(writer_gate.get("deployment_uid") or "").strip() != source_deployment_uid
                or _mapping(writer_gate.get("deployment_selector")) != expected_source_selector
                or retired_fence.get("status") != "verified"
                or str(retired_fence.get("deployment_uid") or "").strip() != source_deployment_uid
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff manager-paused selector gap lacks the exact "
                    "pre-delete disabled-writer Deployment binding."
                )
        else:
            deployment = _accounting_handoff_deployment_state(
                command_runner=command_runner,
                kube_context=kube_context,
            )
            deployment_owner_matches = (
                str(deployment.get("owner_uid") or "").strip() == source_binding["uid"]
            )
            if not deployment_owner_matches and not str(deployment.get("owner_uid") or "").strip():
                optional_source_for_owner = _accounting_handoff_optional_exact_slurmcluster(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    binding=source_binding,
                    label="deferred-import source cleanup owner",
                )
                if source_retired:
                    if optional_source_for_owner is not None:
                        raise SoperatorMigrationPhasePending(
                            "accounting handoff retired source SlurmCluster reappeared at the "
                            "deferred-import cleanup boundary."
                        )
                    source_resource_for_owner: Mapping[str, Any] = {}
                else:
                    if optional_source_for_owner is None:
                        raise SoperatorMigrationPhasePending(
                            "accounting handoff deferred-import source cleanup owner "
                            "SlurmCluster no longer matches its exact namespace/name/UID "
                            "binding."
                        )
                    source_resource_for_owner = optional_source_for_owner[0]
                deployment_owner_matches = _accounting_handoff_deployment_owner_matches_retirement(
                    state=state,
                    source_binding=source_binding,
                    target_binding=target_binding,
                    source_resource=source_resource_for_owner,
                    deployment=deployment,
                    phase=phase,
                )
            if (
                str(deployment.get("uid") or "") != str(deferred.get("deployment_uid") or "")
                or not deployment_owner_matches
                or not _accounting_handoff_deployment_writer_is_fenced(deployment)
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff source-owned shared Deployment changed before retirement."
                )
        sealed_line = _accounting_handoff_reuse_sealed_source_dump(
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            phase=phase,
        )
        if sealed_line is None:
            raise SoperatorMigrationPhasePending(
                "accounting handoff source cleanup lacks its sealed source dump."
            )
        if source_retired:
            cleanup_preconditions = _mapping(state.get("source_cleanup_preconditions"))
            source_resource_version = str(
                cleanup_preconditions.get("resource_version") or ""
            ).strip()
            if (
                str(cleanup_preconditions.get("uid") or "").strip() != source_binding["uid"]
                or not source_resource_version
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff retired source cleanup lacks its exact prior "
                    "UID/resourceVersion precondition."
                )
            if manager_gap is None:
                target_resource_name = _accounting_handoff_cluster_name(
                    state.get("target_resource_name"),
                    label="target SlurmCluster resource",
                )
                _accounting_handoff_wait_target_command_fence_after_source_retirement(
                    phase=phase,
                    state=state,
                    source_binding=source_binding,
                    target_binding=target_binding,
                    target_pod=f"{target_resource_name}-acct-db-0",
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            lines = [
                sealed_line,
                "Accounting history handoff revalidated the sealed dump, exact retired "
                "source UID, and target-only command fence before immutable-child restore.",
            ]
        else:
            source_resource, source_resource_version, source_enabled = (
                _accounting_handoff_exact_slurmcluster(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    binding=source_binding,
                    label="deferred-import source cleanup",
                )
            )
            if not source_enabled or not _accounting_handoff_writer_command_is_fenced(
                source_resource
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff source command fence drifted before deferred import."
                )
            state["source_cleanup_preconditions"] = {
                "uid": source_binding["uid"],
                "resource_version": source_resource_version,
            }
            lines = [
                sealed_line,
                "Accounting history handoff revalidated the sealed dump and exact "
                "source-owned command fence for UID/resourceVersion-preconditioned retirement.",
            ]
        state["deferred_import_revalidated_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif status == "imported-paused":
        lines = _accounting_handoff_revalidate_imported_paused_before_source_cleanup(
            phase=phase,
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    elif status == "verified":
        lines = _accounting_handoff_revalidate_verified_before_cleanup(
            phase=phase,
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    elif status == "target-enabled" and _accounting_handoff_waits_for_target_config_restore(phase):
        source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
        if not _accounting_handoff_source_retirement_checkpoint_is_exact(
            phase=phase,
            state=state,
            source_binding=source_binding,
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff cannot adopt target-enabled cleanup before exact "
                "source-owner retirement is durable."
            )
        if (
            _accounting_handoff_optional_exact_slurmcluster(
                command_runner=command_runner,
                kube_context=kube_context,
                binding=source_binding,
                label="retired source cleanup resume",
            )
            is not None
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff retired source reappeared before target config restore."
            )
        lines = _accounting_handoff_restore_target_writer_after_source_retirement(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        lines.append(
            "Accounting source cleanup remains bound to the exact retired UID while "
            "target registration verification waits for active-slot Slurm config."
        )
    else:
        raise SoperatorMigrationPhasePending(
            "accounting handoff source cleanup cannot proceed before history handoff "
            "verification is durable."
        )
    cleanup_preconditions = _mapping(state.get("source_cleanup_preconditions"))
    expected_source_uid = _source_cleanup_binding(
        source_report,
        target_ref=target_ref,
    )["uid"]
    if str(cleanup_preconditions.get("uid") or "").strip() != expected_source_uid:
        raise SoperatorMigrationPhasePending(
            "accounting handoff final cleanup precondition is not bound to the exact "
            "source SlurmCluster UID."
        )
    return str(cleanup_preconditions.get("resource_version") or "").strip(), lines


def _accounting_handoff_checkpoint_final_source_delete_preconditions(
    *,
    phase: dict[str, Any],
    values: Mapping[str, Any],
    held_job_operations: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> str:
    state = _accounting_handoff_state(phase)
    handoff_binding = _mapping(phase.get("slurmcluster_handoff_binding"))

    def _exact_handoff_binding(label: str) -> dict[str, str]:
        raw = _mapping(handoff_binding.get(label))
        binding = {key: str(raw.get(key) or "").strip() for key in ("namespace", "name", "uid")}
        if binding["namespace"] != _SOPERATOR_NAMESPACE or not all(binding.values()):
            raise SoperatorMigrationPhasePending(
                "final source retirement requires exact source/target "
                f"namespace/name/UID bindings; the {label} binding is incomplete."
            )
        return binding

    source_binding = _exact_handoff_binding("source")
    target_binding = _exact_handoff_binding("target")
    status = str(state.get("status") or "").strip()
    command_fence_schema = _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
    source_command_gate = _mapping(state.get("source_writer_command_fence"))
    target_command_gate = _mapping(state.get("target_writer_command_fence"))
    command_fenced_retirement = bool(
        source_command_gate.get("schema") == command_fence_schema
        and target_command_gate.get("schema") == command_fence_schema
    )
    if command_fenced_retirement:
        if (
            _accounting_handoff_source_binding(phase=phase, state=state) != source_binding
            or _accounting_handoff_target_binding(phase=phase, state=state) != target_binding
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff command fences disagree with the exact source/target "
                "retirement binding."
            )
    elif (
        source_command_gate.get("schema") == command_fence_schema
        or target_command_gate.get("schema") == command_fence_schema
        or status == "imported-paused"
    ):
        raise SoperatorMigrationPhasePending(
            "final source retirement found an incomplete dual SlurmDBD command fence."
        )
    elif status != "skipped" and not (
        status == "verified" and str(state.get("in_place_verified_at") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "final source retirement lacks a supported accounting handoff boundary."
        )
    source_resource = _accounting_handoff_optional_exact_slurmcluster(
        command_runner=command_runner,
        kube_context=kube_context,
        binding=source_binding,
        label="source delete boundary",
    )
    existing = dict(_mapping(state.get("source_cleanup_preconditions")))
    if source_resource is None:
        if (
            not str(phase.get("source_cleanup_started_at") or "").strip()
            or str(existing.get("uid") or "").strip() != source_binding["uid"]
            or not str(existing.get("resource_version") or "").strip()
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff cannot adopt an absent source at the final delete boundary."
            )
        active_held_job_ids = sorted(_active_slurm_held_job_operations(held_job_operations))
        held_job_gate = _mapping(state.get("held_jobs_before_source_retirement"))
        if active_held_job_ids and (
            held_job_gate.get("schema") != _ACCOUNTING_HANDOFF_HELD_JOB_RETIREMENT_GATE_SCHEMA
            or held_job_gate.get("status") != "verified"
            or str(held_job_gate.get("source_uid") or "").strip() != source_binding["uid"]
            or str(held_job_gate.get("source_resource_version") or "").strip()
            != str(existing.get("resource_version") or "").strip()
            or held_job_gate.get("job_ids") != active_held_job_ids
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff cannot adopt an absent source without its durable exact "
                "held-job retirement evidence."
            )
        return str(existing["resource_version"])
    source_document, resource_version, source_enabled = source_resource
    target_document, _target_resource_version, target_enabled = (
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=target_binding,
            label="target delete boundary",
        )
    )
    if command_fenced_retirement and (
        not source_enabled
        or not target_enabled
        or not _accounting_handoff_writer_command_is_fenced(source_document)
        or not _accounting_handoff_writer_command_is_fenced(target_document)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff source/target command fence drifted at the final delete boundary."
        )
    replacement = {"uid": source_binding["uid"], "resource_version": resource_version}
    held_job_gate = _accounting_handoff_held_job_retirement_evidence(
        held_job_operations=held_job_operations,
        source_binding=source_binding,
        source_resource_version=resource_version,
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if existing and existing != replacement:
        history = state.setdefault("source_cleanup_precondition_history", [])
        if not isinstance(history, list):
            raise RuntimeError(
                "accounting handoff source_cleanup_precondition_history must be a list."
            )
        history.append({**existing, "superseded_at": _utc_now()})
    state["source_cleanup_preconditions"] = replacement
    state["source_cleanup_preconditions_finalized_at"] = _utc_now()
    state["held_jobs_before_source_retirement"] = held_job_gate
    if checkpoint_writer is not None:
        checkpoint_writer()
    return resource_version


def _accounting_handoff_restore_target_writer_after_source_retirement(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Restore only the target SlurmDBD writer; controller checks happen later."""

    state = _accounting_handoff_state(phase)
    status = str(state.get("status") or "").strip()
    if status in {"skipped", "verified"}:
        return []
    if status not in {"imported-paused", "target-enabling", "target-enabled"}:
        raise SoperatorMigrationPhasePending(
            "accounting handoff cannot restore the target writer before the final "
            "source import is durably paused."
        )
    if not str(phase.get("source_accounting_owner_retired_at") or "").strip():
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer restore requires durable source-owner retirement."
        )
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    target_pod = f"{target_resource_name}-acct-db-0"
    if status != "target-enabled":
        _accounting_handoff_wait_target_command_fence_after_source_retirement(
            phase=phase,
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            target_pod=target_pod,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    dump_path = Path(str(_mapping(state.get("dump")).get("path") or ""))
    import_replay = _accounting_handoff_import_replay_binding(
        state=state,
        dump_path=dump_path,
    )
    if _mapping(state.get("imported_dump")) != import_replay:
        raise SoperatorMigrationPhasePending(
            "accounting handoff imported dump generation/SHA binding changed before "
            "target writer restore; SQL was not replayed."
        )
    if status == "imported-paused":
        _accounting_handoff_assert_target_writer_disabled(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        source_cluster_name = _accounting_handoff_cluster_name(
            state.get("source_cluster_name"),
            label="source",
        )
        observed_history = _accounting_handoff_history_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            source_cluster_name=source_cluster_name,
        )
        if observed_history != _mapping(state.get("source_history")):
            raise SoperatorMigrationPhasePending(
                "accounting handoff imported-paused evidence changed before the target "
                "writer restore boundary; SQL was not replayed."
            )
        state["status"] = "target-enabling"
        state["target_enable_started_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        status = "target-enabling"
    if status == "target-enabling":
        _accounting_handoff_enable_target_writer(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        state["status"] = "target-enabled"
        state["target_writer_restored_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    _accounting_handoff_assert_target_writer_ready(
        state=state,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    return [
        "Accounting handoff restored the exact target SlurmDBD writer after durable "
        "source retirement; controller and sacct verification remain gated on the "
        "immutable-child handoff."
    ]


def _complete_accounting_handoff_import(
    *,
    phase: dict[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None = None,
) -> list[str]:
    state = _accounting_handoff_state(phase)
    status = str(state.get("status", "") or "")
    if status == "skipped":
        return []
    if status == "verified":
        if str(state.get("in_place_verified_at") or "").strip():
            return _accounting_handoff_revalidate_in_place_verified(
                state=state,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        return _accounting_handoff_revalidate_verified_before_cleanup(
            phase=phase,
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    if status not in {
        "source-snapshot",
        "source-dumped",
        "importing",
        "import-reconciled",
        "imported-paused",
        "target-enabling",
        "target-enabled",
        "in-place-pending",
    }:
        raise SoperatorMigrationPhasePending(
            "accounting handoff lacks a checkpointed final source dump before target import."
        )
    source_cluster_name = _accounting_handoff_cluster_name(
        state.get("source_cluster_name"),
        label="source",
    )
    target_cluster_name = _accounting_handoff_cluster_name(
        state.get("target_cluster_name"),
        label="target",
    )
    target_resource_name = _accounting_handoff_cluster_name(
        state.get("target_resource_name"),
        label="target SlurmCluster resource",
    )
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    pre_import_lines: list[str] = []
    if status != "in-place-pending":
        _accounting_handoff_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=target_binding,
            label="target",
        )
        if (
            status in {"source-snapshot", "source-dumped"}
            and not str(phase.get("source_accounting_owner_retired_at") or "").strip()
        ):
            source_binding = {
                key: str(
                    _mapping(_mapping(phase.get("slurmcluster_handoff_binding")).get("source")).get(
                        key
                    )
                    or _mapping(_mapping(state.get("source_writer_gate")).get("binding")).get(key)
                    or ""
                ).strip()
                for key in ("namespace", "name", "uid")
            }
            if not all(source_binding.values()):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff cannot finalize the source dump without the exact "
                    "source SlurmCluster binding."
                )
            pre_import_lines.append(
                _accounting_handoff_finalize_command_fenced_source_dump(
                    state=state,
                    source_binding=source_binding,
                    target_binding=target_binding,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            status = "source-dumped"
    target_pod = f"{target_resource_name}-acct-db-0"
    _accounting_handoff_wait_for_mariadb_pod(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
    )
    target_identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        expected_slurmcluster_binding=target_binding,
    )
    source_evidence = dict(_mapping(state.get("source_history")))

    if status == "in-place-pending":
        source_identity = _mapping(state.get("source"))
        if any(
            target_identity.get(key) != source_identity.get(key)
            for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff found one source/target Slurm DB identity, but chart "
                "apply did not preserve the exact MariaDB Pod/PVC binding; destructive "
                "self-import is disabled."
            )
        restored_evidence = _accounting_handoff_history_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            source_cluster_name=source_cluster_name,
        )
        if restored_evidence != source_evidence:
            raise SoperatorMigrationPhasePending(
                "accounting handoff in-place MariaDB history changed across chart apply."
            )
        registered = _accounting_handoff_ensure_slurm_registrations(
            command_runner=command_runner,
            kube_context=kube_context,
            source_cluster_name=source_cluster_name,
            target_cluster_name=target_cluster_name,
        )
        sacct_evidence = _accounting_handoff_sacct_history_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            source_cluster_name=source_cluster_name,
            source_history=source_evidence,
        )
        state.update(
            {
                "status": "verified",
                "target": target_identity,
                "target_history": restored_evidence,
                "registered_clusters": list(registered),
                "sacct_verification": sacct_evidence,
                "in_place_verified_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            "Accounting history handoff verified in-place MariaDB Pod/PVC continuity "
            "and target-version sacct visibility."
        ]

    expected_target = _mapping(state.get("target"))
    if status != "source-dumped" and any(
        target_identity.get(key) != expected_target.get(key)
        for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target MariaDB Pod/PVC binding changed after import "
            "intent; the immutable dump was not replayed."
        )

    if status == "source-dumped":
        source_evidence = dict(_mapping(state.get("source_history")))

    dump_path = Path(str(_mapping(state.get("dump")).get("path", "") or ""))
    import_replay = _accounting_handoff_import_replay_binding(
        state=state,
        dump_path=dump_path,
    )
    target_cluster_schema: dict[str, Any] | None = None
    if status == "source-dumped":
        source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
        deferred_line = _accounting_handoff_defer_import_until_source_retirement(
            phase=phase,
            state=state,
            source_binding=source_binding,
            target_binding=target_binding,
            target_identity=target_identity,
            import_replay=import_replay,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        if deferred_line is not None:
            return [*pre_import_lines, deferred_line]
        if str(phase.get("source_accounting_owner_retired_at") or "").strip():
            deferred = _mapping(state.get("import_deferred_until_source_retirement"))
            if (
                deferred.get("schema") != _ACCOUNTING_HANDOFF_DEFERRED_IMPORT_SCHEMA
                or deferred.get("status") != "ready"
                or _mapping(deferred.get("source")) != source_binding
                or _mapping(deferred.get("target")) != target_binding
                or _mapping(deferred.get("import_replay")) != import_replay
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff retired the source owner without the exact durable "
                    "deferred-import binding."
                )
            _accounting_handoff_wait_target_command_fence_after_source_retirement(
                phase=phase,
                state=state,
                source_binding=source_binding,
                target_binding=target_binding,
                target_pod=target_pod,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        target_writer_gate = _accounting_handoff_pause_target_writer(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        if str(phase.get("source_accounting_owner_retired_at") or "").strip():
            _accounting_handoff_transition_ownerless_deployment_selector(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        target_identity = _accounting_handoff_revalidate_target_mariadb_identity(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            expected=target_identity,
            target_binding=target_binding,
        )
        raw_source_tables = state.get("source_database_tables")
        if not isinstance(raw_source_tables, Sequence) or isinstance(
            raw_source_tables, (str, bytes, bytearray)
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff final source dump lacks its database table inventory."
            )
        target_cluster_schema = _accounting_handoff_ensure_target_schema_bootstrap(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_pod=target_pod,
            target_identity=target_identity,
            dump_path=dump_path,
            source_cluster_name=source_cluster_name,
            target_cluster_name=target_cluster_name,
            checkpoint_writer=checkpoint_writer,
        )
        target_schema_path = dump_path.parent / _ACCOUNTING_HANDOFF_TARGET_SCHEMA_FILENAME
        target_schema_metadata = _accounting_handoff_capture_target_global_schema(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            source_tables=tuple(str(item) for item in raw_source_tables),
            source_cluster_name=source_cluster_name,
            target_cluster_name=target_cluster_name,
            path=target_schema_path,
        )
        state.update(
            {
                "status": "importing",
                "target": target_identity,
                "target_accounting_deployment": {
                    "uid": str(target_writer_gate.get("deployment_uid") or ""),
                    "replicas": _non_negative_int(
                        target_writer_gate.get("deployment_replicas"), fallback=0
                    ),
                },
                "target_global_schema": target_schema_metadata,
                "import_replay": import_replay,
                "target_pause_started_at": _utc_now(),
                "import_started_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        status = "importing"

    if status == "importing":
        _accounting_handoff_pause_target_writer(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        if str(phase.get("source_accounting_owner_retired_at") or "").strip():
            _accounting_handoff_transition_ownerless_deployment_selector(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        target_identity = _accounting_handoff_revalidate_target_mariadb_identity(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            expected=_mapping(state.get("target")),
            target_binding=target_binding,
        )
        target_global_schema = _accounting_handoff_load_target_global_schema(
            state=state,
            source_cluster_name=source_cluster_name,
        )
        _accounting_handoff_adopt_legacy_no_stdin_import(
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
            target_pod=target_pod,
            source_cluster_name=source_cluster_name,
            target_cluster_name=target_cluster_name,
            checkpoint_writer=checkpoint_writer,
        )
        if target_cluster_schema is None:
            target_cluster_schema = _accounting_handoff_ensure_target_schema_bootstrap(
                state=state,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_pod=target_pod,
                target_identity=target_identity,
                dump_path=dump_path,
                source_cluster_name=source_cluster_name,
                target_cluster_name=target_cluster_name,
                checkpoint_writer=checkpoint_writer,
            )
        _accounting_handoff_pause_target_writer(
            state=state,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        target_identity = _accounting_handoff_revalidate_target_mariadb_identity(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            expected=_mapping(state.get("target")),
            target_binding=target_binding,
        )
        execution_binding = _accounting_handoff_import_execution_binding(
            state=state,
            import_replay=import_replay,
            target_identity=target_identity,
        )
        execution = state.setdefault("import_execution", {})
        if not isinstance(execution, dict):
            raise RuntimeError("accounting handoff import_execution must be a mapping.")
        if not execution:
            journal = _accounting_handoff_import_journal_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
            )
            if journal.get("status") != "absent":
                raise SoperatorMigrationPhasePending(
                    "accounting handoff found an import journal before durable execution intent."
                )
            execution.update(
                {
                    "schema": _ACCOUNTING_HANDOFF_IMPORT_EXECUTION_SCHEMA,
                    "status": "prepared",
                    "operation_id": uuid4().hex,
                    "binding": execution_binding,
                    "prepared_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
        if (
            execution.get("schema") != _ACCOUNTING_HANDOFF_IMPORT_EXECUTION_SCHEMA
            or execution.get("binding") != execution_binding
            or not re.fullmatch(r"[0-9a-f]{32}", str(execution.get("operation_id") or ""))
            or execution.get("status") not in {"prepared", "running", "retryable", "applied"}
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff import execution checkpoint is incomplete or drifted."
            )
        execution_status = str(execution["status"])
        expected_marker = _accounting_handoff_expected_import_marker(
            execution=execution,
            import_replay=import_replay,
        )
        expected_source_tables = set(_mapping(target_cluster_schema.get("definitions")))
        completion = None
        if execution_status in {"running", "retryable"}:
            completion = _accounting_handoff_import_completion_evidence(
                command_runner=command_runner,
                kube_context=kube_context,
                target_pod=target_pod,
                expected_marker=expected_marker,
                expected_source_tables=expected_source_tables,
                source_cluster_name=source_cluster_name,
                source_evidence=source_evidence,
            )
        result: SoperatorMigrationCommandResult | None = None
        if execution_status in {"prepared", "running", "retryable"} and completion is None:
            result = _accounting_handoff_dispatch_import_reset(
                state=state,
                execution=execution,
                command_runner=command_runner,
                kube_context=kube_context,
                target_pod=target_pod,
                dump_path=dump_path,
                import_replay=import_replay,
                checkpoint_writer=checkpoint_writer,
            )
            completion = _accounting_handoff_import_completion_evidence(
                command_runner=command_runner,
                kube_context=kube_context,
                target_pod=target_pod,
                expected_marker=expected_marker,
                expected_source_tables=expected_source_tables,
                source_cluster_name=source_cluster_name,
                source_evidence=source_evidence,
            )
        if completion is not None and execution_status != "applied":
            execution.update(
                {
                    "status": "applied",
                    "completion_marker": completion["marker"],
                    "history": completion["history"],
                    "remote_exit_code": result.returncode if result is not None else None,
                    "applied_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            execution_status = "applied"
        elif execution_status != "applied":
            execution.update(
                {
                    "status": "retryable",
                    "last_incomplete_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            exit_detail = (
                f"; SQL stdout/stderr was redacted (exit {result.returncode})"
                if result is not None and result.returncode != 0
                else ""
            )
            if (
                _non_negative_int(state.get("import_attempts"), fallback=0)
                >= _ACCOUNTING_HANDOFF_IMPORT_MAX_ATTEMPTS
            ):
                raise SoperatorMigrationPhasePending(
                    "accounting handoff exhausted its bounded exact-reset import attempts "
                    "without a durable completion marker; both writers remain disabled"
                    f"{exit_detail}."
                )
            raise SoperatorMigrationPhasePending(
                "accounting handoff exact-reset import did not produce its durable database "
                "completion marker; the target writer remains disabled and a later approved "
                "execute may retry the same immutable reset within the bounded attempt limit"
                f"{exit_detail}."
            )
        if execution_status != "applied":  # pragma: no cover - guarded above
            raise SoperatorMigrationPhasePending(
                "accounting handoff import did not reach its durable applied boundary."
            )
        marker = _accounting_handoff_import_journal_marker(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
        )
        if marker != expected_marker or execution.get("completion_marker") != marker:
            raise SoperatorMigrationPhasePending(
                "accounting handoff durable import marker changed before schema reconciliation."
            )
        schema_reconciliation = _accounting_handoff_reconcile_source_schema_snapshot(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            source_cluster_name=source_cluster_name,
            target_schema=target_cluster_schema,
        )
        if "schema_reconciliation" not in state:
            state["schema_reconciliation"] = schema_reconciliation
            state["source_schema_reconciled_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
        global_schema_reconciliation = _accounting_handoff_reconcile_global_schema(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            definitions=target_global_schema,
        )
        if "global_schema_reconciliation" not in state:
            state["global_schema_reconciliation"] = global_schema_reconciliation
            state["global_schema_reconciled_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
        target_evidence = _accounting_handoff_history_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            source_cluster_name=source_cluster_name,
        )
        if target_evidence != source_evidence:
            state["target_history"] = target_evidence
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise SoperatorMigrationPhasePending(
                "accounting handoff schema-reconciled import no longer matches exact "
                "source-history evidence; the target writer remains disabled."
            )
        state.update(
            {
                "status": "import-reconciled",
                "target_history": target_evidence,
                "imported_dump": import_replay,
                "import_completed_at": _utc_now(),
                "import_reconciled_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        status = "import-reconciled"

    if status == "import-reconciled":
        _accounting_handoff_drop_import_journal(
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=target_pod,
            checkpoint_writer=checkpoint_writer,
        )
        if _mapping(state.get("import_journal_cleanup")).get("status") != "cleaned":
            raise SoperatorMigrationPhasePending(
                "accounting handoff import journal cleanup did not reach its durable "
                "absence boundary."
            )
        if (
            _accounting_handoff_import_journal_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
            ).get("status")
            != "absent"
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff import journal still exists after durable cleanup."
            )
        state.update(
            {
                "status": "imported-paused",
                "imported_paused_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        status = "imported-paused"

    if status == "imported-paused":
        cleanup = _mapping(state.get("import_journal_cleanup"))
        if cleanup.get("status") != "cleaned":
            raise SoperatorMigrationPhasePending(
                "accounting handoff imported-paused checkpoint lacks durable import "
                "journal cleanup proof."
            )
        if (
            _accounting_handoff_import_journal_observation(
                command_runner=command_runner,
                kube_context=kube_context,
                pod_name=target_pod,
            ).get("status")
            != "absent"
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff import journal reappeared after imported-paused."
            )
        command_fenced = (
            _mapping(state.get("target_writer_command_fence")).get("schema")
            == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        )
        if command_fenced and not phase.get("source_accounting_owner_retired_at"):
            return [
                *pre_import_lines,
                *_accounting_handoff_revalidate_imported_paused_before_source_cleanup(
                    phase=phase,
                    state=state,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                ),
            ]
        _accounting_handoff_restore_target_writer_after_source_retirement(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        status = str(state.get("status") or "").strip()

    if status == "target-enabling":
        _accounting_handoff_restore_target_writer_after_source_retirement(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        status = str(state.get("status") or "").strip()

    if status != "target-enabled":  # pragma: no cover - guarded by status transitions
        raise SoperatorMigrationPhasePending(
            "accounting handoff did not reach its durable target-enable boundary."
        )
    if _mapping(state.get("target_writer_command_fence")).get(
        "schema"
    ) == _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA and not phase.get(
        "source_accounting_owner_retired_at"
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff will not restore the target writer before the exact "
            "source accounting owner is durably retired."
        )
    if _mapping(state.get("imported_dump")) != import_replay:
        raise SoperatorMigrationPhasePending(
            "accounting handoff imported dump generation/SHA binding changed before "
            "target writer enable; SQL was not replayed."
        )
    _accounting_handoff_assert_target_writer_ready(
        state=state,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    registered = _accounting_handoff_ensure_slurm_registrations(
        command_runner=command_runner,
        kube_context=kube_context,
        source_cluster_name=source_cluster_name,
        target_cluster_name=target_cluster_name,
    )
    sacct_evidence = _accounting_handoff_sacct_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        source_cluster_name=source_cluster_name,
        source_history=source_evidence,
    )
    restored_evidence = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=target_pod,
        source_cluster_name=source_cluster_name,
    )
    if not _accounting_handoff_history_is_non_regressing(
        source_evidence,
        restored_evidence,
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff history regressed after the exact target writer resumed; "
            "SQL will not be replayed and source resources were not retired."
        )
    state.update(
        {
            "status": "verified",
            "target_history": restored_evidence,
            "registered_clusters": list(registered),
            "sacct_verification": sacct_evidence,
            "target_accounting_restored_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        *pre_import_lines,
        "Accounting history handoff imported and schema-reconciled the final source "
        "slurm_acct_db, then verified both registrations and target-version sacct "
        f"visibility ({restored_evidence['jobs']} jobs, {restored_evidence['steps']} steps).",
    ]


def _accounting_handoff_complete_after_source_retirement(
    *,
    phase: dict[str, Any],
    values: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None = None,
) -> list[str]:
    del values
    _accounting_handoff_checkpoint_source_owner_retired(
        phase=phase,
        checkpoint_writer=checkpoint_writer,
    )
    lines: list[str] = []
    if str(_accounting_handoff_state(phase).get("status") or "").strip() == "source-dumped":
        lines.extend(
            _complete_accounting_handoff_import(
                phase=phase,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
    lines.extend(
        _accounting_handoff_restore_target_writer_after_source_retirement(
            phase=phase,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    return lines


def _accounting_handoff_checkpoint_source_owner_retired(
    *,
    phase: dict[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if not str(phase.get("source_accounting_owner_retired_at") or "").strip():
        phase["source_accounting_owner_retired_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()


def _rolling_compute_skip_target_helm_for_accounting_handoff(
    phase: Mapping[str, Any],
) -> bool:
    accounting_handoff = _mapping(phase.get("accounting_handoff"))
    target_writer_gate_started = bool(
        _mapping(accounting_handoff.get("target_writer_gate"))
        or _mapping(accounting_handoff.get("target_writer_command_fence"))
    )
    target_handoff_values_revision = _non_negative_int(
        phase.get("target_handoff_values_revision"), fallback=0
    )
    handoff_binding = _mapping(phase.get("slurmcluster_handoff_binding"))
    target_binding = _mapping(handoff_binding.get("target"))
    proof = _mapping(phase.get("target_handoff_values_proof"))
    proven_target_helm = bool(
        target_handoff_values_revision == _ROLLING_COMPUTE_VALUES_REVISION
        and proof.get("schema") == _TARGET_HELM_APPLY_PROOF_SCHEMA
        and str(proof.get("status") or "").strip() == "verified"
        and _mapping(proof.get("target")) == target_binding
        and all(str(target_binding.get(key) or "").strip() for key in ("namespace", "name", "uid"))
    )
    if (
        target_writer_gate_started
        and (target_handoff_values_revision != _ROLLING_COMPUTE_VALUES_REVISION)
        and not _accounting_handoff_target_helm_replay_is_safe(phase)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff target writer pause already started without the "
            "current successful target Helm values revision; cxcli will not reapply "
            "Helm and re-enable the writer implicitly."
        )
    return proven_target_helm


def _accounting_handoff_target_helm_replay_is_safe(phase: Mapping[str, Any]) -> bool:
    """Allow a new values revision only after the accounting handoff is fully restored."""

    state = _mapping(phase.get("accounting_handoff"))
    target_binding = _mapping(_mapping(phase.get("slurmcluster_handoff_binding")).get("target"))
    normalized_target = {
        key: str(target_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    if not all(normalized_target.values()):
        return False
    writer_gate = _mapping(state.get("target_writer_gate"))
    writer_fence = _mapping(state.get("target_writer_command_fence"))
    gate_binding = {
        key: str(_mapping(writer_gate.get("binding")).get(key) or "").strip()
        for key in normalized_target
    }
    fence_binding = {
        key: str(_mapping(writer_fence.get("binding")).get(key) or "").strip()
        for key in normalized_target
    }
    return bool(
        str(state.get("status") or "").strip() == "verified"
        and phase.get("live_source_slurmcluster_present") is False
        and str(phase.get("source_accounting_owner_retired_at") or "").strip()
        and _mapping(phase.get("source_cleanup_binding"))
        and str(state.get("target_accounting_restored_at") or "").strip()
        and str(writer_gate.get("status") or "").strip() == "enabled"
        and str(writer_gate.get("enabled_at") or "").strip()
        and str(writer_fence.get("status") or "").strip() == "restored"
        and str(writer_fence.get("restored_at") or "").strip()
        and gate_binding == normalized_target
        and fence_binding == normalized_target
    )


def _rolling_compute_target_helm_ordering_mode(
    phase: Mapping[str, Any],
    *,
    skip_target_helm: bool,
) -> str:
    if skip_target_helm:
        return "skip"
    if _accounting_handoff_target_helm_replay_is_safe(phase):
        return "restored-accounting-replay"
    return "fresh-target"


def _rolling_compute_target_helm_checkpoint_keys(
    ordering_mode: str,
) -> tuple[str, str, str]:
    if ordering_mode == "restored-accounting-replay":
        suffix = str(_ROLLING_COMPUTE_VALUES_REVISION)
        return (
            f"target_values_reapply_intent_v{suffix}",
            f"target_values_reapply_proof_v{suffix}",
            f"target_values_reapply_semantic_drift_v{suffix}",
        )
    return (
        "target_handoff_values_apply_intent",
        "target_handoff_values_proof",
        "target_handoff_values_semantic_drift",
    )


def _source_reconciliation_fence_inventory(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[dict[str, Any], ...]:
    """Enumerate the served namespaced surface used by either Soperator generation."""

    try:
        discovery = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "api-resources",
                "--namespaced=true",
                "--verbs=list",
                "-o",
                "name",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence API discovery timed out."
        ) from exc
    if discovery.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence could not discover the served namespaced APIs."
        )
    served = {
        line.strip()
        for line in (discovery.stdout or "").splitlines()
        if re.fullmatch(r"[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?", line.strip())
    }
    if not {"pods", "configmaps", "secrets", "services"}.issubset(served):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence API discovery omitted required core resources."
        )
    inventory: list[dict[str, Any]] = []
    seen_types: set[str] = set()
    resource_specs: list[tuple[str, str, tuple[str, ...], str, str, str]] = []
    for (
        resource_type,
        api_versions,
        kind,
        api_prefix,
        collection,
    ) in _SOURCE_RECONCILIATION_FENCE_RESOURCE_TYPES:
        discovery_name = {
            "mariadb.k8s.mariadb.com": "mariadbs.k8s.mariadb.com",
        }.get(resource_type, resource_type)
        if discovery_name in seen_types or discovery_name not in served:
            continue
        seen_types.add(discovery_name)
        resource_specs.append(
            (resource_type, discovery_name, api_versions, kind, api_prefix, collection)
        )

    def _list_resource(discovery_name: str) -> SoperatorMigrationCommandResult:
        try:
            return command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    discovery_name,
                    "-o",
                    "json",
                    "--request-timeout=20s",
                ],
                timeout_seconds=60,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence timed out while enumerating the complete "
                f"{discovery_name} surface."
            ) from exc

    max_workers = min(
        _SOURCE_RECONCILIATION_FENCE_MAX_PARALLEL_READS,
        max(1, len(resource_specs)),
    )
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        listed_resources = [
            (spec, executor.submit(_list_resource, spec[1])) for spec in resource_specs
        ]
        for (
            resource_type,
            discovery_name,
            api_versions,
            kind,
            api_prefix,
            collection,
        ), future in listed_resources:
            result = future.result()
            if result.returncode != 0:
                raise SoperatorMigrationPhasePending(
                    "source reconciliation fence could not enumerate the complete served "
                    f"{discovery_name} surface."
                )
            try:
                payload = json.loads(result.stdout or "{}")
            except json.JSONDecodeError as exc:
                raise SoperatorMigrationPhasePending(
                    f"source reconciliation fence received invalid {resource_type} JSON."
                ) from exc
            raw_items = payload.get("items") if isinstance(payload, Mapping) else None
            if not isinstance(raw_items, Sequence) or isinstance(
                raw_items, (str, bytes, bytearray)
            ):
                raise SoperatorMigrationPhasePending(
                    f"source reconciliation fence received an incomplete {resource_type} list."
                )
            for raw_item in raw_items:
                if not isinstance(raw_item, Mapping):
                    raise SoperatorMigrationPhasePending(
                        f"source reconciliation fence found a malformed {resource_type} item."
                    )
                item = dict(raw_item)
                actual_api_version = str(item.get("apiVersion") or "").strip()
                if actual_api_version not in api_versions:
                    raise SoperatorMigrationPhasePending(
                        "source reconciliation fence found an unsupported served API identity "
                        f"for {resource_type}."
                    )
                identity = _validated_namespaced_resource_identity(
                    item,
                    expected_api_version=actual_api_version,
                    expected_kind=kind,
                    label=f"Source reconciliation fence {kind}",
                )
                resolved_prefix = api_prefix.format(version=actual_api_version.rsplit("/", 1)[-1])
                inventory.append(
                    {
                        "resource": item,
                        "identity": identity,
                        "api_path": (
                            f"{resolved_prefix}/namespaces/{_SOPERATOR_NAMESPACE}/"
                            f"{collection}/{identity['name']}"
                        ),
                    }
                )
    return tuple(inventory)


def _source_reconciliation_fence_identity(
    child: Mapping[str, Any],
) -> dict[str, Any]:
    resource = _mapping(child.get("resource"))
    identity = _mapping(child.get("identity"))
    metadata = _mapping(resource.get("metadata"))
    labels = _mapping(metadata.get("labels"))
    record: dict[str, Any] = {
        "api_path": str(child.get("api_path") or "").strip(),
        "api_version": str(resource.get("apiVersion") or "").strip(),
        "kind": str(resource.get("kind") or "").strip(),
        "namespace": str(identity.get("namespace") or "").strip(),
        "name": str(identity.get("name") or "").strip(),
        "uid": str(identity.get("uid") or "").strip(),
        "resource_version": str(identity.get("resourceVersion") or "").strip(),
        "labels": {
            key: str(labels.get(key) or "").strip()
            for key in _SOURCE_RECONCILIATION_FENCE_LABEL_KEYS
            if str(labels.get(key) or "").strip()
        },
    }
    if (
        record["namespace"] != _SOPERATOR_NAMESPACE
        or not all(record[key] for key in ("api_path", "api_version", "kind", "name", "uid"))
        or not record["resource_version"]
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence found an incomplete immutable resource identity."
        )
    return record


def _source_reconciliation_fence_stable_identity(
    resource: Mapping[str, Any],
) -> dict[str, Any]:
    """Project a frozen resource identity without mutable Kubernetes metadata."""
    return {
        key: resource.get(key)
        for key in (
            "api_path",
            "api_version",
            "kind",
            "namespace",
            "name",
            "uid",
            "labels",
        )
    }


def _source_reconciliation_fence_stable_closure(
    resources: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, Any], ...]:
    return tuple(_source_reconciliation_fence_stable_identity(resource) for resource in resources)


def _source_reconciliation_fence_live_closure(
    *,
    checkpoint: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    source_nodeset_uids: frozenset[str] | None = None,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[dict[str, Any], ...]:
    source_binding = {
        key: str(_mapping(checkpoint.get("source_slurmcluster_ref")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    if source_binding["namespace"] != _SOPERATOR_NAMESPACE or not all(source_binding.values()):
        raise SoperatorMigrationPhasePending(
            "fresh target Helm ordering requires the exact accepted source SlurmCluster binding."
        )
    exists, source = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"slurmcluster/{source_binding['name']}",
        namespace=source_binding["namespace"],
    )
    metadata = _mapping(source.get("metadata"))
    api_version = str(source.get("apiVersion") or "").strip()
    if (
        not exists
        or str(metadata.get("uid") or "").strip() != source_binding["uid"]
        or api_version not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
    ):
        raise SoperatorMigrationPhasePending(
            "fresh target Helm ordering cannot prove the exact live source SlurmCluster."
        )
    source_identity = _validated_namespaced_resource_identity(
        source,
        expected_api_version=api_version,
        expected_kind="SlurmCluster",
        label="Source reconciliation fence SlurmCluster",
    )
    version = api_version.rsplit("/", 1)[-1]
    source_item = {
        "resource": source,
        "identity": source_identity,
        "api_path": (
            f"/apis/slurm.nebius.ai/{version}/namespaces/{_SOPERATOR_NAMESPACE}/"
            f"slurmclusters/{source_binding['name']}"
        ),
    }
    source_names = set(_source_slurmcluster_names(source_report, target_ref=target_ref))
    source_names.add(source_binding["name"])
    if source_nodeset_uids is None:
        source_nodeset_uids, _target_nodeset_uids = _source_cleanup_nodeset_uid_sets(
            source_report=source_report,
            state={},
        )
    source_children, _stable = _classify_source_slurm_child_resources(
        inventory=_source_reconciliation_fence_inventory(
            command_runner=command_runner,
            kube_context=kube_context,
        ),
        source_binding=source_binding,
        target_binding={},
        source_names=source_names,
        source_nodeset_uids=source_nodeset_uids,
        target_nodeset_uids=frozenset(),
        checkpointed_bindings=None,
        source_labels_identify=True,
    )
    records = [
        _source_reconciliation_fence_identity(source_item),
        *(_source_reconciliation_fence_identity(child) for child in source_children),
    ]
    by_uid: dict[str, dict[str, Any]] = {}
    by_path: dict[str, str] = {}
    for record in records:
        uid = str(record["uid"])
        api_path = str(record["api_path"])
        if uid in by_uid or api_path in by_path:
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence closure contains a duplicate immutable identity."
            )
        by_uid[uid] = record
        by_path[api_path] = uid
    return tuple(sorted(by_uid.values(), key=lambda item: str(item["api_path"])))


def _source_reconciliation_fence_names(source_uid: str) -> dict[str, str]:
    suffix = hashlib.sha256(source_uid.encode("utf-8")).hexdigest()[:12]
    base = f"{_SOURCE_RECONCILIATION_FENCE_POLICY_PREFIX}-{suffix}"
    return {
        "policy": base,
        "binding": f"{base}-binding",
        "role": f"{base}-canary",
        "role_binding": f"{base}-canary",
    }


def _source_reconciliation_fence_validation_expression(
    *,
    source_name: str,
    frozen_uids: Sequence[str],
) -> str:
    uid_literal = json.dumps(list(frozen_uids), separators=(",", ":"))

    def _uid_clause(value: str) -> str:
        return f"({value} != null && has({value}.metadata.uid) && {value}.metadata.uid in {uid_literal})"

    def _owner_clause(value: str) -> str:
        return (
            f"({value} != null && has({value}.metadata.ownerReferences) && "
            f"{value}.metadata.ownerReferences.exists(owner, owner.uid in {uid_literal}))"
        )

    def _source_label_clause(value: str) -> str:
        return (
            f"({value} != null && has({value}.metadata.labels) && "
            f"'app.kubernetes.io/name' in {value}.metadata.labels && "
            f"{value}.metadata.labels['app.kubernetes.io/name'] == 'slurmcluster' && "
            f"'app.kubernetes.io/instance' in {value}.metadata.labels && "
            f"{value}.metadata.labels['app.kubernetes.io/instance'] == "
            f"{json.dumps(source_name)})"
        )

    source_name_literal = json.dumps(source_name)
    exact_source = (
        "(request.resource.group == 'slurm.nebius.ai' && "
        "request.resource.resource == 'slurmclusters' && "
        f"((object != null && object.metadata.name == {source_name_literal}) || "
        f"(oldObject != null && oldObject.metadata.name == {source_name_literal})))"
    )
    protected = " || ".join(
        (
            exact_source,
            _uid_clause("object"),
            _uid_clause("oldObject"),
            _owner_clause("object"),
            _owner_clause("oldObject"),
            _source_label_clause("object"),
            _source_label_clause("oldObject"),
        )
    )
    return f"!(request.namespace == '{_SOPERATOR_NAMESPACE}' && ({protected}))"


def _source_reconciliation_fence_resources(
    *,
    state: Mapping[str, Any],
) -> tuple[dict[str, Any], ...]:
    source = _mapping(state.get("source"))
    source_name = str(source.get("name") or "").strip()
    operation_id = str(state.get("operation_id") or "").strip()
    manager = _mapping(state.get("manager_service_account"))
    manager_name = str(manager.get("name") or "").strip()
    manager_username = str(manager.get("username") or "").strip()
    names = _mapping(state.get("resource_names"))
    frozen = _sequence_of_mappings(state.get("frozen_resources"))
    frozen_uids = tuple(str(item.get("uid") or "").strip() for item in frozen)
    if (
        not source_name
        or not operation_id
        or manager_name != _SOURCE_RECONCILIATION_FENCE_MANAGER_SERVICE_ACCOUNT
        or manager_username != f"system:serviceaccount:{_SOPERATOR_NAMESPACE}:{manager_name}"
        or not frozen_uids
        or any(not uid for uid in frozen_uids)
        or not all(
            str(names.get(key) or "").strip()
            for key in ("policy", "binding", "role", "role_binding")
        )
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence journal lacks its exact immutable contract."
        )
    labels = {
        "app.kubernetes.io/managed-by": "nebius-cxcli",
        _SOURCE_RECONCILIATION_FENCE_OPERATION_LABEL: operation_id,
    }
    policy_name = str(names["policy"])
    message = f"{policy_name} denied target-manager mutation of frozen source state"
    policy = {
        "apiVersion": "admissionregistration.k8s.io/v1",
        "kind": "ValidatingAdmissionPolicy",
        "metadata": {"name": policy_name, "labels": labels},
        "spec": {
            "failurePolicy": "Fail",
            "matchConstraints": {
                "matchPolicy": "Equivalent",
                "resourceRules": [
                    {
                        "apiGroups": ["*"],
                        "apiVersions": ["*"],
                        "operations": ["CREATE", "UPDATE", "DELETE"],
                        "resources": ["*/*"],
                        "scope": "Namespaced",
                    }
                ],
            },
            "matchConditions": [
                {
                    "name": "exact-target-manager-service-account",
                    "expression": ("request.userInfo.username == " + json.dumps(manager_username)),
                }
            ],
            "validations": [
                {
                    "expression": _source_reconciliation_fence_validation_expression(
                        source_name=source_name,
                        frozen_uids=frozen_uids,
                    ),
                    "message": message,
                    "reason": "Forbidden",
                }
            ],
        },
    }
    binding = {
        "apiVersion": "admissionregistration.k8s.io/v1",
        "kind": "ValidatingAdmissionPolicyBinding",
        "metadata": {"name": str(names["binding"]), "labels": labels},
        "spec": {"policyName": policy_name, "validationActions": ["Deny"]},
    }
    role = {
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "kind": "Role",
        "metadata": {
            "name": str(names["role"]),
            "namespace": _SOPERATOR_NAMESPACE,
            "labels": labels,
        },
        "rules": [
            {
                "apiGroups": ["slurm.nebius.ai"],
                "resources": ["slurmclusters"],
                "resourceNames": [source_name],
                "verbs": ["get", "patch", "update"],
            }
        ],
    }
    role_binding = {
        "apiVersion": "rbac.authorization.k8s.io/v1",
        "kind": "RoleBinding",
        "metadata": {
            "name": str(names["role_binding"]),
            "namespace": _SOPERATOR_NAMESPACE,
            "labels": labels,
        },
        "roleRef": {
            "apiGroup": "rbac.authorization.k8s.io",
            "kind": "Role",
            "name": str(names["role"]),
        },
        "subjects": [
            {
                "kind": "ServiceAccount",
                "name": manager_name,
                "namespace": _SOPERATOR_NAMESPACE,
            }
        ],
    }
    return policy, binding, role, role_binding


def _source_reconciliation_fence_resource_ref(
    resource: Mapping[str, Any],
) -> tuple[str, str]:
    kind = str(resource.get("kind") or "").strip()
    refs = {
        "ValidatingAdmissionPolicy": "validatingadmissionpolicy.admissionregistration.k8s.io",
        "ValidatingAdmissionPolicyBinding": (
            "validatingadmissionpolicybinding.admissionregistration.k8s.io"
        ),
        "Role": "role.rbac.authorization.k8s.io",
        "RoleBinding": "rolebinding.rbac.authorization.k8s.io",
    }
    resource_type = refs.get(kind, "")
    name = str(_mapping(resource.get("metadata")).get("name") or "").strip()
    if not resource_type or not name:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence contains an unsupported managed resource."
        )
    return resource_type, name


def _source_reconciliation_fence_get_managed_resource(
    *,
    desired: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[bool, dict[str, Any]]:
    resource_type, name = _source_reconciliation_fence_resource_ref(desired)
    namespace = str(_mapping(desired.get("metadata")).get("namespace") or "").strip()
    command = ["kubectl", "--context", kube_context]
    if namespace:
        command.extend(["-n", namespace])
    command.extend(["get", resource_type, name, "-o", "json", "--request-timeout=20s"])
    result = command_runner(command, timeout_seconds=60, check=False)
    if result.returncode != 0:
        if _command_not_found(result):
            return False, {}
        raise SoperatorMigrationPhasePending(
            f"source reconciliation fence could not read {resource_type}/{name}."
        )
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            f"source reconciliation fence received invalid {resource_type}/{name} JSON."
        ) from exc
    if not isinstance(payload, Mapping):
        raise SoperatorMigrationPhasePending(
            f"source reconciliation fence received malformed {resource_type}/{name} state."
        )
    return True, dict(payload)


def _source_reconciliation_fence_managed_binding(
    *,
    desired: Mapping[str, Any],
    live: Mapping[str, Any],
    operation_id: str,
) -> dict[str, str]:
    desired_metadata = _mapping(desired.get("metadata"))
    live_metadata = _mapping(live.get("metadata"))
    desired_namespace = str(desired_metadata.get("namespace") or "").strip()
    live_namespace = str(live_metadata.get("namespace") or "").strip()
    if desired_namespace and not live_namespace:
        live_namespace = _SOPERATOR_NAMESPACE
    if (
        str(live.get("apiVersion") or "").strip() != str(desired.get("apiVersion") or "").strip()
        or str(live.get("kind") or "").strip() != str(desired.get("kind") or "").strip()
        or str(live_metadata.get("name") or "").strip()
        != str(desired_metadata.get("name") or "").strip()
        or live_namespace != desired_namespace
        or str(
            _mapping(live_metadata.get("labels")).get(_SOURCE_RECONCILIATION_FENCE_OPERATION_LABEL)
            or ""
        ).strip()
        != operation_id
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence managed-resource identity or ownership label drifted."
        )
    for key in ("spec", "rules", "roleRef", "subjects"):
        desired_value = desired.get(key)
        if desired_value is None:
            continue
        live_value = live.get(key)
        if isinstance(desired_value, Mapping):
            if not isinstance(live_value, Mapping) or not _mapping_contains_subset(
                _mapping(live_value), _mapping(desired_value)
            ):
                raise SoperatorMigrationPhasePending(
                    f"source reconciliation fence live {desired.get('kind')} {key} drifted."
                )
        elif live_value != desired_value:
            raise SoperatorMigrationPhasePending(
                f"source reconciliation fence live {desired.get('kind')} {key} drifted."
            )
    uid = str(live_metadata.get("uid") or "").strip()
    resource_version = str(live_metadata.get("resourceVersion") or "").strip()
    if not uid or not resource_version:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence managed resource lacks UID/resourceVersion."
        )
    return {
        "api_version": str(live.get("apiVersion") or "").strip(),
        "kind": str(live.get("kind") or "").strip(),
        "namespace": live_namespace,
        "name": str(live_metadata.get("name") or "").strip(),
        "uid": uid,
        "resource_version": resource_version,
    }


def _source_reconciliation_fence_validate_checkpoint(
    state: Mapping[str, Any],
    *,
    source_binding: Mapping[str, str],
    live_closure: Sequence[Mapping[str, Any]],
) -> None:
    if state.get("schema") != _SOURCE_RECONCILIATION_FENCE_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence journal uses an unsupported schema."
        )
    source_nodeset_uids = state.get("source_nodeset_uids")
    if (
        not isinstance(source_nodeset_uids, list)
        or any(not isinstance(item, str) or not item.strip() for item in source_nodeset_uids)
        or source_nodeset_uids != sorted(set(source_nodeset_uids))
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence journal lacks its immutable source NodeSet identities."
        )
    if {
        key: str(_mapping(state.get("source")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    } != dict(source_binding):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence journal changed its accepted source binding."
        )
    frozen = tuple(_sequence_of_mappings(state.get("frozen_resources")))
    stable_frozen = _source_reconciliation_fence_stable_closure(frozen)
    stable_live = _source_reconciliation_fence_stable_closure(live_closure)
    absence_reseal = _mapping(state.get("closure_absence_reseal"))
    accepted_absent = tuple(_sequence_of_mappings(absence_reseal.get("accepted_absent_resources")))
    replacement_reseal = _mapping(state.get("closure_worker_replacement_reseal"))
    replacement_old = _mapping(replacement_reseal.get("frozen_identity"))
    replacement_new = _mapping(replacement_reseal.get("live_identity"))
    reconstructed_live_items = list(stable_live)
    if replacement_reseal:
        replacement_path = str(replacement_new.get("api_path") or "")
        matching_live = tuple(
            item
            for item in reconstructed_live_items
            if str(item.get("api_path") or "") == replacement_path
        )
        if len(matching_live) == 1 and dict(matching_live[0]) == dict(replacement_new):
            reconstructed_live_items.remove(matching_live[0])
            reconstructed_live_items.append(dict(replacement_old))
    if accepted_absent:
        comparison_frozen = tuple(
            sorted(stable_frozen, key=lambda item: str(item.get("api_path") or ""))
        )
        reconstructed_live = tuple(
            sorted(
                (*reconstructed_live_items, *accepted_absent),
                key=lambda item: str(item.get("api_path") or ""),
            )
        )
    else:
        comparison_frozen = stable_frozen
        reconstructed_live = tuple(reconstructed_live_items)
    absence_contract_valid = bool(
        not accepted_absent
        or (
            absence_reseal.get("schema") == "nebius-cxcli/source-fence-writer-absence-reseal-v1"
            and absence_reseal.get("status") == "verified"
            and str(absence_reseal.get("writer_deployment_uid") or "").strip()
            and str(absence_reseal.get("writer_fence_verified_at") or "").strip()
            and str(absence_reseal.get("resealed_at") or "").strip()
        )
    )
    replacement_contract_valid = bool(
        not replacement_reseal
        or (
            replacement_reseal.get("schema")
            == "nebius-cxcli/source-fence-gpu-probe-worker-replacement-v1"
            and replacement_reseal.get("status") == "verified"
            and str(replacement_reseal.get("unsafe_probe_job_uid") or "").strip()
            and str(replacement_reseal.get("worker_owner_uid") or "").strip()
            and str(replacement_reseal.get("node_name") or "").strip()
            and str(replacement_reseal.get("resealed_at") or "").strip()
            and replacement_old
            and replacement_new
            and replacement_old.get("kind") == "Pod"
            and replacement_new.get("kind") == "Pod"
            and replacement_old.get("api_path") == replacement_new.get("api_path")
            and replacement_old.get("namespace") == replacement_new.get("namespace")
            and replacement_old.get("name") == replacement_new.get("name")
            and replacement_old.get("labels") == replacement_new.get("labels")
            and str(replacement_old.get("uid") or "").strip()
            != str(replacement_new.get("uid") or "").strip()
        )
    )
    if (
        not absence_contract_valid
        or not replacement_contract_valid
        or comparison_frozen != reconstructed_live
        or str(state.get("closure_sha256") or "") != _fingerprint(stable_frozen)
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence closure changed before target Helm reconciliation."
        )


def _source_reconciliation_fence_reseal_writer_absence(
    *,
    state: dict[str, Any],
    phase: Mapping[str, Any],
    live_closure: Sequence[Mapping[str, Any]],
    checkpoint_writer: Callable[[], None],
) -> None:
    frozen = _source_reconciliation_fence_stable_closure(
        tuple(_sequence_of_mappings(state.get("frozen_resources")))
    )
    live = _source_reconciliation_fence_stable_closure(live_closure)
    frozen_by_path = {str(item.get("api_path") or ""): item for item in frozen}
    live_by_path = {str(item.get("api_path") or ""): item for item in live}
    added_or_changed = tuple(
        path
        for path, item in live_by_path.items()
        if path not in frozen_by_path or frozen_by_path[path] != item
    )
    removed = tuple(item for path, item in frozen_by_path.items() if path not in live_by_path)
    writer_fence = _mapping(phase.get("pre_target_helm_sconfig_writer_fence"))
    deployment = _mapping(writer_fence.get("deployment"))
    selector = {
        str(key): str(value)
        for key, value in _mapping(deployment.get("selector")).items()
        if str(key).strip() and str(value).strip()
    }
    existing = _mapping(state.get("closure_absence_reseal"))
    accepted = tuple(_sequence_of_mappings(existing.get("accepted_absent_resources")))
    if accepted:
        if tuple(accepted) != removed or added_or_changed:
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence accepted writer-Pod absence or another stable "
                "identity changed after reseal."
            )
        return
    if (
        writer_fence.get("schema") != _PRE_TARGET_HELM_SCONFIG_WRITER_FENCE_SCHEMA
        or writer_fence.get("status") != "verified"
        or _non_negative_int(writer_fence.get("writer_pod_count"), fallback=-1) != 0
        or not str(writer_fence.get("verified_at") or "").strip()
        or not str(deployment.get("uid") or "").strip()
        or not selector
        or added_or_changed
        or not removed
        or len(removed) > 8
        or any(
            str(item.get("kind") or "") != "Pod"
            or str(item.get("namespace") or "") != _SOPERATOR_NAMESPACE
            or not all(
                str(_mapping(item.get("labels")).get(key) or "") == value
                for key, value in selector.items()
            )
            for item in removed
        )
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence closure changed before target Helm reconciliation."
        )
    state["closure_absence_reseal"] = {
        "schema": "nebius-cxcli/source-fence-writer-absence-reseal-v1",
        "status": "verified",
        "writer_deployment_uid": str(deployment["uid"]),
        "writer_fence_verified_at": str(writer_fence["verified_at"]),
        "accepted_absent_resources": [copy.deepcopy(dict(item)) for item in removed],
        "resealed_at": _utc_now(),
    }
    checkpoint_writer()


def _source_reconciliation_fence_reseal_gpu_probe_worker_replacement(
    *,
    state: dict[str, Any],
    checkpoint: Mapping[str, Any],
    live_closure: Sequence[Mapping[str, Any]],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None],
) -> None:
    """Accept one exact worker Pod replacement caused by the retired GPU probe contract."""

    frozen = _source_reconciliation_fence_stable_closure(
        tuple(_sequence_of_mappings(state.get("frozen_resources")))
    )
    live = _source_reconciliation_fence_stable_closure(live_closure)
    frozen_by_path = {str(item.get("api_path") or ""): item for item in frozen}
    live_by_path = {str(item.get("api_path") or ""): item for item in live}
    absence_reseal = _mapping(state.get("closure_absence_reseal"))
    accepted_absent = tuple(_sequence_of_mappings(absence_reseal.get("accepted_absent_resources")))
    accepted_absent_paths = {str(item.get("api_path") or "") for item in accepted_absent}
    changed_paths = tuple(
        path
        for path, item in live_by_path.items()
        if path in frozen_by_path and frozen_by_path[path] != item
    )
    added_paths = tuple(path for path in live_by_path if path not in frozen_by_path)
    removed_paths = {path for path in frozen_by_path if path not in live_by_path}
    if state.get("closure_worker_replacement_reseal"):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence worker replacement changed after reseal."
        )
    if (
        absence_reseal.get("status") != "verified"
        or removed_paths != accepted_absent_paths
        or added_paths
        or len(changed_paths) != 1
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence closure changed before target Helm reconciliation."
        )
    replacement_path = changed_paths[0]
    frozen_worker = frozen_by_path[replacement_path]
    live_worker = live_by_path[replacement_path]
    expected_live_worker = dict(frozen_worker)
    expected_live_worker["uid"] = live_worker.get("uid")
    worker_labels = _mapping(frozen_worker.get("labels"))
    if (
        dict(live_worker) != expected_live_worker
        or frozen_worker.get("kind") != "Pod"
        or frozen_worker.get("namespace") != _SOPERATOR_NAMESPACE
        or worker_labels.get("app.kubernetes.io/component") != "worker"
        or worker_labels.get("app.kubernetes.io/instance")
        != str(_mapping(state.get("source")).get("name") or "")
        or worker_labels.get("app.kubernetes.io/name") != "slurmcluster"
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence changed outside one exact source worker Pod UID."
        )

    populate_phase = _accepted_populate_jail_phase_state(checkpoint)
    gpu_gate = _mapping(populate_phase.get("gpu_post_population"))
    gpu_binding = _mapping(gpu_gate.get("binding"))
    old_image_lock = _mapping(gpu_gate.get("image_lock"))
    unsafe_job_name = str(gpu_binding.get("job") or "").strip()
    if (
        gpu_gate.get("status") != "intent-recorded"
        or _mapping(gpu_gate.get("resource_uids"))
        or str(old_image_lock.get("source") or "") != str(gpu_binding.get("image") or "")
        or not unsafe_job_name
    ):
        raise SoperatorMigrationPhasePending(
            "source worker replacement is not bound to the retired pre-switch GPU probe."
        )
    job_exists, unsafe_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"job/{unsafe_job_name}",
    )
    job_metadata = _mapping(unsafe_job.get("metadata"))
    job_spec = _mapping(unsafe_job.get("spec"))
    pod_spec = _mapping(_mapping(job_spec.get("template")).get("spec"))
    containers = _sequence_of_mappings(pod_spec.get("containers"))
    container = containers[0] if len(containers) == 1 else {}
    gpu_limit = _mapping(_mapping(container.get("resources")).get("limits")).get("nvidia.com/gpu")
    unsafe_job_uid = str(job_metadata.get("uid") or "").strip()
    if (
        not job_exists
        or not unsafe_job_uid
        or not _job_condition_true(unsafe_job, "Failed")
        or _job_condition_true(unsafe_job, "Complete")
        or str(container.get("image") or "") != str(old_image_lock.get("immutable_reference") or "")
        or str(gpu_limit) != "1"
        or not str(pod_spec.get("priorityClassName") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "source worker replacement lacks the exact failed preempting GPU probe evidence."
        )

    pod_exists, worker_pod = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"pod/{live_worker['name']}",
    )
    pod_metadata = _mapping(worker_pod.get("metadata"))
    pod_status = _mapping(worker_pod.get("status"))
    container_statuses = _sequence_of_mappings(pod_status.get("containerStatuses"))
    controller_owners = tuple(
        owner
        for owner in _sequence_of_mappings(pod_metadata.get("ownerReferences"))
        if owner.get("controller") is True
    )
    frozen_owner_uids = {
        str(item.get("uid") or "")
        for item in frozen
        if item.get("kind") == "StatefulSet"
        and item.get("namespace") == _SOPERATOR_NAMESPACE
        and _mapping(item.get("labels")).get("app.kubernetes.io/component") == "worker"
    }
    owner_uid = str(controller_owners[0].get("uid") or "") if len(controller_owners) == 1 else ""
    node_name = str(_mapping(worker_pod.get("spec")).get("nodeName") or "").strip()
    if (
        not pod_exists
        or str(pod_metadata.get("uid") or "") != str(live_worker.get("uid") or "")
        or pod_status.get("phase") != "Running"
        or not container_statuses
        or any(
            status.get("ready") is not True
            or _non_negative_int(status.get("restartCount"), fallback=-1) != 0
            for status in container_statuses
        )
        or owner_uid not in frozen_owner_uids
        or not node_name
    ):
        raise SoperatorMigrationPhasePending(
            "source worker replacement is not one Ready zero-restart Pod of the frozen worker owner."
        )
    state["closure_worker_replacement_reseal"] = {
        "schema": "nebius-cxcli/source-fence-gpu-probe-worker-replacement-v1",
        "status": "verified",
        "frozen_identity": copy.deepcopy(dict(frozen_worker)),
        "live_identity": copy.deepcopy(dict(live_worker)),
        "unsafe_probe_job_uid": unsafe_job_uid,
        "worker_owner_uid": owner_uid,
        "node_name": node_name,
        "resealed_at": _utc_now(),
    }
    checkpoint_writer()


def _source_reconciliation_fence_typecheck_ready(
    *,
    policy: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    for _attempt in range(30):
        exists, live = _source_reconciliation_fence_get_managed_resource(
            desired=policy,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if exists:
            type_checking = _mapping(_mapping(live.get("status")).get("typeChecking"))
            warnings = type_checking.get("expressionWarnings")
            if isinstance(warnings, Sequence) and not isinstance(warnings, (str, bytes, bytearray)):
                if warnings:
                    raise SoperatorMigrationPhasePending(
                        "source reconciliation fence policy has CEL type-check warnings."
                    )
                return live
            if "typeChecking" in _mapping(live.get("status")) and warnings is None:
                return live
        time.sleep(1)
    raise SoperatorMigrationPhasePending(
        "source reconciliation fence policy type-check status did not converge."
    )


def _source_reconciliation_fence_canary(
    *,
    state: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> str:
    source = _mapping(state.get("source"))
    manager = _mapping(state.get("manager_service_account"))
    policy_name = str(_mapping(state.get("resource_names")).get("policy") or "").strip()
    canary_token = hashlib.sha256(
        f"{state.get('operation_id')}:{source.get('uid')}".encode()
    ).hexdigest()[:16]
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "patch",
            "slurmcluster",
            str(source.get("name") or ""),
            "--type=merge",
            "-p",
            json.dumps(
                {
                    "metadata": {
                        "annotations": {"nebius-cxcli.nebius.ai/source-fence-canary": canary_token}
                    }
                },
                separators=(",", ":"),
            ),
            "--dry-run=server",
            f"--as={str(manager.get('username') or '')}",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    detail = f"{result.stderr}\n{result.stdout}"
    normalized = detail.lower()
    if (
        result.returncode == 0
        or policy_name not in detail
        or "denied target-manager mutation of frozen source state" not in detail
        or "cannot patch resource" in normalized
        or "rbac" in normalized
    ):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence canary was not denied by the exact admission policy."
        )
    return hashlib.sha256(detail.encode("utf-8")).hexdigest()


def _ensure_safe_fresh_target_helm_ordering(
    *,
    checkpoint: Mapping[str, Any],
    phase: dict[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None = None,
) -> list[str]:
    """Install and prove a fail-closed source-only manager reconciliation fence."""

    if mutation_guard is not None:
        mutation_guard()
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence requires durable checkpoint writes."
        )
    bridge = checkpoint.get("controller_bridge")
    if not isinstance(bridge, Mapping):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence requires the v6 controller bridge journal."
        )
    validate_bridge_journal(bridge)
    stage = BridgeStage(str(bridge.get("stage") or ""))
    if list(BridgeStage).index(stage) < list(BridgeStage).index(BridgeStage.SOURCE_HA_ACTIVE):
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence requires source authority on the temporary HA bridge."
        )
    authority_owner = str(_mapping(bridge.get("authority")).get("owner") or "").strip()
    if authority_owner not in {"bridge-source", "bridge-target"}:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence requires bridge-owned Slurm authority."
        )
    source_binding = {
        key: str(_mapping(checkpoint.get("source_slurmcluster_ref")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    raw_state = phase.get("source_reconciliation_fence")
    if raw_state is None:
        source_nodeset_uids, _target_nodeset_uids = _source_cleanup_nodeset_uid_sets(
            source_report=source_report,
            state={},
        )
    elif isinstance(raw_state, dict):
        raw_source_nodeset_uids = raw_state.get("source_nodeset_uids")
        if (
            not isinstance(raw_source_nodeset_uids, list)
            or any(
                not isinstance(item, str) or not item.strip() for item in raw_source_nodeset_uids
            )
            or raw_source_nodeset_uids != sorted(set(raw_source_nodeset_uids))
        ):
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence journal lacks its immutable source NodeSet identities."
            )
        source_nodeset_uids = frozenset(raw_source_nodeset_uids)
    else:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence journal must be a mutable mapping."
        )
    live_closure = _source_reconciliation_fence_live_closure(
        checkpoint=checkpoint,
        source_report=source_report,
        target_ref=target_ref,
        source_nodeset_uids=source_nodeset_uids,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if raw_state is None:
        names = _source_reconciliation_fence_names(source_binding["uid"])
        manager_name = _SOURCE_RECONCILIATION_FENCE_MANAGER_SERVICE_ACCOUNT
        state: dict[str, Any] = {
            "schema": _SOURCE_RECONCILIATION_FENCE_SCHEMA,
            "status": "captured",
            "operation_id": str(uuid4()),
            "source": source_binding,
            "source_nodeset_uids": sorted(source_nodeset_uids),
            "manager_service_account": {
                "namespace": _SOPERATOR_NAMESPACE,
                "name": manager_name,
                "username": (f"system:serviceaccount:{_SOPERATOR_NAMESPACE}:{manager_name}"),
            },
            "resource_names": names,
            "frozen_resources": list(live_closure),
            "closure_sha256": _fingerprint(
                _source_reconciliation_fence_stable_closure(live_closure)
            ),
            "captured_at": _utc_now(),
            "managed_resource_bindings": [],
        }
        phase["source_reconciliation_fence"] = state
        checkpoint_writer()
    else:
        state = raw_state
    try:
        _source_reconciliation_fence_validate_checkpoint(
            state,
            source_binding=source_binding,
            live_closure=live_closure,
        )
    except SoperatorMigrationPhasePending as exc:
        if "closure changed" not in str(exc):
            raise
        try:
            _source_reconciliation_fence_reseal_writer_absence(
                state=state,
                phase=phase,
                live_closure=live_closure,
                checkpoint_writer=checkpoint_writer,
            )
        except SoperatorMigrationPhasePending:
            _source_reconciliation_fence_reseal_gpu_probe_worker_replacement(
                state=state,
                checkpoint=checkpoint,
                live_closure=live_closure,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        _source_reconciliation_fence_validate_checkpoint(
            state,
            source_binding=source_binding,
            live_closure=live_closure,
        )
    desired_resources = _source_reconciliation_fence_resources(state=state)
    desired_fingerprint = _fingerprint(desired_resources)
    existing_fingerprint = str(state.get("managed_resources_sha256") or "").strip()
    status = str(state.get("status") or "").strip()
    if existing_fingerprint and existing_fingerprint != desired_fingerprint:
        managed_bindings = tuple(_sequence_of_mappings(state.get("managed_resource_bindings")))
        if status != "apply-intent" or managed_bindings:
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence managed-resource contract changed after capture."
            )
        for desired in desired_resources:
            exists, _live = _source_reconciliation_fence_get_managed_resource(
                desired=desired,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if exists:
                raise SoperatorMigrationPhasePending(
                    "source reconciliation fence managed-resource contract changed after a "
                    "resource was created; recovery is required."
                )
        state["managed_resources_reseal"] = {
            "status": "verified-absent-before-apply",
            "previous_sha256": existing_fingerprint,
            "replacement_sha256": desired_fingerprint,
            "resealed_at": _utc_now(),
        }
        state["managed_resources_sha256"] = desired_fingerprint
        checkpoint_writer()
    if status == "captured":
        for desired in desired_resources:
            exists, _live = _source_reconciliation_fence_get_managed_resource(
                desired=desired,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if exists:
                raise SoperatorMigrationPhasePending(
                    "source reconciliation fence resource name already exists before apply intent."
                )
        state["managed_resources_sha256"] = desired_fingerprint
        state["status"] = "apply-intent"
        state["apply_intent_at"] = _utc_now()
        checkpoint_writer()
        status = "apply-intent"
    bindings_by_kind = {
        str(item.get("kind") or ""): dict(item)
        for item in _sequence_of_mappings(state.get("managed_resource_bindings"))
    }
    if status == "apply-intent":
        for desired in desired_resources:
            exists, live = _source_reconciliation_fence_get_managed_resource(
                desired=desired,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if exists:
                _source_reconciliation_fence_managed_binding(
                    desired=desired,
                    live=live,
                    operation_id=str(state["operation_id"]),
                )
        manifest = {
            "apiVersion": "v1",
            "kind": "List",
            "items": list(desired_resources),
        }
        if mutation_guard is not None:
            mutation_guard()
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "apply",
                "--field-manager=nebius-cxcli-source-fence",
                "-f",
                "-",
                "--request-timeout=30s",
            ],
            input_text=yaml.safe_dump(manifest, sort_keys=True),
            timeout_seconds=120,
        )
        bindings: list[dict[str, str]] = []
        for desired in desired_resources:
            exists, live = _source_reconciliation_fence_get_managed_resource(
                desired=desired,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if not exists:
                raise SoperatorMigrationPhasePending(
                    "source reconciliation fence apply did not create every exact resource."
                )
            bindings.append(
                _source_reconciliation_fence_managed_binding(
                    desired=desired,
                    live=live,
                    operation_id=str(state["operation_id"]),
                )
            )
        state["managed_resource_bindings"] = bindings
        state["status"] = "resources-applied"
        state["resources_applied_at"] = _utc_now()
        checkpoint_writer()
        status = "resources-applied"
        bindings_by_kind = {item["kind"]: item for item in bindings}
    if status not in {"resources-applied", "verified"}:
        raise SoperatorMigrationPhasePending(
            "source reconciliation fence journal stopped at an unsupported boundary."
        )
    for desired in desired_resources:
        exists, live = _source_reconciliation_fence_get_managed_resource(
            desired=desired,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if not exists:
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence managed resource disappeared before target Helm."
            )
        binding = _source_reconciliation_fence_managed_binding(
            desired=desired,
            live=live,
            operation_id=str(state["operation_id"]),
        )
        expected_uid = str(_mapping(bindings_by_kind.get(binding["kind"])).get("uid") or "")
        if expected_uid and binding["uid"] != expected_uid:
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence managed resource was replaced after apply."
            )
    policy = desired_resources[0]
    _source_reconciliation_fence_typecheck_ready(
        policy=policy,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    accounting = _mapping(phase.get("accounting_handoff"))
    retirement = _mapping(accounting.get("source_orphan_finalizer_recovery"))
    retirement_source = _mapping(retirement.get("source"))
    source_retired = bool(
        str(phase.get("source_accounting_owner_retired_at") or "").strip()
        and retirement.get("status") == "verified"
        and str(retirement.get("verified_at") or "").strip()
        and all(
            str(retirement_source.get(key) or "").strip()
            == str(source_binding.get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        )
    )
    if source_retired:
        live_source = _accounting_handoff_optional_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=source_binding,
            label="retired source reconciliation fence canary",
        )
        prior_canary = _mapping(state.get("canary"))
        canary_sha256 = str(prior_canary.get("response_sha256") or "").strip()
        if (
            live_source is not None
            or state.get("status") != "verified"
            or prior_canary.get("status") != "denied-by-policy"
            or prior_canary.get("policy_name")
            != str(_mapping(state.get("resource_names")).get("policy") or "")
            or not canary_sha256
            or not str(prior_canary.get("verified_at") or "").strip()
        ):
            raise SoperatorMigrationPhasePending(
                "source reconciliation fence cannot adopt source absence without its "
                "exact retired UID and prior policy-attributed canary denial."
            )
        state["post_retirement_canary"] = {
            "status": "source-absent",
            "source": dict(source_binding),
            "prior_response_sha256": canary_sha256,
            "verified_at": _utc_now(),
        }
    else:
        canary_sha256 = _source_reconciliation_fence_canary(
            state=state,
            command_runner=command_runner,
            kube_context=kube_context,
        )
    state["status"] = "verified"
    state["typecheck"] = {"status": "ready", "warnings": 0}
    if not source_retired:
        state["canary"] = {
            "status": "denied-by-policy",
            "policy_name": str(_mapping(state.get("resource_names")).get("policy") or ""),
            "response_sha256": canary_sha256,
            "server_dry_run": True,
            "verified_at": _utc_now(),
        }
    state["verified_at"] = state.get("verified_at") or _utc_now()
    checkpoint_writer()
    return [
        "Source reconciliation fence verified: exact source UIDs are protected from the "
        "target manager by a fail-closed ValidatingAdmissionPolicy; server dry-run denial "
        "was attributed to the exact policy, not RBAC."
    ]


def _pre_target_helm_sconfig_writer_pods(
    *,
    selector: Mapping[str, str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[dict[str, str], ...]:
    pods: list[dict[str, str]] = []
    for pod in _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pods",
    ):
        labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
        if not all(str(labels.get(key) or "") == value for key, value in selector.items()):
            continue
        pods.append(
            _immutable_child_exact_identity(
                pod,
                label="pre-target Helm source SConfig writer Pod",
            )
        )
    return tuple(sorted(pods, key=lambda item: item["name"]))


def _pre_target_helm_zero_adoption_allowed(
    *,
    phase: Mapping[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> bool:
    source_fence = _mapping(phase.get("source_reconciliation_fence"))
    if (
        source_fence.get("schema") != _SOURCE_RECONCILIATION_FENCE_SCHEMA
        or source_fence.get("status") != "verified"
    ):
        return False
    target = _immutable_child_optional_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="slurmcluster",
        name=target_ref,
        label="pre-target Helm recovery target SlurmCluster",
    )
    if target is None or _sconfigcontroller_replicas(target) != 0:
        return False
    try:
        releases = tuple(
            release
            for release in list_helm_releases(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                filter_regex=f"^{re.escape(_SOPERATOR_TARGET_RELEASE_NAME)}$",
            )
            if release.name == _SOPERATOR_TARGET_RELEASE_NAME
        )
    except (RuntimeError, subprocess.TimeoutExpired):
        return False
    return bool(
        len(releases) == 1
        and releases[0].namespace == _SOPERATOR_NAMESPACE
        and releases[0].status.strip().lower() == "deployed"
        and _positive_int(releases[0].revision, fallback=0) > 0
    )


def _pre_target_helm_sconfig_writer_observation(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> Mapping[str, Any]:
    return _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
    )


def _ensure_pre_target_helm_sconfig_writer_fence(
    *,
    checkpoint: Mapping[str, Any],
    phase: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None = None,
    initial_deployment: Mapping[str, Any] | None = None,
    timeout_seconds: int = 300,
    poll_interval_seconds: float = 2.0,
) -> list[str]:
    """Stop the legacy Jail writer before target Helm can create a second config."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "pre-target Helm SConfig writer fence requires durable checkpoint writes."
        )
    source = {
        key: str(_mapping(checkpoint.get("source_slurmcluster_ref")).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    if source["namespace"] != _SOPERATOR_NAMESPACE or not all(source.values()):
        raise SoperatorMigrationPhasePending(
            "pre-target Helm SConfig writer fence lacks the exact source SlurmCluster binding."
        )
    source_resource = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="slurmcluster",
        name=source["name"],
    )
    _immutable_child_require_live_uid(
        source_resource,
        expected_uid=source["uid"],
        label="pre-target Helm source SlurmCluster",
    )
    original_replicas = _sconfigcontroller_replicas(source_resource)
    if original_replicas <= 0:
        raise SoperatorMigrationPhasePending(
            "pre-target Helm source SlurmCluster does not declare a positive SConfig writer size."
        )
    deployment = (
        dict(initial_deployment)
        if initial_deployment is not None
        else _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
    )
    identity = _immutable_child_exact_identity(
        deployment,
        label="pre-target Helm source SConfig Deployment",
    )
    owner = _immutable_child_controller_owner(
        deployment,
        label="pre-target Helm source SConfig Deployment",
    )
    if not _controller_owner_reference_matches_binding(_mapping(owner), source):
        raise SoperatorMigrationPhasePending(
            "pre-target Helm SConfig Deployment is not owned by the exact source SlurmCluster."
        )
    selector = {
        str(key): str(value)
        for key, value in _mapping(
            _mapping(_mapping(deployment.get("spec")).get("selector")).get("matchLabels")
        ).items()
        if str(key).strip() and str(value).strip()
    }
    if not selector:
        raise SoperatorMigrationPhasePending(
            "pre-target Helm source SConfig Deployment lacks an exact Pod selector."
        )
    spec_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
        deployment,
        label="pre-target Helm source SConfig Deployment",
    )
    generation = _legacy_rootfs_positive_generation(
        deployment,
        label="pre-target Helm source SConfig Deployment",
    )
    desired = _resource_replicas(deployment, default=-1)
    if desired not in {0, original_replicas}:
        raise SoperatorMigrationPhasePending(
            "pre-target Helm source SConfig replicas drifted outside the exact zero transition."
        )
    raw_state = phase.setdefault(
        "pre_target_helm_sconfig_writer_fence",
        {
            "schema": _PRE_TARGET_HELM_SCONFIG_WRITER_FENCE_SCHEMA,
            "status": "pending",
        },
    )
    if (
        not isinstance(raw_state, dict)
        or raw_state.get("schema") != _PRE_TARGET_HELM_SCONFIG_WRITER_FENCE_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "pre-target Helm SConfig writer-fence checkpoint is malformed or unsupported."
        )
    state = raw_state
    status = str(state.get("status") or "").strip()
    if status == "pending":
        state.update(
            {
                "source": source,
                "deployment": {
                    **identity,
                    "original_replicas": original_replicas,
                    "selector": selector,
                    "spec_fingerprint": spec_fingerprint,
                },
            }
        )
        if desired == 0:
            if not _pre_target_helm_zero_adoption_allowed(
                phase=phase,
                target_ref=target_ref,
                command_runner=command_runner,
                kube_context=kube_context,
            ):
                raise SoperatorMigrationPhasePending(
                    "pre-target Helm found an uncheckpointed zero-replica SConfig writer "
                    "without an exact deployed target recovery boundary."
                )
            state.update(
                {
                    "status": "scale-intent",
                    "scale_mode": "adopted-deployed-target-recovery",
                    "zero_generation": generation,
                    "zero_resource_version": identity["resourceVersion"],
                    "scale_intent_at": _utc_now(),
                }
            )
        else:
            state.update(
                {
                    "status": "scale-intent",
                    "scale_mode": "scaled-by-cxcli",
                    "scale_from_generation": generation,
                    "scale_expected_generation": generation + 1,
                    "scale_intent_resource_version": identity["resourceVersion"],
                    "scale_patch_resource_version": identity["resourceVersion"],
                    "scale_intent_at": _utc_now(),
                }
            )
        checkpoint_writer()
        status = "scale-intent"
    checkpoint_deployment = _mapping(state.get("deployment"))
    if (
        status not in {"scale-intent", "verified"}
        or _mapping(state.get("source")) != source
        or str(checkpoint_deployment.get("uid") or "") != identity["uid"]
        or _positive_int(checkpoint_deployment.get("original_replicas"), fallback=0)
        != original_replicas
        or _mapping(checkpoint_deployment.get("selector")) != selector
        or str(checkpoint_deployment.get("spec_fingerprint") or "") != spec_fingerprint
    ):
        raise SoperatorMigrationPhasePending(
            "pre-target Helm SConfig writer-fence identity or workload contract drifted."
        )
    if desired == original_replicas:
        if (
            status != "scale-intent"
            or state.get("scale_mode") != "scaled-by-cxcli"
            or generation != _positive_int(state.get("scale_from_generation"), fallback=0)
        ):
            raise SoperatorMigrationPhasePending(
                "pre-target Helm source SConfig writer resumed outside its durable scale intent."
            )
        if str(state.get("scale_patch_resource_version") or "") != identity["resourceVersion"]:
            state["scale_patch_resource_version"] = identity["resourceVersion"]
            state["scale_patch_rv_refreshed_at"] = _utc_now()
            checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"deployment/{_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME}",
            replicas=0,
            current_replicas=original_replicas,
            resource_version=identity["resourceVersion"],
        )
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        identity = _immutable_child_require_live_uid(
            deployment,
            expected_uid=str(checkpoint_deployment.get("uid") or ""),
            label="pre-target Helm source SConfig Deployment zero proof",
        )
        live_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
            deployment,
            label="pre-target Helm source SConfig Deployment zero proof",
        )
        live_generation = _legacy_rootfs_positive_generation(
            deployment,
            label="pre-target Helm source SConfig Deployment zero proof",
        )
        live_status = _mapping(deployment.get("status"))
        pods = _pre_target_helm_sconfig_writer_pods(
            selector=selector,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        zero = bool(
            _resource_replicas(deployment, default=-1) == 0
            and _non_negative_int(live_status.get("replicas"), fallback=0) == 0
            and _non_negative_int(live_status.get("readyReplicas"), fallback=0) == 0
            and _non_negative_int(live_status.get("observedGeneration"), fallback=0)
            >= live_generation
            and not pods
        )
        if live_fingerprint != str(checkpoint_deployment.get("spec_fingerprint") or ""):
            raise SoperatorMigrationPhasePending(
                "pre-target Helm source SConfig Deployment changed outside the replica fence."
            )
        if zero:
            expected_generation = _positive_int(
                state.get(
                    "zero_generation"
                    if state.get("scale_mode") == "adopted-deployed-target-recovery"
                    else "scale_expected_generation"
                ),
                fallback=0,
            )
            if live_generation != expected_generation:
                raise SoperatorMigrationPhasePending(
                    "pre-target Helm source SConfig zero proof crossed an unbounded generation."
                )
            state.update(
                {
                    "status": "verified",
                    "zero_generation": live_generation,
                    "zero_resource_version": identity["resourceVersion"],
                    "writer_pod_count": 0,
                    "verified_at": state.get("verified_at") or _utc_now(),
                }
            )
            checkpoint_writer()
            return [
                "Pre-target Helm SConfig writer fence verified: the exact source writer "
                "Deployment and selector-bound Pods are at zero before target CR apply."
            ]
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "pre-target Helm source SConfig writer did not converge to a stable zero."
            )
        time.sleep(max(poll_interval_seconds, 0.0))


def _verify_source_reconciliation_fence_after_target_helm(
    *,
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    state = _mapping(phase.get("source_reconciliation_fence"))
    if (
        state.get("schema") != _SOURCE_RECONCILIATION_FENCE_SCHEMA
        or state.get("status") != "verified"
    ):
        raise SoperatorMigrationPhasePending(
            "target Helm reconciliation lacks its verified source reconciliation fence."
        )
    desired_resources = _source_reconciliation_fence_resources(state=state)
    bindings = {
        str(item.get("kind") or ""): item
        for item in _sequence_of_mappings(state.get("managed_resource_bindings"))
    }
    for desired in desired_resources:
        exists, live = _source_reconciliation_fence_get_managed_resource(
            desired=desired,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if not exists:
            raise SoperatorMigrationPhasePending(
                "target Helm reconciliation removed a source reconciliation fence resource."
            )
        binding = _source_reconciliation_fence_managed_binding(
            desired=desired,
            live=live,
            operation_id=str(state.get("operation_id") or ""),
        )
        if binding["uid"] != str(_mapping(bindings.get(binding["kind"])).get("uid") or ""):
            raise SoperatorMigrationPhasePending(
                "target Helm reconciliation replaced a source reconciliation fence resource."
            )
    exists, manager = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="deployment/soperator-manager",
    )
    service_account_name = str(
        _mapping(_mapping(_mapping(manager.get("spec")).get("template")).get("spec")).get(
            "serviceAccountName"
        )
        or ""
    ).strip()
    if (
        not exists
        or service_account_name
        != str(_mapping(state.get("manager_service_account")).get("name") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "target Soperator manager did not use the exact service account protected by "
            "the source reconciliation fence."
        )
    source_binding = _mapping(state.get("source"))
    accounting = _mapping(phase.get("accounting_handoff"))
    retirement = _mapping(accounting.get("source_orphan_finalizer_recovery"))
    retirement_source = _mapping(retirement.get("source"))
    source_retired = bool(
        str(phase.get("source_accounting_owner_retired_at") or "").strip()
        and retirement.get("status") == "verified"
        and str(retirement.get("verified_at") or "").strip()
        and all(
            str(retirement_source.get(key) or "").strip()
            == str(source_binding.get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        )
    )
    if source_retired:
        live_source = _accounting_handoff_optional_exact_slurmcluster(
            command_runner=command_runner,
            kube_context=kube_context,
            binding=source_binding,
            label="retired post-Helm source reconciliation fence",
        )
        prior_canary = _mapping(state.get("canary"))
        if (
            live_source is not None
            or prior_canary.get("status") != "denied-by-policy"
            or prior_canary.get("policy_name")
            != str(_mapping(state.get("resource_names")).get("policy") or "")
            or not str(prior_canary.get("response_sha256") or "").strip()
            or not str(prior_canary.get("verified_at") or "").strip()
        ):
            raise SoperatorMigrationPhasePending(
                "post-Helm source reconciliation fence cannot adopt source absence "
                "without its exact retired UID and prior policy-attributed denial."
            )
        return
    _source_reconciliation_fence_canary(
        state=state,
        command_runner=command_runner,
        kube_context=kube_context,
    )


def _migrate_accounting_handoff_writer_fences_v1_to_v2(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    values: Mapping[str, Any],
    expected_version: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Rewrite one exact verified v1 fence pair to the hash-only v2 schema."""

    state = _accounting_handoff_state(phase)
    gate_keys = ("source_writer_command_fence", "target_writer_command_fence")
    if all(key not in state for key in gate_keys):
        return []
    raw_gates = tuple(state.get(key) for key in gate_keys)
    schemas = tuple(str(_mapping(gate).get("schema") or "").strip() for gate in raw_gates)
    source_binding = _accounting_handoff_source_binding(phase=phase, state=state)
    target_binding = _accounting_handoff_target_binding(phase=phase, state=state)
    bindings = (source_binding, target_binding)
    handoff_status = str(state.get("status") or "").strip()
    if handoff_status == "source-snapshot" and all(
        schema in {"", _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA} for schema in schemas
    ):
        source_gate = _mapping(raw_gates[0])
        target_gate = _mapping(raw_gates[1])
        if not source_gate or (
            target_gate
            and str(source_gate.get("status") or "").strip() not in {"applied", "verified"}
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff source-snapshot writer command-fence progression is "
                "not source-before-target."
            )
        for raw_gate, binding, label in zip(
            raw_gates,
            bindings,
            ("source", "target"),
            strict=True,
        ):
            if raw_gate is None:
                continue
            gate = _mapping(raw_gate)
            gate_binding = {
                key: str(_mapping(gate.get("binding")).get(key) or "").strip()
                for key in ("namespace", "name", "uid")
            }
            if (
                not isinstance(raw_gate, dict)
                or gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
                or gate_binding != binding
                or str(gate.get("status") or "").strip()
                not in {"fence-intent", "applied", "verified"}
                or "original_writer_config" in gate
                or not isinstance(gate.get("original_enabled"), bool)
            ):
                raise SoperatorMigrationPhasePending(
                    f"accounting handoff {label} source-snapshot writer command-fence "
                    "checkpoint is not the exact hash-only bound schema."
                )
            _accounting_handoff_validated_writer_config_identity(
                gate.get("original_writer_identity"),
                label=f"{label} source-snapshot checkpoint",
            )
        return []
    if schemas == (
        _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA,
        _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA,
    ):
        if handoff_status in {
            "source-dumped",
            "importing",
            "import-reconciled",
            "imported-paused",
        }:
            expected_gate_statuses = ({"verified"}, {"verified"})
        elif handoff_status == "target-enabling":
            expected_gate_statuses = (
                {"verified"},
                {"verified", "restore-intent", "restored"},
            )
        elif handoff_status in {"target-enabled", "verified"}:
            expected_gate_statuses = ({"verified"}, {"restored"})
        else:
            raise SoperatorMigrationPhasePending(
                "accounting handoff v2 writer command-fence pair is not at a supported "
                "handoff status boundary."
            )
        for raw_gate, binding, label in zip(
            raw_gates,
            bindings,
            ("source", "target"),
            strict=True,
        ):
            gate = _mapping(raw_gate)
            gate_binding = {
                key: str(_mapping(gate.get("binding")).get(key) or "").strip()
                for key in ("namespace", "name", "uid")
            }
            expected_statuses = expected_gate_statuses[0 if label == "source" else 1]
            if (
                not isinstance(raw_gate, dict)
                or gate_binding != binding
                or str(gate.get("status") or "").strip() not in expected_statuses
                or "original_writer_config" in gate
                or not isinstance(gate.get("original_enabled"), bool)
            ):
                raise SoperatorMigrationPhasePending(
                    f"accounting handoff {label} v2 writer command-fence checkpoint is "
                    "not the exact hash-only bound schema."
                )
            _accounting_handoff_validated_writer_config_identity(
                gate.get("original_writer_identity"),
                label=f"{label} v2 checkpoint",
            )
        return []
    if schemas != (
        _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_V1_SCHEMA,
        _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_V1_SCHEMA,
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff writer command-fence checkpoint schemas are mixed or "
            "unsupported; cxcli will not partially migrate the pair."
        )
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "accounting handoff writer command-fence migration requires a durable "
            "checkpoint writer."
        )

    expected_gate_keys = {
        "schema",
        "binding",
        "status",
        "original_enabled",
        "original_writer_config",
        "observed_resource_version",
        "pre_fence_deployment_uid",
        "pre_fence_replica_sets",
        "intent_recorded_at",
        "applied_resource_version",
        "applied_at",
        "verified_at",
    }
    expected_config_keys = {"command_present", "command", "args_present", "args"}
    identities: list[dict[str, Any]] = []
    gates: list[dict[str, Any]] = []
    for raw_gate, binding, label in zip(
        raw_gates,
        bindings,
        ("source", "target"),
        strict=True,
    ):
        if not isinstance(raw_gate, dict) or set(raw_gate) != expected_gate_keys:
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} v1 writer command-fence checkpoint has an "
                "unexpected shape."
            )
        gate = dict(copy.deepcopy(to_plain_data(raw_gate)))
        gate_binding = {
            key: str(_mapping(gate.get("binding")).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        raw_config = gate.get("original_writer_config")
        replica_sets = gate.get("pre_fence_replica_sets")
        if (
            gate.get("status") != "verified"
            or gate_binding != binding
            or not isinstance(gate.get("original_enabled"), bool)
            or (label == "target" and gate.get("original_enabled") is not True)
            or not all(
                str(gate.get(key) or "").strip()
                for key in (
                    "observed_resource_version",
                    "pre_fence_deployment_uid",
                    "intent_recorded_at",
                    "applied_resource_version",
                    "applied_at",
                    "verified_at",
                )
            )
            or not isinstance(replica_sets, Sequence)
            or isinstance(replica_sets, (str, bytes, bytearray))
            or any(not str(item or "").strip() for item in replica_sets)
            or not isinstance(raw_config, Mapping)
            or set(raw_config) != expected_config_keys
        ):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} v1 writer command-fence checkpoint is "
                "incomplete or bound to different evidence."
            )
        identity = _accounting_handoff_writer_config_identity(raw_config)
        if _accounting_handoff_writer_command_is_fenced(
            {"spec": {"slurmNodes": {"accounting": {"slurmdbd": dict(to_plain_data(raw_config))}}}}
        ):
            raise SoperatorMigrationPhasePending(
                f"accounting handoff {label} v1 checkpoint cannot treat the canonical "
                "fence as its original writer command."
            )
        gates.append(gate)
        identities.append(identity)

    seal = _mapping(state.get("source_dump_seal"))
    expected_seal_keys = {
        "schema",
        "mode",
        "status",
        "dump_sha256",
        "dump_generation",
        "source_pvc",
        "source_pvc_uid",
        "target_pvc",
        "target_pvc_uid",
        "source_fence_resource_version",
        "target_fence_resource_version",
        "source_history",
        "sealed_at",
    }
    dump = _mapping(state.get("dump"))
    if (
        set(seal) != expected_seal_keys
        or set(dump) != {"path", "size_bytes", "sha256", "semantic_sha256"}
        or _positive_int(state.get("source_dump_generation"), fallback=0) <= 0
        or not str(seal.get("sealed_at") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff v1 writer command-fence migration requires the exact "
            "sealed final dump checkpoint shape."
        )
    fence_resource_versions = (
        str(seal.get("source_fence_resource_version") or "").strip(),
        str(seal.get("target_fence_resource_version") or "").strip(),
    )
    if any(
        not sealed_resource_version
        or sealed_resource_version != str(gate.get("applied_resource_version") or "").strip()
        for gate, sealed_resource_version in zip(gates, fence_resource_versions, strict=True)
    ):
        raise SoperatorMigrationPhasePending(
            "accounting handoff v1 writer command-fence resource versions no longer "
            "match the sealed final source dump."
        )

    candidate_state = dict(copy.deepcopy(to_plain_data(state)))
    for gate_key, gate, identity in zip(gate_keys, gates, identities, strict=True):
        candidate_gate = dict(gate)
        candidate_gate.pop("original_writer_config", None)
        candidate_gate["schema"] = _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        candidate_gate["original_writer_identity"] = identity
        candidate_state[gate_key] = candidate_gate
    candidate_phase = dict(copy.deepcopy(to_plain_data(phase)))
    candidate_phase["accounting_handoff"] = candidate_state

    _accounting_handoff_reuse_sealed_source_dump(
        state=candidate_state,
        source_binding=source_binding,
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=None,
        expected_fence_resource_versions=fence_resource_versions,
    )
    _prove_target_soperator_helm_apply(
        phase=candidate_phase,
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        values=values,
        expected_version=expected_version,
        require_command_fence_override=True,
        recovered_from_live_state=True,
    )
    candidate_state["writer_command_fence_schema_migration"] = {
        "schema": _ACCOUNTING_HANDOFF_WRITER_FENCE_MIGRATION_SCHEMA,
        "status": "complete",
        "from_schema": _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_V1_SCHEMA,
        "to_schema": _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA,
        "migrated_at": _utc_now(),
    }

    original_state = dict(copy.deepcopy(to_plain_data(state)))
    with _checkpoint_mutation(checkpoint_writer):
        state.clear()
        state.update(candidate_state)
        try:
            checkpoint_writer()
        except BaseException:
            state.clear()
            state.update(original_state)
            raise
    return [
        "Accounting handoff migrated the exact verified writer command-fence pair from "
        "v1 raw command state to v2 hash-only identities after revalidating the sealed dump."
    ]


def _recover_target_handoff_values_revision_from_live_proof(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    values: Mapping[str, Any],
    expected_version: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    accounting_handoff = _mapping(phase.get("accounting_handoff"))
    target_writer_gate_started = bool(
        _mapping(accounting_handoff.get("target_writer_gate"))
    ) or any(
        key in accounting_handoff
        for key in ("source_writer_command_fence", "target_writer_command_fence")
    )
    target_apply_started = bool(
        _mapping(phase.get("target_handoff_values_apply_intent"))
        or str(phase.get("target_values_apply_started_at") or "").strip()
    )
    if not target_writer_gate_started and not target_apply_started:
        return []
    if not _mapping(phase.get("slurmcluster_handoff_binding")):
        _checkpoint_live_target_slurmcluster_handoff_binding(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            checkpoint_writer=None,
        )
    lines = _migrate_accounting_handoff_writer_fences_v1_to_v2(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        values=values,
        expected_version=expected_version,
        checkpoint_writer=checkpoint_writer,
    )
    if (
        _non_negative_int(phase.get("target_handoff_values_revision"), fallback=0)
        == _ROLLING_COMPUTE_VALUES_REVISION
    ):
        return lines
    if not target_writer_gate_started:
        pending_recovery_lines = _prepare_interrupted_target_soperator_helm_replay(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            values=values,
            checkpoint_writer=checkpoint_writer,
        )
        if pending_recovery_lines:
            return [*lines, *pending_recovery_lines]
    if target_writer_gate_started and _accounting_handoff_target_helm_replay_is_safe(phase):
        return [
            *lines,
            "Target accounting handoff is fully restored and the source owner is absent; "
            "the new target values revision will be replayed without a writer fence.",
        ]
    return [
        *lines,
        *_checkpoint_proven_target_soperator_helm_apply(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            values=values,
            expected_version=expected_version,
            require_command_fence_override=target_writer_gate_started,
            recovered_from_live_state=True,
            checkpoint_writer=checkpoint_writer,
        ),
    ]


def _execute_rolling_compute_migration_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    worker_node_groups: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    accounting_handoff_artifact_dir: Path | None = None,
    checkpoint_writer: Callable[[], None] | None = None,
    job_policy: str | None = None,
    populate_jail_refresh: str = "auto",
    cancel_job_ids: Sequence[str] = (),
    requeue_job_ids: Sequence[str] = (),
    job_wait_timeout_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_WAIT_TIMEOUT_SECONDS,
    job_refresh_interval_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_REFRESH_INTERVAL_SECONDS,
    slurm_scheduling_pause: bool = True,
    login_session_policy: str = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
    login_session_drain_timeout_seconds: int = 0,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None = None,
    interactive_prompt_pause: Callable[[], Any] | None = None,
    allow_resolved_interactive_job_policy: bool = False,
    mutation_guard: Callable[[], None] | None = None,
    impact_reporter: Callable[[str], None] | None = None,
    in_place_ownership_handoff_only: bool = False,
    handoff_values: Mapping[str, Any] | None = None,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, "rolling-compute-migration")
    nodes = _nodes_for_worker_groups(
        source_report=source_report,
        worker_node_groups=worker_node_groups,
    )
    phase["worker_nodes"] = list(nodes)
    source_snapshot = _mapping(source_report.get("snapshot"))
    if not _has_soperator_custom_resources(source_snapshot) and not _has_soperator_custom_resources(
        live_snapshot
    ):
        phase["skipped_reason"] = "no Soperator Slurm custom resources were detected"
        return False, [
            "Compute migration skipped: no Slurm custom resources were detected on the source cluster."
        ]
    compute_migration = _compute_migration_contract(payload, target_ref)
    if (
        compute_migration.get("mode") == COMPUTE_MIGRATION_MODE_IN_PLACE
        and not in_place_ownership_handoff_only
    ):
        return _execute_in_place_compute_migration_phase(
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            live_snapshot=live_snapshot,
            target_ref=target_ref,
            kube_context=kube_context,
            nebius_api=nebius_api,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            job_policy=job_policy,
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            job_wait_timeout_seconds=job_wait_timeout_seconds,
            job_refresh_interval_seconds=job_refresh_interval_seconds,
            slurm_scheduling_pause=slurm_scheduling_pause,
            slurm_decision_recorder=slurm_decision_recorder,
            interactive_prompt_pause=interactive_prompt_pause,
            allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
            impact_reporter=impact_reporter,
        )
    if in_place_ownership_handoff_only:
        _checkpoint_in_place_login_handoff_binding(
            checkpoint=checkpoint,
            checkpoint_writer=checkpoint_writer,
        )
    pre_mutation_lines = _ensure_continuous_worker_slurm_pause(
        checkpoint=checkpoint,
        source_report=source_report,
        worker_node_groups=worker_node_groups,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        job_policy=str(job_policy or "preserve"),
        cancel_job_ids=cancel_job_ids,
        requeue_job_ids=requeue_job_ids,
        job_wait_timeout_seconds=job_wait_timeout_seconds,
        job_refresh_interval_seconds=job_refresh_interval_seconds,
        slurm_decision_recorder=slurm_decision_recorder,
        interactive_prompt_pause=interactive_prompt_pause,
        allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
        slurm_scheduling_pause=slurm_scheduling_pause,
    )
    accounting_handoff = _mapping(phase.get("accounting_handoff"))
    writer_fence_checkpoint_started = bool(
        _mapping(accounting_handoff.get("target_writer_gate"))
    ) or any(
        key in accounting_handoff
        for key in ("source_writer_command_fence", "target_writer_command_fence")
    )
    if writer_fence_checkpoint_started:
        pre_mutation_values = (
            copy.deepcopy(dict(handoff_values))
            if handoff_values is not None
            else _patch_target_values_for_compute(
                payload=payload,
                target_ref=target_ref,
                checkpoint=checkpoint,
                source_report=source_report,
                live_snapshot=live_snapshot,
            )
        )
        pre_mutation_values = _target_values_gated_by_controller_bridge(
            checkpoint=checkpoint,
            values=pre_mutation_values,
            checkpoint_writer=checkpoint_writer,
        )
        pre_mutation_lines.extend(
            _recover_target_handoff_values_revision_from_live_proof(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=pre_mutation_values,
                expected_version=str(
                    _mapping(source_report.get("report")).get("target_version", "") or ""
                ),
                checkpoint_writer=checkpoint_writer,
            )
        )
    if in_place_ownership_handoff_only:
        mutation_performed = False
        lines = [
            "In-place Soperator ownership handoff reuses the accepted provider node groups; "
            "no replacement group was created."
        ]
    else:
        mutation_performed, lines = _create_or_reuse_target_node_groups(
            checkpoint=checkpoint,
            payload=payload,
            target_ref=target_ref,
            source_report=source_report,
            worker_node_groups=worker_node_groups,
            nebius_api=nebius_api,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
        lines.extend(
            _verify_target_worker_replacement_node_groups(
                checkpoint=checkpoint,
                nebius_api=nebius_api,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
    lines = [*pre_mutation_lines, *lines]
    if checkpoint_writer is not None:
        checkpoint_writer()
    live_source_slurmcluster_present = _live_source_slurmcluster_present(
        command_runner=command_runner,
        kube_context=kube_context,
        source_report=source_report,
        target_ref=target_ref,
    )
    phase["live_source_slurmcluster_present"] = live_source_slurmcluster_present
    live_worker_slurm_nodes = _external_upgrade_worker_nodeset_slurm_nodes(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    quiet_nodes = live_worker_slurm_nodes or nodes
    phase["slurm_job_scope_nodes"] = list(quiet_nodes)
    phase["slurm_job_scope"] = (
        "live-worker-nodesets" if live_worker_slurm_nodes else "source-worker-node-groups"
    )
    external_phase = _phase_state(checkpoint, _EXTERNAL_NODE_TEMPLATE_PHASE_ID)
    bridge_pause_records = tuple(
        _bridge_partition_record(item)
        for item in _sequence_of_mappings(
            _mapping(checkpoint.get("controller_bridge")).get("partition_pause")
        )
    )
    inherited_slurm_pause_records = _merge_slurm_partition_pause_records(
        bridge_pause_records,
        _rolling_compute_checkpoint_pause_records(external_phase),
    )
    checkpointed_slurm_pause_records = _merge_slurm_partition_pause_records(
        inherited_slurm_pause_records,
        _rolling_compute_checkpoint_pause_records(phase),
    )
    if inherited_slurm_pause_records:
        phase["slurm_pause_inherited_from"] = [
            source
            for source, records in (
                (_CONTROLLER_HA_BRIDGE_PHASE_ID, bridge_pause_records),
                (
                    _EXTERNAL_NODE_TEMPLATE_PHASE_ID,
                    _rolling_compute_checkpoint_pause_records(external_phase),
                ),
            )
            if records
        ]
        phase["slurm_paused_partitions"] = [
            record.as_payload() for record in checkpointed_slurm_pause_records
        ]
        phase["slurm_partition_restore_manual_command"] = (
            _external_upgrade_slurm_partition_recovery_inspection_command(
                checkpointed_slurm_pause_records
            )
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    slurm_pause_records = checkpointed_slurm_pause_records

    def _record_slurm_pause_intent(record: SlurmPartitionPauseRecord) -> None:
        _checkpoint_slurm_partition_pause_intent(
            phase=phase,
            record=record,
            checkpoint_writer=checkpoint_writer,
        )

    slurm_pause_outcome_checkpointed = phase.get("slurm_paused_partitions") is not None
    target_handoff_resume = (
        slurm_pause_outcome_checkpointed and _rolling_compute_target_handoff_started(phase)
    )
    if target_handoff_resume:
        if checkpointed_slurm_pause_records:
            quiet_lines = [
                "Slurm quiet window check reused checkpointed partition pause from the "
                "target-applied rolling compute resume."
            ]
        else:
            quiet_lines = [
                "Slurm quiet window check reused checkpointed pre-handoff success: no "
                "affected UP partitions required cxcli scheduling changes before target "
                "values were applied."
            ]
    else:
        try:
            quiet_lines, live_slurm_pause_records = _ensure_slurm_quiet(
                command_runner=command_runner,
                kube_context=kube_context,
                node_names=quiet_nodes,
                job_policy=job_policy,
                cancel_job_ids=cancel_job_ids,
                requeue_job_ids=requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                slurm_decision_recorder=slurm_decision_recorder,
                slurm_pause_intent_recorder=_record_slurm_pause_intent,
                allow_missing_login_recovery=not live_source_slurmcluster_present,
                interactive_prompt_pause=interactive_prompt_pause,
                allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
                slurm_scheduling_pause=slurm_scheduling_pause,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                held_job_checkpoint_writer=checkpoint_writer,
                slurm_action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
                slurm_action_checkpoint_writer=checkpoint_writer,
                slurm_controller_authority_provider=lambda: (
                    _external_upgrade_slurm_action_authority(checkpoint)
                ),
            )
            slurm_pause_records = _merge_slurm_partition_pause_records(
                checkpointed_slurm_pause_records,
                live_slurm_pause_records,
            )
            if checkpointed_slurm_pause_records and not live_slurm_pause_records:
                quiet_lines.append(
                    "Slurm scheduling pause: reused checkpointed partition restore state."
                )
        except RuntimeError as exc:
            if not slurm_pause_records or not _slurm_handoff_mismatch_detail(str(exc)):
                raise
            phase["legacy_markerless_target_handoff_inferred_at"] = _utc_now()
            target_handoff_resume = True
            quiet_lines = [
                "Slurm quiet window check reused checkpointed partition pause after "
                "a markerless resume observed target-era Slurm config handoff."
            ]
    phase["slurm_paused_partitions"] = [record.as_payload() for record in slurm_pause_records]
    if slurm_pause_records:
        phase["slurm_partition_restore_manual_command"] = (
            _external_upgrade_slurm_partition_recovery_inspection_command(slurm_pause_records)
        )
    try:
        lines.extend(
            _ensure_worker_nodeset_topology_checkpoint(
                checkpoint=checkpoint,
                source_report=source_report,
                kube_context=kube_context,
                command_runner=command_runner,
                nodeset_names=_target_worker_nodeset_names(
                    _target_soperator_values(payload, target_ref)
                ),
            )
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        ungated_values = (
            copy.deepcopy(dict(handoff_values))
            if handoff_values is not None
            else _patch_target_values_for_compute(
                payload=payload,
                target_ref=target_ref,
                checkpoint=checkpoint,
                source_report=source_report,
                live_snapshot=live_snapshot,
            )
        )
        target_version = str(_mapping(source_report.get("report")).get("target_version", "") or "")
        _delete_pending_accounting_pvcs(
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
        )
        checkpoint_worker_groups = tuple(
            str(group or "") for group in checkpoint.get("worker_node_groups", []) or []
        )
        _reconcile_target_node_storage_labels(
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            worker_node_groups=checkpoint_worker_groups,
        )
        source_login_pod_names = _login_pod_names(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        service_identity_before = _login_service_identities(
            command_runner=command_runner,
            kube_context=kube_context,
            required=True,
        )
        raw_allocation_operations = phase.setdefault("login_allocation_operations", {})
        if not isinstance(raw_allocation_operations, dict):
            raise RuntimeError(
                "recovery-required: rolling-compute login allocation operation state "
                "must be a mapping."
            )
        service_identity_before, allocation_decisions, allocation_lines = (
            stabilize_soperator_login_load_balancer_allocations(
                command_runner=command_runner,
                kube_context=kube_context,
                project_id=_nebius_project_id(payload),
                nebius_api=nebius_api,
                values=ungated_values,
                service_identities=service_identity_before,
                checkpoint=checkpoint,
                operation_states=raw_allocation_operations,
                checkpoint_writer=checkpoint_writer,
            )
        )
        lines.extend(allocation_lines)
        _assert_login_service_stable_load_balancer_preconditions(service_identity_before)
        checkpointed_ssh_digest = _expected_source_sshd_host_key_data_sha256(
            checkpoint=checkpoint,
            phase=phase,
        )
        phase["login_continuity"] = {
            **dict(_mapping(phase.get("login_continuity"))),
            "service_identity_before_handoff": [
                dict(to_plain_data(item)) for item in service_identity_before
            ],
            "login_load_balancer_allocation": [
                decision.as_payload() for decision in allocation_decisions
            ],
            "source_login_pods_before_handoff": list(source_login_pod_names),
            "session_policy": login_session_policy,
            "session_drain_timeout_seconds": login_session_drain_timeout_seconds,
        }
        ssh_identity = _preserve_source_sshd_host_key_secret(
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            target_ref=target_ref,
            values=ungated_values,
            expected_host_key_data_sha256=checkpointed_ssh_digest,
        )
        target_login = _mapping(_mapping(ungated_values.get("slurmNodes")).get("login"))
        root_public_keys = target_login.get("sshRootPublicKeys")
        ssh_identity["root_public_key_count"] = (
            len(root_public_keys)
            if isinstance(root_public_keys, Sequence)
            and not isinstance(root_public_keys, (str, bytes, bytearray))
            else 0
        )
        phase["login_continuity"]["ssh_identity"] = ssh_identity
        lines.append(
            "Login SSH identity prepared: "
            f"root public keys={ssh_identity['root_public_key_count']}; host-key "
            f"Secret status={ssh_identity.get('status', 'unknown')}."
        )
        values = _target_values_gated_by_controller_bridge(
            checkpoint=checkpoint,
            values=ungated_values,
            checkpoint_writer=checkpoint_writer,
        )
        allow_slurm_smoke_defer = _rolling_compute_slurm_smoke_may_defer(
            checkpoint=checkpoint,
            phase=phase,
        )
        lines.extend(
            _recover_target_handoff_values_revision_from_live_proof(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=values,
                expected_version=target_version,
                checkpoint_writer=checkpoint_writer,
            )
        )
        skip_target_helm = _rolling_compute_skip_target_helm_for_accounting_handoff(phase)
        target_helm_ordering_mode = _rolling_compute_target_helm_ordering_mode(
            phase,
            skip_target_helm=skip_target_helm,
        )
        (
            target_helm_intent_key,
            target_helm_proof_key,
            target_helm_semantic_drift_key,
        ) = _rolling_compute_target_helm_checkpoint_keys(target_helm_ordering_mode)
        lines.append(
            "Target controller staging: command-gated behind the active temporary HA bridge; "
            "service continuity is enforced without a downtime override."
        )
        if target_helm_ordering_mode == "restored-accounting-replay":
            lines.append(
                "Target Soperator Helm values revision replay is authorized by the exact "
                "retired-source and restored target accounting writer proof."
            )
        elif target_helm_ordering_mode == "fresh-target":
            lines.extend(
                _ensure_safe_fresh_target_helm_ordering(
                    checkpoint=checkpoint,
                    phase=phase,
                    source_report=source_report,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
        if (
            _source_accounting_handoff_required(
                checkpoint=checkpoint,
                source_report=source_report,
            )
            and accounting_handoff_artifact_dir is None
        ):
            raise SoperatorMigrationPhasePending(
                "accounting handoff requires a durable checkpoint artifact directory."
            )
        lines.extend(
            _prepare_accounting_handoff_source_dump(
                checkpoint=checkpoint,
                phase=phase,
                source_report=source_report,
                values=values,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
                artifact_dir=(
                    accounting_handoff_artifact_dir
                    if accounting_handoff_artifact_dir is not None
                    else Path(".")
                ),
                checkpoint_writer=checkpoint_writer,
            )
        )
        source_login_pod_names = _login_pod_names(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        phase["login_continuity"]["source_login_pods_before_handoff"] = list(source_login_pod_names)
        if skip_target_helm:
            lines.append(
                "Target Soperator Helm apply reused the checkpointed accounting-handoff "
                "values revision; no writer-enabling Helm replay was issued."
            )
        else:
            lines.extend(
                _checkpoint_target_soperator_helm_apply_intent(
                    phase=phase,
                    command_runner=command_runner,
                    target_ref=target_ref,
                    values=values,
                    expected_version=target_version,
                    checkpoint_writer=checkpoint_writer,
                    intent_key=target_helm_intent_key,
                    apply_started_at_key=(
                        f"target_values_reapply_started_at_v{_ROLLING_COMPUTE_VALUES_REVISION}"
                        if target_helm_ordering_mode == "restored-accounting-replay"
                        else "target_values_apply_started_at"
                    ),
                )
            )

            def _before_target_helm_reconcile() -> None:
                nonlocal source_login_pod_names
                lines.extend(
                    _enforce_target_helm_login_session_policy(
                        checkpoint=checkpoint,
                        phase=phase,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        policy=login_session_policy,
                        timeout_seconds=login_session_drain_timeout_seconds,
                        gate_key="target_helm_login_session_gate",
                        boundary="target handoff",
                        checkpoint_writer=checkpoint_writer,
                    )
                )
                source_login_pod_names = tuple(
                    _string_sequence(
                        _mapping(phase.get("target_helm_login_session_gate")).get("pods")
                    )
                )
                phase["login_continuity"]["source_login_pods_before_handoff"] = list(
                    source_login_pod_names
                )

            def _after_target_helm_reconcile() -> None:
                lines.extend(
                    _verify_login_session_gate_hold_after_helm(
                        gate=phase["target_helm_login_session_gate"],
                        checkpoint=checkpoint,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                )

            _helm_upgrade_target_soperator(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                expected_version=target_version,
                wait=False,
                before_reconcile=_before_target_helm_reconcile,
                after_reconcile=_after_target_helm_reconcile,
            )
            _verify_source_reconciliation_fence_after_target_helm(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
            )
        if skip_target_helm and phase.get("source_reconciliation_fence") is not None:
            _verify_source_reconciliation_fence_after_target_helm(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
            )
        _checkpoint_live_target_slurmcluster_handoff_binding(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            checkpoint_writer=None,
        )
        if not skip_target_helm:
            lines.extend(
                _checkpoint_proven_target_soperator_helm_apply(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    values=values,
                    expected_version=target_version,
                    require_command_fence_override=False,
                    recovered_from_live_state=False,
                    checkpoint_writer=checkpoint_writer,
                    intent_key=target_helm_intent_key,
                    proof_key=target_helm_proof_key,
                    semantic_drift_key=target_helm_semantic_drift_key,
                    promote_for_child_handoff=True,
                )
            )
        _accounting_handoff_state(phase)
        _immutable_child_handoff_state(phase)
        if _accounting_handoff_waits_for_target_config_restore(phase):
            lines.append(
                "Accounting history verification remains deferred until immutable-child "
                "handoff restores the target-version manager and the SConfig compatibility "
                "pulse materializes the active Jail slot."
            )
        else:
            lines.extend(
                _complete_accounting_handoff_import(
                    phase=phase,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
        try:
            lines.extend(
                _upgrade_controller_bridge_to_target_version(
                    checkpoint=checkpoint,
                    values=values,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                )
            )
        except (Exception, KeyboardInterrupt) as transition_error:
            recovery_lines = _restore_source_bridge_after_failed_target_transition(
                checkpoint=checkpoint,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
            if recovery_lines:
                raise SoperatorMigrationPhasePending(
                    "target-version controller transition failed before target write; "
                    "cxcli restored the exact source bridge 2/2 and proved bridge-0 primary: "
                    f"{transition_error}"
                ) from transition_error
            raise
        lines.extend(
            _suspend_legacy_flux_helmreleases(
                command_runner=command_runner,
                kube_context=kube_context,
                phase=phase,
            )
        )
        scaled_source_controller, scale_lines = _scale_down_legacy_soperator_controllers(
            command_runner=command_runner,
            kube_context=kube_context,
            phase=phase,
            target_version=str(
                _mapping(source_report.get("report")).get("target_version", "") or ""
            ),
            profile_group=_source_report_migration_profile_group(source_report),
            checkpoint_writer=checkpoint_writer,
        )
        mutation_performed = mutation_performed or scaled_source_controller
        lines.extend(scale_lines)
        if checkpoint_writer is not None:
            checkpoint_writer()
        accounting_handoff = _accounting_handoff_state(phase)
        if (
            str(accounting_handoff.get("status") or "").strip() == "verified"
            and not str(accounting_handoff.get("in_place_verified_at") or "").strip()
        ):
            lines.extend(
                _accounting_handoff_revalidate_verified_before_cleanup(
                    phase=phase,
                    state=accounting_handoff,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
        live_target_binding = _revalidate_live_target_slurmcluster_handoff(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            target_ref=target_ref,
        )
        if live_target_binding:
            lines.extend(
                _enforce_source_retirement_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    policy=login_session_policy,
                    timeout_seconds=login_session_drain_timeout_seconds,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            _checkpoint_source_cleanup_started(
                phase=phase,
                source_report=source_report,
                target_ref=target_ref,
                live_target_binding=live_target_binding,
                checkpoint_writer=checkpoint_writer,
            )
            source_resource_version_precondition, cleanup_lines = (
                _accounting_handoff_revalidate_source_cleanup_boundary(
                    phase=phase,
                    source_report=source_report,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            lines.extend(cleanup_lines)
            lines.extend(
                _enforce_source_retirement_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    policy=login_session_policy,
                    timeout_seconds=login_session_drain_timeout_seconds,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            source_resource_version_precondition = (
                _accounting_handoff_checkpoint_final_source_delete_preconditions(
                    phase=phase,
                    values=values,
                    held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            handoff_binding = _mapping(phase.get("slurmcluster_handoff_binding"))
            _checkpoint_immutable_child_handoff_inventory(
                phase=phase,
                state=_accounting_handoff_state(phase),
                source_report=source_report,
                values=values,
                source_binding=_mapping(handoff_binding.get("source")),
                target_binding=_mapping(handoff_binding.get("target")),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            lines.extend(
                _prepare_immutable_child_handoff_before_source_retirement(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                    controller_bridge=_mapping(checkpoint.get("controller_bridge")),
                )
            )
            _require_target_soperator_semantic_compatibility_for_child_handoff(phase)
            _delete_conflicting_source_slurm_resources(
                command_runner=command_runner,
                kube_context=kube_context,
                source_report=source_report,
                source_cleanup_state=_accounting_handoff_state(phase),
                target_ref=target_ref,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                target_slurmcluster_binding=live_target_binding,
                source_slurmcluster_resource_version=(source_resource_version_precondition),
                retire_slurmcluster_only=True,
                mutation_guard=mutation_guard,
                checkpoint_writer=checkpoint_writer,
            )
            _accounting_handoff_checkpoint_source_owner_retired(
                phase=phase,
                checkpoint_writer=checkpoint_writer,
            )
            _clear_worker_nodeset_ephemeral_storage_aliases(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                phase=phase,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
            lines.extend(
                _execute_immutable_child_handoff_before_target_readiness(
                    phase=phase,
                    values=ungated_values,
                    controller_bridge=dict(_mapping(checkpoint.get("controller_bridge"))),
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _verify_legacy_rootfs_bridge_after_manager_restore(
                    phase=phase,
                    populate_phase=_accepted_populate_jail_phase_state(checkpoint),
                    handoff=_immutable_child_handoff_state(phase),
                    source_binding=_mapping(handoff_binding.get("source")),
                    target_binding=_mapping(handoff_binding.get("target")),
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _accounting_handoff_complete_after_source_retirement(
                    phase=phase,
                    values=values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            if in_place_ownership_handoff_only:
                phase["in_place_ownership_handoff"] = {
                    "status": "target-children-created",
                    "target_values_fingerprint": _fingerprint(ungated_values),
                    "completed_at": _utc_now(),
                }
                mutation_performed = True
                if checkpoint_writer is not None:
                    checkpoint_writer()
                return mutation_performed, [
                    *lines,
                    "In-place immutable ownership handoff created target workloads while "
                    "the temporary controller bridge and exact protected login Pods remain active.",
                ]
            lines.extend(
                _handoff_controller_bridge_to_target_singleton(
                    checkpoint=checkpoint,
                    ungated_values=ungated_values,
                    target_ref=target_ref,
                    expected_version=target_version,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            values = ungated_values
            lines.extend(
                _ensure_rolling_login_continuity(
                    phase=phase,
                    checkpoint=checkpoint,
                    checkpoint_writer=checkpoint_writer,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    service_identity_before=service_identity_before,
                    source_login_pod_names=source_login_pod_names,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                    allow_degraded_slurm_smoke=allow_slurm_smoke_defer,
                    session_policy_applied_before_mutation=True,
                )
            )
            accounting_handoff = _accounting_handoff_state(phase)
            _accounting_handoff_require_target_control_plane_ready(
                state=accounting_handoff,
                target_binding=live_target_binding,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            target_worker_bindings = _wait_for_target_worker_nodesets_ready(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                timeout_seconds=1800,
                expected_slurmcluster_binding=live_target_binding,
            )
            accounting_handoff["target_worker_workload_bindings"] = target_worker_bindings
            accounting_handoff["target_worker_workload_bindings_recorded_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
            lines.extend(
                _complete_accounting_handoff_import(
                    phase=phase,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _complete_immutable_child_handoff_after_target_readiness(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            _delete_conflicting_source_slurm_resources(
                command_runner=command_runner,
                kube_context=kube_context,
                source_report=source_report,
                source_cleanup_state=_accounting_handoff_state(phase),
                target_ref=target_ref,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                target_slurmcluster_binding=live_target_binding,
                mutation_guard=mutation_guard,
                checkpoint_writer=checkpoint_writer,
            )
            phase["source_cleanup_completed_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
    except (Exception, KeyboardInterrupt):
        if inherited_slurm_pause_records:
            phase["slurm_partition_restore_deferred_reason"] = (
                "continuous scheduling pause remains active until target Soperator "
                "workers pass the exact GPU workload release gate"
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise
        accounting_handoff = _mapping(phase.get("accounting_handoff"))
        accounting_status = str(accounting_handoff.get("status", "") or "")
        accounting_cleanup_incomplete = _accounting_handoff_cleanup_incomplete(phase)
        immutable_child_handoff_incomplete = _immutable_child_handoff_incomplete(phase)
        if (
            accounting_status
            in {
                "source-snapshotting",
                "source-dumped",
                "importing",
                "import-reconciled",
                "imported-paused",
                "target-enabling",
                "target-enabled",
                "in-place-pending",
            }
            or accounting_cleanup_incomplete
            or immutable_child_handoff_incomplete
        ):
            phase["slurm_partition_restore_deferred_reason"] = (
                "accounting history or immutable-child ownership handoff is incomplete; "
                "scheduling remains paused until the same rolling-compute phase "
                "resumes successfully"
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise
        phase["slurm_partition_restore_deferred_reason"] = (
            "rolling-compute migration did not complete; exact partition pause state "
            "remains owned by the v6 checkpoint for roll-forward recovery"
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise
    _kubectl_rollout_status(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="deployment/soperator-manager",
        timeout="15m",
    )
    phase["preserved_worker_nodes"] = list(nodes)
    resume_lines = _resume_slurm_after_cutover(
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        phase=phase,
        values=values,
        checkpoint_writer=checkpoint_writer,
        slurm_pause_records=slurm_pause_records,
        cxcli_drained_node_names=_checkpoint_cxcli_owned_slurm_drains(phase),
        action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
    )
    if slurm_pause_records:
        phase["slurm_partition_restore_deferred_reason"] = (
            "target compute cutover passed; scheduling remains paused until final "
            "controller, action, Jail, worker, accounting, and login gates pass"
        )
        phase["slurm_pause_release_boundary"] = "before-controller-bridge-cleanup"
    phase["cxcli_drained_slurm_nodes"] = []
    phase["slurm_workload_release_gate_passed_at"] = _utc_now()
    mutation_performed = True
    phase["target_values_revision"] = _ROLLING_COMPUTE_VALUES_REVISION
    phase["target_values_applied_at"] = _utc_now()
    phase["slurm_quiet_window"] = "verified"
    if checkpoint_writer is not None:
        checkpoint_writer()
    return mutation_performed, [
        *lines,
        *quiet_lines,
        *resume_lines,
        "Target Soperator chart values applied to aligned service-role and worker replacements.",
        "Source worker nodes remain untouched until each allocation and epilog is clear.",
    ]


def _rolling_compute_values_revision(checkpoint: Mapping[str, Any]) -> int:
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    return max(
        _non_negative_int(rolling.get("target_values_revision"), fallback=0),
        _non_negative_int(rolling.get("target_handoff_values_revision"), fallback=0),
    )


def _reapply_stale_rolling_compute_values(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    nebius_api: SoperatorMigrationNebiusApi,
    checkpoint_writer: Callable[[], None] | None = None,
    job_policy: str = "preserve",
    cancel_job_ids: Sequence[str] = (),
    requeue_job_ids: Sequence[str] = (),
    job_wait_timeout_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_WAIT_TIMEOUT_SECONDS,
    job_refresh_interval_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_REFRESH_INTERVAL_SECONDS,
    slurm_scheduling_pause: bool = True,
    login_session_policy: str = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
    login_session_drain_timeout_seconds: int = 0,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None = None,
    interactive_prompt_pause: Callable[[], Any] | None = None,
    allow_resolved_interactive_job_policy: bool = False,
    mutation_guard: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    if _rolling_compute_values_revision(checkpoint) >= _ROLLING_COMPUTE_VALUES_REVISION:
        return False, []
    phase = _phase_state(checkpoint, "rolling-compute-migration")
    lines = _ensure_worker_nodeset_topology_checkpoint(
        checkpoint=checkpoint,
        source_report=source_report,
        kube_context=kube_context,
        command_runner=command_runner,
        nodeset_names=_target_worker_nodeset_names(_target_soperator_values(payload, target_ref)),
    )
    ungated_values = _patch_target_values_for_compute(
        payload=payload,
        target_ref=target_ref,
        checkpoint=checkpoint,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    values = _target_values_gated_by_controller_bridge(
        checkpoint=checkpoint,
        values=ungated_values,
        checkpoint_writer=checkpoint_writer,
    )
    checkpoint_worker_groups = tuple(
        str(group or "") for group in checkpoint.get("worker_node_groups", []) or []
    )
    source_login_pod_names = _login_pod_names(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    lines.extend(
        _wait_for_login_session_policy(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            policy=login_session_policy,
            timeout_seconds=login_session_drain_timeout_seconds,
            pod_names=source_login_pod_names,
        )
    )
    phase["values_reapply_login_session_gate"] = {
        "status": "passed",
        "policy": login_session_policy,
        "checked_at": _utc_now(),
        "pods": list(source_login_pod_names),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()

    live_worker_slurm_nodes = _external_upgrade_worker_nodeset_slurm_nodes(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    checkpoint_worker_nodes = tuple(
        str(node or "").strip()
        for node in phase.get("worker_nodes", []) or []
        if str(node or "").strip()
    )
    source_worker_nodes = _nodes_for_worker_groups(
        source_report=source_report,
        worker_node_groups=checkpoint_worker_groups,
    )
    quiet_nodes = live_worker_slurm_nodes or checkpoint_worker_nodes or source_worker_nodes
    if not quiet_nodes:
        raise SoperatorMigrationPhasePending(
            "completed compute cutover needs target-values reconciliation, but cxcli "
            "could not resolve the affected worker Slurm nodes. Rerun after worker "
            "NodeSet pods and Slurm node aliases are visible."
        )
    phase["values_reapply_slurm_job_scope_nodes"] = list(quiet_nodes)

    def _values_reapply_pause_records() -> tuple[SlurmPartitionPauseRecord, ...]:
        return _rolling_compute_checkpoint_pause_records(
            {"slurm_paused_partitions": phase.get("values_reapply_slurm_paused_partitions")}
        )

    def _record_values_reapply_slurm_decision(decision: Mapping[str, Any]) -> None:
        action = str(decision.get("action", "") or "")
        records = _slurm_decision_pause_records(decision)
        if action == "scheduling-pause-applied":
            records = _merge_slurm_partition_pause_records(
                _values_reapply_pause_records(),
                records,
            )
            phase["values_reapply_slurm_paused_partitions"] = [
                record.as_payload() for record in records
            ]
            phase["values_reapply_slurm_partition_restore_manual_command"] = (
                _external_upgrade_slurm_partition_recovery_inspection_command(records) or None
            )
        elif action == "scheduling-pause-restored":
            restored = {record.partition for record in records}
            remaining = tuple(
                record
                for record in _values_reapply_pause_records()
                if not restored or record.partition not in restored
            )
            phase["values_reapply_slurm_paused_partitions"] = [
                record.as_payload() for record in remaining
            ]
            phase["values_reapply_slurm_partition_restore_manual_command"] = (
                _external_upgrade_slurm_partition_recovery_inspection_command(remaining) or None
            )
        if slurm_decision_recorder is not None:
            slurm_decision_recorder(decision)
        if checkpoint_writer is not None:
            checkpoint_writer()

    def _record_values_reapply_slurm_intent(record: SlurmPartitionPauseRecord) -> None:
        _checkpoint_slurm_partition_pause_intent(
            phase=phase,
            record=record,
            checkpoint_writer=checkpoint_writer,
            records_key="values_reapply_slurm_paused_partitions",
            manual_command_key="values_reapply_slurm_partition_restore_manual_command",
        )

    checkpointed_pause_records = _values_reapply_pause_records()
    slurm_pause_records = checkpointed_pause_records
    try:
        quiet_lines, new_pause_records = _ensure_slurm_quiet(
            command_runner=command_runner,
            kube_context=kube_context,
            node_names=quiet_nodes,
            job_policy=job_policy,
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            job_wait_timeout_seconds=job_wait_timeout_seconds,
            job_refresh_interval_seconds=job_refresh_interval_seconds,
            slurm_decision_recorder=_record_values_reapply_slurm_decision,
            slurm_pause_intent_recorder=_record_values_reapply_slurm_intent,
            interactive_prompt_pause=interactive_prompt_pause,
            allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
            slurm_scheduling_pause=slurm_scheduling_pause,
            held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
            held_job_checkpoint_writer=checkpoint_writer,
            slurm_action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
            slurm_action_checkpoint_writer=checkpoint_writer,
            slurm_controller_authority_provider=lambda: _external_upgrade_slurm_action_authority(
                checkpoint
            ),
        )
        records_by_partition = {record.partition: record for record in checkpointed_pause_records}
        for record in new_pause_records:
            records_by_partition.setdefault(record.partition, record)
        slurm_pause_records = tuple(records_by_partition.values())
        phase["values_reapply_slurm_paused_partitions"] = [
            record.as_payload() for record in slurm_pause_records
        ]
        phase["values_reapply_slurm_partition_restore_manual_command"] = (
            _external_upgrade_slurm_partition_recovery_inspection_command(slurm_pause_records)
            or None
        )
        if checkpoint_writer is not None:
            checkpoint_writer()

        _delete_pending_accounting_pvcs(
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
        )
        _reconcile_target_node_storage_labels(
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            worker_node_groups=checkpoint_worker_groups,
        )
        service_identity_before = _login_service_identities(
            command_runner=command_runner,
            kube_context=kube_context,
            required=True,
        )
        raw_allocation_operations = phase.setdefault("login_allocation_operations", {})
        if not isinstance(raw_allocation_operations, dict):
            raise RuntimeError(
                "recovery-required: rolling-compute login allocation operation state "
                "must be a mapping."
            )
        service_identity_before, allocation_decisions, allocation_lines = (
            stabilize_soperator_login_load_balancer_allocations(
                command_runner=command_runner,
                kube_context=kube_context,
                project_id=_nebius_project_id(payload),
                nebius_api=nebius_api,
                values=values,
                service_identities=service_identity_before,
                checkpoint=checkpoint,
                operation_states=raw_allocation_operations,
                checkpoint_writer=checkpoint_writer,
            )
        )
        lines.extend(allocation_lines)
        _assert_login_service_stable_load_balancer_preconditions(service_identity_before)
        checkpointed_ssh_digest = _expected_source_sshd_host_key_data_sha256(
            checkpoint=checkpoint,
            phase=phase,
        )
        phase["login_continuity"] = {
            **dict(_mapping(phase.get("login_continuity"))),
            "service_identity_before_handoff": [
                dict(to_plain_data(item)) for item in service_identity_before
            ],
            "login_load_balancer_allocation": [
                decision.as_payload() for decision in allocation_decisions
            ],
            "source_login_pods_before_handoff": list(source_login_pod_names),
            "session_policy": login_session_policy,
            "session_drain_timeout_seconds": login_session_drain_timeout_seconds,
        }
        ssh_identity = _preserve_source_sshd_host_key_secret(
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            target_ref=target_ref,
            values=values,
            expected_host_key_data_sha256=checkpointed_ssh_digest,
        )
        target_login = _mapping(_mapping(values.get("slurmNodes")).get("login"))
        root_public_keys = target_login.get("sshRootPublicKeys")
        ssh_identity["root_public_key_count"] = (
            len(root_public_keys)
            if isinstance(root_public_keys, Sequence)
            and not isinstance(root_public_keys, (str, bytes, bytearray))
            else 0
        )
        phase["login_continuity"]["ssh_identity"] = ssh_identity
        lines.append(
            "Login SSH identity reconciled before target values reapply: "
            f"root public keys={ssh_identity['root_public_key_count']}; host-key "
            f"Secret status={ssh_identity.get('status', 'unknown')}."
        )
        source_login_pod_names = _login_pod_names(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        phase["login_continuity"]["source_login_pods_before_handoff"] = list(source_login_pod_names)
        phase.setdefault("target_values_apply_started_at", _utc_now())
        if checkpoint_writer is not None:
            checkpoint_writer()
        allow_slurm_smoke_defer = _rolling_compute_slurm_smoke_may_defer(
            checkpoint=checkpoint,
            phase=phase,
        )
        target_version = str(_mapping(source_report.get("report")).get("target_version", "") or "")
        reapply_suffix = str(_ROLLING_COMPUTE_VALUES_REVISION)
        reapply_intent_key = f"target_values_reapply_intent_v{reapply_suffix}"
        reapply_proof_key = f"target_values_reapply_proof_v{reapply_suffix}"
        reapply_semantic_drift_key = f"target_values_reapply_semantic_drift_v{reapply_suffix}"
        recover_existing_apply = _target_soperator_helm_apply_intent_requires_live_recovery(
            phase,
            values=values,
            intent_key=reapply_intent_key,
        )

        def _before_values_reapply_helm_reconcile() -> None:
            nonlocal source_login_pod_names
            lines.extend(
                _enforce_target_helm_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    policy=login_session_policy,
                    timeout_seconds=login_session_drain_timeout_seconds,
                    gate_key="values_reapply_final_login_session_gate",
                    boundary="target values reapply",
                    checkpoint_writer=checkpoint_writer,
                )
            )
            source_login_pod_names = tuple(
                _string_sequence(
                    _mapping(phase.get("values_reapply_final_login_session_gate")).get("pods")
                )
            )
            phase["login_continuity"]["source_login_pods_before_handoff"] = list(
                source_login_pod_names
            )

        def _after_values_reapply_helm_reconcile() -> None:
            lines.extend(
                _verify_login_session_gate_hold_after_helm(
                    gate=phase["values_reapply_final_login_session_gate"],
                    checkpoint=checkpoint,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )

        if recover_existing_apply:
            lines.append(
                "Target Soperator Helm reapply found a prior immutable intent whose "
                "derived current values changed; proving the exact live applied revision "
                "without replaying Helm."
            )
        else:
            lines.extend(
                _checkpoint_target_soperator_helm_apply_intent(
                    phase=phase,
                    command_runner=command_runner,
                    target_ref=target_ref,
                    values=values,
                    expected_version=target_version,
                    checkpoint_writer=checkpoint_writer,
                    intent_key=reapply_intent_key,
                    apply_started_at_key=(f"target_values_reapply_started_at_v{reapply_suffix}"),
                )
            )
            _helm_upgrade_target_soperator(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                expected_version=target_version,
                wait=False,
                before_reconcile=_before_values_reapply_helm_reconcile,
                after_reconcile=_after_values_reapply_helm_reconcile,
            )
        _checkpoint_live_target_slurmcluster_handoff_binding(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            checkpoint_writer=checkpoint_writer,
        )
        lines.extend(
            _checkpoint_proven_target_soperator_helm_apply(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=values,
                expected_version=target_version,
                require_command_fence_override=False,
                recovered_from_live_state=recover_existing_apply,
                checkpoint_writer=checkpoint_writer,
                intent_key=reapply_intent_key,
                proof_key=reapply_proof_key,
                semantic_drift_key=reapply_semantic_drift_key,
                promote_for_child_handoff=True,
            )
        )
        lines.extend(
            _suspend_legacy_flux_helmreleases(
                command_runner=command_runner,
                kube_context=kube_context,
                phase=phase,
            )
        )
        _scaled_source_controller, scale_lines = _scale_down_legacy_soperator_controllers(
            command_runner=command_runner,
            kube_context=kube_context,
            phase=phase,
            target_version=str(
                _mapping(source_report.get("report")).get("target_version", "") or ""
            ),
            profile_group=_source_report_migration_profile_group(source_report),
            checkpoint_writer=checkpoint_writer,
        )
        lines.extend(scale_lines)
        live_target_binding = _revalidate_live_target_slurmcluster_handoff(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            target_ref=target_ref,
        )
        if live_target_binding:
            lines.extend(
                _enforce_source_retirement_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    policy=login_session_policy,
                    timeout_seconds=login_session_drain_timeout_seconds,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            _checkpoint_source_cleanup_started(
                phase=phase,
                source_report=source_report,
                target_ref=target_ref,
                live_target_binding=live_target_binding,
                checkpoint_writer=checkpoint_writer,
            )
            source_resource_version_precondition, cleanup_lines = (
                _accounting_handoff_revalidate_source_cleanup_boundary(
                    phase=phase,
                    source_report=source_report,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            lines.extend(cleanup_lines)
            lines.extend(
                _enforce_source_retirement_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    policy=login_session_policy,
                    timeout_seconds=login_session_drain_timeout_seconds,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            source_resource_version_precondition = (
                _accounting_handoff_checkpoint_final_source_delete_preconditions(
                    phase=phase,
                    values=values,
                    held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            handoff_binding = _mapping(phase.get("slurmcluster_handoff_binding"))
            _checkpoint_immutable_child_handoff_inventory(
                phase=phase,
                state=_accounting_handoff_state(phase),
                source_report=source_report,
                values=values,
                source_binding=_mapping(handoff_binding.get("source")),
                target_binding=_mapping(handoff_binding.get("target")),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            lines.extend(
                _prepare_immutable_child_handoff_before_source_retirement(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                    controller_bridge=_mapping(checkpoint.get("controller_bridge")),
                )
            )
            _require_target_soperator_semantic_compatibility_for_child_handoff(phase)
            _delete_conflicting_source_slurm_resources(
                command_runner=command_runner,
                kube_context=kube_context,
                source_report=source_report,
                source_cleanup_state=_accounting_handoff_state(phase),
                target_ref=target_ref,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                target_slurmcluster_binding=live_target_binding,
                source_slurmcluster_resource_version=(source_resource_version_precondition),
                retire_slurmcluster_only=True,
                mutation_guard=mutation_guard,
                checkpoint_writer=checkpoint_writer,
            )
            _accounting_handoff_checkpoint_source_owner_retired(
                phase=phase,
                checkpoint_writer=checkpoint_writer,
            )
            _clear_worker_nodeset_ephemeral_storage_aliases(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                phase=phase,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
            lines.extend(
                _execute_immutable_child_handoff_before_target_readiness(
                    phase=phase,
                    values=ungated_values,
                    controller_bridge=dict(_mapping(checkpoint.get("controller_bridge"))),
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _verify_legacy_rootfs_bridge_after_manager_restore(
                    phase=phase,
                    populate_phase=_accepted_populate_jail_phase_state(checkpoint),
                    handoff=_immutable_child_handoff_state(phase),
                    source_binding=_mapping(handoff_binding.get("source")),
                    target_binding=_mapping(handoff_binding.get("target")),
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _accounting_handoff_complete_after_source_retirement(
                    phase=phase,
                    values=values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _ensure_rolling_login_continuity(
                    phase=phase,
                    checkpoint=checkpoint,
                    checkpoint_writer=checkpoint_writer,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    service_identity_before=service_identity_before,
                    source_login_pod_names=source_login_pod_names,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                    allow_degraded_slurm_smoke=allow_slurm_smoke_defer,
                    session_policy_applied_before_mutation=True,
                )
            )
            accounting_handoff = _accounting_handoff_state(phase)
            _accounting_handoff_require_target_control_plane_ready(
                state=accounting_handoff,
                target_binding=live_target_binding,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            target_worker_bindings = _wait_for_target_worker_nodesets_ready(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                timeout_seconds=1800,
                expected_slurmcluster_binding=live_target_binding,
            )
            accounting_handoff["target_worker_workload_bindings"] = target_worker_bindings
            accounting_handoff["target_worker_workload_bindings_recorded_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
            lines.extend(
                _complete_accounting_handoff_import(
                    phase=phase,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            lines.extend(
                _complete_immutable_child_handoff_after_target_readiness(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            _delete_conflicting_source_slurm_resources(
                command_runner=command_runner,
                kube_context=kube_context,
                source_report=source_report,
                source_cleanup_state=_accounting_handoff_state(phase),
                target_ref=target_ref,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                target_slurmcluster_binding=live_target_binding,
                mutation_guard=mutation_guard,
                checkpoint_writer=checkpoint_writer,
            )
            phase["source_cleanup_completed_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
        else:
            lines.extend(
                _ensure_rolling_login_continuity(
                    phase=phase,
                    checkpoint=checkpoint,
                    checkpoint_writer=checkpoint_writer,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    service_identity_before=service_identity_before,
                    source_login_pod_names=source_login_pod_names,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                    allow_degraded_slurm_smoke=allow_slurm_smoke_defer,
                    session_policy_applied_before_mutation=True,
                )
            )
            _wait_for_target_worker_nodesets_ready(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                timeout_seconds=1800,
            )
        _kubectl_rollout_status(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="deployment/soperator-manager",
            timeout="15m",
        )
        resume_lines = _resume_slurm_after_cutover(
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            phase=phase,
            values=values,
            checkpoint_writer=checkpoint_writer,
            slurm_pause_records=slurm_pause_records,
            cxcli_drained_node_names=_checkpoint_cxcli_owned_slurm_drains(phase),
            action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
            authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
        )
    except (Exception, KeyboardInterrupt):
        gpu_gate_status = str(
            _mapping(phase.get("gpu_workload_release_gate")).get("status") or ""
        ).strip()
        if _gpu_worker_nodeset_names(values) and gpu_gate_status != "passed":
            phase["slurm_partition_restore_deferred_reason"] = (
                "target values reconciliation did not pass the exact GPU workload release "
                "gate; scheduling remains paused until target lineage, chart-owned "
                "driver-jail contract, plain jailed nvidia-smi, and Pod UID revalidation pass"
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise
        if _accounting_handoff_cleanup_incomplete(phase) or _immutable_child_handoff_incomplete(
            phase
        ):
            phase["slurm_partition_restore_deferred_reason"] = (
                "accounting history or immutable-child ownership source cleanup is "
                "incomplete; scheduling remains paused until the exact "
                "resourceVersion-preconditioned source retirement and child handoff "
                "succeed"
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise
        if slurm_pause_records:
            phase["slurm_partition_restore_deferred_reason"] = (
                "target values reconciliation failed; scheduling remains paused for "
                "checkpointed roll-forward recovery"
            )
            phase["slurm_pause_release_boundary"] = "before-controller-bridge-cleanup"
            if checkpoint_writer is not None:
                checkpoint_writer()
        raise

    if slurm_pause_records:
        phase["slurm_partition_restore_deferred_reason"] = (
            "target values reconciliation passed; scheduling remains paused until "
            "final continuity gates pass before controller bridge cleanup"
        )
        phase["slurm_pause_release_boundary"] = "before-controller-bridge-cleanup"
    phase["cxcli_drained_slurm_nodes"] = []
    lines.extend([*quiet_lines, *resume_lines])
    phase["target_values_revision"] = _ROLLING_COMPUTE_VALUES_REVISION
    phase["target_values_reapplied_at"] = _utc_now()
    lines.append(
        "Target Soperator chart values reapplied for the current compute migration contract."
    )
    return True, lines


def _reconcile_completed_compute_cutover(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    nebius_api: SoperatorMigrationNebiusApi,
    checkpoint_writer: Callable[[], None] | None = None,
    job_policy: str = "preserve",
    cancel_job_ids: Sequence[str] = (),
    requeue_job_ids: Sequence[str] = (),
    job_wait_timeout_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_WAIT_TIMEOUT_SECONDS,
    job_refresh_interval_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_REFRESH_INTERVAL_SECONDS,
    slurm_scheduling_pause: bool = True,
    login_session_policy: str = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
    login_session_drain_timeout_seconds: int = 0,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None = None,
    interactive_prompt_pause: Callable[[], Any] | None = None,
    allow_resolved_interactive_job_policy: bool = False,
    mutation_guard: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    lines: list[str] = []
    mutation_performed = False
    ungated_values = _patch_target_values_for_compute(
        payload=payload,
        target_ref=target_ref,
        checkpoint=checkpoint,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    values = _target_values_gated_by_controller_bridge(
        checkpoint=checkpoint,
        values=ungated_values,
        checkpoint_writer=checkpoint_writer,
    )
    if _rolling_compute_values_revision(checkpoint) < _ROLLING_COMPUTE_VALUES_REVISION:
        phase_mutation, phase_lines = _reapply_stale_rolling_compute_values(
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            live_snapshot=live_snapshot,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            nebius_api=nebius_api,
            checkpoint_writer=checkpoint_writer,
            job_policy=job_policy,
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            job_wait_timeout_seconds=job_wait_timeout_seconds,
            job_refresh_interval_seconds=job_refresh_interval_seconds,
            slurm_scheduling_pause=slurm_scheduling_pause,
            login_session_policy=login_session_policy,
            login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
            slurm_decision_recorder=slurm_decision_recorder,
            interactive_prompt_pause=interactive_prompt_pause,
            allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
            mutation_guard=mutation_guard,
        )
        mutation_performed = mutation_performed or phase_mutation
        lines.extend(phase_lines)
    else:
        _wait_for_target_worker_nodesets_ready(
            command_runner=command_runner,
            kube_context=kube_context,
            values=values,
            timeout_seconds=1800,
        )
    phase = _phase_state(checkpoint, "rolling-compute-migration")
    live_target_binding = _revalidate_live_target_slurmcluster_handoff(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        source_report=source_report,
        target_ref=target_ref,
    )
    source_cleanup = False
    if live_target_binding:
        lines.extend(
            _enforce_source_retirement_login_session_policy(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                policy=login_session_policy,
                timeout_seconds=login_session_drain_timeout_seconds,
                checkpoint_writer=checkpoint_writer,
            )
        )
        _checkpoint_source_cleanup_started(
            phase=phase,
            source_report=source_report,
            target_ref=target_ref,
            live_target_binding=live_target_binding,
            checkpoint_writer=checkpoint_writer,
        )
        source_resource_version_precondition, cleanup_lines = (
            _accounting_handoff_revalidate_source_cleanup_boundary(
                phase=phase,
                source_report=source_report,
                target_ref=target_ref,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        lines.extend(cleanup_lines)
        lines.extend(
            _enforce_source_retirement_login_session_policy(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                policy=login_session_policy,
                timeout_seconds=login_session_drain_timeout_seconds,
                checkpoint_writer=checkpoint_writer,
            )
        )
        source_resource_version_precondition = (
            _accounting_handoff_checkpoint_final_source_delete_preconditions(
                phase=phase,
                values=values,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        handoff_binding = _mapping(phase.get("slurmcluster_handoff_binding"))
        _checkpoint_immutable_child_handoff_inventory(
            phase=phase,
            state=_accounting_handoff_state(phase),
            source_report=source_report,
            values=values,
            source_binding=_mapping(handoff_binding.get("source")),
            target_binding=_mapping(handoff_binding.get("target")),
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        lines.extend(
            _prepare_immutable_child_handoff_before_source_retirement(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
                controller_bridge=_mapping(checkpoint.get("controller_bridge")),
            )
        )
        _require_target_soperator_semantic_compatibility_for_child_handoff(phase)
        source_cleanup = _delete_conflicting_source_slurm_resources(
            command_runner=command_runner,
            kube_context=kube_context,
            source_report=source_report,
            source_cleanup_state=_accounting_handoff_state(phase),
            target_ref=target_ref,
            held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
            target_slurmcluster_binding=live_target_binding,
            source_slurmcluster_resource_version=(source_resource_version_precondition),
            retire_slurmcluster_only=True,
            mutation_guard=mutation_guard,
            checkpoint_writer=checkpoint_writer,
        )
        _accounting_handoff_checkpoint_source_owner_retired(
            phase=phase,
            checkpoint_writer=checkpoint_writer,
        )
        _clear_worker_nodeset_ephemeral_storage_aliases(
            command_runner=command_runner,
            kube_context=kube_context,
            values=values,
            phase=phase,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        lines.extend(
            _execute_immutable_child_handoff_before_target_readiness(
                phase=phase,
                values=ungated_values,
                controller_bridge=dict(_mapping(checkpoint.get("controller_bridge"))),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        lines.extend(
            _verify_legacy_rootfs_bridge_after_manager_restore(
                phase=phase,
                populate_phase=_accepted_populate_jail_phase_state(checkpoint),
                handoff=_immutable_child_handoff_state(phase),
                source_binding=_mapping(handoff_binding.get("source")),
                target_binding=_mapping(handoff_binding.get("target")),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        lines.extend(
            _accounting_handoff_complete_after_source_retirement(
                phase=phase,
                values=values,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        continuity = _mapping(phase.get("login_continuity"))
        service_identity_before = tuple(
            _sequence_of_mappings(continuity.get("service_identity_before_handoff"))
        ) or _login_service_identities(
            command_runner=command_runner,
            kube_context=kube_context,
            required=True,
        )
        source_login_pod_names = tuple(
            str(name)
            for name in continuity.get("source_login_pods_before_handoff") or ()
            if str(name)
        )
        lines.extend(
            _ensure_rolling_login_continuity(
                phase=phase,
                checkpoint=checkpoint,
                checkpoint_writer=checkpoint_writer,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                service_identity_before=service_identity_before,
                source_login_pod_names=source_login_pod_names,
                login_session_policy=login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                allow_degraded_slurm_smoke=_rolling_compute_slurm_smoke_may_defer(
                    checkpoint=checkpoint,
                    phase=phase,
                ),
                session_policy_applied_before_mutation=True,
            )
        )
        accounting_handoff = _accounting_handoff_state(phase)
        _accounting_handoff_require_target_control_plane_ready(
            state=accounting_handoff,
            target_binding=live_target_binding,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        accounting_handoff["target_worker_workload_bindings"] = (
            _wait_for_target_worker_nodesets_ready(
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                timeout_seconds=1800,
                expected_slurmcluster_binding=live_target_binding,
            )
        )
        accounting_handoff["target_worker_workload_bindings_recorded_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        lines.extend(
            _complete_accounting_handoff_import(
                phase=phase,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        lines.extend(
            _complete_immutable_child_handoff_after_target_readiness(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        source_cleanup = (
            _delete_conflicting_source_slurm_resources(
                command_runner=command_runner,
                kube_context=kube_context,
                source_report=source_report,
                source_cleanup_state=_accounting_handoff_state(phase),
                target_ref=target_ref,
                held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
                target_slurmcluster_binding=live_target_binding,
                mutation_guard=mutation_guard,
                checkpoint_writer=checkpoint_writer,
            )
            or source_cleanup
        )
        phase["source_cleanup_completed_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    if source_cleanup:
        mutation_performed = True
        lines.append("Conflicting source Slurm resources removed for target cutover.")
    if source_cleanup or mutation_performed:
        _wait_for_target_slurmcluster_available(
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            timeout_seconds=900,
        )
    return mutation_performed, lines


def _delete_options_body_with_uid_precondition(
    uid: str,
    *,
    resource_version: str = "",
    propagation_policy: str,
) -> bytes:
    normalized_uid = str(uid or "").strip()
    if not normalized_uid:
        raise RuntimeError("Kubernetes UID-preconditioned deletion requires a non-empty UID.")
    normalized_propagation_policy = str(propagation_policy or "").strip()
    if normalized_propagation_policy not in _KUBERNETES_DELETE_PROPAGATION_POLICIES:
        raise RuntimeError(
            "Kubernetes UID-preconditioned deletion requires an explicitly allowlisted "
            "propagation policy."
        )
    preconditions = {"uid": normalized_uid}
    normalized_resource_version = str(resource_version or "").strip()
    if normalized_resource_version:
        preconditions["resourceVersion"] = normalized_resource_version
    return json.dumps(
        {
            "apiVersion": "v1",
            "kind": "DeleteOptions",
            "preconditions": preconditions,
            "propagationPolicy": normalized_propagation_policy,
        },
        separators=(",", ":"),
    ).encode("utf-8")


def _uid_preconditioned_delete_api_path_is_supported(api_path: str) -> bool:
    resource_name = r"[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?"
    return bool(
        re.fullmatch(
            rf"(?:"
            rf"/api/v1/namespaces/{CONTROLLER_BRIDGE_NAMESPACE}"
            rf"|/api/v1/namespaces/{CONTROLLER_INSPECTOR_NAMESPACE}"
            rf"|/api/v1/persistentvolumes/cxcli-controller-bridge-state-pv"
            rf"|/api/v1/persistentvolumes/cxcli-controller-bridge-jail-pv"
            rf"|/apis/scheduling\.k8s\.io/v1/priorityclasses/"
            rf"cxcli-soperator-upgrade-bridge"
            rf"|/api/v1/namespaces/{CONTROLLER_BRIDGE_NAMESPACE}/"
            rf"persistentvolumeclaims/(?:cxcli-controller-bridge-state|"
            rf"cxcli-controller-bridge-jail)"
            rf"|/api/v1/namespaces/{CONTROLLER_BRIDGE_NAMESPACE}/pods/"
            rf"cxcli-controller-bridge-canary-[01]"
            rf"|/apis/rbac\.authorization\.k8s\.io/v1/namespaces/soperator/"
            rf"rolebindings/cxcli-controller-bridge-power-manager"
            rf"|/apis/rbac\.authorization\.k8s\.io/v1/namespaces/soperator/"
            rf"(?:roles|rolebindings)/cxcli-source-fence-[a-f0-9]{{12}}-canary"
            rf"|/apis/admissionregistration\.k8s\.io/v1/"
            rf"validatingadmissionpolicies/cxcli-source-fence-[a-f0-9]{{12}}"
            rf"|/apis/admissionregistration\.k8s\.io/v1/"
            rf"validatingadmissionpolicybindings/"
            rf"cxcli-source-fence-[a-f0-9]{{12}}-binding"
            rf"|/apis/slurm\.nebius\.ai/(?:v1|v1alpha1)/namespaces/soperator/"
            rf"(?:slurmclusters|nodesets)/{resource_name}"
            rf"|/apis/apps/v1/namespaces/soperator/"
            rf"(?:deployments|statefulsets|daemonsets|replicasets)/{resource_name}"
            rf"|/apis/apps\.kruise\.io/v1beta1/namespaces/soperator/"
            rf"statefulsets/{resource_name}"
            rf"|/apis/k8s\.mariadb\.com/v1alpha1/namespaces/soperator/"
            rf"mariadbs/{resource_name}"
            rf"|/apis/networking\.k8s\.io/v1/namespaces/soperator/"
            rf"networkpolicies/{resource_name}"
            rf"|/apis/slurm\.nebius\.ai/v1alpha1/namespaces/soperator/"
            rf"jailedconfigs/{resource_name}"
            rf"|/api/v1/namespaces/soperator/configmaps/{resource_name}"
            rf"|/apis/batch/v1/namespaces/soperator/jobs/{resource_name}"
            rf"|/api/v1/namespaces/soperator/services/{resource_name}"
            rf"|/api/v1/namespaces/soperator/pods/{resource_name}"
            rf")",
            str(api_path or ""),
        )
    )


def _validated_namespaced_resource_identity(
    resource: Mapping[str, Any],
    *,
    expected_api_version: str,
    expected_kind: str,
    label: str,
) -> dict[str, str]:
    if (
        str(resource.get("apiVersion") or "").strip() != expected_api_version
        or str(resource.get("kind") or "").strip() != expected_kind
    ):
        raise RuntimeError(f"{label} inventory contains an unsupported or ambiguous API identity.")
    raw_metadata = resource.get("metadata")
    if not isinstance(raw_metadata, Mapping):
        raise RuntimeError(f"{label} inventory contains malformed resource metadata.")
    identity = {
        key: str(raw_metadata.get(key) or "").strip()
        for key in ("namespace", "name", "uid", "resourceVersion")
    }
    if identity["namespace"] != _SOPERATOR_NAMESPACE or not all(identity.values()):
        raise RuntimeError(
            f"{label} inventory lacks an exact namespace/name/UID/resourceVersion identity."
        )
    if not re.fullmatch(
        r"[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?",
        identity["name"],
    ):
        raise RuntimeError(f"{label} inventory contains an unsupported Kubernetes name.")
    return identity


def _validated_resource_owner_references(
    resource: Mapping[str, Any],
    *,
    label: str,
) -> tuple[dict[str, Any], ...]:
    metadata = _mapping(resource.get("metadata"))
    raw_owners = metadata.get("ownerReferences")
    if raw_owners is None:
        return ()
    if not isinstance(raw_owners, Sequence) or isinstance(
        raw_owners,
        (str, bytes, bytearray),
    ):
        raise RuntimeError(f"{label} has malformed Kubernetes ownerReferences.")
    owners: list[dict[str, Any]] = []
    for raw_owner in raw_owners:
        if not isinstance(raw_owner, Mapping):
            raise RuntimeError(f"{label} has a malformed Kubernetes owner reference.")
        owner = {
            key: str(raw_owner.get(key) or "").strip()
            for key in ("apiVersion", "kind", "name", "uid")
        }
        if not all(owner.values()):
            raise RuntimeError(f"{label} has an incomplete Kubernetes owner identity.")
        controller = raw_owner.get("controller")
        if controller is not None and not isinstance(controller, bool):
            raise RuntimeError(f"{label} has an ambiguous Kubernetes controller owner flag.")
        owner["controller"] = controller is True
        owners.append(owner)
    return tuple(owners)


def _immutable_child_handoff_state(phase: dict[str, Any]) -> dict[str, Any]:
    raw = phase.setdefault(
        "immutable_child_handoff",
        {"schema": _IMMUTABLE_CHILD_HANDOFF_SCHEMA, "status": "pending"},
    )
    if not isinstance(raw, dict) or raw.get("schema") != _IMMUTABLE_CHILD_HANDOFF_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff checkpoint is malformed or uses an unsupported schema."
        )
    return raw


def _immutable_child_workload_spec(
    *,
    api_version: str,
    kind: str,
    name: str,
    worker_names: set[str] | frozenset[str],
) -> tuple[str, str] | None:
    """Return (kubectl resource type, target component) for collision-prone children."""

    if kind == "StatefulSet" and api_version == "apps.kruise.io/v1beta1":
        resource_type = "statefulset.apps.kruise.io"
    elif kind == "StatefulSet" and api_version == "apps/v1":
        resource_type = "statefulset.apps"
    elif kind == "Deployment" and api_version == "apps/v1":
        resource_type = "deployment"
    elif kind == "DaemonSet" and api_version == "apps/v1":
        resource_type = "daemonset"
    else:
        return None
    if name == "controller" and kind in {"StatefulSet", "DaemonSet"}:
        return resource_type, "controller"
    if name == "login" and kind == "StatefulSet":
        return resource_type, "login"
    if name in worker_names and kind == "StatefulSet":
        return resource_type, "nodeset"
    if name == "sconfigcontroller" and kind == "Deployment":
        return resource_type, "sconfigcontroller"
    if name == "rest" and kind == "Deployment":
        return resource_type, "rest"
    return None


def _immutable_child_target_selector(
    *,
    target_binding: Mapping[str, Any],
    component: str,
) -> dict[str, str]:
    target_name = str(target_binding.get("name") or "").strip()
    if not target_name or not component:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff lacks an exact target selector binding."
        )
    return {
        "app.kubernetes.io/name": "slurmcluster",
        "app.kubernetes.io/instance": target_name,
        "app.kubernetes.io/component": component,
    }


def _immutable_child_exact_identity(
    resource: Mapping[str, Any],
    *,
    namespace: str = _SOPERATOR_NAMESPACE,
    label: str,
) -> dict[str, str]:
    metadata = _mapping(resource.get("metadata"))
    identity = {
        key: str(metadata.get(key) or "").strip()
        for key in ("namespace", "name", "uid", "resourceVersion")
    }
    if identity["namespace"] != namespace or not all(identity.values()):
        raise SoperatorMigrationPhasePending(
            f"{label} lacks an exact namespace/name/UID/resourceVersion identity."
        )
    return identity


def _immutable_child_controller_owner(
    resource: Mapping[str, Any],
    *,
    label: str,
) -> dict[str, Any] | None:
    owners = _validated_resource_owner_references(resource, label=label)
    controller_owners = tuple(owner for owner in owners if owner.get("controller") is True)
    if len(controller_owners) > 1:
        raise SoperatorMigrationPhasePending(f"{label} has multiple controller owners.")
    return dict(controller_owners[0]) if controller_owners else None


def _immutable_child_list(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    resource_type: str,
) -> tuple[dict[str, Any], ...]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            resource_type,
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
    )
    raw_items = payload.get("items")
    if not isinstance(raw_items, Sequence) or isinstance(raw_items, (str, bytes, bytearray)):
        raise SoperatorMigrationPhasePending(
            f"immutable child handoff could not enumerate exact {resource_type} identities."
        )
    return tuple(dict(item) for item in raw_items if isinstance(item, Mapping))


def _immutable_child_pod_ready(pod: Mapping[str, Any]) -> bool:
    return bool(
        str(_mapping(pod.get("status")).get("phase") or "").strip() == "Running"
        and any(
            str(condition.get("type") or "").strip() == "Ready"
            and str(condition.get("status") or "").strip() == "True"
            for condition in _sequence_of_mappings(_mapping(pod.get("status")).get("conditions"))
        )
        and not str(_mapping(pod.get("metadata")).get("deletionTimestamp") or "").strip()
    )


def _released_login_pod_identity_in_hold_history(
    hold: Mapping[str, Any],
    *,
    pod_name: str,
    pod_uid: str,
) -> bool:
    allowed_statuses = {
        "metadata-released",
        "gone-after-release-intent",
        "replaced-after-release-intent",
        "terminating-after-release-intent",
    }

    def _matches_shrink_history(source: Mapping[str, Any]) -> bool:
        matches = [
            identity
            for history in _sequence_of_mappings(source.get("shrink_history"))
            if str(history.get("completed_at") or "").strip()
            for identity in _sequence_of_mappings(history.get("released_identities"))
            if str(identity.get("pod") or "").strip() == pod_name
            and str(identity.get("uid") or "").strip() == pod_uid
            and str(identity.get("status") or "").strip() in allowed_statuses
        ]
        return len(matches) == 1

    if _matches_shrink_history(hold):
        return True
    for archived in _sequence_of_mappings(hold.get("release_history")):
        archived_pods = {
            str(item.get("name") or "").strip(): str(item.get("uid") or "").strip()
            for item in _sequence_of_mappings(archived.get("pods"))
            if str(item.get("name") or "").strip()
        }
        archived_releases = {
            str(item.get("pod") or "").strip(): str(item.get("status") or "").strip()
            for item in _sequence_of_mappings(archived.get("released_pods"))
            if str(item.get("pod") or "").strip()
        }
        release_probe = _mapping(archived.get("release_probe"))
        if (
            archived.get("status") == "released"
            and archived_pods.get(pod_name) == pod_uid
            and archived_releases.get(pod_name) in allowed_statuses
            and str(archived.get("release_intent_at") or "").strip()
            and str(archived.get("released_at") or "").strip()
            and release_probe.get("status") == "checked"
            and _non_negative_int(release_probe.get("active_sessions"), fallback=-1) == 0
            and _mapping(archived.get("session_drain")).get("status") == "drained"
            and _matches_shrink_history(archived)
        ):
            return True
    return False


def _reconcile_released_login_pods_in_immutable_handoff(
    *,
    checkpoint: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Adopt same-workload login Pod replacements after the exact SSH hold release."""

    hold = _mapping(checkpoint.get("active_login_session_hold"))
    if str(hold.get("status") or "").strip() != "released":
        return []
    held_pods = _sequence_of_mappings(hold.get("pods"))
    released_by_name = {
        str(item.get("pod") or "").strip(): str(item.get("status") or "").strip()
        for item in _sequence_of_mappings(hold.get("released_pods"))
        if str(item.get("pod") or "").strip()
    }
    held_by_name = {
        str(item.get("name") or "").strip(): item
        for item in held_pods
        if str(item.get("name") or "").strip()
    }
    release_probe = _mapping(hold.get("release_probe"))
    session_drain = _mapping(hold.get("session_drain"))
    if not (
        held_by_name
        and set(released_by_name) == set(held_by_name)
        and all(
            status
            in {
                "metadata-released",
                "gone-after-release-intent",
                "replaced-after-release-intent",
                "terminating-after-release-intent",
            }
            for status in released_by_name.values()
        )
        and str(hold.get("release_intent_at") or "").strip()
        and str(hold.get("released_at") or "").strip()
        and release_probe.get("status") == "checked"
        and _non_negative_int(release_probe.get("active_sessions"), fallback=-1) == 0
        and session_drain.get("status") == "drained"
    ):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff found a released login hold without its exact "
            "zero-session release journal."
        )

    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    immutable = rolling.get("immutable_child_handoff")
    if not isinstance(immutable, dict):
        return []
    if immutable.get("schema") != _IMMUTABLE_CHILD_HANDOFF_SCHEMA or str(
        immutable.get("status") or ""
    ).strip() not in {"captured", "login-bridge-ready", "manager-paused"}:
        return []
    workload_matches = [
        item
        for item in _sequence_of_mappings(tuple(_mapping(immutable.get("workloads")).values()))
        if str(item.get("resource_type") or "").strip() == "statefulset.apps.kruise.io"
        and str(item.get("name") or "").strip() == "login"
        and str(item.get("uid") or "").strip()
    ]
    if len(workload_matches) != 1:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff cannot reconcile a released login hold without one "
            "exact captured login workload."
        )
    captured_login = workload_matches[0]
    captured_pods = _sequence_of_mappings(captured_login.get("pods"))
    if not captured_pods:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff cannot reconcile a released login hold without its "
            "captured login Pod identities."
        )
    workload_uid = str(captured_login.get("uid") or "").strip()
    live_workload = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="statefulsets.apps.kruise.io",
        name="login",
    )
    live_workload_identity = _immutable_child_exact_identity(
        live_workload,
        label="released-hold login StatefulSet",
    )
    if live_workload_identity["uid"] != workload_uid:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff login workload changed after the SSH hold release."
        )

    transitions = list(_sequence_of_mappings(immutable.get("released_login_pod_transitions")))
    reconciled: list[dict[str, Any]] = []
    changed = False
    for captured in captured_pods:
        pod_name = str(captured.get("name") or "").strip()
        captured_uid = str(captured.get("uid") or "").strip()
        prior_transition = next(
            (
                item
                for item in transitions
                if item.get("schema") == _IMMUTABLE_CHILD_RELEASED_LOGIN_REPLACEMENT_SCHEMA
                and item.get("status") == "verified"
                and str(item.get("pod") or "").strip() == pod_name
                and str(item.get("to_uid") or "").strip() == captured_uid
                and str(item.get("workload_uid") or "").strip() == workload_uid
                and str(item.get("from_uid") or "").strip()
                and str(item.get("release_intent_at") or "").strip()
                and str(item.get("released_at") or "").strip()
                and str(item.get("observed_at") or "").strip()
            ),
            None,
        )
        bound_to_current_hold = pod_name in held_by_name
        if not pod_name or not captured_uid:
            raise SoperatorMigrationPhasePending(
                "immutable child handoff captured login Pod identity is incomplete."
            )
        live_pod = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=pod_name,
        )
        live_identity = _immutable_child_exact_identity(
            live_pod,
            label=f"released-hold login Pod {pod_name}",
        )
        owner = _immutable_child_controller_owner(
            live_pod,
            label=f"released-hold login Pod {pod_name}",
        )
        statuses = _sequence_of_mappings(_mapping(live_pod.get("status")).get("containerStatuses"))
        metadata = _mapping(live_pod.get("metadata"))
        if not (
            _immutable_child_pod_ready(live_pod)
            and statuses
            and all(status.get("ready") is True for status in statuses)
            and all(
                _non_negative_int(status.get("restartCount"), fallback=-1) == 0
                for status in statuses
            )
            and str(_mapping(owner).get("apiVersion") or "").strip() == "apps.kruise.io/v1beta1"
            and str(_mapping(owner).get("kind") or "").strip() == "StatefulSet"
            and str(_mapping(owner).get("name") or "").strip() == "login"
            and str(_mapping(owner).get("uid") or "").strip() == workload_uid
        ):
            raise SoperatorMigrationPhasePending(
                f"immutable child handoff replacement login Pod {pod_name} is not an exact "
                "Ready zero-restart child of the captured StatefulSet."
            )
        live_uid = live_identity["uid"]
        if live_uid == captured_uid:
            if not (
                bound_to_current_hold
                or prior_transition is not None
                or _released_login_pod_identity_in_hold_history(
                    hold,
                    pod_name=pod_name,
                    pod_uid=captured_uid,
                )
            ):
                raise SoperatorMigrationPhasePending(
                    "immutable child handoff captured login Pod is not bound to an exact "
                    "released hold."
                )
            reconciled.append(dict(captured))
            continue
        if not bound_to_current_hold:
            raise SoperatorMigrationPhasePending(
                f"immutable child handoff replacement login Pod {pod_name} changed again "
                "without an exact released hold."
            )
        held_uid = str(_mapping(held_by_name[pod_name]).get("uid") or "").strip()
        labels = _mapping(metadata.get("labels"))
        annotations = _mapping(metadata.get("annotations"))
        contract = _mapping(hold.get("contract"))
        if (
            held_uid != captured_uid
            or labels.get(str(contract.get("label_key") or "")) is not None
            or annotations.get(_LOGIN_SESSION_HOLD_RELATED_PUB_ANNOTATION) is not None
        ):
            raise SoperatorMigrationPhasePending(
                f"immutable child handoff replacement login Pod {pod_name} is not an exact "
                "post-release successor of the captured held Pod."
            )
        transition = {
            "schema": _IMMUTABLE_CHILD_RELEASED_LOGIN_REPLACEMENT_SCHEMA,
            "status": "verified",
            "pod": pod_name,
            "from_uid": captured_uid,
            "to_uid": live_uid,
            "workload_uid": workload_uid,
            "release_intent_at": str(hold.get("release_intent_at") or "").strip(),
            "released_at": str(hold.get("released_at") or "").strip(),
            "observed_at": _utc_now(),
        }
        if not any(
            item.get("schema") == transition["schema"]
            and item.get("status") == "verified"
            and item.get("pod") == pod_name
            and item.get("from_uid") == captured_uid
            and item.get("to_uid") == live_uid
            and item.get("workload_uid") == workload_uid
            for item in transitions
        ):
            transitions.append(transition)
        reconciled.append(
            {
                **dict(captured),
                **live_identity,
                "api_path": f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/pods/{pod_name}",
                "ready": True,
                "owner_uid": workload_uid,
                "labels": dict(labels),
            }
        )
        changed = True
    if not changed:
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff cannot adopt released login Pod replacements without "
            "a durable checkpoint writer."
        )
    captured_login["pods"] = reconciled
    immutable["released_login_pod_transitions"] = transitions
    immutable["released_login_pods_reconciled_at"] = _utc_now()
    checkpoint_writer()
    return [
        "Login continuity: checkpointed exact post-release login Pod replacement(s) under "
        "the unchanged source StatefulSet."
    ]


def _immutable_child_pvc_claim_names(pod: Mapping[str, Any]) -> tuple[str, ...]:
    return tuple(
        dict.fromkeys(
            str(
                _mapping(_mapping(volume).get("persistentVolumeClaim")).get("claimName") or ""
            ).strip()
            for volume in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
            if str(
                _mapping(_mapping(volume).get("persistentVolumeClaim")).get("claimName") or ""
            ).strip()
        )
    )


def _immutable_child_manager_spec_fingerprint(manager: Mapping[str, Any]) -> str:
    spec = manager.get("spec")
    if not isinstance(spec, Mapping):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff found a manager Deployment without a mapping spec."
        )
    normalized = dict(copy.deepcopy(to_plain_data(spec)))
    normalized.pop("replicas", None)
    if not _mapping(normalized.get("selector")) or not _mapping(normalized.get("template")):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff manager Deployment lacks selector/template identity."
        )
    return _fingerprint(normalized)


def _immutable_child_manager_generation(manager: Mapping[str, Any]) -> int:
    generation = _positive_int(_mapping(manager.get("metadata")).get("generation"), fallback=0)
    if generation <= 0:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff manager Deployment lacks a positive generation."
        )
    return generation


def _immutable_child_require_manager_spec_contract(
    *,
    manager_binding: Mapping[str, Any],
    manager: Mapping[str, Any],
) -> tuple[str, int]:
    fingerprint = _immutable_child_manager_spec_fingerprint(manager)
    generation = _immutable_child_manager_generation(manager)
    expected = str(manager_binding.get("spec_fingerprint") or "").strip()
    if expected and expected != fingerprint:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff manager Deployment selector/template/image/env/SA "
            "contract changed after capture."
        )
    return fingerprint, generation


def _immutable_child_manager_manifest_deployment(manifest_text: str) -> dict[str, Any]:
    matches: list[Mapping[str, Any]] = []
    for document in _target_soperator_helm_documents(
        manifest_text,
        label="manual manager-pause adoption release manifest",
    ):
        candidates = (
            _sequence_of_mappings(document.get("items"))
            if str(document.get("kind") or "").strip() == "List"
            else (document,)
        )
        for candidate in candidates:
            metadata = _mapping(candidate.get("metadata"))
            namespace = str(metadata.get("namespace") or _SOPERATOR_NAMESPACE).strip()
            if (
                str(candidate.get("apiVersion") or "").strip() == "apps/v1"
                and str(candidate.get("kind") or "").strip() == "Deployment"
                and namespace == _SOPERATOR_NAMESPACE
                and str(metadata.get("name") or "").strip() == "soperator-manager"
            ):
                matches.append(candidate)
    if len(matches) != 1:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption requires exactly one "
            "apps/v1 Deployment/soperator-manager in the deployed Helm manifest."
        )
    return dict(copy.deepcopy(to_plain_data(matches[0])))


def _immutable_child_drop_absent_nulls(live: Any, declared: Any) -> None:
    if isinstance(live, dict) and isinstance(declared, Mapping):
        for key in tuple(live):
            if key not in declared and live.get(key) is None:
                live.pop(key, None)
                continue
            if key in declared:
                _immutable_child_drop_absent_nulls(live.get(key), declared.get(key))
        return
    if (
        isinstance(live, list)
        and isinstance(declared, Sequence)
        and not isinstance(declared, (str, bytes, bytearray))
    ):
        for live_item, declared_item in zip(live, declared, strict=False):
            _immutable_child_drop_absent_nulls(live_item, declared_item)


def _immutable_child_drop_absent_default(
    live: dict[str, Any],
    declared: Mapping[str, Any],
    key: str,
    value: Any,
) -> None:
    if key not in declared and live.get(key) == value:
        live.pop(key, None)


def _immutable_child_manager_helm_spec_fingerprint(
    *,
    declared_manager: Mapping[str, Any],
    live_manager: Mapping[str, Any],
) -> str:
    """Match the Helm-declared manager spec after removing API-server defaults."""

    declared_spec = declared_manager.get("spec")
    live_spec = live_manager.get("spec")
    if not isinstance(declared_spec, Mapping) or not isinstance(live_spec, Mapping):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption found an incomplete Deployment spec."
        )
    declared = dict(copy.deepcopy(to_plain_data(declared_spec)))
    live = dict(copy.deepcopy(to_plain_data(live_spec)))
    declared.pop("replicas", None)
    live.pop("replicas", None)
    if not _mapping(declared.get("selector")) or not _mapping(declared.get("template")):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption Helm Deployment lacks its "
            "selector/template contract."
        )

    _immutable_child_drop_absent_nulls(live, declared)
    for key, default in (
        ("progressDeadlineSeconds", 600),
        ("revisionHistoryLimit", 10),
        (
            "strategy",
            {
                "rollingUpdate": {"maxSurge": "25%", "maxUnavailable": "25%"},
                "type": "RollingUpdate",
            },
        ),
    ):
        _immutable_child_drop_absent_default(live, declared, key, default)

    declared_template = _mapping(declared.get("template"))
    live_template = live.get("template")
    if not isinstance(live_template, dict):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption live Deployment lacks its Pod template."
        )
    declared_pod_spec = _mapping(declared_template.get("spec"))
    live_pod_spec = live_template.get("spec")
    if not isinstance(live_pod_spec, dict):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption live Deployment lacks its Pod spec."
        )
    for key, default in (
        ("dnsPolicy", "ClusterFirst"),
        ("enableServiceLinks", True),
        ("restartPolicy", "Always"),
        ("schedulerName", "default-scheduler"),
        ("securityContext", {}),
    ):
        _immutable_child_drop_absent_default(live_pod_spec, declared_pod_spec, key, default)
    if "serviceAccount" not in declared_pod_spec and live_pod_spec.get(
        "serviceAccount"
    ) == live_pod_spec.get("serviceAccountName"):
        live_pod_spec.pop("serviceAccount", None)

    declared_containers = _sequence_of_mappings(declared_pod_spec.get("containers"))
    live_containers = live_pod_spec.get("containers")
    if not isinstance(live_containers, list) or len(live_containers) != len(declared_containers):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption found manager container-set drift "
            "from the deployed Helm manifest."
        )
    for index, (declared_container, live_container) in enumerate(
        zip(declared_containers, live_containers, strict=True)
    ):
        if not isinstance(live_container, dict) or str(live_container.get("name") or "") != str(
            declared_container.get("name") or ""
        ):
            raise SoperatorMigrationPhasePending(
                "manual Soperator manager-pause adoption found manager container identity "
                f"drift at index {index}."
            )
        for key, default in (
            ("imagePullPolicy", "IfNotPresent"),
            ("terminationMessagePath", "/dev/termination-log"),
            ("terminationMessagePolicy", "File"),
        ):
            _immutable_child_drop_absent_default(
                live_container,
                declared_container,
                key,
                default,
            )
        for probe_name in ("livenessProbe", "readinessProbe", "startupProbe"):
            declared_probe = _mapping(declared_container.get(probe_name))
            live_probe = live_container.get(probe_name)
            if not isinstance(live_probe, dict):
                continue
            for key, default in (
                ("failureThreshold", 3),
                ("successThreshold", 1),
                ("timeoutSeconds", 1),
            ):
                _immutable_child_drop_absent_default(live_probe, declared_probe, key, default)
            declared_http = _mapping(declared_probe.get("httpGet"))
            live_http = live_probe.get("httpGet")
            if isinstance(live_http, dict):
                _immutable_child_drop_absent_default(live_http, declared_http, "scheme", "HTTP")

    if live != declared:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption found live manager spec drift from "
            "the exact deployed Helm manifest after Kubernetes default normalization."
        )
    return _fingerprint(declared)


def _immutable_child_require_zero_owned_manager_pods(
    *,
    manager: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[dict[str, str], ...]:
    manager_uid = str(_mapping(manager.get("metadata")).get("uid") or "").strip()
    selector = {
        str(key): str(value)
        for key, value in _mapping(
            _mapping(_mapping(manager.get("spec")).get("selector")).get("matchLabels")
        ).items()
        if str(key).strip() and str(value).strip()
    }
    if not manager_uid or not selector:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption lacks an exact manager UID/selector."
        )
    replica_sets = _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="replicasets.apps",
    )
    owned_replica_sets: list[dict[str, str]] = []
    owned_replica_set_uids: set[str] = set()
    for replica_set in replica_sets:
        owner = _immutable_child_controller_owner(
            replica_set,
            label="ReplicaSet observed during manual Soperator manager-pause adoption",
        )
        if str(_mapping(owner).get("uid") or "").strip() != manager_uid:
            continue
        identity = _immutable_child_exact_identity(
            replica_set,
            label="manager ReplicaSet observed during manual pause adoption",
        )
        status = _mapping(replica_set.get("status"))
        if _resource_replicas(replica_set, default=-1) != 0 or any(
            _non_negative_int(status.get(key), fallback=0) != 0
            for key in ("replicas", "readyReplicas", "availableReplicas")
        ):
            raise SoperatorMigrationPhasePending(
                "manual Soperator manager-pause adoption found a manager ReplicaSet that "
                "is not fully paused."
            )
        owned_replica_sets.append(identity)
        owned_replica_set_uids.add(identity["uid"])

    pods = _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pods",
    )
    for pod in pods:
        owner = _immutable_child_controller_owner(
            pod,
            label="Pod observed during manual Soperator manager-pause adoption",
        )
        owner_uid = str(_mapping(owner).get("uid") or "").strip()
        labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
        selector_match = all(str(labels.get(key) or "") == value for key, value in selector.items())
        if owner_uid == manager_uid or owner_uid in owned_replica_set_uids or selector_match:
            identity = _immutable_child_exact_identity(
                pod,
                label="manager Pod observed during manual pause adoption",
            )
            raise SoperatorMigrationPhasePending(
                "manual Soperator manager-pause adoption requires zero owned manager Pods; "
                f"found {_SOPERATOR_NAMESPACE}/{identity['name']}."
            )
    return tuple(owned_replica_sets)


def _immutable_child_manual_pause_adoption_is_exact(
    *,
    handoff: Mapping[str, Any],
    identity: Mapping[str, str],
    manager_fingerprint: str,
) -> bool:
    proof = _mapping(handoff.get("manual_manager_pause_adoption"))
    proof_manager = _mapping(proof.get("manager"))
    return bool(
        proof.get("schema") == _IMMUTABLE_CHILD_MANUAL_MANAGER_PAUSE_ADOPTION_SCHEMA
        and proof.get("status") == "verified"
        and str(proof.get("observed_at") or "").strip()
        and re.fullmatch(r"[0-9a-f]{64}", str(proof.get("manifest_sha256") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(proof.get("manifest_manager_spec_fingerprint") or ""))
        and _positive_int(proof.get("original_replicas"), fallback=0) > 0
        and _non_negative_int(proof.get("owned_manager_pod_count"), fallback=-1) == 0
        and all(
            str(proof_manager.get(key) or "").strip() == str(identity.get(key) or "").strip()
            for key in ("namespace", "name", "uid", "resourceVersion")
        )
        and str(proof_manager.get("spec_fingerprint") or "").strip() == manager_fingerprint
    )


def _adopt_exact_manually_paused_soperator_manager(
    *,
    handoff: dict[str, Any],
    manager: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Durably bind an externally paused manager to the installed Helm release."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption requires durable checkpoint writes."
        )
    identity = _immutable_child_exact_identity(
        manager,
        label="manually paused Soperator manager Deployment",
    )
    manager_fingerprint, generation = _immutable_child_require_manager_spec_contract(
        manager_binding=_mapping(handoff.get("manager")),
        manager=manager,
    )
    status = _mapping(manager.get("status"))
    if not (
        _resource_replicas(manager, default=-1) == 0
        and _non_negative_int(status.get("replicas"), fallback=0) == 0
        and _non_negative_int(status.get("readyReplicas"), fallback=0) == 0
        and _non_negative_int(status.get("observedGeneration"), fallback=0) >= generation
    ):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption requires an observed, fully stopped "
            "manager Deployment."
        )
    owned_replica_sets = _immutable_child_require_zero_owned_manager_pods(
        manager=manager,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    try:
        releases = tuple(
            release
            for release in list_helm_releases(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                filter_regex=f"^{re.escape(_SOPERATOR_TARGET_RELEASE_NAME)}$",
            )
            if release.name == _SOPERATOR_TARGET_RELEASE_NAME
        )
    except (RuntimeError, subprocess.TimeoutExpired) as exc:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption could not verify the installed Helm "
            "release identity."
        ) from exc
    if len(releases) != 1:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption requires exactly one target Soperator "
            "Helm release."
        )
    release = releases[0]
    revision = _positive_int(release.revision, fallback=0)
    if (
        release.namespace != _SOPERATOR_NAMESPACE
        or release.status.strip().lower() != "deployed"
        or revision <= 0
        or not release.chart.startswith(f"{_SOPERATOR_TARGET_RELEASE_NAME}-")
        or not release.app_version.strip()
    ):
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption found an incomplete or non-deployed "
            "target Soperator Helm release identity."
        )
    manifest_result = command_runner(
        [
            "helm",
            "--kube-context",
            kube_context,
            "get",
            "manifest",
            _SOPERATOR_TARGET_RELEASE_NAME,
            "-n",
            _SOPERATOR_NAMESPACE,
            "--revision",
            str(revision),
        ],
        timeout_seconds=120,
        check=False,
    )
    if manifest_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption could not read the exact deployed Helm "
            "revision manifest."
        )
    manifest_text = manifest_result.stdout or ""
    declared_manager = _immutable_child_manager_manifest_deployment(manifest_text)
    original_replicas = _positive_int(
        _mapping(declared_manager.get("spec")).get("replicas"),
        fallback=0,
    )
    if original_replicas <= 0:
        raise SoperatorMigrationPhasePending(
            "manual Soperator manager-pause adoption requires the deployed Helm manifest "
            "to declare a positive original manager replica count."
        )
    manifest_manager_fingerprint = _immutable_child_manager_helm_spec_fingerprint(
        declared_manager=declared_manager,
        live_manager=manager,
    )
    proof = {
        "schema": _IMMUTABLE_CHILD_MANUAL_MANAGER_PAUSE_ADOPTION_SCHEMA,
        "status": "verified",
        "release": {
            "name": release.name,
            "namespace": release.namespace,
            "revision": revision,
            "chart": release.chart,
            "app_version": release.app_version,
        },
        "manifest_sha256": hashlib.sha256(manifest_text.encode("utf-8")).hexdigest(),
        "manifest_manager_spec_fingerprint": manifest_manager_fingerprint,
        "original_replicas": original_replicas,
        "manager": {
            **identity,
            "generation": generation,
            "spec_fingerprint": manager_fingerprint,
        },
        "owned_manager_replica_sets": [
            {key: item[key] for key in ("name", "uid", "resourceVersion")}
            for item in owned_replica_sets
        ],
        "owned_manager_pod_count": 0,
        "observed_at": _utc_now(),
    }
    existing = _mapping(handoff.get("manual_manager_pause_adoption"))
    if existing and dict(existing) != proof:
        comparable_existing = dict(copy.deepcopy(to_plain_data(existing)))
        comparable_proof = dict(copy.deepcopy(to_plain_data(proof)))
        existing_observed_at = comparable_existing.pop("observed_at", None)
        comparable_proof.pop("observed_at", None)
        for comparable in (comparable_existing, comparable_proof):
            comparable_manager = comparable.get("manager")
            if isinstance(comparable_manager, dict):
                comparable_manager.pop("resourceVersion", None)
            replica_sets = comparable.get("owned_manager_replica_sets")
            if isinstance(replica_sets, list):
                for replica_set in replica_sets:
                    if isinstance(replica_set, dict):
                        replica_set.pop("resourceVersion", None)
        if not str(existing_observed_at or "").strip() or comparable_existing != comparable_proof:
            raise SoperatorMigrationPhasePending(
                "manual Soperator manager-pause adoption live Helm/manager proof drifted "
                "from its durable checkpoint."
            )
        proof["observed_at"] = existing_observed_at
    handoff.update(
        {
            "status": "manager-paused",
            "manager": {
                **identity,
                "replicas": original_replicas,
                "spec_fingerprint": manager_fingerprint,
                "capture_generation": generation,
            },
            "manager_paused_resource_version": identity["resourceVersion"],
            "manager_paused_generation": generation,
            "manager_paused_at": proof["observed_at"],
            "manual_manager_pause_adoption": proof,
        }
    )
    checkpoint_writer()


def _immutable_child_capture_manager_binding(
    *,
    handoff: dict[str, Any],
    manager: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    """Capture a running manager or adopt its exact durable paused checkpoint."""

    identity = _immutable_child_exact_identity(
        manager,
        label="Soperator manager Deployment",
    )
    live_replicas = _resource_replicas(manager, default=-1)
    if live_replicas > 0:
        if str(handoff.get("status") or "").strip() == "manager-paused":
            raise SoperatorMigrationPhasePending(
                "immutable child handoff manager resumed after its durable pause checkpoint."
            )
        fingerprint, generation = _immutable_child_require_manager_spec_contract(
            manager_binding=_mapping(handoff.get("manager")),
            manager=manager,
        )
        return {
            **identity,
            "replicas": live_replicas,
            "spec_fingerprint": fingerprint,
            "capture_generation": generation,
        }, "captured"
    if live_replicas < 0:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff cannot read the Soperator manager replica count."
        )

    checkpointed = _mapping(handoff.get("manager"))
    original_replicas = _non_negative_int(checkpointed.get("replicas"), fallback=0)
    paused_resource_version = str(handoff.get("manager_paused_resource_version") or "").strip()
    fingerprint, generation = _immutable_child_require_manager_spec_contract(
        manager_binding=checkpointed,
        manager=manager,
    )
    checkpointed_fingerprint = str(checkpointed.get("spec_fingerprint") or "").strip()
    manual_pause_adoption = _immutable_child_manual_pause_adoption_is_exact(
        handoff=handoff,
        identity=identity,
        manager_fingerprint=fingerprint,
    )
    exact_checkpoint = bool(
        str(handoff.get("status") or "").strip() == "manager-paused"
        and (str(handoff.get("manager_pause_intent_at") or "").strip() or manual_pause_adoption)
        and str(handoff.get("manager_paused_at") or "").strip()
        and paused_resource_version
        and original_replicas > 0
        and str(checkpointed.get("namespace") or "").strip() == identity["namespace"]
        and str(checkpointed.get("name") or "").strip() == identity["name"]
        and str(checkpointed.get("uid") or "").strip() == identity["uid"]
        and checkpointed_fingerprint == fingerprint
    )
    status = _mapping(manager.get("status"))
    metadata = _mapping(manager.get("metadata"))
    paused_live = bool(
        _non_negative_int(status.get("replicas"), fallback=0) == 0
        and _non_negative_int(status.get("readyReplicas"), fallback=0) == 0
        and _non_negative_int(status.get("observedGeneration"), fallback=0)
        >= _non_negative_int(metadata.get("generation"), fallback=0)
    )
    if not exact_checkpoint or not paused_live:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff found a paused Soperator manager without its exact "
            "durable pre-pause replica/UID/resourceVersion proof; cxcli will not "
            "transiently resume it for recapture."
        )
    adopted = dict(checkpointed)
    adopted["spec_fingerprint"] = fingerprint
    adopted.setdefault("capture_generation", generation)
    handoff["manager_paused_generation"] = generation
    return adopted, "manager-paused"


def _checkpoint_immutable_child_handoff_inventory(
    *,
    phase: dict[str, Any],
    state: dict[str, Any],
    source_report: Mapping[str, Any],
    values: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    """Capture every identity that must survive source-CR orphan retirement."""

    handoff = _immutable_child_handoff_state(phase)
    normalized_source = {
        key: str(source_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    normalized_target = {
        key: str(target_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    if (
        normalized_source["namespace"] != _SOPERATOR_NAMESPACE
        or normalized_target["namespace"] != _SOPERATOR_NAMESPACE
        or not all(normalized_source.values())
        or not all(normalized_target.values())
        or normalized_source == normalized_target
    ):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff requires distinct exact source/target bindings."
        )
    if handoff.get("captured_at"):
        if (
            _mapping(handoff.get("source")) != normalized_source
            or _mapping(handoff.get("target")) != normalized_target
        ):
            raise SoperatorMigrationPhasePending(
                "immutable child handoff source/target binding changed after capture."
            )
        if str(handoff.get("status") or "").strip() == "manager-paused":
            if checkpoint_writer is None:
                raise SoperatorMigrationPhasePending(
                    "immutable child paused-manager resume requires durable contract writes."
                )
            manager = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="deployment",
                name="soperator-manager",
            )
            if _mapping(handoff.get("manual_manager_pause_adoption")):
                _adopt_exact_manually_paused_soperator_manager(
                    handoff=handoff,
                    manager=manager,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            prior_manager = dict(_mapping(handoff.get("manager")))
            manager_binding, manager_status = _immutable_child_capture_manager_binding(
                handoff=handoff,
                manager=manager,
            )
            handoff["manager"] = manager_binding
            handoff["status"] = manager_status
            if manager_binding != prior_manager:
                handoff["manager_contract_adopted_at"] = _utc_now()
                checkpoint_writer()
        return handoff
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff requires a durable checkpoint writer before capture."
        )
    source_names = set(
        _source_slurmcluster_names(source_report, target_ref=normalized_target["name"])
    )
    source_names.add(normalized_source["name"])
    _checkpoint_source_orphan_child_bindings(
        state=state,
        source_report=source_report,
        source_binding=normalized_source,
        target_binding=normalized_target,
        source_names=source_names,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    checkpointed = _source_cleanup_checkpointed_child_bindings(
        state=state,
        source_binding=normalized_source,
        target_binding=normalized_target,
        required=True,
    )
    live_inventory = {
        str(item.get("api_path") or "").strip(): item
        for item in _source_slurm_child_resource_inventory(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    }
    worker_names = set(_target_worker_nodeset_names(values))
    collision_candidates = [
        api_path
        for api_path in _mapping(checkpointed)
        if (
            (live := _mapping(live_inventory.get(api_path)))
            and (resource := _mapping(live.get("resource")))
            and _immutable_child_workload_spec(
                api_version=str(resource.get("apiVersion") or "").strip(),
                kind=str(resource.get("kind") or "").strip(),
                name=str(_mapping(live.get("identity")).get("name") or "").strip(),
                worker_names=worker_names,
            )
            is not None
        )
    ]
    if not collision_candidates:
        handoff.update(
            {
                "status": "not-required",
                "source": normalized_source,
                "target": normalized_target,
                "workloads": {},
                "captured_at": _utc_now(),
                "completed_at": _utc_now(),
            }
        )
        checkpoint_writer()
        return handoff
    pods = _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pods",
    )
    replica_sets = _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="replicasets.apps",
    )
    pvcs = _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="persistentvolumeclaims",
    )
    pvc_by_name = {
        str(_mapping(pvc.get("metadata")).get("name") or "").strip(): pvc for pvc in pvcs
    }
    workloads: dict[str, dict[str, Any]] = {}
    for api_path, binding in sorted(_mapping(checkpointed).items()):
        live = _mapping(live_inventory.get(api_path))
        resource = _mapping(live.get("resource"))
        identity = _mapping(live.get("identity"))
        if (
            not resource
            or str(identity.get("uid") or "").strip()
            != str(_mapping(binding).get("uid") or "").strip()
        ):
            raise SoperatorMigrationPhasePending(
                "immutable child handoff source workload changed after durable child capture."
            )
        api_version = str(resource.get("apiVersion") or "").strip()
        kind = str(resource.get("kind") or "").strip()
        name = str(identity.get("name") or "").strip()
        workload_spec = _immutable_child_workload_spec(
            api_version=api_version,
            kind=kind,
            name=name,
            worker_names=worker_names,
        )
        if workload_spec is None:
            continue
        resource_type, component = workload_spec
        workload_uid = str(identity.get("uid") or "").strip()
        owned_replica_sets = []
        owned_replica_set_uids: set[str] = set()
        if kind == "Deployment":
            for replica_set in replica_sets:
                owner = _immutable_child_controller_owner(
                    replica_set,
                    label=f"ReplicaSet for source Deployment {name}",
                )
                if str(_mapping(owner).get("uid") or "").strip() != workload_uid:
                    continue
                replica_identity = _immutable_child_exact_identity(
                    replica_set,
                    label=f"ReplicaSet for source Deployment {name}",
                )
                replica_selector = _mapping(
                    _mapping(_mapping(replica_set.get("spec")).get("selector")).get("matchLabels")
                )
                if not replica_selector or any(
                    not isinstance(key, str) or not key or not isinstance(value, str) or not value
                    for key, value in replica_selector.items()
                ):
                    raise SoperatorMigrationPhasePending(
                        f"ReplicaSet for source Deployment {name} lacks an exact selector."
                    )
                owned_replica_sets.append(
                    {
                        **replica_identity,
                        "selector": dict(replica_selector),
                        "api_path": (
                            "/apis/apps/v1/namespaces/soperator/replicasets/"
                            + replica_identity["name"]
                        ),
                    }
                )
                owned_replica_set_uids.add(replica_identity["uid"])
        owned_pods: list[dict[str, Any]] = []
        claim_names: set[str] = set()
        for pod in pods:
            owner = _immutable_child_controller_owner(
                pod,
                label=f"Pod for source {kind} {name}",
            )
            owner_uid = str(_mapping(owner).get("uid") or "").strip()
            if owner_uid != workload_uid and owner_uid not in owned_replica_set_uids:
                continue
            pod_identity = _immutable_child_exact_identity(
                pod,
                label=f"Pod for source {kind} {name}",
            )
            owned_pods.append(
                {
                    **pod_identity,
                    "api_path": f"/api/v1/namespaces/soperator/pods/{pod_identity['name']}",
                    "ready": _immutable_child_pod_ready(pod),
                    "owner_uid": owner_uid,
                    "labels": dict(_mapping(_mapping(pod.get("metadata")).get("labels"))),
                }
            )
            claim_names.update(_immutable_child_pvc_claim_names(pod))
        captured_pvcs: list[dict[str, Any]] = []
        for claim_name in sorted(claim_names):
            pvc = _mapping(pvc_by_name.get(claim_name))
            if not pvc:
                raise SoperatorMigrationPhasePending(
                    f"immutable child handoff Pod references missing PVC {claim_name}."
                )
            captured_pvcs.append(
                _immutable_child_exact_identity(
                    pvc,
                    label=f"PVC for source {kind} {name}",
                )
            )
        workloads[api_path] = {
            "api_path": api_path,
            "api_version": api_version,
            "kind": kind,
            "resource_type": resource_type,
            "name": name,
            "uid": workload_uid,
            "resource_version": str(identity.get("resourceVersion") or "").strip(),
            "component": component,
            "target_selector": _immutable_child_target_selector(
                target_binding=normalized_target,
                component=component,
            ),
            "pods": owned_pods,
            "replica_sets": owned_replica_sets,
            "pvcs": captured_pvcs,
            "status": "captured",
        }
    required_names = {"controller", "login", *worker_names}
    observed_names = {str(item.get("name") or "") for item in workloads.values()}
    missing = sorted(required_names - observed_names)
    if missing:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff did not capture required source workload(s): "
            + ", ".join(missing)
        )
    login_target_selector = _immutable_child_target_selector(
        target_binding=normalized_target,
        component="login",
    )
    source_login_services: list[dict[str, Any]] = []
    for api_path, live in live_inventory.items():
        resource = _mapping(_mapping(live).get("resource"))
        if str(resource.get("kind") or "").strip() != "Service":
            continue
        metadata = _mapping(resource.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        spec = _mapping(resource.get("spec"))
        selector = {
            str(key): str(value)
            for key, value in _mapping(spec.get("selector")).items()
            if str(key) and str(value)
        }
        checkpointed_service = _mapping(_mapping(checkpointed).get(api_path))
        if (
            checkpointed_service
            and labels.get("app.kubernetes.io/component") == "login"
            and str(spec.get("type") or "").strip() == "LoadBalancer"
        ):
            identity = _immutable_child_exact_identity(
                resource,
                label="source login LoadBalancer Service",
            )
            source_login_services.append(
                {
                    **identity,
                    "api_path": api_path,
                    "selector": selector,
                }
            )
    if not source_login_services:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff requires an exact retained source login LoadBalancer "
            "Service before its selector can move to the pinned target binding."
        )
    manager = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            _IMMUTABLE_CHILD_HANDOFF_MANAGER_RESOURCE,
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    if _resource_replicas(manager, default=-1) == 0:
        _adopt_exact_manually_paused_soperator_manager(
            handoff=handoff,
            manager=manager,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    manager_binding, handoff_status = _immutable_child_capture_manager_binding(
        handoff=handoff,
        manager=manager,
    )
    handoff.update(
        {
            "status": handoff_status,
            "source": normalized_source,
            "target": normalized_target,
            "manager": manager_binding,
            "workloads": workloads,
            "source_login_services": source_login_services,
            "target_login_selector": login_target_selector,
            "captured_at": _utc_now(),
        }
    )
    state["retained_login_service_bindings"] = [
        {
            "namespace": service["namespace"],
            "name": service["name"],
            "uid": service["uid"],
            "target_selector": dict(login_target_selector),
        }
        for service in source_login_services
    ]
    checkpoint_writer()
    return handoff


def _immutable_child_get_namespaced_resource(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    resource_type: str,
    name: str,
) -> Mapping[str, Any]:
    return _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"{resource_type}/{name}",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )


def _immutable_child_optional_namespaced_resource(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    resource_type: str,
    name: str,
    label: str,
) -> Mapping[str, Any] | None:
    try:
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                f"{resource_type}/{name}",
                "--ignore-not-found",
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise SoperatorMigrationPhasePending(
            f"{label} absence proof timed out; API output was redacted."
        ) from exc
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"{label} exact read-or-absence proof failed; API output was redacted."
        )
    if not str(result.stdout or "").strip():
        return None
    try:
        payload = json.loads(result.stdout or "")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            f"{label} returned invalid JSON during exact absence proof."
        ) from exc
    if not isinstance(payload, Mapping) or not _mapping(payload.get("metadata")):
        raise SoperatorMigrationPhasePending(
            f"{label} returned an incomplete object during exact absence proof."
        )
    return payload


def _immutable_child_require_live_uid(
    resource: Mapping[str, Any],
    *,
    expected_uid: str,
    label: str,
) -> dict[str, str]:
    if not _mapping(resource.get("metadata")):
        raise SoperatorMigrationPhasePending(f"{label} disappeared before its durable intent.")
    identity = _immutable_child_exact_identity(resource, label=label)
    if identity["uid"] != expected_uid:
        raise SoperatorMigrationPhasePending(
            f"{label} UID changed after immutable handoff capture."
        )
    return identity


def _immutable_child_wait_manager_replicas(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    expected_uid: str,
    replicas: int,
    timeout_seconds: int = 300,
) -> dict[str, str]:
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        manager = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name="soperator-manager",
        )
        identity = _immutable_child_require_live_uid(
            manager,
            expected_uid=expected_uid,
            label="Soperator manager Deployment",
        )
        desired = _resource_replicas(manager, default=-1)
        status = _mapping(manager.get("status"))
        observed = _non_negative_int(status.get("observedGeneration"), fallback=0)
        generation = _non_negative_int(
            _mapping(manager.get("metadata")).get("generation"), fallback=0
        )
        status_replicas = _non_negative_int(status.get("replicas"), fallback=0)
        ready = _non_negative_int(status.get("readyReplicas"), fallback=0)
        if (
            desired == replicas
            and status_replicas == replicas
            and ready == replicas
            and observed >= generation
        ):
            return identity
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "Soperator manager did not converge to the checkpointed immutable-child "
                f"handoff replica count {replicas}."
            )
        time.sleep(2)


def _pause_soperator_manager_for_child_handoff(
    *,
    handoff: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff requires durable manager-pause checkpoints."
        )
    manager_binding = _mapping(handoff.get("manager"))
    expected_uid = str(manager_binding.get("uid") or "").strip()
    original_replicas = _non_negative_int(manager_binding.get("replicas"), fallback=0)
    if not expected_uid or original_replicas <= 0:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff lacks the exact original Soperator manager binding."
        )
    manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    identity = _immutable_child_require_live_uid(
        manager,
        expected_uid=expected_uid,
        label="Soperator manager Deployment",
    )
    manager_fingerprint, manager_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=manager,
    )
    if not str(manager_binding.get("spec_fingerprint") or "").strip():
        raise SoperatorMigrationPhasePending(
            "immutable child handoff refuses manager pause without its pre-mutation spec "
            "fingerprint."
        )
    desired = _resource_replicas(manager, default=-1)
    if desired not in {0, original_replicas}:
        raise SoperatorMigrationPhasePending(
            "Soperator manager replica count drifted outside the checkpointed pause transition."
        )
    capture_generation = _positive_int(manager_binding.get("capture_generation"), fallback=0)
    expected_pause_generation = capture_generation + 1
    pause_intent_at = str(handoff.get("manager_pause_intent_at") or "").strip()
    if not pause_intent_at:
        if (
            desired != original_replicas
            or capture_generation <= 0
            or manager_generation != capture_generation
        ):
            raise SoperatorMigrationPhasePending(
                "immutable child handoff found a paused manager without a durable "
                "pre-scale pause intent."
            )
        handoff.update(
            {
                "manager_pause_intent_at": _utc_now(),
                "manager_pause_from_resource_version": identity["resourceVersion"],
                "manager_pause_from_generation": capture_generation,
                "manager_pause_expected_generation": expected_pause_generation,
            }
        )
        checkpoint_writer()
    elif (
        not str(handoff.get("manager_pause_from_resource_version") or "").strip()
        or _positive_int(handoff.get("manager_pause_from_generation"), fallback=0)
        != capture_generation
        or _positive_int(handoff.get("manager_pause_expected_generation"), fallback=0)
        != expected_pause_generation
    ):
        if desired != original_replicas or manager_generation != capture_generation:
            raise SoperatorMigrationPhasePending(
                "immutable child handoff manager pause intent lacks its exact pre-scale "
                "resourceVersion/generation fence."
            )
        handoff.update(
            {
                "manager_pause_from_resource_version": identity["resourceVersion"],
                "manager_pause_from_generation": capture_generation,
                "manager_pause_expected_generation": expected_pause_generation,
            }
        )
        checkpoint_writer()
    if desired == original_replicas:
        if manager_generation != capture_generation:
            raise SoperatorMigrationPhasePending(
                "immutable child handoff manager generation drifted after its durable pause intent."
            )
        if (
            identity["resourceVersion"]
            != str(handoff.get("manager_pause_from_resource_version") or "").strip()
        ):
            handoff["manager_pause_from_resource_version"] = identity["resourceVersion"]
            handoff["manager_pause_resource_version_refreshed_at"] = _utc_now()
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=_IMMUTABLE_CHILD_HANDOFF_MANAGER_RESOURCE,
            replicas=0,
            current_replicas=original_replicas,
            resource_version=identity["resourceVersion"],
        )
    elif manager_generation != expected_pause_generation:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff found a paused manager outside the single "
            "checkpointed pause generation transition."
        )
    paused_identity = _immutable_child_wait_manager_replicas(
        command_runner=command_runner,
        kube_context=kube_context,
        expected_uid=expected_uid,
        replicas=0,
    )
    paused_manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    paused_fingerprint, paused_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=paused_manager,
    )
    if paused_fingerprint != manager_fingerprint or paused_generation != expected_pause_generation:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff manager spec/generation changed outside the single "
            "checkpointed pause transition."
        )
    handoff["manager_paused_resource_version"] = paused_identity["resourceVersion"]
    handoff["manager_paused_generation"] = paused_generation
    handoff["manager_paused_at"] = _utc_now()
    handoff["status"] = "manager-paused"
    checkpoint_writer()


def _restore_soperator_manager_after_child_handoff(
    *,
    handoff: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff requires durable manager-restore checkpoints."
        )
    manager_binding = _mapping(handoff.get("manager"))
    expected_uid = str(manager_binding.get("uid") or "").strip()
    original_replicas = _non_negative_int(manager_binding.get("replicas"), fallback=0)
    manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    identity = _immutable_child_require_live_uid(
        manager,
        expected_uid=expected_uid,
        label="Soperator manager Deployment",
    )
    manager_fingerprint, manager_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=manager,
    )
    paused_generation = _positive_int(handoff.get("manager_paused_generation"), fallback=0)
    if (
        not expected_uid
        or original_replicas <= 0
        or not str(manager_binding.get("spec_fingerprint") or "").strip()
        or paused_generation <= 0
    ):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff lacks the exact paused manager UID/replica/spec/"
            "generation contract required before restore."
        )
    desired = _resource_replicas(manager, default=-1)
    if desired not in {0, original_replicas}:
        raise SoperatorMigrationPhasePending(
            "Soperator manager replica count drifted before immutable-child restore."
        )
    restore_intent_at = str(handoff.get("manager_restore_intent_at") or "").strip()
    expected_restore_generation = paused_generation + 1
    if not restore_intent_at:
        if desired != 0 or manager_generation != paused_generation:
            raise SoperatorMigrationPhasePending(
                "immutable child handoff found a resumed manager without a durable "
                "pre-scale restore intent."
            )
        handoff.update(
            {
                "manager_restore_intent_at": _utc_now(),
                "manager_restore_from_resource_version": identity["resourceVersion"],
                "manager_restore_from_generation": paused_generation,
                "manager_restore_expected_generation": expected_restore_generation,
            }
        )
        checkpoint_writer()
    elif (
        not str(handoff.get("manager_restore_from_resource_version") or "").strip()
        or _positive_int(handoff.get("manager_restore_from_generation"), fallback=0)
        != paused_generation
        or _positive_int(handoff.get("manager_restore_expected_generation"), fallback=0)
        != expected_restore_generation
    ):
        if desired != 0 or manager_generation != paused_generation:
            raise SoperatorMigrationPhasePending(
                "immutable child handoff manager restore intent lacks its exact pre-scale "
                "resourceVersion/generation fence."
            )
        handoff.update(
            {
                "manager_restore_from_resource_version": identity["resourceVersion"],
                "manager_restore_from_generation": paused_generation,
                "manager_restore_expected_generation": expected_restore_generation,
            }
        )
        checkpoint_writer()
    if desired == 0:
        if manager_generation != paused_generation:
            raise SoperatorMigrationPhasePending(
                "immutable child handoff paused manager generation drifted after its "
                "durable restore intent."
            )
        if (
            identity["resourceVersion"]
            != str(handoff.get("manager_restore_from_resource_version") or "").strip()
        ):
            handoff["manager_restore_from_resource_version"] = identity["resourceVersion"]
            handoff["manager_restore_resource_version_refreshed_at"] = _utc_now()
            checkpoint_writer()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=_IMMUTABLE_CHILD_HANDOFF_MANAGER_RESOURCE,
            replicas=original_replicas,
            current_replicas=0,
            resource_version=identity["resourceVersion"],
        )
    elif manager_generation != expected_restore_generation:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff found a manager at its original replica count but "
            "outside the single checkpointed restore generation transition."
        )
    restored_identity = _immutable_child_wait_manager_replicas(
        command_runner=command_runner,
        kube_context=kube_context,
        expected_uid=expected_uid,
        replicas=original_replicas,
    )
    restored_manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    restored_fingerprint, restored_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=restored_manager,
    )
    if (
        restored_fingerprint != manager_fingerprint
        or restored_generation != expected_restore_generation
    ):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff manager spec/generation changed outside the single "
            "checkpointed restore transition."
        )
    handoff["manager_restored_resource_version"] = restored_identity["resourceVersion"]
    handoff["manager_restored_generation"] = restored_generation
    handoff["manager_restored_at"] = _utc_now()
    handoff["status"] = "manager-restored"
    checkpoint_writer()


def _immutable_child_patch_exact_labels(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    resource_type: str,
    name: str,
    expected_uid: str,
    labels: Mapping[str, str],
) -> dict[str, str]:
    live = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type=resource_type,
        name=name,
    )
    identity = _immutable_child_require_live_uid(
        live,
        expected_uid=expected_uid,
        label=f"immutable child {resource_type} {_SOPERATOR_NAMESPACE}/{name}",
    )
    current_labels = _mapping(_mapping(live.get("metadata")).get("labels"))
    if any(str(current_labels.get(key) or "") != value for key, value in labels.items()):
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"{resource_type}/{name}",
            patch={
                "metadata": {
                    "resourceVersion": identity["resourceVersion"],
                    "labels": dict(labels),
                }
            },
        )
    updated = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type=resource_type,
        name=name,
    )
    updated_identity = _immutable_child_require_live_uid(
        updated,
        expected_uid=expected_uid,
        label=f"immutable child {resource_type} {_SOPERATOR_NAMESPACE}/{name}",
    )
    updated_labels = _mapping(_mapping(updated.get("metadata")).get("labels"))
    if any(str(updated_labels.get(key) or "") != value for key, value in labels.items()):
        raise SoperatorMigrationPhasePending(
            f"immutable child {resource_type} {_SOPERATOR_NAMESPACE}/{name} label patch did not converge."
        )
    return updated_identity


def _login_handoff_exact_ready_pods(
    *,
    handoff: Mapping[str, Any],
    required_labels: Mapping[str, str],
    require_live_workload: bool,
    minimum_ready: int,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[dict[str, str], ...]:
    login_items = [
        item
        for item in _mapping(handoff.get("workloads")).values()
        if isinstance(item, Mapping)
        and item.get("component") == "login"
        and item.get("kind") == "StatefulSet"
    ]
    if len(login_items) != 1:
        raise SoperatorMigrationPhasePending(
            "login handoff bridge lacks one exact captured source login workload."
        )
    item = login_items[0]
    workload_uid = str(item.get("uid") or "").strip()
    workload_name = str(item.get("name") or "").strip()
    workload_api_version = str(item.get("api_version") or "").strip()
    if not workload_uid or not workload_name or not workload_api_version:
        raise SoperatorMigrationPhasePending(
            "login handoff bridge source workload identity is incomplete."
        )
    if require_live_workload:
        workload = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type=str(item.get("resource_type") or "statefulsets.apps.kruise.io"),
            name=workload_name,
        )
        _immutable_child_require_live_uid(
            workload,
            expected_uid=workload_uid,
            label="login handoff source workload",
        )
        source_binding = _legacy_rootfs_bridge_binding(
            _mapping(handoff.get("source")),
            label="login handoff source SlurmCluster",
        )
        _legacy_rootfs_bridge_controller_owner(
            workload,
            allowed_bindings={"source": source_binding},
            label="login handoff source workload",
        )
        if _mapping(workload.get("metadata")).get("deletionTimestamp"):
            raise SoperatorMigrationPhasePending(
                "login handoff source workload is terminating before selector mutation."
            )
    elif (
        str(item.get("status") or "") != "pods-relabeled"
        or not str(item.get("orphaned_at") or "").strip()
        or not str(item.get("pods_relabeled_at") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "login handoff target-selector switch lacks durable Pod Orphan/relabel proof."
        )
    ready: list[dict[str, str]] = []
    for captured in _sequence_of_mappings(item.get("pods")):
        name = str(captured.get("name") or "").strip()
        uid = str(captured.get("uid") or "").strip()
        if not name or not uid:
            raise SoperatorMigrationPhasePending(
                "login handoff captured Pod identity is incomplete."
            )
        pod = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=name,
        )
        if not _mapping(pod.get("metadata")):
            continue
        identity = _immutable_child_require_live_uid(
            pod,
            expected_uid=uid,
            label="login handoff captured Pod",
        )
        owner = _immutable_child_controller_owner(
            pod,
            label="login handoff captured Pod",
        )
        labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
        exact_source_owner = bool(
            str(_mapping(owner).get("apiVersion") or "") == workload_api_version
            and str(_mapping(owner).get("kind") or "") == "StatefulSet"
            and str(_mapping(owner).get("name") or "") == workload_name
            and str(_mapping(owner).get("uid") or "") == workload_uid
        )
        owner_contract = (
            exact_source_owner
            if require_live_workload
            else not _validated_resource_owner_references(
                pod,
                label="orphaned login handoff captured Pod",
            )
        )
        if not owner_contract or any(
            str(labels.get(key) or "") != value for key, value in required_labels.items()
        ):
            raise SoperatorMigrationPhasePending(
                "login handoff captured Pod drifted from its exact workload/label binding."
            )
        if _immutable_child_pod_ready(pod):
            ready.append(identity)
    if len(ready) < minimum_ready:
        raise SoperatorMigrationPhasePending(
            "login handoff lacks enough exact current Ready captured Pods before selector mutation."
        )
    return tuple(sorted(ready, key=lambda item: item["name"]))


def _login_handoff_require_exact_service_endpoints(
    *,
    handoff: Mapping[str, Any],
    ready_pods: Sequence[Mapping[str, str]],
    expected_selectors: Mapping[str, Mapping[str, str]],
    service_owner_mode: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    timeout_seconds: int,
) -> None:
    source_binding = _legacy_rootfs_bridge_binding(
        _mapping(handoff.get("source")),
        label="login handoff source SlurmCluster",
    )
    candidates = {str(pod.get("uid") or ""): str(pod.get("name") or "") for pod in ready_pods}
    if not candidates:
        raise SoperatorMigrationPhasePending(
            "login handoff endpoint proof lacks exact Ready Pod identities."
        )
    if service_owner_mode not in {"source", "orphan"}:
        raise SoperatorMigrationPhasePending(
            "login handoff endpoint proof requested an unsupported Service owner phase."
        )
    if service_owner_mode == "orphan":
        source_resource = _immutable_child_optional_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="slurmcluster",
            name=source_binding["name"],
            label="login handoff source SlurmCluster",
        )
        if source_resource is not None:
            raise SoperatorMigrationPhasePending(
                "login target-selector switch requires the exact source SlurmCluster to be absent."
            )
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        pending: list[str] = []
        matched_endpoint_uids: dict[str, set[str]] = {}
        for service_binding in _sequence_of_mappings(handoff.get("source_login_services")):
            name = str(service_binding.get("name") or "").strip()
            service = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="service",
                name=name,
            )
            _immutable_child_require_live_uid(
                service,
                expected_uid=str(service_binding.get("uid") or ""),
                label=f"retained login Service {_SOPERATOR_NAMESPACE}/{name}",
            )
            if service_owner_mode == "source":
                _legacy_rootfs_bridge_controller_owner(
                    service,
                    allowed_bindings={"source": source_binding},
                    label=f"retained login Service {_SOPERATOR_NAMESPACE}/{name}",
                )
            elif _validated_resource_owner_references(
                service,
                label=f"orphaned retained login Service {_SOPERATOR_NAMESPACE}/{name}",
            ):
                raise SoperatorMigrationPhasePending(
                    "orphaned retained login Service acquired an unauthorized owner."
                )
            if _mapping(_mapping(service.get("spec")).get("selector")) != _mapping(
                expected_selectors.get(name)
            ):
                raise SoperatorMigrationPhasePending(
                    f"retained login Service {name} selector drifted outside its exact bridge state."
                )
            slices = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    "endpointslices.discovery.k8s.io",
                    "-l",
                    f"kubernetes.io/service-name={name}",
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
                check=False,
            )
            exact_ready_uids: set[str] = set()
            for endpoint_slice in _sequence_of_mappings(slices.get("items")):
                owner = _immutable_child_controller_owner(
                    endpoint_slice,
                    label=f"retained login EndpointSlice for {name}",
                )
                if (
                    str(_mapping(owner).get("apiVersion") or "") != "v1"
                    or str(_mapping(owner).get("kind") or "") != "Service"
                    or str(_mapping(owner).get("name") or "") != name
                    or str(_mapping(owner).get("uid") or "")
                    != str(service_binding.get("uid") or "")
                ):
                    raise SoperatorMigrationPhasePending(
                        "retained login EndpointSlice is not controlled by its exact Service."
                    )
                for endpoint in _sequence_of_mappings(endpoint_slice.get("endpoints")):
                    target_ref = _mapping(endpoint.get("targetRef"))
                    uid = str(target_ref.get("uid") or "").strip()
                    if (
                        _mapping(endpoint.get("conditions")).get("ready") is True
                        and str(target_ref.get("kind") or "").strip().lower() == "pod"
                        and uid in candidates
                        and str(target_ref.get("namespace") or _SOPERATOR_NAMESPACE)
                        == _SOPERATOR_NAMESPACE
                        and str(target_ref.get("name") or "") == candidates[uid]
                    ):
                        exact_ready_uids.add(uid)
            matched_endpoint_uids[name] = exact_ready_uids
            refreshed_ready = _login_handoff_exact_ready_pods(
                handoff=handoff,
                required_labels=_mapping(expected_selectors.get(name)),
                require_live_workload=service_owner_mode == "source",
                minimum_ready=1,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            refreshed_uids = {pod["uid"] for pod in refreshed_ready}
            if not exact_ready_uids.intersection(refreshed_uids):
                pending.append(name)
        if not pending:
            for name, endpoint_uids in matched_endpoint_uids.items():
                final_ready = _login_handoff_exact_ready_pods(
                    handoff=handoff,
                    required_labels=_mapping(expected_selectors.get(name)),
                    require_live_workload=service_owner_mode == "source",
                    minimum_ready=1,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
                if not endpoint_uids.intersection({pod["uid"] for pod in final_ready}):
                    pending.append(name)
            if not pending:
                return
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "retained login Service lacks an exact Ready captured backend: "
                + ", ".join(pending)
            )
        time.sleep(2)


def _prepare_login_handoff_bridge(
    *,
    handoff: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "login handoff bridge requires durable checkpoint writes."
        )
    bridge = handoff.setdefault("login_bridge", {})
    if not isinstance(bridge, dict):
        raise SoperatorMigrationPhasePending("login handoff bridge checkpoint is malformed.")
    if bridge.get("status") == "target-selector-ready":
        return
    login_workload = next(
        (
            item
            for item in _mapping(handoff.get("workloads")).values()
            if _mapping(item).get("component") == "login"
        ),
        None,
    )
    login_pods = _sequence_of_mappings(_mapping(login_workload).get("pods"))
    ready_pods = [pod for pod in login_pods if pod.get("ready") is True]
    if not ready_pods:
        raise SoperatorMigrationPhasePending(
            "immutable login handoff requires at least one captured Ready source login Pod."
        )
    token = (
        "handoff-"
        + hashlib.sha256(
            str(_mapping(handoff.get("source")).get("uid") or "").encode()
        ).hexdigest()[:16]
    )
    if bridge and str(bridge.get("token") or "") != token:
        raise SoperatorMigrationPhasePending("login handoff bridge token drifted after capture.")
    bridge.setdefault("token", token)
    bridge.setdefault("intent_at", _utc_now())
    bridge.setdefault("status", "token-selector-intent")
    if bridge.get("status") not in {"token-selector-intent", "token-selector-ready"}:
        raise SoperatorMigrationPhasePending(
            "login handoff bridge cannot resume from its checkpointed selector state."
        )
    checkpoint_writer()
    token_selector = {_IMMUTABLE_CHILD_HANDOFF_LABEL: token}
    current_ready_pods = _login_handoff_exact_ready_pods(
        handoff=handoff,
        required_labels={},
        require_live_workload=True,
        minimum_ready=1,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    current_selectors: dict[str, Mapping[str, str]] = {}
    for service_binding in _sequence_of_mappings(handoff.get("source_login_services")):
        name = str(service_binding.get("name") or "").strip()
        service = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="service",
            name=name,
        )
        live_selector = _mapping(_mapping(service.get("spec")).get("selector"))
        captured_selector = _mapping(service_binding.get("selector"))
        merge_bug_selector = {**captured_selector, **token_selector}
        if live_selector not in (captured_selector, token_selector, merge_bug_selector):
            raise SoperatorMigrationPhasePending(
                f"retained login Service {name} escaped its original-to-token transition."
            )
        current_selectors[name] = live_selector
    _login_handoff_require_exact_service_endpoints(
        handoff=handoff,
        ready_pods=current_ready_pods,
        expected_selectors=current_selectors,
        service_owner_mode="source",
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=0,
    )
    for pod in current_ready_pods:
        _immutable_child_patch_exact_labels(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=str(pod.get("name") or ""),
            expected_uid=str(pod.get("uid") or ""),
            labels=token_selector,
        )
    current_ready_pods = _login_handoff_exact_ready_pods(
        handoff=handoff,
        required_labels=token_selector,
        require_live_workload=True,
        minimum_ready=1,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    service_names: list[str] = []
    for service in _sequence_of_mappings(handoff.get("source_login_services")):
        _login_handoff_require_exact_service_endpoints(
            handoff=handoff,
            ready_pods=current_ready_pods,
            expected_selectors=current_selectors,
            service_owner_mode="source",
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=0,
        )
        name = str(service.get("name") or "").strip()
        live = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="service",
            name=name,
        )
        identity = _immutable_child_require_live_uid(
            live,
            expected_uid=str(service.get("uid") or ""),
            label=f"retained login Service {_SOPERATOR_NAMESPACE}/{name}",
        )
        _legacy_rootfs_bridge_controller_owner(
            live,
            allowed_bindings={
                "source": _legacy_rootfs_bridge_binding(
                    _mapping(handoff.get("source")),
                    label="login handoff source SlurmCluster",
                )
            },
            label=f"retained login Service {_SOPERATOR_NAMESPACE}/{name}",
        )
        selector = _mapping(_mapping(live.get("spec")).get("selector"))
        if selector != token_selector:
            _kubectl_replace_service_selector(
                command_runner=command_runner,
                kube_context=kube_context,
                name=name,
                expected_uid=identity["uid"],
                expected_resource_version=identity["resourceVersion"],
                selector=token_selector,
            )
        current_selectors[name] = token_selector
        service_names.append(name)
        _login_handoff_require_exact_service_endpoints(
            handoff=handoff,
            ready_pods=current_ready_pods,
            expected_selectors=current_selectors,
            service_owner_mode="source",
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=300,
        )
    _login_handoff_require_exact_service_endpoints(
        handoff=handoff,
        ready_pods=current_ready_pods,
        expected_selectors={name: token_selector for name in service_names},
        service_owner_mode="source",
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=300,
    )
    bridge["status"] = "token-selector-ready"
    bridge["service_names"] = service_names
    bridge["ready_at"] = _utc_now()
    checkpoint_writer()


def _switch_login_bridge_to_target_selector(
    *,
    handoff: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "login target-selector bridge requires durable checkpoint writes."
        )
    bridge = handoff.get("login_bridge")
    if not isinstance(bridge, dict) or bridge.get("status") not in {
        "token-selector-ready",
        "target-selector-ready",
    }:
        raise SoperatorMigrationPhasePending(
            "login target-selector switch lacks its exact token-selector bridge."
        )
    target_selector = {
        str(key): str(value)
        for key, value in _mapping(handoff.get("target_login_selector")).items()
    }
    if set(target_selector) != set(_IMMUTABLE_CHILD_SELECTOR_LABELS):
        raise SoperatorMigrationPhasePending(
            "login target-selector switch lacks the pinned Soperator selector contract."
        )
    token = str(bridge.get("token") or "")
    bridge.setdefault("target_selector_intent_at", _utc_now())
    checkpoint_writer()
    ready_pods = _login_handoff_exact_ready_pods(
        handoff=handoff,
        required_labels={**target_selector, _IMMUTABLE_CHILD_HANDOFF_LABEL: token},
        require_live_workload=False,
        minimum_ready=1,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    token_selector = {_IMMUTABLE_CHILD_HANDOFF_LABEL: token}
    merge_bug_selector = {**target_selector, **token_selector}
    current_selectors: dict[str, Mapping[str, str]] = {}
    for service_binding in _sequence_of_mappings(handoff.get("source_login_services")):
        name = str(service_binding.get("name") or "")
        live = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="service",
            name=name,
        )
        selector = _mapping(_mapping(live.get("spec")).get("selector"))
        if selector not in (token_selector, target_selector, merge_bug_selector):
            raise SoperatorMigrationPhasePending(
                f"retained login Service {name} escaped its token-to-target transition."
            )
        current_selectors[name] = selector
    _login_handoff_require_exact_service_endpoints(
        handoff=handoff,
        ready_pods=ready_pods,
        expected_selectors=current_selectors,
        service_owner_mode="orphan",
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=0,
    )
    for service in _sequence_of_mappings(handoff.get("source_login_services")):
        _login_handoff_require_exact_service_endpoints(
            handoff=handoff,
            ready_pods=ready_pods,
            expected_selectors=current_selectors,
            service_owner_mode="orphan",
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=0,
        )
        name = str(service.get("name") or "")
        live = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="service",
            name=name,
        )
        identity = _immutable_child_require_live_uid(
            live,
            expected_uid=str(service.get("uid") or ""),
            label=f"retained login Service {_SOPERATOR_NAMESPACE}/{name}",
        )
        if _validated_resource_owner_references(
            live,
            label=f"orphaned retained login Service {_SOPERATOR_NAMESPACE}/{name}",
        ):
            raise SoperatorMigrationPhasePending(
                "orphaned retained login Service acquired an unauthorized owner."
            )
        if _mapping(_mapping(live.get("spec")).get("selector")) != target_selector:
            _kubectl_replace_service_selector(
                command_runner=command_runner,
                kube_context=kube_context,
                name=name,
                expected_uid=identity["uid"],
                expected_resource_version=identity["resourceVersion"],
                selector=target_selector,
            )
        current_selectors[name] = target_selector
        _login_handoff_require_exact_service_endpoints(
            handoff=handoff,
            ready_pods=ready_pods,
            expected_selectors=current_selectors,
            service_owner_mode="orphan",
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=300,
        )
    _login_handoff_require_exact_service_endpoints(
        handoff=handoff,
        ready_pods=ready_pods,
        expected_selectors={
            str(item.get("name") or ""): target_selector
            for item in _sequence_of_mappings(handoff.get("source_login_services"))
        },
        service_owner_mode="orphan",
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=300,
    )
    bridge["status"] = "target-selector-ready"
    bridge["target_selector_ready_at"] = _utc_now()
    checkpoint_writer()


def _immutable_child_wait_captured_dependents_orphaned(
    *,
    item: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    timeout_seconds: int = 180,
) -> None:
    old_uid = str(item.get("uid") or "").strip()
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        pending: list[str] = []
        for pod in _sequence_of_mappings(item.get("pods")):
            name = str(pod.get("name") or "")
            live = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=name,
            )
            _immutable_child_require_live_uid(
                live,
                expected_uid=str(pod.get("uid") or ""),
                label=f"preserved Pod {_SOPERATOR_NAMESPACE}/{name}",
            )
            owner = _immutable_child_controller_owner(
                live,
                label=f"preserved Pod {_SOPERATOR_NAMESPACE}/{name}",
            )
            if str(_mapping(owner).get("uid") or "").strip() == old_uid:
                pending.append(f"Pod/{name}")
        for replica_set in _sequence_of_mappings(item.get("replica_sets")):
            name = str(replica_set.get("name") or "")
            live = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="replicaset.apps",
                name=name,
            )
            _immutable_child_require_live_uid(
                live,
                expected_uid=str(replica_set.get("uid") or ""),
                label=f"preserved ReplicaSet {_SOPERATOR_NAMESPACE}/{name}",
            )
            owner = _immutable_child_controller_owner(
                live,
                label=f"preserved ReplicaSet {_SOPERATOR_NAMESPACE}/{name}",
            )
            if str(_mapping(owner).get("uid") or "").strip() == old_uid:
                pending.append(f"ReplicaSet/{name}")
        for pvc in _sequence_of_mappings(item.get("pvcs")):
            name = str(pvc.get("name") or "")
            live = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="persistentvolumeclaim",
                name=name,
            )
            _immutable_child_require_live_uid(
                live,
                expected_uid=str(pvc.get("uid") or ""),
                label=f"preserved PVC {_SOPERATOR_NAMESPACE}/{name}",
            )
        if not pending:
            return
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "immutable child Orphan deletion did not release captured dependents: "
                + ", ".join(pending)
            )
        time.sleep(2)


def _revalidate_immutable_child_pvcs(
    *,
    item: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    """Reject missing or same-name replacement PVCs at every adoption boundary."""

    for pvc in _sequence_of_mappings(item.get("pvcs")):
        name = str(pvc.get("name") or "").strip()
        expected_uid = str(pvc.get("uid") or "").strip()
        if not name or not expected_uid:
            raise SoperatorMigrationPhasePending(
                "immutable child PVC checkpoint lacks an exact name/UID binding."
            )
        live = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="persistentvolumeclaim",
            name=name,
        )
        _immutable_child_require_live_uid(
            live,
            expected_uid=expected_uid,
            label=f"preserved PVC {_SOPERATOR_NAMESPACE}/{name}",
        )


def _orphan_delete_bound_workload(
    *,
    item: dict[str, Any],
    source_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> None:
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "immutable child Orphan deletion requires durable checkpoint writes."
        )
    source_uid = str(item.get("uid") or "").strip()
    resource_type = str(item.get("resource_type") or "").strip()
    name = str(item.get("name") or "").strip()
    status = str(item.get("status") or "").strip()
    if status in {"orphaned", "pods-relabeled", "target-bound", "cleaned"}:
        _revalidate_immutable_child_pvcs(
            item=item,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        return
    live = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type=resource_type,
        name=name,
    )
    live_metadata = _mapping(live.get("metadata"))
    live_uid = str(live_metadata.get("uid") or "").strip()
    if live_uid and live_uid != source_uid:
        if status != "orphan-delete-intent":
            raise SoperatorMigrationPhasePending(
                f"immutable child {item.get('kind')} {name} was replaced before delete intent."
            )
    elif live_uid == source_uid:
        identity = _immutable_child_exact_identity(
            live,
            label=f"source {item.get('kind')} {_SOPERATOR_NAMESPACE}/{name}",
        )
        if status == "captured":
            source = _legacy_rootfs_bridge_binding(
                source_binding,
                label="immutable child source SlurmCluster",
            )
            source_resource = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="slurmcluster",
                name=source["name"],
                label="immutable child source SlurmCluster",
            )
            if source_resource is not None:
                raise SoperatorMigrationPhasePending(
                    f"immutable child {item.get('kind')} {name} cannot be orphaned before "
                    "the exact source SlurmCluster is absent."
                )
            if _validated_resource_owner_references(
                live,
                label=f"orphaned source {item.get('kind')} {_SOPERATOR_NAMESPACE}/{name}",
            ):
                raise SoperatorMigrationPhasePending(
                    f"orphaned source {item.get('kind')} {name} acquired an unauthorized owner."
                )
            item["orphan_delete_resource_version"] = identity["resourceVersion"]
            item["status"] = "orphan-delete-intent"
            item["orphan_delete_intent_at"] = _utc_now()
            checkpoint_writer()
        elif str(item.get("orphan_delete_resource_version") or "") != identity["resourceVersion"]:
            raise SoperatorMigrationPhasePending(
                f"source {item.get('kind')} {name} resourceVersion drifted after delete intent."
            )
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=str(item.get("api_path") or ""),
            uid=source_uid,
            resource_version=identity["resourceVersion"],
            propagation_policy="Orphan",
            timeout_seconds=420,
            mutation_guard=mutation_guard,
        )
    elif status != "orphan-delete-intent":
        raise SoperatorMigrationPhasePending(
            f"source {item.get('kind')} {name} disappeared before delete intent."
        )
    _immutable_child_wait_captured_dependents_orphaned(
        item=item,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    item["status"] = "orphaned"
    item["orphaned_at"] = _utc_now()
    checkpoint_writer()


def _relabel_orphan_pods_for_target_adoption(
    *,
    item: dict[str, Any],
    handoff_token: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    _revalidate_immutable_child_pvcs(
        item=item,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    component = str(item.get("component") or "")
    if component in {"sconfigcontroller", "rest"} or (
        component == "controller" and item.get("kind") == "StatefulSet"
    ):
        return
    if str(item.get("status") or "") not in {"orphaned", "pods-relabeled"}:
        raise SoperatorMigrationPhasePending(
            f"immutable child {item.get('name')} Pods cannot be relabeled before Orphan deletion."
        )
    target_selector = {
        str(key): str(value) for key, value in _mapping(item.get("target_selector")).items()
    }
    if set(target_selector) != set(_IMMUTABLE_CHILD_SELECTOR_LABELS):
        raise SoperatorMigrationPhasePending(
            f"immutable child {item.get('name')} lacks the pinned target selector."
        )
    for pod in _sequence_of_mappings(item.get("pods")):
        pod_name = str(pod.get("name") or "")
        live_pod = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=pod_name,
        )
        _immutable_child_require_live_uid(
            live_pod,
            expected_uid=str(pod.get("uid") or ""),
            label=f"orphaned immutable child Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
        )
        if _validated_resource_owner_references(
            live_pod,
            label=f"orphaned immutable child Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
        ):
            raise SoperatorMigrationPhasePending(
                f"orphaned immutable child Pod {pod_name} acquired an unauthorized owner."
            )
        labels = dict(target_selector)
        if component == "login":
            labels[_IMMUTABLE_CHILD_HANDOFF_LABEL] = handoff_token
        _immutable_child_patch_exact_labels(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=pod_name,
            expected_uid=str(pod.get("uid") or ""),
            labels=labels,
        )
    item["status"] = "pods-relabeled"
    item["pods_relabeled_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()


def _delete_captured_controller_pods_for_spool_handoff(
    *,
    item: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> None:
    if item.get("component") != "controller" or item.get("kind") != "StatefulSet":
        return
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "controller Pod handoff requires durable checkpoint writes."
        )
    if (
        str(item.get("status") or "") != "orphaned"
        or not str(item.get("orphaned_at") or "").strip()
    ):
        raise SoperatorMigrationPhasePending(
            "controller Pod cleanup lacks durable source StatefulSet Orphan proof."
        )
    cleanup = item.setdefault("controller_pod_cleanup", {})
    if not isinstance(cleanup, dict):
        raise SoperatorMigrationPhasePending("controller Pod cleanup checkpoint is malformed.")
    for pod in _sequence_of_mappings(item.get("pods")):
        name = str(pod.get("name") or "")
        pod_state = cleanup.setdefault(name, {})
        if not isinstance(pod_state, dict):
            raise SoperatorMigrationPhasePending("controller Pod cleanup item is malformed.")
        live = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=name,
        )
        live_uid = str(_mapping(live.get("metadata")).get("uid") or "").strip()
        if live_uid:
            identity = _immutable_child_require_live_uid(
                live,
                expected_uid=str(pod.get("uid") or ""),
                label=f"source controller Pod {_SOPERATOR_NAMESPACE}/{name}",
            )
            if not pod_state.get("delete_intent_at"):
                if _validated_resource_owner_references(
                    live,
                    label=f"orphaned source controller Pod {_SOPERATOR_NAMESPACE}/{name}",
                ):
                    raise SoperatorMigrationPhasePending(
                        f"orphaned source controller Pod {name} acquired an unauthorized owner."
                    )
                pod_state.update(
                    {
                        "uid": identity["uid"],
                        "resource_version": identity["resourceVersion"],
                        "delete_intent_at": _utc_now(),
                    }
                )
                checkpoint_writer()
            elif pod_state.get("resource_version") != identity["resourceVersion"]:
                raise SoperatorMigrationPhasePending(
                    f"source controller Pod {name} resourceVersion drifted after delete intent."
                )
            _command_runner_uid_preconditioned_delete(
                command_runner,
                kube_context=kube_context,
                api_path=str(pod.get("api_path") or ""),
                uid=identity["uid"],
                resource_version=identity["resourceVersion"],
                propagation_policy="Orphan",
                timeout_seconds=300,
                mutation_guard=mutation_guard,
            )
        elif not pod_state.get("delete_intent_at"):
            raise SoperatorMigrationPhasePending(
                f"source controller Pod {name} disappeared before delete intent."
            )
        pod_state["deleted_at"] = _utc_now()
        checkpoint_writer()
    item["controller_pods_deleted_at"] = _utc_now()
    checkpoint_writer()


def _controller_placeholder_selector(
    *,
    slurmcluster_binding: Mapping[str, Any],
) -> dict[str, str]:
    selector = _immutable_child_target_selector(
        target_binding=slurmcluster_binding,
        component="controller",
    )
    selector["slurm.nebius.ai/controller-type"] = "placeholder"
    return selector


def _require_exact_inert_controller_placeholder_daemonset(
    *,
    daemonset: Mapping[str, Any],
    expected_selector: Mapping[str, str],
    expected_owner: Mapping[str, Any] | None,
    expected_uid: str | None,
    label: str,
) -> dict[str, str]:
    if (
        str(daemonset.get("apiVersion") or "").strip() != "apps/v1"
        or str(daemonset.get("kind") or "").strip() != "DaemonSet"
    ):
        raise SoperatorMigrationPhasePending(f"{label} has an unsupported API identity.")
    identity = _immutable_child_exact_identity(daemonset, label=label)
    if expected_uid and identity["uid"] != expected_uid:
        raise SoperatorMigrationPhasePending(f"{label} UID differs from its checkpoint binding.")
    metadata = _mapping(daemonset.get("metadata"))
    if metadata.get("deletionTimestamp"):
        raise SoperatorMigrationPhasePending(f"{label} is already terminating.")
    selector = {
        str(key): str(value)
        for key, value in _mapping(
            _mapping(_mapping(daemonset.get("spec")).get("selector")).get("matchLabels")
        ).items()
    }
    if selector != dict(expected_selector):
        raise SoperatorMigrationPhasePending(f"{label} selector is not the exact expected binding.")
    template_labels = _mapping(
        _mapping(_mapping(_mapping(daemonset.get("spec")).get("template")).get("metadata")).get(
            "labels"
        )
    )
    if any(str(template_labels.get(key) or "") != value for key, value in selector.items()):
        raise SoperatorMigrationPhasePending(
            f"{label} Pod template does not carry its exact immutable selector."
        )
    if not _workload_is_exact_inert_known_controller_helper(
        resource="daemonsets.apps",
        workload=daemonset,
    ):
        raise SoperatorMigrationPhasePending(
            f"{label} is not the allowlisted inert controller placeholder."
        )
    owner = _immutable_child_controller_owner(daemonset, label=label)
    if expected_owner is None:
        if owner is not None or _validated_resource_owner_references(daemonset, label=label):
            raise SoperatorMigrationPhasePending(
                f"{label} must remain ownerless after exact source retirement."
            )
    elif not _controller_owner_reference_matches_binding(_mapping(owner), expected_owner):
        raise SoperatorMigrationPhasePending(
            f"{label} is not owned by the checkpointed target SlurmCluster."
        )
    return identity


def _require_exact_ready_inert_controller_placeholder_pods(
    *,
    daemonset: Mapping[str, Any],
    daemonset_identity: Mapping[str, str],
    expected_selector: Mapping[str, str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    status = _mapping(daemonset.get("status"))
    desired = _positive_int(status.get("desiredNumberScheduled"), fallback=0)
    current = _positive_int(status.get("currentNumberScheduled"), fallback=0)
    ready = _positive_int(status.get("numberReady"), fallback=0)
    if desired <= 0 or (current, ready) != (desired, desired):
        raise SoperatorMigrationPhasePending(
            "source controller-placeholder DaemonSet is not fully Ready before inert replacement."
        )
    matching_pods: list[Mapping[str, Any]] = []
    for pod in _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pods",
    ):
        labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
        if any(str(labels.get(key) or "") != value for key, value in expected_selector.items()):
            continue
        owner = _immutable_child_controller_owner(
            pod,
            label="source controller-placeholder Pod",
        )
        if (
            str(_mapping(owner).get("apiVersion") or "") != "apps/v1"
            or str(_mapping(owner).get("kind") or "") != "DaemonSet"
            or str(_mapping(owner).get("name") or "") != "controller-placeholder"
            or str(_mapping(owner).get("uid") or "") != daemonset_identity["uid"]
            or not _pod_is_exact_inert_known_controller_helper(pod)
            or not _immutable_child_pod_ready(pod)
        ):
            raise SoperatorMigrationPhasePending(
                "source controller-placeholder selector includes a Pod outside the exact "
                "Ready inert DaemonSet binding."
            )
        matching_pods.append(pod)
    if len(matching_pods) != desired:
        raise SoperatorMigrationPhasePending(
            "source controller-placeholder Ready Pod count differs from its exact DaemonSet status."
        )


def _transition_inert_controller_placeholder_selector(
    *,
    phase: dict[str, Any],
    handoff: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    timeout_seconds: int = 300,
) -> None:
    """Replace only the exact inert source placeholder that blocks target reconciliation."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "controller-placeholder selector handoff requires durable checkpoint writes."
        )
    source_binding = _mapping(handoff.get("source"))
    target_binding = _mapping(handoff.get("target"))
    accounting = _accounting_handoff_state(phase)
    if not _accounting_handoff_source_retirement_checkpoint_is_exact(
        phase=phase,
        state=accounting,
        source_binding=source_binding,
    ):
        raise SoperatorMigrationPhasePending(
            "controller-placeholder selector handoff requires exact source retirement proof."
        )
    checkpointed = _source_cleanup_checkpointed_child_bindings(
        state=accounting,
        source_binding=source_binding,
        target_binding=target_binding,
        required=True,
    )
    api_path = f"/apis/apps/v1/namespaces/{_SOPERATOR_NAMESPACE}/daemonsets/controller-placeholder"
    source_child = _mapping(_mapping(checkpointed).get(api_path))
    source_owner = _mapping(source_child.get("controller_owner"))
    if (
        source_child.get("api_version") != "apps/v1"
        or source_child.get("kind") != "DaemonSet"
        or source_child.get("namespace") != _SOPERATOR_NAMESPACE
        or source_child.get("name") != "controller-placeholder"
        or not str(source_child.get("uid") or "").strip()
        or str(source_owner.get("kind") or "") != "SlurmCluster"
        or str(source_owner.get("name") or "") != str(source_binding.get("name") or "")
        or str(source_owner.get("uid") or "") != str(source_binding.get("uid") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "controller-placeholder lacks its exact checkpointed source child binding."
        )
    state = handoff.setdefault("controller_placeholder_selector_handoff", {})
    if not isinstance(state, dict):
        raise SoperatorMigrationPhasePending(
            "controller-placeholder selector handoff checkpoint is malformed."
        )
    if state and state.get("schema") != (
        _IMMUTABLE_CHILD_CONTROLLER_PLACEHOLDER_SELECTOR_HANDOFF_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "controller-placeholder selector handoff checkpoint uses an unsupported schema."
        )
    source_selector = _controller_placeholder_selector(slurmcluster_binding=source_binding)
    target_selector = _controller_placeholder_selector(slurmcluster_binding=target_binding)
    source_uid = str(source_child.get("uid") or "").strip()
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        live = _immutable_child_optional_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="daemonset",
            name="controller-placeholder",
            label="controller-placeholder selector handoff",
        )
        live_uid = str(_mapping(_mapping(live).get("metadata")).get("uid") or "").strip()
        if live is not None and live_uid == source_uid:
            identity = _require_exact_inert_controller_placeholder_daemonset(
                daemonset=live,
                expected_selector=source_selector,
                expected_owner=None,
                expected_uid=source_uid,
                label="source controller-placeholder DaemonSet",
            )
            _require_exact_ready_inert_controller_placeholder_pods(
                daemonset=live,
                daemonset_identity=identity,
                expected_selector=source_selector,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            spec_fingerprint = _fingerprint(to_plain_data(_mapping(live.get("spec"))))
            if not state:
                state.update(
                    {
                        "schema": (_IMMUTABLE_CHILD_CONTROLLER_PLACEHOLDER_SELECTOR_HANDOFF_SCHEMA),
                        "status": "source-delete-intent",
                        "source_uid": source_uid,
                        "source_resource_version": identity["resourceVersion"],
                        "source_spec_fingerprint": spec_fingerprint,
                        "source_selector": source_selector,
                        "target_selector": target_selector,
                        "delete_intent_at": _utc_now(),
                    }
                )
                checkpoint_writer()
            elif (
                str(state.get("source_uid") or "") != source_uid
                or str(state.get("source_spec_fingerprint") or "") != spec_fingerprint
                or _mapping(state.get("source_selector")) != source_selector
                or _mapping(state.get("target_selector")) != target_selector
                or state.get("status") not in {"source-delete-intent", "source-deleted"}
            ):
                raise SoperatorMigrationPhasePending(
                    "controller-placeholder source delete intent drifted from its exact binding."
                )
            if state.get("status") == "source-deleted":
                raise SoperatorMigrationPhasePending(
                    "controller-placeholder source UID reappeared after durable deletion proof."
                )
            if state.get("source_resource_version") != identity["resourceVersion"]:
                state["source_resource_version"] = identity["resourceVersion"]
                state["source_resource_version_refreshed_at"] = _utc_now()
                checkpoint_writer()
            _command_runner_uid_preconditioned_delete(
                command_runner,
                kube_context=kube_context,
                api_path=api_path,
                uid=source_uid,
                resource_version=identity["resourceVersion"],
                propagation_policy="Foreground",
                timeout_seconds=300,
                mutation_guard=mutation_guard,
            )
            state["status"] = "source-deleted"
            state["source_deleted_at"] = _utc_now()
            checkpoint_writer()
        elif live is None:
            if not state.get("delete_intent_at"):
                raise SoperatorMigrationPhasePending(
                    "controller-placeholder disappeared before its durable delete intent."
                )
            if state.get("status") == "source-delete-intent":
                state["status"] = "source-deleted"
                state["source_deleted_at"] = _utc_now()
                checkpoint_writer()
        else:
            if not state.get("source_deleted_at") or live_uid == source_uid:
                raise SoperatorMigrationPhasePending(
                    "controller-placeholder changed UID outside its checkpointed selector handoff."
                )
            identity = _require_exact_inert_controller_placeholder_daemonset(
                daemonset=live,
                expected_selector=target_selector,
                expected_owner=target_binding,
                expected_uid=(str(state.get("target_uid") or "").strip() or None),
                label="target controller-placeholder DaemonSet",
            )
            state.update(
                {
                    "status": "target-created",
                    "target_uid": identity["uid"],
                    "target_resource_version": identity["resourceVersion"],
                    "target_created_at": state.get("target_created_at") or _utc_now(),
                }
            )
            checkpoint_writer()
            return
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target controller-placeholder DaemonSet did not appear after exact inert "
                "source selector replacement."
            )
        time.sleep(2)


def _wait_for_target_immutable_child_replacements(
    *,
    handoff: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    timeout_seconds: int = 900,
) -> None:
    deadline = time.monotonic() + max(timeout_seconds, 0)
    pending: list[str] = []
    while True:
        pending = []
        for item in _mapping(handoff.get("workloads")).values():
            if not isinstance(item, dict):
                raise SoperatorMigrationPhasePending(
                    "immutable child workload checkpoint item is malformed."
                )
            _revalidate_immutable_child_pvcs(
                item=item,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            name = str(item.get("name") or "")
            live = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type=str(item.get("resource_type") or ""),
                name=name,
            )
            metadata = _mapping(live.get("metadata"))
            new_uid = str(metadata.get("uid") or "").strip()
            if not new_uid or new_uid == str(item.get("uid") or ""):
                pending.append(f"{item.get('kind')}/{name}")
                continue
            identity = _immutable_child_exact_identity(
                live,
                label=f"target {item.get('kind')} {_SOPERATOR_NAMESPACE}/{name}",
            )
            selector = {
                str(key): str(value)
                for key, value in _mapping(_mapping(live.get("spec")).get("selector"))
                .get("matchLabels", _mapping(_mapping(live.get("spec")).get("selector")))
                .items()
            }
            expected_selector = _mapping(item.get("target_selector"))
            if any(selector.get(key) != value for key, value in expected_selector.items()):
                raise SoperatorMigrationPhasePending(
                    f"target {item.get('kind')} {name} selector differs from its exact target binding."
                )
            owner = _immutable_child_controller_owner(
                live,
                label=f"target {item.get('kind')} {_SOPERATOR_NAMESPACE}/{name}",
            )
            if item.get("component") == "nodeset":
                if (
                    str(_mapping(owner).get("kind") or "").strip() != "NodeSet"
                    or str(_mapping(owner).get("name") or "").strip() != name
                    or not str(_mapping(owner).get("uid") or "").strip()
                ):
                    raise SoperatorMigrationPhasePending(
                        f"target worker workload {name} lacks its exact NodeSet controller owner."
                    )
            elif not _controller_owner_reference_matches_binding(
                _mapping(owner),
                _mapping(handoff.get("target")),
            ):
                raise SoperatorMigrationPhasePending(
                    f"target {item.get('kind')} {name} is not owned by the checkpointed target SlurmCluster."
                )
            prior_target_uid = str(item.get("target_uid") or "").strip()
            if prior_target_uid and prior_target_uid != new_uid:
                raise SoperatorMigrationPhasePending(
                    f"target {item.get('kind')} {name} UID changed after replacement binding."
                )
            item.update(
                {
                    "status": "target-bound",
                    "target_uid": new_uid,
                    "target_resource_version": identity["resourceVersion"],
                    "target_bound_at": item.get("target_bound_at") or _utc_now(),
                }
            )
        if not pending:
            handoff["status"] = "target-children-created"
            handoff["target_children_created_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
            return
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target immutable child replacements did not appear after manager restore: "
                + ", ".join(pending)
            )
        time.sleep(2)


def _verified_gpu_health_sysfs_worker_replacement(
    phase: Mapping[str, Any],
    *,
    pod_name: str,
    prior_uid: str,
    live_uid: str,
    nodeset_name: str,
    target_statefulset_uid: str,
) -> Mapping[str, Any] | None:
    """Return the exact verified sysfs-repair transition for a worker Pod."""

    repair = _mapping(phase.get("gpu_health_sysfs_repair"))
    if not repair:
        return None
    if (
        repair.get("schema") != _GPU_HEALTH_SYSFS_REPAIR_SCHEMA
        or repair.get("status") != "verified"
    ):
        return None
    old_pod = _mapping(_mapping(repair.get("old_pods")).get(pod_name))
    replacement = _mapping(_mapping(repair.get("replacement_pods")).get(pod_name))
    if (
        str(old_pod.get("uid") or "").strip() != prior_uid
        or str(replacement.get("uid") or "").strip() != live_uid
        or str(old_pod.get("nodeset") or "").strip() != nodeset_name
        or str(replacement.get("nodeset") or "").strip() != nodeset_name
        or str(old_pod.get("statefulset_uid") or "").strip() != target_statefulset_uid
        or str(replacement.get("statefulset_uid") or "").strip() != target_statefulset_uid
        or not str(repair.get("verified_at") or "").strip()
    ):
        return None
    return replacement


def _verified_completed_in_place_worker_rollout_successor(
    phase: Mapping[str, Any],
    *,
    pod: Mapping[str, Any],
    pod_name: str,
    live_uid: str,
    nodeset_name: str,
    target_statefulset_uid: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> Mapping[str, Any] | None:
    """Return the exact worker successor proven by a completed in-place rollout."""

    if (
        phase.get("status") != "completed"
        or not str(phase.get("completed_at") or "").strip()
        or str(_mapping(phase.get("immutable_child_handoff")).get("status") or "") != "complete"
    ):
        return None
    health = _mapping(phase.get("in_place_worker_replacement_health"))
    if health.get("status") != "passed" or not str(health.get("verified_at") or "").strip():
        return None
    rootfs_checks = _sequence_of_mappings(phase.get("in_place_rootfs_consumer_checks"))
    mount_checks = _sequence_of_mappings(phase.get("in_place_persistent_mount_checks"))
    if (
        not any(
            item.get("kind") == "worker-nodeset"
            and str(item.get("name") or "") == nodeset_name
            and item.get("status") == "verified"
            and item.get("rootfs_observed") is True
            and not _string_sequence(item.get("missing_mounts"))
            for item in rootfs_checks
        )
        or not mount_checks
        or any(item.get("status") != "passed" for item in mount_checks)
    ):
        return None
    metadata = _mapping(pod.get("metadata"))
    spec = _mapping(pod.get("spec"))
    if (
        str(metadata.get("name") or "") != pod_name
        or str(metadata.get("uid") or "") != live_uid
        or metadata.get("deletionTimestamp")
        or not _pod_is_ready(pod)
        or str(_mapping(pod.get("status")).get("phase") or "") != "Running"
        or any(
            _nonnegative_int(item.get("restartCount"), fallback=0) != 0
            for item in _sequence_of_mappings(_mapping(pod.get("status")).get("containerStatuses"))
        )
    ):
        return None
    owner = _immutable_child_controller_owner(
        pod,
        label=f"completed in-place worker successor {_SOPERATOR_NAMESPACE}/{pod_name}",
    )
    if (
        str(_mapping(owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
        or str(_mapping(owner).get("kind") or "") != "StatefulSet"
        or str(_mapping(owner).get("name") or "") != nodeset_name
        or str(_mapping(owner).get("uid") or "") != target_statefulset_uid
    ):
        return None
    node_name = str(spec.get("nodeName") or "").strip()
    if not node_name or node_name not in set(_string_sequence(phase.get("worker_nodes"))):
        return None
    gate = _mapping(phase.get("in_place_gpu_workload_release_gate"))
    worker_matches = tuple(
        item
        for item in _sequence_of_mappings(gate.get("workers"))
        if str(item.get("pod") or "") == pod_name
        and str(item.get("pod_uid") or "") == live_uid
        and str(item.get("node") or "") == node_name
        and str(item.get("nodeset") or "") == nodeset_name
        and str(item.get("workload_uid") or "") == target_statefulset_uid
        and item.get("status") == "passed"
    )
    if gate.get("status") != "passed" or len(worker_matches) != 1:
        return None
    node = _json_from_command(
        command_runner,
        ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
        timeout_seconds=120,
        check=False,
    )
    node_metadata = _mapping(node.get("metadata"))
    node_uid = str(node_metadata.get("uid") or "").strip()
    node_group_id = str(
        _mapping(node_metadata.get("labels")).get("nebius.com/node-group-id") or ""
    ).strip()
    group = _mapping(_mapping(phase.get("in_place_node_groups")).get(node_group_id))
    role = str(group.get("role") or "").strip()
    if (
        not node_uid
        or not node_group_id
        or not role.startswith(nodeset_name)
        or group.get("status") != "completed"
        or not str(group.get("completed_at") or "").strip()
        or node_uid not in set(_string_sequence(group.get("replacement_node_uids")))
        or not str(_mapping(group.get("target")).get("kubernetes_version") or "").strip()
    ):
        return None
    return {
        "pod_uid": live_uid,
        "node_name": node_name,
        "node_uid": node_uid,
        "node_group_id": node_group_id,
        "node_group_completed_at": str(group.get("completed_at") or ""),
        "health_verified_at": str(health.get("verified_at") or ""),
    }


def _verified_target_topology_values_replay_after_gpu_health_sysfs(
    phase: Mapping[str, Any],
    *,
    target_ref: str,
    release_revision: int,
    stored_values: Mapping[str, Any],
    installed_manifest: str,
    chart_content_fingerprint: str,
) -> bool:
    revision = _non_negative_int(phase.get("target_handoff_values_revision"), fallback=0)
    if revision != _ROLLING_COMPUTE_VALUES_REVISION:
        return False
    proof = _mapping(phase.get(f"target_values_reapply_proof_v{revision}"))
    promoted_proof = _mapping(phase.get("target_handoff_values_proof"))
    target_binding = _mapping(_mapping(phase.get("slurmcluster_handoff_binding")).get("target"))
    if (
        proof.get("schema") != _TARGET_HELM_APPLY_PROOF_SCHEMA
        or proof.get("status") != "verified"
        or proof != promoted_proof
        or _mapping(proof.get("target")) != target_binding
        or str(_mapping(proof.get("target")).get("name") or "") != target_ref
        or _positive_int(proof.get("release_revision"), fallback=0) != release_revision
        or str(proof.get("values_fingerprint") or "") != _fingerprint(stored_values)
        or str(proof.get("current_chart_content_fingerprint") or "") != chart_content_fingerprint
        or str(proof.get("installed_manifest_fingerprint") or "")
        != _target_slurmcluster_manifest_fingerprint(
            installed_manifest,
            target_ref=target_ref,
            label="GPU repair topology replay installed manifest",
        )
        or _mapping(proof.get("semantic_drift")).get("status") != "compatible"
    ):
        return False
    gpu_nodesets = set(_gpu_worker_nodeset_names(stored_values))
    matched: set[str] = set()
    for nodeset in _sequence_of_mappings(stored_values.get("nodesets")):
        name = str(nodeset.get("name") or "").strip()
        if name not in gpu_nodesets:
            continue
        static = str(_mapping(nodeset.get("nodeConfig")).get("static") or "")
        if f"Parameters={_TARGET_GPU_GRES_AFFINITY_PARAMETER}" not in static.split():
            return False
        matched.add(name)
    return bool(gpu_nodesets and matched == gpu_nodesets)


def _rollover_orphaned_worker_pods_for_target_statefulsets(
    *,
    phase: dict[str, Any],
    values: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> list[str]:
    """Release exact orphaned worker Pod names so target StatefulSets can recreate them."""

    raw_handoff = _mapping(phase.get("immutable_child_handoff"))
    if not raw_handoff or str(raw_handoff.get("status") or "") not in {
        "target-children-created",
        "cleanup-intent",
        "complete",
    }:
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "worker Pod handoff requires durable checkpoint writes."
        )
    handoff = _immutable_child_handoff_state(phase)
    workloads = _mapping(handoff.get("workloads"))
    lines: list[str] = []
    for nodeset_name in _target_worker_nodeset_names(values):
        matches = [
            item
            for item in workloads.values()
            if isinstance(item, dict)
            and item.get("component") == "nodeset"
            and item.get("kind") == "StatefulSet"
            and str(item.get("name") or "") == nodeset_name
        ]
        if len(matches) != 1:
            raise SoperatorMigrationPhasePending(
                f"worker Pod handoff lacks one exact immutable-child binding for {nodeset_name}."
            )
        item = matches[0]
        target_uid = str(item.get("target_uid") or "").strip()
        if item.get("status") != "target-bound" or not target_uid:
            raise SoperatorMigrationPhasePending(
                f"worker Pod handoff lacks the target StatefulSet UID for {nodeset_name}."
            )
        target = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="statefulset.apps.kruise.io",
            name=nodeset_name,
        )
        target_identity = _immutable_child_require_live_uid(
            target,
            expected_uid=target_uid,
            label=f"target worker StatefulSet {_SOPERATOR_NAMESPACE}/{nodeset_name}",
        )
        target_owner = _immutable_child_controller_owner(
            target,
            label=f"target worker StatefulSet {_SOPERATOR_NAMESPACE}/{nodeset_name}",
        )
        nodeset_uid = str(_mapping(target_owner).get("uid") or "").strip()
        if (
            str(_mapping(target_owner).get("apiVersion") or "")
            not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
            or str(_mapping(target_owner).get("kind") or "") != "NodeSet"
            or str(_mapping(target_owner).get("name") or "") != nodeset_name
            or not nodeset_uid
        ):
            raise SoperatorMigrationPhasePending(
                f"target worker StatefulSet {nodeset_name} lacks its exact NodeSet owner."
            )
        nodeset = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="nodeset",
            name=nodeset_name,
        )
        _immutable_child_require_live_uid(
            nodeset,
            expected_uid=nodeset_uid,
            label=f"target worker NodeSet {_SOPERATOR_NAMESPACE}/{nodeset_name}",
        )
        expected_selector = {
            str(key): str(value) for key, value in _mapping(item.get("target_selector")).items()
        }
        live_selector = {
            str(key): str(value)
            for key, value in _mapping(
                _mapping(_mapping(target.get("spec")).get("selector")).get("matchLabels")
            ).items()
        }
        if not expected_selector or any(
            live_selector.get(key) != value for key, value in expected_selector.items()
        ):
            raise SoperatorMigrationPhasePending(
                f"target worker StatefulSet {nodeset_name} selector drifted before Pod handoff."
            )
        rollover = item.setdefault("old_pod_rollover", {})
        if not isinstance(rollover, dict):
            raise SoperatorMigrationPhasePending(
                f"worker Pod handoff checkpoint is malformed for {nodeset_name}."
            )
        for captured in _sequence_of_mappings(item.get("pods")):
            pod_name = str(captured.get("name") or "").strip()
            captured_uid = str(captured.get("uid") or "").strip()
            api_path = str(captured.get("api_path") or "").strip()
            if (
                not pod_name
                or not captured_uid
                or api_path != f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/pods/{pod_name}"
            ):
                raise SoperatorMigrationPhasePending(
                    f"worker Pod handoff binding is incomplete for {nodeset_name}."
                )
            pod_state = rollover.setdefault(pod_name, {})
            if not isinstance(pod_state, dict):
                raise SoperatorMigrationPhasePending(
                    f"worker Pod handoff item is malformed for {pod_name}."
                )
            live_pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=pod_name,
                label=f"worker Pod handoff {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if live_pod is None:
                if not pod_state.get("delete_intent_at"):
                    raise SoperatorMigrationPhasePending(
                        f"orphaned worker Pod {pod_name} disappeared before delete intent."
                    )
                if not pod_state.get("deleted_at"):
                    pod_state["deleted_at"] = _utc_now()
                    checkpoint_writer()
                continue
            live_identity = _immutable_child_exact_identity(
                live_pod,
                label=f"worker Pod handoff {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            live_labels = _mapping(_mapping(live_pod.get("metadata")).get("labels"))
            if any(
                str(live_labels.get(key) or "") != value for key, value in expected_selector.items()
            ):
                raise SoperatorMigrationPhasePending(
                    f"worker Pod {pod_name} selector labels drifted during handoff."
                )
            if live_identity["uid"] == captured_uid:
                if _validated_resource_owner_references(
                    live_pod,
                    label=f"orphaned worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
                ):
                    raise SoperatorMigrationPhasePending(
                        f"orphaned worker Pod {pod_name} acquired an unauthorized owner."
                    )
                if not pod_state.get("delete_intent_at"):
                    pod_state.update(
                        {
                            "uid": captured_uid,
                            "resource_version": live_identity["resourceVersion"],
                            "delete_intent_at": _utc_now(),
                        }
                    )
                    checkpoint_writer()
                elif (
                    str(pod_state.get("uid") or "") != captured_uid
                    or str(pod_state.get("resource_version") or "")
                    != live_identity["resourceVersion"]
                ):
                    raise SoperatorMigrationPhasePending(
                        f"orphaned worker Pod {pod_name} changed after delete intent."
                    )
                _command_runner_uid_preconditioned_delete(
                    command_runner,
                    kube_context=kube_context,
                    api_path=api_path,
                    uid=captured_uid,
                    resource_version=live_identity["resourceVersion"],
                    propagation_policy="Orphan",
                    timeout_seconds=300,
                    mutation_guard=mutation_guard,
                )
                pod_state["deleted_at"] = _utc_now()
                checkpoint_writer()
                continue
            if not pod_state.get("delete_intent_at") or not pod_state.get("deleted_at"):
                raise SoperatorMigrationPhasePending(
                    f"worker Pod {pod_name} changed UID before exact delete proof."
                )
            live_owner = _immutable_child_controller_owner(
                live_pod,
                label=f"replacement worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if (
                str(_mapping(live_owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
                or str(_mapping(live_owner).get("kind") or "") != "StatefulSet"
                or str(_mapping(live_owner).get("name") or "") != nodeset_name
                or str(_mapping(live_owner).get("uid") or "") != target_identity["uid"]
            ):
                raise SoperatorMigrationPhasePending(
                    f"replacement worker Pod {pod_name} lacks its target StatefulSet owner."
                )
            replacement_uid = str(pod_state.get("replacement_uid") or "").strip()
            if replacement_uid and replacement_uid != live_identity["uid"]:
                verified_replacement = _verified_gpu_health_sysfs_worker_replacement(
                    phase,
                    pod_name=pod_name,
                    prior_uid=replacement_uid,
                    live_uid=live_identity["uid"],
                    nodeset_name=nodeset_name,
                    target_statefulset_uid=target_identity["uid"],
                )
                rollout_successor = None
                if verified_replacement is None:
                    rollout_successor = _verified_completed_in_place_worker_rollout_successor(
                        phase,
                        pod=live_pod,
                        pod_name=pod_name,
                        live_uid=live_identity["uid"],
                        nodeset_name=nodeset_name,
                        target_statefulset_uid=target_identity["uid"],
                        command_runner=command_runner,
                        kube_context=kube_context,
                    )
                if verified_replacement is None and rollout_successor is None:
                    raise SoperatorMigrationPhasePending(
                        f"replacement worker Pod {pod_name} changed UID after binding."
                    )
                history = pod_state.setdefault("replacement_uid_history", [])
                if not isinstance(history, list):
                    raise SoperatorMigrationPhasePending(
                        f"replacement worker Pod {pod_name} UID history is malformed."
                    )
                transition = (
                    {
                        "uid": replacement_uid,
                        "replaced_by_uid": live_identity["uid"],
                        "boundary": "gpu-health-sysfs-repair",
                        "repair_verified_at": str(
                            _mapping(phase.get("gpu_health_sysfs_repair")).get("verified_at") or ""
                        ),
                    }
                    if verified_replacement is not None
                    else {
                        "uid": replacement_uid,
                        "replaced_by_uid": live_identity["uid"],
                        "boundary": "completed-in-place-worker-rollout",
                        "rollout": dict(_mapping(rollout_successor)),
                    }
                )
                if transition not in history:
                    history.append(transition)
                pod_state["replacement_rebound_at"] = _utc_now()
            pod_state.update(
                {
                    "replacement_uid": live_identity["uid"],
                    "replacement_bound_at": pod_state.get("replacement_bound_at") or _utc_now(),
                }
            )
            checkpoint_writer()
        replacement_count = sum(
            bool(_mapping(rollover.get(str(pod.get("name") or ""))).get("replacement_uid"))
            for pod in _sequence_of_mappings(item.get("pods"))
        )
        rollover["status"] = (
            "target-replacements-bound"
            if replacement_count == len(_sequence_of_mappings(item.get("pods")))
            else "old-pods-released"
        )
        rollover["updated_at"] = _utc_now()
        checkpoint_writer()
        lines.append(
            f"Worker Pod handoff released exact orphaned Pods for target StatefulSet {nodeset_name}."
        )
    return lines


def _gpu_driver_jail_init_script_from_pod_spec(
    pod_spec: Mapping[str, Any],
) -> str:
    matching = tuple(
        container
        for container in _sequence_of_mappings(pod_spec.get("initContainers"))
        if str(container.get("name") or "").strip() == SOPERATOR_GPU_DRIVER_JAIL_INIT_CONTAINER_NAME
    )
    if len(matching) != 1:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair requires exactly one chart-owned init container."
        )
    args = _string_sequence(matching[0].get("args"))
    if len(args) != 1:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair requires one canonical init script argument."
        )
    return args[0]


def _gpu_driver_jail_init_script_is_old_chroot_contract(script: str) -> bool:
    return all(line in script for line in _GPU_DRIVER_JAIL_OLD_CHROOT_PROBE_LINES) and not any(
        line in script for line in _GPU_DRIVER_JAIL_LOADER_PROBE_LINES
    )


def _gpu_driver_jail_init_script_is_loader_contract(script: str) -> bool:
    return all(line in script for line in _GPU_DRIVER_JAIL_LOADER_PROBE_LINES) and not any(
        line in script for line in _GPU_DRIVER_JAIL_OLD_CHROOT_PROBE_LINES
    )


def _gpu_health_sysfs_manifest_has_contract(
    manifest: str,
    *,
    gpu_nodesets: Sequence[str],
) -> bool:
    try:
        documents = tuple(
            item for item in yaml.safe_load_all(manifest) if isinstance(item, Mapping)
        )
    except yaml.YAMLError:
        return False
    for nodeset_name in gpu_nodesets:
        matches = tuple(
            item
            for item in documents
            if str(item.get("kind") or "").strip() == "NodeSet"
            and str(_mapping(item.get("metadata")).get("name") or "").strip() == nodeset_name
        )
        if len(matches) != 1:
            return False
        mounts = _sequence_of_mappings(
            _mapping(_mapping(_mapping(matches[0].get("spec")).get("slurmd")).get("volumes")).get(
                "customVolumeMounts"
            )
        )
        named = tuple(
            item
            for item in mounts
            if str(item.get("name") or "").strip() == _GPU_HEALTH_SYSFS_MOUNT_NAME
            or str(item.get("mountPath") or "").strip() == _GPU_HEALTH_SYSFS_MOUNT_PATH
        )
        if len(named) != 1:
            return False
        mount = named[0]
        host_path = _mapping(_mapping(mount.get("volumeSource")).get("hostPath"))
        if (
            str(mount.get("name") or "").strip() != _GPU_HEALTH_SYSFS_MOUNT_NAME
            or str(mount.get("mountPath") or "").strip() != _GPU_HEALTH_SYSFS_MOUNT_PATH
            or mount.get("readOnly") is not True
            or str(host_path.get("path") or "").strip() != _GPU_HEALTH_SYSFS_HOST_PATH
            or str(host_path.get("type") or "").strip() != "Directory"
        ):
            return False
    return True


def _gpu_driver_jail_init_failed(item: Mapping[str, Any]) -> bool:
    for status in _sequence_of_mappings(_mapping(item.get("status")).get("initContainerStatuses")):
        if str(status.get("name") or "").strip() != (SOPERATOR_GPU_DRIVER_JAIL_INIT_CONTAINER_NAME):
            continue
        current = _mapping(_mapping(status.get("state")).get("terminated"))
        previous = _mapping(_mapping(status.get("lastState")).get("terminated"))
        terminated = current or previous
        return _nonnegative_int(terminated.get("exitCode"), fallback=0) > 0
    return False


def _exact_deployed_target_soperator_release(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> Any:
    releases = tuple(
        release
        for release in list_helm_releases(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            filter_regex=f"^{re.escape(_SOPERATOR_TARGET_RELEASE_NAME)}$",
        )
        if release.name == _SOPERATOR_TARGET_RELEASE_NAME
    )
    if (
        len(releases) != 1
        or releases[0].namespace != _SOPERATOR_NAMESPACE
        or releases[0].status.lower() != "deployed"
        or _positive_int(releases[0].revision, fallback=0) <= 0
    ):
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair requires one exact deployed target Helm release."
        )
    return releases[0]


def _target_soperator_installed_manifest(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> str:
    result = command_runner(
        [
            "helm",
            "--kube-context",
            kube_context,
            "get",
            "manifest",
            _SOPERATOR_TARGET_RELEASE_NAME,
            "-n",
            _SOPERATOR_NAMESPACE,
        ],
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair could not read the installed Helm manifest."
        )
    _target_soperator_helm_documents(result.stdout, label="GPU init repair installed manifest")
    return result.stdout


def _target_soperator_helm_revision_history_entry(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    revision: int,
) -> dict[str, Any]:
    result = command_runner(
        [
            "helm",
            "--kube-context",
            kube_context,
            "history",
            _SOPERATOR_TARGET_RELEASE_NAME,
            "-n",
            _SOPERATOR_NAMESPACE,
            "--max",
            "20",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair could not read target Helm history."
        )
    try:
        history = json.loads(result.stdout or "[]")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair found invalid target Helm history."
        ) from exc
    matches = (
        [
            entry
            for entry in history
            if isinstance(entry, Mapping)
            and _positive_int(entry.get("revision"), fallback=0) == revision
        ]
        if isinstance(history, list)
        else []
    )
    if len(matches) != 1:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair did not find one exact target Helm history revision."
        )
    entry = matches[0]
    updated_at = _target_soperator_helm_history_time(entry.get("updated"))
    return {
        "revision": revision,
        "updated_at": updated_at.isoformat().replace("+00:00", "Z"),
        "updated": updated_at,
        "status": str(entry.get("status") or "").strip().lower(),
        "chart": str(entry.get("chart") or "").strip(),
        "app_version": str(entry.get("app_version") or "").strip(),
    }


def _revalidate_legacy_rootfs_sconfig_before_target_helm_replay(
    *,
    populate_phase: Mapping[str, Any],
    rolling_phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Revalidate the current SConfig epoch before a same-version Helm replay."""

    bridge = _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge"))
    bridge_status = str(bridge.get("status") or "").strip()
    if bridge_status == "target-compatibility-active":
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=rolling_phase,
            handoff=_immutable_child_handoff_state(rolling_phase),
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        return
    if bridge_status != "released":
        raise SoperatorMigrationPhasePending(
            "target Helm replay requires an active or released legacy-rootfs SConfig proof."
        )
    release = _mapping(bridge.get("target_writer_release"))
    rootfs_pvc = str(release.get("rootfs_pvc") or "").strip()
    if release.get("status") != "verified" or not rootfs_pvc:
        raise SoperatorMigrationPhasePending(
            "target Helm replay requires the exact verified released SConfig writer proof."
        )
    _release_legacy_rootfs_sconfig_writer_after_slot_verification(
        bridge_phase=rolling_phase,
        handoff_verification=_mapping(populate_phase.get("rootfs_handoff_verification")),
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=None,
        rootfs_pvc=rootfs_pvc,
        open_metrics_handoff=_mapping(populate_phase.get("slurm_open_metrics_handoff")),
        verification_timeout_seconds=0,
        poll_interval_seconds=0,
    )


def _gpu_topology_values_only_delta(
    *,
    stored_values: Mapping[str, Any],
    desired_values: Mapping[str, Any],
    topology_by_nodeset: Mapping[str, Any],
) -> bool:
    """Accept only the exact discovered GPU NodeSet static-topology delta."""

    gpu_nodesets = _gpu_worker_nodeset_names(desired_values)
    if not gpu_nodesets:
        return False
    stored = dict(copy.deepcopy(to_plain_data(stored_values)))
    desired = dict(copy.deepcopy(to_plain_data(desired_values)))
    stored_nodesets = _target_worker_nodesets_by_name(stored)
    desired_nodesets = _target_worker_nodesets_by_name(desired)
    if set(stored_nodesets) != set(desired_nodesets):
        return False
    placeholder = "<cxcli-verified-gpu-topology>"
    for nodeset_name in gpu_nodesets:
        topology = _mapping(topology_by_nodeset.get(nodeset_name))
        desired_nodeset = desired_nodesets.get(nodeset_name)
        stored_nodeset = stored_nodesets.get(nodeset_name)
        if (
            not topology
            or not isinstance(desired_nodeset, dict)
            or not isinstance(stored_nodeset, dict)
        ):
            return False
        required_tokens = set(_worker_topology_static_tokens(topology))
        desired_node_config = desired_nodeset.get("nodeConfig")
        stored_node_config = stored_nodeset.get("nodeConfig")
        if not isinstance(desired_node_config, dict) or not isinstance(stored_node_config, dict):
            return False
        desired_static = str(desired_node_config.get("static") or "").strip()
        if not required_tokens or not required_tokens <= set(desired_static.split()):
            return False
        desired_node_config["static"] = placeholder
        stored_node_config["static"] = placeholder
    return stored == desired


def _gpu_topology_gres_only_successor(
    *,
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
    nodeset_names: Sequence[str],
) -> bool:
    """Accept only addition of an exact typed GPU GRES to proven topology."""

    names = tuple(dict.fromkeys(str(name or "").strip() for name in nodeset_names))
    if not names or set(previous) != set(current) or set(previous) != set(names):
        return False
    for name in names:
        old = dict(copy.deepcopy(to_plain_data(_mapping(previous.get(name)))))
        new = dict(copy.deepcopy(to_plain_data(_mapping(current.get(name)))))
        old_gres = str(old.pop("gres", "") or "").strip().lower()
        new_gres = str(new.pop("gres", "") or "").strip().lower()
        if old != new or old_gres not in {"", new_gres}:
            return False
        if not re.fullmatch(r"gpu:[a-z0-9_]+:[1-9][0-9]*", new_gres):
            return False
    return True


def _repair_gpu_worker_topology_before_jail_smoke(
    *,
    checkpoint: dict[str, Any],
    populate_phase: dict[str, Any],
    rolling_phase: dict[str, Any],
    target_ref: str,
    values: Mapping[str, Any],
    expected_version: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    login_session_policy: str,
    login_session_drain_timeout_seconds: int,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> list[str]:
    """Replay one exact topology-only Helm revision before a GPU Slurm smoke."""

    gpu_nodesets = _gpu_worker_nodeset_names(values)
    if not gpu_nodesets:
        return []
    topology_by_nodeset = _mapping(rolling_phase.get("worker_topology_by_nodeset"))
    if not topology_by_nodeset or any(
        not _worker_topology_static_tokens(_mapping(topology_by_nodeset.get(name)))
        for name in gpu_nodesets
    ):
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay requires durable checkpoint writes."
        )

    repair = rolling_phase.setdefault("gpu_topology_values_replay", {})
    if not isinstance(repair, dict):
        raise SoperatorMigrationPhasePending("GPU worker topology replay checkpoint is malformed.")
    if repair and repair.get("schema") != _GPU_TOPOLOGY_VALUES_REPLAY_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay checkpoint schema is unsupported."
        )
    release = _exact_deployed_target_soperator_release(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    current_revision = _positive_int(release.revision, fallback=0)
    stored_values = _target_soperator_helm_stored_values(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    desired_values = _effective_target_soperator_helm_values(values)
    if _fingerprint(desired_values) != _fingerprint(
        _effective_target_soperator_helm_values(
            values,
            disable_open_metrics_for_legacy_clients=False,
        )
    ):
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay found an unresolved legacy OpenMetrics values bridge."
        )
    chart_path = _target_soperator_chart_path()
    chart = _target_soperator_chart_metadata(chart_path)
    expected_chart = f"{chart['name']}-{chart['version']}"
    if release.chart != expected_chart or release.app_version != chart["app_version"]:
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay found target Helm chart or application version drift."
        )

    intent_key = f"target_values_reapply_intent_v{_ROLLING_COMPUTE_VALUES_REVISION}"
    proof_key = f"target_values_reapply_proof_v{_ROLLING_COMPUTE_VALUES_REVISION}"
    semantic_key = f"target_values_reapply_semantic_drift_v{_ROLLING_COMPUTE_VALUES_REVISION}"
    if repair.get("status") == "verified":
        installed_manifest = _target_soperator_installed_manifest(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if not _verified_target_topology_values_replay_after_gpu_health_sysfs(
            rolling_phase,
            target_ref=target_ref,
            release_revision=current_revision,
            stored_values=stored_values,
            installed_manifest=installed_manifest,
            chart_content_fingerprint=_target_soperator_chart_content_fingerprint(chart_path),
        ):
            raise SoperatorMigrationPhasePending(
                "GPU worker topology replay drifted from its exact verified Helm proof."
            )
        replay_topology = _mapping(repair.get("topology_by_nodeset"))
        current_topology = {
            name: copy.deepcopy(to_plain_data(_mapping(topology_by_nodeset.get(name))))
            for name in gpu_nodesets
        }
        if replay_topology != current_topology:
            if not _gpu_topology_gres_only_successor(
                previous=replay_topology,
                current=current_topology,
                nodeset_names=gpu_nodesets,
            ):
                raise SoperatorMigrationPhasePending(
                    "GPU worker topology replay changed outside the exact typed-GRES "
                    "preservation successor."
                )
            history = rolling_phase.setdefault("gpu_topology_values_replay_history", [])
            if not isinstance(history, list):
                raise SoperatorMigrationPhasePending(
                    "GPU worker topology replay history is malformed."
                )
            history.append(copy.deepcopy(to_plain_data(repair)))
            repair.update(
                {
                    "topology_by_nodeset": current_topology,
                    "stored_values_fingerprint_before": _fingerprint(stored_values),
                    "desired_values_fingerprint": _fingerprint(stored_values),
                    "release_revision_after": current_revision,
                    "typed_gres_successor": True,
                    "verified_at": _utc_now(),
                }
            )
            checkpoint_writer()
        return ["GPU worker topology replay reused its exact verified checkpoint."]

    gpu_post_activation = populate_phase.get("gpu_post_activation")
    if isinstance(gpu_post_activation, dict):
        smoke = gpu_post_activation.get("pinned_h100_smoke")
        if (
            isinstance(smoke, dict)
            and str(smoke.get("status") or "") == "Indeterminate"
            and not _reconcile_jail_gpu_unstartable_indeterminate_smoke(
                command_runner=command_runner,
                kube_context=kube_context,
                smoke=smoke,
                checkpoint_writer=checkpoint_writer,
                namespace=_SOPERATOR_NAMESPACE,
            )
        ):
            raise SoperatorMigrationPhasePending(
                "GPU topology replay cannot reconcile the exact Indeterminate H100 smoke."
            )
        partition_name = str(gpu_post_activation.get("partition_name") or "").strip()
        if partition_name:
            _delete_jail_gpu_temporary_partition(
                command_runner=command_runner,
                kube_context=kube_context,
                state=gpu_post_activation,
                checkpoint_writer=checkpoint_writer,
                namespace=_SOPERATOR_NAMESPACE,
            )

    installed_manifest = _target_soperator_installed_manifest(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if _verified_target_topology_values_replay_after_gpu_health_sysfs(
        rolling_phase,
        target_ref=target_ref,
        release_revision=current_revision,
        stored_values=stored_values,
        installed_manifest=installed_manifest,
        chart_content_fingerprint=_target_soperator_chart_content_fingerprint(chart_path),
    ):
        prior_post_activation = copy.deepcopy(to_plain_data(gpu_post_activation or {}))
        populate_phase["gpu_post_activation"] = {
            "status": "topology-replayed",
            "topology_replay_history": prior_post_activation,
        }
        repair.update(
            {
                "schema": _GPU_TOPOLOGY_VALUES_REPLAY_SCHEMA,
                "status": "verified",
                "target": _target_handoff_binding_for_helm_apply_proof(
                    rolling_phase,
                    target_ref=target_ref,
                ),
                "chart": release.chart,
                "app_version": release.app_version,
                "release_revision_before": current_revision,
                "release_revision_after": current_revision,
                "stored_values_fingerprint_before": _fingerprint(stored_values),
                "desired_values_fingerprint": _fingerprint(stored_values),
                "topology_by_nodeset": {
                    name: copy.deepcopy(to_plain_data(_mapping(topology_by_nodeset.get(name))))
                    for name in gpu_nodesets
                },
                "recovered_from_verified_helm_proof": True,
                "verified_at": _utc_now(),
            }
        )
        checkpoint_writer()
        return [
            "GPU worker topology replay recovered its exact verified Helm proof without "
            "a redundant apply."
        ]

    stored_matches_desired = _fingerprint(stored_values) == _fingerprint(desired_values)
    if not stored_matches_desired and not _gpu_topology_values_only_delta(
        stored_values=stored_values,
        desired_values=desired_values,
        topology_by_nodeset=topology_by_nodeset,
    ):
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay refuses target values drift outside the exact "
            "discovered GPU NodeSet static topology."
        )

    before_revision = _positive_int(repair.get("release_revision_before"), fallback=0)
    if not repair:
        repair.update(
            {
                "schema": _GPU_TOPOLOGY_VALUES_REPLAY_SCHEMA,
                "status": "prepared",
                "target": _target_handoff_binding_for_helm_apply_proof(
                    rolling_phase,
                    target_ref=target_ref,
                ),
                "chart": release.chart,
                "app_version": release.app_version,
                "release_revision_before": current_revision,
                "stored_values_fingerprint_before": _fingerprint(stored_values),
                "desired_values_fingerprint": _fingerprint(desired_values),
                "topology_by_nodeset": {
                    name: copy.deepcopy(to_plain_data(_mapping(topology_by_nodeset.get(name))))
                    for name in gpu_nodesets
                },
                "prepared_at": _utc_now(),
            }
        )
        checkpoint_writer()
        before_revision = current_revision
    if (
        before_revision <= 0
        or repair.get("chart") != release.chart
        or repair.get("app_version") != release.app_version
        or repair.get("desired_values_fingerprint") != _fingerprint(desired_values)
        or _mapping(repair.get("topology_by_nodeset"))
        != {name: _mapping(topology_by_nodeset.get(name)) for name in gpu_nodesets}
    ):
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay evidence drifted after it was checkpointed."
        )

    lines = _checkpoint_target_soperator_helm_apply_intent(
        phase=rolling_phase,
        command_runner=command_runner,
        target_ref=target_ref,
        values=values,
        expected_version=expected_version,
        checkpoint_writer=checkpoint_writer,
        intent_key=intent_key,
        apply_started_at_key=(
            f"target_values_reapply_started_at_v{_ROLLING_COMPUTE_VALUES_REVISION}"
        ),
    )
    recover_existing_apply = _target_soperator_helm_apply_intent_requires_live_recovery(
        rolling_phase,
        values=values,
        intent_key=intent_key,
    )
    if not stored_matches_desired and not recover_existing_apply:
        repair["status"] = "apply-intent"
        repair["apply_intent_at"] = repair.get("apply_intent_at") or _utc_now()
        checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _revalidate_legacy_rootfs_sconfig_before_target_helm_replay(
            populate_phase=populate_phase,
            rolling_phase=rolling_phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        lines.extend(
            _helm_upgrade_target_soperator_with_jail_login_session_policy(
                checkpoint=checkpoint,
                phase=populate_phase,
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                expected_version=expected_version,
                boundary="gpu-worker-topology-replay",
                login_session_policy=login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                wait=False,
                disable_open_metrics_for_legacy_clients=False,
                checkpoint_writer=checkpoint_writer,
            )
        )
    _checkpoint_live_target_slurmcluster_handoff_binding(
        checkpoint=checkpoint,
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        checkpoint_writer=checkpoint_writer,
    )
    lines.extend(
        _checkpoint_proven_target_soperator_helm_apply(
            phase=rolling_phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            values=values,
            expected_version=expected_version,
            require_command_fence_override=False,
            recovered_from_live_state=(stored_matches_desired or recover_existing_apply),
            checkpoint_writer=checkpoint_writer,
            intent_key=intent_key,
            proof_key=proof_key,
            semantic_drift_key=semantic_key,
            promote_for_child_handoff=True,
        )
    )
    _wait_for_target_worker_nodesets_ready(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
        timeout_seconds=1800,
    )
    deployed = _exact_deployed_target_soperator_release(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    deployed_revision = _positive_int(deployed.revision, fallback=0)
    expected_revision = before_revision if stored_matches_desired else before_revision + 1
    if deployed_revision != expected_revision:
        raise SoperatorMigrationPhasePending(
            "GPU worker topology replay did not produce the exact expected Helm revision."
        )
    prior_post_activation = copy.deepcopy(to_plain_data(gpu_post_activation or {}))
    populate_phase["gpu_post_activation"] = {
        "status": "topology-replayed",
        "topology_replay_history": prior_post_activation,
    }
    repair.update(
        {
            "status": "verified",
            "release_revision_after": deployed_revision,
            "verified_at": _utc_now(),
        }
    )
    checkpoint_writer()
    return [
        *lines,
        (
            "GPU worker topology replay adopted already-current exact Helm values."
            if stored_matches_desired
            else "GPU worker topology replay applied one exact topology-only Helm revision."
        ),
    ]


def _repair_gpu_driver_jail_init_loader_for_target_workers(
    *,
    checkpoint: dict[str, Any],
    populate_phase: dict[str, Any],
    rolling_phase: dict[str, Any],
    target_ref: str,
    values: Mapping[str, Any],
    expected_version: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    login_session_policy: str,
    login_session_drain_timeout_seconds: int,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    replacement_timeout_seconds: int = 900,
) -> list[str]:
    """Repair only the checkpoint-bound old chroot GPU init probe."""

    gpu_nodesets = _gpu_worker_nodeset_names(values)
    if not gpu_nodesets:
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair requires durable checkpoint writes."
        )
    handoff = _immutable_child_handoff_state(rolling_phase)
    if str(handoff.get("status") or "") != "target-children-created":
        return []
    workloads = _mapping(handoff.get("workloads"))
    repair_checkpoint = _mapping(rolling_phase.get("gpu_driver_jail_init_repair"))
    repair_checkpoint_status = str(repair_checkpoint.get("status") or "").strip()
    bindings: list[tuple[str, dict[str, Any], Mapping[str, Any], str]] = []
    for nodeset_name in gpu_nodesets:
        matches = [
            item
            for item in workloads.values()
            if isinstance(item, dict)
            and item.get("component") == "nodeset"
            and item.get("kind") == "StatefulSet"
            and str(item.get("name") or "") == nodeset_name
        ]
        if len(matches) != 1:
            raise SoperatorMigrationPhasePending(
                f"GPU driver jail init repair lacks one worker binding for {nodeset_name}."
            )
        item = matches[0]
        rollover = _mapping(item.get("old_pod_rollover"))
        rollover_status = str(rollover.get("status") or "").strip()
        if rollover_status not in {"old-pods-released", "target-replacements-bound"}:
            if repair_checkpoint:
                raise SoperatorMigrationPhasePending(
                    "GPU driver jail init repair checkpoint exists outside the exact "
                    f"old-Pod release boundary for {nodeset_name}."
                )
            return []
        if rollover_status == "target-replacements-bound" and (
            repair_checkpoint_status != "verified"
            or repair_checkpoint.get("schema") != _GPU_DRIVER_JAIL_INIT_REPAIR_SCHEMA
        ):
            raise SoperatorMigrationPhasePending(
                "GPU driver jail init repair crossed into replacement binding before its "
                f"exact proof was verified for {nodeset_name}."
            )
        target_uid = str(item.get("target_uid") or "").strip()
        if item.get("status") != "target-bound" or not target_uid:
            raise SoperatorMigrationPhasePending(
                f"GPU driver jail init repair lacks the target StatefulSet UID for {nodeset_name}."
            )
        for captured in _sequence_of_mappings(item.get("pods")):
            pod_name = str(captured.get("name") or "").strip()
            pod_state = _mapping(rollover.get(pod_name))
            replacement_uid = str(pod_state.get("replacement_uid") or "").strip()
            if (
                not pod_name
                or not str(captured.get("uid") or "").strip()
                or not str(pod_state.get("delete_intent_at") or "").strip()
                or not str(pod_state.get("deleted_at") or "").strip()
            ):
                raise SoperatorMigrationPhasePending(
                    f"GPU driver jail init repair found incomplete Pod release proof for {pod_name}."
                )
            if rollover_status == "old-pods-released" and replacement_uid:
                raise SoperatorMigrationPhasePending(
                    f"GPU driver jail init repair found premature replacement binding for {pod_name}."
                )
            if rollover_status == "target-replacements-bound":
                verified_pod = _mapping(
                    _mapping(repair_checkpoint.get("replacement_pods")).get(pod_name)
                )
                verified_uid = str(verified_pod.get("uid") or "").strip()
                replacement_is_verified = replacement_uid == verified_uid
                if not replacement_is_verified and replacement_uid and verified_uid:
                    replacement_is_verified = (
                        _verified_gpu_health_sysfs_worker_replacement(
                            rolling_phase,
                            pod_name=pod_name,
                            prior_uid=verified_uid,
                            live_uid=replacement_uid,
                            nodeset_name=nodeset_name,
                            target_statefulset_uid=target_uid,
                        )
                        is not None
                    )
                if (
                    not replacement_uid
                    or not replacement_is_verified
                    or str(verified_pod.get("nodeset") or "").strip() != nodeset_name
                    or str(verified_pod.get("statefulset_uid") or "").strip() != target_uid
                    or not str(pod_state.get("replacement_bound_at") or "").strip()
                ):
                    raise SoperatorMigrationPhasePending(
                        "GPU driver jail init repair replacement binding drifted from its "
                        f"verified checkpoint for {pod_name}."
                    )
            bindings.append((nodeset_name, item, captured, target_uid))
    if not bindings:
        return []

    target_binding = _target_handoff_binding_for_helm_apply_proof(
        rolling_phase,
        target_ref=target_ref,
    )
    _accounting_handoff_exact_slurmcluster(
        command_runner=command_runner,
        kube_context=kube_context,
        binding=target_binding,
        label="GPU driver jail init repair",
    )
    repair = rolling_phase.setdefault("gpu_driver_jail_init_repair", {})
    if not isinstance(repair, dict):
        raise SoperatorMigrationPhasePending("GPU driver jail init repair checkpoint is malformed.")
    if repair and repair.get("schema") != _GPU_DRIVER_JAIL_INIT_REPAIR_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair checkpoint schema is unsupported."
        )

    release = _exact_deployed_target_soperator_release(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    chart_path = _target_soperator_chart_path()
    chart = _target_soperator_chart_metadata(chart_path)
    expected_chart = f"{chart['name']}-{chart['version']}"
    if release.chart != expected_chart or release.app_version != chart["app_version"]:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair found target Helm chart or application version drift."
        )
    stored_values = _target_soperator_helm_stored_values(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    effective_values = _effective_target_soperator_helm_values(stored_values)
    if _fingerprint(effective_values) != _fingerprint(stored_values):
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair refuses a Helm replay that would normalize stored values."
        )
    rendered_manifest = _render_target_soperator_manifest(
        command_runner=command_runner,
        chart_path=chart_path,
        effective_values=effective_values,
    )
    if not _gpu_driver_jail_init_script_is_loader_contract(rendered_manifest):
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair selected chart does not render the loader probe contract."
        )

    before_revision = _positive_int(repair.get("release_revision_before"), fallback=0)
    current_revision = _positive_int(release.revision, fallback=0)
    status = str(repair.get("status") or "").strip()
    if status == "verified":
        verified_manifest = _target_soperator_installed_manifest(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        sysfs_repair = _mapping(rolling_phase.get("gpu_health_sysfs_repair"))
        if sysfs_repair.get("status") == "verified":
            exact_sysfs_revision = bool(
                sysfs_repair.get("schema") == _GPU_HEALTH_SYSFS_REPAIR_SCHEMA
                and current_revision
                == _positive_int(sysfs_repair.get("release_revision_after"), fallback=0)
                and _fingerprint(stored_values) == str(sysfs_repair.get("values_fingerprint") or "")
                and _fingerprint(verified_manifest)
                == str(sysfs_repair.get("installed_manifest_fingerprint_after") or "")
            )
            gpu_contracts_hold = bool(
                _gpu_driver_jail_init_script_is_loader_contract(verified_manifest)
                and _gpu_health_sysfs_manifest_has_contract(
                    verified_manifest,
                    gpu_nodesets=gpu_nodesets,
                )
            )
            topology_replay = _verified_target_topology_values_replay_after_gpu_health_sysfs(
                rolling_phase,
                target_ref=target_ref,
                release_revision=current_revision,
                stored_values=stored_values,
                installed_manifest=verified_manifest,
                chart_content_fingerprint=_target_soperator_chart_content_fingerprint(chart_path),
            )
            if not gpu_contracts_hold or not (exact_sysfs_revision or topology_replay):
                raise SoperatorMigrationPhasePending(
                    "GPU driver jail init repair drifted after the verified GPU health "
                    "sysfs Helm revision."
                )
            if topology_replay:
                return [
                    "GPU driver jail init loader repair reused its verified GPU health "
                    "contract after the exact target topology values replay."
                ]
            return [
                "GPU driver jail init loader repair reused its exact verified checkpoint "
                "after the GPU health sysfs Helm revision."
            ]
        repair_revision = _positive_int(repair.get("release_revision_after"), fallback=0)
        stored_values_fingerprint = _fingerprint(stored_values)
        installed_manifest_fingerprint = _fingerprint(verified_manifest)
        loader_contract_verified = _gpu_driver_jail_init_script_is_loader_contract(
            verified_manifest
        )
        if (
            current_revision == repair_revision
            and stored_values_fingerprint == str(repair.get("values_fingerprint") or "")
            and installed_manifest_fingerprint
            == str(repair.get("installed_manifest_fingerprint_after") or "")
            and loader_contract_verified
        ):
            return ["GPU driver jail init loader repair reused its exact verified checkpoint."]

        downstream = _mapping(repair.get("post_repair_helm_reconciliation"))
        if downstream:
            downstream_open_metrics = _mapping(populate_phase.get("slurm_open_metrics_handoff"))
            topology_replay = _verified_target_topology_values_replay_after_gpu_health_sysfs(
                rolling_phase,
                target_ref=target_ref,
                release_revision=current_revision,
                stored_values=stored_values,
                installed_manifest=verified_manifest,
                chart_content_fingerprint=_target_soperator_chart_content_fingerprint(chart_path),
            )
            static_downstream_proof = bool(
                downstream.get("schema") == _GPU_DRIVER_JAIL_POST_REPAIR_HELM_SCHEMA
                and downstream.get("status") == "verified"
                and downstream_open_metrics.get("status") == "restored"
                and downstream.get("restore_intent_at")
                == downstream_open_metrics.get("restore_intent_at")
                and downstream.get("restored_at") == downstream_open_metrics.get("restored_at")
                and loader_contract_verified
            )
            exact_downstream_revision = bool(
                current_revision == _positive_int(downstream.get("release_revision"), fallback=0)
                and stored_values_fingerprint == str(downstream.get("values_fingerprint") or "")
                and installed_manifest_fingerprint
                == str(downstream.get("installed_manifest_fingerprint") or "")
            )
            if topology_replay and static_downstream_proof and not exact_downstream_revision:
                mutable_downstream = repair.get("post_repair_helm_reconciliation")
                if not isinstance(mutable_downstream, dict):
                    raise SoperatorMigrationPhasePending(
                        "GPU driver jail init downstream topology successor is not writable."
                    )
                history = repair.setdefault("post_repair_helm_reconciliation_history", [])
                if not isinstance(history, list):
                    raise SoperatorMigrationPhasePending(
                        "GPU driver jail init downstream Helm history is malformed."
                    )
                history.append(copy.deepcopy(to_plain_data(mutable_downstream)))
                topology_proof = _mapping(rolling_phase.get("target_handoff_values_proof"))
                mutable_downstream.update(
                    {
                        "release_revision": current_revision,
                        "values_fingerprint": stored_values_fingerprint,
                        "installed_manifest_fingerprint": installed_manifest_fingerprint,
                        "target_manifest_fingerprint": (
                            _target_slurmcluster_manifest_fingerprint(
                                verified_manifest,
                                target_ref=target_ref,
                                label="GPU init downstream topology successor",
                            )
                        ),
                        "successor": "typed-gres-topology-values-replay",
                        "topology_values_proof_fingerprint": _fingerprint(topology_proof),
                        "verified_at": _utc_now(),
                    }
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                return [
                    "GPU driver jail init loader repair promoted its downstream Helm proof "
                    "through the exact typed-GRES topology values successor."
                ]
            if not static_downstream_proof or not exact_downstream_revision:
                raise SoperatorMigrationPhasePending(
                    "GPU driver jail init repair downstream Helm proof drifted after verification."
                )
            return [
                "GPU driver jail init loader repair reused its exact verified checkpoint "
                "after the checkpointed OpenMetrics restore revision."
            ]

        open_metrics = _mapping(populate_phase.get("slurm_open_metrics_handoff"))
        restore_intent_at = _target_soperator_helm_history_time(
            open_metrics.get("restore_intent_at")
        )
        restored_at = _target_soperator_helm_history_time(open_metrics.get("restored_at"))
        history_entry = _target_soperator_helm_revision_history_entry(
            command_runner=command_runner,
            kube_context=kube_context,
            revision=current_revision,
        )
        history_updated = cast(datetime, history_entry["updated"])
        expected_values_fingerprint = _fingerprint(_effective_target_soperator_helm_values(values))
        installed_target_fingerprint = _target_slurmcluster_manifest_fingerprint(
            verified_manifest,
            target_ref=target_ref,
            label="GPU init repair downstream installed manifest",
        )
        rendered_target_fingerprint = _target_slurmcluster_manifest_fingerprint(
            rendered_manifest,
            target_ref=target_ref,
            label="GPU init repair downstream chart render",
        )
        topology_replay = _verified_target_topology_values_replay_after_gpu_health_sysfs(
            rolling_phase,
            target_ref=target_ref,
            release_revision=current_revision,
            stored_values=stored_values,
            installed_manifest=verified_manifest,
            chart_content_fingerprint=_target_soperator_chart_content_fingerprint(chart_path),
        )
        exact_open_metrics_successor = bool(
            current_revision == repair_revision + 1
            and history_updated >= restore_intent_at
            and history_updated <= restored_at
        )
        topology_replay_successor = bool(topology_replay and history_updated >= restored_at)
        if (
            not (exact_open_metrics_successor or topology_replay_successor)
            or open_metrics.get("status") != "restored"
            or not str(open_metrics.get("post_restore_readiness_verified_at") or "").strip()
            or history_entry["status"] != "deployed"
            or history_entry["chart"] != expected_chart
            or history_entry["app_version"] != chart["app_version"]
            or (
                not topology_replay_successor
                and stored_values_fingerprint != expected_values_fingerprint
            )
            or installed_target_fingerprint != rendered_target_fingerprint
            or not loader_contract_verified
        ):
            raise SoperatorMigrationPhasePending(
                "GPU driver jail init repair Helm proof drifted after verification."
            )
        repair["post_repair_helm_reconciliation"] = {
            "schema": _GPU_DRIVER_JAIL_POST_REPAIR_HELM_SCHEMA,
            "status": "verified",
            "boundary": "open-metrics-restore",
            "release_revision": current_revision,
            "release_updated_at": history_entry["updated_at"],
            "values_fingerprint": stored_values_fingerprint,
            "installed_manifest_fingerprint": installed_manifest_fingerprint,
            "target_manifest_fingerprint": installed_target_fingerprint,
            "restore_intent_at": open_metrics.get("restore_intent_at"),
            "restored_at": open_metrics.get("restored_at"),
            "successor": (
                "topology-values-replay" if topology_replay_successor else "open-metrics-restore"
            ),
            "verified_at": _utc_now(),
        }
        checkpoint_writer()
        return [
            "GPU driver jail init loader repair sealed the exact checkpointed "
            "OpenMetrics restore Helm revision."
        ]

    if not repair:
        target_contracts: dict[str, str] = {}
        for nodeset_name, _item, _captured, target_uid in bindings:
            if nodeset_name in target_contracts:
                continue
            target = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="statefulset.apps.kruise.io",
                name=nodeset_name,
            )
            _immutable_child_require_live_uid(
                target,
                expected_uid=target_uid,
                label=f"GPU init repair target StatefulSet {nodeset_name}",
            )
            target_script = _gpu_driver_jail_init_script_from_pod_spec(
                _mapping(_mapping(_mapping(target.get("spec")).get("template")).get("spec"))
            )
            if _gpu_driver_jail_init_script_is_loader_contract(target_script):
                target_contracts[nodeset_name] = "loader"
            elif _gpu_driver_jail_init_script_is_old_chroot_contract(target_script):
                target_contracts[nodeset_name] = "old-chroot"
            else:
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair refuses target StatefulSet drift for {nodeset_name}."
                )

        if "loader" in target_contracts.values():
            if set(target_contracts.values()) != {"loader"}:
                raise SoperatorMigrationPhasePending(
                    "GPU init repair refuses mixed target StatefulSet GPU probe contracts."
                )
            installed_manifest = _target_soperator_installed_manifest(
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if not _gpu_driver_jail_init_script_is_loader_contract(installed_manifest):
                raise SoperatorMigrationPhasePending(
                    "GPU init repair target StatefulSets use the loader contract, but the "
                    "installed target Helm manifest does not."
                )

            replacement_deadline = time.monotonic() + replacement_timeout_seconds
            replacement_pods: dict[str, dict[str, str]] = {}
            while True:
                replacement_pods = {}
                pending: list[str] = []
                for nodeset_name, item, captured, target_uid in bindings:
                    pod_name = str(captured.get("name") or "").strip()
                    pod = _immutable_child_optional_namespaced_resource(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        resource_type="pod",
                        name=pod_name,
                        label=f"GPU init repair replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
                    )
                    if pod is None:
                        pending.append(pod_name)
                        continue
                    identity = _immutable_child_exact_identity(
                        pod,
                        label=f"GPU init repair replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
                    )
                    owner = _immutable_child_controller_owner(
                        pod,
                        label=f"GPU init repair replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
                    )
                    selector = _mapping(item.get("target_selector"))
                    labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
                    script = _gpu_driver_jail_init_script_from_pod_spec(_mapping(pod.get("spec")))
                    if (
                        identity["uid"] == str(captured.get("uid") or "")
                        or str(_mapping(owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
                        or str(_mapping(owner).get("kind") or "") != "StatefulSet"
                        or str(_mapping(owner).get("name") or "") != nodeset_name
                        or str(_mapping(owner).get("uid") or "") != target_uid
                        or not selector
                        or any(
                            str(labels.get(key) or "") != value for key, value in selector.items()
                        )
                        or not _gpu_driver_jail_init_script_is_loader_contract(script)
                    ):
                        raise SoperatorMigrationPhasePending(
                            "GPU init repair refuses unproven preinstalled loader state for "
                            f"replacement Pod {pod_name}."
                        )
                    replacement_pods[pod_name] = {
                        "nodeset": nodeset_name,
                        "uid": identity["uid"],
                        "statefulset_uid": target_uid,
                        "script_fingerprint": _fingerprint(script),
                    }
                if not pending:
                    break
                if time.monotonic() >= replacement_deadline:
                    raise SoperatorMigrationPhasePending(
                        "GPU init repair timed out waiting for exact preinstalled "
                        "loader-contract replacement Pods: " + ", ".join(sorted(pending))
                    )
                time.sleep(2)

            repair.update(
                {
                    "schema": _GPU_DRIVER_JAIL_INIT_REPAIR_SCHEMA,
                    "status": "verified",
                    "target": target_binding,
                    "release_revision_before": current_revision,
                    "release_revision_after": current_revision,
                    "chart": release.chart,
                    "app_version": release.app_version,
                    "values_fingerprint": _fingerprint(stored_values),
                    "installed_manifest_fingerprint_before": _fingerprint(installed_manifest),
                    "installed_manifest_fingerprint_after": _fingerprint(installed_manifest),
                    "chart_content_fingerprint": (
                        _target_soperator_chart_content_fingerprint(chart_path)
                    ),
                    "rendered_manifest_fingerprint": _fingerprint(rendered_manifest),
                    "replacement_pods": replacement_pods,
                    "recovered_from_live_state": True,
                    "recovery_boundary": "preinstalled-loader-contract",
                    "verified_at": _utc_now(),
                }
            )
            checkpoint_writer()
            return [
                "GPU driver jail init loader repair adopted the exact preinstalled "
                "loader contract without a redundant Helm replay."
            ]

    deadline = time.monotonic() + replacement_timeout_seconds
    old_pod_evidence: dict[str, dict[str, str]] = {}
    while not repair:
        old_pod_evidence = {}
        pending: list[str] = []
        for nodeset_name, item, captured, target_uid in bindings:
            target = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="statefulset.apps.kruise.io",
                name=nodeset_name,
            )
            _immutable_child_require_live_uid(
                target,
                expected_uid=target_uid,
                label=f"GPU init repair target StatefulSet {nodeset_name}",
            )
            target_script = _gpu_driver_jail_init_script_from_pod_spec(
                _mapping(_mapping(_mapping(target.get("spec")).get("template")).get("spec"))
            )
            if not _gpu_driver_jail_init_script_is_old_chroot_contract(target_script):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair refuses target StatefulSet drift for {nodeset_name}."
                )
            pod_name = str(captured.get("name") or "").strip()
            pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=pod_name,
                label=f"GPU init repair {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if pod is None:
                pending.append(pod_name)
                continue
            identity = _immutable_child_exact_identity(
                pod,
                label=f"GPU init repair {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if identity["uid"] == str(captured.get("uid") or ""):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair found legacy worker Pod UID still live for {pod_name}."
                )
            owner = _immutable_child_controller_owner(
                pod,
                label=f"GPU init repair {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if (
                str(_mapping(owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
                or str(_mapping(owner).get("kind") or "") != "StatefulSet"
                or str(_mapping(owner).get("name") or "") != nodeset_name
                or str(_mapping(owner).get("uid") or "") != target_uid
            ):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair found non-target ownership for replacement Pod {pod_name}."
                )
            selector = _mapping(item.get("target_selector"))
            labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
            if not selector or any(
                str(labels.get(key) or "") != value for key, value in selector.items()
            ):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair found selector drift for replacement Pod {pod_name}."
                )
            script = _gpu_driver_jail_init_script_from_pod_spec(_mapping(pod.get("spec")))
            if not _gpu_driver_jail_init_script_is_old_chroot_contract(script):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair refuses an unclassified init script on Pod {pod_name}."
                )
            if not _gpu_driver_jail_init_failed(pod):
                pending.append(pod_name)
                continue
            log_result = command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "logs",
                    pod_name,
                    "-c",
                    SOPERATOR_GPU_DRIVER_JAIL_INIT_CONTAINER_NAME,
                    "--previous",
                    "--tail=50",
                ],
                timeout_seconds=60,
                check=False,
            )
            if log_result.returncode != 0 or (
                "ERROR: jailed nvidia-smi -L failed" not in log_result.stdout
            ):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair found an unclassified init failure on Pod {pod_name}."
                )
            old_pod_evidence[pod_name] = {
                "nodeset": nodeset_name,
                "uid": identity["uid"],
                "statefulset_uid": target_uid,
                "script_fingerprint": _fingerprint(script),
                "failure_log_fingerprint": _fingerprint(log_result.stdout),
            }
        if not pending:
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "GPU driver jail init repair timed out waiting for exact failed replacement Pods: "
                + ", ".join(sorted(pending))
            )
        time.sleep(2)

    if not repair:
        installed_manifest = _target_soperator_installed_manifest(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if not _gpu_driver_jail_init_script_is_old_chroot_contract(installed_manifest):
            raise SoperatorMigrationPhasePending(
                "GPU driver jail init repair installed manifest is not the exact old contract."
            )
        repair.update(
            {
                "schema": _GPU_DRIVER_JAIL_INIT_REPAIR_SCHEMA,
                "status": "prepared",
                "target": target_binding,
                "release_revision_before": current_revision,
                "chart": release.chart,
                "app_version": release.app_version,
                "values_fingerprint": _fingerprint(stored_values),
                "installed_manifest_fingerprint_before": _fingerprint(installed_manifest),
                "chart_content_fingerprint": _target_soperator_chart_content_fingerprint(
                    chart_path
                ),
                "rendered_manifest_fingerprint": _fingerprint(rendered_manifest),
                "old_pods": old_pod_evidence,
                "prepared_at": _utc_now(),
            }
        )
        checkpoint_writer()
        status = "prepared"
        before_revision = current_revision

    if (
        before_revision <= 0
        or repair.get("target") != target_binding
        or repair.get("chart") != release.chart
        or repair.get("app_version") != release.app_version
        or str(repair.get("values_fingerprint") or "") != _fingerprint(stored_values)
        or str(repair.get("chart_content_fingerprint") or "")
        != _target_soperator_chart_content_fingerprint(chart_path)
    ):
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair pre-apply evidence drifted after checkpoint."
        )

    installed_manifest = _target_soperator_installed_manifest(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    installed_is_old = _gpu_driver_jail_init_script_is_old_chroot_contract(installed_manifest)
    installed_is_new = _gpu_driver_jail_init_script_is_loader_contract(installed_manifest)
    if current_revision == before_revision and installed_is_old:
        for nodeset_name, _item, _captured, target_uid in bindings:
            target = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="statefulset.apps.kruise.io",
                name=nodeset_name,
            )
            _immutable_child_require_live_uid(
                target,
                expected_uid=target_uid,
                label=f"GPU init repair pre-apply StatefulSet {nodeset_name}",
            )
            script = _gpu_driver_jail_init_script_from_pod_spec(
                _mapping(_mapping(_mapping(target.get("spec")).get("template")).get("spec"))
            )
            if not _gpu_driver_jail_init_script_is_old_chroot_contract(script):
                raise SoperatorMigrationPhasePending(
                    f"GPU init repair target StatefulSet changed before apply for {nodeset_name}."
                )
        repair["status"] = "apply-intent"
        repair["apply_intent_at"] = repair.get("apply_intent_at") or _utc_now()
        checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _revalidate_legacy_rootfs_sconfig_before_target_helm_replay(
            populate_phase=populate_phase,
            rolling_phase=rolling_phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        _helm_upgrade_target_soperator_with_jail_login_session_policy(
            checkpoint=checkpoint,
            phase=populate_phase,
            command_runner=command_runner,
            kube_context=kube_context,
            values=stored_values,
            expected_version=expected_version,
            boundary="gpu-driver-jail-init-loader-repair",
            login_session_policy=login_session_policy,
            login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
            wait=False,
            checkpoint_writer=checkpoint_writer,
        )
        release = _exact_deployed_target_soperator_release(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        current_revision = _positive_int(release.revision, fallback=0)
        installed_manifest = _target_soperator_installed_manifest(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        installed_is_new = _gpu_driver_jail_init_script_is_loader_contract(installed_manifest)
    if current_revision != before_revision + 1 or not installed_is_new:
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair did not produce exactly one loader-contract Helm revision."
        )
    if (
        release.chart != repair.get("chart")
        or release.app_version != repair.get("app_version")
        or _fingerprint(
            _target_soperator_helm_stored_values(
                command_runner=command_runner,
                kube_context=kube_context,
            )
        )
        != repair.get("values_fingerprint")
    ):
        raise SoperatorMigrationPhasePending(
            "GPU driver jail init repair changed Helm chart metadata or stored values."
        )
    _revalidate_legacy_rootfs_sconfig_before_target_helm_replay(
        populate_phase=populate_phase,
        rolling_phase=rolling_phase,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    for nodeset_name, _item, _captured, target_uid in bindings:
        target = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="statefulset.apps.kruise.io",
            name=nodeset_name,
        )
        _immutable_child_require_live_uid(
            target,
            expected_uid=target_uid,
            label=f"GPU init repair post-apply StatefulSet {nodeset_name}",
        )
        script = _gpu_driver_jail_init_script_from_pod_spec(
            _mapping(_mapping(_mapping(target.get("spec")).get("template")).get("spec"))
        )
        if not _gpu_driver_jail_init_script_is_loader_contract(script):
            raise SoperatorMigrationPhasePending(
                f"GPU init repair target StatefulSet lacks loader contract for {nodeset_name}."
            )

    replacement_deadline = time.monotonic() + replacement_timeout_seconds
    replacement_pods: dict[str, dict[str, str]] = {}
    while True:
        replacement_pods = {}
        pending = []
        for nodeset_name, _item, captured, target_uid in bindings:
            pod_name = str(captured.get("name") or "").strip()
            pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=pod_name,
                label=f"GPU init repair replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if pod is None:
                pending.append(pod_name)
                continue
            identity = _immutable_child_exact_identity(
                pod,
                label=f"GPU init repair replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            prior_uid = str(_mapping(repair.get("old_pods")).get(pod_name, {}).get("uid") or "")
            owner = _immutable_child_controller_owner(
                pod,
                label=f"GPU init repair replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            script = _gpu_driver_jail_init_script_from_pod_spec(_mapping(pod.get("spec")))
            if (
                identity["uid"] == prior_uid
                or str(_mapping(owner).get("uid") or "") != target_uid
                or not _gpu_driver_jail_init_script_is_loader_contract(script)
            ):
                pending.append(pod_name)
                continue
            replacement_pods[pod_name] = {
                "nodeset": nodeset_name,
                "uid": identity["uid"],
                "statefulset_uid": target_uid,
                "script_fingerprint": _fingerprint(script),
            }
        if not pending:
            break
        if time.monotonic() >= replacement_deadline:
            raise SoperatorMigrationPhasePending(
                "GPU driver jail init repair timed out waiting for loader-contract replacement Pods: "
                + ", ".join(sorted(pending))
            )
        time.sleep(2)
    repair.update(
        {
            "status": "verified",
            "release_revision_after": current_revision,
            "installed_manifest_fingerprint_after": _fingerprint(installed_manifest),
            "replacement_pods": replacement_pods,
            "verified_at": _utc_now(),
        }
    )
    checkpoint_writer()
    return [
        "GPU driver jail init loader repair applied one exact same-version Helm revision "
        "with unchanged stored values."
    ]


def _repair_gpu_health_sysfs_for_target_workers(
    *,
    checkpoint: dict[str, Any],
    populate_phase: dict[str, Any],
    rolling_phase: dict[str, Any],
    values: Mapping[str, Any],
    expected_version: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    login_session_policy: str,
    login_session_drain_timeout_seconds: int,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    replacement_timeout_seconds: int = 900,
) -> list[str]:
    """Install the exact host-sysfs projection required by jailed GPU health checks."""

    gpu_nodesets = _gpu_worker_nodeset_names(values)
    if not gpu_nodesets:
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair requires durable checkpoint writes."
        )
    handoff = _immutable_child_handoff_state(rolling_phase)
    if str(handoff.get("status") or "") != "target-children-created":
        return []

    release = _exact_deployed_target_soperator_release(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    chart_path = _target_soperator_chart_path()
    chart = _target_soperator_chart_metadata(chart_path)
    chart_content_fingerprint = _target_soperator_chart_content_fingerprint(chart_path)
    expected_chart = f"{chart['name']}-{chart['version']}"
    if release.chart != expected_chart or release.app_version != chart["app_version"]:
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair found target Helm chart or application version drift."
        )
    stored_values = _target_soperator_helm_stored_values(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if _fingerprint(_effective_target_soperator_helm_values(stored_values)) != _fingerprint(
        stored_values
    ):
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair refuses a Helm replay that would normalize stored values."
        )
    rendered_manifest = _render_target_soperator_manifest(
        command_runner=command_runner,
        chart_path=chart_path,
        effective_values=stored_values,
    )
    if not _gpu_health_sysfs_manifest_has_contract(
        rendered_manifest,
        gpu_nodesets=gpu_nodesets,
    ):
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair selected chart lacks the exact host /sys projection."
        )

    repair = rolling_phase.setdefault("gpu_health_sysfs_repair", {})
    if not isinstance(repair, dict):
        raise SoperatorMigrationPhasePending("GPU health sysfs repair checkpoint is malformed.")
    if repair and repair.get("schema") != _GPU_HEALTH_SYSFS_REPAIR_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair checkpoint schema is unsupported."
        )
    current_revision = _positive_int(release.revision, fallback=0)
    installed_manifest = _target_soperator_installed_manifest(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    installed_has_contract = _gpu_health_sysfs_manifest_has_contract(
        installed_manifest,
        gpu_nodesets=gpu_nodesets,
    )
    if not repair and installed_has_contract:
        return ["GPU health sysfs mount already matches the chart contract."]

    if repair.get("status") == "verified":
        exact_repair_revision = bool(
            current_revision == _positive_int(repair.get("release_revision_after"), fallback=0)
            and repair.get("chart") == release.chart
            and repair.get("app_version") == release.app_version
            and str(repair.get("values_fingerprint") or "") == _fingerprint(stored_values)
            and str(repair.get("installed_manifest_fingerprint_after") or "")
            == _fingerprint(installed_manifest)
        )
        topology_replay = bool(
            repair.get("chart") == release.chart
            and repair.get("app_version") == release.app_version
            and _verified_target_topology_values_replay_after_gpu_health_sysfs(
                rolling_phase,
                target_ref=str(
                    _mapping(
                        _mapping(rolling_phase.get("slurmcluster_handoff_binding")).get("target")
                    ).get("name")
                    or ""
                ),
                release_revision=current_revision,
                stored_values=stored_values,
                installed_manifest=installed_manifest,
                chart_content_fingerprint=chart_content_fingerprint,
            )
        )
        if not installed_has_contract or not (exact_repair_revision or topology_replay):
            raise SoperatorMigrationPhasePending(
                "GPU health sysfs repair drifted from its verified Helm checkpoint."
            )
        if topology_replay:
            return [
                "GPU health sysfs repair reused its verified mount contract after the "
                "exact target topology values replay."
            ]
        return ["GPU health sysfs repair reused its exact verified checkpoint."]

    workloads = _mapping(handoff.get("workloads"))
    old_pods: dict[str, dict[str, str]] = {}
    if not repair:
        if not _gpu_driver_jail_init_script_is_loader_contract(installed_manifest):
            raise SoperatorMigrationPhasePending(
                "GPU health sysfs repair requires the verified loader-contract release."
            )
        for nodeset_name in gpu_nodesets:
            matches = tuple(
                item
                for item in workloads.values()
                if isinstance(item, Mapping)
                and item.get("component") == "nodeset"
                and str(item.get("name") or "") == nodeset_name
            )
            if len(matches) != 1:
                raise SoperatorMigrationPhasePending(
                    f"GPU health sysfs repair lacks one worker binding for {nodeset_name}."
                )
            item = matches[0]
            target_uid = str(item.get("target_uid") or "").strip()
            rollover = _mapping(item.get("old_pod_rollover"))
            if (
                item.get("status") != "target-bound"
                or not target_uid
                or rollover.get("status") != "target-replacements-bound"
            ):
                raise SoperatorMigrationPhasePending(
                    f"GPU health sysfs repair lacks bound target replacements for {nodeset_name}."
                )
            for captured in _sequence_of_mappings(item.get("pods")):
                pod_name = str(captured.get("name") or "").strip()
                expected_uid = str(_mapping(rollover.get(pod_name)).get("replacement_uid") or "")
                pod = _immutable_child_get_namespaced_resource(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    resource_type="pod",
                    name=pod_name,
                )
                identity = _immutable_child_exact_identity(
                    pod,
                    label=f"GPU health sysfs repair {_SOPERATOR_NAMESPACE}/{pod_name}",
                )
                owner = _immutable_child_controller_owner(
                    pod,
                    label=f"GPU health sysfs repair {_SOPERATOR_NAMESPACE}/{pod_name}",
                )
                if (
                    not expected_uid
                    or identity["uid"] != expected_uid
                    or str(_mapping(owner).get("uid") or "") != target_uid
                ):
                    raise SoperatorMigrationPhasePending(
                        f"GPU health sysfs repair worker binding drifted for {pod_name}."
                    )
                old_pods[pod_name] = {
                    "nodeset": nodeset_name,
                    "uid": identity["uid"],
                    "statefulset_uid": target_uid,
                }
        repair.update(
            {
                "schema": _GPU_HEALTH_SYSFS_REPAIR_SCHEMA,
                "status": "prepared",
                "release_revision_before": current_revision,
                "chart": release.chart,
                "app_version": release.app_version,
                "chart_content_fingerprint": chart_content_fingerprint,
                "values_fingerprint": _fingerprint(stored_values),
                "installed_manifest_fingerprint_before": _fingerprint(installed_manifest),
                "rendered_manifest_fingerprint": _fingerprint(rendered_manifest),
                "old_pods": old_pods,
                "prepared_at": _utc_now(),
            }
        )
        checkpoint_writer()

    before_revision = _positive_int(repair.get("release_revision_before"), fallback=0)
    if (
        before_revision <= 0
        or repair.get("chart") != release.chart
        or repair.get("app_version") != release.app_version
        or repair.get("chart_content_fingerprint") != chart_content_fingerprint
        or str(repair.get("values_fingerprint") or "") != _fingerprint(stored_values)
        or str(repair.get("rendered_manifest_fingerprint") or "") != _fingerprint(rendered_manifest)
    ):
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair pre-apply evidence drifted after checkpoint."
        )
    if current_revision == before_revision and not installed_has_contract:
        if _fingerprint(installed_manifest) != str(
            repair.get("installed_manifest_fingerprint_before") or ""
        ):
            raise SoperatorMigrationPhasePending(
                "GPU health sysfs repair installed manifest drifted before apply."
            )
        repair["status"] = "apply-intent"
        repair["apply_intent_at"] = repair.get("apply_intent_at") or _utc_now()
        checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _revalidate_legacy_rootfs_sconfig_before_target_helm_replay(
            populate_phase=populate_phase,
            rolling_phase=rolling_phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        _helm_upgrade_target_soperator_with_jail_login_session_policy(
            checkpoint=checkpoint,
            phase=populate_phase,
            command_runner=command_runner,
            kube_context=kube_context,
            values=stored_values,
            expected_version=expected_version,
            boundary="gpu-health-sysfs-repair",
            login_session_policy=login_session_policy,
            login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
            wait=False,
            checkpoint_writer=checkpoint_writer,
        )
        release = _exact_deployed_target_soperator_release(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        current_revision = _positive_int(release.revision, fallback=0)
        installed_manifest = _target_soperator_installed_manifest(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        installed_has_contract = _gpu_health_sysfs_manifest_has_contract(
            installed_manifest,
            gpu_nodesets=gpu_nodesets,
        )
    if current_revision != before_revision + 1 or not installed_has_contract:
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair did not produce exactly one contract Helm revision."
        )
    if (
        release.chart != repair.get("chart")
        or release.app_version != repair.get("app_version")
        or _fingerprint(
            _target_soperator_helm_stored_values(
                command_runner=command_runner,
                kube_context=kube_context,
            )
        )
        != repair.get("values_fingerprint")
    ):
        raise SoperatorMigrationPhasePending(
            "GPU health sysfs repair changed Helm metadata or stored values."
        )

    deadline = time.monotonic() + replacement_timeout_seconds
    replacement_pods: dict[str, dict[str, str]] = {}
    while True:
        replacement_pods = {}
        pending: list[str] = []
        for pod_name, prior in _mapping(repair.get("old_pods")).items():
            pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=pod_name,
                label=f"GPU health sysfs replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if pod is None:
                pending.append(pod_name)
                continue
            identity = _immutable_child_exact_identity(
                pod,
                label=f"GPU health sysfs replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            owner = _immutable_child_controller_owner(
                pod,
                label=f"GPU health sysfs replacement {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if (
                identity["uid"] == str(_mapping(prior).get("uid") or "")
                or str(_mapping(owner).get("uid") or "")
                != str(_mapping(prior).get("statefulset_uid") or "")
                or _gpu_driver_jail_pod_contract_reason(pod)
            ):
                pending.append(pod_name)
                continue
            replacement_pods[pod_name] = {
                "nodeset": str(_mapping(prior).get("nodeset") or ""),
                "uid": identity["uid"],
                "statefulset_uid": str(_mapping(prior).get("statefulset_uid") or ""),
            }
        if not pending:
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "GPU health sysfs repair timed out waiting for exact replacement Pods: "
                + ", ".join(sorted(pending))
            )
        time.sleep(2)
    repair.update(
        {
            "status": "verified",
            "release_revision_after": current_revision,
            "installed_manifest_fingerprint_after": _fingerprint(installed_manifest),
            "replacement_pods": replacement_pods,
            "verified_at": _utc_now(),
        }
    )
    checkpoint_writer()
    return [
        "GPU health sysfs repair applied one exact same-version Helm revision with "
        "unchanged stored values."
    ]


def _prepare_immutable_child_handoff_before_source_retirement(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    controller_bridge: Mapping[str, Any] | None = None,
) -> list[str]:
    handoff = _immutable_child_handoff_state(phase)
    if handoff.get("status") in {"not-required", "complete"}:
        return []
    if not handoff.get("captured_at"):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff cannot pause the manager before exact inventory capture."
        )
    status = str(handoff.get("status") or "")
    if status not in {"captured", "login-bridge-ready", "manager-paused"}:
        if status in {
            "children-prepared",
            "manager-restored",
            "target-children-created",
            "cleanup-intent",
        }:
            return []
        raise SoperatorMigrationPhasePending(
            f"immutable child pre-retirement handoff cannot resume from status {status or 'missing'}."
        )
    bridge = _mapping(handoff.get("login_bridge"))
    if bridge.get("status") not in {"token-selector-ready", "target-selector-ready"}:
        _prepare_login_handoff_bridge(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    if status != "manager-paused":
        handoff["status"] = "login-bridge-ready"
        if checkpoint_writer is not None:
            checkpoint_writer()
        _pause_soperator_manager_for_child_handoff(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    bridge_lines = _activate_legacy_rootfs_slurm_config_bridge(
        phase=phase,
        handoff=handoff,
        source_binding=_mapping(handoff.get("source")),
        target_binding=_mapping(handoff.get("target")),
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
        controller_bridge=controller_bridge,
    )
    return [
        "Immutable child handoff paused the exact Soperator manager and retained login "
        "LoadBalancer endpoints before source retirement.",
        *bridge_lines,
    ]


def _legacy_rootfs_target_sconfig_binding(
    *,
    state: Mapping[str, Any],
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[Mapping[str, Any], dict[str, str], str, dict[str, str]]:
    item = _legacy_rootfs_sconfig_workload(handoff)
    expected_uid = str(item.get("target_uid") or "").strip()
    if not expected_uid:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility stage lacks the target SConfig Deployment UID."
        )
    deployment = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
    )
    identity = _immutable_child_require_live_uid(
        deployment,
        expected_uid=expected_uid,
        label="target SConfig Deployment",
    )
    owner = _immutable_child_controller_owner(
        deployment,
        label="target SConfig Deployment",
    )
    if not _controller_owner_reference_matches_binding(
        _mapping(owner),
        _mapping(handoff.get("target")),
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment is not owned by the exact target SlurmCluster."
        )
    pod_spec = _mapping(_mapping(_mapping(deployment.get("spec")).get("template")).get("spec"))
    service_account_name = str(pod_spec.get("serviceAccountName") or "").strip()
    target_resource, _target_identity = _legacy_rootfs_target_slurmcluster(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    expected_service_account_name = str(
        _mapping(_mapping(target_resource.get("spec")).get("sConfigController")).get(
            "serviceAccountName"
        )
        or ""
    ).strip()
    source_service_account_name = str(
        _mapping(state.get("sconfig_deployment")).get("service_account_name") or ""
    ).strip()
    if (
        not service_account_name
        or service_account_name != expected_service_account_name
        or service_account_name == source_service_account_name
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment must use the exact target SlurmCluster/chart "
            "ServiceAccount, not the retired source ServiceAccount."
        )
    service_account = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="serviceaccount",
        name=service_account_name,
    )
    service_account_identity = _immutable_child_exact_identity(
        service_account,
        label="target SConfig ServiceAccount",
    )
    metadata = _mapping(service_account.get("metadata"))
    annotations = _mapping(metadata.get("annotations"))
    labels = _mapping(metadata.get("labels"))
    if not (
        annotations.get("meta.helm.sh/release-name") == _SOPERATOR_TARGET_RELEASE_NAME
        and annotations.get("meta.helm.sh/release-namespace") == _SOPERATOR_NAMESPACE
        and labels.get("app.kubernetes.io/managed-by") == "Helm"
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig ServiceAccount lacks the exact target Helm release identity."
        )
    _legacy_rootfs_bridge_verify_sconfig_rbac(
        service_account_name=service_account_name,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    return deployment, identity, service_account_name, service_account_identity


def _legacy_rootfs_wait_target_sconfig_zero(
    *,
    deployment_uid: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    timeout_seconds: int = 300,
) -> dict[str, str]:
    deadline = time.monotonic() + max(timeout_seconds, 0)
    stable_signature: tuple[str, int, str, tuple[tuple[str, str, int], ...]] | None = None
    while True:
        deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        identity = _immutable_child_require_live_uid(
            deployment,
            expected_uid=deployment_uid,
            label="target SConfig Deployment zero fence",
        )
        status = _mapping(deployment.get("status"))
        generation = _legacy_rootfs_positive_generation(
            deployment,
            label="target SConfig Deployment zero fence",
        )
        selector = _mapping(_mapping(deployment.get("spec")).get("selector"))
        match_labels = _mapping(selector.get("matchLabels"))
        if not match_labels:
            raise SoperatorMigrationPhasePending(
                "target SConfig Deployment zero fence lacks an exact selector."
            )
        replica_set_uids: set[str] = set()
        replica_set_signatures: list[tuple[str, str, int]] = []
        replica_sets_zero = True
        for replica_set in _immutable_child_list(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="replicasets.apps",
        ):
            metadata = _mapping(replica_set.get("metadata"))
            raw_owners = _sequence_of_mappings(metadata.get("ownerReferences"))
            if not any(
                owner.get("controller") is True
                and str(owner.get("kind") or "").strip() == "Deployment"
                and str(owner.get("uid") or "").strip() == deployment_uid
                for owner in raw_owners
            ):
                continue
            replica_set_uid = _immutable_child_exact_identity(
                replica_set,
                label="target SConfig ReplicaSet zero fence",
            )["uid"]
            replica_set_uids.add(replica_set_uid)
            replica_set_identity = _immutable_child_exact_identity(
                replica_set,
                label="target SConfig ReplicaSet zero stability",
            )
            replica_set_signatures.append(
                (
                    replica_set_uid,
                    replica_set_identity["resourceVersion"],
                    _legacy_rootfs_positive_generation(
                        replica_set,
                        label="target SConfig ReplicaSet zero stability",
                    ),
                )
            )
            replica_status = _mapping(replica_set.get("status"))
            if (
                _resource_replicas(replica_set, default=-1) != 0
                or _non_negative_int(replica_status.get("replicas"), fallback=0) != 0
                or _non_negative_int(replica_status.get("readyReplicas"), fallback=0) != 0
                or _non_negative_int(replica_status.get("availableReplicas"), fallback=0) != 0
            ):
                replica_sets_zero = False
        replica_sets_zero = replica_sets_zero and bool(replica_set_uids)
        matching_pods: list[dict[str, str]] = []
        for pod in _immutable_child_list(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pods",
        ):
            metadata = _mapping(pod.get("metadata"))
            labels = _mapping(metadata.get("labels"))
            raw_owners = _sequence_of_mappings(metadata.get("ownerReferences"))
            owner_bound = any(
                owner.get("controller") is True
                and str(owner.get("kind") or "").strip() == "ReplicaSet"
                and str(owner.get("uid") or "").strip() in replica_set_uids
                for owner in raw_owners
            )
            selector_bound = all(labels.get(key) == value for key, value in match_labels.items())
            if owner_bound or selector_bound:
                matching_pods.append(
                    _immutable_child_exact_identity(
                        pod,
                        label="target SConfig Pod zero fence",
                    )
                )
        ready_candidate = bool(
            _resource_replicas(deployment, default=-1) == 0
            and _non_negative_int(status.get("replicas"), fallback=0) == 0
            and _non_negative_int(status.get("readyReplicas"), fallback=0) == 0
            and replica_sets_zero
            and not matching_pods
        )
        signature = (
            identity["uid"],
            generation,
            _legacy_rootfs_scalable_spec_fingerprint(
                deployment,
                label="target SConfig Deployment zero stability",
            ),
            tuple(sorted(replica_set_signatures)),
        )
        if ready_candidate and stable_signature == signature:
            return identity
        if ready_candidate:
            if stable_signature is not None and time.monotonic() >= deadline:
                raise SoperatorMigrationPhasePending(
                    "target SConfig zero proof did not remain stable before its deadline."
                )
            stable_signature = signature
            time.sleep(0 if timeout_seconds <= 0 else min(1, max(timeout_seconds, 0)))
            continue
        stable_signature = None
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target SConfig Deployment or its writer Pods did not converge to zero."
            )
        time.sleep(2)


def _legacy_rootfs_require_source_bridge_object_cleanup_state(
    *,
    resource: Mapping[str, Any],
    binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    label: str,
) -> None:
    _immutable_child_require_live_uid(
        resource,
        expected_uid=str(binding.get("uid") or ""),
        label=label,
    )
    owners = _validated_resource_owner_references(resource, label=label)
    if not owners:
        return
    controller = _immutable_child_controller_owner(resource, label=label)
    if (
        str(binding.get("target_adopted_at") or "").strip()
        and _controller_owner_reference_matches_binding(_mapping(controller), target_binding)
        and len(owners) == 1
    ):
        return
    raise SoperatorMigrationPhasePending(
        f"{label} has foreign or uncheckpointed ownership after source Orphan deletion."
    )


def _legacy_rootfs_target_stage_restored_cycle_is_exact(
    *,
    stage: Mapping[str, Any],
    manager_fingerprint: str,
    manager_generation: int,
    desired: int,
    original_replicas: int,
) -> bool:
    return bool(
        desired == original_replicas > 0
        and str(stage.get("manager_paused_at") or "").strip()
        and str(stage.get("manager_restore_intent_at") or "").strip()
        and str(stage.get("manager_restored_at") or "").strip()
        and str(stage.get("config_replace_applied_at") or "").strip()
        and str(_mapping(stage.get("target_writer_refresh")).get("status") or "") == "zero"
        and str(_mapping(stage.get("target_writer_refresh")).get("zero_at") or "").strip()
        and _positive_int(stage.get("manager_pause_generation"), fallback=0)
        == _positive_int(stage.get("manager_restore_from_generation"), fallback=0)
        and manager_generation
        == _positive_int(stage.get("manager_restore_generation"), fallback=0)
        == _positive_int(stage.get("manager_restore_expected_generation"), fallback=0)
        and manager_fingerprint
        == str(stage.get("manager_pause_spec_fingerprint") or "")
        == str(stage.get("manager_restore_spec_fingerprint") or "")
    )


def _legacy_rootfs_target_stage_manager_replicas(
    *,
    stage: dict[str, Any],
    handoff: Mapping[str, Any],
    replicas: int,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None],
    mutation_guard: Callable[[], None] | None,
) -> dict[str, str]:
    manager_binding = _mapping(handoff.get("manager"))
    expected_uid = str(manager_binding.get("uid") or "").strip()
    original_replicas = _positive_int(manager_binding.get("replicas"), fallback=0)
    if not expected_uid or original_replicas <= 0 or replicas not in {0, original_replicas}:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility stage lacks the manager replica contract."
        )
    action = "pause" if replicas == 0 else "restore"
    intent_key = f"manager_{action}_intent_at"
    manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    identity = _immutable_child_require_live_uid(
        manager,
        expected_uid=expected_uid,
        label=f"Soperator manager target-compatibility {action}",
    )
    manager_fingerprint, manager_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=manager,
    )
    desired = _resource_replicas(manager, default=-1)
    allowed = {0, original_replicas}
    if desired not in allowed:
        raise SoperatorMigrationPhasePending(
            "Soperator manager drifted outside the target compatibility transition."
        )
    if not str(stage.get(intent_key) or "").strip():
        if desired == replicas:
            raise SoperatorMigrationPhasePending(
                f"Soperator manager was already at {replicas} replicas without a durable "
                f"target-compatibility {action} intent."
            )
        stage[intent_key] = _utc_now()
        stage[f"manager_{action}_intent_resource_version"] = identity["resourceVersion"]
        stage[f"manager_{action}_patch_resource_version"] = identity["resourceVersion"]
        stage[f"manager_{action}_from_generation"] = manager_generation
        stage[f"manager_{action}_expected_generation"] = manager_generation + 1
        stage[f"manager_{action}_spec_fingerprint"] = manager_fingerprint
        checkpoint_writer()
    if desired != replicas:
        restored_cycle = bool(
            action == "pause"
            and _legacy_rootfs_target_stage_restored_cycle_is_exact(
                stage=stage,
                manager_fingerprint=manager_fingerprint,
                manager_generation=manager_generation,
                desired=desired,
                original_replicas=original_replicas,
            )
        )
        if restored_cycle:
            return identity
        if manager_generation != _positive_int(
            stage.get(f"manager_{action}_from_generation"), fallback=0
        ) or manager_fingerprint != str(stage.get(f"manager_{action}_spec_fingerprint") or ""):
            raise SoperatorMigrationPhasePending(
                f"Soperator manager changed after target-compatibility {action} intent."
            )
        if (
            str(stage.get(f"manager_{action}_patch_resource_version") or "")
            != identity["resourceVersion"]
        ):
            stage[f"manager_{action}_patch_resource_version"] = identity["resourceVersion"]
            stage[f"manager_{action}_patch_rv_refreshed_at"] = _utc_now()
            checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=_IMMUTABLE_CHILD_HANDOFF_MANAGER_RESOURCE,
            replicas=replicas,
            current_replicas=desired,
            resource_version=identity["resourceVersion"],
        )
    converged = _immutable_child_wait_manager_replicas(
        command_runner=command_runner,
        kube_context=kube_context,
        expected_uid=expected_uid,
        replicas=replicas,
    )
    converged_manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    _immutable_child_require_live_uid(
        converged_manager,
        expected_uid=expected_uid,
        label=f"Soperator manager target-compatibility {action} proof",
    )
    converged_fingerprint, converged_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=converged_manager,
    )
    if converged_generation != _positive_int(
        stage.get(f"manager_{action}_expected_generation"), fallback=0
    ) or converged_fingerprint != str(stage.get(f"manager_{action}_spec_fingerprint") or ""):
        raise SoperatorMigrationPhasePending(
            f"Soperator manager target-compatibility {action} crossed an unbounded generation."
        )
    stage[f"manager_{action}_resource_version"] = converged["resourceVersion"]
    stage[f"manager_{action}_generation"] = converged_generation
    stage[f"manager_{action}d_at"] = stage.get(f"manager_{action}d_at") or _utc_now()
    checkpoint_writer()
    return converged


def _legacy_rootfs_released_worker_pod_proof_for_full_target_login(
    *,
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    if str(handoff.get("status") or "") != "target-children-created":
        raise SoperatorMigrationPhasePending(
            "full-target login Jail config requires completed target child creation."
        )
    released: list[dict[str, str]] = []
    for item in _mapping(handoff.get("workloads")).values():
        if (
            not isinstance(item, Mapping)
            or item.get("component") != "nodeset"
            or item.get("kind") != "StatefulSet"
        ):
            continue
        name = str(item.get("name") or "").strip()
        target_uid = str(item.get("target_uid") or "").strip()
        rollover = _mapping(item.get("old_pod_rollover"))
        if (
            not name
            or item.get("status") != "target-bound"
            or not target_uid
            or str(rollover.get("status") or "")
            not in {"old-pods-released", "target-replacements-bound"}
        ):
            raise SoperatorMigrationPhasePending(
                "full-target login Jail config requires every worker StatefulSet handoff "
                "and old-Pod release proof."
            )
        for captured in _sequence_of_mappings(item.get("pods")):
            pod_name = str(captured.get("name") or "").strip()
            old_uid = str(captured.get("uid") or "").strip()
            pod_state = _mapping(rollover.get(pod_name))
            if (
                not pod_name
                or not old_uid
                or not str(pod_state.get("delete_intent_at") or "").strip()
                or not str(pod_state.get("deleted_at") or "").strip()
            ):
                raise SoperatorMigrationPhasePending(
                    f"full-target login Jail config lacks exact old-Pod release for {pod_name}."
                )
            live_pod = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="pod",
                name=pod_name,
                label=f"full-target login Jail worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
            )
            if live_pod is not None:
                live_identity = _immutable_child_exact_identity(
                    live_pod,
                    label=f"full-target login Jail worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
                )
                if live_identity["uid"] == old_uid:
                    raise SoperatorMigrationPhasePending(
                        f"legacy worker Pod {pod_name} remains live before full-target login config."
                    )
                owner = _immutable_child_controller_owner(
                    live_pod,
                    label=f"full-target login Jail worker Pod {_SOPERATOR_NAMESPACE}/{pod_name}",
                )
                if (
                    str(_mapping(owner).get("apiVersion") or "") != "apps.kruise.io/v1beta1"
                    or str(_mapping(owner).get("kind") or "") != "StatefulSet"
                    or str(_mapping(owner).get("name") or "") != name
                    or str(_mapping(owner).get("uid") or "") != target_uid
                ):
                    raise SoperatorMigrationPhasePending(
                        f"replacement worker Pod {pod_name} lacks exact target ownership "
                        "before full-target login config."
                    )
            released.append(
                {
                    "nodeset": name,
                    "pod": pod_name,
                    "old_uid": old_uid,
                    "delete_intent_at": str(pod_state.get("delete_intent_at") or ""),
                    "deleted_at": str(pod_state.get("deleted_at") or ""),
                    "target_statefulset_uid": target_uid,
                }
            )
    if not released:
        raise SoperatorMigrationPhasePending(
            "full-target login Jail config requires at least one released legacy worker Pod."
        )
    released.sort(key=lambda item: (item["nodeset"], item["pod"]))
    return {
        "released_worker_pods": released,
        "released_worker_pods_fingerprint": _fingerprint(released),
    }


def _legacy_rootfs_login_jail_digest(
    *,
    handoff: Mapping[str, Any],
    expected_sha256: str | Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> str:
    backend = _legacy_rootfs_exact_login_backend(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    result = _legacy_rootfs_direct_login_exec(
        backend=backend,
        command_runner=command_runner,
        kube_context=kube_context,
        args=("sha256sum", _SOPERATOR_LEGACY_SLURM_CONF),
        timeout_seconds=60,
    )
    digest = str(result.stdout or "").strip().split(maxsplit=1)[0] if result.returncode == 0 else ""
    allowed = (
        {str(item).strip() for item in expected_sha256 if str(item).strip()}
        if isinstance(expected_sha256, Sequence) and not isinstance(expected_sha256, str)
        else {str(expected_sha256).strip()}
    )
    if digest not in allowed:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs login consumer does not observe an exact checkpointed "
            "slurm.conf digest allowed at this handoff boundary."
        )
    return digest


def _legacy_rootfs_verify_login_complete_jailed_config_payload(
    *,
    handoff: Mapping[str, Any],
    allowed_payloads: Mapping[str, Sequence[tuple[str, str, str]]],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    retirement_state: Mapping[str, Any] | None = None,
    source_resource: Mapping[str, Any] | None = None,
) -> tuple[str, dict[str, Any]]:
    normalized: dict[str, dict[str, str]] = {}
    for label, files in allowed_payloads.items():
        expected = {path: sha256 for _key, path, sha256 in files}
        if not expected or len(expected) != len(files):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs login payload proof has an incomplete allowed file set."
            )
        normalized[str(label)] = expected
    path_sets = {frozenset(payload) for payload in normalized.values()}
    if not normalized or len(path_sets) != 1:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs login payload proof requires complete equal-path file sets."
        )
    backend = _legacy_rootfs_exact_login_backend(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        retirement_state=retirement_state,
        source_resource=source_resource,
    )
    expected_paths = sorted(next(iter(path_sets)))
    result = _legacy_rootfs_direct_login_exec(
        backend=backend,
        command_runner=command_runner,
        kube_context=kube_context,
        args=("sha256sum", *expected_paths),
        timeout_seconds=60,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs exact login backend could not digest the complete Jail payload."
        )
    observed: dict[str, str] = {}
    for line in str(result.stdout or "").splitlines():
        parts = line.split(maxsplit=1)
        digest = parts[0] if parts else ""
        path = parts[1].removeprefix("*").strip() if len(parts) == 2 else ""
        if (
            re.fullmatch(r"[0-9a-f]{64}", digest) is None
            or path not in expected_paths
            or path in observed
        ):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs exact login backend could not digest the complete Jail payload."
            )
        observed[path] = digest
    if set(observed) != set(expected_paths):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs exact login backend could not digest the complete Jail payload."
        )
    matches = sorted(label for label, payload in normalized.items() if payload == observed)
    if not matches:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs zero-writer Jail is mixed or outside every complete allowed payload."
        )
    return matches[0], dict(backend)


def _legacy_rootfs_controller_bridge_recovery_payload(
    *,
    controller_bridge: Mapping[str, Any],
    source_checkpoint: Mapping[str, Any],
    source_safe_digests: Mapping[str, str],
    canonical_files: Sequence[tuple[str, str, str]],
) -> tuple[tuple[str, str, str], ...] | None:
    """Bind an exact controller-recovery slurm.conf to the source-safe Jail files."""

    transition = _mapping(controller_bridge.get("version_transition"))
    jailed_repair = _mapping(transition.get("target_jailed_config"))
    job_recovery = _mapping(transition.get("job_state_recovery"))
    if not jailed_repair and not job_recovery:
        return None
    target_sha = str(transition.get("target_config_sha256") or "").strip()
    source_name = str(source_checkpoint.get("name") or "").strip()
    source_original_sha = str(source_checkpoint.get("original_sha256") or "").strip()
    repair_evidence_sha = str(jailed_repair.get("evidence_sha256") or "").strip()
    jailed_config_contract_valid = (
        jailed_repair.get("schema") == "nebius-cxcli/controller-bridge-jailed-config-v1"
        and jailed_repair.get("state") == "accepted"
        and str(jailed_repair.get("config_key") or "") == "slurm.conf"
        and str(jailed_repair.get("config_map_name") or "") == source_name
        and str(jailed_repair.get("expected_preimage_sha256") or "") == source_original_sha
        and str(jailed_repair.get("target_sha256") or "") == target_sha
        and re.fullmatch(r"[0-9a-f]{64}", repair_evidence_sha) is not None
        and str(jailed_repair.get("intent_at") or "").strip()
        and str(jailed_repair.get("accepted_at") or "").strip()
        and str(jailed_repair.get("pod_name") or "").strip()
        and re.fullmatch(r"[0-9a-f]{64}", target_sha) is not None
        and re.fullmatch(r"[0-9a-f]{64}", source_original_sha) is not None
    )
    explicit_job_recovery_valid = bool(
        job_recovery.get("schema") == "nebius-cxcli/controller-bridge-job-state-recovery-v1"
        and job_recovery.get("state") == "verified"
        and str(job_recovery.get("target_config_sha256") or "") == target_sha
        and str(job_recovery.get("recovery_epoch") or "").strip()
        and str(job_recovery.get("job_id") or "").strip()
        and str(job_recovery.get("job_partition") or "").strip()
        and str(job_recovery.get("verified_at") or "").strip()
        and _positive_int(job_recovery.get("verified_ready_replicas"), fallback=0) >= 2
    )
    cold_census = _mapping(transition.get("cold_job_census"))
    cold_jobs = _mapping(cold_census.get("jobs"))
    cold_verification = _mapping(cold_census.get("verification"))
    cold_job_ids = cold_census.get("job_ids")
    verified_cold_census_valid = bool(
        cold_census.get("schema") == _SLURM_COLD_JOB_CENSUS_SCHEMA
        and cold_census.get("status") == "verified"
        and isinstance(cold_job_ids, list)
        and cold_job_ids == sorted(cold_jobs)
        and set(cold_verification) == set(cold_jobs)
        and str(cold_census.get("captured_at") or "").strip()
        and str(cold_census.get("verified_at") or "").strip()
    )
    if verified_cold_census_valid:
        for job_id, raw_record in cold_jobs.items():
            record = _mapping(raw_record)
            observation = _mapping(record.get("observation"))
            evidence = _mapping(cold_verification.get(job_id))
            try:
                _validate_slurm_job_control_observation_payload(
                    observation,
                    job_id=job_id,
                    label="legacy-rootfs controller bridge cold-job census",
                )
            except RuntimeError:
                verified_cold_census_valid = False
                break
            if not str(record.get("partition") or "").strip() or evidence.get("status") not in {
                "preserved",
                "completed",
                "operator-modified",
            }:
                verified_cold_census_valid = False
                break
    if not (
        jailed_config_contract_valid and (explicit_job_recovery_valid or verified_cold_census_valid)
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs controller-bridge recovery payload lacks its exact accepted "
            "Jail repair and verified job-state recovery contract."
        )
    recovery_files: list[tuple[str, str, str]] = []
    for key, path, _sha256 in canonical_files:
        digest = (
            target_sha
            if path == _SOPERATOR_LEGACY_SLURM_CONF
            else str(source_safe_digests.get(path) or "")
        )
        if re.fullmatch(r"[0-9a-f]{64}", digest) is None:
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs controller-bridge recovery payload has an incomplete "
                "source-safe file contract."
            )
        recovery_files.append((key, path, digest))
    if not any(path == _SOPERATOR_LEGACY_SLURM_CONF for _key, path, _sha in recovery_files):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs controller-bridge recovery payload lacks slurm.conf."
        )
    return tuple(recovery_files)


def _legacy_rootfs_require_ready_login_backend_pod(
    *,
    pod: Mapping[str, Any],
    binding: Mapping[str, Any],
    require_selector: bool = True,
) -> None:
    identity = _immutable_child_require_live_uid(
        pod,
        expected_uid=str(binding.get("uid") or ""),
        label="legacy-rootfs exact login backend Pod",
    )
    owner = _immutable_child_controller_owner(
        pod,
        label="legacy-rootfs exact login backend Pod",
    )
    labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
    expected_selector = _mapping(binding.get("pod_selector"))
    conditions = {
        str(condition.get("type") or ""): str(condition.get("status") or "")
        for condition in _sequence_of_mappings(_mapping(pod.get("status")).get("conditions"))
    }
    if (
        identity["name"] != str(binding.get("name") or "")
        or str(_mapping(owner).get("apiVersion") or "")
        != str(binding.get("workload_api_version") or "")
        or str(_mapping(owner).get("kind") or "") != str(binding.get("workload_kind") or "")
        or str(_mapping(owner).get("name") or "") != str(binding.get("workload_name") or "")
        or str(_mapping(owner).get("uid") or "") != str(binding.get("workload_uid") or "")
        or (
            require_selector
            and (
                not expected_selector
                or any(
                    str(labels.get(key) or "") != str(value)
                    for key, value in expected_selector.items()
                )
            )
        )
        or _mapping(pod.get("metadata")).get("deletionTimestamp")
        or str(_mapping(pod.get("status")).get("phase") or "") != "Running"
        or conditions.get("Ready") != "True"
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs login proof Pod is not the exact Ready workload backend."
        )


def _legacy_rootfs_exact_login_backend(
    *,
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    retirement_state: Mapping[str, Any] | None = None,
    source_resource: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    source_login_items = [
        item
        for item in _mapping(handoff.get("workloads")).values()
        if isinstance(item, Mapping)
        and item.get("component") == "login"
        and item.get("kind") == "StatefulSet"
    ]
    if len(source_login_items) > 1:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs bridge has multiple captured source login workloads."
        )
    if len(source_login_items) == 1:
        item = source_login_items[0]
        resource_type = str(item.get("resource_type") or "statefulsets.apps.kruise.io")
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                ",".join(
                    (
                        resource_type,
                        "pods",
                        "services",
                        "endpointslices.discovery.k8s.io",
                    )
                ),
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=70,
            check=False,
        )
        if result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs exact login backend snapshot failed; API output was redacted."
            )
        try:
            snapshot = json.loads(result.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs exact login backend snapshot returned invalid JSON."
            ) from exc
        raw_items = _mapping(snapshot).get("items")
        if not isinstance(raw_items, Sequence) or isinstance(raw_items, (str, bytes, bytearray)):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs exact login backend snapshot is incomplete."
            )
        snapshot_items = tuple(
            dict(resource) for resource in raw_items if isinstance(resource, Mapping)
        )
        workload = next(
            (
                resource
                for resource in snapshot_items
                if str(resource.get("apiVersion") or "") == str(item.get("api_version") or "")
                and str(resource.get("kind") or "") == str(item.get("kind") or "")
                and str(_mapping(resource.get("metadata")).get("name") or "")
                == str(item.get("name") or "")
            ),
            None,
        )
        source_workload_live = False
        target_workload_live = False
        if workload is not None:
            live_identity = _immutable_child_exact_identity(
                workload,
                label="current login workload during legacy-rootfs proof",
            )
            source_workload_live = live_identity["uid"] == str(item.get("uid") or "")
            target_workload_live = bool(
                live_identity["uid"] == str(item.get("target_uid") or "")
                and str(item.get("status") or "") == "target-bound"
                and str(item.get("target_bound_at") or "").strip()
                and str(handoff.get("status") or "")
                in {"target-children-created", "cleanup-intent", "complete"}
            )
            if not source_workload_live and not target_workload_live:
                raise SoperatorMigrationPhasePending(
                    "current login workload UID is outside the exact source/target handoff journal."
                )
        if source_workload_live:
            source_binding = _legacy_rootfs_bridge_binding(
                _mapping(handoff.get("source")),
                label="source login owner",
            )
            workload_identity = _immutable_child_require_live_uid(
                workload,
                expected_uid=str(item.get("uid") or ""),
                label="captured source login workload",
            )
            if _mapping(workload.get("metadata")).get("deletionTimestamp"):
                raise SoperatorMigrationPhasePending(
                    "captured source login workload is terminating before login proof."
                )
            _legacy_rootfs_bridge_controller_owner(
                workload,
                allowed_bindings={"source": source_binding},
                label="captured source login workload",
                retirement_state=retirement_state,
                source_resource=source_resource,
            )
            bridge = _mapping(handoff.get("login_bridge"))
            bridge_status = str(bridge.get("status") or "").strip()
            expected_token = (
                "handoff-" + hashlib.sha256(source_binding["uid"].encode()).hexdigest()[:16]
            )
            if (
                bridge_status != "token-selector-ready"
                or str(bridge.get("token") or "").strip() != expected_token
            ):
                raise SoperatorMigrationPhasePending(
                    "legacy-rootfs source login proof lacks the exact durable token-selector bridge."
                )
            expected_selector = {_IMMUTABLE_CHILD_HANDOFF_LABEL: expected_token}
            pods_by_name = {
                str(_mapping(resource.get("metadata")).get("name") or ""): resource
                for resource in snapshot_items
                if str(resource.get("kind") or "") == "Pod"
            }
            services_by_name = {
                str(_mapping(resource.get("metadata")).get("name") or ""): resource
                for resource in snapshot_items
                if str(resource.get("kind") or "") == "Service"
            }
            endpoint_slices = tuple(
                resource
                for resource in snapshot_items
                if str(resource.get("kind") or "") == "EndpointSlice"
            )
            candidates: dict[str, dict[str, Any]] = {}
            for captured in _sequence_of_mappings(item.get("pods")):
                pod = _mapping(pods_by_name.get(str(captured.get("name") or "")))
                if not _mapping(pod.get("metadata")):
                    continue
                binding = {
                    "name": str(captured.get("name") or ""),
                    "uid": str(captured.get("uid") or ""),
                    "workload_api_version": str(item.get("api_version") or ""),
                    "workload_kind": str(item.get("kind") or ""),
                    "workload_name": workload_identity["name"],
                    "workload_uid": workload_identity["uid"],
                    "pod_selector": expected_selector,
                }
                labels = _mapping(_mapping(pod.get("metadata")).get("labels"))
                handoff_label = str(labels.get(_IMMUTABLE_CHILD_HANDOFF_LABEL) or "").strip()
                if not handoff_label:
                    try:
                        _legacy_rootfs_require_ready_login_backend_pod(
                            pod=pod,
                            binding=binding,
                            require_selector=False,
                        )
                    except SoperatorMigrationPhasePending:
                        if _immutable_child_pod_ready(pod):
                            raise
                    continue
                try:
                    _legacy_rootfs_require_ready_login_backend_pod(
                        pod=pod,
                        binding=binding,
                    )
                except SoperatorMigrationPhasePending:
                    if _immutable_child_pod_ready(pod):
                        raise
                    continue
                candidates[binding["uid"]] = binding
            if not candidates:
                raise SoperatorMigrationPhasePending(
                    "legacy-rootfs bridge lacks an exact Ready captured source login Pod."
                )
            endpoint_uids: set[str] = set()
            for service_binding in _sequence_of_mappings(handoff.get("source_login_services")):
                service = _mapping(services_by_name.get(str(service_binding.get("name") or "")))
                _immutable_child_require_live_uid(
                    service,
                    expected_uid=str(service_binding.get("uid") or ""),
                    label="captured source login Service",
                )
                _legacy_rootfs_bridge_controller_owner(
                    service,
                    allowed_bindings={"source": source_binding},
                    label="captured source login Service",
                    retirement_state=retirement_state,
                    source_resource=source_resource,
                )
                if _mapping(_mapping(service.get("spec")).get("selector")) != expected_selector:
                    raise SoperatorMigrationPhasePending(
                        "captured source login Service is not on the checkpointed token selector."
                    )
                for endpoint_slice in endpoint_slices:
                    if str(
                        _mapping(_mapping(endpoint_slice.get("metadata")).get("labels")).get(
                            "kubernetes.io/service-name"
                        )
                        or ""
                    ) != str(service_binding.get("name") or ""):
                        continue
                    slice_owner = _immutable_child_controller_owner(
                        endpoint_slice,
                        label=f"captured source login EndpointSlice for {service_binding.get('name')}",
                    )
                    if (
                        str(_mapping(slice_owner).get("apiVersion") or "") != "v1"
                        or str(_mapping(slice_owner).get("kind") or "") != "Service"
                        or str(_mapping(slice_owner).get("name") or "")
                        != str(service_binding.get("name") or "")
                        or str(_mapping(slice_owner).get("uid") or "")
                        != str(service_binding.get("uid") or "")
                    ):
                        raise SoperatorMigrationPhasePending(
                            "captured source login EndpointSlice is not controlled by the "
                            "exact retained Service."
                        )
                    for endpoint in _sequence_of_mappings(endpoint_slice.get("endpoints")):
                        target_ref = _mapping(endpoint.get("targetRef"))
                        uid = str(target_ref.get("uid") or "").strip()
                        if (
                            _mapping(endpoint.get("conditions")).get("ready") is True
                            and str(target_ref.get("kind") or "").lower() == "pod"
                            and uid in candidates
                            and str(target_ref.get("namespace") or _SOPERATOR_NAMESPACE)
                            == _SOPERATOR_NAMESPACE
                            and str(target_ref.get("name") or "")
                            == str(_mapping(candidates.get(uid)).get("name") or "")
                        ):
                            endpoint_uids.add(uid)
            exact = [candidates[uid] for uid in sorted(endpoint_uids)]
            if not exact:
                raise SoperatorMigrationPhasePending(
                    "captured source login Service lacks an exact Ready backend endpoint."
                )
            return exact[0]
        if target_workload_live:
            target_binding = _mapping(handoff.get("target"))
            _legacy_rootfs_bridge_controller_owner(
                _mapping(workload),
                allowed_bindings={
                    "target": _legacy_rootfs_bridge_binding(
                        target_binding,
                        label="target login owner",
                    )
                },
                label="target login workload during legacy-rootfs proof",
            )
            selector = _mapping(_mapping(_mapping(workload).get("spec")).get("selector")).get(
                "matchLabels"
            )
            if _mapping(selector) != _mapping(item.get("target_selector")) or _mapping(
                _mapping(workload).get("metadata")
            ).get("deletionTimestamp"):
                raise SoperatorMigrationPhasePending(
                    "target login workload drifted from its exact immutable-child binding."
                )
    target_binding = _mapping(handoff.get("target"))
    pod_name, evidence = _accounting_handoff_exact_target_login_state(
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    return {
        "name": pod_name,
        "uid": str(evidence.get("selected_pod_uid") or ""),
        "workload_api_version": "apps.kruise.io/v1beta1",
        "workload_kind": "StatefulSet",
        "workload_name": "login",
        "workload_uid": str(evidence.get("login_workload_uid") or ""),
        "pod_selector": _immutable_child_target_selector(
            target_binding=target_binding,
            component="login",
        ),
    }


def _legacy_rootfs_direct_login_exec(
    *,
    backend: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    args: Sequence[str],
    timeout_seconds: int,
) -> SoperatorMigrationCommandResult:
    pod_name = str(backend.get("name") or "").strip()
    if not pod_name:
        return SoperatorMigrationCommandResult(tuple(args), 1, "", "login pod not found")
    pod = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pod",
        name=pod_name,
    )
    _legacy_rootfs_require_ready_login_backend_pod(
        pod=pod,
        binding=backend,
    )
    result = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        args=args,
        timeout_seconds=timeout_seconds,
        pod_name=pod_name,
    )
    live_pod = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pod",
        name=pod_name,
    )
    _legacy_rootfs_require_ready_login_backend_pod(
        pod=live_pod,
        binding=backend,
    )
    return result


def _legacy_rootfs_bridge_legacy_slurm_health(
    *,
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    retirement_state: Mapping[str, Any] | None = None,
    source_resource: Mapping[str, Any] | None = None,
) -> None:
    backend = _legacy_rootfs_exact_login_backend(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        retirement_state=retirement_state,
        source_resource=source_resource,
    )
    controller = _legacy_rootfs_direct_login_exec(
        backend=backend,
        command_runner=command_runner,
        kube_context=kube_context,
        args=_slurm_cli_with_legacy_conf(("scontrol", "ping")),
        timeout_seconds=60,
    )
    if controller.returncode != 0 or re.search(r"\bis\s+UP\b", controller.stdout or "") is None:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs canonical bridge could not prove the legacy controller is UP."
        )
    queue = _legacy_rootfs_direct_login_exec(
        backend=backend,
        command_runner=command_runner,
        kube_context=kube_context,
        args=_slurm_cli_with_legacy_conf(("squeue", "--noheader", "--format=%A")),
        timeout_seconds=60,
    )
    if queue.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs canonical bridge could not query the live Slurm job queue."
        )


def _revalidate_legacy_rootfs_source_sconfig_fence(
    *,
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    source_item = _legacy_rootfs_sconfig_workload(handoff)
    for binding in _sequence_of_mappings(source_item.get("replica_sets")):
        name = str(binding.get("name") or "").strip()
        uid = str(binding.get("uid") or "").strip()
        live = _immutable_child_optional_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="replicaset.apps",
            name=name,
            label=f"captured source SConfig ReplicaSet {name} active-fence revalidation",
        )
        if live is None:
            cleanup = _mapping(
                _mapping(source_item.get("old_dependent_cleanup")).get(f"replicaset.apps/{name}")
            )
            if (
                str(cleanup.get("uid") or "") != uid
                or not str(cleanup.get("delete_intent_at") or "").strip()
                or not str(cleanup.get("deleted_at") or "").strip()
            ):
                raise SoperatorMigrationPhasePending(
                    f"captured source SConfig ReplicaSet {name} disappeared without cleanup proof."
                )
            continue
        _immutable_child_require_live_uid(
            live,
            expected_uid=uid,
            label=f"captured source SConfig ReplicaSet {name} active-fence revalidation",
        )
        status = _mapping(live.get("status"))
        if (
            _resource_replicas(live, default=-1) != 0
            or _non_negative_int(status.get("replicas"), fallback=0) != 0
            or _non_negative_int(status.get("readyReplicas"), fallback=0) != 0
            or _non_negative_int(status.get("availableReplicas"), fallback=0) != 0
        ):
            raise SoperatorMigrationPhasePending(
                f"captured source SConfig ReplicaSet {name} escaped its zero fence."
            )
    _legacy_rootfs_wait_source_sconfig_pods_absent(
        item=source_item,
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=0,
    )


def _legacy_rootfs_accounting_restore_successor_is_exact(
    *,
    target_resource: Mapping[str, Any],
    target_identity: Mapping[str, str],
    rebind: Mapping[str, Any],
    accounting_handoff: Mapping[str, Any],
) -> bool:
    """Accept only the exact generation created by restoring the fenced writer."""

    gate = _mapping(accounting_handoff.get("target_writer_gate"))
    command_fence = _mapping(accounting_handoff.get("target_writer_command_fence"))
    rebind_generation = _positive_int(rebind.get("target_generation"), fallback=0)
    generation = _positive_int(
        _mapping(target_resource.get("metadata")).get("generation"), fallback=0
    )
    enabled_resource_version = str(gate.get("enabled_resource_version") or "").strip()
    if (
        accounting_handoff.get("status") != "verified"
        or gate.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or gate.get("status") != "enabled"
        or command_fence.get("schema") != _ACCOUNTING_HANDOFF_WRITER_COMMAND_FENCE_SCHEMA
        or command_fence.get("status") != "restored"
        or _mapping(gate.get("binding")).get("uid") != target_identity.get("uid")
        or _mapping(command_fence.get("binding")).get("uid") != target_identity.get("uid")
        or not enabled_resource_version
        or command_fence.get("restored_resource_version") != enabled_resource_version
        or generation != rebind_generation + 1
    ):
        return False
    accounting = _mapping(
        _mapping(_mapping(target_resource.get("spec")).get("slurmNodes")).get("accounting")
    )
    if accounting.get("enabled") is not True:
        return False
    try:
        if not _accounting_handoff_writer_config_matches_identity(
            _accounting_handoff_writer_command_config(target_resource),
            _accounting_handoff_validated_writer_config_identity(
                command_fence.get("original_writer_identity"),
                label="restored target",
            ),
        ):
            return False
    except SoperatorMigrationPhasePending:
        return False
    normalized = copy.deepcopy(to_plain_data(target_resource))
    normalized_slurmdbd = _mapping(
        _mapping(
            _mapping(_mapping(normalized.get("spec")).get("slurmNodes")).get("accounting")
        ).get("slurmdbd")
    )
    if not isinstance(normalized_slurmdbd, dict):
        return False
    normalized_slurmdbd["command"] = list(_ACCOUNTING_HANDOFF_WRITER_FENCE_COMMAND)
    normalized_slurmdbd["args"] = list(_ACCOUNTING_HANDOFF_WRITER_FENCE_ARGS)
    return _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(normalized) == str(
        rebind.get("target_jail_boundary_fingerprint") or ""
    )


def _revalidate_legacy_rootfs_target_cr_fence(
    *,
    state: Mapping[str, Any],
    stage: Mapping[str, Any],
    handoff: Mapping[str, Any],
    accounting_handoff: Mapping[str, Any] | None = None,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    target_resource, target_identity = _legacy_rootfs_target_slurmcluster(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    fence = _mapping(state.get("writer_fence"))
    if _sconfigcontroller_replicas(target_resource) != 0 or target_identity["uid"] != str(
        fence.get("target_uid") or ""
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility lost its exact target size-zero fence."
        )
    generation = _legacy_rootfs_positive_generation(
        target_resource,
        label="target SlurmCluster active compatibility fence",
    )
    fence_fingerprint = _legacy_rootfs_slurmcluster_fence_fingerprint(target_resource)
    jail_boundary_fingerprint = _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(
        target_resource
    )
    login_jail_submounts_fingerprint = _legacy_rootfs_login_jail_submounts_fingerprint(
        target_resource
    )
    intents = _mapping(stage.get("jail_boundary_intents"))
    rebinds = _mapping(stage.get("jail_boundary_rebinds"))
    boundary_ids = set(intents) | set(rebinds)
    if not boundary_ids:
        if (
            generation != _positive_int(fence.get("target_size_expected_generation"), fallback=0)
            or fence_fingerprint != str(fence.get("target_spec_fingerprint") or "")
            or jail_boundary_fingerprint != str(fence.get("target_jail_boundary_fingerprint") or "")
            or login_jail_submounts_fingerprint
            != str(fence.get("target_login_jail_submounts_fingerprint") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster drifted outside its pre-switch compatibility fence."
            )
        return
    if boundary_ids != {"active-slot-switch"}:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility has an unsupported Jail-boundary set."
        )
    intent = _mapping(intents.get("active-slot-switch"))
    rebind = _mapping(rebinds.get("active-slot-switch"))
    if not intent:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility lacks its durable Jail-boundary intent."
        )
    if rebind:
        exact_rebind = bool(
            target_identity["uid"] == str(rebind.get("target_uid") or "")
            and generation == _positive_int(rebind.get("target_generation"), fallback=0)
            and jail_boundary_fingerprint
            == str(rebind.get("target_jail_boundary_fingerprint") or "")
            and login_jail_submounts_fingerprint
            == str(rebind.get("login_jail_submounts_fingerprint") or "")
        )
        accounting_restore_successor = (
            not exact_rebind
            and _legacy_rootfs_accounting_restore_successor_is_exact(
                target_resource=target_resource,
                target_identity=target_identity,
                rebind=rebind,
                accounting_handoff=_mapping(accounting_handoff),
            )
        )
        if not exact_rebind and not accounting_restore_successor:
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster drifted after its exact Jail-boundary rebind."
            )
        expected_pvc = str(rebind.get("rootfs_pvc") or "")
        expected_volume_source = str(rebind.get("rootfs_volume_source") or "")
        expected_maintenance = str(rebind.get("maintenance") or "")
    else:
        pre_switch = bool(
            generation == _positive_int(intent.get("target_from_generation"), fallback=0)
            and fence_fingerprint == str(fence.get("target_spec_fingerprint") or "")
            and jail_boundary_fingerprint
            == str(fence.get("target_jail_boundary_fingerprint") or "")
            and login_jail_submounts_fingerprint
            == str(fence.get("target_login_jail_submounts_fingerprint") or "")
        )
        if pre_switch:
            return
        if (
            target_identity["uid"] != str(intent.get("target_uid") or "")
            or generation != _positive_int(intent.get("target_expected_generation"), fallback=0)
            or jail_boundary_fingerprint
            != str(intent.get("target_jail_boundary_fingerprint") or "")
            or login_jail_submounts_fingerprint
            != str(intent.get("expected_login_jail_submounts_fingerprint") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster crossed an unbounded Jail-boundary generation."
            )
        expected_pvc = str(intent.get("expected_rootfs_pvc") or "")
        expected_volume_source = str(intent.get("expected_rootfs_volume_source") or "")
        expected_maintenance = str(intent.get("expected_maintenance") or "")
    target_spec = _mapping(target_resource.get("spec"))
    slurm_nodes = _mapping(target_spec.get("slurmNodes"))
    observed_volume_sources = {
        str(
            _mapping(_mapping(_mapping(slurm_nodes.get(role)).get("volumes")).get("jail")).get(
                "volumeSourceName"
            )
            or ""
        ).strip()
        for role in ("controller", "login")
    }
    if (
        not expected_pvc
        or _pvc_volume_source_claim_name(target_spec, source_name="jail") != expected_pvc
        or observed_volume_sources != {expected_volume_source}
        or str(target_spec.get("maintenance") or "none").strip() != expected_maintenance
    ):
        raise SoperatorMigrationPhasePending(
            "target SlurmCluster no longer matches its exact Jail-boundary alias contract."
        )


def _revalidate_legacy_rootfs_target_compatibility_active(
    *,
    phase: dict[str, Any],
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    require_login_digest: bool = True,
    checkpoint_writer: Callable[[], None] | None = None,
) -> None:
    state = _legacy_rootfs_slurm_config_bridge_state(phase)
    if not _legacy_rootfs_target_compatibility_is_active(phase):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility active checkpoint is incomplete."
        )
    _legacy_rootfs_bridge_require_source_absent(
        source_binding=_legacy_rootfs_bridge_binding(
            _mapping(handoff.get("source")), label="source SlurmCluster"
        ),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    stage = _mapping(state.get("target_compatibility_stage"))
    expected_deployment_fingerprint = str(stage.get("deployment_spec_fingerprint") or "")
    if not expected_deployment_fingerprint:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility lacks the Deployment spec fingerprint."
        )
    manager_binding = _mapping(handoff.get("manager"))
    manager_uid = str(manager_binding.get("uid") or "").strip()
    manager_replicas = _positive_int(manager_binding.get("replicas"), fallback=0)
    if not manager_uid or manager_replicas <= 0:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility lacks the manager identity contract."
        )
    _immutable_child_wait_manager_replicas(
        command_runner=command_runner,
        kube_context=kube_context,
        expected_uid=manager_uid,
        replicas=manager_replicas,
        timeout_seconds=0,
    )
    manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    _immutable_child_require_live_uid(
        manager,
        expected_uid=manager_uid,
        label="Soperator manager active target-compatibility revalidation",
    )
    _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=manager,
    )
    config_binding = _mapping(state.get("configmap"))
    target_config_map = _legacy_rootfs_bridge_optional_resource(
        resource_type="configmap",
        name=str(config_binding.get("name") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if target_config_map is None:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap disappeared from the active compatibility fence."
        )
    _immutable_child_require_live_uid(
        target_config_map,
        expected_uid=str(stage.get("configmap_uid") or ""),
        label="target Slurm ConfigMap active compatibility fence",
    )
    _legacy_rootfs_bridge_controller_owner(
        target_config_map,
        allowed_bindings={
            "target": _legacy_rootfs_bridge_binding(
                _mapping(handoff.get("target")), label="target SlurmCluster"
            )
        },
        label="target Slurm ConfigMap active compatibility fence",
    )
    config_state, _compatible_config = _legacy_rootfs_configmap_compatible_transform(
        config_map=target_config_map,
        stage=stage,
    )
    active_config_variant = str(stage.get("active_config_variant") or "compatible")
    live_config_sha = hashlib.sha256(
        _legacy_rootfs_bridge_config_text(target_config_map).encode("utf-8")
    ).hexdigest()
    live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(target_config_map)
    if active_config_variant == "post-restore-full-target":
        post_restore = _mapping(stage.get("post_restore_full_target"))
        if (
            not post_restore
            or live_config_sha != str(stage.get("full_target_sha256") or "")
            or live_data_fingerprint != str(stage.get("full_target_data_fingerprint") or "")
            or str(post_restore.get("configmap_uid") or "") != str(stage.get("configmap_uid") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "post-restore full target Slurm ConfigMap drifted after activation."
            )
    elif (
        active_config_variant != "compatible"
        or config_state != "compatible"
        or live_config_sha != str(stage.get("compatible_sha256") or "")
        or live_data_fingerprint != str(stage.get("compatible_data_fingerprint") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap drifted from its active compatibility variant."
        )
    _legacy_rootfs_target_jailed_config_files(
        state=state,
        stage=stage,
        handoff=handoff,
        config_map=target_config_map,
        command_runner=command_runner,
        kube_context=kube_context,
        initialize=False,
    )
    deployment, identity, service_account_name, service_account_identity = (
        _legacy_rootfs_target_sconfig_binding(
            state=state,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
    )
    if (
        identity["uid"] != str(stage.get("deployment_uid") or "")
        or service_account_name != str(stage.get("service_account_name") or "")
        or service_account_identity["uid"] != str(stage.get("service_account_uid") or "")
        or _resource_replicas(deployment, default=-1) != 0
        or _legacy_rootfs_scalable_spec_fingerprint(
            deployment,
            label="target SConfig Deployment active-fence revalidation",
        )
        != str(stage.get("deployment_spec_fingerprint") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility binding drifted after activation."
        )
    _legacy_rootfs_wait_target_sconfig_zero(
        deployment_uid=identity["uid"],
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=0,
    )
    _revalidate_legacy_rootfs_target_cr_fence(
        state=state,
        stage=stage,
        handoff=handoff,
        accounting_handoff=_mapping(phase.get("accounting_handoff")),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    _revalidate_legacy_rootfs_source_sconfig_fence(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if require_login_digest:
        compatible_sha = str(stage.get("compatible_sha256") or "")
        full_target_sha = str(stage.get("full_target_sha256") or "")
        transition = _mapping(stage.get("login_full_target_transition"))
        can_classify_full_target = bool(
            active_config_variant == "post-restore-full-target"
            and full_target_sha
            and str(
                _mapping(
                    _mapping(stage.get("jail_boundary_writer_refreshes")).get("active-slot-switch")
                ).get("status")
                or ""
            )
            == "verified"
        )
        allowed_digests = [compatible_sha]
        if transition or can_classify_full_target:
            allowed_digests.append(full_target_sha)
        observed_digest = _legacy_rootfs_login_jail_digest(
            handoff=handoff,
            expected_sha256=allowed_digests,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if observed_digest == compatible_sha:
            if transition or str(stage.get("active_login_config_variant") or "") not in {
                "",
                "compatible",
            }:
                raise SoperatorMigrationPhasePending(
                    "legacy-rootfs login Jail config regressed after the full-target transition."
                )
        elif observed_digest == full_target_sha:
            if not can_classify_full_target:
                raise SoperatorMigrationPhasePending(
                    "legacy-rootfs login Jail reached full-target config outside the exact "
                    "post-restore worker-release boundary."
                )
            released = _legacy_rootfs_released_worker_pod_proof_for_full_target_login(
                handoff=handoff,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            proposed = {
                "schema": _LEGACY_ROOTFS_LOGIN_FULL_TARGET_TRANSITION_SCHEMA,
                "status": "verified",
                "configmap_uid": str(stage.get("configmap_uid") or ""),
                "full_target_sha256": full_target_sha,
                "released_worker_pods_fingerprint": released["released_worker_pods_fingerprint"],
            }
            if transition:
                if any(transition.get(key) != value for key, value in proposed.items()):
                    raise SoperatorMigrationPhasePending(
                        "legacy-rootfs login full-target transition proof drifted."
                    )
            else:
                if checkpoint_writer is None or not isinstance(stage, dict):
                    raise SoperatorMigrationPhasePending(
                        "legacy-rootfs login full-target transition requires a durable "
                        "checkpoint before continuing."
                    )
                stage["login_full_target_transition"] = {
                    **proposed,
                    "released_worker_pods": released["released_worker_pods"],
                    "verified_at": _utc_now(),
                }
                stage["active_login_config_variant"] = "post-restore-full-target"
                checkpoint_writer()


def _wait_for_legacy_rootfs_post_restore_full_target_config(
    *,
    state: Mapping[str, Any],
    stage: Mapping[str, Any],
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    timeout_seconds: int,
    poll_interval_seconds: float = 1.0,
) -> None:
    """Wait only for the exact manager-restored ConfigMap after a compatible writer pulse."""

    if str(stage.get("active_config_variant") or "compatible") != ("post-restore-full-target"):
        return
    config_binding = _mapping(state.get("configmap"))
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        config_map = _legacy_rootfs_bridge_optional_resource(
            resource_type="configmap",
            name=str(config_binding.get("name") or ""),
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if config_map is None:
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap disappeared during post-restore reconciliation."
            )
        _immutable_child_require_live_uid(
            config_map,
            expected_uid=str(stage.get("configmap_uid") or ""),
            label="target Slurm ConfigMap post-restore reconciliation",
        )
        _legacy_rootfs_bridge_controller_owner(
            config_map,
            allowed_bindings={
                "target": _legacy_rootfs_bridge_binding(
                    _mapping(handoff.get("target")), label="target SlurmCluster"
                )
            },
            label="target Slurm ConfigMap post-restore reconciliation",
        )
        live_sha = hashlib.sha256(
            _legacy_rootfs_bridge_config_text(config_map).encode("utf-8")
        ).hexdigest()
        live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(config_map)
        if live_sha == str(stage.get("full_target_sha256") or "") and live_data_fingerprint == str(
            stage.get("full_target_data_fingerprint") or ""
        ):
            return
        compatible_pending = bool(
            live_sha == str(stage.get("compatible_sha256") or "")
            and live_data_fingerprint == str(stage.get("compatible_data_fingerprint") or "")
        )
        if not compatible_pending:
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap drifted outside the exact compatible/full-target "
                "post-restore transition."
            )
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "Soperator manager has not reconciled the exact full-target Slurm ConfigMap "
                "after the compatibility writer pulse."
            )
        time.sleep(max(poll_interval_seconds, 0.0))


def _require_legacy_rootfs_boundary_pulse_deployment_state(
    *,
    rebind: Mapping[str, Any],
    refresh: Mapping[str, Any],
    generation: int,
    replicas: int,
    spec_fingerprint: str,
    stage_spec_fingerprint: str,
) -> None:
    base_generation = _positive_int(rebind.get("deployment_generation"), fallback=0)
    refresh_status = str(refresh.get("status") or "pending")
    allowed_states = {
        "pending": {(base_generation, 0)},
        "scale-up-intent": {
            (base_generation, 0),
            (base_generation + 1, 1),
        },
        "writer-ready": {(base_generation + 1, 1)},
        "scale-down-intent": {
            (base_generation + 1, 1),
            (base_generation + 2, 0),
        },
        "zero": {(base_generation + 2, 0)},
        "verified": {(base_generation + 2, 0)},
    }
    if (
        base_generation <= 0
        or refresh_status not in allowed_states
        or (generation, replicas) not in allowed_states[refresh_status]
        or spec_fingerprint != str(rebind.get("deployment_spec_fingerprint") or "")
        or spec_fingerprint != stage_spec_fingerprint
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary writer pulse resumed outside its exact "
            "checkpointed Deployment state."
        )


def _legacy_rootfs_missing_boundary_intent_recovery_is_exact(
    *,
    consumer_switch_applied_at: str,
    state: Mapping[str, Any],
    stage: Mapping[str, Any],
    fence: Mapping[str, Any],
    boundary_id: str,
    target_resource: Mapping[str, Any],
    target_identity: Mapping[str, str],
    target_generation: int,
    deployment: Mapping[str, Any],
    deployment_identity: Mapping[str, str],
    deployment_jail_boundary_fingerprint: str,
) -> bool:
    """Recognize an already-applied active-slot boundary with complete exact evidence."""

    return bool(
        boundary_id == "active-slot-switch"
        and consumer_switch_applied_at.strip()
        and state.get("status") == "target-compatibility-active"
        and str(stage.get("stable_at") or "").strip()
        and stage.get("active_config_variant") in {"compatible", "post-restore-full-target"}
        and stage.get("active_login_config_variant") == "compatible"
        and fence.get("status") == "prepared"
        and str(fence.get("target_uid") or "") == target_identity.get("uid")
        and _positive_int(fence.get("target_size_applied_generation"), fallback=0)
        == target_generation
        and str(fence.get("target_spec_fingerprint") or "")
        == _legacy_rootfs_slurmcluster_fence_fingerprint(target_resource)
        and str(fence.get("target_jail_boundary_fingerprint") or "")
        == _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
        and str(fence.get("target_login_jail_submounts_fingerprint") or "")
        == _legacy_rootfs_login_jail_submounts_fingerprint(target_resource)
        and str(stage.get("deployment_uid") or "") == deployment_identity.get("uid")
        and str(stage.get("deployment_spec_fingerprint") or "")
        == _legacy_rootfs_scalable_spec_fingerprint(
            deployment,
            label="target SConfig Deployment exact Jail-boundary recovery",
        )
        and str(stage.get("deployment_jail_boundary_fingerprint") or "")
        == deployment_jail_boundary_fingerprint
    )


def _legacy_rootfs_missing_boundary_full_target_recovery_is_exact(
    *,
    stage: Mapping[str, Any],
    manager_fingerprint: str,
    manager_generation: int,
    manager_desired: int,
    manager_replicas: int,
    configmap_uid: str,
    live_config_sha: str,
    live_data_fingerprint: str,
) -> bool:
    """Recognize the exact manager-restored ConfigMap after a missed boundary intent."""

    return bool(
        str(stage.get("active_config_variant") or "compatible") == "compatible"
        and configmap_uid == str(stage.get("configmap_uid") or "")
        and live_config_sha == str(stage.get("full_target_sha256") or "")
        and live_data_fingerprint == str(stage.get("full_target_data_fingerprint") or "")
        and _legacy_rootfs_target_stage_restored_cycle_is_exact(
            stage=stage,
            manager_fingerprint=manager_fingerprint,
            manager_generation=manager_generation,
            desired=manager_desired,
            original_replicas=manager_replicas,
        )
    )


def _rebind_legacy_rootfs_target_compatibility_after_jail_helm(
    *,
    phase: dict[str, Any],
    consumer_switch_applied_at: str,
    boundary_id: str,
    expected_rootfs_pvc: str,
    expected_rootfs_volume_source: str,
    expected_maintenance: str,
    expected_login_jail_submounts_fingerprint: str,
    values: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> None:
    if not _legacy_rootfs_target_compatibility_is_active(phase):
        return
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary SConfig rebind requires durable checkpoint writes."
        )
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", boundary_id):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary SConfig rebind has an invalid checkpoint id."
        )
    state = _legacy_rootfs_slurm_config_bridge_state(phase)
    stage = _mapping(state.get("target_compatibility_stage"))
    handoff = _immutable_child_handoff_state(phase)
    target_resource, target_identity = _legacy_rootfs_target_slurmcluster(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    observed_pvc = _pvc_volume_source_claim_name(
        _mapping(target_resource.get("spec")),
        source_name="jail",
    )
    observed_maintenance = str(
        _mapping(target_resource.get("spec")).get("maintenance") or "none"
    ).strip()
    slurm_nodes = _mapping(_mapping(target_resource.get("spec")).get("slurmNodes"))
    observed_role_volume_sources = {
        role: str(
            _mapping(_mapping(_mapping(slurm_nodes.get(role)).get("volumes")).get("jail")).get(
                "volumeSourceName"
            )
            or ""
        ).strip()
        for role in ("controller", "login")
    }
    if (
        not expected_rootfs_pvc
        or not expected_rootfs_volume_source
        or observed_pvc != expected_rootfs_pvc
        or set(observed_role_volume_sources.values()) != {expected_rootfs_volume_source}
        or observed_maintenance != expected_maintenance
        or not re.fullmatch(r"[0-9a-f]{64}", expected_login_jail_submounts_fingerprint)
        or _legacy_rootfs_login_jail_submounts_fingerprint(target_resource)
        != expected_login_jail_submounts_fingerprint
        or _sconfigcontroller_replicas(target_resource) != 0
        or _slurmcluster_controller_open_metrics_enabled(target_resource) is not False
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary SConfig rebind lacks the exact target alias, "
            "maintenance, size-zero, and OpenMetrics compatibility state."
        )
    fence = state.get("writer_fence")
    if not isinstance(fence, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary SConfig rebind lacks a mutable writer fence."
        )
    recovered_exact_helm_boundary = _legacy_rootfs_rebind_sconfig_fence_after_manager_restore(
        phase=phase,
        handoff=handoff,
        fence=fence,
        values=values,
        target_resource=target_resource,
        target_identity=target_identity,
        live_size=_sconfigcontroller_replicas(target_resource),
        live_generation=_legacy_rootfs_positive_generation(
            target_resource,
            label="target SlurmCluster exact Helm boundary recovery",
        ),
        live_spec_fingerprint=_legacy_rootfs_slurmcluster_fence_fingerprint(target_resource),
        live_jail_boundary_fingerprint=(
            _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
        ),
        live_login_jail_submounts_fingerprint=(
            _legacy_rootfs_login_jail_submounts_fingerprint(target_resource)
        ),
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        allow_active_boundary_recovery=True,
    )
    checkpointed_rebind = _mapping(_mapping(stage.get("jail_boundary_rebinds")).get(boundary_id))
    accounting_restore_successor = (
        boundary_id == "active-slot-switch"
        and bool(checkpointed_rebind)
        and _legacy_rootfs_accounting_restore_successor_is_exact(
            target_resource=target_resource,
            target_identity=target_identity,
            rebind=checkpointed_rebind,
            accounting_handoff=_mapping(phase.get("accounting_handoff")),
        )
    )
    if (
        _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
        != str(fence.get("target_jail_boundary_fingerprint") or "")
        and not accounting_restore_successor
    ):
        raise SoperatorMigrationPhasePending(
            "target SlurmCluster changed outside the authorized Jail alias/maintenance boundary."
        )
    deployment, deployment_identity, _service_account_name, _service_account_identity = (
        _legacy_rootfs_target_sconfig_binding(
            state=state,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
    )
    if not _pod_template_has_jail_rootfs_consumer_mount(
        payload=deployment,
        rootfs_pvc=expected_rootfs_pvc,
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment template has not adopted the checkpointed Jail alias PVC."
        )
    (
        deployment_jail_boundary_fingerprint,
        deployment_jail_volume_name,
        deployment_jail_pvc,
    ) = _legacy_rootfs_sconfig_jail_boundary_contract(deployment)
    if (
        deployment_jail_pvc != expected_rootfs_pvc
        or deployment_jail_boundary_fingerprint
        != str(stage.get("deployment_jail_boundary_fingerprint") or "")
        or deployment_jail_volume_name != str(stage.get("deployment_jail_volume_name") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment changed outside the authorized Jail PVC transition."
        )
    if accounting_restore_successor:
        existing_refresh = _mapping(
            _mapping(stage.get("jail_boundary_writer_refreshes")).get(boundary_id)
        )
        expected_rebind = {
            "target_uid": target_identity["uid"],
            "rootfs_pvc": expected_rootfs_pvc,
            "rootfs_volume_source": expected_rootfs_volume_source,
            "maintenance": expected_maintenance,
            "login_jail_submounts_fingerprint": expected_login_jail_submounts_fingerprint,
            "deployment_uid": deployment_identity["uid"],
            "deployment_spec_fingerprint": _legacy_rootfs_scalable_spec_fingerprint(
                deployment,
                label="target SConfig Deployment restored-accounting successor",
            ),
            "deployment_jail_boundary_fingerprint": deployment_jail_boundary_fingerprint,
        }
        if any(checkpointed_rebind.get(key) != value for key, value in expected_rebind.items()):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs Jail-boundary proof drifted after the exact accounting restore."
            )
        _require_legacy_rootfs_boundary_pulse_deployment_state(
            rebind=checkpointed_rebind,
            refresh=existing_refresh,
            generation=_legacy_rootfs_positive_generation(
                deployment,
                label="target SConfig Deployment restored-accounting successor",
            ),
            replicas=_resource_replicas(deployment, default=-1),
            spec_fingerprint=expected_rebind["deployment_spec_fingerprint"],
            stage_spec_fingerprint=str(stage.get("deployment_spec_fingerprint") or ""),
        )
        _revalidate_legacy_rootfs_source_sconfig_fence(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        return
    target_generation = _legacy_rootfs_positive_generation(
        target_resource,
        label="target SlurmCluster Jail-boundary rebind",
    )
    missing_intent_recovery_exact = _legacy_rootfs_missing_boundary_intent_recovery_is_exact(
        consumer_switch_applied_at=consumer_switch_applied_at,
        state=state,
        stage=stage,
        fence=fence,
        boundary_id=boundary_id,
        target_resource=target_resource,
        target_identity=target_identity,
        target_generation=target_generation,
        deployment=deployment,
        deployment_identity=deployment_identity,
        deployment_jail_boundary_fingerprint=deployment_jail_boundary_fingerprint,
    )
    recover_missing_intent = bool(recovered_exact_helm_boundary or missing_intent_recovery_exact)
    if recover_missing_intent:
        mutable_stage = state.get("target_compatibility_stage")
        if not isinstance(mutable_stage, dict):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs exact Helm boundary recovery lacks a mutable stage."
            )
        recovered_intents = mutable_stage.setdefault("jail_boundary_intents", {})
        if not isinstance(recovered_intents, dict):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs exact Helm boundary recovery intent collection is malformed."
            )
        if boundary_id not in recovered_intents:
            deployment_generation = _legacy_rootfs_positive_generation(
                deployment,
                label="target SConfig Deployment recovered Jail-boundary intent",
            )
            recovered_intents[boundary_id] = {
                "target_uid": target_identity["uid"],
                "target_resource_version": target_identity["resourceVersion"],
                "target_from_generation": target_generation,
                "target_expected_generation": target_generation,
                "target_jail_boundary_fingerprint": (
                    _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
                ),
                "deployment_uid": deployment_identity["uid"],
                "deployment_resource_version": deployment_identity["resourceVersion"],
                "deployment_from_generation": deployment_generation,
                "deployment_expected_generation": deployment_generation,
                "deployment_spec_fingerprint": (
                    _legacy_rootfs_scalable_spec_fingerprint(
                        deployment,
                        label="target SConfig Deployment recovered Jail-boundary intent",
                    )
                ),
                "deployment_jail_boundary_fingerprint": deployment_jail_boundary_fingerprint,
                "expected_rootfs_pvc": expected_rootfs_pvc,
                "expected_rootfs_volume_source": expected_rootfs_volume_source,
                "expected_maintenance": expected_maintenance,
                "expected_login_jail_submounts_fingerprint": (
                    expected_login_jail_submounts_fingerprint
                ),
                "recovered_after_exact_helm_at": _utc_now(),
            }
            checkpoint_writer()
    if missing_intent_recovery_exact:
        config_binding = _mapping(state.get("configmap"))
        target_config_map = _legacy_rootfs_bridge_optional_resource(
            resource_type="configmap",
            name=str(config_binding.get("name") or ""),
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if target_config_map is None:
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap disappeared during exact Jail-boundary recovery."
            )
        config_identity = _immutable_child_require_live_uid(
            target_config_map,
            expected_uid=str(stage.get("configmap_uid") or ""),
            label="target Slurm ConfigMap exact Jail-boundary recovery",
        )
        _legacy_rootfs_bridge_controller_owner(
            target_config_map,
            allowed_bindings={
                "target": _legacy_rootfs_bridge_binding(
                    _mapping(handoff.get("target")), label="target SlurmCluster"
                )
            },
            label="target Slurm ConfigMap exact Jail-boundary recovery",
        )
        manager_binding = _mapping(handoff.get("manager"))
        manager = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name="soperator-manager",
        )
        _immutable_child_require_live_uid(
            manager,
            expected_uid=str(manager_binding.get("uid") or ""),
            label="Soperator manager exact Jail-boundary recovery",
        )
        manager_fingerprint, manager_generation = _immutable_child_require_manager_spec_contract(
            manager_binding=manager_binding,
            manager=manager,
        )
        live_config_sha = hashlib.sha256(
            _legacy_rootfs_bridge_config_text(target_config_map).encode("utf-8")
        ).hexdigest()
        live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(target_config_map)
        if _legacy_rootfs_missing_boundary_full_target_recovery_is_exact(
            stage=stage,
            manager_fingerprint=manager_fingerprint,
            manager_generation=manager_generation,
            manager_desired=_resource_replicas(manager, default=-1),
            manager_replicas=_positive_int(manager_binding.get("replicas"), fallback=0),
            configmap_uid=config_identity["uid"],
            live_config_sha=live_config_sha,
            live_data_fingerprint=live_data_fingerprint,
        ):
            proposed_post_restore = {
                "configmap_uid": config_identity["uid"],
                "configmap_resource_version": config_identity["resourceVersion"],
                "full_target_sha256": live_config_sha,
                "full_target_data_fingerprint": live_data_fingerprint,
                "manager_generation": manager_generation,
                "manager_spec_fingerprint": manager_fingerprint,
            }
            existing_post_restore = stage.get("post_restore_full_target")
            if (
                existing_post_restore is not None
                and _mapping(existing_post_restore) != proposed_post_restore
            ):
                raise SoperatorMigrationPhasePending(
                    "post-restore full target Slurm ConfigMap proof changed during exact "
                    "Jail-boundary recovery."
                )
            mutable_stage = state.get("target_compatibility_stage")
            if not isinstance(mutable_stage, dict):
                raise SoperatorMigrationPhasePending(
                    "legacy-rootfs exact full-target recovery lacks a mutable stage."
                )
            if existing_post_restore is None:
                mutable_stage["post_restore_full_target"] = proposed_post_restore
                mutable_stage["post_restore_full_target_at"] = _utc_now()
            mutable_stage["active_config_variant"] = "post-restore-full-target"
            checkpoint_writer()
    _revalidate_legacy_rootfs_source_sconfig_fence(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    intent = _mapping(_mapping(stage.get("jail_boundary_intents")).get(boundary_id))
    existing_refresh = _mapping(
        _mapping(stage.get("jail_boundary_writer_refreshes")).get(boundary_id)
    )
    deployment_generation = _legacy_rootfs_positive_generation(
        deployment,
        label="target SConfig Deployment Jail-boundary rebind",
    )
    deployment_desired = _resource_replicas(deployment, default=-1)
    deployment_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
        deployment,
        label="target SConfig Deployment Jail-boundary rebind",
    )
    if (
        not intent
        or intent.get("target_uid") != target_identity["uid"]
        or intent.get("deployment_uid") != deployment_identity["uid"]
        or intent.get("expected_rootfs_pvc") != expected_rootfs_pvc
        or intent.get("expected_rootfs_volume_source") != expected_rootfs_volume_source
        or intent.get("expected_maintenance") != expected_maintenance
        or intent.get("expected_login_jail_submounts_fingerprint")
        != expected_login_jail_submounts_fingerprint
        or _positive_int(intent.get("target_expected_generation"), fallback=0) != target_generation
        or intent.get("target_jail_boundary_fingerprint")
        != _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
        or intent.get("deployment_jail_boundary_fingerprint")
        != deployment_jail_boundary_fingerprint
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary rebind is outside its generation-bound Helm intent."
        )
    rebinds = stage.get("jail_boundary_rebinds")
    if rebinds is None:
        rebinds = {}
        if isinstance(state.get("target_compatibility_stage"), dict):
            state["target_compatibility_stage"]["jail_boundary_rebinds"] = rebinds
    if not isinstance(rebinds, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary SConfig rebind collection is malformed."
        )
    rebind = _mapping(rebinds.get(boundary_id))
    proposed = {
        "target_uid": target_identity["uid"],
        "target_resource_version": target_identity["resourceVersion"],
        "target_generation": target_generation,
        "target_jail_boundary_fingerprint": (
            _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
        ),
        "rootfs_pvc": expected_rootfs_pvc,
        "rootfs_volume_source": expected_rootfs_volume_source,
        "maintenance": expected_maintenance,
        "login_jail_submounts_fingerprint": (expected_login_jail_submounts_fingerprint),
        "deployment_uid": deployment_identity["uid"],
        "deployment_resource_version": deployment_identity["resourceVersion"],
        "deployment_generation": deployment_generation,
        "deployment_spec_fingerprint": deployment_fingerprint,
        "deployment_jail_boundary_fingerprint": deployment_jail_boundary_fingerprint,
    }
    immutable_rebind_keys = (
        "target_uid",
        "target_generation",
        "target_jail_boundary_fingerprint",
        "rootfs_pvc",
        "rootfs_volume_source",
        "maintenance",
        "login_jail_submounts_fingerprint",
        "deployment_uid",
        "deployment_spec_fingerprint",
    )
    if rebind:
        if (
            any(rebind.get(key) != proposed[key] for key in immutable_rebind_keys)
            or rebind.get("deployment_jail_boundary_fingerprint")
            != deployment_jail_boundary_fingerprint
        ):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs Jail-boundary SConfig rebind changed after its durable proof."
            )
        _require_legacy_rootfs_boundary_pulse_deployment_state(
            rebind=rebind,
            refresh=existing_refresh,
            generation=deployment_generation,
            replicas=deployment_desired,
            spec_fingerprint=deployment_fingerprint,
            stage_spec_fingerprint=str(stage.get("deployment_spec_fingerprint") or ""),
        )
        if deployment_desired == 0:
            _legacy_rootfs_wait_target_sconfig_zero(
                deployment_uid=deployment_identity["uid"],
                command_runner=command_runner,
                kube_context=kube_context,
                timeout_seconds=0,
            )
    else:
        if (
            deployment_generation
            != _positive_int(intent.get("deployment_expected_generation"), fallback=0)
            or deployment_desired != 0
        ):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs Jail-boundary rebind did not observe the single expected "
                "post-Helm Deployment generation at zero replicas."
            )
        _legacy_rootfs_wait_target_sconfig_zero(
            deployment_uid=deployment_identity["uid"],
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=0,
        )
        trial_phase = copy.deepcopy(to_plain_data(phase))
        trial_stage = _mapping(
            _mapping(trial_phase.get("legacy_rootfs_slurm_config_bridge")).get(
                "target_compatibility_stage"
            )
        )
        if not isinstance(trial_stage, dict):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs Jail-boundary SConfig trial checkpoint is malformed."
            )
        trial_stage["deployment_spec_fingerprint"] = deployment_fingerprint
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=trial_phase,
            handoff=_immutable_child_handoff_state(trial_phase),
            command_runner=command_runner,
            kube_context=kube_context,
            require_login_digest=False,
        )
    mutable_stage = state.get("target_compatibility_stage")
    if not isinstance(mutable_stage, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility stage is not mutable."
        )
    if not rebind:
        mutable_stage["deployment_spec_fingerprint"] = deployment_fingerprint
    mutable_rebinds = mutable_stage.setdefault("jail_boundary_rebinds", {})
    if not isinstance(mutable_rebinds, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility rebind collection is not mutable."
        )
    if not rebind:
        mutable_rebinds[boundary_id] = {
            **proposed,
            "verified_at": _utc_now(),
        }
        checkpoint_writer()
    _pulse_legacy_rootfs_target_writer_for_jail_boundary(
        phase=phase,
        boundary_id=boundary_id,
        expected_rootfs_pvc=expected_rootfs_pvc,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )


def _checkpoint_legacy_rootfs_jail_boundary_intent(
    *,
    phase: dict[str, Any],
    boundary_id: str,
    expected_rootfs_pvc: str,
    expected_rootfs_volume_source: str,
    expected_maintenance: str,
    expected_login_jail_submounts_fingerprint: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if not _legacy_rootfs_target_compatibility_is_active(phase):
        return
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary mutation intent requires durable checkpoint writes."
        )
    state = _legacy_rootfs_slurm_config_bridge_state(phase)
    stage = state.get("target_compatibility_stage")
    if not isinstance(stage, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary mutation intent lacks a mutable compatibility stage."
        )
    handoff = _immutable_child_handoff_state(phase)
    _revalidate_legacy_rootfs_target_compatibility_active(
        phase=phase,
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    target_resource, target_identity = _legacy_rootfs_target_slurmcluster(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    deployment, deployment_identity, _service_account_name, _service_account_identity = (
        _legacy_rootfs_target_sconfig_binding(
            state=state,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
    )
    intents = stage.setdefault("jail_boundary_intents", {})
    if not isinstance(intents, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary mutation intent collection is malformed."
        )
    if not re.fullmatch(r"[0-9a-f]{64}", expected_login_jail_submounts_fingerprint):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary intent lacks the exact login jailSubMounts contract."
        )
    proposed = {
        "target_uid": target_identity["uid"],
        "target_resource_version": target_identity["resourceVersion"],
        "target_from_generation": _legacy_rootfs_positive_generation(
            target_resource,
            label="target SlurmCluster Jail-boundary intent",
        ),
        "target_jail_boundary_fingerprint": (
            _legacy_rootfs_slurmcluster_jail_boundary_fingerprint(target_resource)
        ),
        "deployment_uid": deployment_identity["uid"],
        "deployment_resource_version": deployment_identity["resourceVersion"],
        "deployment_from_generation": _legacy_rootfs_positive_generation(
            deployment,
            label="target SConfig Deployment Jail-boundary intent",
        ),
        "deployment_spec_fingerprint": _legacy_rootfs_scalable_spec_fingerprint(
            deployment,
            label="target SConfig Deployment Jail-boundary intent",
        ),
        "deployment_jail_boundary_fingerprint": (
            _legacy_rootfs_sconfig_jail_boundary_contract(deployment)[0]
        ),
        "expected_rootfs_pvc": expected_rootfs_pvc,
        "expected_rootfs_volume_source": expected_rootfs_volume_source,
        "expected_maintenance": expected_maintenance,
        "expected_login_jail_submounts_fingerprint": (expected_login_jail_submounts_fingerprint),
    }
    existing = _mapping(intents.get(boundary_id))
    if existing:
        immutable_keys = tuple(proposed)
        if any(existing.get(key) != proposed[key] for key in immutable_keys):
            raise SoperatorMigrationPhasePending(
                "legacy-rootfs Jail-boundary mutation changed after its durable intent."
            )
        return
    intents[boundary_id] = {
        **proposed,
        "target_expected_generation": proposed["target_from_generation"] + 1,
        "deployment_expected_generation": proposed["deployment_from_generation"] + 1,
        "intent_at": _utc_now(),
    }
    checkpoint_writer()


def _pulse_legacy_rootfs_target_writer_for_jail_boundary(
    *,
    phase: dict[str, Any],
    boundary_id: str,
    expected_rootfs_pvc: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None],
    mutation_guard: Callable[[], None] | None,
    verification_timeout_seconds: int = 300,
) -> None:
    state = _legacy_rootfs_slurm_config_bridge_state(phase)
    stage = state.get("target_compatibility_stage")
    if not isinstance(stage, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary writer pulse lacks a mutable stage."
        )
    rebind = _mapping(_mapping(stage.get("jail_boundary_rebinds")).get(boundary_id))
    if not rebind or str(rebind.get("rootfs_pvc") or "") != expected_rootfs_pvc:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary writer pulse lacks its exact rebind proof."
        )
    refreshes = stage.setdefault("jail_boundary_writer_refreshes", {})
    if not isinstance(refreshes, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary writer refresh collection is malformed."
        )
    refresh = refreshes.setdefault(boundary_id, {"status": "pending"})
    if not isinstance(refresh, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary writer refresh is malformed."
        )
    handoff = _immutable_child_handoff_state(phase)
    refresh_status = str(refresh.get("status") or "pending")
    if refresh_status == "verified":
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        return
    manager_transition = refresh.setdefault("manager_transition", {})
    if not isinstance(manager_transition, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs Jail-boundary manager transition is malformed."
        )
    if refresh_status == "zero":
        manager_binding = _mapping(handoff.get("manager"))
        manager = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name="soperator-manager",
        )
        _immutable_child_require_live_uid(
            manager,
            expected_uid=str(manager_binding.get("uid") or ""),
            label="Soperator manager post-seed recovery",
        )
        _immutable_child_require_manager_spec_contract(
            manager_binding=manager_binding,
            manager=manager,
        )
        manager_desired = _resource_replicas(manager, default=-1)
        original_manager_replicas = _positive_int(manager_binding.get("replicas"), fallback=0)
        if manager_desired == original_manager_replicas:
            if not str(refresh.get("all_files_verified_at") or "").strip() or _positive_int(
                refresh.get("all_files_item_count"), fallback=0
            ) != _positive_int(stage.get("jailed_config_item_count"), fallback=0):
                raise SoperatorMigrationPhasePending(
                    "legacy-rootfs slot-b seed recovery lacks its durable all-file proof."
                )
            _legacy_rootfs_target_stage_manager_replicas(
                stage=manager_transition,
                handoff=handoff,
                replicas=original_manager_replicas,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
            _wait_for_legacy_rootfs_post_restore_full_target_config(
                state=state,
                stage=stage,
                handoff=handoff,
                command_runner=command_runner,
                kube_context=kube_context,
                timeout_seconds=verification_timeout_seconds,
            )
            _revalidate_legacy_rootfs_target_compatibility_active(
                phase=phase,
                handoff=handoff,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            refresh["status"] = "verified"
            refresh["verified_at"] = refresh.get("verified_at") or _utc_now()
            refresh["recovered_after_manager_restore"] = True
            checkpoint_writer()
            return
        if manager_desired != 0:
            raise SoperatorMigrationPhasePending(
                "Soperator manager drifted outside the slot-b seed recovery transition."
            )
    if refresh_status != "zero":
        _legacy_rootfs_target_stage_manager_replicas(
            stage=manager_transition,
            handoff=handoff,
            replicas=0,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
    target_config_binding = _mapping(state.get("configmap"))
    target_config_map = _legacy_rootfs_bridge_optional_resource(
        resource_type="configmap",
        name=str(target_config_binding.get("name") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if target_config_map is None:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap disappeared before the Jail-boundary writer pulse."
        )
    target_config_identity = _immutable_child_require_live_uid(
        target_config_map,
        expected_uid=str(stage.get("configmap_uid") or ""),
        label="target Slurm ConfigMap Jail-boundary writer pulse",
    )
    _legacy_rootfs_bridge_controller_owner(
        target_config_map,
        allowed_bindings={
            "target": _legacy_rootfs_bridge_binding(
                _mapping(handoff.get("target")), label="target SlurmCluster"
            )
        },
        label="target Slurm ConfigMap Jail-boundary writer pulse",
    )
    compatible_sha = str(stage.get("compatible_sha256") or "")
    config_state, compatible_config = _legacy_rootfs_configmap_compatible_transform(
        config_map=target_config_map,
        stage=stage,
    )
    config_refresh = refresh.setdefault("config_refresh", {})
    if not isinstance(config_refresh, dict):
        raise SoperatorMigrationPhasePending(
            "Jail-boundary target config refresh checkpoint is malformed."
        )
    if config_state == "transformable":
        live_config = _legacy_rootfs_bridge_config_text(target_config_map)
        live_sha = hashlib.sha256(live_config.encode("utf-8")).hexdigest()
        live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(target_config_map)
        if not config_refresh:
            config_refresh.update(
                {
                    "uid": target_config_identity["uid"],
                    "intent_resource_version": target_config_identity["resourceVersion"],
                    "source_sha256": live_sha,
                    "source_data_fingerprint": live_data_fingerprint,
                    "compatible_sha256": compatible_sha,
                    "compatible_data_fingerprint": str(
                        stage.get("compatible_data_fingerprint") or ""
                    ),
                    "intent_at": _utc_now(),
                }
            )
            checkpoint_writer()
        elif (
            config_refresh.get("uid") != target_config_identity["uid"]
            or config_refresh.get("source_sha256") != live_sha
            or config_refresh.get("source_data_fingerprint") != live_data_fingerprint
            or config_refresh.get("compatible_sha256") != compatible_sha
            or config_refresh.get("compatible_data_fingerprint")
            != str(stage.get("compatible_data_fingerprint") or "")
            or config_refresh.get("intent_resource_version")
            != target_config_identity["resourceVersion"]
        ):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap changed after Jail-boundary compatibility intent."
            )
        replacement = copy.deepcopy(to_plain_data(target_config_map))
        data = replacement.get("data")
        if not isinstance(data, dict):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap data is malformed before Jail-boundary refresh."
            )
        data["slurm.conf"] = compatible_config
        _legacy_rootfs_bridge_replace_exact_resource(
            resource=replacement,
            command_runner=command_runner,
            kube_context=kube_context,
            mutation_guard=mutation_guard,
        )
        config_refresh["applied_at"] = _utc_now()
        checkpoint_writer()
        target_config_map = _legacy_rootfs_bridge_optional_resource(
            resource_type="configmap",
            name=str(target_config_binding.get("name") or ""),
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if target_config_map is None:
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap disappeared after Jail-boundary compatibility replace."
            )
        _immutable_child_require_live_uid(
            target_config_map,
            expected_uid=str(stage.get("configmap_uid") or ""),
            label="target Slurm ConfigMap post-pulse compatibility proof",
        )
        _legacy_rootfs_bridge_controller_owner(
            target_config_map,
            allowed_bindings={
                "target": _legacy_rootfs_bridge_binding(
                    _mapping(handoff.get("target")), label="target SlurmCluster"
                )
            },
            label="target Slurm ConfigMap post-pulse compatibility proof",
        )
        post_state, _post_config = _legacy_rootfs_configmap_compatible_transform(
            config_map=target_config_map,
            stage=stage,
        )
        if post_state != "compatible":
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap compatibility replace did not preserve full data."
            )
        config_refresh["applied_resource_version"] = _immutable_child_exact_identity(
            target_config_map,
            label="target Slurm ConfigMap post-pulse compatibility proof",
        )["resourceVersion"]
        config_refresh["applied_at"] = config_refresh.get("applied_at") or _utc_now()
        checkpoint_writer()
    elif config_refresh:
        if (
            config_refresh.get("uid") != target_config_identity["uid"]
            or config_refresh.get("compatible_sha256") != compatible_sha
            or config_refresh.get("compatible_data_fingerprint")
            != str(stage.get("compatible_data_fingerprint") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap compatibility checkpoint drifted after replace."
            )
        if not str(config_refresh.get("applied_at") or "").strip():
            config_refresh["applied_resource_version"] = target_config_identity["resourceVersion"]
            config_refresh["applied_at"] = _utc_now()
            config_refresh["recovered_after_replace"] = True
            checkpoint_writer()
    target_jailed_files = _legacy_rootfs_target_jailed_config_files(
        state=state,
        stage=stage,
        handoff=handoff,
        config_map=target_config_map,
        command_runner=command_runner,
        kube_context=kube_context,
        initialize=False,
    )
    deployment, identity, service_account_name, _service_account_identity = (
        _legacy_rootfs_target_sconfig_binding(
            state=state,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
    )
    fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
        deployment,
        label="target SConfig Jail-boundary writer pulse",
    )
    if identity["uid"] != str(rebind.get("deployment_uid") or "") or fingerprint != str(
        stage.get("deployment_spec_fingerprint") or ""
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment changed before its Jail-boundary writer pulse."
        )
    status = str(refresh.get("status") or "")
    desired = _resource_replicas(deployment, default=-1)
    generation = _legacy_rootfs_positive_generation(
        deployment,
        label="target SConfig Jail-boundary writer pulse",
    )
    if status == "pending":
        if desired != 0:
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer was active before pulse intent."
            )
        refresh.update(
            {
                "status": "scale-up-intent",
                "deployment_uid": identity["uid"],
                "spec_fingerprint": fingerprint,
                "scale_up_from_generation": generation,
                "scale_up_expected_generation": generation + 1,
                "scale_up_resource_version": identity["resourceVersion"],
                "scale_up_intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
        status = "scale-up-intent"
    if status == "scale-up-intent" and desired == 0:
        if generation != _positive_int(
            refresh.get("scale_up_from_generation"), fallback=0
        ) or fingerprint != str(refresh.get("spec_fingerprint") or ""):
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer changed after scale-up intent."
            )
        if mutation_guard is not None:
            mutation_guard()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"deployment/{_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME}",
            replicas=1,
            current_replicas=0,
            resource_version=identity["resourceVersion"],
        )
        desired = 1
    if status in {"scale-up-intent", "writer-ready"}:
        ready_deployment, ready_pod = _legacy_rootfs_bridge_wait_jail_digest(
            expected_sha256=str(stage.get("compatible_sha256") or ""),
            deployment_uid=identity["uid"],
            service_account_name=service_account_name,
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=verification_timeout_seconds,
            poll_interval_seconds=1,
        )
        ready_identity = _immutable_child_exact_identity(
            ready_deployment,
            label="target SConfig Jail-boundary ready Deployment",
        )
        ready_generation = _legacy_rootfs_positive_generation(
            ready_deployment,
            label="target SConfig Jail-boundary ready Deployment",
        )
        if (
            ready_identity["uid"] != identity["uid"]
            or ready_generation
            != _positive_int(refresh.get("scale_up_expected_generation"), fallback=0)
            or _legacy_rootfs_scalable_spec_fingerprint(
                ready_deployment,
                label="target SConfig Jail-boundary ready Deployment",
            )
            != str(refresh.get("spec_fingerprint") or "")
        ):
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer scale-up crossed an unbounded generation."
            )
        live_pod = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="pod",
            name=ready_pod["name"],
        )
        _immutable_child_require_live_uid(
            live_pod,
            expected_uid=ready_pod["uid"],
            label="target SConfig Jail-boundary writer Pod",
        )
        if not _pod_template_has_jail_rootfs_consumer_mount(
            payload={"spec": {"template": {"spec": _mapping(live_pod.get("spec"))}}},
            rootfs_pvc=expected_rootfs_pvc,
        ):
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer Pod does not mount the switched rootfs PVC."
            )
        _legacy_rootfs_verify_jailed_config_files(
            pod=ready_pod,
            files=target_jailed_files,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        ready_spec_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
            ready_deployment,
            label="target SConfig Jail-boundary writer-ready Deployment",
        )
        if status == "scale-up-intent":
            refresh.update(
                {
                    "status": "writer-ready",
                    "ready_pod_uid": ready_pod["uid"],
                    "writer_ready_deployment_uid": ready_identity["uid"],
                    "writer_ready_generation": ready_generation,
                    "writer_ready_spec_fingerprint": ready_spec_fingerprint,
                    "all_files_item_count": len(target_jailed_files),
                    "all_files_verified_at": _utc_now(),
                    "digest_verified_at": _utc_now(),
                }
            )
            checkpoint_writer()
            status = "writer-ready"
        elif (
            str(refresh.get("ready_pod_uid") or "") != ready_pod["uid"]
            or str(refresh.get("writer_ready_deployment_uid") or "") != ready_identity["uid"]
            or _positive_int(refresh.get("writer_ready_generation"), fallback=0) != ready_generation
            or str(refresh.get("writer_ready_spec_fingerprint") or "") != ready_spec_fingerprint
            or not str(refresh.get("all_files_verified_at") or "").strip()
            or _positive_int(refresh.get("all_files_item_count"), fallback=0)
            != len(target_jailed_files)
        ):
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer-ready identity drifted before scale-down."
            )
        deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        identity = _immutable_child_require_live_uid(
            deployment,
            expected_uid=identity["uid"],
            label="target SConfig Jail-boundary writer scale-down",
        )
        generation = _legacy_rootfs_positive_generation(
            deployment,
            label="target SConfig Jail-boundary writer scale-down",
        )
        if (
            generation != ready_generation
            or _legacy_rootfs_scalable_spec_fingerprint(
                deployment,
                label="target SConfig Jail-boundary writer scale-down",
            )
            != ready_spec_fingerprint
            or _resource_replicas(deployment, default=-1) != 1
        ):
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer changed before scale-down intent."
            )
        refresh.update(
            {
                "status": "scale-down-intent",
                "scale_down_from_generation": generation,
                "scale_down_expected_generation": generation + 1,
                "scale_down_resource_version": identity["resourceVersion"],
                "scale_down_intent_at": refresh.get("scale_down_intent_at") or _utc_now(),
            }
        )
        checkpoint_writer()
        status = "scale-down-intent"
        desired = _resource_replicas(deployment, default=-1)
    if status == "scale-down-intent":
        if desired == 1:
            if generation != _positive_int(refresh.get("scale_down_from_generation"), fallback=0):
                raise SoperatorMigrationPhasePending(
                    "target SConfig Jail-boundary writer changed after scale-down intent."
                )
            if mutation_guard is not None:
                mutation_guard()
            _kubectl_scale_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=f"deployment/{_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME}",
                replicas=0,
                current_replicas=1,
                resource_version=identity["resourceVersion"],
            )
        zero_identity = _legacy_rootfs_wait_target_sconfig_zero(
            deployment_uid=identity["uid"],
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=verification_timeout_seconds,
        )
        zero_deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        _immutable_child_require_live_uid(
            zero_deployment,
            expected_uid=identity["uid"],
            label="target SConfig Jail-boundary writer zero proof",
        )
        zero_generation = _legacy_rootfs_positive_generation(
            zero_deployment,
            label="target SConfig Jail-boundary writer zero proof",
        )
        if zero_generation != _positive_int(
            refresh.get("scale_down_expected_generation"), fallback=0
        ) or _legacy_rootfs_scalable_spec_fingerprint(
            zero_deployment,
            label="target SConfig Jail-boundary writer zero proof",
        ) != str(refresh.get("spec_fingerprint") or ""):
            raise SoperatorMigrationPhasePending(
                "target SConfig Jail-boundary writer scale-down crossed an unbounded generation."
            )
        refresh.update(
            {
                "status": "zero",
                "zero_resource_version": zero_identity["resourceVersion"],
                "zero_generation": zero_generation,
                "zero_at": _utc_now(),
            }
        )
        checkpoint_writer()
    if str(refresh.get("status") or "") == "zero":
        _legacy_rootfs_target_stage_manager_replicas(
            stage=manager_transition,
            handoff=handoff,
            replicas=_positive_int(_mapping(handoff.get("manager")).get("replicas"), fallback=0),
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _wait_for_legacy_rootfs_post_restore_full_target_config(
            state=state,
            stage=stage,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=verification_timeout_seconds,
        )
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        refresh["status"] = "verified"
        refresh["verified_at"] = _utc_now()
        checkpoint_writer()
    if str(refresh.get("status") or "") == "verified":
        _wait_for_legacy_rootfs_post_restore_full_target_config(
            state=state,
            stage=stage,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=verification_timeout_seconds,
        )
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )


def _stage_legacy_rootfs_target_slurm_config_compatibility(
    *,
    phase: dict[str, Any],
    handoff: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    verification_timeout_seconds: int = 300,
    poll_interval_seconds: float = 2.0,
) -> list[str]:
    """Materialize a target-owned compatible jail config while every writer is fenced."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility stage requires durable checkpoint writes."
        )
    state = _legacy_rootfs_slurm_config_bridge_state(phase)
    if state.get("dual_aggregated_config") is not True:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility requires exact source/target config bindings."
        )
    if str(state.get("status") or "") == "target-compatibility-active":
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        return ["Legacy-rootfs target-only Slurm compatibility fence remains active."]
    if str(state.get("status") or "") not in {"active", "target-compatibility-intent"}:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility requires the active pre-retirement bridge."
        )
    _legacy_rootfs_bridge_require_source_absent(
        source_binding=_legacy_rootfs_bridge_binding(
            _mapping(handoff.get("source")), label="source SlurmCluster"
        ),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    fence = _legacy_rootfs_sconfig_writer_fence_state(phase)
    if str(fence.get("status") or "") != "prepared":
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility requires the prepared writer fence."
        )
    stage = state.setdefault("target_compatibility_stage", {})
    if not isinstance(stage, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target compatibility checkpoint is malformed."
        )
    if not stage:
        state["status"] = "target-compatibility-intent"
        stage["intent_at"] = _utc_now()
        checkpoint_writer()
    _legacy_rootfs_target_stage_manager_replicas(
        stage=stage,
        handoff=handoff,
        replicas=0,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )
    manager_binding = _mapping(handoff.get("manager"))
    manager = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name="soperator-manager",
    )
    _immutable_child_require_live_uid(
        manager,
        expected_uid=str(manager_binding.get("uid") or ""),
        label="Soperator manager target-compatibility stage",
    )
    manager_fingerprint, manager_generation = _immutable_child_require_manager_spec_contract(
        manager_binding=manager_binding,
        manager=manager,
    )
    restored_cycle_resume = _legacy_rootfs_target_stage_restored_cycle_is_exact(
        stage=stage,
        manager_fingerprint=manager_fingerprint,
        manager_generation=manager_generation,
        desired=_resource_replicas(manager, default=-1),
        original_replicas=_positive_int(manager_binding.get("replicas"), fallback=0),
    )
    deployment, deployment_identity, service_account_name, service_account_identity = (
        _legacy_rootfs_target_sconfig_binding(
            state=state,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
    )
    if _resource_replicas(deployment, default=-1) != 0:
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment must remain zero while compatibility is staged."
        )
    prior_deployment_uid = str(stage.get("deployment_uid") or "")
    prior_service_account_uid = str(stage.get("service_account_uid") or "")
    deployment_spec_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
        deployment,
        label="target SConfig Deployment compatibility stage",
    )
    (
        deployment_jail_boundary_fingerprint,
        deployment_jail_volume_name,
        deployment_jail_pvc,
    ) = _legacy_rootfs_sconfig_jail_boundary_contract(deployment)
    if prior_deployment_uid and prior_deployment_uid != deployment_identity["uid"]:
        raise SoperatorMigrationPhasePending("target SConfig Deployment UID changed during stage.")
    if prior_service_account_uid and prior_service_account_uid != service_account_identity["uid"]:
        raise SoperatorMigrationPhasePending(
            "target SConfig ServiceAccount UID changed during compatibility stage."
        )
    if str(stage.get("deployment_spec_fingerprint") or "") not in {
        "",
        deployment_spec_fingerprint,
    }:
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment spec changed during compatibility stage."
        )
    if str(stage.get("deployment_jail_boundary_fingerprint") or "") not in {
        "",
        deployment_jail_boundary_fingerprint,
    } or str(stage.get("deployment_jail_volume_name") or "") not in {
        "",
        deployment_jail_volume_name,
    }:
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment non-Jail contract changed during compatibility stage."
        )
    stage.update(
        {
            "deployment_uid": deployment_identity["uid"],
            "service_account_name": service_account_name,
            "service_account_uid": service_account_identity["uid"],
            "deployment_spec_fingerprint": deployment_spec_fingerprint,
            "deployment_jail_boundary_fingerprint": deployment_jail_boundary_fingerprint,
            "deployment_jail_volume_name": deployment_jail_volume_name,
            "pre_switch_jail_pvc": stage.get("pre_switch_jail_pvc") or deployment_jail_pvc,
        }
    )
    checkpoint_writer()

    target_config_binding = _mapping(state.get("configmap"))
    target_config_map = _legacy_rootfs_bridge_optional_resource(
        resource_type="configmap",
        name=str(target_config_binding.get("name") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if target_config_map is None:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap disappeared before compatibility staging."
        )
    target_config_identity = _immutable_child_require_live_uid(
        target_config_map,
        expected_uid=str(target_config_binding.get("uid") or ""),
        label="target Slurm ConfigMap compatibility stage",
    )
    _legacy_rootfs_bridge_controller_owner(
        target_config_map,
        allowed_bindings={
            "target": _legacy_rootfs_bridge_binding(
                _mapping(handoff.get("target")), label="target SlurmCluster"
            )
        },
        label="target Slurm ConfigMap compatibility stage",
    )
    jailed_config_was_bound = bool(str(stage.get("jailed_config_spec_fingerprint") or "").strip())
    target_jailed_files = _legacy_rootfs_target_jailed_config_files(
        state=state,
        stage=stage,
        handoff=handoff,
        config_map=target_config_map,
        command_runner=command_runner,
        kube_context=kube_context,
        initialize=True,
    )
    if not jailed_config_was_bound:
        checkpoint_writer()
    live_config = _legacy_rootfs_bridge_config_text(target_config_map)
    live_sha = hashlib.sha256(live_config.encode("utf-8")).hexdigest()
    live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(target_config_map)
    original_sha = str(stage.get("full_target_sha256") or "")
    compatible_sha = str(stage.get("compatible_sha256") or "")
    compatible_config = ""
    if not original_sha:
        compatible_config, counts = _legacy_rootfs_slurm_config_bridge_text(live_config)
        open_metrics_disabled_config = _legacy_rootfs_slurm_config_without_metrics_type(live_config)
        original_sha = live_sha
        compatible_sha = hashlib.sha256(compatible_config.encode("utf-8")).hexdigest()
        compatible_config_map = copy.deepcopy(to_plain_data(target_config_map))
        compatible_data = compatible_config_map.get("data")
        if not isinstance(compatible_data, dict):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap data is malformed during compatibility intent."
            )
        compatible_data["slurm.conf"] = compatible_config
        open_metrics_disabled_config_map = copy.deepcopy(to_plain_data(target_config_map))
        open_metrics_disabled_data = open_metrics_disabled_config_map.get("data")
        if not isinstance(open_metrics_disabled_data, dict):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap data is malformed during OpenMetrics intent."
            )
        open_metrics_disabled_data["slurm.conf"] = open_metrics_disabled_config
        stage.update(
            {
                "configmap_uid": target_config_identity["uid"],
                "full_target_sha256": original_sha,
                "compatible_sha256": compatible_sha,
                "open_metrics_disabled_sha256": hashlib.sha256(
                    open_metrics_disabled_config.encode("utf-8")
                ).hexdigest(),
                "full_target_data_fingerprint": live_data_fingerprint,
                "compatible_data_fingerprint": _legacy_rootfs_configmap_data_fingerprint(
                    compatible_config_map
                ),
                "open_metrics_disabled_data_fingerprint": (
                    _legacy_rootfs_configmap_data_fingerprint(open_metrics_disabled_config_map)
                ),
                "directive_counts": counts,
                "config_replace_intent_resource_version": target_config_identity["resourceVersion"],
                "config_replace_intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
    elif live_sha == original_sha:
        compatible_config, counts = _legacy_rootfs_slurm_config_bridge_text(live_config)
        if hashlib.sha256(
            compatible_config.encode("utf-8")
        ).hexdigest() != compatible_sha or counts != _mapping(stage.get("directive_counts")):
            raise SoperatorMigrationPhasePending(
                "target Slurm config compatibility transform changed after intent."
            )
    elif live_sha != compatible_sha:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap drifted outside full/compatible checkpointed digests."
        )
    expected_data_fingerprint = str(
        stage.get(
            "full_target_data_fingerprint"
            if live_sha == original_sha
            else "compatible_data_fingerprint"
        )
        or ""
    )
    if live_data_fingerprint != expected_data_fingerprint:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap non-slurm.conf data drifted during compatibility staging."
        )
    if str(stage.get("configmap_uid") or "") != target_config_identity["uid"]:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap UID changed during compatibility staging."
        )
    if live_sha == original_sha:
        if restored_cycle_resume:
            proposed_post_restore = {
                "configmap_uid": target_config_identity["uid"],
                "configmap_resource_version": target_config_identity["resourceVersion"],
                "full_target_sha256": live_sha,
                "full_target_data_fingerprint": live_data_fingerprint,
                "manager_generation": manager_generation,
                "manager_spec_fingerprint": manager_fingerprint,
            }
            post_restore = stage.get("post_restore_full_target")
            if post_restore is not None and _mapping(post_restore) != proposed_post_restore:
                raise SoperatorMigrationPhasePending(
                    "post-restore full target Slurm ConfigMap proof changed after checkpoint."
                )
            if post_restore is None:
                stage["post_restore_full_target"] = proposed_post_restore
                stage["post_restore_full_target_at"] = _utc_now()
                checkpoint_writer()
        elif (
            str(stage.get("config_replace_intent_resource_version") or "")
            != target_config_identity["resourceVersion"]
        ):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap changed after compatibility replace intent."
            )
        if not restored_cycle_resume:
            replacement = copy.deepcopy(to_plain_data(target_config_map))
            data = replacement.get("data")
            if not isinstance(data, dict):
                raise SoperatorMigrationPhasePending("target Slurm ConfigMap data is malformed.")
            data["slurm.conf"] = compatible_config
            _legacy_rootfs_bridge_replace_exact_resource(
                resource=replacement,
                command_runner=command_runner,
                kube_context=kube_context,
                mutation_guard=mutation_guard,
            )
            stage["config_replace_applied_at"] = _utc_now()
            checkpoint_writer()

    target_config_map = _legacy_rootfs_bridge_optional_resource(
        resource_type="configmap",
        name=str(target_config_binding.get("name") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if target_config_map is None:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap disappeared after compatibility replacement."
        )
    _immutable_child_require_live_uid(
        target_config_map,
        expected_uid=str(stage.get("configmap_uid") or ""),
        label="target Slurm ConfigMap compatible file proof",
    )
    _legacy_rootfs_bridge_controller_owner(
        target_config_map,
        allowed_bindings={
            "target": _legacy_rootfs_bridge_binding(
                _mapping(handoff.get("target")), label="target SlurmCluster"
            )
        },
        label="target Slurm ConfigMap compatible file proof",
    )
    compatible_state, _compatible_config = _legacy_rootfs_configmap_compatible_transform(
        config_map=target_config_map,
        stage=stage,
    )
    current_config_sha = hashlib.sha256(
        _legacy_rootfs_bridge_config_text(target_config_map).encode("utf-8")
    ).hexdigest()
    current_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(target_config_map)
    post_restore_full_target = bool(
        restored_cycle_resume
        and _mapping(stage.get("post_restore_full_target"))
        and current_config_sha == str(stage.get("full_target_sha256") or "")
        and current_data_fingerprint == str(stage.get("full_target_data_fingerprint") or "")
    )
    if compatible_state != "compatible" and not post_restore_full_target:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap did not converge to the exact compatible data set."
        )
    target_jailed_files = _legacy_rootfs_target_jailed_config_files(
        state=state,
        stage=stage,
        handoff=handoff,
        config_map=target_config_map,
        command_runner=command_runner,
        kube_context=kube_context,
        initialize=False,
    )

    for state_key, resource_type, api_path in (
        (
            "source_jailed_config",
            "jailedconfig",
            "/apis/slurm.nebius.ai/v1alpha1/namespaces/soperator/jailedconfigs",
        ),
        ("source_configmap", "configmap", "/api/v1/namespaces/soperator/configmaps"),
    ):
        binding = _mapping(state.get(state_key))
        cleanup = _mapping(_mapping(state.get("source_config_cleanup")).get(state_key))
        if not str(cleanup.get("deleted_at") or "").strip():
            live_source = _legacy_rootfs_bridge_optional_resource(
                resource_type=resource_type,
                name=str(binding.get("name") or ""),
                command_runner=command_runner,
                kube_context=kube_context,
            )
            if live_source is None:
                raise SoperatorMigrationPhasePending(
                    f"legacy-rootfs {state_key} disappeared before cleanup intent."
                )
            _legacy_rootfs_require_source_bridge_object_cleanup_state(
                resource=live_source,
                binding=binding,
                target_binding=_mapping(handoff.get("target")),
                label=f"legacy-rootfs {state_key}",
            )
        _legacy_rootfs_bridge_delete_exact_source_config(
            state=state,
            state_key=state_key,
            resource_type=resource_type,
            api_path=api_path,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
            target_binding=_mapping(handoff.get("target")),
        )

    refresh = stage.setdefault("target_writer_refresh", {"status": "pending"})
    if not isinstance(refresh, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target writer refresh checkpoint is malformed."
        )
    deployment = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="deployment",
        name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
    )
    deployment_identity = _immutable_child_require_live_uid(
        deployment,
        expected_uid=str(stage.get("deployment_uid") or ""),
        label="target SConfig Deployment writer refresh",
    )
    desired = _resource_replicas(deployment, default=-1)
    deployment_generation = _legacy_rootfs_positive_generation(
        deployment,
        label="target SConfig Deployment writer refresh",
    )
    deployment_spec_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
        deployment,
        label="target SConfig Deployment writer refresh",
    )
    if deployment_spec_fingerprint != str(stage.get("deployment_spec_fingerprint") or ""):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment spec drifted before writer refresh."
        )
    refresh_status = str(refresh.get("status") or "")
    if refresh_status == "pending":
        if desired != 0:
            raise SoperatorMigrationPhasePending(
                "target SConfig writer was active before its scale-up intent."
            )
        refresh.update(
            {
                "status": "scale-up-intent",
                "scale_up_resource_version": deployment_identity["resourceVersion"],
                "scale_up_patch_resource_version": deployment_identity["resourceVersion"],
                "scale_up_from_generation": deployment_generation,
                "scale_up_expected_generation": deployment_generation + 1,
                "scale_up_spec_fingerprint": deployment_spec_fingerprint,
                "scale_up_intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
        refresh_status = "scale-up-intent"
    if refresh_status == "scale-up-intent" and desired == 0:
        if deployment_generation != _positive_int(
            refresh.get("scale_up_from_generation"), fallback=0
        ) or deployment_spec_fingerprint != str(refresh.get("scale_up_spec_fingerprint") or ""):
            raise SoperatorMigrationPhasePending(
                "target SConfig Deployment changed after writer scale-up intent."
            )
        if refresh.get("scale_up_patch_resource_version") != deployment_identity["resourceVersion"]:
            refresh["scale_up_patch_resource_version"] = deployment_identity["resourceVersion"]
            refresh["scale_up_patch_rv_refreshed_at"] = _utc_now()
            checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _kubectl_scale_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"deployment/{_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME}",
            replicas=1,
            current_replicas=0,
            resource_version=deployment_identity["resourceVersion"],
        )
        desired = 1
    if refresh_status in {"scale-up-intent", "writer-ready"}:
        if refresh_status == "writer-ready" and (
            desired != 1
            or str(refresh.get("writer_ready_deployment_uid") or "") != deployment_identity["uid"]
            or _positive_int(refresh.get("writer_ready_generation"), fallback=0)
            != deployment_generation
            or str(refresh.get("writer_ready_spec_fingerprint") or "")
            != deployment_spec_fingerprint
        ):
            raise SoperatorMigrationPhasePending(
                "target SConfig writer-ready Deployment drifted before scale-down intent."
            )
        if refresh_status == "scale-up-intent" and desired == 1:
            scaled_deployment = _immutable_child_get_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type="deployment",
                name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
            )
            _immutable_child_require_live_uid(
                scaled_deployment,
                expected_uid=str(stage.get("deployment_uid") or ""),
                label="target SConfig Deployment writer scale-up proof",
            )
            if _legacy_rootfs_positive_generation(
                scaled_deployment,
                label="target SConfig Deployment writer scale-up proof",
            ) != _positive_int(
                refresh.get("scale_up_expected_generation"), fallback=0
            ) or _legacy_rootfs_scalable_spec_fingerprint(
                scaled_deployment,
                label="target SConfig Deployment writer scale-up proof",
            ) != str(refresh.get("scale_up_spec_fingerprint") or ""):
                raise SoperatorMigrationPhasePending(
                    "target SConfig writer scale-up crossed an unbounded generation."
                )
        _ready_deployment, ready_pod = _legacy_rootfs_bridge_wait_jail_digest(
            expected_sha256=compatible_sha,
            deployment_uid=str(stage.get("deployment_uid") or ""),
            service_account_name=service_account_name,
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=verification_timeout_seconds,
            poll_interval_seconds=poll_interval_seconds,
        )
        _legacy_rootfs_verify_jailed_config_files(
            pod=ready_pod,
            files=target_jailed_files,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        refresh.update(
            {
                "status": "writer-ready",
                "ready_pod_uid": ready_pod["uid"],
                "writer_ready_deployment_uid": _immutable_child_exact_identity(
                    _ready_deployment,
                    label="target SConfig writer-ready Deployment",
                )["uid"],
                "writer_ready_generation": _legacy_rootfs_positive_generation(
                    _ready_deployment,
                    label="target SConfig writer-ready Deployment",
                ),
                "writer_ready_spec_fingerprint": _legacy_rootfs_scalable_spec_fingerprint(
                    _ready_deployment,
                    label="target SConfig writer-ready Deployment",
                ),
                "digest_verified_at": _utc_now(),
            }
        )
        checkpoint_writer()
        deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        deployment_identity = _immutable_child_require_live_uid(
            deployment,
            expected_uid=str(stage.get("deployment_uid") or ""),
            label="target SConfig Deployment writer scale-down",
        )
        desired = _resource_replicas(deployment, default=-1)
        deployment_generation = _legacy_rootfs_positive_generation(
            deployment,
            label="target SConfig Deployment writer scale-down",
        )
        deployment_spec_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
            deployment,
            label="target SConfig Deployment writer scale-down",
        )
        if desired != 1:
            raise SoperatorMigrationPhasePending(
                "target SConfig writer changed before scale-down intent."
            )
        refresh.update(
            {
                "status": "scale-down-intent",
                "scale_down_resource_version": deployment_identity["resourceVersion"],
                "scale_down_patch_resource_version": deployment_identity["resourceVersion"],
                "scale_down_from_generation": deployment_generation,
                "scale_down_expected_generation": deployment_generation + 1,
                "scale_down_spec_fingerprint": deployment_spec_fingerprint,
                "scale_down_intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
        refresh_status = "scale-down-intent"
    if refresh_status == "scale-down-intent":
        deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        deployment_identity = _immutable_child_require_live_uid(
            deployment,
            expected_uid=str(stage.get("deployment_uid") or ""),
            label="target SConfig Deployment writer scale-down",
        )
        desired = _resource_replicas(deployment, default=-1)
        deployment_generation = _legacy_rootfs_positive_generation(
            deployment,
            label="target SConfig Deployment writer scale-down",
        )
        deployment_spec_fingerprint = _legacy_rootfs_scalable_spec_fingerprint(
            deployment,
            label="target SConfig Deployment writer scale-down",
        )
        if desired not in {0, 1}:
            raise SoperatorMigrationPhasePending("target SConfig writer drifted during scale-down.")
        if desired == 1:
            if deployment_generation != _positive_int(
                refresh.get("scale_down_from_generation"), fallback=0
            ) or deployment_spec_fingerprint != str(
                refresh.get("scale_down_spec_fingerprint") or ""
            ):
                raise SoperatorMigrationPhasePending(
                    "target SConfig Deployment changed after writer scale-down intent."
                )
            if (
                refresh.get("scale_down_patch_resource_version")
                != deployment_identity["resourceVersion"]
            ):
                refresh["scale_down_patch_resource_version"] = deployment_identity[
                    "resourceVersion"
                ]
                refresh["scale_down_patch_rv_refreshed_at"] = _utc_now()
                checkpoint_writer()
            if mutation_guard is not None:
                mutation_guard()
            _kubectl_scale_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=f"deployment/{_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME}",
                replicas=0,
                current_replicas=1,
                resource_version=deployment_identity["resourceVersion"],
            )
        zero_identity = _legacy_rootfs_wait_target_sconfig_zero(
            deployment_uid=str(stage.get("deployment_uid") or ""),
            command_runner=command_runner,
            kube_context=kube_context,
            timeout_seconds=verification_timeout_seconds,
        )
        zero_deployment = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=_LEGACY_ROOTFS_SCONFIG_DEPLOYMENT_NAME,
        )
        _immutable_child_require_live_uid(
            zero_deployment,
            expected_uid=str(stage.get("deployment_uid") or ""),
            label="target SConfig Deployment writer zero proof",
        )
        zero_generation = _legacy_rootfs_positive_generation(
            zero_deployment,
            label="target SConfig Deployment writer zero proof",
        )
        if zero_generation != _positive_int(
            refresh.get("scale_down_expected_generation"), fallback=0
        ) or _legacy_rootfs_scalable_spec_fingerprint(
            zero_deployment,
            label="target SConfig Deployment writer zero proof",
        ) != str(refresh.get("scale_down_spec_fingerprint") or ""):
            raise SoperatorMigrationPhasePending(
                "target SConfig writer scale-down crossed an unbounded generation."
            )
        refresh.update(
            {
                "status": "zero",
                "zero_resource_version": zero_identity["resourceVersion"],
                "zero_generation": zero_generation,
                "zero_at": _utc_now(),
            }
        )
        checkpoint_writer()
    if str(refresh.get("status") or "") != "zero":
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs target writer refresh did not reach its zero-replica fence."
        )

    _legacy_rootfs_target_stage_manager_replicas(
        stage=stage,
        handoff=handoff,
        replicas=_positive_int(_mapping(handoff.get("manager")).get("replicas"), fallback=0),
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )
    target_resource, _target_identity = _legacy_rootfs_target_slurmcluster(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if _sconfigcontroller_replicas(target_resource) != 0:
        raise SoperatorMigrationPhasePending(
            "target SConfig desired size changed after manager restore."
        )
    _legacy_rootfs_wait_target_sconfig_zero(
        deployment_uid=str(stage.get("deployment_uid") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=verification_timeout_seconds,
    )
    _legacy_rootfs_login_jail_digest(
        handoff=handoff,
        expected_sha256=compatible_sha,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    stage["active_login_config_variant"] = "compatible"
    stage["compatible_login_digest_verified_at"] = _utc_now()
    stage["active_config_variant"] = (
        "post-restore-full-target" if post_restore_full_target else "compatible"
    )
    stage["stable_at"] = _utc_now()
    state["status"] = "target-compatibility-active"
    state["target_compatibility_active_at"] = _utc_now()
    checkpoint_writer()
    return [
        "Legacy-rootfs target-only Slurm compatibility is active with the target writer "
        "fenced at zero replicas and no source ServiceAccount reuse."
    ]


def _legacy_rootfs_target_compatibility_is_active(phase: Mapping[str, Any]) -> bool:
    state = _mapping(phase.get("legacy_rootfs_slurm_config_bridge"))
    stage = _mapping(state.get("target_compatibility_stage"))
    fence = _mapping(state.get("writer_fence"))
    refresh = _mapping(stage.get("target_writer_refresh"))
    boundary_intents = _mapping(stage.get("jail_boundary_intents"))
    boundary_rebinds = _mapping(stage.get("jail_boundary_rebinds"))
    boundary_refreshes = _mapping(stage.get("jail_boundary_writer_refreshes"))
    boundary_ids = set(boundary_intents) | set(boundary_rebinds) | set(boundary_refreshes)
    boundary_shape_valid = not boundary_ids
    if boundary_ids == {"active-slot-switch"}:
        boundary_intent = _mapping(boundary_intents.get("active-slot-switch"))
        boundary_rebind = _mapping(boundary_rebinds.get("active-slot-switch"))
        boundary_refresh = _mapping(boundary_refreshes.get("active-slot-switch"))
        boundary_shape_valid = bool(
            boundary_intent
            and re.fullmatch(
                r"[0-9a-f]{64}",
                str(boundary_intent.get("expected_login_jail_submounts_fingerprint") or ""),
            )
            and (
                (not boundary_rebind and not boundary_refresh)
                or (
                    boundary_rebind
                    and re.fullmatch(
                        r"[0-9a-f]{64}",
                        str(boundary_rebind.get("login_jail_submounts_fingerprint") or ""),
                    )
                    and (
                        not boundary_refresh
                        or boundary_refresh.get("status")
                        in {
                            "pending",
                            "scale-up-intent",
                            "writer-ready",
                            "scale-down-intent",
                            "zero",
                            "verified",
                        }
                    )
                )
            )
        )
    return bool(
        state.get("schema") == _LEGACY_ROOTFS_SLURM_CONFIG_BRIDGE_SCHEMA
        and state.get("status") == "target-compatibility-active"
        and fence.get("schema") == _LEGACY_ROOTFS_SCONFIG_WRITER_FENCE_SCHEMA
        and fence.get("status") == "prepared"
        and _positive_int(fence.get("original_size"), fallback=0) > 0
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(fence.get("target_login_jail_submounts_fingerprint") or ""),
        )
        and str(stage.get("deployment_uid") or "").strip()
        and str(stage.get("service_account_name") or "").strip()
        and str(stage.get("service_account_uid") or "").strip()
        and str(stage.get("configmap_uid") or "").strip()
        and str(stage.get("jailed_config_uid") or "").strip()
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("full_target_sha256") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("full_target_data_fingerprint") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("compatible_sha256") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("compatible_data_fingerprint") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("open_metrics_disabled_sha256") or ""))
        and re.fullmatch(
            r"[0-9a-f]{64}",
            str(stage.get("open_metrics_disabled_data_fingerprint") or ""),
        )
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("jailed_config_spec_fingerprint") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(stage.get("jailed_config_items_fingerprint") or ""))
        and _positive_int(stage.get("jailed_config_item_count"), fallback=0) > 0
        and refresh.get("status") == "zero"
        and str(stage.get("stable_at") or "").strip()
        and boundary_shape_valid
    )


def _legacy_rootfs_release_requires_active_zero_revalidation(
    *,
    bridge_status: str,
    release_status: str,
    current_size: int,
    original_size: int,
) -> bool:
    if bridge_status != "target-compatibility-active":
        return False
    if current_size == 0 and release_status in {"pending", "intent"}:
        return True
    if release_status == "intent" and current_size == original_size > 0:
        return False
    raise SoperatorMigrationPhasePending(
        "legacy-rootfs SConfig release checkpoint is inconsistent with live target size."
    )


def _verified_legacy_rootfs_post_open_metrics_topology_replay(
    *,
    phase: Mapping[str, Any],
    prior_topology_replay: Mapping[str, Any] | None,
    target_resource: Mapping[str, Any],
    target_identity: Mapping[str, str],
    target_generation: int,
) -> dict[str, Any] | None:
    """Bind the exact current target to the verified post-handoff values replay."""

    prior_topology_replay = _mapping(prior_topology_replay)
    final_reconciliation = _mapping(phase.get("post_singleton_values_reconciliation"))
    final_proof = _mapping(phase.get("post_singleton_values_proof"))
    target_binding = _mapping(_mapping(phase.get("slurmcluster_handoff_binding")).get("target"))
    normalized_target = {
        key: str(target_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    live_target = {
        key: str(target_identity.get(key) or "").strip() for key in ("namespace", "name", "uid")
    }
    live_spec_fingerprint = _fingerprint(_mapping(target_resource.get("spec")))
    final_proof_fingerprint = _fingerprint(final_proof) if final_proof else ""
    final_fingerprint_fields = (
        "values_fingerprint",
        "installed_manifest_fingerprint",
        "live_spec_fingerprint",
    )
    if final_reconciliation or final_proof:
        if (
            final_reconciliation.get("schema") != _IN_PLACE_TARGET_VALUES_RECONCILIATION_SCHEMA
            or final_reconciliation.get("status") != "verified"
            or final_reconciliation.get("active_jail_slot") != "slot-b"
            or str(final_reconciliation.get("values_fingerprint") or "")
            != str(final_proof.get("values_fingerprint") or "")
            or str(final_reconciliation.get("proof_fingerprint") or "") != final_proof_fingerprint
            or final_proof.get("schema") != _TARGET_HELM_APPLY_PROOF_SCHEMA
            or final_proof.get("status") != "verified"
            or _mapping(final_proof.get("target")) != target_binding
            or not all(normalized_target.values())
            or any(
                live_target[key] and live_target[key] != normalized_target[key]
                for key in live_target
            )
            or live_target["uid"] != normalized_target["uid"]
            or _positive_int(final_proof.get("release_revision"), fallback=0) <= 0
            or str(final_proof.get("live_spec_fingerprint") or "") != live_spec_fingerprint
            or _mapping(final_proof.get("semantic_drift")).get("status") != "compatible"
            or any(
                not re.fullmatch(r"[0-9a-f]{64}", str(final_proof.get(field) or ""))
                for field in final_fingerprint_fields
            )
            or target_generation <= 0
        ):
            return None
        recorded_final_values = _mapping(prior_topology_replay.get("final_values_reconciliation"))
        recorded_final_values_reusable = bool(
            recorded_final_values.get("schema") == _LEGACY_ROOTFS_FINAL_VALUES_REPLAY_SCHEMA
            and recorded_final_values.get("status") == "verified"
            and recorded_final_values.get("active_jail_slot") == "slot-b"
            and str(recorded_final_values.get("values_fingerprint") or "")
            == str(final_proof.get("values_fingerprint") or "")
            and str(recorded_final_values.get("proof_fingerprint") or "") == final_proof_fingerprint
            and _positive_int(prior_topology_replay.get("helm_release_revision"), fallback=0)
            == _positive_int(final_proof.get("release_revision"), fallback=0)
            and _positive_int(prior_topology_replay.get("target_generation"), fallback=0)
            == target_generation
            and str(prior_topology_replay.get("live_spec_fingerprint") or "")
            == live_spec_fingerprint
            and str(prior_topology_replay.get("values_fingerprint") or "")
            == str(final_proof.get("values_fingerprint") or "")
            and str(prior_topology_replay.get("installed_manifest_fingerprint") or "")
            == str(final_proof.get("installed_manifest_fingerprint") or "")
        )
        final_values_binding = (
            copy.deepcopy(to_plain_data(recorded_final_values))
            if recorded_final_values_reusable
            else {
                "schema": _LEGACY_ROOTFS_FINAL_VALUES_REPLAY_SCHEMA,
                "status": "verified",
                "active_jail_slot": "slot-b",
                "values_fingerprint": str(final_proof.get("values_fingerprint") or ""),
                "proof_fingerprint": final_proof_fingerprint,
                "prior_topology_replay_fingerprint": _fingerprint(prior_topology_replay),
            }
        )
        return {
            "schema": _LEGACY_ROOTFS_POST_OPEN_METRICS_TOPOLOGY_REPLAY_SCHEMA,
            "status": "verified",
            "values_revision": _ROLLING_COMPUTE_VALUES_REVISION,
            "helm_release_revision": _positive_int(final_proof.get("release_revision"), fallback=0),
            "target_uid": normalized_target["uid"],
            "target_generation": target_generation,
            "live_spec_fingerprint": live_spec_fingerprint,
            "values_fingerprint": str(final_proof.get("values_fingerprint") or ""),
            "installed_manifest_fingerprint": str(
                final_proof.get("installed_manifest_fingerprint") or ""
            ),
            **(
                {
                    "controller_gate_removal": copy.deepcopy(
                        to_plain_data(prior_topology_replay.get("controller_gate_removal"))
                    )
                }
                if prior_topology_replay.get("controller_gate_removal") is not None
                else {}
            ),
            "final_values_reconciliation": final_values_binding,
        }

    revision = _non_negative_int(phase.get("target_handoff_values_revision"), fallback=0)
    if revision != _ROLLING_COMPUTE_VALUES_REVISION:
        return None
    proof = _mapping(phase.get(f"target_values_reapply_proof_v{revision}"))
    promoted_proof = _mapping(phase.get("target_handoff_values_proof"))
    native_cleanup = _mapping(phase.get("in_place_target_native_controller_ha"))
    admission_window = _mapping(native_cleanup.get("slurmcluster_admission_window"))
    controller_gate_removal_replay: dict[str, Any] | None = None
    proof_live_spec_fingerprint = str(proof.get("live_spec_fingerprint") or "")
    if proof_live_spec_fingerprint != live_spec_fingerprint:
        prior_generation = _positive_int(prior_topology_replay.get("target_generation"), fallback=0)
        prior_removal = _mapping(prior_topology_replay.get("controller_gate_removal"))
        common_successor_proof = bool(
            prior_topology_replay.get("schema")
            == _LEGACY_ROOTFS_POST_OPEN_METRICS_TOPOLOGY_REPLAY_SCHEMA
            and prior_topology_replay.get("status") == "verified"
            and str(prior_topology_replay.get("target_uid") or "") == normalized_target["uid"]
            and prior_generation > 0
            and _non_negative_int(prior_topology_replay.get("values_revision"), fallback=0)
            == revision
            and _positive_int(prior_topology_replay.get("helm_release_revision"), fallback=0)
            == _positive_int(proof.get("release_revision"), fallback=0)
            and str(prior_topology_replay.get("values_fingerprint") or "")
            == str(proof.get("values_fingerprint") or "")
            and str(prior_topology_replay.get("installed_manifest_fingerprint") or "")
            == str(proof.get("installed_manifest_fingerprint") or "")
            and native_cleanup.get("cleanup_status") == "verified"
            and str(native_cleanup.get("controller_gate_removed_at") or "")
            and str(native_cleanup.get("cleaned_at") or "")
            and admission_window.get("schema")
            == "nebius-cxcli/in-place-slurmcluster-admission-window-v1"
            and admission_window.get("status") == "restored"
            and admission_window.get("original_failure_policy") == "Fail"
            and str(admission_window.get("target_uid") or "") == normalized_target["uid"]
            and str(admission_window.get("restored_at") or "")
            and _in_place_target_controller_gate_removed(target_resource)
        )
        recorded_successor = bool(
            common_successor_proof
            and prior_generation == target_generation
            and str(prior_topology_replay.get("live_spec_fingerprint") or "")
            == live_spec_fingerprint
            and prior_removal.get("schema") == _LEGACY_ROOTFS_CONTROLLER_GATE_REMOVAL_REPLAY_SCHEMA
            and prior_removal.get("status") == "verified"
            and _positive_int(prior_removal.get("prior_target_generation"), fallback=0)
            == target_generation - 1
            and str(prior_removal.get("prior_live_spec_fingerprint") or "")
            == proof_live_spec_fingerprint
            and _positive_int(prior_removal.get("target_generation"), fallback=0)
            == target_generation
            and str(prior_removal.get("live_spec_fingerprint") or "") == live_spec_fingerprint
        )
        if recorded_successor:
            controller_gate_removal_replay = copy.deepcopy(to_plain_data(prior_removal))
        elif not (
            common_successor_proof
            and target_generation == prior_generation + 1
            and str(prior_topology_replay.get("live_spec_fingerprint") or "")
            == proof_live_spec_fingerprint
        ):
            return None
        else:
            controller_gate_removal_replay = {
                "schema": _LEGACY_ROOTFS_CONTROLLER_GATE_REMOVAL_REPLAY_SCHEMA,
                "status": "verified",
                "prior_target_generation": prior_generation,
                "prior_live_spec_fingerprint": proof_live_spec_fingerprint,
                "target_generation": target_generation,
                "live_spec_fingerprint": live_spec_fingerprint,
                "controller_gate_removed_at": str(
                    native_cleanup.get("controller_gate_removed_at") or ""
                ),
                "admission_window_uid": str(admission_window.get("uid") or ""),
                "admission_restored_at": str(admission_window.get("restored_at") or ""),
            }
    fingerprint_fields = (
        "values_fingerprint",
        "installed_manifest_fingerprint",
        "live_spec_fingerprint",
    )
    if (
        proof.get("schema") != _TARGET_HELM_APPLY_PROOF_SCHEMA
        or proof.get("status") != "verified"
        or proof != promoted_proof
        or _mapping(proof.get("target")) != target_binding
        or not all(normalized_target.values())
        or any(
            live_target[key] and live_target[key] != normalized_target[key] for key in live_target
        )
        or live_target["uid"] != normalized_target["uid"]
        or _positive_int(proof.get("release_revision"), fallback=0) <= 0
        or (
            proof_live_spec_fingerprint != live_spec_fingerprint
            and controller_gate_removal_replay is None
        )
        or _mapping(proof.get("semantic_drift")).get("status") != "compatible"
        or any(
            not re.fullmatch(r"[0-9a-f]{64}", str(proof.get(field) or ""))
            for field in fingerprint_fields
        )
        or target_generation <= 0
    ):
        return None
    return {
        "schema": _LEGACY_ROOTFS_POST_OPEN_METRICS_TOPOLOGY_REPLAY_SCHEMA,
        "status": "verified",
        "values_revision": revision,
        "helm_release_revision": _positive_int(proof.get("release_revision"), fallback=0),
        "target_uid": normalized_target["uid"],
        "target_generation": target_generation,
        "live_spec_fingerprint": live_spec_fingerprint,
        "values_fingerprint": str(proof.get("values_fingerprint") or ""),
        "installed_manifest_fingerprint": str(proof.get("installed_manifest_fingerprint") or ""),
        **(
            {"controller_gate_removal": controller_gate_removal_replay}
            if controller_gate_removal_replay is not None
            else {}
        ),
    }


def _legacy_rootfs_controller_gate_replay_successor(
    *,
    checkpointed: Mapping[str, Any],
    proposed: Mapping[str, Any],
) -> bool:
    removal = _mapping(proposed.get("controller_gate_removal"))
    stable_keys = (
        "schema",
        "status",
        "values_revision",
        "helm_release_revision",
        "target_uid",
        "values_fingerprint",
        "installed_manifest_fingerprint",
        "config",
    )
    return bool(
        removal.get("schema") == _LEGACY_ROOTFS_CONTROLLER_GATE_REMOVAL_REPLAY_SCHEMA
        and removal.get("status") == "verified"
        and all(checkpointed.get(key) == proposed.get(key) for key in stable_keys)
        and _positive_int(removal.get("prior_target_generation"), fallback=0)
        == _positive_int(checkpointed.get("target_generation"), fallback=0)
        and str(removal.get("prior_live_spec_fingerprint") or "")
        == str(checkpointed.get("live_spec_fingerprint") or "")
        and _positive_int(proposed.get("target_generation"), fallback=0)
        == _positive_int(checkpointed.get("target_generation"), fallback=0) + 1
        and str(proposed.get("live_spec_fingerprint") or "")
        == str(removal.get("live_spec_fingerprint") or "")
    )


def _legacy_rootfs_final_values_replay_successor(
    *,
    checkpointed: Mapping[str, Any],
    proposed: Mapping[str, Any],
) -> bool:
    final_values = _mapping(proposed.get("final_values_reconciliation"))
    stable_keys = (
        "schema",
        "status",
        "values_revision",
        "target_uid",
        "controller_gate_removal",
        "config",
    )
    return bool(
        checkpointed.get("final_values_reconciliation") is None
        and final_values.get("schema") == _LEGACY_ROOTFS_FINAL_VALUES_REPLAY_SCHEMA
        and final_values.get("status") == "verified"
        and final_values.get("active_jail_slot") == "slot-b"
        and all(checkpointed.get(key) == proposed.get(key) for key in stable_keys)
        and str(final_values.get("values_fingerprint") or "")
        == str(proposed.get("values_fingerprint") or "")
        and re.fullmatch(r"[0-9a-f]{64}", str(final_values.get("proof_fingerprint") or ""))
        and str(final_values.get("prior_topology_replay_fingerprint") or "")
        == _fingerprint(checkpointed)
        and _positive_int(proposed.get("helm_release_revision"), fallback=0)
        >= _positive_int(checkpointed.get("helm_release_revision"), fallback=0)
        and _positive_int(proposed.get("target_generation"), fallback=0)
        >= _positive_int(checkpointed.get("target_generation"), fallback=0)
        and re.fullmatch(r"[0-9a-f]{64}", str(proposed.get("installed_manifest_fingerprint") or ""))
        and re.fullmatch(r"[0-9a-f]{64}", str(proposed.get("live_spec_fingerprint") or ""))
    )


def _legacy_rootfs_bridge_client_config_replay_successor(
    *,
    phase: Mapping[str, Any],
    checkpointed: Mapping[str, Any],
    proposed: Mapping[str, Any],
) -> bool:
    """Accept only the separately proven in-place bridge client config delta."""

    checkpointed_without_config = {
        key: value for key, value in checkpointed.items() if key != "config"
    }
    proposed_without_config = {key: value for key, value in proposed.items() if key != "config"}
    checkpointed_config = _mapping(checkpointed.get("config"))
    proposed_config = _mapping(proposed.get("config"))
    handoff = _mapping(phase.get("in_place_bridge_client_handoff"))
    propagation = _mapping(handoff.get("propagation"))
    config_sha256 = str(handoff.get("config_sha256") or "")
    return bool(
        checkpointed_without_config == proposed_without_config
        and checkpointed_config.get("directive_counts") == proposed_config.get("directive_counts")
        and handoff.get("status") == "verified"
        and propagation.get("status") == "verified"
        and propagation.get("live_rpc_verified") is True
        and re.fullmatch(r"[0-9a-f]{64}", config_sha256)
        and str(propagation.get("config_sha256") or "") == config_sha256
        and str(proposed_config.get("full_sha256") or "") == config_sha256
    )


def _legacy_rootfs_typed_gres_values_replay_successor(
    *,
    phase: Mapping[str, Any],
    checkpointed: Mapping[str, Any],
    proposed: Mapping[str, Any],
) -> bool:
    """Accept only the Helm-proven typed-GRES values revision successor."""

    replay = _mapping(phase.get("gpu_topology_values_replay"))
    previous_topology = _mapping(replay.get("topology_by_nodeset"))
    current_topology = _mapping(phase.get("worker_topology_by_nodeset"))
    nodeset_names = tuple(sorted(current_topology))
    revision = _non_negative_int(phase.get("target_handoff_values_revision"), fallback=0)
    proof = _mapping(phase.get(f"target_values_reapply_proof_v{revision}"))
    promoted_proof = _mapping(phase.get("target_handoff_values_proof"))
    stable_keys = (
        "schema",
        "status",
        "target_uid",
        "target_generation",
        "live_spec_fingerprint",
        "installed_manifest_fingerprint",
    )
    return bool(
        replay.get("schema") == _GPU_TOPOLOGY_VALUES_REPLAY_SCHEMA
        and replay.get("status") == "verified"
        and revision == _ROLLING_COMPUTE_VALUES_REVISION
        and _non_negative_int(checkpointed.get("values_revision"), fallback=-1) == revision - 1
        and _non_negative_int(proposed.get("values_revision"), fallback=-1) == revision
        and all(checkpointed.get(key) == proposed.get(key) for key in stable_keys)
        and (
            checkpointed.get("config") == proposed.get("config")
            or _legacy_rootfs_bridge_client_config_replay_successor(
                phase=phase,
                checkpointed=checkpointed,
                proposed={**checkpointed, "config": proposed.get("config")},
            )
        )
        and _gpu_topology_gres_only_successor(
            previous=previous_topology,
            current=current_topology,
            nodeset_names=nodeset_names,
        )
        and proof.get("schema") == _TARGET_HELM_APPLY_PROOF_SCHEMA
        and proof.get("status") == "verified"
        and proof == promoted_proof
        and _mapping(proof.get("semantic_drift")).get("status") == "compatible"
        and str(_mapping(proof.get("target")).get("uid") or "")
        == str(proposed.get("target_uid") or "")
        and _positive_int(proof.get("release_revision"), fallback=0)
        == _positive_int(proposed.get("helm_release_revision"), fallback=0)
        and _positive_int(proposed.get("helm_release_revision"), fallback=0)
        > _positive_int(checkpointed.get("helm_release_revision"), fallback=0)
        and str(proof.get("values_fingerprint") or "")
        == str(proposed.get("values_fingerprint") or "")
        and str(proof.get("installed_manifest_fingerprint") or "")
        == str(proposed.get("installed_manifest_fingerprint") or "")
    )


def _legacy_rootfs_post_open_metrics_typed_gres_helm_successor(
    *,
    bridge_phase: Mapping[str, Any],
    checkpointed: Mapping[str, Any],
    proposed: Mapping[str, Any],
    checkpointed_replay: Mapping[str, Any],
    proposed_replay: Mapping[str, Any],
) -> bool:
    """Accept the outer Helm binding only with its exact typed-GRES successor."""

    repair = _mapping(bridge_phase.get("gpu_driver_jail_init_repair"))
    downstream = _mapping(repair.get("post_repair_helm_reconciliation"))
    history = repair.get("post_repair_helm_reconciliation_history")
    if not isinstance(history, list) or not history:
        return False
    prior = _mapping(history[-1])
    stable_keys = (
        "schema",
        "status",
        "target_uid",
        "configmap_uid",
        "directive_counts",
        "restore_intent_at",
        "restored_at",
    )
    return bool(
        downstream.get("schema") == _GPU_DRIVER_JAIL_POST_REPAIR_HELM_SCHEMA
        and downstream.get("status") == "verified"
        and downstream.get("boundary") == "open-metrics-restore"
        and downstream.get("successor") == "typed-gres-topology-values-replay"
        and prior.get("schema") == _GPU_DRIVER_JAIL_POST_REPAIR_HELM_SCHEMA
        and prior.get("status") == "verified"
        and prior.get("boundary") == "open-metrics-restore"
        and prior.get("restore_intent_at") == downstream.get("restore_intent_at")
        and prior.get("restored_at") == downstream.get("restored_at")
        and all(checkpointed.get(key) == proposed.get(key) for key in stable_keys)
        and _positive_int(checkpointed.get("helm_release_revision"), fallback=0)
        == _positive_int(prior.get("release_revision"), fallback=0)
        and str(checkpointed.get("helm_values_fingerprint") or "")
        == str(prior.get("values_fingerprint") or "")
        and str(checkpointed.get("helm_manifest_fingerprint") or "")
        == str(prior.get("installed_manifest_fingerprint") or "")
        and _positive_int(proposed.get("helm_release_revision"), fallback=0)
        == _positive_int(downstream.get("release_revision"), fallback=0)
        and str(proposed.get("helm_values_fingerprint") or "")
        == str(downstream.get("values_fingerprint") or "")
        and str(proposed.get("helm_manifest_fingerprint") or "")
        == str(downstream.get("installed_manifest_fingerprint") or "")
        and _positive_int(proposed.get("helm_release_revision"), fallback=0)
        > _positive_int(checkpointed.get("helm_release_revision"), fallback=0)
        and _legacy_rootfs_typed_gres_values_replay_successor(
            phase=bridge_phase,
            checkpointed=checkpointed_replay,
            proposed=proposed_replay,
        )
    )


def _legacy_rootfs_bind_post_open_metrics_config(
    *,
    bridge_phase: Mapping[str, Any],
    stage: Mapping[str, Any],
    release: dict[str, Any],
    open_metrics_state: Mapping[str, Any],
    target_resource: Mapping[str, Any],
    target_identity: Mapping[str, str],
    target_generation: int,
    config_map: Mapping[str, Any],
    config_map_identity: Mapping[str, str],
    checkpoint_writer: Callable[[], None],
) -> Mapping[str, Any]:
    """Bind one exact manager reconciliation after the OpenMetrics Helm restore."""

    desired_open_metrics = open_metrics_state.get("desired_enabled")
    observed_open_metrics = _slurmcluster_controller_open_metrics_enabled(target_resource)
    if desired_open_metrics is not True or observed_open_metrics is not True:
        return {}
    downstream = _mapping(
        _mapping(bridge_phase.get("gpu_driver_jail_init_repair")).get(
            "post_repair_helm_reconciliation"
        )
    )
    legacy_generation = (
        target_generation
        == _positive_int(release.get("target_size_expected_generation"), fallback=0) + 1
    )
    topology_replay = _verified_legacy_rootfs_post_open_metrics_topology_replay(
        phase=bridge_phase,
        prior_topology_replay=_mapping(
            _mapping(release.get("post_open_metrics_config")).get("topology_values_replay")
        ),
        target_resource=target_resource,
        target_identity=target_identity,
        target_generation=target_generation,
    )
    if (
        str(open_metrics_state.get("status") or "") != "restored"
        or str(open_metrics_state.get("slurmcluster_uid") or "")
        != str(target_identity.get("uid") or "")
        or release.get("status") != "verified"
        or str(release.get("target_uid") or "") != str(target_identity.get("uid") or "")
        or (not legacy_generation and topology_replay is None)
        or downstream.get("schema") != _GPU_DRIVER_JAIL_POST_REPAIR_HELM_SCHEMA
        or downstream.get("status") != "verified"
        or downstream.get("boundary") != "open-metrics-restore"
        or downstream.get("restore_intent_at") != open_metrics_state.get("restore_intent_at")
        or downstream.get("restored_at") != open_metrics_state.get("restored_at")
    ):
        raise SoperatorMigrationPhasePending(
            "post-OpenMetrics Slurm ConfigMap lacks the exact checkpointed Helm and "
            "target-generation proof."
        )
    if topology_replay is None:
        normalized_target = copy.deepcopy(to_plain_data(target_resource))
        normalized_open_metrics = _mapping(
            _mapping(
                _mapping(_mapping(normalized_target.get("spec")).get("slurmNodes")).get(
                    "controller"
                )
            ).get("openMetrics")
        )
        if not isinstance(normalized_open_metrics, dict):
            raise SoperatorMigrationPhasePending(
                "post-OpenMetrics target SlurmCluster has a malformed controller contract."
            )
        normalized_open_metrics["enabled"] = False
        if _legacy_rootfs_slurmcluster_fence_fingerprint(normalized_target) != str(
            release.get("target_spec_fingerprint") or ""
        ):
            raise SoperatorMigrationPhasePending(
                "post-OpenMetrics target SlurmCluster drifted outside its single Helm generation."
            )
    if str(config_map_identity.get("uid") or "") != str(release.get("configmap_uid") or "") or str(
        config_map_identity.get("uid") or ""
    ) != str(stage.get("configmap_uid") or ""):
        raise SoperatorMigrationPhasePending(
            "post-OpenMetrics Slurm ConfigMap identity drifted from the released writer."
        )
    live_config = _legacy_rootfs_bridge_config_text(config_map)
    live_sha = hashlib.sha256(live_config.encode("utf-8")).hexdigest()
    live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(config_map)
    compatible_config, directive_counts = _legacy_rootfs_slurm_config_bridge_text(live_config)
    expected_counts = dict(_mapping(stage.get("directive_counts")))
    expected_counts["metrics_type"] = (
        _positive_int(expected_counts.get("metrics_type"), fallback=0) + 1
    )
    if directive_counts != expected_counts:
        raise SoperatorMigrationPhasePending(
            "post-OpenMetrics Slurm ConfigMap changed outside the exact directive delta."
        )
    compatible_map = copy.deepcopy(to_plain_data(config_map))
    compatible_data = compatible_map.get("data")
    if not isinstance(compatible_data, dict):
        raise SoperatorMigrationPhasePending("post-OpenMetrics Slurm ConfigMap data is malformed.")
    compatible_data["slurm.conf"] = compatible_config
    proposed = {
        "schema": _LEGACY_ROOTFS_POST_OPEN_METRICS_CONFIG_SCHEMA,
        "status": "verified",
        "target_uid": str(target_identity.get("uid") or ""),
        "target_generation": target_generation,
        "configmap_uid": str(config_map_identity.get("uid") or ""),
        "full_sha256": live_sha,
        "full_data_fingerprint": live_data_fingerprint,
        "compatible_sha256": hashlib.sha256(compatible_config.encode("utf-8")).hexdigest(),
        "compatible_data_fingerprint": _legacy_rootfs_configmap_data_fingerprint(compatible_map),
        "directive_counts": directive_counts,
        "helm_release_revision": _positive_int(downstream.get("release_revision"), fallback=0),
        "helm_values_fingerprint": str(downstream.get("values_fingerprint") or ""),
        "helm_manifest_fingerprint": str(downstream.get("installed_manifest_fingerprint") or ""),
        "restore_intent_at": str(open_metrics_state.get("restore_intent_at") or ""),
        "restored_at": str(open_metrics_state.get("restored_at") or ""),
    }
    topology_config = {
        key: proposed[key]
        for key in (
            "full_sha256",
            "full_data_fingerprint",
            "compatible_sha256",
            "compatible_data_fingerprint",
            "directive_counts",
        )
    }
    topology_binding = {**topology_replay, "config": topology_config} if topology_replay else None
    proof = release.get("post_open_metrics_config")
    if proof is None:
        release["post_open_metrics_config"] = {
            **proposed,
            **({"topology_values_replay": topology_binding} if topology_binding else {}),
            "configmap_resource_version": str(config_map_identity.get("resourceVersion") or ""),
            "verified_at": _utc_now(),
        }
        checkpoint_writer()
        return _mapping(release.get("post_open_metrics_config"))
    immutable_keys = (
        "schema",
        "status",
        "target_uid",
        "configmap_uid",
        "directive_counts",
        "helm_release_revision",
        "helm_values_fingerprint",
        "helm_manifest_fingerprint",
        "restore_intent_at",
        "restored_at",
    )
    expected_proposed = (
        {key: proposed[key] for key in immutable_keys}
        if topology_binding is not None
        else {key: value for key, value in proposed.items() if key != "target_generation"}
    )
    expected_proof_generations = {
        _positive_int(release.get("target_size_expected_generation"), fallback=0) + 1
    }
    if topology_binding is not None:
        expected_proof_generations.add(
            _positive_int(topology_binding.get("target_generation"), fallback=0)
        )
    checkpointed_replay = (
        proof.get("topology_values_replay") if isinstance(proof, Mapping) else None
    )
    typed_gres_helm_successor = bool(
        topology_binding is not None
        and checkpointed_replay is not None
        and _legacy_rootfs_post_open_metrics_typed_gres_helm_successor(
            bridge_phase=bridge_phase,
            checkpointed=_mapping(proof),
            proposed=proposed,
            checkpointed_replay=_mapping(checkpointed_replay),
            proposed_replay=topology_binding,
        )
    )
    if (
        not isinstance(proof, Mapping)
        or (
            any(proof.get(key) != value for key, value in expected_proposed.items())
            and not typed_gres_helm_successor
        )
        or _positive_int(proof.get("target_generation"), fallback=0)
        not in expected_proof_generations
    ):
        raise SoperatorMigrationPhasePending(
            "post-OpenMetrics Slurm ConfigMap drifted from its exact checkpointed proof."
        )
    if typed_gres_helm_successor:
        if not isinstance(proof, dict):
            raise SoperatorMigrationPhasePending(
                "post-OpenMetrics typed-GRES Helm successor proof is not durably writable."
            )
        proof.update(
            {
                "helm_release_revision": proposed["helm_release_revision"],
                "helm_values_fingerprint": proposed["helm_values_fingerprint"],
                "helm_manifest_fingerprint": proposed["helm_manifest_fingerprint"],
            }
        )
    if topology_binding is not None:
        if checkpointed_replay is None:
            if not isinstance(proof, dict):
                raise SoperatorMigrationPhasePending(
                    "post-OpenMetrics topology replay proof is not durably writable."
                )
            proof["topology_values_replay"] = topology_binding
            checkpoint_writer()
        elif checkpointed_replay != topology_binding:
            checkpointed_replay_mapping = _mapping(checkpointed_replay)
            if not (
                _legacy_rootfs_controller_gate_replay_successor(
                    checkpointed=checkpointed_replay_mapping,
                    proposed=topology_binding,
                )
                or _legacy_rootfs_final_values_replay_successor(
                    checkpointed=checkpointed_replay_mapping,
                    proposed=topology_binding,
                )
                or _legacy_rootfs_bridge_client_config_replay_successor(
                    phase=bridge_phase,
                    checkpointed=checkpointed_replay_mapping,
                    proposed=topology_binding,
                )
                or _legacy_rootfs_typed_gres_values_replay_successor(
                    phase=bridge_phase,
                    checkpointed=checkpointed_replay_mapping,
                    proposed=topology_binding,
                )
            ):
                raise SoperatorMigrationPhasePending(
                    "post-OpenMetrics topology replay drifted from its exact checkpointed proof."
                )
            if not isinstance(proof, dict):
                raise SoperatorMigrationPhasePending(
                    "post-OpenMetrics topology successor proof is not durably writable."
                )
            proof["topology_values_replay"] = topology_binding
            checkpoint_writer()
    elif checkpointed_replay is not None:
        raise SoperatorMigrationPhasePending(
            "post-OpenMetrics topology replay lost its exact live Helm proof."
        )
    return proof


def _release_legacy_rootfs_sconfig_writer_after_slot_verification(
    *,
    bridge_phase: dict[str, Any],
    handoff_verification: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    rootfs_pvc: str,
    open_metrics_handoff: Mapping[str, Any] | None = None,
    verification_timeout_seconds: int = 300,
    poll_interval_seconds: float = 2.0,
) -> list[str]:
    """Release the target writer only after all other rootfs consumers prove slot-b."""

    raw_state = _mapping(bridge_phase.get("legacy_rootfs_slurm_config_bridge"))
    bridge_status = str(raw_state.get("status") or "").strip()
    if bridge_status not in {"target-compatibility-active", "released"}:
        return []
    state = _legacy_rootfs_slurm_config_bridge_state(bridge_phase)
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig writer release requires durable checkpoint writes."
        )
    accepted_handoff_statuses = (
        {"consumers-verified-with-sconfig-fenced"}
        if bridge_status == "target-compatibility-active"
        else {"consumers-verified-with-sconfig-released", "verified"}
    )
    if (
        handoff_verification.get("status") not in accepted_handoff_statuses
        or str(handoff_verification.get("active_pvc") or "").strip() != rootfs_pvc
        or not str(
            handoff_verification.get("staged_verified_at")
            or handoff_verification.get("released_consumers_verified_at")
            or ""
        ).strip()
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig writer release requires the durable non-SConfig slot proof."
        )
    stage = _mapping(state.get("target_compatibility_stage"))
    expected_deployment_fingerprint = str(stage.get("deployment_spec_fingerprint") or "")
    if not expected_deployment_fingerprint:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig release lacks the rebound Deployment spec fingerprint."
        )
    boundary_rebind = _mapping(
        _mapping(stage.get("jail_boundary_rebinds")).get("active-slot-switch")
    )
    boundary_refresh = _mapping(
        _mapping(stage.get("jail_boundary_writer_refreshes")).get("active-slot-switch")
    )
    if (
        boundary_rebind.get("rootfs_pvc") != rootfs_pvc
        or boundary_refresh.get("status") != "verified"
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig release lacks the verified slot-bound compatible writer pulse."
        )
    fence = _mapping(state.get("writer_fence"))
    release = state.setdefault("target_writer_release", {"status": "pending"})
    if not isinstance(release, dict):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig writer-release checkpoint is malformed."
        )
    handoff = _immutable_child_handoff_state(bridge_phase)
    target_resource, target_identity = _legacy_rootfs_target_slurmcluster(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    original_size = _positive_int(fence.get("original_size"), fallback=0)
    current_size = _sconfigcontroller_replicas(target_resource)
    target_generation = _legacy_rootfs_positive_generation(
        target_resource,
        label="target SlurmCluster SConfig writer release",
    )
    target_spec_fingerprint = _legacy_rootfs_slurmcluster_fence_fingerprint(target_resource)
    release_status = str(release.get("status") or "pending")
    if _legacy_rootfs_release_requires_active_zero_revalidation(
        bridge_status=bridge_status,
        release_status=release_status,
        current_size=current_size,
        original_size=original_size,
    ):
        _revalidate_legacy_rootfs_target_compatibility_active(
            phase=bridge_phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    open_metrics_state = _mapping(open_metrics_handoff)
    desired_open_metrics = open_metrics_state.get("desired_enabled")
    observed_open_metrics = _slurmcluster_controller_open_metrics_enabled(target_resource)
    post_open_metrics_recovery = bool(
        bridge_status == "released"
        and str(open_metrics_state.get("status") or "") in {"restore-intent-recorded", "restored"}
        and isinstance(desired_open_metrics, bool)
        and observed_open_metrics is desired_open_metrics
        and str(open_metrics_state.get("slurmcluster_uid") or "") == target_identity["uid"]
    )

    def _pre_open_metrics_target_fingerprint(resource: Mapping[str, Any]) -> str:
        normalized_resource = copy.deepcopy(to_plain_data(resource))
        open_metrics = _mapping(
            _mapping(
                _mapping(_mapping(normalized_resource.get("spec")).get("slurmNodes")).get(
                    "controller"
                )
            ).get("openMetrics")
        )
        if not isinstance(open_metrics, dict):
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster OpenMetrics recovery state is malformed."
            )
        open_metrics["enabled"] = False
        return _legacy_rootfs_slurmcluster_fence_fingerprint(normalized_resource)

    if (
        original_size <= 0
        or target_identity["uid"] != str(fence.get("target_uid") or "")
        or current_size not in {0, original_size}
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig release found target size/UID outside its fence."
        )
    if observed_open_metrics is not False and not post_open_metrics_recovery:
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig release refuses to restore OpenMetrics before full slot proof."
        )
    target_config_binding = _mapping(state.get("configmap"))
    target_config_map = _legacy_rootfs_bridge_optional_resource(
        resource_type="configmap",
        name=str(target_config_binding.get("name") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if target_config_map is None:
        raise SoperatorMigrationPhasePending(
            "target Slurm ConfigMap disappeared before SConfig writer release."
        )
    target_config_identity = _immutable_child_require_live_uid(
        target_config_map,
        expected_uid=str(stage.get("configmap_uid") or ""),
        label="target Slurm ConfigMap writer release",
    )
    _legacy_rootfs_bridge_controller_owner(
        target_config_map,
        allowed_bindings={
            "target": _legacy_rootfs_bridge_binding(
                _mapping(handoff.get("target")), label="target SlurmCluster"
            )
        },
        label="target Slurm ConfigMap writer release",
    )
    post_open_metrics_config = (
        _legacy_rootfs_bind_post_open_metrics_config(
            bridge_phase=bridge_phase,
            stage=stage,
            release=release,
            open_metrics_state=open_metrics_state,
            target_resource=target_resource,
            target_identity=target_identity,
            target_generation=target_generation,
            config_map=target_config_map,
            config_map_identity=target_config_identity,
            checkpoint_writer=checkpoint_writer,
        )
        if post_open_metrics_recovery
        else {}
    )
    post_open_metrics_config_active = bool(post_open_metrics_config)
    topology_replay = _mapping(post_open_metrics_config.get("topology_values_replay"))
    topology_config = _mapping(topology_replay.get("config"))
    topology_replay_active = bool(
        topology_replay.get("schema") == _LEGACY_ROOTFS_POST_OPEN_METRICS_TOPOLOGY_REPLAY_SCHEMA
        and topology_replay.get("status") == "verified"
        and topology_replay.get("target_uid") == target_identity["uid"]
    )
    if not post_open_metrics_config_active:
        _legacy_rootfs_configmap_compatible_transform(
            config_map=target_config_map,
            stage=stage,
        )
    _legacy_rootfs_target_jailed_config_files(
        state=state,
        stage=stage,
        handoff=handoff,
        config_map=target_config_map,
        command_runner=command_runner,
        kube_context=kube_context,
        initialize=False,
    )
    live_config = _legacy_rootfs_bridge_config_text(target_config_map)
    live_sha = hashlib.sha256(live_config.encode("utf-8")).hexdigest()
    live_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(target_config_map)
    compatible_sha = str(stage.get("compatible_sha256") or "")
    compatible_data_fingerprint = str(stage.get("compatible_data_fingerprint") or "")
    pre_metrics_sha = str(stage.get("open_metrics_disabled_sha256") or "")
    pre_metrics_data_fingerprint = str(stage.get("open_metrics_disabled_data_fingerprint") or "")
    expected_full_sha = str(release.get("expected_full_sha256") or "")
    if not expected_full_sha:
        if current_size != 0:
            raise SoperatorMigrationPhasePending(
                "target SConfig size was restored without a durable writer-release intent."
            )
        expected_full_sha = str(stage.get("full_target_sha256") or "")
        expected_full_data_fingerprint = str(stage.get("full_target_data_fingerprint") or "")
        if (
            not re.fullmatch(r"[0-9a-f]{64}", expected_full_sha)
            or not re.fullmatch(r"[0-9a-f]{64}", expected_full_data_fingerprint)
            or (live_sha, live_data_fingerprint)
            not in {
                (compatible_sha, compatible_data_fingerprint),
                (pre_metrics_sha, pre_metrics_data_fingerprint),
            }
        ):
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap changed before writer-release intent."
            )
        release.update(
            {
                "status": "intent",
                "target_uid": target_identity["uid"],
                "deployment_uid": str(stage.get("deployment_uid") or ""),
                "service_account_name": str(stage.get("service_account_name") or ""),
                "service_account_uid": str(stage.get("service_account_uid") or ""),
                "configmap_uid": target_config_identity["uid"],
                "compatible_sha256": compatible_sha,
                "compatible_data_fingerprint": compatible_data_fingerprint,
                "expected_pre_metrics_sha256": pre_metrics_sha,
                "expected_pre_metrics_data_fingerprint": pre_metrics_data_fingerprint,
                "expected_full_sha256": expected_full_sha,
                "expected_full_data_fingerprint": expected_full_data_fingerprint,
                "rootfs_pvc": rootfs_pvc,
                "target_size_intent_resource_version": target_identity["resourceVersion"],
                "target_size_patch_resource_version": target_identity["resourceVersion"],
                "target_size_from_generation": target_generation,
                "target_size_expected_generation": target_generation + 1,
                "target_spec_fingerprint": target_spec_fingerprint,
                "intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
    elif (
        str(release.get("target_uid") or "") != target_identity["uid"]
        or str(release.get("rootfs_pvc") or "") != rootfs_pvc
        or str(release.get("deployment_uid") or "") != str(stage.get("deployment_uid") or "")
        or str(release.get("service_account_uid") or "")
        != str(stage.get("service_account_uid") or "")
        or str(release.get("compatible_sha256") or "") != compatible_sha
        or str(release.get("compatible_data_fingerprint") or "") != compatible_data_fingerprint
        or str(release.get("expected_pre_metrics_sha256") or "") != pre_metrics_sha
        or str(release.get("expected_pre_metrics_data_fingerprint") or "")
        != pre_metrics_data_fingerprint
        or str(release.get("expected_full_sha256") or "")
        != str(stage.get("full_target_sha256") or "")
        or str(release.get("expected_full_data_fingerprint") or "")
        != str(stage.get("full_target_data_fingerprint") or "")
        or (
            (live_sha, live_data_fingerprint)
            not in {
                (compatible_sha, compatible_data_fingerprint),
                (
                    expected_full_sha
                    if post_open_metrics_recovery and desired_open_metrics is True
                    else pre_metrics_sha,
                    str(release.get("expected_full_data_fingerprint") or "")
                    if post_open_metrics_recovery and desired_open_metrics is True
                    else pre_metrics_data_fingerprint,
                ),
            }
            and not post_open_metrics_recovery
        )
        or (
            _pre_open_metrics_target_fingerprint(target_resource)
            if post_open_metrics_recovery
            else target_spec_fingerprint
        )
        != str(release.get("target_spec_fingerprint") or "")
        and not topology_replay_active
    ):
        raise SoperatorMigrationPhasePending(
            "legacy-rootfs SConfig writer-release identity or config digest drifted."
        )
    if current_size == 0:
        if target_generation != _positive_int(
            release.get("target_size_from_generation"), fallback=0
        ):
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster changed after SConfig writer-release intent."
            )
        if (
            str(release.get("target_size_patch_resource_version") or "")
            != target_identity["resourceVersion"]
        ):
            release["target_size_patch_resource_version"] = target_identity["resourceVersion"]
            release["target_size_patch_rv_refreshed_at"] = _utc_now()
            checkpoint_writer()
        if mutation_guard is not None:
            mutation_guard()
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"slurmcluster/{_mapping(handoff.get('target')).get('name')}",
            patch={
                "metadata": {"resourceVersion": target_identity["resourceVersion"]},
                "spec": {"sConfigController": {"node": {"size": original_size}}},
            },
            patch_via_stdin=True,
        )
    deadline = time.monotonic() + max(verification_timeout_seconds, 0)
    expected_runtime_sha = (
        str(
            (
                topology_config.get("full_sha256")
                if topology_replay_active
                else post_open_metrics_config.get("full_sha256")
            )
            or ""
        )
        if post_open_metrics_config_active
        else pre_metrics_sha
    )
    expected_runtime_data_fingerprint = (
        str(
            (
                topology_config.get("full_data_fingerprint")
                if topology_replay_active
                else post_open_metrics_config.get("full_data_fingerprint")
            )
            or ""
        )
        if post_open_metrics_config_active
        else pre_metrics_data_fingerprint
    )
    verified_config_sha = expected_runtime_sha
    verified_jailed_files: tuple[tuple[str, str, str], ...] = ()
    while True:
        target_resource, target_identity = _legacy_rootfs_target_slurmcluster(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        target_generation = _legacy_rootfs_positive_generation(
            target_resource,
            label="target SlurmCluster SConfig writer release proof",
        )
        expected_release_generation = _positive_int(
            release.get("target_size_expected_generation"), fallback=0
        )
        expected_live_generation = (
            _positive_int(topology_replay.get("target_generation"), fallback=0)
            if topology_replay_active
            else (
                expected_release_generation + 1
                if post_open_metrics_recovery and desired_open_metrics is True
                else expected_release_generation
            )
        )
        observed_release_fingerprint = (
            _fingerprint(_mapping(target_resource.get("spec")))
            if topology_replay_active
            else (
                _pre_open_metrics_target_fingerprint(target_resource)
                if post_open_metrics_recovery
                else _legacy_rootfs_slurmcluster_fence_fingerprint(target_resource)
            )
        )
        expected_release_fingerprint = str(
            (
                topology_replay.get("live_spec_fingerprint")
                if topology_replay_active
                else release.get("target_spec_fingerprint")
            )
            or ""
        )
        if (
            target_generation != expected_live_generation
            or observed_release_fingerprint != expected_release_fingerprint
        ):
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster SConfig release crossed an unbounded generation."
            )
        if (
            _slurmcluster_controller_open_metrics_enabled(target_resource) is not False
            and not post_open_metrics_recovery
        ):
            raise SoperatorMigrationPhasePending(
                "OpenMetrics changed before SConfig slot-b release verification completed."
            )
        deployment, deployment_identity, service_account_name, service_account_identity = (
            _legacy_rootfs_target_sconfig_binding(
                state=state,
                handoff=handoff,
                command_runner=command_runner,
                kube_context=kube_context,
            )
        )
        if (
            deployment_identity["uid"] != str(release.get("deployment_uid") or "")
            or service_account_name != str(release.get("service_account_name") or "")
            or service_account_identity["uid"] != str(release.get("service_account_uid") or "")
            or _legacy_rootfs_scalable_spec_fingerprint(
                deployment,
                label="target SConfig Deployment writer release",
            )
            != expected_deployment_fingerprint
        ):
            raise SoperatorMigrationPhasePending(
                "target SConfig Deployment/ServiceAccount changed during writer release."
            )
        config_map = _legacy_rootfs_bridge_optional_resource(
            resource_type="configmap",
            name=str(target_config_binding.get("name") or ""),
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if config_map is None:
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap disappeared during writer release."
            )
        _immutable_child_require_live_uid(
            config_map,
            expected_uid=str(release.get("configmap_uid") or ""),
            label="target Slurm ConfigMap writer release",
        )
        _legacy_rootfs_bridge_controller_owner(
            config_map,
            allowed_bindings={
                "target": _legacy_rootfs_bridge_binding(
                    _mapping(handoff.get("target")), label="target SlurmCluster"
                )
            },
            label="target Slurm ConfigMap writer release",
        )
        if not post_open_metrics_config_active:
            _legacy_rootfs_configmap_compatible_transform(
                config_map=config_map,
                stage=stage,
            )
        config_sha = hashlib.sha256(
            _legacy_rootfs_bridge_config_text(config_map).encode("utf-8")
        ).hexdigest()
        config_data_fingerprint = _legacy_rootfs_configmap_data_fingerprint(config_map)
        jailed_files = _legacy_rootfs_target_jailed_config_files(
            state=state,
            stage=stage,
            handoff=handoff,
            config_map=config_map,
            command_runner=command_runner,
            kube_context=kube_context,
            initialize=False,
        )
        if (config_sha, config_data_fingerprint) not in {
            (compatible_sha, compatible_data_fingerprint),
            (pre_metrics_sha, pre_metrics_data_fingerprint),
            (
                expected_full_sha,
                str(release.get("expected_full_data_fingerprint") or ""),
            ),
            (
                str(post_open_metrics_config.get("full_sha256") or ""),
                str(post_open_metrics_config.get("full_data_fingerprint") or ""),
            ),
            (
                str(topology_config.get("full_sha256") or ""),
                str(topology_config.get("full_data_fingerprint") or ""),
            ),
        }:
            raise SoperatorMigrationPhasePending(
                "target Slurm ConfigMap changed outside exact compatible/release data variants."
            )
        if (
            _sconfigcontroller_replicas(target_resource) == original_size
            and _resource_replicas(deployment, default=-1) == original_size
            and (config_sha, config_data_fingerprint)
            == (expected_runtime_sha, expected_runtime_data_fingerprint)
        ):
            verified_config_sha = config_sha
            verified_jailed_files = jailed_files
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target SConfig writer did not reconcile the full config after slot proof."
            )
        time.sleep(max(poll_interval_seconds, 0.0))
    _ready_deployment, ready_pod = _legacy_rootfs_bridge_wait_jail_digest(
        expected_sha256=verified_config_sha,
        deployment_uid=str(release.get("deployment_uid") or ""),
        service_account_name=str(release.get("service_account_name") or ""),
        command_runner=command_runner,
        kube_context=kube_context,
        timeout_seconds=verification_timeout_seconds,
        poll_interval_seconds=poll_interval_seconds,
    )
    _legacy_rootfs_verify_jailed_config_files(
        pod=ready_pod,
        files=verified_jailed_files,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if (
        _legacy_rootfs_scalable_spec_fingerprint(
            _ready_deployment,
            label="target SConfig ready Deployment writer release",
        )
        != expected_deployment_fingerprint
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig Deployment spec drifted while the released writer became ready."
        )
    live_pod = _immutable_child_get_namespaced_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pod",
        name=ready_pod["name"],
    )
    _immutable_child_require_live_uid(
        live_pod,
        expected_uid=ready_pod["uid"],
        label="target SConfig slot-b writer Pod",
    )
    if not _pod_template_has_jail_rootfs_consumer_mount(
        payload={"spec": {"template": {"spec": _mapping(live_pod.get("spec"))}}},
        rootfs_pvc=rootfs_pvc,
    ):
        raise SoperatorMigrationPhasePending(
            "target SConfig writer Pod does not mount the verified active rootfs PVC at /mnt/jail."
        )
    release.update(
        {
            "status": "verified",
            "target_size_resource_version": target_identity["resourceVersion"],
            "ready_pod_uid": ready_pod["uid"],
            "verified_at": _utc_now(),
        }
    )
    state["status"] = "released"
    state["released_at"] = state.get("released_at") or _utc_now()
    if post_open_metrics_config_active:
        post_open_metrics_config["jail_digest_verified_at"] = (
            post_open_metrics_config.get("jail_digest_verified_at") or _utc_now()
        )
    checkpoint_writer()
    if bridge_status == "released":
        if post_open_metrics_config_active:
            return [
                "Legacy-rootfs SConfig writer reused its live-validated full target slot "
                "proof after the exact OpenMetrics Helm reconciliation."
            ]
        return [
            "Legacy-rootfs SConfig writer reused its live-validated full target slot proof; "
            "OpenMetrics remains disabled."
        ]
    return [
        "Legacy-rootfs SConfig writer reconciled the full target config from the verified "
        "active rootfs slot; OpenMetrics remains disabled for the separate release stage."
    ]


def _verify_legacy_rootfs_bridge_after_manager_restore(
    *,
    phase: dict[str, Any],
    populate_phase: Mapping[str, Any],
    handoff: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> list[str]:
    state = _mapping(phase.get("legacy_rootfs_slurm_config_bridge"))
    if not state or str(state.get("status") or "") == "pending":
        return []
    if str(state.get("status") or "") == "released":
        _revalidate_legacy_rootfs_sconfig_before_target_helm_replay(
            populate_phase=populate_phase,
            rolling_phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        return ["Legacy-rootfs released target SConfig writer and active-slot proof remain exact."]
    return _stage_legacy_rootfs_target_slurm_config_compatibility(
        phase=phase,
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )


def _execute_immutable_child_handoff_before_target_readiness(
    *,
    phase: dict[str, Any],
    values: Mapping[str, Any],
    controller_bridge: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> list[str]:
    handoff = _immutable_child_handoff_state(phase)
    if handoff.get("status") in {"complete", "not-required"}:
        return ["Immutable child ownership handoff reused its completed checkpoint."]
    if not handoff.get("captured_at"):
        raise SoperatorMigrationPhasePending(
            "immutable child ownership handoff lacks its pre-source-delete inventory."
        )
    if not str(phase.get("source_accounting_owner_retired_at") or "").strip():
        raise SoperatorMigrationPhasePending(
            "immutable child ownership handoff requires durable source retirement."
        )
    status = str(handoff.get("status") or "")
    if status == "target-children-created":
        return []
    if status == "manager-restored":
        _prepare_legacy_rootfs_sconfig_writer_fence(
            phase=phase,
            handoff=handoff,
            values=values,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _accounting_handoff_transition_ownerless_deployment_selector(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _transition_inert_controller_placeholder_selector(
            phase=phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _wait_for_target_immutable_child_replacements(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        return ["Immutable child ownership handoff resumed target child creation."]
    if status == "children-prepared":
        _prepare_legacy_rootfs_sconfig_writer_fence(
            phase=phase,
            handoff=handoff,
            values=values,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        for workload in _mapping(handoff.get("workloads")).values():
            if isinstance(workload, Mapping):
                _revalidate_immutable_child_pvcs(
                    item=workload,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
        _restore_soperator_manager_after_child_handoff(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        _accounting_handoff_transition_ownerless_deployment_selector(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _transition_inert_controller_placeholder_selector(
            phase=phase,
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _wait_for_target_immutable_child_replacements(
            handoff=handoff,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        return ["Immutable child ownership handoff resumed manager restore and target creation."]
    if status not in {"captured", "login-bridge-ready", "manager-paused"}:
        raise SoperatorMigrationPhasePending(
            f"immutable child ownership handoff cannot resume from status {status or 'missing'}."
        )
    if status != "manager-paused":
        raise SoperatorMigrationPhasePending(
            "immutable child handoff refuses source-child Orphan deletion until the exact "
            "manager pause and legacy-rootfs bridge are durable."
        )
    if not _legacy_rootfs_slurm_config_bridge_is_active(phase):
        raise SoperatorMigrationPhasePending(
            "immutable child handoff refuses source-child Orphan deletion until the "
            "legacy-rootfs Slurm config bridge is active."
        )
    bridge = _mapping(handoff.get("login_bridge"))
    token = str(bridge.get("token") or "")
    workloads = _mapping(handoff.get("workloads"))
    ordered_items = sorted(
        (item for item in workloads.values() if isinstance(item, dict)),
        key=lambda item: (
            item.get("component") == "controller" and item.get("kind") == "StatefulSet",
            str(item.get("api_path") or ""),
        ),
    )
    for item in ordered_items:
        _orphan_delete_bound_workload(
            item=item,
            source_binding=_mapping(handoff.get("source")),
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        _relabel_orphan_pods_for_target_adoption(
            item=item,
            handoff_token=token,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    _switch_login_bridge_to_target_selector(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    controller_item = next(
        (
            item
            for item in ordered_items
            if item.get("component") == "controller" and item.get("kind") == "StatefulSet"
        ),
        None,
    )
    if controller_item is None:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff lacks the captured source controller StatefulSet."
        )
    validate_bridge_journal(controller_bridge)
    bridge_stage = BridgeStage(str(controller_bridge.get("stage", "") or ""))
    if bridge_stage not in {BridgeStage.SOURCE_HA_ACTIVE, BridgeStage.TARGET_HA_ACTIVE}:
        raise SoperatorMigrationPhasePending(
            "immutable child handoff requires the temporary controller bridge to own "
            f"Slurm authority; current stage={bridge_stage.value}."
        )
    phase["controller_spool_handoff"] = {
        "mode": "shared-sfs-authority-epoch",
        "bridge_stage": bridge_stage.value,
        "source_controller_pods_already_fenced": True,
        "clustername_cleanup": "prohibited",
        "state_manifest_sha256": str(
            _mapping(controller_bridge.get("state_manifest")).get("sha256", "") or ""
        ),
        "verified_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    handoff["children_prepared_at"] = _utc_now()
    handoff["status"] = "children-prepared"
    if checkpoint_writer is not None:
        checkpoint_writer()
    _prepare_legacy_rootfs_sconfig_writer_fence(
        phase=phase,
        handoff=handoff,
        values=values,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )
    for workload in _mapping(handoff.get("workloads")).values():
        if isinstance(workload, Mapping):
            _revalidate_immutable_child_pvcs(
                item=workload,
                command_runner=command_runner,
                kube_context=kube_context,
            )
    _restore_soperator_manager_after_child_handoff(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    _accounting_handoff_transition_ownerless_deployment_selector(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )
    _transition_inert_controller_placeholder_selector(
        phase=phase,
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )
    _wait_for_target_immutable_child_replacements(
        handoff=handoff,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    return [
        "Immutable child ownership handoff orphan-preserved login/worker Pods and PVCs, "
        "preserved the bridge-owned controller state without clustername deletion, and bound "
        "new target workloads."
    ]


def _immutable_child_require_new_target_deployment_capacity(
    *,
    target: Mapping[str, Any],
    item: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> None:
    target_identity = _immutable_child_exact_identity(
        target,
        label=f"target Deployment {_SOPERATOR_NAMESPACE}/{item.get('name')}",
    )
    selector = {
        str(key): str(value)
        for key, value in _mapping(
            _mapping(_mapping(target.get("spec")).get("selector")).get("matchLabels")
        ).items()
    }
    desired = _positive_int(_resource_replicas(target, default=-1), fallback=0)
    if not selector or desired <= 0:
        raise SoperatorMigrationPhasePending(
            f"target Deployment {item.get('name')} lacks positive exact replacement capacity."
        )
    workload_ready, workload_detail = _pod_workload_ready_state(target, kind="deployment")
    if not workload_ready:
        raise SoperatorMigrationPhasePending(
            f"target Deployment {item.get('name')} current rollout is not converged "
            f"({workload_detail})."
        )
    target_template = _mapping(_mapping(target.get("spec")).get("template"))
    if not target_template:
        raise SoperatorMigrationPhasePending(
            f"target Deployment {item.get('name')} lacks its current Pod template."
        )

    def template_fingerprint(template: Mapping[str, Any]) -> str:
        normalized = copy.deepcopy(to_plain_data(template))
        metadata = normalized.get("metadata") if isinstance(normalized, dict) else None
        labels = metadata.get("labels") if isinstance(metadata, dict) else None
        if isinstance(labels, dict):
            labels.pop("pod-template-hash", None)
        return _fingerprint(normalized)

    current_template_fingerprint = template_fingerprint(target_template)
    captured_replica_set_uids = {
        str(replica_set.get("uid") or "").strip()
        for replica_set in _sequence_of_mappings(item.get("replica_sets"))
    }
    new_replica_set_uids: set[str] = set()
    for replica_set in _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="replicasets.apps",
    ):
        labels = _mapping(_mapping(replica_set.get("metadata")).get("labels"))
        if any(str(labels.get(key) or "") != value for key, value in selector.items()):
            continue
        owner = _immutable_child_controller_owner(
            replica_set,
            label=f"target Deployment {item.get('name')} replacement ReplicaSet",
        )
        if (
            str(_mapping(owner).get("apiVersion") or "") == "apps/v1"
            and str(_mapping(owner).get("kind") or "") == "Deployment"
            and str(_mapping(owner).get("name") or "") == str(item.get("name") or "")
            and str(_mapping(owner).get("uid") or "") == target_identity["uid"]
            and template_fingerprint(_mapping(_mapping(replica_set.get("spec")).get("template")))
            == current_template_fingerprint
        ):
            uid = _immutable_child_exact_identity(
                replica_set,
                label=f"target Deployment {item.get('name')} replacement ReplicaSet",
            )["uid"]
            if uid not in captured_replica_set_uids:
                new_replica_set_uids.add(uid)
    captured_pod_uids = {
        str(pod.get("uid") or "").strip() for pod in _sequence_of_mappings(item.get("pods"))
    }
    ready_new_pods = 0
    for pod in _immutable_child_list(
        command_runner=command_runner,
        kube_context=kube_context,
        resource_type="pods",
    ):
        metadata = _mapping(pod.get("metadata"))
        if str(metadata.get("uid") or "").strip() in captured_pod_uids:
            continue
        labels = _mapping(metadata.get("labels"))
        if any(str(labels.get(key) or "") != value for key, value in selector.items()):
            continue
        owner = _immutable_child_controller_owner(
            pod,
            label=f"target Deployment {item.get('name')} replacement Pod",
        )
        if (
            str(_mapping(owner).get("apiVersion") or "") == "apps/v1"
            and str(_mapping(owner).get("kind") or "") == "ReplicaSet"
            and str(_mapping(owner).get("uid") or "") in new_replica_set_uids
            and not metadata.get("deletionTimestamp")
            and _immutable_child_pod_ready(pod)
        ):
            ready_new_pods += 1
    if ready_new_pods < desired:
        raise SoperatorMigrationPhasePending(
            f"target Deployment {item.get('name')} readiness depends on captured old dependents "
            f"({ready_new_pods}/{desired} independent Ready Pods)."
        )


def _complete_immutable_child_handoff_after_target_readiness(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> list[str]:
    handoff = _immutable_child_handoff_state(phase)
    if handoff.get("status") in {"complete", "not-required"}:
        return []
    if handoff.get("status") not in {"target-children-created", "cleanup-intent"}:
        raise SoperatorMigrationPhasePending(
            "immutable child cleanup requires target child creation and readiness first."
        )
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "immutable child cleanup requires durable checkpoint writes."
        )
    if handoff.get("status") != "cleanup-intent":
        handoff["status"] = "cleanup-intent"
        handoff["cleanup_intent_at"] = _utc_now()
        checkpoint_writer()
    for item in _mapping(handoff.get("workloads")).values():
        if not isinstance(item, dict) or item.get("kind") != "Deployment":
            continue
        target = _immutable_child_get_namespaced_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource_type="deployment",
            name=str(item.get("name") or ""),
        )
        target_identity = _immutable_child_exact_identity(
            target,
            label=f"target Deployment {_SOPERATOR_NAMESPACE}/{item.get('name')}",
        )
        if target_identity["uid"] != str(item.get("target_uid") or ""):
            raise SoperatorMigrationPhasePending(
                f"target Deployment {item.get('name')} identity drifted before old ReplicaSet cleanup."
            )
        _legacy_rootfs_bridge_controller_owner(
            target,
            allowed_bindings={
                "target": _legacy_rootfs_bridge_binding(
                    _mapping(handoff.get("target")),
                    label="immutable child target SlurmCluster",
                )
            },
            label=f"target Deployment {_SOPERATOR_NAMESPACE}/{item.get('name')}",
        )
        sconfig_fenced = bool(
            item.get("component") == "sconfigcontroller"
            and _legacy_rootfs_target_compatibility_is_active(phase)
        )
        if sconfig_fenced:
            state = _mapping(phase.get("legacy_rootfs_slurm_config_bridge"))
            stage = _mapping(state.get("target_compatibility_stage"))
            _revalidate_legacy_rootfs_target_compatibility_active(
                phase=phase,
                handoff=handoff,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            deployment, exact_identity, service_account_name, service_account_identity = (
                _legacy_rootfs_target_sconfig_binding(
                    state=state,
                    handoff=handoff,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
            )
            if (
                exact_identity["uid"] != target_identity["uid"]
                or exact_identity["uid"] != str(stage.get("deployment_uid") or "")
                or service_account_name != str(stage.get("service_account_name") or "")
                or service_account_identity["uid"] != str(stage.get("service_account_uid") or "")
                or _resource_replicas(deployment, default=-1) != 0
            ):
                raise SoperatorMigrationPhasePending(
                    "target SConfig zero-replica binding drifted before old dependent cleanup."
                )
            _legacy_rootfs_wait_target_sconfig_zero(
                deployment_uid=target_identity["uid"],
                command_runner=command_runner,
                kube_context=kube_context,
                timeout_seconds=0,
            )
        else:
            ready, detail = _pod_workload_ready_state(target, kind="deployment")
            if not ready:
                raise SoperatorMigrationPhasePending(
                    f"target Deployment {item.get('name')} is not ready before old Pod cleanup ({detail})."
                )
            _immutable_child_require_new_target_deployment_capacity(
                target=target,
                item=item,
                command_runner=command_runner,
                kube_context=kube_context,
            )
        for dependent, resource_type in (
            *[(pod, "pod") for pod in _sequence_of_mappings(item.get("pods"))],
            *[
                (replica_set, "replicaset.apps")
                for replica_set in _sequence_of_mappings(item.get("replica_sets"))
            ],
        ):
            name = str(dependent.get("name") or "")
            cleanup_key = f"{resource_type}/{name}"
            cleanup_state = item.setdefault("old_dependent_cleanup", {}).setdefault(cleanup_key, {})
            live = _immutable_child_optional_namespaced_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type=resource_type,
                name=name,
                label=f"old {resource_type} {_SOPERATOR_NAMESPACE}/{name}",
            )
            if live is not None:
                identity = _immutable_child_require_live_uid(
                    live,
                    expected_uid=str(dependent.get("uid") or ""),
                    label=f"old {resource_type} {_SOPERATOR_NAMESPACE}/{name}",
                )
                if not cleanup_state.get("delete_intent_at"):
                    if resource_type == "replicaset.apps":
                        if _validated_resource_owner_references(
                            live,
                            label=f"old ReplicaSet {_SOPERATOR_NAMESPACE}/{name}",
                        ):
                            raise SoperatorMigrationPhasePending(
                                f"old ReplicaSet {name} was adopted before cleanup intent."
                            )
                    else:
                        owner = _immutable_child_controller_owner(
                            live,
                            label=f"old Pod {_SOPERATOR_NAMESPACE}/{name}",
                        )
                        captured_replica_set_uids = {
                            str(replica_set.get("uid") or "").strip()
                            for replica_set in _sequence_of_mappings(item.get("replica_sets"))
                        }
                        owner_uid = str(_mapping(owner).get("uid") or "").strip()
                        if (
                            str(_mapping(owner).get("apiVersion") or "") != "apps/v1"
                            or str(_mapping(owner).get("kind") or "") != "ReplicaSet"
                            or owner_uid not in captured_replica_set_uids
                        ):
                            raise SoperatorMigrationPhasePending(
                                f"old Pod {name} changed ownership before cleanup intent."
                            )
                        owner_binding = next(
                            (
                                replica_set
                                for replica_set in _sequence_of_mappings(item.get("replica_sets"))
                                if str(replica_set.get("uid") or "").strip() == owner_uid
                            ),
                            None,
                        )
                        owner_replica_set = _immutable_child_optional_namespaced_resource(
                            command_runner=command_runner,
                            kube_context=kube_context,
                            resource_type="replicaset.apps",
                            name=str(_mapping(owner_binding).get("name") or ""),
                            label=f"old Pod {name} owner ReplicaSet",
                        )
                        if owner_replica_set is None or _validated_resource_owner_references(
                            owner_replica_set,
                            label=f"old Pod {name} owner ReplicaSet",
                        ):
                            raise SoperatorMigrationPhasePending(
                                f"old Pod {name} owner ReplicaSet was adopted before cleanup intent."
                            )
                    cleanup_state.update(
                        {
                            "uid": identity["uid"],
                            "resource_version": identity["resourceVersion"],
                            "delete_intent_at": _utc_now(),
                        }
                    )
                    checkpoint_writer()
                elif (
                    str(cleanup_state.get("resource_version") or "") != identity["resourceVersion"]
                ):
                    raise SoperatorMigrationPhasePending(
                        f"old {resource_type} {name} changed after cleanup intent."
                    )
                _command_runner_uid_preconditioned_delete(
                    command_runner,
                    kube_context=kube_context,
                    api_path=str(dependent.get("api_path") or ""),
                    uid=identity["uid"],
                    resource_version=identity["resourceVersion"],
                    propagation_policy="Orphan",
                    timeout_seconds=300,
                    mutation_guard=mutation_guard,
                )
            elif not cleanup_state.get("delete_intent_at"):
                if sconfig_fenced and resource_type == "pod":
                    fence = _mapping(
                        _mapping(phase.get("legacy_rootfs_slurm_config_bridge")).get("writer_fence")
                    )
                    if not str(fence.get("source_writer_pods_absent_at") or "").strip():
                        raise SoperatorMigrationPhasePending(
                            f"old {resource_type} {name} disappeared without source writer proof."
                        )
                    cleanup_state.update(
                        {
                            "uid": str(dependent.get("uid") or ""),
                            "already_paused_at": fence["source_writer_pods_absent_at"],
                        }
                    )
                    checkpoint_writer()
                else:
                    raise SoperatorMigrationPhasePending(
                        f"old {resource_type} {name} disappeared before cleanup intent."
                    )
            cleanup_state["deleted_at"] = _utc_now()
            checkpoint_writer()
        item["old_dependents_cleaned_at"] = _utc_now()
        checkpoint_writer()
    handoff["status"] = "complete"
    handoff["completed_at"] = _utc_now()
    checkpoint_writer()
    return [
        "Immutable child ownership handoff removed exact old Deployment Pods/ReplicaSets "
        "after target readiness without Background or Foreground cascade."
    ]


def _controller_owner_reference_matches_binding(
    owner: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> bool:
    return (
        owner.get("controller") is True
        and str(owner.get("name") or "").strip() == str(binding.get("name") or "").strip()
        and str(owner.get("uid") or "").strip() == str(binding.get("uid") or "").strip()
    )


def _owner_reference_partially_matches_binding(
    owner: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> bool:
    owner_name = str(owner.get("name") or "").strip()
    owner_uid = str(owner.get("uid") or "").strip()
    binding_name = str(binding.get("name") or "").strip()
    binding_uid = str(binding.get("uid") or "").strip()
    return (owner_name == binding_name) != (owner_uid == binding_uid)


def _slurmcluster_nodeset_refs_for_cleanup(
    slurmcluster: Mapping[str, Any],
) -> frozenset[str]:
    partition_configuration = _mapping(
        _mapping(slurmcluster.get("spec")).get("partitionConfiguration")
    )
    if not partition_configuration:
        return frozenset()
    raw_partitions = partition_configuration.get("partitions")
    if not isinstance(raw_partitions, Sequence) or isinstance(
        raw_partitions,
        (str, bytes, bytearray),
    ):
        raise RuntimeError(
            "Target SlurmCluster partitionConfiguration has an ambiguous NodeSet binding."
        )
    refs: set[str] = set()
    for raw_partition in raw_partitions:
        if not isinstance(raw_partition, Mapping):
            raise RuntimeError(
                "Target SlurmCluster partitionConfiguration contains a malformed partition."
            )
        raw_refs = raw_partition.get("nodeSetRefs")
        if raw_refs is None:
            continue
        if not isinstance(raw_refs, Sequence) or isinstance(
            raw_refs,
            (str, bytes, bytearray),
        ):
            raise RuntimeError(
                "Target SlurmCluster partition contains ambiguous NodeSet references."
            )
        for raw_ref in raw_refs:
            if isinstance(raw_ref, Mapping):
                raise RuntimeError(
                    "Target SlurmCluster partition contains a malformed NodeSet reference."
                )
            ref = str(raw_ref or "").strip()
            if not ref or not re.fullmatch(
                r"[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?",
                ref,
            ):
                raise RuntimeError(
                    "Target SlurmCluster partition contains an invalid NodeSet reference."
                )
            refs.add(ref)
    return frozenset(refs)


def _source_slurm_child_resource_inventory(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[dict[str, Any], ...]:
    inventory: list[dict[str, Any]] = []
    for (
        resource_type,
        api_versions,
        kind,
        api_prefix,
        collection,
    ) in _SOURCE_SLURM_CHILD_RESOURCE_TYPES:
        try:
            result = command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    resource_type,
                    "-o",
                    "json",
                    "--request-timeout=20s",
                ],
                timeout_seconds=60,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise RuntimeError(
                "Timed out while enumerating source Slurm child identities; no child "
                "resource was deleted."
            ) from exc
        if result.returncode != 0:
            raise RuntimeError(
                "Could not enumerate source Slurm child identities; no child resource "
                f"was deleted: {_command_detail(result)}"
            )
        try:
            payload = json.loads(result.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "Source Slurm child inventory returned invalid JSON; no child resource was deleted."
            ) from exc
        raw_items = payload.get("items") if isinstance(payload, Mapping) else None
        if not isinstance(raw_items, Sequence) or isinstance(
            raw_items,
            (str, bytes, bytearray),
        ):
            raise RuntimeError(
                "Source Slurm child inventory was incomplete; no child resource was deleted."
            )
        for raw_item in raw_items:
            if not isinstance(raw_item, Mapping):
                raise RuntimeError(
                    "Source Slurm child inventory contains a malformed object; no child "
                    "resource was deleted."
                )
            item = dict(raw_item)
            actual_api_version = str(item.get("apiVersion") or "").strip()
            if actual_api_version not in api_versions:
                raise RuntimeError(
                    f"Source Slurm {kind} inventory contains an unsupported or ambiguous "
                    "API identity."
                )
            identity = _validated_namespaced_resource_identity(
                item,
                expected_api_version=actual_api_version,
                expected_kind=kind,
                label=f"Source Slurm {kind}",
            )
            resolved_api_prefix = api_prefix.format(version=actual_api_version.rsplit("/", 1)[-1])
            inventory.append(
                {
                    "resource": item,
                    "identity": identity,
                    "api_path": (
                        f"{resolved_api_prefix}/namespaces/{_SOPERATOR_NAMESPACE}/"
                        f"{collection}/{identity['name']}"
                    ),
                }
            )
    return tuple(inventory)


def _source_cleanup_child_stable_binding(
    child: Mapping[str, Any],
    *,
    controller_owner: Mapping[str, Any] | None,
) -> dict[str, Any]:
    resource = _mapping(child.get("resource"))
    identity = _mapping(child.get("identity"))
    binding: dict[str, Any] = {
        "api_path": str(child.get("api_path") or "").strip(),
        "api_version": str(resource.get("apiVersion") or "").strip(),
        "kind": str(resource.get("kind") or "").strip(),
        "namespace": str(identity.get("namespace") or "").strip(),
        "name": str(identity.get("name") or "").strip(),
        "uid": str(identity.get("uid") or "").strip(),
    }
    if controller_owner is not None:
        binding["controller_owner"] = {
            key: str(controller_owner.get(key) or "").strip()
            for key in ("apiVersion", "kind", "name", "uid")
        }
    return binding


def _source_cleanup_checkpointed_child_bindings(
    *,
    state: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    required: bool,
) -> dict[str, dict[str, Any]] | None:
    raw_checkpoint = state.get("source_orphan_child_bindings")
    if raw_checkpoint is None:
        if required:
            raise SoperatorMigrationPhasePending(
                "source SlurmCluster retirement lacks its durable pre-orphan child bindings."
            )
        return None
    if not isinstance(raw_checkpoint, Mapping):
        raise SoperatorMigrationPhasePending(
            "source SlurmCluster pre-orphan child binding checkpoint is malformed."
        )
    if raw_checkpoint.get("schema") != _SOURCE_ORPHAN_CHILD_BINDINGS_SCHEMA:
        raise SoperatorMigrationPhasePending(
            "source SlurmCluster pre-orphan child binding checkpoint uses an unsupported schema."
        )
    for label, expected in (("source", source_binding), ("target", target_binding)):
        observed = {
            key: str(_mapping(raw_checkpoint.get(label)).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        normalized_expected = {
            key: str(expected.get(key) or "").strip() for key in ("namespace", "name", "uid")
        }
        if observed != normalized_expected:
            raise SoperatorMigrationPhasePending(
                "source SlurmCluster pre-orphan child bindings disagree with the exact "
                f"{label} identity."
            )
    raw_items = raw_checkpoint.get("items")
    if not isinstance(raw_items, Sequence) or isinstance(raw_items, (str, bytes, bytearray)):
        raise SoperatorMigrationPhasePending(
            "source SlurmCluster pre-orphan child binding items are malformed."
        )
    bindings: dict[str, dict[str, Any]] = {}
    bound_uids: dict[str, str] = {}
    for raw_item in raw_items:
        if not isinstance(raw_item, Mapping):
            raise SoperatorMigrationPhasePending(
                "source SlurmCluster pre-orphan child binding contains a malformed item."
            )
        item = {
            key: str(raw_item.get(key) or "").strip()
            for key in ("api_path", "api_version", "kind", "namespace", "name", "uid")
        }
        expected_api_paths = {
            (
                f"{api_prefix.format(version=item['api_version'].rsplit('/', 1)[-1])}/"
                f"namespaces/{_SOPERATOR_NAMESPACE}/{collection}/{item['name']}"
            )
            for _resource_type, api_versions, kind, api_prefix, collection in (
                _SOURCE_SLURM_CHILD_RESOURCE_TYPES
            )
            if item["api_version"] in api_versions and item["kind"] == kind
        }
        if (
            not all(item.values())
            or item["namespace"] != _SOPERATOR_NAMESPACE
            or not _uid_preconditioned_delete_api_path_is_supported(item["api_path"])
            or item["api_path"] not in expected_api_paths
            or not re.fullmatch(r"[a-z0-9](?:[-a-z0-9.]*[a-z0-9])?", item["name"])
        ):
            raise SoperatorMigrationPhasePending(
                "source SlurmCluster pre-orphan child binding lacks a supported stable identity."
            )
        if item["api_path"] in bindings or (
            item["uid"] in bound_uids and bound_uids[item["uid"]] != item["api_path"]
        ):
            raise SoperatorMigrationPhasePending(
                "source SlurmCluster pre-orphan child bindings contain a duplicate identity."
            )
        controller_owner = raw_item.get("controller_owner")
        normalized_item: dict[str, Any] = dict(item)
        if controller_owner is not None:
            if not isinstance(controller_owner, Mapping):
                raise SoperatorMigrationPhasePending(
                    "source SlurmCluster pre-orphan child binding has a malformed controller owner."
                )
            normalized_owner = {
                key: str(controller_owner.get(key) or "").strip()
                for key in ("apiVersion", "kind", "name", "uid")
            }
            if not all(normalized_owner.values()):
                raise SoperatorMigrationPhasePending(
                    "source SlurmCluster pre-orphan child binding has an incomplete controller owner."
                )
            normalized_item["controller_owner"] = normalized_owner
        bindings[item["api_path"]] = normalized_item
        bound_uids[item["uid"]] = item["api_path"]
    return bindings


def _source_cleanup_nodeset_uid_sets(
    *,
    source_report: Mapping[str, Any],
    state: Mapping[str, Any],
) -> tuple[frozenset[str], frozenset[str]]:
    source_uids = frozenset(
        str(_mapping(item.get("metadata")).get("uid") or "").strip()
        for item in _sequence_of_mappings(
            _mapping(source_report.get("snapshot")).get("soperator_resources")
        )
        if str(item.get("kind") or "").strip().lower() == "nodeset"
        and str(_mapping(item.get("metadata")).get("uid") or "").strip()
    )
    target_uids = frozenset(
        str(_mapping(binding).get("nodeset_uid") or "").strip()
        for binding in _mapping(state.get("target_worker_workload_bindings")).values()
        if str(_mapping(binding).get("nodeset_uid") or "").strip()
    )
    return source_uids, target_uids


def _classify_source_slurm_child_resources(
    *,
    inventory: Sequence[Mapping[str, Any]],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    source_names: set[str] | frozenset[str],
    source_nodeset_uids: set[str] | frozenset[str],
    target_nodeset_uids: set[str] | frozenset[str],
    checkpointed_bindings: Mapping[str, Mapping[str, Any]] | None,
    deleted_source_controllers: Mapping[str, Mapping[str, Any]] | None = None,
    source_labels_identify: bool = False,
) -> tuple[list[dict[str, Any]], tuple[dict[str, Any], ...]]:
    records: dict[str, dict[str, Any]] = {}
    uid_to_path: dict[str, str] = {}
    checkpointed_uid_paths = {
        str(binding.get("uid") or "").strip(): path
        for path, binding in _mapping(checkpointed_bindings).items()
    }
    for raw_child in inventory:
        child = dict(raw_child)
        resource = _mapping(child.get("resource"))
        identity = _mapping(child.get("identity"))
        api_path = str(child.get("api_path") or "").strip()
        uid = str(identity.get("uid") or "").strip()
        kind = str(resource.get("kind") or "").strip()
        name = str(identity.get("name") or "").strip()
        label = f"Source cleanup {kind} {_SOPERATOR_NAMESPACE}/{name}"
        if api_path in records or (uid in uid_to_path and uid_to_path[uid] != api_path):
            raise RuntimeError(f"{label} has a duplicate live Kubernetes identity.")
        checkpointed = _mapping(_mapping(checkpointed_bindings).get(api_path))
        checkpoint_uid_mismatch = bool(
            checkpointed and str(checkpointed.get("uid") or "").strip() != uid
        )
        checkpointed_path_for_uid = checkpointed_uid_paths.get(uid)
        if checkpointed_path_for_uid and checkpointed_path_for_uid != api_path:
            raise RuntimeError(
                f"{label} reused a checkpointed pre-orphan source child UID at another API path."
            )
        all_owners = _validated_resource_owner_references(resource, label=label)
        controller_owners = tuple(owner for owner in all_owners if owner.get("controller") is True)
        if len(controller_owners) > 1:
            raise RuntimeError(
                f"{label} has multiple controller owners; refusing ambiguous cleanup."
            )
        slurmcluster_owners = tuple(
            owner
            for owner in all_owners
            if str(owner.get("kind") or "").strip().lower() == "slurmcluster"
        )
        if any(
            str(owner.get("apiVersion") or "").strip()
            not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
            for owner in slurmcluster_owners
        ):
            raise RuntimeError(f"{label} has an unsupported SlurmCluster owner API identity.")
        if any(
            _owner_reference_partially_matches_binding(owner, source_binding)
            or _owner_reference_partially_matches_binding(owner, target_binding)
            for owner in slurmcluster_owners
        ):
            raise RuntimeError(
                f"{label} has a SlurmCluster owner name/UID mismatch; refusing deletion."
            )
        labels = _mapping(_mapping(resource.get("metadata")).get("labels"))
        source_labeled = bool(
            str(labels.get("app.kubernetes.io/name") or "").strip() == "slurmcluster"
            and str(labels.get("app.kubernetes.io/instance") or "").strip() in source_names
        )
        records[api_path] = {
            "child": child,
            "identity": identity,
            "owners": all_owners,
            "controller_owner": controller_owners[0] if controller_owners else None,
            "slurmcluster_owners": slurmcluster_owners,
            "source_labeled": source_labeled,
            "checkpoint_uid_mismatch": checkpoint_uid_mismatch,
            "label": label,
        }
        uid_to_path[uid] = api_path

    classifications: dict[str, str] = {}
    for api_path, record in records.items():
        slurmcluster_owners = record["slurmcluster_owners"]
        controller_owner = _mapping(record.get("controller_owner"))
        record_resource = _mapping(_mapping(record.get("child")).get("resource"))
        record_kind = str(record_resource.get("kind") or "")
        record_uid = str(_mapping(record.get("identity")).get("uid") or "").strip()
        if record_kind == "NodeSet":
            # A NodeSet can be intentionally reused in place without an owner.
            # The durable target worker binding must win a source/target UID overlap.
            if record_uid in target_nodeset_uids:
                classifications[api_path] = "target"
                continue
            if record_uid in source_nodeset_uids:
                classifications[api_path] = "source"
                continue
        if source_labels_identify and record["source_labeled"]:
            classifications[api_path] = "source"
            continue
        if any(
            _controller_owner_reference_matches_binding(owner, target_binding)
            for owner in slurmcluster_owners
        ):
            classifications[api_path] = "target"
            continue
        if any(
            _controller_owner_reference_matches_binding(owner, source_binding)
            for owner in slurmcluster_owners
        ):
            classifications[api_path] = "source"
            continue
        if str(controller_owner.get("kind") or "").strip().lower() == "nodeset":
            owner_uid = str(controller_owner.get("uid") or "").strip()
            if owner_uid in target_nodeset_uids:
                classifications[api_path] = "target"
                continue
            if owner_uid in source_nodeset_uids:
                classifications[api_path] = "source"
                continue
        if not record["owners"] and api_path in _mapping(checkpointed_bindings):
            classifications[api_path] = "source"

    changed = True
    while changed:
        changed = False
        for api_path, record in records.items():
            if api_path in classifications:
                continue
            controller_owner = _mapping(record.get("controller_owner"))
            owner_path = uid_to_path.get(str(controller_owner.get("uid") or "").strip())
            if owner_path and owner_path in classifications:
                classifications[api_path] = classifications[owner_path]
                changed = True

    source_children: list[dict[str, Any]] = []
    stable_bindings: list[dict[str, Any]] = []
    for api_path, record in records.items():
        classification = classifications.get(api_path)
        if classification == "target":
            continue
        checkpointed = _mapping(_mapping(checkpointed_bindings).get(api_path))
        checkpointed_controller = _mapping(checkpointed.get("controller_owner"))
        live_controller = _mapping(record.get("controller_owner"))
        controller_owner_path = uid_to_path.get(str(live_controller.get("uid") or "").strip())
        controller_owner_record = _mapping(records.get(controller_owner_path or ""))
        exact_captured_controller_recreation = bool(
            classification == "source"
            and record["checkpoint_uid_mismatch"]
            and checkpointed_controller
            and all(
                str(live_controller.get(field) or "").strip()
                == str(checkpointed_controller.get(field) or "").strip()
                for field in ("apiVersion", "kind", "name", "uid")
            )
            and str(live_controller.get("kind") or "").strip().lower() != "slurmcluster"
            and controller_owner_path
            and classifications.get(controller_owner_path) == "source"
            and not controller_owner_record.get("checkpoint_uid_mismatch")
        )
        checkpointed_controller_path = checkpointed_uid_paths.get(
            str(checkpointed_controller.get("uid") or "").strip()
        )
        checkpointed_controller_binding = _mapping(
            _mapping(checkpointed_bindings).get(checkpointed_controller_path or "")
        )
        deleted_controller_binding = _mapping(
            _mapping(deleted_source_controllers).get(checkpointed_controller_path or "")
        )
        exact_deleted_controller_orphan_recreation = bool(
            classification == "source"
            and record["checkpoint_uid_mismatch"]
            and not record["owners"]
            and checkpointed_controller
            and str(checkpointed_controller.get("kind") or "").strip().lower() != "slurmcluster"
            and checkpointed_controller_path
            and checkpointed_controller_path not in records
            and all(
                str(checkpointed_controller_binding.get(binding_field) or "").strip()
                == str(checkpointed_controller.get(owner_field) or "").strip()
                for binding_field, owner_field in (
                    ("api_version", "apiVersion"),
                    ("kind", "kind"),
                    ("name", "name"),
                    ("uid", "uid"),
                )
            )
            and str(checkpointed_controller_binding.get("namespace") or "").strip()
            == _SOPERATOR_NAMESPACE
            and all(
                str(deleted_controller_binding.get(field) or "").strip()
                == str(checkpointed_controller_binding.get(field) or "").strip()
                for field in (
                    "api_path",
                    "api_version",
                    "kind",
                    "namespace",
                    "name",
                    "uid",
                )
            )
        )
        if record["checkpoint_uid_mismatch"] and not (
            exact_captured_controller_recreation or exact_deleted_controller_orphan_recreation
        ):
            raise RuntimeError(
                f"{record['label']} replaced a checkpointed pre-orphan source child UID; "
                "refusing cleanup."
            )
        if classification == "source":
            if checkpointed_bindings is not None and not checkpointed:
                raise RuntimeError(
                    "Source cleanup found an uncaptured source-owned child after the durable "
                    f"pre-orphan boundary: {api_path}."
                )
            source_children.append(dict(record["child"]))
            stable_bindings.append(
                _source_cleanup_child_stable_binding(
                    record["child"],
                    controller_owner=(
                        _mapping(record.get("controller_owner"))
                        if record.get("controller_owner") is not None
                        else None
                    ),
                )
            )
            continue
        if checkpointed:
            raise RuntimeError(
                "Checkpointed pre-orphan source child gained an ambiguous controller owner: "
                f"{api_path}."
            )
        if record["source_labeled"]:
            raise RuntimeError(
                "Source cleanup found source selector labels without an exact captured source "
                f"ownership chain: {api_path}."
            )
    return source_children, tuple(
        sorted(stable_bindings, key=lambda binding: str(binding.get("api_path") or ""))
    )


def _source_cleanup_child_refresh_material(child: Mapping[str, Any]) -> dict[str, Any]:
    resource = copy.deepcopy(dict(_mapping(child.get("resource"))))
    resource.pop("status", None)
    metadata = dict(_mapping(resource.get("metadata")))
    metadata.pop("managedFields", None)
    metadata.pop("resourceVersion", None)
    resource["metadata"] = metadata
    return resource


def _delete_source_slurm_child_with_resource_version_refresh(
    *,
    child: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    source_names: set[str] | frozenset[str],
    source_nodeset_uids: set[str] | frozenset[str],
    target_nodeset_uids: set[str] | frozenset[str],
    checkpointed_bindings: Mapping[str, Mapping[str, Any]],
    deleted_source_controllers: Mapping[str, Mapping[str, Any]] | None = None,
    mutation_guard: Callable[[], None] | None,
) -> None:
    identity = _mapping(child.get("identity"))
    api_path = str(child.get("api_path") or "").strip()
    uid = str(identity.get("uid") or "").strip()

    def delete(
        candidate: Mapping[str, Any],
        *,
        include_resource_version: bool = True,
    ) -> None:
        candidate_identity = _mapping(candidate.get("identity"))
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=api_path,
            uid=uid,
            resource_version=(
                str(candidate_identity.get("resourceVersion") or "").strip()
                if include_resource_version
                else ""
            ),
            propagation_policy="Orphan",
            timeout_seconds=420,
            mutation_guard=mutation_guard,
        )

    baseline_material = _source_cleanup_child_refresh_material(child)
    candidate = child
    last_precondition_exc: RuntimeError | None = None
    for _attempt in range(4):
        try:
            delete(candidate)
            return
        except RuntimeError as exc:
            if "HTTP 409" not in str(exc):
                raise
            last_precondition_exc = exc
        refreshed_inventory = _source_slurm_child_resource_inventory(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        refreshed_candidates, _stable_bindings = _classify_source_slurm_child_resources(
            inventory=refreshed_inventory,
            source_binding=source_binding,
            target_binding=target_binding,
            source_names=source_names,
            source_nodeset_uids=source_nodeset_uids,
            target_nodeset_uids=target_nodeset_uids,
            checkpointed_bindings=checkpointed_bindings,
            deleted_source_controllers=deleted_source_controllers,
        )
        refreshed_live = {
            str(item.get("api_path") or "").strip(): item for item in refreshed_inventory
        }.get(api_path)
        refreshed_source = {
            str(item.get("api_path") or "").strip(): item for item in refreshed_candidates
        }.get(api_path)
        if refreshed_live is None or refreshed_source is None:
            return
        refreshed_identity = _mapping(refreshed_source.get("identity"))
        if (
            str(refreshed_identity.get("uid") or "").strip() != uid
            or _source_cleanup_child_refresh_material(refreshed_source) != baseline_material
        ):
            raise RuntimeError(
                "Source Slurm child changed beyond controller status before its "
                "UID-preconditioned cleanup retry."
            ) from last_precondition_exc
        candidate = refreshed_source

    # Some controllers continuously update status, making an exact resourceVersion
    # precondition impossible to win even though the object identity, ownership graph,
    # and deletion-relevant material remain unchanged. The immutable UID still prevents
    # deleting a replacement; use it alone only after repeated full re-enumeration and
    # exact material revalidation above.
    try:
        delete(candidate, include_resource_version=False)
    except RuntimeError as exc:
        raise RuntimeError(
            "Source Slurm child UID-only cleanup after persistent status churn was rejected."
        ) from exc


def _checkpoint_source_orphan_child_bindings(
    *,
    state: dict[str, Any],
    source_report: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    source_names: set[str] | frozenset[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    checkpointed = _source_cleanup_checkpointed_child_bindings(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        required=False,
    )
    source_nodeset_uids, target_nodeset_uids = _source_cleanup_nodeset_uid_sets(
        source_report=source_report,
        state=state,
    )
    inventory = _source_slurm_child_resource_inventory(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    _source_children, stable_bindings = _classify_source_slurm_child_resources(
        inventory=inventory,
        source_binding=source_binding,
        target_binding=target_binding,
        source_names=source_names,
        source_nodeset_uids=source_nodeset_uids,
        target_nodeset_uids=target_nodeset_uids,
        checkpointed_bindings=checkpointed,
    )
    if checkpointed is not None:
        return
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "source SlurmCluster retirement requires a durable checkpoint writer before "
            "capturing pre-orphan child identities."
        )
    state["source_orphan_child_bindings"] = {
        "schema": _SOURCE_ORPHAN_CHILD_BINDINGS_SCHEMA,
        "source": {
            key: str(source_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
        },
        "target": {
            key: str(target_binding.get(key) or "").strip() for key in ("namespace", "name", "uid")
        },
        "items": list(stable_bindings),
        "captured_at": _utc_now(),
    }
    checkpoint_writer()
    checkpointed = _source_cleanup_checkpointed_child_bindings(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        required=True,
    )
    _classify_source_slurm_child_resources(
        inventory=_source_slurm_child_resource_inventory(
            command_runner=command_runner,
            kube_context=kube_context,
        ),
        source_binding=source_binding,
        target_binding=target_binding,
        source_names=source_names,
        source_nodeset_uids=source_nodeset_uids,
        target_nodeset_uids=target_nodeset_uids,
        checkpointed_bindings=checkpointed,
    )


def _delete_via_kubernetes_unix_socket(
    *,
    socket_path: Path,
    api_path: str,
    uid: str,
    resource_version: str = "",
    propagation_policy: str,
    timeout_seconds: int,
    mutation_guard: Callable[[], None] | None = None,
    allow_not_found: bool = False,
) -> None:
    """Send one DELETE request whose wire body contains an immutable UID precondition."""

    if not _uid_preconditioned_delete_api_path_is_supported(api_path):
        raise RuntimeError("Kubernetes UID-preconditioned DELETE API path is unsupported.")

    class _UnixSocketHttpConnection(http.client.HTTPConnection):
        def connect(self) -> None:
            connection = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            connection.settimeout(self.timeout)
            connection.connect(str(socket_path))
            self.sock = connection

    body = _delete_options_body_with_uid_precondition(
        uid,
        resource_version=resource_version,
        propagation_policy=propagation_policy,
    )
    connection = _UnixSocketHttpConnection("localhost", timeout=timeout_seconds)
    try:
        connection.connect()
        if mutation_guard is not None:
            mutation_guard()
        connection.request(
            "DELETE",
            api_path,
            body=body,
            headers={
                "Content-Type": "application/json",
                "Content-Length": str(len(body)),
            },
        )
        response = connection.getresponse()
        response_body = response.read(64 * 1024).decode("utf-8", errors="replace").strip()
    except (OSError, http.client.HTTPException) as exc:
        raise RuntimeError(
            "Kubernetes UID-preconditioned DELETE transport failed before a confirmed response."
        ) from exc
    finally:
        connection.close()
    accepted_statuses = {200, 202, 404} if allow_not_found else {200, 202}
    if response.status not in accepted_statuses:
        del response_body
        reason = re.sub(r"[^A-Za-z0-9 ._-]", "", str(response.reason or ""))[:80]
        detail = f"HTTP {response.status}" + (f" {reason}" if reason else "")
        raise RuntimeError(
            "Kubernetes UID-preconditioned DELETE was rejected; the resource may have been "
            f"replaced after verification: {detail}."
        )


def _delete_kubernetes_resource_with_uid_precondition(
    *,
    kube_context: str,
    api_path: str,
    uid: str,
    resource_version: str = "",
    propagation_policy: str,
    timeout_seconds: int,
    mutation_guard: Callable[[], None] | None = None,
    allow_not_found: bool = False,
) -> None:
    """Use a loopback-only kubectl proxy to transmit DeleteOptions with a UID precondition."""

    with tempfile.TemporaryDirectory(prefix="nebius-cxcli-kube-delete-") as temp_dir:
        if mutation_guard is not None:
            mutation_guard()
        socket_path = Path(temp_dir) / "proxy.sock"
        process = subprocess.Popen(
            [
                "kubectl",
                "--context",
                kube_context,
                "proxy",
                f"--unix-socket={socket_path}",
                "--api-prefix=/",
                "--accept-hosts=^localhost$",
            ],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        try:
            deadline = time.monotonic() + min(max(timeout_seconds, 1), 30)
            while not socket_path.exists():
                if process.poll() is not None:
                    raise RuntimeError(
                        "kubectl proxy exited before opening the local UID-preconditioned "
                        "Kubernetes DELETE transport."
                    )
                if time.monotonic() >= deadline:
                    raise RuntimeError(
                        "Timed out waiting for the local UID-preconditioned Kubernetes DELETE "
                        "transport."
                    )
                time.sleep(0.05)
            _delete_via_kubernetes_unix_socket(
                socket_path=socket_path,
                api_path=api_path,
                uid=uid,
                resource_version=resource_version,
                propagation_policy=propagation_policy,
                timeout_seconds=timeout_seconds,
                mutation_guard=mutation_guard,
                allow_not_found=allow_not_found,
            )
        finally:
            if process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait(timeout=5)


def _wait_for_kubernetes_resource_uid_absent(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    api_path: str,
    uid: str,
    timeout_seconds: int,
) -> None:
    """Wait until the deleted UID is absent, allowing a different-UID replacement."""

    if not _uid_preconditioned_delete_api_path_is_supported(api_path):
        raise RuntimeError("Kubernetes UID absence verification API path is unsupported.")
    expected_uid = str(uid or "").strip()
    if not expected_uid:
        raise RuntimeError("Kubernetes UID absence verification requires a non-empty UID.")
    deadline = time.monotonic() + max(timeout_seconds, 0)
    while True:
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                f"--raw={api_path}",
                "--request-timeout=20s",
            ],
            timeout_seconds=30,
            check=False,
        )
        if result.returncode != 0:
            if _command_not_found(result):
                return
            raise RuntimeError(
                "Kubernetes UID absence verification failed after an accepted delete."
            )
        try:
            payload = json.loads(result.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "Kubernetes UID absence verification returned invalid JSON."
            ) from exc
        observed_uid = str(_mapping(_mapping(payload).get("metadata")).get("uid") or "").strip()
        if not observed_uid:
            raise RuntimeError(
                "Kubernetes UID absence verification returned an object without an exact UID."
            )
        if observed_uid != expected_uid:
            return
        if time.monotonic() >= deadline:
            raise RuntimeError(
                "Kubernetes accepted deletion, but the exact resource UID did not disappear "
                f"within {timeout_seconds}s."
            )
        time.sleep(1)


def _command_runner_uid_preconditioned_delete(
    command_runner: SoperatorMigrationCommandRunner,
    *,
    kube_context: str,
    api_path: str,
    uid: str,
    resource_version: str = "",
    propagation_policy: str,
    timeout_seconds: int,
    mutation_guard: Callable[[], None] | None = None,
    allow_not_found: bool = False,
    wait_for_absence: bool = True,
) -> None:
    if not _uid_preconditioned_delete_api_path_is_supported(api_path):
        raise RuntimeError("Kubernetes UID-preconditioned DELETE API path is unsupported.")
    if propagation_policy not in _KUBERNETES_DELETE_PROPAGATION_POLICIES:
        raise RuntimeError(
            "Kubernetes UID-preconditioned deletion requires an explicitly allowlisted "
            "propagation policy."
        )
    injected = getattr(command_runner, "uid_preconditioned_delete", None)
    if mutation_guard is not None:
        mutation_guard()
    if callable(injected):
        injected_kwargs: dict[str, Any] = {
            "kube_context": kube_context,
            "api_path": api_path,
            "uid": uid,
            "propagation_policy": propagation_policy,
            "timeout_seconds": timeout_seconds,
        }
        if resource_version:
            injected_kwargs["resource_version"] = resource_version
        injected(
            **injected_kwargs,
        )
        return
    _delete_kubernetes_resource_with_uid_precondition(
        kube_context=kube_context,
        api_path=api_path,
        uid=uid,
        resource_version=resource_version,
        propagation_policy=propagation_policy,
        timeout_seconds=timeout_seconds,
        mutation_guard=mutation_guard,
        allow_not_found=allow_not_found,
    )
    if wait_for_absence:
        _wait_for_kubernetes_resource_uid_absent(
            command_runner=command_runner,
            kube_context=kube_context,
            api_path=api_path,
            uid=uid,
            timeout_seconds=timeout_seconds,
        )


def _accounting_handoff_revalidate_held_jobs_after_child_capture(
    *,
    state: dict[str, Any],
    held_job_operations: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    source_resource_version: str,
    target_binding: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    active_operations = _active_slurm_held_job_operations(held_job_operations)
    active_job_ids = sorted(active_operations)
    prior_evidence = _mapping(state.get("held_jobs_before_source_retirement"))
    if not active_job_ids:
        if prior_evidence.get("job_ids"):
            raise SoperatorMigrationPhasePending(
                "final source retirement held-job lineage changed after its durable gate."
            )
        return
    if (
        prior_evidence.get("schema") != _ACCOUNTING_HANDOFF_HELD_JOB_RETIREMENT_GATE_SCHEMA
        or prior_evidence.get("status") != "verified"
        or str(prior_evidence.get("source_uid") or "").strip()
        != str(source_binding.get("uid") or "").strip()
        or str(prior_evidence.get("source_resource_version") or "").strip()
        != str(source_resource_version or "").strip()
        or prior_evidence.get("job_ids") != active_job_ids
    ):
        raise SoperatorMigrationPhasePending(
            "final source retirement lacks durable exact held-job evidence at the "
            "post-capture delete boundary."
        )
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "final source retirement requires a durable checkpoint writer for its "
            "post-capture held-job revalidation."
        )
    evidence = _accounting_handoff_held_job_retirement_evidence(
        held_job_operations=held_job_operations,
        source_binding=source_binding,
        source_resource_version=source_resource_version,
        target_binding=target_binding,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    evidence["boundary"] = "post-child-capture"
    state["held_jobs_before_source_retirement"] = evidence
    checkpoint_writer()


def _soperator_slurmcluster_admission_webhook(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    name = "soperator-validating-webhook-configuration"
    resource = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "validatingwebhookconfiguration",
            name,
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    metadata = _mapping(resource.get("metadata"))
    identity = {
        "name": str(metadata.get("name") or "").strip(),
        "uid": str(metadata.get("uid") or "").strip(),
        "resourceVersion": str(metadata.get("resourceVersion") or "").strip(),
    }
    if identity["name"] != name or not identity["uid"] or not identity["resourceVersion"]:
        raise SoperatorMigrationPhasePending(
            "Soperator SlurmCluster validating webhook configuration lacks an exact "
            "cluster-scoped name/UID/resourceVersion identity."
        )
    webhooks = _sequence_of_mappings(resource.get("webhooks"))
    matches = [
        (index, webhook)
        for index, webhook in enumerate(webhooks)
        if str(webhook.get("name") or "").strip() == "vslurmcluster-v1.kb.io"
        and str(_mapping(_mapping(webhook.get("clientConfig")).get("service")).get("name") or "")
        == "soperator-webhook-service"
        and str(
            _mapping(_mapping(webhook.get("clientConfig")).get("service")).get("namespace") or ""
        )
        == _SOPERATOR_NAMESPACE
    ]
    if len(matches) != 1:
        raise SoperatorMigrationPhasePending(
            "Soperator admission recovery could not bind one exact SlurmCluster validating webhook."
        )
    index, webhook = matches[0]
    failure_policy = str(webhook.get("failurePolicy") or "").strip()
    if failure_policy not in {"Fail", "Ignore"}:
        raise SoperatorMigrationPhasePending(
            "Soperator SlurmCluster validating webhook has an unsupported failure policy."
        )
    return {
        **identity,
        "webhook_name": "vslurmcluster-v1.kb.io",
        "webhook_index": index,
        "failure_policy": failure_policy,
    }


def _patch_soperator_slurmcluster_admission_policy(
    *,
    binding: Mapping[str, Any],
    desired_policy: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    mutation_guard: Callable[[], None] | None,
) -> None:
    expected_policy = str(binding.get("failure_policy") or "").strip()
    if expected_policy not in {"Fail", "Ignore"} or desired_policy not in {"Fail", "Ignore"}:
        raise SoperatorMigrationPhasePending(
            "Soperator SlurmCluster admission recovery requested an unsupported policy."
        )
    index = _non_negative_int(binding.get("webhook_index"), fallback=-1)
    if index < 0:
        raise SoperatorMigrationPhasePending(
            "Soperator SlurmCluster admission recovery lacks its exact webhook index."
        )
    patch = [
        {"op": "test", "path": "/metadata/uid", "value": str(binding.get("uid") or "")},
        {
            "op": "test",
            "path": "/metadata/resourceVersion",
            "value": str(binding.get("resourceVersion") or ""),
        },
        {
            "op": "test",
            "path": f"/webhooks/{index}/name",
            "value": str(binding.get("webhook_name") or ""),
        },
        {
            "op": "test",
            "path": f"/webhooks/{index}/failurePolicy",
            "value": expected_policy,
        },
        {
            "op": "replace",
            "path": f"/webhooks/{index}/failurePolicy",
            "value": desired_policy,
        },
    ]
    if mutation_guard is not None:
        mutation_guard()
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "patch",
            "validatingwebhookconfiguration",
            str(binding.get("name") or ""),
            "--type=json",
            "-p",
            json.dumps(patch, separators=(",", ":")),
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "Soperator SlurmCluster admission recovery exact webhook patch was rejected."
        )


def _restore_source_orphan_finalizer_admission_window(
    *,
    recovery: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None],
    mutation_guard: Callable[[], None] | None,
) -> None:
    window = recovery.get("admission_window")
    if not isinstance(window, dict) or str(window.get("status") or "") not in {
        "intent",
        "active",
    }:
        return
    live = _soperator_slurmcluster_admission_webhook(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if str(live.get("uid") or "") != str(window.get("uid") or ""):
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer admission webhook identity changed before restoration."
        )
    if live["failure_policy"] == "Ignore":
        _patch_soperator_slurmcluster_admission_policy(
            binding=live,
            desired_policy="Fail",
            command_runner=command_runner,
            kube_context=kube_context,
            mutation_guard=mutation_guard,
        )
    elif live["failure_policy"] != "Fail":
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer admission webhook escaped its exact recovery window."
        )
    window["status"] = "restored"
    window["restored_at"] = _utc_now()
    checkpoint_writer()


def _recover_stalled_source_orphan_finalizer(
    *,
    state: dict[str, Any],
    source_report: Mapping[str, Any],
    source_binding: Mapping[str, Any],
    target_binding: Mapping[str, Any],
    source_names: set[str] | frozenset[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
    timeout_seconds: int,
) -> None:
    """Finalize an accepted orphan delete only after every child is ownerless."""

    recovery = state.setdefault("source_orphan_finalizer_recovery", {})
    if not isinstance(recovery, dict):
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery checkpoint is malformed."
        )
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery requires a durable checkpoint writer."
        )
    _restore_source_orphan_finalizer_admission_window(
        recovery=recovery,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
        mutation_guard=mutation_guard,
    )
    name = str(source_binding.get("name") or "").strip()
    uid = str(source_binding.get("uid") or "").strip()
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"slurmcluster/{name}",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    if result.returncode != 0:
        detail = _command_detail(result).lower()
        if "notfound" in detail or "not found" in detail:
            recovery["status"] = "verified"
            recovery["verified_at"] = recovery.get("verified_at") or _utc_now()
            checkpoint_writer()
            return
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery could not read the exact deleting SlurmCluster."
        )
    try:
        source = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery received malformed SlurmCluster JSON."
        ) from exc
    metadata = _mapping(_mapping(source).get("metadata"))
    api_version = str(_mapping(source).get("apiVersion") or "").strip()
    resource_version = str(metadata.get("resourceVersion") or "").strip()
    finalizers = metadata.get("finalizers")
    if (
        str(metadata.get("namespace") or _SOPERATOR_NAMESPACE).strip() != _SOPERATOR_NAMESPACE
        or str(metadata.get("name") or "").strip() != name
        or str(metadata.get("uid") or "").strip() != uid
        or not str(metadata.get("deletionTimestamp") or "").strip()
        or finalizers != ["orphan"]
        or not resource_version
        or api_version not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
    ):
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery requires the exact deleting source UID "
            "with only the Kubernetes orphan finalizer."
        )
    checkpointed = _source_cleanup_checkpointed_child_bindings(
        state=state,
        source_binding=source_binding,
        target_binding=target_binding,
        required=True,
    )
    inventory = _source_reconciliation_fence_inventory(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    direct_dependents: list[str] = []
    for child in inventory:
        resource = _mapping(child.get("resource"))
        identity = _mapping(child.get("identity"))
        owners = _validated_resource_owner_references(
            resource,
            label=(
                "Source orphan-finalizer recovery "
                f"{resource.get('kind')} {_SOPERATOR_NAMESPACE}/{identity.get('name')}"
            ),
        )
        if any(str(owner.get("uid") or "").strip() == uid for owner in owners):
            direct_dependents.append(str(child.get("api_path") or ""))
    if direct_dependents:
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery found direct source ownerReferences after "
            "the accepted orphan delete."
        )
    source_nodeset_uids, target_nodeset_uids = _source_cleanup_nodeset_uid_sets(
        source_report=source_report,
        state=state,
    )
    _source_children, stable_bindings = _classify_source_slurm_child_resources(
        inventory=_source_slurm_child_resource_inventory(
            command_runner=command_runner,
            kube_context=kube_context,
        ),
        source_binding=source_binding,
        target_binding=target_binding,
        source_names=source_names,
        source_nodeset_uids=source_nodeset_uids,
        target_nodeset_uids=target_nodeset_uids,
        checkpointed_bindings=checkpointed,
    )
    observed_bindings = {
        str(binding.get("api_path") or ""): str(binding.get("uid") or "")
        for binding in stable_bindings
    }
    expected_bindings = {
        path: str(binding.get("uid") or "") for path, binding in checkpointed.items()
    }
    if observed_bindings != expected_bindings:
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery could not prove every captured child at "
            "its exact ownerless UID."
        )
    recovery.update(
        {
            "schema": "nebius-cxcli/source-orphan-finalizer-recovery-v1",
            "status": "intent",
            "source": {
                key: str(source_binding.get(key) or "").strip()
                for key in ("namespace", "name", "uid")
            },
            "resource_version": resource_version,
            "captured_child_count": len(expected_bindings),
            "complete_inventory_count": len(inventory),
            "intent_at": recovery.get("intent_at") or _utc_now(),
        }
    )
    checkpoint_writer()
    patch = [
        {"op": "test", "path": "/metadata/uid", "value": uid},
        {
            "op": "test",
            "path": "/metadata/resourceVersion",
            "value": resource_version,
        },
        {"op": "test", "path": "/metadata/finalizers", "value": ["orphan"]},
        {"op": "remove", "path": "/metadata/finalizers"},
    ]
    if mutation_guard is not None:
        mutation_guard()
    patched = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "patch",
            f"slurmcluster/{name}",
            "--type=json",
            "-p",
            json.dumps(patch, separators=(",", ":")),
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    patch_detail = _command_detail(patched).lower()
    webhook_unavailable = bool(
        patched.returncode != 0
        and 'failed calling webhook "vslurmcluster-v1.kb.io"' in patch_detail
        and (
            "connection refused" in patch_detail
            or "no endpoints available" in patch_detail
            or "failed to call webhook" in patch_detail
        )
    )
    if webhook_unavailable:
        admission = _soperator_slurmcluster_admission_webhook(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if admission["failure_policy"] != "Fail":
            raise SoperatorMigrationPhasePending(
                "source orphan-finalizer validating webhook was not fail-closed before recovery."
            )
        recovery["admission_window"] = {
            **admission,
            "schema": "nebius-cxcli/source-orphan-finalizer-admission-window-v1",
            "status": "intent",
            "intent_at": _utc_now(),
        }
        checkpoint_writer()
        _patch_soperator_slurmcluster_admission_policy(
            binding=admission,
            desired_policy="Ignore",
            command_runner=command_runner,
            kube_context=kube_context,
            mutation_guard=mutation_guard,
        )
        recovery["admission_window"]["status"] = "active"
        recovery["admission_window"]["activated_at"] = _utc_now()
        checkpoint_writer()
        try:
            if mutation_guard is not None:
                mutation_guard()
            patched = command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "patch",
                    f"slurmcluster/{name}",
                    "--type=json",
                    "-p",
                    json.dumps(patch, separators=(",", ":")),
                    "--request-timeout=20s",
                ],
                timeout_seconds=60,
                check=False,
            )
        finally:
            _restore_source_orphan_finalizer_admission_window(
                recovery=recovery,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
    if patched.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source orphan-finalizer recovery exact UID/resourceVersion patch was rejected."
        )
    recovery["status"] = "patch-accepted"
    recovery["patch_accepted_at"] = _utc_now()
    checkpoint_writer()
    _wait_for_kubernetes_resource_uid_absent(
        command_runner=command_runner,
        kube_context=kube_context,
        api_path=(
            f"/apis/slurm.nebius.ai/{api_version.rsplit('/', 1)[1]}/namespaces/"
            f"{_SOPERATOR_NAMESPACE}/"
            f"slurmclusters/{name}"
        ),
        uid=uid,
        timeout_seconds=timeout_seconds,
    )
    recovery["status"] = "verified"
    recovery["verified_at"] = _utc_now()
    checkpoint_writer()


def _delete_conflicting_source_slurm_resources(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    source_report: Mapping[str, Any],
    source_cleanup_state: dict[str, Any],
    target_ref: str,
    held_job_operations: Mapping[str, Any] | None = None,
    target_slurmcluster_binding: Mapping[str, Any] | None = None,
    source_slurmcluster_resource_version: str | None = None,
    retire_slurmcluster_only: bool = False,
    mutation_guard: Callable[[], None] | None = None,
    checkpoint_writer: Callable[[], None] | None = None,
) -> bool:
    cleanup_binding = _source_cleanup_binding(source_report, target_ref=target_ref)
    bound_name = cleanup_binding["name"]
    bound_uid = cleanup_binding["uid"]
    source_names = set(_source_slurmcluster_names(source_report, target_ref=target_ref))
    if bound_name == normalize_component_token(target_ref) and bound_uid:
        source_names.add(bound_name)
    if not source_names:
        return False
    if not bound_name or not bound_uid or bound_name not in source_names:
        raise RuntimeError(
            "External Soperator upgrade cannot clean source Slurm resources without "
            "the immutable accepted source name and UID binding."
        )
    inventory_args = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        _SOPERATOR_NAMESPACE,
        "get",
        "slurmclusters",
        "-o",
        "json",
        "--request-timeout=20s",
    ]
    try:
        inventory = command_runner(
            inventory_args,
            timeout_seconds=30,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            "Timed out while verifying the live source SlurmCluster UID immediately "
            "before cleanup; no source resource was deleted."
        ) from exc
    if inventory.returncode != 0:
        raise RuntimeError(
            "Could not verify the live source SlurmCluster UID immediately before "
            "cleanup; no source resource was deleted: " + _command_detail(inventory)
        )
    try:
        result = json.loads(inventory.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            "Source SlurmCluster inventory returned invalid JSON immediately before "
            "cleanup; no source resource was deleted."
        ) from exc
    if not isinstance(result, Mapping) or not isinstance(result.get("items"), Sequence):
        raise RuntimeError(
            "Source SlurmCluster inventory was incomplete immediately before cleanup; "
            "no source resource was deleted."
        )
    normalized_target = normalize_component_token(target_ref)
    expected_target_binding = {
        key: str(_mapping(target_slurmcluster_binding).get(key) or "").strip()
        for key in ("namespace", "name", "uid")
    }
    target_nodeset_refs: frozenset[str] = frozenset()
    inventory_items = tuple(_sequence_of_mappings(result.get("items")))
    malformed_inventory_items = [
        item
        for item in inventory_items
        if not all(
            str(_mapping(item.get("metadata")).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        )
    ]
    if malformed_inventory_items:
        raise RuntimeError(
            "Source cleanup inventory contains a SlurmCluster without explicit immutable "
            "namespace/name/UID identity; no source resource was deleted."
        )
    if bound_name == normalized_target:
        same_name_matches = [
            item
            for item in inventory_items
            if str(_mapping(item.get("metadata")).get("name") or "").strip() == normalized_target
        ]
        if len(same_name_matches) != 1:
            raise RuntimeError(
                "Could not prove exactly one live target/source SlurmCluster for same-name "
                "adoption; refusing cleanup."
            )
        same_name_metadata = _mapping(same_name_matches[0].get("metadata"))
        same_name_api_version = str(same_name_matches[0].get("apiVersion") or "").strip()
        if (
            same_name_api_version not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
            or str(same_name_metadata.get("namespace") or _SOPERATOR_NAMESPACE).strip()
            != _SOPERATOR_NAMESPACE
            or str(same_name_metadata.get("uid") or "").strip() != bound_uid
        ):
            raise RuntimeError(
                "Could not prove the live target/source SlurmCluster immutable identity; "
                "refusing child-resource cleanup for a same-name adoption."
            )
        return False
    if bound_name != normalized_target:
        if (
            expected_target_binding["namespace"] != _SOPERATOR_NAMESPACE
            or expected_target_binding["name"] != normalized_target
            or not expected_target_binding["uid"]
        ):
            raise RuntimeError(
                "External Soperator source cleanup has no complete immutable target "
                "SlurmCluster binding; no source resource was deleted."
            )
        expected_names = {bound_name, normalized_target}
        observed_names = {
            str(_mapping(item.get("metadata")).get("name") or "").strip()
            for item in inventory_items
            if str(_mapping(item.get("metadata")).get("name") or "").strip()
        }
        if not observed_names.issubset(expected_names):
            raise RuntimeError(
                "Source cleanup inventory contains an unbound SlurmCluster name; no source "
                "resource was deleted."
            )
        target_matches = [
            item
            for item in inventory_items
            if str(_mapping(item.get("metadata")).get("name") or "").strip() == normalized_target
        ]
        if len(target_matches) != 1:
            raise RuntimeError(
                "External Soperator could not prove exactly one live target SlurmCluster at "
                "the destructive cleanup boundary; no source resource was deleted."
            )
        live_target_metadata = _mapping(target_matches[0].get("metadata"))
        live_target_binding = {
            "namespace": str(live_target_metadata.get("namespace") or _SOPERATOR_NAMESPACE).strip(),
            "name": str(live_target_metadata.get("name") or "").strip(),
            "uid": str(live_target_metadata.get("uid") or "").strip(),
        }
        if live_target_binding != expected_target_binding:
            raise RuntimeError(
                "Live target SlurmCluster UID changed after the cleanup intent was "
                "checkpointed; no source resource was deleted."
            )
        target_nodeset_refs = _slurmcluster_nodeset_refs_for_cleanup(target_matches[0])
    live_source_matches = [
        item
        for item in inventory_items
        if str(_mapping(item.get("metadata")).get("name") or "").strip() == bound_name
    ]
    source_orphan_finalizer_recovered = False
    if live_source_matches:
        if len(live_source_matches) != 1:
            raise RuntimeError(
                "Source cleanup inventory contains multiple source SlurmCluster identities."
            )
        source_metadata = _mapping(live_source_matches[0].get("metadata"))
        source_api_version = str(live_source_matches[0].get("apiVersion") or "").strip()
        source_resource_version = str(source_metadata.get("resourceVersion") or "").strip()
        if str(source_metadata.get("uid") or "").strip() != bound_uid or source_api_version not in {
            "slurm.nebius.ai/v1",
            "slurm.nebius.ai/v1alpha1",
        }:
            raise RuntimeError(
                "Live source SlurmCluster immutable identity changed before child capture."
            )
        if source_slurmcluster_resource_version is not None and (
            not str(source_slurmcluster_resource_version).strip()
            or source_resource_version != str(source_slurmcluster_resource_version).strip()
        ):
            raise RuntimeError(
                "Live source SlurmCluster resourceVersion changed before pre-orphan child capture."
            )
        _checkpoint_source_orphan_child_bindings(
            state=source_cleanup_state,
            source_report=source_report,
            source_binding=cleanup_binding,
            target_binding=expected_target_binding,
            source_names=source_names,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        _accounting_handoff_revalidate_held_jobs_after_child_capture(
            state=source_cleanup_state,
            held_job_operations=(held_job_operations or {}),
            source_binding=cleanup_binding,
            source_resource_version=source_resource_version,
            target_binding=expected_target_binding,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        if str(source_metadata.get("deletionTimestamp") or "").strip():
            _recover_stalled_source_orphan_finalizer(
                state=source_cleanup_state,
                source_report=source_report,
                source_binding=cleanup_binding,
                target_binding=expected_target_binding,
                source_names=source_names,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
                timeout_seconds=300,
            )
            source_orphan_finalizer_recovered = True
    else:
        _source_cleanup_checkpointed_child_bindings(
            state=source_cleanup_state,
            source_binding=cleanup_binding,
            target_binding=expected_target_binding,
            required=True,
        )
    mutation_performed = False
    for item in inventory_items:
        metadata = _mapping(item.get("metadata"))
        name = str(metadata.get("name", "") or "").strip()
        if not name or name == normalized_target:
            continue
        if name not in source_names:
            raise RuntimeError(
                "Source cleanup inventory contains an unbound SlurmCluster name; "
                "refusing deletion outside the immutable accepted source binding."
            )
        if name != bound_name:
            continue
        if source_orphan_finalizer_recovered:
            mutation_performed = True
            continue
        live_uid = str(metadata.get("uid") or "").strip()
        live_resource_version = str(metadata.get("resourceVersion") or "").strip()
        live_api_version = str(item.get("apiVersion") or "").strip()
        if live_api_version not in {
            "slurm.nebius.ai/v1",
            "slurm.nebius.ai/v1alpha1",
        }:
            raise RuntimeError(
                "Live source SlurmCluster uses an unsupported served API version; "
                "refusing deletion."
            )
        if name == bound_name and live_uid != bound_uid:
            raise RuntimeError(
                "Live source SlurmCluster UID changed after the cleanup intent was "
                "checkpointed; refusing to delete a same-name replacement."
            )
        if source_slurmcluster_resource_version is not None:
            expected_resource_version = str(source_slurmcluster_resource_version).strip()
            if not expected_resource_version or live_resource_version != expected_resource_version:
                raise RuntimeError(
                    "Live source SlurmCluster resourceVersion changed after the final "
                    "writer-pausence gate; refusing source deletion."
                )
        try:
            _command_runner_uid_preconditioned_delete(
                command_runner,
                kube_context=kube_context,
                api_path=(
                    f"/apis/slurm.nebius.ai/{live_api_version.rsplit('/', 1)[1]}/namespaces/"
                    f"{_SOPERATOR_NAMESPACE}/slurmclusters/{name}"
                ),
                uid=bound_uid,
                resource_version=(
                    str(source_slurmcluster_resource_version or "").strip()
                    if source_slurmcluster_resource_version is not None
                    else ""
                ),
                propagation_policy="Orphan",
                timeout_seconds=_SOURCE_ORPHAN_DELETE_GRACE_SECONDS,
                mutation_guard=mutation_guard,
            )
        except RuntimeError:
            try:
                _recover_stalled_source_orphan_finalizer(
                    state=source_cleanup_state,
                    source_report=source_report,
                    source_binding=cleanup_binding,
                    target_binding=expected_target_binding,
                    source_names=source_names,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                    timeout_seconds=300,
                )
            except SoperatorMigrationPhasePending as recovery_exc:
                raise RuntimeError(
                    "UID-preconditioned source SlurmCluster deletion did not complete and "
                    "its exact orphan-finalizer recovery was not safe; no child-resource "
                    "cleanup was attempted."
                ) from recovery_exc
        mutation_performed = True
    if retire_slurmcluster_only:
        return mutation_performed
    checkpointed_child_bindings = _source_cleanup_checkpointed_child_bindings(
        state=source_cleanup_state,
        source_binding=cleanup_binding,
        target_binding=expected_target_binding,
        required=True,
    )
    source_nodeset_uids, target_nodeset_uids = _source_cleanup_nodeset_uid_sets(
        source_report=source_report,
        state=source_cleanup_state,
    )
    retained_login_services = {
        str(binding.get("uid") or "").strip(): _mapping(binding)
        for binding in _sequence_of_mappings(
            source_cleanup_state.get("retained_login_service_bindings")
        )
        if str(binding.get("uid") or "").strip()
    }
    captured_controller_uids = {
        str(_mapping(binding.get("controller_owner")).get("uid") or "").strip()
        for binding in checkpointed_child_bindings.values()
        if str(_mapping(binding.get("controller_owner")).get("kind") or "").strip().lower()
        != "slurmcluster"
        and str(_mapping(binding.get("controller_owner")).get("uid") or "").strip()
    }
    raw_controller_deletions = source_cleanup_state.get("source_child_controller_deletions")
    if raw_controller_deletions is None:
        controller_deletion_journal: dict[str, Any] = {
            "schema": _SOURCE_CHILD_CONTROLLER_DELETIONS_SCHEMA,
            "items": {},
        }
    elif not isinstance(raw_controller_deletions, Mapping) or (
        raw_controller_deletions.get("schema") != _SOURCE_CHILD_CONTROLLER_DELETIONS_SCHEMA
    ):
        raise SoperatorMigrationPhasePending(
            "source child-controller deletion journal is malformed or unsupported."
        )
    else:
        controller_deletion_journal = copy.deepcopy(dict(raw_controller_deletions))
    raw_controller_deletion_items = controller_deletion_journal.get("items")
    if not isinstance(raw_controller_deletion_items, Mapping):
        raise SoperatorMigrationPhasePending(
            "source child-controller deletion journal items are malformed."
        )
    controller_deletion_items = {
        str(path): dict(_mapping(binding))
        for path, binding in raw_controller_deletion_items.items()
    }
    for api_path, deletion in controller_deletion_items.items():
        checkpointed = _mapping(checkpointed_child_bindings.get(api_path))
        if (
            str(deletion.get("status") or "") not in {"dispatching", "accepted"}
            or any(
                str(deletion.get(field) or "").strip() != str(checkpointed.get(field) or "").strip()
                for field in (
                    "api_path",
                    "api_version",
                    "kind",
                    "namespace",
                    "name",
                    "uid",
                )
            )
            or str(deletion.get("uid") or "").strip() not in captured_controller_uids
        ):
            raise SoperatorMigrationPhasePending(
                "source child-controller deletion journal disagrees with the exact "
                "pre-orphan binding."
            )

    # A captured controller can recreate a child after that child is deleted but
    # before the controller itself is removed. Re-enumerate once after controller
    # deletion and clean only an ownerless replacement at the same checkpointed
    # path when the exact controller deletion intent is already durable.
    for _cleanup_sweep in range(2):
        child_delete_candidates, _stable_child_bindings = _classify_source_slurm_child_resources(
            inventory=_source_slurm_child_resource_inventory(
                command_runner=command_runner,
                kube_context=kube_context,
            ),
            source_binding=cleanup_binding,
            target_binding=expected_target_binding,
            source_names=source_names,
            source_nodeset_uids=source_nodeset_uids,
            target_nodeset_uids=target_nodeset_uids,
            checkpointed_bindings=checkpointed_child_bindings,
            deleted_source_controllers=controller_deletion_items,
        )
        for child in child_delete_candidates:
            resource = _mapping(child.get("resource"))
            identity = _mapping(child.get("identity"))
            api_path = str(child.get("api_path") or "").strip()
            uid = str(identity.get("uid") or "").strip()
            kind = str(resource.get("kind") or "").strip()
            name = str(identity.get("name") or "").strip()
            retained_service = _mapping(retained_login_services.get(uid))
            if kind == "Service" and retained_service:
                selector = {
                    str(key): str(value)
                    for key, value in _mapping(
                        _mapping(resource.get("spec")).get("selector")
                    ).items()
                }
                expected_selector = {
                    str(key): str(value)
                    for key, value in _mapping(retained_service.get("target_selector")).items()
                }
                if (
                    str(retained_service.get("namespace") or "") != _SOPERATOR_NAMESPACE
                    or str(retained_service.get("name") or "") != name
                    or str(_mapping(resource.get("spec")).get("type") or "") != "LoadBalancer"
                    or selector != expected_selector
                ):
                    raise SoperatorMigrationPhasePending(
                        "retained login LoadBalancer Service drifted from its exact target "
                        f"selector binding for {_SOPERATOR_NAMESPACE}/{name}."
                    )
                continue
            is_captured_controller = uid in captured_controller_uids
            if is_captured_controller and api_path not in controller_deletion_items:
                if checkpoint_writer is None:
                    raise SoperatorMigrationPhasePending(
                        "source child-controller cleanup requires a durable checkpoint writer."
                    )
                checkpointed_controller = _mapping(checkpointed_child_bindings.get(api_path))
                controller_deletion_items[api_path] = {
                    field: str(checkpointed_controller.get(field) or "").strip()
                    for field in (
                        "api_path",
                        "api_version",
                        "kind",
                        "namespace",
                        "name",
                        "uid",
                    )
                }
                controller_deletion_items[api_path]["status"] = "dispatching"
                controller_deletion_items[api_path]["intent_at"] = _utc_now()
                controller_deletion_journal["items"] = copy.deepcopy(controller_deletion_items)
                source_cleanup_state["source_child_controller_deletions"] = copy.deepcopy(
                    controller_deletion_journal
                )
                checkpoint_writer()
            try:
                _delete_source_slurm_child_with_resource_version_refresh(
                    child=child,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    source_binding=cleanup_binding,
                    target_binding=expected_target_binding,
                    source_names=source_names,
                    source_nodeset_uids=source_nodeset_uids,
                    target_nodeset_uids=target_nodeset_uids,
                    checkpointed_bindings=checkpointed_child_bindings,
                    deleted_source_controllers=controller_deletion_items,
                    mutation_guard=mutation_guard,
                )
            except RuntimeError as exc:
                raise RuntimeError(
                    "UID-preconditioned source Slurm child deletion was rejected; the live "
                    "object may have changed after identity and ownership verification for "
                    f"{kind} {_SOPERATOR_NAMESPACE}/{name}."
                ) from exc
            if is_captured_controller:
                controller_deletion_items[api_path]["status"] = "accepted"
                controller_deletion_items[api_path]["accepted_at"] = _utc_now()
                controller_deletion_journal["items"] = copy.deepcopy(controller_deletion_items)
                source_cleanup_state["source_child_controller_deletions"] = copy.deepcopy(
                    controller_deletion_journal
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
            mutation_performed = True

    source_nodeset_bindings = {
        str(_mapping(item.get("metadata")).get("name") or "").strip(): {
            "uid": str(_mapping(item.get("metadata")).get("uid") or "").strip(),
        }
        for item in _sequence_of_mappings(
            _mapping(source_report.get("snapshot")).get("soperator_resources")
        )
        if str(item.get("kind") or "").strip().lower() == "nodeset"
        and str(_mapping(item.get("metadata")).get("name") or "").strip()
    }
    target_nodeset_bindings = _mapping(source_cleanup_state.get("target_worker_workload_bindings"))
    nodeset_names = sorted({*source_nodeset_bindings, *target_nodeset_bindings})
    for nodeset_name in nodeset_names:
        get_args = [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "nodeset",
            nodeset_name,
            "-o",
            "json",
            "--request-timeout=20s",
        ]
        try:
            get_result = command_runner(
                get_args,
                timeout_seconds=60,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            raise RuntimeError(
                "Timed out while verifying source NodeSet identity before cleanup; "
                f"refusing deletion of {_SOPERATOR_NAMESPACE}/{nodeset_name}."
            ) from exc
        if get_result.returncode != 0:
            if _command_not_found(get_result):
                continue
            raise RuntimeError(
                "Could not verify source NodeSet identity before cleanup for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}: {_command_detail(get_result)}"
            )
        try:
            live_nodeset_payload = json.loads(get_result.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "Source NodeSet lookup returned invalid JSON before cleanup for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            ) from exc
        if not isinstance(live_nodeset_payload, Mapping):
            raise RuntimeError(
                "Source NodeSet lookup returned an invalid payload before cleanup for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        live_nodeset = live_nodeset_payload
        metadata = _mapping(live_nodeset.get("metadata"))
        if not metadata:
            continue
        live_api_version = str(live_nodeset.get("apiVersion") or "").strip()
        if live_api_version not in {
            "slurm.nebius.ai/v1",
            "slurm.nebius.ai/v1alpha1",
        }:
            raise RuntimeError(
                "Source NodeSet cleanup requires a supported immutable API version binding for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        identity = _validated_namespaced_resource_identity(
            live_nodeset,
            expected_api_version=live_api_version,
            expected_kind="NodeSet",
            label=f"Source NodeSet {_SOPERATOR_NAMESPACE}/{nodeset_name}",
        )
        if identity["name"] != nodeset_name:
            raise RuntimeError(
                "Source NodeSet lookup returned a different immutable object identity for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        owners = _validated_resource_owner_references(
            live_nodeset,
            label=f"Source NodeSet {_SOPERATOR_NAMESPACE}/{nodeset_name}",
        )
        controller_owners = tuple(owner for owner in owners if owner.get("controller") is True)
        if len(controller_owners) > 1:
            raise RuntimeError(
                "Source NodeSet cleanup found multiple controller owners for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        slurmcluster_owners = tuple(
            owner
            for owner in owners
            if str(owner.get("kind") or "").strip().lower() == "slurmcluster"
        )
        if any(
            str(owner.get("apiVersion") or "").strip()
            not in {"slurm.nebius.ai/v1", "slurm.nebius.ai/v1alpha1"}
            for owner in slurmcluster_owners
        ):
            raise RuntimeError(
                "Source NodeSet cleanup found an unsupported SlurmCluster owner API identity "
                f"for {_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        if any(
            _owner_reference_partially_matches_binding(owner, cleanup_binding)
            or _owner_reference_partially_matches_binding(owner, expected_target_binding)
            for owner in slurmcluster_owners
        ):
            raise RuntimeError(
                "Source NodeSet cleanup found a SlurmCluster owner name/UID mismatch for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        target_uid_owned = any(
            _controller_owner_reference_matches_binding(owner, expected_target_binding)
            for owner in slurmcluster_owners
        )
        annotations = _mapping(metadata.get("annotations"))
        labels = _mapping(metadata.get("labels"))
        target_parented_shape = bool(
            nodeset_name in target_nodeset_refs
            and identity["uid"]
            and annotations.get("slurm.nebius.ai/parental-cluster-ref")
            == expected_target_binding["name"]
            and annotations.get("meta.helm.sh/release-name") == _SOPERATOR_TARGET_RELEASE_NAME
            and annotations.get("meta.helm.sh/release-namespace") == _SOPERATOR_NAMESPACE
            and labels.get("app.kubernetes.io/instance") == _SOPERATOR_TARGET_RELEASE_NAME
            and labels.get("app.kubernetes.io/managed-by") == "Helm"
        )
        expected_target_uid = str(
            _mapping(target_nodeset_bindings.get(nodeset_name)).get("nodeset_uid") or ""
        ).strip()
        if target_parented_shape and owners and not target_uid_owned:
            raise RuntimeError(
                "Target-parented Helm NodeSet still has an ownerReference and could be "
                "garbage-collected with the retired source; refusing cleanup for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        target_parented_reuse = target_parented_shape and not owners
        if expected_target_uid and identity["uid"] == expected_target_uid:
            if not target_parented_shape or not (target_uid_owned or target_parented_reuse):
                raise RuntimeError(
                    "Exact target-bound NodeSet metadata or ownership drifted after its "
                    "durable worker binding; refusing source cleanup for "
                    f"{_SOPERATOR_NAMESPACE}/{nodeset_name}."
                )
            continue
        if target_uid_owned or target_parented_reuse:
            raise RuntimeError(
                "Live target-shaped NodeSet UID disagrees with its durable target worker "
                f"binding for {_SOPERATOR_NAMESPACE}/{nodeset_name}."
            )
        expected_binding = source_nodeset_bindings.get(nodeset_name, {})
        expected_uid = str(expected_binding.get("uid") or "").strip()
        live_uid = identity["uid"]
        if not expected_uid or live_uid != expected_uid:
            raise RuntimeError(
                "Live source NodeSet identity no longer matches the immutable accepted "
                f"binding for {_SOPERATOR_NAMESPACE}/{nodeset_name}; refusing deletion."
            )
        api_version = live_api_version.rsplit("/", 1)[1]
        api_path = (
            f"/apis/slurm.nebius.ai/{api_version}/namespaces/"
            f"{_SOPERATOR_NAMESPACE}/nodesets/{nodeset_name}"
        )
        captured_nodeset = _mapping(checkpointed_child_bindings.get(api_path))
        if str(captured_nodeset.get("uid") or "").strip() != expected_uid:
            raise RuntimeError(
                "Live source NodeSet was not captured at the durable pre-orphan boundary for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}; refusing deletion."
            )
        if controller_owners and not _controller_owner_reference_matches_binding(
            controller_owners[0],
            cleanup_binding,
        ):
            raise RuntimeError(
                "Live source NodeSet has an ambiguous non-source controller binding for "
                f"{_SOPERATOR_NAMESPACE}/{nodeset_name}; refusing deletion."
            )
        try:
            _command_runner_uid_preconditioned_delete(
                command_runner,
                kube_context=kube_context,
                api_path=api_path,
                uid=expected_uid,
                resource_version=identity["resourceVersion"],
                propagation_policy="Orphan",
                timeout_seconds=420,
                mutation_guard=mutation_guard,
            )
        except RuntimeError as exc:
            raise RuntimeError(
                "UID-preconditioned source NodeSet deletion was rejected; the live object may "
                "have been replaced after identity verification for "
                f"{nodeset_name}."
            ) from exc
        mutation_performed = True
    return mutation_performed


_SLURMCLUSTER_REQUIRED_AVAILABLE_CONDITIONS = frozenset(
    {
        "CommonAvailable",
        "ControllersAvailable",
        "LoginAvailable",
        "SConfigControllerAvailable",
        "AccountingAvailable",
    }
)


def _slurmcluster_status_available(status: Mapping[str, Any]) -> bool:
    """Accept both legacy phase and current condition-based availability schemas."""

    if str(status.get("phase") or "").strip() == "Available":
        return True
    conditions = {
        str(condition.get("type") or "").strip(): condition
        for condition in _sequence_of_mappings(status.get("conditions"))
    }
    return _SLURMCLUSTER_REQUIRED_AVAILABLE_CONDITIONS.issubset(conditions) and all(
        str(conditions[name].get("status") or "").strip() == "True"
        and str(conditions[name].get("reason") or "").strip() == "Available"
        for name in _SLURMCLUSTER_REQUIRED_AVAILABLE_CONDITIONS
    )


def _wait_for_target_slurmcluster_available(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    timeout_seconds: int,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> None:
    deadline = time.monotonic() + timeout_seconds
    last_phase = ""
    while True:
        result = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "slurmcluster",
                target_ref,
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        if not _mapping(result.get("metadata")):
            last_phase = "missing"
        else:
            status = _mapping(result.get("status"))
            last_phase = str(status.get("phase", "") or "").strip()
            if _slurmcluster_status_available(status):
                return
            if not last_phase and _sequence_of_mappings(status.get("conditions")):
                last_phase = "conditions-not-available"
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                f"target SlurmCluster '{target_ref}' did not become Available "
                f"within {timeout_seconds}s; last phase: {last_phase or 'unknown'}."
            )
        time.sleep(10)


def _resource_output_contains(names: Sequence[str], kind: str, name: str) -> bool:
    kind_lower = kind.lower()
    return any(kind_lower in item.lower() and item.rsplit("/", 1)[-1] == name for item in names)


def _expected_cutover_nodesets(checkpoint: Mapping[str, Any]) -> tuple[str, ...]:
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    target_groups = _mapping(rolling.get("target_node_groups"))
    return tuple(
        dict.fromkeys(
            normalize_component_token(state.get("nodeset_name"))
            for state in target_groups.values()
            if isinstance(state, Mapping)
            and str(state.get("compute_role", "") or "").strip() == "worker"
            and normalize_component_token(state.get("nodeset_name"))
        )
    )


def _execute_final_cutover_phase(
    *,
    checkpoint: dict[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, "final-control-plane-cutover")
    if not _has_soperator_custom_resources(live_snapshot):
        phase["skipped_reason"] = "no Soperator Slurm custom resources were detected"
        _kubectl_rollout_status(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="deployment/soperator-manager",
            timeout="10m",
        )
        return False, [
            "Final cutover skipped: no Slurm custom resources were detected; Soperator manager deployment is healthy."
        ]
    _kubectl_rollout_status(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="deployment/soperator-manager",
        timeout="15m",
    )
    _wait_for_target_slurmcluster_available(
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        timeout_seconds=900,
    )
    resources = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "slurmclusters,nodesets",
            "-o",
            "name",
        ],
        timeout_seconds=300,
    )
    names = tuple(line.strip() for line in resources.stdout.splitlines() if line.strip())
    if not _resource_output_contains(names, "slurmcluster", target_ref):
        raise SoperatorMigrationPhasePending(
            f"final-control-plane-cutover expected target SlurmCluster '{target_ref}' "
            "after target chart apply, but it was not found."
        )
    missing_nodesets = [
        name
        for name in _expected_cutover_nodesets(checkpoint)
        if not _resource_output_contains(names, "nodeset", name)
    ]
    if missing_nodesets:
        raise SoperatorMigrationPhasePending(
            "final-control-plane-cutover expected target NodeSet resources after "
            "target chart apply, but these were not found: " + ", ".join(missing_nodesets) + "."
        )
    phase["validated_resources"] = list(names)
    phase["cutover_at"] = _utc_now()
    return False, ["Final cutover validated: target Slurm custom resources are present."]


def _expected_home_mount_sources(values: Mapping[str, Any]) -> tuple[str, ...]:
    external_nfs = _mapping(values.get("externalNfs"))
    if _bool_value(external_nfs.get("enabled"), fallback=False):
        server = str(external_nfs.get("server") or "").strip()
        path = str(external_nfs.get("path") or "").strip()
        return (f"{server}:{path}",) if server and path else ()

    candidates: list[str] = []
    jail_source_name = str(
        _mapping(_mapping(values.get("volume")).get("jail")).get("name") or "jail"
    ).strip()
    jail_store_roots = tuple(
        dict.fromkeys(
            root
            for root in (
                str(
                    _mapping(_mapping(values.get("volume")).get("jail")).get("localPath") or ""
                ).rstrip("/"),
                str(
                    _mapping(_mapping(values.get("jailRootfs")).get("store")).get("mountPath") or ""
                ).rstrip("/"),
                JAIL_LEGACY_ROOT_PATH.rstrip("/"),
            )
            if root
        )
    )
    for item in _sequence_of_mappings(values.get("jailPersistentMounts")):
        if str(item.get("mountPath") or "").rstrip("/") != "/home":
            continue
        local_path = str(item.get("localPath") or "").rstrip("/")
        if local_path:
            candidates.append(local_path)
            for root in sorted(jail_store_roots, key=len, reverse=True):
                if local_path.startswith(root + "/"):
                    relative_path = local_path.removeprefix(root)
                    candidates.append(f"{jail_source_name}[{relative_path}]")
                    break

    login_volumes = _mapping(
        _mapping(_mapping(values.get("slurmNodes")).get("login")).get("volumes")
    )
    home_source_names = {
        str(item.get("volumeSourceName") or "").strip()
        for item in _sequence_of_mappings(login_volumes.get("jailSubMounts"))
        if str(item.get("mountPath") or "").rstrip("/") == "/home"
    }
    for source in _sequence_of_mappings(values.get("volumeSources")):
        if str(source.get("name") or "").strip() not in home_source_names:
            continue
        nfs = _mapping(source.get("nfs"))
        server = str(nfs.get("server") or "").strip()
        path = str(nfs.get("path") or "").strip()
        if server and path:
            candidates.append(f"{server}:{path}")
        for key in ("hostPath", "local"):
            source_path = str(_mapping(source.get(key)).get("path") or "").strip()
            if source_path:
                candidates.append(source_path)
    return tuple(dict.fromkeys(candidate for candidate in candidates if candidate))


def _configured_home_submounts(
    values: Mapping[str, Any],
    *,
    worker_nodeset_name: str = "",
) -> tuple[Mapping[str, Any], ...]:
    configured_mounts: Sequence[Mapping[str, Any]] = ()
    if worker_nodeset_name:
        normalized_nodeset = normalize_component_token(worker_nodeset_name)
        for nodeset in _sequence_of_mappings(values.get("nodesets")):
            if normalize_component_token(nodeset.get("name")) != normalized_nodeset:
                continue
            configured_mounts = _sequence_of_mappings(
                _mapping(_mapping(nodeset.get("slurmd")).get("volumes")).get("jailSubMounts")
            )
            break
    else:
        configured_mounts = _sequence_of_mappings(
            _mapping(_mapping(_mapping(values.get("slurmNodes")).get("login")).get("volumes")).get(
                "jailSubMounts"
            )
        )
    return tuple(
        item
        for item in configured_mounts
        if str(item.get("mountPath") or "").rstrip("/") == "/home"
    )


def _home_mount_contracts(
    values: Mapping[str, Any],
    *,
    worker_nodeset_name: str = "",
) -> tuple[Mapping[str, Any], ...]:
    contracts: list[dict[str, Any]] = []
    volume_sources = {
        str(item.get("name") or "").strip(): item
        for item in _sequence_of_mappings(values.get("volumeSources"))
        if str(item.get("name") or "").strip()
    }
    for mount in _configured_home_submounts(
        values,
        worker_nodeset_name=worker_nodeset_name,
    ):
        name = str(mount.get("name") or "").strip()
        if not name:
            contracts.append({"invalid": "configured /home submount has no name"})
            continue
        mount_contract = {
            "readOnly": _bool_value(mount.get("readOnly"), fallback=False),
            "subPath": str(mount.get("subPath") or "").strip(),
        }
        claim_template = _mapping(mount.get("volumeClaimTemplateSpec"))
        if claim_template:
            contracts.append(
                {
                    "name": name,
                    "mount": mount_contract,
                    "volumeClaimTemplateSpec": dict(copy.deepcopy(to_plain_data(claim_template))),
                    "runtime_sources": (),
                }
            )
            continue
        inline_source = _mapping(mount.get("volumeSource"))
        source_name = str(mount.get("volumeSourceName") or "").strip()
        source = inline_source or _mapping(volume_sources.get(source_name))
        if not source:
            contracts.append(
                {
                    "name": name,
                    "mount": mount_contract,
                    "invalid": f"volume source '{source_name or '<missing>'}' is unavailable",
                }
            )
            continue
        contract: dict[str, Any] = {
            "name": name,
            "mount": mount_contract,
            "runtime_sources": (),
        }
        for key in ("persistentVolumeClaim", "nfs", "hostPath", "csi"):
            source_value = _mapping(source.get(key))
            if source_value:
                contract[key] = dict(copy.deepcopy(to_plain_data(source_value)))
                if key in {"persistentVolumeClaim", "nfs", "csi"}:
                    contract[key].setdefault("readOnly", False)
                break
        else:
            local = _mapping(source.get("local"))
            local_path = str(local.get("path") or "").strip()
            if local_path:
                contract["hostPath"] = {"path": local_path}
            else:
                contract["invalid"] = (
                    f"volume source '{source_name}' has no supported live Pod source"
                )
        if "nfs" in contract:
            nfs = _mapping(contract["nfs"])
            server = str(nfs.get("server") or "").strip()
            path = str(nfs.get("path") or "").strip()
            contract["runtime_sources"] = (f"{server}:{path}",) if server and path else ()
        contracts.append(contract)

    external_nfs = _mapping(values.get("externalNfs"))
    if _bool_value(external_nfs.get("enabled"), fallback=False):
        server = str(external_nfs.get("server") or "").strip()
        path = str(external_nfs.get("path") or "").strip()
        contracts.append(
            {
                "name": "external-home",
                "mount": {
                    "readOnly": _bool_value(
                        external_nfs.get("readOnly"),
                        fallback=False,
                    ),
                    "subPath": "",
                },
                "nfs": {
                    "server": server,
                    "path": path,
                    "readOnly": _bool_value(
                        external_nfs.get("readOnly"),
                        fallback=False,
                    ),
                },
                "runtime_sources": ((f"{server}:{path}",) if server and path else ()),
            }
        )
    elif not contracts:
        for item in _sequence_of_mappings(values.get("jailPersistentMounts")):
            if str(item.get("mountPath") or "").rstrip("/") == "/home":
                name = _jail_persistent_mount_volume_source_name(item)
                contracts.append(
                    {
                        "name": name,
                        "mount": {"readOnly": False, "subPath": ""},
                        "persistentVolumeClaim": {
                            "claimName": f"{name}-pvc",
                            "readOnly": False,
                        },
                        "runtime_sources": _expected_home_mount_sources(values),
                    }
                )
    return tuple(contracts)


def _mapping_contains(actual: Any, expected: Any) -> bool:
    if isinstance(expected, Mapping):
        return isinstance(actual, Mapping) and all(
            (key in actual and _mapping_contains(actual[key], value))
            or (key not in actual and value is False)
            for key, value in expected.items()
        )
    if isinstance(expected, Sequence) and not isinstance(expected, (str, bytes, bytearray)):
        return (
            isinstance(actual, Sequence)
            and not isinstance(actual, (str, bytes, bytearray))
            and list(actual) == list(expected)
        )
    return actual == expected


def _live_pvc_is_bound(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    claim_name: str,
    expected_spec: Mapping[str, Any] | None = None,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> bool:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pvc",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    pvc = next(
        (
            item
            for item in _sequence_of_mappings(_mapping(payload).get("items"))
            if str(_mapping(item.get("metadata")).get("name") or "").strip() == claim_name
        ),
        {},
    )
    return (
        bool(pvc)
        and str(_mapping(pvc.get("status")).get("phase") or "").strip() == "Bound"
        and (not expected_spec or _mapping_contains(_mapping(pvc.get("spec")), expected_spec))
    )


def _live_claim_template_matches(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod: Mapping[str, Any],
    template_name: str,
    expected_spec: Mapping[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> bool:
    owner = next(
        (
            item
            for item in _sequence_of_mappings(_mapping(pod.get("metadata")).get("ownerReferences"))
            if str(item.get("kind") or "").strip() == "StatefulSet"
            and _bool_value(item.get("controller"), fallback=False)
        ),
        {},
    )
    owner_name = str(_mapping(owner).get("name") or "").strip()
    owner_api_version = str(_mapping(owner).get("apiVersion") or "").strip()
    owner_uid = str(_mapping(owner).get("uid") or "").strip()
    if not owner_name or not owner_uid:
        return False
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "statefulsets,statefulsets.apps.kruise.io",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    workload = next(
        (
            item
            for item in _sequence_of_mappings(_mapping(payload).get("items"))
            if str(_mapping(item.get("metadata")).get("name") or "").strip() == owner_name
            and (
                not owner_api_version
                or str(item.get("apiVersion") or "").strip() == owner_api_version
            )
        ),
        {},
    )
    if str(_mapping(workload.get("metadata")).get("uid") or "").strip() != owner_uid:
        return False
    template = next(
        (
            item
            for item in _sequence_of_mappings(
                _mapping(workload.get("spec")).get("volumeClaimTemplates")
            )
            if str(_mapping(item.get("metadata")).get("name") or "").strip() == template_name
        ),
        {},
    )
    return bool(template) and _mapping_contains(
        _mapping(template.get("spec")),
        expected_spec,
    )


def _configured_home_volume_is_mounted(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod: Mapping[str, Any],
    container_name: str,
    contracts: Sequence[Mapping[str, Any]],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> bool:
    if len(contracts) != 1:
        return False
    contract = _mapping(contracts[0])
    if contract.get("invalid"):
        return False
    expected_name = str(contract.get("name") or "").strip()
    spec = _mapping(pod.get("spec"))
    volumes = {
        str(volume.get("name") or "").strip(): volume
        for volume in _sequence_of_mappings(spec.get("volumes"))
        if str(volume.get("name") or "").strip()
    }
    container = next(
        (
            item
            for item in _sequence_of_mappings(spec.get("containers"))
            if str(item.get("name") or "").strip() == container_name
        ),
        {},
    )
    mount = next(
        (
            item
            for item in _sequence_of_mappings(_mapping(container).get("volumeMounts"))
            if str(item.get("name") or "").strip() == expected_name
            and str(item.get("mountPath") or "").rstrip("/") == "/mnt/jail.upper/home"
        ),
        {},
    )
    volume = _mapping(volumes.get(expected_name))
    normalized_mount = dict(mount)
    normalized_mount.setdefault("subPath", "")
    if (
        not mount
        or not volume
        or not _mapping_contains(normalized_mount, _mapping(contract.get("mount")))
    ):
        return False

    expected_pvc = _mapping(contract.get("persistentVolumeClaim"))
    if expected_pvc:
        live_pvc_source = _mapping(volume.get("persistentVolumeClaim"))
        claim_name = str(live_pvc_source.get("claimName") or "").strip()
        return (
            bool(claim_name)
            and _mapping_contains(
                live_pvc_source,
                expected_pvc,
            )
            and _live_pvc_is_bound(
                command_runner=command_runner,
                kube_context=kube_context,
                claim_name=claim_name,
                namespace=namespace,
            )
        )

    claim_template = _mapping(contract.get("volumeClaimTemplateSpec"))
    if claim_template:
        live_pvc_source = _mapping(volume.get("persistentVolumeClaim"))
        claim_name = str(live_pvc_source.get("claimName") or "").strip()
        pod_name = str(_mapping(pod.get("metadata")).get("name") or "").strip()
        expected_claim_name = f"{expected_name}-{pod_name}" if pod_name else ""
        return (
            bool(claim_name)
            and claim_name == expected_claim_name
            and _mapping_contains(live_pvc_source, {"readOnly": False})
            and _live_pvc_is_bound(
                command_runner=command_runner,
                kube_context=kube_context,
                claim_name=claim_name,
                expected_spec=claim_template,
                namespace=namespace,
            )
            and _live_claim_template_matches(
                command_runner=command_runner,
                kube_context=kube_context,
                pod=pod,
                template_name=expected_name,
                expected_spec=claim_template,
                namespace=namespace,
            )
        )

    for key in ("nfs", "hostPath", "csi"):
        expected_source = _mapping(contract.get(key))
        if expected_source:
            return _mapping_contains(_mapping(volume.get(key)), expected_source)
    return False


def _home_mount_source_matches(source: str, expected_sources: Sequence[str]) -> bool:
    expected = {str(item or "").strip() for item in expected_sources if str(item or "").strip()}
    return source in expected


def _home_mount_probe_check(
    name: str,
    result: SoperatorMigrationCommandResult,
    *,
    expected_sources: Sequence[str],
    configured_volume_mounted: bool = False,
) -> Mapping[str, str]:
    if result.returncode != 0:
        return _fast_verification_check(
            name,
            "failed",
            f"live /home mount probe failed with exit {result.returncode}",
        )
    records: dict[str, tuple[str, ...]] = {}
    for raw_line in (result.stdout or "").splitlines():
        parts = tuple(part.strip() for part in raw_line.split("\t"))
        if parts and parts[0]:
            records[parts[0]] = parts[1:]
    upper = records.get("upper", ())
    final = records.get("final", ())
    identity = records.get("identity", ())
    upper_parts = upper[0].split(maxsplit=2) if upper else []
    final_parts = final[0].split(maxsplit=2) if final else []
    upper_target = upper_parts[0] if upper_parts else ""
    upper_source = upper_parts[1] if len(upper_parts) > 1 else "unknown"
    upper_fstype = upper_parts[2] if len(upper_parts) > 2 else "unknown"
    final_target = final_parts[0] if final_parts else ""
    final_source = final_parts[1] if len(final_parts) > 1 else "unknown"
    final_fstype = final_parts[2] if len(final_parts) > 2 else "unknown"
    if upper_target.rstrip("/") != "/mnt/jail.upper/home":
        return _fast_verification_check(
            name,
            "failed",
            "/home configured upper volume does not resolve through exact mount target "
            f"/mnt/jail.upper/home (reported {upper_target or 'unknown'})",
        )
    if final_target.rstrip("/") != "/mnt/jail/home":
        return _fast_verification_check(
            name,
            "failed",
            "/home does not resolve through exact mount target /mnt/jail/home "
            f"(reported {final_target or 'unknown'}; fs type {final_fstype})",
        )
    if len(identity) != 2 or not identity[0] or identity[0] != identity[1]:
        return _fast_verification_check(
            name,
            "failed",
            "configured upper /home and final jail /home do not have the same live "
            "device/inode identity",
        )
    if not configured_volume_mounted:
        return _fast_verification_check(
            name,
            "failed",
            "live Pod does not mount the configured /home volume at /mnt/jail.upper/home",
        )
    selected_sources = tuple(
        str(item or "").strip() for item in expected_sources if str(item or "").strip()
    )
    if selected_sources and (
        not _home_mount_source_matches(upper_source, selected_sources)
        or not _home_mount_source_matches(final_source, selected_sources)
    ):
        return _fast_verification_check(
            name,
            "failed",
            "live /mnt/jail.upper/home or /mnt/jail/home source does not match the "
            "configured source",
        )
    evidence = "configured source matched" if selected_sources else "configured Pod volume"
    return _fast_verification_check(
        name,
        "passed",
        "/mnt/jail/home is the same live filesystem object as "
        f"/mnt/jail.upper/home from {evidence} ({upper_fstype}/{final_fstype})",
    )


def _pod_is_ready(item: Mapping[str, Any]) -> bool:
    status = _mapping(item.get("status"))
    if str(status.get("phase") or "").strip() != "Running":
        return False
    return any(
        str(condition.get("type") or "").strip() == "Ready"
        and str(condition.get("status") or "").strip() == "True"
        for condition in _sequence_of_mappings(status.get("conditions"))
    )


def _target_home_probe_pods(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> tuple[Mapping[str, Any], ...]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    candidates: list[Mapping[str, Any]] = []
    for item in _sequence_of_mappings(_mapping(payload).get("items")):
        if not _pod_is_ready(item):
            continue
        metadata = _mapping(item.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        if str(labels.get("app.kubernetes.io/instance") or "").strip() == target_ref:
            candidates.append(item)
    return tuple(
        sorted(
            candidates,
            key=lambda item: str(_mapping(item.get("metadata")).get("name") or ""),
        )
    )


def _home_probe_exec(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod_name: str,
    container_name: str,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> SoperatorMigrationCommandResult:
    return command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "exec",
            pod_name,
            "-c",
            container_name,
            "--",
            "/bin/sh",
            "-ceu",
            _HOME_MOUNT_PROBE_SCRIPT,
        ],
        check=False,
        timeout_seconds=120,
    )


def _home_contract_runtime_sources(
    contracts: Sequence[Mapping[str, Any]],
) -> tuple[str, ...]:
    if len(contracts) != 1:
        return ()
    sources = contracts[0].get("runtime_sources")
    if not isinstance(sources, Sequence) or isinstance(sources, (str, bytes, bytearray)):
        return ()
    return tuple(str(item or "").strip() for item in sources if str(item or "").strip())


def _home_probe_replica_coverage_check(
    *,
    name: str,
    workload: Mapping[str, Any],
    ready_pod_count: int,
    configured_replicas: int,
    desired_override: int | None = None,
) -> Mapping[str, str]:
    desired = (
        max(desired_override, 0)
        if desired_override is not None
        else _positive_int(
            _mapping(workload.get("spec")).get("replicas"),
            fallback=configured_replicas,
        )
    )
    status = _mapping(workload.get("status"))
    ready = (
        ready_pod_count
        if desired_override is not None
        else _positive_int(status.get("readyReplicas"), fallback=0)
    )
    if desired_override is None and not ready and str(status.get("phase") or "").strip() == "Ready":
        ready = _positive_int(status.get("replicas"), fallback=0)
    if desired <= 0:
        return _fast_verification_check(
            name,
            "failed",
            "desired replica count is unavailable",
        )
    if ready != desired or ready_pod_count != desired:
        return _fast_verification_check(
            name,
            "failed",
            f"desired={desired}, workload-ready={ready}, target-owned Ready Pods={ready_pod_count}",
        )
    return _fast_verification_check(
        name,
        "passed",
        f"all {desired} desired target-owned Pods are Ready and selected",
    )


def _home_pod_mount_probe_check(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    pod: Mapping[str, Any],
    container_name: str,
    contracts: Sequence[Mapping[str, Any]],
    check_name: str,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> Mapping[str, str]:
    pod_name = str(_mapping(pod.get("metadata")).get("name") or "").strip()
    configured_volume_mounted = _configured_home_volume_is_mounted(
        command_runner=command_runner,
        kube_context=kube_context,
        pod=pod,
        container_name=container_name,
        contracts=contracts,
        namespace=namespace,
    )
    return _home_mount_probe_check(
        check_name,
        _home_probe_exec(
            command_runner=command_runner,
            kube_context=kube_context,
            pod_name=pod_name,
            container_name=container_name,
            namespace=namespace,
        ),
        expected_sources=_home_contract_runtime_sources(contracts),
        configured_volume_mounted=configured_volume_mounted,
    )


def _login_home_mount_probe_checks(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    values: Mapping[str, Any],
    pods: Sequence[Mapping[str, Any]],
    namespace: str = _SOPERATOR_NAMESPACE,
    protected_pod_uids: frozenset[str] = frozenset(),
) -> tuple[Mapping[str, str], ...]:
    login_pods = tuple(
        item
        for item in pods
        if str(
            _mapping(_mapping(item.get("metadata")).get("labels")).get(
                "app.kubernetes.io/component"
            )
            or ""
        ).strip()
        == "login"
        and str(_mapping(item.get("metadata")).get("uid") or "").strip() not in protected_pod_uids
    )
    login_workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "statefulsets.apps.kruise.io",
            "login",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    login_values = _mapping(_mapping(values.get("slurmNodes")).get("login"))
    configured_replicas = _positive_int(
        login_values.get("size"),
        fallback=_positive_int(login_values.get("replicas"), fallback=0),
    )
    checks: list[Mapping[str, str]] = [
        _home_probe_replica_coverage_check(
            name="/home login Pod coverage",
            workload=login_workload,
            ready_pod_count=len(login_pods),
            configured_replicas=configured_replicas,
            desired_override=(
                max(configured_replicas - len(protected_pod_uids), 1)
                if protected_pod_uids
                else None
            ),
        )
    ]
    contracts = _home_mount_contracts(values)
    for pod in login_pods:
        pod_name = str(_mapping(pod.get("metadata")).get("name") or "").strip()
        checks.append(
            _home_pod_mount_probe_check(
                command_runner=command_runner,
                kube_context=kube_context,
                pod=pod,
                container_name="sshd",
                contracts=contracts,
                check_name=f"/home login Pod {pod_name} mount",
                namespace=namespace,
            )
        )
    return tuple(checks)


def _worker_home_mount_probe_checks(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    values: Mapping[str, Any],
    pods: Sequence[Mapping[str, Any]],
    nodeset_name: str,
    namespace: str = _SOPERATOR_NAMESPACE,
) -> tuple[Mapping[str, str], ...]:
    normalized_nodeset = normalize_component_token(nodeset_name)
    candidates: list[Mapping[str, Any]] = []
    for item in pods:
        labels = _mapping(_mapping(item.get("metadata")).get("labels"))
        live_nodeset = next(
            (
                str(labels.get(key) or "").strip()
                for key in _SOPERATOR_NODESET_LABEL_KEYS
                if str(labels.get(key) or "").strip()
            ),
            "",
        )
        if normalize_component_token(live_nodeset) == normalized_nodeset:
            candidates.append(item)
    nodeset = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "nodeset",
            nodeset_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    configured_nodeset = _mapping(_target_worker_nodesets_by_name(values).get(nodeset_name))
    checks: list[Mapping[str, str]] = [
        _home_probe_replica_coverage_check(
            name=f"/home worker NodeSet {nodeset_name} Pod coverage",
            workload=nodeset,
            ready_pod_count=len(candidates),
            configured_replicas=_positive_int(
                configured_nodeset.get("replicas"),
                fallback=0,
            ),
        )
    ]
    contracts = _home_mount_contracts(values, worker_nodeset_name=nodeset_name)
    for pod in candidates:
        pod_name = str(_mapping(pod.get("metadata")).get("name") or "").strip()
        checks.append(
            _home_pod_mount_probe_check(
                command_runner=command_runner,
                kube_context=kube_context,
                pod=pod,
                container_name="slurmd",
                contracts=contracts,
                check_name=f"/home worker NodeSet {nodeset_name} Pod {pod_name} mount",
                namespace=namespace,
            )
        )
    return tuple(checks)


def _live_home_mount_probe_checks(
    *,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    values: Mapping[str, Any],
    target_ref: str,
    namespace: str = _SOPERATOR_NAMESPACE,
    protected_login_pod_uids: Sequence[str] = (),
) -> tuple[Mapping[str, str], ...]:
    verification_values = values
    target_nodesets = _target_worker_nodeset_names(values)
    missing_reconstructed_contract = not _home_mount_contracts(values) or any(
        not _home_mount_contracts(values, worker_nodeset_name=nodeset_name)
        for nodeset_name in target_nodesets
    )
    if missing_reconstructed_contract:
        stored_values = _target_soperator_helm_stored_values(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        verification_values = _effective_target_soperator_helm_values(stored_values)
        target_nodesets = _target_worker_nodeset_names(verification_values)
        live_contract_missing = not _home_mount_contracts(verification_values) or any(
            not _home_mount_contracts(
                verification_values,
                worker_nodeset_name=nodeset_name,
            )
            for nodeset_name in target_nodesets
        )
        if live_contract_missing:
            raise SoperatorMigrationPhasePending(
                "live /home mount verification cannot reconstruct the deployed login "
                "and worker volume contracts from Helm stored values."
            )
    pods = _target_home_probe_pods(
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        namespace=namespace,
    )
    checks: list[Mapping[str, str]] = list(
        _login_home_mount_probe_checks(
            command_runner=command_runner,
            kube_context=kube_context,
            values=verification_values,
            pods=pods,
            namespace=namespace,
            protected_pod_uids=frozenset(
                str(uid).strip() for uid in protected_login_pod_uids if str(uid).strip()
            ),
        )
    )
    if not target_nodesets:
        checks.append(
            _fast_verification_check(
                "/home worker pod mount",
                "failed",
                "target values do not identify any worker NodeSet",
            )
        )
    for nodeset_name in target_nodesets:
        checks.extend(
            _worker_home_mount_probe_checks(
                command_runner=command_runner,
                kube_context=kube_context,
                values=verification_values,
                pods=pods,
                nodeset_name=nodeset_name,
                namespace=namespace,
            )
        )
    return tuple(checks)


def _live_home_mount_pending_reason(checks: Sequence[Mapping[str, Any]]) -> str:
    failed = [check for check in checks if check.get("status") != "passed"]
    details = "; ".join(
        f"{check.get('name', '/home mount')}: {check.get('summary', 'failed')}" for check in failed
    )
    return "post-switch live /home mount verification did not pass: " + details


def _persistent_mount_overwrite_checks(
    *,
    checkpoint: Mapping[str, Any],
    values: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[Mapping[str, str], ...]:
    status = jail_persistent_mount_status(values)
    _ = (checkpoint, kube_context, command_runner)
    return (
        _fast_verification_check(
            "persistent jail mounts",
            "passed" if status.verified else "failed",
            status.reason,
        ),
    )


def _persistent_migration_writer_hold_values(
    values: Mapping[str, Any],
) -> dict[str, Any]:
    patched = copy.deepcopy(dict(values))
    patched["maintenance"] = _PERSISTENT_MIGRATION_MAINTENANCE
    return patched


def _persistent_migration_original_maintenance(
    state: Mapping[str, Any],
) -> str:
    resource = next(
        (
            item
            for item in _sequence_of_mappings(state.get("resources"))
            if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
        ),
        {},
    )
    return str(resource.get("maintenance") or "none").strip()


def _hold_persistent_migration_writers(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    values: Mapping[str, Any],
    state: dict[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
    checkpoint_writer: Callable[[], None] | None = None,
) -> list[str]:
    if state.get("status") == "held":
        return []
    existing_resource = next(
        (
            item
            for item in _sequence_of_mappings(state.get("resources"))
            if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
        ),
        {},
    )
    if state.get("status") == "holding" and existing_resource:
        resource = str(existing_resource.get("resource") or "").strip()
        exists, cluster_payload = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=resource,
            namespace=str(existing_resource.get("namespace") or namespace),
        )
        expected_uid = str(existing_resource.get("uid") or "").strip()
        live_uid = str(_mapping(cluster_payload.get("metadata")).get("uid") or "").strip()
        if not exists or not expected_uid or live_uid != expected_uid:
            raise SoperatorMigrationPhasePending(
                "persistent-migration writer hold target SlurmCluster identity changed "
                "after it was checkpointed."
            )
        maintenance = str(
            _mapping(cluster_payload.get("spec")).get("maintenance") or "none"
        ).strip()
        original_maintenance = str(existing_resource.get("maintenance") or "none").strip()
        target_maintenance = str(
            existing_resource.get("target_maintenance") or _PERSISTENT_MIGRATION_MAINTENANCE
        ).strip()
        if maintenance == original_maintenance:
            _kubectl_patch_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=resource,
                patch={"spec": {"maintenance": target_maintenance}},
                namespace=str(existing_resource.get("namespace") or namespace),
            )
        elif maintenance != target_maintenance:
            raise SoperatorMigrationPhasePending(
                "persistent-migration writer hold refuses to overwrite a changed target "
                f"maintenance mode: observed {maintenance or '<empty>'}."
            )
        _wait_for_persistent_migration_writer_hold(
            command_runner=command_runner,
            kube_context=kube_context,
            state=state,
            namespace=namespace,
            checkpoint_writer=checkpoint_writer,
        )
        state.update(
            {
                "status": "held",
                "held_at": state.get("held_at") or _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return ["Resumed the checkpointed maintenance=downscale login and worker writer hold."]
    resources: list[dict[str, Any]] = []
    state.update(
        {
            "status": "holding",
            "holding_at": _utc_now(),
            "resources": resources,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    cluster_resource = f"slurmcluster/{target_ref}"
    cluster_exists, cluster_payload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=cluster_resource,
        namespace=namespace,
    )
    if not cluster_exists:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer hold could not find the target SlurmCluster."
        )
    original_maintenance = str(
        _mapping(cluster_payload.get("spec")).get("maintenance") or "none"
    ).strip()
    if original_maintenance != "none":
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer hold requires the target SlurmCluster to be in "
            f"maintenance=none, observed {original_maintenance or '<empty>'}."
        )
    cluster_uid = str(_mapping(cluster_payload.get("metadata")).get("uid") or "").strip()
    if not cluster_uid:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer hold target SlurmCluster has no immutable UID."
        )
    worker_nodesets = list(_target_worker_nodeset_names(values))
    resources.append(
        {
            "kind": "slurmcluster-maintenance",
            "action": "patch-maintenance",
            "name": target_ref,
            "namespace": namespace,
            "resource": cluster_resource,
            "exists": True,
            "uid": cluster_uid,
            "maintenance": original_maintenance,
            "target_maintenance": _PERSISTENT_MIGRATION_MAINTENANCE,
            "worker_nodesets": worker_nodesets,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    _kubectl_patch_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=cluster_resource,
        patch={"spec": {"maintenance": _PERSISTENT_MIGRATION_MAINTENANCE}},
        namespace=namespace,
    )
    _wait_for_persistent_migration_writer_hold(
        command_runner=command_runner,
        kube_context=kube_context,
        state=state,
        namespace=namespace,
        checkpoint_writer=checkpoint_writer,
    )
    state.update(
        {
            "status": "held",
            "held_at": state.get("held_at") or _utc_now(),
            "resources": resources,
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Held Soperator login and worker consumers with maintenance=downscale for "
        "one-time persistent mount migration."
    ]


def _restore_persistent_migration_writers(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: dict[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> list[str]:
    state_status = str(state.get("status") or "").strip()
    resources = _sequence_of_mappings(state.get("resources"))
    has_maintenance_resource = any(
        str(item.get("kind") or "").strip() == "slurmcluster-maintenance" for item in resources
    )
    if state_status not in {"holding", "held"} and not (
        state_status == "restored" and has_maintenance_resource
    ):
        return []
    _preflight_persistent_migration_writer_restore_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        state=state,
        namespace=namespace,
    )
    for item in reversed(resources):
        if not _bool_value(item.get("exists"), fallback=False):
            continue
        kind = str(item.get("kind") or "").strip()
        if kind == "slurmcluster-maintenance":
            resource = str(item.get("resource") or "").strip()
            if not resource:
                name = str(item.get("name") or "").strip()
                resource = f"slurmcluster/{name}" if name else ""
            if not resource:
                continue
            resource_namespace = str(item.get("namespace") or namespace)
            exists, payload = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=resource,
                namespace=resource_namespace,
            )
            expected_uid = str(item.get("uid") or "").strip()
            live_uid = str(_mapping(payload.get("metadata")).get("uid") or "").strip()
            if not exists or not expected_uid or live_uid != expected_uid:
                raise SoperatorMigrationPhasePending(
                    "persistent-migration writer restore target SlurmCluster identity "
                    "changed after it was checkpointed."
                )
            original_maintenance = str(item.get("maintenance") or "none").strip()
            target_maintenance = str(
                item.get("target_maintenance") or _PERSISTENT_MIGRATION_MAINTENANCE
            ).strip()
            live_maintenance = str(
                _mapping(payload.get("spec")).get("maintenance") or "none"
            ).strip()
            if live_maintenance not in {original_maintenance, target_maintenance}:
                raise SoperatorMigrationPhasePending(
                    "persistent-migration writer restore refuses to overwrite a changed "
                    f"target maintenance mode: observed {live_maintenance or '<empty>'}."
                )
            if live_maintenance != original_maintenance:
                _kubectl_patch_namespace_resource(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    resource=resource,
                    patch={"spec": {"maintenance": original_maintenance}},
                    namespace=resource_namespace,
                )
            restored_exists, restored_payload = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=resource,
                namespace=resource_namespace,
            )
            restored_uid = str(_mapping(restored_payload.get("metadata")).get("uid") or "").strip()
            restored_maintenance = str(
                _mapping(restored_payload.get("spec")).get("maintenance") or "none"
            ).strip()
            if (
                not restored_exists
                or restored_uid != expected_uid
                or restored_maintenance != original_maintenance
            ):
                raise SoperatorMigrationPhasePending(
                    "persistent-migration writer restore could not verify the checkpointed "
                    "SlurmCluster maintenance state."
                )
        elif kind == "nodeset" and state_status != "restored":
            name = str(item.get("name") or "").strip()
            if not name:
                continue
            _kubectl_patch_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=f"nodeset/{name}",
                patch={"spec": {"replicas": _non_negative_int(item.get("replicas"), fallback=0)}},
                namespace=str(item.get("namespace") or namespace),
            )
        elif kind == "login" and state_status != "restored":
            resource = str(item.get("resource") or "statefulsets.apps.kruise.io/login")
            namespace = str(item.get("namespace") or _SOPERATOR_NAMESPACE)
            _kubectl_scale_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=resource,
                namespace=namespace,
                replicas=_non_negative_int(item.get("replicas"), fallback=1),
            )
    state["status"] = "restored"
    state["restored_at"] = _utc_now()
    if state_status == "restored":
        return ["Verified restored persistent-migration maintenance state."]
    return ["Restored login and worker consumers after persistent mount migration."]


def _preflight_persistent_migration_writer_restore_identity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: Mapping[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> Mapping[str, Any]:
    """Validate the immutable writer-restore binding without changing cluster state."""

    state_status = str(state.get("status") or "").strip()
    if state_status not in {"holding", "held", "restored"}:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore lacks a restorable checkpoint state."
        )
    bindings = [
        item
        for item in _sequence_of_mappings(state.get("resources"))
        if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
    ]
    if len(bindings) != 1:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore requires exactly one checkpointed "
            "SlurmCluster maintenance binding."
        )
    binding = bindings[0]
    if not _bool_value(binding.get("exists"), fallback=False):
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore checkpoint does not bind an existing SlurmCluster."
        )
    name = str(binding.get("name") or "").strip()
    resource = str(binding.get("resource") or "").strip()
    resource_namespace = str(binding.get("namespace") or "").strip()
    expected_uid = str(binding.get("uid") or "").strip()
    if not name or not resource or not resource_namespace or not expected_uid:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore checkpoint has an incomplete immutable "
            "SlurmCluster identity binding."
        )
    if resource != f"slurmcluster/{name}":
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore checkpoint has inconsistent SlurmCluster "
            "resource and name bindings."
        )
    exists, payload = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=resource,
        namespace=resource_namespace,
    )
    live_uid = str(_mapping(payload.get("metadata")).get("uid") or "").strip()
    if not exists or live_uid != expected_uid:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore target SlurmCluster identity changed "
            "after it was checkpointed."
        )
    original_maintenance = str(binding.get("maintenance") or "none").strip()
    target_maintenance = str(
        binding.get("target_maintenance") or _PERSISTENT_MIGRATION_MAINTENANCE
    ).strip()
    live_maintenance = str(_mapping(payload.get("spec")).get("maintenance") or "none").strip()
    if live_maintenance not in {original_maintenance, target_maintenance}:
        raise SoperatorMigrationPhasePending(
            "persistent-migration writer restore refuses to overwrite a changed target "
            f"maintenance mode: observed {live_maintenance or '<empty>'}."
        )
    return binding


def _persistent_migration_writer_hold_drift(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: Mapping[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
) -> tuple[Mapping[str, Any], ...]:
    drift: list[Mapping[str, Any]] = []
    resources = _sequence_of_mappings(state.get("resources"))
    maintenance_bindings = [
        item
        for item in resources
        if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
    ]
    if len(maintenance_bindings) != 1:
        drift.append(
            {
                "kind": "slurmcluster-maintenance",
                "reason": "checkpoint requires exactly one writer SlurmCluster binding",
                "binding_count": len(maintenance_bindings),
            }
        )
    held_login = False
    held_worker_names: set[str] = set()
    for item in resources:
        kind = str(item.get("kind") or "").strip()
        if not _bool_value(item.get("exists"), fallback=False):
            if kind == "slurmcluster-maintenance":
                drift.append(
                    {
                        "kind": kind,
                        "reason": "checkpointed writer resource is not bound as existing",
                    }
                )
            continue
        resource_namespace = str(item.get("namespace") or namespace)
        if kind == "slurmcluster-maintenance":
            name = str(item.get("name") or "").strip()
            resource = str(item.get("resource") or "").strip()
            expected_uid = str(item.get("uid") or "").strip()
            checkpoint_namespace = str(item.get("namespace") or "").strip()
            if (
                not name
                or not resource
                or not checkpoint_namespace
                or not expected_uid
                or resource != f"slurmcluster/{name}"
            ):
                drift.append({"kind": kind, "reason": "resource identity missing"})
                continue
            exists, payload = (
                _kubectl_get_namespace_resource(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    resource=resource,
                    namespace=resource_namespace,
                )
                if resource
                else (False, {})
            )
            held_login = True
            held_worker_names.update(
                str(worker or "").strip()
                for worker in item.get("worker_nodesets", []) or []
                if str(worker or "").strip()
            )
            if not exists:
                drift.append(
                    {
                        "kind": kind,
                        "resource": resource,
                        "namespace": resource_namespace,
                        "reason": "checkpointed writer resource is missing",
                    }
                )
                continue
            live_uid = str(_mapping(payload.get("metadata")).get("uid") or "").strip()
            if not expected_uid or live_uid != expected_uid:
                drift.append(
                    {
                        "kind": kind,
                        "resource": resource,
                        "namespace": resource_namespace,
                        "reason": "checkpointed writer SlurmCluster UID changed",
                    }
                )
                continue
            maintenance = str(_mapping(payload.get("spec")).get("maintenance") or "none").strip()
            target_maintenance = str(
                item.get("target_maintenance") or _PERSISTENT_MIGRATION_MAINTENANCE
            ).strip()
            if maintenance != target_maintenance:
                drift.append(
                    {
                        "kind": kind,
                        "resource": resource,
                        "namespace": resource_namespace,
                        "maintenance": maintenance,
                        "target_maintenance": target_maintenance,
                        "reason": "checkpointed writer hold is no longer active",
                    }
                )
            continue
        if kind == "nodeset":
            name = str(item.get("name") or "").strip()
            resource = f"nodeset/{name}" if name else ""
            payload = (
                _json_from_command(
                    command_runner,
                    [
                        "kubectl",
                        "--context",
                        kube_context,
                        "-n",
                        resource_namespace,
                        "get",
                        "nodeset",
                        name,
                        "-o",
                        "json",
                    ],
                    timeout_seconds=120,
                    check=False,
                )
                if name
                else {}
            )
            exists = bool(_mapping(payload.get("metadata")))
            held_worker_names.add(name)
        elif kind == "login":
            resource = str(item.get("resource") or "statefulsets.apps.kruise.io/login").strip()
            exists, payload = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource=resource,
                namespace=resource_namespace,
            )
            held_login = True
        else:
            resource = ""
            payload = {}
            exists = False
        if not resource:
            drift.append({"kind": kind or "unknown", "reason": "resource identity missing"})
            continue
        if not exists:
            drift.append(
                {
                    "kind": kind,
                    "resource": resource,
                    "namespace": resource_namespace,
                    "reason": "checkpointed writer resource is missing",
                }
            )
            continue
        desired_replicas = _resource_replicas(payload)
        status = _mapping(payload.get("status"))
        active_replicas = max(
            (
                _non_negative_int(status.get(key), fallback=0)
                for key in (
                    "replicas",
                    "readyReplicas",
                    "availableReplicas",
                    "currentReplicas",
                    "updatedReplicas",
                )
            ),
            default=0,
        )
        if desired_replicas != 0 or active_replicas != 0:
            drift.append(
                {
                    "kind": kind,
                    "resource": resource,
                    "namespace": resource_namespace,
                    "desired_replicas": desired_replicas,
                    "active_replicas": active_replicas,
                    "reason": "checkpointed writer hold is no longer active",
                }
            )
    if held_login or held_worker_names:
        pods_result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "pods",
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=30,
            check=False,
        )
        if pods_result.returncode != 0:
            drift.append(
                {
                    "kind": "pods",
                    "namespace": namespace,
                    "reason": "writer pod state is unavailable",
                }
            )
        else:
            try:
                pods_payload = json.loads(pods_result.stdout or "{}")
            except json.JSONDecodeError:
                pods_payload = {}
                drift.append(
                    {
                        "kind": "pods",
                        "namespace": namespace,
                        "reason": "writer pod state returned invalid JSON",
                    }
                )
            active_pods: list[str] = []
            for pod in _sequence_of_mappings(_mapping(pods_payload).get("items")):
                phase = str(_mapping(pod.get("status")).get("phase") or "").strip()
                if phase in {"Succeeded", "Failed"}:
                    continue
                metadata = _mapping(pod.get("metadata"))
                name = str(metadata.get("name") or "").strip()
                labels = _mapping(metadata.get("labels"))
                label_values = {str(value or "").strip() for value in labels.values()}
                nodeset_name = next(
                    (
                        str(labels.get(key) or "").strip()
                        for key in _SOPERATOR_NODESET_LABEL_KEYS
                        if str(labels.get(key) or "").strip()
                    ),
                    "",
                )
                login_pod = held_login and (name.startswith("login-") or "login" in label_values)
                worker_pod = bool(
                    nodeset_name in held_worker_names
                    or any(name.startswith(f"{worker_name}-") for worker_name in held_worker_names)
                )
                if name and (login_pod or worker_pod):
                    active_pods.append(name)
            if active_pods:
                drift.append(
                    {
                        "kind": "pods",
                        "namespace": namespace,
                        "active_pods": sorted(dict.fromkeys(active_pods)),
                        "reason": "writer pods are still active",
                    }
                )
    return tuple(drift)


def _wait_for_persistent_migration_writer_hold(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: dict[str, Any],
    namespace: str = _SOPERATOR_NAMESPACE,
    timeout_seconds: int = 600,
    poll_interval_seconds: float = 5.0,
    checkpoint_writer: Callable[[], None] | None = None,
) -> None:
    deadline = time.monotonic() + timeout_seconds
    while True:
        drift = _persistent_migration_writer_hold_drift(
            command_runner=command_runner,
            kube_context=kube_context,
            state=state,
            namespace=namespace,
        )
        if not drift:
            state["live_zero_verified_at"] = _utc_now()
            state["live_zero_verification"] = {"status": "verified"}
            if checkpoint_writer is not None:
                checkpoint_writer()
            return
        if time.monotonic() >= deadline:
            state["live_zero_verification"] = {
                "status": "pending",
                "drift": [dict(item) for item in drift],
            }
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise SoperatorMigrationPhasePending(
                "persistent-migration login and worker consumers did not reach a "
                "verified zero-pod state before the copy timeout: "
                + "; ".join(str(item.get("reason") or "pending") for item in drift)
                + "."
            )
        time.sleep(poll_interval_seconds)


def _ensure_persistent_migration_writer_hold_intact_after_copy(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    state: dict[str, Any],
    boundary: str,
    namespace: str = _SOPERATOR_NAMESPACE,
    checkpoint_writer: Callable[[], None] | None = None,
) -> None:
    drift = _persistent_migration_writer_hold_drift(
        command_runner=command_runner,
        kube_context=kube_context,
        state=state,
        namespace=namespace,
    )
    if not drift:
        return
    state["drift_detected_at"] = _utc_now()
    state["drift_boundary"] = boundary
    state["drift"] = [dict(item) for item in drift]
    migration_state = phase.setdefault("legacy_persistent_mount_migration", {})
    if not isinstance(migration_state, dict):
        raise RuntimeError(
            "populate-jail-refresh.legacy_persistent_mount_migration must be a mapping."
        )
    migration_state["status"] = "stale-after-writer-drift"
    migration_state["stale_at"] = _utc_now()
    migration_state["stale_boundary"] = boundary
    migration_state["stale_reason"] = (
        "checkpointed writers were not continuously held after the persistent copy started"
    )
    checkpoint["populate_jail_refresh"] = {
        **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
        "legacy_persistent_mount_migration": dict(migration_state),
    }
    phase["persistent_migration_failure_boundary"] = {
        "status": "manual-reconciliation-required",
        "boundary": boundary,
        "reason": (
            "persistent copy may be stale after writer-hold drift; automatic marker "
            "reuse is blocked"
        ),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    raise SoperatorMigrationPhasePending(
        "checkpointed persistent-migration writers drifted after the copy started "
        f"at {boundary}. The shared copy may be stale, so cxcli will restore "
        "steady-state writers and Slurm scheduling but block automatic marker reuse "
        "pending manual reconciliation."
    )


def _ensure_persistent_migration_login_hold_allowed(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str = _SOPERATOR_NAMESPACE,
    policy: str,
    timeout_seconds: int,
    continuous_login_required: bool = False,
) -> list[str]:
    state = phase.setdefault("persistent_migration_login_hold_policy", {})
    if not isinstance(state, dict):
        raise RuntimeError(
            "populate-jail-refresh.persistent_migration_login_hold_policy must be a mapping."
        )
    state["session_policy"] = policy
    state["session_drain_timeout_seconds"] = timeout_seconds
    if continuous_login_required:
        state.update(
            {
                "status": "rejected",
                "reason": (
                    "the external-upgrade contract does not permit a relocated persistent-copy "
                    "layout that downscales every login writer"
                ),
            }
        )
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade requires shared-SFS/in-place persistent mount adoption. A relocated "
            "copy that sets all login Pods to zero would violate the continuous SSH endpoint "
            "contract and is not supported."
        )
    if policy == EXTERNAL_LOGIN_SESSION_POLICY_TARGET_READY:
        state["status"] = "pending"
        state["reason"] = (
            "first-adoption persistent mount migration must temporarily stop login "
            "writers and cannot preserve continuous SSH endpoints under target-ready"
        )
        raise SoperatorMigrationPhasePending(_FIRST_ADOPTION_LOGIN_HOLD_PENDING_REASON)
    login_pods = _login_pod_names(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
    )
    state["login_pods_before_hold"] = list(login_pods)
    session_phase = {"login_continuity": dict(state)}
    lines = _wait_for_login_session_policy(
        phase=session_phase,
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        policy=policy,
        timeout_seconds=timeout_seconds,
        pod_names=login_pods,
    )
    state.update(dict(_mapping(session_phase.get("login_continuity"))))
    state["status"] = "allowed"
    return [
        f"Persistent mount migration login hold allowed by {policy} session policy.",
        *lines,
    ]


def _enforce_jail_helm_login_session_policy(
    *,
    checkpoint: dict[str, Any] | None,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    boundary: str,
    policy: str,
    timeout_seconds: int,
    writer_hold_state: dict[str, Any] | None = None,
    allow_writer_hold_drift: bool = False,
    namespace: str = _SOPERATOR_NAMESPACE,
    checkpoint_writer: Callable[[], None] | None = None,
) -> list[str]:
    """Apply a fresh login-session gate immediately before one Jail Helm attempt."""

    gates = phase.setdefault("helm_login_session_gates", {})
    if not isinstance(gates, dict):
        raise RuntimeError("populate-jail-refresh.helm_login_session_gates must be a mapping.")
    gate = gates.setdefault(boundary, {})
    if not isinstance(gate, dict):
        raise RuntimeError(
            f"populate-jail-refresh.helm_login_session_gates[{boundary!r}] must be a mapping."
        )
    gate.update(
        {
            "status": "checking",
            "attempts": _non_negative_int(gate.get("attempts"), fallback=0) + 1,
            "policy": policy,
            "timeout_seconds": timeout_seconds,
            "checking_at": _utc_now(),
        }
    )
    gate.pop("reason", None)
    if checkpoint_writer is not None:
        checkpoint_writer()

    try:
        has_writer_hold = bool(
            writer_hold_state is not None
            and str(writer_hold_state.get("status") or "").strip() == "held"
        )
        writer_hold_verified = False
        writer_pod_inventory_verified = False
        if has_writer_hold:
            if checkpoint is None:
                raise RuntimeError(
                    "Jail Upgrade Helm session gating cannot verify a persistent-migration "
                    "writer hold without the migration checkpoint."
                )
            if allow_writer_hold_drift:
                writer_drift = _persistent_migration_writer_hold_drift(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    state=writer_hold_state,
                    namespace=namespace,
                )
                writer_hold_verified = not writer_drift
                writer_pod_inventory_verified = not any(
                    str(item.get("kind") or "").strip() == "pods" for item in writer_drift
                )
            else:
                _ensure_persistent_migration_writer_hold_intact_after_copy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    state=writer_hold_state,
                    boundary=f"{boundary} Helm session gate",
                    namespace=namespace,
                    checkpoint_writer=checkpoint_writer,
                )
                writer_hold_verified = True
                writer_pod_inventory_verified = True

        pod_names = _login_pod_names(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
        )
        gate["pods"] = list(pod_names)
        gate["writer_hold_verified"] = writer_hold_verified
        gate["writer_pod_inventory_verified"] = writer_pod_inventory_verified
        if checkpoint_writer is not None:
            checkpoint_writer()

        if (
            writer_pod_inventory_verified
            and policy == EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE
            and not pod_names
        ):
            continuity = phase.setdefault("login_continuity", {})
            if not isinstance(continuity, dict):
                raise RuntimeError("populate-jail-refresh.login_continuity must be a mapping.")
            verified_probe = {
                "status": "checked",
                "active_sessions": 0,
                "pods": [],
                "source": "verified-persistent-migration-writer-hold",
            }
            continuity.update(
                {
                    "session_policy": policy,
                    "session_drain_timeout_seconds": timeout_seconds,
                    "last_session_probe": verified_probe,
                    "session_drain": {
                        "status": "drained",
                        "last_probe": verified_probe,
                    },
                }
            )
            lines = [
                "Login continuity: active SSH sessions are drained because the fresh "
                "persistent-migration writer-hold check verified zero backing login Pods."
            ]
        else:
            lines = (
                _ensure_active_login_session_hold(
                    checkpoint=checkpoint,
                    gate=gate,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    namespace=namespace,
                    pod_names=pod_names,
                    checkpoint_writer=checkpoint_writer,
                )
                if (
                    checkpoint is not None
                    and policy == EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE
                    and re.fullmatch(
                        r"[0-9a-f]{64}",
                        str(checkpoint.get("campaign_fingerprint") or "").strip(),
                    )
                )
                else None
            )
            if lines is None:
                lines = _wait_for_login_session_policy(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    namespace=namespace,
                    policy=policy,
                    timeout_seconds=timeout_seconds,
                    pod_names=pod_names,
                )
    except Exception as exc:
        gate.update(
            {
                "status": "pending",
                "reason": str(exc),
                "checked_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise

    active_hold = bool(
        isinstance(gate.get("active_session_hold"), Mapping)
        and str(_mapping(gate.get("active_session_hold")).get("status") or "") != "released"
    )
    gate.update(
        {
            "status": "deferred" if active_hold else "passed",
            "checked_at": _utc_now(),
            "session_drain": to_plain_data(
                _mapping(phase.get("login_continuity")).get("session_drain")
            ),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        *lines,
        (
            "Login continuity: the wait-active session drain is deferred under an exact "
            f"active-Pod hold before the Jail Upgrade {boundary} Helm reconciliation attempt."
            if active_hold
            else "Login continuity: the selected session policy passed immediately before "
            f"the Jail Upgrade {boundary} Helm reconciliation attempt."
        ),
    ]


def _helm_upgrade_target_soperator_with_jail_login_session_policy(
    *,
    checkpoint: dict[str, Any] | None,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    values: Mapping[str, Any],
    expected_version: str,
    boundary: str,
    login_session_policy: str,
    login_session_drain_timeout_seconds: int,
    wait: bool,
    disable_open_metrics_for_legacy_clients: bool | None = None,
    writer_hold_state: dict[str, Any] | None = None,
    allow_writer_hold_drift: bool = False,
    checkpoint_writer: Callable[[], None] | None = None,
) -> list[str]:
    gate_lines: list[str] = []

    def _before_reconcile() -> None:
        gate_lines.extend(
            _enforce_jail_helm_login_session_policy(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                boundary=boundary,
                policy=login_session_policy,
                timeout_seconds=login_session_drain_timeout_seconds,
                writer_hold_state=writer_hold_state,
                allow_writer_hold_drift=allow_writer_hold_drift,
                checkpoint_writer=checkpoint_writer,
            )
        )

    def _after_reconcile() -> None:
        gates = phase.get("helm_login_session_gates")
        gate = _mapping(gates).get(boundary)
        if not isinstance(gate, dict):
            return
        gate_lines.extend(
            _verify_login_session_gate_hold_after_helm(
                gate=gate,
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )

    _helm_upgrade_target_soperator(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
        expected_version=expected_version,
        wait=wait,
        disable_open_metrics_for_legacy_clients=disable_open_metrics_for_legacy_clients,
        before_reconcile=_before_reconcile,
        after_reconcile=_after_reconcile,
    )
    return gate_lines


def _ensure_in_place_jail_ownership_handoff(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    values: Mapping[str, Any],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    accounting_handoff_artifact_dir: Path,
    job_policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    login_session_policy: str,
    login_session_drain_timeout_seconds: int,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None,
    interactive_prompt_pause: Callable[[], Any] | None,
    allow_resolved_interactive_job_policy: bool,
    slurm_scheduling_pause: bool,
    checkpoint_writer: Callable[[], None] | None,
    mutation_guard: Callable[[], None] | None,
) -> tuple[bool, list[str]]:
    if (
        _compute_migration_contract(payload, target_ref).get("mode")
        != COMPUTE_MIGRATION_MODE_IN_PLACE
    ):
        return False, []
    rolling = _phase_state(checkpoint, "rolling-compute-migration")
    handoff = _mapping(rolling.get("in_place_ownership_handoff"))
    revision_is_current = (
        _non_negative_int(rolling.get("target_handoff_values_revision"), fallback=0)
        == _ROLLING_COMPUTE_VALUES_REVISION
    )
    safe_revision_replay_required = (
        handoff.get("status") == "target-children-created"
        and not revision_is_current
        and _accounting_handoff_target_helm_replay_is_safe(rolling)
    )
    if handoff.get("status") == "target-children-created" and not safe_revision_replay_required:
        return False, ["In-place immutable ownership handoff reused its durable checkpoint."]
    surged_values = _in_place_jail_login_surge_values(
        checkpoint=checkpoint,
        values=values,
        target_ref=target_ref,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    return _execute_rolling_compute_migration_phase(
        checkpoint=checkpoint,
        payload=payload,
        source_report=source_report,
        live_snapshot=live_snapshot,
        target_ref=target_ref,
        kube_context=kube_context,
        worker_node_groups=tuple(str(item) for item in checkpoint.get("worker_node_groups", [])),
        nebius_api=nebius_api,
        command_runner=command_runner,
        accounting_handoff_artifact_dir=accounting_handoff_artifact_dir,
        checkpoint_writer=checkpoint_writer,
        job_policy=job_policy,
        cancel_job_ids=cancel_job_ids,
        requeue_job_ids=requeue_job_ids,
        job_wait_timeout_seconds=job_wait_timeout_seconds,
        job_refresh_interval_seconds=job_refresh_interval_seconds,
        slurm_scheduling_pause=slurm_scheduling_pause,
        login_session_policy=login_session_policy,
        login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
        slurm_decision_recorder=slurm_decision_recorder,
        interactive_prompt_pause=interactive_prompt_pause,
        allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
        mutation_guard=mutation_guard,
        in_place_ownership_handoff_only=True,
        handoff_values=surged_values,
    )


def _release_jail_login_hold_before_full_rollout(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    rootfs_pvc: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Keep one old-slot login Pod until a target-slot peer is ready, then drain/release."""

    gate = phase.setdefault("login_hold_release_before_full_rollout", {})
    if not isinstance(gate, dict):
        raise RuntimeError("login_hold_release_before_full_rollout must be a mapping.")
    contract = _login_session_hold_contract(str(checkpoint.get("campaign_fingerprint") or ""))
    state = _login_session_hold_checkpoint_state(
        checkpoint=checkpoint,
        gate=gate,
        contract=contract,
    )
    if not state or str(state.get("status") or "").strip() == "released":
        return []
    held_uids = {
        str(item.get("uid") or "").strip()
        for item in _sequence_of_mappings(state.get("pods"))
        if str(item.get("uid") or "").strip()
    }
    target_binding = _live_target_slurmcluster_binding(
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
    )
    login_workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulsets.apps.kruise.io",
            "login",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    login_identity = _immutable_child_exact_identity(
        login_workload,
        label="Jail Upgrade target login workload",
    )
    _legacy_rootfs_bridge_controller_owner(
        login_workload,
        allowed_bindings={"target": target_binding},
        label="Jail Upgrade target login workload",
    )
    pods = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-l",
            f"app.kubernetes.io/instance={target_ref},app.kubernetes.io/component=login",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    peer_candidates: dict[str, str] = {}
    pod_names: list[str] = []
    for pod in _sequence_of_mappings(pods.get("items")):
        metadata = _mapping(pod.get("metadata"))
        name = str(metadata.get("name") or "").strip()
        uid = str(metadata.get("uid") or "").strip()
        if name:
            pod_names.append(name)
        owner = _immutable_child_controller_owner(
            pod,
            label=f"Jail Upgrade login Pod {name or '<unknown>'}",
        )
        if (
            uid
            and uid not in held_uids
            and not metadata.get("deletionTimestamp")
            and _immutable_child_pod_ready(pod)
            and str(_mapping(owner).get("apiVersion") or "") == "apps.kruise.io/v1beta1"
            and str(_mapping(owner).get("kind") or "") == "StatefulSet"
            and str(_mapping(owner).get("name") or "") == "login"
            and str(_mapping(owner).get("uid") or "") == login_identity["uid"]
            and _pod_template_has_jail_rootfs_consumer_mount(
                payload={"spec": {"template": {"spec": _mapping(pod.get("spec"))}}},
                rootfs_pvc=rootfs_pvc,
            )
        ):
            peer_candidates[uid] = name
    if not peer_candidates:
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade wait-active hold has no exact Ready unprotected login peer on "
            f"target rootfs PVC {rootfs_pvc}."
        )
    services = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "services",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    endpoint_peer_uids: set[str] = set()
    for service in _sequence_of_mappings(services.get("items")):
        service_metadata = _mapping(service.get("metadata"))
        service_labels = _mapping(service_metadata.get("labels"))
        service_name = str(service_metadata.get("name") or "").strip()
        if (
            not service_name
            or service_labels.get("app.kubernetes.io/component") != "login"
            or str(_mapping(service.get("spec")).get("type") or "") != "LoadBalancer"
        ):
            continue
        slices = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "endpointslices.discovery.k8s.io",
                "-l",
                f"kubernetes.io/service-name={service_name}",
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        for endpoint_slice in _sequence_of_mappings(slices.get("items")):
            for endpoint in _sequence_of_mappings(endpoint_slice.get("endpoints")):
                target = _mapping(endpoint.get("targetRef"))
                uid = str(target.get("uid") or "").strip()
                if (
                    _mapping(endpoint.get("conditions")).get("ready") is True
                    and uid in peer_candidates
                    and str(target.get("kind") or "").lower() == "pod"
                    and str(target.get("name") or "") == peer_candidates[uid]
                ):
                    endpoint_peer_uids.add(uid)
    if not endpoint_peer_uids:
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade wait-active hold has no Ready Service endpoint on its exact "
            "unprotected target-slot login peer."
        )

    gate["target_slot_peer"] = {
        "status": "verified",
        "rootfs_pvc": rootfs_pvc,
        "pod_uids": sorted(endpoint_peer_uids),
        "verified_at": _utc_now(),
    }
    gate.update(
        {
            "status": "pending-voluntary-handoff",
            "checked_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    try:
        handoff_lines = _complete_upgrade_login_handoff(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    except SoperatorMigrationPhasePending:
        handoff = _controller_bridge_login_handoff(checkpoint)
        if (
            handoff.get("target_ready") is True
            and str(handoff.get("state") or "").strip() == "pending-voluntary-exit"
        ):
            gate.update(
                {
                    "status": "protected-session-deferred",
                    "checked_at": _utc_now(),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return [
                "Login continuity: a target-slot peer is Ready and serving while exact "
                "original SSH sessions remain protected for voluntary exit."
            ]
        raise
    handoff = _controller_bridge_login_handoff(checkpoint)
    if str(handoff.get("state") or "").strip() != "complete":
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade cannot release the protected source login Pod before the "
            "canonical login handoff is complete, including an exact ready target "
            "endpoint and explicit acknowledgement for every disappeared SSH socket."
        )
    lines = _ensure_active_login_session_hold(
        checkpoint=checkpoint,
        gate=gate,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        pod_names=tuple(sorted(pod_names)),
        checkpoint_writer=checkpoint_writer,
    )
    canonical = _mapping(checkpoint.get("active_login_session_hold"))
    if str(canonical.get("status") or "").strip() != "released":
        gate.update(
            {
                "status": "pending-session-drain",
                "checked_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade target-slot login peer is Ready and serving, but the exact "
            "protected SSH session is still active. Keep the hold installed; after that "
            "session drains, rerun to release it and finish the full login rollout."
        )
    gate["status"] = "released"
    gate["released_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        *handoff_lines,
        *(lines or []),
        "Login continuity: target-slot peer and voluntary handoff verified before hold release.",
    ]


def _wait_for_jail_target_availability_or_defer_protected_login(
    *,
    checkpoint: Mapping[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    release_gate = _mapping(phase.get("login_hold_release_before_full_rollout"))
    if release_gate.get("status") == "protected-session-deferred":
        handoff = _controller_bridge_login_handoff(checkpoint)
        if (
            handoff.get("target_ready") is not True
            or str(handoff.get("state") or "").strip() != "pending-voluntary-exit"
        ):
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade cannot defer target availability without an exact Ready "
                "target login peer and protected voluntary-exit state."
            )
        phase["target_availability"] = {
            "status": "deferred-protected-login",
            "reason": "exact original SSH sessions remain protected",
            "checked_at": _utc_now(),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
        return
    _wait_for_target_slurmcluster_available(
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        timeout_seconds=900,
    )


def _persistent_mount_failed_job_recovery_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    job_name: str,
    job_uid: str,
    job_contract: Mapping[str, Any],
) -> dict[str, Any]:
    """Prove that an exact retained legacy copy Job failed in its owned Pod with exit 19."""

    exists, live_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"job/{job_name}",
        namespace=namespace,
    )
    live_uid = str(_mapping(live_job.get("metadata")).get("uid") or "").strip()
    if (
        not exists
        or not job_uid
        or live_uid != job_uid
        or _passive_populate_job_contract(live_job) != to_plain_data(job_contract)
        or not _job_condition_true(live_job, "Failed")
    ):
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery requires the retained failed Job's exact "
            "checkpointed UID, contract, and Failed condition."
        )
    pods_result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=30,
        check=False,
    )
    if pods_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery could not verify the retained failed Job's owned Pod."
        )
    try:
        pods_payload = json.loads(pods_result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery Pod lookup returned invalid JSON."
        ) from exc
    owned_pods: list[Mapping[str, Any]] = []
    for pod in _sequence_of_mappings(_mapping(pods_payload).get("items")):
        metadata = _mapping(pod.get("metadata"))
        owner_matches = any(
            str(owner.get("apiVersion") or "").strip() == "batch/v1"
            and str(owner.get("kind") or "").strip() == "Job"
            and str(owner.get("name") or "").strip() == job_name
            and str(owner.get("uid") or "").strip() == job_uid
            and _bool_value(owner.get("controller"), fallback=False)
            for owner in _sequence_of_mappings(metadata.get("ownerReferences"))
        )
        if owner_matches:
            owned_pods.append(pod)
    if len(owned_pods) != 1:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery requires exactly one controller-owner-bound Pod "
            "for the retained failed Job."
        )
    pod = owned_pods[0]
    pod_metadata = _mapping(pod.get("metadata"))
    pod_name = str(pod_metadata.get("name") or "").strip()
    pod_uid = str(pod_metadata.get("uid") or "").strip()
    statuses = [
        item
        for item in _sequence_of_mappings(_mapping(pod.get("status")).get("containerStatuses"))
        if str(item.get("name") or "").strip() == "persistent-mount-migration"
    ]
    terminated = (
        _mapping(_mapping(statuses[0].get("state")).get("terminated")) if len(statuses) == 1 else {}
    )
    exit_code = terminated.get("exitCode")
    if not pod_name or not pod_uid or len(statuses) != 1 or exit_code != 19:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery is permitted only when the exact owner-bound "
            "persistent-mount-migration container terminated with exit code 19."
        )
    log_result = command_runner(
        ["kubectl", "--context", kube_context, "-n", namespace, "logs", f"job/{job_name}"],
        timeout_seconds=120,
        check=False,
    )
    if log_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery could not read the retained failed Job logs."
        )
    failure_prefix = "persistent mount migration content verification failed: "
    failed_mounts = [
        line.strip().removeprefix(failure_prefix).strip()
        for line in str(log_result.stdout or "").splitlines()
        if line.strip().startswith(failure_prefix)
    ]
    if len(failed_mounts) != 1 or not failed_mounts[0]:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery requires exactly one failed-mount proof in the "
            "retained original Job logs."
        )
    return {
        "job_name": job_name,
        "job_uid": job_uid,
        "pod_name": pod_name,
        "pod_uid": pod_uid,
        "container": "persistent-mount-migration",
        "exit_code": 19,
        "failed_mount_path": failed_mounts[0],
        "logs_sha256": hashlib.sha256(str(log_result.stdout or "").encode("utf-8")).hexdigest(),
    }


def _ensure_persistent_mount_recovery_writer_hold(
    *,
    phase: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
) -> None:
    writer_state = _mapping(phase.get("persistent_migration_writer_hold"))
    if str(writer_state.get("status") or "").strip() != "held":
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery requires the checkpointed writer hold to remain held."
        )
    drift = _persistent_migration_writer_hold_drift(
        command_runner=command_runner,
        kube_context=kube_context,
        state=writer_state,
        namespace=namespace,
    )
    if drift:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery refuses to run because the checkpointed writer "
            "hold identity or live-zero state drifted."
        )


def _persistent_mount_recovery_succeeded_pod_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    job_name: str,
    job_uid: str,
    operation_label: str = "Persistent mount recovery",
) -> dict[str, Any]:
    pods_result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=30,
        check=False,
    )
    if pods_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"{operation_label} could not verify its owner-bound succeeded Pod."
        )
    try:
        payload = json.loads(pods_result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            f"{operation_label} Pod lookup returned invalid JSON."
        ) from exc
    owned: list[Mapping[str, Any]] = []
    for pod in _sequence_of_mappings(_mapping(payload).get("items")):
        metadata = _mapping(pod.get("metadata"))
        if any(
            str(owner.get("apiVersion") or "").strip() == "batch/v1"
            and str(owner.get("kind") or "").strip() == "Job"
            and str(owner.get("name") or "").strip() == job_name
            and str(owner.get("uid") or "").strip() == job_uid
            and _bool_value(owner.get("controller"), fallback=False)
            for owner in _sequence_of_mappings(metadata.get("ownerReferences"))
        ):
            owned.append(pod)
    if len(owned) != 1:
        raise SoperatorMigrationPhasePending(
            f"{operation_label} requires exactly one controller-owner-bound Pod."
        )
    pod = owned[0]
    metadata = _mapping(pod.get("metadata"))
    pod_name = str(metadata.get("name") or "").strip()
    pod_uid = str(metadata.get("uid") or "").strip()
    status = _mapping(pod.get("status"))
    container_statuses = [
        item
        for item in _sequence_of_mappings(status.get("containerStatuses"))
        if str(item.get("name") or "").strip() == "persistent-mount-migration"
    ]
    terminated = (
        _mapping(_mapping(container_statuses[0].get("state")).get("terminated"))
        if len(container_statuses) == 1
        else {}
    )
    if (
        not pod_name
        or not pod_uid
        or str(status.get("phase") or "").strip() != "Succeeded"
        or terminated.get("exitCode") != 0
    ):
        raise SoperatorMigrationPhasePending(
            f"{operation_label} owner-bound Pod did not succeed with container exit 0."
        )
    return {
        "name": pod_name,
        "uid": pod_uid,
        "job_name": job_name,
        "job_uid": job_uid,
        "container": "persistent-mount-migration",
        "exit_code": 0,
    }


def _validate_persistent_mount_job_controller_binding(
    job: Mapping[str, Any],
    *,
    expected_name: str,
    expected_uid: str,
) -> None:
    metadata = _mapping(job.get("metadata"))
    spec = _mapping(job.get("spec"))
    live_name = str(metadata.get("name") or "").strip()
    live_uid = str(metadata.get("uid") or "").strip()
    selector_labels = _mapping(_mapping(spec.get("selector")).get("matchLabels"))
    template_labels = _mapping(
        _mapping(_mapping(spec.get("template")).get("metadata")).get("labels")
    )
    controller_uid = str(selector_labels.get("batch.kubernetes.io/controller-uid") or "").strip()
    template_controller_uid = str(
        template_labels.get("batch.kubernetes.io/controller-uid") or ""
    ).strip()
    selector_job_name = str(selector_labels.get("batch.kubernetes.io/job-name") or "").strip()
    template_job_name = str(template_labels.get("batch.kubernetes.io/job-name") or "").strip()
    if (
        not expected_name
        or not expected_uid
        or live_name != expected_name
        or live_uid != expected_uid
        or _bool_value(spec.get("manualSelector"), fallback=False)
        or controller_uid != expected_uid
        or template_controller_uid != expected_uid
        or (selector_job_name and selector_job_name != expected_name)
        or template_job_name != expected_name
    ):
        raise SoperatorMigrationPhasePending(
            "Persistent mount migration Job auto-selector/controller UID binding is "
            "missing or changed."
        )


def _execute_failed_persistent_mount_recovery(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    migration_state: dict[str, Any],
    original_job: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    jail_pvc: str,
    entries: Sequence[Mapping[str, Any]],
    scheduling: Mapping[str, Any] | None,
    namespace: str,
    checkpoint_writer: Callable[[], None] | None,
) -> tuple[str, dict[str, str]]:
    original_name = str(original_job.get("name") or "").strip()
    original_uid = str(original_job.get("uid") or "").strip()
    original_operation_token = str(original_job.get("operation_token") or "").strip()
    original_pvc_uid = str(original_job.get("pvc_uid") or "").strip()
    original_contract = _mapping(original_job.get("contract"))
    if not original_operation_token or not original_pvc_uid:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery requires the original copy operation token and "
            "checkpointed PVC UID."
        )
    if _positive_int(original_job.get("copy_schema_version"), fallback=0) >= (
        _PERSISTENT_MOUNT_COPY_SCHEMA_VERSION
    ):
        raise SoperatorMigrationPhasePending(
            "The schema-v2 persistent mount copy Job failed; automatic legacy exit-19 "
            "recovery is not applicable."
        )
    _ensure_persistent_mount_recovery_writer_hold(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
    )
    original_evidence = _persistent_mount_failed_job_recovery_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        job_name=original_name,
        job_uid=original_uid,
        job_contract=original_contract,
    )
    failed_mount_path = str(original_evidence.get("failed_mount_path") or "").strip()
    failed_entries = [
        entry
        for entry in entries
        if str(entry.get("mount_path") or "").strip() == failed_mount_path
    ]
    if (
        len(failed_entries) != 1
        or str(failed_entries[0].get("source_status") or "").strip() != "present"
    ):
        raise SoperatorMigrationPhasePending(
            "The retained exit-19 failed mount is not exactly one checkpoint-present "
            "persistent migration entry."
        )
    first_mount_path = str(entries[0].get("mount_path") or "").strip() if entries else ""
    if failed_mount_path != first_mount_path:
        raise SoperatorMigrationPhasePending(
            "The retained schema-v1 copy failed after an earlier mount entry may already "
            "have been processed. Automatic recovery is allowed only when the failed "
            "mount is the first checkpoint entry; preserve the failed Job and reconcile "
            "the earlier targets and markers manually before continuing."
        )
    existing_recovery = _mapping(migration_state.get("recovery"))
    operation_token = (
        str(existing_recovery.get("operation_token") or "").strip() or uuid4().hex[:12]
    )
    manifest = _persistent_mount_migration_job_manifest(
        target_ref=target_ref,
        namespace=namespace,
        image=_CONTROLLER_SPOOL_CLEANUP_IMAGE,
        jail_pvc=jail_pvc,
        entries=entries,
        scheduling=scheduling,
        operation_token=operation_token,
        recovery_mode=True,
        recovery_of_job_uid=original_uid,
        copy_operation_token=original_operation_token,
        recovery_mount_path=failed_mount_path,
    )
    metadata = manifest.setdefault("metadata", {})
    if not isinstance(metadata, dict):
        raise RuntimeError("Persistent mount recovery Job metadata must be a mapping.")
    base_name = f"{str(metadata.get('name') or '').strip()}-recovery"
    suffix = f"-{operation_token}"
    metadata["name"] = f"{base_name[: 63 - len(suffix)].rstrip('-')}{suffix}"
    recovery_name = str(metadata["name"])
    proposed = {
        "status": "intent-recorded",
        "name": recovery_name,
        "pvc": jail_pvc,
        "pvc_uid": original_pvc_uid,
        "image": _CONTROLLER_SPOOL_CLEANUP_IMAGE,
        "operation_token": operation_token,
        "copy_operation_token": original_operation_token,
        "copy_schema_version": _PERSISTENT_MOUNT_COPY_SCHEMA_VERSION,
        "contract": _persistent_mount_recovery_job_contract(manifest),
        "original_job": dict(original_evidence),
        "failed_mount_path": failed_mount_path,
    }
    if existing_recovery:
        for key in (
            "name",
            "pvc",
            "pvc_uid",
            "image",
            "operation_token",
            "copy_operation_token",
            "copy_schema_version",
            "contract",
            "original_job",
            "failed_mount_path",
        ):
            if to_plain_data(existing_recovery.get(key)) != to_plain_data(proposed[key]):
                raise SoperatorMigrationPhasePending(
                    "Persistent mount recovery intent drifted from its exact failed Job, "
                    "Pod, PVC, image, operation token, or Job contract."
                )
    recovery_state = {**proposed, **dict(existing_recovery)}
    migration_state["recovery"] = recovery_state
    if checkpoint_writer is not None:
        checkpoint_writer()
    _bind_passive_populate_pvc_uid(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state=recovery_state,
        pvc=jail_pvc,
        allow_initial_binding=False,
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    live_exists, live_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"job/{recovery_name}",
        namespace=namespace,
    )
    if live_exists:
        live_uid = str(_mapping(live_job.get("metadata")).get("uid") or "").strip()
        expected_uid = str(recovery_state.get("uid") or "").strip()
        if (
            not live_uid
            or (expected_uid and live_uid != expected_uid)
            or _persistent_mount_recovery_job_contract(live_job) != proposed["contract"]
        ):
            raise SoperatorMigrationPhasePending(
                "Live persistent mount recovery Job changed immutable UID or exact contract."
            )
        if _job_condition_true(live_job, "Failed"):
            raise SoperatorMigrationPhasePending(
                "The UID-bound persistent mount recovery Job failed and was retained."
            )
        if not expected_uid:
            recovery_state["uid"] = live_uid
            if checkpoint_writer is not None:
                checkpoint_writer()
        _validate_persistent_mount_job_controller_binding(
            live_job,
            expected_name=recovery_name,
            expected_uid=live_uid,
        )
    else:
        if any(
            str(recovery_state.get(key) or "").strip()
            for key in ("apply_started_at", "applied_at", "uid")
        ):
            raise SoperatorMigrationPhasePending(
                "The UID-bound persistent mount recovery Job disappeared after apply; "
                "it will not be recreated."
            )
        recovery_state["apply_started_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=(manifest,),
            timeout_seconds=300,
        )
        applied_exists, applied_job = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"job/{recovery_name}",
            namespace=namespace,
        )
        applied_uid = str(_mapping(applied_job.get("metadata")).get("uid") or "").strip()
        if (
            not applied_exists
            or not applied_uid
            or _persistent_mount_recovery_job_contract(applied_job) != proposed["contract"]
        ):
            raise SoperatorMigrationPhasePending(
                "Persistent mount recovery Job was applied but its exact contract and UID "
                "could not be bound."
            )
        recovery_state.update({"uid": applied_uid, "action": "created", "applied_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        _validate_persistent_mount_job_controller_binding(
            applied_job,
            expected_name=recovery_name,
            expected_uid=applied_uid,
        )
    recovery_state["status"] = "running"
    if checkpoint_writer is not None:
        checkpoint_writer()
    _wait_for_job_complete_or_failed(
        command_runner=command_runner,
        kube_context=kube_context,
        name=recovery_name,
        namespace=namespace,
        timeout_seconds=3900,
        job_label="Soperator persistent mount recovery Job",
    )
    completed_exists, completed_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"job/{recovery_name}",
        namespace=namespace,
    )
    completed_uid = str(_mapping(completed_job.get("metadata")).get("uid") or "").strip()
    if (
        not completed_exists
        or not completed_uid
        or completed_uid != str(recovery_state.get("uid") or "").strip()
        or _persistent_mount_recovery_job_contract(completed_job) != proposed["contract"]
        or not _job_condition_true(completed_job, "Complete")
        or _job_condition_true(completed_job, "Failed")
    ):
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery Job identity, contract, or Complete condition "
            "changed before checkpoint completion."
        )
    _validate_persistent_mount_job_controller_binding(
        completed_job,
        expected_name=recovery_name,
        expected_uid=completed_uid,
    )
    recovery_pod_evidence = _persistent_mount_recovery_succeeded_pod_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        job_name=recovery_name,
        job_uid=completed_uid,
    )
    checkpointed_recovery_pod = _mapping(recovery_state.get("pod"))
    if checkpointed_recovery_pod and checkpointed_recovery_pod != recovery_pod_evidence:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery owner-bound Pod identity drifted from checkpoint."
        )
    recovery_state["pod"] = recovery_pod_evidence
    if checkpoint_writer is not None:
        checkpoint_writer()
    _bind_passive_populate_pvc_uid(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state=recovery_state,
        pvc=jail_pvc,
        allow_initial_binding=False,
    )
    _ensure_persistent_mount_recovery_writer_hold(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
    )
    final_original_evidence = _persistent_mount_failed_job_recovery_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        job_name=original_name,
        job_uid=original_uid,
        job_contract=original_contract,
    )
    if final_original_evidence != original_evidence:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery original failed Job or owner-bound Pod identity drifted."
        )
    log_result = command_runner(
        ["kubectl", "--context", kube_context, "-n", namespace, "logs", f"job/{recovery_name}"],
        timeout_seconds=120,
        check=False,
    )
    if log_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "Soperator persistent mount recovery Job completed, but its proof logs "
            f"could not be read: {_command_detail(log_result)}"
        )
    try:
        statuses = _persistent_mount_migration_copy_status_by_log(log_result.stdout)
    except ValueError as exc:
        raise SoperatorMigrationPhasePending(str(exc)) from exc
    expected_mounts = {str(entry.get("mount_path") or "").strip() for entry in entries}
    if not expected_mounts or set(statuses) != expected_mounts:
        raise SoperatorMigrationPhasePending(
            "Soperator persistent mount recovery Job logs did not prove exactly one "
            "durable-marker result for every checkpoint-bound mount."
        )
    post_log_exists, post_log_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"job/{recovery_name}",
        namespace=namespace,
    )
    post_log_uid = str(_mapping(post_log_job.get("metadata")).get("uid") or "").strip()
    if (
        not post_log_exists
        or post_log_uid != completed_uid
        or _persistent_mount_recovery_job_contract(post_log_job) != proposed["contract"]
        or not _job_condition_true(post_log_job, "Complete")
        or _job_condition_true(post_log_job, "Failed")
    ):
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery Job changed after proof logs were read."
        )
    _validate_persistent_mount_job_controller_binding(
        post_log_job,
        expected_name=recovery_name,
        expected_uid=post_log_uid,
    )
    post_log_pod_evidence = _persistent_mount_recovery_succeeded_pod_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        job_name=recovery_name,
        job_uid=completed_uid,
    )
    if post_log_pod_evidence != recovery_pod_evidence:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery owner-bound Pod changed after proof logs were read."
        )
    _bind_passive_populate_pvc_uid(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state=recovery_state,
        pvc=jail_pvc,
        allow_initial_binding=False,
    )
    _ensure_persistent_mount_recovery_writer_hold(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
    )
    post_log_original_evidence = _persistent_mount_failed_job_recovery_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        job_name=original_name,
        job_uid=original_uid,
        job_contract=original_contract,
    )
    if post_log_original_evidence != original_evidence:
        raise SoperatorMigrationPhasePending(
            "Persistent mount recovery original failure evidence changed after proof logs."
        )
    recovery_state.update({"status": "completed", "completed_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return recovery_name, statuses


def _execute_legacy_persistent_mount_migration(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    image: str,
    jail_pvc: str,
    entries: Sequence[Mapping[str, Any]],
    scheduling: Mapping[str, Any] | None,
    namespace: str = _SOPERATOR_NAMESPACE,
    checkpoint_writer: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    migration_state = phase.setdefault("legacy_persistent_mount_migration", {})
    if not isinstance(migration_state, dict):
        raise RuntimeError(
            "populate-jail-refresh.legacy_persistent_mount_migration must be a mapping."
        )
    if not entries:
        migration_state["status"] = "not_required"
        return False, []
    if migration_state.get("status") == "completed":
        return False, ["Persistent mount migration already completed in checkpoint."]
    existing_job = _mapping(migration_state.get("job"))
    existing_recovery = _mapping(migration_state.get("recovery"))
    if existing_recovery and not existing_job:
        raise SoperatorMigrationPhasePending(
            "Persistent mount migration recovery checkpoint lacks its retained original Job."
        )
    checkpointed_entries = _sequence_of_mappings(migration_state.get("entries"))
    if (existing_job or existing_recovery) and _persistent_mount_migration_entry_binding(
        checkpointed_entries
    ) != _persistent_mount_migration_entry_binding(entries):
        raise SoperatorMigrationPhasePending(
            "Persistent mount migration mount entries drifted from the checkpointed exact "
            "source, target, marker, mount-path, or present/absent binding."
        )
    operation_token = str(existing_job.get("operation_token") or "").strip() or uuid4().hex[:12]
    copy_job_image = (
        str(existing_job.get("image") or "").strip()
        if existing_job
        else _CONTROLLER_SPOOL_CLEANUP_IMAGE
    )
    manifest = _persistent_mount_migration_job_manifest(
        target_ref=target_ref,
        namespace=namespace,
        image=copy_job_image,
        jail_pvc=jail_pvc,
        entries=entries,
        scheduling=scheduling,
        operation_token=operation_token,
    )
    metadata = manifest.setdefault("metadata", {})
    if not isinstance(metadata, dict):
        raise RuntimeError("Persistent mount migration Job metadata must be a mapping.")
    base_name = str(metadata.get("name") or "").strip()
    suffix = f"-{operation_token}"
    metadata["name"] = f"{base_name[: 63 - len(suffix)].rstrip('-')}{suffix}"
    annotations = metadata.setdefault("annotations", {})
    if not isinstance(annotations, dict):
        raise RuntimeError("Persistent mount migration Job annotations must be a mapping.")
    annotations[_CXCLI_JOB_OPERATION_ANNOTATION] = operation_token
    job_name = str(metadata.get("name") or "")
    proposed_job = {
        "name": job_name,
        "pvc": jail_pvc,
        "image": copy_job_image,
        "operation_token": operation_token,
        "copy_schema_version": _PERSISTENT_MOUNT_COPY_SCHEMA_VERSION,
        "contract": _persistent_mount_copy_job_contract(manifest),
    }
    if existing_job:
        # The checkpointed contract remains authoritative for an already-applied Job.
        # This permits a retained schema-v1 exit-19 Job to be proven and recovered
        # without pretending that it was created from the current schema-v2 script.
        for key in ("name", "pvc", "image", "operation_token"):
            if to_plain_data(existing_job.get(key)) != to_plain_data(proposed_job[key]):
                raise SoperatorMigrationPhasePending(
                    "Persistent mount migration Job contract drifted from its checkpointed "
                    "name, PVC, image, scheduling, or pod-security binding. Refusing to "
                    "delete, overwrite, or reuse the Job."
                )
        if not _mapping(existing_job.get("contract")):
            raise SoperatorMigrationPhasePending(
                "The checkpointed persistent mount migration Job lacks its exact contract."
            )
        job_state = dict(existing_job)
    else:
        job_state = dict(proposed_job)
    expected_job_contract = _mapping(job_state.get("contract"))
    job_copy_schema_version = _positive_int(job_state.get("copy_schema_version"), fallback=0)
    _bind_passive_populate_pvc_uid(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state=job_state,
        pvc=jail_pvc,
        allow_initial_binding=not bool(existing_job),
    )
    migration_state.update(
        {
            "status": "running",
            "job": job_state,
            "entries": [dict(to_plain_data(entry)) for entry in entries],
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    live_exists, live_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"job/{job_name}",
        namespace=namespace,
    )
    if live_exists:
        if (
            _persistent_mount_checkpoint_job_contract(
                live_job,
                copy_schema_version=job_copy_schema_version,
            )
            != expected_job_contract
        ):
            raise SoperatorMigrationPhasePending(
                "Live persistent mount migration Job does not match the checkpointed exact "
                "contract. Refusing to delete, overwrite, or reuse it."
            )
        live_uid = str(_mapping(live_job.get("metadata")).get("uid") or "").strip()
        expected_uid = str(job_state.get("uid") or "").strip()
        if not live_uid or (expected_uid and live_uid != expected_uid):
            raise SoperatorMigrationPhasePending(
                "Live persistent mount migration Job UID does not match the checkpointed "
                "immutable identity. Refusing to delete or reuse it."
            )
        if not expected_uid:
            job_state["uid"] = live_uid
            migration_state["job"] = job_state
            if checkpoint_writer is not None:
                checkpoint_writer()
        if job_copy_schema_version >= _PERSISTENT_MOUNT_COPY_SCHEMA_VERSION:
            _validate_persistent_mount_job_controller_binding(
                live_job,
                expected_name=job_name,
                expected_uid=live_uid,
            )
    else:
        if (
            str(existing_job.get("apply_started_at") or "").strip()
            or str(existing_job.get("applied_at") or "").strip()
            or str(existing_job.get("uid") or "").strip()
        ):
            raise SoperatorMigrationPhasePending(
                "The UID-bound persistent mount migration Job disappeared after apply. "
                "Refusing to recreate it against a possibly partial target."
            )
        job_state["apply_started_at"] = _utc_now()
        migration_state["job"] = job_state
        if checkpoint_writer is not None:
            checkpoint_writer()
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=(manifest,),
            timeout_seconds=300,
        )
        applied_exists, applied_job = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"job/{job_name}",
            namespace=namespace,
        )
        applied_uid = str(_mapping(applied_job.get("metadata")).get("uid") or "").strip()
        if (
            not applied_exists
            or not applied_uid
            or _persistent_mount_checkpoint_job_contract(
                applied_job,
                copy_schema_version=job_copy_schema_version,
            )
            != expected_job_contract
        ):
            raise SoperatorMigrationPhasePending(
                "Persistent mount migration Job was applied, but its immutable UID and exact "
                "contract could not be bound before waiting. Legacy writers remain stopped "
                "until the Job is reconciled."
            )
        job_state["uid"] = applied_uid
        job_state["action"] = "created"
        job_state["applied_at"] = _utc_now()
        migration_state["job"] = job_state
        if checkpoint_writer is not None:
            checkpoint_writer()
        _validate_persistent_mount_job_controller_binding(
            applied_job,
            expected_name=job_name,
            expected_uid=applied_uid,
        )
    result_job_name = job_name
    fresh_schema2_completed_uid = ""
    fresh_schema2_pod_evidence: dict[str, Any] = {}
    if live_exists and _job_condition_true(live_job, "Failed"):
        if not str(existing_job.get("uid") or "").strip():
            raise SoperatorMigrationPhasePending(
                "Persistent mount recovery requires the failed original Job UID to have "
                "been checkpointed before failure reconciliation."
            )
        result_job_name, copy_status_by_mount = _execute_failed_persistent_mount_recovery(
            checkpoint=checkpoint,
            phase=phase,
            migration_state=migration_state,
            original_job=job_state,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            jail_pvc=jail_pvc,
            entries=entries,
            scheduling=scheduling,
            namespace=namespace,
            checkpoint_writer=checkpoint_writer,
        )
    else:
        _wait_for_job_complete_or_failed(
            command_runner=command_runner,
            kube_context=kube_context,
            name=job_name,
            namespace=namespace,
            timeout_seconds=3900,
            job_label="Soperator persistent mount migration Job",
        )
        completed_exists, completed_job = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"job/{job_name}",
            namespace=namespace,
        )
        completed_uid = str(_mapping(completed_job.get("metadata")).get("uid") or "").strip()
        expected_uid = str(job_state.get("uid") or "").strip()
        if (
            not completed_exists
            or not completed_uid
            or (expected_uid and completed_uid != expected_uid)
            or _persistent_mount_checkpoint_job_contract(
                completed_job,
                copy_schema_version=job_copy_schema_version,
            )
            != expected_job_contract
            or not _job_condition_true(completed_job, "Complete")
            or _job_condition_true(completed_job, "Failed")
        ):
            raise SoperatorMigrationPhasePending(
                "Persistent mount migration Job identity or exact contract changed before "
                "completion could be checkpointed."
            )
        if job_copy_schema_version >= _PERSISTENT_MOUNT_COPY_SCHEMA_VERSION:
            _validate_persistent_mount_job_controller_binding(
                completed_job,
                expected_name=job_name,
                expected_uid=completed_uid,
            )
            fresh_schema2_pod_evidence = _persistent_mount_recovery_succeeded_pod_evidence(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                job_name=job_name,
                job_uid=completed_uid,
                operation_label="Persistent mount copy",
            )
            checkpointed_copy_pod = _mapping(job_state.get("pod"))
            if checkpointed_copy_pod and checkpointed_copy_pod != fresh_schema2_pod_evidence:
                raise SoperatorMigrationPhasePending(
                    "Persistent mount copy owner-bound Pod identity drifted from checkpoint."
                )
            job_state["pod"] = fresh_schema2_pod_evidence
            migration_state["job"] = job_state
            _bind_passive_populate_pvc_uid(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                state=job_state,
                pvc=jail_pvc,
                allow_initial_binding=False,
            )
            fresh_schema2_completed_uid = completed_uid
            if checkpoint_writer is not None:
                checkpoint_writer()
        job_state["uid"] = completed_uid
        migration_state["job"] = job_state
        if checkpoint_writer is not None:
            checkpoint_writer()
        log_result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "logs",
                f"job/{job_name}",
            ],
            timeout_seconds=120,
            check=False,
        )
        if log_result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "Soperator persistent mount migration Job completed, but its proof-of-copy "
                f"logs could not be read: {_command_detail(log_result)}"
            )
        try:
            copy_status_by_mount = _persistent_mount_migration_copy_status_by_log(log_result.stdout)
        except ValueError as exc:
            raise SoperatorMigrationPhasePending(str(exc)) from exc
    expected_mounts = {
        str(entry.get("mount_path") or "").strip()
        for entry in _sequence_of_mappings(migration_state.get("entries"))
    }
    if not expected_mounts or set(copy_status_by_mount) != expected_mounts:
        missing = sorted(expected_mounts - set(copy_status_by_mount))
        unexpected = sorted(set(copy_status_by_mount) - expected_mounts)
        raise SoperatorMigrationPhasePending(
            "Soperator persistent mount migration Job logs did not prove exactly one "
            "recognized durable-marker result for every mount"
            + (f"; missing={missing}" if missing else "")
            + (f"; unexpected={unexpected}" if unexpected else "")
            + "."
        )
    if fresh_schema2_completed_uid:
        post_log_exists, post_log_job = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"job/{job_name}",
            namespace=namespace,
        )
        post_log_uid = str(_mapping(post_log_job.get("metadata")).get("uid") or "").strip()
        if (
            not post_log_exists
            or post_log_uid != fresh_schema2_completed_uid
            or _persistent_mount_checkpoint_job_contract(
                post_log_job,
                copy_schema_version=job_copy_schema_version,
            )
            != expected_job_contract
            or not _job_condition_true(post_log_job, "Complete")
            or _job_condition_true(post_log_job, "Failed")
        ):
            raise SoperatorMigrationPhasePending(
                "Persistent mount copy Job changed after proof logs were read."
            )
        _validate_persistent_mount_job_controller_binding(
            post_log_job,
            expected_name=job_name,
            expected_uid=post_log_uid,
        )
        post_log_pod_evidence = _persistent_mount_recovery_succeeded_pod_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            job_name=job_name,
            job_uid=post_log_uid,
            operation_label="Persistent mount copy",
        )
        if post_log_pod_evidence != fresh_schema2_pod_evidence:
            raise SoperatorMigrationPhasePending(
                "Persistent mount copy owner-bound Pod changed after proof logs were read."
            )
        _bind_passive_populate_pvc_uid(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            state=job_state,
            pvc=jail_pvc,
            allow_initial_binding=False,
        )
    for entry in migration_state["entries"]:
        if isinstance(entry, dict):
            mount_path = str(entry.get("mount_path") or "")
            copy_status = copy_status_by_mount.get(mount_path)
            if copy_status not in {"copied", "source_missing", "skipped"}:
                raise SoperatorMigrationPhasePending(
                    "Soperator persistent mount migration lacks a recognized copy result "
                    f"for {mount_path or '<empty>'}."
                )
            entry["copy_status"] = copy_status
            entry["status"] = "completed"
    migration_state["status"] = "completed"
    migration_state["completed_at"] = _utc_now()
    _sync_persistent_mount_decisions_from_migration_entries(
        checkpoint,
        _sequence_of_mappings(migration_state.get("entries")),
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    copied = sum(
        1
        for entry in migration_state["entries"]
        if isinstance(entry, Mapping) and entry.get("copy_status") == "copied"
    )
    missing = sum(
        1
        for entry in migration_state["entries"]
        if isinstance(entry, Mapping) and entry.get("copy_status") == "source_missing"
    )
    skipped = sum(
        1
        for entry in migration_state["entries"]
        if isinstance(entry, Mapping) and entry.get("copy_status") == "skipped"
    )
    detail = f"copied={copied}, source_missing={missing}, skipped={skipped}"
    return True, [f"Persistent mount migration job completed: {result_job_name} ({detail})."]


def _passive_populate_job_contract(job: Mapping[str, Any]) -> dict[str, Any]:
    metadata = _mapping(job.get("metadata"))
    spec = _mapping(job.get("spec"))
    template = _mapping(spec.get("template"))
    pod_spec = _mapping(template.get("spec"))
    container = next(
        (
            item
            for item in _sequence_of_mappings(pod_spec.get("containers"))
            if str(item.get("name") or "").strip() == "populate-jail"
        ),
        {},
    )
    jail_volume = next(
        (
            item
            for item in _sequence_of_mappings(pod_spec.get("volumes"))
            if str(item.get("name") or "").strip() == "jail-rootfs"
        ),
        {},
    )
    jail_mount = next(
        (
            item
            for item in _sequence_of_mappings(container.get("volumeMounts"))
            if str(item.get("name") or "").strip() == "jail-rootfs"
        ),
        {},
    )
    labels = _mapping(metadata.get("labels"))
    annotations = _mapping(metadata.get("annotations"))
    tolerations = [
        to_plain_data(item)
        for item in _sequence_of_mappings(pod_spec.get("tolerations"))
        if not (
            str(item.get("key") or "").strip()
            in {
                "node.kubernetes.io/not-ready",
                "node.kubernetes.io/unreachable",
            }
            and str(item.get("effect") or "").strip() == "NoExecute"
            and str(item.get("operator") or "Exists").strip() == "Exists"
            and _positive_int(item.get("tolerationSeconds"), fallback=0) == 300
        )
    ]
    normalized_containers = [
        {
            "name": str(item.get("name") or "").strip(),
            "image": str(item.get("image") or "").strip(),
            "image_pull_policy": str(item.get("imagePullPolicy") or "").strip(),
            "command": to_plain_data(item.get("command") or []),
            "args": to_plain_data(item.get("args") or []),
            "env": to_plain_data(item.get("env") or []),
            "env_from": to_plain_data(item.get("envFrom") or []),
            "security_context": to_plain_data(_mapping(item.get("securityContext"))),
            "resources": to_plain_data(_mapping(item.get("resources"))),
            "volume_mounts": [
                {
                    "name": str(mount.get("name") or "").strip(),
                    "mount_path": str(mount.get("mountPath") or "").strip(),
                    "read_only": bool(mount.get("readOnly", False)),
                    "sub_path": str(mount.get("subPath") or "").strip(),
                    "sub_path_expr": str(mount.get("subPathExpr") or "").strip(),
                }
                for mount in _sequence_of_mappings(item.get("volumeMounts"))
            ],
        }
        for item in _sequence_of_mappings(pod_spec.get("containers"))
    ]
    normalized_volumes = [
        {
            "name": str(item.get("name") or "").strip(),
            "persistent_volume_claim": {
                "claim_name": str(
                    _mapping(item.get("persistentVolumeClaim")).get("claimName") or ""
                ).strip(),
                "read_only": bool(
                    _mapping(item.get("persistentVolumeClaim")).get("readOnly", False)
                ),
            },
            "host_path": to_plain_data(_mapping(item.get("hostPath"))),
            "secret": to_plain_data(_mapping(item.get("secret"))),
            "config_map": to_plain_data(_mapping(item.get("configMap"))),
            "empty_dir": to_plain_data(_mapping(item.get("emptyDir"))),
            "projected": to_plain_data(_mapping(item.get("projected"))),
        }
        for item in _sequence_of_mappings(pod_spec.get("volumes"))
    ]
    return {
        "name": str(metadata.get("name") or "").strip(),
        "namespace": str(metadata.get("namespace") or _SOPERATOR_NAMESPACE).strip(),
        "slot": str(labels.get("slurm.nebius.ai/jail-rootfs-slot") or "").strip(),
        "operation_token": str(
            annotations.get(_PASSIVE_POPULATE_OPERATION_ANNOTATION)
            or annotations.get(_CXCLI_JOB_OPERATION_ANNOTATION)
            or ""
        ).strip(),
        "image": str(container.get("image") or "").strip(),
        "image_pull_policy": str(container.get("imagePullPolicy") or "").strip(),
        "claim_name": str(
            _mapping(jail_volume.get("persistentVolumeClaim")).get("claimName") or ""
        ).strip(),
        "mount_path": str(jail_mount.get("mountPath") or "").strip(),
        "automount_service_account_token": pod_spec.get("automountServiceAccountToken"),
        "restart_policy": str(pod_spec.get("restartPolicy") or "").strip(),
        "node_selector": to_plain_data(_mapping(pod_spec.get("nodeSelector"))),
        "affinity": to_plain_data(_mapping(pod_spec.get("affinity"))),
        "tolerations": tolerations,
        "backoff_limit": spec.get("backoffLimit"),
        "containers": normalized_containers,
        "init_containers": to_plain_data(pod_spec.get("initContainers") or []),
        "ephemeral_containers": to_plain_data(pod_spec.get("ephemeralContainers") or []),
        "volumes": normalized_volumes,
        "service_account_name": str(pod_spec.get("serviceAccountName") or "default").strip(),
        "pod_security_context": to_plain_data(_mapping(pod_spec.get("securityContext"))),
        "host_network": bool(pod_spec.get("hostNetwork", False)),
        "host_pid": bool(pod_spec.get("hostPID", False)),
        "host_ipc": bool(pod_spec.get("hostIPC", False)),
        "active_deadline_seconds": spec.get("activeDeadlineSeconds"),
        "ttl_seconds_after_finished": spec.get("ttlSecondsAfterFinished"),
    }


def _persistent_mount_recovery_job_contract(job: Mapping[str, Any]) -> dict[str, Any]:
    """Bind a recovery Job to its attempt, original copy, and retained failed Job."""

    annotations = _mapping(_mapping(job.get("metadata")).get("annotations"))
    return {
        "job": _persistent_mount_copy_job_contract(job),
        "recovery_attempt_token": str(
            annotations.get(_CXCLI_JOB_OPERATION_ANNOTATION) or ""
        ).strip(),
        "copy_operation_token": str(
            annotations.get(_PERSISTENT_MOUNT_COPY_TOKEN_ANNOTATION) or ""
        ).strip(),
        "recovery_of_job_uid": str(
            annotations.get(_PERSISTENT_MOUNT_RECOVERY_OF_UID_ANNOTATION) or ""
        ).strip(),
        "failed_mount_path": str(
            annotations.get(_PERSISTENT_MOUNT_RECOVERY_MOUNT_ANNOTATION) or ""
        ).strip(),
    }


def _persistent_mount_copy_job_contract(job: Mapping[str, Any]) -> dict[str, Any]:
    spec = _mapping(job.get("spec"))
    managed_by = str(spec.get("managedBy") or "").strip()
    if managed_by in {"", "kubernetes.io/job-controller"}:
        managed_by = "kubernetes.io/job-controller"
    return {
        "job": _passive_populate_job_contract(job),
        "pod_replacement_policy": str(spec.get("podReplacementPolicy") or "").strip(),
        "parallelism": _non_negative_int(spec.get("parallelism"), fallback=1),
        "completions": _non_negative_int(spec.get("completions"), fallback=1),
        "suspend": _bool_value(spec.get("suspend"), fallback=False),
        "managed_by": managed_by,
        "manual_selector": _bool_value(spec.get("manualSelector"), fallback=False),
        "completion_mode": str(spec.get("completionMode") or "NonIndexed").strip(),
        "pod_failure_policy": to_plain_data(_mapping(spec.get("podFailurePolicy"))),
        "success_policy": to_plain_data(_mapping(spec.get("successPolicy"))),
        "backoff_limit_per_index": spec.get("backoffLimitPerIndex"),
        "max_failed_indexes": spec.get("maxFailedIndexes"),
    }


def _persistent_mount_checkpoint_job_contract(
    job: Mapping[str, Any],
    *,
    copy_schema_version: int,
) -> dict[str, Any]:
    if copy_schema_version >= _PERSISTENT_MOUNT_COPY_SCHEMA_VERSION:
        return _persistent_mount_copy_job_contract(job)
    return _passive_populate_job_contract(job)


def _passive_populate_job_failed(job: Mapping[str, Any]) -> bool:
    status = _mapping(job.get("status"))
    return _positive_int(status.get("failed"), fallback=0) > 0 or any(
        str(item.get("type") or "").strip() == "Failed"
        and str(item.get("status") or "").strip() == "True"
        for item in _sequence_of_mappings(status.get("conditions"))
    )


def _passive_populate_job_complete(job: Mapping[str, Any]) -> bool:
    status = _mapping(job.get("status"))
    return _positive_int(status.get("succeeded"), fallback=0) > 0 or any(
        str(item.get("type") or "").strip() == "Complete"
        and str(item.get("status") or "").strip() == "True"
        for item in _sequence_of_mappings(status.get("conditions"))
    )


def _bind_passive_populate_pvc_uid(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    state: dict[str, Any],
    pvc: str,
    allow_initial_binding: bool,
) -> str:
    """Bind or revalidate the immutable PVC identity used by a populate Job."""

    try:
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                "persistentvolumeclaim",
                pvc,
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise SoperatorMigrationPhasePending(
            "Timed out while verifying the passive-slot PVC immutable identity; no "
            "populate Job or slot switch was attempted."
        ) from exc
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "Could not verify the passive-slot PVC immutable identity; no populate Job "
            f"or slot switch was attempted: {_command_detail(result)}"
        )
    try:
        live_pvc = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "The passive-slot PVC lookup returned invalid JSON; no populate Job or "
            "slot switch was attempted."
        ) from exc
    metadata = _mapping(live_pvc.get("metadata")) if isinstance(live_pvc, Mapping) else {}
    live_name = str(metadata.get("name") or "").strip()
    live_uid = str(metadata.get("uid") or "").strip()
    if live_name != pvc or not live_uid:
        raise SoperatorMigrationPhasePending(
            "The passive-slot PVC lookup did not return the requested name and immutable "
            "UID; no populate Job or slot switch was attempted."
        )
    checkpointed_pvc = str(state.get("pvc") or "").strip()
    checkpointed_uid = str(state.get("pvc_uid") or "").strip()
    if checkpointed_pvc and checkpointed_pvc != pvc:
        raise SoperatorMigrationPhasePending(
            "The passive-slot populate checkpoint is bound to a different PVC name; no "
            "populate Job or slot switch was attempted."
        )
    if checkpointed_uid:
        if checkpointed_uid != live_uid:
            raise SoperatorMigrationPhasePending(
                "The passive-slot PVC UID no longer matches the checkpointed immutable "
                "identity; refusing to populate a same-name replacement."
            )
    elif not allow_initial_binding:
        raise SoperatorMigrationPhasePending(
            "The passive-slot populate checkpoint lacks its immutable PVC UID; no "
            "completed Job was reused and no slot switch was attempted."
        )
    else:
        state["pvc_uid"] = live_uid
    return live_uid


def _bind_passive_populate_job_checkpoint(
    *,
    existing: Mapping[str, Any],
    manifest: dict[str, Any],
    slot: str,
    pvc: str,
    image: str,
) -> dict[str, Any]:
    operation_token = str(existing.get("operation_token") or "").strip() or uuid4().hex[:12]
    metadata = manifest.setdefault("metadata", {})
    if not isinstance(metadata, dict):
        raise RuntimeError("Passive-slot populate Job metadata must be a mapping.")
    base_name = str(metadata.get("name") or "").strip()
    suffix = f"-{operation_token}"
    metadata["name"] = f"{base_name[: 63 - len(suffix)].rstrip('-')}{suffix}"
    annotations = metadata.setdefault("annotations", {})
    if not isinstance(annotations, dict):
        raise RuntimeError("Passive-slot populate Job annotations must be a mapping.")
    annotations[_PASSIVE_POPULATE_OPERATION_ANNOTATION] = operation_token
    job_name = str(_mapping(manifest.get("metadata")).get("name") or "").strip()
    proposed = {
        "name": job_name,
        "slot": slot,
        "pvc": pvc,
        "image": image,
        "operation_token": operation_token,
        "contract": _passive_populate_job_contract(manifest),
    }
    if not existing:
        return proposed
    for key in ("name", "slot", "pvc", "image", "operation_token", "contract"):
        if to_plain_data(existing.get(key)) != to_plain_data(proposed[key]):
            raise SoperatorMigrationPhasePending(
                "Passive-slot populate Job contract drifted from the checkpointed name, "
                "slot, PVC, image, scheduling, or pod-security binding. Refusing to "
                "overwrite the accepted Job contract."
            )
    return {**dict(existing), **proposed}


def _ensure_passive_populate_job(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    manifest: Mapping[str, Any],
    expected_uid: str = "",
    expected_pvc_uid: str = "",
    state: dict[str, Any] | None = None,
    checkpoint_writer: Callable[[], None] | None = None,
) -> str:
    expected = _passive_populate_job_contract(manifest)
    job_name = str(expected.get("name") or "").strip()
    if not job_name:
        raise RuntimeError("Passive-slot populate Job manifest has no name.")
    claim_name = str(expected.get("claim_name") or "").strip()
    if not claim_name or not expected_pvc_uid:
        raise SoperatorMigrationPhasePending(
            "Passive-slot population requires a checkpointed PVC name and immutable UID."
        )
    _bind_passive_populate_pvc_uid(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state={"pvc": claim_name, "pvc_uid": expected_pvc_uid},
        pvc=claim_name,
        allow_initial_binding=False,
    )
    get_args = [
        "kubectl",
        "--context",
        kube_context,
        "-n",
        namespace,
        "get",
        f"job/{job_name}",
        "-o",
        "json",
        "--request-timeout=20s",
    ]
    try:
        result = command_runner(get_args, timeout_seconds=60, check=False)
    except subprocess.TimeoutExpired as exc:
        raise SoperatorMigrationPhasePending(
            "Timed out while reconciling the checkpointed passive-slot populate Job; "
            "the Job was not deleted or reapplied."
        ) from exc
    live_job: Mapping[str, Any] = {}
    if result.returncode != 0:
        if not _command_not_found(result):
            raise SoperatorMigrationPhasePending(
                "Could not reconcile the checkpointed passive-slot populate Job; the Job "
                f"was not deleted or reapplied: {_command_detail(result)}"
            )
    else:
        try:
            payload = json.loads(result.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise SoperatorMigrationPhasePending(
                "Passive-slot populate Job lookup returned invalid JSON; the Job was not "
                "deleted or reapplied."
            ) from exc
        if not isinstance(payload, Mapping):
            raise SoperatorMigrationPhasePending(
                "Passive-slot populate Job lookup returned an invalid payload; the Job was "
                "not deleted or reapplied."
            )
        live_job = payload
    if _mapping(live_job.get("metadata")):
        live_uid = str(_mapping(live_job.get("metadata")).get("uid") or "").strip()
        if not live_uid or (expected_uid and live_uid != expected_uid):
            raise SoperatorMigrationPhasePending(
                "Live passive-slot populate Job UID no longer matches the checkpointed "
                "immutable Job identity. Refusing to delete or reuse it."
            )
        actual = _passive_populate_job_contract(live_job)
        if actual != expected:
            raise SoperatorMigrationPhasePending(
                "Live passive-slot populate Job no longer matches the checkpointed exact "
                "slot, PVC, image, scheduling, and pod-security contract. Refusing to "
                "delete or reuse it."
            )
        if not _passive_populate_job_failed(live_job):
            if state is not None:
                state["uid"] = live_uid
                if checkpoint_writer is not None:
                    checkpoint_writer()
            return "reused"
        raise SoperatorMigrationPhasePending(
            "The UID-bound passive-slot populate Job failed. Its target slot may be "
            "partial, so cxcli will not delete or replace it automatically; reconcile "
            "the target slot and checkpoint before retrying."
        )
    else:
        action = "created"
    _kubectl_apply_objects(
        command_runner=command_runner,
        kube_context=kube_context,
        objects=(manifest,),
        timeout_seconds=300,
    )
    created_exists, created_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        resource=f"job/{job_name}",
        namespace=namespace,
    )
    created_uid = str(_mapping(created_job.get("metadata")).get("uid") or "").strip()
    if (
        not created_exists
        or not created_uid
        or (expected_uid and created_uid != expected_uid)
        or _passive_populate_job_contract(created_job) != expected
    ):
        raise SoperatorMigrationPhasePending(
            "The applied passive-slot populate Job could not be bound to its exact "
            "checkpointed contract and immutable UID; no slot switch was attempted."
        )
    if _passive_populate_job_failed(created_job):
        raise SoperatorMigrationPhasePending(
            "The newly applied passive-slot populate Job failed. Its target slot may be "
            "partial, so cxcli will not replace it automatically."
        )
    if state is not None:
        state["uid"] = created_uid
        if checkpoint_writer is not None:
            checkpoint_writer()
    return action


def _validate_completed_passive_populate_job_checkpoint(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    existing: Mapping[str, Any],
    manifest: Mapping[str, Any],
    slot: str,
    pvc: str,
    image: str,
    completed_at: Any,
    target_ref: str,
    expected_pvc_uid: str,
) -> PopulateJailSnapshot:
    """Read-only validation for a completed, UID-bound passive populate Job."""

    if not str(completed_at or "").strip():
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade switch recovery lacks the checkpointed passive populate Job "
            "completion timestamp."
        )
    if not existing:
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade switch recovery lacks the checkpointed passive populate Job contract."
        )
    checkpointed_pvc_uid = str(existing.get("pvc_uid") or "").strip()
    if not expected_pvc_uid or checkpointed_pvc_uid != expected_pvc_uid:
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade switch recovery lacks a consistent checkpointed passive PVC UID."
        )
    _bind_passive_populate_pvc_uid(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        state=dict(existing),
        pvc=pvc,
        allow_initial_binding=False,
    )
    bound_manifest = copy.deepcopy(dict(manifest))
    bound = _bind_passive_populate_job_checkpoint(
        existing=existing,
        manifest=bound_manifest,
        slot=slot,
        pvc=pvc,
        image=image,
    )
    job_name = str(bound.get("name") or "").strip()
    expected_uid = str(bound.get("uid") or "").strip()
    if not job_name or not expected_uid:
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade switch recovery requires the completed passive populate Job "
            "name and immutable UID."
        )
    try:
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                f"job/{job_name}",
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise SoperatorMigrationPhasePending(
            "Timed out while validating the completed passive populate Job; no desired "
            "state or live resource was changed."
        ) from exc
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "The UID-bound completed passive populate Job is unavailable; no desired "
            "state or live resource was changed."
        )
    try:
        live_job = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise SoperatorMigrationPhasePending(
            "The completed passive populate Job lookup returned invalid JSON; no desired "
            "state or live resource was changed."
        ) from exc
    if not isinstance(live_job, Mapping) or not _mapping(live_job.get("metadata")):
        raise SoperatorMigrationPhasePending(
            "The completed passive populate Job lookup returned an invalid payload; no "
            "desired state or live resource was changed."
        )
    live_uid = str(_mapping(live_job.get("metadata")).get("uid") or "").strip()
    if live_uid != expected_uid:
        raise SoperatorMigrationPhasePending(
            "The live passive populate Job UID no longer matches the checkpointed "
            "immutable identity; no desired state or live resource was changed."
        )
    if _passive_populate_job_contract(live_job) != _passive_populate_job_contract(bound_manifest):
        raise SoperatorMigrationPhasePending(
            "The live completed passive populate Job no longer matches its checkpointed "
            "exact contract; no desired state or live resource was changed."
        )
    if _passive_populate_job_failed(live_job) or not _passive_populate_job_complete(live_job):
        raise SoperatorMigrationPhasePending(
            "The checkpointed passive populate Job is not currently proven complete; no "
            "desired state or live resource was changed."
        )
    return PopulateJailSnapshot(
        slurmcluster_name=target_ref,
        image=image,
        job_name=job_name,
        job_uid=expected_uid,
        job_complete=True,
        job_image=image,
        status="collected",
        detail="validated completed passive-slot Job from immutable checkpoint",
    )


def _execute_populate_jail_refresh_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi | None = None,
    command_runner: SoperatorMigrationCommandRunner,
    accounting_handoff_artifact_dir: Path | None = None,
    populate_jail_refresh: str,
    job_policy: str,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    login_session_policy: str = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
    login_session_drain_timeout_seconds: int = 0,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None = None,
    interactive_prompt_pause: Callable[[], Any] | None = None,
    allow_resolved_interactive_job_policy: bool = False,
    slurm_scheduling_pause: bool = True,
    checkpoint_writer: Callable[[], None] | None = None,
    jail_sfs_resize_handler: JailSfsResizeHandler | None = None,
    mutation_guard: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, POPULATE_JAIL_REFRESH_PHASE_ID)
    execution = phase.setdefault("execution", {})
    if not isinstance(execution, dict):
        raise RuntimeError("Jail Upgrade execution checkpoint must be a mapping.")
    resumed_at = _utc_now()
    execution.setdefault("started_at", resumed_at)
    execution["last_resumed_at"] = resumed_at
    execution["status"] = "running"
    if checkpoint_writer is not None:
        checkpoint_writer()
    rolling_phase = _phase_state(checkpoint, "rolling-compute-migration")
    gpu_post_population_runner_lock = _mapping(
        _mapping(checkpoint.get("controller_bridge")).get("target_image_lock")
    )

    def _ensure_ownership_handoff(values: Mapping[str, Any]) -> tuple[bool, list[str]]:
        if nebius_api is None or accounting_handoff_artifact_dir is None:
            return False, []
        return _ensure_in_place_jail_ownership_handoff(
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            live_snapshot=live_snapshot,
            target_ref=target_ref,
            kube_context=kube_context,
            values=values,
            nebius_api=nebius_api,
            command_runner=command_runner,
            accounting_handoff_artifact_dir=accounting_handoff_artifact_dir,
            job_policy=job_policy,
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            job_wait_timeout_seconds=job_wait_timeout_seconds,
            job_refresh_interval_seconds=job_refresh_interval_seconds,
            login_session_policy=login_session_policy,
            login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
            slurm_decision_recorder=slurm_decision_recorder,
            interactive_prompt_pause=interactive_prompt_pause,
            allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
            slurm_scheduling_pause=slurm_scheduling_pause,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )

    def _protected_login_pod_uids() -> tuple[str, ...]:
        hold = _mapping(checkpoint.get("active_login_session_hold"))
        if str(hold.get("status") or "").strip() != "verified":
            return ()
        return tuple(
            sorted(
                str(item.get("uid") or "").strip()
                for item in _sequence_of_mappings(hold.get("pods"))
                if str(item.get("uid") or "").strip()
            )
        )

    def _login_ready_after_switch() -> dict[str, Any]:
        release_gate = _mapping(phase.get("login_hold_release_before_full_rollout"))
        peer = _mapping(release_gate.get("target_slot_peer"))
        if release_gate.get("status") == "protected-session-deferred":
            peer_uids = tuple(_string_sequence(peer.get("pod_uids")))
            if peer.get("status") != "verified" or not peer_uids:
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade protected-session deferral lacks its exact target-slot peer."
                )
            return {
                "status": "target-slot-peer-ready-protected-sessions-deferred",
                "ready_endpoints": len(peer_uids),
                "pod_uids": list(peer_uids),
            }
        return wait_for_login_statefulset_rollout_with_ready_endpoint_guard(
            command_runner,
            namespace=_SOPERATOR_NAMESPACE,
            target_ref=target_ref,
            kube_context=kube_context,
        )

    def _shrink_session_free_login_holds_before_ownership() -> list[str]:
        gate = phase.setdefault("login_hold_release_before_full_rollout", {})
        if not isinstance(gate, dict):
            raise RuntimeError("login_hold_release_before_full_rollout must be a mapping.")
        lines = _ensure_active_login_session_hold(
            checkpoint=checkpoint,
            gate=gate,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            pod_names=_login_pod_names(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
            ),
            release_if_drained=False,
            checkpoint_writer=checkpoint_writer,
        )
        return list(lines or [])

    def _require_live_rolling_sconfig_fence(*, boundary: str) -> None:
        if not _legacy_rootfs_target_compatibility_is_active(rolling_phase):
            return
        try:
            _stage_legacy_rootfs_target_slurm_config_compatibility(
                phase=rolling_phase,
                handoff=_immutable_child_handoff_state(rolling_phase),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        except SoperatorMigrationPhasePending as exc:
            raise SoperatorMigrationPhasePending(
                f"Jail Upgrade {boundary} is blocked because the canonical rolling SConfig "
                f"fence no longer verifies: {exc}"
            ) from exc

    before = inspect_populate_jail(
        command_runner,
        namespace=_SOPERATOR_NAMESPACE,
        target_ref=target_ref,
        kube_context=kube_context,
    )
    campaign_target_image = _active_campaign_jail_rootfs_target_image(
        payload=payload,
        target_ref=target_ref,
    )
    after_chart = PopulateJailSnapshot(
        slurmcluster_name=before.slurmcluster_name or target_ref,
        image=campaign_target_image,
        status="planned",
        detail="immutable active campaign Jail rootfs target",
    )
    plan = plan_populate_jail_refresh(
        mode=populate_jail_refresh,
        chart_changed=True,
        before=before,
        after_chart=after_chart,
        namespace=_SOPERATOR_NAMESPACE,
    )
    phase["plan"] = plan.as_payload()
    if checkpoint_writer is not None:
        checkpoint_writer()
    if not plan.required:
        bridge_status = str(
            _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge")).get("status") or ""
        ).strip()
        release_status = str(
            _mapping(
                _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge")).get(
                    "target_writer_release"
                )
            ).get("status")
            or ""
        ).strip()
        if bridge_status in {"target-compatibility-active", "released"} or release_status in {
            "intent",
            "applied",
        }:
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade planner returned no-op while the canonical rolling SConfig "
                "writer remains fenced or its slot release is incomplete; resume the "
                "checkpointed Jail switch/release before completing this phase."
            )
        result = skipped_populate_jail_refresh_result(plan)
        phase["result"] = result.as_payload()
        phase["completed_at"] = _utc_now()
        execution["status"] = "completed"
        execution["completed_at"] = phase["completed_at"]
        if checkpoint_writer is not None:
            checkpoint_writer()
        return False, [f"Jail Upgrade skipped: {result.reason}."]
    if plan.mode == "manual":
        result = manual_populate_jail_refresh_result(plan)
        phase["result"] = result.as_payload()
        phase["pending_reason"] = result.detail
        execution["status"] = "pending-manual-action"
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(result.detail)

    source_slurmcluster = _source_slurmcluster_resource(source_report, target_ref=target_ref)
    source_declares_controller = "controller" in _mapping(
        _mapping(source_slurmcluster.get("spec")).get("slurmNodes")
    )
    migration_mode = ""
    if source_declares_controller:
        migration_mode = str(
            _compute_migration_contract(payload, target_ref).get("mode", "") or ""
        ).strip()
        controller_bridge = checkpoint.get("controller_bridge")
        if not isinstance(controller_bridge, Mapping):
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade controller continuity preflight requires the v6 "
                "controller bridge journal."
            )
        try:
            validate_bridge_journal(controller_bridge)
            bridge_stage = BridgeStage(str(controller_bridge.get("stage", "") or ""))
        except (TypeError, ValueError) as exc:
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade controller continuity preflight found an invalid v6 "
                f"controller bridge journal: {exc}"
            ) from exc
        if migration_mode == COMPUTE_MIGRATION_MODE_IN_PLACE:
            if bridge_stage not in {
                BridgeStage.SOURCE_HA_ACTIVE,
                BridgeStage.TARGET_HA_ACTIVE,
            }:
                raise SoperatorMigrationPhasePending(
                    "In-place Jail slot-B preparation requires the temporary controller "
                    "bridge to own Slurm authority before any compute group is updated; "
                    f"current stage={bridge_stage.value}."
                )
        else:
            identity_transition = soperator_migration_slurmcluster_identity_transition(checkpoint)
            rolling_handoff = _mapping(rolling_phase.get("slurmcluster_handoff_binding"))
            controller_owner_binding = _mapping(identity_transition.get("target")) or _mapping(
                rolling_handoff.get("target")
            )
            if (
                str(controller_owner_binding.get("namespace") or "").strip() != _SOPERATOR_NAMESPACE
                or str(controller_owner_binding.get("name") or "").strip() != target_ref
                or not str(controller_owner_binding.get("uid") or "").strip()
            ):
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade controller continuity preflight lacks the exact completed "
                    "target SlurmCluster owner binding."
                )
            if bridge_stage not in {
                BridgeStage.HANDOFF_VALIDATED,
                BridgeStage.PARTITIONS_RESTORED,
                BridgeStage.CLEANED,
            }:
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade requires the supported target singleton handoff to be "
                    "validated before passive rootfs population; "
                    f"current controller bridge stage={bridge_stage.value}."
                )
            _prove_controller_bridge_cleanup_target_singleton(
                journal=controller_bridge,
                command_runner=command_runner,
                kube_context=kube_context,
                require_cluster_wide_census=not _controller_bridge_kubernetes_cleanup_complete(
                    _mapping(controller_bridge.get("cleanup"))
                ),
            )

    topology_lines = _ensure_worker_nodeset_topology_checkpoint(
        checkpoint=checkpoint,
        source_report=source_report,
        kube_context=kube_context,
        command_runner=command_runner,
        nodeset_names=_target_worker_nodeset_names(_target_soperator_values(payload, target_ref)),
    )
    if topology_lines and checkpoint_writer is not None:
        checkpoint_writer()
    values = _patch_target_values_for_compute(
        checkpoint=checkpoint,
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    values = _restore_checkpointed_pre_switch_rootfs_values(values, phase=phase)
    persistent_mount_checks = _persistent_mount_overwrite_checks(
        checkpoint=checkpoint,
        values=values,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    phase["persistent_jail_mounts"] = {
        "checks": list(persistent_mount_checks),
        "status": "failed" if _fast_verification_failed(persistent_mount_checks) else "verified",
    }
    if _fast_verification_failed(persistent_mount_checks):
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "jail rootfs refresh is blocked until persistent jail mounts are verified. "
            "Review the populate-jail-refresh.persistent_jail_mounts checks in the checkpoint."
        )
    slots = active_passive_jail_rootfs_slots(values)
    job_scheduling = active_passive_populate_jail_job_scheduling(
        values,
    )
    phase["rootfs_strategy"] = "activePassive"
    current_rootfs_slots = slots.as_payload()
    checkpointed_rootfs_slots = dict(_mapping(phase.get("rootfs_slots")))
    if checkpointed_rootfs_slots:
        slot_binding_keys = (
            "active_slot",
            "passive_slot",
            "active_volume_source",
            "passive_volume_source",
            "active_pvc",
            "passive_pvc",
        )
        accepted_slot_binding = {
            key: str(checkpointed_rootfs_slots.get(key) or "").strip() for key in slot_binding_keys
        }
        current_slot_binding = {
            key: str(current_rootfs_slots.get(key) or "").strip() for key in slot_binding_keys
        }
        if not all(accepted_slot_binding.values()) or current_slot_binding != accepted_slot_binding:
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade retry found PVC or volume-source drift inside the "
                "checkpointed active/passive rootfs slot binding. No capacity resize, "
                "populate Job, or slot switch was attempted."
            )
    else:
        phase["rootfs_slots"] = copy.deepcopy(current_rootfs_slots)
        if checkpoint_writer is not None:
            checkpoint_writer()
    legacy_active_rootfs = jail_rootfs_uses_legacy_active_source(values)
    legacy_migration_entries = _legacy_persistent_mount_migration_entries(values)
    legacy_in_place_entries = _legacy_persistent_mount_in_place_entries(values)
    legacy_active_rootfs = bool(legacy_active_rootfs or legacy_migration_entries)
    phase["legacy_active_rootfs"] = legacy_active_rootfs
    open_metrics_handoff = (
        _bind_jail_slurm_open_metrics_handoff(
            phase=phase,
            values=values,
            rolling_phase=rolling_phase,
        )
        if legacy_active_rootfs or isinstance(phase.get("slurm_open_metrics_handoff"), Mapping)
        else None
    )
    if open_metrics_handoff is not None and checkpoint_writer is not None:
        checkpoint_writer()
    legacy_jail_pvc = (
        _source_jail_pvc_name(
            source_report,
            target_ref=target_ref,
            values=values,
        )
        if legacy_active_rootfs
        else ""
    )
    if legacy_active_rootfs and not legacy_jail_pvc:
        raise SoperatorMigrationPhasePending(
            "first-adoption Jail Upgrade could not resolve the discovered legacy jail PVC. "
            "Rerun external discovery/onboarding before resuming."
        )
    if legacy_jail_pvc:
        phase["legacy_jail_pvc"] = legacy_jail_pvc
    if legacy_active_rootfs and legacy_jail_pvc:
        expected_jail_pvc_uid = _source_jail_pvc_uid(
            source_report,
            pvc_name=legacy_jail_pvc,
        )
        if not expected_jail_pvc_uid:
            raise SoperatorMigrationPhasePending(
                "first-adoption Jail Upgrade requires the immutable source jail PVC UID "
                "from accepted discovery or the verified pre-mutation backup."
            )
        live_pvc_exists, live_pvc = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"pvc/{legacy_jail_pvc}",
            namespace=_SOPERATOR_NAMESPACE,
        )
        live_jail_pvc_uid = str(_mapping(live_pvc.get("metadata")).get("uid") or "").strip()
        if not live_pvc_exists or live_jail_pvc_uid != expected_jail_pvc_uid:
            raise SoperatorMigrationPhasePending(
                "the live legacy jail PVC identity no longer matches the immutable "
                "accepted source binding. Refusing source probe or copy from a missing "
                "or replaced PVC."
            )
        phase["legacy_jail_pvc_uid"] = expected_jail_pvc_uid
        jail_rootfs_values = values.setdefault("jailRootfs", {})
        if not isinstance(jail_rootfs_values, dict):
            raise SoperatorMigrationPhasePending(
                "first-adoption Jail Upgrade requires jailRootfs values to be a mapping."
            )
        adoption_values = jail_rootfs_values.setdefault("adoption", {})
        if not isinstance(adoption_values, dict):
            raise SoperatorMigrationPhasePending(
                "first-adoption Jail Upgrade requires jailRootfs.adoption to be a mapping."
            )
        adoption_values["legacyPvcName"] = legacy_jail_pvc
    target_version = str(_mapping(source_report.get("report")).get("target_version", "") or "")
    populate_image = plan.after_chart.image
    if not populate_image:
        raise SoperatorMigrationPhasePending(
            "Could not resolve the active campaign target populate-jail image for "
            "passive-slot rootfs population."
        )

    def _restore_external_stale_persistent_copy_writers(
        *,
        writer_state: dict[str, Any],
    ) -> tuple[list[str], list[str]]:
        cleanup_errors: list[str] = []
        cleanup_lines: list[str] = []
        cleanup_state = phase.setdefault("stale_persistent_copy_cleanup", {})
        if not isinstance(cleanup_state, dict):
            raise RuntimeError(
                "populate-jail-refresh.stale_persistent_copy_cleanup must be a mapping."
            )
        try:
            _preflight_persistent_migration_writer_restore_identity(
                command_runner=command_runner,
                kube_context=kube_context,
                state=writer_state,
            )
        except SoperatorMigrationPhasePending as exc:
            cleanup_errors.append(f"persistent writer restore preflight failed: {exc}")
            cleanup_state.update(
                {
                    "status": "pending",
                    "checked_at": _utc_now(),
                    "identity_drift": [
                        {
                            "kind": "slurmcluster-maintenance",
                            "reason": str(exc),
                        }
                    ],
                    "errors": list(cleanup_errors),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return cleanup_errors, cleanup_lines
        binding_drift = _persistent_migration_writer_hold_drift(
            command_runner=command_runner,
            kube_context=kube_context,
            state=writer_state,
        )
        identity_drift = [
            item
            for item in binding_drift
            if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
            and str(item.get("reason") or "").strip()
            in {
                "resource identity missing",
                "checkpointed writer resource is missing",
                "checkpointed writer SlurmCluster UID changed",
            }
        ]
        if identity_drift:
            cleanup_errors.append(
                "persistent writer restore failed: immutable target SlurmCluster "
                "identity no longer matches the checkpoint"
            )
            cleanup_state.update(
                {
                    "status": "pending",
                    "checked_at": _utc_now(),
                    "identity_drift": [dict(item) for item in identity_drift],
                    "errors": list(cleanup_errors),
                }
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            return cleanup_errors, cleanup_lines
        original_maintenance = _persistent_migration_original_maintenance(writer_state)
        desired_values = (
            populate_jail_refresh_values(values)
            if str(phase.get("passive_slot_refresh_values_applied_at") or "").strip()
            else copy.deepcopy(values)
        )
        desired_slots = active_passive_jail_rootfs_slots(desired_values).as_payload()
        desired_values["maintenance"] = original_maintenance
        if active_passive_jail_rootfs_slots(desired_values).as_payload() != desired_slots:
            raise RuntimeError(
                "stale persistent-copy cleanup changed the active/passive jail rootfs slot binding"
            )
        cleanup_state.update(
            {
                "status": "restoring-desired-maintenance",
                "checked_at": _utc_now(),
                "desired_state": {
                    "status": "pending",
                    "maintenance": original_maintenance,
                    "rootfs_slots": desired_slots,
                },
            }
        )
        cleanup_state.pop("errors", None)
        if checkpoint_writer is not None:
            checkpoint_writer()
        try:
            _require_live_rolling_sconfig_fence(boundary="persistent desired-state Helm restore")
            cleanup_lines.extend(
                _helm_upgrade_target_soperator_with_jail_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    values=desired_values,
                    expected_version=target_version,
                    boundary="stale-persistent-copy-cleanup",
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    wait=False,
                    writer_hold_state=writer_state,
                    allow_writer_hold_drift=True,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            cleanup_state["desired_state"] = {
                "status": "restored",
                "maintenance": original_maintenance,
                "rootfs_slots": desired_slots,
                "verified_at": _utc_now(),
            }
            cleanup_lines.append(
                "Restored target Helm desired maintenance while preserving the current "
                "active/passive jail rootfs slot."
            )
        except Exception as exc:
            cleanup_errors.append(f"persistent desired-state writer restore failed: {exc}")
            cleanup_state["desired_state"] = {
                "status": "pending",
                "maintenance": original_maintenance,
                "rootfs_slots": desired_slots,
                "error": str(exc),
            }
        if not cleanup_errors and writer_state.get("status") in {"holding", "held", "restored"}:
            try:
                cleanup_lines.extend(
                    _restore_persistent_migration_writers(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        state=writer_state,
                    )
                )
                phase["persistent_migration_writer_hold"] = dict(writer_state)
                _wait_for_target_slurmcluster_available(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    timeout_seconds=900,
                )
                _wait_for_target_worker_nodesets_ready(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    values=desired_values,
                    timeout_seconds=1800,
                )
                wait_for_login_statefulset_rollout_with_ready_endpoint_guard(
                    command_runner,
                    namespace=_SOPERATOR_NAMESPACE,
                    target_ref=target_ref,
                    kube_context=kube_context,
                )
                consumer_checks = _verify_target_rootfs_handoff_consumers(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    values=desired_values,
                )
                cleanup_state["consumer_checks"] = consumer_checks
                if any(check.get("status") != "verified" for check in consumer_checks):
                    raise SoperatorMigrationPhasePending(
                        _rootfs_handoff_pending_reason(consumer_checks)
                    )
                cleanup_state["readiness_verified_at"] = _utc_now()
            except Exception as exc:
                cleanup_errors.append(f"persistent writer restore failed: {exc}")
        elif not cleanup_errors:
            cleanup_errors.append(
                "persistent writer restore failed: checkpointed writer hold state is not restorable"
            )
        cleanup_state.update(
            {
                "status": "pending" if cleanup_errors else "restored",
                "checked_at": _utc_now(),
                **({"errors": cleanup_errors} if cleanup_errors else {}),
            }
        )
        if not cleanup_errors:
            cleanup_state.pop("errors", None)
        if checkpoint_writer is not None:
            checkpoint_writer()
        return cleanup_errors, cleanup_lines

    def _raise_after_external_stale_copy_cleanup(*, writer_state: dict[str, Any]) -> None:
        cleanup_errors, _cleanup_lines = _restore_external_stale_persistent_copy_writers(
            writer_state=writer_state
        )
        stale_pause_records = _rolling_compute_checkpoint_pause_records(phase)
        if cleanup_errors:
            phase["slurm_resume_after_failure"] = {
                "status": "pending",
                "reason": (
                    "steady-state writer cleanup must complete while the upgrade-owned "
                    "partition pause remains in force"
                ),
                "partitions": [record.as_payload() for record in stale_pause_records],
            }
        elif not stale_pause_records:
            phase["slurm_resume_after_failure"] = {
                "status": "not-required",
                "partitions": [],
                "reason": "no checkpoint-owned Slurm partition pause exists",
            }
        else:
            phase["slurm_resume_after_failure"] = {
                "status": "deferred",
                "partitions": [record.as_payload() for record in stale_pause_records],
                "reason": (
                    "the upgrade-owned partition pause is released only after final "
                    "singleton health, action-journal drain, login handoff, and bridge cleanup"
                ),
            }
        cleanup_state = phase.setdefault("stale_persistent_copy_cleanup", {})
        if not isinstance(cleanup_state, dict):
            raise RuntimeError(
                "populate-jail-refresh.stale_persistent_copy_cleanup must be a mapping."
            )
        cleanup_state.update(
            {
                "status": "pending" if cleanup_errors else "restored",
                "checked_at": _utc_now(),
                **({"errors": cleanup_errors} if cleanup_errors else {}),
            }
        )
        if cleanup_errors:
            phase["refresh_failure_cleanup_errors"] = cleanup_errors
        else:
            cleanup_state.pop("errors", None)
            phase.pop("refresh_failure_cleanup_errors", None)
        if checkpoint_writer is not None:
            checkpoint_writer()
        if cleanup_errors:
            raise SoperatorMigrationPhasePending(
                "persistent mount migration copy is stale after writer-hold drift, and "
                "steady-state writer/Slurm cleanup remains pending: "
                + "; ".join(cleanup_errors)
                + ". Rerun the same command to retry cleanup before manual reconciliation."
            )
        raise SoperatorMigrationPhasePending(
            "persistent mount migration copy may be stale after checkpointed writer-hold "
            "drift. The upgrade restored steady-state writers but retained the Slurm "
            "partition pause and will not reuse or overwrite the shared copy automatically. "
            "Reconcile the "
            "legacy source, shared target, completion markers, and checkpoint under an "
            "approved maintenance window before rerunning."
        )

    switch_checkpointed = bool(
        str(phase.get("consumer_switch_applied_at") or "").strip()
        or str(phase.get("active_slot") or "").strip() == slots.passive_slot
        or _mapping(phase.get("rootfs_handoff_verification"))
    )
    switch_crash_window_possible = bool(
        switch_checkpointed
        or str(phase.get("job_completed_at") or "").strip()
        or _mapping(phase.get("post_jail_slurm_smoke"))
    )
    external_switch_recovery_snapshot: PopulateJailSnapshot | None = None
    external_switch_recovery_manifest: dict[str, Any] | None = None
    live_switch_corroborated = False
    live_pre_switch = False
    external_resume_consumers_uncertain = False
    resume_hold_lines: list[str] = []

    def _backfill_passive_populate_monitor() -> None:
        if _mapping(phase.get("passive_slot_populate_monitor")):
            return
        passive_job = _mapping(phase.get("passive_slot_populate_job"))
        phase["passive_slot_populate_monitor"] = inspect_active_passive_populate_jail_progress(
            command_runner,
            namespace=_SOPERATOR_NAMESPACE,
            job_name=str(passive_job.get("name") or ""),
            expected_job_uid=str(passive_job.get("uid") or ""),
            expected_image=str(passive_job.get("image") or populate_image),
            kube_context=kube_context,
        ).as_payload()
        if checkpoint_writer is not None:
            checkpoint_writer()

    if switch_crash_window_possible:
        resume_hold_lines = _recover_preparing_active_login_session_hold(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            checkpoint_writer=checkpoint_writer,
            mutation_guard=mutation_guard,
        )
        resume_hold_lines.extend(
            _reconcile_released_login_pods_in_immutable_handoff(
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        switched_values = switch_active_passive_jail_rootfs_values(values)
        handoff_consumer_snapshot = _target_rootfs_handoff_consumer_snapshot(
            command_runner=command_runner,
            kube_context=kube_context,
            values=switched_values,
        )
        switched_checks = _verify_target_rootfs_handoff_consumers(
            command_runner=command_runner,
            kube_context=kube_context,
            values=switched_values,
            resource_snapshot=handoff_consumer_snapshot,
        )
        pre_switch_values = copy.deepcopy(values)
        if legacy_active_rootfs:
            pre_switch_rootfs = pre_switch_values.setdefault("jailRootfs", {})
            if not isinstance(pre_switch_rootfs, dict):
                pre_switch_rootfs = {}
                pre_switch_values["jailRootfs"] = pre_switch_rootfs
            pre_switch_slots = pre_switch_rootfs.setdefault("slots", {})
            if not isinstance(pre_switch_slots, dict):
                pre_switch_slots = {}
                pre_switch_rootfs["slots"] = pre_switch_slots
            pre_switch_active = pre_switch_slots.setdefault(slots.active_slot, {})
            if not isinstance(pre_switch_active, dict):
                pre_switch_active = {}
                pre_switch_slots[slots.active_slot] = pre_switch_active
            pre_switch_active["pvcName"] = legacy_jail_pvc
            pre_switch_active["volumeSourceName"] = "cxcli-legacy-rootfs-source"
        pre_switch_checks = _verify_target_rootfs_handoff_consumers(
            command_runner=command_runner,
            kube_context=kube_context,
            values=pre_switch_values,
            resource_snapshot=handoff_consumer_snapshot,
        )
        switched_rootfs = tuple(bool(check.get("rootfs_observed")) for check in switched_checks)
        pre_switch_rootfs = tuple(bool(check.get("rootfs_observed")) for check in pre_switch_checks)
        live_switched = (
            bool(switched_checks) and all(switched_rootfs) and not any(pre_switch_rootfs)
        )
        live_pre_switch = (
            bool(pre_switch_checks) and all(pre_switch_rootfs) and not any(switched_rootfs)
        )
        in_place_pre_ownership_transition = False
        if not live_switched and not live_pre_switch:
            in_place_pre_ownership_transition = (
                _checkpoint_proves_in_place_jail_pre_ownership_transition(
                    checkpoint=checkpoint,
                    payload=payload,
                    phase=phase,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    switched_values=switched_values,
                    switched_checks=switched_checks,
                    pre_switch_checks=pre_switch_checks,
                    command_runner=command_runner,
                )
            )
            live_switched = in_place_pre_ownership_transition
        phase["post_switch_resume_detection"] = {
            "status": (
                "in-place-pre-ownership-transition"
                if in_place_pre_ownership_transition
                else "switched"
                if live_switched
                else "pre-switch"
                if live_pre_switch
                else "uncertain"
            ),
            "checkpointed_switch": switch_checkpointed,
            "switched_consumer_count": sum(switched_rootfs),
            "pre_switch_consumer_count": sum(pre_switch_rootfs),
            "consumer_count": len(switched_checks),
            "checked_at": _utc_now(),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
        external_resume_consumers_uncertain = not live_switched and not live_pre_switch
        recovery_manifest = active_passive_populate_jail_job_manifest(
            namespace=_SOPERATOR_NAMESPACE,
            target_ref=target_ref,
            image=populate_image,
            passive_slot=slots.passive_slot,
            passive_pvc=slots.passive_pvc,
            image_pull_policy=str(
                _mapping(values.get("populateJail")).get("imagePullPolicy") or "IfNotPresent"
            ),
            scheduling=job_scheduling,
        )
        external_switch_recovery_manifest = recovery_manifest
        if live_switched:
            external_switch_recovery_snapshot = _validate_completed_passive_populate_job_checkpoint(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                existing=_mapping(phase.get("passive_slot_populate_job")),
                manifest=recovery_manifest,
                slot=slots.passive_slot,
                pvc=slots.passive_pvc,
                image=populate_image,
                completed_at=phase.get("job_completed_at"),
                target_ref=target_ref,
                expected_pvc_uid=str(
                    _mapping(phase.get("passive_slot_populate_job")).get("pvc_uid") or ""
                ),
            )
            _backfill_passive_populate_monitor()
        live_switch_corroborated = live_switched
        if live_switched:
            if legacy_in_place_entries:
                _ensure_in_place_persistent_mount_adoption_gate(
                    phase=phase,
                    values=values,
                    legacy_jail_pvc=legacy_jail_pvc,
                    slot_pvcs=(slots.active_pvc, slots.passive_pvc),
                    entries=legacy_in_place_entries,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    scheduling=job_scheduling,
                    stage="ready-before-switch",
                    checkpoint_writer=checkpoint_writer,
                )
            mutation_performed = False
            resume_lines = [
                *resume_hold_lines,
                (
                    "Jail Upgrade resume proved the exact in-place pre-ownership boundary: "
                    f"target desired workers use {slots.passive_slot}, source-owned login "
                    "Pods remain held on the legacy rootfs, and passive population and the "
                    "alias switch were not repeated."
                    if in_place_pre_ownership_transition
                    else "Jail Upgrade resume corroborated that login and worker consumers "
                    f"already use active slot {slots.passive_slot}; passive population and "
                    "switching were not repeated."
                ),
            ]
            resume_lines.extend(
                _ensure_jail_gpu_post_population_gate(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    values=values,
                    populate_image=populate_image,
                    runner_image_lock=gpu_post_population_runner_lock,
                    passive_pvc=slots.passive_pvc,
                    populate_job=_mapping(phase.get("passive_slot_populate_job")),
                    checkpoint_writer=checkpoint_writer,
                    allow_apply=False,
                    mutation_guard=mutation_guard,
                )
            )
            resume_lines.extend(
                _require_checkpointed_gpu_activation_boundary_after_switch(
                    phase=phase,
                    values=values,
                )
            )
            phase["consumer_switch_applied_at"] = (
                phase.get("consumer_switch_applied_at") or _utc_now()
            )
            phase["consumer_switch_recovered_from_live_state"] = not switch_checkpointed
            phase["rollback_slot"] = "legacy-rootfs" if legacy_active_rootfs else slots.active_slot
            phase["active_slot"] = slots.passive_slot

            writer_hold_state = phase.setdefault("persistent_migration_writer_hold", {})
            if not isinstance(writer_hold_state, dict):
                raise RuntimeError(
                    "populate-jail-refresh.persistent_migration_writer_hold must be a mapping."
                )
            if legacy_migration_entries:
                switched_values["maintenance"] = _persistent_migration_original_maintenance(
                    writer_hold_state
                )
            maintenance_binding = next(
                (
                    item
                    for item in _sequence_of_mappings(writer_hold_state.get("resources"))
                    if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
                ),
                {},
            )
            if writer_hold_state.get("status") in {"holding", "held", "restored"} and (
                maintenance_binding or writer_hold_state.get("status") in {"holding", "held"}
            ):
                resume_lines.extend(
                    _restore_persistent_migration_writers(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        state=writer_hold_state,
                    )
                )
                phase["persistent_migration_writer_hold"] = dict(writer_hold_state)
                mutation_performed = True
                if checkpoint_writer is not None:
                    checkpoint_writer()

            live_cluster = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    "slurmcluster",
                    target_ref,
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
                check=False,
            )
            if not _mapping(live_cluster.get("metadata")):
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade resume could not verify the target SlurmCluster after "
                    "the live consumer switch; no populate or switch action was retried."
                )
            live_maintenance = str(
                _mapping(live_cluster.get("spec")).get("maintenance") or "none"
            ).strip()
            expected_maintenance = (
                _persistent_migration_original_maintenance(writer_hold_state)
                if legacy_migration_entries
                else str(switched_values.get("maintenance") or "none").strip()
            )
            live_uid = str(_mapping(live_cluster.get("metadata")).get("uid") or "").strip()
            expected_uid = str(maintenance_binding.get("uid") or "").strip()
            if maintenance_binding and (not expected_uid or live_uid != expected_uid):
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade resume target SlurmCluster identity changed after the "
                    "persistent-migration maintenance binding was checkpointed."
                )
            if legacy_migration_entries and live_maintenance != expected_maintenance:
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade resume could not verify the checkpointed steady-state "
                    "maintenance value after restoring the persistent-migration hold."
                )
            if not legacy_migration_entries and live_maintenance != expected_maintenance:
                maintenance_reapply_required = True
            else:
                maintenance_reapply_required = False

            expected_jail_alias_pvc = _pvc_volume_source_claim_name(
                switched_values,
                source_name="jail",
            )
            if not expected_jail_alias_pvc:
                raise RuntimeError(
                    "Jail Upgrade switched values must define exactly one PVC-backed "
                    "volumeSources[name=jail] alias before post-switch resume."
                )
            live_jail_alias_pvc = _pvc_volume_source_claim_name(
                _mapping(live_cluster.get("spec")),
                source_name="jail",
            )
            alias_reapply_required = live_jail_alias_pvc != expected_jail_alias_pvc
            observed_open_metrics = _slurmcluster_controller_open_metrics_enabled(live_cluster)
            open_metrics_status = str((open_metrics_handoff or {}).get("status") or "").strip()
            desired_open_metrics = (open_metrics_handoff or {}).get("desired_enabled")
            open_metrics_restoration_live = bool(
                open_metrics_handoff is not None
                and open_metrics_status in {"restore-intent-recorded", "restored"}
                and isinstance(desired_open_metrics, bool)
                and observed_open_metrics is desired_open_metrics
            )
            open_metrics_compatibility_required = bool(
                open_metrics_handoff is not None and not open_metrics_restoration_live
            )
            open_metrics_reapply_required = bool(
                open_metrics_compatibility_required and observed_open_metrics is not False
            )

            if (
                maintenance_reapply_required
                or alias_reapply_required
                or open_metrics_reapply_required
            ):
                if open_metrics_compatibility_required and open_metrics_handoff is not None:
                    _record_jail_open_metrics_switch_intent(
                        state=open_metrics_handoff,
                        checkpoint_writer=checkpoint_writer,
                    )
                if alias_reapply_required:
                    resume_slots = active_passive_jail_rootfs_slots(switched_values)
                    _checkpoint_legacy_rootfs_jail_boundary_intent(
                        phase=rolling_phase,
                        boundary_id="active-slot-switch",
                        expected_rootfs_pvc=expected_jail_alias_pvc,
                        expected_rootfs_volume_source=resume_slots.active_volume_source,
                        expected_maintenance=expected_maintenance,
                        expected_login_jail_submounts_fingerprint=(
                            _legacy_rootfs_expected_login_jail_submounts_fingerprint(
                                switched_values
                            )
                        ),
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                _require_live_rolling_sconfig_fence(
                    boundary="post-switch resume Helm reconciliation"
                )
                resume_lines.extend(
                    _helm_upgrade_target_soperator_with_jail_login_session_policy(
                        checkpoint=checkpoint,
                        phase=phase,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        values=switched_values,
                        expected_version=target_version,
                        boundary="post-switch-resume",
                        login_session_policy=login_session_policy,
                        login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                        wait=False,
                        disable_open_metrics_for_legacy_clients=(
                            open_metrics_compatibility_required
                            if open_metrics_handoff is not None
                            else None
                        ),
                        checkpoint_writer=checkpoint_writer,
                    )
                )
                mutation_performed = True
                if maintenance_reapply_required:
                    resume_lines.append(
                        "Jail Upgrade resume restored steady-state maintenance values without "
                        "repopulating or switching the active slot."
                    )
                if alias_reapply_required:
                    resume_lines.append(
                        "Jail Upgrade resume reapplied switched Helm values to move the "
                        f"canonical jail alias to active slot PVC {expected_jail_alias_pvc}."
                    )
                if open_metrics_reapply_required:
                    resume_lines.append(
                        "Jail Upgrade resume restored the checkpointed legacy-client "
                        "OpenMetrics compatibility override before continuing consumer checks."
                    )

                live_cluster = _json_from_command(
                    command_runner,
                    [
                        "kubectl",
                        "--context",
                        kube_context,
                        "-n",
                        _SOPERATOR_NAMESPACE,
                        "get",
                        "slurmcluster",
                        target_ref,
                        "-o",
                        "json",
                    ],
                    timeout_seconds=120,
                    check=False,
                )
                refreshed_uid = str(_mapping(live_cluster.get("metadata")).get("uid") or "").strip()
                if not refreshed_uid or refreshed_uid != live_uid:
                    raise SoperatorMigrationPhasePending(
                        "Jail Upgrade resume could not preserve the target SlurmCluster "
                        "identity while reconciling switched Helm values."
                    )

            if open_metrics_compatibility_required and open_metrics_handoff is not None:
                _verify_jail_open_metrics_compatibility_active(
                    state=open_metrics_handoff,
                    resource=live_cluster,
                    checkpoint_writer=checkpoint_writer,
                    recovered_from_live_state=not open_metrics_reapply_required,
                )

            observed_maintenance = str(
                _mapping(live_cluster.get("spec")).get("maintenance") or "none"
            ).strip()
            maintenance_reconciliation = {
                "status": (
                    "reapplied"
                    if maintenance_reapply_required and observed_maintenance == expected_maintenance
                    else "verified"
                    if observed_maintenance == expected_maintenance
                    else "pending"
                ),
                "expected": expected_maintenance,
                "observed": observed_maintenance,
                "checked_at": _utc_now(),
            }
            phase["maintenance_reconciliation"] = maintenance_reconciliation
            if observed_maintenance != expected_maintenance:
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade resume reapplied switched Helm values, but the live "
                    "SlurmCluster steady-state maintenance value still does not match "
                    f"{expected_maintenance}."
                )

            observed_jail_alias_pvc = _pvc_volume_source_claim_name(
                _mapping(live_cluster.get("spec")),
                source_name="jail",
            )
            alias_reconciliation = {
                "status": ("reapplied" if alias_reapply_required else "verified"),
                "expected_pvc": expected_jail_alias_pvc,
                "observed_pvc": observed_jail_alias_pvc,
                "checked_at": _utc_now(),
            }
            phase["jail_volume_source_alias_reconciliation"] = alias_reconciliation
            if observed_jail_alias_pvc != expected_jail_alias_pvc:
                alias_reconciliation["status"] = "pending"
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise SoperatorMigrationPhasePending(
                    "Jail Upgrade resume reapplied switched Helm values, but the live "
                    "SlurmCluster jail volume-source alias still does not reference the "
                    f"active slot PVC {expected_jail_alias_pvc}."
                )
            phase["maintenance_restored_at"] = phase.get("maintenance_restored_at") or _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()

            bridge_active = _legacy_rootfs_target_compatibility_is_active(rolling_phase)
            bridge_released = (
                str(
                    _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge")).get("status")
                    or ""
                ).strip()
                == "released"
            )
            if bridge_active:
                _rebind_legacy_rootfs_target_compatibility_after_jail_helm(
                    phase=rolling_phase,
                    consumer_switch_applied_at=str(phase.get("consumer_switch_applied_at") or ""),
                    boundary_id="active-slot-switch",
                    expected_rootfs_pvc=expected_jail_alias_pvc,
                    expected_rootfs_volume_source=active_passive_jail_rootfs_slots(
                        switched_values
                    ).active_volume_source,
                    expected_maintenance=expected_maintenance,
                    expected_login_jail_submounts_fingerprint=(
                        _legacy_rootfs_expected_login_jail_submounts_fingerprint(switched_values)
                    ),
                    values=switched_values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            resume_lines.extend(_shrink_session_free_login_holds_before_ownership())
            handoff_mutation, handoff_lines = _ensure_ownership_handoff(switched_values)
            mutation_performed = mutation_performed or handoff_mutation
            resume_lines.extend(handoff_lines)
            resume_lines.extend(
                _release_jail_login_hold_before_full_rollout(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    rootfs_pvc=expected_jail_alias_pvc,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            _wait_for_jail_target_availability_or_defer_protected_login(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                checkpoint_writer=checkpoint_writer,
            )
            alias_consumer_checks = _verify_target_jail_alias_consumers(
                command_runner=command_runner,
                kube_context=kube_context,
                slurmcluster=live_cluster,
                rootfs_pvc=expected_jail_alias_pvc,
                wait_for_rollout=True,
                legacy_rootfs_bridge_state=_mapping(
                    rolling_phase.get("legacy_rootfs_slurm_config_bridge")
                ),
            )
            alias_consumer_verification = {
                "status": (
                    "pending"
                    if any(check.get("status") != "verified" for check in alias_consumer_checks)
                    else "verified"
                ),
                "expected_pvc": expected_jail_alias_pvc,
                "checks": alias_consumer_checks,
                "sconfig_fenced": bridge_active,
                "checked_at": _utc_now(),
            }
            phase["jail_alias_consumer_verification"] = alias_consumer_verification
            if alias_consumer_verification["status"] != "verified":
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise SoperatorMigrationPhasePending(
                    _jail_alias_consumer_pending_reason(alias_consumer_checks)
                )
            if checkpoint_writer is not None:
                checkpoint_writer()
            resume_lines.extend(
                _repair_gpu_driver_jail_init_loader_for_target_workers(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    target_ref=target_ref,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            resume_lines.extend(
                _rollover_orphaned_worker_pods_for_target_statefulsets(
                    phase=rolling_phase,
                    values=switched_values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            resume_lines.extend(
                _repair_gpu_driver_jail_init_loader_for_target_workers(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    target_ref=target_ref,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            resume_lines.extend(
                _repair_gpu_health_sysfs_for_target_workers(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            _wait_for_target_worker_nodesets_ready(
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
                timeout_seconds=1800,
            )
            resume_lines.extend(
                _rollover_orphaned_worker_pods_for_target_statefulsets(
                    phase=rolling_phase,
                    values=switched_values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            phase["login_service_ready_after_switch"] = _login_ready_after_switch()
            switched_checks = _verify_target_rootfs_handoff_consumers(
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
            )
            consumer_handoff_pending = any(
                check.get("status") != "verified" for check in switched_checks
            )
            live_home_mount_checks = _live_home_mount_probe_checks(
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
                target_ref=target_ref,
                protected_login_pod_uids=_protected_login_pod_uids(),
            )
            handoff_mount_status = jail_persistent_mount_status(switched_values)
            handoff_slots = active_passive_jail_rootfs_slots(switched_values)
            handoff_verification = {
                "status": (
                    "pending"
                    if consumer_handoff_pending or _fast_verification_failed(live_home_mount_checks)
                    else "consumers-verified-with-sconfig-fenced"
                    if bridge_active
                    else "consumers-verified-with-sconfig-released"
                    if bridge_released
                    else "verified"
                ),
                "active_slot": handoff_slots.active_slot,
                "active_volume_source": handoff_slots.active_volume_source,
                "active_pvc": handoff_slots.active_pvc,
                "rollback_slot": phase["rollback_slot"],
                "worker_nodesets": list(_target_worker_nodeset_names(switched_values)),
                "persistent_mounts": [mount.as_payload() for mount in handoff_mount_status.mounts],
                "persistent_mount_status": handoff_mount_status.status,
                "persistent_mount_reason": handoff_mount_status.reason,
                "consumer_checks": switched_checks,
                "live_home_mount_checks": list(live_home_mount_checks),
                "verification_revision": _ROOTFS_HANDOFF_VERIFICATION_REVISION,
                "recovered_from_live_state": True,
            }
            if consumer_handoff_pending:
                handoff_verification["reason"] = _rootfs_handoff_pending_reason(switched_checks)
            elif _fast_verification_failed(live_home_mount_checks):
                handoff_verification["reason"] = _live_home_mount_pending_reason(
                    live_home_mount_checks
                )
            else:
                if bridge_active:
                    handoff_verification["staged_verified_at"] = _utc_now()
                elif bridge_released:
                    handoff_verification["released_consumers_verified_at"] = _utc_now()
                else:
                    handoff_verification["verified_at"] = _utc_now()
            phase["rootfs_handoff_verification"] = handoff_verification
            if checkpoint_writer is not None:
                checkpoint_writer()
            if consumer_handoff_pending or _fast_verification_failed(live_home_mount_checks):
                raise SoperatorMigrationPhasePending(str(handoff_verification["reason"]))
            resume_lines.extend(
                _release_legacy_rootfs_sconfig_writer_after_slot_verification(
                    bridge_phase=rolling_phase,
                    handoff_verification=handoff_verification,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=None,
                    rootfs_pvc=expected_jail_alias_pvc,
                    open_metrics_handoff=open_metrics_handoff,
                )
            )
            if handoff_verification["status"] in {
                "consumers-verified-with-sconfig-fenced",
                "consumers-verified-with-sconfig-released",
            }:
                handoff_verification["status"] = "verified"
                handoff_verification["sconfig_release"] = dict(
                    _mapping(
                        _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge")).get(
                            "target_writer_release"
                        )
                    )
                )
                handoff_verification["verified_at"] = _utc_now()
                phase["rootfs_handoff_verification"] = handoff_verification
                if checkpoint_writer is not None:
                    checkpoint_writer()
            _kubectl_rollout_status(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                resource="deployment/soperator-manager",
                timeout="15m",
            )

            if open_metrics_handoff is not None:
                restored_mutation, restored_lines = (
                    _restore_jail_open_metrics_before_release_checks(
                        phase=phase,
                        state=open_metrics_handoff,
                        switched_values=switched_values,
                        target_version=target_version,
                        target_ref=target_ref,
                        kube_context=kube_context,
                        command_runner=command_runner,
                        login_session_policy=login_session_policy,
                        login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                        checkpoint_writer=checkpoint_writer,
                    )
                )
                mutation_performed |= restored_mutation
                resume_lines.extend(restored_lines)
            resume_lines.extend(
                _repair_gpu_worker_topology_before_jail_smoke(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    target_ref=target_ref,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            resume_lines.extend(
                _ensure_gpu_worker_jail_release_gate(
                    phase=phase,
                    checkpoint=checkpoint,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    values=switched_values,
                    checkpoint_writer=checkpoint_writer,
                    gate_key="post_jail_gpu_workload_release_gate",
                )
            )
            resume_lines.extend(
                _ensure_jail_gpu_post_activation_gate(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    values=switched_values,
                    checkpoint_writer=checkpoint_writer,
                    replacement_phase=rolling_phase,
                    mutation_guard=mutation_guard,
                )
            )
            resume_lines.extend(
                _ensure_post_jail_slurm_pre_release_checks(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            slurm_pause_records = _rolling_compute_checkpoint_pause_records(phase)
            if slurm_pause_records and not phase.get("slurm_resumed_at"):
                phase["slurm_partition_restore_status"] = "deferred"
                phase["slurm_partition_restore_deferred_reason"] = (
                    "Jail validation passed, but scheduling remains paused until the final "
                    "singleton, action, login, worker, and health gates pass before bridge "
                    "cleanup."
                )
                resume_lines.append(
                    "Slurm partitions remain paused until final gates pass; exact records "
                    "restore before destructive bridge cleanup."
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()

            smoke_state = _mapping(phase.get("post_jail_slurm_smoke"))
            if str(smoke_state.get("status") or "").strip() == "passed":
                post_jail_smoke_lines = [
                    "Jail Upgrade post-rootfs Slurm smoke reused the passed checkpoint."
                ]
            else:
                post_jail_smoke_lines = _ensure_post_jail_slurm_smoke(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            if (
                _compute_migration_contract(payload, target_ref).get("mode")
                == COMPUTE_MIGRATION_MODE_IN_PLACE
            ):
                resume_lines.extend(
                    _ensure_in_place_target_manager_paused(
                        phase=rolling_phase,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                )
                resume_lines.extend(
                    _ensure_in_place_target_controller_command_gate(
                        checkpoint=checkpoint,
                        phase=rolling_phase,
                        target_ref=target_ref,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                )
            passive_job = _mapping(phase.get("passive_slot_populate_job"))
            prior_result = _mapping(phase.get("result"))
            refreshed = type(before)(
                slurmcluster_name=before.slurmcluster_name or target_ref,
                image=str(passive_job.get("image") or before.image or populate_image),
                job_name=str(passive_job.get("name") or prior_result.get("job_name") or ""),
                job_uid=str(
                    passive_job.get("uid")
                    or (
                        external_switch_recovery_snapshot.job_uid
                        if external_switch_recovery_snapshot is not None
                        else ""
                    )
                    or prior_result.get("job_uid")
                    or ""
                ),
                job_complete=True,
                job_image=str(
                    passive_job.get("image") or prior_result.get("job_image") or populate_image
                ),
                active_consumer_pods=before.active_consumer_pods,
                status="collected",
                detail="resumed from a live-corroborated post-switch state",
            )
            result = completed_populate_jail_refresh_result(
                mode=plan.mode,
                reason=plan.reason,
                snapshot=refreshed,
                maintenance_restored=True,
            )
            phase["result"] = result.as_payload()
            phase["completed_at"] = _utc_now()
            execution["status"] = "completed"
            execution["completed_at"] = phase["completed_at"]
            if checkpoint_writer is not None:
                checkpoint_writer()
            return mutation_performed, [
                *topology_lines,
                *resume_lines,
                *post_jail_smoke_lines,
            ]
    existing_migration_state = dict(_mapping(phase.get("legacy_persistent_mount_migration")))
    migration_status = str(existing_migration_state.get("status") or "").strip()
    if migration_status == "stale-after-writer-drift":
        stale_writer_state = phase.setdefault("persistent_migration_writer_hold", {})
        if not isinstance(stale_writer_state, dict):
            raise RuntimeError(
                "populate-jail-refresh.persistent_migration_writer_hold must be a mapping."
            )
        _raise_after_external_stale_copy_cleanup(writer_state=stale_writer_state)
    if migration_status not in {"completed", "running"}:
        migration_status = "planned" if legacy_migration_entries else "not_required"
    phase["legacy_persistent_mount_migration"] = {
        **existing_migration_state,
        "status": migration_status,
        "entries": existing_migration_state.get("entries")
        if migration_status in {"completed", "running"}
        else [dict(to_plain_data(entry)) for entry in legacy_migration_entries],
    }
    checkpoint["populate_jail_refresh"] = {
        **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
        "legacy_persistent_mount_migration": dict(
            _mapping(phase.get("legacy_persistent_mount_migration"))
        ),
    }
    resume_writer_state = phase.setdefault("persistent_migration_writer_hold", {})
    if not isinstance(resume_writer_state, dict):
        raise RuntimeError(
            "populate-jail-refresh.persistent_migration_writer_hold must be a mapping."
        )
    hold_failure_reason = ""
    if migration_status in {"running", "completed"} and not live_switch_corroborated:
        if resume_writer_state.get("status") != "held":
            hold_failure_reason = (
                "a checkpointed persistent copy no longer has a continuously held writer boundary"
            )
        else:
            resume_hold_drift = _persistent_migration_writer_hold_drift(
                command_runner=command_runner,
                kube_context=kube_context,
                state=resume_writer_state,
            )
            if resume_hold_drift:
                resume_writer_state["drift_detected_at"] = _utc_now()
                resume_writer_state["drift_boundary"] = "resume before source probe"
                resume_writer_state["drift"] = [dict(item) for item in resume_hold_drift]
                hold_failure_reason = (
                    "checkpointed writers were not continuously held when the upgrade resumed"
                )
    if hold_failure_reason:
        migration_state = phase.setdefault("legacy_persistent_mount_migration", {})
        if not isinstance(migration_state, dict):
            raise RuntimeError(
                "populate-jail-refresh.legacy_persistent_mount_migration must be a mapping."
            )
        migration_state["status"] = "stale-after-writer-drift"
        migration_state["stale_at"] = _utc_now()
        migration_state["stale_boundary"] = "resume before source probe"
        migration_state["stale_reason"] = hold_failure_reason
        checkpoint["populate_jail_refresh"] = {
            **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
            "legacy_persistent_mount_migration": dict(migration_state),
        }
        phase["persistent_migration_failure_boundary"] = {
            "status": "manual-reconciliation-required",
            "boundary": "resume before source probe",
            "reason": (
                "persistent copy may be stale after writer-hold drift; source probe, "
                "capacity resize, and automatic marker reuse are blocked"
            ),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
        _raise_after_external_stale_copy_cleanup(writer_state=resume_writer_state)
    if external_resume_consumers_uncertain:
        raise SoperatorMigrationPhasePending(
            "Jail Upgrade resume found mixed or uncertain live login/worker rootfs "
            "consumer slots after passive population. The checkpointed writer boundary "
            "was checked first; no source probe, capacity resize, populate Job, or Helm "
            "switch was attempted. Reconcile the live consumers to one checkpointed slot "
            "and rerun the same command."
        )
    if live_pre_switch and external_switch_recovery_manifest is not None:
        external_switch_recovery_snapshot = _validate_completed_passive_populate_job_checkpoint(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            existing=_mapping(phase.get("passive_slot_populate_job")),
            manifest=external_switch_recovery_manifest,
            slot=slots.passive_slot,
            pvc=slots.passive_pvc,
            image=populate_image,
            completed_at=phase.get("job_completed_at"),
            target_ref=target_ref,
            expected_pvc_uid=str(
                _mapping(phase.get("passive_slot_populate_job")).get("pvc_uid") or ""
            ),
        )
        _backfill_passive_populate_monitor()
    source_probe_entries: tuple[dict[str, Any], ...] = ()
    if legacy_migration_entries and migration_status != "completed":
        checkpointed_migration_entries = _sequence_of_mappings(
            _mapping(phase.get("legacy_persistent_mount_migration")).get("entries")
        )
        source_probe_entries = _probe_legacy_persistent_mount_sources(
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            image=populate_image,
            jail_pvc=legacy_jail_pvc,
            entries=legacy_migration_entries,
            scheduling=job_scheduling,
        )
        source_by_mount = {
            str(entry.get("mount_path") or ""): entry
            for entry in source_probe_entries
            if str(entry.get("mount_path") or "")
        }
        updated_entries: list[dict[str, Any]] = []
        for entry in legacy_migration_entries:
            next_entry = dict(to_plain_data(entry))
            probe = source_by_mount.get(str(next_entry.get("mount_path") or ""))
            if probe:
                next_entry["source_status"] = str(probe.get("source_status") or "unknown")
                next_entry["marker_status"] = str(probe.get("marker_status") or "unknown")
                next_entry["marker_present"] = bool(probe.get("marker_present"))
            else:
                next_entry["source_status"] = "unknown"
            updated_entries.append(next_entry)
        legacy_migration_entries = tuple(updated_entries)
        _require_persistent_mount_reprobe_binding(
            migration_status=migration_status,
            checkpointed_entries=checkpointed_migration_entries,
            probed_entries=legacy_migration_entries,
        )
        phase["legacy_persistent_mount_source_probe"] = {
            "status": "completed",
            "probed_at": _utc_now(),
            "entries": [dict(entry) for entry in source_probe_entries],
        }
        phase["legacy_persistent_mount_migration"] = {
            **dict(_mapping(phase.get("legacy_persistent_mount_migration"))),
            "entries": [dict(entry) for entry in legacy_migration_entries],
        }
        _sync_persistent_mount_decisions_from_migration_entries(
            checkpoint,
            legacy_migration_entries,
        )
        checkpoint["populate_jail_refresh"] = {
            **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
            "legacy_persistent_mount_source_probe": dict(
                _mapping(phase.get("legacy_persistent_mount_source_probe"))
            ),
            "legacy_persistent_mount_migration": dict(
                _mapping(phase.get("legacy_persistent_mount_migration"))
            ),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()

    def _probe_jail_capacity() -> JailCapacityPreflight:
        copy_required_entries = tuple(
            entry
            for entry in legacy_migration_entries
            if str(entry.get("source_status") or "unknown") != "absent"
        )
        active_pvc = legacy_jail_pvc if legacy_active_rootfs else slots.active_pvc
        passive_pvc = active_pvc if legacy_active_rootfs else slots.passive_pvc
        active_rootfs_path = JAIL_LEGACY_ROOT_PATH if legacy_active_rootfs else ""
        exclude_paths = (
            *jail_persistent_mount_exclude_paths(values),
            *(str(entry.get("source_path") or "") for entry in legacy_migration_entries),
        )
        extra_required_paths = (
            ()
            if str(
                _mapping(phase.get("legacy_persistent_mount_migration")).get("status") or ""
            ).strip()
            == "completed"
            else tuple(str(entry.get("source_path") or "") for entry in copy_required_entries)
        )
        return probe_active_passive_jail_capacity(
            command_runner,
            namespace=_SOPERATOR_NAMESPACE,
            target_ref=target_ref,
            image=populate_image,
            active_pvc=active_pvc,
            passive_pvc=passive_pvc,
            active_rootfs_path=active_rootfs_path,
            exclude_paths=exclude_paths,
            extra_required_paths=extra_required_paths,
            scheduling=job_scheduling,
            kube_context=kube_context,
        )

    capacity_preflight = _probe_jail_capacity()
    phase["capacity_preflight"] = capacity_preflight.as_payload()
    checkpoint["populate_jail_refresh"] = {
        **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
        "capacity_preflight": capacity_preflight.as_payload(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    if not capacity_preflight.sufficient:
        if jail_sfs_resize_handler is None:
            phase["capacity_preflight_check"] = dict(
                capacity_preflight_check_payload(capacity_preflight)
            )
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise SoperatorMigrationPhasePending(
                "passive jail rootfs slot does not have enough free space. "
                "Review populate-jail-refresh.capacity_preflight in the checkpoint "
                "and resize the existing Nebius jail SFS before retrying."
            )
        _require_live_rolling_sconfig_fence(boundary="jail SFS capacity resize")
        capacity_preflight = jail_sfs_resize_handler(
            capacity_preflight,
            _probe_jail_capacity,
            phase,
            checkpoint,
            checkpoint_writer,
        )
    phase["capacity_preflight"] = capacity_preflight.as_payload()
    phase["capacity_preflight_check"] = dict(capacity_preflight_check_payload(capacity_preflight))
    checkpoint["populate_jail_refresh"] = {
        **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
        "capacity_preflight": capacity_preflight.as_payload(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    if not capacity_preflight.sufficient:
        raise SoperatorMigrationPhasePending(
            "passive jail rootfs slot does not have enough free space after resize recheck."
        )
    checkpoint_worker_groups = tuple(
        str(group or "") for group in checkpoint.get("worker_node_groups", []) or []
    )
    live_source_slurmcluster_present = _live_source_slurmcluster_present(
        command_runner=command_runner,
        kube_context=kube_context,
        source_report=source_report,
        target_ref=target_ref,
    )
    live_worker_slurm_nodes = _external_upgrade_worker_nodeset_slurm_nodes(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    source_worker_nodes = _nodes_for_worker_groups(
        source_report=source_report,
        worker_node_groups=checkpoint_worker_groups,
    )
    quiet_nodes = live_worker_slurm_nodes or source_worker_nodes
    phase["slurm_job_scope_nodes"] = list(quiet_nodes)
    phase["slurm_job_scope"] = (
        "live-worker-nodesets" if live_worker_slurm_nodes else "source-worker-node-groups"
    )
    writer_hold_state = phase.setdefault("persistent_migration_writer_hold", {})
    if not isinstance(writer_hold_state, dict):
        raise RuntimeError(
            "populate-jail-refresh.persistent_migration_writer_hold must be a mapping."
        )
    checkpointed_slurm_pause_records = _rolling_compute_checkpoint_pause_records(phase)

    def _record_populate_jail_slurm_intent(record: SlurmPartitionPauseRecord) -> None:
        _checkpoint_slurm_partition_pause_intent(
            phase=phase,
            record=record,
            checkpoint_writer=checkpoint_writer,
        )

    quiet_lines, live_slurm_pause_records = _ensure_slurm_quiet(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=quiet_nodes,
        job_policy=job_policy,
        cancel_job_ids=cancel_job_ids,
        requeue_job_ids=requeue_job_ids,
        job_wait_timeout_seconds=job_wait_timeout_seconds,
        job_refresh_interval_seconds=job_refresh_interval_seconds,
        slurm_decision_recorder=slurm_decision_recorder,
        slurm_pause_intent_recorder=_record_populate_jail_slurm_intent,
        allow_missing_login_recovery=not live_source_slurmcluster_present,
        interactive_prompt_pause=interactive_prompt_pause,
        allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
        slurm_scheduling_pause=slurm_scheduling_pause,
        held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
        held_job_checkpoint_writer=checkpoint_writer,
        slurm_action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
        slurm_action_checkpoint_writer=checkpoint_writer,
        slurm_controller_authority_provider=lambda: _external_upgrade_slurm_action_authority(
            checkpoint
        ),
    )
    slurm_pause_records = _merge_slurm_partition_pause_records(
        checkpointed_slurm_pause_records,
        live_slurm_pause_records,
    )
    if checkpointed_slurm_pause_records and not live_slurm_pause_records:
        quiet_lines.append("Slurm scheduling pause: reused checkpointed partition restore state.")

    try:
        phase["slurm_quiet_at"] = _utc_now()
        phase["slurm_quiet_lines"] = list(quiet_lines)
        phase["slurm_paused_partitions"] = [record.as_payload() for record in slurm_pause_records]
        if slurm_pause_records:
            phase.pop("slurm_resumed_at", None)
            phase.pop("slurm_resumed_after_failure_at", None)
        if checkpoint_writer is not None:
            checkpoint_writer()
    except (Exception, KeyboardInterrupt):
        if slurm_pause_records:
            phase["slurm_partition_restore_status"] = "deferred"
            phase["slurm_partition_restore_deferred_reason"] = (
                "the phase checkpoint failed after the durable pause intent; partitions "
                "remain DOWN for fail-closed recovery"
            )
        raise
    mutation_performed = False
    migration_lines: list[str] = []

    def _restore_after_refresh_failure() -> None:
        cleanup_errors: list[str] = []
        current_migration_status = str(
            _mapping(phase.get("legacy_persistent_mount_migration")).get("status") or ""
        ).strip()
        stale_after_writer_drift = current_migration_status == "stale-after-writer-drift"
        if stale_after_writer_drift:
            try:
                stale_errors, stale_lines = _restore_external_stale_persistent_copy_writers(
                    writer_state=writer_hold_state
                )
                cleanup_errors.extend(stale_errors)
                migration_lines.extend(stale_lines)
            except Exception as exc:  # pragma: no cover - cleanup checkpoint guard
                cleanup_errors.append(f"stale persistent-copy cleanup failed: {exc}")
        migration_completed = current_migration_status == "completed"
        migration_job = _mapping(
            _mapping(phase.get("legacy_persistent_mount_migration")).get("job")
        )
        migration_copy_may_be_active = current_migration_status == "running" and any(
            str(migration_job.get(key) or "").strip()
            for key in ("apply_started_at", "applied_at", "uid")
        )
        keep_writers_held = bool(
            legacy_migration_entries
            and writer_hold_state.get("status") == "held"
            and (migration_completed or migration_copy_may_be_active)
        )
        if keep_writers_held:
            phase["persistent_migration_failure_boundary"] = {
                "status": "writers_held",
                "reason": (
                    "persistent mount migration already completed; keeping legacy "
                    "writers stopped so the shared copy cannot become stale"
                    if migration_completed
                    else "persistent mount migration started; keeping legacy writers "
                    "stopped until the UID-bound copy Job and durable proof are reconciled"
                ),
            }
        if (
            legacy_migration_entries
            and writer_hold_state.get("status") in {"holding", "held"}
            and not keep_writers_held
            and not stale_after_writer_drift
        ):
            try:
                migration_lines.extend(
                    _restore_persistent_migration_writers(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        state=writer_hold_state,
                    )
                )
                phase["persistent_migration_writer_hold"] = dict(writer_hold_state)
            except Exception as exc:  # pragma: no cover - best-effort operational cleanup
                cleanup_errors.append(f"persistent writer restore failed: {exc}")
        if (
            slurm_pause_records
            and phase.get("slurm_quiet_at")
            and not phase.get("slurm_resumed_at")
        ):
            reason = (
                "Jail Upgrade failed or remains pending; the upgrade-owned pause stays in "
                "force until final continuity gates pass before controller bridge cleanup"
            )
            if cleanup_errors:
                reason += "; persistent-writer cleanup also remains incomplete"
            elif keep_writers_held:
                reason += "; persistent-migration writers remain deliberately fenced"
            phase["slurm_resume_after_failure"] = {
                "status": "deferred",
                "reason": reason,
                "partitions": [record.as_payload() for record in slurm_pause_records],
            }
            phase["slurm_partition_restore_status"] = "deferred"
            phase["slurm_partition_restore_deferred_reason"] = reason
        if cleanup_errors:
            phase["refresh_failure_cleanup_errors"] = cleanup_errors
        else:
            phase.pop("refresh_failure_cleanup_errors", None)
        if checkpoint_writer is not None:
            checkpoint_writer()

    if legacy_migration_entries:
        try:
            migration_status = str(
                _mapping(phase.get("legacy_persistent_mount_migration")).get("status") or ""
            ).strip()
            if migration_status == "running" and writer_hold_state.get("status") != "held":
                migration_state = phase.setdefault("legacy_persistent_mount_migration", {})
                if not isinstance(migration_state, dict):
                    raise RuntimeError(
                        "populate-jail-refresh.legacy_persistent_mount_migration must be a mapping."
                    )
                migration_state["status"] = "stale-after-writer-drift"
                migration_state["stale_at"] = _utc_now()
                migration_state["stale_reason"] = (
                    "a checkpointed running copy no longer has a continuously held writer boundary"
                )
                checkpoint["populate_jail_refresh"] = {
                    **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
                    "legacy_persistent_mount_migration": dict(migration_state),
                }
                phase["persistent_migration_failure_boundary"] = {
                    "status": "manual-reconciliation-required",
                    "reason": (
                        "running persistent copy lost its continuous writer hold; automatic "
                        "Job and marker reuse is blocked"
                    ),
                }
                if checkpoint_writer is not None:
                    checkpoint_writer()
                raise SoperatorMigrationPhasePending(
                    "checkpointed persistent-migration copy was running without a "
                    "continuously held writer boundary. The copy may be stale, so cxcli "
                    "blocks automatic Job and marker reuse pending manual reconciliation."
                )
            maintenance_hold_checkpointed = any(
                str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
                for item in _sequence_of_mappings(writer_hold_state.get("resources"))
            )
            if writer_hold_state.get("status") == "holding" and not maintenance_hold_checkpointed:
                migration_lines.extend(
                    _restore_persistent_migration_writers(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        state=writer_hold_state,
                    )
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
            hold_policy_state = _mapping(phase.get("persistent_migration_login_hold_policy"))
            if writer_hold_state.get("status") == "held":
                if str(hold_policy_state.get("status") or "").strip() != "allowed":
                    raise SoperatorMigrationPhasePending(
                        "persistent migration writers are checkpointed as held, but the "
                        "login-session hold authorization is missing. Review the checkpoint "
                        "before resuming."
                    )
                hold_drift = _persistent_migration_writer_hold_drift(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    state=writer_hold_state,
                )
                if hold_drift:
                    writer_hold_state["drift_detected_at"] = _utc_now()
                    writer_hold_state["drift"] = [dict(item) for item in hold_drift]
                    migration_status = str(
                        _mapping(phase.get("legacy_persistent_mount_migration")).get("status") or ""
                    ).strip()
                    if migration_status in {"running", "completed"}:
                        migration_state = phase.setdefault("legacy_persistent_mount_migration", {})
                        if not isinstance(migration_state, dict):
                            raise RuntimeError(
                                "populate-jail-refresh.legacy_persistent_mount_migration "
                                "must be a mapping."
                            )
                        migration_state["status"] = "stale-after-writer-drift"
                        migration_state["stale_at"] = _utc_now()
                        migration_state["stale_reason"] = (
                            "checkpointed writers were not continuously held after the "
                            f"persistent copy was {migration_status}"
                        )
                        checkpoint["populate_jail_refresh"] = {
                            **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
                            "legacy_persistent_mount_migration": dict(migration_state),
                        }
                        phase["persistent_migration_failure_boundary"] = {
                            "status": "manual-reconciliation-required",
                            "reason": (
                                "persistent copy may be stale after writer-hold drift; "
                                "automatic marker reuse is blocked"
                            ),
                        }
                        if checkpoint_writer is not None:
                            checkpoint_writer()
                        raise SoperatorMigrationPhasePending(
                            "checkpointed persistent-migration writers drifted after the copy "
                            f"was {migration_status}. The shared copy may be stale, so cxcli will "
                            "restore steady-state writers and Slurm scheduling but block "
                            "automatic marker reuse pending manual reconciliation."
                        )
                    if checkpoint_writer is not None:
                        checkpoint_writer()
                    raise SoperatorMigrationPhasePending(
                        "checkpointed persistent-migration writers drifted before the copy "
                        "completed. cxcli will restore steady-state writers and Slurm "
                        "scheduling; rerun the same command to establish a fresh hold."
                    )
                migration_lines.append(
                    "Reused checkpointed login-session authorization and writer hold."
                )
            else:
                migration_lines.extend(
                    _ensure_persistent_migration_login_hold_allowed(
                        phase=phase,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        policy=login_session_policy,
                        timeout_seconds=login_session_drain_timeout_seconds,
                        continuous_login_required=True,
                    )
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                migration_lines.extend(
                    _hold_persistent_migration_writers(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        target_ref=target_ref,
                        values=values,
                        state=writer_hold_state,
                        checkpoint_writer=checkpoint_writer,
                    )
                )
            if checkpoint_writer is not None:
                checkpoint_writer()
            migration_mutation, lines = _execute_legacy_persistent_mount_migration(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                image="ubuntu:24.04",
                jail_pvc=legacy_jail_pvc,
                entries=legacy_migration_entries,
                scheduling=job_scheduling,
                checkpoint_writer=checkpoint_writer,
            )
            _ensure_persistent_migration_writer_hold_intact_after_copy(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                state=writer_hold_state,
                boundary="persistent copy completion",
                checkpoint_writer=checkpoint_writer,
            )
        except (Exception, KeyboardInterrupt):
            _restore_after_refresh_failure()
            raise
        mutation_performed = mutation_performed or migration_mutation
        migration_lines.extend(lines)
        checkpoint["populate_jail_refresh"] = {
            **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
            "legacy_persistent_mount_migration": dict(
                _mapping(phase.get("legacy_persistent_mount_migration"))
            ),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
    try:
        maintenance_restored = not legacy_migration_entries
        post_jail_smoke_lines: list[str] = []
        if legacy_in_place_entries:
            _ensure_in_place_persistent_mount_adoption_gate(
                phase=phase,
                values=values,
                legacy_jail_pvc=legacy_jail_pvc,
                slot_pvcs=(slots.active_pvc, slots.passive_pvc),
                entries=legacy_in_place_entries,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
                scheduling=job_scheduling,
                stage="pre-refresh",
                checkpoint_writer=checkpoint_writer,
            )
        for attempt_key in (
            "job_completed_at",
            "consumer_switch_applied_at",
            "login_service_ready_before_switch",
            "login_service_ready_after_switch",
            "rootfs_handoff_verification",
            "post_jail_slurm_smoke",
            "result",
            "completed_at",
        ):
            if external_switch_recovery_snapshot is not None and attempt_key == "job_completed_at":
                continue
            phase.pop(attempt_key, None)
        phase["refresh_attempt"] = (
            _positive_int(
                phase.get("refresh_attempt"),
                fallback=0,
            )
            + 1
        )
        phase["refresh_attempt_started_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
        in_place_source_fence_required = bool(
            legacy_active_rootfs
            and source_declares_controller
            and migration_mode == COMPUTE_MIGRATION_MODE_IN_PLACE
        )
        if in_place_source_fence_required:
            writer_observation = _pre_target_helm_sconfig_writer_observation(
                command_runner=command_runner,
                kube_context=kube_context,
            )
            writer_already_zero = _resource_replicas(writer_observation, default=-1) == 0
            if writer_already_zero:
                migration_lines.extend(
                    _ensure_pre_target_helm_sconfig_writer_fence(
                        checkpoint=checkpoint,
                        phase=rolling_phase,
                        target_ref=target_ref,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                        mutation_guard=mutation_guard,
                        initial_deployment=writer_observation,
                    )
                )
            migration_lines.extend(
                _ensure_safe_fresh_target_helm_ordering(
                    checkpoint=checkpoint,
                    phase=rolling_phase,
                    source_report=source_report,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            if not writer_already_zero:
                migration_lines.extend(
                    _ensure_pre_target_helm_sconfig_writer_fence(
                        checkpoint=checkpoint,
                        phase=rolling_phase,
                        target_ref=target_ref,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                        mutation_guard=mutation_guard,
                    )
                )
        if external_switch_recovery_snapshot is None:
            refresh_values = populate_jail_refresh_values(values)
            if legacy_migration_entries:
                refresh_values = _persistent_migration_writer_hold_values(refresh_values)
            _require_live_rolling_sconfig_fence(boundary="passive-slot Helm preparation")
            migration_lines.extend(
                _helm_upgrade_target_soperator_with_jail_login_session_policy(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    values=refresh_values,
                    expected_version=target_version,
                    boundary="passive-slot-preparation",
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    wait=False,
                    disable_open_metrics_for_legacy_clients=(
                        True if open_metrics_handoff is not None else None
                    ),
                    writer_hold_state=(writer_hold_state if legacy_migration_entries else None),
                    checkpoint_writer=checkpoint_writer,
                )
            )
            if in_place_source_fence_required:
                _verify_source_reconciliation_fence_after_target_helm(
                    phase=rolling_phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
            mutation_performed = True
            phase["passive_slot_refresh_values_applied_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
            manifest = active_passive_populate_jail_job_manifest(
                namespace=_SOPERATOR_NAMESPACE,
                target_ref=target_ref,
                image=populate_image,
                passive_slot=slots.passive_slot,
                passive_pvc=slots.passive_pvc,
                image_pull_policy=str(
                    _mapping(values.get("populateJail")).get("imagePullPolicy") or "IfNotPresent"
                ),
                scheduling=job_scheduling,
            )
            completion_validation_manifest = copy.deepcopy(manifest)
            existing_populate_job = _mapping(phase.get("passive_slot_populate_job"))
            phase["passive_slot_populate_job"] = _bind_passive_populate_job_checkpoint(
                existing=existing_populate_job,
                manifest=manifest,
                slot=slots.passive_slot,
                pvc=slots.passive_pvc,
                image=populate_image,
            )
            _bind_passive_populate_pvc_uid(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                state=phase["passive_slot_populate_job"],
                pvc=slots.passive_pvc,
                allow_initial_binding=not bool(
                    existing_populate_job.get("uid")
                    or existing_populate_job.get("action")
                    or phase.get("job_completed_at")
                ),
            )
            job_name = str(phase["passive_slot_populate_job"].get("name") or "")
            if checkpoint_writer is not None:
                checkpoint_writer()
            _require_live_rolling_sconfig_fence(boundary="passive-slot populate Job apply")
            job_action = _ensure_passive_populate_job(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                manifest=manifest,
                expected_uid=str(phase["passive_slot_populate_job"].get("uid") or ""),
                expected_pvc_uid=str(phase["passive_slot_populate_job"].get("pvc_uid") or ""),
                state=phase["passive_slot_populate_job"],
                checkpoint_writer=checkpoint_writer,
            )
            phase["passive_slot_populate_job"]["action"] = job_action
            if not _mapping(phase.get("passive_slot_populate_monitor")):
                phase["passive_slot_populate_monitor"] = PopulateJailProgress(
                    status="job-bound",
                    observed_at=_utc_now(),
                    job_name=job_name,
                    job_uid=str(phase["passive_slot_populate_job"].get("uid") or ""),
                ).as_payload()
            if checkpoint_writer is not None:
                checkpoint_writer()

            def _checkpoint_populate_progress(progress: PopulateJailProgress) -> None:
                payload = progress.as_payload()
                previous_monitor = _mapping(phase.get("passive_slot_populate_monitor"))
                if not payload.get("deadline_at") and previous_monitor.get("deadline_at"):
                    payload["deadline_at"] = previous_monitor["deadline_at"]
                phase["passive_slot_populate_monitor"] = payload
                if checkpoint_writer is not None:
                    checkpoint_writer()

            existing_populate_monitor = _mapping(phase.get("passive_slot_populate_monitor"))
            wait_for_active_passive_populate_jail_job(
                command_runner,
                namespace=_SOPERATOR_NAMESPACE,
                job_name=job_name,
                expected_image=populate_image,
                expected_job_uid=str(phase["passive_slot_populate_job"].get("uid") or ""),
                expected_pod_uid=str(existing_populate_monitor.get("pod_uid") or ""),
                kube_context=kube_context,
                on_progress=_checkpoint_populate_progress,
                absolute_deadline_at=str(existing_populate_monitor.get("deadline_at") or ""),
            )
            job_completed_at = _utc_now()
            refreshed = _validate_completed_passive_populate_job_checkpoint(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=_SOPERATOR_NAMESPACE,
                existing=_mapping(phase.get("passive_slot_populate_job")),
                manifest=completion_validation_manifest,
                slot=slots.passive_slot,
                pvc=slots.passive_pvc,
                image=populate_image,
                completed_at=job_completed_at,
                target_ref=target_ref,
                expected_pvc_uid=str(
                    _mapping(phase.get("passive_slot_populate_job")).get("pvc_uid") or ""
                ),
            )
            phase["job_completed_at"] = job_completed_at
            if checkpoint_writer is not None:
                checkpoint_writer()
        else:
            refreshed = external_switch_recovery_snapshot
            phase["passive_slot_populate_job"]["action"] = "validated-completed"
        migration_lines.extend(
            _ensure_jail_gpu_post_population_gate(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=values,
                populate_image=populate_image,
                runner_image_lock=gpu_post_population_runner_lock,
                passive_pvc=slots.passive_pvc,
                populate_job=_mapping(phase.get("passive_slot_populate_job")),
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        migration_lines.extend(
            _ensure_gpu_worker_jail_release_gate(
                phase=phase,
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=values,
                checkpoint_writer=checkpoint_writer,
                gate_key=_GPU_PRE_ACTIVATION_FLEET_GATE_KEY,
            )
        )
        if legacy_migration_entries:
            _ensure_persistent_migration_writer_hold_intact_after_copy(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                state=writer_hold_state,
                boundary="passive rootfs population completion",
                checkpoint_writer=checkpoint_writer,
            )
        if legacy_migration_entries:
            phase["login_service_ready_before_switch"] = {
                "status": "skipped",
                "reason": "login consumers are held during one-time persistent mount migration",
            }
        else:
            phase["login_service_ready_before_switch"] = wait_for_login_service_ready_endpoints(
                command_runner,
                namespace=_SOPERATOR_NAMESPACE,
                target_ref=target_ref,
                kube_context=kube_context,
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
        switched_values = switch_active_passive_jail_rootfs_values(values)
        if legacy_migration_entries:
            switched_values["maintenance"] = _persistent_migration_original_maintenance(
                writer_hold_state
            )
        switch_boundary_manifest = active_passive_populate_jail_job_manifest(
            namespace=_SOPERATOR_NAMESPACE,
            target_ref=target_ref,
            image=populate_image,
            passive_slot=slots.passive_slot,
            passive_pvc=slots.passive_pvc,
            image_pull_policy=str(
                _mapping(values.get("populateJail")).get("imagePullPolicy") or "IfNotPresent"
            ),
            scheduling=job_scheduling,
        )
        refreshed = _validate_completed_passive_populate_job_checkpoint(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            existing=_mapping(phase.get("passive_slot_populate_job")),
            manifest=switch_boundary_manifest,
            slot=slots.passive_slot,
            pvc=slots.passive_pvc,
            image=populate_image,
            completed_at=phase.get("job_completed_at"),
            target_ref=target_ref,
            expected_pvc_uid=str(
                _mapping(phase.get("passive_slot_populate_job")).get("pvc_uid") or ""
            ),
        )
        if legacy_in_place_entries:
            _ensure_in_place_persistent_mount_adoption_gate(
                phase=phase,
                values=values,
                legacy_jail_pvc=legacy_jail_pvc,
                slot_pvcs=(slots.active_pvc, slots.passive_pvc),
                entries=legacy_in_place_entries,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
                scheduling=job_scheduling,
                stage="ready-before-switch",
                checkpoint_writer=checkpoint_writer,
            )
        if open_metrics_handoff is not None:
            _record_jail_open_metrics_switch_intent(
                state=open_metrics_handoff,
                checkpoint_writer=checkpoint_writer,
            )
        _require_live_rolling_sconfig_fence(boundary="active-slot Helm switch")
        migration_lines.extend(
            _revalidate_gpu_pre_activation_fleet_before_switch(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=values,
                checkpoint_writer=checkpoint_writer,
            )
        )
        switched_slots = active_passive_jail_rootfs_slots(switched_values)
        _checkpoint_legacy_rootfs_jail_boundary_intent(
            phase=rolling_phase,
            boundary_id="active-slot-switch",
            expected_rootfs_pvc=_pvc_volume_source_claim_name(
                switched_values,
                source_name="jail",
            ),
            expected_rootfs_volume_source=switched_slots.active_volume_source,
            expected_maintenance=str(switched_values.get("maintenance") or "none").strip(),
            expected_login_jail_submounts_fingerprint=(
                _legacy_rootfs_expected_login_jail_submounts_fingerprint(switched_values)
            ),
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        migration_lines.extend(
            _helm_upgrade_target_soperator_with_jail_login_session_policy(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
                expected_version=target_version,
                boundary="active-slot-switch",
                login_session_policy=login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                wait=False,
                disable_open_metrics_for_legacy_clients=(
                    True if open_metrics_handoff is not None else None
                ),
                writer_hold_state=(writer_hold_state if legacy_migration_entries else None),
                checkpoint_writer=checkpoint_writer,
            )
        )
        phase["consumer_switch_applied_at"] = _utc_now()
        phase["rollback_slot"] = "legacy-rootfs" if legacy_active_rootfs else slots.active_slot
        phase["active_slot"] = slots.passive_slot
        if legacy_migration_entries:
            migration_lines.extend(
                _restore_persistent_migration_writers(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    state=writer_hold_state,
                )
            )
            phase["persistent_migration_writer_hold"] = dict(writer_hold_state)
            maintenance_restored = True
            if checkpoint_writer is not None:
                checkpoint_writer()

        expected_jail_alias_pvc = _pvc_volume_source_claim_name(
            switched_values,
            source_name="jail",
        )
        if not expected_jail_alias_pvc:
            raise RuntimeError(
                "Jail Upgrade switched values must define exactly one PVC-backed "
                "volumeSources[name=jail] alias before consumer handoff."
            )
        live_cluster = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "slurmcluster",
                target_ref,
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        if not _mapping(live_cluster.get("metadata")):
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade could not verify the target SlurmCluster after applying "
                "the active-slot consumer switch."
            )
        if open_metrics_handoff is not None:
            _verify_jail_open_metrics_compatibility_active(
                state=open_metrics_handoff,
                resource=live_cluster,
                checkpoint_writer=checkpoint_writer,
            )
        observed_jail_alias_pvc = _pvc_volume_source_claim_name(
            _mapping(live_cluster.get("spec")),
            source_name="jail",
        )
        alias_reconciliation = {
            "status": (
                "verified" if observed_jail_alias_pvc == expected_jail_alias_pvc else "pending"
            ),
            "expected_pvc": expected_jail_alias_pvc,
            "observed_pvc": observed_jail_alias_pvc,
            "checked_at": _utc_now(),
        }
        phase["jail_volume_source_alias_reconciliation"] = alias_reconciliation
        if checkpoint_writer is not None:
            checkpoint_writer()
        if observed_jail_alias_pvc != expected_jail_alias_pvc:
            raise SoperatorMigrationPhasePending(
                "Jail Upgrade applied switched Helm values, but the live SlurmCluster "
                "jail volume-source alias does not reference the active slot PVC "
                f"{expected_jail_alias_pvc}."
            )

        bridge_active = _legacy_rootfs_target_compatibility_is_active(rolling_phase)
        bridge_released = (
            str(
                _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge")).get("status") or ""
            ).strip()
            == "released"
        )
        if bridge_active:
            _rebind_legacy_rootfs_target_compatibility_after_jail_helm(
                phase=rolling_phase,
                consumer_switch_applied_at=str(phase.get("consumer_switch_applied_at") or ""),
                boundary_id="active-slot-switch",
                expected_rootfs_pvc=expected_jail_alias_pvc,
                expected_rootfs_volume_source=active_passive_jail_rootfs_slots(
                    switched_values
                ).active_volume_source,
                expected_maintenance=str(switched_values.get("maintenance") or "none").strip(),
                expected_login_jail_submounts_fingerprint=(
                    _legacy_rootfs_expected_login_jail_submounts_fingerprint(switched_values)
                ),
                values=switched_values,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        migration_lines.extend(_shrink_session_free_login_holds_before_ownership())
        handoff_mutation, handoff_lines = _ensure_ownership_handoff(switched_values)
        mutation_performed = mutation_performed or handoff_mutation
        migration_lines.extend(handoff_lines)
        migration_lines.extend(
            _release_jail_login_hold_before_full_rollout(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                rootfs_pvc=expected_jail_alias_pvc,
                checkpoint_writer=checkpoint_writer,
            )
        )
        _wait_for_jail_target_availability_or_defer_protected_login(
            checkpoint=checkpoint,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            checkpoint_writer=checkpoint_writer,
        )
        alias_consumer_checks = _verify_target_jail_alias_consumers(
            command_runner=command_runner,
            kube_context=kube_context,
            slurmcluster=live_cluster,
            rootfs_pvc=expected_jail_alias_pvc,
            wait_for_rollout=True,
            legacy_rootfs_bridge_state=_mapping(
                rolling_phase.get("legacy_rootfs_slurm_config_bridge")
            ),
        )
        alias_consumer_verification = {
            "status": (
                "pending"
                if any(check.get("status") != "verified" for check in alias_consumer_checks)
                else "verified"
            ),
            "expected_pvc": expected_jail_alias_pvc,
            "checks": alias_consumer_checks,
            "sconfig_fenced": bridge_active,
            "checked_at": _utc_now(),
        }
        phase["jail_alias_consumer_verification"] = alias_consumer_verification
        if alias_consumer_verification["status"] != "verified":
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise SoperatorMigrationPhasePending(
                _jail_alias_consumer_pending_reason(alias_consumer_checks)
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
        phase["login_service_ready_after_switch"] = _login_ready_after_switch()
        if checkpoint_writer is not None:
            checkpoint_writer()
        handoff_mount_status = jail_persistent_mount_status(switched_values)
        handoff_slots = active_passive_jail_rootfs_slots(switched_values)
        handoff_verification = {
            "status": "checking",
            "active_slot": handoff_slots.active_slot,
            "active_volume_source": handoff_slots.active_volume_source,
            "active_pvc": handoff_slots.active_pvc,
            "rollback_slot": phase["rollback_slot"],
            "worker_nodesets": list(_target_worker_nodeset_names(switched_values)),
            "persistent_mounts": [mount.as_payload() for mount in handoff_mount_status.mounts],
            "persistent_mount_status": handoff_mount_status.status,
            "persistent_mount_reason": handoff_mount_status.reason,
            "verification_revision": _ROOTFS_HANDOFF_VERIFICATION_REVISION,
        }
        phase["rootfs_handoff_verification"] = handoff_verification
        if checkpoint_writer is not None:
            checkpoint_writer()
        try:
            migration_lines.extend(
                _repair_gpu_driver_jail_init_loader_for_target_workers(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    target_ref=target_ref,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            migration_lines.extend(
                _rollover_orphaned_worker_pods_for_target_statefulsets(
                    phase=rolling_phase,
                    values=switched_values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            migration_lines.extend(
                _repair_gpu_driver_jail_init_loader_for_target_workers(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    target_ref=target_ref,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            migration_lines.extend(
                _repair_gpu_health_sysfs_for_target_workers(
                    checkpoint=checkpoint,
                    populate_phase=phase,
                    rolling_phase=rolling_phase,
                    values=switched_values,
                    expected_version=target_version,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    login_session_policy=login_session_policy,
                    login_session_drain_timeout_seconds=(login_session_drain_timeout_seconds),
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            _wait_for_target_worker_nodesets_ready(
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
                timeout_seconds=1800,
            )
            migration_lines.extend(
                _rollover_orphaned_worker_pods_for_target_statefulsets(
                    phase=rolling_phase,
                    values=switched_values,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    mutation_guard=mutation_guard,
                )
            )
            consumer_checks = _verify_target_rootfs_handoff_consumers(
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
            )
            handoff_verification["consumer_checks"] = consumer_checks
            if any(check.get("status") != "verified" for check in consumer_checks):
                raise SoperatorMigrationPhasePending(
                    _rootfs_handoff_pending_reason(consumer_checks)
                )
            live_home_mount_checks = _live_home_mount_probe_checks(
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
                target_ref=target_ref,
                protected_login_pod_uids=_protected_login_pod_uids(),
            )
            handoff_verification["live_home_mount_checks"] = list(live_home_mount_checks)
            if _fast_verification_failed(live_home_mount_checks):
                raise SoperatorMigrationPhasePending(
                    _live_home_mount_pending_reason(live_home_mount_checks)
                )
        except SoperatorMigrationPhasePending as exc:
            handoff_verification["status"] = "pending"
            handoff_verification["reason"] = str(exc)
            phase["rootfs_handoff_verification"] = handoff_verification
            if checkpoint_writer is not None:
                checkpoint_writer()
            raise
        if bridge_active:
            handoff_verification["status"] = "consumers-verified-with-sconfig-fenced"
            handoff_verification["staged_verified_at"] = _utc_now()
        elif bridge_released:
            handoff_verification["status"] = "consumers-verified-with-sconfig-released"
            handoff_verification["released_consumers_verified_at"] = _utc_now()
        else:
            handoff_verification["status"] = "verified"
            handoff_verification["verified_at"] = _utc_now()
        phase["rootfs_handoff_verification"] = handoff_verification
        if checkpoint_writer is not None:
            checkpoint_writer()
        post_jail_smoke_lines.extend(
            _release_legacy_rootfs_sconfig_writer_after_slot_verification(
                bridge_phase=rolling_phase,
                handoff_verification=handoff_verification,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=None,
                rootfs_pvc=expected_jail_alias_pvc,
                open_metrics_handoff=open_metrics_handoff,
            )
        )
        if handoff_verification["status"] in {
            "consumers-verified-with-sconfig-fenced",
            "consumers-verified-with-sconfig-released",
        }:
            handoff_verification["status"] = "verified"
            handoff_verification["sconfig_release"] = dict(
                _mapping(
                    _mapping(rolling_phase.get("legacy_rootfs_slurm_config_bridge")).get(
                        "target_writer_release"
                    )
                )
            )
            handoff_verification["verified_at"] = _utc_now()
            phase["rootfs_handoff_verification"] = handoff_verification
            if checkpoint_writer is not None:
                checkpoint_writer()
        _kubectl_rollout_status(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="deployment/soperator-manager",
            timeout="15m",
        )
        if open_metrics_handoff is not None:
            restored_mutation, restored_lines = _restore_jail_open_metrics_before_release_checks(
                phase=phase,
                state=open_metrics_handoff,
                switched_values=switched_values,
                target_version=target_version,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
                login_session_policy=login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                checkpoint_writer=checkpoint_writer,
            )
            mutation_performed |= restored_mutation
            post_jail_smoke_lines.extend(restored_lines)
        post_jail_smoke_lines.extend(
            _repair_gpu_worker_topology_before_jail_smoke(
                checkpoint=checkpoint,
                populate_phase=phase,
                rolling_phase=rolling_phase,
                target_ref=target_ref,
                values=switched_values,
                expected_version=target_version,
                command_runner=command_runner,
                kube_context=kube_context,
                login_session_policy=login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                checkpoint_writer=checkpoint_writer,
                mutation_guard=mutation_guard,
            )
        )
        post_jail_smoke_lines.extend(
            _ensure_gpu_worker_jail_release_gate(
                phase=phase,
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                values=switched_values,
                checkpoint_writer=checkpoint_writer,
                gate_key="post_jail_gpu_workload_release_gate",
            )
        )
        post_jail_smoke_lines.extend(
            _ensure_jail_gpu_post_activation_gate(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                values=switched_values,
                checkpoint_writer=checkpoint_writer,
                replacement_phase=rolling_phase,
                mutation_guard=mutation_guard,
            )
        )
        post_jail_smoke_lines.extend(
            _ensure_post_jail_slurm_pre_release_checks(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        if slurm_pause_records:
            phase["slurm_partition_restore_status"] = "deferred"
            phase["slurm_partition_restore_deferred_reason"] = (
                "Jail Upgrade completed, but the exact pre-upgrade partition records are "
                "restored only after final singleton health, durable-action drain, voluntary "
                "login handoff, worker retirement, and bridge cleanup."
            )
        post_jail_smoke_lines.extend(
            _ensure_post_jail_slurm_smoke(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        if (
            _compute_migration_contract(payload, target_ref).get("mode")
            == COMPUTE_MIGRATION_MODE_IN_PLACE
        ):
            post_jail_smoke_lines.extend(
                _ensure_in_place_target_manager_paused(
                    phase=rolling_phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            post_jail_smoke_lines.extend(
                _ensure_in_place_target_controller_command_gate(
                    checkpoint=checkpoint,
                    phase=rolling_phase,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
        if checkpoint_writer is not None:
            checkpoint_writer()
    except (Exception, KeyboardInterrupt):
        _restore_after_refresh_failure()
        raise
    result = completed_populate_jail_refresh_result(
        mode=plan.mode,
        reason=plan.reason,
        snapshot=refreshed,
        maintenance_restored=maintenance_restored,
    )
    phase["result"] = result.as_payload()
    phase["completed_at"] = _utc_now()
    execution["status"] = "completed"
    execution["completed_at"] = phase["completed_at"]
    if legacy_migration_entries:
        phase["persistent_migration_failure_boundary"] = {
            "status": "released",
            "released_at": _utc_now(),
            "reason": ("maintenance restored and rootfs handoff plus post-Jail Slurm smoke passed"),
        }
    if checkpoint_writer is not None:
        checkpoint_writer()
    return mutation_performed, [
        *topology_lines,
        *quiet_lines,
        *migration_lines,
        "Slurm partitions remain paused after Jail Upgrade until final gates pass; exact "
        "records restore before destructive bridge cleanup.",
        *post_jail_smoke_lines,
        (
            "Jail rootfs passive slot populated and consumers switched "
            f"from {phase['rollback_slot']} to {phase['active_slot']}."
        ),
    ]


def _target_mk8s_gpu_validation_specs(
    payload: Mapping[str, Any],
    *,
    target_ref: str,
) -> list[dict[str, Any]]:
    normalized_target = normalize_component_token(target_ref) or target_ref
    return [
        dict(spec)
        for spec in mk8s_gpu_validation_specs(payload)
        if normalize_component_token(spec.get("target_ref")) == normalized_target
    ]


def _external_upgrade_artifact_identity(
    *,
    target_ref: str,
    payload_or_config: Any = None,
    checkpoint: Mapping[str, Any] | None = None,
) -> Any:
    checkpoint_map = checkpoint if isinstance(checkpoint, Mapping) else {}
    cluster_id = str(checkpoint_map.get("cluster_id", "") or "").strip()
    cluster_name = str(checkpoint_map.get("cluster_name", "") or "").strip()
    kube_context = str(checkpoint_map.get("kube_context", "") or "").strip()
    if cluster_id or cluster_name or kube_context:
        return soperator_cluster_artifact_identity(
            cluster_id=cluster_id,
            cluster_name=cluster_name,
            target_ref=target_ref,
            kube_context=kube_context,
        )
    return soperator_cluster_artifact_identity_from_payload(
        payload_or_config,
        target_ref=target_ref,
    )


