def _target_soperator_cluster_validation_specs(
    payload: Mapping[str, Any],
    *,
    target_ref: str,
    kube_context: str,
    checkpoint: Mapping[str, Any],
) -> list[dict[str, Any]]:
    normalized_target = normalize_component_token(target_ref) or target_ref
    specs: list[dict[str, Any]] = []
    for spec in soperator_cluster_validation_specs(payload):
        if normalize_component_token(spec.get("target_ref")) != normalized_target:
            continue
        item = dict(spec)
        item["kube_context"] = kube_context
        if not str(item.get("cluster_name", "") or "").strip():
            item["cluster_name"] = target_ref
        item["check_old_source_flux"] = True
        active_jail_storage = _checkpointed_active_jail_storage(checkpoint)
        if active_jail_storage:
            jail_storage = dict(_mapping(item.get("jail_storage")))
            jail_storage.update(active_jail_storage)
            item["jail_storage"] = jail_storage
        specs.append(item)
    return specs


def _checkpointed_active_jail_storage(
    checkpoint: Mapping[str, Any],
) -> dict[str, str]:
    """Return the accepted active Jail slot as a validation storage contract."""

    populate = _accepted_populate_jail_phase_state(checkpoint)
    handoff = _mapping(populate.get("rootfs_handoff_verification"))
    active_pvc = str(handoff.get("active_pvc") or "").strip()
    active_volume_source = str(handoff.get("active_volume_source") or "").strip()
    if (
        not str(populate.get("completed_at") or "").strip()
        or str(handoff.get("status") or "").strip() not in {"verified", "passed"}
        or not str(handoff.get("active_slot") or "").strip()
        or not active_pvc
        or not active_volume_source
    ):
        return {}
    pv_name = (
        active_pvc[: -len("-pvc")] + "-pv"
        if active_pvc.endswith("-pvc")
        else _chart_mashed_kebab(f"{active_volume_source} pv")
    )
    if not pv_name:
        return {}
    return {
        "pvc_name": active_pvc,
        "pv_name": pv_name,
    }


def _migration_validation_command_runner(
    command_runner: SoperatorMigrationCommandRunner,
) -> Callable[..., SoperatorValidationCommandResult]:
    def _run(
        args: Sequence[str],
        *,
        input_text: str | None = None,
        timeout_seconds: int = 300,
        check: bool = True,
    ) -> SoperatorValidationCommandResult:
        result = command_runner(
            args,
            input_text=input_text,
            timeout_seconds=timeout_seconds,
            check=check,
        )
        return SoperatorValidationCommandResult(
            args=result.args,
            returncode=result.returncode,
            stdout=result.stdout,
            stderr=result.stderr,
        )

    return _run


def _migration_safety_baseline_from_checkpoint(
    checkpoint: Mapping[str, Any],
) -> ProtectedCustomerState | None:
    safety = checkpoint.get("upgrade_safety")
    safety_map = safety if isinstance(safety, Mapping) else {}
    protected = safety_map.get("protected_customer_state")
    protected_map = protected if isinstance(protected, Mapping) else {}
    before = protected_map.get("before")
    return protected_customer_state_from_payload(before if isinstance(before, Mapping) else None)


def _capture_external_upgrade_protected_state(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
) -> ProtectedCustomerState:
    state = capture_protected_customer_state(
        command_runner=command_runner,
        target_ref=target_ref,
        namespace=_SOPERATOR_NAMESPACE,
        kube_context=kube_context,
        source_payload=payload,
    )
    if not state.complete:
        details = "; ".join(state.warnings) or "unknown protected-state capture failure"
        raise RuntimeError(
            "External Soperator upgrade protected-state capture is incomplete; refusing to mutate. "
            + details
        )
    return state


def _run_external_upgrade_safety_verification(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint: Mapping[str, Any],
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    approve_remediation: bool,
) -> Any:
    before_state = _migration_safety_baseline_from_checkpoint(checkpoint)
    populate_phase = _accepted_populate_jail_phase_state(checkpoint)
    open_metrics_handoff = _mapping(populate_phase.get("slurm_open_metrics_handoff"))
    bridge = _mapping(checkpoint.get("controller_bridge"))
    authority = _mapping(bridge.get("authority"))
    manager_pause = _mapping(bridge.get("in_place_target_manager_pause"))
    source_configuration = _mapping(bridge.get("source_configuration"))
    client_propagation = _mapping(source_configuration.get("client_propagation"))
    paused_partitions = {
        str(item.get("partition", "") or "").strip()
        for item in _sequence_of_mappings(bridge.get("partition_pause"))
        if str(item.get("applied_state", "") or "").strip() == "DOWN"
    }
    reasserted_partitions = {
        str(item or "").strip()
        for item in bridge.get("partition_pause_reasserted", []) or []
        if str(item or "").strip()
    }
    transition_handoff = {
        "status": "verified",
        "stage": str(bridge.get("stage", "") or "").strip(),
        "authority_owner": str(authority.get("owner", "") or "").strip(),
        "manager_pause_status": str(manager_pause.get("status", "") or "").strip(),
        "client_propagation_status": str(client_propagation.get("status", "") or "").strip(),
        "partition_pause_verified": bool(
            paused_partitions
            and reasserted_partitions <= paused_partitions
            and str(bridge.get("partition_pause_revalidated_at", "") or "").strip()
        ),
    }
    result = run_post_upgrade_fast_verification(
        command_runner=command_runner,
        target_ref=target_ref,
        namespace=_SOPERATOR_NAMESPACE,
        kube_context=kube_context,
        before_state=before_state,
        source_payload=payload,
        external_cluster=True,
        external_jail_storage_handoff=populate_phase or None,
        external_transition_handoff=transition_handoff,
        external_open_metrics_handoff=open_metrics_handoff or None,
        remediation_approved=approve_remediation,
    )
    return result


def external_soperator_upgrade_protected_comparison_passed(
    *,
    config_path: Path,
    target_ref: str,
    payload_or_config: Any = None,
) -> bool:
    checkpoint = _load_checkpoint(
        soperator_migration_checkpoint_path(
            config_path,
            target_ref,
            payload_or_config=payload_or_config,
        )
    )
    if checkpoint is None:
        return False
    return _checkpoint_protected_comparison_passed(checkpoint)


def _checkpoint_protected_comparison_passed(checkpoint: Mapping[str, Any]) -> bool:
    safety = checkpoint.get("upgrade_safety")
    safety_map = safety if isinstance(safety, Mapping) else {}
    verification = safety_map.get("post_upgrade_verification")
    verification_map = verification if isinstance(verification, Mapping) else {}
    comparison = verification_map.get("comparison")
    comparison_map = comparison if isinstance(comparison, Mapping) else {}
    protected = safety_map.get("protected_customer_state")
    protected_map = protected if isinstance(protected, Mapping) else {}
    return (
        bool(verification_map.get("passed"))
        and int(comparison_map.get("blocked_count") or 0) == 0
        and str(protected_map.get("after_hash", "") or "").strip() != ""
    )


def _failed_safety_check_names(safety_result: Any) -> list[str]:
    return [
        str(check.get("name") or "check")
        for check in safety_result.checks
        if isinstance(check, Mapping) and check.get("status") == "failed"
    ]


def _store_external_upgrade_safety_verification(
    *,
    checkpoint: dict[str, Any],
    safety_result: Any,
    approve_remediation: bool,
) -> None:
    checkpoint["upgrade_safety"] = update_safety_payload_with_verification(
        checkpoint.get("upgrade_safety")
        if isinstance(checkpoint.get("upgrade_safety"), Mapping)
        else None,
        safety_result,
        remediation_approved=approve_remediation,
    )
    phase = _phase_state(checkpoint, "validation-and-rollback-hold")
    phase["shared_safety_verification"] = safety_result.as_payload()


def _ensure_external_upgrade_safety_verified(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    approve_remediation: bool,
) -> list[str]:
    if _checkpoint_protected_comparison_passed(checkpoint):
        return ["Shared Soperator upgrade safety verification already passed."]
    safety_result = _run_external_upgrade_safety_verification(
        command_runner=command_runner,
        checkpoint=checkpoint,
        payload=payload,
        target_ref=target_ref,
        kube_context=kube_context,
        approve_remediation=approve_remediation,
    )
    _store_external_upgrade_safety_verification(
        checkpoint=checkpoint,
        safety_result=safety_result,
        approve_remediation=approve_remediation,
    )
    if not safety_result.passed:
        failed = _failed_safety_check_names(safety_result)
        raise SoperatorMigrationPhasePending(
            "Shared Soperator upgrade safety verification failed"
            + (": " + ", ".join(failed) if failed else ".")
        )
    return ["Shared Soperator upgrade safety verification completed: passed."]


def _run_migration_soperator_cluster_validation(
    *,
    config_path: Path,
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    phase: dict[str, Any],
    checkpoint: Mapping[str, Any],
) -> list[str]:
    validations = _target_soperator_cluster_validation_specs(
        payload,
        target_ref=target_ref,
        kube_context=kube_context,
        checkpoint=checkpoint,
    )
    phase["soperator_cluster_validation_count"] = len(validations)
    if not validations:
        phase["soperator_cluster_validations"] = []
        return [
            "Soperator cluster smoke validation skipped: no Soperator app row is configured for this target."
        ]
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    manager_pause = _mapping(rolling.get("in_place_target_manager_pause"))
    bridge_stage = str(_mapping(checkpoint.get("controller_bridge")).get("stage") or "")
    if (
        manager_pause.get("status") == "verified"
        and str(manager_pause.get("deployment_uid") or "")
        and _positive_int(manager_pause.get("original_replicas"), fallback=0) > 0
        and bridge_stage
        in {
            BridgeStage.SOURCE_HA_ACTIVE.value,
            BridgeStage.TARGET_HA_ACTIVE.value,
            BridgeStage.BRIDGE_FENCED.value,
            BridgeStage.TARGET_SINGLETON_ACTIVE.value,
        }
    ):
        pause_contract = {
            "schema": "nebius-cxcli/checkpointed-manager-pause-v1",
            "status": "verified",
            "deployment_uid": str(manager_pause.get("deployment_uid") or ""),
            "original_replicas": _positive_int(manager_pause.get("original_replicas"), fallback=0),
            "bridge_stage": bridge_stage,
        }
        for spec in validations:
            spec["checkpointed_manager_pause"] = pause_contract
    reports_dir = _migration_validation_reports_dir(
        config_path,
        target_ref=target_ref,
        payload_or_config=payload,
    )
    reports_dir.mkdir(parents=True, exist_ok=True)
    messages: list[str] = []
    try:
        reports = run_soperator_cluster_validations(
            validations,
            reports_dir=reports_dir,
            emit=messages.append,
            command_runner=_migration_validation_command_runner(command_runner),
        )
    except Exception as exc:
        phase["soperator_cluster_validations"] = [
            {
                "kind": SOPERATOR_CLUSTER_VALIDATION_KIND,
                "name": str(spec.get("name", "") or ""),
                "report_file": str(spec.get("report_file", "") or ""),
            }
            for spec in validations
        ]
        phase["soperator_cluster_validation_reports"] = [
            str(reports_dir / str(spec.get("report_file") or "deploy-smoke-report.json"))
            for spec in validations
        ]
        raise SoperatorMigrationPhasePending(
            "Soperator cluster smoke validation failed during validation-and-rollback-hold: "
            + str(exc)
        ) from exc
    phase["soperator_cluster_validations"] = [
        {
            "kind": SOPERATOR_CLUSTER_VALIDATION_KIND,
            "name": str(spec.get("name", "") or ""),
            "report_file": str(spec.get("report_file", "") or ""),
        }
        for spec in validations
    ]
    phase["soperator_cluster_validation_reports"] = [str(path) for path in reports]
    return [
        *messages,
        f"Soperator cluster smoke validation completed: {len(reports)}/{len(validations)} report(s) written.",
    ]


def _write_validation_only_deploy_report(
    *,
    payload: Mapping[str, Any],
    target_ref: str,
    validations: Sequence[Mapping[str, Any]],
    reports_dir: Path,
) -> Path:
    report_path = reports_dir / DEPLOY_REPORT_FILENAME
    report = build_deploy_validation_report(
        validations,
        reports_dir=reports_dir,
        markdown_path=report_path,
    )
    project_id = str(
        _mapping(_mapping(payload.get("client_info")).get("nebius")).get("project_id", "") or ""
    ).strip()
    heading = f"Deploy Report: {project_id}" if project_id else "Deploy Report"
    lines = [
        f"# {heading}",
        "",
        f"- External Soperator upgrade target: `{target_ref}`",
        "",
        *validation_section_lines(report),
    ]
    report_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")
    return report_path


def _refresh_migration_deploy_report(
    *,
    config_path: Path,
    payload: Mapping[str, Any],
    target_ref: str,
    validations: Sequence[Mapping[str, Any]],
    reports_dir: Path,
) -> Path:
    try:
        paths = resolve_project_paths(config_path)
    except ValueError:
        return _write_validation_only_deploy_report(
            payload=payload,
            target_ref=target_ref,
            validations=validations,
            reports_dir=reports_dir,
        )
    artifacts = write_inventory(payload, paths, validations=validations)
    return artifacts.markdown


def _run_migration_mk8s_gpu_validations(
    *,
    config_path: Path,
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    phase: dict[str, Any],
) -> list[str]:
    validations = _target_mk8s_gpu_validation_specs(payload, target_ref=target_ref)
    phase["mk8s_gpu_validation_count"] = len(validations)
    if not validations:
        phase["mk8s_gpu_validations"] = []
        return ["MK8s GPU validations skipped: no enabled target-scoped checks were configured."]
    reports_dir = _migration_validation_reports_dir(
        config_path,
        target_ref=target_ref,
        payload_or_config=payload,
    )
    reports_dir.mkdir(parents=True, exist_ok=True)
    clear_deploy_validation_artifacts(validations, reports_dir=reports_dir)
    messages: list[str] = []
    try:
        reports = run_mk8s_gpu_validations(
            validations,
            reports_dir=reports_dir,
            extra_env={
                "KUBECTL_CONTEXT": kube_context,
                "HELM_KUBECONTEXT": kube_context,
            },
            emit=messages.append,
        )
    except Exception:
        report_path = _refresh_migration_deploy_report(
            config_path=config_path,
            payload=payload,
            target_ref=target_ref,
            validations=validations,
            reports_dir=reports_dir,
        )
        phase["deploy_report"] = str(report_path)
        raise
    report_path = _refresh_migration_deploy_report(
        config_path=config_path,
        payload=payload,
        target_ref=target_ref,
        validations=validations,
        reports_dir=reports_dir,
    )
    phase["mk8s_gpu_validations"] = [
        {
            "kind": str(spec.get("kind", "") or ""),
            "name": str(spec.get("name", "") or ""),
            "report_file": str(spec.get("report_file", "") or ""),
        }
        for spec in validations
    ]
    phase["mk8s_gpu_validation_reports"] = [str(path) for path in reports]
    phase["deploy_report"] = str(report_path)
    return [
        *messages,
        f"MK8s GPU validations completed: {len(reports)}/{len(validations)} report(s) written.",
        "External Soperator upgrade report will include the MK8s GPU validation rollup.",
        f"Deploy-compatible validation report refreshed: {report_path}",
    ]


def _validation_hold_revision(checkpoint: Mapping[str, Any]) -> int:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("validation-and-rollback-hold"))
    return _positive_int(phase.get("validation_contract_revision"), fallback=0)


def _execute_validation_hold_phase(
    *,
    config_path: Path,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    target_version: str,
    command_runner: SoperatorMigrationCommandRunner,
    approve_remediation: bool = False,
    require_target_soperator_helm: bool = True,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, "validation-and-rollback-hold")
    _ensure_live_nodes_ready(live_snapshot)
    _kubectl_rollout_status(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="deployment/soperator-manager",
        timeout="10m",
    )
    helm_state_lines = _verify_completed_soperator_migration_helm_state(
        command_runner=command_runner,
        kube_context=kube_context,
        target_version=target_version,
        require_target_release=require_target_soperator_helm,
    )
    validation_lines = _run_migration_mk8s_gpu_validations(
        config_path=config_path,
        payload=payload,
        target_ref=target_ref,
        kube_context=kube_context,
        phase=phase,
    )
    soperator_validation_lines = _run_migration_soperator_cluster_validation(
        config_path=config_path,
        payload=payload,
        target_ref=target_ref,
        kube_context=kube_context,
        command_runner=command_runner,
        phase=phase,
        checkpoint=checkpoint,
    )
    safety_lines = _ensure_external_upgrade_safety_verified(
        command_runner=command_runner,
        checkpoint=checkpoint,
        payload=payload,
        target_ref=target_ref,
        kube_context=kube_context,
        approve_remediation=approve_remediation,
    )
    phase["validation_contract_revision"] = _VALIDATION_HOLD_REVISION
    phase["validated_at"] = _utc_now()
    return bool(phase.get("mk8s_gpu_validations") or phase.get("soperator_cluster_validations")), [
        "Validation hold passed: nodes are present and Soperator manager state is valid.",
        *helm_state_lines,
        *validation_lines,
        *soperator_validation_lines,
        *safety_lines,
    ]


def _validation_hold_needs_reconcile(
    checkpoint: Mapping[str, Any],
    completed_phases: set[str],
) -> bool:
    return (
        "validation-and-rollback-hold" in completed_phases
        and _validation_hold_revision(checkpoint) < _VALIDATION_HOLD_REVISION
    )


def _source_worker_group_retirement_evidence(
    *,
    group_name: str,
    source_report: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    allowed_node_reason: str = "",
) -> tuple[bool, dict[str, Any]]:
    """Return exact no-allocation/no-epilog evidence for one source worker group."""

    kubernetes_nodes = _nodes_for_source_groups(
        source_report=source_report,
        source_groups=(group_name,),
    )
    if not kubernetes_nodes:
        return True, {
            "status": "clear",
            "source_nodes": [],
            "slurm_nodes": [],
            "active_job_ids": [],
            "node_states": {},
            "checked_at": _utc_now(),
            "reason": "source group has no remaining Kubernetes nodes",
        }
    alias_result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "show", "nodes"),
        check=False,
        timeout_seconds=_SLURM_FAST_PROBE_TIMEOUT_SECONDS,
    )
    if alias_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source worker retirement could not read the exact Kubernetes-to-Slurm "
            f"node aliases for {group_name}; epilog state is indeterminate: "
            + _command_detail(alias_result)
        )
    aliases = _external_upgrade_parse_slurm_node_aliases(alias_result.stdout)
    slurm_nodes = tuple(
        dict.fromkeys(str(aliases.get(node, "") or "").strip() for node in kubernetes_nodes)
    )
    unresolved_nodes = tuple(node for node in kubernetes_nodes if not aliases.get(node))
    if unresolved_nodes or not slurm_nodes or len(slurm_nodes) != len(kubernetes_nodes):
        raise SoperatorMigrationPhasePending(
            "source worker retirement could not map every remaining Kubernetes worker "
            f"in {group_name} one-to-one to an exact Slurm node; epilog state is "
            "indeterminate"
            + (": " + ", ".join(unresolved_nodes) + "." if unresolved_nodes else ".")
        )
    jobs = _external_upgrade_slurm_jobs(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=slurm_nodes,
        include_pending=False,
    )
    if jobs:
        return False, {
            "status": "busy",
            "source_nodes": list(kubernetes_nodes),
            "slurm_nodes": list(slurm_nodes),
            "active_job_ids": sorted({job.job_id for job in jobs}),
            "node_states": {},
            "checked_at": _utc_now(),
            "reason": "active Slurm allocations remain",
        }
    state_result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "show", "node", ",".join(slurm_nodes), "-o"),
        check=False,
        timeout_seconds=_SLURM_FAST_PROBE_TIMEOUT_SECONDS,
    )
    if state_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "source worker retirement could not prove post-job epilog completion for "
            f"{group_name}: {_command_detail(state_result)}."
        )
    node_states: dict[str, str] = {}
    node_reasons: dict[str, str] = {}
    for line in state_result.stdout.splitlines():
        fields = _slurm_job_control_record_fields(line)
        node_name = str(fields.get("NodeName", "") or "").strip()
        state = str(fields.get("State", "") or "").strip().upper()
        if node_name and state:
            node_states[node_name] = state
            node_reasons[node_name] = _slurm_node_reason_message(fields.get("Reason", ""))
    missing = sorted(set(slurm_nodes).difference(node_states))
    uncleared_states = {
        name: state
        for name, state in node_states.items()
        if "IDLE" not in set(state.replace("~", "+").split("+"))
        or any(
            token in set(state.replace("~", "+").split("+"))
            for token in {"ALLOCATED", "ALLOC", "COMPLETING", "MIXED", "CONFIGURING"}
        )
    }
    uncleared_reasons = {
        name: reason
        for name, reason in node_reasons.items()
        if reason.strip().lower() not in {"", "none", "(null)"} and reason != allowed_node_reason
    }
    clear = not missing and not uncleared_states and not uncleared_reasons
    return clear, {
        "status": "clear" if clear else "epilog-pending",
        "source_nodes": list(kubernetes_nodes),
        "slurm_nodes": list(slurm_nodes),
        "active_job_ids": [],
        "node_states": dict(sorted(node_states.items())),
        "node_reasons": dict(sorted(node_reasons.items())),
        "checked_at": _utc_now(),
        "reason": (
            "no active allocations and no Slurm node is completing"
            if clear
            else "Slurm node state or reason does not prove an idle post-epilog boundary"
        ),
        "missing_state_nodes": missing,
        "uncleared_state_nodes": dict(sorted(uncleared_states.items())),
        "uncleared_reason_nodes": dict(sorted(uncleared_reasons.items())),
    }


def _in_place_group_drain_reason(checkpoint: Mapping[str, Any], group_id: str) -> str:
    fingerprint = str(checkpoint.get("campaign_fingerprint", "") or "").strip()
    return f"cxcli-in-place-{fingerprint[:12]}-{normalize_component_token(group_id)[:32]}"


def _slurm_node_reason_message(value: Any) -> str:
    """Remove only Slurm's display-only reason annotations."""

    without_audit = re.sub(
        r"\s+\[[^\[\]@\s]+@\d{4}-\d{2}-\d{2}T[^\[\]]+\]\s*$",
        "",
        str(value or "").strip(),
    )
    return re.sub(r"\s+:\s+Not responding\s*$", "", without_audit)


def _selector_matches_labels(selector: Mapping[str, Any], labels: Mapping[str, Any]) -> bool:
    if any(
        str(labels.get(key, "")) != str(value)
        for key, value in _mapping(selector.get("matchLabels")).items()
    ):
        return False
    for expression in _sequence_of_mappings(selector.get("matchExpressions")):
        key = str(expression.get("key", "") or "")
        operator = str(expression.get("operator", "") or "")
        values = {str(value) for value in expression.get("values", []) or []}
        observed = str(labels.get(key, "") or "")
        if operator == "In" and observed not in values:
            return False
        if operator == "NotIn" and observed in values:
            return False
        if operator == "Exists" and key not in labels:
            return False
        if operator == "DoesNotExist" and key in labels:
            return False
    return True


def _require_in_place_kubernetes_workload_clear(
    *,
    group_name: str,
    kubernetes_nodes: Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> Mapping[str, Any]:
    node_names = set(kubernetes_nodes)
    if not node_names:
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} has no exact Kubernetes node membership."
        )
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "pods",
            "--all-namespaces",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    evictable: list[Mapping[str, Any]] = []
    unexpected: list[str] = []
    local_state: list[str] = []
    for pod in _sequence_of_mappings(pods_payload.get("items")):
        metadata = _mapping(pod.get("metadata"))
        spec = _mapping(pod.get("spec"))
        status = _mapping(pod.get("status"))
        if str(spec.get("nodeName", "") or "") not in node_names:
            continue
        namespace = str(metadata.get("namespace", "") or "default")
        name = str(metadata.get("name", "") or "unknown")
        owners = _sequence_of_mappings(metadata.get("ownerReferences"))
        owner_contracts = {
            (
                str(owner.get("kind", "") or ""),
                str(owner.get("name", "") or ""),
            )
            for owner in owners
        }
        # Terminal validation Jobs carry hostPath probes but no longer participate
        # in eviction.  Node-owned device-plugin Pods have the same lifecycle as
        # DaemonSets and disappear with the provider node replacement.
        if str(status.get("phase", "") or "") in {"Succeeded", "Failed"} or any(
            kind in {"DaemonSet", "Node"} for kind, _name in owner_contracts
        ):
            continue
        evictable.append(pod)
        controlled_replica = any(kind == "ReplicaSet" for kind, _name in owner_contracts)
        if namespace != _SOPERATOR_NAMESPACE and not controlled_replica:
            unexpected.append(f"{namespace}/{name}")
        expected_worker_runtime = namespace == _SOPERATOR_NAMESPACE and any(
            kind == "StatefulSet" and owner_name == "worker" for kind, owner_name in owner_contracts
        )
        if not expected_worker_runtime and any(
            "hostPath" in _mapping(volume) for volume in _sequence_of_mappings(spec.get("volumes"))
        ):
            local_state.append(f"{namespace}/{name}")
    if unexpected or local_state:
        details: list[str] = []
        if unexpected:
            details.append("unexpected Pods=" + ",".join(sorted(unexpected)))
        if local_state:
            details.append("hostPath state=" + ",".join(sorted(local_state)))
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} is not eligible for a finite provider drain timeout: "
            + "; ".join(details)
            + "."
        )
    pdb_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "poddisruptionbudgets.policy",
            "--all-namespaces",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    blockers: list[str] = []
    for pdb in _sequence_of_mappings(pdb_payload.get("items")):
        metadata = _mapping(pdb.get("metadata"))
        namespace = str(metadata.get("namespace", "") or "default")
        if _nonnegative_int(_mapping(pdb.get("status")).get("disruptionsAllowed"), fallback=0) > 0:
            continue
        selector = _mapping(_mapping(pdb.get("spec")).get("selector"))
        if any(
            str(_mapping(pod.get("metadata")).get("namespace", "") or "default") == namespace
            and _selector_matches_labels(
                selector,
                _mapping(_mapping(pod.get("metadata")).get("labels")),
            )
            for pod in evictable
        ):
            blockers.append(f"{namespace}/{metadata.get('name') or 'unknown'}")
    if blockers:
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} has PodDisruptionBudget blockers with zero "
            "disruptions allowed: " + ", ".join(sorted(blockers)) + "."
        )
    return pods_payload


def _in_place_worker_guarded_affinity(
    *,
    original_affinity: Any,
    node_group_id: str,
) -> dict[str, Any]:
    """Exclude one rolling provider group without weakening existing affinity."""

    if original_affinity is None:
        affinity: dict[str, Any] = {}
    elif isinstance(original_affinity, Mapping):
        affinity = copy.deepcopy(to_plain_data(dict(original_affinity)))
    else:
        raise SoperatorMigrationPhasePending(
            "Worker provider drain guard found a non-object Pod affinity contract."
        )
    node_affinity_raw = affinity.get("nodeAffinity")
    if node_affinity_raw is None:
        node_affinity: dict[str, Any] = {}
    elif isinstance(node_affinity_raw, Mapping):
        node_affinity = copy.deepcopy(to_plain_data(dict(node_affinity_raw)))
    else:
        raise SoperatorMigrationPhasePending(
            "Worker provider drain guard found a non-object nodeAffinity contract."
        )
    required_raw = node_affinity.get("requiredDuringSchedulingIgnoredDuringExecution")
    if required_raw is None:
        required: dict[str, Any] = {"nodeSelectorTerms": [{}]}
    elif isinstance(required_raw, Mapping):
        required = copy.deepcopy(to_plain_data(dict(required_raw)))
    else:
        raise SoperatorMigrationPhasePending(
            "Worker provider drain guard found a non-object required node-affinity contract."
        )
    terms_raw = required.get("nodeSelectorTerms")
    if not isinstance(terms_raw, list) or not terms_raw:
        raise SoperatorMigrationPhasePending(
            "Worker provider drain guard cannot safely merge an empty required "
            "node-affinity term set."
        )
    guarded_terms: list[dict[str, Any]] = []
    for term_raw in terms_raw:
        if not isinstance(term_raw, Mapping):
            raise SoperatorMigrationPhasePending(
                "Worker provider drain guard found an invalid required node-affinity term."
            )
        term = copy.deepcopy(to_plain_data(dict(term_raw)))
        expressions_raw = term.get("matchExpressions", [])
        if not isinstance(expressions_raw, list):
            raise SoperatorMigrationPhasePending(
                "Worker provider drain guard found invalid node-affinity matchExpressions."
            )
        expressions = copy.deepcopy(to_plain_data(expressions_raw))
        expressions.append(
            {
                "key": "nebius.com/node-group-id",
                "operator": "NotIn",
                "values": [node_group_id],
            }
        )
        term["matchExpressions"] = expressions
        guarded_terms.append(term)
    required["nodeSelectorTerms"] = guarded_terms
    node_affinity["requiredDuringSchedulingIgnoredDuringExecution"] = required
    affinity["nodeAffinity"] = node_affinity
    return affinity


def _in_place_deployment_for_replica_set(
    replica_set: Mapping[str, Any],
) -> str:
    owners = _sequence_of_mappings(_mapping(replica_set.get("metadata")).get("ownerReferences"))
    deployments = {
        str(owner.get("name", "") or "").strip()
        for owner in owners
        if str(owner.get("kind", "") or "") == "Deployment"
        and str(owner.get("name", "") or "").strip()
    }
    if len(deployments) != 1:
        return ""
    return next(iter(deployments))


def _in_place_worker_guard_live_deployment(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    name: str,
) -> Mapping[str, Any]:
    return _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "deployment",
            name,
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )


def _in_place_deployment_max_unavailable(
    deployment: Mapping[str, Any],
    *,
    replicas: int,
) -> int:
    spec = _mapping(deployment.get("spec"))
    strategy = _mapping(spec.get("strategy"))
    rolling = _mapping(strategy.get("rollingUpdate"))
    raw = rolling.get("maxUnavailable", "25%")
    text = str(raw).strip()
    if text.endswith("%"):
        with suppress(ValueError):
            percentage = int(text[:-1])
            if percentage >= 0:
                return math.floor(replicas * percentage / 100)
        return replicas
    return _nonnegative_int(raw, fallback=replicas)


def _in_place_deployment_can_seed_outside_replica(
    deployment: Mapping[str, Any],
    *,
    replicas: int,
) -> bool:
    """Prove a guard rollout keeps at least one existing replica available."""

    spec = _mapping(deployment.get("spec"))
    strategy = _mapping(spec.get("strategy"))
    strategy_type = str(strategy.get("type") or "RollingUpdate").strip()
    status = _mapping(deployment.get("status"))
    return bool(
        replicas >= 2
        and strategy_type == "RollingUpdate"
        and _in_place_deployment_max_unavailable(deployment, replicas=replicas) < replicas
        and _nonnegative_int(status.get("availableReplicas"), fallback=0) >= replicas
    )


def _in_place_worker_guard_patch_affinity(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    deployment: Mapping[str, Any],
    affinity: Any,
    remove: bool = False,
) -> None:
    metadata = _mapping(deployment.get("metadata"))
    namespace = str(metadata.get("namespace", "") or "default")
    name = str(metadata.get("name", "") or "").strip()
    uid = str(metadata.get("uid", "") or "").strip()
    resource_version = str(metadata.get("resourceVersion", "") or "").strip()
    if not name or not uid or not resource_version:
        raise SoperatorMigrationPhasePending(
            "Worker provider drain guard requires an exact Deployment UID and resourceVersion."
        )
    patch: list[dict[str, Any]] = [
        {"op": "test", "path": "/metadata/uid", "value": uid},
        {
            "op": "test",
            "path": "/metadata/resourceVersion",
            "value": resource_version,
        },
    ]
    if remove:
        patch.append({"op": "remove", "path": "/spec/template/spec/affinity"})
    else:
        template_spec = _mapping(
            _mapping(_mapping(deployment.get("spec")).get("template")).get("spec")
        )
        patch.append(
            {
                "op": "replace" if "affinity" in template_spec else "add",
                "path": "/spec/template/spec/affinity",
                "value": to_plain_data(affinity),
            }
        )
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "patch",
            "deployment",
            name,
            "--type",
            "json",
            "-p",
            json.dumps(patch, sort_keys=True, separators=(",", ":")),
        ],
        timeout_seconds=120,
    )


def _in_place_worker_guard_wait_available(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    namespace: str,
    name: str,
) -> None:
    result = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "rollout",
            "status",
            f"deployment/{name}",
            "--timeout=10m",
        ],
        check=False,
        timeout_seconds=660,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"Worker provider drain guard did not restore an Available rollout for "
            f"{namespace}/{name}: {_command_detail(result)}."
        )


def _ensure_in_place_worker_drain_rescheduling_guard(
    *,
    group_state: dict[str, Any],
    group_id: str,
    group_name: str,
    kubernetes_nodes: Sequence[str],
    pods_payload: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Keep Deployment controllers from recreating Pods on cordoned source nodes."""

    existing_guard = group_state.get("kubernetes_drain_rescheduling_guard")
    if isinstance(existing_guard, Mapping) and existing_guard.get("status") == "restored":
        history = group_state.setdefault("kubernetes_drain_rescheduling_guard_history", [])
        if not isinstance(history, list):
            raise RuntimeError("Worker drain rescheduling guard history must be an array.")
        history.append(copy.deepcopy(to_plain_data(dict(existing_guard))))
        group_state["kubernetes_drain_rescheduling_guard"] = {}
        if checkpoint_writer is not None:
            checkpoint_writer()
    guard = group_state.setdefault("kubernetes_drain_rescheduling_guard", {})
    if not isinstance(guard, dict):
        raise RuntimeError("Worker Kubernetes drain rescheduling guard must be a mapping.")
    node_names = {str(name) for name in kubernetes_nodes if str(name)}
    entries = guard.get("deployments")
    if entries is None:
        replica_sets_payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                "replicasets.apps",
                "--all-namespaces",
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
            check=False,
        )
        deployments_payload = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                "deployments.apps",
                "--all-namespaces",
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=60,
            check=False,
        )
        replica_sets = {
            (
                str(_mapping(item.get("metadata")).get("namespace", "") or "default"),
                str(_mapping(item.get("metadata")).get("name", "") or ""),
            ): item
            for item in _sequence_of_mappings(replica_sets_payload.get("items"))
        }
        deployments = {
            (
                str(_mapping(item.get("metadata")).get("namespace", "") or "default"),
                str(_mapping(item.get("metadata")).get("name", "") or ""),
            ): item
            for item in _sequence_of_mappings(deployments_payload.get("items"))
        }
        pod_deployments: dict[tuple[str, str], tuple[str, str]] = {}
        for pod in _sequence_of_mappings(pods_payload.get("items")):
            metadata = _mapping(pod.get("metadata"))
            namespace = str(metadata.get("namespace", "") or "default")
            for owner in _sequence_of_mappings(metadata.get("ownerReferences")):
                if str(owner.get("kind", "") or "") != "ReplicaSet":
                    continue
                replica_set_name = str(owner.get("name", "") or "").strip()
                replica_set = replica_sets.get((namespace, replica_set_name), {})
                deployment_name = _in_place_deployment_for_replica_set(replica_set)
                if deployment_name:
                    pod_deployments[(namespace, str(metadata.get("name", "") or ""))] = (
                        namespace,
                        deployment_name,
                    )
        candidate_keys = {
            pod_deployments[(namespace, name)]
            for pod in _sequence_of_mappings(pods_payload.get("items"))
            if str(_mapping(pod.get("spec")).get("nodeName", "") or "") in node_names
            for namespace, name in [
                (
                    str(_mapping(pod.get("metadata")).get("namespace", "") or "default"),
                    str(_mapping(pod.get("metadata")).get("name", "") or ""),
                )
            ]
            if (namespace, name) in pod_deployments
            and str(_mapping(pod.get("status")).get("phase", "") or "")
            not in {"Succeeded", "Failed"}
        }
        prepared: list[dict[str, Any]] = []
        for namespace, name in sorted(candidate_keys):
            deployment = deployments.get((namespace, name))
            if not isinstance(deployment, Mapping):
                raise SoperatorMigrationPhasePending(
                    f"Worker provider drain guard could not resolve Deployment {namespace}/{name}."
                )
            outside_ready = [
                pod
                for pod in _sequence_of_mappings(pods_payload.get("items"))
                if pod_deployments.get(
                    (
                        str(_mapping(pod.get("metadata")).get("namespace", "") or "default"),
                        str(_mapping(pod.get("metadata")).get("name", "") or ""),
                    )
                )
                == (namespace, name)
                and str(_mapping(pod.get("spec")).get("nodeName", "") or "") not in node_names
                and _pod_is_ready(pod)
                and not _mapping(pod.get("metadata")).get("deletionTimestamp")
            ]
            replicas = _resource_replicas(deployment, default=1)
            if not _in_place_deployment_can_seed_outside_replica(
                deployment,
                replicas=replicas,
            ):
                raise SoperatorMigrationPhasePending(
                    f"Worker group {group_name} hosts Deployment {namespace}/{name}, but "
                    "it has no redundant Ready replica, or its RollingUpdate maxUnavailable "
                    "contract "
                    "cannot preserve at least one Ready replica while drain rescheduling "
                    "is fenced."
                )
            metadata = _mapping(deployment.get("metadata"))
            template_spec = _mapping(
                _mapping(_mapping(deployment.get("spec")).get("template")).get("spec")
            )
            original_present = "affinity" in template_spec
            original_affinity = to_plain_data(template_spec.get("affinity"))
            guarded_affinity = _in_place_worker_guarded_affinity(
                original_affinity=original_affinity,
                node_group_id=group_id,
            )
            prepared.append(
                {
                    "namespace": namespace,
                    "name": name,
                    "uid": str(metadata.get("uid", "") or ""),
                    "original_affinity_present": original_present,
                    "original_affinity": original_affinity,
                    "guarded_affinity": guarded_affinity,
                    "outside_ready_pod_uids": sorted(
                        str(_mapping(pod.get("metadata")).get("uid", "") or "")
                        for pod in outside_ready
                    ),
                    "initial_ready_pod_uids": sorted(
                        str(_mapping(pod.get("metadata")).get("uid", "") or "")
                        for pod in _sequence_of_mappings(pods_payload.get("items"))
                        if pod_deployments.get(
                            (
                                str(
                                    _mapping(pod.get("metadata")).get("namespace", "") or "default"
                                ),
                                str(_mapping(pod.get("metadata")).get("name", "") or ""),
                            )
                        )
                        == (namespace, name)
                        and _pod_is_ready(pod)
                        and not _mapping(pod.get("metadata")).get("deletionTimestamp")
                    ),
                    "status": "prepared",
                }
            )
        guard.update(
            {
                "status": "prepared",
                "node_group_id": group_id,
                "source_nodes": sorted(node_names),
                "deployments": prepared,
                "prepared_at": _utc_now(),
            }
        )
        entries = prepared
        if checkpoint_writer is not None:
            checkpoint_writer()
    if not isinstance(entries, list):
        raise RuntimeError("Worker drain rescheduling guard deployments must be an array.")
    if str(guard.get("node_group_id", "") or "") != group_id:
        raise RuntimeError("Worker drain rescheduling guard provider identity drifted.")
    for entry in entries:
        if not isinstance(entry, dict):
            raise RuntimeError("Worker drain rescheduling guard entry must be a mapping.")
        namespace = str(entry.get("namespace", "") or "default")
        name = str(entry.get("name", "") or "").strip()
        live = _in_place_worker_guard_live_deployment(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            name=name,
        )
        metadata = _mapping(live.get("metadata"))
        if str(metadata.get("uid", "") or "") != str(entry.get("uid", "") or ""):
            raise RuntimeError(
                f"recovery-required: worker drain guard Deployment identity changed for "
                f"{namespace}/{name}."
            )
        template_spec = _mapping(_mapping(_mapping(live.get("spec")).get("template")).get("spec"))
        observed = to_plain_data(template_spec.get("affinity"))
        guarded = to_plain_data(entry.get("guarded_affinity"))
        original = to_plain_data(entry.get("original_affinity"))
        if _stable_json(observed) == _stable_json(original):
            _in_place_worker_guard_patch_affinity(
                command_runner=command_runner,
                kube_context=kube_context,
                deployment=live,
                affinity=guarded,
            )
        elif _stable_json(observed) != _stable_json(guarded):
            raise RuntimeError(
                f"recovery-required: worker drain guard affinity drifted for {namespace}/{name}."
            )
        _in_place_worker_guard_wait_available(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            name=name,
        )
        verified = _in_place_worker_guard_live_deployment(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            name=name,
        )
        verified_affinity = to_plain_data(
            _mapping(_mapping(_mapping(verified.get("spec")).get("template")).get("spec")).get(
                "affinity"
            )
        )
        if _stable_json(verified_affinity) != _stable_json(guarded):
            raise SoperatorMigrationPhasePending(
                f"Worker drain rescheduling guard has not converged for {namespace}/{name}."
            )
        replicas = _resource_replicas(verified, default=1)
        verified_status = _mapping(verified.get("status"))
        if (
            _nonnegative_int(verified_status.get("updatedReplicas"), fallback=0) < replicas
            or _nonnegative_int(verified_status.get("availableReplicas"), fallback=0) < replicas
        ):
            raise SoperatorMigrationPhasePending(
                f"Worker drain rescheduling guard has not produced {replicas} updated and "
                f"Available outside-group replicas for {namespace}/{name}."
            )
        entry.update({"status": "guarded", "guarded_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
    guard.update({"status": "guarded", "guarded_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        f"Worker drain rescheduling guard fenced {len(entries)} Deployment(s) from "
        f"provider group {group_name}."
    ]


def _restore_in_place_worker_drain_rescheduling_guard(
    *,
    group_state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    guard = group_state.get("kubernetes_drain_rescheduling_guard")
    if not isinstance(guard, dict) or not guard:
        return []
    if guard.get("status") == "restored":
        return ["Worker drain rescheduling guard restore reused from the checkpoint."]
    entries = guard.get("deployments")
    if not isinstance(entries, list):
        raise RuntimeError("Worker drain rescheduling guard deployments must be an array.")
    for entry in entries:
        if not isinstance(entry, dict):
            raise RuntimeError("Worker drain rescheduling guard entry must be a mapping.")
        namespace = str(entry.get("namespace", "") or "default")
        name = str(entry.get("name", "") or "").strip()
        live = _in_place_worker_guard_live_deployment(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            name=name,
        )
        metadata = _mapping(live.get("metadata"))
        if str(metadata.get("uid", "") or "") != str(entry.get("uid", "") or ""):
            raise RuntimeError(
                f"recovery-required: guarded Deployment identity changed for {namespace}/{name}."
            )
        template_spec = _mapping(_mapping(_mapping(live.get("spec")).get("template")).get("spec"))
        observed_present = "affinity" in template_spec
        observed = to_plain_data(template_spec.get("affinity"))
        original_present = bool(entry.get("original_affinity_present"))
        original = to_plain_data(entry.get("original_affinity"))
        guarded = to_plain_data(entry.get("guarded_affinity"))
        original_matches = observed_present == original_present and (
            not original_present or _stable_json(observed) == _stable_json(original)
        )
        if not original_matches:
            if _stable_json(observed) != _stable_json(guarded):
                raise RuntimeError(
                    f"recovery-required: guarded Deployment affinity drifted before restore "
                    f"for {namespace}/{name}."
                )
            _in_place_worker_guard_patch_affinity(
                command_runner=command_runner,
                kube_context=kube_context,
                deployment=live,
                affinity=original,
                remove=not original_present,
            )
        _in_place_worker_guard_wait_available(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            name=name,
        )
        verified = _in_place_worker_guard_live_deployment(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            name=name,
        )
        verified_spec = _mapping(
            _mapping(_mapping(verified.get("spec")).get("template")).get("spec")
        )
        verified_present = "affinity" in verified_spec
        verified_affinity = to_plain_data(verified_spec.get("affinity"))
        if verified_present != original_present or (
            original_present and _stable_json(verified_affinity) != _stable_json(original)
        ):
            raise SoperatorMigrationPhasePending(
                f"Worker drain rescheduling guard restore has not converged for {namespace}/{name}."
            )
        entry.update({"status": "restored", "restored_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
    guard.update({"status": "restored", "restored_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [f"Restored {len(entries)} worker drain rescheduling Deployment guard(s)."]


def _in_place_slurm_nodes_after_drain(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    slurm_nodes: Sequence[str],
    reason: str,
) -> dict[str, Any]:
    jobs = _external_upgrade_slurm_jobs(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=slurm_nodes,
        include_pending=False,
    )
    state_result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "show", "node", ",".join(slurm_nodes), "-o"),
        check=False,
        timeout_seconds=_SLURM_FAST_PROBE_TIMEOUT_SECONDS,
    )
    if state_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "In-place worker lock could not re-read drained Slurm nodes: "
            + _command_detail(state_result)
        )
    states: dict[str, str] = {}
    reasons: dict[str, str] = {}
    for line in state_result.stdout.splitlines():
        fields = _slurm_job_control_record_fields(line)
        node = str(fields.get("NodeName", "") or "").strip()
        if node:
            states[node] = str(fields.get("State", "") or "").strip().upper()
            reasons[node] = _slurm_node_reason_message(fields.get("Reason", ""))
    expected = set(slurm_nodes)
    locked = bool(
        not jobs
        and set(states) == expected
        and all("IDLE" in state.replace("~", "+").split("+") for state in states.values())
        and all("DRAIN" in state for state in states.values())
        and all(reasons.get(node) == reason for node in expected)
    )
    return {
        "status": "locked" if locked else "blocked",
        "slurm_nodes": list(slurm_nodes),
        "active_job_ids": sorted({job.job_id for job in jobs}),
        "node_states": dict(sorted(states.items())),
        "node_reasons": dict(sorted(reasons.items())),
        "reason": reason,
        "checked_at": _utc_now(),
    }


def _apply_in_place_worker_group_lock(
    *,
    checkpoint: dict[str, Any],
    group_state: dict[str, Any],
    group_id: str,
    group_name: str,
    source_report: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    clear, evidence = _source_worker_group_retirement_evidence(
        group_name=group_name,
        source_report=source_report,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    group_state["pre_drain_clear_evidence"] = evidence
    if checkpoint_writer is not None:
        checkpoint_writer()
    if not clear:
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} remains blocked until every allocation and epilog clears."
        )
    slurm_nodes = tuple(str(node) for node in evidence.get("slurm_nodes", []) or [])
    pods_payload = _require_in_place_kubernetes_workload_clear(
        group_name=group_name,
        kubernetes_nodes=tuple(str(node) for node in evidence.get("source_nodes", []) or []),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    _ensure_in_place_worker_drain_rescheduling_guard(
        group_state=group_state,
        group_id=group_id,
        group_name=group_name,
        kubernetes_nodes=tuple(str(node) for node in evidence.get("source_nodes", []) or []),
        pods_payload=pods_payload,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    if not slurm_nodes:
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} has no exact Kubernetes-to-Slurm node mapping; "
            "no provider update was submitted."
        )
    reason = _in_place_group_drain_reason(checkpoint, group_id)
    drain_result = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=(
            "scontrol",
            "update",
            f"NodeName={','.join(slurm_nodes)}",
            "State=DRAIN",
            f"Reason={reason}",
        ),
        check=False,
        timeout_seconds=120,
    )
    if drain_result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} could not acquire its Slurm dispatch lock: "
            + _command_detail(drain_result)
        )
    group_state["slurm_drain"] = {
        "status": "applied",
        "nodes": list(slurm_nodes),
        "reason": reason,
        "applied_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    final_evidence = _in_place_slurm_nodes_after_drain(
        command_runner=command_runner,
        kube_context=kube_context,
        slurm_nodes=slurm_nodes,
        reason=reason,
    )
    group_state["final_dispatch_evidence"] = final_evidence
    if checkpoint_writer is not None:
        checkpoint_writer()
    if final_evidence.get("status") != "locked":
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} changed while its Slurm drain was acquired; "
            "it remains blocked and no provider update was submitted."
        )
    return final_evidence


def _revalidate_in_place_worker_group_lock(
    *,
    group_state: dict[str, Any],
    group_id: str,
    group_name: str,
    source_report: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> dict[str, Any]:
    """Re-prove identity, workload, epilog and owned-drain state before dispatch."""

    drain = _mapping(group_state.get("slurm_drain"))
    slurm_nodes = tuple(str(node) for node in drain.get("nodes", []) or [])
    reason = str(drain.get("reason", "") or "").strip()
    if drain.get("status") != "applied" or not slurm_nodes or not reason:
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} has no complete cxcli-owned Slurm dispatch lock."
        )
    clear, evidence = _source_worker_group_retirement_evidence(
        group_name=group_name,
        source_report=source_report,
        command_runner=command_runner,
        kube_context=kube_context,
        allowed_node_reason=reason,
    )
    group_state["pre_dispatch_clear_evidence"] = evidence
    if (
        not clear
        or tuple(str(node) for node in evidence.get("slurm_nodes", []) or []) != slurm_nodes
    ):
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} changed after its cxcli-owned Slurm drain; "
            "no provider update was submitted."
        )
    pods_payload = _require_in_place_kubernetes_workload_clear(
        group_name=group_name,
        kubernetes_nodes=tuple(str(node) for node in evidence.get("source_nodes", []) or []),
        command_runner=command_runner,
        kube_context=kube_context,
    )
    _ensure_in_place_worker_drain_rescheduling_guard(
        group_state=group_state,
        group_id=group_id,
        group_name=group_name,
        kubernetes_nodes=tuple(str(node) for node in evidence.get("source_nodes", []) or []),
        pods_payload=pods_payload,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    final_evidence = _in_place_slurm_nodes_after_drain(
        command_runner=command_runner,
        kube_context=kube_context,
        slurm_nodes=slurm_nodes,
        reason=reason,
    )
    group_state["final_dispatch_evidence"] = final_evidence
    if checkpoint_writer is not None:
        checkpoint_writer()
    if final_evidence.get("status") != "locked":
        raise SoperatorMigrationPhasePending(
            f"Worker group {group_name} changed immediately before provider dispatch; "
            "no provider update was submitted."
        )
    return final_evidence


def _restore_in_place_worker_group_lock(
    *,
    group_state: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    drain = _mapping(group_state.get("slurm_drain"))
    nodes = tuple(str(node) for node in drain.get("nodes", []) or [])
    reason = str(drain.get("reason", "") or "").strip()
    if not nodes or not reason or drain.get("status") == "restored":
        return []
    evidence = _in_place_slurm_nodes_after_drain(
        command_runner=command_runner,
        kube_context=kube_context,
        slurm_nodes=nodes,
        reason=reason,
    )
    if evidence.get("status") != "locked":
        raise SoperatorMigrationPhasePending(
            "In-place rollout will not release its Slurm drain until every replacement "
            "slurmd is registered, IDLE+DRAIN, job-free, and still carries the exact "
            "cxcli-owned reason."
        )
    owned = [
        node
        for node, observed_reason in _mapping(evidence.get("node_reasons")).items()
        if observed_reason == reason
    ]
    if owned:
        result = _kubectl_exec_login(
            command_runner=command_runner,
            kube_context=kube_context,
            args=("scontrol", "update", f"NodeName={','.join(owned)}", "State=RESUME"),
            check=False,
            timeout_seconds=120,
        )
        if result.returncode != 0:
            raise RuntimeError(
                "In-place rollout could not restore its exact cxcli-owned Slurm node drains: "
                + _command_detail(result)
            )
    drain_payload = dict(drain)
    drain_payload.update({"status": "restored", "restored_nodes": owned, "restored_at": _utc_now()})
    group_state["slurm_drain"] = drain_payload
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [f"Restored {len(owned)} cxcli-owned Slurm node drain(s)."]


def _in_place_live_node_uids(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    node_group_id: str,
    require_ready: bool = False,
) -> tuple[str, ...]:
    payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "nodes",
            "-l",
            f"nebius.com/node-group-id={node_group_id}",
            "-o",
            "json",
            "--request-timeout=20s",
        ],
        timeout_seconds=60,
        check=False,
    )
    result: list[str] = []
    for node in _sequence_of_mappings(payload.get("items")):
        metadata = _mapping(node.get("metadata"))
        uid = str(metadata.get("uid", "") or "").strip()
        if not uid:
            raise SoperatorMigrationPhasePending(
                f"Kubernetes node identity is incomplete for provider group {node_group_id}."
            )
        if require_ready and not any(
            str(condition.get("type", "") or "") == "Ready"
            and str(condition.get("status", "") or "") == "True"
            for condition in _sequence_of_mappings(_mapping(node.get("status")).get("conditions"))
        ):
            raise SoperatorMigrationPhasePending(
                f"Replacement Kubernetes node {metadata.get('name') or uid} is not Ready "
                f"for provider group {node_group_id}; its Slurm drain remains held."
            )
        result.append(uid)
    return tuple(sorted(result))


def _prepare_in_place_worker_provider_drain(
    *,
    checkpoint: Mapping[str, Any],
    group_state: dict[str, Any],
    group_id: str,
    group_name: str,
    source_nodes: Sequence[str],
    source_node_uids: Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Fence and empty every quiesced worker node before the provider update."""

    nodes = tuple(sorted({str(node).strip() for node in source_nodes if str(node).strip()}))
    uids = tuple(sorted({str(uid).strip() for uid in source_node_uids if str(uid).strip()}))
    if not nodes or len(nodes) != len(uids):
        raise SoperatorMigrationPhasePending(
            f"Worker provider drain for {group_name} lacks a complete node identity set."
        )
    campaign_fingerprint = str(checkpoint.get("campaign_fingerprint") or "").strip()
    if not re.fullmatch(r"[0-9a-f]{64}", campaign_fingerprint):
        raise RuntimeError(
            "Worker provider drain requires the canonical checkpointed campaign fingerprint."
        )
    campaign_token = campaign_fingerprint[:16]
    state = group_state.setdefault("kubernetes_provider_drain", {})
    if not isinstance(state, dict):
        raise RuntimeError("Worker Kubernetes provider drain journal must be a mapping.")
    binding = {
        "node_group_id": group_id,
        "source_nodes": list(nodes),
        "source_node_uids": list(uids),
        "taint_key": "nebius-cxcli.io/in-place-provider-rollout",
        "taint_value": campaign_token,
    }
    existing_binding = {key: state.get(key) for key in binding}
    if state and existing_binding != binding:
        raise RuntimeError(
            f"recovery-required: worker provider drain binding drifted for {group_name}."
        )
    state.update(binding)
    if state.get("status") != "drained":
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "taint",
                "nodes",
                *nodes,
                f"{binding['taint_key']}={campaign_token}:NoSchedule",
                "--overwrite",
            ],
            timeout_seconds=120,
        )
        state.update({"status": "tainted", "tainted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "drain",
                *nodes,
                "--ignore-daemonsets",
                "--delete-emptydir-data",
                "--force",
                "--timeout=15m",
            ],
            check=False,
            timeout_seconds=960,
        )
        if result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                f"Worker provider drain for {group_name} remains pending: "
                + _command_detail(result)
            )
        state.update({"status": "drained", "drained_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()


def _in_place_campaign_segment(
    campaign: Mapping[str, Any], checkpoint: Mapping[str, Any]
) -> Mapping[str, Any]:
    segment_id = str(checkpoint.get("current_segment_id", "") or "").strip()
    for segment in _sequence_of_mappings(campaign.get("segments")):
        if str(segment.get("id", "") or "").strip() == segment_id:
            return segment
    raise RuntimeError(
        "External Soperator in-place rollout cannot find the checkpointed campaign segment."
    )


def _latest_completed_segment_phase_state(
    checkpoint: Mapping[str, Any],
    *,
    phase_id: str,
) -> Mapping[str, Any]:
    """Return immutable phase evidence from the latest completed campaign segment."""

    segment_state = _mapping(checkpoint.get("segment_state"))
    completed_segment_ids = tuple(
        str(segment_id or "").strip()
        for segment_id in checkpoint.get("completed_segment_ids", []) or []
        if str(segment_id or "").strip()
    )
    for segment_id in reversed(completed_segment_ids):
        completed = _mapping(segment_state.get(segment_id))
        completed_phases = {
            str(phase_id or "").strip()
            for phase_id in completed.get("completed_phases", []) or []
            if str(phase_id or "").strip()
        }
        if (
            not str(completed.get("completed_at", "") or "").strip()
            or phase_id not in completed_phases
        ):
            continue
        operation_evidence = _mapping(completed.get("operation_evidence"))
        archived_phase = _mapping(_mapping(operation_evidence.get("phase_state")).get(phase_id))
        if archived_phase:
            return archived_phase
    return {}


def _accepted_populate_jail_phase_state(
    checkpoint: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Return the current or latest completed segment's immutable Jail handoff proof."""

    current = _mapping(_mapping(checkpoint.get("phase_state")).get(POPULATE_JAIL_REFRESH_PHASE_ID))
    return current or _latest_completed_segment_phase_state(
        checkpoint,
        phase_id=POPULATE_JAIL_REFRESH_PHASE_ID,
    )


def _in_place_source_group(
    source_report: Mapping[str, Any],
    *,
    node_group_id: str,
) -> Mapping[str, Any]:
    groups = _mapping(_mapping(source_report.get("snapshot")).get("node_groups"))
    matches = [
        group
        for group in groups.values()
        if isinstance(group, Mapping) and _source_group_node_group_id(group) == node_group_id
    ]
    if len(matches) != 1:
        raise RuntimeError(
            "External Soperator in-place rollout requires one exact source group for "
            f"provider node group {node_group_id}; found {len(matches)}."
        )
    return matches[0]


def _require_in_place_jail_slot_switch(
    *,
    checkpoint: Mapping[str, Any],
    planned_groups: Sequence[Mapping[str, Any]],
) -> None:
    populate = _accepted_populate_jail_phase_state(checkpoint)
    handoff = _mapping(populate.get("rootfs_handoff_verification"))
    active_slot = str(handoff.get("active_slot") or populate.get("active_slot") or "").strip()
    rollback_slot = str(populate.get("rollback_slot") or "").strip()
    rootfs_slots = _mapping(populate.get("rootfs_slots"))
    prior_active_slot = str(rootfs_slots.get("active_slot") or "").strip()
    accepted_passive_slot = str(rootfs_slots.get("passive_slot") or "").strip()
    if (
        not str(populate.get("completed_at", "") or "").strip()
        or str(handoff.get("status", "") or "").strip() not in {"verified", "passed"}
        or not prior_active_slot
        or not accepted_passive_slot
        or active_slot != accepted_passive_slot
        or rollback_slot not in {"legacy-rootfs", prior_active_slot}
        or rollback_slot == active_slot
    ):
        raise SoperatorMigrationPhasePending(
            "In-place compute migration waits for completed and verified Jail rootfs "
            "active/passive slot activation with the prior slot retained for recovery."
        )
    persistent_mounts = _mapping(populate.get("persistent_jail_mounts"))
    if persistent_mounts and persistent_mounts.get("status") != "verified":
        raise SoperatorMigrationPhasePending(
            f"In-place compute migration waits for verified persistent Jail mounts on "
            f"{active_slot}."
        )
    has_gpu = any(
        str(group.get("platform", "") or "").startswith("gpu-")
        or group.get("gpu_software_mode") in {"provider-managed", "operator-managed"}
        for group in planned_groups
        if str(group.get("role", "") or "").startswith("worker")
    )
    if has_gpu:
        for field in ("gpu_post_population", _GPU_PRE_ACTIVATION_FLEET_GATE_KEY):
            if str(_mapping(populate.get(field)).get("status", "") or "").strip() != "passed":
                raise SoperatorMigrationPhasePending(
                    f"In-place compute migration waits for the completed {active_slot} GPU "
                    f"health gate {field}."
                )


def _in_place_provider_identity_matches(
    *,
    observed: Mapping[str, Any],
    expected: Mapping[str, Any],
    provider_operation_journaled: bool,
) -> bool:
    observed_identity = to_plain_data(dict(observed))
    expected_identity = to_plain_data(dict(expected))
    if provider_operation_journaled:
        observed_identity.pop("resource_version", None)
        expected_identity.pop("resource_version", None)
    return _stable_json(observed_identity) == _stable_json(expected_identity)


def _bind_in_place_segment_provider_identity(
    *,
    checkpoint: Mapping[str, Any],
    group_state: dict[str, Any],
    planned_group: Mapping[str, Any],
    observed_provider_identity: Mapping[str, Any],
    live: Mapping[str, Any],
    group_name: str,
    provider_operation_journaled: bool,
) -> Mapping[str, Any]:
    """Bind the mutable provider version at a verified campaign segment boundary."""

    expected_provider_identity = _mapping(planned_group.get("provider_identity"))
    if not expected_provider_identity:
        raise RuntimeError(f"In-place campaign provider identity is incomplete for {group_name}.")
    segment_identity = _mapping(group_state.get("segment_start_provider_identity"))
    if segment_identity:
        if not _in_place_provider_identity_matches(
            observed=observed_provider_identity,
            expected=segment_identity,
            provider_operation_journaled=provider_operation_journaled,
        ):
            raise RuntimeError(
                f"recovery-required: segment-bound provider identity drifted for {group_name}."
            )
        return segment_identity
    if _in_place_provider_identity_matches(
        observed=observed_provider_identity,
        expected=expected_provider_identity,
        provider_operation_journaled=provider_operation_journaled,
    ):
        return expected_provider_identity

    observed_immutable = dict(to_plain_data(dict(observed_provider_identity)))
    expected_immutable = dict(to_plain_data(dict(expected_provider_identity)))
    observed_immutable.pop("resource_version", None)
    expected_immutable.pop("resource_version", None)
    completed_segment_ids = tuple(
        str(segment_id or "").strip()
        for segment_id in checkpoint.get("completed_segment_ids", []) or []
        if str(segment_id or "").strip()
    )
    source_target = _mapping(planned_group.get("source"))
    observed_version = str(observed_provider_identity.get("resource_version") or "").strip()
    live_version = str(_node_group_resource_version(live) or "").strip()
    if (
        provider_operation_journaled
        or not completed_segment_ids
        or not source_target
        or not _in_place_node_group_target_satisfied(live, target=source_target)
        or observed_immutable != expected_immutable
        or not observed_version
        or observed_version != live_version
    ):
        raise RuntimeError(
            f"Provider reservation/failure-domain identity drifted for {group_name}. "
            "No mutation was submitted."
        )
    bound_identity = copy.deepcopy(to_plain_data(dict(observed_provider_identity)))
    group_state["segment_start_provider_identity"] = bound_identity
    group_state["segment_start_provider_identity_bound_at"] = _utc_now()
    return _mapping(bound_identity)


def _execute_one_in_place_node_group(
    *,
    checkpoint: dict[str, Any],
    group_state: dict[str, Any],
    planned_group: Mapping[str, Any],
    source_report: Mapping[str, Any],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    max_surge: int,
    max_unavailable: int,
    drain_timeout: str,
    checkpoint_writer: Callable[[], None] | None,
    restore_worker_lock: bool = True,
    cancellation_event: threading.Event | None = None,
) -> tuple[bool, list[str]]:
    group_id = str(planned_group.get("id", "") or "").strip()
    group_name = str(planned_group.get("name", "") or group_id).strip()
    role = str(planned_group.get("role", "") or "").strip()
    target = _mapping(planned_group.get("target"))
    accepted_size = _positive_int(planned_group.get("fixed_size"), fallback=0)
    if not group_id or not role or accepted_size <= 0:
        raise RuntimeError("In-place campaign node-group identity or fixed size is incomplete.")
    source_group = _in_place_source_group(source_report, node_group_id=group_id)
    live = _node_group_payload_by_id(nebius_api=nebius_api, node_group_id=group_id)
    if _node_group_id(live) != group_id:
        raise RuntimeError(f"Provider node-group identity changed for {group_name}.")
    if _node_group_fixed_count(live) != accepted_size:
        raise RuntimeError(
            f"Provider node-group size drifted for {group_name}: accepted={accepted_size}, "
            f"live={_node_group_fixed_count(live)}. No mutation was submitted."
        )
    accepted_provider = _mapping(source_group.get("provider"))
    accepted_reservation = _mapping(accepted_provider.get("reservation"))
    observed_provider_identity = {
        "resource_uid": str(
            accepted_provider.get("resource_uid") or accepted_provider.get("node_group_id") or ""
        ).strip(),
        "resource_version": accepted_provider.get(
            "resource_version", accepted_provider.get("resourceVersion")
        ),
        "reservation_policy": str(
            accepted_reservation.get("policy") or accepted_provider.get("reservation_policy") or ""
        ).strip(),
        "reservation_ids": sorted(
            str(item).strip()
            for item in (
                accepted_reservation.get("reservation_ids")
                or accepted_provider.get("reservation_ids")
                or []
            )
            if str(item).strip()
        ),
        "failure_domains": sorted(
            str(item).strip()
            for item in (accepted_provider.get("failure_domains") or [])
            if str(item).strip()
        ),
        "gpu_cluster_id": str(accepted_provider.get("gpu_cluster_id") or "").strip(),
    }
    journaled_target_update = _mapping(group_state.get("target_update"))
    provider_operation_journaled = isinstance(journaled_target_update.get("operation"), Mapping)
    live_version = _node_group_resource_version(live)
    accepted_provider_identity = _bind_in_place_segment_provider_identity(
        checkpoint=checkpoint,
        group_state=group_state,
        planned_group=planned_group,
        observed_provider_identity=observed_provider_identity,
        live=live,
        group_name=group_name,
        provider_operation_journaled=provider_operation_journaled,
    )
    accepted_version = str(accepted_provider_identity.get("resource_version") or "").strip()
    if checkpoint_writer is not None and group_state.get("segment_start_provider_identity"):
        checkpoint_writer()
    live_metadata = _mapping(live.get("metadata"))
    live_uid = str(live_metadata.get("uid") or live_metadata.get("id") or group_id).strip()
    if live_uid != str(accepted_provider_identity.get("resource_uid") or "").strip():
        raise RuntimeError(
            f"Provider node-group UID drifted for {group_name}. No mutation was submitted."
        )
    target_operation = group_state.setdefault("target_update", {})
    if not isinstance(target_operation, dict):
        raise RuntimeError("In-place target_update journal must be a mapping.")
    journaled_operation = _mapping(target_operation.get("operation"))
    if journaled_operation and str(journaled_operation.get("resource_version") or "").strip() != (
        accepted_version
    ):
        raise RuntimeError(
            f"recovery-required: journaled provider resource version changed for {group_name}."
        )
    if not target_operation and accepted_version and str(live_version) != accepted_version:
        raise RuntimeError(
            f"Provider node-group resource version drifted for {group_name}: "
            f"accepted={accepted_version}, live={live_version}. No mutation was submitted."
        )
    group_state.setdefault("source_template", to_plain_data(_mapping(live.get("spec"))))
    group_state.setdefault("original_strategy", to_plain_data(_node_group_strategy(live)))
    group_state.update(
        {
            "node_group_id": group_id,
            "name": group_name,
            "role": role,
            "accepted_fixed_size": accepted_size,
            "target": to_plain_data(target),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()

    login_handoff_lines: list[str] = []
    already_satisfied = _in_place_node_group_target_satisfied(live, target=target)
    if already_satisfied and isinstance(target_operation.get("operation"), Mapping):
        operation = _mapping(target_operation.get("operation"))
        if operation.get("attempt_state") != "provider-terminal":
            _record_reconciled_provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=target_operation,
                nebius_api=nebius_api,
                provider_payload=live,
                operation_kind="MK8s node-group in-place update",
                resource_id=group_id,
                checkpoint_writer=checkpoint_writer,
                verified_postcondition={"target": to_plain_data(target), "ready": True},
            )
        if role == "login":
            login_handoff_lines.extend(
                _release_in_place_login_hold_after_provider_peer(
                    checkpoint=checkpoint,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
        before_uids = tuple(str(uid) for uid in group_state.get("source_node_uids", []) or [])
        after_uids = _in_place_live_node_uids(
            command_runner=command_runner,
            kube_context=kube_context,
            node_group_id=group_id,
            require_ready=True,
        )
        if (
            len(before_uids) != accepted_size
            or len(after_uids) != accepted_size
            or set(after_uids) & set(before_uids)
        ):
            raise RuntimeError(
                f"recovery-required: {group_name} cannot prove a complete old-to-new node "
                "UID transition after resuming its provider operation."
            )
        group_state["replacement_node_uids"] = list(after_uids)
        if checkpoint_writer is not None:
            checkpoint_writer()
    elif not already_satisfied:
        if target_operation and not _provider_operation_request_is_retryable(target_operation):
            if role == "login":
                login_handoff_lines.extend(
                    _release_in_place_login_hold_after_provider_peer(
                        checkpoint=checkpoint,
                        command_runner=command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=checkpoint_writer,
                    )
                )
            _require_journaled_provider_operation_before_unmet_postcondition(
                resource_state=target_operation,
                nebius_api=nebius_api,
                operation_kind="MK8s node-group in-place update",
                resource_id=group_id,
            )
        if role.startswith("worker"):
            if _mapping(group_state.get("slurm_drain")).get("status") == "applied":
                _revalidate_in_place_worker_group_lock(
                    group_state=group_state,
                    group_id=group_id,
                    group_name=group_name,
                    source_report=source_report,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            else:
                _apply_in_place_worker_group_lock(
                    checkpoint=checkpoint,
                    group_state=group_state,
                    group_id=group_id,
                    group_name=group_name,
                    source_report=source_report,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
        before_uids = _in_place_live_node_uids(
            command_runner=command_runner,
            kube_context=kube_context,
            node_group_id=group_id,
        )
        group_state["source_node_uids"] = list(before_uids)
        if role.startswith("worker"):
            worker_evidence = _mapping(group_state.get("pre_dispatch_clear_evidence")) or _mapping(
                group_state.get("pre_drain_clear_evidence")
            )
            _prepare_in_place_worker_provider_drain(
                checkpoint=checkpoint,
                group_state=group_state,
                group_id=group_id,
                group_name=group_name,
                source_nodes=tuple(
                    str(node) for node in worker_evidence.get("source_nodes", []) or []
                ),
                source_node_uids=before_uids,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        desired_spec, mask_paths = _in_place_node_group_desired_spec(
            original_node_group=live,
            target=target,
            max_surge=max_surge,
            max_unavailable=max_unavailable,
            drain_timeout=drain_timeout,
        )
        intended_postcondition = {
            "node_group_id": group_id,
            "fixed_size": accepted_size,
            "target": to_plain_data(target),
            "temporary_strategy": to_plain_data(_mapping(desired_spec.get("strategy"))),
        }
        operation_entry = _provider_operation_intent_for_request(
            checkpoint=checkpoint,
            resource_state=target_operation,
            operation_kind="mk8s-node-group-in-place-update",
            resource_id=group_id,
            resource_uid=str(_mapping(live.get("metadata")).get("uid") or group_id),
            resource_version=live_version,
            intended_postcondition=intended_postcondition,
            checkpoint_writer=checkpoint_writer,
        )
        _provider_operation_requested(
            checkpoint=checkpoint,
            resource_state=target_operation,
            operation_entry=operation_entry,
            checkpoint_writer=checkpoint_writer,
        )
        try:
            updated = nebius_api.update_node_group(
                node_group_id=group_id,
                original_node_group=live,
                desired_spec=desired_spec,
                update_mask_paths=mask_paths,
                timeout_seconds=int(_PROVIDER_OPERATION_POLL_INITIAL_SECONDS),
                operation_accepted=_provider_operation_acceptance_callback(
                    checkpoint=checkpoint,
                    resource_state=target_operation,
                    operation_entry=operation_entry,
                    checkpoint_writer=checkpoint_writer,
                ),
            )
        except subprocess.TimeoutExpired as exc:
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=target_operation,
                operation_entry=operation_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            operation_id = str(operation_entry.get("provider_operation_id", "") or "").strip()
            if not _provider_operation_id_is_real(operation_id):
                raise
            _require_reconciled_provider_operation_terminal(
                nebius_api=nebius_api,
                provider_operation_id=operation_id,
                provider_operation_kind=str(operation_entry.get("operation_kind", "") or ""),
                operation_kind="MK8s node-group in-place update",
                resource_id=group_id,
                cancellation_event=cancellation_event,
            )
            updated = _wait_for_provider_resource_postcondition(
                fetch=lambda: nebius_api.get_node_group(group_id),
                satisfied=lambda item: _in_place_node_group_target_satisfied(
                    item,
                    target=target,
                ),
                operation_kind="MK8s node-group in-place update",
                resource_id=group_id,
                cancellation_event=cancellation_event,
            )
            updated = {**updated, "_cxcli_provider_operation_id": operation_id}
        except (Exception, KeyboardInterrupt) as exc:
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=target_operation,
                operation_entry=operation_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            raise
        if not _in_place_node_group_target_satisfied(updated, target=target):
            returned_operation_id = _required_provider_operation_id(
                updated,
                operation_kind="MK8s node-group in-place update",
                resource_id=group_id,
            )
            updated = _wait_for_provider_resource_postcondition(
                fetch=lambda: nebius_api.get_node_group(group_id),
                satisfied=lambda item: _in_place_node_group_target_satisfied(
                    item,
                    target=target,
                ),
                operation_kind="MK8s node-group in-place update",
                resource_id=group_id,
                cancellation_event=cancellation_event,
            )
            updated = {**updated, "_cxcli_provider_operation_id": returned_operation_id}
        after_uids = _in_place_live_node_uids(
            command_runner=command_runner,
            kube_context=kube_context,
            node_group_id=group_id,
            require_ready=True,
        )
        if len(after_uids) != accepted_size or set(after_uids) & set(before_uids):
            raise RuntimeError(
                f"recovery-required: {group_name} is an unknown mixed old/new fleet after "
                "the provider rollout."
            )
        group_state["replacement_node_uids"] = list(after_uids)
        _provider_operation_terminal(
            checkpoint=checkpoint,
            resource_state=target_operation,
            operation_entry=operation_entry,
            provider_payload=updated,
            operation_kind="MK8s node-group in-place update",
            resource_id=group_id,
            verified_postcondition={
                **intended_postcondition,
                "replacement_node_uids": list(after_uids),
                "ready": True,
            },
            checkpoint_writer=checkpoint_writer,
        )
        live = updated

    restore_state = group_state.setdefault("strategy_restore", {})
    if not isinstance(restore_state, dict):
        raise RuntimeError("In-place strategy_restore journal must be a mapping.")
    original_strategy = _mapping(group_state.get("original_strategy"))
    restore_operation = _mapping(restore_state.get("operation"))
    if (
        restore_operation
        and restore_operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES
        and _stable_json(_node_group_strategy(live)) == _stable_json(original_strategy)
    ):
        # The provider may have completed the restore between runs.  Reconcile
        # that accepted operation before marking the group complete; matching
        # live state alone is not terminal evidence for the journal.
        _record_reconciled_provider_operation_terminal(
            checkpoint=checkpoint,
            resource_state=restore_state,
            nebius_api=nebius_api,
            provider_payload=live,
            operation_kind="MK8s node-group strategy restore",
            resource_id=group_id,
            checkpoint_writer=checkpoint_writer,
            verified_postcondition={"strategy": to_plain_data(original_strategy)},
        )
    if _stable_json(_node_group_strategy(live)) != _stable_json(original_strategy):
        if restore_state and not _provider_operation_request_is_retryable(restore_state):
            _require_journaled_provider_operation_before_unmet_postcondition(
                resource_state=restore_state,
                nebius_api=nebius_api,
                operation_kind="MK8s node-group strategy restore",
                resource_id=group_id,
            )
        restore_spec = copy.deepcopy(to_plain_data(_mapping(live.get("spec"))))
        if not isinstance(restore_spec, dict):
            raise RuntimeError("Provider node-group spec is invalid during strategy restoration.")
        if original_strategy:
            restore_spec["strategy"] = to_plain_data(original_strategy)
        else:
            restore_spec.pop("strategy", None)
        restore_entry = _provider_operation_intent_for_request(
            checkpoint=checkpoint,
            resource_state=restore_state,
            operation_kind="mk8s-node-group-strategy-restore",
            resource_id=group_id,
            resource_uid=str(_mapping(live.get("metadata")).get("uid") or group_id),
            resource_version=_node_group_resource_version(live),
            intended_postcondition={"strategy": to_plain_data(original_strategy)},
            checkpoint_writer=checkpoint_writer,
        )
        _provider_operation_requested(
            checkpoint=checkpoint,
            resource_state=restore_state,
            operation_entry=restore_entry,
            checkpoint_writer=checkpoint_writer,
        )
        try:
            restored = nebius_api.update_node_group(
                node_group_id=group_id,
                original_node_group=live,
                desired_spec=restore_spec,
                update_mask_paths=("spec.strategy",),
                timeout_seconds=int(_PROVIDER_OPERATION_POLL_INITIAL_SECONDS),
                operation_accepted=_provider_operation_acceptance_callback(
                    checkpoint=checkpoint,
                    resource_state=restore_state,
                    operation_entry=restore_entry,
                    checkpoint_writer=checkpoint_writer,
                ),
            )
        except subprocess.TimeoutExpired as exc:
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=restore_state,
                operation_entry=restore_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            operation_id = str(restore_entry.get("provider_operation_id", "") or "").strip()
            if not _provider_operation_id_is_real(operation_id):
                raise
            _require_reconciled_provider_operation_terminal(
                nebius_api=nebius_api,
                provider_operation_id=operation_id,
                provider_operation_kind=str(restore_entry.get("operation_kind", "") or ""),
                operation_kind="MK8s node-group strategy restore",
                resource_id=group_id,
                cancellation_event=cancellation_event,
            )
            restored = _wait_for_provider_resource_postcondition(
                fetch=lambda: nebius_api.get_node_group(group_id),
                satisfied=lambda item: (
                    _stable_json(_node_group_strategy(item)) == _stable_json(original_strategy)
                ),
                operation_kind="MK8s node-group strategy restore",
                resource_id=group_id,
                cancellation_event=cancellation_event,
            )
            restored = {**restored, "_cxcli_provider_operation_id": operation_id}
        except (Exception, KeyboardInterrupt) as exc:
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=restore_state,
                operation_entry=restore_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
            raise
        if _stable_json(_node_group_strategy(restored)) != _stable_json(original_strategy):
            returned_operation_id = _required_provider_operation_id(
                restored,
                operation_kind="MK8s node-group strategy restore",
                resource_id=group_id,
            )
            restored = _wait_for_provider_resource_postcondition(
                fetch=lambda: nebius_api.get_node_group(group_id),
                satisfied=lambda item: (
                    _stable_json(_node_group_strategy(item)) == _stable_json(original_strategy)
                ),
                operation_kind="MK8s node-group strategy restore",
                resource_id=group_id,
                cancellation_event=cancellation_event,
            )
            restored = {**restored, "_cxcli_provider_operation_id": returned_operation_id}
        _provider_operation_terminal(
            checkpoint=checkpoint,
            resource_state=restore_state,
            operation_entry=restore_entry,
            provider_payload=restored,
            operation_kind="MK8s node-group strategy restore",
            resource_id=group_id,
            verified_postcondition={"strategy": to_plain_data(original_strategy)},
            checkpoint_writer=checkpoint_writer,
        )
    if role.startswith("worker"):
        rescheduling_restore_lines = _restore_in_place_worker_drain_rescheduling_guard(
            group_state=group_state,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    else:
        rescheduling_restore_lines = []
    if role.startswith("worker") and restore_worker_lock:
        restore_lines = _restore_in_place_worker_group_lock(
            group_state=group_state,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    else:
        restore_lines = []
    group_state["status"] = (
        "completed"
        if not role.startswith("worker") or restore_worker_lock
        else "provider-complete-health-pending"
    )
    if group_state["status"] == "completed":
        group_state["completed_at"] = _utc_now()
    if checkpoint_writer is not None:
        checkpoint_writer()
    return not already_satisfied, [
        *login_handoff_lines,
        f"In-place node group {group_name}: target template ready and original strategy restored"
        + (
            "; replacement health remains gated before the Slurm drain is released."
            if role.startswith("worker") and not restore_worker_lock
            else "."
        ),
        *rescheduling_restore_lines,
        *restore_lines,
    ]


def _repair_in_place_login_gateway_spread(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    pods: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> Mapping[str, Any]:
    """Recreate one co-located login replica on the other accepted Ready node."""

    ready_pods = [
        pod
        for pod in _sequence_of_mappings(pods.get("items"))
        if _pod_is_ready(pod) and not _mapping(pod.get("metadata")).get("deletionTimestamp")
    ]
    ready_nodes = {
        str(_mapping(pod.get("spec")).get("nodeName") or "").strip() for pod in ready_pods
    }
    ready_nodes.discard("")
    if len(ready_nodes) >= 2:
        return pods
    if len(ready_pods) != 2 or len(ready_nodes) != 1:
        return pods
    binding = _checkpoint_in_place_login_handoff_binding(
        checkpoint=checkpoint,
        checkpoint_writer=checkpoint_writer,
    )
    node_group_id = str(binding.get("node_group_id") or "").strip()
    target_version = str(binding.get("provider_target_kubernetes_version") or "").strip()
    nodes = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "get",
            "nodes",
            "-l",
            f"nebius.com/node-group-id={node_group_id}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    eligible_nodes = {
        str(_mapping(node.get("metadata")).get("name") or "").strip()
        for node in _sequence_of_mappings(nodes.get("items"))
        if _node_ready(node)
        and _minor_version_text_or_empty(
            str(_mapping(_mapping(node.get("status")).get("nodeInfo")).get("kubeletVersion") or "")
        )
        == parse_k8s_version(target_version).minor_text
    }
    eligible_nodes.discard("")
    occupied_node = next(iter(ready_nodes))
    if len(eligible_nodes) != 2 or occupied_node not in eligible_nodes:
        return pods
    held_uids = {
        str(item.get("uid") or "").strip()
        for item in _sequence_of_mappings(
            _mapping(checkpoint.get("active_login_session_hold")).get("pods")
        )
    }
    candidates = [
        pod
        for pod in ready_pods
        if str(_mapping(pod.get("metadata")).get("uid") or "").strip() not in held_uids
    ]
    if not candidates:
        return pods
    selected = sorted(
        candidates,
        key=lambda pod: str(_mapping(pod.get("metadata")).get("name") or ""),
        reverse=True,
    )[0]
    metadata = _mapping(selected.get("metadata"))
    pod_name = str(metadata.get("name") or "").strip()
    pod_uid = str(metadata.get("uid") or "").strip()
    resource_version = str(metadata.get("resourceVersion") or "").strip()
    repair = phase.setdefault("login_gateway_spread_repair", {})
    if not isinstance(repair, dict):
        raise RuntimeError("login_gateway_spread_repair must be a mapping.")
    repair.update(
        {
            "status": "recreating",
            "occupied_node": occupied_node,
            "source_pod": {"name": pod_name, "uid": pod_uid},
            "started_at": repair.get("started_at") or _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    command_runner(
        ["kubectl", "--context", kube_context, "cordon", occupied_node],
        timeout_seconds=120,
    )
    try:
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/pods/{pod_name}",
            uid=pod_uid,
            resource_version=resource_version,
            propagation_policy="Foreground",
            timeout_seconds=300,
        )
        deadline = time.monotonic() + 600
        while True:
            observed = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "get",
                    "pods",
                    "-l",
                    "app.kubernetes.io/component=login",
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
            observed_ready = [
                pod
                for pod in _sequence_of_mappings(observed.get("items"))
                if _pod_is_ready(pod) and not _mapping(pod.get("metadata")).get("deletionTimestamp")
            ]
            observed_nodes = {
                str(_mapping(pod.get("spec")).get("nodeName") or "").strip()
                for pod in observed_ready
            }
            observed_uids = {
                str(_mapping(pod.get("metadata")).get("uid") or "").strip()
                for pod in observed_ready
            }
            if (
                len(observed_ready) == 2
                and len(observed_nodes) == 2
                and pod_uid not in observed_uids
            ):
                repair.update(
                    {
                        "status": "verified",
                        "ready_nodes": sorted(observed_nodes),
                        "replacement_pod_uids": sorted(observed_uids),
                        "verified_at": _utc_now(),
                    }
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                return observed
            if time.monotonic() >= deadline:
                raise SoperatorMigrationPhasePending(
                    "login gateway spread repair did not produce two Ready replicas on "
                    "distinct accepted login nodes."
                )
            time.sleep(5)
    finally:
        command_runner(
            ["kubectl", "--context", kube_context, "uncordon", occupied_node],
            timeout_seconds=120,
        )


def _require_in_place_continuity_resources(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    checkpoint_writer: Callable[[], None] | None,
    accepted_login_provider_operation_pending: bool = False,
) -> list[str]:
    bridge = checkpoint.get("controller_bridge")
    if not isinstance(bridge, Mapping):
        raise SoperatorMigrationPhasePending(
            "in-place compute migration requires the temporary controller bridge journal."
        )
    validate_bridge_journal(bridge)
    bridge_stage = BridgeStage(str(bridge.get("stage", "") or ""))
    if bridge_stage not in {BridgeStage.SOURCE_HA_ACTIVE, BridgeStage.TARGET_HA_ACTIVE}:
        raise SoperatorMigrationPhasePending(
            "in-place compute migration requires two-node controller bridge authority; "
            f"current stage={bridge_stage.value}."
        )
    if accepted_login_provider_operation_pending:
        proof = _mapping(phase.get("continuity_resources"))
        ready_nodes = tuple(str(item).strip() for item in proof.get("login_ready_nodes", []) or [])
        if (
            str(proof.get("bridge_stage") or "") != bridge_stage.value
            or len(set(ready_nodes)) < 2
            or not str(proof.get("verified_at") or "").strip()
        ):
            raise RuntimeError(
                "recovery-required: an accepted login provider operation lacks its "
                "pre-dispatch two-node continuity proof."
            )
        return [
            "In-place continuity: retained the pre-dispatch two-login-node proof while "
            "the exact checkpointed provider operation remains pending; temporary "
            "replacement unavailability cannot dispatch a duplicate mutation."
        ]
    service_ready = wait_for_login_service_ready_endpoints(
        command_runner,
        namespace=_SOPERATOR_NAMESPACE,
        target_ref=target_ref,
        kube_context=kube_context,
        min_ready_endpoints=2,
        timeout_seconds=0,
    )
    pods = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-l",
            f"app.kubernetes.io/instance={target_ref},app.kubernetes.io/component=login",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _repair_in_place_login_gateway_spread(
        checkpoint=checkpoint,
        phase=phase,
        pods=pods,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    ready_nodes = {
        str(_mapping(pod.get("spec")).get("nodeName", "") or "").strip()
        for pod in _sequence_of_mappings(pods.get("items"))
        if _pod_is_ready(pod)
        and not _mapping(pod.get("metadata")).get("deletionTimestamp")
        and str(_mapping(pod.get("spec")).get("nodeName", "") or "").strip()
    }
    if len(ready_nodes) < 2:
        raise SoperatorMigrationPhasePending(
            "in-place login migration requires two Ready login gateway replicas on "
            "distinct Kubernetes nodes before any login provider update."
        )
    proof = {
        "bridge_stage": bridge_stage.value,
        "login_ready_endpoints": service_ready.get("ready_endpoints"),
        "login_ready_nodes": sorted(ready_nodes),
        "verified_at": _utc_now(),
    }
    phase["continuity_resources"] = proof
    return [
        "In-place continuity: two-node controller bridge authority and two distinct "
        "Ready login gateway replicas verified."
    ]


def _accepted_in_place_login_provider_operation_pending(
    *,
    phase: Mapping[str, Any],
    planned_groups: Sequence[Mapping[str, Any]],
) -> bool:
    """Return whether the exact accepted login rollout is still non-terminal."""

    login_group_ids = {
        str(group.get("id") or "").strip()
        for group in planned_groups
        if str(group.get("role") or "").strip() == "login"
    }
    login_group_ids.discard("")
    groups_state = _mapping(phase.get("in_place_node_groups"))
    for group_id in login_group_ids:
        group_state = _mapping(groups_state.get(group_id))
        operation = _mapping(_mapping(group_state.get("target_update")).get("operation"))
        if (
            operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES
            and _provider_operation_id_is_real(operation.get("provider_operation_id"))
            and str(operation.get("accepted_at") or "").strip()
        ):
            return True
    return False


def _accepted_in_place_worker_provider_operations_pending(
    phase: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    """Return exact accepted non-terminal worker provider operations."""

    pending: list[Mapping[str, Any]] = []
    for group_state in _mapping(phase.get("in_place_node_groups")).values():
        if not isinstance(group_state, Mapping) or not str(
            group_state.get("role") or ""
        ).startswith("worker"):
            continue
        operation = _mapping(_mapping(group_state.get("target_update")).get("operation"))
        if (
            operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES
            and _provider_operation_id_is_real(operation.get("provider_operation_id"))
            and str(operation.get("accepted_at") or "").strip()
        ):
            pending.append(operation)
    return tuple(pending)


def _ensure_in_place_gpu_driver_refresh_after_provider_rollout(
    *,
    checkpoint: Mapping[str, Any],
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_ref: str,
    values: Mapping[str, Any],
    active_pvc: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Refresh the active Jail only after exact replacement GPU nodes are Ready."""

    gpu_nodesets = _gpu_worker_nodeset_names(values)
    if not gpu_nodesets:
        return []
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh requires durable checkpoint writes."
        )
    groups = phase.get("in_place_node_groups")
    if not isinstance(groups, Mapping):
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh requires the exact worker provider journal."
        )
    pending_gpu_groups = [
        state
        for state in groups.values()
        if isinstance(state, Mapping)
        and state.get("status") == "provider-complete-health-pending"
        and _mapping(_mapping(state.get("target_update")).get("operation")).get(
            "intended_postcondition", {}
        )
    ]
    replacement_uids = {
        str(uid).strip()
        for state in pending_gpu_groups
        for uid in state.get("replacement_node_uids", []) or []
        if str(uid).strip()
    }
    if not pending_gpu_groups or not replacement_uids:
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh waits for terminal provider replacement identity."
        )
    node_group_bindings = _target_gpu_node_group_bindings(
        checkpoint=checkpoint,
        gpu_nodesets=gpu_nodesets,
    )
    fleet = _ready_owned_target_gpu_nodes(
        command_runner=command_runner,
        kube_context=kube_context,
        node_groups=node_group_bindings,
    )
    fleet_uids = {str(item.get("node_uid") or "") for item in fleet}
    if fleet_uids != replacement_uids:
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh requires every exact replacement GPU Node UID "
            "and no source-era GPU node."
        )
    selected_node = fleet[0]
    selected_node_name = str(selected_node.get("node") or "").strip()
    selected_node_uid = str(selected_node.get("node_uid") or "").strip()
    populate_phase = _accepted_populate_jail_phase_state(checkpoint)
    image_lock = _mapping(_mapping(populate_phase.get("gpu_post_population")).get("image_lock"))
    immutable_image = str(image_lock.get("immutable_reference") or "").strip()
    if not re.fullmatch(r"[^\s@]+(?:/[^\s@]+)*@sha256:[0-9a-f]{64}", immutable_image):
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh requires the checkpointed immutable target "
            "controller image."
        )
    pvc_exists, pvc = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"persistentvolumeclaim/{active_pvc}",
    )
    active_pvc_uid = str(_mapping(pvc.get("metadata")).get("uid") or "").strip()
    if not pvc_exists or not active_pvc_uid:
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh cannot bind the active Jail PVC UID."
        )
    fleet_fingerprint = _fingerprint(
        [
            {
                "node_group_id": item.get("node_group_id"),
                "node": item.get("node"),
                "node_uid": item.get("node_uid"),
            }
            for item in fleet
        ]
    )
    refresh_ref = f"cxcli-ip-driver-{fleet_fingerprint[:12]}"
    resources = build_jail_gpu_post_population_resources(
        namespace=_SOPERATOR_NAMESPACE,
        target_ref=refresh_ref,
        runner_image=immutable_image,
        passive_pvc=active_pvc,
        scheduling=_jail_gpu_post_population_scheduling(values),
        allow_driver_refresh=True,
    )
    config_manifest = copy.deepcopy(dict(resources.config_map))
    job_manifest = copy.deepcopy(dict(resources.job))
    pod_spec = _mapping(_mapping(job_manifest.get("spec")).get("template")).get("spec")
    if not isinstance(pod_spec, dict):
        raise RuntimeError("generated in-place GPU driver refresh Job is invalid.")
    pod_spec["nodeName"] = selected_node_name
    binding_annotations = {
        "nebius.ai/cxcli-target-ref-sha256": hashlib.sha256(target_ref.encode()).hexdigest(),
        "nebius.ai/cxcli-active-pvc-uid": active_pvc_uid,
        "nebius.ai/cxcli-node-uid": selected_node_uid,
        "nebius.ai/cxcli-fleet-sha256": fleet_fingerprint,
    }
    for manifest in (config_manifest, job_manifest):
        metadata = manifest.setdefault("metadata", {})
        if not isinstance(metadata, dict):
            raise RuntimeError("generated in-place GPU driver refresh metadata is invalid.")
        annotations = metadata.setdefault("annotations", {})
        if not isinstance(annotations, dict):
            raise RuntimeError("generated in-place GPU driver refresh annotations are invalid.")
        annotations.update(binding_annotations)
    pod_metadata = _mapping(_mapping(job_manifest.get("spec")).get("template")).get("metadata")
    if not isinstance(pod_metadata, dict):
        raise RuntimeError("generated in-place GPU driver refresh Pod metadata is invalid.")
    pod_annotations = pod_metadata.setdefault("annotations", {})
    if not isinstance(pod_annotations, dict):
        raise RuntimeError("generated in-place GPU driver refresh Pod annotations are invalid.")
    pod_annotations.update(binding_annotations)
    config_name = str(_mapping(config_manifest.get("metadata")).get("name") or "")
    job_name = str(_mapping(job_manifest.get("metadata")).get("name") or "")
    desired_binding = {
        "schema": "nebius-cxcli/in-place-gpu-driver-refresh-v1",
        "target_ref_sha256": binding_annotations["nebius.ai/cxcli-target-ref-sha256"],
        "active_pvc": active_pvc,
        "active_pvc_uid": active_pvc_uid,
        "selected_node": selected_node_name,
        "selected_node_uid": selected_node_uid,
        "replacement_node_uids": sorted(replacement_uids),
        "fleet_sha256": fleet_fingerprint,
        "image": immutable_image,
        "config_map": config_name,
        "job": job_name,
        "config_contract_sha256": _fingerprint(
            _jail_gpu_post_population_resource_contract(config_manifest)
        ),
        "job_contract_sha256": _fingerprint(
            _jail_gpu_post_population_resource_contract(job_manifest)
        ),
    }
    state = phase.setdefault("in_place_gpu_driver_refresh", {})
    if not isinstance(state, dict):
        raise RuntimeError("In-place GPU driver refresh journal must be a mapping.")
    if state and _mapping(state.get("binding")) != desired_binding:
        raise RuntimeError(
            "recovery-required: in-place GPU driver refresh binding changed after intent."
        )
    config_exists, live_config = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"configmap/{config_name}",
    )
    job_exists, live_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"job/{job_name}",
    )
    cleanup = state.get("cleanup")
    if cleanup is not None and not isinstance(cleanup, dict):
        raise RuntimeError("In-place GPU driver refresh cleanup journal must be a mapping.")
    cleanup = cleanup if isinstance(cleanup, dict) else {}
    if state.get("status") == "verified-clean":
        if config_exists or job_exists:
            raise RuntimeError(
                "recovery-required: cleaned in-place GPU driver refresh resources "
                "reappeared after exact deletion."
            )
        return [
            "In-place GPU provider rollout reused its verified active Jail driver "
            "evidence after exact temporary resource cleanup."
        ]
    if cleanup.get("status") == "pending":
        expected_config_uid = str(cleanup.get("config_map_uid") or "").strip()
        expected_job_uid = str(cleanup.get("job_uid") or "").strip()
        if not expected_config_uid or not expected_job_uid:
            raise RuntimeError("In-place GPU driver refresh cleanup lacks exact resource UIDs.")
        cleanup_targets = (
            (
                config_exists,
                live_config,
                expected_config_uid,
                str(cleanup.get("config_map_resource_version") or "").strip(),
                f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/configmaps/{config_name}",
                "Background",
            ),
            (
                job_exists,
                live_job,
                expected_job_uid,
                str(cleanup.get("job_resource_version") or "").strip(),
                f"/apis/batch/v1/namespaces/{_SOPERATOR_NAMESPACE}/jobs/{job_name}",
                "Foreground",
            ),
        )
        for exists, live_resource, expected_uid, resource_version, api_path, policy in reversed(
            cleanup_targets
        ):
            if not exists:
                continue
            live_metadata = _mapping(live_resource.get("metadata"))
            if str(live_metadata.get("uid") or "").strip() != expected_uid:
                raise RuntimeError(
                    "recovery-required: in-place GPU driver refresh cleanup resource UID "
                    "changed after intent."
                )
            _command_runner_uid_preconditioned_delete(
                command_runner,
                kube_context=kube_context,
                api_path=api_path,
                uid=expected_uid,
                resource_version=resource_version,
                propagation_policy=policy,
                timeout_seconds=300,
                allow_not_found=True,
            )
        cleanup.update({"status": "completed", "completed_at": _utc_now()})
        state["status"] = "verified-clean"
        checkpoint_writer()
        return [
            "In-place GPU provider rollout refreshed the active Jail driver and removed "
            "its exact temporary Job and ConfigMap after verification."
        ]
    if not state:
        state.update(
            {
                "status": "intent-recorded",
                "binding": desired_binding,
                "intent_recorded_at": _utc_now(),
            }
        )
        checkpoint_writer()
    if not config_exists and not job_exists:
        _kubectl_apply_objects(
            command_runner=command_runner,
            kube_context=kube_context,
            objects=(config_manifest, job_manifest),
            timeout_seconds=300,
        )
        config_exists, live_config = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource=f"configmap/{config_name}",
        )
        job_exists, live_job = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource=f"job/{job_name}",
        )
    config_uid = str(_mapping(live_config.get("metadata")).get("uid") or "").strip()
    job_uid = str(_mapping(live_job.get("metadata")).get("uid") or "").strip()
    expected_config_uid = str(state.get("config_map_uid") or "").strip()
    expected_job_uid = str(state.get("job_uid") or "").strip()
    if (
        not config_exists
        or not job_exists
        or not config_uid
        or not job_uid
        or (expected_config_uid and config_uid != expected_config_uid)
        or (expected_job_uid and job_uid != expected_job_uid)
        or not _desired_manifest_contract_matches(live_config, config_manifest)
        or not _desired_manifest_contract_matches(live_job, job_manifest)
    ):
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh resources are missing or differ from their "
            "checkpointed exact contracts."
        )
    if not expected_job_uid:
        state.update(
            {
                "status": "running",
                "config_map_uid": config_uid,
                "job_uid": job_uid,
                "accepted_at": _utc_now(),
            }
        )
        checkpoint_writer()
    _wait_for_job_complete_or_failed(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        name=job_name,
        timeout_seconds=600,
        job_label="In-place GPU driver refresh Job",
    )
    job_exists, live_job = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource=f"job/{job_name}",
    )
    if (
        not job_exists
        or str(_mapping(live_job.get("metadata")).get("uid") or "") != job_uid
        or not _job_condition_true(live_job, "Complete")
        or _job_condition_true(live_job, "Failed")
        or not _desired_manifest_contract_matches(live_job, job_manifest)
    ):
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh Job did not retain exact successful completion."
        )
    pod_evidence = _jail_gpu_post_population_job_pod(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        job_name=job_name,
        job_uid=job_uid,
        image_lock=image_lock,
    )
    if pod_evidence.get("node_name") != selected_node_name:
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh Job ran outside its exact replacement Node UID binding."
        )
    logs = command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "logs",
            f"job/{job_name}",
        ],
        timeout_seconds=120,
        check=False,
    )
    success = re.search(
        r"(?m)^gpu-jail-post-population: driver=([0-9]+(?:\.[0-9]+)*) "
        r"visible_gpus=([1-9][0-9]*) status=passed$",
        logs.stdout,
    )
    if logs.returncode != 0 or success is None:
        raise SoperatorMigrationPhasePending(
            "In-place GPU driver refresh Job lacks canonical success evidence."
        )
    state.update(
        {
            "status": "verified",
            "driver_version": success.group(1),
            "visible_gpu_count": int(success.group(2)),
            "pod": pod_evidence,
            "log_sha256": hashlib.sha256(logs.stdout.encode()).hexdigest(),
            "verified_at": state.get("verified_at") or _utc_now(),
        }
    )
    checkpoint_writer()
    live_config_metadata = _mapping(live_config.get("metadata"))
    live_job_metadata = _mapping(live_job.get("metadata"))
    cleanup.update(
        {
            "status": "pending",
            "config_map_uid": config_uid,
            "config_map_resource_version": str(
                live_config_metadata.get("resourceVersion") or ""
            ).strip(),
            "job_uid": job_uid,
            "job_resource_version": str(live_job_metadata.get("resourceVersion") or "").strip(),
            "recorded_at": cleanup.get("recorded_at") or _utc_now(),
        }
    )
    state["cleanup"] = cleanup
    checkpoint_writer()
    for api_path, uid, resource_version, policy in (
        (
            f"/apis/batch/v1/namespaces/{_SOPERATOR_NAMESPACE}/jobs/{job_name}",
            job_uid,
            str(cleanup.get("job_resource_version") or ""),
            "Foreground",
        ),
        (
            f"/api/v1/namespaces/{_SOPERATOR_NAMESPACE}/configmaps/{config_name}",
            config_uid,
            str(cleanup.get("config_map_resource_version") or ""),
            "Background",
        ),
    ):
        _command_runner_uid_preconditioned_delete(
            command_runner,
            kube_context=kube_context,
            api_path=api_path,
            uid=uid,
            resource_version=resource_version,
            propagation_policy=policy,
            timeout_seconds=300,
            allow_not_found=True,
        )
    cleanup.update({"status": "completed", "completed_at": _utc_now()})
    state["status"] = "verified-clean"
    checkpoint_writer()
    return [
        "In-place GPU provider rollout refreshed the active Jail driver evidence once "
        "from an exact replacement Node UID and removed its exact temporary Job and "
        "ConfigMap; every worker init guard must still verify the shared contract before "
        "becoming Ready."
    ]


def _verify_in_place_worker_replacement_health(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Prove replacement worker health before releasing any per-group Slurm drain."""

    values = _patch_target_values_for_compute(
        payload=payload,
        target_ref=target_ref,
        checkpoint=checkpoint,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    handoff = _mapping(
        _accepted_populate_jail_phase_state(checkpoint).get("rootfs_handoff_verification")
    )
    accepted_active_slot = str(handoff.get("active_slot", "") or "").strip()
    slots = active_passive_jail_rootfs_slots(values)
    if slots.active_slot != accepted_active_slot:
        if slots.passive_slot != accepted_active_slot:
            raise SoperatorMigrationPhasePending(
                "In-place replacement health cannot reconstruct the accepted active Jail "
                "slot from target values; worker Slurm drains remain held."
            )
        values = switch_active_passive_jail_rootfs_values(values)
        slots = active_passive_jail_rootfs_slots(values)
    lines = _ensure_in_place_gpu_driver_refresh_after_provider_rollout(
        checkpoint=checkpoint,
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        target_ref=target_ref,
        values=values,
        active_pvc=slots.active_pvc,
        checkpoint_writer=checkpoint_writer,
    )
    _wait_for_target_worker_nodesets_ready(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
        timeout_seconds=1800,
    )
    rootfs_checks = _verify_target_rootfs_handoff_consumers(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
    )
    phase["in_place_rootfs_consumer_checks"] = rootfs_checks
    if any(check.get("status") != "verified" for check in rootfs_checks):
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            _rootfs_handoff_pending_reason(rootfs_checks) + " Worker Slurm drains remain held."
        )
    mount_checks = _live_home_mount_probe_checks(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
        target_ref=target_ref,
    )
    phase["in_place_persistent_mount_checks"] = list(mount_checks)
    if _fast_verification_failed(mount_checks):
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            _live_home_mount_pending_reason(mount_checks) + " Worker Slurm drains remain held."
        )
    gpu_gate_key = "in_place_gpu_workload_release_gate"
    lines.extend(
        _ensure_gpu_worker_jail_release_gate(
            checkpoint=checkpoint,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            values=values,
            checkpoint_writer=checkpoint_writer,
            gate_key=gpu_gate_key,
        )
    )
    if _gpu_worker_nodeset_names(values):
        lines.extend(
            _release_in_place_worker_locks_for_gpu_smoke(
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                values=values,
                checkpoint_writer=checkpoint_writer,
            )
        )
    lines.extend(
        _ensure_jail_gpu_post_activation_gate(
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            values=values,
            checkpoint_writer=checkpoint_writer,
            release_gate_key=gpu_gate_key,
            replacement_phase=phase,
            mutation_guard=None,
        )
    )
    phase["in_place_worker_replacement_health"] = {
        "status": "passed",
        "active_slot": accepted_active_slot,
        "rootfs_consumers": len(rootfs_checks),
        "persistent_mount_checks": len(mount_checks),
        "verified_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        f"In-place replacement workers are Ready with {accepted_active_slot} Jail consumers, "
        "persistent mounts, GPU runtime (when applicable), and healthy Slurm registration.",
        *lines,
    ]


def _release_in_place_worker_locks_for_gpu_smoke(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    values: Mapping[str, Any],
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Release owned node drains only while exact production partitions remain DOWN."""

    gate = phase.setdefault("in_place_gpu_smoke_scheduling_gate", {})
    if not isinstance(gate, dict):
        raise RuntimeError("In-place GPU smoke scheduling gate must be a mapping.")
    gate.clear()
    gate.update({"status": "checking", "checked_at": _utc_now(), "partitions": []})
    if checkpoint_writer is not None:
        checkpoint_writer()

    def _fail(reason: str) -> NoReturn:
        gate.update({"status": "failed", "reason": reason, "checked_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(reason)

    if phase.get("slurm_scheduling_pause") is not True:
        _fail(
            "In-place GPU smoke requires the continuous Slurm scheduling pause before "
            "cxcli-owned worker drains can be released."
        )
    records = _rolling_compute_checkpoint_pause_records(phase)
    if not records:
        _fail(
            "In-place GPU smoke requires exact checkpointed production partition pause "
            "records before cxcli-owned worker drains can be released."
        )
    partition_configuration = _mapping(values.get("partitionConfiguration"))
    raw_target_partitions = partition_configuration.get("partitions")
    if not isinstance(raw_target_partitions, Sequence) or isinstance(
        raw_target_partitions,
        (str, bytes, bytearray),
    ):
        _fail(
            "In-place GPU smoke requires the canonical target partitionConfiguration "
            "before cxcli-owned worker drains can be released."
        )
    target_partition_names: set[str] = set()
    for raw_partition in raw_target_partitions:
        if not isinstance(raw_partition, Mapping):
            _fail("In-place GPU smoke found a malformed canonical target partition entry.")
        name = str(raw_partition.get("name") or "").strip()
        if not name or name in target_partition_names:
            _fail("In-place GPU smoke requires unique non-empty canonical target partition names.")
        target_partition_names.add(name)
    gate["target_partitions"] = sorted(target_partition_names)
    gate["target_partitions_sha256"] = _fingerprint(sorted(target_partition_names))
    live_partitions = {
        item.name: item
        for item in _external_upgrade_partition_state_snapshot(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    }
    partition_evidence: list[dict[str, Any]] = []
    retired_partitions: list[str] = []
    for record in records:
        if (
            record.applied_state != "DOWN"
            or not record.applied_record
            or not record.applied_record_fingerprint
        ):
            _fail(
                f"In-place GPU smoke partition {record.partition!r} lacks exact durable "
                "State=DOWN ownership evidence."
            )
        live = live_partitions.get(record.partition)
        if live is None:
            if record.partition in target_partition_names:
                _fail(
                    f"In-place GPU smoke cannot verify canonical target partition "
                    f"{record.partition!r} because it is absent from the full live "
                    "partition snapshot."
                )
            retired_partitions.append(record.partition)
            partition_evidence.append(
                {
                    "partition": record.partition,
                    "status": "retired-from-target",
                    "target_configured": False,
                    "record_fingerprint": record.applied_record_fingerprint,
                }
            )
            gate["partitions"] = list(partition_evidence)
            gate["retired_partitions"] = sorted(retired_partitions)
            if checkpoint_writer is not None:
                checkpoint_writer()
            continue
        if not _slurm_partition_observation_matches(
            live,
            record=record.applied_record,
            fingerprint=record.applied_record_fingerprint,
        ):
            _fail(
                f"In-place GPU smoke will not release worker drains because production "
                f"partition {record.partition!r} no longer matches cxcli's exact "
                "State=DOWN record."
            )
        if record.partition not in target_partition_names:
            retired_partitions.append(record.partition)
        partition_evidence.append(
            {
                "partition": record.partition,
                "status": "down",
                "target_configured": record.partition in target_partition_names,
                "state": record.applied_state,
                "record_fingerprint": record.applied_record_fingerprint,
            }
        )
        gate["partitions"] = list(partition_evidence)
        if checkpoint_writer is not None:
            checkpoint_writer()

    groups = phase.get("in_place_node_groups")
    if not isinstance(groups, Mapping):
        _fail("In-place GPU smoke requires the exact worker node-group journal.")
    pending_groups = [
        state
        for state in groups.values()
        if isinstance(state, dict) and state.get("status") == "provider-complete-health-pending"
    ]
    if not pending_groups:
        _fail("In-place GPU smoke found no replacement worker group awaiting health proof.")
    lines: list[str] = []
    for group_state in pending_groups:
        lines.extend(
            _restore_in_place_worker_group_lock(
                group_state=group_state,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
    gate.update(
        {
            "status": "passed",
            "partitions": partition_evidence,
            "retired_partitions": sorted(retired_partitions),
            "released_worker_groups": len(pending_groups),
            "verified_at": _utc_now(),
        }
    )
    gate.pop("reason", None)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Canonical target Slurm partitions remain exactly DOWN and source-era "
        "partitions absent from the target configuration remain retired; released "
        "cxcli-owned worker drains for the root-only GPU smoke.",
        *lines,
    ]


def _verify_in_place_service_role_replacement_health(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    role: str,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    shared_evidence: dict[str, Any] | None = None,
) -> list[str]:
    """Prove serial service-role replacement without weakening Jail/controller health."""

    started_at = time.monotonic()
    values = _patch_target_values_for_compute(
        payload=payload,
        target_ref=target_ref,
        checkpoint=checkpoint,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    handoff = _mapping(
        _accepted_populate_jail_phase_state(checkpoint).get("rootfs_handoff_verification")
    )
    accepted_active_slot = str(handoff.get("active_slot", "") or "").strip()
    slots = active_passive_jail_rootfs_slots(values)
    if slots.active_slot != accepted_active_slot:
        if slots.passive_slot != accepted_active_slot:
            raise SoperatorMigrationPhasePending(
                f"In-place {role} replacement cannot reconstruct the accepted active "
                "Jail slot; continuity resources remain active."
            )
        values = switch_active_passive_jail_rootfs_values(values)
        slots = active_passive_jail_rootfs_slots(values)
    bridge_stage = str(_mapping(checkpoint.get("controller_bridge")).get("stage") or "")
    reusable = bool(
        isinstance(shared_evidence, Mapping)
        and shared_evidence.get("status") == "passed"
        and shared_evidence.get("target_ref") == target_ref
        and shared_evidence.get("active_slot") == accepted_active_slot
        and shared_evidence.get("bridge_stage") == bridge_stage
    )
    if reusable:
        rootfs_checks = copy.deepcopy(list(shared_evidence.get("rootfs_checks") or []))
        alias_checks = copy.deepcopy(list(shared_evidence.get("alias_checks") or []))
        mount_checks = tuple(copy.deepcopy(list(shared_evidence.get("mount_checks") or [])))
    else:
        rootfs_checks = _verify_target_rootfs_handoff_consumers(
            command_runner=command_runner,
            kube_context=kube_context,
            values=values,
        )
        _wait_for_target_slurmcluster_available(
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            timeout_seconds=900,
        )
        live_cluster = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "slurmcluster",
                target_ref,
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        if not _mapping(live_cluster.get("metadata")):
            raise SoperatorMigrationPhasePending(
                f"In-place {role} replacement cannot prove the live target SlurmCluster; "
                "continuity resources remain active."
            )
        alias_checks = _verify_target_jail_alias_consumers(
            command_runner=command_runner,
            kube_context=kube_context,
            slurmcluster=live_cluster,
            rootfs_pvc=slots.active_pvc,
            wait_for_rollout=True,
            controller_bridge_active=bridge_stage
            in {BridgeStage.SOURCE_HA_ACTIVE.value, BridgeStage.TARGET_HA_ACTIVE.value},
        )
        mount_checks = _live_home_mount_probe_checks(
            command_runner=command_runner,
            kube_context=kube_context,
            values=values,
            target_ref=target_ref,
        )
    proof_payload = {
        "target_ref": target_ref,
        "active_slot": accepted_active_slot,
        "bridge_stage": bridge_stage,
        "rootfs_checks": rootfs_checks,
        "alias_checks": alias_checks,
        "mount_checks": list(mount_checks),
    }
    proof_sha256 = _fingerprint(proof_payload)
    service_health = phase.setdefault("in_place_service_role_health", {})
    if not isinstance(service_health, dict):
        raise RuntimeError("In-place service-role health journal must be a mapping.")
    role_health = service_health.setdefault(role, {})
    if not isinstance(role_health, dict):
        raise RuntimeError(f"In-place {role} service-role health must be a mapping.")
    if role_health.get("status") == "passed" and str(role_health.get("verified_at") or "").strip():
        role_health["last_passed"] = {
            "proof_sha256": role_health.get("proof_sha256"),
            "verified_at": role_health.get("verified_at"),
        }
    role_health.update(
        {
            "status": "checking",
            "active_slot": accepted_active_slot,
            "rootfs_consumer_checks": rootfs_checks,
            "jail_alias_consumer_checks": alias_checks,
            "persistent_mount_checks": list(mount_checks),
            "evidence_source": "invocation-reuse" if reusable else "live",
            "proof_sha256": proof_sha256,
            "elapsed_seconds": round(time.monotonic() - started_at, 3),
            "checked_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    if any(check.get("status") != "verified" for check in rootfs_checks):
        raise SoperatorMigrationPhasePending(
            _rootfs_handoff_pending_reason(rootfs_checks)
            + f" The replaced {role} group remains behind continuity resources."
        )
    controller_alias = next(
        (check for check in alias_checks if check.get("name") == "controller"),
        None,
    )
    if controller_alias is None or any(check.get("status") != "verified" for check in alias_checks):
        raise SoperatorMigrationPhasePending(
            _jail_alias_consumer_pending_reason(alias_checks)
            + f" The replaced {role} group remains behind continuity resources."
        )
    if _fast_verification_failed(mount_checks):
        raise SoperatorMigrationPhasePending(
            _live_home_mount_pending_reason(mount_checks)
            + f" The replaced {role} group remains behind continuity resources."
        )
    if shared_evidence is not None and not reusable:
        shared_evidence.clear()
        shared_evidence.update(
            {
                "status": "passed",
                **copy.deepcopy(proof_payload),
                "proof_sha256": proof_sha256,
            }
        )
    verified_at = _utc_now()
    role_health.update(
        {
            "status": "passed",
            "verified_at": verified_at,
            "last_passed": {
                "proof_sha256": proof_sha256,
                "verified_at": verified_at,
            },
        }
    )
    replay = phase.setdefault("in_place_service_health_replay", {})
    if not isinstance(replay, dict):
        raise RuntimeError("In-place service health replay telemetry must be a mapping.")
    replay_roles = replay.setdefault("roles", {})
    if not isinstance(replay_roles, dict):
        raise RuntimeError("In-place service health replay roles must be a mapping.")
    replay_roles[role] = {
        "evidence_source": "invocation-reuse" if reusable else "live",
        "proof_sha256": proof_sha256,
        "elapsed_seconds": role_health["elapsed_seconds"],
        "checked_at": role_health["checked_at"],
    }
    replay.update(
        {
            "status": "passed",
            "last_proof_sha256": proof_sha256,
            "last_role": role,
            "updated_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        f"In-place {role} replacement verified on Jail {accepted_active_slot} with "
        "controller aliases and persistent mounts."
    ]


def _in_place_completed_service_health_reusable(
    *,
    group_state: Mapping[str, Any],
    role_health: Mapping[str, Any],
) -> bool:
    """Reuse only a health proof recorded after the terminal provider replacement."""

    if group_state.get("status") != "completed":
        return False
    last_passed = _mapping(role_health.get("last_passed"))
    verified_at = str(
        last_passed.get("verified_at") or role_health.get("verified_at") or ""
    ).strip()
    operation = _mapping(_mapping(group_state.get("target_update")).get("operation"))
    if operation.get("attempt_state") != "provider-terminal" or not verified_at:
        return False
    provider_terminal_at = str(
        operation.get("terminal_at")
        or operation.get("reconciled_at")
        or operation.get("accepted_at")
        or ""
    ).strip()
    if not provider_terminal_at:
        return False
    try:
        return _journal_timestamp(
            verified_at,
            field="service health verified_at",
        ) >= _journal_timestamp(
            provider_terminal_at,
            field="provider terminal_at",
        )
    except RuntimeError:
        return False


def _in_place_worker_outage_boundary_active(phase: Mapping[str, Any]) -> bool:
    """Return whether an exact worker rollout is accepted or awaiting health."""

    for state in _mapping(phase.get("in_place_node_groups")).values():
        if not isinstance(state, Mapping) or not str(state.get("role") or "").startswith("worker"):
            continue
        operation = _mapping(_mapping(state.get("target_update")).get("operation"))
        if not (
            _provider_operation_id_is_real(operation.get("provider_operation_id"))
            and str(operation.get("accepted_at") or "").strip()
        ):
            continue
        if (
            operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES
            or state.get("status") == "provider-complete-health-pending"
        ):
            return True
    return False


_IN_PLACE_ACCOUNTING_CATALOG_COMMANDS: Mapping[str, tuple[str, ...]] = {
    "accounts": (
        "sacctmgr",
        "-nP",
        "show",
        "account",
        "format=account,description,organization",
    ),
    "users": ("sacctmgr", "-nP", "show", "user", "format=user,defaultaccount,adminlevel"),
    "associations": (
        "sacctmgr",
        "-nP",
        "show",
        "assoc",
        "format=cluster,account,user,partition,qos",
    ),
    "qos": (
        "sacctmgr",
        "-nP",
        "show",
        "qos",
        "format=name,priority,grptres,maxjobs,maxsubmit",
    ),
}


def _in_place_accounting_catalog_evidence(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    evidence: dict[str, Any] = {}
    for name, args in _IN_PLACE_ACCOUNTING_CATALOG_COMMANDS.items():
        result = _kubectl_exec_login(
            command_runner=command_runner,
            kube_context=kube_context,
            args=args,
            check=False,
            timeout_seconds=120,
        )
        if result.returncode != 0:
            raise SoperatorMigrationPhasePending(
                f"in-place accounting continuity could not read {name}: " + _command_detail(result)
            )
        rows = sorted({line.strip() for line in result.stdout.splitlines() if line.strip()})
        evidence[name] = {
            "row_count": len(rows),
            "sha256": hashlib.sha256("\n".join(rows).encode("utf-8")).hexdigest(),
        }
    return evidence


def _in_place_accounting_continuity_evidence(
    *,
    phase: Mapping[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> dict[str, Any]:
    handoff = _mapping(phase.get("accounting_handoff"))
    cluster_name = str(
        handoff.get("target_cluster_name") or handoff.get("source_cluster_name") or target_ref
    ).strip()
    resource_name = str(handoff.get("target_resource_name") or target_ref).strip()
    identity = _accounting_handoff_mariadb_pod_identity(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=f"{resource_name}-acct-db-0",
    )
    history = _accounting_handoff_history_evidence(
        command_runner=command_runner,
        kube_context=kube_context,
        pod_name=identity["pod"],
        source_cluster_name=cluster_name,
    )
    registrations = _accounting_handoff_slurm_registration_details(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    return {
        "cluster_name": cluster_name,
        "resource_name": resource_name,
        "writer_identity": identity,
        "history": history,
        "registrations": registrations,
        "catalogs": _in_place_accounting_catalog_evidence(
            command_runner=command_runner,
            kube_context=kube_context,
        ),
        "observed_at": _utc_now(),
    }


def _verify_in_place_accounting_continuity(
    *,
    baseline: Mapping[str, Any],
    observed: Mapping[str, Any],
) -> None:
    baseline_identity = _mapping(baseline.get("writer_identity"))
    observed_identity = _mapping(observed.get("writer_identity"))
    persistent_identity_keys = tuple(
        key for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS if key != "pod_uid"
    )
    if any(
        baseline_identity.get(key) != observed_identity.get(key) for key in persistent_identity_keys
    ):
        raise SoperatorMigrationPhasePending(
            "in-place accounting replacement changed MariaDB, SlurmCluster, StatefulSet, "
            "or PVC ownership identity."
        )
    if any(
        baseline.get(field) != observed.get(field)
        for field in ("cluster_name", "resource_name")
        if field in baseline
    ):
        raise SoperatorMigrationPhasePending(
            "in-place accounting replacement changed checkpointed cluster/resource identity."
        )
    baseline_history = _mapping(baseline.get("history"))
    observed_history = _mapping(observed.get("history"))
    for field, baseline_value in baseline_history.items():
        observed_value = observed_history.get(field)
        if (
            isinstance(baseline_value, bool)
            or isinstance(observed_value, bool)
            or not isinstance(baseline_value, int)
            or not isinstance(observed_value, int)
            or baseline_value < 0
            or observed_value < baseline_value
        ):
            raise SoperatorMigrationPhasePending(
                "in-place accounting replacement lost or regressed checkpointed "
                f"history evidence for {field}."
            )
    if to_plain_data(baseline.get("catalogs")) != to_plain_data(observed.get("catalogs")):
        raise SoperatorMigrationPhasePending(
            "in-place accounting replacement changed checkpointed catalogs evidence."
        )
    baseline_registrations = _mapping(baseline.get("registrations"))
    observed_registrations = _mapping(observed.get("registrations"))
    if set(baseline_registrations) != set(observed_registrations):
        raise SoperatorMigrationPhasePending(
            "in-place accounting replacement changed checkpointed registrations evidence."
        )
    for name, baseline_registration in baseline_registrations.items():
        before = _mapping(baseline_registration)
        after = _mapping(observed_registrations.get(name))
        stable_fields = set(before) | set(after)
        stable_fields.discard("control_host")
        if any(before.get(field) != after.get(field) for field in stable_fields) or bool(
            str(before.get("control_host", "") or "").strip()
        ) != bool(str(after.get("control_host", "") or "").strip()):
            raise SoperatorMigrationPhasePending(
                "in-place accounting replacement changed checkpointed registrations evidence."
            )


def _controller_bridge_primary_role_from_ping(
    *,
    journal: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
    roles = _sequence_of_mappings(journal.get("controller_roles"))
    if len(roles) != 2:
        raise SoperatorMigrationPhasePending(
            "opposite-domain controller authority requires exactly two journaled bridge roles."
        )
    # Authority must be observed from an exact target client.  The generic
    # read-only Slurm helper may reuse a cached controller route whose local
    # slurm.conf intentionally differs while the target command gate is
    # active.  Such a controller-local view can report the live bridge pair as
    # backups even though target clients correctly use one bridge primary.
    result = _kubectl_exec_login_once(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "ping"),
        timeout_seconds=120,
    )
    if result.returncode != 0:
        raise SoperatorMigrationPhasePending(
            "opposite-domain controller authority could not run scontrol ping: "
            + _command_detail(result)
        )
    primary_hosts = re.findall(
        r"Slurmctld\(primary\)\s+at\s+([^\s]+)\s+is\s+UP",
        result.stdout,
        flags=re.IGNORECASE,
    )
    active = [
        role
        for role in roles
        if any(str(host).startswith(str(role.get("pod_name", "") or "")) for host in primary_hosts)
    ]
    if len(active) != 1:
        raise SoperatorMigrationPhasePending(
            "opposite-domain controller authority did not prove one exact primary bridge Pod."
        )
    standby = [role for role in roles if role is not active[0]]
    return active[0], standby[0]


def _ensure_in_place_target_manager_paused(
    *,
    phase: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    required: bool = True,
    authority_role: str = "target",
) -> list[str]:
    manager = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "deployment",
            "soperator-manager",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    manager_metadata = _mapping(manager.get("metadata"))
    if not manager_metadata:
        if not required:
            return []
        raise SoperatorMigrationPhasePending(
            "bridge-owned controller authority requires deployment/soperator-manager."
        )
    manager_pause = phase.setdefault("in_place_target_manager_pause", {})
    if not isinstance(manager_pause, dict):
        raise RuntimeError("In-place target manager pause journal must be a mapping.")
    manager_replicas = _resource_replicas(manager, default=-1)
    if manager_replicas < 0:
        raise SoperatorMigrationPhasePending(
            "bridge-owned controller authority could not resolve the Soperator manager "
            "replica contract."
        )
    original_replicas = _non_negative_int(
        manager_pause.get("original_replicas"),
        fallback=manager_replicas if manager_replicas > 0 else 1,
    )
    if manager_replicas > 0:
        manager_resource_version = str(manager_metadata.get("resourceVersion", "") or "").strip()
        if not manager_resource_version:
            raise SoperatorMigrationPhasePending(
                "target Soperator manager pause requires a live resourceVersion."
            )
        manager_patch = [
            {
                "op": "test",
                "path": "/metadata/resourceVersion",
                "value": manager_resource_version,
            },
            {"op": "replace", "path": "/spec/replicas", "value": 0},
        ]
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "patch",
                "deployment",
                "soperator-manager",
                "--type",
                "json",
                "-p",
                json.dumps(manager_patch, sort_keys=True, separators=(",", ":")),
            ],
            timeout_seconds=120,
        )
        manager_pause.update(
            {
                "status": "accepted",
                "deployment_uid": str(manager_metadata.get("uid", "") or ""),
                "original_replicas": original_replicas,
                "resource_version": manager_resource_version,
                "accepted_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            f"paused the {authority_role} Soperator manager so it cannot overwrite bridge-owned "
            "client configuration or the controller command gate; resume after its Pod "
            "terminates."
        )
    manager_status = _mapping(manager.get("status"))
    if any(
        _non_negative_int(manager_status.get(field), fallback=0) > 0
        for field in ("replicas", "readyReplicas", "availableReplicas")
    ):
        manager_pause["status"] = "terminating"
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "target Soperator manager pause is accepted, but its Pod is still terminating."
        )
    manager_pause.update(
        {
            "status": "verified",
            "deployment_uid": str(manager_metadata.get("uid", "") or ""),
            "original_replicas": original_replicas,
            "verified_at": _utc_now(),
        }
    )
    return [f"In-place controller safety: {authority_role} Soperator manager pause verified."]


def _restore_in_place_target_manager_after_singleton_handoff(
    *,
    checkpoint: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Restore the exact manager only after target singleton authority is durable."""

    journal = _mapping(checkpoint.get("controller_bridge"))
    manager_pause = journal.get("in_place_target_manager_pause")
    if not isinstance(manager_pause, dict) or not manager_pause:
        phase_state = checkpoint.get("phase_state")
        if not isinstance(phase_state, dict):
            return []
        retire_phase = phase_state.get("retire-old-resources")
        if not isinstance(retire_phase, dict):
            return []
        manager_pause = retire_phase.get("in_place_target_manager_pause")
    if not isinstance(manager_pause, dict) or not manager_pause:
        return []
    if manager_pause.get("status") == "restored":
        return ["Target Soperator manager restore reused from the retirement journal."]
    if str(journal.get("stage") or "") not in {
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
        BridgeStage.CLEANED.value,
    }:
        raise SoperatorMigrationPhasePending(
            "target Soperator manager restore requires the durable target-singleton handoff."
        )
    manager = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "deployment/soperator-manager",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    metadata = _mapping(manager.get("metadata"))
    manager_uid = str(metadata.get("uid", "") or "").strip()
    resource_version = str(metadata.get("resourceVersion", "") or "").strip()
    recorded_uid = str(manager_pause.get("deployment_uid", "") or "").strip()
    original_replicas = _positive_int(manager_pause.get("original_replicas"), fallback=0)
    replicas = _resource_replicas(manager, default=-1)
    if (
        not manager_uid
        or not resource_version
        or not recorded_uid
        or manager_uid != recorded_uid
        or original_replicas <= 0
        or replicas not in {0, original_replicas}
    ):
        raise RuntimeError(
            "recovery-required: target Soperator manager identity or replica contract "
            "changed while its checkpointed pause was active."
        )
    restore = manager_pause.setdefault("restore", {})
    if not isinstance(restore, dict):
        raise RuntimeError("Target Soperator manager restore journal must be mutable.")
    restore.update(
        {
            "schema": "nebius-cxcli/target-manager-restore-v1",
            "deployment_uid": manager_uid,
            "replicas": original_replicas,
            "intent_at": str(restore.get("intent_at") or _utc_now()),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    if replicas == 0:
        patch = [
            {"op": "test", "path": "/metadata/uid", "value": manager_uid},
            {
                "op": "test",
                "path": "/metadata/resourceVersion",
                "value": resource_version,
            },
            {
                "op": "replace",
                "path": "/spec/replicas",
                "value": original_replicas,
            },
        ]
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "patch",
                "deployment/soperator-manager",
                "--type",
                "json",
                "-p",
                json.dumps(patch, sort_keys=True, separators=(",", ":")),
            ],
            timeout_seconds=120,
        )
        restore.update({"status": "accepted", "accepted_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "restored the exact target Soperator manager replica contract after singleton "
            "handoff; resume after its rollout becomes Available."
        )
    _kubectl_rollout_status(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="deployment/soperator-manager",
        timeout="10m",
    )
    manager = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "deployment/soperator-manager",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = _mapping(manager.get("metadata"))
    status = _mapping(manager.get("status"))
    generation = _positive_int(metadata.get("generation"), fallback=0)
    if (
        str(metadata.get("uid", "") or "") != manager_uid
        or _resource_replicas(manager, default=-1) != original_replicas
        or _non_negative_int(status.get("readyReplicas"), fallback=0) < original_replicas
        or _non_negative_int(status.get("availableReplicas"), fallback=0) < original_replicas
        or _non_negative_int(status.get("observedGeneration"), fallback=0) < generation
    ):
        raise SoperatorMigrationPhasePending(
            "target Soperator manager restore is accepted but not yet Available at the "
            "checkpointed replica contract."
        )
    restore.update({"status": "verified", "verified_at": _utc_now()})
    manager_pause.update(
        {
            "status": "restored",
            "restored_replicas": original_replicas,
            "restored_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return ["Target Soperator manager restored after target-singleton handoff."]


def _in_place_completed_worker_replacement_node_uids(
    phase: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return only terminal provider-backed replacement Kubernetes Node UIDs."""

    replacement_uids: list[str] = []
    for state in _mapping(phase.get("in_place_node_groups")).values():
        if not isinstance(state, Mapping) or not str(state.get("role", "") or "").startswith(
            "worker"
        ):
            continue
        accepted_size = _positive_int(state.get("accepted_fixed_size"), fallback=0)
        observed_uids = tuple(
            str(uid or "").strip()
            for uid in state.get("replacement_node_uids", []) or []
            if str(uid or "").strip()
        )
        operation = _mapping(_mapping(state.get("target_update")).get("operation"))
        if (
            state.get("status") not in {"provider-complete-health-pending", "completed"}
            or operation.get("attempt_state") != "provider-terminal"
            or accepted_size <= 0
            or len(observed_uids) != accepted_size
            or len(set(observed_uids)) != accepted_size
        ):
            continue
        replacement_uids.extend(observed_uids)
    return tuple(sorted(set(replacement_uids)))


def _in_place_completed_role_replacement_node_uids(
    phase: Mapping[str, Any], *, role: str
) -> tuple[str, ...]:
    """Return terminal provider replacement Node UIDs for one exact service role."""

    replacement_uids: list[str] = []
    for state in _mapping(phase.get("in_place_node_groups")).values():
        if not isinstance(state, Mapping) or str(state.get("role", "") or "") != role:
            continue
        accepted_size = _positive_int(state.get("accepted_fixed_size"), fallback=0)
        observed_uids = tuple(
            str(uid or "").strip()
            for uid in state.get("replacement_node_uids", []) or []
            if str(uid or "").strip()
        )
        operation = _mapping(_mapping(state.get("target_update")).get("operation"))
        if (
            state.get("status") != "completed"
            or operation.get("attempt_state") != "provider-terminal"
            or accepted_size <= 0
            or len(observed_uids) != accepted_size
            or len(set(observed_uids)) != accepted_size
        ):
            continue
        replacement_uids.extend(observed_uids)
    return tuple(sorted(set(replacement_uids)))


def _gpu_typed_gres_worker_pod_successors(
    checkpoint: Mapping[str, Any],
) -> dict[str, dict[str, str]]:
    """Bind only the exact verified typed-GRES worker Pod rollover lineage."""

    populate = _mapping(_mapping(checkpoint.get("phase_state")).get("populate-jail-refresh"))
    rollover = _mapping(populate.get("gpu_typed_gres_worker_rollover"))
    old_pods = _mapping(rollover.get("old_pods"))
    replacement_pods = _mapping(rollover.get("replacement_pods"))
    if (
        rollover.get("schema") != _GPU_TYPED_GRES_WORKER_ROLLOVER_SCHEMA
        or rollover.get("status") != "verified"
        or not str(rollover.get("verified_at", "") or "").strip()
        or not old_pods
        or set(old_pods) != set(replacement_pods)
    ):
        return {}
    successors: dict[str, dict[str, str]] = {}
    for name, old in old_pods.items():
        replacement = _mapping(replacement_pods.get(name))
        old_binding = _mapping(old)
        old_uid = str(old_binding.get("uid", "") or "").strip()
        replacement_uid = str(replacement.get("uid", "") or "").strip()
        node_name = str(old_binding.get("node", "") or "").strip()
        if (
            not old_uid
            or not replacement_uid
            or old_uid == replacement_uid
            or not node_name
            or str(replacement.get("node", "") or "") != node_name
            or str(old_binding.get("nodeset", "") or "")
            != str(replacement.get("nodeset", "") or "")
            or str(old_binding.get("statefulset_uid", "") or "")
            != str(replacement.get("statefulset_uid", "") or "")
        ):
            return {}
        successors[str(name)] = {
            "previous_uid": old_uid,
            "replacement_uid": replacement_uid,
            "node_name": node_name,
        }
    return successors


def _ensure_in_place_bridge_client_configuration(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    lines = _ensure_in_place_target_manager_paused(
        phase=phase,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            "in-place bridge client handoff requires the checkpointed controller bridge."
        )
    network_peer = journal.setdefault("target_network_peer", {})
    if not isinstance(network_peer, dict):
        raise RuntimeError("Controller bridge target network peer journal must be a mapping.")
    if not (
        network_peer.get("status") == "verified"
        and network_peer.get("cluster_names") == [target_ref]
    ):
        contract = journal.get("security_contract")
        bridge_security = _mapping(_mapping(contract).get("bridge"))
        if not isinstance(contract, dict) or not isinstance(bridge_security, dict):
            raise RuntimeError(
                "Controller bridge target network peer requires the mutable security contract."
            )
        bridge_namespace = str(bridge_security.get("namespace", "") or "")
        desired_policies = list(
            bridge_network_policy_objects(
                namespace=bridge_namespace,
                soperator_namespace=_SOPERATOR_NAMESPACE,
                soperator_cluster_name=str(
                    _mapping(journal.get("source_binding")).get("slurmcluster_name", "") or ""
                ),
                additional_soperator_cluster_names=(target_ref,),
                kubernetes_api_cidrs=tuple(
                    str(item or "") for item in contract.get("kubernetes_api_cidrs", [])
                ),
            )
        )
        expected_annotations = {
            _CONTROLLER_BRIDGE_CAMPAIGN_ANNOTATION: str(
                journal.get("campaign_fingerprint", "") or ""
            ),
            _CONTROLLER_BRIDGE_CLUSTER_ANNOTATION: str(journal.get("cluster_id", "") or ""),
        }
        for desired in desired_policies:
            desired_metadata = desired.setdefault("metadata", {})
            if not isinstance(desired_metadata, dict):  # pragma: no cover - static manifest
                raise AssertionError
            desired_metadata["annotations"] = expected_annotations
        required_policy = next(
            policy
            for policy in desired_policies
            if _mapping(policy.get("metadata")).get("name")
            == "cxcli-controller-bridge-required-traffic"
        )
        exists, live_required = _controller_bridge_live_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            identity={
                "kind": "NetworkPolicy",
                "namespace": bridge_namespace,
                "name": "cxcli-controller-bridge-required-traffic",
            },
        )
        live_metadata = _mapping(live_required.get("metadata"))
        resource_version = str(live_metadata.get("resourceVersion", "") or "").strip()
        if not exists or not resource_version:
            raise SoperatorMigrationPhasePending(
                "controller bridge target network peer requires the exact live "
                "required-traffic NetworkPolicy."
            )
        policy_patch = {
            "metadata": {"resourceVersion": resource_version},
            "spec": copy.deepcopy(dict(_mapping(required_policy.get("spec")))),
        }
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                bridge_namespace,
                "patch",
                "networkpolicy",
                "cxcli-controller-bridge-required-traffic",
                "--type",
                "merge",
                "-p",
                json.dumps(policy_patch, sort_keys=True, separators=(",", ":")),
            ],
            timeout_seconds=120,
        )
        policy_records = {
            str(item.get("name", "") or ""): item
            for item in _sequence_of_mappings(bridge_security.get("network_policies"))
        }
        live_policies: list[Mapping[str, Any]] = []
        for desired in desired_policies:
            name = str(_mapping(desired.get("metadata")).get("name", "") or "")
            live_exists, live = _controller_bridge_live_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                identity={
                    "kind": "NetworkPolicy",
                    "namespace": bridge_namespace,
                    "name": name,
                },
            )
            record = policy_records.get(name)
            if not live_exists or not isinstance(record, dict):
                raise RuntimeError(
                    "Controller bridge target network peer lost a journaled NetworkPolicy."
                )
            record["semantic_sha256"] = _controller_security_resources_sha256((live,))
            live_policies.append(live)
        bridge_security["network_policies_sha256"] = _controller_security_resources_sha256(
            live_policies
        )
        network_peer.update(
            {
                "status": "verified",
                "cluster_names": [target_ref],
                "network_policy_uid": str(live_metadata.get("uid", "") or ""),
                "verified_at": _utc_now(),
            }
        )
        contract["semantic_sha256"] = _fingerprint(
            {key: value for key, value in contract.items() if key != "semantic_sha256"}
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        lines.append(
            "In-place controller safety: bridge NetworkPolicy admits the exact target "
            "Soperator instance."
        )
    source_configuration = _mapping(journal.get("source_configuration"))
    target_config_name, bridge_only_config, _target_state_path = _controller_bridge_target_config(
        journal=journal,
        values={"clusterName": target_ref},
        target_ref=target_ref,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    handoff_config = bridge_only_config
    handoff = phase.setdefault("in_place_bridge_client_handoff", {})
    if not isinstance(handoff, dict):
        raise RuntimeError("In-place bridge client handoff journal must be a mapping.")
    config_sha256 = hashlib.sha256(handoff_config.encode("utf-8")).hexdigest()
    if (
        handoff.get("status") != "verified"
        or str(handoff.get("config_sha256", "") or "") != config_sha256
    ):
        _patch_slurm_config_map_text(
            namespace=_SOPERATOR_NAMESPACE,
            name=target_config_name,
            config_key=str(source_configuration.get("config_key", "") or ""),
            slurm_conf=handoff_config,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        handoff.update(
            {
                "status": "accepted",
                "config_map": target_config_name,
                "config_sha256": config_sha256,
                "accepted_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
    expected_client_contract = _controller_bridge_client_config_contract(handoff_config)
    lines.extend(
        _repair_in_place_login_bridge_config_propagation(
            checkpoint=checkpoint,
            phase=phase,
            expected_contract=expected_client_contract,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
        )
    )
    pending_worker_operations = _accepted_in_place_worker_provider_operations_pending(phase)
    if pending_worker_operations:
        propagation = _mapping(handoff.get("propagation"))
        proof_at = str(
            propagation.get("revalidated_at") or propagation.get("verified_at") or ""
        ).strip()
        accepted_times = [
            str(operation.get("accepted_at") or "").strip()
            for operation in pending_worker_operations
        ]
        try:
            proof_precedes_dispatch = bool(proof_at) and all(
                _journal_timestamp(proof_at, field="bridge client proof")
                <= _journal_timestamp(accepted_at, field="worker provider accepted_at")
                for accepted_at in accepted_times
            )
        except RuntimeError:
            proof_precedes_dispatch = False
        if (
            propagation.get("status") != "verified"
            or str(propagation.get("config_sha256") or "") != config_sha256
            or not proof_precedes_dispatch
        ):
            raise RuntimeError(
                "recovery-required: an accepted worker provider operation lacks its "
                "pre-dispatch bridge-client propagation proof."
            )
        handoff.update({"status": "verified", "verified_at": _utc_now()})
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            *lines,
            "In-place controller clients retained their exact pre-dispatch bridge proof "
            "while the checkpointed worker provider operation remains pending.",
        ]
    lines.extend(
        _prove_controller_bridge_client_configuration(
            journal=journal,
            proof_owner=handoff,
            proof_key="propagation",
            proof_stage="before-in-place-controller-roll",
            expected_contract=expected_client_contract,
            expected_cluster_name=target_ref,
            required_hosts=expected_client_contract["controller_hosts"],
            target_ref=target_ref,
            source_clients=False,
            require_raised_timeouts=False,
            require_live_rpc=True,
            kube_context=kube_context,
            command_runner=command_runner,
            checkpoint_writer=checkpoint_writer,
            allowed_target_worker_replacement_node_uids=(
                _in_place_completed_worker_replacement_node_uids(phase)
            ),
            allowed_target_login_replacement_node_uids=(
                _in_place_completed_role_replacement_node_uids(phase, role="login")
            ),
            allowed_target_worker_pod_successors=(
                _gpu_typed_gres_worker_pod_successors(checkpoint)
            ),
            allow_checkpointed_config_successor=True,
            allow_session_free_target_login_successor=True,
        )
    )
    handoff.update({"status": "verified", "verified_at": _utc_now()})
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [*lines, "In-place controller clients are pinned to the two-node bridge."]


def _ensure_in_place_target_controller_command_gate(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Reassert the inert target controller contract while the bridge owns authority."""

    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            "in-place controller replacement requires the checkpointed HA controller bridge."
        )
    takeover = journal.get("target_singleton_takeover")
    if not isinstance(takeover, dict):
        raise RuntimeError("Controller bridge target takeover journal must be mutable.")
    gate_rearm = takeover.get("command_gate_applied") is not True
    if gate_rearm:
        try:
            validate_bridge_journal(journal)
            stage = BridgeStage(str(journal.get("stage", "") or ""))
        except ValueError as exc:
            raise RuntimeError(f"Controller bridge journal is invalid: {exc}") from exc
        authority = _mapping(journal.get("authority"))
        if (
            stage
            not in {
                BridgeStage.SOURCE_HA_ACTIVE,
                BridgeStage.TARGET_HA_ACTIVE,
                BridgeStage.BRIDGE_FENCED,
            }
            or str(authority.get("owner", "") or "") not in {"bridge-source", "bridge-target"}
            or authority.get("source_restart_prohibited") is not True
        ):
            raise SoperatorMigrationPhasePending(
                "in-place controller replacement may re-arm the target controller command "
                "gate only while the validated bridge exclusively owns authority."
            )
    target = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "slurmcluster",
            target_ref,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    metadata = _mapping(target.get("metadata"))
    if not metadata:
        raise SoperatorMigrationPhasePending(
            f"target SlurmCluster '{target_ref}' is missing while the controller bridge "
            "owns authority."
        )
    expected = _mapping(
        _mapping(
            _mapping(target_controller_gate_values({}).get("slurmNodes")).get("controller")
        ).get("slurmctld")
    )
    observed = _mapping(
        _mapping(_mapping(_mapping(target.get("spec")).get("slurmNodes")).get("controller")).get(
            "slurmctld"
        )
    )
    gate_state = phase.setdefault("in_place_target_controller_command_gate", {})
    if not isinstance(gate_state, dict):
        raise RuntimeError("In-place target controller command-gate journal must be a mapping.")
    admission_window = gate_state.get("slurmcluster_admission_window")
    if _is_exact_target_controller_command_gate(observed) and isinstance(admission_window, dict):
        _restore_in_place_slurmcluster_admission_window(
            window=admission_window,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    if not _is_exact_target_controller_command_gate(observed):
        resource_version = str(metadata.get("resourceVersion", "") or "").strip()
        if not resource_version:
            raise SoperatorMigrationPhasePending(
                "target SlurmCluster command-gate repair requires a live resourceVersion."
            )
        patch = {
            "metadata": {"resourceVersion": resource_version},
            "spec": {
                "slurmNodes": {
                    "controller": {
                        "slurmctld": {
                            "command": list(expected.get("command", []) or []),
                            "args": list(expected.get("args", []) or []),
                            "livenessProbe": None,
                            "readinessProbe": None,
                        }
                    }
                }
            },
        }
        manager_pause = _mapping(phase.get("in_place_target_manager_pause"))
        if manager_pause.get("status") == "verified":
            _patch_in_place_slurmcluster_during_manager_pause(
                state=gate_state,
                target_ref=target_ref,
                target_uid=str(metadata.get("uid", "") or ""),
                target_resource_version=resource_version,
                spec_patch=_mapping(patch.get("spec")),
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        else:
            command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "patch",
                    "slurmcluster",
                    target_ref,
                    "--type",
                    "merge",
                    "-p",
                    json.dumps(patch, sort_keys=True, separators=(",", ":")),
                ],
                timeout_seconds=120,
            )
        gate_state.update(
            {
                "status": "slurmcluster-accepted",
                "slurmcluster_uid": str(metadata.get("uid", "") or ""),
                "resource_version": resource_version,
                "contract_fingerprint": _fingerprint(expected),
                "accepted_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "reasserted the exact inert target controller command gate after target "
            "reconciliation; resume after the controller workload observes it."
        )

    workload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "statefulsets.apps.kruise.io",
            "controller",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    workload_metadata = _mapping(workload.get("metadata"))
    containers = _sequence_of_mappings(
        _mapping(_mapping(workload.get("spec")).get("template")).get("spec", {}).get("containers")
    )
    owner_uids = {
        str(owner.get("uid", "") or "")
        for owner in _sequence_of_mappings(workload_metadata.get("ownerReferences"))
        if owner.get("controller") is True
    }
    if (
        not workload_metadata
        or len(containers) != 1
        or str(containers[0].get("name", "") or "") != "slurmctld"
        or str(metadata.get("uid", "") or "") not in owner_uids
    ):
        raise SoperatorMigrationPhasePending(
            "target controller command-gate repair could not bind one exact owned Kruise "
            "StatefulSet/slurmctld container."
        )
    if not _is_exact_target_controller_command_gate(containers[0]):
        workload_resource_version = str(workload_metadata.get("resourceVersion", "") or "").strip()
        if not workload_resource_version:
            raise SoperatorMigrationPhasePending(
                "target controller workload command-gate repair requires a live resourceVersion."
            )
        workload_patch = [
            {
                "op": "test",
                "path": "/metadata/resourceVersion",
                "value": workload_resource_version,
            },
            {
                "op": "test",
                "path": "/spec/template/spec/containers/0/name",
                "value": "slurmctld",
            },
            {
                "op": "add",
                "path": "/spec/template/spec/containers/0/command",
                "value": list(expected.get("command", []) or []),
            },
            {
                "op": "add",
                "path": "/spec/template/spec/containers/0/args",
                "value": list(expected.get("args", []) or []),
            },
        ]
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "patch",
                "statefulsets.apps.kruise.io",
                "controller",
                "--type",
                "json",
                "-p",
                json.dumps(workload_patch, sort_keys=True, separators=(",", ":")),
            ],
            timeout_seconds=120,
        )
        gate_state.update(
            {
                "status": "workload-accepted",
                "workload_uid": str(workload_metadata.get("uid", "") or ""),
                "workload_resource_version": workload_resource_version,
                "workload_accepted_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "reasserted the exact inert target controller command gate on the owned "
            "Kruise StatefulSet; resume after its live Pod is replaced and fenced."
        )

    workload_replicas = _resource_replicas(workload, default=-1)
    if workload_replicas == 0:
        workload_resource_version = str(workload_metadata.get("resourceVersion", "") or "").strip()
        workload_uid = str(workload_metadata.get("uid", "") or "").strip()
        if not workload_resource_version or not workload_uid:
            raise SoperatorMigrationPhasePending(
                "target controller workload activation requires its exact UID/resourceVersion."
            )
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="statefulsets.apps.kruise.io/controller",
            patch={
                "metadata": {
                    "uid": workload_uid,
                    "resourceVersion": workload_resource_version,
                },
                "spec": {"replicas": 1},
            },
            patch_via_stdin=True,
        )
        gate_state.update(
            {
                "status": "workload-scale-accepted",
                "workload_uid": workload_uid,
                "workload_resource_version": workload_resource_version,
                "workload_scale_accepted_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "activated one exact inert target controller replica under bridge authority; "
            "resume after its live Pod is created and fenced."
        )
    if workload_replicas != 1:
        raise SoperatorMigrationPhasePending(
            "target controller command-gate repair requires exactly one gated workload replica."
        )

    pods = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-l",
            f"app.kubernetes.io/instance={target_ref},app.kubernetes.io/component=controller",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    workload_uid = str(workload_metadata.get("uid", "") or "")
    live_pods = _exact_owned_live_target_controller_pods(
        _sequence_of_mappings(pods.get("items")),
        workload_uid=workload_uid,
    )
    if len(live_pods) != 1 or not _pod_spec_has_exact_target_controller_command_gate(
        _mapping(live_pods[0].get("spec")) if live_pods else {}
    ):
        gate_state["status"] = "pod-pending"
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "target controller workload is gated, but its one exact live Pod has not yet "
            "observed the inert command."
        )
    gate_state.update(
        {
            "status": "verified",
            "slurmcluster_uid": str(metadata.get("uid", "") or ""),
            "workload_uid": str(workload_metadata.get("uid", "") or ""),
            "pod_uid": str(_mapping(live_pods[0].get("metadata")).get("uid", "") or ""),
            "contract_fingerprint": _fingerprint(expected),
            "verified_at": _utc_now(),
        }
    )
    if gate_rearm:
        gate_contract = {
            "schema": "nebius-cxcli/target-controller-command-gate-v2",
            "slurmctld": copy.deepcopy(expected),
        }
        takeover.update(
            {
                "command_gate_applied": True,
                "command_gate_removed_at": "",
                "command_gate_contract_schema": gate_contract["schema"],
                "command_gate_contract_fingerprint": _fingerprint(gate_contract),
                "command_gate_rearmed_at": _utc_now(),
            }
        )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return ["In-place controller safety: exact inert target controller gate verified live."]


_IN_PLACE_TARGET_HA_BACKUP_NAME = "cxcli-target-controller-backup"
_IN_PLACE_TARGET_HA_BACKUP_SERVICE = "cxcli-target-controller-backup-svc"
_IN_PLACE_TARGET_HA_BACKUP_LABEL = "nebius.ai/cxcli-target-controller-backup"


def _pod_condition_true(pod: Mapping[str, Any], condition_type: str) -> bool:
    return any(
        str(condition.get("type", "") or "") == condition_type
        and str(condition.get("status", "") or "") == "True"
        for condition in _sequence_of_mappings(_mapping(pod.get("status")).get("conditions"))
    )


def _pod_named_volume_source(pod: Mapping[str, Any], name: str) -> Mapping[str, Any]:
    return next(
        (
            _mapping(volume)
            for volume in _sequence_of_mappings(_mapping(pod.get("spec")).get("volumes"))
            if str(volume.get("name", "") or "") == name
        ),
        {},
    )


def _pod_slurmctld_image(pod: Mapping[str, Any]) -> str:
    containers = [
        item
        for item in _sequence_of_mappings(_mapping(pod.get("spec")).get("containers"))
        if "slurmctld" in str(item.get("name", "") or "").lower()
    ]
    return str(containers[0].get("image", "") or "") if len(containers) == 1 else ""


def _verify_in_place_target_native_controller_ha(
    *,
    phase: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    proof_stage: str,
) -> list[str]:
    """Prove the temporary target-native controller pair used during provider roll."""

    if not target_ref:
        raise SoperatorMigrationPhasePending(
            "target-native controller HA lost its target SlurmCluster reference."
        )
    manager = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "deployment/soperator-manager",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if not _mapping(manager.get("metadata")) or _resource_replicas(manager, default=-1) != 0:
        raise SoperatorMigrationPhasePending(
            "target-native controller HA requires the target Soperator manager paused at "
            "replicas=0 so it cannot collapse the temporary two-host configuration."
        )
    config_name = f"{target_ref}-slurm-configs"
    config_map = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"configmap/{config_name}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    slurm_conf = str(_mapping(config_map.get("data")).get("slurm.conf", "") or "")
    host_contract = _controller_bridge_client_config_contract(slurm_conf)
    expected_hosts = (
        f"controller-0({target_ref}-controller-svc)",
        (
            f"{_IN_PLACE_TARGET_HA_BACKUP_NAME}("
            f"{_IN_PLACE_TARGET_HA_BACKUP_SERVICE}.soperator.svc.cluster.local)"
        ),
    )
    if tuple(host_contract.get("controller_hosts", ())) != expected_hosts:
        raise SoperatorMigrationPhasePending(
            "target-native controller HA requires the exact target primary and temporary "
            "backup SlurmctldHost entries."
        )
    primary = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pod/controller-0",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    backups = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "pods",
            "-l",
            f"{_IN_PLACE_TARGET_HA_BACKUP_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    backup_items = [
        item
        for item in _sequence_of_mappings(backups.get("items"))
        if str(_mapping(item.get("status")).get("phase", "") or "") not in {"Succeeded", "Failed"}
    ]
    if (
        not _mapping(primary.get("metadata"))
        or not _pod_condition_true(primary, "Ready")
        or len(backup_items) != 1
        or not _pod_condition_true(backup_items[0], "Ready")
    ):
        raise SoperatorMigrationPhasePending(
            "target-native controller HA requires one Ready target primary and one Ready "
            "temporary backup."
        )
    backup = backup_items[0]
    primary_node = str(_mapping(primary.get("spec")).get("nodeName", "") or "")
    backup_node = str(_mapping(backup.get("spec")).get("nodeName", "") or "")
    if not primary_node or not backup_node or primary_node == backup_node:
        raise SoperatorMigrationPhasePending(
            "target-native controller HA members must occupy distinct controller nodes."
        )
    primary_image = _pod_slurmctld_image(primary)
    backup_image = _pod_slurmctld_image(backup)
    if not primary_image or primary_image != backup_image:
        raise SoperatorMigrationPhasePending(
            "target-native controller HA members do not use the same target Slurm image."
        )
    for volume_name, source_key, identity_key in (
        ("controller-spool", "persistentVolumeClaim", "claimName"),
        ("munge-key", "secret", "secretName"),
    ):
        primary_identity = str(
            _mapping(_pod_named_volume_source(primary, volume_name).get(source_key)).get(
                identity_key, ""
            )
            or ""
        )
        backup_identity = str(
            _mapping(_pod_named_volume_source(backup, volume_name).get(source_key)).get(
                identity_key, ""
            )
            or ""
        )
        if not primary_identity or primary_identity != backup_identity:
            raise SoperatorMigrationPhasePending(
                f"target-native controller HA changed its shared {volume_name} identity."
            )
    cluster_names: list[str] = []
    for pod_name in (
        "controller-0",
        str(_mapping(backup.get("metadata")).get("name", "") or ""),
    ):
        observed = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                pod_name,
                "-c",
                "slurmctld",
                "--",
                "cat",
                "/var/spool/slurmctld/clustername",
            ],
            timeout_seconds=120,
            check=False,
        )
        cluster_names.append(observed.stdout.strip() if observed.returncode == 0 else "")
    if (
        not cluster_names[0]
        or cluster_names[0] != cluster_names[1]
        or not cluster_names[0].startswith(f"{target_ref}|")
    ):
        raise SoperatorMigrationPhasePending(
            "target-native controller HA does not share the exact target accounting cluster ID."
        )
    ping = _kubectl_exec_login(
        command_runner=command_runner,
        kube_context=kube_context,
        args=("scontrol", "ping"),
        check=False,
        timeout_seconds=120,
    )
    if ping.returncode != 0 or not all(
        re.search(
            rf"Slurmctld\((?:primary|backup)\)\s+at\s+{re.escape(host)}\s+is\s+UP",
            ping.stdout,
            re.IGNORECASE,
        )
        for host in ("controller-0", _IN_PLACE_TARGET_HA_BACKUP_NAME)
    ):
        raise SoperatorMigrationPhasePending(
            "target-native controller HA did not prove both target controllers UP through "
            "the login Jail."
        )
    state = phase.setdefault("in_place_target_native_controller_ha", {})
    if not isinstance(state, dict):
        raise RuntimeError("Target-native controller HA journal must be a mapping.")
    proofs = state.setdefault("proofs", [])
    if not isinstance(proofs, list):
        raise RuntimeError("Target-native controller HA proofs must be a list.")
    proof = {
        "stage": proof_stage,
        "primary_pod_uid": str(_mapping(primary.get("metadata")).get("uid", "") or ""),
        "backup_pod_uid": str(_mapping(backup.get("metadata")).get("uid", "") or ""),
        "primary_node": primary_node,
        "backup_node": backup_node,
        "config_sha256": hashlib.sha256(slurm_conf.encode("utf-8")).hexdigest(),
        "cluster_identity_sha256": hashlib.sha256(cluster_names[0].encode("utf-8")).hexdigest(),
        "ping_sha256": hashlib.sha256(ping.stdout.encode("utf-8")).hexdigest(),
        "verified_at": _utc_now(),
    }
    proofs.append(proof)
    state.update(
        {
            "schema": "nebius-cxcli/in-place-target-native-controller-ha-v1",
            "status": "verified",
            "target_ref": target_ref,
            "manager_replicas": 0,
            "latest_proof": proof,
            "verified_at": proof["verified_at"],
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "In-place controller safety: target-native primary/backup share the exact target "
        f"state, Munge key, accounting identity, and target image ({proof_stage})."
    ]


def _ensure_in_place_bridge_authority_outside_provider_domain(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    role: str,
    planned_groups: Sequence[Mapping[str, Any]],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    shared_evidence: dict[str, Any] | None = None,
) -> list[str]:
    if role not in {"controller", "system"}:
        return []
    # The retained source bridge is intentionally bound to the source
    # controller state and accounting cluster ID.  Once the in-place target
    # singleton is active, changing only its Munge key or client config would
    # create a split identity.  Controller replacement therefore uses a
    # target-native backup mounted on the exact target state PVC; the system
    # replacement reuses the same verified target HA pair.
    native_ha = phase.get("in_place_target_native_controller_ha")
    if isinstance(native_ha, Mapping):
        return _verify_in_place_target_native_controller_ha(
            phase=phase,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            proof_stage=f"pre-{role}-replacement",
        )
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement requires the checkpointed HA controller bridge."
        )
    rolling_group = next(
        (group for group in planned_groups if str(group.get("role", "") or "").strip() == role),
        None,
    )
    rolling_group_id = str(_mapping(rolling_group).get("id", "") or "").strip()
    if not rolling_group_id:
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement cannot resolve its accepted provider domain."
        )
    roles_fingerprint = _fingerprint(
        [
            {
                key: str(item.get(key, "") or "")
                for key in ("pod_name", "pod_uid", "node_uid", "node_group_id", "role", "image")
            }
            for item in _sequence_of_mappings(journal.get("controller_roles"))
        ]
    )
    if (
        shared_evidence is not None
        and shared_evidence.get("status") == "verified"
        and shared_evidence.get("roles_fingerprint") == roles_fingerprint
    ):
        active_group_id = str(shared_evidence.get("active_node_group_id", "") or "")
        standby_group_id = str(shared_evidence.get("standby_node_group_id", "") or "")
        if (
            active_group_id
            and standby_group_id
            and active_group_id != standby_group_id
            and active_group_id != rolling_group_id
        ):
            transitions = phase.setdefault("in_place_authority_transitions", {})
            if not isinstance(transitions, dict):
                raise RuntimeError("In-place authority transition journal must be a mapping.")
            transitions[role] = {
                "status": "verified",
                "active_pod_uid": str(shared_evidence.get("active_pod_uid", "") or ""),
                "active_node_uid": str(shared_evidence.get("active_node_uid", "") or ""),
                "active_node_group_id": active_group_id,
                "rolling_node_group_id": rolling_group_id,
                "evidence_source": "invocation-reuse",
                "verified_at": _utc_now(),
            }
            if checkpoint_writer is not None:
                checkpoint_writer()
            return [
                f"Bridge authority outside the {role} provider domain reused the exact "
                "invocation-scoped two-domain proof."
            ]
    lines = _ensure_in_place_bridge_client_configuration(
        checkpoint=checkpoint,
        phase=phase,
        target_ref=target_ref,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    lines.extend(
        _ensure_in_place_target_controller_command_gate(
            checkpoint=checkpoint,
            phase=phase,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    _prove_journaled_controller_bridge_exclusivity(
        journal=journal,
        proof_label=f"pre-{role}-replacement opposite-domain authority",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    active, standby = _controller_bridge_primary_role_from_ping(
        journal=journal,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    transitions = phase.setdefault("in_place_authority_transitions", {})
    if not isinstance(transitions, dict):
        raise RuntimeError("In-place authority transition journal must be a mapping.")
    transition = transitions.setdefault(role, {})
    if not isinstance(transition, dict):
        raise RuntimeError(f"In-place {role} authority transition must be a mapping.")
    active_group_id = str(active.get("node_group_id", "") or "").strip()
    standby_group_id = str(standby.get("node_group_id", "") or "").strip()
    if not active_group_id or not standby_group_id or active_group_id == standby_group_id:
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement requires two distinct bridge provider domains."
        )
    if active_group_id != rolling_group_id:
        if shared_evidence is not None:
            shared_evidence.clear()
            shared_evidence.update(
                {
                    "status": "verified",
                    "roles_fingerprint": roles_fingerprint,
                    "active_pod_uid": str(active.get("pod_uid", "") or ""),
                    "active_node_uid": str(active.get("node_uid", "") or ""),
                    "active_node_group_id": active_group_id,
                    "standby_node_group_id": standby_group_id,
                    "verified_at": _utc_now(),
                }
            )
        transition.update(
            {
                "status": "verified",
                "active_pod_uid": str(active.get("pod_uid", "") or ""),
                "active_node_uid": str(active.get("node_uid", "") or ""),
                "active_node_group_id": active_group_id,
                "rolling_node_group_id": rolling_group_id,
                "verified_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [
            *lines,
            f"Bridge authority is outside the {role} provider domain before replacement.",
        ]
    if standby_group_id == rolling_group_id:
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement found no healthy bridge standby outside its "
            "provider domain."
        )
    statefulset = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            str(journal.get("namespace", "") or ""),
            "get",
            "statefulset",
            "cxcli-slurm-controller-bridge",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    container = _controller_bridge_container_name(
        statefulset,
        expected_image=str(standby.get("image", "") or ""),
    )
    transition.update(
        {
            "status": "dispatching",
            "from_pod_uid": str(active.get("pod_uid", "") or ""),
            "to_pod_uid": str(standby.get("pod_uid", "") or ""),
            "to_node_uid": str(standby.get("node_uid", "") or ""),
            "to_node_group_id": standby_group_id,
            "rolling_node_group_id": rolling_group_id,
            "dispatching_at": str(transition.get("dispatching_at", "") or "") or _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            str(journal.get("namespace", "") or ""),
            "exec",
            str(standby.get("pod_name", "") or ""),
            "-c",
            container,
            "--",
            "scontrol",
            "takeover",
            "1",
        ],
        timeout_seconds=180,
    )
    deadline = time.monotonic() + 120
    while True:
        new_active, new_standby = _controller_bridge_primary_role_from_ping(
            journal=journal,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if str(new_active.get("pod_uid", "") or "") == str(standby.get("pod_uid", "") or ""):
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                f"in-place {role} authority takeover remains indeterminate; it will be "
                "reconciled from live primary evidence without resending."
            )
        time.sleep(1)
    for item in journal["controller_roles"]:
        item["role"] = (
            "active"
            if str(item.get("pod_uid", "") or "") == str(new_active.get("pod_uid", "") or "")
            else "standby"
        )
        item["observed_at"] = _utc_now()
    transition.update(
        {
            "status": "verified",
            "active_pod_uid": str(new_active.get("pod_uid", "") or ""),
            "active_node_uid": str(new_active.get("node_uid", "") or ""),
            "active_node_group_id": standby_group_id,
            "rolling_node_group_id": rolling_group_id,
            "verified_at": _utc_now(),
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    if shared_evidence is not None:
        shared_evidence.clear()
        shared_evidence.update(
            {
                "status": "verified",
                "roles_fingerprint": _fingerprint(
                    [
                        {
                            key: str(item.get(key, "") or "")
                            for key in (
                                "pod_name",
                                "pod_uid",
                                "node_uid",
                                "node_group_id",
                                "role",
                                "image",
                            )
                        }
                        for item in _sequence_of_mappings(journal.get("controller_roles"))
                    ]
                ),
                "active_pod_uid": str(new_active.get("pod_uid", "") or ""),
                "active_node_uid": str(new_active.get("node_uid", "") or ""),
                "active_node_group_id": standby_group_id,
                "standby_node_group_id": active_group_id,
                "verified_at": _utc_now(),
            }
        )
    _prove_journaled_controller_bridge_exclusivity(
        journal=journal,
        proof_label=f"post-{role}-takeover opposite-domain authority",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    return [
        *lines,
        f"Transferred bridge authority outside the {role} provider domain before replacement.",
    ]


def _rebind_in_place_bridge_domain_after_provider_roll(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    role: str,
    rolled_group_id: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    if role not in {"controller", "system"}:
        return []
    if isinstance(phase.get("in_place_target_native_controller_ha"), Mapping):
        return _verify_in_place_target_native_controller_ha(
            phase=phase,
            target_ref=str(
                _mapping(phase.get("in_place_target_native_controller_ha")).get("target_ref", "")
                or ""
            ),
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            proof_stage=f"post-{role}-replacement",
        )
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, dict):
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement lost its checkpointed controller bridge."
        )
    prior_roles = _sequence_of_mappings(journal.get("controller_roles"))
    prior_by_group = {str(item.get("node_group_id", "") or ""): item for item in prior_roles}
    if len(prior_by_group) != 2:
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement cannot bind the rolled provider domain to "
            "one exact bridge member."
        )
    if rolled_group_id not in prior_by_group:
        _prove_journaled_controller_bridge_exclusivity(
            journal=journal,
            proof_label=f"post-{role}-replacement dedicated bridge authority",
            kube_context=kube_context,
            command_runner=command_runner,
        )
        active, standby = _controller_bridge_primary_role_from_ping(
            journal=journal,
            command_runner=command_runner,
            kube_context=kube_context,
        )
        health = phase.setdefault("in_place_service_role_health", {})
        if not isinstance(health, dict):
            raise RuntimeError("In-place service-role health journal must be a mapping.")
        role_health = health.setdefault(role, {})
        if not isinstance(role_health, dict):
            raise RuntimeError(f"In-place {role} health journal must be a mapping.")
        role_health["bridge_rebind"] = {
            "status": "verified-dedicated-bridge",
            "rolled_node_group_id": rolled_group_id,
            "active_pod_uid": str(active.get("pod_uid", "") or ""),
            "standby_pod_uid": str(standby.get("pod_uid", "") or ""),
            "bridge_node_group_ids": sorted(prior_by_group),
            "verified_at": _utc_now(),
        }
        if checkpoint_writer is not None:
            checkpoint_writer()
        return [f"Dedicated bridge authority remained outside the rolled {role} provider domain."]
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            str(journal.get("namespace", "") or ""),
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    if len(pods) != 2:
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement requires exactly two Ready bridge Pods."
        )
    rebound_by_group: dict[str, dict[str, Any]] = {}
    for pod in pods:
        metadata = _mapping(pod.get("metadata"))
        pod_name = str(metadata.get("name", "") or "")
        pod_uid = str(metadata.get("uid", "") or "")
        node_name = str(_mapping(pod.get("spec")).get("nodeName", "") or "")
        node = _json_from_command(
            command_runner,
            ["kubectl", "--context", kube_context, "get", "node", node_name, "-o", "json"],
            timeout_seconds=120,
        )
        node_metadata = _mapping(node.get("metadata"))
        node_uid = str(node_metadata.get("uid", "") or "")
        node_group_id = str(
            _mapping(node_metadata.get("labels")).get("nebius.com/node-group-id", "") or ""
        )
        prior = prior_by_group.get(node_group_id)
        if prior is None or not pod_name or not pod_uid or not node_uid:
            raise SoperatorMigrationPhasePending(
                f"in-place {role} replacement found a foreign or incomplete bridge placement."
            )
        if str(prior.get("pod_name", "") or "") != pod_name:
            raise SoperatorMigrationPhasePending(
                f"in-place {role} replacement changed the bridge StatefulSet ordinal binding."
            )
        if node_group_id != rolled_group_id and (
            str(prior.get("pod_uid", "") or "") != pod_uid
            or str(prior.get("node_uid", "") or "") != node_uid
        ):
            raise SoperatorMigrationPhasePending(
                f"in-place {role} replacement changed the opposite-domain bridge identity."
            )
        expected_image = str(prior.get("image", "") or "")
        expected_digest = expected_image.rsplit("sha256:", 1)[-1]
        statuses = _sequence_of_mappings(_mapping(pod.get("status")).get("containerStatuses"))
        if not expected_digest or not any(
            expected_digest in str(status.get("imageID", "") or "")
            and bool(_mapping(status.get("state")).get("running"))
            for status in statuses
        ):
            raise SoperatorMigrationPhasePending(
                f"in-place {role} replacement bridge member lost its exact image digest or "
                "running container state."
            )
        rebound = copy.deepcopy(dict(prior))
        rebound.update(
            {
                "pod_uid": pod_uid,
                "node_name": node_name,
                "node_uid": node_uid,
                "observed_at": _utc_now(),
            }
        )
        rebound_by_group[node_group_id] = rebound
    if set(rebound_by_group) != set(prior_by_group):
        raise SoperatorMigrationPhasePending(
            f"in-place {role} replacement did not preserve both bridge provider domains."
        )
    journal["controller_roles"] = list(rebound_by_group.values())
    active, standby = _controller_bridge_primary_role_from_ping(
        journal=journal,
        command_runner=command_runner,
        kube_context=kube_context,
    )
    for item in journal["controller_roles"]:
        item["role"] = (
            "active"
            if str(item.get("pod_uid", "") or "") == str(active.get("pod_uid", "") or "")
            else "standby"
        )
    health = phase.setdefault("in_place_service_role_health", {})
    if not isinstance(health, dict):
        raise RuntimeError("In-place service-role health journal must be a mapping.")
    role_health = health.setdefault(role, {})
    if not isinstance(role_health, dict):
        raise RuntimeError(f"In-place {role} health journal must be a mapping.")
    role_health["bridge_rebind"] = {
        "status": "verified",
        "rolled_node_group_id": rolled_group_id,
        "active_pod_uid": str(active.get("pod_uid", "") or ""),
        "standby_pod_uid": str(standby.get("pod_uid", "") or ""),
        "rolled_pod_uid": str(rebound_by_group[rolled_group_id].get("pod_uid", "") or ""),
        "rolled_node_uid": str(rebound_by_group[rolled_group_id].get("node_uid", "") or ""),
        "verified_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    _prove_journaled_controller_bridge_exclusivity(
        journal=journal,
        proof_label=f"post-{role}-replacement bridge UID rebind",
        kube_context=kube_context,
        command_runner=command_runner,
    )
    return [f"Rebound the {role} bridge member after provider-terminal replacement."]


_IN_PLACE_CONTROLLER_GATE_FIELDS = (
    "command",
    "args",
    "livenessProbe",
    "readinessProbe",
)
_IN_PLACE_TARGET_NATIVE_CLEANUP_RESUME_STATUSES = frozenset(
    {
        "singleton-config-accepted",
        "backup-retired",
        "controller-gate-removed",
        "manager-restoring",
    }
)


def _in_place_service_role_authority_finalized(
    *,
    phase: Mapping[str, Any],
    group_state: Mapping[str, Any],
) -> bool:
    native_ha = _mapping(phase.get("in_place_target_native_controller_ha"))
    return bool(
        str(group_state.get("status") or "") == "completed"
        and str(native_ha.get("cleanup_status") or "")
        in _IN_PLACE_TARGET_NATIVE_CLEANUP_RESUME_STATUSES
    )


def _in_place_target_controller_gate_removed(resource: Mapping[str, Any]) -> bool:
    slurmctld = _mapping(
        _mapping(_mapping(_mapping(resource.get("spec")).get("slurmNodes")).get("controller")).get(
            "slurmctld"
        )
    )
    return bool(slurmctld) and all(
        field not in slurmctld for field in _IN_PLACE_CONTROLLER_GATE_FIELDS
    )


def _restore_in_place_slurmcluster_admission_window(
    *,
    window: dict[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None],
) -> None:
    if str(window.get("status") or "") not in {"intent", "active", "target-patched"}:
        return
    live = _soperator_slurmcluster_admission_webhook(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if (
        str(live.get("uid") or "") != str(window.get("uid") or "")
        or str(live.get("name") or "") != str(window.get("name") or "")
        or int(live.get("webhook_index") or -1) != int(window.get("webhook_index") or -1)
        or str(live.get("webhook_name") or "") != str(window.get("webhook_name") or "")
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup admission webhook identity changed before restoration."
        )
    if live["failure_policy"] == "Ignore":
        _patch_soperator_slurmcluster_admission_policy(
            binding=live,
            desired_policy="Fail",
            command_runner=command_runner,
            kube_context=kube_context,
            mutation_guard=None,
        )
        live = _soperator_slurmcluster_admission_webhook(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    if (
        str(live.get("uid") or "") != str(window.get("uid") or "")
        or live.get("failure_policy") != "Fail"
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup could not restore the exact SlurmCluster admission "
            "failure policy."
        )
    window.update(
        {
            "status": "restored",
            "restored_resource_version": str(live.get("resourceVersion") or ""),
            "restored_at": _utc_now(),
        }
    )
    checkpoint_writer()


def _patch_in_place_slurmcluster_during_manager_pause(
    *,
    state: dict[str, Any],
    target_ref: str,
    target_uid: str,
    target_resource_version: str,
    spec_patch: Mapping[str, Any],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    """Patch one exact SlurmCluster while its validating webhook is intentionally paused."""

    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "target controller gate repair requires durable admission-window checkpoints."
        )
    manager = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "deployment/soperator-manager",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if not _mapping(manager.get("metadata")) or _resource_replicas(manager, default=-1) != 0:
        raise SoperatorMigrationPhasePending(
            "target controller gate repair may bypass admission only while the exact "
            "Soperator manager is paused at replicas=0."
        )
    window = state.setdefault("slurmcluster_admission_window", {})
    if not isinstance(window, dict):
        raise RuntimeError("Target controller gate admission window must be a mapping.")
    window_status = str(window.get("status") or "")
    if window_status not in {"intent", "active", "target-patched"}:
        admission = _soperator_slurmcluster_admission_webhook(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if admission.get("failure_policy") != "Fail":
            raise SoperatorMigrationPhasePending(
                "target controller gate repair found an unowned SlurmCluster admission bypass."
            )
        window.clear()
        window.update(
            {
                "schema": "nebius-cxcli/in-place-slurmcluster-admission-window-v1",
                "status": "intent",
                "purpose": "target-controller-gate-rearm",
                "target_ref": target_ref,
                "target_uid": target_uid,
                "name": str(admission.get("name") or ""),
                "uid": str(admission.get("uid") or ""),
                "webhook_name": str(admission.get("webhook_name") or ""),
                "webhook_index": int(admission.get("webhook_index") or 0),
                "original_failure_policy": "Fail",
                "intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
    elif (
        window.get("purpose") != "target-controller-gate-rearm"
        or str(window.get("target_ref") or "") != target_ref
        or str(window.get("target_uid") or "") != target_uid
        or window.get("original_failure_policy") != "Fail"
    ):
        raise SoperatorMigrationPhasePending(
            "target controller gate admission window drifted from its exact target binding."
        )

    admission = _soperator_slurmcluster_admission_webhook(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if (
        str(admission.get("uid") or "") != str(window.get("uid") or "")
        or str(admission.get("webhook_name") or "") != str(window.get("webhook_name") or "")
        or int(admission.get("webhook_index") or -1) != int(window.get("webhook_index") or -1)
    ):
        raise SoperatorMigrationPhasePending(
            "target controller gate admission webhook drifted after durable intent."
        )
    if admission.get("failure_policy") == "Fail":
        _patch_soperator_slurmcluster_admission_policy(
            binding=admission,
            desired_policy="Ignore",
            command_runner=command_runner,
            kube_context=kube_context,
            mutation_guard=None,
        )
        admission = _soperator_slurmcluster_admission_webhook(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    if (
        str(admission.get("uid") or "") != str(window.get("uid") or "")
        or admission.get("failure_policy") != "Ignore"
    ):
        raise SoperatorMigrationPhasePending(
            "target controller gate repair could not open its exact admission window."
        )
    window.update(
        {
            "status": "active",
            "active_resource_version": str(admission.get("resourceVersion") or ""),
            "activated_at": str(window.get("activated_at") or _utc_now()),
        }
    )
    checkpoint_writer()

    patch_error: Exception | None = None
    try:
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource=f"slurmcluster/{target_ref}",
            patch={
                "metadata": {
                    "uid": target_uid,
                    "resourceVersion": target_resource_version,
                },
                "spec": copy.deepcopy(dict(spec_patch)),
            },
            patch_via_stdin=True,
        )
        window.update({"status": "target-patched", "target_patched_at": _utc_now()})
        checkpoint_writer()
    except Exception as exc:
        patch_error = exc
    finally:
        _restore_in_place_slurmcluster_admission_window(
            window=window,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    if patch_error is not None:
        raise SoperatorMigrationPhasePending(
            "target controller gate repair failed while the exact admission window was active."
        ) from patch_error


def _remove_in_place_target_controller_command_gate(
    *,
    state: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> None:
    if checkpoint_writer is None:
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup requires durable admission-window checkpoints."
        )
    window = state.setdefault("slurmcluster_admission_window", {})
    if not isinstance(window, dict):
        raise RuntimeError("Target singleton SlurmCluster admission window must be a mapping.")

    target = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            f"slurmcluster/{target_ref}",
            "-o",
            "json",
        ],
        timeout_seconds=120,
    )
    metadata = _mapping(target.get("metadata"))
    target_uid = str(metadata.get("uid") or "").strip()
    target_resource_version = str(metadata.get("resourceVersion") or "").strip()
    if not target_uid or not target_resource_version:
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup lacks the exact SlurmCluster UID/resourceVersion."
        )
    if _in_place_target_controller_gate_removed(target):
        _restore_in_place_slurmcluster_admission_window(
            window=window,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        state["controller_gate_removed_at"] = str(
            state.get("controller_gate_removed_at") or _utc_now()
        )
        return

    window_status = str(window.get("status") or "")
    if window_status not in {"intent", "active", "target-patched"}:
        admission = _soperator_slurmcluster_admission_webhook(
            command_runner=command_runner,
            kube_context=kube_context,
        )
        if admission.get("failure_policy") != "Fail":
            raise SoperatorMigrationPhasePending(
                "target singleton cleanup found an unowned SlurmCluster admission bypass."
            )
        window.clear()
        window.update(
            {
                "schema": "nebius-cxcli/in-place-slurmcluster-admission-window-v1",
                "status": "intent",
                "target_ref": target_ref,
                "target_uid": target_uid,
                "name": str(admission.get("name") or ""),
                "uid": str(admission.get("uid") or ""),
                "webhook_name": str(admission.get("webhook_name") or ""),
                "webhook_index": int(admission.get("webhook_index") or 0),
                "original_failure_policy": "Fail",
                "intent_at": _utc_now(),
            }
        )
        checkpoint_writer()
    elif (
        str(window.get("target_ref") or "") != target_ref
        or str(window.get("target_uid") or "") != target_uid
        or window.get("original_failure_policy") != "Fail"
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup admission window drifted from its exact target binding."
        )

    admission = _soperator_slurmcluster_admission_webhook(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    if (
        str(admission.get("uid") or "") != str(window.get("uid") or "")
        or str(admission.get("webhook_name") or "") != str(window.get("webhook_name") or "")
        or int(admission.get("webhook_index") or -1) != int(window.get("webhook_index") or -1)
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup admission webhook drifted after durable intent."
        )
    if admission["failure_policy"] == "Fail":
        _patch_soperator_slurmcluster_admission_policy(
            binding=admission,
            desired_policy="Ignore",
            command_runner=command_runner,
            kube_context=kube_context,
            mutation_guard=None,
        )
        admission = _soperator_slurmcluster_admission_webhook(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    if (
        str(admission.get("uid") or "") != str(window.get("uid") or "")
        or admission.get("failure_policy") != "Ignore"
    ):
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup could not open its exact SlurmCluster admission window."
        )
    window.update(
        {
            "status": "active",
            "active_resource_version": str(admission.get("resourceVersion") or ""),
            "activated_at": str(window.get("activated_at") or _utc_now()),
        }
    )
    checkpoint_writer()

    patch_error: Exception | None = None
    try:
        _kubectl_patch_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource=f"slurmcluster/{target_ref}",
            patch={
                "metadata": {
                    "uid": target_uid,
                    "resourceVersion": target_resource_version,
                },
                "spec": {
                    "slurmNodes": {
                        "controller": {
                            "slurmctld": {
                                "command": None,
                                "args": None,
                                "livenessProbe": None,
                                "readinessProbe": None,
                            }
                        }
                    }
                },
            },
            patch_via_stdin=True,
        )
        updated = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                f"slurmcluster/{target_ref}",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        if str(
            _mapping(updated.get("metadata")).get("uid") or ""
        ) != target_uid or not _in_place_target_controller_gate_removed(updated):
            raise SoperatorMigrationPhasePending(
                "target singleton cleanup did not remove the exact controller command gate."
            )
        window.update(
            {
                "status": "target-patched",
                "target_resource_version": str(
                    _mapping(updated.get("metadata")).get("resourceVersion") or ""
                ),
                "target_patched_at": _utc_now(),
            }
        )
        checkpoint_writer()
    except Exception as exc:
        patch_error = exc
    finally:
        _restore_in_place_slurmcluster_admission_window(
            window=window,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    if patch_error is not None:
        raise SoperatorMigrationPhasePending(
            "target singleton cleanup could not remove the controller command gate while "
            "the manager remained paused."
        ) from patch_error
    state["controller_gate_removed_at"] = str(state.get("controller_gate_removed_at") or _utc_now())
    checkpoint_writer()


def _finalize_in_place_target_native_controller_ha(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    target_ref: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    state = phase.get("in_place_target_native_controller_ha")
    if not isinstance(state, dict):
        return []
    if state.get("cleanup_status") == "verified":
        return ["Target-native controller HA cleanup reused from the phase-7 journal."]
    cleanup_status = str(state.get("cleanup_status") or "")
    if cleanup_status not in _IN_PLACE_TARGET_NATIVE_CLEANUP_RESUME_STATUSES:
        _verify_in_place_target_native_controller_ha(
            phase=phase,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            proof_stage="before-singleton-restoration",
        )
        config_name = f"{target_ref}-slurm-configs"
        config_map = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                f"configmap/{config_name}",
                "-o",
                "json",
            ],
            timeout_seconds=120,
        )
        slurm_conf = str(_mapping(config_map.get("data")).get("slurm.conf", "") or "")
        backup_line = re.compile(
            rf"(?m)^\s*SlurmctldHost={re.escape(_IN_PLACE_TARGET_HA_BACKUP_NAME)}\("
            rf"{re.escape(_IN_PLACE_TARGET_HA_BACKUP_SERVICE)}\.soperator\.svc\.cluster\.local\)\s*\n?"
        )
        singleton_conf, count = backup_line.subn("", slurm_conf)
        if count != 1:
            raise SoperatorMigrationPhasePending(
                "target-native controller HA cleanup requires one exact temporary backup host."
            )
        singleton_contract = _controller_bridge_client_config_contract(singleton_conf)
        if tuple(singleton_contract.get("controller_hosts", ())) != (
            f"controller-0({target_ref}-controller-svc)",
        ):
            raise SoperatorMigrationPhasePending(
                "target-native controller HA cleanup did not produce the exact target "
                "singleton controller config."
            )
        _patch_slurm_config_map_text(
            namespace=_SOPERATOR_NAMESPACE,
            name=config_name,
            config_key="slurm.conf",
            slurm_conf=singleton_conf,
            kube_context=kube_context,
            command_runner=command_runner,
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                "-i",
                "deployment/sconfigcontroller",
                "-c",
                "sconfigctrl",
                "--",
                "sh",
                "-ceu",
                (
                    "target=/mnt/jail/etc/slurm/slurm.conf; "
                    "staged=/mnt/jail/etc/slurm/.slurm.conf.cxcli-singleton; "
                    'cat > "$staged"; chmod 644 "$staged"; chown 0:0 "$staged"; '
                    'mv "$staged" "$target"'
                ),
            ],
            input_text=singleton_conf,
            timeout_seconds=120,
        )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "exec",
                "controller-0",
                "-c",
                "slurmctld",
                "--",
                "scontrol",
                "reconfigure",
            ],
            timeout_seconds=120,
        )
        state.update(
            {
                "cleanup_status": "singleton-config-accepted",
                "singleton_config_sha256": hashlib.sha256(
                    singleton_conf.encode("utf-8")
                ).hexdigest(),
                "singleton_config_accepted_at": _utc_now(),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        cleanup_status = "singleton-config-accepted"

    if cleanup_status == "singleton-config-accepted":
        backup = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                f"deployment/{_IN_PLACE_TARGET_HA_BACKUP_NAME}",
                "--ignore-not-found=true",
                "-o",
                "name",
            ],
            timeout_seconds=120,
            check=False,
        )
        if backup.returncode != 0:
            raise SoperatorMigrationPhasePending(
                "target-native controller HA cleanup could not inspect its temporary backup."
            )
        if backup.stdout.strip():
            command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "scale",
                    f"deployment/{_IN_PLACE_TARGET_HA_BACKUP_NAME}",
                    "--replicas=0",
                ],
                timeout_seconds=120,
            )
            command_runner(
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    _SOPERATOR_NAMESPACE,
                    "wait",
                    "--for=delete",
                    "pod",
                    "-l",
                    f"{_IN_PLACE_TARGET_HA_BACKUP_LABEL}=true",
                    "--timeout=180s",
                ],
                timeout_seconds=210,
                check=False,
            )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "delete",
                f"deployment/{_IN_PLACE_TARGET_HA_BACKUP_NAME}",
                f"service/{_IN_PLACE_TARGET_HA_BACKUP_SERVICE}",
                "--ignore-not-found=true",
            ],
            timeout_seconds=180,
        )
        remaining = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                f"deployment/{_IN_PLACE_TARGET_HA_BACKUP_NAME}",
                f"service/{_IN_PLACE_TARGET_HA_BACKUP_SERVICE}",
                "--ignore-not-found=true",
                "-o",
                "name",
            ],
            timeout_seconds=120,
            check=False,
        )
        if remaining.returncode != 0 or remaining.stdout.strip():
            raise SoperatorMigrationPhasePending(
                "target-native controller HA temporary backup retirement is not complete."
            )
        state.update(
            {
                "cleanup_status": "backup-retired",
                "backup_retired_at": str(state.get("backup_retired_at") or _utc_now()),
            }
        )
        if checkpoint_writer is not None:
            checkpoint_writer()
        cleanup_status = "backup-retired"

    if cleanup_status == "backup-retired":
        _remove_in_place_target_controller_command_gate(
            state=state,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        state["cleanup_status"] = "controller-gate-removed"
        if checkpoint_writer is not None:
            checkpoint_writer()
        cleanup_status = "controller-gate-removed"
    if cleanup_status not in {"controller-gate-removed", "manager-restoring"}:
        raise SoperatorMigrationPhasePending(
            f"target-native controller HA cleanup has an unsupported resume stage: "
            f"{cleanup_status or 'empty'}."
        )
    manager_pause = _mapping(phase.get("in_place_target_manager_pause"))
    manager_replicas = max(1, _positive_int(manager_pause.get("original_replicas"), fallback=1))
    state["cleanup_status"] = "manager-restoring"
    state["manager_restore_intent_at"] = str(state.get("manager_restore_intent_at") or _utc_now())
    if checkpoint_writer is not None:
        checkpoint_writer()
    command_runner(
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "scale",
            "deployment/soperator-manager",
            f"--replicas={manager_replicas}",
        ],
        timeout_seconds=120,
    )
    _kubectl_rollout_status(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=_SOPERATOR_NAMESPACE,
        resource="deployment/soperator-manager",
        timeout="10m",
    )
    deadline = time.monotonic() + 300
    last_detail = ""
    while True:
        ping = _kubectl_exec_login(
            command_runner=command_runner,
            kube_context=kube_context,
            args=("scontrol", "ping"),
            check=False,
            timeout_seconds=120,
        )
        last_detail = _command_detail(ping)
        if (
            ping.returncode == 0
            and re.search(
                r"Slurmctld\(primary\)\s+at\s+controller-0\s+is\s+UP",
                ping.stdout,
                re.IGNORECASE,
            )
            and _IN_PLACE_TARGET_HA_BACKUP_NAME not in ping.stdout
        ):
            break
        if time.monotonic() >= deadline:
            raise SoperatorMigrationPhasePending(
                "target-native controller HA cleanup did not restore the exact target "
                f"singleton: {last_detail}"
            )
        time.sleep(5)
    takeover = _mapping(
        _mapping(checkpoint.get("controller_bridge")).get("target_singleton_takeover")
    )
    if isinstance(takeover, dict):
        takeover.update(
            {
                "command_gate_applied": False,
                "command_gate_removed_at": _utc_now(),
                "only_primary_proven": True,
            }
        )
    state.update(
        {
            "cleanup_status": "verified",
            "manager_replicas": manager_replicas,
            "singleton_ping_sha256": hashlib.sha256(ping.stdout.encode("utf-8")).hexdigest(),
            "cleaned_at": _utc_now(),
        }
    )
    manager_pause_state = phase.get("in_place_target_manager_pause")
    if isinstance(manager_pause_state, dict):
        manager_pause_state.update(
            {"status": "restored", "restored_replicas": manager_replicas, "restored_at": _utc_now()}
        )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [
        "Target-native controller HA removed after provider replacement; exact target "
        "singleton config, controller command, and Soperator manager were restored."
    ]


def _in_place_worker_max_unavailable(
    *,
    strategy: str,
    raw_max_unavailable: object,
    resolved_all: Mapping[str, Any],
    group_id: str,
    group_size: int,
) -> int:
    maximum_unavailable = (
        _positive_int(resolved_all.get(group_id), fallback=0)
        if raw_max_unavailable == "all"
        else _positive_int(raw_max_unavailable, fallback=0)
    )
    minimum_unavailable = 0 if strategy == NODE_GROUP_ROLLOUT_SAFE_SURGE else 1
    if maximum_unavailable < minimum_unavailable or maximum_unavailable > group_size:
        raise RuntimeError(
            f"In-place max_unavailable is invalid for {group_id}: "
            f"{maximum_unavailable}/{group_size}."
        )
    return maximum_unavailable


def _in_place_worker_max_parallel_groups(raw_max_parallel_groups: object) -> int:
    max_parallel_groups = _positive_int(raw_max_parallel_groups, fallback=0)
    if not 1 <= max_parallel_groups <= MAX_PARALLEL_WORKER_GROUPS:
        raise RuntimeError(
            "In-place max_parallel_groups must be between 1 and "
            f"{MAX_PARALLEL_WORKER_GROUPS}."
        )
    return max_parallel_groups


def _in_place_operator_cancel_count(
    checkpoint: Mapping[str, Any],
    *,
    explicit_cancel_job_ids: Sequence[str],
) -> int:
    journal = _mapping(_mapping(checkpoint.get("slurm")).get("action_journal"))
    dispatched_action_ids = {
        str(action.get("action_id", "") or "").strip()
        for action in _sequence_of_mappings(journal.get("actions"))
        if str(action.get("kind", "") or "") == "cancel"
        and str(action.get("origin", "") or "") == "operator"
        and str(action.get("state", "") or "") in {"Dispatching", "Applied", "Indeterminate"}
        and str(action.get("action_id", "") or "").strip()
    }
    return max(
        len(dispatched_action_ids),
        len({str(job_id).strip() for job_id in explicit_cancel_job_ids if str(job_id).strip()}),
    )


def _in_place_job_disruption_evidence(
    groups_state: Mapping[str, Any],
) -> dict[str, Any]:
    """Summarize durable proof that provider dispatch did not disrupt jobs."""

    worker_groups = {
        str(group_id): state
        for group_id, state in groups_state.items()
        if isinstance(state, Mapping) and str(state.get("role", "") or "").startswith("worker")
    }
    if not worker_groups:
        return {"status": "not-applicable", "groups": {}}
    group_evidence: dict[str, Any] = {}
    for group_id, state in worker_groups.items():
        evidence = _mapping(state.get("final_dispatch_evidence"))
        active_jobs = [str(job) for job in evidence.get("active_job_ids", []) or [] if str(job)]
        group_evidence[group_id] = {
            "status": str(evidence.get("status", "") or "unknown"),
            "active_job_ids": active_jobs,
            "checked_at": str(evidence.get("checked_at", "") or ""),
        }
        if evidence.get("status") != "locked" or active_jobs:
            return {
                "status": "failed" if active_jobs else "unknown",
                "groups": group_evidence,
            }
    return {"status": "verified-zero", "groups": group_evidence}


def _in_place_worker_health_resume_ready(
    group_state: Mapping[str, Any], *, accepted_size: int
) -> bool:
    """Return whether provider dispatch is terminal and only worker health remains."""

    operation = _mapping(_mapping(group_state.get("target_update")).get("operation"))
    replacement_uids = {
        str(uid).strip() for uid in group_state.get("replacement_node_uids", []) or [] if str(uid)
    }
    return bool(
        group_state.get("status") == "provider-complete-health-pending"
        and operation.get("attempt_state") == "provider-terminal"
        and accepted_size > 0
        and len(replacement_uids) == accepted_size
    )


def _in_place_worker_provider_operation_resume_ready(
    group_state: Mapping[str, Any],
) -> bool:
    """Resume an accepted provider operation without rechecking retired slurmd Pods."""

    operation = _mapping(_mapping(group_state.get("target_update")).get("operation"))
    drain = _mapping(group_state.get("slurm_drain"))
    dispatch = _mapping(group_state.get("final_dispatch_evidence"))
    provider_drain = _mapping(group_state.get("kubernetes_provider_drain"))
    accepted_at = str(operation.get("accepted_at") or "").strip()
    checked_at = str(dispatch.get("checked_at") or "").strip()
    if not (
        operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES
        and _provider_operation_id_is_real(operation.get("provider_operation_id"))
        and accepted_at
        and drain.get("status") == "applied"
        and str(drain.get("reason") or "") == str(dispatch.get("reason") or "")
        and dispatch.get("status") == "locked"
        and not tuple(dispatch.get("active_job_ids") or ())
        and checked_at
        and provider_drain.get("status") == "drained"
    ):
        return False
    try:
        return _journal_timestamp(
            checked_at,
            field="worker final dispatch checked_at",
        ) <= _journal_timestamp(
            accepted_at,
            field="worker provider accepted_at",
        )
    except RuntimeError:
        return False


def _in_place_batch_impact_lines(
    prepared: Sequence[tuple[Mapping[str, Any], int]],
    blocked: Sequence[str],
) -> list[str]:
    lines = [
        f"{group.get('name') or group.get('id')}: permits {maximum}/{group.get('fixed_size')} "
        "unavailable"
        for group, maximum in prepared
    ]
    lines.extend(blocked)
    permitted = sum(maximum for _group, maximum in prepared)
    lines.append(f"Batch permits up to {permitted} worker nodes to be unavailable.")
    if any(
        maximum == _positive_int(group.get("fixed_size"), fallback=0) for group, maximum in prepared
    ):
        lines.append("Each full-group dispatch may temporarily have zero Ready nodes.")
    lines.append("Nebius may process fewer nodes concurrently than this permitted bound.")
    return lines


def _in_place_pause_false_job_control(
    *,
    checkpoint: dict[str, Any],
    source_report: Mapping[str, Any],
    worker_group_names: Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    job_policy: str | None,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None,
    interactive_prompt_pause: Callable[[], Any] | None,
    allow_resolved_interactive_job_policy: bool,
) -> list[str]:
    worker_nodes = _nodes_for_worker_groups(
        source_report=source_report,
        worker_node_groups=worker_group_names,
    )
    return _handle_external_upgrade_slurm_jobs(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=worker_nodes,
        policy=job_policy,
        cancel_job_ids=cancel_job_ids,
        requeue_job_ids=requeue_job_ids,
        wait_timeout_seconds=job_wait_timeout_seconds,
        refresh_interval_seconds=job_refresh_interval_seconds,
        decision_recorder=slurm_decision_recorder,
        interactive_prompt_pause=interactive_prompt_pause,
        allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
        include_pending=True,
        return_after_operator_action=True,
        held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
        held_job_checkpoint_writer=checkpoint_writer,
        slurm_action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
        slurm_action_checkpoint_writer=checkpoint_writer,
        slurm_controller_authority_provider=lambda: _external_upgrade_slurm_action_authority(
            checkpoint
        ),
    )


def _in_place_pause_true_job_control(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    source_report: Mapping[str, Any],
    worker_group_names: Sequence[str],
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    job_policy: str | None,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None,
    interactive_prompt_pause: Callable[[], Any] | None,
    allow_resolved_interactive_job_policy: bool,
) -> list[str]:
    worker_nodes = _nodes_for_worker_groups(
        source_report=source_report,
        worker_node_groups=worker_group_names,
    )
    if not worker_nodes:
        raise SoperatorMigrationPhasePending(
            "In-place scheduling pause could not resolve any accepted worker nodes."
        )
    checkpointed_records = _rolling_compute_checkpoint_pause_records(phase)

    def _record_intent(record: SlurmPartitionPauseRecord) -> None:
        _checkpoint_slurm_partition_pause_intent(
            phase=phase,
            record=record,
            checkpoint_writer=checkpoint_writer,
        )

    lines, live_records = _ensure_slurm_quiet(
        command_runner=command_runner,
        kube_context=kube_context,
        node_names=worker_nodes,
        job_policy=str(job_policy or "preserve"),
        cancel_job_ids=cancel_job_ids,
        requeue_job_ids=requeue_job_ids,
        job_wait_timeout_seconds=job_wait_timeout_seconds,
        job_refresh_interval_seconds=job_refresh_interval_seconds,
        slurm_decision_recorder=slurm_decision_recorder,
        slurm_pause_intent_recorder=_record_intent,
        interactive_prompt_pause=interactive_prompt_pause,
        allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
        slurm_scheduling_pause=True,
        held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
        held_job_checkpoint_writer=checkpoint_writer,
        slurm_action_journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
        slurm_action_checkpoint_writer=checkpoint_writer,
        slurm_controller_authority_provider=lambda: _external_upgrade_slurm_action_authority(
            checkpoint
        ),
        all_partitions=True,
    )
    records = _merge_slurm_partition_pause_records(checkpointed_records, live_records)
    phase["slurm_paused_partitions"] = [record.as_payload() for record in records]
    phase["slurm_partition_restore_manual_command"] = (
        _external_upgrade_slurm_partition_recovery_inspection_command(records) or None
    )
    phase["slurm_partition_restore_deferred_reason"] = (
        "worker, service-role, Jail slot-B, login and controller health gates remain"
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return [*lines, "In-place affected Slurm partitions remain paused through final health gates."]


def _execute_in_place_compute_migration_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None,
    job_policy: str | None,
    cancel_job_ids: Sequence[str],
    requeue_job_ids: Sequence[str],
    job_wait_timeout_seconds: int,
    job_refresh_interval_seconds: int,
    slurm_scheduling_pause: bool,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None,
    interactive_prompt_pause: Callable[[], Any] | None,
    allow_resolved_interactive_job_policy: bool,
    impact_reporter: Callable[[str], None] | None = None,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, "rolling-compute-migration")
    contract = _compute_migration_contract(payload, target_ref)
    campaign = _mapping(_target_onboarding(payload, target_ref).get("upgrade_path"))
    segment = _in_place_campaign_segment(campaign, checkpoint)
    planned_groups = _sequence_of_mappings(_mapping(segment.get("mk8s")).get("node_groups"))
    _require_in_place_jail_slot_switch(checkpoint=checkpoint, planned_groups=planned_groups)
    rollout = _mapping(contract.get("node_group_rollout"))
    worker = _mapping(rollout.get("worker"))
    strategy = str(rollout.get("strategy", "") or "").strip()
    if strategy == NODE_GROUP_ROLLOUT_ZERO_SURGE:
        max_surge = 0
        raw_max_unavailable = worker.get("max_unavailable")
    elif strategy == NODE_GROUP_ROLLOUT_SAFE_SURGE:
        max_surge = _positive_int(worker.get("max_surge"), fallback=0)
        raw_max_unavailable = 0
    else:
        raise RuntimeError("In-place node-group rollout strategy is invalid.")
    max_parallel = _in_place_worker_max_parallel_groups(worker.get("max_parallel_groups"))
    drain_timeout = str(worker.get("drain_timeout", "") or "").strip()
    resolved_all = _mapping(worker.get("resolved_max_unavailable"))
    phase.update(
        {
            "mode": COMPUTE_MIGRATION_MODE_IN_PLACE,
            "strategy": strategy,
            "slurm_scheduling_pause": slurm_scheduling_pause,
            "max_parallel_worker_groups": max_parallel,
            "worker_drain_timeout": drain_timeout,
        }
    )
    phase.setdefault("jobs_disruption_evidence", {"status": "unknown", "groups": {}})
    groups_state = phase.setdefault("in_place_node_groups", {})
    if not isinstance(groups_state, dict):
        raise RuntimeError("In-place node-group journal must be a mapping.")
    worker_groups = [
        group for group in planned_groups if str(group.get("role", "") or "").startswith("worker")
    ]
    service_groups = [
        group
        for role in ("login", "accounting", "controller", "system")
        for group in planned_groups
        if str(group.get("role", "") or "").strip() == role
    ]
    worker_group_names = tuple(
        str(group.get("name", "") or group.get("id", "")) for group in worker_groups
    )
    continuous_pause_required = slurm_scheduling_pause and _continuous_worker_pause_required(
        checkpoint
    )
    provider_rollout_started = any(
        isinstance(
            _mapping(_mapping(state).get("target_update")).get("operation"),
            Mapping,
        )
        for state in groups_state.values()
        if isinstance(state, Mapping)
    )
    lines: list[str] = []
    if not provider_rollout_started:
        lines.extend(
            _ensure_in_place_slurm_worker_runtime_identity(
                checkpoint=checkpoint,
                phase=phase,
                command_runner=command_runner,
                kube_context=kube_context,
                target_ref=target_ref,
                checkpoint_writer=checkpoint_writer,
            )
        )
    lines.extend(
        _ensure_continuous_worker_slurm_pause(
            checkpoint=checkpoint,
            source_report=source_report,
            worker_node_groups=worker_group_names,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
            job_policy=str(job_policy or "preserve"),
            cancel_job_ids=cancel_job_ids,
            requeue_job_ids=requeue_job_ids,
            job_wait_timeout_seconds=job_wait_timeout_seconds,
            job_refresh_interval_seconds=job_refresh_interval_seconds,
            slurm_decision_recorder=slurm_decision_recorder,
            interactive_prompt_pause=interactive_prompt_pause,
            allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
            slurm_scheduling_pause=slurm_scheduling_pause,
        )
    )
    if continuous_pause_required:
        _inherit_continuous_worker_slurm_pause_records(
            checkpoint=checkpoint,
            phase=phase,
            checkpoint_writer=checkpoint_writer,
        )
    if slurm_scheduling_pause and not continuous_pause_required:
        lines.extend(
            _in_place_pause_true_job_control(
                checkpoint=checkpoint,
                phase=phase,
                source_report=source_report,
                worker_group_names=worker_group_names,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                job_policy=job_policy,
                cancel_job_ids=cancel_job_ids,
                requeue_job_ids=requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                slurm_decision_recorder=slurm_decision_recorder,
                interactive_prompt_pause=interactive_prompt_pause,
                allow_resolved_interactive_job_policy=(allow_resolved_interactive_job_policy),
            )
        )
    elif not slurm_scheduling_pause:
        lines.extend(
            _in_place_pause_false_job_control(
                checkpoint=checkpoint,
                source_report=source_report,
                worker_group_names=worker_group_names,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
                job_policy=job_policy,
                cancel_job_ids=cancel_job_ids,
                requeue_job_ids=requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                slurm_decision_recorder=slurm_decision_recorder,
                interactive_prompt_pause=interactive_prompt_pause,
                allow_resolved_interactive_job_policy=(allow_resolved_interactive_job_policy),
            )
        )
    lines.extend(
        _require_in_place_continuity_resources(
            checkpoint=checkpoint,
            phase=phase,
            command_runner=command_runner,
            kube_context=kube_context,
            target_ref=target_ref,
            checkpoint_writer=checkpoint_writer,
            accepted_login_provider_operation_pending=(
                _accepted_in_place_login_provider_operation_pending(
                    phase=phase,
                    planned_groups=planned_groups,
                )
            ),
        )
    )
    continuity_verified_since_mutation = True
    shared_service_health_evidence: dict[str, Any] = {}
    shared_bridge_authority_evidence: dict[str, Any] = {}

    phase.pop("blocked_worker_groups", None)
    blocked: list[str] = []
    prepared: list[tuple[Mapping[str, Any], int]] = []
    mutation_performed = False

    # Service domains establish the continuity substrate used by every worker
    # batch.  Keep this sequence explicit: login continuity first, accounting
    # identity next, then roll controller/system under opposite-domain bridge
    # authority.  Workers are admitted only after all four health gates pass.
    for group in service_groups:
        role = str(group.get("role", "") or "")
        group_id = str(group.get("id", "") or "").strip()
        group_state = groups_state.setdefault(group_id, {})
        if not isinstance(group_state, dict):
            raise RuntimeError("In-place service-role journal entry must be a mapping.")
        completed_role_health = _mapping(
            _mapping(phase.get("in_place_service_role_health")).get(role)
        )
        reuse_during_worker_outage = _in_place_worker_outage_boundary_active(
            phase
        ) and _in_place_completed_service_health_reusable(
            group_state=group_state,
            role_health=completed_role_health,
        )
        authority_finalized = _in_place_service_role_authority_finalized(
            phase=phase,
            group_state=group_state,
        )
        if role == "login":
            lines.extend(
                _wait_for_login_session_policy(
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    policy=EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
                    timeout_seconds=0,
                )
            )
        if reuse_during_worker_outage:
            lines.append(
                f"In-place {role} bridge authority reused its post-provider proof while "
                "the exact worker outage boundary remains active."
            )
        elif authority_finalized:
            lines.append(
                f"In-place {role} provider replacement reused its completed journal after "
                "target-native singleton cleanup began."
            )
        else:
            lines.extend(
                _ensure_in_place_bridge_authority_outside_provider_domain(
                    checkpoint=checkpoint,
                    phase=phase,
                    role=role,
                    planned_groups=planned_groups,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                    shared_evidence=shared_bridge_authority_evidence,
                )
            )
        accounting_gate: dict[str, Any] | None = None
        if role == "accounting":
            service_health = phase.setdefault("in_place_service_role_health", {})
            if not isinstance(service_health, dict):
                raise RuntimeError("In-place service-role health journal must be a mapping.")
            accounting_health = service_health.setdefault("accounting", {})
            if not isinstance(accounting_health, dict):
                raise RuntimeError("In-place accounting health journal must be a mapping.")
            accounting_gate = accounting_health.setdefault("accounting_continuity", {})
            if not isinstance(accounting_gate, dict):
                raise RuntimeError("In-place accounting continuity journal must be a mapping.")
            if not _mapping(accounting_gate.get("baseline")):
                accounting_gate["baseline"] = _in_place_accounting_continuity_evidence(
                    phase=phase,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
                accounting_gate["status"] = "baseline-recorded"
                if checkpoint_writer is not None:
                    checkpoint_writer()
        changed, group_lines = _execute_one_in_place_node_group(
            checkpoint=checkpoint,
            group_state=group_state,
            planned_group=group,
            source_report=source_report,
            nebius_api=nebius_api,
            command_runner=command_runner,
            kube_context=kube_context,
            max_surge=0,
            max_unavailable=1,
            drain_timeout="none",
            checkpoint_writer=checkpoint_writer,
        )
        mutation_performed = mutation_performed or changed
        if changed:
            shared_service_health_evidence.clear()
            shared_bridge_authority_evidence.clear()
            continuity_verified_since_mutation = False
        lines.extend(group_lines)
        if not authority_finalized and not reuse_during_worker_outage:
            lines.extend(
                _rebind_in_place_bridge_domain_after_provider_roll(
                    checkpoint=checkpoint,
                    phase=phase,
                    role=role,
                    rolled_group_id=group_id,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
        if not changed and reuse_during_worker_outage:
            lines.append(
                f"In-place {role} replacement reused its checkpointed provider and "
                "service-health proof while workers remain behind their planned outage gate."
            )
        else:
            lines.extend(
                _verify_in_place_service_role_replacement_health(
                    checkpoint=checkpoint,
                    phase=phase,
                    role=role,
                    payload=payload,
                    source_report=source_report,
                    live_snapshot=live_snapshot,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    command_runner=command_runner,
                    checkpoint_writer=checkpoint_writer,
                    shared_evidence=shared_service_health_evidence,
                )
            )
        if role == "accounting" and accounting_gate is not None:
            if reuse_during_worker_outage and accounting_gate.get("status") == "verified":
                lines.append(
                    "In-place accounting continuity reused its post-provider catalog and "
                    "writer proof during the exact worker outage boundary."
                )
            else:
                observed_accounting = _in_place_accounting_continuity_evidence(
                    phase=phase,
                    target_ref=target_ref,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
                _verify_in_place_accounting_continuity(
                    baseline=_mapping(accounting_gate.get("baseline")),
                    observed=observed_accounting,
                )
                accounting_gate.update(
                    {
                        "status": "verified",
                        "observed": observed_accounting,
                        "verified_at": _utc_now(),
                    }
                )
                if checkpoint_writer is not None:
                    checkpoint_writer()
                lines.append(
                    "In-place accounting replacement preserved writer/PVC ownership, "
                    "accounts, users, associations, QOS, registrations, and history."
                )
        if continuity_verified_since_mutation:
            lines.append(
                f"In-place {role} continuity reused the invocation-scoped proof because "
                "no provider mutation occurred."
            )
        else:
            lines.extend(
                _require_in_place_continuity_resources(
                    checkpoint=checkpoint,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    target_ref=target_ref,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            continuity_verified_since_mutation = True

    for group in worker_groups:
        group_id = str(group.get("id", "") or "").strip()
        group_name = str(group.get("name", "") or group_id).strip()
        group_state = groups_state.setdefault(group_id, {})
        if not isinstance(group_state, dict):
            raise RuntimeError("In-place worker journal entry must be a mapping.")
        group_size = _positive_int(group.get("fixed_size"), fallback=0)
        maximum_unavailable = _in_place_worker_max_unavailable(
            strategy=strategy,
            raw_max_unavailable=raw_max_unavailable,
            resolved_all=resolved_all,
            group_id=group_id,
            group_size=group_size,
        )
        if _in_place_worker_provider_operation_resume_ready(group_state):
            # The provider accepted this exact operation only after the durable Slurm/job
            # and Kubernetes pre-drain proofs.  Its replacement Pods may intentionally be
            # absent or init-blocked, so re-running source-fleet checks here would create a
            # circular dependency before provider reconciliation.
            prepared.append((group, maximum_unavailable))
            continue
        if _in_place_worker_health_resume_ready(group_state, accepted_size=group_size):
            # Provider dispatch and the complete replacement UID transition are already
            # terminal.  Re-running the pre-dispatch Kubernetes eviction classifier here
            # can only inspect a stale source fleet and must not gate the replacement
            # health proof.  _execute_one_in_place_node_group still revalidates the live
            # provider identity, size, target template, Ready UIDs, and restored strategy.
            prepared.append((group, maximum_unavailable))
            continue
        try:
            if _mapping(group_state.get("slurm_drain")).get("status") == "applied":
                _revalidate_in_place_worker_group_lock(
                    group_state=group_state,
                    group_id=group_id,
                    group_name=group_name,
                    source_report=source_report,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            else:
                _apply_in_place_worker_group_lock(
                    checkpoint=checkpoint,
                    group_state=group_state,
                    group_id=group_id,
                    group_name=group_name,
                    source_report=source_report,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
        except SoperatorMigrationPhasePending as exc:
            blocked.append(f"{group_name}: blocked - {exc}")
            _restore_in_place_worker_drain_rescheduling_guard(
                group_state=group_state,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            _restore_in_place_worker_group_lock(
                group_state=group_state,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
            continue
        prepared.append((group, maximum_unavailable))

    impact_lines = _in_place_batch_impact_lines(prepared, blocked)
    phase["batch_impact"] = {
        "status": "displayed" if prepared else "blocked",
        "prepared_group_ids": [str(group.get("id") or "") for group, _maximum in prepared],
        "blocked": list(blocked),
        "permitted_unavailable": sum(maximum for _group, maximum in prepared),
        "lines": list(impact_lines),
        "displayed_at": _utc_now(),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    if impact_reporter is not None:
        impact_reporter("In-place worker batch impact:\n" + "\n".join(impact_lines))
    lines.extend(impact_lines)

    worker_cancellation = threading.Event()

    def _run_worker(item: tuple[Mapping[str, Any], int]) -> tuple[bool, list[str]]:
        group, maximum_unavailable = item
        group_id = str(group.get("id", "") or "").strip()
        group_state = groups_state.setdefault(group_id, {})
        if not isinstance(group_state, dict):
            raise RuntimeError("In-place worker journal entry must be a mapping.")
        try:
            return _execute_one_in_place_node_group(
                checkpoint=checkpoint,
                group_state=group_state,
                planned_group=group,
                source_report=source_report,
                nebius_api=nebius_api,
                command_runner=command_runner,
                kube_context=kube_context,
                max_surge=max_surge,
                max_unavailable=maximum_unavailable,
                drain_timeout=drain_timeout,
                checkpoint_writer=checkpoint_writer,
                restore_worker_lock=False,
                cancellation_event=worker_cancellation,
            )
        except SoperatorMigrationPhasePending:
            target_operation = _mapping(group_state.get("target_update"))
            operation = _mapping(target_operation.get("operation"))
            if not operation or operation.get("attempt_state") == "intent-recorded":
                _restore_in_place_worker_group_lock(
                    group_state=group_state,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            raise

    executor = ThreadPoolExecutor(max_workers=max(1, max_parallel))
    futures: dict[Any, Mapping[str, Any]] = {}
    try:
        futures = {executor.submit(_run_worker, item): item[0] for item in prepared}
        for future in as_completed(futures):
            group = futures[future]
            try:
                changed, group_lines = future.result()
            except SoperatorMigrationPhasePending as exc:
                blocked.append(f"{group.get('name') or group.get('id')}: {exc}")
                continue
            mutation_performed = mutation_performed or changed
            lines.extend(group_lines)
    except BaseException:
        worker_cancellation.set()
        for future in futures:
            future.cancel()
        executor.shutdown(wait=True, cancel_futures=True)
        raise
    else:
        executor.shutdown(wait=True)
    health_pending_states = [
        state
        for state in groups_state.values()
        if isinstance(state, dict) and state.get("status") == "provider-complete-health-pending"
    ]
    if health_pending_states:
        lines.extend(
            _verify_in_place_worker_replacement_health(
                checkpoint=checkpoint,
                phase=phase,
                payload=payload,
                source_report=source_report,
                live_snapshot=live_snapshot,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
        for group_state in health_pending_states:
            lines.extend(
                _restore_in_place_worker_group_lock(
                    group_state=group_state,
                    command_runner=command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=checkpoint_writer,
                )
            )
            group_state["status"] = "completed"
            group_state["completed_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    if blocked:
        phase["blocked_worker_groups"] = blocked
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "In-place worker groups remain blocked while other clear groups were allowed "
            "to advance: " + "; ".join(blocked)
        )

    lines.extend(
        _finalize_in_place_target_native_controller_ha(
            checkpoint=checkpoint,
            phase=phase,
            target_ref=target_ref,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    phase["status"] = "completed"
    phase["completed_at"] = _utc_now()
    phase["jobs_disruption_evidence"] = _in_place_job_disruption_evidence(groups_state)
    phase["jobs_disrupted_by_provider_rollout"] = (
        0 if phase["jobs_disruption_evidence"]["status"] == "verified-zero" else None
    )
    cancelled_count = _in_place_operator_cancel_count(
        checkpoint,
        explicit_cancel_job_ids=cancel_job_ids,
    )
    phase["jobs_explicitly_cancelled_by_operator"] = cancelled_count
    if checkpoint_writer is not None:
        checkpoint_writer()
    return mutation_performed, lines + [
        "Jobs explicitly cancelled by operator: " + str(cancelled_count),
        "Jobs disrupted by provider rollout: 0",
    ]


def _require_worker_replacement_jail_activation(
    checkpoint: Mapping[str, Any],
) -> None:
    populate = _accepted_populate_jail_phase_state(checkpoint)
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    has_gpu_replacement = any(
        state.get("gpu") is True for _key, state in _target_worker_replacement_states(checkpoint)
    )
    required_statuses = {
        "rootfs handoff": str(
            _mapping(populate.get("rootfs_handoff_verification")).get("status", "") or ""
        ),
        "GPU post-population": str(
            _mapping(populate.get("gpu_post_population")).get("status", "") or ""
        ),
        "GPU pre-activation fleet": str(
            _mapping(populate.get(_GPU_PRE_ACTIVATION_FLEET_GATE_KEY)).get("status", "") or ""
        ),
        "GPU activation boundary": str(
            _mapping(
                _mapping(populate.get(_GPU_PRE_ACTIVATION_FLEET_GATE_KEY)).get(
                    "activation_revalidation"
                )
            ).get("status", "")
            or ""
        ),
        "GPU workload release": str(
            _mapping(populate.get("post_jail_gpu_workload_release_gate")).get("status", "") or ""
        ),
        "GPU post-activation": str(
            _mapping(populate.get("gpu_post_activation")).get("status", "") or ""
        ),
    }
    if not str(populate.get("completed_at", "") or "").strip():
        raise SoperatorMigrationPhasePending(
            "target worker replacement activation waits for completed passive Jail "
            "population and active-slot handoff."
        )
    if required_statuses["rootfs handoff"] != "verified":
        raise SoperatorMigrationPhasePending(
            "target worker replacement activation waits for verified active Jail/rootfs "
            "consumer handoff."
        )
    expected_gpu_status = "passed" if has_gpu_replacement else "not-required"
    for label in (
        "GPU post-population",
        "GPU pre-activation fleet",
        "GPU activation boundary",
        "GPU workload release",
        "GPU post-activation",
    ):
        if required_statuses[label] != expected_gpu_status:
            raise SoperatorMigrationPhasePending(
                "target worker replacement activation waits for the completed Jail/GPU "
                f"gate '{label}' (expected {expected_gpu_status}, observed "
                f"{required_statuses[label] or 'missing'})."
            )
    if rolling.get("worker_replacements_finalized") is True:
        return


def _journaled_node_group_scale(
    *,
    checkpoint: dict[str, Any],
    resource_state: dict[str, Any],
    nebius_api: SoperatorMigrationNebiusApi,
    node_group_id: str,
    desired_count: int,
    checkpoint_writer: Callable[[], None] | None,
) -> Mapping[str, Any]:
    """Apply or reconcile one exact fixed-size scale operation."""

    live = _node_group_payload_by_id(nebius_api=nebius_api, node_group_id=node_group_id)
    live_count = _node_group_fixed_count_allow_zero(live)
    operation = _mapping(resource_state.get("operation"))
    postcondition = {"fixed_node_count": desired_count}
    if live_count == desired_count:
        if operation.get("attempt_state") in _PROVIDER_OPERATION_TERMINAL_STATES:
            if _mapping(operation.get("verified_postcondition")) != postcondition:
                raise RuntimeError(
                    "recovery-required: terminal node-group scale evidence does not match "
                    f"the accepted count for {node_group_id}."
                )
            return live
        if _provider_operation_id_is_real(operation.get("provider_operation_id")):
            _record_reconciled_provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=resource_state,
                nebius_api=nebius_api,
                provider_payload=live,
                operation_kind="MK8s node-group scale",
                resource_id=node_group_id,
                checkpoint_writer=checkpoint_writer,
                verified_postcondition=postcondition,
            )
            return live
        raise RuntimeError(
            "recovery-required: node-group capacity reached an exchange waypoint without "
            f"an accepted provider operation ID: {node_group_id}={desired_count}."
        )
    if resource_state and not _provider_operation_request_is_retryable(resource_state):
        _require_journaled_provider_operation_before_unmet_postcondition(
            resource_state=resource_state,
            nebius_api=nebius_api,
            operation_kind="MK8s node-group scale",
            resource_id=node_group_id,
        )
    metadata = _mapping(live.get("metadata"))
    operation_entry = _provider_operation_intent_for_request(
        checkpoint=checkpoint,
        resource_state=resource_state,
        operation_kind="mk8s-node-group-scale",
        resource_id=node_group_id,
        resource_uid=str(metadata.get("uid") or metadata.get("id") or node_group_id),
        resource_version=_node_group_resource_version(live),
        intended_postcondition=postcondition,
        checkpoint_writer=checkpoint_writer,
    )
    _provider_operation_requested(
        checkpoint=checkpoint,
        resource_state=resource_state,
        operation_entry=operation_entry,
        checkpoint_writer=checkpoint_writer,
    )
    try:
        scaled = _scale_node_group(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
            count=desired_count,
            operation_accepted=_provider_operation_acceptance_callback(
                checkpoint=checkpoint,
                resource_state=resource_state,
                operation_entry=operation_entry,
                checkpoint_writer=checkpoint_writer,
            ),
        )
        if _node_group_fixed_count_allow_zero(scaled) != desired_count:
            raise RuntimeError(
                f"Nebius node group {node_group_id} did not report "
                f"fixed_node_count={desired_count}."
            )
        _provider_operation_terminal(
            checkpoint=checkpoint,
            resource_state=resource_state,
            operation_entry=operation_entry,
            provider_payload=scaled,
            operation_kind="MK8s node-group scale",
            resource_id=node_group_id,
            verified_postcondition=postcondition,
            checkpoint_writer=checkpoint_writer,
        )
        return scaled
    except (Exception, KeyboardInterrupt) as exc:
        if operation_entry.get("attempt_state") != "provider-terminal":
            _provider_operation_pending(
                checkpoint=checkpoint,
                resource_state=resource_state,
                operation_entry=operation_entry,
                reason=str(exc),
                checkpoint_writer=checkpoint_writer,
            )
        raise


def _exchange_blue_green_worker_capacity(
    *,
    checkpoint: dict[str, Any],
    phase: dict[str, Any],
    rolling: Mapping[str, Any],
    old_groups: Mapping[str, Any],
    worker_group_names: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    checkpoint_writer: Callable[[], None] | None,
) -> list[str]:
    """Exchange source capacity for target capacity using the accepted bootstrap slice."""

    target_groups = _mapping(rolling.get("target_node_groups"))
    raw_exchanges = phase.setdefault("worker_capacity_exchanges", {})
    if not isinstance(raw_exchanges, dict):
        raise RuntimeError("recovery-required: worker capacity exchanges must be a mapping.")
    lines: list[str] = []
    for group_name in worker_group_names:
        old_group = _mapping(old_groups.get(group_name))
        source_id = str(old_group.get("id", "") or "").strip()
        replacement_keys = [
            str(item) for item in old_group.get("replacement_keys", []) if str(item).strip()
        ]
        worker_keys = [
            key
            for key in replacement_keys
            if str(_mapping(target_groups.get(key)).get("compute_role", "") or "") == "worker"
        ]
        if not source_id or len(worker_keys) != 1:
            raise RuntimeError(
                "recovery-required: blue-green capacity exchange requires one exact "
                f"worker replacement binding for {group_name}."
            )
        target_state = _mapping(target_groups.get(worker_keys[0]))
        target_id = str(target_state.get("id", "") or "").strip()
        accepted_count = _positive_int(
            old_group.get("source_fixed_node_count") or target_state.get("source_fixed_node_count"),
            fallback=0,
        )
        bootstrap_count = _positive_int(target_state.get("bootstrap_node_count"), fallback=0)
        if not target_id or accepted_count < 1 or not 1 <= bootstrap_count <= accepted_count:
            raise RuntimeError(
                "recovery-required: blue-green capacity exchange has an incomplete accepted "
                f"size/bootstrap contract for {group_name}."
            )
        raw_exchange = raw_exchanges.setdefault(group_name, {})
        if not isinstance(raw_exchange, dict):
            raise RuntimeError(
                f"recovery-required: capacity exchange state for {group_name} must be a mapping."
            )
        immutable = {
            "source_node_group_id": source_id,
            "target_node_group_id": target_id,
            "accepted_node_count": accepted_count,
            "bootstrap_node_count": bootstrap_count,
        }
        if raw_exchange and any(raw_exchange.get(key) != value for key, value in immutable.items()):
            raise RuntimeError(
                f"recovery-required: accepted capacity exchange identity drifted for {group_name}."
            )
        raw_exchange.update(immutable)
        raw_steps = raw_exchange.setdefault("steps", [])
        if not isinstance(raw_steps, list) or any(not isinstance(item, dict) for item in raw_steps):
            raise RuntimeError(
                f"recovery-required: capacity exchange steps for {group_name} are invalid."
            )
        incomplete = [item for item in raw_steps if item.get("completed_at") is None]
        if len(incomplete) > 1:
            raise RuntimeError(
                f"recovery-required: multiple incomplete capacity steps exist for {group_name}."
            )
        if incomplete:
            step = incomplete[0]
            _journaled_node_group_scale(
                checkpoint=checkpoint,
                resource_state=step.setdefault("source_scale", {}),
                nebius_api=nebius_api,
                node_group_id=source_id,
                desired_count=int(step["source_after"]),
                checkpoint_writer=checkpoint_writer,
            )
            _journaled_node_group_scale(
                checkpoint=checkpoint,
                resource_state=step.setdefault("target_scale", {}),
                nebius_api=nebius_api,
                node_group_id=target_id,
                desired_count=int(step["target_after"]),
                checkpoint_writer=checkpoint_writer,
            )
            step["completed_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
        source_live = _node_group_payload_by_id(nebius_api=nebius_api, node_group_id=source_id)
        target_live = _node_group_payload_by_id(nebius_api=nebius_api, node_group_id=target_id)
        source_count = _node_group_fixed_count_allow_zero(source_live)
        target_count = _node_group_fixed_count_allow_zero(target_live)
        if raw_steps:
            last = raw_steps[-1]
            if last.get("completed_at") and (
                source_count != int(last["source_after"])
                or target_count != int(last["target_after"])
            ):
                raise RuntimeError(
                    "recovery-required: live capacity drifted from the last completed "
                    f"exchange waypoint for {group_name}."
                )
        while target_count < accepted_count:
            delta = min(bootstrap_count, accepted_count - target_count, source_count)
            if delta < 1:
                raise RuntimeError(
                    f"recovery-required: no source capacity remains to complete {group_name}."
                )
            step = {
                "index": len(raw_steps) + 1,
                "source_before": source_count,
                "target_before": target_count,
                "delta": delta,
                "source_after": source_count - delta,
                "target_after": target_count + delta,
                "source_scale": {},
                "target_scale": {},
                "intent_recorded_at": _utc_now(),
            }
            raw_steps.append(step)
            if checkpoint_writer is not None:
                checkpoint_writer()
            source_live = _journaled_node_group_scale(
                checkpoint=checkpoint,
                resource_state=step["source_scale"],
                nebius_api=nebius_api,
                node_group_id=source_id,
                desired_count=step["source_after"],
                checkpoint_writer=checkpoint_writer,
            )
            target_live = _journaled_node_group_scale(
                checkpoint=checkpoint,
                resource_state=step["target_scale"],
                nebius_api=nebius_api,
                node_group_id=target_id,
                desired_count=step["target_after"],
                checkpoint_writer=checkpoint_writer,
            )
            source_count = _node_group_fixed_count_allow_zero(source_live)
            target_count = _node_group_fixed_count_allow_zero(target_live)
            step["completed_at"] = _utc_now()
            if checkpoint_writer is not None:
                checkpoint_writer()
        if target_count != accepted_count:
            raise RuntimeError(
                f"recovery-required: target capacity exchange did not converge for {group_name}."
            )
        if isinstance(target_groups.get(worker_keys[0]), dict):
            target_groups[worker_keys[0]]["fixed_node_count"] = accepted_count
        raw_exchange["completed_at"] = raw_exchange.get("completed_at") or _utc_now()
        raw_exchange["remaining_source_overlap"] = source_count
        if checkpoint_writer is not None:
            checkpoint_writer()
        lines.append(
            f"Worker capacity exchanged incrementally for {group_name}: target "
            f"{target_count}/{accepted_count}, remaining source overlap {source_count}."
        )
    return lines


def _execute_retire_old_resources_phase(
    *,
    checkpoint: dict[str, Any],
    payload: Mapping[str, Any],
    target_ref: str,
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    checkpoint_writer: Callable[[], None] | None = None,
) -> tuple[bool, list[str]]:
    phase = _phase_state(checkpoint, "retire-old-resources")
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    bridge = checkpoint.get("controller_bridge")
    if not isinstance(bridge, dict):
        raise SoperatorMigrationPhasePending(
            "old-resource retirement requires the v6 controller bridge journal."
        )
    validate_bridge_journal(bridge)
    validation = _mapping(
        _mapping(checkpoint.get("phase_state")).get("validation-and-rollback-hold")
    )
    if _positive_int(validation.get("validation_contract_revision"), fallback=0) < (
        _VALIDATION_HOLD_REVISION
    ):
        raise SoperatorMigrationPhasePending(
            "old-resource retirement requires the completed validation and rollback hold."
        )
    action_journal = _checkpoint_slurm_action_journal_for_job_control(checkpoint)
    action_blockers = slurm_action_partition_restore_blockers(action_journal)
    if action_blockers:
        raise SoperatorMigrationPhasePending(
            "old-resource retirement is blocked until every durable TUI action is "
            "Applied or Rejected; Queued, Dispatching and Indeterminate actions remain."
        )
    bridge_lines: list[str] = []
    bridge_stage = BridgeStage(str(bridge.get("stage") or ""))
    bridge_handoff_reconciled = False
    target_values: Mapping[str, Any] | None = None
    target_version = str(
        _mapping(source_report.get("report")).get("target_version", "") or ""
    ).strip()
    if bridge_stage is BridgeStage.SOURCE_HA_ACTIVE:
        target_values = _patch_target_values_for_compute(
            payload=payload,
            target_ref=target_ref,
            checkpoint=checkpoint,
            source_report=source_report,
            live_snapshot=live_snapshot,
        )
        bridge_lines.extend(
            _upgrade_controller_bridge_to_target_version(
                checkpoint=checkpoint,
                values=target_values,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
        bridge_handoff_reconciled = True
        validate_bridge_journal(bridge)
        bridge_stage = BridgeStage(str(bridge.get("stage") or ""))
    if bridge_stage is not BridgeStage.HANDOFF_VALIDATED:
        if bridge_stage not in {
            BridgeStage.TARGET_HA_ACTIVE,
            BridgeStage.BRIDGE_FENCED,
            BridgeStage.TARGET_SINGLETON_ACTIVE,
        }:
            raise SoperatorMigrationPhasePending(
                "old-resource retirement requires a validated target singleton handoff while "
                "the stopped bridge remains available for roll-forward recovery."
            )
        if target_values is None:
            target_values = _patch_target_values_for_compute(
                payload=payload,
                target_ref=target_ref,
                checkpoint=checkpoint,
                source_report=source_report,
                live_snapshot=live_snapshot,
            )
        bridge_lines.extend(
            _handoff_controller_bridge_to_target_singleton(
                checkpoint=checkpoint,
                ungated_values=target_values,
                target_ref=target_ref,
                expected_version=target_version,
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint_writer=checkpoint_writer,
            )
        )
        bridge_handoff_reconciled = True
        validate_bridge_journal(bridge)
        if str(bridge.get("stage") or "") != BridgeStage.HANDOFF_VALIDATED.value:
            raise SoperatorMigrationPhasePending(
                "old-resource retirement could not prove the target singleton handoff; "
                "the controller bridge remains available for roll-forward recovery."
            )
    login_lines = _complete_upgrade_login_handoff(
        checkpoint=checkpoint,
        command_runner=command_runner,
        kube_context=kube_context,
        checkpoint_writer=checkpoint_writer,
    )
    login_lines.extend(
        _release_completed_upgrade_login_hold(
            checkpoint=checkpoint,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
    )
    old_groups_raw = _mapping(rolling.get("old_node_groups"))
    old_group_names = tuple(str(name) for name in old_groups_raw if str(name).strip())
    if not old_group_names:
        phase["skipped_reason"] = "no source-to-replacement node-group bindings"
        if _snapshot_storage(source_report):
            phase["storage_retirement"] = "retained"
        if checkpoint_writer is not None:
            checkpoint_writer()
        return bridge_handoff_reconciled, [
            *bridge_lines,
            *login_lines,
            "Retire old resources skipped: no source-to-replacement node-group bindings"
            + (
                ", and source storage remains retained."
                if phase.get("storage_retirement") == "retained"
                else "."
            ),
        ]

    checkpoint_retired_ids = {
        str(item.get("node_group_id", "") or "").strip()
        for item in _sequence_of_mappings(phase.get("retired_node_groups"))
        if str(item.get("node_group_id", "") or "").strip()
    }
    all_worker_group_names = tuple(
        str(group_name)
        for group_name, raw_item in old_groups_raw.items()
        if "worker"
        in {str(role) for role in _mapping(raw_item).get("roles", []) if str(role).strip()}
    )
    worker_group_names = tuple(
        group_name
        for group_name in all_worker_group_names
        if str(_mapping(old_groups_raw.get(group_name)).get("id", "") or "").strip()
        not in checkpoint_retired_ids
    )
    worker_readiness_lines: list[str] = []
    worker_retirement_checks: dict[str, Any] = {}
    blocked_worker_groups: list[str] = []
    if worker_group_names:
        if rolling.get("worker_replacements_finalized") is True:
            raise RuntimeError(
                "recovery-required: source worker groups remain after target worker "
                "capacity was marked finalized."
            )
        _require_worker_replacement_jail_activation(checkpoint)
        worker_readiness_lines = _verify_target_worker_replacement_node_groups(
            checkpoint=checkpoint,
            nebius_api=nebius_api,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        staged_values = _patch_target_values_for_compute(
            payload=payload,
            target_ref=target_ref,
            checkpoint=checkpoint,
            source_report=source_report,
            live_snapshot=live_snapshot,
            stage_worker_replacement_capacity=True,
        )
        image_lock = _checkpoint_target_slurmd_image_lock(
            checkpoint=checkpoint,
            payload=payload,
            target_ref=target_ref,
            checkpoint_writer=checkpoint_writer,
        )
        target_version = str(
            _mapping(source_report.get("report")).get("target_version", "") or ""
        ).strip()
        if not str(phase.get("worker_replacement_capacity_staged_at", "") or "").strip():
            _helm_upgrade_target_soperator(
                command_runner=command_runner,
                kube_context=kube_context,
                values=staged_values,
                expected_version=target_version,
                wait=False,
            )
            phase["worker_replacement_capacity_staged_at"] = _utc_now()
            phase["worker_replacement_capacity_values_sha256"] = _fingerprint(staged_values)
            if checkpoint_writer is not None:
                checkpoint_writer()
        _wait_for_target_worker_nodesets_ready(
            command_runner=command_runner,
            kube_context=kube_context,
            values=staged_values,
            timeout_seconds=1800,
        )
        worker_readiness_lines.extend(
            _verify_target_worker_replacement_workloads(
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                image_lock=image_lock,
                checkpoint_writer=checkpoint_writer,
            )
        )
        gpu_validation = phase.setdefault("target_worker_replacement_gpu_validation", {})
        if not isinstance(gpu_validation, dict):
            raise RuntimeError(
                "recovery-required: target worker replacement GPU validation state "
                "must be a mapping."
            )
        gpu_gate_key = "target_worker_replacement_gpu_release_gate"
        gpu_validation[gpu_gate_key] = copy.deepcopy(dict(_mapping(rolling.get(gpu_gate_key))))
        worker_readiness_lines.extend(
            _ensure_jail_gpu_post_activation_gate(
                phase=gpu_validation,
                command_runner=command_runner,
                kube_context=kube_context,
                values=staged_values,
                checkpoint_writer=checkpoint_writer,
                release_gate_key=gpu_gate_key,
                replacement_phase=rolling,
                mutation_guard=None,
            )
        )
        for group_name in worker_group_names:
            clear, evidence = _source_worker_group_retirement_evidence(
                group_name=group_name,
                source_report=source_report,
                command_runner=command_runner,
                kube_context=kube_context,
            )
            worker_retirement_checks[group_name] = evidence
            if not clear:
                blocked_worker_groups.append(group_name)
        phase["worker_retirement_checks"] = worker_retirement_checks
        if checkpoint_writer is not None:
            checkpoint_writer()
    retirable_group_names = tuple(
        group_name for group_name in old_group_names if group_name not in blocked_worker_groups
    )
    old_nodes = _nodes_for_source_groups(
        source_report=source_report,
        source_groups=retirable_group_names,
    )
    if old_nodes:
        _uncordon_or_drain_nodes(
            command_runner=command_runner,
            kube_context=kube_context,
            nodes=old_nodes,
            action="cordon",
        )
        phase["old_nodes_cordoned_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    exchange_lines: list[str] = []
    retirable_worker_groups = tuple(
        group_name for group_name in worker_group_names if group_name in retirable_group_names
    )
    if retirable_worker_groups:
        exchange_lines = _exchange_blue_green_worker_capacity(
            checkpoint=checkpoint,
            phase=phase,
            rolling=rolling,
            old_groups=old_groups_raw,
            worker_group_names=retirable_worker_groups,
            nebius_api=nebius_api,
            checkpoint_writer=checkpoint_writer,
        )
        _uncordon_or_drain_nodes(
            command_runner=command_runner,
            kube_context=kube_context,
            nodes=old_nodes,
            action="drain",
        )
        phase["old_nodes_drained_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    existing_retired = _sequence_of_mappings(phase.get("retired_node_groups"))
    retired: list[dict[str, str]] = [
        {
            "source_group": str(item.get("source_group", "") or ""),
            "node_group_id": str(item.get("node_group_id", "") or ""),
        }
        for item in existing_retired
        if str(item.get("node_group_id", "") or "").strip()
    ]
    retired_ids = {item["node_group_id"] for item in retired}
    raw_operation_states = phase.setdefault("node_group_operations", {})
    if not isinstance(raw_operation_states, dict):
        raise RuntimeError(
            "recovery-required: retire-old-resources node-group operation state must be a mapping."
        )
    for group_name, item in old_groups_raw.items():
        if group_name not in retirable_group_names:
            continue
        node_group_id = str(_mapping(item).get("id", "") or "").strip()
        if not node_group_id:
            continue
        raw_group_state = raw_operation_states.setdefault(node_group_id, {})
        if not isinstance(raw_group_state, dict):
            raise RuntimeError(
                "recovery-required: retire-old-resources operation state must be a "
                f"mapping for {node_group_id}."
            )
        scale_state = raw_group_state.setdefault("scale_to_zero", {})
        delete_state = raw_group_state.setdefault("delete", {})
        if not isinstance(scale_state, dict) or not isinstance(delete_state, dict):
            raise RuntimeError(
                "recovery-required: retire-old-resources scale/delete state is invalid "
                f"for {node_group_id}."
            )
        try:
            live_node_group: Mapping[str, Any] | None = _node_group_payload_by_id(
                nebius_api=nebius_api,
                node_group_id=node_group_id,
            )
        except Exception as exc:
            if not _sdk_not_found_error(exc):
                raise
            live_node_group = None
        if live_node_group is None:
            if _provider_operation_is_pre_request_intent(delete_state):
                if node_group_id not in retired_ids:
                    retired.append(
                        {"source_group": str(group_name), "node_group_id": node_group_id}
                    )
                    retired_ids.add(node_group_id)
                phase["retired_node_groups"] = retired
                _discard_pre_request_provider_intent(
                    checkpoint=checkpoint,
                    resource_state=delete_state,
                    checkpoint_writer=checkpoint_writer,
                )
                continue
            delete_operation = _mapping(delete_state.get("operation"))
            if delete_operation.get(
                "attempt_state"
            ) not in _PROVIDER_OPERATION_TERMINAL_STATES and _provider_operation_id_is_real(
                delete_operation.get("provider_operation_id")
            ):
                _record_reconciled_provider_operation_terminal(
                    checkpoint=checkpoint,
                    resource_state=delete_state,
                    nebius_api=nebius_api,
                    provider_payload={},
                    operation_kind="MK8s node-group delete",
                    resource_id=node_group_id,
                    checkpoint_writer=checkpoint_writer,
                    verified_postcondition={"deleted": True},
                )
                delete_operation = _mapping(delete_state.get("operation"))
            if delete_operation.get(
                "attempt_state"
            ) not in _PROVIDER_OPERATION_TERMINAL_STATES or not (
                _provider_operation_id_is_real(delete_operation.get("provider_operation_id"))
            ):
                raise RuntimeError(
                    "recovery-required: retired node group is absent from live Nebius "
                    f"state, but its delete operation is not terminal with an exact "
                    f"provider operation ID: {node_group_id}."
                )
            if node_group_id not in retired_ids:
                retired.append({"source_group": str(group_name), "node_group_id": node_group_id})
                retired_ids.add(node_group_id)
            continue

        if delete_state and not _provider_operation_request_is_retryable(delete_state):
            _require_journaled_provider_operation_before_unmet_postcondition(
                resource_state=delete_state,
                nebius_api=nebius_api,
                operation_kind="MK8s node-group delete",
                resource_id=node_group_id,
            )

        if _node_group_fixed_count_allow_zero(live_node_group) != 0:
            if scale_state and not _provider_operation_request_is_retryable(scale_state):
                _require_journaled_provider_operation_before_unmet_postcondition(
                    resource_state=scale_state,
                    nebius_api=nebius_api,
                    operation_kind="MK8s node-group scale",
                    resource_id=node_group_id,
                )
            metadata = _mapping(live_node_group.get("metadata"))
            scale_postcondition = {"fixed_node_count": 0}
            scale_operation = _provider_operation_intent_for_request(
                checkpoint=checkpoint,
                resource_state=scale_state,
                operation_kind="mk8s-node-group-scale",
                resource_id=node_group_id,
                resource_uid=str(metadata.get("uid") or metadata.get("id") or node_group_id),
                resource_version=_node_group_resource_version(live_node_group),
                intended_postcondition=scale_postcondition,
                checkpoint_writer=checkpoint_writer,
            )
            _provider_operation_requested(
                checkpoint=checkpoint,
                resource_state=scale_state,
                operation_entry=scale_operation,
                checkpoint_writer=checkpoint_writer,
            )
            try:
                live_node_group = _scale_node_group(
                    nebius_api=nebius_api,
                    node_group_id=node_group_id,
                    count=0,
                    operation_accepted=_provider_operation_acceptance_callback(
                        checkpoint=checkpoint,
                        resource_state=scale_state,
                        operation_entry=scale_operation,
                        checkpoint_writer=checkpoint_writer,
                    ),
                )
                if not live_node_group or _node_group_fixed_count_allow_zero(live_node_group) != 0:
                    raise RuntimeError(
                        f"Nebius node group {node_group_id} did not report fixed_node_count=0."
                    )
                _provider_operation_terminal(
                    checkpoint=checkpoint,
                    resource_state=scale_state,
                    operation_entry=scale_operation,
                    provider_payload=live_node_group,
                    operation_kind="MK8s node-group scale",
                    resource_id=node_group_id,
                    verified_postcondition=scale_postcondition,
                    checkpoint_writer=checkpoint_writer,
                )
            except (Exception, KeyboardInterrupt) as exc:
                if scale_operation.get("attempt_state") != "provider-terminal":
                    _provider_operation_pending(
                        checkpoint=checkpoint,
                        resource_state=scale_state,
                        operation_entry=scale_operation,
                        reason=str(exc),
                        checkpoint_writer=checkpoint_writer,
                    )
                raise
            phase["last_scaled_node_group_id"] = node_group_id
        elif scale_state:
            if _provider_operation_is_pre_request_intent(scale_state):
                _discard_pre_request_provider_intent(
                    checkpoint=checkpoint,
                    resource_state=scale_state,
                    checkpoint_writer=checkpoint_writer,
                )
                scale_state = raw_group_state.setdefault("scale_to_zero", {})
            scale_operation = _mapping(scale_state.get("operation"))
            if scale_operation.get(
                "attempt_state"
            ) not in _PROVIDER_OPERATION_TERMINAL_STATES and _provider_operation_id_is_real(
                scale_operation.get("provider_operation_id")
            ):
                _record_reconciled_provider_operation_terminal(
                    checkpoint=checkpoint,
                    resource_state=scale_state,
                    nebius_api=nebius_api,
                    provider_payload=live_node_group,
                    operation_kind="MK8s node-group scale",
                    resource_id=node_group_id,
                    checkpoint_writer=checkpoint_writer,
                    verified_postcondition={"fixed_node_count": 0},
                )
                scale_operation = _mapping(scale_state.get("operation"))
            if scale_operation and (
                scale_operation.get("attempt_state") not in _PROVIDER_OPERATION_TERMINAL_STATES
                or not _provider_operation_id_is_real(scale_operation.get("provider_operation_id"))
            ):
                raise RuntimeError(
                    "recovery-required: old node group is scaled to zero, but the v6 "
                    f"journal lacks terminal provider evidence for {node_group_id}."
                )

        metadata = _mapping(live_node_group.get("metadata"))
        delete_postcondition = {"deleted": True}
        delete_operation = _provider_operation_intent_for_request(
            checkpoint=checkpoint,
            resource_state=delete_state,
            operation_kind="mk8s-node-group-delete",
            resource_id=node_group_id,
            resource_uid=str(metadata.get("uid") or metadata.get("id") or node_group_id),
            resource_version=_node_group_resource_version(live_node_group),
            intended_postcondition=delete_postcondition,
            checkpoint_writer=checkpoint_writer,
        )
        _provider_operation_requested(
            checkpoint=checkpoint,
            resource_state=delete_state,
            operation_entry=delete_operation,
            checkpoint_writer=checkpoint_writer,
        )
        try:
            delete_result = _delete_node_group(
                nebius_api=nebius_api,
                node_group_id=node_group_id,
                operation_accepted=_provider_operation_acceptance_callback(
                    checkpoint=checkpoint,
                    resource_state=delete_state,
                    operation_entry=delete_operation,
                    checkpoint_writer=checkpoint_writer,
                ),
            )
            _provider_operation_terminal(
                checkpoint=checkpoint,
                resource_state=delete_state,
                operation_entry=delete_operation,
                provider_payload=delete_result,
                operation_kind="MK8s node-group delete",
                resource_id=node_group_id,
                verified_postcondition=delete_postcondition,
                checkpoint_writer=checkpoint_writer,
            )
        except (Exception, KeyboardInterrupt) as exc:
            if delete_operation.get("attempt_state") != "provider-terminal":
                _provider_operation_pending(
                    checkpoint=checkpoint,
                    resource_state=delete_state,
                    operation_entry=delete_operation,
                    reason=str(exc),
                    checkpoint_writer=checkpoint_writer,
                )
            raise
        if node_group_id not in retired_ids:
            retired.append({"source_group": str(group_name), "node_group_id": node_group_id})
            retired_ids.add(node_group_id)
        phase["retired_node_groups"] = retired
        if checkpoint_writer is not None:
            checkpoint_writer()
    if blocked_worker_groups:
        phase["pending_worker_groups"] = blocked_worker_groups
        if checkpoint_writer is not None:
            checkpoint_writer()
        raise SoperatorMigrationPhasePending(
            "source worker retirement is waiting for active jobs and worker epilogs to "
            "finish; untouched groups: " + ", ".join(blocked_worker_groups) + "."
        )
    phase.pop("pending_worker_groups", None)
    if all_worker_group_names and rolling.get("worker_replacements_finalized") is not True:
        expected_worker_ids = {
            str(_mapping(old_groups_raw.get(group_name)).get("id", "") or "").strip()
            for group_name in all_worker_group_names
        }
        if not expected_worker_ids or not expected_worker_ids <= retired_ids:
            raise SoperatorMigrationPhasePending(
                "target worker capacity cannot return to its final replica count until "
                "every exact source worker node group is retired."
            )
        if not _mapping(rolling.get("target_worker_replacement_workload_proof")):
            raise RuntimeError(
                "recovery-required: source worker groups were retired without the durable "
                "target replacement workload proof."
            )
        final_values = _patch_target_values_for_compute(
            payload=payload,
            target_ref=target_ref,
            checkpoint=checkpoint,
            source_report=source_report,
            live_snapshot=live_snapshot,
        )
        target_version = str(
            _mapping(source_report.get("report")).get("target_version", "") or ""
        ).strip()
        _helm_upgrade_target_soperator(
            command_runner=command_runner,
            kube_context=kube_context,
            values=final_values,
            expected_version=target_version,
            wait=False,
        )
        phase["worker_final_capacity_apply_started_at"] = (
            phase.get("worker_final_capacity_apply_started_at") or _utc_now()
        )
        phase["worker_final_capacity_values_sha256"] = _fingerprint(final_values)
        if checkpoint_writer is not None:
            checkpoint_writer()
        _wait_for_target_worker_nodesets_ready(
            command_runner=command_runner,
            kube_context=kube_context,
            values=final_values,
            timeout_seconds=1800,
        )
        worker_readiness_lines.extend(
            _verify_target_worker_replacement_node_groups(
                checkpoint=checkpoint,
                nebius_api=nebius_api,
                command_runner=command_runner,
                kube_context=kube_context,
                checkpoint_writer=checkpoint_writer,
            )
        )
        image_lock = _checkpoint_target_slurmd_image_lock(
            checkpoint=checkpoint,
            payload=payload,
            target_ref=target_ref,
            checkpoint_writer=checkpoint_writer,
        )
        worker_readiness_lines.extend(
            _verify_target_worker_replacement_workloads(
                checkpoint=checkpoint,
                command_runner=command_runner,
                kube_context=kube_context,
                image_lock=image_lock,
                checkpoint_writer=checkpoint_writer,
                final_capacity=True,
            )
        )
        final_gpu_validation = phase.setdefault("target_worker_final_gpu_validation", {})
        if not isinstance(final_gpu_validation, dict):
            raise RuntimeError(
                "recovery-required: final target worker GPU validation state must be a mapping."
            )
        final_gpu_gate_key = "target_worker_final_gpu_release_gate"
        final_gpu_validation[final_gpu_gate_key] = copy.deepcopy(
            dict(_mapping(rolling.get(final_gpu_gate_key)))
        )
        worker_readiness_lines.extend(
            _ensure_jail_gpu_post_activation_gate(
                phase=final_gpu_validation,
                command_runner=command_runner,
                kube_context=kube_context,
                values=final_values,
                checkpoint_writer=checkpoint_writer,
                release_gate_key=final_gpu_gate_key,
                replacement_phase=rolling,
                mutation_guard=None,
            )
        )
        rolling["worker_replacements_finalized"] = True
        rolling["worker_replacements_finalized_at"] = _utc_now()
        phase["worker_final_capacity_verified_at"] = _utc_now()
        if checkpoint_writer is not None:
            checkpoint_writer()
    if not retired:
        raise SoperatorMigrationPhasePending(
            "retire-old-resources found replaced service-role groups in the checkpoint, but no "
            "Nebius node group ids were recorded."
        )
    phase["retired_node_groups"] = retired
    if _snapshot_storage(source_report):
        phase["storage_retirement"] = "held"
    if checkpoint_writer is not None:
        checkpoint_writer()
    return True, [
        *bridge_lines,
        *login_lines,
        *worker_readiness_lines,
        *exchange_lines,
        "Retired replaced source node groups after worker allocation/epilog clearance: "
        + ", ".join(f"{item['source_group']} ({item['node_group_id']})" for item in retired),
    ]


def _load_checkpoint(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"External Soperator upgrade checkpoint is invalid JSON: {path}"
        ) from exc
    if not isinstance(payload, dict):
        raise RuntimeError(f"External Soperator upgrade checkpoint must be a JSON object: {path}")
    if payload.get("schema") != SOPERATOR_MIGRATION_EXECUTION_SCHEMA:
        raise RuntimeError(_unsupported_checkpoint_schema_message(path))
    _validate_checkpoint_journal_contract(payload)
    return payload


def _write_text_atomic(
    path: Path,
    content: str,
    *,
    encoding: str = "utf-8",
    file_mode: int | None = None,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    data = content.encode(encoding)
    resolved_file_mode = file_mode if file_mode is not None else _replacement_text_file_mode(path)
    fd = -1
    temp_path: Path | None = None
    try:
        fd, raw_temp_path = tempfile.mkstemp(
            prefix=f".{path.name}.",
            suffix=".tmp",
            dir=path.parent,
        )
        temp_path = Path(raw_temp_path)
        with os.fdopen(fd, "wb") as handle:
            fd = -1
            os.fchmod(handle.fileno(), resolved_file_mode)
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if fd >= 0:
            os.close(fd)
        if temp_path is not None:
            temp_path.unlink(missing_ok=True)


def _replacement_text_file_mode(path: Path) -> int:
    with suppress(OSError):
        return stat.S_IMODE(path.stat().st_mode)
    return _default_text_file_mode(path.parent, path.name)


def _default_text_file_mode(parent: Path, name: str) -> int:
    for _attempt in range(100):
        probe_path = parent / f".{name}.{uuid4().hex}.mode"
        fd = -1
        try:
            fd = os.open(probe_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o666)
            return stat.S_IMODE(os.fstat(fd).st_mode)
        except FileExistsError:
            continue
        finally:
            if fd >= 0:
                os.close(fd)
                probe_path.unlink(missing_ok=True)
    return 0o644


def _secure_checkpoint_directories(parent: Path) -> None:
    state_root = next(
        (candidate for candidate in (parent, *parent.parents) if candidate.name == ".nebius-cxcli"),
        parent,
    )
    state_root.mkdir(parents=True, exist_ok=True, mode=0o700)
    directories: list[Path] = []
    current = parent
    while True:
        directories.append(current)
        if current == state_root:
            break
        current = current.parent
    for directory in reversed(directories):
        directory.mkdir(exist_ok=True, mode=0o700)
        directory.chmod(0o700)


_CHECKPOINT_WRITE_LOCK_TIMEOUT_SECONDS = 30.0


@contextmanager
def _checkpoint_write_lock(path: Path) -> Iterator[None]:
    """Serialize checkpoint writers across the upgrade and jobs processes."""

    _secure_checkpoint_directories(path.parent)
    lock_path = path.with_name(f"{path.name}.lock")
    fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o600)
    os.fchmod(fd, 0o600)
    deadline = time.monotonic() + _CHECKPOINT_WRITE_LOCK_TIMEOUT_SECONDS
    try:
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError as exc:
                if time.monotonic() >= deadline:
                    raise RuntimeError(
                        "recovery-required: timed out acquiring the external Soperator "
                        f"operation-journal lock {lock_path}; no checkpoint was changed."
                    ) from exc
                time.sleep(0.05)
        yield
    finally:
        with suppress(OSError):
            fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


def _journal_timestamp(value: object, *, field: str) -> datetime:
    text = str(value or "").strip()
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError as exc:
        raise RuntimeError(f"Slurm action journal {field} must be an ISO timestamp.") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return parsed.astimezone(UTC)


def _newer_journal_mapping(
    local: Mapping[str, Any],
    disk: Mapping[str, Any],
    *,
    timestamp_field: str,
    label: str,
) -> dict[str, Any]:
    local_raw_time = str(local.get(timestamp_field, "") or "").strip()
    disk_raw_time = str(disk.get(timestamp_field, "") or "").strip()
    if not local_raw_time or not disk_raw_time:
        if local_raw_time and not disk_raw_time:
            return copy.deepcopy(dict(local))
        if disk_raw_time and not local_raw_time:
            return copy.deepcopy(dict(disk))
        if dict(local) != dict(disk):
            raise RuntimeError(
                f"recovery-required: concurrent Slurm action journal {label} observations "
                "lack timestamps and have different content."
            )
        return copy.deepcopy(dict(disk))
    local_time = _journal_timestamp(local_raw_time, field=f"{label}.{timestamp_field}")
    disk_time = _journal_timestamp(disk_raw_time, field=f"{label}.{timestamp_field}")
    if local_time == disk_time and dict(local) != dict(disk):
        raise RuntimeError(
            f"recovery-required: concurrent Slurm action journal {label} observations "
            "have the same timestamp but different content."
        )
    return copy.deepcopy(dict(local if local_time > disk_time else disk))


def _slurm_action_record_history_prefix(
    prefix: Sequence[Any],
    complete: Sequence[Any],
) -> bool:
    return len(prefix) <= len(complete) and list(prefix) == list(complete[: len(prefix)])


def _merge_slurm_action_record(
    local: Mapping[str, Any],
    disk: Mapping[str, Any],
) -> dict[str, Any]:
    immutable_fields = (
        "action_id",
        "batch_id",
        "kind",
        "origin",
        "authority_generation",
        "binding",
        "intended_postcondition",
        "accepted_authority_epoch",
        "accepted_at",
    )
    if any(local.get(field) != disk.get(field) for field in immutable_fields):
        raise RuntimeError(
            "recovery-required: concurrent Slurm action writers changed immutable action "
            f"identity {local.get('action_id') or disk.get('action_id')}."
        )
    local_history = local.get("transitions")
    disk_history = disk.get("transitions")
    if not isinstance(local_history, Sequence) or isinstance(local_history, (str, bytes)):
        raise RuntimeError("Slurm action transitions must be a sequence.")
    if not isinstance(disk_history, Sequence) or isinstance(disk_history, (str, bytes)):
        raise RuntimeError("Slurm action transitions must be a sequence.")
    if _slurm_action_record_history_prefix(disk_history, local_history):
        selected = local
    elif _slurm_action_record_history_prefix(local_history, disk_history):
        selected = disk
    else:
        raise RuntimeError(
            "recovery-required: concurrent Slurm action writers produced divergent terminal "
            f"history for action {local.get('action_id')}. No result was overwritten."
        )
    if len(local_history) == len(disk_history) and dict(local) != dict(disk):
        raise RuntimeError(
            "recovery-required: concurrent Slurm action writers changed action content "
            f"without a state transition for {local.get('action_id')}."
        )
    return copy.deepcopy(dict(selected))


def _merge_slurm_action_journals(
    local: Mapping[str, Any],
    disk: Mapping[str, Any],
) -> dict[str, Any]:
    """Merge monotonic action records without losing a concurrent TUI intent."""

    validate_slurm_action_journal(local)
    validate_slurm_action_journal(disk)
    local_broker = {
        "mode": local.get("broker_mode"),
        "updated_at": local.get("broker_mode_updated_at"),
    }
    disk_broker = {
        "mode": disk.get("broker_mode"),
        "updated_at": disk.get("broker_mode_updated_at"),
    }
    local_broker_time = _journal_timestamp(
        local_broker["updated_at"], field="broker_mode_updated_at"
    )
    disk_broker_time = _journal_timestamp(disk_broker["updated_at"], field="broker_mode_updated_at")
    if local_broker_time == disk_broker_time and local_broker != disk_broker:
        raise RuntimeError(
            "recovery-required: concurrent Slurm action writers disagree on broker mode."
        )
    local_broker_selected = local_broker_time > disk_broker_time
    selected_broker = local_broker if local_broker_selected else disk_broker

    generation_fields = (
        "active_authority_generation",
        "authority_generation_updated_at",
        "authority_generations",
        "partition_restore_boundary",
        "target_finalization_boundary",
    )
    local_generation = {field: local.get(field) for field in generation_fields}
    disk_generation = {field: disk.get(field) for field in generation_fields}
    local_generation_time = _journal_timestamp(
        local_generation["authority_generation_updated_at"],
        field="authority_generation_updated_at",
    )
    disk_generation_time = _journal_timestamp(
        disk_generation["authority_generation_updated_at"],
        field="authority_generation_updated_at",
    )
    if local_generation_time == disk_generation_time and local_generation != disk_generation:
        raise RuntimeError(
            "recovery-required: concurrent Slurm action writers disagree on the authority "
            "generation boundary."
        )
    selected_generation = (
        local_generation if local_generation_time > disk_generation_time else disk_generation
    )
    selected_active_generation = int(selected_generation["active_authority_generation"] or 0)
    selected_restore_boundary = _mapping(selected_generation["partition_restore_boundary"])

    local_actions = {
        str(item.get("action_id", "")): item
        for item in local.get("actions", [])
        if isinstance(item, Mapping)
    }
    disk_actions = {
        str(item.get("action_id", "")): item
        for item in disk.get("actions", [])
        if isinstance(item, Mapping)
    }
    if selected_broker["mode"] == SLURM_ACTION_ADMISSION_CLOSED and not local_broker_selected:
        # Actions already persisted by the TUI before the closure lock was won are accepted
        # work and merge below. An intent whose writer loses to an already durable closure
        # was never accepted and must fail instead of appearing after the final boundary.
        late_local_action_ids = sorted(set(local_actions) - set(disk_actions))
        if late_local_action_ids:
            raise RuntimeError(
                "Slurm action admission closed before the concurrent TUI intent was "
                "durably accepted; no late action was queued. Refresh the jobs screen."
            )
    ordered_ids = list(disk_actions)
    ordered_ids.extend(action_id for action_id in local_actions if action_id not in disk_actions)
    merged_actions: list[dict[str, Any]] = []
    for action_id in ordered_ids:
        local_action = local_actions.get(action_id)
        disk_action = disk_actions.get(action_id)
        if local_action is None:
            selected_action = copy.deepcopy(dict(disk_action or {}))
        elif disk_action is None:
            selected_action = copy.deepcopy(dict(local_action))
        else:
            selected_action = _merge_slurm_action_record(local_action, disk_action)
            local_history = list(local_action.get("transitions", []))
            disk_history = list(disk_action.get("transitions", []))
            if (
                len(local_history) > len(disk_history)
                and local_action.get("state") == SLURM_ACTION_DISPATCHING
                and selected_broker["mode"]
                not in {"dispatch-enabled", SLURM_ACTION_ADMISSION_CLOSED}
            ):
                raise RuntimeError(
                    f"Slurm action broker changed to {selected_broker['mode']} before "
                    "dispatch claim; "
                    "the action remains queued and no RPC was sent."
                )
        if (
            selected_action.get("state") == SLURM_ACTION_DISPATCHING
            and (disk_action is None or disk_action.get("state") != SLURM_ACTION_DISPATCHING)
            and selected_broker["mode"] not in {"dispatch-enabled", SLURM_ACTION_ADMISSION_CLOSED}
        ):
            raise RuntimeError(
                f"Slurm action broker changed to {selected_broker['mode']} before "
                "dispatch claim; "
                "the action remains queued and no RPC was sent."
            )
        action_generation = int(selected_action.get("authority_generation", 0) or 0)
        if (
            selected_restore_boundary
            and action_generation <= int(selected_restore_boundary.get("sealed_generation", -1))
            and selected_action.get("state") in SLURM_ACTION_BLOCKING_STATES
        ):
            if selected_action.get("state") != SLURM_ACTION_QUEUED:
                raise RuntimeError(
                    "recovery-required: an old-generation Slurm action reached Dispatching or "
                    "Indeterminate concurrently with the target-authority boundary; its outcome "
                    "must be reconciled before partition restoration."
                )
            selected_action["authority_generation"] = selected_active_generation
            selected_action["carried_from_authority_generation"] = action_generation
            selected_action["carried_at"] = selected_generation["authority_generation_updated_at"]
        merged_actions.append(selected_action)

    if (
        disk_broker.get("mode") == "dispatch-enabled"
        and selected_broker.get("mode") != "dispatch-enabled"
        and any(action.get("state") == SLURM_ACTION_DISPATCHING for action in disk_actions.values())
    ):
        raise RuntimeError(
            "Slurm action dispatch is in flight; the broker cannot enter a non-dispatch mode "
            "until that action has one definitive or Indeterminate result."
        )

    merged = copy.deepcopy(dict(disk))
    merged["broker_mode"] = selected_broker["mode"]
    merged["broker_mode_updated_at"] = selected_broker["updated_at"]
    for field, value in selected_generation.items():
        merged[field] = copy.deepcopy(value)
    merged["actions"] = merged_actions
    merged["controller"] = _newer_journal_mapping(
        _mapping(local.get("controller")),
        _mapping(disk.get("controller")),
        timestamp_field="observed_at",
        label="controller",
    )
    merged_login = _newer_journal_mapping(
        _mapping(local.get("login")),
        _mapping(disk.get("login")),
        timestamp_field="observed_at",
        label="login",
    )
    acknowledgement_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    for source in (_mapping(disk.get("login")), _mapping(local.get("login"))):
        for acknowledgement in _sequence_of_mappings(source.get("exit_acknowledgements")):
            key = (
                str(acknowledgement.get("socket_fingerprint") or ""),
                str(acknowledgement.get("absence_observed_at") or ""),
            )
            existing_acknowledgement = acknowledgement_by_key.get(key)
            if existing_acknowledgement is not None and existing_acknowledgement != dict(
                acknowledgement
            ):
                raise RuntimeError(
                    "recovery-required: concurrent login-exit acknowledgements differ for "
                    f"protected socket fingerprint {key[0]}."
                )
            acknowledgement_by_key[key] = copy.deepcopy(dict(acknowledgement))
    merged_login["exit_acknowledgements"] = list(acknowledgement_by_key.values())
    merged["login"] = merged_login
    merged_snapshots = copy.deepcopy(dict(_mapping(disk.get("job_snapshots"))))
    for job_id, raw_local_snapshot in _mapping(local.get("job_snapshots")).items():
        local_snapshot = _validate_slurm_action_job_snapshot(raw_local_snapshot, job_id=job_id)
        raw_disk_snapshot = merged_snapshots.get(job_id)
        if raw_disk_snapshot is None:
            merged_snapshots[job_id] = copy.deepcopy(local_snapshot)
            continue
        disk_snapshot = _validate_slurm_action_job_snapshot(raw_disk_snapshot, job_id=job_id)
        merged_snapshots[job_id] = _newer_journal_mapping(
            local_snapshot,
            disk_snapshot,
            timestamp_field="observed_at",
            label=f"job_snapshots.{job_id}",
        )
    if merged_snapshots:
        merged["job_snapshots"] = merged_snapshots
    validate_slurm_action_journal(merged)
    return merged


def _write_checkpoint_unlocked(path: Path, checkpoint: Mapping[str, Any]) -> None:
    _write_text_atomic(
        path,
        json.dumps(to_plain_data(checkpoint), indent=2, sort_keys=True) + "\n",
        file_mode=0o600,
    )


def _write_checkpoint(path: Path, checkpoint: Mapping[str, Any]) -> None:
    with _checkpoint_write_lock(path):
        if path.exists():
            disk_checkpoint = _load_checkpoint(path)
            if disk_checkpoint is None:  # pragma: no cover - exists/read race is lock-protected
                raise RuntimeError(f"External Soperator checkpoint disappeared: {path}")
            local_journal = ensure_slurm_action_journal(
                checkpoint if isinstance(checkpoint, dict) else dict(checkpoint)
            )
            disk_journal = ensure_slurm_action_journal(disk_checkpoint)
            merged_journal = _merge_slurm_action_journals(local_journal, disk_journal)
            if isinstance(checkpoint, dict):
                checkpoint_slurm = checkpoint.setdefault("slurm", {})
                if not isinstance(checkpoint_slurm, dict):
                    raise RuntimeError("External Soperator checkpoint slurm state must be mutable.")
                local_journal.clear()
                local_journal.update(copy.deepcopy(merged_journal))
                checkpoint_slurm["action_journal"] = local_journal
            else:
                mutable_checkpoint = copy.deepcopy(dict(checkpoint))
                mutable_slurm = mutable_checkpoint.setdefault("slurm", {})
                if not isinstance(mutable_slurm, dict):
                    raise RuntimeError("External Soperator checkpoint slurm state must be mutable.")
                mutable_slurm["action_journal"] = merged_journal
                checkpoint = mutable_checkpoint
        _write_checkpoint_unlocked(path, checkpoint)


def _write_external_upgrade_action_journal(
    path: Path,
    journal: dict[str, Any],
) -> None:
    """Persist only TUI-owned journal state without overwriting upgrade progress."""

    with _checkpoint_write_lock(path):
        checkpoint = _load_checkpoint(path)
        if checkpoint is None:
            raise RuntimeError(
                f"External Soperator jobs screen requires an active checkpoint at {path}."
            )
        disk_journal = ensure_slurm_action_journal(checkpoint)
        merged_journal = _merge_slurm_action_journals(journal, disk_journal)
        checkpoint_slurm = checkpoint.setdefault("slurm", {})
        if not isinstance(checkpoint_slurm, dict):
            raise RuntimeError("External Soperator checkpoint slurm state must be mutable.")
        checkpoint_slurm["action_journal"] = merged_journal
        _write_checkpoint_unlocked(path, checkpoint)
        journal.clear()
        journal.update(copy.deepcopy(merged_journal))


def _clear_completed_pending_phase(checkpoint: dict[str, Any], phase_id: str) -> bool:
    if str(checkpoint.get("pending_phase", "") or "") != phase_id:
        return False
    checkpoint["pending_phase"] = "none"
    checkpoint["pending_reason"] = ""
    _append_event(checkpoint, "execute-pending-cleared", phase=phase_id)
    return True


def _phase_report_status(
    phase_id: str,
    *,
    completed_phases: set[str],
    pending_phase: str,
) -> str:
    if phase_id in completed_phases:
        return "passed"
    if pending_phase == phase_id:
        return "pending"
    return "not_run"


_EXTERNAL_UPGRADE_REPORT_VERIFICATION_STATUSES = frozenset(
    {"passed", "failed", "skipped", "not_run", "incomplete"}
)
_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES = frozenset(
    {
        "approved",
        "available",
        "captured",
        "complete",
        "completed",
        "current",
        "failed",
        "blocked",
        "drift-detected",
        "import-reconciled",
        "imported-paused",
        "incomplete",
        "manual",
        "matched",
        "not_applicable",
        "not-evaluated",
        "not-recorded",
        "not-required",
        "not-run",
        "not_run",
        "passed",
        "pending",
        "ready",
        "refreshed",
        "remaining",
        "restored",
        "restoring",
        "skipped",
        "verified",
    }
)


def _external_upgrade_report_enum(
    value: object,
    *,
    allowed: frozenset[str],
    fallback: str,
) -> str:
    text = str(value or "").strip()
    return text if text in allowed else fallback


def _external_upgrade_report_timestamp(value: object) -> str:
    """Return one canonical UTC timestamp or an empty value.

    Parsing is deliberately strict so arbitrary checkpoint strings cannot become report
    content merely because they were stored under a timestamp-shaped key.
    """

    text = str(value or "").strip()
    if not text:
        return ""
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return ""
    if parsed.tzinfo is None:
        return ""
    return parsed.astimezone(UTC).isoformat()


def _external_upgrade_report_nonnegative_int(value: object) -> int | None:
    if isinstance(value, bool):
        return None
    try:
        result = int(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None
    return result if result >= 0 else None


def _external_upgrade_report_nonnegative_seconds(value: object) -> float:
    if isinstance(value, bool):
        return 0.0
    try:
        result = float(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return 0.0
    return round(result, 3) if math.isfinite(result) and result >= 0 else 0.0


def _external_upgrade_elapsed_text(value: object) -> str:
    total_seconds = max(0, int(round(_external_upgrade_report_nonnegative_seconds(value))))
    hours, remainder = divmod(total_seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"


def _external_upgrade_report_timing(checkpoint: Mapping[str, Any]) -> dict[str, Any]:
    timing = _mapping(checkpoint.get("upgrade_timing"))
    started_at = _external_upgrade_report_timestamp(timing.get("started_at"))
    completed_at = _external_upgrade_report_timestamp(timing.get("completed_at"))
    elapsed_seconds = _external_upgrade_report_nonnegative_seconds(
        timing.get("active_elapsed_seconds")
    )
    attempt_count = _external_upgrade_report_nonnegative_int(timing.get("attempt_count")) or 0
    return {
        "scope": "active-execute-command-time",
        "started_at": started_at,
        "completed_at": completed_at,
        "elapsed_seconds": elapsed_seconds,
        "elapsed_time": _external_upgrade_elapsed_text(elapsed_seconds),
        "attempt_count": attempt_count,
    }


def _refresh_external_upgrade_timing_payload(
    checkpoint: dict[str, Any],
    *,
    attempt_base_seconds: float,
    attempt_started_monotonic: float,
    now_monotonic: float,
    completed: bool = False,
    completed_at: str = "",
) -> bool:
    timing = dict(_mapping(checkpoint.get("upgrade_timing")))
    if _external_upgrade_report_timestamp(timing.get("completed_at")):
        return True
    current_elapsed = max(0.0, now_monotonic - attempt_started_monotonic)
    timing["active_elapsed_seconds"] = round(
        _external_upgrade_report_nonnegative_seconds(attempt_base_seconds) + current_elapsed,
        3,
    )
    if completed:
        timing["completed_at"] = _external_upgrade_report_timestamp(
            completed_at
        ) or _external_upgrade_report_timestamp(_utc_now())
    checkpoint["upgrade_timing"] = timing
    return completed


def _external_upgrade_report_version(value: object) -> str:
    """Allow only the product version forms used by the locked upgrade campaign."""

    text = str(value or "").strip()
    if len(text) <= 128 and re.fullmatch(
        r"[0-9]+(?:\.[0-9]+){1,3}(?:-[a-z0-9]+(?:\.[0-9]+)*)*",
        text,
    ):
        return text
    return "unknown"


def _external_upgrade_report_phase_metrics(
    phase_id: str,
    phase: Mapping[str, Any],
    *,
    checkpoint: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Project phase state into fixed, identifier-free counters and statuses."""

    checkpoint = _mapping(checkpoint)
    if phase_id == "discovery-and-plan":
        planned = {
            str(item or "").strip()
            for item in checkpoint.get("planned_phases", []) or []
            if str(item or "").strip() in _SUPPORTED_EXECUTE_PHASE_IDS
        }
        return {"planned_phase_count": len(planned)}
    if phase_id == "customer-approval":
        approved_at = _external_upgrade_report_timestamp(checkpoint.get("customer_approved_at"))
        return {
            "approval_recorded": bool(approved_at),
            **({"approved_at": approved_at} if approved_at else {}),
        }
    if phase_id == "create-aligned-sfs":
        return {
            "filesystem_count": len(_mapping(phase.get("filesystems"))),
            "expected_filesystem_count": len(
                _soperator_storage_keys_for_target(payload={}, target_ref="")
            ),
        }
    if phase_id == _CONTROLLER_HA_BRIDGE_PHASE_ID:
        return {
            "bridge_stage": _external_upgrade_report_enum(
                phase.get("bridge_stage"),
                allowed=frozenset(stage.value for stage in BridgeStage),
                fallback="unknown",
            )
        }
    if phase_id == _EXTERNAL_NODE_TEMPLATE_PHASE_ID:
        control_plane = _mapping(phase.get("control_plane"))
        return {
            "control_plane_status": _external_upgrade_report_enum(
                control_plane.get("status") or phase.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="unknown",
            ),
            "observed_version": _external_upgrade_report_version(
                control_plane.get("current_version")
            ),
            "target_version": _external_upgrade_report_version(control_plane.get("target_version")),
        }
    if phase_id == _TARGET_GPU_STACK_PHASE_ID:
        return {"chart_count": len(_sequence_of_mappings(phase.get("charts")))}
    if phase_id == "online-bulk-data-sync":
        return {"copy_job_count": len(_mapping(phase.get("jobs")))}
    if phase_id == "rolling-compute-migration":
        mode = _external_upgrade_report_enum(
            phase.get("mode"),
            allowed=frozenset({COMPUTE_MIGRATION_MODE_IN_PLACE, COMPUTE_MIGRATION_MODE_BLUE_GREEN}),
            fallback=COMPUTE_MIGRATION_MODE_BLUE_GREEN,
        )
        if mode == COMPUTE_MIGRATION_MODE_IN_PLACE:
            groups = _mapping(phase.get("in_place_node_groups"))
            service_health = _mapping(phase.get("in_place_service_role_health"))
            accounting_continuity = _mapping(
                _mapping(service_health.get("accounting")).get("accounting_continuity")
            )
            authority_transitions = _mapping(phase.get("in_place_authority_transitions"))
            completed = sum(
                1
                for state in groups.values()
                if isinstance(state, Mapping) and state.get("status") == "completed"
            )
            return {
                "compute_migration_mode": mode,
                "in_place_node_group_count": len(groups),
                "completed_in_place_node_group_count": completed,
                "blocked_worker_group_count": len(phase.get("blocked_worker_groups", []) or []),
                "jobs_explicitly_cancelled_by_operator": _positive_int(
                    phase.get("jobs_explicitly_cancelled_by_operator"), fallback=0
                ),
                "jobs_disruption_evidence_status": _external_upgrade_report_enum(
                    _mapping(phase.get("jobs_disruption_evidence")).get("status"),
                    allowed=frozenset({"verified-zero", "failed", "unknown", "not-applicable"}),
                    fallback="unknown",
                ),
                "accounting_continuity_status": _external_upgrade_report_enum(
                    accounting_continuity.get("status"),
                    allowed=frozenset({"verified", "baseline-recorded", "failed"}),
                    fallback="unknown",
                ),
                "controller_authority_status": _external_upgrade_report_enum(
                    _mapping(authority_transitions.get("controller")).get("status"),
                    allowed=frozenset({"verified", "dispatching"}),
                    fallback="unknown",
                ),
                "system_authority_status": _external_upgrade_report_enum(
                    _mapping(authority_transitions.get("system")).get("status"),
                    allowed=frozenset({"verified", "dispatching"}),
                    fallback="unknown",
                ),
            }
        workers = phase.get("replacement_worker_node_groups")
        worker_count = (
            len(workers)
            if isinstance(workers, Sequence) and not isinstance(workers, (str, bytes, bytearray))
            else 0
        )
        accounting = _mapping(phase.get("accounting_handoff"))
        history = _mapping(accounting.get("target_history") or accounting.get("source_history"))
        metrics: dict[str, Any] = {
            "compute_migration_mode": mode,
            "target_node_group_count": len(_mapping(phase.get("target_node_groups"))),
            "replacement_worker_group_count": worker_count,
            "accounting_handoff_status": _external_upgrade_report_enum(
                accounting.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="unknown",
            ),
        }
        for source_key, report_key in (
            ("jobs", "accounting_job_count"),
            ("steps", "accounting_step_count"),
        ):
            count = _external_upgrade_report_nonnegative_int(history.get(source_key))
            if count is not None:
                metrics[report_key] = count
        return metrics
    if phase_id == "final-control-plane-cutover":
        return {"cutover_state_recorded": bool(phase)}
    if phase_id == POPULATE_JAIL_REFRESH_PHASE_ID:
        result = _mapping(phase.get("result"))
        handoff = _mapping(phase.get("rootfs_handoff_verification"))
        post_population = _mapping(phase.get("gpu_post_population"))
        post_activation = _mapping(phase.get("gpu_post_activation"))
        return {
            "jail_status": _external_upgrade_report_enum(
                result.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not_run",
            ),
            "handoff_status": _external_upgrade_report_enum(
                handoff.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not_run",
            ),
            "gpu_post_population_status": _external_upgrade_report_enum(
                post_population.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not_run",
            ),
            "gpu_post_activation_status": _external_upgrade_report_enum(
                post_activation.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not_run",
            ),
        }
    if phase_id == "validation-and-rollback-hold":
        safety = _mapping(phase.get("shared_safety_verification"))
        return {
            "mk8s_gpu_validation_count": _positive_int(
                phase.get("mk8s_gpu_validation_count"), fallback=0
            ),
            "soperator_validation_count": _positive_int(
                phase.get("soperator_cluster_validation_count"), fallback=0
            ),
            "shared_safety_status": _external_upgrade_report_enum(
                safety.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not_run",
            ),
            "shared_safety_passed": safety.get("passed") is True,
        }
    if phase_id == "retire-old-resources":
        return {
            "retired_node_group_count": len(
                _sequence_of_mappings(phase.get("retired_node_groups"))
            ),
            "retirement_skipped": bool(str(phase.get("skipped_reason") or "").strip()),
        }
    return {}


def _phase_report_summary(
    phase_id: str,
    phase: Mapping[str, Any],
    *,
    checkpoint: Mapping[str, Any] | None = None,
) -> str:
    """Generate a summary exclusively from allowlisted report metrics."""

    metrics = _external_upgrade_report_phase_metrics(
        phase_id,
        phase,
        checkpoint=checkpoint,
    )
    if phase_id == "discovery-and-plan":
        return f"Upgrade plan recorded with {metrics['planned_phase_count']} phase(s)."
    if phase_id == "customer-approval":
        return (
            "Customer approval is recorded."
            if metrics["approval_recorded"]
            else "Customer approval is not recorded."
        )
    if phase_id == "create-aligned-sfs":
        return (
            "Aligned SFS filesystems recorded: "
            f"{metrics['filesystem_count']}/{metrics['expected_filesystem_count']}."
        )
    if phase_id == _CONTROLLER_HA_BRIDGE_PHASE_ID:
        return f"Temporary controller bridge stage={metrics['bridge_stage']}."
    if phase_id == _EXTERNAL_NODE_TEMPLATE_PHASE_ID:
        return (
            "external control-plane-only upgrade: "
            f"observed={metrics['observed_version']}; target={metrics['target_version']}; "
            f"status={metrics['control_plane_status']}; source node groups immutable."
        )
    if phase_id == _TARGET_GPU_STACK_PHASE_ID:
        return f"Target GPU stack charts applied or verified: {metrics['chart_count']}."
    if phase_id == "online-bulk-data-sync":
        return f"Data-copy jobs recorded: {metrics['copy_job_count']}."
    if phase_id == "rolling-compute-migration":
        if metrics["compute_migration_mode"] == COMPUTE_MIGRATION_MODE_IN_PLACE:
            return (
                "in-place node groups completed: "
                f"{metrics['completed_in_place_node_group_count']}/"
                f"{metrics['in_place_node_group_count']}; blocked worker groups: "
                f"{metrics['blocked_worker_group_count']}; jobs explicitly cancelled by "
                f"operator: {metrics['jobs_explicitly_cancelled_by_operator']}; provider-rollout "
                f"job-disruption evidence: {metrics['jobs_disruption_evidence_status']}; "
                f"accounting continuity: {metrics['accounting_continuity_status']}; "
                "opposite-domain authority: "
                f"controller={metrics['controller_authority_status']}, "
                f"system={metrics['system_authority_status']}."
            )
        summary = (
            f"blue/green target groups recorded: {metrics['target_node_group_count']}; "
            "worker replacement groups bound: "
            f"{metrics['replacement_worker_group_count']}."
        )
        counts = ""
        if "accounting_job_count" in metrics and "accounting_step_count" in metrics:
            counts = (
                f" (jobs={metrics['accounting_job_count']}; "
                f"steps={metrics['accounting_step_count']})"
            )
        summary += f" Accounting history handoff={metrics['accounting_handoff_status']}{counts}."
        return summary
    if phase_id == "final-control-plane-cutover":
        return "Target Soperator chart and singleton cutover checkpoint recorded."
    if phase_id == POPULATE_JAIL_REFRESH_PHASE_ID:
        return (
            f"Jail Upgrade status={metrics['jail_status']}; "
            f"handoff verification={metrics['handoff_status']}; "
            f"GPU post-population={metrics['gpu_post_population_status']}; "
            f"GPU post-activation={metrics['gpu_post_activation_status']}."
        )
    if phase_id == "validation-and-rollback-hold":
        return (
            "Validation checks recorded: "
            f"MK8s GPU={metrics['mk8s_gpu_validation_count']}, "
            f"Soperator/Slurm={metrics['soperator_validation_count']}; "
            f"shared safety={metrics['shared_safety_status']}/"
            + ("passed" if metrics["shared_safety_passed"] else "not-passed")
            + "."
        )
    if phase_id == "retire-old-resources":
        if metrics["retirement_skipped"]:
            return "Resource retirement was skipped."
        return f"Retired replaced node groups: {metrics['retired_node_group_count']}."
    return "Phase checkpoint state recorded." if phase else "No phase state recorded."


def _external_upgrade_status_summary(
    *,
    pending_phase: str,
    pending_reason: str,
    mutation_performed: bool,
) -> str:
    normalized_phase = str(pending_phase or "").strip() or "none"
    reason = str(pending_reason or "").strip()
    if normalized_phase == "none":
        return "completed." if mutation_performed else "complete; no upgrade mutation was required."
    if normalized_phase == "customer-approval":
        return "waiting for customer approval; no upgrade mutation was performed."
    if "stopped by operator" in reason.lower():
        mutation_state = (
            "after upgrade mutation" if mutation_performed else "before upgrade mutation"
        )
        return (
            f"stopped by operator {mutation_state}; rerun the same command "
            "after choosing how to handle affected Slurm jobs."
        )
    if mutation_performed:
        return "pending after upgrade mutation; rerun the same command to resume."
    return "pending before upgrade mutation; rerun the same command after resolving the gate."


def _external_upgrade_resume_command(
    config_path: Path,
    target_ref: str,
    *,
    pending_phase: str = "",
    pending_reason: str = "",
    checkpoint: Mapping[str, Any] | None = None,
) -> str:
    del config_path, target_ref
    if pending_phase == "validation-and-rollback-hold" and (
        "protected-state-comparison" in pending_reason
    ):
        safety = _mapping((checkpoint or {}).get("upgrade_safety"))
        verification = _mapping(safety.get("post_upgrade_verification"))
        comparison = _mapping(verification.get("comparison"))
        blocked_count = int(comparison.get("blocked_count") or 0)
        approval_count = int(comparison.get("approval_required_count") or 0)
        approval = _mapping(safety.get("remediation_approval"))
        if blocked_count:
            return (
                "review the blocked protected-state deltas in the JSON report and "
                "repair or recover the protected state before rerunning; "
                "--approve-remediation cannot override blocked deltas"
            )
        if approval_count and not bool(approval.get("approved")):
            return (
                "review the protected-state deltas in the JSON report; if every "
                "approval-required delta is expected, rerun the original command adding "
                "--approve-remediation"
            )
        if approval_count:
            return (
                "remediation approval is already recorded; resolve the remaining failed "
                "verification checks, then rerun the exact original command with every "
                "option unchanged"
            )
        return (
            "review the protected-state deltas in the JSON report and resolve every "
            "blocked delta; add --approve-remediation only when the report shows zero "
            "blocked deltas and one or more expected approval-required deltas"
        )
    return "rerun the exact original command with every option unchanged"


def _slurm_decision_pause_records(
    decision: Mapping[str, Any],
) -> tuple[SlurmPartitionPauseRecord, ...]:
    return _rolling_compute_checkpoint_pause_records(
        {"slurm_paused_partitions": decision.get("partitions")}
    )


def _update_slurm_recovery_state(
    slurm: dict[str, Any],
    decision: Mapping[str, Any],
) -> None:
    action = str(decision.get("action", "") or "")
    if action not in {"scheduling-pause-applied", "scheduling-pause-restored"}:
        return
    existing_records = _rolling_compute_checkpoint_pause_records(
        {"slurm_paused_partitions": slurm.get("paused_partitions")}
    )
    records_by_partition = {record.partition: record for record in existing_records}
    decision_records = _slurm_decision_pause_records(decision)
    if action == "scheduling-pause-applied":
        for record in decision_records:
            records_by_partition.setdefault(record.partition, record)
    elif decision_records:
        for record in decision_records:
            records_by_partition.pop(record.partition, None)
    else:
        records_by_partition.clear()
    remaining = tuple(records_by_partition.values())
    slurm["paused_partitions"] = [record.as_payload() for record in remaining]
    slurm["partition_restore_manual_command"] = (
        _external_upgrade_slurm_partition_recovery_inspection_command(remaining) or None
    )


def _checkpoint_owned_slurm_partition_pause_records(
    checkpoint: Mapping[str, Any],
) -> tuple[SlurmPartitionPauseRecord, ...]:
    phase_state = _mapping(checkpoint.get("phase_state"))
    bridge = _mapping(checkpoint.get("controller_bridge"))
    record_groups = [
        _rolling_compute_checkpoint_pause_records(
            {"slurm_paused_partitions": _mapping(checkpoint.get("slurm")).get("paused_partitions")}
        ),
        _rolling_compute_checkpoint_pause_records(
            {"slurm_paused_partitions": bridge.get("partition_pause")}
        ),
    ]
    for phase_id in (
        _EXTERNAL_NODE_TEMPLATE_PHASE_ID,
        "rolling-compute-migration",
        POPULATE_JAIL_REFRESH_PHASE_ID,
    ):
        phase = _mapping(phase_state.get(phase_id))
        record_groups.append(_rolling_compute_checkpoint_pause_records(phase))
        if phase_id == "rolling-compute-migration":
            record_groups.append(
                _rolling_compute_checkpoint_pause_records(
                    {"slurm_paused_partitions": phase.get("values_reapply_slurm_paused_partitions")}
                )
            )
    return _merge_slurm_partition_pause_records(*record_groups)


def _checkpoint_target_retired_slurm_partition_names(
    checkpoint: Mapping[str, Any],
    *,
    records: Sequence[SlurmPartitionPauseRecord],
) -> frozenset[str]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    gate = _mapping(phase.get("in_place_gpu_smoke_scheduling_gate"))
    raw_retired = gate.get("retired_partitions")
    if raw_retired is None:
        return frozenset()
    if (
        gate.get("status") != "passed"
        or not isinstance(raw_retired, Sequence)
        or isinstance(
            raw_retired,
            (str, bytes, bytearray),
        )
    ):
        raise RuntimeError(
            "recovery-required: target-retired Slurm partitions lack a passed GPU smoke "
            "scheduling-gate proof."
        )
    raw_target = gate.get("target_partitions")
    if not isinstance(raw_target, Sequence) or isinstance(
        raw_target,
        (str, bytes, bytearray),
    ):
        raise RuntimeError(
            "recovery-required: target-retired Slurm partitions lack their canonical "
            "target partition inventory."
        )
    target_names = sorted({str(item or "").strip() for item in raw_target})
    if any(not item for item in target_names) or gate.get(
        "target_partitions_sha256"
    ) != _fingerprint(target_names):
        raise RuntimeError(
            "recovery-required: canonical target Slurm partition inventory changed after "
            "the worker scheduling gate."
        )
    retired = frozenset(str(item or "").strip() for item in raw_retired)
    partition_evidence = _sequence_of_mappings(gate.get("partitions"))
    # A source partition can still be present and exactly DOWN when the GPU
    # scheduling gate runs because the controller bridge deliberately keeps
    # legacy partition definitions readable until the final Helm replay.  Its
    # absence from the canonical target partitionConfiguration is already the
    # durable retirement decision; waiting until the partition disappears
    # makes the classification depend on whether the gate ran before or after
    # that replay.
    planned_retired = frozenset(
        str(item.get("partition") or "").strip()
        for item in partition_evidence
        if item.get("target_configured") is False
    )
    retired = retired | planned_retired
    record_names = {record.partition for record in records}
    if "" in retired or not retired <= record_names or retired & set(target_names):
        raise RuntimeError(
            "recovery-required: target-retired Slurm partition evidence conflicts with "
            "the exact pause journal or canonical target configuration."
        )
    evidence = {str(item.get("partition") or "").strip(): item for item in partition_evidence}
    if any(
        not (
            str(_mapping(evidence.get(name)).get("status") or "").strip() == "retired-from-target"
            or (
                str(_mapping(evidence.get(name)).get("status") or "").strip() == "down"
                and _mapping(evidence.get(name)).get("target_configured") is False
            )
        )
        for name in retired
    ):
        raise RuntimeError(
            "recovery-required: target-retired Slurm partition evidence is incomplete."
        )
    return retired


def _checkpoint_slurm_partition_restore_plan(
    checkpoint: Mapping[str, Any],
) -> tuple[
    tuple[SlurmPartitionPauseRecord, ...],
    tuple[SlurmPartitionPauseRecord, ...],
    list[dict[str, Any]],
    list[dict[str, Any]],
    str,
]:
    all_records = _checkpoint_owned_slurm_partition_pause_records(checkpoint)
    retired_partition_names = _checkpoint_target_retired_slurm_partition_names(
        checkpoint,
        records=all_records,
    )
    records = tuple(
        record for record in all_records if record.partition not in retired_partition_names
    )
    records_payload = [record.as_payload() for record in records]
    retired_records_payload = [
        record.as_payload() for record in all_records if record.partition in retired_partition_names
    ]
    records_sha256 = _fingerprint(
        {"restored": records_payload, "target_retired": retired_records_payload}
    )
    return (
        all_records,
        records,
        records_payload,
        retired_records_payload,
        records_sha256,
    )


def _reconcile_in_progress_partition_restore_target_retirement(
    *,
    restore: dict[str, Any],
    bridge_restore: dict[str, Any],
    all_records: Sequence[SlurmPartitionPauseRecord],
    records: Sequence[SlurmPartitionPauseRecord],
    records_payload: Sequence[Mapping[str, Any]],
    retired_records_payload: Sequence[Mapping[str, Any]],
    records_sha256: str,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
) -> bool:
    """Repair the pre-fix restore plan after the final target Helm replay.

    Older checkpoints classified a legacy partition as retired only when it
    was already absent at the GPU gate.  If final Helm reconciliation removed
    those partitions later, restore could set an earlier target partition UP
    and then stop at the first absent legacy partition.  Rebind only that exact
    in-progress shape after proving all retired partitions are absent and every
    surviving partition still matches either cxcli's DOWN record or its saved
    pre-pause record.
    """

    old_hashes = {
        str(value or "").strip()
        for value in (restore.get("records_sha256"), bridge_restore.get("records_sha256"))
        if str(value or "").strip()
    }
    if (
        len(old_hashes) != 1
        or records_sha256 in old_hashes
        or restore.get("status") != "restoring"
        or bridge_restore.get("status") != "restoring"
        or str(restore.get("restored_at") or "").strip()
        or str(bridge_restore.get("restored_at") or "").strip()
        or not retired_records_payload
    ):
        return False
    old_payload = restore.get("partitions")
    if not isinstance(old_payload, list):
        return False
    expected_old_payload = [record.as_payload() for record in all_records]
    if old_payload != expected_old_payload:
        return False
    old_names = [str(_mapping(item).get("partition") or "").strip() for item in old_payload]
    surviving_names = {
        str(_mapping(item).get("partition") or "").strip() for item in records_payload
    }
    retired_names = {
        str(_mapping(item).get("partition") or "").strip() for item in retired_records_payload
    }
    if (
        not all(old_names)
        or len(set(old_names)) != len(old_names)
        or set(old_names) != surviving_names | retired_names
        or surviving_names & retired_names
    ):
        return False
    live = {
        item.name: item
        for item in _external_upgrade_partition_state_snapshot(
            command_runner=command_runner,
            kube_context=kube_context,
        )
    }
    if retired_names & set(live) or set(live) != surviving_names:
        return False
    for record in records:
        observation = live.get(record.partition)
        if observation is None or not (
            _slurm_partition_observation_matches(
                observation,
                record=record.applied_record,
                fingerprint=record.applied_record_fingerprint,
            )
            or _slurm_partition_observation_matches(
                observation,
                record=record.previous_record,
                fingerprint=record.previous_record_fingerprint,
            )
        ):
            return False
    old_hash = next(iter(old_hashes))
    restore.update(
        {
            "records_sha256": records_sha256,
            "partition_count": len(records_payload),
            "target_retired_partition_count": len(retired_records_payload),
            "target_retired_partitions": sorted(retired_names),
            "partitions": [copy.deepcopy(to_plain_data(item)) for item in records_payload],
            "superseded_restore_plan_sha256": old_hash,
            "target_retirement_reconciled_at": _utc_now(),
        }
    )
    bridge_restore.update(
        {
            "records_sha256": records_sha256,
            "partition_count": len(records_payload),
            "target_retired_partition_count": len(retired_records_payload),
            "target_retired_partitions": sorted(retired_names),
            "superseded_restore_plan_sha256": old_hash,
            "target_retirement_reconciled_at": restore["target_retirement_reconciled_at"],
        }
    )
    if checkpoint_writer is not None:
        checkpoint_writer()
    return True


def _restore_slurm_partitions_before_controller_bridge_cleanup(
    *,
    checkpoint: dict[str, Any],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    checkpoint_writer: Callable[[], None] | None,
    slurm_decision_recorder: Callable[[Mapping[str, Any]], None] | None,
    final_health_revalidator: Callable[[Mapping[str, Any]], None],
) -> tuple[bool, list[str]]:
    bridge = checkpoint.get("controller_bridge")
    if not isinstance(bridge, dict):
        raise SoperatorMigrationPhasePending(
            "Slurm partition restoration requires the v6 controller bridge journal."
        )
    validate_bridge_journal(bridge)
    stage = BridgeStage(str(bridge.get("stage", "") or ""))
    if stage is BridgeStage.CLEANED:
        _controller_bridge_require_partition_restore_binding(checkpoint)
        return False, [
            "Final Slurm scheduling restore reused its exact checkpoint after bridge cleanup."
        ]
    if stage is BridgeStage.PARTITIONS_RESTORED:
        _controller_bridge_require_partition_restore_binding(checkpoint)
        return False, [
            "Final Slurm scheduling restore reused its exact checkpoint while the stopped "
            "bridge remains retained for destructive cleanup."
        ]
    if stage is not BridgeStage.HANDOFF_VALIDATED:
        raise SoperatorMigrationPhasePending(
            "Slurm partitions remain paused until the target singleton handoff is validated; "
            f"current controller bridge stage={stage.value}."
        )
    cleanup = bridge.get("cleanup")
    if not isinstance(cleanup, dict):
        raise RuntimeError("Controller bridge cleanup journal must be mutable.")
    action_journal = _checkpoint_slurm_action_journal_for_job_control(checkpoint)
    _ensure_controller_bridge_target_action_generation(
        checkpoint=checkpoint,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    _controller_bridge_cleanup_required_gates(checkpoint)
    cleanup = _mapping(bridge.get("cleanup"))
    login_handoff = _mapping(bridge.get("login_session_handoff"))
    final_health = _mapping(checkpoint.get("final_health"))
    if login_handoff.get("state") != "complete" or final_health.get("status") != "passed":
        raise SoperatorMigrationPhasePending(
            "Slurm partitions remain paused until the final singleton, voluntary login "
            "handoff, and final health proofs all pass."
        )
    _finalize_controller_bridge_target_actions(
        checkpoint=checkpoint,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    _controller_bridge_cleanup_require_target_action_generation(action_journal)
    proof_binding = _controller_bridge_cleanup_action_binding(checkpoint)
    final_health = _mapping(checkpoint.get("final_health"))
    if final_health.get("status") != "passed" or any(
        final_health.get(field) != value for field, value in proof_binding.items()
    ):
        final_health_revalidator(proof_binding)
    _controller_bridge_cleanup_required_gates(checkpoint)

    preservation_lines = _verify_controller_bridge_preservation_jobs(
        checkpoint=checkpoint,
        journal=bridge,
        proof_stage="pre-cleanup",
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
        reuse_existing=False,
        proof_binding=proof_binding,
    )
    verification = next(
        (
            item
            for item in _sequence_of_mappings(
                _mapping(bridge.get("preservation_jobs")).get("verifications")
            )
            if item.get("stage") == "pre-cleanup"
        ),
        {},
    )
    cleanup["pre_cleanup_preservation_proof"] = {
        "status": "verified",
        "verified_at": str(verification.get("verified_at", "") or ""),
        **proof_binding,
        "verification_sha256": _fingerprint(verification),
    }
    if checkpoint_writer is not None:
        checkpoint_writer()
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )
    _revalidate_target_singleton_before_controller_bridge_cleanup(
        journal=bridge,
        kube_context=kube_context,
        command_runner=command_runner,
        checkpoint_writer=checkpoint_writer,
    )
    target_state = _prove_controller_bridge_cleanup_target_singleton(
        journal=bridge,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    _controller_bridge_require_stopped_retained_substrate(
        journal=bridge,
        target_state=target_state,
        kube_context=kube_context,
        nebius_api=nebius_api,
        command_runner=command_runner,
    )
    _controller_bridge_cleanup_require_preservation_binding(
        checkpoint,
        cleanup=cleanup,
    )

    (
        all_records,
        records,
        records_payload,
        retired_records_payload,
        records_sha256,
    ) = _checkpoint_slurm_partition_restore_plan(checkpoint)
    retired_partition_names = frozenset(
        str(item.get("partition") or "") for item in retired_records_payload
    )
    slurm = checkpoint.setdefault("slurm", {})
    if not isinstance(slurm, dict):
        raise RuntimeError("External Soperator v6 checkpoint slurm state must be a mapping.")
    restore = slurm.setdefault("final_partition_restore", {})
    if not isinstance(restore, dict):
        raise RuntimeError("External Soperator v6 final_partition_restore state must be a mapping.")
    checkpointed_sha256 = str(restore.get("records_sha256") or "").strip()
    previous_status = str(restore.get("status") or "").strip()
    bridge_restore = bridge.get("partition_restore")
    if not isinstance(bridge_restore, dict):
        raise RuntimeError("Controller bridge partition_restore journal must be mutable.")
    bridge_records_sha256 = str(bridge_restore.get("records_sha256") or "").strip()
    if (checkpointed_sha256 and checkpointed_sha256 != records_sha256) or (
        bridge_records_sha256 and bridge_records_sha256 != records_sha256
    ):
        repaired = _reconcile_in_progress_partition_restore_target_retirement(
            restore=restore,
            bridge_restore=bridge_restore,
            all_records=all_records,
            records=records,
            records_payload=records_payload,
            retired_records_payload=retired_records_payload,
            records_sha256=records_sha256,
            command_runner=command_runner,
            kube_context=kube_context,
            checkpoint_writer=checkpoint_writer,
        )
        if not repaired:
            raise RuntimeError(
                "recovery-required: final Slurm partition restore ownership records changed "
                "after restore intent was checkpointed."
            )
    existing_intents = {
        str(item or "").strip()
        for item in (restore.get("intent_at"), bridge_restore.get("intent_at"))
        if str(item or "").strip()
    }
    if len(existing_intents) > 1:
        raise RuntimeError(
            "recovery-required: partition restore intent timestamps disagree across journals."
        )
    intent_at = next(iter(existing_intents), _utc_now())
    restore_binding = {
        "status": "restoring",
        "records_sha256": records_sha256,
        "partition_count": len(records_payload),
        "target_retired_partition_count": len(retired_records_payload),
        "target_retired_partitions": sorted(retired_partition_names),
        **proof_binding,
        "intent_at": intent_at,
    }
    restore.update(
        {
            **restore_binding,
            "partitions": records_payload,
            "release_boundary": "before-controller-bridge-cleanup",
        }
    )
    bridge_restore.update(restore_binding)
    if checkpoint_writer is not None:
        checkpoint_writer()
    _restore_external_upgrade_slurm_partitions(
        command_runner=command_runner,
        kube_context=kube_context,
        records=records,
        action_journal=action_journal,
        action_checkpoint_writer=checkpoint_writer,
        authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
    )
    restored_at = str(restore.get("restored_at") or bridge_restore.get("restored_at") or _utc_now())
    restore.update({"status": "restored", "restored_at": restored_at})
    bridge_restore.update({"status": "restored", "restored_at": restored_at})
    bridge["partition_pause_released_at"] = restored_at
    phase_state = _mapping(checkpoint.get("phase_state"))
    for phase_id in (
        _EXTERNAL_NODE_TEMPLATE_PHASE_ID,
        "rolling-compute-migration",
        POPULATE_JAIL_REFRESH_PHASE_ID,
    ):
        phase = phase_state.get(phase_id)
        if isinstance(phase, dict):
            phase["slurm_partition_restore_status"] = "restored"
            phase["slurm_partition_restored_at"] = restored_at
            phase.pop("slurm_partition_restore_deferred_reason", None)
    if slurm_decision_recorder is not None:
        slurm_decision_recorder(
            {
                "at": restored_at,
                "action": "scheduling-pause-restored",
                "partitions": records_payload,
                "target_retired_partitions": retired_records_payload,
                "reason": "final continuity gates passed before bridge cleanup",
            }
        )
    if checkpoint_writer is not None:
        checkpoint_writer()
    _controller_bridge_require_partition_restore_binding(checkpoint)
    advance_bridge_stage(bridge, BridgeStage.PARTITIONS_RESTORED)
    if checkpoint_writer is not None:
        checkpoint_writer()
    return (
        bool(all_records) and previous_status != "restored",
        preservation_lines
        + [
            "Final Slurm scheduling restore: surviving target partition records restored "
            "with compare-and-set, while canonical target-retired source partitions were "
            "not recreated, after all continuity gates and before destructive bridge "
            f"cleanup ({len(records)} restored, {len(retired_records_payload)} retired)."
        ],
    )


_EXTERNAL_EXECUTE_DEDUPE_PREFIXES = (
    "Quota preflight ",
    "Worker rollout live preflight:",
    "Slurm worker rollout preflight:",
    "External MK8s control plane already ",
    "External control plane already handled:",
    "External control-plane strategy:",
    "Applied target GPU stack chart:",
    "Applied target GPU stack post-render patch:",
)


def _external_execute_line_dedupe_key(line: str) -> str:
    text = str(line or "").strip()
    unprefixed = re.sub(r"^[a-z0-9-]+:\s+", "", text)
    if any(unprefixed.startswith(prefix) for prefix in _EXTERNAL_EXECUTE_DEDUPE_PREFIXES):
        return unprefixed
    return text


def _dedupe_external_execute_lines(lines: Sequence[str]) -> list[str]:
    seen: set[str] = set()
    deduped: list[str] = []
    for line in lines:
        key = _external_execute_line_dedupe_key(line)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(str(line))
    return deduped


def _external_upgrade_report_identifier(value: object) -> str:
    """Return a stable report-local reference without exposing a customer identifier."""

    text = str(value or "").strip()
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16] if text else ""


def _external_upgrade_report_safe_slurm_payload(slurm: Mapping[str, Any]) -> dict[str, Any]:
    """Project the private Slurm operation journal into a shareable status summary.

    The checkpoint remains the authoritative 0600 recovery record. Reports intentionally
    omit raw ``scontrol`` records, usernames, JobIDs, partition/node names, commands, socket
    fingerprints, and action result text because those values can contain customer data.
    Unknown future journal fields are dropped by default.
    """

    journal = _mapping(slurm.get("action_journal"))
    controller = _mapping(journal.get("controller"))
    login = _mapping(journal.get("login"))
    raw_actions = _sequence_of_mappings(journal.get("actions"))
    safe_actions: list[dict[str, Any]] = []
    action_states = frozenset(
        {
            SLURM_ACTION_QUEUED,
            SLURM_ACTION_DISPATCHING,
            SLURM_ACTION_APPLIED,
            SLURM_ACTION_REJECTED,
            SLURM_ACTION_INDETERMINATE,
        }
    )
    action_kinds = frozenset(
        {"cancel", "requeue", "hold", "requeue-hold", "release", "wait", "refresh"}
    )
    for action in raw_actions:
        kind = _external_upgrade_report_enum(
            action.get("kind"),
            allowed=action_kinds,
            fallback="unknown",
        )
        state = _external_upgrade_report_enum(
            action.get("state"),
            allowed=action_states,
            fallback="unknown",
        )
        binding = _mapping(action.get("binding"))
        lineage = str(binding.get("lineage_fingerprint") or "").strip()
        if not lineage:
            lineage = "\x1f".join(
                str(binding.get(field) or "")
                for field in ("job_id", "user_id", "submit_time", "identity_fingerprint")
            )
        accepted_at = _external_upgrade_report_timestamp(action.get("accepted_at"))
        restart_baseline = _external_upgrade_report_nonnegative_int(binding.get("restart_baseline"))
        transitions: list[dict[str, str]] = []
        for transition in _sequence_of_mappings(action.get("transitions")):
            transition_state = _external_upgrade_report_enum(
                transition.get("state"),
                allowed=action_states,
                fallback="unknown",
            )
            transition_at = _external_upgrade_report_timestamp(transition.get("at"))
            transitions.append(
                {
                    "state": transition_state,
                    **({"at": transition_at} if transition_at else {}),
                }
            )
        safe_action: dict[str, Any] = {
            "action_ref": _external_upgrade_report_identifier(action.get("action_id")),
            "job_ref": _external_upgrade_report_identifier(lineage),
            "kind": kind,
            "state": state,
            "result_recorded": bool(str(action.get("result") or "").strip()),
            "transitions": transitions,
        }
        if accepted_at:
            safe_action["accepted_at"] = accepted_at
        if restart_baseline is not None:
            safe_action["restart_baseline"] = restart_baseline
        safe_actions.append(safe_action)

    safe_journal = {
        "present": bool(journal),
        "broker_mode": _external_upgrade_report_enum(
            journal.get("broker_mode"),
            allowed=frozenset({"dispatch-enabled", "accept-only", SLURM_ACTION_ADMISSION_CLOSED}),
            fallback="unknown",
        ),
        "controller": {
            "authority": _external_upgrade_report_enum(
                controller.get("authority"),
                allowed=frozenset(
                    {
                        "unknown",
                        "source-singleton",
                        "bridge-source",
                        "bridge-target",
                        "target-singleton",
                        "none",
                    }
                ),
                fallback="unknown",
            ),
            "connectivity": _external_upgrade_report_enum(
                controller.get("connectivity"),
                allowed=frozenset(
                    {"unknown", "connected", "connected-no-authority-epoch", "unavailable"}
                ),
                fallback="unknown",
            ),
        },
        "login": {
            "state": _external_upgrade_report_enum(
                login.get("state"),
                allowed=frozenset(
                    {
                        "unknown",
                        "protected",
                        "target-ready",
                        "pending-voluntary-exit",
                        "complete",
                        "indeterminate",
                    }
                ),
                fallback="unknown",
            ),
            "protected_pod_count": (
                _external_upgrade_report_nonnegative_int(login.get("protected_pod_count")) or 0
            ),
            "active_session_count": (
                _external_upgrade_report_nonnegative_int(login.get("active_session_count")) or 0
            ),
            "target_ready": login.get("target_ready") is True,
        },
        "actions": safe_actions,
        "action_count": len(raw_actions),
        "job_snapshot_count": len(_mapping(journal.get("job_snapshots"))),
        "exit_confirmation_request_count": len(
            _sequence_of_mappings(login.get("exit_confirmation_requests"))
        ),
        "exit_acknowledgement_count": len(
            _sequence_of_mappings(login.get("exit_acknowledgements"))
        ),
    }
    broker_updated_at = _external_upgrade_report_timestamp(journal.get("broker_mode_updated_at"))
    if broker_updated_at:
        safe_journal["broker_mode_updated_at"] = broker_updated_at
    controller_observed_at = _external_upgrade_report_timestamp(controller.get("observed_at"))
    if controller_observed_at:
        safe_journal["controller"]["observed_at"] = controller_observed_at
    snapshot_age = _external_upgrade_report_nonnegative_int(controller.get("snapshot_age_seconds"))
    if snapshot_age is not None:
        safe_journal["controller"]["snapshot_age_seconds"] = snapshot_age
    login_observed_at = _external_upgrade_report_timestamp(login.get("observed_at"))
    if login_observed_at:
        safe_journal["login"]["observed_at"] = login_observed_at

    held_operations = _mapping(slurm.get("held_job_operations"))
    held_states: dict[str, int] = {}
    allowed_held_states = frozenset(
        {"intent-recorded", "held-observed", "release-intent", "released", "release-not-required"}
    )
    for operation in held_operations.values():
        state = _external_upgrade_report_enum(
            _mapping(operation).get("state"),
            allowed=allowed_held_states,
            fallback="unknown",
        )
        held_states[state] = held_states.get(state, 0) + 1
    final_restore = _mapping(slurm.get("final_partition_restore"))
    result: dict[str, Any] = {
        "job_policy": _external_upgrade_report_enum(
            slurm.get("job_policy"),
            allowed=_EXTERNAL_UPGRADE_JOB_POLICIES,
            fallback="unknown",
        ),
        "scheduling_pause": slurm.get("scheduling_pause") is True,
        "action_journal": safe_journal,
        "paused_partition_count": len(
            slurm.get("paused_partitions")
            if isinstance(slurm.get("paused_partitions"), list)
            else []
        ),
        "held_job_operation_count": len(held_operations),
        "held_job_operation_states": held_states,
        "final_partition_restore": {
            "status": _external_upgrade_report_enum(
                final_restore.get("status"),
                allowed=frozenset({"restoring", "restored"}),
                fallback="not_run",
            ),
            "partition_count": len(
                final_restore.get("partitions")
                if isinstance(final_restore.get("partitions"), list)
                else []
            ),
        },
    }
    for source_key, report_key in (
        ("wait_timeout_seconds", "wait_timeout_seconds"),
        ("refresh_interval_seconds", "refresh_interval_seconds"),
    ):
        count = _external_upgrade_report_nonnegative_int(slurm.get(source_key))
        if count is not None:
            result[report_key] = count
    for key in ("intent_at", "restored_at"):
        timestamp = _external_upgrade_report_timestamp(final_restore.get(key))
        if timestamp:
            result["final_partition_restore"][key] = timestamp
    if final_restore.get("release_boundary") == "before-controller-bridge-cleanup":
        result["final_partition_restore"]["release_boundary"] = "before-controller-bridge-cleanup"
    return result


def _external_upgrade_report_fast_verification(
    phase_id: str,
    phase: Mapping[str, Any],
) -> dict[str, Any]:
    raw = stage_fast_verification_report(phase_id, phase)
    status = _external_upgrade_report_enum(
        raw.get("status"),
        allowed=_EXTERNAL_UPGRADE_REPORT_VERIFICATION_STATUSES,
        fallback="not_run",
    )
    status_counts = {key: 0 for key in sorted(_EXTERNAL_UPGRADE_REPORT_VERIFICATION_STATUSES)}
    checks = _sequence_of_mappings(raw.get("checks"))
    for check in checks:
        check_status = _external_upgrade_report_enum(
            check.get("status"),
            allowed=_EXTERNAL_UPGRADE_REPORT_VERIFICATION_STATUSES,
            fallback="not_run",
        )
        status_counts[check_status] += 1
    verified_at = _external_upgrade_report_timestamp(raw.get("verified_at"))
    return {
        "phase_id": phase_id,
        "status": status,
        "passed": True if status == "passed" else False if status == "failed" else None,
        "summary": f"Fast verification {status_label(status).lower()} ({len(checks)} check(s)).",
        "check_count": len(checks),
        "check_status_counts": status_counts,
        **({"verified_at": verified_at} if verified_at else {}),
    }


def _external_upgrade_report_campaign_summary(
    campaign: Mapping[str, Any],
    checkpoint: Mapping[str, Any],
) -> dict[str, Any]:
    segments = _sequence_of_mappings(campaign.get("segments"))
    segment_ids = [str(segment.get("id") or "").strip() for segment in segments]
    completed_ids = {
        str(item or "").strip()
        for item in checkpoint.get("completed_segment_ids", []) or []
        if str(item or "").strip() in segment_ids
    }
    current_id = str(checkpoint.get("current_segment_id") or "").strip()
    current_position = (
        segment_ids.index(current_id) + 1 if current_id and current_id in segment_ids else None
    )
    chart = _mapping(campaign.get("soperator_chart"))
    jail = _mapping(campaign.get("jail_rootfs"))
    return {
        "present": bool(campaign),
        "segment_count": len(segments),
        "completed_segment_count": len(completed_ids),
        "remaining_segment_count": max(len(segments) - len(completed_ids), 0),
        **({"current_segment_position": current_position} if current_position is not None else {}),
        "soperator_chart": {
            "current_version": _external_upgrade_report_version(chart.get("current_version")),
            "target_version": _external_upgrade_report_version(chart.get("target_version")),
        },
        "jail_rootfs": {
            "current_version": _external_upgrade_report_version(jail.get("current_version")),
            "target_version": _external_upgrade_report_version(jail.get("target_version")),
            "refresh_required": jail.get("refresh_required") is True,
        },
    }


def _external_upgrade_report_backup_summary(backup: Mapping[str, Any]) -> dict[str, Any]:
    size_bytes = _external_upgrade_report_nonnegative_int(backup.get("size_bytes"))
    categories = backup.get("included_categories")
    category_count = (
        len(categories)
        if isinstance(categories, Sequence) and not isinstance(categories, (str, bytes, bytearray))
        else 0
    )
    return {
        "present": bool(backup),
        "size_bytes": size_bytes or 0,
        "included_category_count": category_count,
    }


def _external_upgrade_report_validation_summary(
    validation: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        "mk8s_gpu_validation_count": _positive_int(
            validation.get("mk8s_gpu_validation_count"), fallback=0
        ),
        "soperator_validation_count": _positive_int(
            validation.get("soperator_cluster_validation_count"), fallback=0
        ),
        "mk8s_gpu_report_count": len(
            validation.get("mk8s_gpu_validation_reports")
            if isinstance(validation.get("mk8s_gpu_validation_reports"), list)
            else []
        ),
        "soperator_report_count": len(
            validation.get("soperator_cluster_validation_reports")
            if isinstance(validation.get("soperator_cluster_validation_reports"), list)
            else []
        ),
        "shared_safety_status": _external_upgrade_report_enum(
            _mapping(validation.get("shared_safety_verification")).get("status"),
            allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
            fallback="not_run",
        ),
    }


def _external_upgrade_report_safety_summary(safety: Mapping[str, Any]) -> dict[str, Any]:
    protected = _mapping(safety.get("protected_customer_state"))
    verification = _mapping(safety.get("post_upgrade_verification"))
    smoke = _mapping(safety.get("fast_smoke"))
    eligibility = _mapping(safety.get("zero_downtime_eligibility"))
    approvals = safety.get("remediation_approvals")
    followups = safety.get("heavy_validation_followups")
    deltas = protected.get("deltas")
    return {
        "present": bool(safety),
        "protected_state": {
            "status": _external_upgrade_report_enum(
                protected.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not-run",
            ),
            "before_captured": bool(str(protected.get("before_hash") or "").strip()),
            "after_captured": bool(str(protected.get("after_hash") or "").strip()),
            "delta_count": len(deltas) if isinstance(deltas, list) else 0,
        },
        "post_upgrade_verification": {
            "status": _external_upgrade_report_enum(
                verification.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not-run",
            ),
            "passed": verification.get("passed") is True,
            "check_count": len(_sequence_of_mappings(verification.get("checks"))),
        },
        "fast_smoke": {
            "status": _external_upgrade_report_enum(
                smoke.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not-run",
            ),
            "check_count": len(_sequence_of_mappings(smoke.get("checks"))),
        },
        "remediation_approval_count": len(approvals) if isinstance(approvals, list) else 0,
        "heavy_validation_followup_count": len(followups) if isinstance(followups, list) else 0,
        "zero_downtime_eligibility": {
            "status": _external_upgrade_report_enum(
                eligibility.get("status"),
                allowed=_EXTERNAL_UPGRADE_REPORT_OPERATION_STATUSES,
                fallback="not-evaluated",
            ),
            "eligible": eligibility.get("eligible") is True,
            "reason_count": len(eligibility.get("reasons"))
            if isinstance(eligibility.get("reasons"), list)
            else 0,
        },
    }


def _external_upgrade_report_event_summary(events: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    timestamps = [
        timestamp
        for event in events
        if (timestamp := _external_upgrade_report_timestamp(event.get("at")))
    ]
    return {
        "event_count": len(events),
        **({"latest_event_at": max(timestamps)} if timestamps else {}),
    }


def _external_upgrade_report_overall_status(
    *,
    pending_phase: str,
    mutation_performed: bool,
) -> str:
    if pending_phase == "none":
        return "completed" if mutation_performed else "no-mutation-required"
    if pending_phase == "customer-approval":
        return "approval-required"
    return "pending-after-mutation" if mutation_performed else "pending-before-mutation"


def _external_upgrade_report_markdown(payload: Mapping[str, Any]) -> str:
    campaign = _mapping(payload.get("campaign"))
    validation = _mapping(payload.get("validation"))
    safety = _mapping(payload.get("upgrade_safety"))
    protected = _mapping(safety.get("protected_state"))
    verification = _mapping(safety.get("post_upgrade_verification"))
    event_summary = _mapping(payload.get("event_summary"))
    timing = _mapping(payload.get("timing"))
    timing_label = (
        "Total active upgrade time" if timing.get("completed_at") else "Active upgrade time so far"
    )
    lines = [
        "# External Soperator Upgrade Report",
        "",
        f"- Report scope: `{payload.get('report_scope', 'latest')}`",
        f"- Source version: `{payload.get('source_version', 'unknown')}`",
        f"- Target version: `{payload.get('target_version', 'unknown')}`",
        f"- Generated at: `{payload.get('generated_at', '')}`",
        f"- Upgrade status: `{payload.get('status', 'unknown')}`",
        f"- Pending phase: `{payload.get('pending_phase', 'unknown')}`",
        "- Upgrade performed: `" + ("yes" if payload.get("upgrade_performed") else "no") + "`",
        f"- {timing_label}: `{timing.get('elapsed_time', '00:00:00')}` ",
        "  (`"
        + str(timing.get("elapsed_seconds", 0.0))
        + "` seconds across `"
        + str(timing.get("attempt_count", 0))
        + "` execute invocation(s); offline gaps excluded)",
        "",
        "## Upgrade Campaign",
        "",
        f"- Segments: `{campaign.get('segment_count', 0)}`",
        f"- Completed segments: `{campaign.get('completed_segment_count', 0)}`",
        f"- Remaining segments: `{campaign.get('remaining_segment_count', 0)}`",
        "",
        "## Upgrade Steps",
        "",
    ]
    for phase in _sequence_of_mappings(payload.get("phases")):
        lines.extend(
            [
                f"### {phase.get('id', 'unknown')}",
                "",
                f"- Status: `{phase.get('status', 'UNKNOWN')}`",
                f"- Top-level stage: `{phase.get('top_level_stage', 'unknown')}`",
                f"- Summary: {phase.get('summary', 'No safe summary recorded.')}",
                "",
            ]
        )
    lines.extend(["## Stage Fast Verification", ""])
    stage_verification = _sequence_of_mappings(payload.get("stage_verification"))
    if stage_verification:
        for item in stage_verification:
            lines.append(
                f"- `{item.get('phase_id', 'unknown')}`: "
                f"`{status_label(str(item.get('status') or 'not_run'))}` - "
                f"{item.get('summary', 'No safe summary recorded.')}"
            )
    else:
        lines.append("- No executable upgrade stages were selected.")
    lines.extend(
        [
            "",
            "## Validations",
            "",
            "- MK8s GPU validations: `" + str(validation.get("mk8s_gpu_validation_count", 0)) + "`",
            "- Soperator/Slurm validations: `"
            + str(validation.get("soperator_validation_count", 0))
            + "`",
            "- Shared safety status: `"
            + str(validation.get("shared_safety_status", "not_run"))
            + "`",
            "",
            "## Shared Upgrade Safety",
            "",
            f"- Protected-state result: `{protected.get('status', 'not-run')}`",
            f"- Protected-state deltas: `{protected.get('delta_count', 0)}`",
            f"- Fast verification: `{verification.get('status', 'not-run')}`",
            "",
            "## Event Log",
            "",
            f"- Checkpoint event count: `{event_summary.get('event_count', 0)}`",
        ]
    )
    latest_event_at = str(event_summary.get("latest_event_at") or "")
    if latest_event_at:
        lines.append(f"- Latest event at: `{latest_event_at}`")
    return "\n".join(lines).rstrip() + "\n"


def _write_soperator_migrate_report(
    *,
    config_path: Path,
    checkpoint_path: Path,
    checkpoint: Mapping[str, Any],
    phase_ids: Sequence[str],
    completed_phases: set[str],
    target_ref: str,
    source_version: str,
    target_version: str,
    pending_phase: str,
    pending_reason: str,
    mutation_performed: bool,
    campaign: Mapping[str, Any],
) -> Path:
    report_path = _migrate_report_path(
        config_path,
        target_ref=target_ref,
        checkpoint=checkpoint,
    )
    json_report_path = _upgrade_report_json_path(
        config_path,
        target_ref=target_ref,
        checkpoint=checkpoint,
    )
    report_path.parent.mkdir(parents=True, exist_ok=True)
    phase_state = _mapping(checkpoint.get("phase_state"))
    report_phase_ids = _external_upgrade_report_phase_ids(
        phase_ids=phase_ids,
        checkpoint=checkpoint,
    )
    del checkpoint_path, pending_reason
    generated_at = _external_upgrade_report_timestamp(_utc_now())
    campaign_payload = _mapping(campaign)
    campaign_report = _external_upgrade_report_campaign_summary(campaign_payload, checkpoint)
    phase_reports: list[dict[str, Any]] = []
    stage_verification_reports: list[dict[str, Any]] = []
    for phase_id in report_phase_ids:
        if phase_id in _POST_UPGRADE_CHECK_PHASE_IDS:
            continue
        status = _phase_report_status(
            phase_id,
            completed_phases=completed_phases,
            pending_phase=pending_phase,
        )
        phase = _mapping(phase_state.get(phase_id))
        fast_verification = _external_upgrade_report_fast_verification(phase_id, phase)
        top_level_stage = external_soperator_upgrade_top_level_stage(phase_id)
        if phase_id in _FAST_STAGE_VERIFICATION_PHASE_IDS:
            stage_verification_reports.append(fast_verification)
        phase_reports.append(
            {
                "id": phase_id,
                "top_level_stage": top_level_stage,
                "status": status_label(status),
                "summary": _phase_report_summary(
                    phase_id,
                    phase,
                    checkpoint=checkpoint,
                ),
                "metrics": _external_upgrade_report_phase_metrics(
                    phase_id,
                    phase,
                    checkpoint=checkpoint,
                ),
                "fast_verification": fast_verification,
            }
        )
    for phase_id in _POST_UPGRADE_CHECK_PHASE_IDS:
        phase = _mapping(phase_state.get(phase_id))
        fast_verification = _external_upgrade_report_fast_verification(phase_id, phase)
        stage_verification_reports.append(fast_verification)
        verification_status = str(fast_verification.get("status", "") or "not_run")
        verification_summary = str(
            fast_verification.get("summary", "") or "No safe summary recorded."
        )
        top_level_stage = external_soperator_upgrade_top_level_stage(phase_id)
        phase_reports.append(
            {
                "id": phase_id,
                "top_level_stage": top_level_stage,
                "status": status_label(verification_status),
                "summary": verification_summary,
                "fast_verification": fast_verification,
                "metrics": {},
            }
        )
    validation_phase = _mapping(phase_state.get("validation-and-rollback-hold"))
    events = _sequence_of_mappings(checkpoint.get("events"))
    upgrade_safety = _mapping(checkpoint.get("upgrade_safety"))
    allowed_pending_phases = frozenset(
        {
            "none",
            "final-health-validation",
            "slurm-held-job-release",
            *_SUPPORTED_EXECUTE_PHASE_IDS,
        }
    )
    safe_pending_phase = _external_upgrade_report_enum(
        pending_phase or "none",
        allowed=allowed_pending_phases,
        fallback="unknown",
    )
    completed_report_phases = _ordered_phase_list(
        completed_phases & _SUPPORTED_EXECUTE_PHASE_IDS,
        report_phase_ids,
    )
    json_report = {
        "schema": SOPERATOR_MIGRATION_REPORT_SCHEMA,
        "report_scope": "latest",
        "source_version": _external_upgrade_report_version(source_version),
        "target_version": _external_upgrade_report_version(target_version),
        "generated_at": generated_at,
        "status": _external_upgrade_report_overall_status(
            pending_phase=safe_pending_phase,
            mutation_performed=mutation_performed,
        ),
        "pending_phase": safe_pending_phase,
        "upgrade_performed": mutation_performed,
        "timing": _external_upgrade_report_timing(checkpoint),
        "completed_phases": completed_report_phases,
        "completed_phase_count": len(completed_report_phases),
        "phases": phase_reports,
        "stage_verification": stage_verification_reports,
        "backup": _external_upgrade_report_backup_summary(_mapping(checkpoint.get("backup"))),
        "campaign": campaign_report,
        "slurm": _external_upgrade_report_safe_slurm_payload(_mapping(checkpoint.get("slurm"))),
        "validation": _external_upgrade_report_validation_summary(validation_phase),
        "event_summary": _external_upgrade_report_event_summary(events),
        "upgrade_safety": _external_upgrade_report_safety_summary(upgrade_safety),
    }
    markdown_report = _external_upgrade_report_markdown(json_report)
    _write_text_atomic(
        json_report_path,
        json.dumps(json_report, indent=2, sort_keys=True) + "\n",
        file_mode=0o600,
    )
    _write_text_atomic(report_path, markdown_report, file_mode=0o600)
    current_segment_id = str(checkpoint.get("current_segment_id", "") or "").strip()
    if campaign_payload and current_segment_id:
        segment_report_path, segment_json_report_path = ext_soperator_upgrade_segment_report_paths(
            config_path,
            target_ref,
            current_segment_id,
            cluster_id=str(checkpoint.get("cluster_id", "") or ""),
            cluster_name=str(checkpoint.get("cluster_name", "") or ""),
            kube_context=str(checkpoint.get("kube_context", "") or ""),
        )
        snapshot_json_report = {**json_report, "report_scope": "segment"}
        snapshot_markdown_report = _external_upgrade_report_markdown(snapshot_json_report)
        _write_text_atomic(
            segment_json_report_path,
            json.dumps(snapshot_json_report, indent=2, sort_keys=True) + "\n",
            file_mode=0o600,
        )
        _write_text_atomic(
            segment_report_path,
            snapshot_markdown_report,
            file_mode=0o600,
        )
    return report_path


def _new_operation_intent(
    *,
    campaign_fingerprint: str,
    segment_id: str,
) -> dict[str, Any]:
    return {
        "segment_id": segment_id,
        "idempotency_key": hashlib.sha256(
            f"{campaign_fingerprint}:{segment_id}".encode()
        ).hexdigest(),
        "attempt_state": "intent-recorded",
        "intended_postcondition": {"segment_id": segment_id},
        "resources": {},
        "provider_operations": [],
        "recorded_at": _utc_now(),
    }


def soperator_migration_slurmcluster_identity_transition(
    checkpoint: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Return validated campaign-level terminal source-to-target identity evidence."""

    raw = (checkpoint or {}).get("slurmcluster_identity_transition")
    if raw is None:
        return {}
    if not isinstance(raw, Mapping):
        raise RuntimeError("External Soperator SlurmCluster identity transition must be a mapping.")
    if raw.get("schema") != SOPERATOR_SLURMCLUSTER_IDENTITY_TRANSITION_SCHEMA:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition has an unsupported schema."
        )
    if str(raw.get("phase_id") or "").strip() != "rolling-compute-migration":
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition has an invalid phase id."
        )
    checkpoint_target = normalize_component_token((checkpoint or {}).get("target_ref"))
    transition_target = normalize_component_token(raw.get("target_ref"))
    if not checkpoint_target or transition_target != checkpoint_target:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition target differs from the "
            "checkpoint target."
        )

    def _ref(value: Any, *, label: str) -> dict[str, str]:
        mapping = _mapping(value)
        normalized = {
            key: str(mapping.get(key) or "").strip() for key in ("namespace", "name", "uid")
        }
        if not all(normalized.values()) or normalized["namespace"] != _SOPERATOR_NAMESPACE:
            raise RuntimeError(
                "External Soperator SlurmCluster identity transition has an incomplete or "
                f"unsupported {label} binding."
            )
        return normalized

    source = _ref(raw.get("source"), label="source")
    target = _ref(raw.get("target"), label="target")
    if source["name"] == target["name"] or source["uid"] == target["uid"]:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition requires distinct source "
            "and target identities."
        )
    if target["name"] != checkpoint_target:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition target binding differs "
            "from target_ref."
        )
    origin_segment_id = str(raw.get("origin_segment_id") or "").strip()
    completed_segment_ids = {
        str(item or "").strip()
        for item in (checkpoint or {}).get("completed_segment_ids", []) or []
        if str(item or "").strip()
    }
    if not origin_segment_id or origin_segment_id not in completed_segment_ids:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition origin is not a completed "
            "campaign segment."
        )
    apply_started_at = str(raw.get("target_values_apply_started_at") or "").strip()
    handoff_bound_at = str(raw.get("handoff_bound_at") or "").strip()
    if not apply_started_at or not handoff_bound_at:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition lacks apply/bind evidence."
        )
    operation_source_uid = str(
        _mapping(_mapping((checkpoint or {}).get("operation_intent")).get("resources")).get(
            "slurmcluster_uid"
        )
        or ""
    ).strip()
    if operation_source_uid and operation_source_uid != source["uid"]:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition source differs from the "
            "campaign operation identity."
        )
    cleanup = _mapping(raw.get("source_cleanup"))
    cleanup_binding = _ref(cleanup.get("binding"), label="source cleanup")
    if cleanup_binding != source:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition cleanup differs from source."
        )
    started_at = str(cleanup.get("started_at") or "").strip()
    completed_at = str(cleanup.get("completed_at") or "").strip()
    if not started_at or not completed_at:
        raise RuntimeError(
            "External Soperator SlurmCluster identity transition requires completed source "
            "cleanup evidence."
        )
    return {
        "schema": SOPERATOR_SLURMCLUSTER_IDENTITY_TRANSITION_SCHEMA,
        "phase_id": "rolling-compute-migration",
        "target_ref": checkpoint_target,
        "origin_segment_id": origin_segment_id,
        "source": source,
        "target": target,
        "target_values_apply_started_at": apply_started_at,
        "handoff_bound_at": handoff_bound_at,
        "source_cleanup": {
            "binding": cleanup_binding,
            "started_at": started_at,
            "completed_at": completed_at,
        },
    }


def _terminal_slurmcluster_identity_transition(
    checkpoint: Mapping[str, Any],
) -> dict[str, Any]:
    saved = soperator_migration_slurmcluster_identity_transition(checkpoint)
    if saved:
        rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
        concurrent_handoff = _mapping(rolling.get("slurmcluster_handoff_binding"))
        if concurrent_handoff and {
            "source": dict(_mapping(concurrent_handoff.get("source"))),
            "target": dict(_mapping(concurrent_handoff.get("target"))),
        } != {"source": saved["source"], "target": saved["target"]}:
            raise RuntimeError(
                "External Soperator campaign identity transition conflicts with operational "
                "rolling-compute handoff evidence."
            )
        return saved
    rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    handoff = _mapping(rolling.get("slurmcluster_handoff_binding"))
    if not handoff:
        return {}
    completed_at = str(rolling.get("source_cleanup_completed_at") or "").strip()
    if not completed_at:
        raise RuntimeError(
            "External Soperator upgrade cannot advance campaign segments while the "
            "source-to-target SlurmCluster handoff cleanup is incomplete."
        )
    transition = {
        "schema": SOPERATOR_SLURMCLUSTER_IDENTITY_TRANSITION_SCHEMA,
        "phase_id": "rolling-compute-migration",
        "target_ref": str(checkpoint.get("target_ref") or "").strip(),
        "origin_segment_id": str(checkpoint.get("current_segment_id") or "").strip(),
        "source": copy.deepcopy(dict(_mapping(handoff.get("source")))),
        "target": copy.deepcopy(dict(_mapping(handoff.get("target")))),
        "target_values_apply_started_at": str(
            rolling.get("target_values_apply_started_at") or ""
        ).strip(),
        "handoff_bound_at": str(rolling.get("slurmcluster_handoff_bound_at") or "").strip(),
        "source_cleanup": {
            "binding": copy.deepcopy(dict(_mapping(rolling.get("source_cleanup_binding")))),
            "started_at": str(rolling.get("source_cleanup_started_at") or "").strip(),
            "completed_at": completed_at,
        },
    }
    return soperator_migration_slurmcluster_identity_transition(
        {
            "target_ref": checkpoint.get("target_ref"),
            "completed_segment_ids": checkpoint.get("completed_segment_ids"),
            "operation_intent": checkpoint.get("operation_intent"),
            "slurmcluster_identity_transition": transition,
        }
    )


def _checkpoint_for_run(
    *,
    existing: Mapping[str, Any] | None,
    target_ref: str,
    source_report_fingerprint: str,
    source_version: str,
    target_version: str,
    phase_ids: Sequence[str],
    allow_source_report_refresh: bool = False,
    campaign_fingerprint: str,
    campaign_segment_id: str,
    source_backup_identity_fingerprint: str = "",
) -> dict[str, Any]:
    normalized_campaign_fingerprint = str(campaign_fingerprint or "").strip()
    normalized_segment_id = str(campaign_segment_id or "").strip()
    if not normalized_campaign_fingerprint:
        raise RuntimeError(
            "External Soperator upgrade execution requires the config-owned v6 "
            "campaign fingerprint."
        )
    if not normalized_segment_id:
        raise RuntimeError(
            "External Soperator upgrade execution requires one config-owned campaign segment id."
        )

    source_report_refreshed = False
    previous_source_report_fingerprint = ""
    existing_planned_phases: tuple[str, ...] = ()
    preserved_completed_segment_ids: list[str] = []
    preserved_segment_state: dict[str, Any] = {}
    preserved_events: list[Any] = []
    preserved_identity_transition: dict[str, Any] = {}
    preserved_upgrade_timing: dict[str, Any] = {}
    starting_next_segment = False
    if existing is not None:
        if existing.get("schema") != SOPERATOR_MIGRATION_EXECUTION_SCHEMA:
            raise RuntimeError(
                "External Soperator upgrade cannot resume an unsupported checkpoint "
                f"schema; expected {SOPERATOR_MIGRATION_EXECUTION_SCHEMA}."
            )
        _validate_checkpoint_journal_contract(existing)
        if str(existing.get("target_ref", "") or "") != target_ref:
            raise RuntimeError(
                "External Soperator upgrade checkpoint belongs to a different target."
            )
        existing_campaign_fingerprint = str(existing.get("campaign_fingerprint", "") or "").strip()
        if not existing_campaign_fingerprint:
            raise RuntimeError(
                "External Soperator upgrade v6 operation journal is missing its campaign "
                "fingerprint."
            )
        if existing_campaign_fingerprint != normalized_campaign_fingerprint:
            raise RuntimeError(
                "External Soperator upgrade checkpoint belongs to a different config-owned "
                "campaign. Archive the completed journal or resume the campaign whose "
                "fingerprint is already checkpointed."
            )
        existing_segment_id = str(existing.get("current_segment_id", "") or "").strip()
        if not existing_segment_id:
            raise RuntimeError(
                "External Soperator upgrade v6 operation journal is missing its current campaign "
                "segment id."
            )
        starting_next_segment = bool(
            existing_segment_id and existing_segment_id != normalized_segment_id
        )
        if starting_next_segment and not _checkpoint_run_complete(existing):
            raise RuntimeError(
                "External Soperator upgrade checkpoint has an incomplete current segment "
                f"'{existing_segment_id}'; it cannot advance to '{normalized_segment_id}'."
            )
        preserved_completed_segment_ids = [
            str(segment_id or "").strip()
            for segment_id in existing.get("completed_segment_ids", []) or []
            if str(segment_id or "").strip()
        ]
        if starting_next_segment and existing_segment_id not in preserved_completed_segment_ids:
            raise RuntimeError(
                "External Soperator upgrade checkpoint cannot advance because its current "
                f"segment '{existing_segment_id}' is not recorded as completed."
            )
        if starting_next_segment and normalized_segment_id in preserved_completed_segment_ids:
            raise RuntimeError(
                "External Soperator upgrade cannot restart completed campaign segment "
                f"'{normalized_segment_id}'."
            )
        if starting_next_segment:
            segment_state = to_plain_data(_mapping(existing.get("segment_state")))
            preserved_segment_state = (
                dict(segment_state) if isinstance(segment_state, Mapping) else {}
            )
            preserved_events = list(existing.get("events", []) or [])
            preserved_identity_transition = _terminal_slurmcluster_identity_transition(existing)
            preserved_upgrade_timing = copy.deepcopy(
                to_plain_data(_mapping(existing.get("upgrade_timing")))
            )
            completed_phases = {
                str(phase_id or "").strip()
                for phase_id in existing.get("completed_phases", []) or []
                if str(phase_id or "").strip()
            }
            if (
                "rolling-compute-migration" in completed_phases
                and not preserved_identity_transition
            ):
                raise RuntimeError(
                    "External Soperator completed rolling-compute campaign evidence has no "
                    "immutable source-to-target SlurmCluster handoff binding."
                )
            existing = None
    if existing is not None:
        existing_source_version = str(existing.get("source_version", "") or "").strip()
        existing_target_version = str(existing.get("target_version", "") or "").strip()
        existing_planned_phases = _normalized_phase_ids(existing.get("planned_phases", []) or [])
        if str(existing.get("source_report_fingerprint", "") or "") != source_report_fingerprint:
            existing_backup_identity = str(
                existing.get("backup_source_identity_fingerprint", "") or ""
            ).strip()
            if (
                _mapping(existing.get("backup"))
                and existing_backup_identity
                and source_backup_identity_fingerprint
                and existing_backup_identity != source_backup_identity_fingerprint
            ):
                raise RuntimeError(
                    "recovery-required: the immutable pre-mutation backup is bound to a "
                    "different source observation for this campaign segment. Refusing to "
                    "reuse a stale restore point after source-state drift."
                )
            rolling = _mapping(
                _mapping(existing.get("phase_state")).get("rolling-compute-migration")
            )
            handoff_target = _mapping(
                _mapping(rolling.get("slurmcluster_handoff_binding")).get("target")
            )
            checkpoint_scoped_target_version_refresh = bool(
                str(rolling.get("target_values_apply_started_at") or "").strip()
                and str(handoff_target.get("namespace") or "").strip() == _SOPERATOR_NAMESPACE
                and normalize_component_token(handoff_target.get("name"))
                == normalize_component_token(target_ref)
                and str(handoff_target.get("uid") or "").strip()
                and existing_target_version
                and source_version == existing_target_version
            )
            same_resume_contract = (
                allow_source_report_refresh
                and _same_resume_checkpoint_plan(existing_planned_phases, phase_ids)
                and (
                    not existing_source_version
                    or existing_source_version == source_version
                    or checkpoint_scoped_target_version_refresh
                )
                and (not existing_target_version or existing_target_version == target_version)
            )
            if not same_resume_contract:
                raise RuntimeError(
                    "External Soperator upgrade checkpoint is stale because the source discovery bundle changed. "
                    "Review the new bundle and remove the old checkpoint before executing."
                )
            previous_source_report_fingerprint = str(
                existing.get("source_report_fingerprint", "") or ""
            )
            source_report_refreshed = True
        completed = {
            str(phase or "").strip()
            for phase in existing.get("completed_phases", []) or []
            if str(phase or "").strip()
        }
        unsupported_completed = sorted(completed - _SUPPORTED_EXECUTE_PHASE_IDS)
        if unsupported_completed:
            raise RuntimeError(
                "External Soperator upgrade checkpoint contains completed phase(s) that this "
                "executor cannot resume safely: "
                + ", ".join(unsupported_completed)
                + ". Review or remove the checkpoint before executing."
            )
        checkpoint = dict(existing)
        if source_report_refreshed:
            checkpoint["source_report_fingerprint"] = source_report_fingerprint
    else:
        checkpoint = {
            "schema": SOPERATOR_MIGRATION_EXECUTION_SCHEMA,
            "target_ref": target_ref,
            "source_report_fingerprint": source_report_fingerprint,
            "source_version": source_version,
            "target_version": target_version,
            "created_at": _utc_now(),
            "completed_phases": [],
            "events": preserved_events,
            "upgrade_safety": upgrade_safety_checkpoint_payload(),
            "campaign_fingerprint": normalized_campaign_fingerprint,
            "current_segment_id": normalized_segment_id,
            "completed_segment_ids": list(preserved_completed_segment_ids),
            "segment_state": copy.deepcopy(preserved_segment_state),
            "operation_intent": _new_operation_intent(
                campaign_fingerprint=normalized_campaign_fingerprint,
                segment_id=normalized_segment_id,
            ),
            "compensation_obligations": [],
        }
        if source_backup_identity_fingerprint:
            checkpoint["backup_source_identity_fingerprint"] = source_backup_identity_fingerprint
        if preserved_identity_transition:
            checkpoint["slurmcluster_identity_transition"] = copy.deepcopy(
                preserved_identity_transition
            )
        if preserved_upgrade_timing:
            checkpoint["upgrade_timing"] = copy.deepcopy(preserved_upgrade_timing)
        if starting_next_segment:
            checkpoint["events"].append(
                {
                    "at": _utc_now(),
                    "event": "campaign-segment-started",
                    "segment_id": normalized_segment_id,
                }
            )
    checkpoint.setdefault("upgrade_safety", upgrade_safety_checkpoint_payload())
    checkpoint.setdefault("pending_phase", "none")
    checkpoint.setdefault("pending_reason", "")
    checkpoint.setdefault("phase_state", {})
    durable_phase_ids = _checkpoint_phase_ids_for_run(
        existing_planned_phases=existing_planned_phases,
        phase_ids=phase_ids,
    )
    segment_state = checkpoint.setdefault("segment_state", {})
    if not isinstance(segment_state, dict):
        raise RuntimeError("External Soperator upgrade checkpoint segment_state must be a mapping.")
    segment_entry = segment_state.setdefault(normalized_segment_id, {})
    if not isinstance(segment_entry, dict):
        raise RuntimeError(
            "External Soperator upgrade checkpoint current segment state must be a mapping."
        )
    segment_entry.setdefault("started_at", _utc_now())
    segment_entry["source_report_fingerprint"] = source_report_fingerprint
    segment_entry["planned_phases"] = list(durable_phase_ids)
    completed_segment_ids = checkpoint.get("completed_segment_ids")
    if not isinstance(completed_segment_ids, list):
        raise RuntimeError(
            "External Soperator upgrade checkpoint completed_segment_ids must be a list."
        )
    checkpoint["campaign_fingerprint"] = normalized_campaign_fingerprint
    checkpoint["current_segment_id"] = normalized_segment_id
    checkpoint["completed_segment_ids"] = list(completed_segment_ids)
    checkpoint["segment_state"] = segment_state
    checkpoint["updated_at"] = _utc_now()
    checkpoint["planned_phases"] = list(durable_phase_ids)
    checkpoint.setdefault(
        "operation_intent",
        _new_operation_intent(
            campaign_fingerprint=normalized_campaign_fingerprint,
            segment_id=normalized_segment_id,
        ),
    )
    checkpoint.setdefault("compensation_obligations", [])
    ensure_slurm_action_journal(checkpoint)
    if source_report_refreshed:
        events = list(checkpoint.get("events", []) or [])
        events.append(
            {
                "at": _utc_now(),
                "event": "execute-checkpoint-source-report-refreshed",
                "previous_source_report_fingerprint": previous_source_report_fingerprint,
                "source_report_fingerprint": source_report_fingerprint,
            }
        )
        checkpoint["events"] = events
    return checkpoint


def _campaign_segment_operation_intent(
    *,
    campaign_fingerprint: str,
    segment_id: str,
    segment: Mapping[str, Any],
    campaign_identity: Mapping[str, Any],
) -> dict[str, Any]:
    mk8s = _mapping(segment.get("mk8s"))
    return {
        "segment_id": segment_id,
        "idempotency_key": hashlib.sha256(
            f"{campaign_fingerprint}:{segment_id}".encode()
        ).hexdigest(),
        "attempt_state": "intent-recorded",
        "intended_postcondition": {
            "target_k8s_version": segment.get("target_k8s_version"),
            "soperator_app": to_plain_data(_mapping(segment.get("soperator_app"))),
            "soperator_chart": to_plain_data(_mapping(segment.get("soperator_chart"))),
            "jail_rootfs": to_plain_data(_mapping(segment.get("jail_rootfs"))),
            "mk8s": to_plain_data(mk8s),
        },
        "resources": {
            "cluster_id": campaign_identity.get("cluster_id"),
            "kubernetes_uid": campaign_identity.get("kubernetes_uid"),
            "soperator_uid": campaign_identity.get("soperator_uid"),
            "slurmcluster_uid": campaign_identity.get("slurmcluster_uid"),
            "jail_filesystem_id": campaign_identity.get("jail_filesystem_id"),
            "node_groups": [
                {
                    "id": group.get("id"),
                    "source": to_plain_data(_mapping(group.get("source"))),
                    "target": to_plain_data(_mapping(group.get("target"))),
                }
                for group in mk8s.get("node_groups", []) or []
                if isinstance(group, Mapping)
            ],
        },
        "provider_operations": [],
        "recorded_at": _utc_now(),
    }


def _preserved_same_segment_operation_intent(
    *,
    existing: Mapping[str, Any],
    expected: Mapping[str, Any],
) -> dict[str, Any]:
    operation_intent = existing.get("operation_intent")
    if not isinstance(operation_intent, Mapping):
        raise RuntimeError(
            "recovery-required: external Soperator operation journal lost its "
            "same-segment operation_intent."
        )
    if str(operation_intent.get("segment_id", "") or "") != str(
        expected.get("segment_id", "") or ""
    ):
        raise RuntimeError(
            "recovery-required: external Soperator same-segment operation intent "
            "references a different segment."
        )
    if str(operation_intent.get("idempotency_key", "") or "") != str(
        expected.get("idempotency_key", "") or ""
    ):
        raise RuntimeError(
            "recovery-required: external Soperator same-segment operation intent "
            "has a different idempotency key."
        )
    if to_plain_data(operation_intent.get("intended_postcondition")) != to_plain_data(
        expected.get("intended_postcondition")
    ):
        raise RuntimeError(
            "recovery-required: external Soperator same-segment operation intent "
            "postcondition differs from the config-owned campaign."
        )
    existing_resources = operation_intent.get("resources")
    expected_resources = expected.get("resources")
    if not isinstance(existing_resources, Mapping) or not isinstance(expected_resources, Mapping):
        raise RuntimeError(
            "recovery-required: external Soperator same-segment operation resources are invalid."
        )
    resource_conflicts = [
        key
        for key, value in expected_resources.items()
        if to_plain_data(existing_resources.get(key)) != to_plain_data(value)
    ]
    if resource_conflicts:
        raise RuntimeError(
            "recovery-required: external Soperator same-segment operation resource "
            "identity differs from the config-owned campaign: "
            + ", ".join(sorted(resource_conflicts))
            + "."
        )
    preserved = to_plain_data(dict(operation_intent))
    if not isinstance(preserved, Mapping):  # pragma: no cover - to_plain_data contract
        raise RuntimeError("External Soperator operation intent could not be normalized.")
    result = dict(copy.deepcopy(preserved))
    _validate_checkpoint_journal_contract(
        {
            "campaign_fingerprint": existing.get("campaign_fingerprint"),
            "current_segment_id": existing.get("current_segment_id"),
            "completed_segment_ids": existing.get("completed_segment_ids"),
            "segment_state": existing.get("segment_state"),
            "operation_intent": result,
            "compensation_obligations": existing.get("compensation_obligations"),
            "slurm": existing.get("slurm"),
        }
    )
    return result


def initialize_soperator_migration_operation_journal(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    campaign: Mapping[str, Any],
    campaign_segment_id: str,
) -> Path:
    """Persist fingerprint-specific operation intent before backup-side mutation."""

    campaign_fingerprint = str(campaign.get("fingerprint", "") or "").strip()
    segment_id = str(campaign_segment_id or "").strip()
    segments = {
        str(item.get("id", "") or "").strip(): item
        for item in campaign.get("segments", []) or []
        if isinstance(item, Mapping) and str(item.get("id", "") or "").strip()
    }
    segment = segments.get(segment_id)
    if segment is None:
        raise RuntimeError(
            "Cannot journal external Soperator operation intent for a segment that is "
            "absent from the config-owned campaign."
        )
    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        target_ref,
        payload_or_config=payload,
    )
    existing = _load_checkpoint(checkpoint_path)
    existing_same_segment = (
        existing is not None
        and str(existing.get("current_segment_id", "") or "").strip() == segment_id
    )
    report = _mapping(source_report.get("report"))
    existing_phase_ids = _checkpoint_planned_phase_ids(existing)
    checkpoint = _checkpoint_for_run(
        existing=existing,
        target_ref=target_ref,
        source_report_fingerprint=_source_report_checkpoint_fingerprint(source_report),
        source_version=str(report.get("source_version", "") or "").strip(),
        target_version=str(report.get("target_version", "") or "").strip(),
        phase_ids=existing_phase_ids,
        allow_source_report_refresh=True,
        campaign_fingerprint=campaign_fingerprint,
        campaign_segment_id=segment_id,
        source_backup_identity_fingerprint=_source_backup_identity_fingerprint(
            source_report,
            target_ref=target_ref,
        ),
    )
    expected_operation_intent = _campaign_segment_operation_intent(
        campaign_fingerprint=campaign_fingerprint,
        segment_id=segment_id,
        segment=segment,
        campaign_identity=_mapping(campaign.get("identity")),
    )
    operation_intent = (
        _preserved_same_segment_operation_intent(
            existing=existing,
            expected=expected_operation_intent,
        )
        if existing_same_segment and existing is not None
        else expected_operation_intent
    )
    checkpoint["operation_intent"] = operation_intent
    segment_state = checkpoint.setdefault("segment_state", {})
    if not isinstance(segment_state, dict):
        raise RuntimeError("External Soperator operation journal segment_state is invalid.")
    segment_entry = segment_state.setdefault(segment_id, {})
    if not isinstance(segment_entry, dict):
        raise RuntimeError("External Soperator operation journal segment entry is invalid.")
    segment_entry["operation_intent"] = copy.deepcopy(operation_intent)
    obligations = checkpoint.setdefault("compensation_obligations", [])
    if not isinstance(obligations, list):
        raise RuntimeError("External Soperator compensation obligations are invalid.")
    if not any(
        isinstance(item, Mapping) and item.get("kind") == "backup-side-effects"
        for item in obligations
    ) and not _mapping(checkpoint.get("backup")):
        obligations.append(
            {
                "kind": "backup-side-effects",
                "state": "intent-recorded",
                "required_postcondition": (
                    "restore any accounting or Slurm state paused by backup creation"
                ),
            }
        )
    _write_checkpoint(checkpoint_path, checkpoint)
    return checkpoint_path


def _campaign_segment_expected_provider_observations(
    *,
    campaign: Mapping[str, Any],
    segment: Mapping[str, Any],
    replacement_bindings: Sequence[Mapping[str, Any]] = (),
    retired_node_group_ids: Sequence[str] = (),
) -> tuple[dict[str, Any], ...]:
    identity = _mapping(campaign.get("identity"))
    campaign_segments = [
        effective_campaign_segment_for_replacements(
            item,
            replacement_bindings=replacement_bindings,
            retired_node_group_ids=retired_node_group_ids,
        )
        for item in campaign.get("segments", []) or []
        if isinstance(item, Mapping)
    ]
    segment_id = str(segment.get("id", "") or "").strip()
    segment_index = next(
        (
            index
            for index, item in enumerate(campaign_segments)
            if str(item.get("id", "") or "").strip() == segment_id
        ),
        -1,
    )
    if segment_index < 0:
        raise RuntimeError(
            "External Soperator live-observation completion cannot derive later "
            "waypoints for a segment absent from the config-owned campaign."
        )
    effective_segment = campaign_segments[segment_index]
    mk8s = _mapping(effective_segment.get("mk8s"))

    def _unique_postconditions(values: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
        result: list[dict[str, Any]] = []
        seen: set[str] = set()
        for value in values:
            plain = to_plain_data(dict(value))
            if not isinstance(plain, Mapping):
                continue
            key = _stable_json(plain)
            if key in seen:
                continue
            seen.add(key)
            result.append(dict(copy.deepcopy(plain)))
        return result

    expected: list[dict[str, Any]] = []
    control_plane = _mapping(mk8s.get("control_plane"))
    control_source = str(control_plane.get("source_version", "") or "").strip()
    control_target = str(control_plane.get("target_version", "") or "").strip()
    if control_source and control_target and control_source != control_target:
        cluster_id = str(identity.get("cluster_id", "") or "").strip()
        if not cluster_id:
            raise RuntimeError(
                "External Soperator live-observation completion requires the campaign's "
                "immutable MK8s cluster id."
            )
        acceptable_control_plane_postconditions = _unique_postconditions(
            [
                {"control_plane_version": later_target}
                for later_segment in campaign_segments[segment_index:]
                for later_target in [
                    str(
                        _mapping(_mapping(later_segment.get("mk8s")).get("control_plane")).get(
                            "target_version", ""
                        )
                        or ""
                    ).strip()
                ]
                if later_target
            ]
        )
        expected.append(
            {
                "operation_kind": "mk8s-control-plane-update",
                "resource_id": cluster_id,
                "intended_postcondition": {"control_plane_version": control_target},
                "acceptable_observed_postconditions": acceptable_control_plane_postconditions,
            }
        )
    seen_node_group_ids: set[str] = set()
    for node_group in mk8s.get("node_groups", []) or []:
        if not isinstance(node_group, Mapping):
            raise RuntimeError(
                "External Soperator live-observation completion found an invalid campaign "
                "node-group record."
            )
        source = _mapping(node_group.get("source"))
        target = _mapping(node_group.get("target"))
        if to_plain_data(source) == to_plain_data(target):
            continue
        node_group_id = str(node_group.get("id", "") or "").strip()
        if not node_group_id or node_group_id in seen_node_group_ids:
            raise RuntimeError(
                "External Soperator live-observation completion requires unique, non-empty "
                "campaign node-group ids."
            )
        seen_node_group_ids.add(node_group_id)
        intended_postcondition = {
            "kubernetes": target.get("kubernetes_version"),
            "os": target.get("os"),
            "drivers_preset": target.get("drivers_preset"),
        }
        acceptable_group_postconditions: list[Mapping[str, Any]] = [intended_postcondition]
        for later_segment in campaign_segments[segment_index + 1 :]:
            later_mk8s = _mapping(later_segment.get("mk8s"))
            later_group = next(
                (
                    item
                    for item in later_mk8s.get("node_groups", []) or []
                    if isinstance(item, Mapping)
                    and str(item.get("id", "") or "").strip() == node_group_id
                ),
                None,
            )
            if later_group is None:
                continue
            later_target = _mapping(later_group.get("target"))
            acceptable_group_postconditions.append(
                {
                    "kubernetes": later_target.get("kubernetes_version"),
                    "os": later_target.get("os"),
                    "drivers_preset": later_target.get("drivers_preset"),
                }
            )
        expected.append(
            {
                "operation_kind": "mk8s-node-group-update",
                "resource_id": node_group_id,
                "intended_postcondition": intended_postcondition,
                "acceptable_observed_postconditions": _unique_postconditions(
                    acceptable_group_postconditions
                ),
            }
        )
    return tuple(expected)


def _live_observation_provider_operations(
    *,
    campaign_fingerprint: str,
    segment_id: str,
    expected: Sequence[Mapping[str, Any]],
    observations: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    expected_by_key = {
        (
            str(item.get("operation_kind", "") or "").strip(),
            str(item.get("resource_id", "") or "").strip(),
        ): item
        for item in expected
    }
    observed_by_key: dict[tuple[str, str], Mapping[str, Any]] = {}
    for observation in observations:
        if not isinstance(observation, Mapping):
            raise RuntimeError("External Soperator live provider observation must be a mapping.")
        key = (
            str(observation.get("operation_kind", "") or "").strip(),
            str(observation.get("resource_id", "") or "").strip(),
        )
        if not all(key) or key in observed_by_key:
            raise RuntimeError(
                "External Soperator live provider observations require unique operation_kind/"
                "resource_id pairs."
            )
        observed_by_key[key] = observation
    missing = sorted(set(expected_by_key) - set(observed_by_key))
    unexpected = sorted(set(observed_by_key) - set(expected_by_key))
    if missing or unexpected:
        details: list[str] = []
        if missing:
            details.append(
                "missing " + ", ".join(f"{kind}:{resource}" for kind, resource in missing)
            )
        if unexpected:
            details.append(
                "unexpected " + ", ".join(f"{kind}:{resource}" for kind, resource in unexpected)
            )
        raise RuntimeError(
            "External Soperator live provider observations do not exactly match the "
            "campaign segment: " + "; ".join(details) + "."
        )

    checkpoint_identity = {
        "campaign_fingerprint": campaign_fingerprint,
        "current_segment_id": segment_id,
        "operation_intent": _new_operation_intent(
            campaign_fingerprint=campaign_fingerprint,
            segment_id=segment_id,
        ),
    }
    provider_operations: list[dict[str, Any]] = []
    for key in sorted(expected_by_key):
        expected_record = expected_by_key[key]
        observation = observed_by_key[key]
        resource_uid = str(observation.get("resource_uid", "") or "").strip()
        raw_resource_version = observation.get("resource_version")
        if isinstance(raw_resource_version, bool):
            raw_resource_version = None
        try:
            resource_version = int(raw_resource_version)
        except (TypeError, ValueError):
            resource_version = 0
        if not resource_uid or resource_version <= 0:
            raise RuntimeError(
                "External Soperator live provider observation requires a non-empty resource_uid "
                f"and positive resource_version for {key[0]}:{key[1]}."
            )
        observed_postcondition = observation.get("observed_postcondition")
        intended_postcondition = _mapping(expected_record.get("intended_postcondition"))
        acceptable_postconditions = expected_record.get("acceptable_observed_postconditions")
        if not isinstance(acceptable_postconditions, Sequence) or isinstance(
            acceptable_postconditions, (str, bytes, bytearray)
        ):
            acceptable_postconditions = [intended_postcondition]
        normalized_observed_postcondition = to_plain_data(observed_postcondition)
        normalized_acceptable_postconditions = [
            to_plain_data(item) for item in acceptable_postconditions if isinstance(item, Mapping)
        ]
        if (
            not isinstance(observed_postcondition, Mapping)
            or normalized_observed_postcondition not in normalized_acceptable_postconditions
        ):
            raise RuntimeError(
                "External Soperator live provider observation does not satisfy the "
                "segment postcondition or a later exact campaign waypoint for "
                f"{key[0]}:{key[1]}."
            )
        observation_material = {
            "campaign_fingerprint": campaign_fingerprint,
            "segment_id": segment_id,
            "operation_kind": key[0],
            "resource_id": key[1],
            "resource_uid": resource_uid,
            "resource_version": resource_version,
            "observed_postcondition": to_plain_data(observed_postcondition),
        }
        observation_id = (
            "observation-"
            + hashlib.sha256(_stable_json(observation_material).encode("utf-8")).hexdigest()
        )
        operation = _provider_operation_entry(
            checkpoint=checkpoint_identity,
            operation_kind=key[0],
            resource_id=key[1],
            resource_uid=resource_uid,
            resource_version=resource_version,
            intended_postcondition=intended_postcondition,
        )
        operation.update(
            {
                "attempt_state": "verified",
                "provider_operation_id": observation_id,
                "provider_operation_id_kind": "deterministic-observation-id",
                "observation_id": observation_id,
                "evidence_source": "live-provider-observation",
                "verified_postcondition": to_plain_data(observed_postcondition),
                "satisfaction_mode": (
                    "exact-postcondition"
                    if normalized_observed_postcondition == to_plain_data(intended_postcondition)
                    else "later-campaign-waypoint"
                ),
            }
        )
        provider_operations.append(operation)
    return provider_operations


def record_live_satisfied_soperator_upgrade_campaign_segment(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    campaign: Mapping[str, Any],
    campaign_segment_id: str,
    provider_observations: Sequence[Mapping[str, Any]] = (),
    replacement_bindings: Sequence[Mapping[str, Any]] = (),
    retired_node_group_ids: Sequence[str] = (),
    command_started_at: str | None = None,
    command_started_monotonic: float | None = None,
) -> Path:
    """Journal one campaign segment already satisfied by fresh live observations."""

    normalized_target = normalize_component_token(target_ref)
    campaign_fingerprint = str(campaign.get("fingerprint", "") or "").strip()
    segment_id = str(campaign_segment_id or "").strip()
    if not normalized_target or not campaign_fingerprint or not segment_id:
        raise RuntimeError(
            "External Soperator live-observation completion requires target_ref, campaign "
            "fingerprint, and campaign segment id."
        )
    if soperator_upgrade_campaign_fingerprint(campaign) != campaign_fingerprint:
        raise RuntimeError(
            "External Soperator live-observation completion requires an intact config-owned "
            "campaign fingerprint."
        )
    segments = {
        str(item.get("id", "") or "").strip(): item
        for item in campaign.get("segments", []) or []
        if isinstance(item, Mapping) and str(item.get("id", "") or "").strip()
    }
    segment = segments.get(segment_id)
    if segment is None:
        raise RuntimeError(
            "External Soperator live-observation completion cannot record a segment absent "
            "from the config-owned campaign."
        )
    expected_provider_observations = _campaign_segment_expected_provider_observations(
        campaign=campaign,
        segment=segment,
        replacement_bindings=replacement_bindings,
        retired_node_group_ids=retired_node_group_ids,
    )
    provider_operations = _live_observation_provider_operations(
        campaign_fingerprint=campaign_fingerprint,
        segment_id=segment_id,
        expected=expected_provider_observations,
        observations=provider_observations,
    )
    operation_intent = _campaign_segment_operation_intent(
        campaign_fingerprint=campaign_fingerprint,
        segment_id=segment_id,
        segment=segment,
        campaign_identity=_mapping(campaign.get("identity")),
    )
    operation_intent.update(
        {
            "attempt_state": "verified",
            "evidence_source": "live-provider-observation",
            "provider_operations": provider_operations,
        }
    )

    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        normalized_target,
        payload_or_config=payload,
        campaign_id=str(campaign.get("campaign_id", "") or ""),
    )
    existing = _load_checkpoint(checkpoint_path)
    completed_segment_ids: list[str] = []
    segment_state: dict[str, Any] = {}
    events: list[Any] = []
    created_at = _utc_now()
    prior_current_segment_id = ""
    prior_current_intent: Mapping[str, Any] | None = None
    identity_transition: dict[str, Any] = {}
    preserved_upgrade_timing: dict[str, Any] = {}
    if existing is not None:
        if str(existing.get("target_ref", "") or "") != normalized_target:
            raise RuntimeError(
                "recovery-required: external Soperator operation journal belongs to a "
                "different target."
            )
        if str(existing.get("campaign_fingerprint", "") or "") != campaign_fingerprint:
            raise RuntimeError(
                "recovery-required: external Soperator operation journal belongs to a "
                "different config-owned campaign."
            )
        if existing.get("compensation_obligations"):
            raise RuntimeError(
                "recovery-required: live-observation completion cannot clear existing "
                "compensation obligations. Resume the journaled segment first."
            )
        completed_segment_ids = [
            str(item or "").strip()
            for item in existing.get("completed_segment_ids", []) or []
            if str(item or "").strip()
        ]
        raw_segment_state = to_plain_data(_mapping(existing.get("segment_state")))
        segment_state = dict(copy.deepcopy(raw_segment_state))
        events = list(copy.deepcopy(existing.get("events", []) or []))
        created_at = str(existing.get("created_at", "") or "").strip() or created_at
        prior_current_segment_id = str(existing.get("current_segment_id", "") or "").strip()
        prior_current_intent = _mapping(existing.get("operation_intent"))
        identity_transition = _terminal_slurmcluster_identity_transition(existing)
        preserved_upgrade_timing = copy.deepcopy(
            to_plain_data(_mapping(existing.get("upgrade_timing")))
        )
        if segment_id in completed_segment_ids:
            completed_entry = _mapping(segment_state.get(segment_id))
            completed_intent = _mapping(completed_entry.get("operation_intent"))
            if completed_intent.get("attempt_state") != "verified":
                raise RuntimeError(
                    "recovery-required: completed external Soperator segment lacks its final "
                    "verified operation intent."
                )
            return checkpoint_path
        if (
            prior_current_segment_id
            and prior_current_segment_id != segment_id
            and prior_current_segment_id not in completed_segment_ids
        ):
            raise RuntimeError(
                "recovery-required: external Soperator journal has an incomplete prior "
                f"segment {prior_current_segment_id}; it cannot observe-complete {segment_id}."
            )
    dependencies = {
        str(item or "").strip()
        for item in segment.get("depends_on", []) or []
        if str(item or "").strip()
    }
    missing_dependencies = sorted(dependencies - set(completed_segment_ids))
    if missing_dependencies:
        raise RuntimeError(
            "External Soperator live-observation completion cannot skip incomplete campaign "
            "dependencies: " + ", ".join(missing_dependencies) + "."
        )

    recorded_at = _utc_now()
    segment_entry = dict(copy.deepcopy(_mapping(segment_state.get(segment_id))))
    if prior_current_segment_id == segment_id and prior_current_intent:
        segment_entry["reconciled_prior_operation_intent"] = copy.deepcopy(
            to_plain_data(dict(prior_current_intent))
        )
    segment_entry.update(
        {
            "started_at": segment_entry.get("started_at") or recorded_at,
            "completed_at": recorded_at,
            "completion_source": "live-observation",
            "mutation_performed": False,
            "source_report_fingerprint": _source_report_checkpoint_fingerprint(source_report),
            "planned_phases": [],
            "completed_phases": [],
            "operation_intent": copy.deepcopy(to_plain_data(operation_intent)),
            "operation_evidence": {
                "evidence_source": "live-provider-observation",
                "provider_observation_ids": [
                    str(item.get("observation_id", "") or "") for item in provider_operations
                ],
            },
        }
    )
    segment_state[segment_id] = segment_entry
    completed_segment_ids.append(segment_id)
    checkpoint: dict[str, Any] = {
        "schema": SOPERATOR_MIGRATION_EXECUTION_SCHEMA,
        "target_ref": normalized_target,
        "source_report_fingerprint": _source_report_checkpoint_fingerprint(source_report),
        "source_version": str(
            _mapping(source_report.get("report")).get("source_version", "") or ""
        ),
        "target_version": str(
            _mapping(source_report.get("report")).get("target_version", "") or ""
        ),
        "created_at": created_at,
        "updated_at": recorded_at,
        "completed_phases": [],
        "planned_phases": [],
        "events": events,
        "upgrade_safety": (
            copy.deepcopy(to_plain_data(_mapping(existing.get("upgrade_safety"))))
            if existing is not None
            else upgrade_safety_checkpoint_payload()
        ),
        "pending_phase": "none",
        "pending_reason": "",
        "phase_state": {},
        "campaign_fingerprint": campaign_fingerprint,
        "current_segment_id": segment_id,
        "completed_segment_ids": completed_segment_ids,
        "segment_state": segment_state,
        "operation_intent": operation_intent,
        "compensation_obligations": [],
    }
    ensure_slurm_action_journal(checkpoint)
    if identity_transition:
        checkpoint["slurmcluster_identity_transition"] = copy.deepcopy(identity_transition)
    if preserved_upgrade_timing:
        checkpoint["upgrade_timing"] = preserved_upgrade_timing
    if command_started_monotonic is not None:
        timing = dict(_mapping(checkpoint.get("upgrade_timing")))
        timing["started_at"] = (
            _external_upgrade_report_timestamp(timing.get("started_at"))
            or _external_upgrade_report_timestamp(command_started_at)
            or recorded_at
        )
        timing["last_attempt_started_at"] = (
            _external_upgrade_report_timestamp(command_started_at) or recorded_at
        )
        timing["active_elapsed_seconds"] = round(
            _external_upgrade_report_nonnegative_seconds(timing.get("active_elapsed_seconds"))
            + max(0.0, time.monotonic() - command_started_monotonic),
            3,
        )
        timing["attempt_count"] = (
            _external_upgrade_report_nonnegative_int(timing.get("attempt_count")) or 0
        ) + 1
        campaign_segment_ids = {
            str(item.get("id", "") or "").strip()
            for item in campaign.get("segments", []) or []
            if isinstance(item, Mapping) and str(item.get("id", "") or "").strip()
        }
        if campaign_segment_ids and campaign_segment_ids <= set(completed_segment_ids):
            timing["completed_at"] = recorded_at
        checkpoint["upgrade_timing"] = timing
    checkpoint["events"].append(
        {
            "at": recorded_at,
            "event": "campaign-segment-completed-from-live-observation",
            "segment_id": segment_id,
            "mutation_performed": False,
            "provider_observation_ids": [
                str(item.get("observation_id", "") or "") for item in provider_operations
            ],
        }
    )
    _validate_checkpoint_journal_contract(checkpoint)
    _write_checkpoint(checkpoint_path, checkpoint)
    return checkpoint_path


def record_soperator_migration_backup_binding(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    backup_metadata: Mapping[str, Any],
) -> None:
    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        target_ref,
        payload_or_config=payload,
    )
    checkpoint = _load_checkpoint(checkpoint_path)
    if checkpoint is None:
        raise RuntimeError("External Soperator operation journal disappeared before backup bind.")
    incoming_backup = copy.deepcopy(to_plain_data(dict(backup_metadata)))
    existing_backup = copy.deepcopy(to_plain_data(dict(_mapping(checkpoint.get("backup")))))
    if existing_backup:
        if existing_backup != incoming_backup:
            raise RuntimeError(
                "recovery-required: the campaign segment is already bound to a different "
                "immutable pre-mutation backup. The existing binding was preserved."
            )
        return
    checkpoint["backup"] = incoming_backup
    obligations = checkpoint.get("compensation_obligations")
    if not isinstance(obligations, list):
        raise RuntimeError("External Soperator compensation obligations are invalid.")
    checkpoint["compensation_obligations"] = [
        item
        for item in obligations
        if not (isinstance(item, Mapping) and item.get("kind") == "backup-side-effects")
    ]
    operation = checkpoint.get("operation_intent")
    if not isinstance(operation, dict):
        raise RuntimeError("External Soperator operation journal has no operation intent.")
    resources = operation.setdefault("resources", {})
    if not isinstance(resources, dict):
        raise RuntimeError("External Soperator operation resources are invalid.")
    resources["backup"] = {
        "path": backup_metadata.get("path"),
        "sha256": backup_metadata.get("sha256"),
        "manifest_sha256": backup_metadata.get("manifest_sha256"),
        "campaign_fingerprint": checkpoint.get("campaign_fingerprint"),
        "segment_id": checkpoint.get("current_segment_id"),
        "source_report_fingerprint": checkpoint.get("source_report_fingerprint"),
        "source_identity": {
            key: value
            for key, value in _mapping(operation.get("resources")).items()
            if key
            in {
                "cluster_id",
                "kubernetes_uid",
                "soperator_uid",
                "slurmcluster_uid",
                "jail_filesystem_id",
            }
        },
    }
    operation["resources"] = resources
    checkpoint["operation_intent"] = operation
    _append_event(
        checkpoint,
        "backup-metadata-checkpointed",
        segment_id=str(checkpoint.get("current_segment_id", "") or ""),
    )
    checkpoint["updated_at"] = _utc_now()
    _write_checkpoint(checkpoint_path, checkpoint)


def record_soperator_migration_slurmcluster_handoff_binding(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    target_slurmcluster_ref: Mapping[str, Any],
    target_creation_phase_id: str,
) -> None:
    """Persist one exact target UID recovered during checkpoint-scoped discovery."""

    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        target_ref,
        payload_or_config=payload,
    )
    checkpoint = _load_checkpoint(checkpoint_path)
    if checkpoint is None:
        raise RuntimeError(
            "External Soperator operation journal disappeared before SlurmCluster handoff bind."
        )
    target_namespace = str(target_slurmcluster_ref.get("namespace") or _SOPERATOR_NAMESPACE).strip()
    target_name = normalize_component_token(target_slurmcluster_ref.get("name"))
    target_uid = str(target_slurmcluster_ref.get("uid") or "").strip()
    if (
        target_namespace != _SOPERATOR_NAMESPACE
        or target_name != normalize_component_token(target_ref)
        or not target_uid
    ):
        raise RuntimeError(
            "External Soperator discovered target SlurmCluster binding is incomplete or "
            "belongs to a different target."
        )
    _checkpoint_rolling_compute_slurmcluster_handoff_binding(
        checkpoint=checkpoint,
        target_ref=target_ref,
        target_uid=target_uid,
        target_creation_phase_id=target_creation_phase_id,
        checkpoint_writer=None,
    )
    _write_checkpoint(checkpoint_path, checkpoint)


_BACKUP_ACCOUNTING_COMPENSATION_KIND = "backup-accounting-replicas-restore"


def record_soperator_migration_backup_compensation(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    required: bool,
    state: Mapping[str, Any],
) -> None:
    """Persist or clear the exact accounting restore obligation around backup."""

    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        target_ref,
        payload_or_config=payload,
    )
    checkpoint = _load_checkpoint(checkpoint_path)
    if checkpoint is None:
        raise RuntimeError(
            "External Soperator operation journal disappeared at the backup "
            "accounting compensation boundary."
        )
    obligations = checkpoint.get("compensation_obligations")
    if not isinstance(obligations, list):
        raise RuntimeError("External Soperator compensation obligations are invalid.")
    remaining = [
        item
        for item in obligations
        if not (
            isinstance(item, Mapping) and item.get("kind") == _BACKUP_ACCOUNTING_COMPENSATION_KIND
        )
    ]
    if required:
        normalized_state = {
            "namespace": str(state.get("namespace", "") or "").strip(),
            "deployment": str(state.get("deployment", "") or "").strip(),
            "uid": str(state.get("uid", "") or "").strip(),
            "resource_version": str(state.get("resource_version", "") or "").strip(),
            "replicas": state.get("replicas"),
        }
        missing = [
            key
            for key in ("namespace", "deployment", "uid", "resource_version")
            if not normalized_state[key]
        ]
        replicas = normalized_state.get("replicas")
        if isinstance(replicas, bool) or not isinstance(replicas, int) or replicas < 0:
            missing.append("replicas")
        if missing:
            raise RuntimeError(
                "External Soperator backup accounting compensation state is incomplete: "
                + ", ".join(missing)
                + "."
            )
        remaining.append(
            {
                "kind": _BACKUP_ACCOUNTING_COMPENSATION_KIND,
                "state": "restore-required",
                **normalized_state,
            }
        )
    checkpoint["compensation_obligations"] = remaining
    events = checkpoint.setdefault("events", [])
    if isinstance(events, list):
        events.append(
            {
                "at": _utc_now(),
                "event": (
                    "backup-accounting-restore-required"
                    if required
                    else "backup-accounting-restored"
                ),
                "deployment": str(state.get("deployment", "") or ""),
                "namespace": str(state.get("namespace", "") or ""),
            }
        )
    checkpoint["updated_at"] = _utc_now()
    _write_checkpoint(checkpoint_path, checkpoint)


def external_soperator_upgrade_backup_compensation(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Return the one exact accounting compensation obligation, if present."""

    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        target_ref,
        payload_or_config=payload,
    )
    checkpoint = _load_checkpoint(checkpoint_path)
    if checkpoint is None:
        return None
    _validate_checkpoint_journal_contract(checkpoint)
    matches = [
        dict(item)
        for item in checkpoint.get("compensation_obligations", []) or []
        if isinstance(item, Mapping) and item.get("kind") == _BACKUP_ACCOUNTING_COMPENSATION_KIND
    ]
    if len(matches) > 1:
        raise RuntimeError(
            "External Soperator operation journal contains duplicate backup accounting "
            "compensation obligations."
        )
    return matches[0] if matches else None


def _checkpoint_run_complete(checkpoint: Mapping[str, Any]) -> bool:
    if str(checkpoint.get("pending_phase", "") or "").strip() != "none":
        return False
    if checkpoint.get("compensation_obligations"):
        return False
    bridge_stage = str(_mapping(checkpoint.get("controller_bridge")).get("stage") or "")
    if bridge_stage in {
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
    }:
        return False
    current_segment_id = str(checkpoint.get("current_segment_id", "") or "").strip()
    current_segment = _mapping(_mapping(checkpoint.get("segment_state")).get(current_segment_id))
    current_operation = _mapping(current_segment.get("operation_intent"))
    if (
        current_segment.get("completion_source") == "live-observation"
        and current_operation.get("attempt_state") == "verified"
        and current_segment_id
        in {
            str(segment_id or "").strip()
            for segment_id in checkpoint.get("completed_segment_ids", []) or []
        }
        and not checkpoint.get("compensation_obligations")
    ):
        return True
    planned = set(_checkpoint_planned_phase_ids(checkpoint))
    completed = {
        str(phase or "").strip()
        for phase in checkpoint.get("completed_phases", []) or []
        if str(phase or "").strip()
    }
    return bool(planned) and planned <= completed


def _checkpoint_planned_phase_ids(checkpoint: Mapping[str, Any] | None) -> tuple[str, ...]:
    return _normalized_phase_ids((checkpoint or {}).get("planned_phases", []) or [])


def _validate_mutating_checkpoint_phase_plan(
    *,
    checkpoint_phase_ids: Sequence[str],
    required_phase_ids: Sequence[str],
) -> None:
    checkpoint = _normalized_phase_ids(checkpoint_phase_ids)
    if not checkpoint:
        raise RuntimeError(
            "External Soperator upgrade checkpoint has mutating progress but no planned "
            "phase contract. Recovery cannot continue safely."
        )
    required = _normalized_phase_ids(required_phase_ids)
    missing = [phase_id for phase_id in required if phase_id not in set(checkpoint)]
    if missing:
        raise RuntimeError(
            "External Soperator upgrade checkpoint has mutating progress but omits "
            "phase(s) required by the accepted onboarding actions: "
            + ", ".join(missing)
            + ". Recovery cannot silently add or skip accepted work after mutation."
        )
    extra = [phase_id for phase_id in checkpoint if phase_id not in set(required)]
    if extra:
        raise RuntimeError(
            "External Soperator upgrade checkpoint has mutating progress but contains "
            "phase(s) outside the accepted onboarding plan: "
            + ", ".join(extra)
            + ". Recovery cannot execute unaccepted work."
        )
    if checkpoint != required:
        raise RuntimeError(
            "External Soperator upgrade checkpoint has mutating progress but its phase "
            "order differs from the canonical accepted onboarding plan. Recovery cannot "
            "execute a reordered plan."
        )


def _normalized_phase_ids(phases: Sequence[str]) -> tuple[str, ...]:
    return tuple(str(phase or "").strip() for phase in phases if str(phase or "").strip())


def _checkpoint_phase_ids_for_run(
    *,
    existing_planned_phases: Sequence[str],
    phase_ids: Sequence[str],
) -> tuple[str, ...]:
    incoming = _normalized_phase_ids(phase_ids)
    existing = _normalized_phase_ids(existing_planned_phases)
    if not existing:
        return incoming
    if not incoming:
        return existing
    if existing == incoming:
        return incoming
    if (
        incoming
        and existing[: len(incoming)] == incoming
        and all(phase in _RESUME_OPTIONAL_PLANNED_PHASE_IDS for phase in existing[len(incoming) :])
    ):
        return existing
    if (
        existing
        and incoming[: len(existing)] == existing
        and all(phase in _RESUME_OPTIONAL_PLANNED_PHASE_IDS for phase in incoming[len(existing) :])
    ):
        return incoming
    return incoming


def _same_resume_checkpoint_plan(
    existing_planned_phases: Sequence[str],
    phase_ids: Sequence[str],
) -> bool:
    incoming = _normalized_phase_ids(phase_ids)
    existing = _normalized_phase_ids(existing_planned_phases)
    if existing == incoming:
        return True
    if incoming and existing[: len(incoming)] == incoming:
        return all(
            phase in _RESUME_OPTIONAL_PLANNED_PHASE_IDS for phase in existing[len(incoming) :]
        )
    if existing and incoming[: len(existing)] == existing:
        return all(
            phase in _RESUME_OPTIONAL_PLANNED_PHASE_IDS for phase in incoming[len(existing) :]
        )
    return False


def _checkpoint_has_mutating_progress(checkpoint: Mapping[str, Any] | None) -> bool:
    phase_state = _mapping((checkpoint or {}).get("phase_state"))
    for phase_id in _MUTATING_PHASE_IDS:
        state = phase_state.get(phase_id)
        if isinstance(state, Mapping) and bool(state):
            return True
    return False


def _node_group_provider_update_attempted(group: Mapping[str, Any]) -> bool:
    return group.get("provider_update_attempted") is True or group.get("mutation_performed") is True


def _external_node_template_phase_mutation_performed(phase: Mapping[str, Any]) -> bool:
    if phase.get("mutation_performed") is True:
        return True
    control_plane = _mapping(phase.get("control_plane"))
    for hop in _mapping(control_plane.get("hops")).values():
        if not isinstance(hop, Mapping):
            continue
        if hop.get("provider_update_attempted") is True or hop.get("mutation_performed") is True:
            return True
        if str(hop.get("status", "") or "") == "completed":
            return True
    for group in _mapping(phase.get("node_groups")).values():
        if not isinstance(group, Mapping):
            continue
        if _node_group_provider_update_attempted(group):
            return True
        if str(group.get("status", "") or "") == "completed":
            return True
    return False


def _checkpoint_phase_mutation_performed(
    checkpoint: Mapping[str, Any] | None,
    phase_id: str,
) -> bool:
    if checkpoint is None:
        return False
    for event in checkpoint.get("events", []) or []:
        if (
            isinstance(event, Mapping)
            and str(event.get("phase", "") or "") == phase_id
            and event.get("mutation_performed") is True
        ):
            return True
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id))
    if phase.get("mutation_performed") is True:
        return True
    if phase_id == _EXTERNAL_NODE_TEMPLATE_PHASE_ID:
        return _external_node_template_phase_mutation_performed(phase)
    return False


def _checkpoint_upgrade_mutation_performed(checkpoint: Mapping[str, Any] | None) -> bool:
    if checkpoint is None:
        return False
    for event in checkpoint.get("events", []) or []:
        if isinstance(event, Mapping) and event.get("mutation_performed") is True:
            return True
    for phase_id in _MUTATING_PHASE_IDS:
        if _checkpoint_phase_mutation_performed(checkpoint, phase_id):
            return True
    return False


def _checkpoint_runtime_compensation_obligations(
    checkpoint: Mapping[str, Any],
) -> list[dict[str, Any]]:
    _validate_compensation_obligations(checkpoint.get("compensation_obligations"))
    obligations = [
        copy.deepcopy(to_plain_data(dict(item)))
        for item in checkpoint.get("compensation_obligations", []) or []
        if isinstance(item, Mapping)
        and item.get("kind") in {"backup-side-effects", _BACKUP_ACCOUNTING_COMPENSATION_KIND}
    ]
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get(_EXTERNAL_NODE_TEMPLATE_PHASE_ID))
    for group_name, raw_group in _mapping(phase.get("node_groups")).items():
        if not isinstance(raw_group, Mapping):
            continue
        if (
            _node_group_provider_update_attempted(raw_group)
            and raw_group.get("strategy_restore_required") is True
            and raw_group.get("strategy_restored") is not True
        ):
            obligations.append(
                {
                    "kind": "node-group-strategy-restore",
                    "resource": str(group_name),
                    "original_strategy_args": list(
                        raw_group.get("original_strategy_args", []) or []
                    ),
                }
            )
    paused = phase.get("slurm_paused_partitions")
    final_partition_restore = _mapping(
        _mapping(checkpoint.get("slurm")).get("final_partition_restore")
    )
    if isinstance(paused, list) and paused and final_partition_restore.get("status") != "restored":
        obligations.append(
            {
                "kind": "slurm-partition-restore",
                "status": (
                    "continuous-pause"
                    if phase.get("slurm_partition_restore_deferred_reason")
                    else "recovery-required"
                ),
                "partitions": copy.deepcopy(to_plain_data(paused)),
                "manual_command": phase.get("slurm_partition_restore_manual_command"),
                "release_boundary": phase.get("slurm_pause_release_boundary"),
                "reason": phase.get("slurm_partition_restore_deferred_reason"),
            }
        )
    if not isinstance(checkpoint, dict):
        raise RuntimeError(
            "External Soperator v6 compensation reconciliation requires a mutable checkpoint."
        )
    held_job_operations = _checkpoint_slurm_held_job_operations(checkpoint)
    active_held_job_operations = _active_slurm_held_job_operations(held_job_operations)
    held_jobs = sorted(active_held_job_operations)
    if active_held_job_operations:
        obligations.append(
            {
                "kind": "slurm-held-job-release",
                "job_ids": held_jobs,
                "jobs": [
                    copy.deepcopy(to_plain_data(active_held_job_operations[job_id]))
                    for job_id in held_jobs
                ],
                "manual_command": _slurm_held_job_recovery_inspection_command(held_jobs),
            }
        )
    action_journal = ensure_slurm_action_journal(checkpoint)
    action_blockers = slurm_action_partition_restore_blockers(action_journal)
    if action_blockers:
        obligations.append(
            {
                "kind": "slurm-action-resolution",
                "actions": [copy.deepcopy(to_plain_data(dict(item))) for item in action_blockers],
            }
        )
    login_handoff = _mapping(
        _mapping(checkpoint.get("controller_bridge")).get("login_session_handoff")
    )
    login_state = str(login_handoff.get("state") or "")
    if login_state and login_state not in {"uninitialized", "complete"}:
        obligations.append(
            {
                "kind": "login-session-handoff",
                "state": login_state,
                "protected_pod_uids": [
                    str(item.get("uid") or "")
                    for item in _sequence_of_mappings(login_handoff.get("protected_pods"))
                    if str(item.get("uid") or "")
                ],
                "active_session_count": sum(
                    1
                    for item in _sequence_of_mappings(login_handoff.get("sessions"))
                    if not str(item.get("ended_at") or "").strip()
                ),
                "reason": (
                    str(login_handoff.get("indeterminate_reason") or "")
                    or "source login Pod/node group must remain until voluntary SSH exit"
                ),
            }
        )
    _validate_compensation_obligations(obligations)
    return obligations


def _checkpoint_controller_bridge_finalization_due(checkpoint: Mapping[str, Any]) -> bool:
    stage = str(_mapping(checkpoint.get("controller_bridge")).get("stage") or "")
    return stage in {
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
    }


def _checkpoint_mutating_progress_started(checkpoint: Mapping[str, Any] | None) -> bool:
    completed = {
        str(phase or "").strip()
        for phase in (checkpoint or {}).get("completed_phases", []) or []
        if str(phase or "").strip()
    }
    return bool(completed & _MUTATING_PHASE_IDS) or _checkpoint_has_mutating_progress(checkpoint)


def external_soperator_upgrade_resume_backup_metadata(
    config_path: Path,
    target_ref: str,
    *,
    payload_or_config: Any = None,
) -> dict[str, Any] | None:
    checkpoint = _load_checkpoint(
        soperator_migration_checkpoint_path(
            config_path,
            target_ref,
            payload_or_config=payload_or_config,
        )
    )
    if checkpoint is None or _checkpoint_run_complete(checkpoint):
        return None
    backup = dict(_mapping(checkpoint.get("backup")))
    if not backup and _checkpoint_mutating_progress_started(checkpoint):
        raise RuntimeError(
            "External Soperator upgrade checkpoint has mutating progress but no "
            "restore-capable backup metadata. Do not create a fresh backup over a "
            "partially upgraded cluster; review recovery state and remove the checkpoint "
            "only after deciding to restart."
        )
    if not backup:
        return None
    plain_backup = to_plain_data(backup)
    return dict(plain_backup) if isinstance(plain_backup, Mapping) else backup


def _external_upgrade_backup_archive_path(
    config_path: Path,
    value: Any,
) -> Path | None:
    text = str(value or "").strip()
    if not text:
        return None
    path = Path(text).expanduser()
    if path.is_absolute():
        return path
    return config_path.parent / path


def _external_upgrade_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _external_upgrade_backup_expected_size(backup: Mapping[str, Any]) -> int | None:
    raw_size = backup.get("size_bytes")
    try:
        size = int(str(raw_size or "").strip())
    except ValueError:
        return None
    return size if size > 0 else None


def _validate_external_upgrade_backup_metadata(
    backup: Mapping[str, Any],
    *,
    config_path: Path | None = None,
    verify_archive_hash: bool = False,
) -> None:
    missing_fields = [
        field
        for field in _EXTERNAL_UPGRADE_BACKUP_REQUIRED_FIELDS
        if not str(backup.get(field, "") or "").strip() and field != "included_categories"
    ]
    categories_value = backup.get("included_categories")
    categories = (
        {
            str(category or "").strip()
            for category in categories_value
            if str(category or "").strip()
        }
        if isinstance(categories_value, Sequence)
        and not isinstance(categories_value, (str, bytes, bytearray))
        else set()
    )
    if not categories:
        missing_fields.append("included_categories")
    missing_categories = sorted(_EXTERNAL_UPGRADE_BACKUP_REQUIRED_CATEGORIES - categories)
    details: list[str] = []
    if missing_fields:
        details.append("missing fields: " + ", ".join(missing_fields))
    if missing_categories:
        details.append("missing archive categories: " + ", ".join(missing_categories))
    if details:
        raise RuntimeError(
            "External Soperator upgrade backup metadata is sparse and cannot prove "
            "recreation-grade coverage before mutation: "
            + "; ".join(details)
            + ". Create a fresh ext-soperator upgrade backup with this cxcli version."
        )
    if config_path is None:
        return
    archive_path = _external_upgrade_backup_archive_path(config_path, backup.get("path"))
    if archive_path is None or not archive_path.exists():
        raise RuntimeError(
            "External Soperator upgrade backup metadata points to a missing archive. "
            "Review the checkpoint before rerunning mutation."
        )
    if not verify_archive_hash:
        return
    expected_size = _external_upgrade_backup_expected_size(backup)
    if expected_size is not None:
        actual_size = archive_path.stat().st_size
        if actual_size != expected_size:
            raise RuntimeError(
                "External Soperator upgrade backup archive size does not match checkpoint "
                "metadata. Review the backup archive and checkpoint before rerunning mutation."
            )
    expected_sha = str(backup.get("sha256") or "").strip()
    actual_sha = _external_upgrade_file_sha256(archive_path)
    if actual_sha != expected_sha:
        raise RuntimeError(
            "External Soperator upgrade backup archive SHA256 does not match checkpoint "
            "metadata. Review the backup archive and checkpoint before rerunning mutation."
        )


def _external_upgrade_backup_safe_members(
    archive: tarfile.TarFile,
) -> dict[str, tarfile.TarInfo]:
    raw_members = archive.getmembers()
    if len(raw_members) > _EXTERNAL_UPGRADE_BACKUP_MAX_MEMBERS:
        raise RuntimeError(
            "External Soperator upgrade backup archive contains too many members to "
            "validate safely."
        )
    members: dict[str, tarfile.TarInfo] = {}
    for member in raw_members:
        name = str(member.name or "")
        path = PurePosixPath(name)
        if not name or path.is_absolute() or ".." in path.parts:
            raise RuntimeError(
                "External Soperator upgrade backup archive contains an unsafe member path."
            )
        if name in members:
            raise RuntimeError(
                "External Soperator upgrade backup archive contains duplicate members."
            )
        if not member.isfile() and not member.isdir():
            raise RuntimeError(
                "External Soperator upgrade backup archive contains a link or special member."
            )
        members[name] = member
    return members


def _external_upgrade_backup_member_bytes(
    archive: tarfile.TarFile,
    members: Mapping[str, tarfile.TarInfo],
    name: str,
    *,
    max_bytes: int = _EXTERNAL_UPGRADE_BACKUP_MAX_IDENTITY_MEMBER_BYTES,
) -> bytes:
    member = members.get(name)
    if member is None or not member.isfile():
        raise RuntimeError(
            f"External Soperator upgrade backup archive is missing required member {name}."
        )
    if member.size < 0 or member.size > max_bytes:
        raise RuntimeError(
            f"External Soperator upgrade backup member {name} is too large to inspect safely."
        )
    extracted = archive.extractfile(member)
    if extracted is None:
        raise RuntimeError(f"External Soperator upgrade backup member {name} could not be read.")
    data = extracted.read(max_bytes + 1)
    if len(data) > max_bytes:
        raise RuntimeError(
            f"External Soperator upgrade backup member {name} is too large to inspect safely."
        )
    return data


def _external_upgrade_backup_json_member(
    archive: tarfile.TarFile,
    members: Mapping[str, tarfile.TarInfo],
    name: str,
) -> dict[str, Any]:
    try:
        payload = json.loads(
            _external_upgrade_backup_member_bytes(archive, members, name).decode("utf-8")
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError(
            f"External Soperator upgrade backup member {name} is not valid JSON."
        ) from exc
    if not isinstance(payload, Mapping):
        raise RuntimeError(
            f"External Soperator upgrade backup member {name} must contain a JSON object."
        )
    return dict(payload)


def _external_upgrade_backup_member_sha256(
    archive: tarfile.TarFile,
    member: tarfile.TarInfo,
) -> str:
    extracted = archive.extractfile(member)
    if extracted is None:
        raise RuntimeError(
            "External Soperator upgrade backup archive contains an unreadable file member."
        )
    digest = hashlib.sha256()
    for chunk in iter(lambda: extracted.read(1024 * 1024), b""):
        digest.update(chunk)
    return digest.hexdigest()


def _external_upgrade_backup_list_items(
    payload: Mapping[str, Any],
    *,
    member_name: str,
) -> list[Mapping[str, Any]]:
    items = payload.get("items")
    if not isinstance(items, Sequence) or isinstance(items, (str, bytes, bytearray)):
        raise RuntimeError(
            f"External Soperator upgrade backup member {member_name} has no Kubernetes items."
        )
    return [item for item in items if isinstance(item, Mapping)]


def _external_upgrade_backup_resource_namespace(
    resource: Mapping[str, Any],
    *,
    default: str,
) -> str:
    return str(_mapping(resource.get("metadata")).get("namespace", "") or default).strip()


def _external_upgrade_backup_resource_name(resource: Mapping[str, Any]) -> str:
    return str(_mapping(resource.get("metadata")).get("name", "") or "").strip()


def _external_upgrade_backup_source_jail_claim(
    source: Mapping[str, Any],
    *,
    pvc_names: set[str],
) -> tuple[str, set[str]]:
    spec = _mapping(source.get("spec"))
    volume_sources = {
        str(item.get("name", "") or "").strip(): item
        for item in _sequence_of_mappings(spec.get("volumeSources"))
        if str(item.get("name", "") or "").strip()
    }
    referenced_source_names: set[str] = set()
    candidates: set[str] = set()
    slurm_nodes = _mapping(spec.get("slurmNodes"))
    for role in slurm_nodes.values():
        jail = _mapping(_mapping(_mapping(role).get("volumes")).get("jail"))
        direct_claim = str(
            _mapping(jail.get("persistentVolumeClaim")).get("claimName", "") or ""
        ).strip()
        if direct_claim:
            candidates.add(direct_claim)
        source_name = str(jail.get("volumeSourceName", "") or "").strip()
        if source_name:
            referenced_source_names.add(source_name)
    if not referenced_source_names:
        referenced_source_names.update(
            name
            for name in volume_sources
            if normalize_component_token(name) in {"jail", "jail-rootfs"}
        )
    for source_name in referenced_source_names:
        claim_name = str(
            _mapping(_mapping(volume_sources.get(source_name)).get("persistentVolumeClaim")).get(
                "claimName", ""
            )
            or ""
        ).strip()
        if claim_name:
            candidates.add(claim_name)
    candidates.intersection_update(pvc_names)
    if not candidates and JAIL_LEGACY_PVC_NAME in pvc_names:
        candidates.add(JAIL_LEGACY_PVC_NAME)
    if len(candidates) != 1:
        raise RuntimeError(
            "External Soperator upgrade backup cannot prove one source jail PVC from "
            "the source SlurmCluster and namespaced PVC inventory."
        )
    return next(iter(candidates)), referenced_source_names


def _verified_external_upgrade_backup_identity(
    *,
    backup: Mapping[str, Any],
    config_path: Path,
    target_ref: str,
    expected_checkpoint: Mapping[str, Any] | None = None,
    expected_campaign: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    _validate_external_upgrade_backup_metadata(
        backup,
        config_path=config_path,
        verify_archive_hash=True,
    )
    archive_path = _external_upgrade_backup_archive_path(config_path, backup.get("path"))
    if archive_path is None:  # pragma: no cover - validated above
        raise RuntimeError("External Soperator upgrade backup archive path is missing.")
    try:
        with tarfile.open(archive_path, "r:gz") as archive:
            members = _external_upgrade_backup_safe_members(archive)
            for name in _EXTERNAL_UPGRADE_BACKUP_IDENTITY_MEMBERS:
                if name not in members:
                    raise RuntimeError(
                        "External Soperator upgrade backup archive is missing identity "
                        f"evidence member {name}."
                    )
            manifest_bytes = _external_upgrade_backup_member_bytes(
                archive,
                members,
                "backup-manifest.json",
            )
            actual_manifest_sha = hashlib.sha256(manifest_bytes).hexdigest()
            expected_manifest_sha = str(backup.get("manifest_sha256", "") or "").strip()
            if actual_manifest_sha != expected_manifest_sha:
                raise RuntimeError(
                    "External Soperator upgrade backup manifest SHA256 does not match "
                    "checkpoint metadata."
                )
            try:
                manifest_payload = json.loads(manifest_bytes.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise RuntimeError(
                    "External Soperator upgrade backup manifest is not valid JSON."
                ) from exc
            if not isinstance(manifest_payload, Mapping):
                raise RuntimeError(
                    "External Soperator upgrade backup manifest must contain a JSON object."
                )
            if manifest_payload.get("schema") != _EXTERNAL_UPGRADE_BACKUP_SCHEMA:
                raise RuntimeError("Unsupported external Soperator upgrade backup schema.")
            manifest_target = normalize_component_token(manifest_payload.get("target_ref"))
            if manifest_target != normalize_component_token(target_ref):
                raise RuntimeError(
                    "External Soperator upgrade backup belongs to a different target."
                )
            if str(manifest_payload.get("source_kind", "") or "").strip() != "external-upgrade":
                raise RuntimeError(
                    "External Soperator upgrade identity recovery requires the original "
                    "external-upgrade backup archive."
                )
            checkpoint_contract = _mapping(expected_checkpoint)
            for field in ("cluster_key", "cluster_id", "cluster_name", "kube_context"):
                expected = str(checkpoint_contract.get(field, "") or "").strip()
                actual = str(manifest_payload.get(field, "") or "").strip()
                if expected and actual != expected:
                    raise RuntimeError(
                        "External Soperator upgrade backup cluster identity does not match "
                        f"the checkpoint field {field}."
                    )
            expected_segment_id = str(
                checkpoint_contract.get("current_segment_id", "") or ""
            ).strip()
            campaign_contract = _mapping(expected_campaign)
            expected_segment = next(
                (
                    segment
                    for segment in _sequence_of_mappings(campaign_contract.get("segments"))
                    if str(segment.get("id", "") or "").strip() == expected_segment_id
                ),
                {},
            )
            expected_chart = _mapping(expected_segment.get("soperator_chart"))
            expected_chart_from = str(
                expected_chart.get("current_version")
                or checkpoint_contract.get("source_version")
                or ""
            ).strip()
            expected_chart_to = str(
                expected_chart.get("target_version")
                or checkpoint_contract.get("target_version")
                or ""
            ).strip()
            manifest_chart = _mapping(manifest_payload.get("chart"))
            for label, expected, actual in (
                ("chart.from", expected_chart_from, manifest_chart.get("from")),
                ("chart.to", expected_chart_to, manifest_chart.get("to")),
                (
                    "kubernetes.from",
                    str(expected_segment.get("current_k8s_version", "") or "").strip(),
                    _mapping(manifest_payload.get("kubernetes")).get("from"),
                ),
                (
                    "kubernetes.to",
                    str(expected_segment.get("target_k8s_version", "") or "").strip(),
                    _mapping(manifest_payload.get("kubernetes")).get("to"),
                ),
            ):
                if expected and str(actual or "").strip() != expected:
                    raise RuntimeError(
                        "External Soperator upgrade backup transition does not match "
                        f"the checkpoint field {label}."
                    )
            backup_checkpoint_id = str(manifest_payload.get("checkpoint_id", "") or "").strip()
            if checkpoint_contract and not backup_checkpoint_id:
                raise RuntimeError(
                    "External Soperator upgrade backup manifest lacks its checkpoint identity."
                )
            checksums_payload = _external_upgrade_backup_json_member(
                archive,
                members,
                "checksums.json",
            )
            checksums: dict[str, str] = {}
            for raw_name, raw_expected in checksums_payload.items():
                name = str(raw_name or "")
                expected = str(raw_expected or "").lower()
                if not re.fullmatch(r"[0-9a-f]{64}", expected):
                    raise RuntimeError(
                        "External Soperator upgrade backup checksums.json contains an "
                        "invalid SHA256 entry."
                    )
                member = members.get(name)
                if member is None or not member.isfile():
                    raise RuntimeError(
                        "External Soperator upgrade backup checksums.json references a "
                        "missing file member."
                    )
                actual = _external_upgrade_backup_member_sha256(archive, member)
                if actual != expected:
                    raise RuntimeError(
                        f"External Soperator upgrade backup archive checksum mismatch for {name}."
                    )
                checksums[name] = expected
            unchecked = sorted(
                name
                for name, member in members.items()
                if member.isfile() and name != "checksums.json" and name not in checksums
            )
            if unchecked:
                raise RuntimeError(
                    "External Soperator upgrade backup archive contains unchecked file members."
                )
            if checksums.get("backup-manifest.json") != actual_manifest_sha:
                raise RuntimeError(
                    "External Soperator upgrade backup checksums do not authenticate its manifest."
                )
            manifest_checksums = _mapping(manifest_payload.get("checksums"))
            if any(
                checksums.get(str(name)) != str(expected).lower()
                for name, expected in manifest_checksums.items()
            ):
                raise RuntimeError(
                    "External Soperator upgrade backup manifest checksums disagree with "
                    "checksums.json."
                )
            slurmclusters_payload = _external_upgrade_backup_json_member(
                archive,
                members,
                "kubernetes/slurmclusters.json",
            )
            pvcs_payload = _external_upgrade_backup_json_member(
                archive,
                members,
                "kubernetes/persistentvolumeclaims.json",
            )
            secrets_payload = _external_upgrade_backup_json_member(
                archive,
                members,
                "kubernetes/secrets.json",
            )
    except (OSError, tarfile.TarError) as exc:
        raise RuntimeError(
            "External Soperator upgrade backup archive could not be read safely."
        ) from exc

    namespace = str(manifest_payload.get("namespace", "") or _SOPERATOR_NAMESPACE).strip()
    if namespace != _SOPERATOR_NAMESPACE:
        raise RuntimeError(
            "External Soperator upgrade backup source namespace is unsupported for resume."
        )
    source_candidates = [
        item
        for item in _external_upgrade_backup_list_items(
            slurmclusters_payload,
            member_name="kubernetes/slurmclusters.json",
        )
        if str(item.get("kind", "") or "").strip().lower() == "slurmcluster"
        and _external_upgrade_backup_resource_namespace(item, default=namespace) == namespace
    ]
    non_target_candidates = [
        item
        for item in source_candidates
        if normalize_component_token(_external_upgrade_backup_resource_name(item))
        != normalize_component_token(target_ref)
    ]
    expected_source_ref = _mapping(_mapping(expected_checkpoint).get("source_slurmcluster_ref"))
    if len(non_target_candidates) == 1:
        selected = non_target_candidates
    elif len(non_target_candidates) == 0 and len(source_candidates) == 1:
        target_candidate = source_candidates[0]
        target_metadata = _mapping(target_candidate.get("metadata"))
        target_candidate_uid = str(target_metadata.get("uid", "") or "").strip()
        target_source_is_checkpoint_bound = (
            normalize_component_token(expected_source_ref.get("name"))
            == normalize_component_token(target_ref)
            and str(expected_source_ref.get("uid", "") or "").strip() == target_candidate_uid
            and bool(target_candidate_uid)
        )
        if not target_source_is_checkpoint_bound:
            raise RuntimeError(
                "External Soperator upgrade backup contains only the target-named "
                "SlurmCluster without a matching checkpointed later-segment source binding."
            )
        selected = source_candidates
    else:
        selected = []
    if len(selected) != 1:
        raise RuntimeError(
            "External Soperator upgrade backup cannot prove one source SlurmCluster identity."
        )
    source = selected[0]
    source_metadata = _mapping(source.get("metadata"))
    source_name = _external_upgrade_backup_resource_name(source)
    source_uid = str(source_metadata.get("uid", "") or "").strip()
    if not source_name or not source_uid:
        raise RuntimeError(
            "External Soperator upgrade backup source SlurmCluster identity lacks name or UID."
        )

    pvc_items = _external_upgrade_backup_list_items(
        pvcs_payload,
        member_name="kubernetes/persistentvolumeclaims.json",
    )
    pvc_by_name = {
        _external_upgrade_backup_resource_name(item): item
        for item in pvc_items
        if _external_upgrade_backup_resource_namespace(item, default=namespace) == namespace
        and _external_upgrade_backup_resource_name(item)
    }
    jail_pvc_name, jail_volume_source_names = _external_upgrade_backup_source_jail_claim(
        source,
        pvc_names=set(pvc_by_name),
    )

    source_spec = _mapping(source.get("spec"))
    source_secrets = _mapping(source_spec.get("secrets"))
    sshd_secret_name = str(source_secrets.get("sshdKeysName") or f"{source_name}-sshd-keys").strip()
    source_secret_matches = [
        item
        for item in _external_upgrade_backup_list_items(
            secrets_payload,
            member_name="kubernetes/secrets.json",
        )
        if _external_upgrade_backup_resource_namespace(item, default=namespace) == namespace
        and _external_upgrade_backup_resource_name(item) == sshd_secret_name
    ]
    if len(source_secret_matches) != 1:
        raise RuntimeError(
            "External Soperator upgrade backup cannot corroborate exactly one source SSH "
            "host-key Secret."
        )
    source_secret = source_secret_matches[0]
    secret_metadata = _mapping(source_secret.get("metadata"))
    slurmcluster_owners = [
        owner
        for owner in _sequence_of_mappings(secret_metadata.get("ownerReferences"))
        if str(owner.get("kind", "") or "").strip().lower() == "slurmcluster"
    ]
    if any(str(owner.get("uid", "") or "").strip() != source_uid for owner in slurmcluster_owners):
        raise RuntimeError(
            "External Soperator upgrade backup source SSH host-key Secret has a conflicting "
            "SlurmCluster owner UID."
        )
    source_secret_data = _mapping(source_secret.get("data"))
    missing_host_key_data = sorted(
        key
        for key in _SSHD_HOST_KEY_DATA_KEYS
        if not str(source_secret_data.get(key, "") or "").strip()
    )
    if missing_host_key_data:
        raise RuntimeError(
            "External Soperator upgrade backup source SSH host-key Secret does not contain "
            "all required host-key data fields."
        )
    source_sshd_host_key_data_sha256 = _sshd_host_key_data_digest(source_secret_data)

    recovered_spec: dict[str, Any] = {
        "secrets": {"sshdKeysName": sshd_secret_name},
    }
    source_slurm_nodes = _mapping(source_spec.get("slurmNodes"))
    recovered_slurm_nodes: dict[str, Any] = {}
    for role_name, raw_role in source_slurm_nodes.items():
        role = _mapping(raw_role)
        recovered_role: dict[str, Any] = {}
        jail = _mapping(_mapping(role.get("volumes")).get("jail"))
        if jail:
            recovered_jail: dict[str, Any] = {}
            source_name_ref = str(jail.get("volumeSourceName", "") or "").strip()
            if source_name_ref in jail_volume_source_names:
                recovered_jail["volumeSourceName"] = source_name_ref
            direct_claim = str(
                _mapping(jail.get("persistentVolumeClaim")).get("claimName", "") or ""
            ).strip()
            if direct_claim == jail_pvc_name:
                recovered_jail["persistentVolumeClaim"] = {"claimName": direct_claim}
            if recovered_jail:
                recovered_role["volumes"] = {"jail": recovered_jail}
        if str(role_name) == "login":
            raw_keys = role.get("sshRootPublicKeys")
            if isinstance(raw_keys, Sequence) and not isinstance(
                raw_keys,
                (str, bytes, bytearray),
            ):
                recovered_role["sshRootPublicKeys"] = [
                    str(key) for key in raw_keys if str(key).strip()
                ]
        if recovered_role:
            recovered_slurm_nodes[str(role_name)] = recovered_role
    if recovered_slurm_nodes:
        recovered_spec["slurmNodes"] = recovered_slurm_nodes
    recovered_volume_sources = []
    for item in _sequence_of_mappings(source_spec.get("volumeSources")):
        source_name_ref = str(item.get("name", "") or "").strip()
        claim_name = str(
            _mapping(item.get("persistentVolumeClaim")).get("claimName", "") or ""
        ).strip()
        if source_name_ref in jail_volume_source_names and claim_name == jail_pvc_name:
            recovered_volume_sources.append(
                {
                    "name": source_name_ref,
                    "persistentVolumeClaim": {"claimName": claim_name},
                }
            )
    if recovered_volume_sources:
        recovered_spec["volumeSources"] = recovered_volume_sources

    source_resource = {
        "apiVersion": str(source.get("apiVersion", "") or "slurm.nebius.ai/v1"),
        "kind": "SlurmCluster",
        "metadata": {
            "name": source_name,
            "namespace": namespace,
            "uid": source_uid,
        },
        "spec": recovered_spec,
    }
    pvc_metadata = _mapping(pvc_by_name[jail_pvc_name].get("metadata"))
    source_pvc = {
        "apiVersion": str(pvc_by_name[jail_pvc_name].get("apiVersion", "") or "v1"),
        "kind": "PersistentVolumeClaim",
        "metadata": {
            "name": jail_pvc_name,
            "namespace": namespace,
            **(
                {"uid": str(pvc_metadata.get("uid"))}
                if str(pvc_metadata.get("uid", "") or "").strip()
                else {}
            ),
        },
    }
    recovered_identity = {
        "source_slurmcluster_ref": {
            "status": "resolved",
            "namespace": namespace,
            "name": source_name,
            "uid": source_uid,
            "sshd_host_key_secret_name": sshd_secret_name,
        },
        "source_slurmcluster": source_resource,
        "source_jail_pvc": source_pvc,
    }
    provenance = {
        "schema": _EXTERNAL_UPGRADE_BACKUP_IDENTITY_RECOVERY_SCHEMA,
        "status": "verified",
        "backup_path": str(backup.get("path", "") or ""),
        "archive_sha256": str(backup.get("sha256", "") or ""),
        "manifest_sha256": actual_manifest_sha,
        "backup_checkpoint_id": str(manifest_payload.get("checkpoint_id", "") or ""),
        "current_segment_id": str(
            _mapping(expected_checkpoint).get("current_segment_id", "") or ""
        ),
        "evidence_members": list(_EXTERNAL_UPGRADE_BACKUP_IDENTITY_MEMBERS),
        "source_slurmcluster": {
            "namespace": namespace,
            "name": source_name,
            "uid": source_uid,
        },
        "source_sshd_host_key_secret_name": sshd_secret_name,
        "source_sshd_host_key_data_sha256": source_sshd_host_key_data_sha256,
        "source_jail_pvc_name": jail_pvc_name,
        "source_jail_pvc_uid": str(pvc_metadata.get("uid", "") or ""),
    }
    return recovered_identity, provenance


def _source_report_needs_verified_backup_identity(
    source_report: Mapping[str, Any],
    *,
    checkpoint: Mapping[str, Any],
    target_ref: str,
) -> bool:
    saved_ref = _mapping(checkpoint.get("source_slurmcluster_ref"))
    snapshot = _mapping(source_report.get("snapshot"))
    candidates = [
        resource
        for resource in _sequence_of_mappings(snapshot.get("soperator_resources"))
        if str(resource.get("kind", "") or "").strip().lower() == "slurmcluster"
    ]
    source_ref = _mapping(source_report.get("source_slurmcluster_ref"))
    if not saved_ref:
        non_target_candidates = [
            resource
            for resource in candidates
            if normalize_component_token(_mapping(resource.get("metadata")).get("name"))
            != normalize_component_token(target_ref)
        ]
        if len(non_target_candidates) != 1:
            return True
        source_ref_status = str(source_ref.get("status", "") or "").strip()
        if source_ref_status == "ambiguous":
            return True
        if source_ref_status == "resolved":
            ref_name = normalize_component_token(source_ref.get("name"))
            candidate_name = normalize_component_token(
                _mapping(non_target_candidates[0].get("metadata")).get("name")
            )
            if ref_name and ref_name != candidate_name:
                return True
        return False
    saved_name = str(saved_ref.get("name", "") or "").strip()
    saved_namespace = str(saved_ref.get("namespace", "") or _SOPERATOR_NAMESPACE).strip()
    saved_uid = str(saved_ref.get("uid", "") or "").strip()
    saved_secret_name = str(saved_ref.get("sshd_host_key_secret_name", "") or "").strip()
    if (
        not saved_name
        or normalize_component_token(saved_name) == normalize_component_token(target_ref)
        or not saved_uid
        or not saved_secret_name
    ):
        return True
    matches = []
    for resource in candidates:
        metadata = _mapping(resource.get("metadata"))
        if str(metadata.get("name", "") or "").strip() != saved_name:
            continue
        if str(metadata.get("namespace", "") or _SOPERATOR_NAMESPACE).strip() != saved_namespace:
            continue
        if saved_uid and str(metadata.get("uid", "") or "").strip() != saved_uid:
            continue
        matches.append(resource)
    if len(matches) != 1:
        return True
    source_ref_status = str(source_ref.get("status", "") or "").strip()
    if source_ref_status == "ambiguous":
        return True
    if source_ref_status == "resolved":
        for key in ("namespace", "name", "uid", "sshd_host_key_secret_name"):
            expected = str(saved_ref.get(key, "") or "").strip()
            actual = str(source_ref.get(key, "") or "").strip()
            if expected and actual != expected:
                return True
        return False
    raw_secrets = _mapping(matches[0].get("spec")).get("secrets")
    resource_secret_name = (
        str(_mapping(raw_secrets).get("sshdKeysName", "") or "").strip()
        if isinstance(raw_secrets, Mapping)
        else ""
    )
    return resource_secret_name != saved_secret_name


def _source_identity_required_for_execution(
    *,
    actions: Sequence[str],
    phase_ids: Sequence[str],
) -> bool:
    return (
        ONBOARDING_ACTION_UPGRADE_SOPERATOR in actions
        or ONBOARDING_ACTION_PLAN_COMPUTE_MIGRATION in actions
        or POPULATE_JAIL_REFRESH_PHASE_ID in phase_ids
        or "rolling-compute-migration" in phase_ids
    )


def _source_report_with_verified_backup_identity(
    *,
    source_report: Mapping[str, Any],
    backup: Mapping[str, Any],
    config_path: Path,
    target_ref: str,
    expected_checkpoint: Mapping[str, Any] | None = None,
    expected_campaign: Mapping[str, Any] | None = None,
) -> tuple[Mapping[str, Any], dict[str, Any]]:
    recovered, provenance = _verified_external_upgrade_backup_identity(
        backup=backup,
        config_path=config_path,
        target_ref=target_ref,
        expected_checkpoint=expected_checkpoint,
        expected_campaign=expected_campaign,
    )
    recovered_ref = _mapping(recovered.get("source_slurmcluster_ref"))
    existing_ref = _mapping(source_report.get("source_slurmcluster_ref"))
    existing_status = str(existing_ref.get("status", "") or "").strip()
    if existing_status == "ambiguous":
        raise RuntimeError(
            "Accepted source discovery has an ambiguous SlurmCluster identity; the backup "
            "cannot override an ambiguous accepted contract."
        )
    existing_ref_is_target = normalize_component_token(
        existing_ref.get("name")
    ) == normalize_component_token(target_ref)
    if (
        existing_status == "resolved"
        and not existing_ref_is_target
        and any(
            str(existing_ref.get(key, "") or "").strip()
            and str(existing_ref.get(key, "") or "").strip()
            != str(recovered_ref.get(key, "") or "").strip()
            for key in ("namespace", "name", "uid", "sshd_host_key_secret_name")
        )
    ):
        raise RuntimeError(
            "Verified backup source identity conflicts with the accepted discovery bundle."
        )

    plain_report = copy.deepcopy(to_plain_data(source_report))
    if not isinstance(plain_report, dict):  # pragma: no cover - Mapping contract
        raise RuntimeError("Soperator source discovery report could not be copied safely.")
    snapshot = plain_report.setdefault("snapshot", {})
    if not isinstance(snapshot, dict):
        raise RuntimeError("Soperator source discovery snapshot must contain a JSON object.")
    resources = snapshot.setdefault("soperator_resources", [])
    if not isinstance(resources, list):
        raise RuntimeError("Soperator source discovery resources must contain a JSON list.")
    recovered_source = _mapping(recovered.get("source_slurmcluster"))
    target_resource_present = any(
        isinstance(resource, Mapping)
        and str(resource.get("kind", "") or "").strip().lower() == "slurmcluster"
        and normalize_component_token(_mapping(resource.get("metadata")).get("name"))
        == normalize_component_token(target_ref)
        for resource in resources
    )
    source_matches = [
        resource
        for resource in resources
        if isinstance(resource, Mapping)
        and str(resource.get("kind", "") or "").strip().lower() == "slurmcluster"
        and str(_mapping(resource.get("metadata")).get("name", "") or "").strip()
        == str(recovered_ref.get("name", "") or "").strip()
        and str(
            _mapping(resource.get("metadata")).get("namespace", "") or _SOPERATOR_NAMESPACE
        ).strip()
        == str(recovered_ref.get("namespace", "") or "").strip()
    ]
    other_sources = [
        resource
        for resource in resources
        if isinstance(resource, Mapping)
        and str(resource.get("kind", "") or "").strip().lower() == "slurmcluster"
        and resource not in source_matches
        and normalize_component_token(_mapping(resource.get("metadata")).get("name"))
        != normalize_component_token(target_ref)
    ]
    if other_sources or len(source_matches) > 1:
        raise RuntimeError(
            "Verified backup source identity conflicts with source SlurmCluster resources "
            "in the accepted discovery bundle."
        )
    if source_matches:
        existing_source = source_matches[0]
        existing_uid = str(_mapping(existing_source.get("metadata")).get("uid", "") or "").strip()
        if existing_uid and existing_uid != str(recovered_ref.get("uid", "") or "").strip():
            raise RuntimeError(
                "Verified backup source UID conflicts with the accepted discovery bundle."
            )
        if not isinstance(existing_source, dict):  # pragma: no cover - plain-data contract
            raise RuntimeError("Accepted source SlurmCluster could not be enriched safely.")

        def _fill_recovered_identity_fields(
            target: dict[str, Any],
            recovered_fields: Mapping[str, Any],
        ) -> None:
            for key, recovered_value in recovered_fields.items():
                existing_value = target.get(key)
                if isinstance(recovered_value, Mapping):
                    if not isinstance(existing_value, dict):
                        if existing_value not in (None, "", "[redacted]"):
                            continue
                        existing_value = {}
                        target[key] = existing_value
                    _fill_recovered_identity_fields(existing_value, recovered_value)
                    continue
                if (
                    key not in target
                    or existing_value in (None, "", "[redacted]")
                    or (
                        isinstance(existing_value, Sequence)
                        and not isinstance(existing_value, (str, bytes, bytearray))
                        and not existing_value
                    )
                ):
                    target[key] = copy.deepcopy(recovered_value)

        _fill_recovered_identity_fields(existing_source, recovered_source)
        plain_report.pop("recovered_source_slurmcluster", None)
    else:
        plain_report["recovered_source_slurmcluster"] = copy.deepcopy(recovered_source)

    pvcs = snapshot.setdefault("pvcs", [])
    if not isinstance(pvcs, list):
        raise RuntimeError("Soperator source discovery PVCs must contain a JSON list.")
    recovered_pvc = _mapping(recovered.get("source_jail_pvc"))
    recovered_pvc_metadata = _mapping(recovered_pvc.get("metadata"))
    recovered_pvc_name = str(recovered_pvc_metadata.get("name", "") or "").strip()
    recovered_pvc_namespace = str(
        recovered_pvc_metadata.get("namespace", "") or _SOPERATOR_NAMESPACE
    ).strip()
    matching_pvcs = [
        pvc
        for pvc in pvcs
        if isinstance(pvc, Mapping)
        and str(_mapping(pvc.get("metadata")).get("name", "") or "").strip() == recovered_pvc_name
        and str(_mapping(pvc.get("metadata")).get("namespace", "") or _SOPERATOR_NAMESPACE).strip()
        == recovered_pvc_namespace
    ]
    if len(matching_pvcs) > 1:
        raise RuntimeError(
            "Verified backup source jail PVC identity is ambiguous in the accepted "
            "discovery bundle."
        )
    if matching_pvcs:
        existing_pvc = matching_pvcs[0]
        existing_pvc_metadata = _mapping(existing_pvc.get("metadata"))
        existing_pvc_uid = str(existing_pvc_metadata.get("uid", "") or "").strip()
        recovered_pvc_uid = str(recovered_pvc_metadata.get("uid", "") or "").strip()
        if existing_pvc_uid and recovered_pvc_uid and existing_pvc_uid != recovered_pvc_uid:
            raise RuntimeError(
                "Verified backup source jail PVC UID conflicts with the accepted discovery bundle."
            )
        if recovered_pvc_uid and not existing_pvc_uid:
            if not isinstance(existing_pvc, dict):  # pragma: no cover - plain-data contract
                raise RuntimeError("Accepted source jail PVC could not be enriched safely.")
            metadata = existing_pvc.setdefault("metadata", {})
            if not isinstance(metadata, dict):
                raise RuntimeError("Accepted source jail PVC metadata must be a mapping.")
            metadata["uid"] = recovered_pvc_uid
    else:
        pvcs.append(copy.deepcopy(recovered_pvc))
    storage = snapshot.setdefault("storage", {})
    if not isinstance(storage, dict):
        raise RuntimeError("Soperator source discovery storage must contain a JSON object.")
    existing_jail = _mapping(storage.get("jail"))
    existing_jail_pvc = str(
        existing_jail.get("pvc", "")
        or existing_jail.get("claimName", "")
        or str(existing_jail.get("source", "") or "").removeprefix("pvc/")
    ).strip()
    if (
        existing_jail_pvc
        and existing_jail_pvc != recovered_pvc_name
        and not existing_ref_is_target
        and not target_resource_present
    ):
        raise RuntimeError(
            "Verified backup source jail PVC conflicts with the accepted discovery bundle."
        )
    storage["jail"] = {"source": f"pvc/{recovered_pvc_name}", "pvc": recovered_pvc_name}
    plain_report["source_slurmcluster_ref"] = copy.deepcopy(dict(recovered_ref))
    return plain_report, provenance


def _target_resume_versions(target_version: str) -> set[str]:
    versions: set[str] = set()
    normalized = normalize_soperator_release_version(target_version)
    if normalized:
        versions.add(normalized)
    for marker in ("-ps.", "+"):
        base = str(target_version or "").split(marker, 1)[0]
        normalized_base = normalize_soperator_release_version(base)
        if normalized_base:
            versions.add(normalized_base)
    return versions


def _soperator_source_release_selectors() -> tuple[frozenset[str], frozenset[str], tuple[str, ...]]:
    """Return the code-owned v6 cleanup allowlist without mutable profile I/O."""

    release_names = {name.lower() for name in _SOPERATOR_SOURCE_RELEASE_NAMES}
    chart_prefixes = {prefix.lower() for prefix in _SOPERATOR_SOURCE_CHART_PREFIXES}
    release_prefixes = tuple(prefix.lower() for prefix in _SOPERATOR_SOURCE_RELEASE_NAME_PREFIXES)
    return (
        frozenset(item for item in release_names if item),
        frozenset(item for item in chart_prefixes if item),
        release_prefixes,
    )


def _source_chart_matches_profile(chart: str) -> bool:
    chart_text = str(chart or "").strip().lower()
    if not chart_text:
        return False
    _release_names, chart_prefixes, _release_prefixes = _soperator_source_release_selectors()
    return any(
        chart_text == prefix or chart_text.startswith(f"{prefix}-") for prefix in chart_prefixes
    )


def _source_release_name_matches_profile(name: str) -> bool:
    name_text = str(name or "").strip().lower()
    if not name_text:
        return False
    release_names, _chart_prefixes, release_prefixes = _soperator_source_release_selectors()
    return name_text in release_names or any(
        name_text.startswith(prefix) for prefix in release_prefixes
    )


def _soperator_target_release_record(release: Any, *, target_versions: set[str]) -> bool:
    name = str(getattr(release, "name", "") or "").strip().lower()
    namespace = str(getattr(release, "namespace", "") or "").strip()
    if name != _SOPERATOR_TARGET_RELEASE_NAME or namespace != _SOPERATOR_NAMESPACE:
        return False
    chart = str(getattr(release, "chart", "") or "").strip().lower()
    if not chart.startswith(f"{_SOPERATOR_TARGET_RELEASE_NAME}-"):
        return False
    release_versions = _soperator_release_versions(release)
    return not release_versions or release_versions.issubset(target_versions)


def _target_gpu_stack_release_matches_row(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    row: Mapping[str, Any],
) -> bool:
    release_name = str(
        row.get("release-name", "") or row.get("release_name", "") or row.get("id") or ""
    ).strip()
    namespace = str(row.get("namespace", "") or "").strip()
    expected_version = str(row.get("version", "") or "").strip()
    expected_chart = str(row.get("chart", "") or "").strip()
    chart_ref = _app_chart_ref(row)
    if not expected_chart and chart_ref:
        expected_chart = chart_ref.rstrip("/").rsplit("/", maxsplit=1)[-1]
    if not release_name or not namespace or not expected_version or not expected_chart:
        return False
    try:
        releases = list_helm_releases(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=namespace,
            filter_regex=f"^{re.escape(release_name)}$",
        )
    except (RuntimeError, subprocess.TimeoutExpired):
        return False
    matching = tuple(
        release
        for release in releases
        if release.name == release_name and release.namespace == namespace
    )
    if len(matching) != 1:
        return False
    release = matching[0]
    return (
        release.status.strip().lower() == "deployed"
        and release.chart == f"{expected_chart}-{expected_version}"
        and release.chart_version == expected_version
    )


def _soperator_source_release_family(release: Any) -> bool:
    name = str(getattr(release, "name", "") or "").strip().lower()
    chart = str(getattr(release, "chart", "") or "").strip().lower()
    source_chart = _source_chart_matches_profile(chart)
    if (
        name == _SOPERATOR_TARGET_RELEASE_NAME
        and str(getattr(release, "namespace", "") or "").strip() == _SOPERATOR_NAMESPACE
    ):
        return source_chart
    if _source_release_name_matches_profile(name):
        return True
    return source_chart


def _soperator_source_auxiliary_release(
    release: Any,
) -> tuple[str, str, str, str] | None:
    namespace = str(getattr(release, "namespace", "") or "").strip()
    name = str(getattr(release, "name", "") or "").strip().lower()
    expected = _SOPERATOR_SOURCE_AUXILIARY_RELEASES.get((namespace, name))
    if expected is None:
        return None
    chart_prefix, flux_helmrelease_name = expected
    chart = str(getattr(release, "chart", "") or "").strip().lower()
    if chart != chart_prefix and not chart.startswith(f"{chart_prefix}-"):
        return None
    return namespace, name, chart_prefix, flux_helmrelease_name


def _soperator_source_auxiliary_release_has_flux_ownership(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    release: Any,
) -> bool:
    auxiliary = _soperator_source_auxiliary_release(release)
    if auxiliary is None:
        return False
    namespace, release_name, _chart_prefix, flux_helmrelease_name = auxiliary
    payload = _kubectl_json_or_empty(
        command_runner=command_runner,
        command=[
            "kubectl",
            "--context",
            kube_context,
            "get",
            "deployment",
            "-A",
            "-o",
            "json",
        ],
        description=f"kubectl get source auxiliary deployments in {namespace}",
    )
    for item in _sequence_of_mappings(payload.get("items")):
        metadata = _mapping(item.get("metadata"))
        annotations = _mapping(metadata.get("annotations"))
        labels = _mapping(metadata.get("labels"))
        if (
            str(metadata.get("namespace", "") or "").strip() == namespace
            and str(annotations.get("meta.helm.sh/release-name", "") or "").strip() == release_name
            and str(annotations.get("meta.helm.sh/release-namespace", "") or "").strip()
            == namespace
            and str(labels.get("helm.toolkit.fluxcd.io/name", "") or "").strip()
            == flux_helmrelease_name
            and str(labels.get("helm.toolkit.fluxcd.io/namespace", "") or "").strip()
            == "flux-system"
        ):
            return True
    return False


def _soperator_release_versions(release: Any) -> set[str]:
    versions: set[str] = set()
    for value in (
        getattr(release, "chart", ""),
        getattr(release, "chart_version", ""),
        getattr(release, "app_version", ""),
    ):
        normalized = normalize_soperator_release_version(str(value or ""))
        if normalized:
            versions.add(normalized)
    return versions


def _deployed_stale_source_soperator_releases(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_version: str,
) -> tuple[Any, ...]:
    target_versions = _target_resume_versions(target_version)
    stale: list[Any] = []
    releases: list[Any] = []
    release_namespaces = tuple(
        dict.fromkeys(
            (
                *_SOPERATOR_SOURCE_RELEASE_NAMESPACES,
                *(namespace for namespace, _name in _SOPERATOR_SOURCE_AUXILIARY_RELEASES),
            )
        )
    )
    for namespace in release_namespaces:
        try:
            releases.extend(
                list_helm_releases(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    namespace=namespace,
                    timeout_seconds=30,
                )
            )
        except subprocess.TimeoutExpired:
            continue
    for release in releases:
        if str(getattr(release, "status", "") or "").strip().lower() != "deployed":
            continue
        if _soperator_target_release_record(release, target_versions=target_versions):
            continue
        auxiliary = _soperator_source_auxiliary_release(release)
        if auxiliary is not None:
            if not _soperator_source_auxiliary_release_has_flux_ownership(
                command_runner=command_runner,
                kube_context=kube_context,
                release=release,
            ):
                continue
        elif not _soperator_source_release_family(release):
            continue
        stale.append(release)
    return tuple(stale)


def _release_key(namespace: Any, name: Any) -> tuple[str, str]:
    return (str(namespace or "").strip(), str(name or "").strip())


def _release_sort_key(release: Any) -> tuple[int, str, str]:
    name = str(getattr(release, "name", "") or "").strip()
    try:
        order = _SOPERATOR_SOURCE_RELEASE_RETIRE_ORDER.index(name)
    except ValueError:
        order = len(_SOPERATOR_SOURCE_RELEASE_RETIRE_ORDER)
    namespace = str(getattr(release, "namespace", "") or "").strip()
    return (order, namespace, name)


def _kubectl_json_or_empty(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    command: Sequence[str],
    description: str,
    timeout_seconds: int = 30,
    request_timeout: str = "20s",
) -> Mapping[str, Any]:
    bounded_command = list(command)
    if (
        bounded_command
        and bounded_command[0] == "kubectl"
        and request_timeout
        and not any(str(item).startswith("--request-timeout=") for item in bounded_command)
    ):
        bounded_command.append(f"--request-timeout={request_timeout}")
    try:
        result = command_runner(bounded_command, timeout_seconds=timeout_seconds, check=False)
    except subprocess.TimeoutExpired:
        return {}
    if result.returncode != 0:
        return {}
    try:
        payload = json.loads(result.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"{description} returned invalid JSON: {exc}") from exc
    return payload if isinstance(payload, Mapping) else {}


def _source_flux_helmrelease_matches_release(
    item: Mapping[str, Any],
    release_keys: set[tuple[str, str]],
) -> bool:
    if not release_keys:
        return False
    metadata = _mapping(item.get("metadata"))
    spec = _mapping(item.get("spec"))
    status = _mapping(item.get("status"))
    target_namespace = str(spec.get("targetNamespace", "") or metadata.get("namespace", "") or "")
    release_name = str(spec.get("releaseName", "") or metadata.get("name", "") or "")
    if _release_key(target_namespace, release_name) in release_keys:
        return True
    for history in _sequence_of_mappings(status.get("history")):
        if _release_key(history.get("namespace"), history.get("name")) in release_keys:
            return True
    return False


def _source_flux_helmrelease_chart_family(
    item: Mapping[str, Any],
    *,
    target_version: str,
) -> bool:
    spec = _mapping(item.get("spec"))
    chart_spec = _mapping(_mapping(spec.get("chart")).get("spec"))
    chart_name = str(chart_spec.get("chart", "") or "").strip().lower()
    if not _source_chart_matches_profile(chart_name):
        return False
    target_versions = _target_resume_versions(target_version)
    release_versions: set[str] = set()
    for value in (chart_spec.get("version"), chart_spec.get("appVersion")):
        normalized = normalize_soperator_release_version(str(value or ""))
        if normalized:
            release_versions.add(normalized)
    for history in _sequence_of_mappings(_mapping(item.get("status")).get("history")):
        for value in (history.get("chartVersion"), history.get("appVersion")):
            normalized = normalize_soperator_release_version(str(value or ""))
            if normalized:
                release_versions.add(normalized)
    return not release_versions or not release_versions.issubset(target_versions)


def _source_flux_helmrelease_candidates(
    *,
    payload: Mapping[str, Any],
    stale_releases: Sequence[Any],
    target_version: str,
    include_suspended: bool,
) -> tuple[Mapping[str, Any], ...]:
    release_keys = {
        _release_key(getattr(release, "namespace", ""), getattr(release, "name", ""))
        for release in stale_releases
    }
    candidates: list[Mapping[str, Any]] = []
    for item in _sequence_of_mappings(payload.get("items")):
        metadata = _mapping(item.get("metadata"))
        spec = _mapping(item.get("spec"))
        if not include_suspended and bool(spec.get("suspend")):
            continue
        name = str(metadata.get("name", "") or "").strip()
        if (
            _legacy_flux_helmrelease_name(name)
            or _source_flux_helmrelease_matches_release(
                item,
                release_keys,
            )
            or _source_flux_helmrelease_chart_family(item, target_version=target_version)
        ):
            candidates.append(item)
    return tuple(candidates)


def _source_flux_helmrelease_suspend_candidates(
    *,
    payload: Mapping[str, Any],
    stale_releases: Sequence[Any],
    target_version: str,
) -> tuple[Mapping[str, Any], ...]:
    return _source_flux_helmrelease_candidates(
        payload=payload,
        stale_releases=stale_releases,
        target_version=target_version,
        include_suspended=False,
    )


def _source_flux_helmrelease_retire_candidates(
    *,
    payload: Mapping[str, Any],
    stale_releases: Sequence[Any],
    target_version: str,
) -> tuple[Mapping[str, Any], ...]:
    return _source_flux_helmrelease_candidates(
        payload=payload,
        stale_releases=stale_releases,
        target_version=target_version,
        include_suspended=True,
    )


def _kubectl_patch_ignore_not_found(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    command: Sequence[str],
    timeout_seconds: int = 120,
) -> bool:
    result = command_runner(command, timeout_seconds=timeout_seconds, check=False)
    if result.returncode == 0:
        return True
    if _command_not_found(result):
        return False
    raise RuntimeError(f"{_command_text(result.args)} failed: {_command_detail(result)}")


def _delete_source_flux_helmreleases(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    stale_releases: Sequence[Any],
    target_version: str,
) -> tuple[str, ...]:
    payload = _kubectl_json_or_empty(
        command_runner=command_runner,
        command=[
            "kubectl",
            "--context",
            kube_context,
            "get",
            "helmreleases.helm.toolkit.fluxcd.io",
            "-A",
            "-o",
            "json",
        ],
        description="kubectl get HelmRelease",
    )
    candidates = _source_flux_helmrelease_retire_candidates(
        payload=payload,
        stale_releases=stale_releases,
        target_version=target_version,
    )
    deleted: list[str] = []
    for item in candidates:
        metadata = _mapping(item.get("metadata"))
        namespace = str(metadata.get("namespace", "") or "").strip()
        name = str(metadata.get("name", "") or "").strip()
        if not namespace or not name:
            continue
        spec = _mapping(item.get("spec"))
        if not _bool_value(spec.get("suspend"), fallback=False):
            _kubectl_patch_ignore_not_found(
                command_runner=command_runner,
                command=[
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    namespace,
                    "patch",
                    "helmrelease.helm.toolkit.fluxcd.io",
                    name,
                    "--type=merge",
                    "-p",
                    json.dumps({"spec": {"suspend": True}}, separators=(",", ":")),
                ],
            )
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "delete",
                "helmrelease.helm.toolkit.fluxcd.io",
                name,
                "--ignore-not-found=true",
                "--wait=false",
            ],
            timeout_seconds=60,
        )
        deleted.append(f"{namespace}/{name}")
    return tuple(sorted(dict.fromkeys(deleted)))


def _source_flux_helmrelease_kustomization_refs(
    items: Sequence[Mapping[str, Any]],
) -> tuple[tuple[str, str], ...]:
    refs: list[tuple[str, str]] = []
    for item in items:
        labels = _mapping(_mapping(item.get("metadata")).get("labels"))
        name = str(labels.get("kustomize.toolkit.fluxcd.io/name", "") or "").strip()
        namespace = str(labels.get("kustomize.toolkit.fluxcd.io/namespace", "") or "").strip()
        if name and namespace:
            refs.append((namespace, name))
    return tuple(sorted(dict.fromkeys(refs)))


def _suspend_source_flux_kustomizations(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    items: Sequence[Mapping[str, Any]],
) -> tuple[str, ...]:
    suspended: list[str] = []
    for namespace, name in _source_flux_helmrelease_kustomization_refs(items):
        patched = _kubectl_patch_ignore_not_found(
            command_runner=command_runner,
            command=[
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "patch",
                "kustomization.kustomize.toolkit.fluxcd.io",
                name,
                "--type=merge",
                "-p",
                json.dumps({"spec": {"suspend": True}}, separators=(",", ":")),
            ],
        )
        if patched:
            suspended.append(f"{namespace}/{name}")
    return tuple(suspended)


def _suspend_source_flux_helmreleases(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    stale_releases: Sequence[Any],
    target_version: str,
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    payload = _kubectl_json_or_empty(
        command_runner=command_runner,
        command=[
            "kubectl",
            "--context",
            kube_context,
            "get",
            "helmreleases.helm.toolkit.fluxcd.io",
            "-A",
            "-o",
            "json",
        ],
        description="kubectl get HelmRelease",
    )
    retire_candidates = _source_flux_helmrelease_retire_candidates(
        payload=payload,
        stale_releases=stale_releases,
        target_version=target_version,
    )
    suspended_kustomizations = _suspend_source_flux_kustomizations(
        command_runner=command_runner,
        kube_context=kube_context,
        items=retire_candidates,
    )
    candidates = _source_flux_helmrelease_suspend_candidates(
        payload=payload,
        stale_releases=stale_releases,
        target_version=target_version,
    )
    suspended: list[str] = []
    for item in candidates:
        metadata = _mapping(item.get("metadata"))
        namespace = str(metadata.get("namespace", "") or "").strip()
        name = str(metadata.get("name", "") or "").strip()
        if not namespace or not name:
            continue
        patched = _kubectl_patch_ignore_not_found(
            command_runner=command_runner,
            command=[
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "patch",
                "helmrelease.helm.toolkit.fluxcd.io",
                name,
                "--type=merge",
                "-p",
                json.dumps({"spec": {"suspend": True}}, separators=(",", ":")),
            ],
        )
        if patched:
            suspended.append(f"{namespace}/{name}")
    return (
        tuple(sorted(dict.fromkeys(suspended))),
        tuple(sorted(dict.fromkeys(suspended_kustomizations))),
    )


def _active_source_flux_helmreleases(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_version: str,
) -> tuple[Mapping[str, Any], ...]:
    payload = _kubectl_json_or_empty(
        command_runner=command_runner,
        command=[
            "kubectl",
            "--context",
            kube_context,
            "get",
            "helmreleases.helm.toolkit.fluxcd.io",
            "-A",
            "-o",
            "json",
        ],
        description="kubectl get HelmRelease",
    )
    return _source_flux_helmrelease_suspend_candidates(
        payload=payload,
        stale_releases=(),
        target_version=target_version,
    )


def _resource_annotation_release_name(item: Mapping[str, Any]) -> str:
    metadata = _mapping(item.get("metadata"))
    annotations = _mapping(metadata.get("annotations"))
    return str(annotations.get("meta.helm.sh/release-name", "") or "").strip()


def _resource_annotation_release_namespace(item: Mapping[str, Any]) -> str:
    metadata = _mapping(item.get("metadata"))
    annotations = _mapping(metadata.get("annotations"))
    return str(annotations.get("meta.helm.sh/release-namespace", "") or "").strip()


def _delete_kubernetes_resource(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    resource_type: str,
    name: str,
    namespace: str = "",
) -> None:
    command = ["kubectl", "--context", kube_context]
    if namespace:
        command.extend(["-n", namespace])
    command.extend(
        [
            "delete",
            resource_type,
            name,
            "--ignore-not-found=true",
            "--wait=false",
        ]
    )
    command_runner(command, timeout_seconds=60)


def _prune_safe_source_soperator_resources(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    stale_releases: Sequence[Any],
) -> tuple[str, ...]:
    safe_release_keys = {
        (
            str(getattr(release, "namespace", "") or "").strip(),
            str(getattr(release, "name", "") or "").strip(),
        )
        for release in stale_releases
        if str(getattr(release, "name", "") or "").strip()
        in _SOPERATOR_SOURCE_SAFE_PRUNE_RELEASE_NAMES
    }
    if not safe_release_keys:
        return ()
    deleted: list[str] = []
    for resource_type in _SOPERATOR_SOURCE_SAFE_NAMESPACED_RESOURCE_TYPES:
        payload = _kubectl_json_or_empty(
            command_runner=command_runner,
            command=[
                "kubectl",
                "--context",
                kube_context,
                "get",
                resource_type,
                "-A",
                "-o",
                "json",
            ],
            description=f"kubectl get {resource_type}",
        )
        for item in _sequence_of_mappings(payload.get("items")):
            release_name = _resource_annotation_release_name(item)
            metadata = _mapping(item.get("metadata"))
            namespace = str(metadata.get("namespace", "") or "").strip()
            release_namespace = _resource_annotation_release_namespace(item) or namespace
            if (release_namespace, release_name) not in safe_release_keys:
                continue
            name = str(metadata.get("name", "") or "").strip()
            if not namespace or not name:
                continue
            _delete_kubernetes_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type=resource_type,
                namespace=namespace,
                name=name,
            )
            deleted.append(f"{resource_type}/{namespace}/{name}")
    for resource_type in _SOPERATOR_SOURCE_SAFE_CLUSTER_RESOURCE_TYPES:
        payload = _kubectl_json_or_empty(
            command_runner=command_runner,
            command=[
                "kubectl",
                "--context",
                kube_context,
                "get",
                resource_type,
                "-o",
                "json",
            ],
            description=f"kubectl get {resource_type}",
        )
        for item in _sequence_of_mappings(payload.get("items")):
            release_name = _resource_annotation_release_name(item)
            release_namespace = _resource_annotation_release_namespace(item)
            if (release_namespace, release_name) not in safe_release_keys:
                continue
            metadata = _mapping(item.get("metadata"))
            name = str(metadata.get("name", "") or "").strip()
            if not name:
                continue
            _delete_kubernetes_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                resource_type=resource_type,
                name=name,
            )
            deleted.append(f"{resource_type}/{name}")
    return tuple(sorted(dict.fromkeys(deleted)))


def _delete_stale_helm_storage_records(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    stale_releases: Sequence[Any],
) -> tuple[str, ...]:
    exact_stale_revisions = {
        (
            str(getattr(release, "name", "") or "").strip(),
            str(getattr(release, "revision", "") or "").strip(),
        )
        for release in stale_releases
        if str(getattr(release, "name", "") or "").strip()
        and str(getattr(release, "revision", "") or "").strip()
    }
    stale_names_without_revision = {
        str(getattr(release, "name", "") or "").strip()
        for release in stale_releases
        if str(getattr(release, "name", "") or "").strip()
        and not str(getattr(release, "revision", "") or "").strip()
        and str(getattr(release, "name", "") or "").strip() != _SOPERATOR_TARGET_RELEASE_NAME
    }
    if not exact_stale_revisions and not stale_names_without_revision:
        return ()
    payload = _kubectl_json_or_empty(
        command_runner=command_runner,
        command=[
            "kubectl",
            "--context",
            kube_context,
            "get",
            "secrets",
            "-A",
            "-l",
            "owner=helm",
            "-o",
            "json",
        ],
        description="kubectl get Helm storage secrets",
    )
    deleted: list[str] = []
    for item in _sequence_of_mappings(payload.get("items")):
        metadata = _mapping(item.get("metadata"))
        labels = _mapping(metadata.get("labels"))
        release_name = str(labels.get("name", "") or "").strip()
        revision = str(labels.get("version", "") or "").strip()
        if (
            release_name,
            revision,
        ) not in exact_stale_revisions and release_name not in stale_names_without_revision:
            continue
        namespace = str(metadata.get("namespace", "") or "").strip()
        name = str(metadata.get("name", "") or "").strip()
        if not namespace or not name:
            continue
        command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "delete",
                "secret",
                name,
                "--ignore-not-found=true",
                "--wait=false",
            ],
            timeout_seconds=120,
        )
        deleted.append(f"{namespace}/{name}")
    return tuple(sorted(dict.fromkeys(deleted)))


def _source_auxiliary_namespace_allowed_residue(item: Mapping[str, Any]) -> bool:
    """Allow only defaults and exact legacy MariaDB webhook residue."""

    kind = str(item.get("kind", "") or "").strip()
    metadata = _mapping(item.get("metadata"))
    name = str(metadata.get("name", "") or "").strip()
    if kind == "Event":
        return True
    if (kind, name) in {
        ("ConfigMap", "kube-root-ca.crt"),
        ("ServiceAccount", "default"),
    }:
        return True
    annotations = _mapping(metadata.get("annotations"))
    labels = _mapping(metadata.get("labels"))
    owners = _sequence_of_mappings(metadata.get("ownerReferences"))
    if kind == "Secret" and name == "mariadb-operator-webhook-cert":
        return bool(
            str(item.get("type", "") or "") == "kubernetes.io/tls"
            and str(annotations.get("cert-manager.io/certificate-name", "") or "")
            == "mariadb-operator-webhook-cert"
            and any(
                str(owner.get("kind", "") or "") == "Certificate"
                and str(owner.get("name", "") or "") == "mariadb-operator-webhook-cert"
                for owner in owners
            )
        )
    legacy_webhook_identity = bool(
        str(annotations.get("meta.helm.sh/release-name", "") or "") == "mariadb-operator"
        and str(annotations.get("meta.helm.sh/release-namespace", "") or "")
        == "mariadb-operator-system"
        and str(labels.get("app.kubernetes.io/instance", "") or "") == "mariadb-operator"
        and str(labels.get("app.kubernetes.io/managed-by", "") or "") == "Helm"
        and str(labels.get("helm.toolkit.fluxcd.io/name", "") or "")
        == "flux-system-soperator-fluxcd-mariadb-operator"
        and str(labels.get("helm.toolkit.fluxcd.io/namespace", "") or "") == "flux-system"
    )
    if not legacy_webhook_identity:
        return False
    if (kind, name) in {
        ("Certificate", "mariadb-operator-webhook-cert"),
        ("Issuer", "mariadb-operator-selfsigned-issuer"),
    }:
        return True
    return bool(
        kind == "CertificateRequest"
        and name.startswith("mariadb-operator-webhook-cert-")
        and str(annotations.get("cert-manager.io/certificate-name", "") or "")
        == "mariadb-operator-webhook-cert"
        and any(
            str(owner.get("kind", "") or "") == "Certificate"
            and str(owner.get("name", "") or "") == "mariadb-operator-webhook-cert"
            and owner.get("controller") is True
            for owner in owners
        )
    )


def _retire_empty_source_auxiliary_namespaces(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
) -> tuple[str, ...]:
    """Delete exact retired Flux namespaces after proving only safe residue remains."""

    deleted: list[str] = []
    for namespace, expected in _SOPERATOR_SOURCE_AUXILIARY_NAMESPACES.items():
        namespace_result = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "get",
                "namespace",
                namespace,
                "-o",
                "json",
                "--request-timeout=20s",
            ],
            timeout_seconds=30,
            check=False,
        )
        if namespace_result.returncode != 0:
            continue
        try:
            namespace_payload = json.loads(namespace_result.stdout or "{}")
        except json.JSONDecodeError:
            continue
        if not isinstance(namespace_payload, Mapping):
            continue
        metadata = _mapping(namespace_payload.get("metadata"))
        annotations = _mapping(metadata.get("annotations"))
        labels = _mapping(metadata.get("labels"))
        if not (
            str(metadata.get("name", "") or "") == namespace
            and str(metadata.get("uid", "") or "").strip()
            and str(annotations.get("meta.helm.sh/release-name", "") or "")
            == expected["release_name"]
            and str(annotations.get("meta.helm.sh/release-namespace", "") or "")
            == expected["release_namespace"]
            and str(labels.get("helm.toolkit.fluxcd.io/name", "") or "") == expected["flux_name"]
            and str(labels.get("helm.toolkit.fluxcd.io/namespace", "") or "")
            == expected["release_namespace"]
        ):
            continue

        helmrelease_payload = _kubectl_json_or_empty(
            command_runner=command_runner,
            command=[
                "kubectl",
                "--context",
                kube_context,
                "get",
                "helmreleases.helm.toolkit.fluxcd.io",
                "-A",
                "-o",
                "json",
            ],
            description="kubectl get HelmRelease for auxiliary namespace retirement",
        )
        if any(
            str(_mapping(item.get("spec")).get("targetNamespace", "") or "") == namespace
            or str(_mapping(item.get("metadata")).get("name", "") or "") == expected["flux_name"]
            for item in _sequence_of_mappings(helmrelease_payload.get("items"))
        ):
            continue

        api_resources = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "api-resources",
                "--verbs=list",
                "--namespaced",
                "-o",
                "name",
            ],
            timeout_seconds=60,
            check=False,
        )
        resource_types = tuple(
            dict.fromkeys(
                line.strip() for line in api_resources.stdout.splitlines() if line.strip()
            )
        )
        if api_resources.returncode != 0 or not resource_types:
            continue
        inventory = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                namespace,
                "get",
                ",".join(resource_types),
                "--ignore-not-found=true",
                "-o",
                "json",
                "--request-timeout=30s",
            ],
            timeout_seconds=120,
            check=False,
        )
        if inventory.returncode != 0:
            continue
        try:
            inventory_payload = json.loads(inventory.stdout or "{}")
        except json.JSONDecodeError:
            continue
        items = _sequence_of_mappings(_mapping(inventory_payload).get("items"))
        if any(not _source_auxiliary_namespace_allowed_residue(item) for item in items):
            continue

        deletion = command_runner(
            [
                "kubectl",
                "--context",
                kube_context,
                "delete",
                "namespace",
                namespace,
                "--wait=true",
                "--timeout=5m",
            ],
            timeout_seconds=360,
            check=False,
        )
        if deletion.returncode != 0:
            raise RuntimeError(
                f"Could not delete retired source auxiliary namespace {namespace}: "
                f"{_command_detail(deletion)}"
            )
        deleted.append(namespace)
    return tuple(deleted)


def _retire_stale_source_soperator_helm_releases(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_version: str,
) -> tuple[str, ...]:
    stale = tuple(
        sorted(
            _deployed_stale_source_soperator_releases(
                command_runner=command_runner,
                kube_context=kube_context,
                target_version=target_version,
            ),
            key=_release_sort_key,
        )
    )
    suspended, suspended_kustomizations = _suspend_source_flux_helmreleases(
        command_runner=command_runner,
        kube_context=kube_context,
        stale_releases=stale,
        target_version=target_version,
    )
    deleted_flux_helmreleases = _delete_source_flux_helmreleases(
        command_runner=command_runner,
        kube_context=kube_context,
        stale_releases=stale,
        target_version=target_version,
    )
    pruned = _prune_safe_source_soperator_resources(
        command_runner=command_runner,
        kube_context=kube_context,
        stale_releases=stale,
    )
    records = _delete_stale_helm_storage_records(
        command_runner=command_runner,
        kube_context=kube_context,
        stale_releases=stale,
    )
    retired_namespaces = _retire_empty_source_auxiliary_namespaces(
        command_runner=command_runner,
        kube_context=kube_context,
    )
    lines: list[str] = []
    if stale:
        retired_names = ", ".join(
            f"{getattr(release, 'namespace', '')}/{getattr(release, 'name', '')}"
            for release in stale
        )
        lines.append("Retired stale source Soperator Helm release records: " + retired_names + ".")
    elif suspended or suspended_kustomizations or deleted_flux_helmreleases:
        lines.append("No stale source Soperator Helm release records remained.")
    if suspended_kustomizations:
        lines.append(
            "Suspended old Flux Kustomization desired state: "
            + ", ".join(suspended_kustomizations)
            + "."
        )
    if suspended:
        lines.append("Suspended old Flux HelmRelease desired state: " + ", ".join(suspended) + ".")
    if deleted_flux_helmreleases:
        lines.append(
            "Deleted old Flux HelmRelease desired state records: "
            + ", ".join(deleted_flux_helmreleases)
            + "."
        )
    if pruned:
        lines.append(f"Pruned {len(pruned)} old source operational resource(s).")
    protected = [
        str(getattr(release, "name", "") or "").strip()
        for release in stale
        if str(getattr(release, "name", "") or "").strip()
        not in _SOPERATOR_SOURCE_SAFE_PRUNE_RELEASE_NAMES
    ]
    if protected:
        lines.append(
            "Preserved shared/storage/custom resources for source release(s): "
            + ", ".join(sorted(dict.fromkeys(protected)))
            + "."
        )
    if records:
        lines.append(f"Deleted {len(records)} stale Helm storage record(s).")
    elif stale:
        lines.append("No stale Helm storage records were found to delete.")
    if retired_namespaces:
        lines.append(
            "Deleted retired source auxiliary namespace(s): " + ", ".join(retired_namespaces) + "."
        )
    return tuple(lines)


def _verify_completed_soperator_migration_helm_state(
    *,
    command_runner: SoperatorMigrationCommandRunner,
    kube_context: str,
    target_version: str,
    require_target_release: bool = True,
) -> tuple[str, ...]:
    retirement_lines = _retire_stale_source_soperator_helm_releases(
        command_runner=command_runner,
        kube_context=kube_context,
        target_version=target_version,
    )
    target_releases = [
        release
        for release in list_helm_releases(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            filter_regex=f"^{re.escape(_SOPERATOR_TARGET_RELEASE_NAME)}$",
        )
        if release.name == _SOPERATOR_TARGET_RELEASE_NAME
    ]
    if require_target_release or target_releases:
        target_readiness = verify_helm_chart_ready(
            command_runner=command_runner,
            kube_context=kube_context,
            release_name=_SOPERATOR_TARGET_RELEASE_NAME,
            namespace=_SOPERATOR_NAMESPACE,
            expected_version=target_version,
        )
        target_line = (
            "Verified target Soperator Helm chart readiness: " + target_readiness.summary()
        )
    else:
        target_line = (
            "Skipped target Soperator Helm chart readiness: no target Soperator Helm release "
            "is installed or expected for this adopted external upgrade segment."
        )
    stale = _deployed_stale_source_soperator_releases(
        command_runner=command_runner,
        kube_context=kube_context,
        target_version=target_version,
    )
    active_source_helmreleases = _active_source_flux_helmreleases(
        command_runner=command_runner,
        kube_context=kube_context,
        target_version=target_version,
    )
    if stale:
        stale_lines = [
            (
                f"- {release.namespace}/{release.name}: chart={release.chart or 'unknown'} "
                f"app={release.app_version or 'unknown'} status={release.status or 'unknown'}"
            )
            for release in stale
        ]
        raise RuntimeError(
            target_line
            + ("\n" + "\n".join(retirement_lines) if retirement_lines else "")
            + "\nStale source Soperator Helm releases remain after upgrade:\n"
            + "\n".join(stale_lines)
            + "\nRetire or remove the remaining old source releases before considering "
            "the upgrade complete."
        )
    if active_source_helmreleases:
        active_lines = []
        for item in active_source_helmreleases:
            metadata = _mapping(item.get("metadata"))
            spec = _mapping(item.get("spec"))
            chart_spec = _mapping(_mapping(spec.get("chart")).get("spec"))
            namespace = str(metadata.get("namespace", "") or "").strip()
            name = str(metadata.get("name", "") or "").strip()
            active_lines.append(
                "- "
                + f"{namespace}/{name}: chart={chart_spec.get('chart') or 'unknown'} "
                + f"version={chart_spec.get('version') or 'unknown'}"
            )
        raise RuntimeError(
            target_line
            + ("\n" + "\n".join(retirement_lines) if retirement_lines else "")
            + "\nActive old source Flux HelmReleases remain after upgrade:\n"
            + "\n".join(active_lines)
            + "\nSuspend or remove the remaining old source desired state before considering "
            "the upgrade complete."
        )
    return (target_line, *retirement_lines)


def _helm_state_lines_include_retirement_mutation(lines: Sequence[str]) -> bool:
    mutating_prefixes = (
        "Retired stale source Soperator Helm release records:",
        "Suspended old Flux Kustomization desired state:",
        "Suspended old Flux HelmRelease desired state:",
        "Deleted old Flux HelmRelease desired state records:",
        "Pruned ",
        "Deleted ",
    )
    return any(str(line).startswith(mutating_prefixes) for line in lines)


def _target_gpu_stack_remediation_satisfied(
    *,
    payload: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> bool:
    rows = _target_gpu_stack_app_rows(payload, target_ref)
    if not rows:
        return False
    for row in rows:
        release_name = str(
            row.get("release-name", "") or row.get("release_name", "") or row.get("id") or ""
        ).strip()
        namespace = str(row.get("namespace", "") or "").strip()
        if not release_name or not namespace:
            return False
        if not _target_gpu_stack_release_matches_row(
            command_runner=command_runner,
            kube_context=kube_context,
            row=row,
        ):
            return False
        app_id = str(row.get("id", "") or "").strip()
        for patch in _target_gpu_stack_post_render_patches(
            payload=payload,
            target_ref=target_ref,
            app_id=app_id,
        ):
            if not _target_gpu_stack_post_render_patch_satisfied(
                command_runner=command_runner,
                kube_context=kube_context,
                patch=patch,
            ):
                return False
    return True


def _external_node_template_upgrade_satisfied(
    *,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    nebius_api: SoperatorMigrationNebiusApi,
) -> bool:
    onboarding = _target_onboarding(payload, target_ref)
    fallback_target = _external_node_template_target(onboarding)
    control_plane_target = _external_control_plane_target(
        onboarding=onboarding,
        fallback=fallback_target,
    )
    cluster_id = _external_migration_cluster_id(
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        nebius_api=nebius_api,
    )
    cluster = _cluster_payload_by_id(nebius_api=nebius_api, cluster_id=cluster_id)
    current_version = _minor_version_text_or_empty(_cluster_control_plane_version(cluster))
    if not current_version:
        return False
    _ensure_external_node_template_k8s_not_downgrade(current_version, control_plane_target)
    return _minor_version_at_least(current_version, control_plane_target)


def _int_or_none(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return int(raw)
    except ValueError:
        return None


def _first_mapping_value(mapping: Mapping[str, Any], *keys: str) -> Any:
    for key in keys:
        if key in mapping:
            return mapping[key]
    return None


def _node_group_readiness_summary(node_group: Mapping[str, Any]) -> tuple[bool, str]:
    status = _mapping(node_group.get("status"))
    name = _node_group_name(node_group) or _node_group_id(node_group) or "unknown"
    if not status:
        return (
            False,
            f"{name}: status not returned by Nebius API; rollout readiness cannot be verified",
        )
    ready = _int_or_none(_first_mapping_value(status, "ready_node_count", "readyNodeCount"))
    target = _int_or_none(_first_mapping_value(status, "target_node_count", "targetNodeCount"))
    node_count = _int_or_none(_first_mapping_value(status, "node_count", "nodeCount"))
    outdated = _int_or_none(
        _first_mapping_value(status, "outdated_node_count", "outdatedNodeCount")
    )
    reconciling = bool(status.get("reconciling", False))
    summary = (
        f"{name}: ready={ready}/{target}, nodes={node_count}, "
        f"outdated={outdated}, reconciling={reconciling}"
    )
    missing = [
        field
        for field, value in (
            ("ready_node_count", ready),
            ("target_node_count", target),
            ("node_count", node_count),
        )
        if value is None
    ]
    if missing:
        return (
            False,
            f"{summary}; status missing {', '.join(missing)}, rollout readiness cannot be verified",
        )
    if ready is not None and target is not None and ready < target:
        return False, summary
    if node_count is not None and target is not None and node_count != target:
        return False, summary
    if outdated is not None and outdated > 0:
        return False, summary
    if reconciling:
        return False, summary
    return True, summary


def _campaign_final_effective_node_groups(
    campaign: Mapping[str, Any],
    checkpoint: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    campaign_mk8s = _mapping(campaign.get("mk8s"))
    planned = list(_sequence_of_mappings(campaign_mk8s.get("node_groups")))
    if not planned:
        segments = _sequence_of_mappings(campaign.get("segments"))
        if segments:
            planned = list(
                _sequence_of_mappings(_mapping(segments[-1].get("mk8s")).get("node_groups"))
            )
    by_id: dict[str, Mapping[str, Any]] = {}
    for group in planned:
        group_id = str(group.get("id", "") or "").strip()
        if group_id:
            by_id[group_id] = group
    transitions = journal_node_group_replacement_transitions(checkpoint)
    projected = project_campaign_node_groups_for_replacements(
        tuple(by_id.values()),
        replacement_bindings=_sequence_of_mappings(transitions.get("bindings")),
        retired_node_group_ids=tuple(str(item) for item in transitions.get("retired_ids", [])),
    )
    return tuple(projected)


def _campaign_final_health_scope(
    campaign: Mapping[str, Any],
    checkpoint: Mapping[str, Any],
) -> dict[str, Any]:
    """Bind final health to the current hop and any completed CR identity handoff."""

    scoped = dict(copy.deepcopy(to_plain_data(dict(campaign))))
    current_segment = _in_place_campaign_segment(campaign, checkpoint)
    segment_mk8s = _mapping(current_segment.get("mk8s"))
    control_plane = _mapping(segment_mk8s.get("control_plane"))
    target_k8s = _minor_version_text_or_empty(control_plane.get("target_version"))
    if not target_k8s:
        raise RuntimeError(
            "final health validation cannot resolve the current campaign segment target"
        )
    scoped["mk8s"] = copy.deepcopy(to_plain_data(dict(segment_mk8s)))
    final_targets = dict(_mapping(scoped.get("final_targets")))
    final_targets["kubernetes"] = target_k8s
    scoped["final_targets"] = final_targets

    transition = soperator_migration_slurmcluster_identity_transition(checkpoint)
    target_identity = _mapping(transition.get("target"))
    if not target_identity:
        rolling = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
        handoff = _mapping(rolling.get("slurmcluster_handoff_binding"))
        handoff_source = _mapping(handoff.get("source"))
        handoff_target = _mapping(handoff.get("target"))
        cleanup_binding = _mapping(rolling.get("source_cleanup_binding"))
        if handoff_target:
            if (
                cleanup_binding != handoff_source
                or not str(rolling.get("source_cleanup_started_at") or "").strip()
                or not str(rolling.get("source_cleanup_completed_at") or "").strip()
            ):
                raise RuntimeError(
                    "final health validation requires the completed source-to-target "
                    "SlurmCluster handoff"
                )
            target_identity = handoff_target
    if target_identity:
        target_uid = str(target_identity.get("uid") or "").strip()
        if not target_uid:
            raise RuntimeError(
                "final health validation found an incomplete target SlurmCluster identity"
            )
        identity = dict(_mapping(scoped.get("identity")))
        identity["slurmcluster_uid"] = target_uid
        scoped["identity"] = identity
    return scoped


def _provider_status_state(status: Mapping[str, Any]) -> str:
    raw_state = _first_mapping_value(status, "state", "State")
    if isinstance(raw_state, Mapping):
        raw_state = _first_mapping_value(raw_state, "name", "value")
    return str(raw_state or "").strip().upper().removeprefix("STATE.")


def _final_health_provider_snapshot(
    *,
    campaign: Mapping[str, Any],
    checkpoint: Mapping[str, Any],
    snapshot: Mapping[str, Any],
    nebius_api: SoperatorMigrationNebiusApi,
) -> tuple[dict[str, Any], tuple[Mapping[str, Any], ...]]:
    result = dict(copy.deepcopy(to_plain_data(dict(snapshot))))
    expected_groups = _campaign_final_effective_node_groups(campaign, checkpoint)
    identity = _mapping(campaign.get("identity"))
    cluster_id = str(
        identity.get("cluster_id", "") or checkpoint.get("cluster_id", "") or ""
    ).strip()
    if not cluster_id:
        raise RuntimeError("final health validation has no immutable MK8s cluster id")
    cluster = _cluster_payload_by_id(nebius_api=nebius_api, cluster_id=cluster_id)
    cluster_status = _mapping(cluster.get("status"))
    status_version = _cluster_control_plane_status_version(cluster)
    provider = result.setdefault("provider", {})
    if not isinstance(provider, dict):
        provider = {}
        result["provider"] = provider
    provider["mk8s_cluster"] = {
        "id": cluster_id,
        "provider_state": _provider_status_state(cluster_status),
        "provider_reconciling": cluster_status.get("reconciling") is True,
        "operation_terminal": bool(
            cluster_status
            and _provider_status_state(cluster_status) == "RUNNING"
            and cluster_status.get("reconciling") is not True
            and status_version
        ),
        "control_plane_version": status_version
        or _minor_version_text_or_empty(_cluster_control_plane_version(cluster)),
    }

    groups = result.setdefault("node_groups", {})
    if not isinstance(groups, dict):
        groups = {}
        result["node_groups"] = groups
    groups_by_id: dict[str, dict[str, Any]] = {}
    for _group_key, group in groups.items():
        if not isinstance(group, dict):
            continue
        group_id = _source_group_node_group_id(group)
        if group_id:
            groups_by_id[group_id] = group
    for expected in expected_groups:
        node_group_id = str(expected.get("id", "") or "").strip()
        node_group = _node_group_payload_by_id(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
        )
        status = _mapping(node_group.get("status"))
        target_count = _int_or_none(
            _first_mapping_value(status, "target_node_count", "targetNodeCount")
        )
        node_count = _int_or_none(_first_mapping_value(status, "node_count", "nodeCount"))
        ready_count = _int_or_none(
            _first_mapping_value(status, "ready_node_count", "readyNodeCount")
        )
        outdated_count = _int_or_none(
            _first_mapping_value(status, "outdated_node_count", "outdatedNodeCount")
        )
        provider_state = _provider_status_state(status)
        if (
            outdated_count is None
            and provider_state == "RUNNING"
            and status.get("reconciling") is not True
            and target_count is not None
            and target_count == node_count == ready_count
        ):
            # The MK8s API omits outdated_node_count when the value is zero.
            outdated_count = 0
        terminal = bool(
            status
            and provider_state == "RUNNING"
            and status.get("reconciling") is not True
            and target_count is not None
            and target_count == node_count == ready_count
            and outdated_count == 0
        )
        group = groups_by_id.get(node_group_id)
        if group is None:
            group = {
                "node_group_id": node_group_id,
                "node_group_name": _node_group_name(node_group),
                "node_count": node_count or 0,
                "labels": {
                    "nebius.com/node-group-id": node_group_id,
                    "nebius.com/node-group": _node_group_name(node_group),
                },
            }
            groups[node_group_id] = group
        group["node_count"] = node_count or 0
        group["provider"] = {
            "node_group_id": node_group_id,
            "node_group_name": _node_group_name(node_group),
            "provider_state": provider_state,
            "provider_reconciling": status.get("reconciling") is True,
            "operation_terminal": terminal,
            "target_node_count": target_count,
            "node_count": node_count,
            "ready_node_count": ready_count,
            "outdated_node_count": outdated_count,
            "node_template": {
                "k8s_version": _node_group_version(node_group),
                "os": _node_group_template_os(node_group),
                "platform": _node_group_platform(node_group),
                "preset": _node_group_preset(node_group),
                "gpu_stack_preset": _node_group_template_gpu_drivers_preset(node_group),
            },
        }
    return result, expected_groups


def _verify_external_soperator_final_health(
    *,
    campaign: Mapping[str, Any],
    checkpoint: Mapping[str, Any],
    snapshot_collector: Callable[..., Mapping[str, Any]],
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
) -> None:
    health_campaign = _campaign_final_health_scope(campaign, checkpoint)
    fresh_snapshot = snapshot_collector(kube_context=kube_context)
    if not isinstance(fresh_snapshot, Mapping):
        raise RuntimeError("fresh discovery did not return a Soperator snapshot")
    enriched, effective_groups = _final_health_provider_snapshot(
        campaign=health_campaign,
        checkpoint=checkpoint,
        snapshot=fresh_snapshot,
        nebius_api=nebius_api,
    )
    conflicts = external_soperator_final_health_conflicts(
        campaign=health_campaign,
        snapshot=enriched,
        effective_node_groups=effective_groups,
    )
    if conflicts:
        raise RuntimeError("fresh final health validation failed: " + ", ".join(conflicts))


def _verify_completed_soperator_migration_mk8s_state(
    *,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    worker_node_groups: Sequence[str],
    phase_ids: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[str]:
    cluster_id = _external_migration_cluster_id(
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        nebius_api=nebius_api,
    )
    cluster = _cluster_payload_by_id(nebius_api=nebius_api, cluster_id=cluster_id)
    current_version = _minor_version_text_or_empty(_cluster_control_plane_version(cluster))
    errors: list[str] = []
    if not current_version:
        errors.append("control plane did not report a Kubernetes version")
    if _EXTERNAL_NODE_TEMPLATE_PHASE_ID in phase_ids:
        return _verify_completed_soperator_migration_node_template_state(
            payload=payload,
            target_ref=target_ref,
            current_version=current_version,
            errors=errors,
        )
    groups = _source_inventory_node_groups_with_ids(source_report)
    if not groups:
        errors.append("no source node-group inventory was available for MK8s verification")
    verified_groups = 0
    for group_name, raw_group in groups:
        node_group_id = _source_group_node_group_id(raw_group)
        node_group = _node_group_payload_by_id(
            nebius_api=nebius_api,
            node_group_id=node_group_id,
        )
        ready, readiness_summary = _node_group_readiness_summary(node_group)
        if not ready:
            errors.append(f"{group_name}: node group rollout is not ready: {readiness_summary}")
            continue
        verified_groups += 1
    if errors:
        raise RuntimeError(
            "External Soperator upgrade MK8s verification failed after execute:\n"
            + "\n".join(f"- {item}" for item in errors)
        )
    return [
        "External MK8s cluster verified: "
        f"control plane Kubernetes {current_version}; "
        f"node groups {verified_groups}/{len(groups)} ready."
    ]


def _verify_completed_soperator_migration_node_template_state(
    *,
    payload: Mapping[str, Any],
    target_ref: str,
    current_version: str,
    errors: list[str],
) -> list[str]:
    onboarding = _target_onboarding(payload, target_ref)
    fallback_target = _external_node_template_target(onboarding)
    control_plane_target = _external_control_plane_target(
        onboarding=onboarding,
        fallback=fallback_target,
    )
    downgrade_error = _external_node_template_k8s_downgrade_error(
        current_version,
        control_plane_target,
    )
    if downgrade_error:
        errors.append(downgrade_error)
    elif not current_version or not _minor_version_at_least(
        current_version,
        control_plane_target,
    ):
        errors.append(
            f"control plane reports Kubernetes {current_version or 'unknown'}, "
            f"expected at least {control_plane_target}"
        )
    if errors:
        raise RuntimeError(
            "External Soperator upgrade MK8s control-plane verification failed after execute:\n"
            + "\n".join(f"- {item}" for item in errors)
        )
    return [
        "External MK8s control plane verified: "
        f"control plane Kubernetes {current_version}; every source service-role and "
        "worker node group is intentionally retained at its source version. Replacement "
        "node-group readiness is verified by rolling-compute-migration."
    ]


def _source_inventory_node_groups_with_ids(
    source_report: Mapping[str, Any],
) -> tuple[tuple[str, Mapping[str, Any]], ...]:
    groups: list[tuple[str, Mapping[str, Any]]] = []
    seen_ids: set[str] = set()
    for raw_group_name, raw_group in sorted(_source_node_group_inventory(source_report).items()):
        group_name = normalize_component_token(raw_group_name)
        if not group_name or not isinstance(raw_group, Mapping):
            continue
        node_group_id = _source_group_node_group_id(raw_group)
        if not node_group_id or node_group_id in seen_ids:
            continue
        seen_ids.add(node_group_id)
        groups.append((group_name, raw_group))
    return tuple(groups)


def _create_aligned_sfs_satisfied(
    *,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    target_ref: str,
    worker_node_groups: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
) -> bool:
    project_id = _nebius_project_id(payload)
    specs = _aligned_filesystem_specs(payload=payload, target_ref=target_ref)
    for spec in specs:
        filesystem = _get_filesystem_by_name(
            nebius_api=nebius_api,
            project_id=project_id,
            name=spec.name,
        )
        filesystem_id = _filesystem_id(filesystem)
        if not filesystem_id:
            return False
        _validate_existing_filesystem(spec, filesystem)
    return True


def _controller_bridge_satisfied(
    *,
    checkpoint: Mapping[str, Any],
    kube_context: str,
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    process_census: bool = True,
) -> bool:
    journal = checkpoint.get("controller_bridge")
    if not isinstance(journal, Mapping):
        return False
    raw_stage = str(journal.get("stage", "") or "")
    if raw_stage == BridgeStage.CLEANED.value:
        try:
            validate_bridge_journal(journal)
            cleanup = _mapping(journal.get("cleanup"))
            target_state = _prove_controller_bridge_cleanup_target_singleton(
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
                require_cluster_wide_census=False,
            )
            _controller_bridge_cleanup_prove_absent(
                journal=journal,
                cleanup=cleanup,
                target_state=target_state,
                kube_context=kube_context,
                nebius_api=nebius_api,
                command_runner=command_runner,
            )
        except (RuntimeError, ValueError, SoperatorMigrationPhasePending) as exc:
            raise SoperatorMigrationPhasePending(
                "cleaned controller bridge terminal proof could not be revalidated; "
                "cxcli will not recreate deleted bridge resources"
            ) from exc
        return True
    try:
        validate_bridge_journal(journal)
        stage = BridgeStage(raw_stage)
    except (ValueError, TypeError):
        return False
    if stage is BridgeStage.BRIDGE_FENCED:
        try:
            authority = _mapping(journal.get("authority"))
            takeover = _mapping(journal.get("target_singleton_takeover"))
            if (
                authority.get("owner") == "bridge-target"
                and takeover.get("recovery_bridge_active") is True
            ):
                _prove_journaled_controller_bridge_exclusivity(
                    journal=journal,
                    proof_label="recovered target-version bridge resume",
                    kube_context=kube_context,
                    command_runner=command_runner,
                )
                return True
            namespace = str(journal.get("namespace", "") or "")
            bridge_exists, bridge_workload = _kubectl_get_namespace_resource(
                command_runner=command_runner,
                kube_context=kube_context,
                namespace=namespace,
                resource="statefulset/cxcli-slurm-controller-bridge",
            )
            bridge_pods = _json_from_command(
                command_runner,
                [
                    "kubectl",
                    "--context",
                    kube_context,
                    "-n",
                    namespace,
                    "get",
                    "pods",
                    "-l",
                    f"{CONTROLLER_BRIDGE_LABEL}=true",
                    "-o",
                    "json",
                ],
                timeout_seconds=120,
            )
            if (
                not bridge_exists
                or _resource_replicas(bridge_workload, default=-1) != 0
                or _sequence_of_mappings(bridge_pods.get("items"))
            ):
                return False
            if authority.get("owner") != "target-singleton":
                return False
            _revalidate_controller_authority_lease(
                journal=journal,
                kube_context=kube_context,
                command_runner=command_runner,
            )
            target_start_state = str(
                _mapping(
                    _mapping(journal.get("target_singleton_takeover")).get("target_start")
                ).get("state", "")
                or ""
            )
            if target_start_state not in {"dispatching", "accepted"}:
                _prove_cluster_wide_slurmctld_absence(
                    proof_label="fenced bridge before target singleton dispatch",
                    campaign_fingerprint=str(journal.get("campaign_fingerprint", "") or ""),
                    journal=journal,
                    kube_context=kube_context,
                    command_runner=command_runner,
                )
        except (RuntimeError, ValueError, SoperatorMigrationPhasePending):
            return False
        return True
    if stage in {
        BridgeStage.TARGET_SINGLETON_ACTIVE,
        BridgeStage.HANDOFF_VALIDATED,
        BridgeStage.PARTITIONS_RESTORED,
        BridgeStage.CLEANED,
    }:
        try:
            _prove_journaled_target_singleton_exclusivity(
                journal=journal,
                proof_label="target singleton resume",
                kube_context=kube_context,
                command_runner=command_runner,
                checkpoint=checkpoint,
            )
        except (RuntimeError, ValueError, SoperatorMigrationPhasePending):
            return False
        return True
    if stage not in {BridgeStage.SOURCE_HA_ACTIVE, BridgeStage.TARGET_HA_ACTIVE}:
        return False
    namespace = str(journal.get("namespace", "") or "")
    exists, statefulset = _kubectl_get_namespace_resource(
        command_runner=command_runner,
        kube_context=kube_context,
        namespace=namespace,
        resource="statefulset/cxcli-slurm-controller-bridge",
    )
    if not exists:
        return False
    statefulset_status = _mapping(statefulset.get("status"))
    if (
        _resource_replicas(statefulset, default=-1) != 2
        or _positive_int(statefulset_status.get("readyReplicas"), fallback=0) != 2
    ):
        return False
    pods_payload = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            namespace,
            "get",
            "pods",
            "-l",
            f"{CONTROLLER_BRIDGE_LABEL}=true",
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    pods = _sequence_of_mappings(pods_payload.get("items"))
    if (
        len(pods) != 2
        or len({str(_mapping(pod.get("spec")).get("nodeName", "") or "") for pod in pods}) != 2
    ):
        return False
    expected_images = {
        str(role.get("image", "") or "")
        for role in _sequence_of_mappings(journal.get("controller_roles"))
    }
    if len(expected_images) != 1:
        return False
    container_name = _controller_bridge_container_name(
        statefulset,
        expected_image=next(iter(expected_images)),
    )
    pod_by_name = {str(_mapping(pod.get("metadata")).get("name", "") or ""): pod for pod in pods}
    try:
        if stage is BridgeStage.SOURCE_HA_ACTIVE:
            _revalidate_source_bridge_takeover(
                journal=journal,
                pod_by_name=pod_by_name,
                source_container=container_name,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        else:
            _revalidate_target_bridge_roles(
                journal=journal,
                pod_by_name=pod_by_name,
                target_container=container_name,
                kube_context=kube_context,
                command_runner=command_runner,
            )
    except (RuntimeError, ValueError, SoperatorMigrationPhasePending):
        return False
    try:
        _prove_journaled_controller_bridge_exclusivity(
            journal=journal,
            proof_label="controller bridge resume",
            kube_context=kube_context,
            command_runner=command_runner,
            process_census=process_census,
        )
    except (RuntimeError, ValueError, SoperatorMigrationPhasePending):
        return False
    return True


def _final_cutover_satisfied(
    *,
    checkpoint: Mapping[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> bool:
    cluster = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "slurmcluster",
            target_ref,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if not _mapping(cluster.get("metadata")):
        return False
    if not _slurmcluster_status_available(_mapping(cluster.get("status"))):
        return False
    expected_values = _patch_target_values_for_compute(
        checkpoint=checkpoint,
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    expected_nodesets = _target_worker_nodesets_by_name(expected_values)
    expected_names = tuple(
        dict.fromkeys((*_expected_cutover_nodesets(checkpoint), *expected_nodesets))
    )
    for name in expected_names:
        nodeset = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "nodeset",
                name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        if not _mapping(nodeset.get("metadata")):
            return False
        if str(_mapping(nodeset.get("status")).get("phase", "") or "").strip() != "Ready":
            return False
    return True


def _checkpointed_populate_jail_verification(
    *,
    checkpoint: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[bool, bool, str, str, str]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get(POPULATE_JAIL_REFRESH_PHASE_ID))
    result = _mapping(phase.get("result"))
    status = str(result.get("status", "") or "").strip()
    if status == "skipped":
        return True, True, "", "", str(result.get("reason") or "not required")
    if status != "refreshed" or result.get("maintenance_restored") is not True:
        return False, False, "", "", "refresh result or maintenance restoration is incomplete"
    passive_job = _mapping(phase.get("passive_slot_populate_job"))
    job_name = str(passive_job.get("name", "") or "").strip()
    result_job_name = str(result.get("job_name", "") or "").strip()
    if not job_name or (result_job_name and result_job_name != job_name):
        return False, False, job_name, "", "checkpointed passive-slot Job identity is inconsistent"
    if not phase.get("job_completed_at"):
        return False, False, job_name, "", "passive-slot Job completion is not checkpointed"
    writer_hold = _mapping(phase.get("persistent_migration_writer_hold"))
    maintenance_resource = next(
        (
            item
            for item in _sequence_of_mappings(writer_hold.get("resources"))
            if str(item.get("kind") or "").strip() == "slurmcluster-maintenance"
        ),
        {},
    )
    if maintenance_resource:
        if str(writer_hold.get("status") or "").strip() != "restored":
            return (
                False,
                True,
                job_name,
                "",
                "checkpointed persistent-migration maintenance hold is not restored",
            )
        resource = str(maintenance_resource.get("resource") or "").strip()
        namespace = str(maintenance_resource.get("namespace") or _SOPERATOR_NAMESPACE).strip()
        expected_uid = str(maintenance_resource.get("uid") or "").strip()
        expected_maintenance = str(maintenance_resource.get("maintenance") or "none").strip()
        if not resource or not expected_uid:
            return (
                False,
                True,
                job_name,
                "",
                "checkpointed persistent-migration SlurmCluster identity is incomplete",
            )
        exists, live_cluster = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=resource,
            namespace=namespace,
        )
        live_uid = str(_mapping(live_cluster.get("metadata")).get("uid") or "").strip()
        live_maintenance = str(
            _mapping(live_cluster.get("spec")).get("maintenance") or "none"
        ).strip()
        if not exists or live_uid != expected_uid or live_maintenance != expected_maintenance:
            return (
                False,
                True,
                job_name,
                "",
                "live SlurmCluster identity or maintenance does not match the restored "
                "persistent-migration checkpoint",
            )
    job = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "job",
            job_name,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    expected_image = str(
        passive_job.get("image") or result.get("job_image") or result.get("target_image") or ""
    ).strip()
    handoff = _mapping(phase.get("rootfs_handoff_verification"))
    handoff_verified = (
        str(handoff.get("status", "") or "").strip() == "verified"
        and _positive_int(handoff.get("verification_revision"), fallback=0)
        >= _ROOTFS_HANDOFF_VERIFICATION_REVISION
    )
    smoke = _mapping(phase.get("post_jail_slurm_smoke"))
    smoke_passed = str(smoke.get("status", "") or "").strip() == "passed"
    if not _mapping(job.get("metadata")):
        if handoff_verified and smoke_passed:
            return (
                False,
                True,
                job_name,
                expected_image,
                "historical passive-slot Job is unavailable; durable handoff and Slurm-smoke "
                "evidence require current live consumer, /home, and Slurm revalidation",
            )
        return False, False, job_name, "", "checkpointed passive-slot Job is unavailable"
    expected_job_uid = str(passive_job.get("uid") or "").strip()
    live_job_uid = str(_mapping(job.get("metadata")).get("uid") or "").strip()
    if not expected_job_uid or live_job_uid != expected_job_uid:
        return (
            False,
            False,
            job_name,
            "",
            "live passive-slot Job UID does not match the checkpointed immutable identity",
        )
    checkpointed_contract = _mapping(passive_job.get("contract"))
    if not checkpointed_contract or _passive_populate_job_contract(job) != checkpointed_contract:
        return (
            False,
            False,
            job_name,
            "",
            "live passive-slot Job no longer matches its checkpointed exact contract",
        )
    checkpointed_pvc = str(passive_job.get("pvc") or "").strip()
    checkpointed_pvc_uid = str(passive_job.get("pvc_uid") or "").strip()
    if not checkpointed_pvc or not checkpointed_pvc_uid:
        return (
            False,
            False,
            job_name,
            "",
            "checkpointed passive-slot PVC immutable identity is incomplete",
        )
    try:
        _bind_passive_populate_pvc_uid(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            state=dict(passive_job),
            pvc=checkpointed_pvc,
            allow_initial_binding=False,
        )
    except SoperatorMigrationPhasePending as exc:
        return False, False, job_name, "", str(exc)
    job_status = _mapping(job.get("status"))
    conditions = _sequence_of_mappings(job_status.get("conditions"))
    failed = _positive_int(job_status.get("failed"), fallback=0) > 0 or any(
        str(item.get("type", "") or "") == "Failed" and str(item.get("status", "") or "") == "True"
        for item in conditions
    )
    complete = _positive_int(job_status.get("succeeded"), fallback=0) > 0 or any(
        str(item.get("type", "") or "") == "Complete"
        and str(item.get("status", "") or "") == "True"
        for item in conditions
    )
    containers = _sequence_of_mappings(
        _mapping(_mapping(_mapping(job.get("spec")).get("template")).get("spec")).get("containers")
    )
    job_image = next(
        (
            str(container.get("image", "") or "").strip()
            for container in containers
            if str(container.get("name", "") or "").strip() == "populate-jail"
            and str(container.get("image", "") or "").strip()
        ),
        "",
    )
    if not job_image and containers:
        job_image = str(containers[0].get("image", "") or "").strip()
    if failed:
        return False, False, job_name, job_image, "checkpointed passive-slot Job failed"
    if not complete:
        return False, False, job_name, job_image, "checkpointed passive-slot Job is incomplete"
    if expected_image and job_image != expected_image:
        return False, True, job_name, job_image, "checkpointed passive-slot Job image changed"
    if not handoff_verified:
        return False, True, job_name, job_image, "login and worker rootfs handoff is not verified"
    if not smoke_passed:
        return False, True, job_name, job_image, "post-Jail Slurm submission smoke is not passed"
    return True, True, job_name, job_image, "passive-slot Job and consumer handoff are verified"


def _completed_populate_jail_verification(
    *,
    checkpoint: Mapping[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[bool, bool, str, str, str]:
    verification = _checkpointed_populate_jail_verification(
        checkpoint=checkpoint,
        kube_context=kube_context,
        command_runner=command_runner,
    )
    satisfied, job_complete, job_name, job_image, detail = verification
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get(POPULATE_JAIL_REFRESH_PHASE_ID))
    result = _mapping(phase.get("result"))
    if str(result.get("status") or "").strip() == "skipped":
        return verification
    historical_job_unavailable = detail.startswith("historical passive-slot Job is unavailable")
    if not job_complete or (not satisfied and not historical_job_unavailable):
        return verification

    handoff = _mapping(phase.get("rootfs_handoff_verification"))
    recorded_active_slot = str(handoff.get("active_slot") or phase.get("active_slot") or "").strip()
    values = _patch_target_values_for_compute(
        checkpoint=checkpoint,
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    if _gpu_worker_nodeset_names(values):
        post_population = _mapping(phase.get("gpu_post_population"))
        post_population_binding = _mapping(post_population.get("binding"))
        post_population_image_lock = _mapping(post_population.get("image_lock"))
        accepted_runner_image_lock = _mapping(
            _mapping(checkpoint.get("controller_bridge")).get("target_image_lock")
        )
        post_population_uids = _mapping(post_population.get("resource_uids"))
        post_population_library_hashes = _mapping(post_population.get("source_library_sha256"))
        post_population_pod = _mapping(post_population.get("pod"))
        pre_activation_fleet = _mapping(phase.get(_GPU_PRE_ACTIVATION_FLEET_GATE_KEY))
        pre_activation_workers = _sequence_of_mappings(pre_activation_fleet.get("workers"))
        pre_activation_nodes = _sequence_of_mappings(
            pre_activation_fleet.get("target_ready_gpu_nodes")
        )
        pre_activation_groups = _sequence_of_mappings(
            pre_activation_fleet.get("owned_gpu_node_groups")
        )
        activation_revalidation = _mapping(pre_activation_fleet.get("activation_revalidation"))
        activation_nodes = _sequence_of_mappings(activation_revalidation.get("nodes"))
        activation_workers = _sequence_of_mappings(activation_revalidation.get("workers"))
        post_jail_release = _mapping(phase.get("post_jail_gpu_workload_release_gate"))
        post_jail_workers = _sequence_of_mappings(post_jail_release.get("workers"))
        activation_groups = _sequence_of_mappings(activation_revalidation.get("node_groups"))
        post_activation = _mapping(phase.get("gpu_post_activation"))
        post_activation_validation = _mapping(post_activation.get("validation"))
        smoke_accounting = _mapping(post_activation.get("pinned_h100_accounting"))
        locked_immutable_image = str(
            post_population_image_lock.get("immutable_reference") or ""
        ).strip()
        locked_repository = str(post_population_image_lock.get("repository") or "").strip()
        locked_index_digest = str(post_population_image_lock.get("index_digest") or "").strip()
        locked_platform_digest = str(
            post_population_image_lock.get("platform_digest") or ""
        ).strip()
        if (
            str(post_population.get("status") or "") != "passed"
            or str(post_population_binding.get("image") or "") != job_image
            or dict(post_population_image_lock) != dict(accepted_runner_image_lock)
            or not locked_repository
            or not str(post_population_image_lock.get("tag") or "").strip()
            or not str(post_population_image_lock.get("media_type") or "").strip()
            or str(post_population_image_lock.get("os") or "") != "linux"
            or str(post_population_image_lock.get("architecture") or "") != "amd64"
            or str(post_population_image_lock.get("variant") or "") != ""
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", locked_index_digest)
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", locked_platform_digest)
            or str(post_population_binding.get("runner_image") or "") != locked_immutable_image
            or str(post_population_binding.get("runner_image_index_digest") or "")
            != locked_index_digest
            or str(post_population_binding.get("runner_image_platform_digest") or "")
            != locked_platform_digest
            or locked_immutable_image != f"{locked_repository}@{locked_platform_digest}"
            or str(post_population_pod.get("configured_image") or "") != locked_immutable_image
            or str(post_population_pod.get("resolved_image_digest") or "") != locked_platform_digest
            or not str(post_population_uids.get("config_map_uid") or "").strip()
            or not str(post_population_uids.get("job_uid") or "").strip()
            or not re.fullmatch(r"[0-9a-f]{64}", str(post_population.get("log_sha256") or ""))
            or set(post_population_library_hashes) != {"libcuda.so.1", "libnvidia-ml.so.1"}
            or any(
                re.fullmatch(r"[0-9a-f]{64}", str(value or "")) is None
                for value in post_population_library_hashes.values()
            )
        ):
            return (
                False,
                job_complete,
                job_name,
                job_image,
                "completed Jail Upgrade lacks exact passed passive-rootfs GPU linker evidence",
            )
        passive_source_contract = (
            str(post_population.get("driver_version") or ""),
            str(post_population_library_hashes.get("libcuda.so.1") or ""),
            str(post_population_library_hashes.get("libnvidia-ml.so.1") or ""),
        )
        pre_activation_node_uids = {
            str(node.get("node_uid") or "").strip() for node in pre_activation_nodes
        }
        fleet_identity_fields = (
            "node_group_id",
            "node_group_name",
            "nodeset",
            "node",
            "node_uid",
        )
        worker_identity_fields = (
            "nodeset",
            "pod",
            "pod_uid",
            "node",
            "node_uid",
            "node_group_id",
            "node_group_name",
            "target_slurmcluster_uid",
            "nodeset_uid",
            "workload_uid",
        )
        pre_activation_identities = {
            tuple(str(node.get(field) or "") for field in fleet_identity_fields)
            for node in pre_activation_nodes
        }
        activation_identities = {
            tuple(str(node.get(field) or "") for field in fleet_identity_fields)
            for node in activation_nodes
        }
        pre_activation_worker_identities = {
            tuple(str(worker.get(field) or "") for field in worker_identity_fields)
            for worker in pre_activation_workers
        }
        activation_worker_identities = {
            tuple(str(worker.get(field) or "") for field in worker_identity_fields)
            for worker in activation_workers
        }
        post_jail_worker_nodes = {
            str(worker.get("node") or "").strip() for worker in post_jail_workers
        }
        post_jail_worker_pods = {
            (
                str(worker.get("nodeset") or "").strip(),
                str(worker.get("pod") or "").strip(),
                str(worker.get("pod_uid") or "").strip(),
            )
            for worker in post_jail_workers
        }
        expected_post_jail_replicas = {
            str(name): _positive_int(count, fallback=0)
            for name, count in _mapping(post_jail_release.get("expected_replicas")).items()
        }
        observed_post_jail_replicas = {
            str(name): _positive_int(count, fallback=0)
            for name, count in _mapping(post_jail_release.get("observed_ready_replicas")).items()
        }
        post_jail_worker_successor = bool(
            str(post_jail_release.get("status") or "") == "passed"
            and _positive_int(post_jail_release.get("revision"), fallback=0)
            == _GPU_WORKLOAD_RELEASE_GATE_REVISION
            and str(post_jail_release.get("scope") or "") == "active-jail"
            and str(_mapping(post_jail_release.get("target_slurmcluster")).get("name") or "")
            == target_ref
            and str(_mapping(post_jail_release.get("target_slurmcluster")).get("uid") or "")
            and post_jail_workers
            and len(post_jail_workers) == sum(expected_post_jail_replicas.values())
            and expected_post_jail_replicas == observed_post_jail_replicas
            and len(post_jail_worker_nodes) == len(pre_activation_nodes)
            and post_jail_worker_nodes
            == {str(node.get("node") or "").strip() for node in pre_activation_nodes}
            and len(post_jail_worker_pods) == len(post_jail_workers)
            and all("" not in identity for identity in post_jail_worker_pods)
            and all(
                _positive_int(
                    _mapping(binding).get("configured_replicas"),
                    fallback=0,
                )
                == expected_post_jail_replicas.get(str(nodeset), 0)
                and str(_mapping(binding).get("target_slurmcluster_uid") or "")
                == str(_mapping(post_jail_release.get("target_slurmcluster")).get("uid") or "")
                and str(_mapping(binding).get("nodeset_uid") or "")
                and str(_mapping(binding).get("workload_uid") or "")
                for nodeset, binding in _mapping(
                    post_jail_release.get("nodeset_workload_bindings")
                ).items()
            )
            and all(
                worker.get("status") == "passed"
                and (
                    str(worker.get("driver_version") or ""),
                    str(_mapping(worker.get("source_library_sha256")).get("libcuda.so.1") or ""),
                    str(
                        _mapping(worker.get("source_library_sha256")).get("libnvidia-ml.so.1") or ""
                    ),
                )
                == passive_source_contract
                and expected_post_jail_replicas.get(str(worker.get("nodeset") or ""), 0) > 0
                and str(worker.get("target_slurmcluster_uid") or "")
                == str(_mapping(post_jail_release.get("target_slurmcluster")).get("uid") or "")
                and str(worker.get("nodeset_uid") or "")
                == str(
                    _mapping(
                        _mapping(post_jail_release.get("nodeset_workload_bindings")).get(
                            str(worker.get("nodeset") or "")
                        )
                    ).get("nodeset_uid")
                    or ""
                )
                and str(worker.get("workload_uid") or "")
                == str(
                    _mapping(
                        _mapping(post_jail_release.get("nodeset_workload_bindings")).get(
                            str(worker.get("nodeset") or "")
                        )
                    ).get("workload_uid")
                    or ""
                )
                for worker in post_jail_workers
            )
        )
        pre_activation_worker_proof = bool(
            pre_activation_workers
            and activation_workers
            and activation_worker_identities == pre_activation_worker_identities
            and len(activation_worker_identities) == len(activation_workers)
        )
        group_identity_fields = ("node_group_id", "node_group_name", "nodeset")
        pre_activation_group_identities = {
            tuple(str(group.get(field) or "") for field in group_identity_fields)
            for group in pre_activation_groups
        }
        activation_fingerprint = _fingerprint(
            [
                {
                    "node_group_id": node.get("node_group_id"),
                    "node_group_name": node.get("node_group_name"),
                    "nodeset": node.get("nodeset"),
                    "node": node.get("node"),
                    "node_uid": node.get("node_uid"),
                    "driver_version": node.get("driver_version"),
                    "source_library_sha256": node.get("source_library_sha256"),
                }
                for node in activation_nodes
            ]
        )
        group_capacity_matches_fleet = all(
            sum(
                1
                for identity in pre_activation_identities
                if identity[:3]
                == tuple(str(group.get(field) or "") for field in group_identity_fields)
            )
            == _positive_int(group.get("fixed_node_count"), fallback=0)
            for group in pre_activation_groups
        )
        if (
            _positive_int(pre_activation_fleet.get("revision"), fallback=0)
            != _GPU_WORKLOAD_RELEASE_GATE_REVISION
            or str(pre_activation_fleet.get("status") or "") != "passed"
            or not pre_activation_groups
            or not pre_activation_nodes
            or not (pre_activation_worker_proof or post_jail_worker_successor)
            or "" in pre_activation_node_uids
            or any("" in identity for identity in pre_activation_group_identities)
            or any("" in identity for identity in pre_activation_identities)
            or any("" in identity for identity in pre_activation_worker_identities)
            or len(pre_activation_group_identities) != len(pre_activation_groups)
            or not group_capacity_matches_fleet
            or len(pre_activation_node_uids) != len(pre_activation_nodes)
            or len(pre_activation_identities) != len(pre_activation_nodes)
            or sorted(pre_activation_node_uids)
            != sorted(
                str(uid or "").strip()
                for uid in pre_activation_fleet.get("target_ready_gpu_node_uids", []) or []
            )
            or any(
                node.get("status") != "passed"
                or (
                    str(node.get("driver_version") or ""),
                    str(_mapping(node.get("source_library_sha256")).get("libcuda.so.1") or ""),
                    str(_mapping(node.get("source_library_sha256")).get("libnvidia-ml.so.1") or ""),
                )
                != passive_source_contract
                for node in pre_activation_nodes
            )
            or str(pre_activation_fleet.get("fleet_identity_sha256") or "")
            != _fingerprint(
                [
                    {
                        "node_group_id": node.get("node_group_id"),
                        "node_group_name": node.get("node_group_name"),
                        "nodeset": node.get("nodeset"),
                        "node": node.get("node"),
                        "node_uid": node.get("node_uid"),
                        "driver_version": node.get("driver_version"),
                        "source_library_sha256": node.get("source_library_sha256"),
                    }
                    for node in pre_activation_nodes
                ]
            )
            or str(activation_revalidation.get("status") or "") != "passed"
            or activation_groups != pre_activation_groups
            or activation_identities != pre_activation_identities
            or len(activation_identities) != len(activation_nodes)
            or (
                pre_activation_worker_proof
                and (
                    activation_worker_identities != pre_activation_worker_identities
                    or len(activation_worker_identities) != len(activation_workers)
                )
            )
            or any(
                node.get("status") != "passed"
                or (
                    str(node.get("driver_version") or ""),
                    str(_mapping(node.get("source_library_sha256")).get("libcuda.so.1") or ""),
                    str(_mapping(node.get("source_library_sha256")).get("libnvidia-ml.so.1") or ""),
                )
                != passive_source_contract
                for node in activation_nodes
            )
            or any(
                worker.get("status") != "passed"
                or (
                    str(worker.get("driver_version") or ""),
                    str(_mapping(worker.get("source_library_sha256")).get("libcuda.so.1") or ""),
                    str(
                        _mapping(worker.get("source_library_sha256")).get("libnvidia-ml.so.1") or ""
                    ),
                )
                != passive_source_contract
                for worker in (*pre_activation_workers, *activation_workers)
            )
            or str(activation_revalidation.get("fleet_identity_sha256") or "")
            != str(pre_activation_fleet.get("fleet_identity_sha256") or "")
            or activation_fingerprint
            != str(activation_revalidation.get("fleet_identity_sha256") or "")
        ):
            return (
                False,
                job_complete,
                job_name,
                job_image,
                "completed Jail Upgrade lacks exact owned GPU node-group membership and "
                "homogeneous source-driver proof for every Ready target Node UID at the "
                "activation boundary",
            )
        if (
            str(post_activation.get("status") or "") != "passed"
            or post_activation_validation.get("passed") is not True
            or str(smoke_accounting.get("status") or "") != "passed"
            or str(smoke_accounting.get("state") or "") != "COMPLETED"
            or str(smoke_accounting.get("exit_code") or "") != "0:0"
            or str(post_activation.get("partition_status") or "") != "deleted"
        ):
            return (
                False,
                job_complete,
                job_name,
                job_image,
                "completed Jail Upgrade lacks passed post-activation H100/epilog/Slurm "
                "evidence or temporary partition cleanup",
            )
    slots = active_passive_jail_rootfs_slots(values)
    if recorded_active_slot and slots.active_slot != recorded_active_slot:
        if slots.passive_slot != recorded_active_slot:
            return (
                False,
                job_complete,
                job_name,
                job_image,
                "checkpointed active rootfs slot cannot be reconstructed from target values",
            )
        values = switch_active_passive_jail_rootfs_values(values)
    live_cluster = _json_from_command(
        command_runner,
        [
            "kubectl",
            "--context",
            kube_context,
            "-n",
            _SOPERATOR_NAMESPACE,
            "get",
            "slurmcluster",
            target_ref,
            "-o",
            "json",
        ],
        timeout_seconds=120,
        check=False,
    )
    if not _mapping(live_cluster.get("metadata")):
        return (
            False,
            job_complete,
            job_name,
            job_image,
            "current target SlurmCluster is unavailable during completed Jail Upgrade revalidation",
        )
    if not _slurmcluster_status_available(_mapping(live_cluster.get("status"))):
        return (
            False,
            job_complete,
            job_name,
            job_image,
            "current target SlurmCluster is not Available during completed Jail Upgrade "
            "revalidation",
        )
    expected_jail_alias_pvc = _pvc_volume_source_claim_name(values, source_name="jail")
    observed_jail_alias_pvc = _pvc_volume_source_claim_name(
        _mapping(live_cluster.get("spec")),
        source_name="jail",
    )
    if not expected_jail_alias_pvc or observed_jail_alias_pvc != expected_jail_alias_pvc:
        return (
            False,
            job_complete,
            job_name,
            job_image,
            "current canonical jail alias does not match the checkpointed active rootfs "
            "slot during completed Jail Upgrade revalidation",
        )
    alias_consumer_checks = _verify_target_jail_alias_consumers(
        command_runner=command_runner,
        kube_context=kube_context,
        slurmcluster=live_cluster,
        rootfs_pvc=expected_jail_alias_pvc,
        wait_for_rollout=False,
    )
    if any(check.get("status") != "verified" for check in alias_consumer_checks):
        return (
            False,
            job_complete,
            job_name,
            job_image,
            _jail_alias_consumer_pending_reason(alias_consumer_checks),
        )
    consumer_checks = _verify_target_rootfs_handoff_consumers(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
    )
    if not consumer_checks or any(check.get("status") != "verified" for check in consumer_checks):
        return (
            False,
            job_complete,
            job_name,
            job_image,
            "historical passive-slot Job is unavailable and current login/worker rootfs "
            "consumers do not verify the checkpointed handoff",
        )
    home_checks = _live_home_mount_probe_checks(
        command_runner=command_runner,
        kube_context=kube_context,
        values=values,
        target_ref=target_ref,
    )
    if _fast_verification_failed(home_checks):
        return (
            False,
            job_complete,
            job_name,
            job_image,
            _live_home_mount_pending_reason(home_checks),
        )
    for name, args in (
        ("scontrol", ("scontrol", "ping")),
        ("sbatch-test-only", ("sbatch", "--test-only", "--wrap=/bin/true")),
    ):
        result = _kubectl_exec_login(
            command_runner=command_runner,
            kube_context=kube_context,
            args=args,
            check=False,
            timeout_seconds=120,
        )
        if result.returncode != 0:
            return (
                False,
                job_complete,
                job_name,
                job_image,
                f"historical passive-slot Job is unavailable and current {name} "
                f"verification failed: {_command_detail(result)}",
            )
    return (
        True,
        job_complete,
        job_name,
        job_image,
        (
            "current canonical jail alias and alias consumers, current rootfs consumers, "
            "verified /home sources, and Slurm admission match durable checkpoint evidence"
        ),
    )


def _populate_jail_refresh_satisfied(
    *,
    checkpoint: Mapping[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> bool:
    satisfied, _job_complete, _job_name, _job_image, _detail = (
        _completed_populate_jail_verification(
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            live_snapshot=live_snapshot,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
        )
    )
    return satisfied


def _record_phase_fast_verification(
    *,
    checkpoint: dict[str, Any],
    phase_id: str,
    status: str,
    summary: str,
    checks: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    payload = build_stage_fast_verification_payload(
        phase_id=phase_id,
        status=status,
        summary=summary,
        checks=checks,
    )
    phase = _phase_state(checkpoint, phase_id)
    phase["fast_verification"] = payload
    event_status = (
        "failed" if status == "failed" else "skipped" if status == "skipped" else "passed"
    )
    _append_event(
        checkpoint,
        "execute-phase-fast-verification-" + event_status,
        phase=phase_id,
        status=status,
        summary=summary,
    )
    return payload


def _phase_validation_summary_line(phase_id: str, verification: Mapping[str, Any]) -> str:
    return (
        f"Phase validation {phase_id}: "
        f"{status_label(str(verification.get('status', '') or 'not_run'))} - "
        f"{verification.get('summary') or 'No summary recorded.'}"
    )


def _fast_verification_check(name: str, status: str, summary: str) -> dict[str, str]:
    return stage_fast_verification_check(name, status, summary)


def _fast_verification_failed(checks: Sequence[Mapping[str, Any]]) -> bool:
    return stage_fast_verification_failed(checks)


def _online_bulk_data_sync_fast_verification_checks(
    *,
    checkpoint: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[str, list[Mapping[str, str]]]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("online-bulk-data-sync"))
    skipped_reason = str(phase.get("skipped_reason", "") or "").strip()
    if skipped_reason:
        return (
            f"data sync skipped as expected: {skipped_reason}.",
            [
                _fast_verification_check(
                    "Data sync planning",
                    "skipped",
                    skipped_reason,
                )
            ],
        )
    jobs = _mapping(phase.get("jobs"))
    if not jobs:
        return (
            "data sync did not record any copy jobs or skip reason.",
            [
                _fast_verification_check(
                    "Data sync jobs",
                    "failed",
                    "no copy jobs or skip reason recorded",
                )
            ],
        )
    checks: list[Mapping[str, str]] = []
    completed = 0
    skipped = 0
    for key, raw_job in sorted(jobs.items()):
        job_state = _mapping(raw_job)
        if bool(job_state.get("skipped")):
            skipped += 1
            checks.append(
                _fast_verification_check(
                    f"Data sync {key}",
                    "skipped",
                    "source and target PVC already match",
                )
            )
            continue
        job_name = _copy_job_name_for_storage_key(str(key))
        exists, job = _kubectl_get_namespace_resource(
            command_runner=command_runner,
            kube_context=kube_context,
            resource=f"job/{job_name}",
        )
        if not exists:
            checks.append(
                _fast_verification_check(
                    f"Data sync {key}",
                    "failed",
                    f"copy Job {job_name} was not found",
                )
            )
            continue
        if _job_condition_true(job, "Failed"):
            checks.append(
                _fast_verification_check(
                    f"Data sync {key}",
                    "failed",
                    f"copy Job {job_name} reports Failed=True",
                )
            )
            continue
        if not _job_condition_true(job, "Complete"):
            checks.append(
                _fast_verification_check(
                    f"Data sync {key}",
                    "failed",
                    f"copy Job {job_name} has not completed",
                )
            )
            continue
        completed += 1
        checks.append(
            _fast_verification_check(
                f"Data sync {key}",
                "passed",
                f"copy Job {job_name} completed",
            )
        )
    if _fast_verification_failed(checks):
        return "one or more data sync jobs are missing, failed, or incomplete.", checks
    return f"data sync jobs verified complete: {completed}; skipped: {skipped}.", checks


def _rolling_compute_fast_verification_checks(
    *,
    checkpoint: Mapping[str, Any],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner,
) -> tuple[str, list[Mapping[str, str]]]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    skipped_reason = str(phase.get("skipped_reason", "") or "").strip()
    if skipped_reason:
        return (
            f"compute migration skipped as expected: {skipped_reason}.",
            [
                _fast_verification_check(
                    "Compute migration planning",
                    "skipped",
                    skipped_reason,
                )
            ],
        )
    if phase.get("mode") == COMPUTE_MIGRATION_MODE_IN_PLACE:
        groups = _mapping(phase.get("in_place_node_groups"))
        incomplete = sorted(
            str(group_id)
            for group_id, state in groups.items()
            if not isinstance(state, Mapping) or state.get("status") != "completed"
        )
        disruption_status = str(
            _mapping(phase.get("jobs_disruption_evidence")).get("status", "") or "unknown"
        )
        slot_b = _mapping(
            _accepted_populate_jail_phase_state(checkpoint).get("rootfs_handoff_verification")
        )
        checks = [
            _fast_verification_check(
                "In-place node-group convergence",
                "passed" if groups and not incomplete else "failed",
                (
                    f"completed={len(groups) - len(incomplete)}/{len(groups)}"
                    + (f"; incomplete={','.join(incomplete)}" if incomplete else "")
                ),
            ),
            _fast_verification_check(
                "Provider rollout job disruption",
                "passed" if disruption_status in {"verified-zero", "not-applicable"} else "failed",
                f"evidence={disruption_status}",
            ),
            _fast_verification_check(
                "Jail rootfs slot B",
                (
                    "passed"
                    if slot_b.get("status") in {"verified", "passed"}
                    and slot_b.get("active_slot") == "slot-b"
                    else "failed"
                ),
                f"status={slot_b.get('status') or 'missing'}; "
                f"active_slot={slot_b.get('active_slot') or 'missing'}",
            ),
        ]
        if _fast_verification_failed(checks):
            return "in-place node groups or slot-B Jail are not converged.", checks
        return f"in-place node groups and slot-B Jail verified: {len(groups)}.", checks
    checks: list[Mapping[str, str]] = []
    accounting_handoff = _mapping(phase.get("accounting_handoff"))
    accounting_required = _source_accounting_handoff_required(
        checkpoint=checkpoint,
        source_report=source_report,
    )
    accounting_status = str(accounting_handoff.get("status", "") or "").strip()
    if accounting_required:
        accounting_detail = f"status={accounting_status or 'not-recorded'}"
        accounting_passed = False
        if accounting_status == "verified":
            try:
                source_binding = _accounting_handoff_source_binding(
                    phase=phase,
                    state=accounting_handoff,
                )
                if (
                    _accounting_handoff_optional_exact_slurmcluster(
                        command_runner=command_runner,
                        kube_context=kube_context,
                        binding=source_binding,
                        label="retired source",
                    )
                    is not None
                ):
                    raise SoperatorMigrationPhasePending(
                        "source SlurmCluster reappeared after accounting handoff"
                    )
                _accounting_handoff_assert_source_pvc_identity(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    expected=_mapping(accounting_handoff.get("source")),
                )
                _accounting_handoff_assert_target_writer_ready(
                    state=accounting_handoff,
                    phase=phase,
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
                target_cluster_name = _accounting_handoff_cluster_name(
                    accounting_handoff.get("target_cluster_name"),
                    label="target",
                )
                source_cluster_name = _accounting_handoff_cluster_name(
                    accounting_handoff.get("source_cluster_name"),
                    label="source",
                )
                target_resource_name = _accounting_handoff_cluster_name(
                    accounting_handoff.get("target_resource_name"),
                    label="target SlurmCluster resource",
                )
                target_binding = _accounting_handoff_target_binding(
                    phase=phase,
                    state=accounting_handoff,
                )
                target_identity = _accounting_handoff_mariadb_pod_identity(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    pod_name=f"{target_resource_name}-acct-db-0",
                    expected_slurmcluster_binding=target_binding,
                )
                expected_identity = _mapping(accounting_handoff.get("target"))
                if any(
                    target_identity.get(key) != expected_identity.get(key)
                    for key in _ACCOUNTING_HANDOFF_DATABASE_IDENTITY_KEYS
                    if key != "pod_uid"
                ):
                    raise SoperatorMigrationPhasePending(
                        "target MariaDB ownership/PVC identity changed after accounting handoff"
                    )
                observed_history = _accounting_handoff_history_evidence(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    pod_name=target_identity["pod"],
                    source_cluster_name=source_cluster_name,
                )
                expected_history = _mapping(accounting_handoff.get("target_history"))
                history_keys = (
                    "jobs",
                    "steps",
                    "completed_jobs",
                    "max_job_id",
                    "max_time_submit",
                )
                if any(key not in expected_history for key in history_keys):
                    raise SoperatorMigrationPhasePending(
                        "checkpointed target accounting history evidence is incomplete"
                    )
                if any(
                    _non_negative_int(observed_history.get(key), fallback=0)
                    < _non_negative_int(expected_history.get(key), fallback=0)
                    for key in history_keys
                ):
                    raise SoperatorMigrationPhasePending(
                        "source history evidence regressed after accounting handoff"
                    )
                registrations = _accounting_handoff_slurm_registration_details(
                    command_runner=command_runner,
                    kube_context=kube_context,
                )
                _accounting_handoff_validate_registration_details(
                    registrations=registrations,
                    source_cluster_name=source_cluster_name,
                    target_cluster_name=target_cluster_name,
                )
                _accounting_handoff_sacct_history_evidence(
                    command_runner=command_runner,
                    kube_context=kube_context,
                    source_cluster_name=source_cluster_name,
                    source_history=expected_history,
                )
            except (RuntimeError, SoperatorMigrationPhasePending) as exc:
                accounting_detail = str(exc)
            else:
                accounting_passed = True
                accounting_detail = (
                    "source retirement and retained PVC, exact target command restore, "
                    "history, registrations, and target-version sacct were reverified"
                )
        checks.append(
            _fast_verification_check(
                "Accounting history handoff",
                "passed" if accounting_passed else "failed",
                accounting_detail,
            )
        )
    else:
        checks.append(
            _fast_verification_check(
                "Accounting history handoff",
                "skipped",
                "source chart-managed accounting was not detected",
            )
        )
    try:
        _kubectl_rollout_status(
            command_runner=command_runner,
            kube_context=kube_context,
            namespace=_SOPERATOR_NAMESPACE,
            resource="deployment/soperator-manager",
            timeout="2m",
        )
    except RuntimeError as exc:
        checks.append(
            _fast_verification_check(
                "Target Soperator manager rollout",
                "failed",
                str(exc).strip() or "rollout status failed",
            )
        )
    else:
        checks.append(
            _fast_verification_check(
                "Target Soperator manager rollout",
                "passed",
                "deployment/soperator-manager is rolled out",
            )
        )
    values = _patch_target_values_for_compute(
        checkpoint=checkpoint,
        payload=payload,
        target_ref=target_ref,
        source_report=source_report,
        live_snapshot=live_snapshot,
    )
    names = _target_worker_nodeset_names(values)
    for name in names:
        nodeset = _json_from_command(
            command_runner,
            [
                "kubectl",
                "--context",
                kube_context,
                "-n",
                _SOPERATOR_NAMESPACE,
                "get",
                "nodeset",
                name,
                "-o",
                "json",
            ],
            timeout_seconds=120,
            check=False,
        )
        if not _mapping(nodeset.get("metadata")):
            checks.append(
                _fast_verification_check(
                    f"Worker NodeSet {name}",
                    "failed",
                    "target worker NodeSet was not found",
                )
            )
            continue
        ready, detail = _worker_nodeset_ready_state(nodeset)
        checks.append(
            _fast_verification_check(
                f"Worker NodeSet {name}",
                "passed" if ready else "failed",
                detail,
            )
        )
    if _fast_verification_failed(checks):
        return "target Soperator manager or worker NodeSets are not ready.", checks
    return f"target Soperator manager and worker NodeSets are ready: {len(names)}.", checks


def _validation_hold_fast_verification_checks(
    *,
    checkpoint: Mapping[str, Any],
) -> tuple[str, list[Mapping[str, str]]]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("validation-and-rollback-hold"))
    revision = _validation_hold_revision(checkpoint)
    checks: list[Mapping[str, str]] = [
        _fast_verification_check(
            "Validation hold contract revision",
            "passed" if revision >= _VALIDATION_HOLD_REVISION else "failed",
            f"recorded={revision}, expected={_VALIDATION_HOLD_REVISION}",
        )
    ]
    safety = _mapping(phase.get("shared_safety_verification"))
    safety_status = str(safety.get("status", "") or "not_run")
    checks.append(
        _fast_verification_check(
            "Shared upgrade safety",
            "passed" if safety.get("passed") is True else "failed",
            f"status={safety_status}",
        )
    )
    soperator_count = _positive_int(phase.get("soperator_cluster_validation_count"), fallback=0)
    soperator_reports = [
        str(path)
        for path in phase.get("soperator_cluster_validation_reports", []) or []
        if str(path).strip()
    ]
    soperator_status = (
        "passed" if soperator_count > 0 and len(soperator_reports) >= soperator_count else "failed"
    )
    if soperator_count == 0:
        soperator_status = "skipped"
    checks.append(
        _fast_verification_check(
            "Soperator deployment snapshot report",
            soperator_status,
            f"reports={len(soperator_reports)}, expected={soperator_count}",
        )
    )
    gpu_count = _positive_int(phase.get("mk8s_gpu_validation_count"), fallback=0)
    gpu_reports = [
        str(path)
        for path in phase.get("mk8s_gpu_validation_reports", []) or []
        if str(path).strip()
    ]
    gpu_status = "passed" if len(gpu_reports) >= gpu_count else "failed"
    if gpu_count == 0:
        gpu_status = "skipped"
    checks.append(
        _fast_verification_check(
            "Configured MK8s GPU validation reports",
            gpu_status,
            f"reports={len(gpu_reports)}, expected={gpu_count}",
        )
    )
    if _fast_verification_failed(checks):
        return "validation hold artifacts are incomplete or failed.", checks
    return "validation hold artifacts and shared safety result are recorded.", checks


def _retire_old_resources_fast_verification_checks(
    *,
    checkpoint: Mapping[str, Any],
) -> tuple[str, list[Mapping[str, str]]]:
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("retire-old-resources"))
    skipped_reason = str(phase.get("skipped_reason", "") or "").strip()
    if skipped_reason:
        return (
            f"old-resource retirement skipped as expected: {skipped_reason}.",
            [
                _fast_verification_check(
                    "Old resource retirement",
                    "skipped",
                    skipped_reason,
                )
            ],
        )
    retired = _sequence_of_mappings(phase.get("retired_node_groups"))
    if retired:
        summary = f"retired replaced node groups: {len(retired)}."
        storage_retirement = str(phase.get("storage_retirement", "") or "").strip()
        if storage_retirement:
            summary += f" storage_retirement={storage_retirement}."
        return (
            summary,
            [
                _fast_verification_check(
                    "Replaced node-group retirement",
                    "passed",
                    summary,
                )
            ],
        )
    return (
        "old-resource retirement recorded neither retired node groups nor an expected skip.",
        [
            _fast_verification_check(
                "Old resource retirement",
                "failed",
                "no retired node groups or skip reason recorded",
            )
        ],
    )


def _run_external_upgrade_phase_fast_verification(
    *,
    checkpoint: dict[str, Any],
    phase_id: str,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    worker_node_groups: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
) -> list[str]:
    try:
        if phase_id == _EXTERNAL_NODE_TEMPLATE_PHASE_ID:
            verification_lines = _verify_completed_soperator_migration_mk8s_state(
                payload=payload,
                source_report=source_report,
                target_ref=target_ref,
                worker_node_groups=worker_node_groups,
                phase_ids=(phase_id,),
                nebius_api=nebius_api,
                command_runner=command_runner,
            )
            summary = (
                verification_lines[0]
                if verification_lines
                else "control-plane-only upgrade verified."
            )
            checks = [
                _fast_verification_check(
                    "External MK8s control plane",
                    "passed",
                    summary,
                )
            ]
        elif phase_id == _TARGET_GPU_STACK_PHASE_ID:
            satisfied = _target_gpu_stack_remediation_satisfied(
                payload=payload,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
            )
            summary = (
                "target GPU stack Helm releases and post-render patches are applied."
                if satisfied
                else "target GPU stack Helm releases or post-render patches are not ready."
            )
            checks = [
                _fast_verification_check(
                    "Target GPU stack",
                    "passed" if satisfied else "failed",
                    summary,
                )
            ]
        elif phase_id == "create-aligned-sfs":
            satisfied = _create_aligned_sfs_satisfied(
                payload=payload,
                source_report=source_report,
                target_ref=target_ref,
                worker_node_groups=worker_node_groups,
                nebius_api=nebius_api,
                command_runner=command_runner,
            )
            summary = (
                "aligned SFS filesystems are present without a source node-group rollout."
                if satisfied
                else "aligned SFS filesystems are incomplete."
            )
            checks = [
                _fast_verification_check(
                    "Aligned SFS",
                    "passed" if satisfied else "failed",
                    summary,
                )
            ]
        elif phase_id == _CONTROLLER_HA_BRIDGE_PHASE_ID:
            satisfied = _controller_bridge_satisfied(
                checkpoint=checkpoint,
                kube_context=kube_context,
                nebius_api=nebius_api,
                command_runner=command_runner,
                process_census=False,
            )
            summary = (
                "temporary controller bridge authority and one-active/one-standby proof "
                "are satisfied."
                if satisfied
                else "temporary controller bridge authority or live HA proof is incomplete."
            )
            checks = [
                _fast_verification_check(
                    "Temporary controller HA bridge",
                    "passed" if satisfied else "failed",
                    summary,
                )
            ]
        elif phase_id == "online-bulk-data-sync":
            summary, checks = _online_bulk_data_sync_fast_verification_checks(
                checkpoint=checkpoint,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        elif phase_id == "rolling-compute-migration":
            summary, checks = _rolling_compute_fast_verification_checks(
                checkpoint=checkpoint,
                payload=payload,
                source_report=source_report,
                live_snapshot=live_snapshot,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        elif phase_id == "final-control-plane-cutover":
            phase = _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id))
            skipped_reason = str(phase.get("skipped_reason", "") or "").strip()
            if skipped_reason:
                summary = f"final cutover skipped as expected: {skipped_reason}."
                checks = [
                    _fast_verification_check(
                        "Final control-plane cutover",
                        "skipped",
                        skipped_reason,
                    )
                ]
            else:
                satisfied = _final_cutover_satisfied(
                    checkpoint=checkpoint,
                    payload=payload,
                    source_report=source_report,
                    live_snapshot=live_snapshot,
                    target_ref=target_ref,
                    kube_context=kube_context,
                    command_runner=command_runner,
                )
                summary = (
                    "target SlurmCluster is Available and expected NodeSets are Ready."
                    if satisfied
                    else "target SlurmCluster is not Available or expected NodeSets are not Ready."
                )
                checks = [
                    _fast_verification_check(
                        "Final control-plane cutover",
                        "passed" if satisfied else "failed",
                        summary,
                    )
                ]
        elif phase_id == POPULATE_JAIL_REFRESH_PHASE_ID:
            phase = _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id))
            result = _mapping(phase.get("result"))
            status = str(result.get("status", "") or "").strip()
            if status == "skipped":
                summary = (
                    f"Jail Upgrade skipped as expected: {result.get('reason') or 'not required'}."
                )
                checks = [
                    _fast_verification_check(
                        "Jail Upgrade",
                        "skipped",
                        str(result.get("reason") or "not required"),
                    )
                ]
            else:
                satisfied, job_complete, job_name, job_image, detail = (
                    _completed_populate_jail_verification(
                        checkpoint=checkpoint,
                        payload=payload,
                        source_report=source_report,
                        live_snapshot=live_snapshot,
                        target_ref=target_ref,
                        kube_context=kube_context,
                        command_runner=command_runner,
                    )
                )
                passive_job = _mapping(phase.get("passive_slot_populate_job"))
                expected_image = str(
                    passive_job.get("image")
                    or result.get("job_image")
                    or result.get("target_image")
                    or ""
                ).strip()
                handoff = _mapping(phase.get("rootfs_handoff_verification"))
                smoke = _mapping(phase.get("post_jail_slurm_smoke"))
                maintenance_restored = result.get("maintenance_restored") is True
                checks = [
                    _fast_verification_check(
                        "Jail Upgrade passive-slot Job",
                        "passed" if job_complete else "failed",
                        f"job={job_name or 'unknown'}; {detail}",
                    ),
                    _fast_verification_check(
                        "Jail Upgrade image",
                        "passed" if not expected_image or job_image == expected_image else "failed",
                        f"expected={expected_image or 'unknown'}, actual={job_image or 'unknown'}",
                    ),
                    _fast_verification_check(
                        "Jail Upgrade rootfs handoff",
                        "passed" if handoff.get("status") == "verified" else "failed",
                        f"status={handoff.get('status') or 'unknown'}",
                    ),
                    _fast_verification_check(
                        "Jail Upgrade Slurm smoke",
                        "passed" if smoke.get("status") == "passed" else "failed",
                        f"status={smoke.get('status') or 'unknown'}",
                    ),
                    _fast_verification_check(
                        "Jail Upgrade maintenance restore",
                        "passed" if maintenance_restored else "failed",
                        "steady-state maintenance values were reapplied"
                        if maintenance_restored
                        else "steady-state maintenance restoration was not recorded",
                    ),
                ]
                summary = (
                    f"Jail Upgrade verified with passive-slot Job {job_name}."
                    if not _fast_verification_failed(checks)
                    else f"Jail Upgrade verification failed: {detail}."
                )
        elif phase_id == "validation-and-rollback-hold":
            summary, checks = _validation_hold_fast_verification_checks(checkpoint=checkpoint)
        elif phase_id == "retire-old-resources":
            summary, checks = _retire_old_resources_fast_verification_checks(checkpoint=checkpoint)
        else:
            summary = "no fast verifier is registered for this stage."
            checks = [
                _fast_verification_check(
                    "Fast stage verifier",
                    "failed",
                    summary,
                )
            ]
    except Exception as exc:
        summary = str(exc).strip() or "fast stage verification failed"
        checks = [
            _fast_verification_check(
                _STATUS_PHASE_LABELS.get(phase_id, phase_id),
                "failed",
                summary,
            )
        ]
    status = stage_fast_verification_status(checks)
    payload = _record_phase_fast_verification(
        checkpoint=checkpoint,
        phase_id=phase_id,
        status=status,
        summary=summary,
        checks=checks,
    )
    if status == "failed":
        raise SoperatorMigrationPhasePending(
            f"fast stage verification failed after {phase_id}: {summary}"
        )
    return [_phase_validation_summary_line(phase_id, payload)]


def _fast_check_result_satisfied(result: tuple[str, list[Mapping[str, str]]]) -> bool:
    _summary, checks = result
    return not _fast_verification_failed(checks)


def _completed_phase_probe_satisfied(probe: Callable[[], Any]) -> bool:
    try:
        probe()
    except Exception:
        return False
    return True


def _persistent_mount_copy_failure_boundary_active(
    checkpoint: Mapping[str, Any],
) -> bool:
    completed_phases = {
        str(phase_id or "").strip()
        for phase_id in checkpoint.get("completed_phases", []) or []
        if str(phase_id or "").strip()
    }
    if POPULATE_JAIL_REFRESH_PHASE_ID in completed_phases:
        return False
    populate = _mapping(_mapping(checkpoint.get("phase_state")).get(POPULATE_JAIL_REFRESH_PHASE_ID))
    writer_hold = _mapping(populate.get("persistent_migration_writer_hold"))
    writer_status = str(writer_hold.get("status") or "").strip()
    migration = _mapping(populate.get("legacy_persistent_mount_migration"))
    migration_status = str(migration.get("status") or "").strip()
    copy_job = _mapping(migration.get("job"))
    recovery = _mapping(migration.get("recovery"))
    recovery_job = _mapping(recovery.get("job"))
    passive_job = _mapping(populate.get("passive_slot_populate_job"))
    boundary_status = str(
        _mapping(populate.get("persistent_migration_failure_boundary")).get("status") or ""
    ).strip()

    def _has_job_intent(job: Mapping[str, Any]) -> bool:
        return any(
            str(job.get(key) or "").strip() for key in ("apply_started_at", "applied_at", "uid")
        )

    passive_job_started = any(
        str(passive_job.get(key) or "").strip()
        for key in ("apply_started_at", "applied_at", "action", "uid")
    )
    downstream_evidence = any(
        (
            str(populate.get("passive_slot_refresh_values_applied_at") or "").strip(),
            str(populate.get("job_completed_at") or "").strip(),
            str(populate.get("consumer_switch_applied_at") or "").strip(),
            bool(_mapping(populate.get("rootfs_handoff_verification"))),
            bool(_mapping(populate.get("post_jail_slurm_smoke"))),
            bool(_mapping(populate.get("result"))),
        )
    )
    return (
        writer_status in {"holding", "held"}
        or migration_status in {"running", "completed", "stale-after-writer-drift"}
        or _has_job_intent(copy_job)
        or str(recovery.get("status") or "").strip() in {"intent-recorded", "running", "completed"}
        or _has_job_intent(recovery_job)
        or passive_job_started
        or downstream_evidence
        or boundary_status
        in {
            "writers_held",
            "copy-active",
            "recovery-active",
            "manual-reconciliation-required",
        }
    )


def _persistent_mount_copy_failure_boundary_started_at(
    checkpoint: Mapping[str, Any],
) -> datetime | None:
    populate = _mapping(_mapping(checkpoint.get("phase_state")).get(POPULATE_JAIL_REFRESH_PHASE_ID))
    writer_hold = _mapping(populate.get("persistent_migration_writer_hold"))
    migration = _mapping(populate.get("legacy_persistent_mount_migration"))
    copy_job = _mapping(migration.get("job"))
    recovery = _mapping(migration.get("recovery"))
    recovery_job = _mapping(recovery.get("job"))
    candidates: list[datetime] = []
    for raw_value in (
        writer_hold.get("holding_at"),
        writer_hold.get("held_at"),
        copy_job.get("apply_started_at"),
        copy_job.get("applied_at"),
        recovery.get("intent_recorded_at"),
        recovery_job.get("apply_started_at"),
        recovery_job.get("applied_at"),
        populate.get("passive_slot_refresh_values_applied_at"),
        populate.get("refresh_attempt_started_at"),
        populate.get("consumer_switch_applied_at"),
    ):
        raw = str(raw_value or "").strip()
        if not raw:
            continue
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except ValueError:
            continue
        candidates.append(parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=UTC))
    return min(candidates) if candidates else None


def _phase_has_durable_completed_fast_verification(
    checkpoint: Mapping[str, Any],
    phase_id: str,
    *,
    require_before_copy_boundary: bool = True,
    require_current_verification_report: bool = True,
) -> bool:
    events = _sequence_of_mappings(checkpoint.get("events"))
    fence_started_at = _persistent_mount_copy_failure_boundary_started_at(checkpoint)

    def _event_at(event: Mapping[str, Any]) -> datetime | None:
        raw = str(event.get("at") or "").strip()
        if not raw:
            return None
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except ValueError:
            return None
        return parsed if parsed.tzinfo is not None else parsed.replace(tzinfo=UTC)

    completed_at = [
        event_at
        for event in events
        if str(event.get("event") or "").strip() == "execute-phase-completed"
        and str(event.get("phase") or "").strip() == phase_id
        and (event_at := _event_at(event)) is not None
        and (
            not require_before_copy_boundary
            or fence_started_at is None
            or event_at <= fence_started_at
        )
    ]
    passed_at = [
        event_at
        for event in events
        if str(event.get("event") or "").strip() == "execute-phase-fast-verification-passed"
        and str(event.get("phase") or "").strip() == phase_id
        and (event_at := _event_at(event)) is not None
        and (
            not require_before_copy_boundary
            or fence_started_at is None
            or event_at <= fence_started_at
        )
    ]
    durable_event_pair = any(
        verification_at <= completion_at
        for verification_at in passed_at
        for completion_at in completed_at
    )
    verification = stage_fast_verification_report(
        phase_id,
        _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id)),
    )
    return durable_event_pair and (
        not require_current_verification_report
        or str(verification.get("status") or "").strip() == "passed"
    )


def _external_upgrade_predecessor_phases(
    phase_ids: Sequence[str],
) -> frozenset[str]:
    try:
        populate_index = tuple(phase_ids).index(POPULATE_JAIL_REFRESH_PHASE_ID)
    except ValueError:
        return frozenset()
    return frozenset(str(phase_id) for phase_id in phase_ids[:populate_index])


def _rolling_compute_predecessor_phases(
    phase_ids: Sequence[str],
) -> frozenset[str]:
    try:
        rolling_index = tuple(phase_ids).index("rolling-compute-migration")
    except ValueError:
        return frozenset()
    return frozenset(str(phase_id) for phase_id in phase_ids[:rolling_index])


def _rolling_compute_provider_boundary_active(checkpoint: Mapping[str, Any]) -> bool:
    completed_phases = {
        str(phase_id or "").strip()
        for phase_id in checkpoint.get("completed_phases", []) or []
        if str(phase_id or "").strip()
    }
    if "rolling-compute-migration" in completed_phases:
        return False
    phase = _mapping(_mapping(checkpoint.get("phase_state")).get("rolling-compute-migration"))
    pending: list[Any] = [phase]
    while pending:
        candidate = pending.pop()
        if isinstance(candidate, Mapping):
            if (
                str(candidate.get("operation_kind") or "").strip()
                and str(candidate.get("requested_at") or "").strip()
                and _provider_operation_id_is_real(candidate.get("provider_operation_id"))
            ):
                return True
            pending.extend(candidate.values())
        elif isinstance(candidate, Sequence) and not isinstance(candidate, (str, bytes)):
            pending.extend(candidate)
    return False


def _controller_singleton_handoff_boundary_active(checkpoint: Mapping[str, Any]) -> bool:
    journal = _mapping(checkpoint.get("controller_bridge"))
    stage = str(journal.get("stage") or "").strip()
    if stage in {
        BridgeStage.SOURCE_FENCED.value,
        BridgeStage.STATE_PROMOTED.value,
        BridgeStage.BRIDGE_FENCED.value,
        BridgeStage.TARGET_SINGLETON_ACTIVE.value,
        BridgeStage.HANDOFF_VALIDATED.value,
        BridgeStage.PARTITIONS_RESTORED.value,
    }:
        return True
    transition = _mapping(journal.get("version_transition"))
    if (
        stage == BridgeStage.SOURCE_HA_ACTIVE.value
        and str(transition.get("cold_stop_dispatching_at", "") or "").strip()
        and _mapping(transition.get("target_writer_scale")).get("state") != "accepted"
    ):
        return True
    completed_phases = {
        str(phase_id or "").strip()
        for phase_id in checkpoint.get("completed_phases", []) or []
        if str(phase_id or "").strip()
    }
    if stage == BridgeStage.SOURCE_HA_ACTIVE.value and {
        "rolling-compute-migration",
        "final-control-plane-cutover",
    }.issubset(completed_phases):
        return True
    if "retire-old-resources" in completed_phases:
        return False
    if stage != BridgeStage.TARGET_HA_ACTIVE.value:
        return False
    takeover = _mapping(journal.get("target_singleton_takeover"))
    authentication_handoff = _mapping(takeover.get("bridge_authentication_handoff"))
    bridge_configuration_handoff = _mapping(takeover.get("bridge_handoff_configuration"))
    return bool(
        (
            str(takeover.get("client_handoff_config_applied_at") or "").strip()
            and re.fullmatch(
                r"[0-9a-f]{64}",
                str(takeover.get("client_handoff_config_sha256") or "").strip(),
            )
        )
        or (
            authentication_handoff.get("schema")
            == "nebius-cxcli/target-bridge-authentication-handoff-v1"
            and str(authentication_handoff.get("intent_at") or "").strip()
        )
        or (
            bridge_configuration_handoff.get("schema")
            == "nebius-cxcli/target-bridge-handoff-configuration-v1"
            and str(bridge_configuration_handoff.get("intent_at") or "").strip()
        )
    )


def _retirement_predecessor_phases(phase_ids: Sequence[str]) -> frozenset[str]:
    try:
        retirement_index = tuple(phase_ids).index("retire-old-resources")
    except ValueError:
        return frozenset()
    return frozenset(str(phase_id) for phase_id in phase_ids[:retirement_index])


def _restore_historically_completed_copy_boundary_phases(
    *,
    checkpoint: dict[str, Any],
    completed_phases: set[str],
    phase_ids: Sequence[str],
    allow_transient_verification_drift: bool = False,
) -> list[str]:
    lines: list[str] = []
    copy_predecessors = _external_upgrade_predecessor_phases(phase_ids)
    restorable = [
        phase_id
        for phase_id in phase_ids
        if phase_id in copy_predecessors or phase_id == POPULATE_JAIL_REFRESH_PHASE_ID
    ]
    for phase_id in restorable:
        if phase_id in completed_phases:
            continue
        if not _phase_has_durable_completed_fast_verification(
            checkpoint,
            phase_id,
            require_before_copy_boundary=(phase_id != POPULATE_JAIL_REFRESH_PHASE_ID),
            require_current_verification_report=(not allow_transient_verification_drift),
        ):
            continue
        completed_phases.add(phase_id)
        _append_event(
            checkpoint,
            "execute-phase-completion-restored",
            phase=phase_id,
            reason=("active downstream mutation boundary preserved durable completion"),
        )
        lines.append(
            f"{phase_id}: restored completed phase from durable completion and passed "
            "fast-verification evidence while a downstream mutation boundary remains active."
        )
    return lines


def _reconcile_completed_action_phases(
    *,
    checkpoint: dict[str, Any],
    completed_phases: set[str],
    phase_ids: Sequence[str],
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    live_snapshot: Mapping[str, Any],
    target_ref: str,
    kube_context: str,
    worker_node_groups: Sequence[str],
    nebius_api: SoperatorMigrationNebiusApi,
    command_runner: SoperatorMigrationCommandRunner,
    protected_predecessors: Collection[str] = (),
) -> list[str]:
    checks: Mapping[str, Callable[[], bool]] = {
        _EXTERNAL_NODE_TEMPLATE_PHASE_ID: lambda: _external_node_template_upgrade_satisfied(
            payload=payload,
            source_report=source_report,
            target_ref=target_ref,
            nebius_api=nebius_api,
        ),
        _TARGET_GPU_STACK_PHASE_ID: lambda: _target_gpu_stack_remediation_satisfied(
            payload=payload,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
        ),
        "create-aligned-sfs": lambda: _create_aligned_sfs_satisfied(
            payload=payload,
            source_report=source_report,
            target_ref=target_ref,
            worker_node_groups=worker_node_groups,
            nebius_api=nebius_api,
            command_runner=command_runner,
        ),
        _CONTROLLER_HA_BRIDGE_PHASE_ID: lambda: _controller_bridge_satisfied(
            checkpoint=checkpoint,
            kube_context=kube_context,
            nebius_api=nebius_api,
            command_runner=command_runner,
        ),
        "final-control-plane-cutover": lambda: _final_cutover_satisfied(
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            live_snapshot=live_snapshot,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
        ),
        "online-bulk-data-sync": lambda: _fast_check_result_satisfied(
            _online_bulk_data_sync_fast_verification_checks(
                checkpoint=checkpoint,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        ),
        "rolling-compute-migration": lambda: _fast_check_result_satisfied(
            _rolling_compute_fast_verification_checks(
                checkpoint=checkpoint,
                payload=payload,
                source_report=source_report,
                live_snapshot=live_snapshot,
                target_ref=target_ref,
                kube_context=kube_context,
                command_runner=command_runner,
            )
        ),
        POPULATE_JAIL_REFRESH_PHASE_ID: lambda: _populate_jail_refresh_satisfied(
            checkpoint=checkpoint,
            payload=payload,
            source_report=source_report,
            live_snapshot=live_snapshot,
            target_ref=target_ref,
            kube_context=kube_context,
            command_runner=command_runner,
        ),
        "validation-and-rollback-hold": lambda: _fast_check_result_satisfied(
            _validation_hold_fast_verification_checks(checkpoint=checkpoint)
        ),
        "retire-old-resources": lambda: _fast_check_result_satisfied(
            _retire_old_resources_fast_verification_checks(checkpoint=checkpoint)
        ),
    }
    lines: list[str] = []
    demoted_action = False
    current_segment_id = str(checkpoint.get("current_segment_id", "") or "").strip()
    immutable_completed_segment = bool(
        current_segment_id
        and current_segment_id
        in {
            str(segment_id or "").strip()
            for segment_id in checkpoint.get("completed_segment_ids", []) or []
        }
    )
    protected_predecessor_ids = frozenset(protected_predecessors)
    for phase_id in phase_ids:
        if phase_id not in completed_phases:
            continue
        if phase_id in protected_predecessor_ids:
            if phase_id == _CONTROLLER_HA_BRIDGE_PHASE_ID:
                bridge_journal = checkpoint.get("controller_bridge")
                if not isinstance(bridge_journal, dict):
                    raise RuntimeError(
                        "recovery-required: protected controller bridge completion lacks "
                        "its mutable security journal."
                    )
                cleanup = _mapping(bridge_journal.get("cleanup"))
                if _controller_bridge_kubernetes_cleanup_complete(cleanup):
                    _controller_bridge_cleanup_prove_kubernetes_absent(
                        journal=bridge_journal,
                        cleanup=cleanup,
                        kube_context=kube_context,
                        command_runner=command_runner,
                    )
                else:
                    _revalidate_controller_bridge_security_contract(
                        journal=bridge_journal,
                        kube_context=kube_context,
                        command_runner=command_runner,
                    )
            lines.append(
                f"{phase_id}: preserved completed action while the checkpointed "
                "persistent-copy writer boundary remains active."
            )
            continue
        check = checks.get(phase_id)
        if check is None:
            continue
        if check():
            lines.append(f"{phase_id}: live state already satisfies completed action.")
            continue
        if immutable_completed_segment:
            raise RuntimeError(
                "recovery-required: completed external upgrade segment "
                f"'{current_segment_id}' is immutable, but live state drifted at phase "
                f"'{phase_id}'. Rerun `nebius-cxcli ext-soperator onboard` to lock a new "
                "campaign; the completed v6 journal was not rewritten."
            )
        completed_phases.discard(phase_id)
        if (
            phase_id == "final-control-plane-cutover"
            and "rolling-compute-migration" in completed_phases
        ):
            completed_phases.discard("rolling-compute-migration")
            rolling = _phase_state(checkpoint, "rolling-compute-migration")
            rolling["target_values_revision"] = 0
            _append_event(
                checkpoint,
                "execute-phase-reconcile-required",
                phase="rolling-compute-migration",
                reason="final-control-plane-cutover no longer satisfies live state",
            )
            lines.append(
                "rolling-compute-migration: target Soperator values will be reapplied "
                "because final-control-plane-cutover drifted."
            )
        demoted_action = True
        _append_event(
            checkpoint,
            "execute-phase-reconcile-required",
            phase=phase_id,
            reason="completed checkpoint no longer satisfies live state",
        )
        lines.append(f"{phase_id}: live state no longer satisfies completed action; retrying.")
    if demoted_action and "validation-and-rollback-hold" in completed_phases:
        completed_phases.discard("validation-and-rollback-hold")
        _append_event(
            checkpoint,
            "execute-phase-reconcile-required",
            phase="validation-and-rollback-hold",
            reason="completed action was retried",
        )
        lines.append(
            "validation-and-rollback-hold: completed action changed; validation will rerun."
        )
    return lines


def reconcile_completed_soperator_migration_final_worker_runtime_identity(
    *,
    checkpoint_path: Path,
    target_ref: str,
    campaign_fingerprint: str,
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner | None = None,
    mutation_guard: Callable[[], None] | None = None,
) -> dict[str, Any]:
    """Repair a completed campaign's exact Slurm worker bindings before discovery.

    Provider node replacement can leave Slurm's ``InstanceId`` and ``NodeAddr``
    records stale after every campaign phase has already been journaled complete.
    Completed-campaign discovery treats the resulting SlurmCluster condition as a
    health failure, so this deliberately narrow repair has to run before that
    discovery.  The immutable campaign, target, completed journal, and cleaned
    controller-bridge boundary remain mandatory.
    """

    normalized_target = normalize_component_token(target_ref)
    if not normalized_target:
        raise RuntimeError("Completed external Soperator recovery requires a target ref.")
    checkpoint = _load_checkpoint(checkpoint_path)
    if checkpoint is None:
        raise RuntimeError(
            "recovery-required: completed external Soperator worker recovery requires "
            f"the exact operation journal at {checkpoint_path}."
        )
    if str(checkpoint.get("target_ref", "") or "") != normalized_target:
        raise RuntimeError(
            "recovery-required: completed external Soperator worker recovery target "
            "differs from the operation journal."
        )
    if str(checkpoint.get("campaign_fingerprint", "") or "") != campaign_fingerprint:
        raise RuntimeError(
            "recovery-required: completed external Soperator worker recovery campaign "
            "differs from the operation journal."
        )
    if not _checkpoint_run_complete(checkpoint):
        raise RuntimeError(
            "recovery-required: pre-discovery Slurm worker recovery is permitted only "
            "for an exactly completed external Soperator operation journal."
        )
    bridge = _mapping(checkpoint.get("controller_bridge"))
    if str(bridge.get("stage", "") or "") != "cleaned":
        raise RuntimeError(
            "recovery-required: completed external Soperator worker recovery requires "
            "the checkpointed controller bridge to be cleaned."
        )
    operation_intent = _mapping(checkpoint.get("operation_intent"))
    if str(operation_intent.get("attempt_state", "") or "") != "verified":
        raise RuntimeError(
            "recovery-required: completed external Soperator worker recovery requires "
            "a verified terminal operation intent."
        )
    if mutation_guard is not None:
        mutation_guard()
    proof = _ensure_final_slurm_worker_runtime_identity(
        command_runner=command_runner or _default_command_runner,
        kube_context=kube_context,
        target_ref=normalized_target,
    )
    final_health = checkpoint.setdefault("final_health", {})
    if not isinstance(final_health, dict):
        raise RuntimeError("External Soperator final_health journal must be a mapping.")
    final_health["worker_runtime_identity"] = copy.deepcopy(proof)
    final_health["worker_runtime_identity_rechecked_at"] = _utc_now()
    _append_event(
        checkpoint,
        "completed-campaign-worker-runtime-identity-verified",
        mutation_performed=proof.get("reconciled") is True,
    )
    _write_checkpoint(checkpoint_path, checkpoint)
    return proof


def reconcile_completed_soperator_migration_final_helm_state(
    *,
    config_path: Path,
    checkpoint_path: Path,
    target_ref: str,
    campaign_fingerprint: str,
    campaign: Mapping[str, Any],
    kube_context: str,
    command_runner: SoperatorMigrationCommandRunner | None = None,
    mutation_guard: Callable[[], None] | None = None,
) -> tuple[str, ...]:
    """Retire proven source Helm state and refresh a completed campaign report."""

    normalized_target = normalize_component_token(target_ref)
    if not normalized_target:
        raise RuntimeError("Completed external Soperator Helm recovery requires a target ref.")
    checkpoint = _load_checkpoint(checkpoint_path)
    if checkpoint is None:
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery requires "
            f"the exact operation journal at {checkpoint_path}."
        )
    if str(checkpoint.get("target_ref", "") or "") != normalized_target:
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery target "
            "differs from the operation journal."
        )
    if str(checkpoint.get("campaign_fingerprint", "") or "") != campaign_fingerprint:
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery campaign "
            "differs from the operation journal."
        )
    if not _checkpoint_run_complete(checkpoint):
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery is permitted "
            "only for an exactly completed operation journal."
        )
    bridge = _mapping(checkpoint.get("controller_bridge"))
    if str(bridge.get("stage", "") or "") != "cleaned":
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery requires "
            "the checkpointed controller bridge to be cleaned."
        )
    operation_intent = _mapping(checkpoint.get("operation_intent"))
    if str(operation_intent.get("attempt_state", "") or "") != "verified":
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery requires "
            "a verified terminal operation intent."
        )
    target_version = str(checkpoint.get("target_version", "") or "").strip()
    if not target_version:
        raise RuntimeError(
            "recovery-required: completed external Soperator Helm recovery requires "
            "the checkpointed target chart version."
        )
    if mutation_guard is not None:
        mutation_guard()
    lines = _verify_completed_soperator_migration_helm_state(
        command_runner=command_runner or _default_command_runner,
        kube_context=kube_context,
        target_version=target_version,
    )
    mutation_performed = _helm_state_lines_include_retirement_mutation(lines)
    summary = lines[0] if lines else "Final Helm releases and target Soperator readiness verified."
    _record_phase_fast_verification(
        checkpoint=checkpoint,
        phase_id="post-upgrade-helm-check",
        status="passed",
        summary=summary,
        checks=[
            _fast_verification_check(
                "Post-upgrade Helm state",
                "passed",
                summary,
            )
        ],
    )
    _append_event(
        checkpoint,
        "completed-campaign-helm-state-verified",
        mutation_performed=mutation_performed,
    )
    report_path = _migrate_report_path(
        config_path,
        target_ref=normalized_target,
        checkpoint=checkpoint,
    )
    json_report_path = _upgrade_report_json_path(
        config_path,
        target_ref=normalized_target,
        checkpoint=checkpoint,
    )
    checkpoint["upgrade_report"] = str(report_path)
    checkpoint["upgrade_report_json"] = str(json_report_path)
    _write_checkpoint(checkpoint_path, checkpoint)
    completed_phases = {
        str(phase or "").strip()
        for phase in checkpoint.get("completed_phases", []) or []
        if str(phase or "").strip()
    }
    _write_soperator_migrate_report(
        config_path=config_path,
        checkpoint_path=checkpoint_path,
        checkpoint=checkpoint,
        phase_ids=tuple(
            str(phase or "").strip()
            for phase in checkpoint.get("planned_phases", []) or []
            if str(phase or "").strip()
        ),
        completed_phases=completed_phases,
        target_ref=normalized_target,
        source_version=str(checkpoint.get("source_version", "") or ""),
        target_version=target_version,
        pending_phase="none",
        pending_reason="",
        mutation_performed=_checkpoint_upgrade_mutation_performed(checkpoint),
        campaign=campaign,
    )
    return lines


def execute_soperator_migration(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    backup_metadata: Mapping[str, Any] | None = None,
    snapshot_collector: Callable[..., Mapping[str, Any]],
    source_identity_collector: Callable[..., Mapping[str, Any]] | None = None,
    approved: bool = False,
    approve_remediation: bool = False,
    nebius_api: SoperatorMigrationNebiusApi | None = None,
    command_runner: SoperatorMigrationCommandRunner | None = None,
    status_callback: Callable[[str], None] | None = None,
    mutation_guard: Callable[[], None] | None = None,
    status_poll_interval_seconds: float = 30.0,
    job_policy: str | None = None,
    populate_jail_refresh: str = "auto",
    jail_persistent_mounts: Sequence[str] = (),
    cancel_job_ids: Sequence[str] = (),
    requeue_job_ids: Sequence[str] = (),
    job_wait_timeout_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_WAIT_TIMEOUT_SECONDS,
    job_refresh_interval_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_REFRESH_INTERVAL_SECONDS,
    slurm_scheduling_pause: bool = True,
    login_session_policy: str = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
    login_session_drain_timeout_seconds: int = 0,
    jail_sfs_resize_handler: JailSfsResizeHandler | None = None,
    stop_after_phase_id: str | None = None,
    campaign_fingerprint: str,
    campaign_segment_id: str,
    campaign: Mapping[str, Any],
    command_started_at: str | None = None,
    command_started_monotonic: float | None = None,
) -> SoperatorMigrationExecutionResult:
    """Run checkpointed live external Soperator upgrade phases."""

    normalized_target = normalize_component_token(target_ref)
    if not normalized_target:
        raise RuntimeError("External Soperator upgrade execute requires a target ref.")
    config_was_present = config_path.exists()
    _validate_config_owned_campaign_for_execution(
        campaign,
        payload=payload,
        target_ref=normalized_target,
        campaign_fingerprint=campaign_fingerprint,
        campaign_segment_id=campaign_segment_id,
    )
    legacy_checkpoint_path = legacy_soperator_migration_checkpoint_path(
        config_path,
        normalized_target,
    )
    if legacy_checkpoint_path.exists():
        raise RuntimeError(
            "Retired external Soperator checkpoint found: "
            f"{legacy_checkpoint_path}. Remove the old checkpoint after reviewing it; "
            "`nebius-cxcli ext-soperator upgrade` does not resume retired checkpoints."
        )
    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        normalized_target,
        payload_or_config=payload,
        cluster_id=str(source_report.get("cluster_id", "") or ""),
        cluster_name=str(source_report.get("cluster_name", "") or ""),
        kube_context=str(source_report.get("kube_context", "") or ""),
        campaign_id=str(campaign.get("campaign_id", "") or ""),
    )
    retired_cluster_checkpoint = _soperator_migration_cluster_command_checkpoint_path(
        config_path,
        normalized_target,
        payload_or_config=payload,
        cluster_id=str(source_report.get("cluster_id", "") or ""),
        cluster_name=str(source_report.get("cluster_name", "") or ""),
        kube_context=str(source_report.get("kube_context", "") or ""),
    )
    if retired_cluster_checkpoint.exists():
        raise RuntimeError(_unsupported_checkpoint_schema_message(retired_cluster_checkpoint))
    old_checkpoint_path = old_soperator_migration_checkpoint_path(config_path, normalized_target)
    if old_checkpoint_path != checkpoint_path and old_checkpoint_path.exists():
        raise RuntimeError(
            "Old target-scoped external Soperator checkpoint found: "
            f"{old_checkpoint_path}. This cxcli version writes cluster-scoped checkpoints "
            f"under {checkpoint_path.parent}. Review or remove the old checkpoint before "
            "rerunning ext-soperator upgrade; it is not resumed automatically."
        )
    with SoperatorMigrationExecutionLock(
        soperator_migration_lock_path(
            config_path,
            normalized_target,
            payload_or_config=payload,
        )
    ):
        _revalidate_config_campaign_under_shared_lease(
            config_path=config_path,
            config_was_present=config_was_present,
            target_ref=normalized_target,
            campaign=campaign,
            campaign_fingerprint=campaign_fingerprint,
            campaign_segment_id=campaign_segment_id,
        )
        active_command_runner = command_runner or _default_command_runner
        attached_nebius_api = getattr(active_command_runner, "nebius_api", None)
        owned_nebius_api: SoperatorMigrationNebiusApi | None = None
        active_nebius_api = nebius_api or attached_nebius_api
        if active_nebius_api is None:
            owned_nebius_api = _SdkSoperatorMigrationNebiusApi(
                project_id=_nebius_project_id(payload)
            )
            active_nebius_api = owned_nebius_api
        try:
            return _execute_soperator_migration_unlocked(
                config_path=config_path,
                target_ref=normalized_target,
                payload=payload,
                source_report=source_report,
                backup_metadata=backup_metadata,
                snapshot_collector=snapshot_collector,
                source_identity_collector=source_identity_collector,
                approved=approved,
                approve_remediation=approve_remediation,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                status_callback=status_callback,
                mutation_guard=mutation_guard,
                status_poll_interval_seconds=status_poll_interval_seconds,
                job_policy=job_policy,
                populate_jail_refresh=populate_jail_refresh,
                jail_persistent_mounts=jail_persistent_mounts,
                cancel_job_ids=cancel_job_ids,
                requeue_job_ids=requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                slurm_scheduling_pause=slurm_scheduling_pause,
                login_session_policy=login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                jail_sfs_resize_handler=jail_sfs_resize_handler,
                stop_after_phase_id=stop_after_phase_id,
                campaign_fingerprint=campaign_fingerprint,
                campaign_segment_id=campaign_segment_id,
                campaign=campaign,
                command_started_at=command_started_at,
                command_started_monotonic=command_started_monotonic,
            )
        finally:
            if owned_nebius_api is not None:
                owned_nebius_api.close()


def _soperator_migration_command_requires_live_lease_fence(args: Sequence[str]) -> bool:
    """Fence mutations, but do not turn every kubectl read into a Lease write."""

    command = tuple(str(item or "").strip() for item in args)
    if not command or Path(command[0]).name != "kubectl":
        return True
    index = 1
    global_flags_with_values = {
        "--context",
        "--kubeconfig",
        "--namespace",
        "-n",
        "--cluster",
        "--user",
        "--request-timeout",
    }
    while index < len(command):
        token = command[index]
        if token in global_flags_with_values:
            index += 2
            continue
        if token.startswith("--") and "=" in token:
            index += 1
            continue
        if token.startswith("-"):
            index += 1
            continue
        return token != "get"
    return True


def _execute_soperator_migration_unlocked(
    *,
    config_path: Path,
    target_ref: str,
    payload: Mapping[str, Any],
    source_report: Mapping[str, Any],
    backup_metadata: Mapping[str, Any] | None = None,
    snapshot_collector: Callable[..., Mapping[str, Any]],
    source_identity_collector: Callable[..., Mapping[str, Any]] | None = None,
    approved: bool = False,
    approve_remediation: bool = False,
    nebius_api: SoperatorMigrationNebiusApi | None = None,
    command_runner: SoperatorMigrationCommandRunner | None = None,
    status_callback: Callable[[str], None] | None = None,
    mutation_guard: Callable[[], None] | None = None,
    status_poll_interval_seconds: float = 30.0,
    job_policy: str | None = None,
    populate_jail_refresh: str = "auto",
    jail_persistent_mounts: Sequence[str] = (),
    cancel_job_ids: Sequence[str] = (),
    requeue_job_ids: Sequence[str] = (),
    job_wait_timeout_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_WAIT_TIMEOUT_SECONDS,
    job_refresh_interval_seconds: int = _EXTERNAL_UPGRADE_DEFAULT_JOB_REFRESH_INTERVAL_SECONDS,
    slurm_scheduling_pause: bool = True,
    login_session_policy: str = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE,
    login_session_drain_timeout_seconds: int = 0,
    jail_sfs_resize_handler: JailSfsResizeHandler | None = None,
    stop_after_phase_id: str | None = None,
    campaign_fingerprint: str,
    campaign_segment_id: str,
    campaign: Mapping[str, Any],
    command_started_at: str | None = None,
    command_started_monotonic: float | None = None,
) -> SoperatorMigrationExecutionResult:
    normalized_target = normalize_component_token(target_ref)
    if not normalized_target:
        raise RuntimeError("External Soperator upgrade execute requires a target ref.")
    _validate_config_owned_campaign_for_execution(
        campaign,
        payload=payload,
        target_ref=normalized_target,
        campaign_fingerprint=campaign_fingerprint,
        campaign_segment_id=campaign_segment_id,
    )
    active_command_runner = command_runner or _default_command_runner
    attached_nebius_api = getattr(active_command_runner, "nebius_api", None)
    active_nebius_api = nebius_api or attached_nebius_api
    if active_nebius_api is None:
        raise RuntimeError("External Soperator upgrade execution requires a Nebius API adapter.")
    if mutation_guard is not None:
        mutation_guard()
        unguarded_command_runner = active_command_runner

        def _guarded_command_runner(
            args: Sequence[str],
            *,
            input_text: str | None = None,
            timeout_seconds: int = 300,
            check: bool = True,
        ) -> SoperatorMigrationCommandResult:
            if _soperator_migration_command_requires_live_lease_fence(args):
                mutation_guard()
            return unguarded_command_runner(
                args,
                input_text=input_text,
                timeout_seconds=timeout_seconds,
                check=check,
            )

        class _GuardedNebiusApi:
            def __init__(self, delegate: SoperatorMigrationNebiusApi) -> None:
                self._delegate = delegate

            def __getattr__(self, name: str) -> Any:
                attribute = getattr(self._delegate, name)
                if not callable(attribute):
                    return attribute

                def _guarded_call(*args: Any, **kwargs: Any) -> Any:
                    mutation_guard()
                    return attribute(*args, **kwargs)

                return _guarded_call

        active_command_runner = _guarded_command_runner
        active_nebius_api = cast(SoperatorMigrationNebiusApi, _GuardedNebiusApi(active_nebius_api))
    if not isinstance(active_command_runner, _SoperatorMigrationExecutionCommandRunner):
        active_command_runner = _SoperatorMigrationExecutionCommandRunner(active_command_runner)
    if (
        login_session_policy != EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE
        or login_session_drain_timeout_seconds != 0
    ):
        raise RuntimeError(
            "External Soperator upgrade has one SSH-continuity contract: protect the "
            "original session and wait indefinitely for voluntary handoff. Policy and "
            "timeout overrides are not supported."
        )
    resolved_login_session_policy = EXTERNAL_LOGIN_SESSION_POLICY_WAIT_ACTIVE

    def _emit_phase_comment(phase_id: str, comment: str) -> None:
        if status_callback is None:
            return
        if phase_id == "backup":
            status_callback(f"External Soperator upgrade backup guard: {comment}")
            return
        status_callback(f"External Soperator upgrade phase {phase_id}: {comment}")

    _emit_phase_comment(
        "execute-preflight",
        "verifying onboarding, live source contract, checkpoint, and accepted compute plan.",
    )
    onboarding = _target_onboarding(payload, normalized_target)
    source_snapshot, report = _source_report_payload(source_report)
    source_report_fingerprint = _source_report_checkpoint_fingerprint(source_report)
    expected_source_version = _expected_source_version(onboarding=onboarding, report=report)
    source_analysis_fingerprint = str(report.get("fingerprint", "") or "").strip()
    if not source_analysis_fingerprint:
        raise RuntimeError(
            "Soperator source discovery bundle is missing its analysis fingerprint. "
            "Rerun `nebius-cxcli ext-soperator onboard` before executing the upgrade."
        )
    expected_source_contract = _execution_source_contract(source_snapshot)
    expected_source_contract_fingerprint = _fingerprint(expected_source_contract)
    target_version = str(
        onboarding.get("target_version", "") or report.get("target_version", "") or ""
    )
    kube_context = _target_kube_context(payload, normalized_target)
    actions = _onboarding_actions(onboarding)
    require_target_soperator_helm = _target_soperator_helm_release_required(onboarding)
    resolved_populate_jail_refresh = normalize_populate_jail_refresh_mode(populate_jail_refresh)
    phase_ids = _phase_ids_for_actions(
        report=report,
        onboarding=onboarding,
        populate_jail_refresh=resolved_populate_jail_refresh,
    )
    if not phase_ids:
        phase_ids = ("discovery-and-plan",)
    explicit_mount_requested = any(str(item or "").strip() for item in jail_persistent_mounts)
    jail_rootfs = report.get("jail_rootfs")
    jail_rootfs_refresh_required = (
        isinstance(jail_rootfs, Mapping) and jail_rootfs.get("refresh_required") is True
    )
    explicit_populate_jail_refresh = resolved_populate_jail_refresh in {"force", "manual"}
    auto_persistent_mounts = (
        explicit_mount_requested or explicit_populate_jail_refresh or jail_rootfs_refresh_required
    )
    payload, persistent_mount_state = _prepare_jail_persistent_mount_payload(
        payload=payload,
        target_ref=normalized_target,
        jail_persistent_mounts=jail_persistent_mounts,
        populate_jail_refresh=populate_jail_refresh,
        auto_persistent_mounts=auto_persistent_mounts,
    )
    onboarding = _target_onboarding(payload, normalized_target)
    actions = _onboarding_actions(onboarding)
    require_target_soperator_helm = _target_soperator_helm_release_required(onboarding)
    phase_ids = _phase_ids_with_jail_persistent_mount_prerequisites(
        phase_ids=phase_ids,
        payload=payload,
        target_ref=normalized_target,
    )
    checkpoint_path = soperator_migration_checkpoint_path(
        config_path,
        normalized_target,
        payload_or_config=payload,
        cluster_id=str(source_report.get("cluster_id", "") or ""),
        cluster_name=str(source_report.get("cluster_name", "") or ""),
        kube_context=str(source_report.get("kube_context", "") or ""),
        campaign_id=str(campaign.get("campaign_id", "") or ""),
    )
    existing_checkpoint = _load_checkpoint(checkpoint_path)
    completed_prior_run = (
        existing_checkpoint is not None
        and _checkpoint_run_complete(existing_checkpoint)
        and str(existing_checkpoint.get("source_report_fingerprint", "") or "")
        != source_report_fingerprint
    )
    resume_checkpoint = None if completed_prior_run else existing_checkpoint
    mutating_progress_started = _checkpoint_mutating_progress_started(resume_checkpoint)
    if mutating_progress_started:
        checkpoint_phase_ids = _checkpoint_planned_phase_ids(resume_checkpoint)
        unsupported_planned = sorted(set(checkpoint_phase_ids) - _SUPPORTED_EXECUTE_PHASE_IDS)
        if unsupported_planned:
            raise RuntimeError(
                "External Soperator upgrade checkpoint contains planned phase(s) that this "
                "executor cannot resume safely: "
                + ", ".join(unsupported_planned)
                + ". Review or remove the checkpoint before executing."
            )
        _validate_mutating_checkpoint_phase_plan(
            checkpoint_phase_ids=checkpoint_phase_ids,
            required_phase_ids=phase_ids,
        )
        phase_ids = checkpoint_phase_ids
    requires_compute_executor = _actions_require_compute_executor(actions)
    strict_source_fingerprint = not mutating_progress_started
    # The CLI has just produced this discovery bundle under the shared lease.
    # Reanalyze that immutable command-start observation instead of recollecting
    # the same provider, Kubernetes, Helm, and Slurm inventory a second time.
    # Mutation phases retain ``snapshot_collector`` for narrow post-mutation
    # reconciliation reads below.
    live_snapshot = source_snapshot
    live_report = analyze_soperator_onboarding_snapshot(
        live_snapshot,
        target_ref=normalized_target,
        pinned_chart_version=target_version,
        pinned_app_version=target_version,
        source_version_override=expected_source_version,
    )
    live_source_version = normalize_soperator_release_version(live_report.source_version)
    allowed_source_versions = {expected_source_version} if expected_source_version else set()
    if mutating_progress_started:
        allowed_source_versions.update(_target_resume_versions(target_version))
    if expected_source_version and live_source_version not in allowed_source_versions:
        raise RuntimeError(
            "Live Soperator source version changed since onboarding discovery: "
            f"expected {', '.join(sorted(allowed_source_versions))}, "
            f"found {live_source_version or 'not detected'}. "
            "Rerun `nebius-cxcli ext-soperator onboard` before executing the upgrade."
        )
    if not live_source_version:
        raise RuntimeError(
            "Live Soperator source release was not detected. Rerun onboarding after installing "
            "the source Soperator release."
        )
    expected_node_groups = set(_mapping(expected_source_contract.get("node_groups")))
    ignored_live_target_node_groups = frozenset(
        role for role in _SOPERATOR_COMPUTE_ROLES if role not in expected_node_groups
    )
    live_source_contract_fingerprint = _fingerprint(
        _execution_source_contract(
            live_snapshot,
            ignored_node_groups=ignored_live_target_node_groups,
        )
    )
    if (
        strict_source_fingerprint
        and live_source_contract_fingerprint != expected_source_contract_fingerprint
    ):
        raise RuntimeError(
            "Live Soperator source discovery changed since onboarding: "
            f"expected stable contract fingerprint {expected_source_contract_fingerprint}, "
            f"found {live_source_contract_fingerprint}. "
            "Rerun `nebius-cxcli ext-soperator onboard` before executing the upgrade."
        )

    locked_migration_profile = _mapping(campaign.get("migration_profile"))
    expected_profile_id = str(report.get("migration_profile_id", "") or "").strip()
    locked_profile_id = str(locked_migration_profile.get("id", "") or "").strip()
    if (
        (expected_profile_id and locked_profile_id != expected_profile_id)
        or not locked_profile_id
        or not _mapping(locked_migration_profile.get("execution_contract"))
    ):
        raise RuntimeError(
            "External Soperator v6 campaign is missing the exact migration profile "
            "execution contract accepted during onboarding."
        )
    execution_source_report = copy.deepcopy(dict(source_report))
    execution_source_report["locked_migration_profile"] = copy.deepcopy(
        dict(locked_migration_profile)
    )
    source_identity_recovery: dict[str, Any] = {}
    source_identity_required = _source_identity_required_for_execution(
        actions=actions,
        phase_ids=phase_ids,
    )
    if (
        mutating_progress_started
        and not _checkpoint_run_complete(existing_checkpoint)
        and source_identity_required
        and _source_report_needs_verified_backup_identity(
            execution_source_report,
            checkpoint=existing_checkpoint or {},
            target_ref=normalized_target,
        )
    ):
        resume_backup = dict(_mapping((existing_checkpoint or {}).get("backup")))
        if not resume_backup:
            raise RuntimeError(
                "External Soperator upgrade cannot recover the missing accepted source "
                "SlurmCluster identity because the mutating checkpoint has no original "
                "pre-mutation backup metadata."
            )
        execution_source_report, source_identity_recovery = (
            _source_report_with_verified_backup_identity(
                source_report=execution_source_report,
                backup=resume_backup,
                config_path=config_path,
                target_ref=normalized_target,
                expected_checkpoint=existing_checkpoint,
                expected_campaign=campaign,
            )
        )
    checkpoint = _checkpoint_for_run(
        existing=existing_checkpoint,
        target_ref=normalized_target,
        source_report_fingerprint=source_report_fingerprint,
        source_version=expected_source_version or live_source_version,
        target_version=target_version,
        phase_ids=phase_ids,
        # Premutation runs passed strict live source-contract validation above;
        # mutation resumes remain phase-checkpoint based. Refresh still requires
        # the same source version, target version, and phase plan.
        allow_source_report_refresh=True,
        campaign_fingerprint=campaign_fingerprint,
        campaign_segment_id=campaign_segment_id,
        source_backup_identity_fingerprint=_source_backup_identity_fingerprint(
            execution_source_report,
            target_ref=normalized_target,
        ),
    )
    timing = dict(_mapping(checkpoint.get("upgrade_timing")))
    timing_completed_at = _external_upgrade_report_timestamp(timing.get("completed_at"))
    timing_is_frozen = bool(timing_completed_at)
    timing_attempt_base_seconds = _external_upgrade_report_nonnegative_seconds(
        timing.get("active_elapsed_seconds")
    )
    timing_attempt_started_monotonic = (
        command_started_monotonic if command_started_monotonic is not None else time.monotonic()
    )
    if not timing_is_frozen:
        normalized_started_at = _external_upgrade_report_timestamp(command_started_at)
        timing["started_at"] = (
            _external_upgrade_report_timestamp(timing.get("started_at"))
            or normalized_started_at
            or _external_upgrade_report_timestamp(_utc_now())
        )
        timing["last_attempt_started_at"] = (
            normalized_started_at or _external_upgrade_report_timestamp(_utc_now())
        )
        timing["attempt_count"] = (
            _external_upgrade_report_nonnegative_int(timing.get("attempt_count")) or 0
        ) + 1
        timing.pop("completed_at", None)
    checkpoint["upgrade_timing"] = timing

    def _refresh_upgrade_timing(*, completed: bool = False) -> None:
        nonlocal timing_is_frozen
        if timing_is_frozen:
            return
        timing_is_frozen = _refresh_external_upgrade_timing_payload(
            checkpoint,
            attempt_base_seconds=timing_attempt_base_seconds,
            attempt_started_monotonic=timing_attempt_started_monotonic,
            now_monotonic=time.monotonic(),
            completed=completed,
            completed_at=_utc_now() if completed else "",
        )

    _seed_read_only_slurm_route_from_checkpoint(
        command_runner=active_command_runner,
        checkpoint=checkpoint,
        kube_context=kube_context,
    )
    if source_identity_recovery:
        saved_recovery = dict(_mapping(checkpoint.get("source_identity_recovery")))
        if saved_recovery and saved_recovery != source_identity_recovery:
            recovery_without_digest = dict(source_identity_recovery)
            recovery_without_digest.pop("source_sshd_host_key_data_sha256", None)
            if saved_recovery != recovery_without_digest:
                raise RuntimeError(
                    "External Soperator upgrade checkpoint source identity recovery no "
                    "longer matches the verified pre-mutation backup."
                )
        checkpoint["source_identity_recovery"] = source_identity_recovery
        if not saved_recovery:
            _append_event(
                checkpoint,
                "source-identity-recovered",
                source="verified-pre-mutation-backup",
            )
    preflight_completed_phases = {
        str(phase or "").strip()
        for phase in checkpoint.get("completed_phases", []) or []
        if str(phase or "").strip()
    }
    existing_approval = "customer-approval" in preflight_completed_phases or bool(
        str(checkpoint.get("customer_approved_at", "") or "").strip()
    )
    effective_approval = approved or existing_approval
    source_cleanup_expected_absence = False
    if source_identity_required and (effective_approval or mutating_progress_started):
        source_cleanup_expected_absence = _source_cleanup_expected_absence_checkpointed(
            checkpoint=checkpoint,
            source_report=execution_source_report,
            target_ref=normalized_target,
        )
    source_slurmcluster = _source_slurmcluster_resource(
        execution_source_report,
        target_ref=normalized_target,
    )
    source_metadata = _mapping(source_slurmcluster.get("metadata"))
    if (
        source_identity_required
        and (effective_approval or mutating_progress_started)
        and not source_cleanup_expected_absence
        and not str(source_metadata.get("name", "") or "").strip()
    ):
        raise RuntimeError(
            "External Soperator upgrade requires one resolved source SlurmCluster "
            "identity before any takeover or Jail Upgrade mutation. Rerun onboarding "
            "against the live source cluster."
        )
    observed_source_slurmcluster_ref = {
        "namespace": str(source_metadata.get("namespace", "") or _SOPERATOR_NAMESPACE),
        "name": str(source_metadata.get("name", "") or ""),
        "uid": str(source_metadata.get("uid", "") or ""),
        "sshd_host_key_secret_name": _source_sshd_host_key_secret_name(
            execution_source_report,
            target_ref=normalized_target,
        ),
    }
    saved_source_slurmcluster_ref = dict(_mapping(checkpoint.get("source_slurmcluster_ref")))
    if source_cleanup_expected_absence:
        migration_phase = _mapping(
            _mapping(checkpoint.get("phase_state")).get("rolling-compute-migration")
        )
        handoff_binding = _mapping(migration_phase.get("slurmcluster_handoff_binding"))
        expected_source = {
            key: str(_mapping(handoff_binding.get("source")).get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        saved_identity = {
            key: str(saved_source_slurmcluster_ref.get(key) or "").strip()
            for key in ("namespace", "name", "uid")
        }
        if (
            saved_identity != dict(expected_source)
            or not str(saved_source_slurmcluster_ref.get("sshd_host_key_secret_name") or "").strip()
        ):
            raise RuntimeError(
                "External Soperator upgrade cannot resume after source cleanup without its "
                "exact checkpointed source identity and SSH host-key binding."
            )
        source_slurmcluster_ref = saved_source_slurmcluster_ref
    else:
        source_slurmcluster_ref = observed_source_slurmcluster_ref
    incomplete_source_binding = [
        field
        for field in ("namespace", "name", "uid", "sshd_host_key_secret_name")
        if not str(source_slurmcluster_ref.get(field, "") or "").strip()
    ]
    if (
        source_identity_required
        and (effective_approval or mutating_progress_started)
        and incomplete_source_binding
    ):
        raise RuntimeError(
            "External Soperator upgrade requires a complete immutable source "
            "SlurmCluster binding before mutation; missing "
            + ", ".join(incomplete_source_binding)
            + ". Rerun onboarding against the live source cluster."
        )
    saved_source_binding_present = bool(
        str(saved_source_slurmcluster_ref.get("name", "") or "").strip()
        and str(saved_source_slurmcluster_ref.get("uid", "") or "").strip()
    )
    if saved_source_binding_present and saved_source_slurmcluster_ref != source_slurmcluster_ref:
        raise RuntimeError(
            "External Soperator upgrade checkpoint is bound to a different source "
            "SlurmCluster identity. Review the checkpoint and rerun onboarding before "
            "resuming."
        )
    if source_slurmcluster_ref["name"]:
        checkpoint["source_slurmcluster_ref"] = source_slurmcluster_ref
    artifact_identity = soperator_cluster_artifact_identity_from_payload(
        payload,
        target_ref=normalized_target,
        cluster_id=str(source_report.get("cluster_id", "") or ""),
        cluster_name=str(source_report.get("cluster_name", "") or ""),
        kube_context=str(source_report.get("kube_context", "") or ""),
    )
    checkpoint.update(artifact_identity.as_metadata())
    checkpoint_phase_ids = _checkpoint_planned_phase_ids(checkpoint)
    if checkpoint_phase_ids:
        phase_ids = checkpoint_phase_ids
    execution_phase_ids = _execution_phase_ids_through(phase_ids, stop_after_phase_id)
    existing_mounts = dict(_mapping(checkpoint.get("persistent_jail_mounts")))
    checkpoint["persistent_jail_mounts"] = {
        **existing_mounts,
        **dict(to_plain_data(persistent_mount_state)),
    }
    resolved_job_policy = _external_upgrade_job_policy(
        job_policy,
        default_policy="preserve",
        allow_resolved_interactive=job_policy == "interactive",
    )
    allow_resolved_interactive_job_policy = resolved_job_policy == "interactive"
    if resolved_job_policy == "wait-then-cancel" and job_wait_timeout_seconds <= 0:
        raise RuntimeError(
            "--job-policy wait-then-cancel requires a positive --job-wait-timeout. "
            "Use --job-policy wait-to-finish --job-wait-timeout 0s for an unlimited wait."
        )
    selected_cancel_job_ids = tuple(
        str(job_id or "").strip() for job_id in cancel_job_ids if str(job_id or "").strip()
    )
    selected_requeue_job_ids = tuple(
        str(job_id or "").strip() for job_id in requeue_job_ids if str(job_id or "").strip()
    )
    backup_state = dict(_mapping(checkpoint.get("backup")))
    incoming_backup: dict[str, Any] = {}
    if backup_metadata:
        plain_backup = to_plain_data(dict(backup_metadata))
        incoming_backup = dict(plain_backup) if isinstance(plain_backup, Mapping) else {}
    if mutating_progress_started:
        if not backup_state:
            raise RuntimeError(
                "External Soperator upgrade checkpoint has mutating progress but no "
                "restore-capable backup metadata. Do not create a fresh backup over a "
                "partially upgraded cluster; review recovery state and remove the checkpoint "
                "only after deciding to restart."
            )
        if incoming_backup and incoming_backup != backup_state:
            raise RuntimeError(
                "recovery-required: resume supplied backup metadata that differs from the "
                "segment's immutable pre-mutation backup binding."
            )
    elif incoming_backup:
        if backup_state and incoming_backup != backup_state:
            raise RuntimeError(
                "recovery-required: the campaign segment is already bound to different "
                "pre-mutation backup metadata."
            )
        if not backup_state:
            backup_state = incoming_backup
            _append_event(
                checkpoint,
                "backup-metadata-checkpointed",
                segment_id=campaign_segment_id,
            )
    checkpoint["backup"] = backup_state
    slurm_state = dict(_mapping(checkpoint.get("slurm")))
    slurm_state.update(
        {
            "job_policy": resolved_job_policy,
            "cancel_job_ids": list(selected_cancel_job_ids),
            "requeue_job_ids": list(selected_requeue_job_ids),
            "wait_timeout_seconds": job_wait_timeout_seconds,
            "refresh_interval_seconds": job_refresh_interval_seconds,
            "scheduling_pause": slurm_scheduling_pause,
        }
    )
    checkpoint["slurm"] = slurm_state
    _checkpoint_slurm_held_job_operations(checkpoint)
    checkpoint["login_continuity"] = {
        **dict(_mapping(checkpoint.get("login_continuity"))),
        "session_policy": resolved_login_session_policy,
        "session_drain_timeout_seconds": login_session_drain_timeout_seconds,
        "guarantee": (
            "new SSH connections require a ready target login endpoint before source "
            "login retirement; existing TCP sessions are best-effort unless session "
            "drain is selected"
        ),
    }
    checkpoint["populate_jail_refresh"] = {
        **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
        "mode": resolved_populate_jail_refresh,
        "status": str(
            _mapping(checkpoint.get("populate_jail_refresh")).get("status", "planned") or "planned"
        ),
    }

    def _record_slurm_decision(decision: Mapping[str, Any]) -> None:
        slurm = checkpoint.setdefault("slurm", {})
        if not isinstance(slurm, dict):
            slurm = {}
            checkpoint["slurm"] = slurm
        decisions = slurm.setdefault("decisions", [])
        if not isinstance(decisions, list):
            decisions = []
            slurm["decisions"] = decisions
        decisions.append(to_plain_data(decision))
        _update_slurm_recovery_state(slurm, decision)
        _append_event(
            checkpoint,
            "slurm-job-policy",
            action=str(decision.get("action", "") or "unknown"),
        )

    status_prompt_pause = (
        getattr(status_callback, "pause", None) if status_callback is not None else None
    )
    if not callable(status_prompt_pause):
        status_prompt_pause = None

    accepted_compute_migration = _mapping(campaign.get("compute_migration"))
    accepted_pause = bool(accepted_compute_migration.get("slurm_scheduling_pause", True))
    if (
        accepted_compute_migration.get("mode") == COMPUTE_MIGRATION_MODE_IN_PLACE
        and slurm_scheduling_pause != accepted_pause
    ):
        raise RuntimeError(
            "External Soperator upgrade cannot override the accepted v6 "
            "compute_migration.slurm_scheduling_pause choice."
        )
    checkpoint["compute_migration"] = copy.deepcopy(to_plain_data(dict(accepted_compute_migration)))
    completed_phases = set(
        str(phase or "").strip()
        for phase in checkpoint.get("completed_phases", []) or []
        if str(phase or "").strip()
    )
    completed_phases.add("discovery-and-plan")
    persistent_copy_boundary_active = _persistent_mount_copy_failure_boundary_active(checkpoint)
    rolling_compute_provider_boundary_active = _rolling_compute_provider_boundary_active(checkpoint)
    controller_singleton_handoff_boundary_active = _controller_singleton_handoff_boundary_active(
        checkpoint
    )
    downstream_mutation_boundary_active = (
        persistent_copy_boundary_active
        or rolling_compute_provider_boundary_active
        or controller_singleton_handoff_boundary_active
    )
    protected_completed_predecessors: set[str] = set()
    if persistent_copy_boundary_active:
        protected_completed_predecessors.update(_external_upgrade_predecessor_phases(phase_ids))
    if rolling_compute_provider_boundary_active:
        protected_completed_predecessors.update(_rolling_compute_predecessor_phases(phase_ids))
    if controller_singleton_handoff_boundary_active:
        protected_completed_predecessors.update(_retirement_predecessor_phases(phase_ids))
    protected_state_before = _migration_safety_baseline_from_checkpoint(checkpoint)
    preflight_worker_groups: tuple[str, ...] = ()
    quota_preflight_lines: list[str] = []
    quota_preflight_pending_phase = ""
    quota_preflight_pending_reason = ""
    unsupported_relocated_copy_pending = bool(
        effective_approval
        and resolved_populate_jail_refresh != "manual"
        and POPULATE_JAIL_REFRESH_PHASE_ID in phase_ids
        and POPULATE_JAIL_REFRESH_PHASE_ID not in completed_phases
        and _legacy_persistent_mount_migration_required(
            _target_soperator_values(payload, normalized_target)
        )
        and str(
            _mapping(
                _mapping(
                    _mapping(checkpoint.get("phase_state")).get(POPULATE_JAIL_REFRESH_PHASE_ID)
                ).get("legacy_persistent_mount_migration")
            ).get("status", "")
            or ""
        ).strip()
        != "completed"
    )
    if unsupported_relocated_copy_pending:
        checkpoint["populate_jail_refresh"] = {
            **dict(_mapping(checkpoint.get("populate_jail_refresh"))),
            "persistent_migration_login_hold_policy": {
                "status": "rejected",
                "reason": (
                    "relocated persistent copying would require every login writer to "
                    "stop and violates unconditional SSH continuity"
                ),
            },
        }
    if effective_approval:
        if requires_compute_executor:
            raw_worker_groups = tuple(
                str(group or "") for group in checkpoint.get("worker_node_groups", []) or []
            )
            preflight_worker_groups = _validate_worker_node_groups(
                source_report=execution_source_report,
                worker_node_groups=raw_worker_groups,
            )
            checkpoint["worker_node_groups"] = list(preflight_worker_groups)
        if unsupported_relocated_copy_pending:
            quota_preflight_lines = [
                "Quota and affected-job preflight deferred because the configured "
                "persistent-copy layout violates continuous login availability."
            ]
        elif downstream_mutation_boundary_active:
            quota_preflight_lines = [
                "Quota and affected-job preflight deferred while a checkpointed "
                "Jail or rolling-compute mutation boundary is active."
            ]
        else:
            try:
                quota_preflight_lines = _run_soperator_migration_quota_preflight(
                    checkpoint=checkpoint,
                    completed_phases=completed_phases,
                    phase_ids=phase_ids,
                    payload=payload,
                    target_ref=normalized_target,
                    source_report=execution_source_report,
                    worker_node_groups=preflight_worker_groups,
                    nebius_api=active_nebius_api,
                )
            except _SoperatorMigrationQuotaPreflightPending as exc:
                quota_preflight_pending_phase = exc.phase_id
                quota_preflight_pending_reason = str(exc)
    else:
        quota_preflight_lines = [
            "Quota preflight: deferred until customer approval because no mutating phase will run."
        ]
    if effective_approval and not quota_preflight_pending_phase:
        if not backup_state and (set(phase_ids) & _MUTATING_PHASE_IDS):
            raise RuntimeError(
                "External Soperator upgrade requires restore-capable backup metadata before "
                "approved mutation. Run through `nebius-cxcli ext-soperator upgrade --execute "
                "--approve` so cxcli can create or reuse the pre-upgrade backup."
            )
        if backup_state and (set(phase_ids) & _MUTATING_PHASE_IDS):
            _emit_phase_comment(
                "backup",
                "validating restore-capable backup metadata before approved mutation.",
            )
            _validate_external_upgrade_backup_metadata(
                backup_state,
                config_path=config_path,
                verify_archive_hash=True,
            )
        if (
            source_identity_required
            and not source_cleanup_expected_absence
            and (set(phase_ids) & _MUTATING_PHASE_IDS)
        ):
            fresh_identity_snapshot = (
                source_identity_collector(kube_context=kube_context)
                if source_identity_collector is not None
                else _fresh_live_source_identity_snapshot(
                    source_report=execution_source_report,
                    target_ref=normalized_target,
                    command_runner=active_command_runner,
                    kube_context=kube_context,
                )
            )
            _validate_live_source_identity_bindings(
                source_report=execution_source_report,
                live_snapshot=fresh_identity_snapshot,
                target_ref=normalized_target,
                require_slurmcluster=(
                    "rolling-compute-migration" not in preflight_completed_phases
                ),
                require_pvc=(POPULATE_JAIL_REFRESH_PHASE_ID not in preflight_completed_phases),
            )
        if protected_state_before is None:
            _emit_phase_comment(
                "protected-state-capture",
                "capturing protected customer state before external remediation or rollout.",
            )
            protected_state_before = _capture_external_upgrade_protected_state(
                command_runner=active_command_runner,
                payload=payload,
                target_ref=normalized_target,
                kube_context=kube_context,
            )
            checkpoint["upgrade_safety"] = update_safety_payload_with_before(
                checkpoint.get("upgrade_safety")
                if isinstance(checkpoint.get("upgrade_safety"), Mapping)
                else None,
                protected_state_before,
                backup=backup_state or {"status": "not-recorded"},
            )
            _append_event(checkpoint, "protected-state-captured")
            _write_checkpoint(checkpoint_path, checkpoint)
            _emit_phase_comment(
                "protected-state-capture",
                "protected customer-state baseline captured and checkpointed.",
            )
    _append_event(
        checkpoint,
        "execute-preflight-completed",
        live_source_contract_fingerprint=live_source_contract_fingerprint,
        live_source_version=live_source_version,
        source_analysis_fingerprint=source_analysis_fingerprint,
        source_contract_fingerprint=expected_source_contract_fingerprint,
        strict_source_fingerprint=strict_source_fingerprint,
    )

    approved_worker_groups: tuple[str, ...] = ()
    if effective_approval:
        if requires_compute_executor:
            approved_worker_groups = preflight_worker_groups
            checkpoint["worker_node_groups"] = list(approved_worker_groups)
        completed_phases.add("customer-approval")
        if "customer_approved_at" not in checkpoint:
            checkpoint["customer_approved_at"] = _utc_now()
        if approved and not existing_approval:
            _append_event(
                checkpoint,
                "customer-approval-recorded",
                worker_node_groups=approved_worker_groups,
            )

    mutation_performed = False
    phase_lines: list[str] = []
    pending_phase = ""
    pending_reason = ""

    def _checkpoint_progress_unlocked() -> None:
        _refresh_upgrade_timing()
        checkpoint["completed_phases"] = _ordered_phase_list(completed_phases, phase_ids)
        checkpoint["compensation_obligations"] = _checkpoint_runtime_compensation_obligations(
            checkpoint
        )
        checkpoint["updated_at"] = _utc_now()
        _write_checkpoint(checkpoint_path, checkpoint)

    # Worker-group replacement runs concurrently in in-place mode.  Every
    # provider-operation callback must therefore use the same execution-scoped
    # writer so its journal mutation and durable snapshot cannot interleave
    # with another group's accepted-operation evidence.
    _checkpoint_progress: Callable[[], None] = _ExecutionCheckpointWriter(
        _checkpoint_progress_unlocked
    )

    controller_bridge_finalization_due = _checkpoint_controller_bridge_finalization_due(checkpoint)
    if not pending_phase and effective_approval and controller_bridge_finalization_due:
        _emit_phase_comment(
            "target-manager-restore",
            "reconciling final slot-aware values and the exact checkpointed manager before "
            "post-handoff safety checks.",
        )
        try:
            target_values = _patch_target_values_for_compute(
                payload=payload,
                target_ref=normalized_target,
                checkpoint=checkpoint,
                source_report=execution_source_report,
                live_snapshot=live_snapshot,
            )
            manager_restore_lines = _handoff_controller_bridge_to_target_singleton(
                checkpoint=checkpoint,
                ungated_values=target_values,
                target_ref=normalized_target,
                expected_version=target_version,
                kube_context=kube_context,
                command_runner=active_command_runner,
                checkpoint_writer=_checkpoint_progress,
            )
        except SoperatorMigrationPhasePending as exc:
            pending_phase = "target-manager-restore"
            pending_reason = str(exc)
            checkpoint["pending_phase"] = pending_phase
            checkpoint["pending_reason"] = pending_reason
            _checkpoint_progress()
        else:
            phase_lines.extend(f"target-manager-restore: {line}" for line in manager_restore_lines)
            _checkpoint_progress()

    phase_lines.extend(
        _reconcile_intent_recorded_slurm_holds_before_worker_classification(
            command_runner=active_command_runner,
            kube_context=kube_context,
            held_job_operations=_checkpoint_slurm_held_job_operations(checkpoint),
            checkpoint_writer=_checkpoint_progress,
            approve_remediation=approve_remediation,
        )
    )

    def _record_phase_failure(
        phase_id: str,
        exc: BaseException,
    ) -> None:
        nonlocal mutation_performed, pending_phase, pending_reason
        interrupted = isinstance(exc, (KeyboardInterrupt, EOFError))
        pending_phase = phase_id
        pending_reason = (
            "interrupted by user" if interrupted else (str(exc).strip() or exc.__class__.__name__)
        )
        phase_mutation_performed = _checkpoint_phase_mutation_performed(checkpoint, phase_id)
        mutation_performed = (
            mutation_performed
            or phase_mutation_performed
            or _checkpoint_upgrade_mutation_performed(checkpoint)
        )
        if phase_mutation_performed and phase_id in _MUTATING_PHASE_IDS:
            failed_phase_state = _phase_state(checkpoint, phase_id)
            failed_phase_state["mutation_performed"] = True
            if phase_id == _EXTERNAL_NODE_TEMPLATE_PHASE_ID:
                for group in _mapping(failed_phase_state.get("node_groups")).values():
                    if isinstance(group, dict) and _node_group_provider_update_attempted(group):
                        group["mutation_performed"] = True
        checkpoint["pending_phase"] = pending_phase
        checkpoint["pending_reason"] = pending_reason
        _append_event(
            checkpoint,
            "execute-interrupted" if interrupted else "execute-phase-failed",
            phase=phase_id,
            error=pending_reason,
        )
        report_path = _migrate_report_path(
            config_path,
            target_ref=normalized_target,
            checkpoint=checkpoint,
        )
        json_report_path = _upgrade_report_json_path(
            config_path,
            target_ref=normalized_target,
            checkpoint=checkpoint,
        )
        checkpoint["upgrade_report"] = str(report_path)
        checkpoint["upgrade_report_json"] = str(json_report_path)
        _refresh_upgrade_timing()
        _write_soperator_migrate_report(
            config_path=config_path,
            checkpoint_path=checkpoint_path,
            checkpoint=checkpoint,
            phase_ids=phase_ids,
            completed_phases=completed_phases,
            target_ref=normalized_target,
            source_version=live_source_version,
            target_version=target_version,
            pending_phase=pending_phase,
            pending_reason=pending_reason,
            mutation_performed=mutation_performed,
            campaign=campaign,
        )
        _checkpoint_progress()

    status_reporter: SoperatorMigrationStatusReporter | None = None
    if effective_approval and status_callback is not None:
        status_reporter = SoperatorMigrationStatusReporter(
            emit=status_callback,
            nebius_api=active_nebius_api,
            command_runner=active_command_runner,
            kube_context=kube_context,
            checkpoint=checkpoint,
            payload=payload,
            source_report=execution_source_report,
            target_ref=normalized_target,
            phase_ids=phase_ids,
            poll_interval_seconds=status_poll_interval_seconds,
        )

    def _append_status_event(
        snapshot: SoperatorMigrationStatusSnapshot | None,
        *,
        point: str,
    ) -> None:
        event = dict(_status_snapshot_event(snapshot))
        if not event:
            return
        event["point"] = point
        _append_event(checkpoint, "execute-status", **event)

    if not effective_approval:
        pending_phase = "customer-approval"
        pending_reason = (
            "live preflight completed and checkpointed; customer approval is required "
            "before mutating phases."
        )
    elif unsupported_relocated_copy_pending:
        pending_phase = POPULATE_JAIL_REFRESH_PHASE_ID
        pending_reason = (
            "Jail Upgrade requires shared-SFS/in-place persistent mount adoption; "
            "relocated copying that downscales every login Pod is unsupported."
        )
    elif quota_preflight_pending_phase:
        pending_phase = quota_preflight_pending_phase
        pending_reason = quota_preflight_pending_reason
    elif pending_phase:
        pass
    else:
        if downstream_mutation_boundary_active:
            restored_cutover_lines = _restore_historically_completed_copy_boundary_phases(
                checkpoint=checkpoint,
                completed_phases=completed_phases,
                phase_ids=phase_ids,
                allow_transient_verification_drift=True,
            )
            if restored_cutover_lines:
                phase_lines.extend(restored_cutover_lines)
                _checkpoint_progress()
        if _validation_hold_needs_reconcile(checkpoint, completed_phases):
            completed_phases.discard("validation-and-rollback-hold")
            _append_event(
                checkpoint,
                "execute-phase-reconcile-required",
                phase="validation-and-rollback-hold",
                reason="validation contract changed",
                target_revision=_VALIDATION_HOLD_REVISION,
            )
        if (
            not downstream_mutation_boundary_active
            and "rolling-compute-migration" in completed_phases
            and _has_soperator_custom_resources(live_snapshot)
        ):
            phase_mutation, lines = _reconcile_completed_compute_cutover(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                live_snapshot=live_snapshot,
                target_ref=normalized_target,
                kube_context=kube_context,
                command_runner=active_command_runner,
                nebius_api=active_nebius_api,
                checkpoint_writer=_checkpoint_progress,
                job_policy=resolved_job_policy,
                cancel_job_ids=selected_cancel_job_ids,
                requeue_job_ids=selected_requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                slurm_scheduling_pause=slurm_scheduling_pause,
                login_session_policy=resolved_login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                slurm_decision_recorder=_record_slurm_decision,
                interactive_prompt_pause=status_prompt_pause,
                allow_resolved_interactive_job_policy=(allow_resolved_interactive_job_policy),
                mutation_guard=mutation_guard,
            )
            if phase_mutation or lines:
                mutation_performed = mutation_performed or phase_mutation
                phase_lines.extend([f"rolling-compute-migration: {line}" for line in lines])
                _append_event(
                    checkpoint,
                    "execute-phase-reconciled",
                    phase="rolling-compute-migration",
                    mutation_performed=phase_mutation,
                )
                _checkpoint_progress()
                live_snapshot = snapshot_collector(kube_context=kube_context)
        action_reconcile_lines = _reconcile_completed_action_phases(
            checkpoint=checkpoint,
            completed_phases=completed_phases,
            phase_ids=phase_ids,
            payload=payload,
            source_report=execution_source_report,
            live_snapshot=live_snapshot,
            target_ref=normalized_target,
            kube_context=kube_context,
            worker_node_groups=approved_worker_groups,
            nebius_api=active_nebius_api,
            command_runner=active_command_runner,
            protected_predecessors=protected_completed_predecessors,
        )
        if action_reconcile_lines:
            phase_lines.extend(action_reconcile_lines)
            _checkpoint_progress()
        phase_handlers: Mapping[str, Callable[[], tuple[bool, list[str]]]] = {
            _EXTERNAL_NODE_TEMPLATE_PHASE_ID: lambda: _execute_external_node_template_upgrade_phase(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                target_ref=normalized_target,
                kube_context=kube_context,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                checkpoint_writer=_checkpoint_progress,
            ),
            _TARGET_GPU_STACK_PHASE_ID: lambda: _execute_target_gpu_stack_remediation_phase(
                checkpoint=checkpoint,
                payload=payload,
                target_ref=normalized_target,
                kube_context=kube_context,
                command_runner=active_command_runner,
                checkpoint_writer=_checkpoint_progress,
                continuous_pause_guard=lambda: _ensure_continuous_worker_slurm_pause(
                    checkpoint=checkpoint,
                    source_report=execution_source_report,
                    worker_node_groups=approved_worker_groups,
                    command_runner=active_command_runner,
                    kube_context=kube_context,
                    checkpoint_writer=_checkpoint_progress,
                    job_policy=resolved_job_policy,
                    cancel_job_ids=selected_cancel_job_ids,
                    requeue_job_ids=selected_requeue_job_ids,
                    job_wait_timeout_seconds=job_wait_timeout_seconds,
                    job_refresh_interval_seconds=job_refresh_interval_seconds,
                    slurm_decision_recorder=_record_slurm_decision,
                    interactive_prompt_pause=status_prompt_pause,
                    allow_resolved_interactive_job_policy=(allow_resolved_interactive_job_policy),
                    slurm_scheduling_pause=slurm_scheduling_pause,
                ),
            ),
            "create-aligned-sfs": lambda: _execute_create_aligned_sfs_phase(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                target_ref=normalized_target,
                worker_node_groups=approved_worker_groups,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                checkpoint_writer=_checkpoint_progress,
            ),
            _CONTROLLER_HA_BRIDGE_PHASE_ID: lambda: _execute_controller_ha_bridge_phase(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                target_ref=normalized_target,
                kube_context=kube_context,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                artifact_dir=checkpoint_path.parent / "controller-bridge",
                checkpoint_writer=_checkpoint_progress,
            ),
            "online-bulk-data-sync": lambda: _execute_online_bulk_data_sync_phase(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                live_snapshot=live_snapshot,
                target_ref=normalized_target,
                kube_context=kube_context,
                command_runner=active_command_runner,
            ),
            "rolling-compute-migration": lambda: _execute_rolling_compute_migration_phase(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                live_snapshot=live_snapshot,
                target_ref=normalized_target,
                kube_context=kube_context,
                worker_node_groups=approved_worker_groups,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                accounting_handoff_artifact_dir=(
                    checkpoint_path.parent / _ACCOUNTING_HANDOFF_DIRNAME
                ),
                checkpoint_writer=_checkpoint_progress,
                job_policy=resolved_job_policy,
                cancel_job_ids=selected_cancel_job_ids,
                requeue_job_ids=selected_requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                slurm_decision_recorder=_record_slurm_decision,
                interactive_prompt_pause=status_prompt_pause,
                allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
                slurm_scheduling_pause=slurm_scheduling_pause,
                login_session_policy=resolved_login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                mutation_guard=mutation_guard,
                impact_reporter=lambda message: _emit_phase_comment(
                    "rolling-compute-migration", message
                ),
            ),
            "final-control-plane-cutover": lambda: _execute_final_cutover_phase(
                checkpoint=checkpoint,
                live_snapshot=live_snapshot,
                target_ref=normalized_target,
                kube_context=kube_context,
                command_runner=active_command_runner,
            ),
            POPULATE_JAIL_REFRESH_PHASE_ID: lambda: _execute_populate_jail_refresh_phase(
                checkpoint=checkpoint,
                payload=payload,
                source_report=execution_source_report,
                live_snapshot=live_snapshot,
                target_ref=normalized_target,
                kube_context=kube_context,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                accounting_handoff_artifact_dir=(
                    checkpoint_path.parent / _ACCOUNTING_HANDOFF_DIRNAME
                ),
                populate_jail_refresh=resolved_populate_jail_refresh,
                job_policy=resolved_job_policy,
                cancel_job_ids=selected_cancel_job_ids,
                requeue_job_ids=selected_requeue_job_ids,
                job_wait_timeout_seconds=job_wait_timeout_seconds,
                job_refresh_interval_seconds=job_refresh_interval_seconds,
                login_session_policy=resolved_login_session_policy,
                login_session_drain_timeout_seconds=login_session_drain_timeout_seconds,
                slurm_decision_recorder=_record_slurm_decision,
                interactive_prompt_pause=status_prompt_pause,
                allow_resolved_interactive_job_policy=allow_resolved_interactive_job_policy,
                slurm_scheduling_pause=slurm_scheduling_pause,
                checkpoint_writer=_checkpoint_progress,
                jail_sfs_resize_handler=jail_sfs_resize_handler,
                mutation_guard=mutation_guard,
            ),
            "validation-and-rollback-hold": lambda: _execute_validation_hold_phase(
                config_path=config_path,
                checkpoint=checkpoint,
                payload=payload,
                live_snapshot=live_snapshot,
                target_ref=normalized_target,
                kube_context=kube_context,
                target_version=target_version,
                command_runner=active_command_runner,
                approve_remediation=approve_remediation,
                require_target_soperator_helm=require_target_soperator_helm,
            ),
            "retire-old-resources": lambda: _execute_retire_old_resources_phase(
                checkpoint=checkpoint,
                payload=payload,
                target_ref=normalized_target,
                source_report=execution_source_report,
                live_snapshot=live_snapshot,
                kube_context=kube_context,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
                checkpoint_writer=_checkpoint_progress,
            ),
        }
        active_copy_predecessors = _external_upgrade_predecessor_phases(phase_ids)
        for phase_id in execution_phase_ids:
            if phase_id in {"discovery-and-plan", "customer-approval"}:
                continue
            if phase_id in _POST_UPGRADE_CHECK_PHASE_IDS:
                continue
            if (
                persistent_copy_boundary_active
                and phase_id in active_copy_predecessors
                and phase_id not in completed_phases
            ):
                pending_phase = POPULATE_JAIL_REFRESH_PHASE_ID
                pending_reason = (
                    "Active persistent-copy writer boundary found incomplete predecessor "
                    f"phase '{phase_id}' without restorable durable completion evidence. "
                    "Writers remain held; reconcile the checkpoint evidence before resume."
                )
                checkpoint["pending_phase"] = pending_phase
                checkpoint["pending_reason"] = pending_reason
                phase_lines.append(
                    f"{phase_id}: blocked while the checkpointed persistent-copy "
                    "writer boundary remains active; no predecessor mutation or Jail "
                    "Upgrade continuation was attempted."
                )
                _checkpoint_progress()
                break
            if phase_id in completed_phases:
                continue
            handler = phase_handlers.get(phase_id)
            if handler is None:
                pending_phase = phase_id
                pending_reason = f"unsupported external Soperator upgrade phase '{phase_id}'."
                break
            status_started = False
            phase_mutation = False
            fast_verification_attempted = False
            verification_lines: list[str] = []
            try:
                checkpoint["pending_phase"] = phase_id
                checkpoint["pending_reason"] = ""
                _append_event(checkpoint, "execute-phase-started", phase=phase_id)
                _checkpoint_progress()
                if status_reporter is not None:
                    _append_status_event(status_reporter.set_phase(phase_id), point="phase-start")
                    status_reporter.start()
                    status_started = True
                phase_mutation, lines = handler()
                mutation_performed = mutation_performed or phase_mutation
                phase_lines.extend([f"{phase_id}: {line}" for line in lines])
                if phase_id in _FAST_STAGE_VERIFICATION_PHASE_IDS:
                    fast_verification_attempted = True
                    _emit_phase_comment(phase_id, "running fast stage verification.")
                    verification_lines = _run_external_upgrade_phase_fast_verification(
                        checkpoint=checkpoint,
                        phase_id=phase_id,
                        payload=payload,
                        source_report=execution_source_report,
                        live_snapshot=live_snapshot,
                        target_ref=normalized_target,
                        kube_context=kube_context,
                        worker_node_groups=approved_worker_groups,
                        nebius_api=active_nebius_api,
                        command_runner=active_command_runner,
                    )
            except SoperatorMigrationPhasePending as exc:
                pending_phase = phase_id
                pending_reason = str(exc)
                checkpoint["pending_phase"] = pending_phase
                checkpoint["pending_reason"] = pending_reason
                phase_mutation = bool(
                    _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id)).get(
                        "mutation_performed"
                    )
                )
                mutation_performed = mutation_performed or phase_mutation
                if fast_verification_attempted:
                    verification = stage_fast_verification_report(
                        phase_id,
                        _mapping(_mapping(checkpoint.get("phase_state")).get(phase_id)),
                    )
                else:
                    verification = _record_phase_fast_verification(
                        checkpoint=checkpoint,
                        phase_id=phase_id,
                        status="failed",
                        summary=pending_reason,
                        checks=[
                            _fast_verification_check(
                                _STATUS_PHASE_LABELS.get(phase_id, phase_id),
                                "failed",
                                pending_reason,
                            )
                        ],
                    )
                phase_lines.append(_phase_validation_summary_line(phase_id, verification))
                _checkpoint_progress()
                break
            except (KeyboardInterrupt, EOFError) as exc:
                _record_phase_failure(phase_id, exc)
                raise
            except Exception as exc:
                _record_phase_failure(phase_id, exc)
                raise
            finally:
                if status_reporter is not None:
                    _append_status_event(status_reporter.emit(force=True), point="phase-end")
                    if status_started:
                        status_reporter.stop()
            completed_phases.add(phase_id)
            _append_event(
                checkpoint,
                "execute-phase-completed",
                phase=phase_id,
                mutation_performed=phase_mutation,
            )
            _clear_completed_pending_phase(checkpoint, phase_id)
            phase_lines.extend(verification_lines)
            _checkpoint_progress()
            if phase_id in {
                _EXTERNAL_NODE_TEMPLATE_PHASE_ID,
                _TARGET_GPU_STACK_PHASE_ID,
                "create-aligned-sfs",
                "online-bulk-data-sync",
                "rolling-compute-migration",
                "final-control-plane-cutover",
                POPULATE_JAIL_REFRESH_PHASE_ID,
            }:
                live_snapshot = snapshot_collector(kube_context=kube_context)
                _append_event(
                    checkpoint,
                    "execute-live-snapshot-refreshed",
                    after_phase=phase_id,
                )
                _checkpoint_progress()

        if not pending_phase and len(execution_phase_ids) < len(phase_ids):
            completed_through = execution_phase_ids[-1]
            pending_phase = phase_ids[len(execution_phase_ids)]
            pending_reason = (
                f"execution stopped after phase {completed_through!r} by --stop-after-phase; "
                "rerun without that ceiling to continue the accepted campaign segment."
            )
            checkpoint["pending_phase"] = pending_phase
            checkpoint["pending_reason"] = pending_reason
            _append_event(
                checkpoint,
                "execute-phase-ceiling-reached",
                completed_through=completed_through,
                pending_phase=pending_phase,
            )
            _checkpoint_progress()

    if not pending_phase and effective_approval:
        _emit_phase_comment(
            "post-upgrade-mk8s-check",
            "verifying completed MK8s control-plane and accepted compute-migration state.",
        )
        checkpoint["pending_phase"] = "post-upgrade-mk8s-check"
        checkpoint["pending_reason"] = ""
        _append_event(checkpoint, "execute-phase-started", phase="post-upgrade-mk8s-check")
        _checkpoint_progress()
        mk8s_phase_lines: list[str] = []
        try:
            mk8s_state_lines = _verify_completed_soperator_migration_mk8s_state(
                payload=payload,
                source_report=execution_source_report,
                target_ref=normalized_target,
                worker_node_groups=approved_worker_groups,
                phase_ids=phase_ids,
                nebius_api=active_nebius_api,
                command_runner=active_command_runner,
            )
        except RuntimeError as exc:
            pending_phase = "post-upgrade-mk8s-check"
            pending_reason = str(exc).strip() or "post-upgrade MK8s check failed."
            verification_payload = _record_phase_fast_verification(
                checkpoint=checkpoint,
                phase_id=pending_phase,
                status="failed",
                summary=pending_reason,
                checks=[
                    _fast_verification_check(
                        "Post-upgrade MK8s state",
                        "failed",
                        pending_reason,
                    )
                ],
            )
            phase_lines.append(_phase_validation_summary_line(pending_phase, verification_payload))
            _checkpoint_progress()
        except (KeyboardInterrupt, EOFError) as exc:
            _record_phase_failure("post-upgrade-mk8s-check", exc)
            raise
        except Exception as exc:
            _record_phase_failure("post-upgrade-mk8s-check", exc)
            raise
        else:
            mk8s_summary = (
                mk8s_state_lines[0]
                if mk8s_state_lines
                else "completed MK8s control-plane and compute-migration state verified."
            )
            verification_payload = _record_phase_fast_verification(
                checkpoint=checkpoint,
                phase_id="post-upgrade-mk8s-check",
                status="passed",
                summary=mk8s_summary,
                checks=[
                    _fast_verification_check(
                        "Post-upgrade MK8s state",
                        "passed",
                        mk8s_summary,
                    )
                ],
            )
            mk8s_phase_lines = [f"post-upgrade-mk8s-check: {line}" for line in mk8s_state_lines]
            phase_lines.extend(mk8s_phase_lines)
            phase_lines.append(
                _phase_validation_summary_line("post-upgrade-mk8s-check", verification_payload)
            )
            completed_phases.add("post-upgrade-mk8s-check")
            _append_event(
                checkpoint,
                "execute-phase-completed",
                phase="post-upgrade-mk8s-check",
                mutation_performed=False,
            )
            _clear_completed_pending_phase(checkpoint, "post-upgrade-mk8s-check")
            _checkpoint_progress()
    if not pending_phase and effective_approval:
        _emit_phase_comment(
            "post-upgrade-helm-check",
            "verifying final Helm releases and target Soperator readiness.",
        )
        checkpoint["pending_phase"] = "post-upgrade-helm-check"
        checkpoint["pending_reason"] = ""
        _append_event(checkpoint, "execute-phase-started", phase="post-upgrade-helm-check")
        _checkpoint_progress()
        try:
            helm_state_lines = _verify_completed_soperator_migration_helm_state(
                command_runner=active_command_runner,
                kube_context=kube_context,
                target_version=target_version,
                require_target_release=require_target_soperator_helm,
            )
        except RuntimeError as exc:
            pending_phase = "post-upgrade-helm-check"
            pending_reason = str(exc).strip() or "post-upgrade Helm check failed."
            verification_payload = _record_phase_fast_verification(
                checkpoint=checkpoint,
                phase_id=pending_phase,
                status="failed",
                summary=pending_reason,
                checks=[
                    _fast_verification_check(
                        "Post-upgrade Helm state",
                        "failed",
                        pending_reason,
                    )
                ],
            )
            phase_lines.append(_phase_validation_summary_line(pending_phase, verification_payload))
            _checkpoint_progress()
        except (KeyboardInterrupt, EOFError) as exc:
            _record_phase_failure("post-upgrade-helm-check", exc)
            raise
        except Exception as exc:
            _record_phase_failure("post-upgrade-helm-check", exc)
            raise
        else:
            helm_summary = (
                helm_state_lines[0]
                if helm_state_lines
                else "final Helm releases and target Soperator readiness verified."
            )
            verification_payload = _record_phase_fast_verification(
                checkpoint=checkpoint,
                phase_id="post-upgrade-helm-check",
                status="passed",
                summary=helm_summary,
                checks=[
                    _fast_verification_check(
                        "Post-upgrade Helm state",
                        "passed",
                        helm_summary,
                    )
                ],
            )
            mutation_performed = (
                mutation_performed
                or _helm_state_lines_include_retirement_mutation(helm_state_lines)
            )
            phase_lines.extend(f"post-upgrade-helm-check: {line}" for line in helm_state_lines)
            phase_lines.append(
                _phase_validation_summary_line("post-upgrade-helm-check", verification_payload)
            )
            completed_phases.add("post-upgrade-helm-check")
            _append_event(
                checkpoint,
                "execute-phase-completed",
                phase="post-upgrade-helm-check",
                mutation_performed=False,
            )
            _clear_completed_pending_phase(checkpoint, "post-upgrade-helm-check")
            _checkpoint_progress()

    if (
        not pending_phase
        and effective_approval
        and not _checkpoint_protected_comparison_passed(checkpoint)
    ):
        _emit_phase_comment(
            "validation-and-rollback-hold",
            "verifying shared protected-state before config refresh.",
        )
        try:
            safety_lines = _ensure_external_upgrade_safety_verified(
                command_runner=active_command_runner,
                checkpoint=checkpoint,
                payload=payload,
                target_ref=normalized_target,
                kube_context=kube_context,
                approve_remediation=approve_remediation,
            )
        except SoperatorMigrationPhasePending as exc:
            pending_phase = "validation-and-rollback-hold"
            pending_reason = str(exc)
            checkpoint["pending_phase"] = pending_phase
            checkpoint["pending_reason"] = pending_reason
            _checkpoint_progress()
        else:
            phase_lines.extend(f"validation-and-rollback-hold: {line}" for line in safety_lines)
            _checkpoint_progress()

    campaign_segments = _sequence_of_mappings(campaign.get("segments"))
    final_campaign_segment = bool(
        campaign_segments
        and campaign_segment_id
        and str(campaign_segments[-1].get("id", "") or "").strip() == campaign_segment_id
    )
    if (
        not pending_phase
        and effective_approval
        and (final_campaign_segment or controller_bridge_finalization_due)
    ):
        final_health = checkpoint.setdefault("final_health", {})
        if not isinstance(final_health, dict):
            final_health = {}
            checkpoint["final_health"] = final_health
        try:
            final_health_binding = _ensure_controller_bridge_target_action_generation(
                checkpoint=checkpoint,
                kube_context=kube_context,
                command_runner=active_command_runner,
                checkpoint_writer=_checkpoint_progress,
            )
            final_worker_runtime_identity = _ensure_final_slurm_worker_runtime_identity(
                command_runner=active_command_runner,
                kube_context=kube_context,
                target_ref=normalized_target,
            )
            _verify_external_soperator_final_health(
                campaign=campaign,
                checkpoint=checkpoint,
                snapshot_collector=snapshot_collector,
                kube_context=kube_context,
                nebius_api=active_nebius_api,
            )
        except RuntimeError as exc:
            pending_phase = "final-health-validation"
            pending_reason = str(exc)
            final_health.update(
                {
                    "status": "failed",
                    "checked_at": _utc_now(),
                    "reason": pending_reason,
                }
            )
            checkpoint["pending_phase"] = pending_phase
            checkpoint["pending_reason"] = pending_reason
            _checkpoint_progress()
        else:
            final_health.update(
                {
                    "status": "passed",
                    "checked_at": _utc_now(),
                    "reason": "",
                    "worker_runtime_identity": final_worker_runtime_identity,
                    **final_health_binding,
                }
            )
            phase_lines.append(
                "final-health-validation: fresh MK8s, Kubernetes, Soperator, Slurm, "
                "and applicable GPU/network health passed."
            )
            _checkpoint_progress()

    if pending_phase:
        checkpoint["pending_phase"] = pending_phase
        checkpoint["pending_reason"] = pending_reason
        _append_event(checkpoint, "execute-pending", pending_phase=pending_phase)
    else:
        slurm_state = checkpoint.setdefault("slurm", {})
        if not isinstance(slurm_state, dict):
            slurm_state = {}
            checkpoint["slurm"] = slurm_state
        _drain_external_upgrade_slurm_action_journal(
            journal=_checkpoint_slurm_action_journal_for_job_control(checkpoint),
            command_runner=active_command_runner,
            kube_context=kube_context,
            authority_provider=lambda: _external_upgrade_slurm_action_authority(checkpoint),
            checkpoint_writer=_checkpoint_progress,
            finalize_unresolved=True,
        )
        held_job_operations = _checkpoint_slurm_held_job_operations(checkpoint)
        held_job_ids = tuple(sorted(_active_slurm_held_job_operations(held_job_operations)))
        if held_job_ids:
            inspection_command = _slurm_held_job_recovery_inspection_command(held_job_ids)
            checkpoint["pending_phase"] = "slurm-held-job-release"
            checkpoint["pending_reason"] = (
                "reconciling exact cxcli-owned Slurm requeue-hold compensation"
            )
            _checkpoint_progress()
            try:
                _release_journaled_external_upgrade_held_jobs(
                    command_runner=active_command_runner,
                    kube_context=kube_context,
                    held_job_operations=held_job_operations,
                    checkpoint_writer=_checkpoint_progress,
                )
            except Exception as exc:
                checkpoint["pending_reason"] = (
                    "recovery-required: cxcli could not safely reconcile Slurm jobs from its "
                    "identity-bound requeue-hold journal. Inspect without mutating state: "
                    + inspection_command
                    + ". Reconciliation error: "
                    + str(exc)
                )
                _checkpoint_progress()
                raise RuntimeError(str(checkpoint["pending_reason"])) from exc
            _record_slurm_decision(
                {
                    "at": _utc_now(),
                    "action": "held-jobs-released",
                    "job_ids": list(held_job_ids),
                }
            )
        if final_campaign_segment or controller_bridge_finalization_due:

            def _revalidate_final_health_after_action_finalization(
                binding: Mapping[str, Any],
            ) -> None:
                try:
                    final_worker_runtime_identity = _ensure_final_slurm_worker_runtime_identity(
                        command_runner=active_command_runner,
                        kube_context=kube_context,
                        target_ref=normalized_target,
                    )
                    _verify_external_soperator_final_health(
                        campaign=campaign,
                        checkpoint=checkpoint,
                        snapshot_collector=snapshot_collector,
                        kube_context=kube_context,
                        nebius_api=active_nebius_api,
                    )
                except RuntimeError as exc:
                    reason = str(exc).strip() or "finalized-action health validation failed."
                    final_health.update(
                        {
                            "status": "failed",
                            "checked_at": _utc_now(),
                            "reason": reason,
                        }
                    )
                    _checkpoint_progress()
                    raise _SoperatorMigrationFinalHealthPending(reason) from exc
                final_health.update(
                    {
                        "status": "passed",
                        "checked_at": _utc_now(),
                        "reason": "",
                        "worker_runtime_identity": final_worker_runtime_identity,
                        **binding,
                    }
                )
                phase_lines.append(
                    "final-health-validation: rebound fresh health to the closed, finalized "
                    "target TUI action generation."
                )
                _checkpoint_progress()

            _emit_phase_comment(
                "slurm-partition-restore",
                "restoring exact pre-upgrade partition records while the stopped bridge "
                "remains available for roll-forward recovery.",
            )
            try:
                restore_mutation, restore_lines = (
                    _restore_slurm_partitions_before_controller_bridge_cleanup(
                        checkpoint=checkpoint,
                        nebius_api=active_nebius_api,
                        command_runner=active_command_runner,
                        kube_context=kube_context,
                        checkpoint_writer=_checkpoint_progress,
                        slurm_decision_recorder=_record_slurm_decision,
                        final_health_revalidator=(
                            _revalidate_final_health_after_action_finalization
                        ),
                    )
                )
            except SoperatorMigrationPhasePending as exc:
                pending_phase = (
                    "final-health-validation"
                    if isinstance(exc, _SoperatorMigrationFinalHealthPending)
                    else "slurm-partition-restore"
                )
                pending_reason = str(exc)
                checkpoint["pending_phase"] = pending_phase
                checkpoint["pending_reason"] = pending_reason
                _append_event(checkpoint, "execute-pending", pending_phase=pending_phase)
                _checkpoint_progress()
            else:
                mutation_performed = mutation_performed or restore_mutation
                phase_lines.extend(f"slurm-partition-restore: {line}" for line in restore_lines)
                _append_event(
                    checkpoint,
                    "slurm-partition-restore-completed",
                    mutation_performed=restore_mutation,
                )
                _checkpoint_progress()
                _emit_phase_comment(
                    "controller-bridge-cleanup",
                    "removing the fenced temporary bridge after exact partition restoration.",
                )
                try:
                    cleanup_mutation, cleanup_lines = _cleanup_controller_bridge_after_final_health(
                        checkpoint=checkpoint,
                        kube_context=kube_context,
                        nebius_api=active_nebius_api,
                        command_runner=active_command_runner,
                        checkpoint_writer=_checkpoint_progress,
                    )
                except SoperatorMigrationPhasePending as exc:
                    pending_phase = "controller-bridge-cleanup"
                    pending_reason = str(exc)
                    checkpoint["pending_phase"] = pending_phase
                    checkpoint["pending_reason"] = pending_reason
                    _append_event(checkpoint, "execute-pending", pending_phase=pending_phase)
                    _checkpoint_progress()
                else:
                    mutation_performed = mutation_performed or cleanup_mutation
                    phase_lines.extend(
                        f"controller-bridge-cleanup: {line}" for line in cleanup_lines
                    )
                    _append_event(
                        checkpoint,
                        "controller-bridge-cleanup-completed",
                        mutation_performed=cleanup_mutation,
                    )
                    _checkpoint_progress()
        if not pending_phase:
            checkpoint["compensation_obligations"] = _checkpoint_runtime_compensation_obligations(
                checkpoint
            )
            if checkpoint["compensation_obligations"]:
                pending_phase = "compensation-required"
                pending_reason = (
                    "External Soperator segment postconditions passed, but cxcli-owned "
                    "strategy or Slurm compensation obligations remain. Rerun the same "
                    "upgrade command to restore them before completion."
                )
                checkpoint["pending_phase"] = pending_phase
                checkpoint["pending_reason"] = pending_reason
                _append_event(checkpoint, "execute-pending", pending_phase=pending_phase)
            else:
                checkpoint["pending_phase"] = "none"
                checkpoint["pending_reason"] = ""
                operation_intent = checkpoint.get("operation_intent")
                if isinstance(operation_intent, dict):
                    operation_intent["attempt_state"] = "verified"
                    for provider_operation in operation_intent.get("provider_operations", []) or []:
                        if (
                            isinstance(provider_operation, dict)
                            and provider_operation.get("attempt_state") == "provider-terminal"
                        ):
                            provider_operation["attempt_state"] = "verified"
                    checkpoint["operation_intent"] = operation_intent
                    _validate_checkpoint_journal_contract(checkpoint)
                _append_event(checkpoint, "execute-completed")
    mutation_performed = mutation_performed or _checkpoint_upgrade_mutation_performed(checkpoint)
    report_path = _migrate_report_path(
        config_path,
        target_ref=normalized_target,
        checkpoint=checkpoint,
    )
    json_report_path = _upgrade_report_json_path(
        config_path,
        target_ref=normalized_target,
        checkpoint=checkpoint,
    )
    checkpoint["upgrade_report"] = str(report_path)
    checkpoint["upgrade_report_json"] = str(json_report_path)
    if campaign_fingerprint and campaign_segment_id:
        completed_segment_ids = [
            str(segment_id or "").strip()
            for segment_id in checkpoint.get("completed_segment_ids", []) or []
            if str(segment_id or "").strip()
        ]
        segment_state = checkpoint.setdefault("segment_state", {})
        if not isinstance(segment_state, dict):
            segment_state = {}
            checkpoint["segment_state"] = segment_state
        segment_entry = segment_state.setdefault(campaign_segment_id, {})
        if isinstance(segment_entry, dict):
            segment_report_path, segment_json_report_path = (
                ext_soperator_upgrade_segment_report_paths(
                    config_path,
                    normalized_target,
                    campaign_segment_id,
                    cluster_id=str(checkpoint.get("cluster_id", "") or ""),
                    cluster_name=str(checkpoint.get("cluster_name", "") or ""),
                    kube_context=str(checkpoint.get("kube_context", "") or ""),
                )
            )
            segment_entry["live_source_version"] = live_source_version
            segment_entry["target_version"] = target_version
            segment_entry["completed_phases"] = _ordered_phase_list(completed_phases, phase_ids)
            segment_entry["report_path"] = str(report_path)
            segment_entry["json_report_path"] = str(json_report_path)
            segment_entry["segment_report_path"] = str(segment_report_path)
            segment_entry["segment_json_report_path"] = str(segment_json_report_path)
            backup_path = str(_mapping(checkpoint.get("backup")).get("path", "") or "").strip()
            if backup_path:
                segment_entry["backup_path"] = backup_path
            if str(checkpoint.get("pending_phase", "") or "") == "none":
                final_operation_intent = checkpoint.get("operation_intent")
                if not isinstance(final_operation_intent, Mapping):
                    raise RuntimeError(
                        "recovery-required: completed external Soperator segment has no "
                        "verified operation_intent to preserve."
                    )
                segment_entry["operation_intent"] = copy.deepcopy(
                    to_plain_data(dict(final_operation_intent))
                )
                segment_entry["completed_at"] = _utc_now()
                segment_entry["completion_source"] = "executed"
                segment_entry["operation_evidence"] = {
                    "phase_state": copy.deepcopy(
                        to_plain_data(_mapping(checkpoint.get("phase_state")))
                    ),
                    "controller_bridge": copy.deepcopy(
                        to_plain_data(_mapping(checkpoint.get("controller_bridge")))
                    ),
                    "backup": copy.deepcopy(to_plain_data(_mapping(checkpoint.get("backup")))),
                    "slurm": copy.deepcopy(to_plain_data(_mapping(checkpoint.get("slurm")))),
                    "upgrade_safety": copy.deepcopy(
                        to_plain_data(_mapping(checkpoint.get("upgrade_safety")))
                    ),
                }
        if str(checkpoint.get("pending_phase", "") or "") == "none":
            if campaign_segment_id not in completed_segment_ids:
                completed_segment_ids.append(campaign_segment_id)
            checkpoint["completed_segment_ids"] = list(completed_segment_ids)
        checkpoint["segment_state"] = segment_state
        checkpoint["campaign_fingerprint"] = campaign_fingerprint
        checkpoint["current_segment_id"] = campaign_segment_id
        _validate_checkpoint_journal_contract(checkpoint)
    _emit_phase_comment(
        "report",
        "writing external Soperator upgrade checkpoint and reports.",
    )
    _append_event(
        checkpoint,
        "upgrade-report-written",
        path=str(report_path),
        json_path=str(json_report_path),
    )
    _refresh_upgrade_timing(
        completed=(
            str(checkpoint.get("pending_phase", "") or "") == "none" and final_campaign_segment
        )
    )
    report_path = _write_soperator_migrate_report(
        config_path=config_path,
        checkpoint_path=checkpoint_path,
        checkpoint=checkpoint,
        phase_ids=phase_ids,
        completed_phases=completed_phases,
        target_ref=normalized_target,
        source_version=live_source_version,
        target_version=target_version,
        pending_phase=str(checkpoint["pending_phase"]),
        pending_reason=pending_reason,
        mutation_performed=mutation_performed,
        campaign=campaign,
    )
    _checkpoint_progress()

    lines = [
        f"Execute preflight checkpoint: {checkpoint_path}",
        f"Live source version verified: {live_source_version}",
        "Completed execute phases: " + ", ".join(_ordered_phase_list(completed_phases, phase_ids)),
    ]
    lines.extend(quota_preflight_lines)
    if approved_worker_groups:
        lines.insert(
            3,
            "Auto-selected source worker node groups: " + ", ".join(approved_worker_groups),
        )
    migration_mode = str(_compute_migration_contract(payload, normalized_target).get("mode") or "")
    migration_description = (
        "External compute migration: in-place fixed-size group updates with exact Slurm "
        "clear/drain gates and CAS provider operations."
        if migration_mode == COMPUTE_MIGRATION_MODE_IN_PLACE
        else "External compute migration: blue-green target groups with accepted worker "
        "bootstrap counts and guarded source retirement."
    )
    lines.insert(3 if not approved_worker_groups else 4, migration_description)
    lines.extend(phase_lines)
    footer = [
        "Upgrade status: "
        + _external_upgrade_status_summary(
            pending_phase=str(checkpoint["pending_phase"]),
            pending_reason=pending_reason,
            mutation_performed=mutation_performed,
        ),
        f"Pending phase: {checkpoint['pending_phase']}",
        f"Pending reason: {pending_reason or 'none'}",
    ]
    if str(checkpoint["pending_phase"]) != "none":
        footer.append(
            "Next action: "
            + _external_upgrade_resume_command(
                config_path,
                normalized_target,
                pending_phase=str(checkpoint["pending_phase"]),
                pending_reason=pending_reason,
                checkpoint=checkpoint,
            )
        )
    footer.extend(
        [
            "Upgrade performed: " + ("yes." if mutation_performed else "no."),
            f"Upgrade report: {report_path}",
            f"Upgrade JSON report: {json_report_path}",
        ]
    )
    lines.extend(footer)
    lines = _dedupe_external_execute_lines(lines)
    return SoperatorMigrationExecutionResult(
        checkpoint_path=checkpoint_path,
        completed_phases=tuple(_ordered_phase_list(completed_phases, phase_ids)),
        pending_phase=str(checkpoint["pending_phase"]),
        pending_reason=pending_reason,
        live_source_version=live_source_version,
        target_version=target_version,
        mutation_performed=mutation_performed,
        lines=tuple(lines),
        report_path=report_path,
    )
